    // -----------------------------------------------------------------------
    // Generic type argument count checking (TS2314)
    // -----------------------------------------------------------------------

    /**
     * Type parameter info: (minRequired, maxTotal, displayName).
     * minRequired = count of type params without defaults.
     * maxTotal = total type params count.
     */
    private data class TypeParamInfo(val minRequired: Int, val maxTotal: Int, val displayName: String)

    /**
     * Get type parameter info for a named type. Returns null if the type is not generic.
     */
    private fun getTypeParamInfo(name: String, forTypePosition: Boolean = false): TypeParamInfo? {
        // Check binder symbols first (user-declared types)
        for (result in binderResults) {
            val symbol = result.locals[name] ?: continue
            val info = getTypeParamInfoFromSymbol(symbol, forTypePosition)
            if (info != null) return info
            // 16.4: resolve import aliases to the underlying generic class/interface.
            // `import a = require("./C")` where `C` is `class C<T>` should report TS2314
            // as `'C<T>' requires 1 type argument(s)` (baseline uses the resolved name).
            if (symbol.flags.hasAny(SymbolFlags.Alias)) {
                val resolved = try { resolveAlias(symbol) } catch (_: StackOverflowError) { null }
                if (resolved != null && resolved !== symbol) {
                    val aliasInfo = getTypeParamInfoFromSymbol(resolved, forTypePosition)
                    if (aliasInfo != null) return aliasInfo
                }
            }
        }
        // Also check namespace exports (for types declared inside namespaces)
        for (result in binderResults) {
            for ((_, sym) in result.locals) {
                if (sym.flags.hasAny(SymbolFlags.Module)) {
                    val exported = sym.exports?.get(name)
                    if (exported != null) {
                        val info = getTypeParamInfoFromSymbol(exported, forTypePosition)
                        if (info != null) return info
                    }
                }
            }
        }
        val globalSymbol = globals[name]
        if (globalSymbol != null) {
            val info = getTypeParamInfoFromSymbol(globalSymbol, forTypePosition)
            if (info != null) return info
        }
        // Check known built-in generics (all required, no defaults)
        val builtin = KNOWN_GENERIC_BUILTINS[name] ?: return null
        return TypeParamInfo(builtin.first, builtin.first, builtin.second)
    }

    /**
     * Extract type parameter info from a symbol's declarations.
     * Prioritizes class/interface/type-alias over function declarations for type position checks.
     *
     * When [forTypePosition] is true (callers: 17.47's QualifiedName branch in
     * `checkTypeArgCount` and the [isUnresolvedGenericType] filter), the function-
     * declaration fall-through is skipped so a generic function symbol does NOT
     * produce a TypeParamInfo. Type-position TypeRefs to a value-only symbol
     * should resolve to TS2749 ("refers to a value"), not TS2314 ("requires N
     * type arguments"). Without this gate, `var b: A.B` where `A.B` is a
     * generic function would incorrectly emit TS2314.
     */
    private fun getTypeParamInfoFromSymbol(symbol: Symbol, forTypePosition: Boolean = false): TypeParamInfo? {
        var foundClassLike = false
        // First pass: check class/interface/type-alias declarations (higher priority for type position)
        for (decl in symbol.declarations) {
            when (decl) {
                is ClassDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is InterfaceDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is TypeAliasDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size, symbol.name)
                    }
                }
                else -> {}
            }
        }
        // If the symbol has a class/interface/type-alias declaration with 0 type params,
        // it shadows any global builtin with the same name — return (0, 0) to suppress TS2314.
        if (foundClassLike) return TypeParamInfo(0, 0, symbol.name)
        // Second pass: check function declarations (lower priority — only for value-position checks)
        if (forTypePosition) return null
        for (decl in symbol.declarations) {
            if (decl is FunctionDeclaration) {
                val typeParams = decl.typeParameters
                if (!typeParams.isNullOrEmpty()) {
                    val minRequired = typeParams.count { it.default == null }
                    return TypeParamInfo(minRequired, typeParams.size, symbol.name)
                }
            }
        }
        return null
    }

    /**
     * Returns true when [name] is a forward-declarable ES2015+ lib type and the active
     * compiler options exclude the lib that would provide it (either `@noLib: true` or
     * `@lib` listing only pre-es2015 entries). Used to swap TS2304 → TS2583 in type
     * position and to suppress TS2564 on properties whose type references such a name.
     */
    /**
     * B87.3 (round 73): true when the active `@lib` config provides the base-lib
     * VALUE declarations + es5-base essential global TYPES (`Boolean`, `Number`,
     * `Object`, `IArguments`, `CallableFunction`, `NewableFunction`) that live in
     * `lib.es5.d.ts`. A full non-dotted es-version lib (es3/es5/es6/es2015…/esnext)
     * is cumulative over es5 and provides them; a DOTTED sub-library
     * (`es2015.core`, `es2015.iterable`, …) provides only interface augmentations
     * for Array/String/etc., NOT the es5 base. Empty `@lib` = default full lib.
     */
    private fun libProvidesBaseValues(): Boolean {
        if (options.lib.isEmpty()) return true
        return options.lib.any {
            val l = it.lowercase()
            l == "es3" || l == "es5" || l == "es6" || l == "es7" || l == "esnext" ||
                (l.startsWith("es2") && !l.contains('.'))
        }
    }

    private fun isLibTypeUnavailableEs2015(name: String): Boolean {
        if (name !in FORWARD_DECLARABLE_LIB_TYPES_ES2015) return false
        if (options.noLib) return true
        if (options.lib.isEmpty()) return false
        return options.lib.none { lname ->
            val lower = lname.lowercase()
            // es6/es2015 alias, the legacy es7 (=es2016) alias, plus any es2*/esnext
            // entry. es7/es2016+ libs are cumulative over es2015, so Promise et al.
            // are available — without the es7 case, `@lib: dom, es7` FP-emits TS2583.
            lower == "es6" || lower == "es2015" || lower == "es7" ||
                lower.startsWith("es2") || lower == "esnext" ||
                lower.startsWith("es6.") || lower.startsWith("es2015.") ||
                lower.startsWith("es7.")
        }
    }

    /**
     * Returns true when [type] (or any nested type reference) names a forward-declarable
     * ES2015+ lib type that the active lib config doesn't provide. Used by TS2564 emission
     * to suppress on `member: Map<string,number>` under `@noLib`/restricted-lib (TS2583
     * already fires at the type-name position; TS2564 would be a duplicate diagnostic
     * about an effective error type).
     */
    private fun typeContainsUnavailableLibName(type: TypeNode?): Boolean {
        if (type == null) return false
        when (type) {
            is TypeReference -> {
                val nm = (type.typeName as? Identifier)?.text
                if (nm != null && isLibTypeUnavailableEs2015(nm)) return true
                type.typeArguments?.forEach { if (typeContainsUnavailableLibName(it)) return true }
            }
            is ArrayType -> if (typeContainsUnavailableLibName(type.elementType)) return true
            is UnionType -> type.types.forEach { if (typeContainsUnavailableLibName(it)) return true }
            is IntersectionType -> type.types.forEach { if (typeContainsUnavailableLibName(it)) return true }
            is TupleType -> type.elements.forEach { if (typeContainsUnavailableLibName(it)) return true }
            else -> {}
        }
        return false
    }

    /**
     * Check if a type annotation is a bare generic type reference that would trigger TS2314.
     * Used to suppress false-positive TS2564 on error types.
     */
    private fun isUnresolvedGenericType(type: TypeNode?): Boolean {
        if (type !is TypeReference) return false
        val typeName = type.typeName
        val name: String
        val forTypePosition: Boolean
        when (typeName) {
            is Identifier -> {
                name = typeName.text
                forTypePosition = false  // legacy behavior preserved for Identifier branch
            }
            // 17.46b: also accept QualifiedName so `var b: A.B` is filtered when
            // `B` (last segment) resolves to a generic class/interface missing
            // type args. Conservative — `getTypeParamInfo` walks namespace exports
            // by simple name, so a same-named generic in any namespace can match;
            // worst case we OVER-suppress (miss a legitimate TS2454/TS2564), never
            // emit a wrong diagnostic.
            // 17.47-fix: `forTypePosition = true` so generic FUNCTIONS aren't matched
            // (those should resolve to TS2749, not TS2314 — see `genericFunduleInModule`).
            is QualifiedName -> {
                name = (typeName.right as? Identifier)?.text ?: return false
                forTypePosition = true
            }
            else -> return false
        }
        val info = getTypeParamInfo(name, forTypePosition) ?: return false
        if (info.maxTotal == 0) return false // non-generic local type → TS2315, not TS2314
        if (info.minRequired != info.maxTotal) return false
        val providedCount = type.typeArguments?.size ?: 0
        return providedCount != info.maxTotal
    }

    /**
     * Check type argument count for a TypeReference node.
     * Emits TS2314: "Generic type 'X' requires N type argument(s)."
     * Only fires when all type params are required (no defaults).
     * Types with default type params need TS2707 (different code) — skipped.
     */
    private fun checkTypeArgCount(
        typeRef: TypeReference,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val typeName = typeRef.typeName
        val name: String
        val forTypePosition: Boolean
        // 17.47: also accept QualifiedName so `var b: A.B` (where `B` is a
        // generic class missing type args) emits TS2314 at the right position.
        // Skips scope/keyword/type-param checks for QualifiedName because
        // the namespace-walk in `getTypeParamInfo` is the resolution path —
        // `scope.has(name)` would only check the simple name in the current
        // scope. Conservative: a same-named generic in any namespace can match,
        // but worst case we emit TS2314 at a position that the baseline
        // doesn't expect (caller test fails differently); not a wrong-name
        // diagnostic since `info.displayName` is the resolved symbol's display.
        // 17.47-fix: `forTypePosition = true` for QualifiedName so generic
        // FUNCTIONS aren't matched (those resolve to TS2749 in TypeScript —
        // see `genericFunduleInModule_ts`).
        when (typeName) {
            is Identifier -> {
                name = typeName.text
                forTypePosition = false  // legacy behavior preserved for Identifier branch
                // Only check if the name actually resolves (skip if it would be TS2304)
                if (name.isEmpty()) return
                if (name[0] !in 'A'..'Z' && name[0] !in 'a'..'z' && name[0] != '_' && name[0] != '$') return
                if (name in KEYWORD_IDENTIFIERS) return
                if (!scope.has(name)) return
                // Type parameters cannot trigger TS2314 — they are not generic type constructors
                if (scope.isTypeParam(name)) return
            }
            is QualifiedName -> {
                name = (typeName.right as? Identifier)?.text ?: return
                forTypePosition = true
                if (name.isEmpty()) return
            }
            else -> return
        }

        // Look up type parameter info
        val info = getTypeParamInfo(name, forTypePosition) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        // Skip types with default type params — they need TS2707 not TS2314
        if (info.minRequired != info.maxTotal) return

        val providedCount = typeRef.typeArguments?.size ?: 0
        if (providedCount == info.maxTotal) return // correct count

        // Compute squiggle position
        val start: Int
        val length: Int
        // 17.47: For QualifiedName the typeName covers the full `A.B` span; the
        // simple `name.length` (right segment only) understates the squiggle.
        // Compute the full span by summing right.text.length + (right.pos - typeName.pos).
        val nameSpan: Int = if (typeName is QualifiedName) {
            val right = typeName.right
            if (right is Identifier) right.pos + right.text.length - typeName.pos else name.length
        } else {
            name.length
        }
        if (providedCount == 0 && typeRef.typeArguments == null) {
            // No type args at all — squiggle on just the name
            start = typeName.pos
            length = nameSpan
        } else if (providedCount == 0 && typeRef.typeArguments != null) {
            // Empty type arg list `<>` — squiggle covers `Name<>`
            start = typeName.pos
            val ltIdx = source.indexOf("<>", start)
            length = if (ltIdx >= 0) ltIdx + 2 - start else nameSpan
        } else {
            // Wrong count — squiggle on the entire type reference including <args>
            start = typeName.pos
            val lastArgEnd = typeRef.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else nameSpan
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
            category = DiagnosticCategory.Error,
            code = 2314,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check type argument count for an ExpressionWithTypeArguments in heritage clauses.
     * Emits TS2314 when extends/implements clause uses wrong number of type args.
     * Only fires when all type params are required (no defaults).
     */
    private fun checkHeritageTypeArgCount(
        exprWithArgs: ExpressionWithTypeArguments,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val expression = exprWithArgs.expression
        val name = when (expression) {
            is Identifier -> expression.text
            else -> return // PropertyAccessExpression — skip
        }

        // Only check if the name resolves
        if (name.isEmpty()) return
        if (!scope.has(name)) return

        val info = getTypeParamInfo(name) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        // Skip types with default type params — they need TS2707 not TS2314
        if (info.minRequired != info.maxTotal) return

        val providedCount = exprWithArgs.typeArguments?.size ?: 0
        if (providedCount == info.maxTotal) return

        val start = expression.pos
        val length: Int
        if (providedCount == 0) {
            length = name.length
        } else {
            // Squiggle covers name + <args>
            val lastArgEnd = exprWithArgs.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else name.length
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // In JS files, use TS8026 instead of TS2314 for heritage clauses without type args
        val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx")
        if (isJsFile && providedCount == 0) {
            diagnostics.add(Diagnostic(
                message = "Expected ${info.displayName} type arguments; provide these with an '@extends' tag.",
                category = DiagnosticCategory.Error,
                code = 8026,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
                category = DiagnosticCategory.Error,
                code = 2314,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * Walk a declare namespace body to check heritage clauses for TS2314.
     * Called separately because declare namespaces skip TS2304 checking.
     */
    private fun checkHeritageClausesInDeclareNamespace(
        moduleDecl: ModuleDeclaration,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val body = moduleDecl.body
        val statements = when (body) {
            is ModuleBlock -> body.statements
            is ModuleDeclaration -> {
                checkHeritageClausesInDeclareNamespace(body, scope, source, fileName)
                return
            }
            else -> return
        }
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val classScope = scope.child()
                    stmt.typeParameters?.forEach { classScope.addTypeParam(it.name.text) }
                    stmt.heritageClauses?.forEach { clause ->
                        for (type in clause.types) {
                            checkHeritageTypeArgCount(type, classScope, source, fileName)
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    val ifaceScope = scope.child()
                    stmt.typeParameters?.forEach { ifaceScope.addTypeParam(it.name.text) }
                    stmt.heritageClauses?.forEach { clause ->
                        for (type in clause.types) {
                            checkHeritageTypeArgCount(type, ifaceScope, source, fileName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val nsScope = buildNamespaceScope(stmt, scope, fileName)
                    checkHeritageClausesInDeclareNamespace(stmt, nsScope, source, fileName)
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Type used as value checking (TS2693)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // Always-truthy expression checking (TS2872)
    // -----------------------------------------------------------------------

    /**
     * Check for expressions that are always truthy in logical OR and if conditions.
     * Emits TS2872 "This kind of expression is always truthy."
     */
    private fun checkAlwaysTruthy() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAlwaysTruthyInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkAlwaysTruthyInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkAlwaysTruthyInStatement(stmt, source, fileName)
    }

    private fun checkAlwaysTruthyInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkAlwaysTruthyInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            }
            is IfStatement -> {
                // Check for always-falsy conditions (e.g. `void x`) → TS2873
                if (isAlwaysFalsyExpr(stmt.expression)) {
                    emitTS2873(stmt.expression, source, fileName)
                }
                checkEnumReferenceFalsyCondition(stmt.expression, source, fileName)
                // Walk the if-else chain: only flag always-truthy conditions that are
                // UNREACHABLE because a preceding branch was always-truthy
                var prevTruthy = isAlwaysTruthyExpr(stmt.expression)
                checkAlwaysTruthyInStatement(stmt.thenStatement, source, fileName)
                var elseStmt = stmt.elseStatement
                while (elseStmt is IfStatement) {
                    if (isAlwaysFalsyExpr(elseStmt.expression)) {
                        emitTS2873(elseStmt.expression, source, fileName)
                    }
                    if (prevTruthy) {
                        checkAlwaysTruthyCondition(elseStmt.expression, source, fileName)
                    }
                    checkEnumReferenceFalsyCondition(elseStmt.expression, source, fileName)
                    if (isAlwaysTruthyExpr(elseStmt.expression)) prevTruthy = true
                    checkAlwaysTruthyInStatement(elseStmt.thenStatement, source, fileName)
                    elseStmt = elseStmt.elseStatement
                }
                elseStmt?.let { checkAlwaysTruthyInStatement(it, source, fileName) }
            }
            is Block -> checkAlwaysTruthyInStatements(stmt.statements, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                stmt.condition?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
                checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                checkAlwaysTruthyInStatements(clauseStmts, source, fileName)
            }
            is TryStatement -> {
                checkAlwaysTruthyInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkAlwaysTruthyInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            is ExportAssignment -> stmt.expression?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkAlwaysTruthyInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.BarBar) {
                    if (isAlwaysTruthyForOrExpr(expr.left)) {
                        emitTS2872(expr.left, source, fileName)
                    } else if (isAlwaysFalsyExpr(expr.left)) {
                        emitTS2873(expr.left, source, fileName)
                    }
                    // B69.11: numeric-literal LHS — emit TS2872 only when NOT
                    // inside an arrow expression body (TypeScript suppresses there;
                    // the literal serves as a default-value pattern).
                    if (!inArrowExprBody && expr.left is NumericLiteralNode) {
                        val v = (expr.left as NumericLiteralNode).text.toDoubleOrNull()
                        if (v != null && v != 0.0 && !v.isNaN()) {
                            emitTS2872(expr.left, source, fileName)
                        }
                    }
                }
                // Iterative left spine to avoid StackOverflow
                var current: Expression = expr
                while (current is BinaryExpression) {
                    if (current.operator == SyntaxKind.BarBar && current !== expr) {
                        if (isAlwaysTruthyForOrExpr(current.left)) {
                            emitTS2872(current.left, source, fileName)
                        } else if (isAlwaysFalsyExpr(current.left)) {
                            emitTS2873(current.left, source, fileName)
                        }
                        if (!inArrowExprBody && current.left is NumericLiteralNode) {
                            val v = (current.left as NumericLiteralNode).text.toDoubleOrNull()
                            if (v != null && v != 0.0 && !v.isNaN()) {
                                emitTS2872(current.left, source, fileName)
                            }
                        }
                    }
                    checkAlwaysTruthyInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkAlwaysTruthyInExpr(current, source, fileName)
            }
            is ParenthesizedExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is AsExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                if (isAlwaysFalsyExpr(expr.condition)) {
                    emitTS2873(expr.condition, source, fileName)
                }
                checkEnumReferenceFalsyCondition(expr.condition, source, fileName)
                checkAlwaysTruthyInExpr(expr.whenTrue, source, fileName)
                checkAlwaysTruthyInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkAlwaysTruthyInStatements(body.statements, source, fileName)
                is Expression -> {
                    val saved = inArrowExprBody
                    inArrowExprBody = true
                    try {
                        checkAlwaysTruthyInExpr(body, source, fileName)
                    } finally {
                        inArrowExprBody = saved
                    }
                }
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            is CallExpression -> {
                checkAlwaysTruthyInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkAlwaysTruthyInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkAlwaysTruthyInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkAlwaysTruthyInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkAlwaysTruthyInExpr(expr.expression, source, fileName)
                checkAlwaysTruthyInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkAlwaysTruthyInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkAlwaysTruthyInExpr(prop.initializer, source, fileName)
                    is SpreadAssignment -> checkAlwaysTruthyInExpr(prop.expression, source, fileName)
                    is MethodDeclaration -> prop.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is GetAccessor -> prop.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is SetAccessor -> prop.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkAlwaysTruthyInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkAlwaysTruthyInExpr(expr.tag, source, fileName)
                val t = expr.template
                if (t is TemplateExpression) {
                    for (span in t.templateSpans) checkAlwaysTruthyInExpr(span.expression, source, fileName)
                }
            }
            is PrefixUnaryExpression -> checkAlwaysTruthyInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkAlwaysTruthyInExpr(expr.operand, source, fileName)
            is SpreadElement -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            is VoidExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is CommaListExpression -> for (e in expr.elements) checkAlwaysTruthyInExpr(e, source, fileName)
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /** B69.11: tracks whether we're inside an arrow expression body for the
     *  always-truthy walker. TypeScript suppresses TS2872 for numeric-literal
     *  LHS of `||` in this context (the literal is a default-value pattern). */
    private var inArrowExprBody: Boolean = false

    /**
     * TS2845: "This condition will always return 'false'/'true'." for an enum
     * member reference whose computed value is statically falsy/truthy. Fires on
     * the condition position of `a ? b : c` when the condition is a property-
     * access chain resolving to a const- or non-const-enum member with value
     * 0 / "" (false branch) or any non-zero / non-empty literal (true branch).
     * Walks alias chains so namespace-aliased forms like
     * `Internal.WhichThing.A` (where `import Internal = My.Internal`) resolve
     * via `resolveNamePath` + `resolveAlias`.
     */
    private fun checkEnumReferenceFalsyCondition(cond: Expression, source: String, fileName: String) {
        val expr = cond as? PropertyAccessExpression ?: return
        val enumPath = getReferencePath(expr.expression) ?: return
        val memberName = expr.name.text
        val result = fileResults[fileName] ?: return
        val symbol = resolveNamePath(enumPath, result) ?: return
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return
        val value = enumValues[target.id]?.get(memberName) ?: return
        val isTruthy = when (value) {
            is ConstantValue.NumberValue -> value.value != 0.0 && !value.value.isNaN()
            is ConstantValue.StringValue -> value.value.isNotEmpty()
        }
        val verdict = if (isTruthy) "'true'" else "'false'"
        val start = expr.pos
        val length = expressionTrueEnd(expr) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This condition will always return $verdict.",
            category = DiagnosticCategory.Error,
            code = 2845,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun checkAlwaysTruthyCondition(expr: Expression, source: String, fileName: String) {
        if (expr is NumericLiteralNode) {
            val value = expr.text.toDoubleOrNull() ?: return
            if (value != 0.0 && !value.isNaN()) {
                emitTS2872(expr, source, fileName)
            }
        }
        if (expr is ParenthesizedExpression) {
            checkAlwaysTruthyCondition(expr.expression, source, fileName)
        }
    }

    /** Only flag simple literal expressions and function expressions to avoid false positives. */
    private fun isAlwaysTruthyExpr(expr: Expression): Boolean {
        return when (expr) {
            is StringLiteralNode -> expr.text.isNotEmpty()
            is NoSubstitutionTemplateLiteralNode -> expr.text.isNotEmpty()
            is NumericLiteralNode -> {
                val value = expr.text.toDoubleOrNull() ?: return false
                value != 0.0 && !value.isNaN()
            }
            is BigIntLiteralNode -> {
                // `1n`, `2n`, ... — truthy; `0n` — falsy.
                val raw = expr.text.removeSuffix("n")
                raw.toLongOrNull()?.let { it != 0L } ?: false
            }
            is ParenthesizedExpression -> isAlwaysTruthyExpr(expr.expression)
            is AsExpression -> isAlwaysTruthyExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysTruthyExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysTruthyExpr(expr.expression)
            is NonNullExpression -> isAlwaysTruthyExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            is NewExpression -> true
            else -> false
        }
    }

    /**
     * TypeScript only flags these expression kinds in `||` contexts (LHS of ||).
     * Numeric/string literals and `new` expressions are NOT flagged in `||`.
     */
    private fun isAlwaysTruthyForOrExpr(expr: Expression): Boolean {
        return when (expr) {
            is ParenthesizedExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is AsExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is NonNullExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            is StringLiteralNode -> expr.text.isNotEmpty()
            // Note: NumericLiteralNode and NewExpression are NOT flagged in || contexts
            else -> false
        }
    }

    /**
     * Check if an expression is always falsy (e.g. `void x`).
     * TypeScript emits TS2873 for such expressions in `if` conditions.
     */
    private fun isAlwaysFalsyExpr(expr: Expression): Boolean {
        return when (expr) {
            is VoidExpression -> true
            is ParenthesizedExpression -> isAlwaysFalsyExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysFalsyExpr(expr.expression)
            is AsExpression -> isAlwaysFalsyExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysFalsyExpr(expr.expression)
            // `expr!` (non-null assertion) preserves runtime value; if the inner
            // expression is always falsy (e.g. `void 0`), `expr!` is too. Note:
            // `null!` / `undefined!` are intentionally treated as falsy here even
            // though the assertion is conceptually "not null" — the runtime value
            // is still falsy.
            is NonNullExpression -> isAlwaysFalsyExpr(expr.expression)
            is Identifier -> expr.text == "null" || expr.text == "undefined"
            else -> false
        }
    }

    private fun emitTS2873(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // For VoidExpression, compute length from operand's true end to get correct span
        val length = when (expr) {
            is VoidExpression -> expressionTrueEnd(expr.expression) - start
            is AsExpression -> (if (expr.tightEnd > 0) expr.tightEnd else expr.type.end) - start
            else -> expressionTrueEnd(expr) - start
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always falsy.",
            category = DiagnosticCategory.Error,
            code = 2873,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2872(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // Use text length for literals to get accurate squiggle
        val length = when (expr) {
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2 // +2 for quotes
            is NumericLiteralNode -> expr.text.length
            else -> expressionTrueEnd(expr) - start
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always truthy.",
            category = DiagnosticCategory.Error,
            code = 2872,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2774: This condition will always return true since this function is
    // always defined. Did you mean to call it instead?
    //
    // Fires under strictNullChecks when a callable identifier is used as a
    // condition without being called. Walks the operands of an `||`/`??` chain
    // (TypeScript only walks LHS of those, not `&&`).
    //
    // Suppressed when:
    //   - the operand's type can be undefined/null (not "always defined")
    //   - the operand is itself a CallExpression / AwaitExpression / unary
    //   - the body of the condition references the same identifier (e.g.
    //     `if (foo) { foo() }` is intentional defined-check + call)
    // -----------------------------------------------------------------------

    private fun checkUncalledFunctionsInConditions() {
        if (!strictNullChecks) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            currentFlowGraph = result.flowGraph
            uncalledShadowedScopes.clear()
            uncalledTypedLocalsStack.clear()
            uncalledThisTypeStack.clear()
            walkUncalledChecksInStatements(result.sourceFile.statements, source, fileName)
            currentFlowGraph = null
        }
    }

    private fun isUncalledShadowed(name: String): Boolean {
        for (scope in uncalledShadowedScopes) if (name in scope) return true
        return false
    }

    /** True if [expr] (after stripping parens) is a truthiness-test BinaryExpression (`&&`/`||`/`??`). */
    private fun isTruthinessChain(expr: Expression): Boolean {
        var cur: Expression = expr
        while (cur is ParenthesizedExpression) cur = cur.expression
        return cur is BinaryExpression && (cur.operator == SyntaxKind.AmpersandAmpersand || cur.operator == SyntaxKind.BarBar || cur.operator == SyntaxKind.QuestionQuestion)
    }

    private fun lookupUncalledTypedLocal(name: String): Type? {
        for (i in uncalledTypedLocalsStack.indices.reversed()) {
            uncalledTypedLocalsStack[i][name]?.let { return it }
        }
        return null
    }

    /**
     * Compute the param-annotated type for TS2774 typed-local scope.
     * Returns null when the param is unannotated (would resolve to `any`).
     * Wraps in a union with `undefined` when the param has `?` (optional).
     */
    private fun resolveUncalledParamType(p: Parameter): Type? {
        val pType = p.type ?: return null
        val resolved = try { getTypeFromTypeNode(pType) } catch (_: Throwable) { return null }
        if (resolved === errorType || resolved === anyType) return null
        if (p.questionToken) return getUnionType(listOf(resolved, undefinedType))
        return resolved
    }

    /**
     * Pre-scan a function/method body for nested function declarations and
     * variable declarations whose annotated type or initializer would resolve
     * to a callable shape. The resulting types power TS2774 lookups for
     * PropertyAccessExpression / Identifier operands that refer to bindings
     * declared in the enclosing function scope.
     */
    private fun collectUncalledTypedLocalsFromBody(body: Block, into: MutableMap<String, Type>, shadowed: MutableSet<String>) {
        for (stmt in body.statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val fnName = (stmt.name)?.text ?: continue
                    val sigType = buildCallableTypeForLocalFunction(stmt) ?: continue
                    into[fnName] = sigType
                    shadowed.add(fnName)
                }
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    val vName = (d.name as? Identifier)?.text ?: continue
                    val annotated = d.type?.let { try { getTypeFromTypeNode(it) } catch (_: Throwable) { null } }
                    val resolved: Type? = when {
                        annotated != null && annotated !== errorType && annotated !== anyType -> annotated
                        d.initializer != null -> try {
                            val t = getTypeOfExpression(d.initializer!!)
                            if (t === anyType || t === errorType) null else t
                        } catch (_: Throwable) { null }
                        else -> null
                    }
                    if (resolved != null) {
                        into[vName] = resolved
                        shadowed.add(vName)
                    }
                }
                else -> {}
            }
        }
    }

    /** Resolve the instance type for `this` inside a class body. */
    private fun resolveUncalledThisType(cls: ClassDeclaration): Type? {
        val name = cls.name?.text ?: return null
        val symbol = currentFileLocals?.get(name) ?: globals[name] ?: return null
        if (!symbol.flags.hasAny(SymbolFlags.Class)) return null
        return try { getDeclaredTypeOfSymbol(symbol).takeIf { it !== anyType && it !== errorType } } catch (_: Throwable) { null }
    }

    /** Build an anonymous Type.Object with a single call signature for a local function declaration. */
    private fun buildCallableTypeForLocalFunction(fn: FunctionDeclaration): Type? {
        // Build minimal call signature; param/return types are unimportant for the
        // "always callable + not nullish" classification used by TS2774.
        val sig = Signature(
            parameters = emptyList(),
            resolvedReturnType = anyType,
            minArgumentCount = 0,
        )
        val obj = Type.Object()
        obj.callSignatures = listOf(sig)
        return obj
    }

    private inline fun withUncalledScope(params: List<Parameter>, body: Block?, doBody: () -> Unit) {
        val shadowed = mutableSetOf<String>()
        val typed = mutableMapOf<String, Type>()
        for (p in params) {
            collectBindingNames(p.name, shadowed)
            val pName = (p.name as? Identifier)?.text
            if (pName != null) {
                resolveUncalledParamType(p)?.let { typed[pName] = it }
            }
        }
        if (body != null) collectUncalledTypedLocalsFromBody(body, typed, shadowed)
        uncalledShadowedScopes.addLast(shadowed)
        uncalledTypedLocalsStack.addLast(typed)
        try { doBody() } finally {
            uncalledShadowedScopes.removeLast()
            uncalledTypedLocalsStack.removeLast()
        }
    }

    // 17.30c.i: typed-locals scope for a free-standing Block (top-level or
    // inside an if/while/for body). Without this, declarations like
    // `{ const perf = window.performance; if (perf && perf.measure) ... }`
    // resolve to anyType through the file-level fallback in
    // `getTypeOfIdentifier` because block-scoped consts/lets are not in
    // `currentLocalTypes` / `currentFileLocals`. Function bodies don't go
    // through this branch — they walk via `withUncalledScope` against the
    // statements directly, so no double-push.
    private inline fun withUncalledBlockScope(block: Block, doBody: () -> Unit) {
        val shadowed = mutableSetOf<String>()
        val typed = mutableMapOf<String, Type>()
        collectUncalledTypedLocalsFromBody(block, typed, shadowed)
        if (typed.isEmpty() && shadowed.isEmpty()) {
            doBody()
            return
        }
        uncalledShadowedScopes.addLast(shadowed)
        uncalledTypedLocalsStack.addLast(typed)
        try { doBody() } finally {
            uncalledShadowedScopes.removeLast()
            uncalledTypedLocalsStack.removeLast()
        }
    }

    private fun walkUncalledChecksInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkUncalledChecksInStatement(stmt, source, fileName)
    }

    private fun walkUncalledChecksInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is IfStatement -> {
                checkUncalledInCondition(stmt.expression, stmt.thenStatement, source, fileName)
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
                walkUncalledChecksInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkUncalledChecksInStatement(it, source, fileName) }
            }
            is WhileStatement -> {
                checkUncalledInCondition(stmt.expression, stmt.statement, source, fileName)
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
                walkUncalledChecksInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkUncalledInCondition(stmt.expression, stmt.statement, source, fileName)
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
                walkUncalledChecksInStatement(stmt.statement, source, fileName)
            }
            is ForStatement -> {
                stmt.condition?.let { cond ->
                    checkUncalledInCondition(cond, stmt.statement, source, fileName)
                    walkUncalledChecksInExpression(cond, source, fileName)
                }
                walkUncalledChecksInStatement(stmt.statement, source, fileName)
            }
            is Block -> withUncalledBlockScope(stmt) {
                walkUncalledChecksInStatements(stmt.statements, source, fileName)
            }
            is ExpressionStatement -> {
                // Treat top-level `&&`/`||`/`??` BinaryExpression as a truthiness-test
                // site (mirrors TypeScript's check on every BE with these operators).
                // ExpressionStatement discards the expression's value, so the
                // statement itself is NOT a test position — only LHS operands of
                // short-circuit operators inherit "tested" status from the operator
                // semantics; RHS operands do not. Pass inTestPosition = false.
                if (isTruthinessChain(stmt.expression)) {
                    checkUncalledInCondition(stmt.expression, null, source, fileName, inTestPosition = false)
                }
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
            }
            is ReturnStatement -> stmt.expression?.let { walkUncalledChecksInExpression(it, source, fileName) }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkUncalledChecksInExpression(it, source, fileName) }
            }
            is FunctionDeclaration -> stmt.body?.let { body ->
                withUncalledScope(stmt.parameters, body) {
                    walkUncalledChecksInStatements(body.statements, source, fileName)
                }
            }
            is ClassDeclaration -> {
                val classThisType = resolveUncalledThisType(stmt)
                if (classThisType != null) uncalledThisTypeStack.addLast(classThisType)
                try {
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { body ->
                                val isStatic = ModifierFlag.Static in m.modifiers
                                if (isStatic && classThisType != null) uncalledThisTypeStack.removeLast()
                                try {
                                    withUncalledScope(m.parameters, body) {
                                        walkUncalledChecksInStatements(body.statements, source, fileName)
                                    }
                                } finally {
                                    if (isStatic && classThisType != null) uncalledThisTypeStack.addLast(classThisType)
                                }
                            }
                            is Constructor -> m.body?.let { body ->
                                withUncalledScope(m.parameters, body) {
                                    walkUncalledChecksInStatements(body.statements, source, fileName)
                                }
                            }
                            is GetAccessor -> m.body?.let { body ->
                                withUncalledScope(m.parameters, body) {
                                    walkUncalledChecksInStatements(body.statements, source, fileName)
                                }
                            }
                            is SetAccessor -> m.body?.let { body ->
                                withUncalledScope(m.parameters, body) {
                                    walkUncalledChecksInStatements(body.statements, source, fileName)
                                }
                            }
                            is PropertyDeclaration -> m.initializer?.let { walkUncalledChecksInExpression(it, source, fileName) }
                            else -> {}
                        }
                    }
                } finally {
                    if (classThisType != null) uncalledThisTypeStack.removeLast()
                }
            }
            is ForInStatement -> {
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
                walkUncalledChecksInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                walkUncalledChecksInExpression(stmt.expression, source, fileName)
                walkUncalledChecksInStatement(stmt.statement, source, fileName)
            }
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                walkUncalledChecksInStatements(clauseStmts, source, fileName)
            }
            is TryStatement -> {
                walkUncalledChecksInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkUncalledChecksInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
            is LabeledStatement -> walkUncalledChecksInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { walkUncalledChecksInExpression(it, source, fileName) }
            is ExportAssignment -> stmt.expression?.let { walkUncalledChecksInExpression(it, source, fileName) }
            else -> {}
        }
    }

    private fun walkUncalledChecksInExpression(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ConditionalExpression -> {
                checkUncalledInCondition(expr.condition, null, source, fileName, extraBodies = listOf(expr.whenTrue, expr.whenFalse))
                walkUncalledChecksInExpression(expr.condition, source, fileName)
                walkUncalledChecksInExpression(expr.whenTrue, source, fileName)
                walkUncalledChecksInExpression(expr.whenFalse, source, fileName)
            }
            is BinaryExpression -> {
                // Flatten the left-spine iteratively to avoid StackOverflow.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                walkUncalledChecksInExpression(cur, source, fileName)
                while (rightStack.isNotEmpty()) {
                    walkUncalledChecksInExpression(rightStack.removeLast(), source, fileName)
                }
            }
            is ParenthesizedExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is CallExpression -> {
                walkUncalledChecksInExpression(expr.expression, source, fileName)
                for (arg in expr.arguments) walkUncalledChecksInExpression(arg, source, fileName)
            }
            is NewExpression -> {
                walkUncalledChecksInExpression(expr.expression, source, fileName)
                expr.arguments?.forEach { walkUncalledChecksInExpression(it, source, fileName) }
            }
            is ArrowFunction -> {
                val body = expr.body
                withUncalledScope(expr.parameters, body as? Block) {
                    if (body is Block) walkUncalledChecksInStatements(body.statements, source, fileName)
                    else if (body is Expression) {
                        // Expression-bodied arrow: treat top-level `&&`/`||`/`??` as a
                        // check site. The arrow's body produces a value rather than
                        // being a tested condition; same in-test-position rule as
                        // ExpressionStatement above.
                        if (isTruthinessChain(body)) {
                            checkUncalledInCondition(body, null, source, fileName, inTestPosition = false)
                        }
                        walkUncalledChecksInExpression(body, source, fileName)
                    }
                }
            }
            is FunctionExpression -> {
                withUncalledScope(expr.parameters, expr.body) {
                    walkUncalledChecksInStatements(expr.body.statements, source, fileName)
                }
            }
            is PropertyAccessExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkUncalledChecksInExpression(expr.expression, source, fileName)
                walkUncalledChecksInExpression(expr.argumentExpression, source, fileName)
            }
            is PrefixUnaryExpression -> walkUncalledChecksInExpression(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkUncalledChecksInExpression(expr.operand, source, fileName)
            is SpreadElement -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkUncalledChecksInExpression(span.expression, source, fileName)
            is ArrayLiteralExpression -> for (e in expr.elements) walkUncalledChecksInExpression(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> walkUncalledChecksInExpression(p.initializer, source, fileName)
                    is ShorthandPropertyAssignment -> p.objectAssignmentInitializer?.let { walkUncalledChecksInExpression(it, source, fileName) }
                    is SpreadAssignment -> walkUncalledChecksInExpression(p.expression, source, fileName)
                    is MethodDeclaration -> p.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is GetAccessor -> p.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is SetAccessor -> p.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is AsExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is SatisfiesExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is NonNullExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkUncalledChecksInExpression(it, source, fileName) }
            is AwaitExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is VoidExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is DeleteExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is TypeOfExpression -> walkUncalledChecksInExpression(expr.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkUncalledChecksInExpression(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkUncalledChecksInExpression(it.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkUncalledChecksInExpression(e, source, fileName)
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { walkUncalledChecksInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { walkUncalledChecksInExpression(it, source, fileName) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /**
     * Walk a truthiness-test expression and emit TS2774 for each operand that
     * is an "always defined" callable identifier or property-access path.
     *
     * For `&&` operators, walks BOTH operands and adds the OTHER operand to
     * suppression sources (so `isFoo && isFoo()` does not emit on `isFoo` —
     * the sibling `isFoo()` is a call referencing the same path).
     * For `||`/`??` operators, walks BOTH operands but does NOT add siblings
     * to suppression sources (`isFoo || isFoo()` still emits on `isFoo`).
     * Mirrors TypeScript's `bothHelper`/`helper` truthiness-walker pair.
     */
    private fun checkUncalledInCondition(
        cond: Expression,
        body: Statement?,
        source: String,
        fileName: String,
        extraBodies: List<Expression> = emptyList(),
        inTestPosition: Boolean = true,
    ) {
        walkUncalledChain(cond, body, source, fileName, extraBodies, andSiblings = emptyList(), inTestPosition = inTestPosition)
    }

    private fun walkUncalledChain(
        expr: Expression,
        body: Statement?,
        source: String,
        fileName: String,
        extraBodies: List<Expression>,
        andSiblings: List<Expression>,
        inTestPosition: Boolean,
    ) {
        var cur: Expression = expr
        while (cur is ParenthesizedExpression) cur = cur.expression
        if (cur is BinaryExpression) {
            when (cur.operator) {
                SyntaxKind.AmpersandAmpersand -> {
                    // `&&`: LHS truthiness is always tested for short-circuit; RHS
                    // truthiness becomes the operator's result and is "tested" only
                    // when the parent context is itself a test (mirrors TypeScript's
                    // bothHelper/helper asymmetry — see `truthinessCallExpressionCoercion2`
                    // where RHS of `&&` inside an ExpressionStatement does NOT fire).
                    walkUncalledChain(cur.left, body, source, fileName, extraBodies, andSiblings + cur.right, inTestPosition = true)
                    walkUncalledChain(cur.right, body, source, fileName, extraBodies, andSiblings + cur.left, inTestPosition = inTestPosition)
                    return
                }
                SyntaxKind.BarBar, SyntaxKind.QuestionQuestion -> {
                    // `||`/`??`: walk both operands; siblings are NOT suppression sources
                    // (because the right side may not execute when left is truthy).
                    // Same asymmetric in-test-position propagation as `&&`.
                    walkUncalledChain(cur.left, body, source, fileName, extraBodies, andSiblings, inTestPosition = true)
                    walkUncalledChain(cur.right, body, source, fileName, extraBodies, andSiblings, inTestPosition = inTestPosition)
                    return
                }
                else -> {}
            }
        }
        // Leaf: emit only when the operand's truthiness is actually being tested.
        if (!inTestPosition) return
        emitUncalledHelper(cur, body, source, fileName, extraBodies + andSiblings)
    }

    private fun emitUncalledHelper(operand: Expression, body: Statement?, source: String, fileName: String, extraBodies: List<Expression> = emptyList()) {
        var location: Expression = operand
        while (location is ParenthesizedExpression) location = location.expression
        // Skip non-checkable kinds
        if (location is CallExpression) return
        if (location is NewExpression) return
        if (location is AwaitExpression) return
        if (location is PrefixUnaryExpression) return
        if (location is BinaryExpression) return

        // Extract the property path: head + property names. Returns null if the
        // expression isn't a pure Identifier or PropertyAccessExpression chain
        // (e.g. contains a CallExpression base) — those aren't supported.
        val path = extractUncalledPath(location) ?: return
        if (path.isEmpty()) return

        // Resolve the type at the operand position using typed-locals scope when
        // available (parameters, local function/var decls, `this.X` chains).
        val type = resolveUncalledOperandType(location, path) ?: return
        if (type === errorType || type === anyType) return
        if (!isAlwaysCallableType(type)) return
        if (typeIsPossiblyNullish(type)) return

        if (body != null && bodyReferencesPath(body, path)) return
        if (extraBodies.any { expressionReferencesPath(it, path) }) return

        val start = location.pos
        val length = expressionTrueEnd(location) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This condition will always return true since this function is always defined. Did you mean to call it instead?",
            category = DiagnosticCategory.Error,
            code = 2774,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Extract the property path of an Identifier-or-PropertyAccessExpression chain.
     * For Identifier(`x`) returns ["x"]. For `this.foo.bar` returns ["this", "foo", "bar"].
     * Returns null if any segment's base isn't an Identifier or PropertyAccessExpression
     * (e.g. `f().bar` — base of `.bar` is a CallExpression — is rejected).
     */
    private fun extractUncalledPath(operand: Expression): List<String>? {
        val rev = mutableListOf<String>()
        var cur: Expression = operand
        while (cur is PropertyAccessExpression) {
            rev.add(cur.name.text)
            cur = cur.expression
            while (cur is ParenthesizedExpression) cur = cur.expression
        }
        if (cur !is Identifier) return null
        rev.add(cur.text)
        return rev.reversed()
    }

    /**
     * Resolve the type at an Identifier or PropertyAccessExpression operand using
     * the typed-locals stack at the head, then walking property segments via
     * `getApparentType` + `getPropertyOfType`. Returns null when the operand
     * cannot be classified (head is shadowed without typed info, or any segment
     * resolves to anyType / errorType).
     */
    private fun resolveUncalledOperandType(operand: Expression, path: List<String>): Type? {
        val head = path[0]
        // Resolve head type
        val headType: Type = when {
            head == "this" -> uncalledThisTypeStack.lastOrNull() ?: return null
            else -> {
                lookupUncalledTypedLocal(head) ?: run {
                    // Fall back to identifier resolution. If shadowed without typed
                    // info, bail to avoid resolving to an unrelated outer binding.
                    if (isUncalledShadowed(head)) return null
                    val headExpr = if (operand is Identifier) operand else findHeadIdentifier(operand) ?: return null
                    val t = try { getTypeOfIdentifier(headExpr) } catch (_: Throwable) { return null }
                    if (t === anyType || t === errorType) return null
                    t
                }
            }
        }
        // Walk property chain
        var t = headType
        for (i in 1 until path.size) {
            if (t === anyType || t === errorType) return null
            val app = try { getApparentType(t) } catch (_: Throwable) { return null }
            val prop = try { getPropertyOfType(app, path[i]) } catch (_: Throwable) { null } ?: return null
            t = try {
                if (app is Type.Reference) {
                    resolveGenericPropertyType(app, prop) ?: getTypeOfSymbol(prop)
                } else {
                    getTypeOfSymbol(prop)
                }
            } catch (_: Throwable) { return null }
            // Honor optional class properties / interface members: `foo?: T`
            // adds undefined to the property type for nullish-detection purposes.
            if (isOptionalProperty(prop)) {
                t = getUnionType(listOf(t, undefinedType))
            }
        }
        if (t === anyType || t === errorType) return null
        return t
    }

    private fun findHeadIdentifier(expr: Expression): Identifier? {
        var cur: Expression = expr
        while (cur is PropertyAccessExpression) {
            cur = cur.expression
            while (cur is ParenthesizedExpression) cur = cur.expression
        }
        return cur as? Identifier
    }

    private fun isAlwaysCallableType(type: Type): Boolean {
        return when (type) {
            is Type.Object -> {
                try { resolveStructuredTypeMembers(type) } catch (_: StackOverflowError) { return false }
                !type.callSignatures.isNullOrEmpty()
            }
            is Type.Union -> type.types.isNotEmpty() && type.types.all { isAlwaysCallableType(it) }
            else -> false
        }
    }

    private fun typeIsPossiblyNullish(type: Type): Boolean {
        return when (type) {
            is Type.Union -> type.types.any { typeIsPossiblyNullish(it) }
            else -> type.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)
        }
    }

    private fun bodyReferencesName(stmt: Statement, name: String): Boolean = statementReferencesName(stmt, name)

    /** Path-aware body suppression: `bodyReferencesPath(body, ["a", "stats", "isDirectory"])` returns true if the body uses `a.stats.isDirectory` (or a call on it) anywhere. */
    private fun bodyReferencesPath(stmt: Statement, path: List<String>): Boolean {
        if (path.size == 1) return statementReferencesName(stmt, path[0])
        return statementReferencesPath(stmt, path)
    }

    private fun statementReferencesPath(stmt: Statement, path: List<String>): Boolean {
        when (stmt) {
            is Block -> return stmt.statements.any { statementReferencesPath(it, path) }
            is ExpressionStatement -> return expressionReferencesPath(stmt.expression, path)
            is ReturnStatement -> return stmt.expression?.let { expressionReferencesPath(it, path) } ?: false
            is IfStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.thenStatement, path)) return true
                stmt.elseStatement?.let { if (statementReferencesPath(it, path)) return true }
            }
            is WhileStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is DoStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForStatement -> {
                stmt.condition?.let { if (expressionReferencesPath(it, path)) return true }
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForInStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForOfStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { if (expressionReferencesPath(it, path)) return true }
            }
            is SwitchStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                for (c in stmt.caseBlock) {
                    if (c is CaseClause && expressionReferencesPath(c.expression, path)) return true
                    val stmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    if (stmts.any { statementReferencesPath(it, path) }) return true
                }
            }
            is TryStatement -> {
                if (stmt.tryBlock.statements.any { statementReferencesPath(it, path) }) return true
                stmt.catchClause?.let { if (it.block.statements.any { s -> statementReferencesPath(s, path) }) return true }
                stmt.finallyBlock?.let { if (it.statements.any { s -> statementReferencesPath(s, path) }) return true }
            }
            is ThrowStatement -> return stmt.expression?.let { expressionReferencesPath(it, path) } ?: false
            is LabeledStatement -> return statementReferencesPath(stmt.statement, path)
            else -> {}
        }
        return false
    }

    private fun expressionReferencesPath(expr: Expression, path: List<String>): Boolean {
        // Try to extract this expression's own path; if it matches `path`, this is a reference.
        extractUncalledPath(expr)?.let { ownPath ->
            // Single-name path: name shadowing rules already enforced by descend logic.
            if (ownPath == path) return true
        }
        // Recurse into children for nested matches.
        when (expr) {
            is PropertyAccessExpression -> return expressionReferencesPath(expr.expression, path)
            is BinaryExpression -> return expressionReferencesPath(expr.left, path) || expressionReferencesPath(expr.right, path)
            is ParenthesizedExpression -> return expressionReferencesPath(expr.expression, path)
            is CallExpression -> {
                if (expressionReferencesPath(expr.expression, path)) return true
                return expr.arguments.any { expressionReferencesPath(it, path) }
            }
            is NewExpression -> {
                if (expressionReferencesPath(expr.expression, path)) return true
                return expr.arguments?.any { expressionReferencesPath(it, path) } ?: false
            }
            is ElementAccessExpression -> return expressionReferencesPath(expr.expression, path) || expressionReferencesPath(expr.argumentExpression, path)
            is PrefixUnaryExpression -> return expressionReferencesPath(expr.operand, path)
            is PostfixUnaryExpression -> return expressionReferencesPath(expr.operand, path)
            is ConditionalExpression -> return expressionReferencesPath(expr.condition, path) || expressionReferencesPath(expr.whenTrue, path) || expressionReferencesPath(expr.whenFalse, path)
            is ArrayLiteralExpression -> return expr.elements.any { expressionReferencesPath(it, path) }
            is ObjectLiteralExpression -> return expr.properties.any { p ->
                when (p) {
                    is PropertyAssignment -> expressionReferencesPath(p.initializer, path)
                    is ShorthandPropertyAssignment -> path.size == 1 && p.name.text == path[0]
                    else -> false
                }
            }
            is SpreadElement -> return expressionReferencesPath(expr.expression, path)
            is AsExpression -> return expressionReferencesPath(expr.expression, path)
            is TypeAssertionExpression -> return expressionReferencesPath(expr.expression, path)
            is SatisfiesExpression -> return expressionReferencesPath(expr.expression, path)
            is NonNullExpression -> return expressionReferencesPath(expr.expression, path)
            is AwaitExpression -> return expressionReferencesPath(expr.expression, path)
            is YieldExpression -> return expr.expression?.let { expressionReferencesPath(it, path) } ?: false
            is TemplateExpression -> return expr.templateSpans.any { expressionReferencesPath(it.expression, path) }
            is CommaListExpression -> return expr.elements.any { expressionReferencesPath(it, path) }
            // Don't descend into nested function bodies that may shadow the head name.
            is ArrowFunction -> {
                if (expr.parameters.any { (it.name as? Identifier)?.text == path[0] }) return false
                val body = expr.body
                return when (body) {
                    is Block -> body.statements.any { statementReferencesPath(it, path) }
                    is Expression -> expressionReferencesPath(body, path)
                    else -> false
                }
            }
            is FunctionExpression -> {
                if (expr.name?.text == path[0]) return false
                if (expr.parameters.any { (it.name as? Identifier)?.text == path[0] }) return false
                return expr.body.statements.any { statementReferencesPath(it, path) }
            }
            else -> {}
        }
        return false
    }

    private fun statementReferencesName(stmt: Statement, name: String): Boolean {
        when (stmt) {
            is Block -> return stmt.statements.any { statementReferencesName(it, name) }
            is ExpressionStatement -> return expressionReferencesName(stmt.expression, name)
            is ReturnStatement -> return stmt.expression?.let { expressionReferencesName(it, name) } ?: false
            is IfStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.thenStatement, name)) return true
                stmt.elseStatement?.let { if (statementReferencesName(it, name)) return true }
            }
            is WhileStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is DoStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForStatement -> {
                stmt.condition?.let { if (expressionReferencesName(it, name)) return true }
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForInStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForOfStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { if (expressionReferencesName(it, name)) return true }
            }
            is SwitchStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                for (c in stmt.caseBlock) {
                    if (c is CaseClause && expressionReferencesName(c.expression, name)) return true
                    val stmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    if (stmts.any { statementReferencesName(it, name) }) return true
                }
            }
            is TryStatement -> {
                if (stmt.tryBlock.statements.any { statementReferencesName(it, name) }) return true
                stmt.catchClause?.let { if (it.block.statements.any { s -> statementReferencesName(s, name) }) return true }
                stmt.finallyBlock?.let { if (it.statements.any { s -> statementReferencesName(s, name) }) return true }
            }
            is ThrowStatement -> return stmt.expression?.let { expressionReferencesName(it, name) } ?: false
            is LabeledStatement -> return statementReferencesName(stmt.statement, name)
            else -> {}
        }
        return false
    }

    private fun expressionReferencesName(expr: Expression, name: String): Boolean {
        when (expr) {
            is Identifier -> return expr.text == name
            is BinaryExpression -> return expressionReferencesName(expr.left, name) || expressionReferencesName(expr.right, name)
            is ParenthesizedExpression -> return expressionReferencesName(expr.expression, name)
            is CallExpression -> {
                if (expressionReferencesName(expr.expression, name)) return true
                return expr.arguments.any { expressionReferencesName(it, name) }
            }
            is NewExpression -> {
                if (expressionReferencesName(expr.expression, name)) return true
                return expr.arguments?.any { expressionReferencesName(it, name) } ?: false
            }
            is PropertyAccessExpression -> return expressionReferencesName(expr.expression, name)
            is ElementAccessExpression -> return expressionReferencesName(expr.expression, name) || expressionReferencesName(expr.argumentExpression, name)
            is PrefixUnaryExpression -> return expressionReferencesName(expr.operand, name)
            is PostfixUnaryExpression -> return expressionReferencesName(expr.operand, name)
            is ConditionalExpression -> return expressionReferencesName(expr.condition, name) || expressionReferencesName(expr.whenTrue, name) || expressionReferencesName(expr.whenFalse, name)
            is ArrayLiteralExpression -> return expr.elements.any { expressionReferencesName(it, name) }
            is ObjectLiteralExpression -> return expr.properties.any { p ->
                when (p) {
                    is PropertyAssignment -> expressionReferencesName(p.initializer, name)
                    is ShorthandPropertyAssignment -> p.name.text == name
                    else -> false
                }
            }
            is SpreadElement -> return expressionReferencesName(expr.expression, name)
            is AsExpression -> return expressionReferencesName(expr.expression, name)
            is TypeAssertionExpression -> return expressionReferencesName(expr.expression, name)
            is SatisfiesExpression -> return expressionReferencesName(expr.expression, name)
            is NonNullExpression -> return expressionReferencesName(expr.expression, name)
            is AwaitExpression -> return expressionReferencesName(expr.expression, name)
            is YieldExpression -> return expr.expression?.let { expressionReferencesName(it, name) } ?: false
            is TemplateExpression -> return expr.templateSpans.any { expressionReferencesName(it.expression, name) }
            is CommaListExpression -> return expr.elements.any { expressionReferencesName(it, name) }
            // Don't descend into nested function bodies that may shadow the name.
            is ArrowFunction -> {
                if (expr.parameters.any { (it.name as? Identifier)?.text == name }) return false
                val body = expr.body
                return when (body) {
                    is Block -> body.statements.any { statementReferencesName(it, name) }
                    is Expression -> expressionReferencesName(body, name)
                    else -> false
                }
            }
            is FunctionExpression -> {
                if (expr.name?.text == name) return false
                if (expr.parameters.any { (it.name as? Identifier)?.text == name }) return false
                return expr.body.statements.any { statementReferencesName(it, name) }
            }
            else -> {}
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Comma operator left side unused (TS2695)
    // -----------------------------------------------------------------------

    private fun checkCommaOperatorUnused() {
        // TypeScript suppresses TS2695 when allowUnreachableCode is explicitly true
        if (options.allowUnreachableCode == true) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCommaInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkCommaInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkCommaInStatement(stmt, source, fileName)
    }

    private fun checkCommaInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkCommaInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkCommaInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkCommaInExpr(it, source, fileName) }
            is IfStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkCommaInStatement(it, source, fileName) }
            }
            is Block -> checkCommaInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkCommaInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkCommaInExpr(it, source, fileName) }
                    is GetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> for (d in init.declarations) {
                            d.initializer?.let { checkCommaInExpr(it, source, fileName) }
                        }
                        is Expression -> checkCommaInExpr(init, source, fileName)
                        else -> {}
                    }
                }
                stmt.condition?.let { checkCommaInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkCommaInExpr(it, source, fileName) }
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkCommaInStatement(stmt.statement, source, fileName)
                checkCommaInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> {
                            checkCommaInExpr(c.expression, source, fileName)
                            checkCommaInStatements(c.statements, source, fileName)
                        }
                        is DefaultClause -> checkCommaInStatements(c.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkCommaInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkCommaInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkCommaInStatements(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkCommaInExpr(it, source, fileName) }
            is LabeledStatement -> checkCommaInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCommaInStatements(it.statements, source, fileName) }
            is EnumDeclaration -> for (m in stmt.members) {
                m.initializer?.let { checkCommaInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    /** Check if this comma expression is an indirect call pattern: (0, obj.prop)() */
    private fun isIndirectCallComma(expr: BinaryExpression): Boolean {
        val right = expr.right
        // (0, obj.method)() — indirect call pattern with property/element access
        if (right is PropertyAccessExpression || right is ElementAccessExpression) return true
        // (0, eval)("code") — indirect eval pattern
        if (right is Identifier && right.text == "eval") return true
        return false
    }

    private fun checkCommaInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // B64.3: iterative left-spine flatten to avoid StackOverflow on
                // deeply nested binary chains (`a + b + c + ... + z`). For each
                // BinaryExpression on the spine, check the Comma-operator rule
                // BEFORE flattening so the per-node diagnostic emission is
                // preserved. Rights are pushed onto a stack and processed at
                // the end via the recursive helper (the standard recursive
                // path handles them since they have bounded depth from the
                // parser).
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    if (cur.operator == SyntaxKind.Comma) {
                        if (!hasSideEffects(cur.left) && !isIndirectCallComma(cur)) {
                            val start = cur.left.pos
                            val length = commaLeftSpanLength(cur.left, start)
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Left side of comma operator is unused and has no side effects.",
                                category = DiagnosticCategory.Error,
                                code = 2695,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkCommaInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) {
                    checkCommaInExpr(rightStack.removeLast(), source, fileName)
                }
            }
            is ParenthesizedExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkCommaInExpr(expr.condition, source, fileName)
                checkCommaInExpr(expr.whenTrue, source, fileName)
                checkCommaInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkCommaInStatements(body.statements, source, fileName)
                is Expression -> checkCommaInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkCommaInStatements(it.statements, source, fileName) }
            is CallExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkCommaInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkCommaInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                checkCommaInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkCommaInExpr(el, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkCommaInExpr(prop.initializer, source, fileName)
                    is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkCommaInExpr(it, source, fileName) }
                    is SpreadAssignment -> checkCommaInExpr(prop.expression, source, fileName)
                    else -> {}
                }
            }
            is PrefixUnaryExpression -> checkCommaInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkCommaInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkCommaInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkCommaInExpr(expr.tag, source, fileName)
                val template = expr.template
                if (template is TemplateExpression) {
                    for (span in template.templateSpans) {
                        checkCommaInExpr(span.expression, source, fileName)
                    }
                }
            }
            is TypeAssertionExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is AsExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is SpreadElement -> checkCommaInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkCommaInExpr(it, source, fileName) }
            is VoidExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is CommaListExpression -> for (el in expr.elements) checkCommaInExpr(el, source, fileName)
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                is Constructor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                is GetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { checkCommaInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    /** Compute squiggle length for the left operand of a comma expression. */
    private fun commaLeftSpanLength(expr: Expression, start: Int): Int {
        return when (expr) {
            // Function expressions: squiggle only covers 'function' keyword (8 chars)
            is FunctionExpression -> 8
            // Arrow functions: squiggle covers the whole expression
            is ArrowFunction -> (expr.end - 1 - start).coerceAtLeast(1)
            // Parenthesized: squiggle covers the whole parenthesized expression
            is ParenthesizedExpression -> (expr.end - 1 - start).coerceAtLeast(1)
            // String literals: text.length + 2 for quotes
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2
            // Template strings: use node span
            is NoSubstitutionTemplateLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Regex literals: use node span
            is RegularExpressionLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Default: use node span
            else -> (expr.end - 1 - start).coerceAtLeast(1)
        }
    }

    /** Check if an expression has side effects (assignments, calls, increments, etc.) */
    private fun hasSideEffects(expr: Expression): Boolean {
        return when (expr) {
            // Assignments always have side effects
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals, SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
                SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals, SyntaxKind.PercentEquals,
                SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals, SyntaxKind.CaretEquals,
                SyntaxKind.LessThanLessThanEquals, SyntaxKind.GreaterThanGreaterThanEquals,
                SyntaxKind.GreaterThanGreaterThanGreaterThanEquals,
                SyntaxKind.AsteriskAsteriskEquals,
                SyntaxKind.BarBarEquals, SyntaxKind.AmpersandAmpersandEquals,
                SyntaxKind.QuestionQuestionEquals -> true
                // Comma: if left has side effects, whole thing does
                SyntaxKind.Comma -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
                // Other binary ops: check both sides
                else -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
            }
            // Increment/decrement have side effects
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> true
                else -> hasSideEffects(expr.operand)
            }
            is PostfixUnaryExpression -> true // ++ and -- always have side effects
            // Function/method calls have side effects
            is CallExpression -> true
            is NewExpression -> true
            is TaggedTemplateExpression -> true
            // Delete has side effects
            is DeleteExpression -> true
            // Yield/await have side effects
            is YieldExpression -> true
            is AwaitExpression -> true
            // Void expression: TypeScript treats as OK (no TS2695)
            is VoidExpression -> true
            // Type assertions: TypeScript treats as OK (no TS2695)
            is TypeAssertionExpression -> true
            is AsExpression -> true
            is SatisfiesExpression -> true
            // Parenthesized: check inner
            is ParenthesizedExpression -> hasSideEffects(expr.expression)
            // Non-null assertion (x!): no side effect
            is NonNullExpression -> hasSideEffects(expr.expression)
            // Conditional: has side effects if any branch does
            is ConditionalExpression -> hasSideEffects(expr.whenTrue) || hasSideEffects(expr.whenFalse)
            // Everything else (literals, identifiers, typeof, array/object literals,
            // arrow functions, function expressions, etc.) — no side effects
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // Null/undefined usage checking (TS18050)
    // -----------------------------------------------------------------------

    /**
     * Check for null/undefined used in invalid positions:
     * property access base, binary operator operands, etc.
     * Emits TS18050: "The value 'null'/'undefined' cannot be used here."
     */
    private fun checkNullUndefinedUsage() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkNullUndefinedInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkNullUndefinedInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkNullUndefinedInStatement(stmt, source, fileName)
    }

    private fun checkNullUndefinedInStatement(stmt: Statement, source: String, fileName: String) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    }
                }
                is ExpressionStatement -> checkNullUndefinedInExpr(stmt.expression, source, fileName)
                is ReturnStatement -> stmt.expression?.let { checkNullUndefinedInExpr(it, source, fileName) }
                is IfStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { checkNullUndefinedInStatement(it, source, fileName) }
                }
                is Block -> checkNullUndefinedInStatements(stmt.statements, source, fileName)
                is ForStatement -> {
                    stmt.initializer?.let { if (it is Expression) checkNullUndefinedInExpr(it, source, fileName) }
                    stmt.condition?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    stmt.incrementor?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is WhileStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is DoStatement -> {
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                }
                is SwitchStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> {
                                checkNullUndefinedInExpr(clause.expression, source, fileName)
                                checkNullUndefinedInStatements(clause.statements, source, fileName)
                            }
                            is DefaultClause -> {
                                checkNullUndefinedInStatements(clause.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> {
                    stmt.body?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            is PropertyDeclaration -> member.initializer?.let {
                                checkNullUndefinedInExpr(it, source, fileName)
                            }
                            is Constructor -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            // B18.4: descend into accessor bodies so TS18050 fires inside
                            // `get x() { throw undefined.; }` and similar patterns.
                            is GetAccessor -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            is SetAccessor -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> {
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkNullUndefinedInStatements(body.statements, source, fileName)
                        else -> {}
                    }
                }
                is ThrowStatement -> stmt.expression?.let { checkNullUndefinedInExpr(it, source, fileName) }
                is ForInStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is ForOfStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is TryStatement -> {
                    checkNullUndefinedInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkNullUndefinedInStatement(stmt.statement, source, fileName)
                is ExportAssignment -> stmt.expression?.let { checkNullUndefinedInExpr(it, source, fileName) }
                else -> {}
            }
        } finally { checkDepth-- }
    }

    private fun checkNullUndefinedInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // Check if null/undefined is used as operand of arithmetic/bitwise operators
                val op = expr.operator
                val isArithmeticOrBitwise = op in setOf(
                    SyntaxKind.Plus, SyntaxKind.Minus,
                    SyntaxKind.Asterisk, SyntaxKind.Slash, SyntaxKind.Percent,
                    SyntaxKind.AsteriskAsterisk,
                    SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret,
                    SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
                    SyntaxKind.GreaterThanGreaterThanGreaterThan,
                    SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
                    SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals,
                    SyntaxKind.PercentEquals, SyntaxKind.AsteriskAsteriskEquals,
                    SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals,
                    SyntaxKind.CaretEquals, SyntaxKind.LessThanLessThanEquals,
                    SyntaxKind.GreaterThanGreaterThanEquals,
                    SyntaxKind.GreaterThanGreaterThanGreaterThanEquals,
                )
                if (isArithmeticOrBitwise && strictNullChecks) {
                    // Under non-strict, TS2365 ("Operator cannot be applied to types 'X' and 'null'")
                    // takes over from TS18050 for arithmetic-with-null/undefined.
                    // For '+' operator, null/undefined is valid when other side is a string
                    val isPlus = op == SyntaxKind.Plus || op == SyntaxKind.PlusEquals
                    val leftIsString = expr.left is StringLiteralNode || expr.left is TemplateExpression ||
                            (expr.left is Identifier && (expr.left as Identifier).text.let { it != "null" && it != "undefined" } && false) // only literals
                    val rightIsString = expr.right is StringLiteralNode || expr.right is TemplateExpression
                    if (!(isPlus && rightIsString)) {
                        checkNullUndefinedLiteral(expr.left, source, fileName)
                    }
                    if (!(isPlus && leftIsString)) {
                        checkNullUndefinedLiteral(expr.right, source, fileName)
                    }
                }
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkNullUndefinedInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkNullUndefinedInExpr(current, source, fileName)
            }
            is PropertyAccessExpression -> {
                // null.foo or undefined.foo
                checkNullUndefinedLiteral(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.expression, source, fileName)
            }
            is ElementAccessExpression -> {
                // null[x] or undefined[x]
                checkNullUndefinedLiteral(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.argumentExpression, source, fileName)
            }
            is CallExpression -> {
                checkNullUndefinedInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkNullUndefinedInExpr(arg, source, fileName)
            }
            is ParenthesizedExpression -> checkNullUndefinedInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkNullUndefinedInExpr(expr.condition, source, fileName)
                checkNullUndefinedInExpr(expr.whenTrue, source, fileName)
                checkNullUndefinedInExpr(expr.whenFalse, source, fileName)
            }
            is PrefixUnaryExpression -> checkNullUndefinedInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkNullUndefinedInExpr(expr.operand, source, fileName)
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkNullUndefinedInExpr(span.expression, source, fileName)
                }
            }
            is ArrayLiteralExpression -> {
                for (elem in expr.elements) checkNullUndefinedInExpr(elem, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkNullUndefinedInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> checkNullUndefinedInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkNullUndefinedInStatements(body.statements, source, fileName)
                    is Expression -> checkNullUndefinedInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkNullUndefinedLiteral(expr: Expression, source: String, fileName: String) {
        // In our AST, null and undefined are parsed as Identifiers
        val keyword = when {
            expr is Identifier && expr.text == "null" -> "null"
            expr is Identifier && expr.text == "undefined" -> "undefined"
            else -> return
        }
        val start = expr.pos
        val length = keyword.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The value '$keyword' cannot be used here.",
            category = DiagnosticCategory.Error,
            code = 18050,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check for type-only names used in value positions.
     * Emits TS2693 "'X' only refers to a type, but is being used as a value here."
     */
    /**
     * TS4081: "Exported type alias 'X' has or is using private name 'Y'."
     *
     * Narrow scope: only fires when `options.declaration` is enabled and a top-level
     * exported `type X = typeof Y;` references a name `Y` that is declared INSIDE a
     * non-top-level block (e.g. `if (false) { export var Y = 0; }`) and NOT also at
     * the file's top level. Other TS4081 patterns (using a non-exported top-level name)
     * require declaration-emission visibility analysis we don't yet model.
     */
    private fun checkExportTypeAliasPrivateNameRef() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val statements = result.sourceFile.statements
            val topLevelValueNames = mutableSetOf<String>()
            val nestedValueNames = mutableSetOf<String>()
            for (stmt in statements) {
                collectTopLevelValueNames(stmt, topLevelValueNames)
            }
            for (stmt in statements) {
                collectNestedValueNames(stmt, nestedValueNames, topLevel = true)
            }
            for (stmt in statements) {
                if (stmt !is TypeAliasDeclaration) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                val aliasName = stmt.name.text
                walkTypeQueryForPrivateName(stmt.type, aliasName, topLevelValueNames, nestedValueNames, source, fileName)
            }
        }
    }

    private fun collectTopLevelValueNames(stmt: Statement, out: MutableSet<String>) {
        when (stmt) {
            is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                (decl.name as? Identifier)?.text?.let { out.add(it) }
            }
            is FunctionDeclaration -> stmt.name?.text?.let { out.add(it) }
            is ClassDeclaration -> stmt.name?.text?.let { out.add(it) }
            is EnumDeclaration -> out.add(stmt.name.text)
            is ModuleDeclaration -> (stmt.name as? Identifier)?.text?.let { out.add(it) }
            else -> {}
        }
    }

    private fun collectNestedValueNames(stmt: Statement, out: MutableSet<String>, topLevel: Boolean) {
        when (stmt) {
            is Block -> for (s in stmt.statements) collectNestedValueNames(s, out, topLevel = false)
            is IfStatement -> {
                collectNestedValueNames(stmt.thenStatement, out, topLevel = false)
                stmt.elseStatement?.let { collectNestedValueNames(it, out, topLevel = false) }
            }
            is ForStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is ForInStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is ForOfStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is WhileStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is DoStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is LabeledStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) collectNestedValueNames(s, out, topLevel = false)
                stmt.catchClause?.let { for (s in it.block.statements) collectNestedValueNames(s, out, topLevel = false) }
                stmt.finallyBlock?.let { for (s in it.statements) collectNestedValueNames(s, out, topLevel = false) }
            }
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                when (clause) {
                    is CaseClause -> for (s in clause.statements) collectNestedValueNames(s, out, topLevel = false)
                    is DefaultClause -> for (s in clause.statements) collectNestedValueNames(s, out, topLevel = false)
                    else -> {}
                }
            }
            is VariableStatement -> if (!topLevel) for (decl in stmt.declarationList.declarations) {
                (decl.name as? Identifier)?.text?.let { out.add(it) }
            }
            is FunctionDeclaration -> if (!topLevel) stmt.name?.text?.let { out.add(it) }
            is ClassDeclaration -> if (!topLevel) stmt.name?.text?.let { out.add(it) }
            else -> {}
        }
    }

    private fun walkTypeQueryForPrivateName(
        type: TypeNode,
        aliasName: String,
        topLevel: Set<String>,
        nested: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (type) {
            is TypeQuery -> {
                val expr = type.exprName
                if (expr is Identifier) {
                    val n = expr.text
                    if (n in nested && n !in topLevel) {
                        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                        diagnostics.add(Diagnostic(
                            message = "Exported type alias '$aliasName' has or is using private name '$n'.",
                            category = DiagnosticCategory.Error,
                            code = 4081,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = expr.pos,
                            length = n.length,
                        ))
                    }
                }
            }
            is UnionType -> type.types.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
            is IntersectionType -> type.types.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
            is ParenthesizedType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            is ArrayType -> walkTypeQueryForPrivateName(type.elementType, aliasName, topLevel, nested, source, fileName)
            is TupleType -> type.elements.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
            is TypeReference -> type.typeArguments?.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) } }
                walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) } }
                walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            }
            is TypeLiteral -> for (m in type.members) {
                when (m) {
                    is PropertyDeclaration -> m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
                    is MethodDeclaration -> {
                        m.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) } }
                        m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
                    }
                    is IndexSignature -> m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName) }
                    else -> {}
                }
            }
            is ConditionalType -> {
                walkTypeQueryForPrivateName(type.checkType, aliasName, topLevel, nested, source, fileName)
                walkTypeQueryForPrivateName(type.extendsType, aliasName, topLevel, nested, source, fileName)
                walkTypeQueryForPrivateName(type.trueType, aliasName, topLevel, nested, source, fileName)
                walkTypeQueryForPrivateName(type.falseType, aliasName, topLevel, nested, source, fileName)
            }
            is IndexedAccessType -> {
                walkTypeQueryForPrivateName(type.objectType, aliasName, topLevel, nested, source, fileName)
                walkTypeQueryForPrivateName(type.indexType, aliasName, topLevel, nested, source, fileName)
            }
            is TypeOperator -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            is RestType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            is OptionalType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName)
            else -> {}
        }
    }

    private fun checkTypeUsedAsValue() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Collect interface/type alias names at file level (type-only declarations)
            // Skip names that also have a class/function/variable declaration (merged)
            val typeOnlyNames = mutableSetOf<String>()
            val valueNames = mutableSetOf<String>()
            val namespaceOnlyNames = mutableSetOf<String>()
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> stmt.name?.text?.let { valueNames.add(it) }
                    is FunctionDeclaration -> stmt.name?.text?.let { valueNames.add(it) }
                    is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                        (decl.name as? Identifier)?.text?.let { valueNames.add(it) }
                    }
                    is EnumDeclaration -> valueNames.add(stmt.name.text)
                    // Import declarations create value bindings (aliases), not type-only names
                    is ImportDeclaration -> {
                        val clause = stmt.importClause ?: continue
                        clause.name?.text?.let { valueNames.add(it) }
                        when (val nb = clause.namedBindings) {
                            is NamespaceImport -> valueNames.add(nb.name.text)
                            is NamedImports -> nb.elements.forEach { spec -> valueNames.add(spec.name.text) }
                            else -> {}
                        }
                    }
                    is ImportEqualsDeclaration -> {
                        // 17.228: `import X = require("./m")` where m has
                        // `export = X` and that X is a type-only entity
                        // (interface/type alias) imports a type-only name —
                        // using `X` as a value is TS2693 just like a local
                        // type-only declaration. Other forms (QualifiedName,
                        // Identifier module reference) stay value-side.
                        //
                        // 17.230: Exclude body-less ambient modules
                        // (`declare module "foo";` with no `{...}` block) —
                        // those are `any`-typed at runtime, so the local name
                        // is value-side. `isAmbientModuleTypeOnly` treats
                        // body-less as type-only (used by Transformer elision)
                        // but for TS2693 emission we need the opposite.
                        //
                        // 17.231: When `export = X` resolves to a type-only
                        // namespace (no value exports), the local name should
                        // fire TS2708 "Cannot use namespace 'X' as a value"
                        // instead of TS2693. Route to `namespaceOnlyNames`.
                        val ref = stmt.moduleReference
                        val spec = (ref as? ExternalModuleReference)?.expression?.let {
                            (it as? StringLiteralNode)?.text
                        }
                        val isBodyless = spec != null && isBodylessAmbientModule(spec)
                        val isTypeOnly = spec != null && isTypeOnlyImportRequire(spec, fileName) && !isBodyless
                        val isTypeOnlyNamespace = isTypeOnly && exportEqualsIsNamespace(spec!!)
                        when {
                            isTypeOnlyNamespace -> namespaceOnlyNames.add(stmt.name.text)
                            isTypeOnly -> typeOnlyNames.add(stmt.name.text)
                            else -> valueNames.add(stmt.name.text)
                        }
                    }
                    else -> {}
                }
            }
            // When @lib explicitly excludes es2015+, user-declared interfaces matching
            // well-known forward-declarable lib types (Promise, Symbol, Map, …) ARE
            // type-only — the lib doesn't provide a value-side counterpart for them.
            // Use as a value fires TS2585 with a lib-hint message instead of TS2693.
            val libExcludesEs2015 = options.lib.isNotEmpty() &&
                options.lib.none { lname ->
                    lname.startsWith("es2") || lname.equals("esnext", ignoreCase = true) ||
                        lname.startsWith("ES2") || lname.equals("ESNext", ignoreCase = true)
                }
            val forwardLibTypeNames = mutableSetOf<String>()
            // iter17 B86.10: aggregate ModuleDeclaration hasValues across ALL
            // declarations with the same name BEFORE deciding namespaceOnly.
            // Without this, a merged-namespace pair like
            //   namespace M { interface T {} }       // type-only
            //   namespace M { export const x = 1 }   // value-bearing
            // mis-classifies M as namespace-only (the first decl wins, second
            // never removes it). Tightening the gate prevents FP TS2708 when
            // the per-decl walk treats hybrid M as a runtime-erased namespace.
            val moduleHasValues = mutableMapOf<String, Boolean>()
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is InterfaceDeclaration -> {
                        val n = stmt.name.text
                        if (n !in valueNames && n !in KNOWN_GLOBALS) typeOnlyNames.add(n)
                        if (libExcludesEs2015 && n !in valueNames &&
                            n in FORWARD_DECLARABLE_LIB_TYPES_ES2015) {
                            forwardLibTypeNames.add(n)
                            typeOnlyNames.add(n)
                        }
                    }
                    is TypeAliasDeclaration -> {
                        val n = stmt.name.text
                        if (n !in valueNames && n !in KNOWN_GLOBALS) typeOnlyNames.add(n)
                    }
                    is ModuleDeclaration -> {
                        val n = (stmt.name as? Identifier)?.text ?: continue
                        if (n !in valueNames) {
                            val body = stmt.body
                            val hasValues = when (body) {
                                is ModuleBlock -> body.statements.any { s ->
                                    s is FunctionDeclaration || s is ClassDeclaration ||
                                        s is VariableStatement || s is EnumDeclaration ||
                                        s is ModuleDeclaration // nested namespace may have value exports
                                }
                                else -> false
                            }
                            // OR-merge across all declarations of the same name
                            moduleHasValues[n] = (moduleHasValues[n] ?: false) || hasValues
                        }
                    }
                    else -> {}
                }
            }
            // Finalize: only names with NO value-bearing declarations are namespace-only
            for ((n, hasValues) in moduleHasValues) {
                if (!hasValues) namespaceOnlyNames.add(n)
            }
            // B87.3 (round 73): under a dotted-only `@lib` (no full es-lib), the
            // base-lib VALUE `declare var Array: ArrayConstructor` (lib.es5.d.ts)
            // is unavailable, so `Array` used as a value is TS2693 even though the
            // Array TYPE is provided by the sub-library. Our embedded lib always
            // loads the value; synthesize the type-only treatment for that name.
            if (!libProvidesBaseValues() && "Array" !in valueNames) {
                typeOnlyNames.add("Array")
            }
            currentForwardLibTypeNames = forwardLibTypeNames
            try {
                checkTypeAsValueInStatements(result.sourceFile.statements, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            } finally {
                currentForwardLibTypeNames = emptySet()
            }
        }
    }

    private fun checkTypeAsValueInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
        namespaceOnlyNames: Set<String> = emptySet(),
    ) {
        for (stmt in statements) {
            checkTypeAsValueInStatement(stmt, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
        }
    }

    private fun checkTypeAsValueInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
        namespaceOnlyNames: Set<String> = emptySet(),
    ) {
        when (stmt) {
            is ExpressionStatement -> checkTypeAsValueInExpr(stmt.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is LabeledStatement -> checkTypeAsValueInStatement(stmt.statement, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            is Block -> checkTypeAsValueInStatements(stmt.statements, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is IfStatement -> {
                checkTypeAsValueInExpr(stmt.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                checkTypeAsValueInStatement(stmt.thenStatement, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                stmt.elseStatement?.let { checkTypeAsValueInStatement(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            }
            is FunctionDeclaration -> {
                // Collect type parameters as type-only within this function
                // But exclude names that are also parameter names (parameter shadows type param)
                val innerTypeOnly = typeOnlyNames.toMutableSet()
                stmt.typeParameters?.forEach { innerTypeOnly.add(it.name.text) }
                // Remove parameter names — they are values, not types
                val innerValues = valueNames.toMutableSet()
                for (p in stmt.parameters) {
                    addParamBindingNamesToValues(p.name, innerTypeOnly, innerValues)
                }
                // B86.9c: walk parameter default initializers AFTER binding names are
                // registered so self-referential defaults `function f(x = x) {}` resolve
                // correctly. Mirror of B86.9b for FunctionExpression/ArrowFunction.
                for (p in stmt.parameters) {
                    p.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                }
                stmt.body?.let { checkTypeAsValueInStatements(it.statements, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
            }
            is ClassDeclaration -> {
                // `extends X` takes a value expression, so type-only names in it are TS2693.
                // `implements X` is a type position and is handled elsewhere.
                // Specialization: when the extended name resolves to a pure interface (no
                // Class/Variable/Function backing), emit TS2689 "Cannot extend an interface
                // 'X'. Did you mean 'implements'?" instead of the generic TS2693. Only the
                // bare-Identifier form (`extends Comparable`, `extends Comparable<T>`) is
                // specialized — qualified names and computed expressions fall through to
                // the existing TS2693 path.
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        clause.types.forEach { ewta ->
                            val ts2689 = tryClassifyExtendsInterface(ewta.expression, valueNames)
                            if (ts2689 != null) {
                                val (leftmost, displayName) = ts2689
                                val (line, character) = getLineAndCharacterOfPosition(source, leftmost.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Cannot extend an interface '$displayName'. Did you mean 'implements'?",
                                    category = DiagnosticCategory.Error,
                                    code = 2689,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = leftmost.pos,
                                    length = leftmost.text.length,
                                ))
                            } else {
                                checkTypeAsValueInExpr(ewta.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                            }
                        }
                    }
                }
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            val innerTypeOnly = typeOnlyNames.toMutableSet()
                            member.typeParameters?.forEach { innerTypeOnly.add(it.name.text) }
                            // iter18 B86.11: register method parameter binding names as
                            // values so a parameter named `N` shadows an outer
                            // namespace-only `N` and doesn't trigger spurious TS2708
                            // / TS2693 inside the method body.
                            val innerValues = valueNames.toMutableSet()
                            for (p in member.parameters) {
                                addParamBindingNamesToValues(p.name, innerTypeOnly, innerValues)
                            }
                            for (p in member.parameters) {
                                p.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                            }
                            member.body?.let { checkTypeAsValueInStatements(it.statements, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                        }
                        is Constructor -> {
                            val innerTypeOnly = typeOnlyNames.toMutableSet()
                            val innerValues = valueNames.toMutableSet()
                            for (p in member.parameters) {
                                addParamBindingNamesToValues(p.name, innerTypeOnly, innerValues)
                            }
                            for (p in member.parameters) {
                                p.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                            }
                            member.body?.let {
                                checkTypeAsValueInStatements(it.statements, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames)
                            }
                        }
                        is PropertyDeclaration -> member.initializer?.let {
                            // iter17 B86.10b: re-attempt B86.9d on top of tightened
                            // namespaceOnlyNames classification (merged-namespace
                            // value+type aggregate). Propagate namespaceOnlyNames so
                            // `class C { x = N }` where N is a pure type-only namespace
                            // fires TS2708 in property initializers.
                            checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                // B86.8: recurse into namespace bodies for TS2708/TS2693. The file-level
                // walker only collected sub-namespaces at the top scope; expressions
                // inside `namespace M { ... }` like `var z = N.X` need their own
                // scope-aware namespace-only set (so a nested `namespace N { }`
                // sibling can fire TS2708). Build inner sets by surveying the
                // namespace body's direct child statements only — recursion handles
                // any deeper nesting. Outer names propagate (a type alias declared
                // at the file level is still type-only inside any namespace body).
                val body = stmt.body ?: return
                if (body !is ModuleBlock) return
                // Self-reference: a namespace's own name is a valid value-side
                // self-reference from inside its body (the JS emit binds the name
                // locally via the IIFE arg). Drop it from inherited
                // `namespaceOnlyNames` so e.g. `namespace N { N; }` does NOT fire
                // TS2708 on the inner `N`.
                val selfName = (stmt.name as? Identifier)?.text
                val innerValueNames = valueNames.toMutableSet().also {
                    if (selfName != null) it.add(selfName)
                }
                val innerTypeOnlyNames = typeOnlyNames.toMutableSet()
                val innerNamespaceOnlyNames = namespaceOnlyNames.toMutableSet().also {
                    if (selfName != null) it.remove(selfName)
                }
                for (s in body.statements) {
                    when (s) {
                        is ClassDeclaration -> s.name?.text?.let { innerValueNames.add(it) }
                        is FunctionDeclaration -> s.name?.text?.let { innerValueNames.add(it) }
                        is VariableStatement -> for (decl in s.declarationList.declarations) {
                            (decl.name as? Identifier)?.text?.let { innerValueNames.add(it) }
                        }
                        is EnumDeclaration -> innerValueNames.add(s.name.text)
                        is InterfaceDeclaration -> {
                            val n = s.name.text
                            if (n !in innerValueNames && n !in KNOWN_GLOBALS) innerTypeOnlyNames.add(n)
                        }
                        is TypeAliasDeclaration -> {
                            val n = s.name.text
                            if (n !in innerValueNames && n !in KNOWN_GLOBALS) innerTypeOnlyNames.add(n)
                        }
                        is ModuleDeclaration -> {
                            val n = (s.name as? Identifier)?.text ?: continue
                            if (n !in innerValueNames) {
                                val subBody = s.body
                                val hasValues = when (subBody) {
                                    is ModuleBlock -> subBody.statements.any { ss ->
                                        ss is FunctionDeclaration || ss is ClassDeclaration ||
                                            ss is VariableStatement || ss is EnumDeclaration ||
                                            ss is ModuleDeclaration
                                    }
                                    else -> false
                                }
                                if (!hasValues) innerNamespaceOnlyNames.add(n)
                            }
                        }
                        else -> {}
                    }
                }
                checkTypeAsValueInStatements(body.statements, source, fileName, innerTypeOnlyNames, innerValueNames, innerNamespaceOnlyNames)
            }
            else -> {}
        }
    }

    /**
     * If the heritage `extends` expression resolves to a pure interface (bare or namespace-
     * qualified like `M.I` / `Mod.Nested.I`), return `(leftmostIdentifier, fullDisplayName)`
     * so the caller can emit TS2689 instead of the generic TS2693/TS2708. Returns null when
     * the expression isn't a bare/qualified-name access, or when the resolved symbol carries
     * value-side flags (Class/Variable/Function) — those are valid `extends` targets.
     */
    private fun tryClassifyExtendsInterface(
        expr: Expression, valueNames: Set<String>,
    ): Pair<Identifier, String>? {
        // Walk the property-access chain leftward, collecting names.
        val names = mutableListOf<String>()
        var leftmost: Identifier? = null
        var current: Expression = expr
        while (true) {
            when (current) {
                is Identifier -> {
                    names.add(0, current.text)
                    leftmost = current
                    break
                }
                is PropertyAccessExpression -> {
                    names.add(0, current.name.text)
                    current = current.expression
                }
                else -> return null
            }
        }
        if (leftmost == null || leftmost.text in valueNames) return null
        // B51.1: skip built-in lib types that are ALSO values (e.g. `Array`,
        // `Object`, `Function`) — TypeScript's full lib.d.ts has both
        // `interface X { ... }` AND `declare const X: XConstructor`, making
        // them valid `extends` targets. Our embedded lib only declares the
        // interface, so the Variable flag is missing — skip via name allowlist.
        if (names.size == 1 && leftmost.text in BUILTIN_LIB_VALUE_INTERFACES) return null
        // Walk the symbol chain: leftmost in scope, then each step via `exports`.
        var symbol: Symbol? = currentFileLocals?.get(names[0]) ?: globals[names[0]] ?: return null
        for (i in 1 until names.size) {
            val nextSym = symbol?.exports?.get(names[i]) ?: return null
            symbol = nextSym
        }
        val resolved = symbol ?: return null
        if (!resolved.flags.hasAny(SymbolFlags.Interface)) return null
        if (resolved.flags.hasAny(SymbolFlags.Class or SymbolFlags.Variable or SymbolFlags.Function)) return null
        return leftmost to names.joinToString(".")
    }

    private fun checkTypeAsValueInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
        namespaceOnlyNames: Set<String> = emptySet(),
    ) {
        when (expr) {
            is Identifier -> {
                val name = expr.text
                // Skip if the name is declared as a value (variable/parameter shadows type keyword)
                if (name !in valueNames && (name in TYPE_ONLY_KEYWORDS || name in typeOnlyNames)) {
                    emitTS2693(name, expr, source, fileName)
                } else if (name !in valueNames && name in namespaceOnlyNames) {
                    // TS2708: Cannot use namespace 'X' as a value.
                    val start = expr.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot use namespace '$name' as a value.",
                        category = DiagnosticCategory.Error,
                        code = 2708,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = name.length,
                    ))
                }
            }
            is NewExpression -> {
                // Check the constructor expression
                val ctorExpr = expr.expression
                if (ctorExpr is Identifier) {
                    val name = ctorExpr.text
                    if (name !in valueNames && (name in TYPE_ONLY_KEYWORDS || name in typeOnlyNames)) {
                        emitTS2693(name, ctorExpr, source, fileName)
                    }
                } else {
                    // Non-Identifier ctor expressions may still contain type-only names
                    // in value positions (e.g. `new number[]` parses as
                    // `new (ElementAccess(number, missing))` — the `number` is value-pos).
                    checkTypeAsValueInExpr(ctorExpr, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                }
                // Recurse into arguments
                expr.arguments?.forEach { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            }
            is CallExpression -> {
                checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                expr.arguments.forEach { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            }
            is BinaryExpression -> {
                // Iteratively walk binary chains to avoid StackOverflow on deep trees
                // For `=` assignment, skip left side for TS2708 (checkConstAssignment handles it)
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkTypeAsValueInExpr(current.right, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                    if (current.operator == SyntaxKind.Equals) {
                        // Assignment: check left side for TS2693 only, not TS2708 (avoid duplicate with checkConstAssignment)
                        checkTypeAsValueInExpr(current.left, source, fileName, typeOnlyNames, valueNames)
                        return
                    }
                    current = current.left
                }
                checkTypeAsValueInExpr(current, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            }
            is TypeOfExpression -> {
                // typeof T where T is a type param → TS2693
                val operand = expr.expression
                if (operand is Identifier) {
                    val name = operand.text
                    if (name !in valueNames && name in typeOnlyNames) {
                        emitTS2693(name, operand, source, fileName)
                    }
                }
            }
            is ParenthesizedExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is ConditionalExpression -> {
                checkTypeAsValueInExpr(expr.condition, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                checkTypeAsValueInExpr(expr.whenTrue, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                checkTypeAsValueInExpr(expr.whenFalse, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            }
            is PropertyAccessExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is ElementAccessExpression -> {
                checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                checkTypeAsValueInExpr(expr.argumentExpression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            }
            // Descend into function/arrow bodies — type-as-value checks apply inside
            // IIFE-style `(function() { new ForwardLibType; })` patterns.
            is FunctionExpression -> {
                val innerTypeOnly = typeOnlyNames.toMutableSet()
                val innerValues = valueNames.toMutableSet()
                for (p in expr.parameters) {
                    addParamBindingNamesToValues(p.name, innerTypeOnly, innerValues)
                }
                // B86.9b: walk parameter default initializers AFTER binding names are
                // registered so self-referential defaults `(x = x) =>` resolve correctly.
                for (p in expr.parameters) {
                    p.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                }
                checkTypeAsValueInStatements(expr.body.statements, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames)
            }
            is ArrowFunction -> {
                val innerTypeOnly = typeOnlyNames.toMutableSet()
                val innerValues = valueNames.toMutableSet()
                for (p in expr.parameters) {
                    addParamBindingNamesToValues(p.name, innerTypeOnly, innerValues)
                }
                // B86.9b: walk parameter default initializers AFTER binding names are
                // registered so self-referential defaults `(x = x) =>` resolve correctly.
                for (p in expr.parameters) {
                    p.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames) }
                }
                when (val body = expr.body) {
                    is Block -> checkTypeAsValueInStatements(body.statements, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames)
                    is Expression -> checkTypeAsValueInExpr(body, source, fileName, innerTypeOnly, innerValues, namespaceOnlyNames)
                    else -> {}
                }
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            // Value-preserving wrappers — recurse through the inner expression
            is AsExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is TypeAssertionExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is SatisfiesExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is NonNullExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            // Unary / expression wrappers
            is PrefixUnaryExpression -> checkTypeAsValueInExpr(expr.operand, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is PostfixUnaryExpression -> checkTypeAsValueInExpr(expr.operand, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is SpreadElement -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is AwaitExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is YieldExpression -> expr.expression?.let { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames) }
            is VoidExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            is DeleteExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            // Note: TypeOfExpression handled above with TS2693 logic
            // Template / tagged template — recurse into spans (tag is checked for TaggedTemplate)
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkTypeAsValueInExpr(span.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            }
            is TaggedTemplateExpression -> {
                checkTypeAsValueInExpr(expr.tag, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                val template = expr.template
                if (template is TemplateExpression) {
                    for (span in template.templateSpans) {
                        checkTypeAsValueInExpr(span.expression, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
                    }
                }
            }
            is CommaListExpression -> for (e in expr.elements) {
                checkTypeAsValueInExpr(e, source, fileName, typeOnlyNames, valueNames, namespaceOnlyNames)
            }
            else -> {}
        }
    }

    /**
     * Walk a parameter binding (Identifier / ObjectBindingPattern / ArrayBindingPattern)
     * and register every introduced local-name in [innerValues] so subsequent body checks
     * don't flag them as type-as-value misuses. Each registered name is also removed from
     * [innerTypeOnly] (the parameter binding shadows any same-named outer type-only symbol).
     * Mirrors [addBindingName] but populates the type-as-value walker's name sets instead
     * of a [NameScope].
     */
    private fun addParamBindingNamesToValues(
        name: Node,
        innerTypeOnly: MutableSet<String>,
        innerValues: MutableSet<String>,
    ) {
        when (name) {
            is Identifier -> {
                innerTypeOnly.remove(name.text)
                innerValues.add(name.text)
            }
            is ObjectBindingPattern -> {
                for (element in name.elements) {
                    addParamBindingNamesToValues(element.name, innerTypeOnly, innerValues)
                }
            }
            is ArrayBindingPattern -> {
                for (element in name.elements) {
                    if (element is BindingElement) {
                        addParamBindingNamesToValues(element.name, innerTypeOnly, innerValues)
                    }
                }
            }
            else -> {}
        }
    }

    private fun emitTS2693(name: String, node: Node, source: String, fileName: String) {
        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Forward-declarable lib types (Promise, Symbol, Map, …) under restrictive @lib
        // get the more specific TS2585 with a lib-hint message instead of TS2693.
        val (code, message) = if (name in currentForwardLibTypeNames) {
            2585 to "'$name' only refers to a type, but is being used as a value here. Do you need to change your target library? Try changing the 'lib' compiler option to es2015 or later."
        } else {
            2693 to "'$name' only refers to a type, but is being used as a value here."
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Unreachable code checking (TS7027)
    // -----------------------------------------------------------------------

    /**
     * Check for unreachable code after return, throw, break, continue,
     * and infinite loops.
     */
    private fun checkUnreachableCode() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUnreachableInStatements(result.sourceFile.statements, source, fileName, result)
        }
    }

    private fun checkUnreachableInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        var termIdx = -1
        var currentRun = mutableListOf<Statement>()

        for (i in statements.indices) {
            val stmt = statements[i]
            if (termIdx >= 0) {
                // After a terminating statement: collect unreachable runs separated by hoisted decls.
                // Hoisted = doesn't generate runtime code:
                //   - FunctionDeclaration: truly hoisted (JS var hoisting)
                //   - InterfaceDeclaration, TypeAliasDeclaration: type-only, erased
                //   - ImportDeclaration, ImportEqualsDeclaration, ExportDeclaration: module-level
                //   - VariableStatement with var flags: var declarations are function-hoisted
                //   - ModuleDeclaration that is non-instantiated (only type-only contents)
                val isHoisted = stmt is FunctionDeclaration ||
                    stmt is InterfaceDeclaration ||
                    stmt is TypeAliasDeclaration ||
                    stmt is ImportDeclaration ||
                    stmt is ImportEqualsDeclaration ||
                    stmt is ExportDeclaration ||
                    isVarDeclaration(stmt) ||
                    isNonPreservedConstEnum(stmt) ||
                    isNonInstantiatedNamespace(stmt, binderResult)
                if (isHoisted) {
                    // Emit current run if non-empty
                    if (currentRun.isNotEmpty()) {
                        emitTS7027(currentRun, source, fileName)
                        currentRun = mutableListOf()
                    }
                    // Recurse into hoisted declaration (it IS reachable for inner checks)
                    checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
                } else {
                    // Add to current unreachable run (do NOT recurse — it's unreachable)
                    currentRun.add(stmt)
                }
            } else {
                // Before the terminating statement: check normally
                if (isDefinitelyTerminating(stmt)) {
                    termIdx = i
                }
                // Recurse into nested blocks
                checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
            }
        }

        // Emit final run if any unreachable statements remain
        if (currentRun.isNotEmpty()) {
            emitTS7027(currentRun, source, fileName)
        }
    }

    /**
     * Returns true for `var` variable statements with NO initializer (pure declarations).
     * TypeScript does not report TS7027 for bare `var x;` after unreachable code because
     * `var` declarations without initializers are hoisted and have no runtime side effects.
     * `var x = 1;` (with initializer) IS reported since the initializer is unreachable code.
     */
    private fun isVarDeclaration(stmt: Statement): Boolean {
        if (stmt !is VariableStatement) return false
        if (stmt.declarationList.flags != SyntaxKind.VarKeyword) return false
        // Only treat as hoisted if ALL declarations have no initializer
        return stmt.declarationList.declarations.all { it.initializer == null }
    }

    /**
     * Returns true if a ModuleDeclaration is non-instantiated or const-enum-only (produces no runtime code).
     * Non-instantiated/ConstEnumOnly namespaces contain only type-only declarations (interfaces, type aliases,
     * non-preserved const enums) and are treated like hoisted declarations for TS7027 purposes.
     */
    private fun isNonInstantiatedNamespace(stmt: Statement, binderResult: BinderResult): Boolean {
        if (stmt !is ModuleDeclaration) return false
        val state = binderResult.moduleInstanceStates[nodeKey(stmt)]
        return state == ModuleInstanceState.NonInstantiated || state == ModuleInstanceState.ConstEnumOnly
    }

    /**
     * Returns true if this is a non-preserved `const enum` declaration.
     * Without `preserveConstEnums`, const enums are type-only (inlined at use sites)
     * and should not be reported as unreachable code.
     */
    private fun isNonPreservedConstEnum(stmt: Statement): Boolean {
        if (stmt !is EnumDeclaration) return false
        if (ModifierFlag.Const !in stmt.modifiers) return false
        return !options.preserveConstEnums
    }

    private fun isDefinitelyTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is ThrowStatement -> true
            is BreakStatement -> true
            is ContinueStatement -> true
            is WhileStatement -> {
                // while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is DoStatement -> {
                // do {} while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is ForStatement -> {
                // for(;;) with no break is infinite
                stmt.condition == null && !containsBreak(stmt.statement)
            }
            is IfStatement -> {
                val thenTerm = isBlockTerminating(stmt.thenStatement)
                val elseTerm = stmt.elseStatement?.let { isBlockTerminating(it) } ?: false
                // if (cond) { ... } else { ... } — both branches terminate
                // if (true) { ... } — always-true with terminating then branch (no else needed)
                (thenTerm && elseTerm) || (thenTerm && stmt.elseStatement == null && isAlwaysTrue(stmt.expression))
            }
            is SwitchStatement -> {
                // All cases terminate → switch is terminating
                val clauses = stmt.caseBlock
                val hasDefault = clauses.any { it is DefaultClause }
                val allTerminate = clauses.all { clause ->
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Empty case clauses fall through to the next
                    clauseStmts.isEmpty() || clauseStmts.any { isDefinitelyTerminating(it) }
                }
                if (hasDefault) return allTerminate
                // No default: check for exhaustive typeof switch
                if (!allTerminate) return false
                val caseClauses = clauses.filterIsInstance<CaseClause>()
                if (caseClauses.isEmpty()) return false
                // switch(typeof x) covering all 8 typeof values is exhaustive
                if (stmt.expression is TypeOfExpression) {
                    val typeofValues = setOf("string", "number", "bigint", "boolean", "symbol", "undefined", "object", "function")
                    val coveredValues = caseClauses.mapNotNull { (it.expression as? StringLiteralNode)?.text }.toSet()
                    if (coveredValues.containsAll(typeofValues)) return true
                }
                // Heuristic — treat as exhaustive if all case clauses have statements and terminate
                caseClauses.all { it.statements.isNotEmpty() }
            }
            is TryStatement -> {
                // Try block terminates and there's no catch that doesn't terminate
                isBlockTerminating(stmt.tryBlock) &&
                    (stmt.catchClause == null || isBlockTerminating(stmt.catchClause!!.block))
            }
            is ExpressionStatement -> {
                // A call to a never-returning function terminates (e.g., fail(): never)
                isNeverReturningExpression(stmt.expression)
            }
            else -> false
        }
    }

    /** Check if an expression is a call to a function with return type `never`. */
    private fun isNeverReturningExpression(expr: Expression): Boolean {
        if (expr !is CallExpression) return false
        val callee = expr.expression
        if (callee !is Identifier) return false
        // Look up the function symbol
        val symbol = globals[callee.text] ?: return false
        if (!symbol.flags.hasAny(SymbolFlags.Function)) return false
        // Check if the function's return type is never
        val decl = symbol.declarations.firstOrNull() as? FunctionDeclaration ?: return false
        val retType = decl.type ?: return false
        return retType is KeywordTypeNode && retType.kind == SyntaxKind.NeverKeyword
    }

    private fun isBlockTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is Block -> stmt.statements.any { isDefinitelyTerminating(it) }
            else -> isDefinitelyTerminating(stmt)
        }
    }

    private fun isAlwaysTrue(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "true"
            is ParenthesizedExpression -> isAlwaysTrue(expr.expression)
            is AsExpression -> isAlwaysTrue(expr.expression)
            is SatisfiesExpression -> isAlwaysTrue(expr.expression)
            is NonNullExpression -> isAlwaysTrue(expr.expression)
            is TypeAssertionExpression -> isAlwaysTrue(expr.expression)
            else -> false
        }
    }

    private fun isAlwaysFalse(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "false"
            is ParenthesizedExpression -> isAlwaysFalse(expr.expression)
            is AsExpression -> isAlwaysFalse(expr.expression)
            is SatisfiesExpression -> isAlwaysFalse(expr.expression)
            is NonNullExpression -> isAlwaysFalse(expr.expression)
            is TypeAssertionExpression -> isAlwaysFalse(expr.expression)
            else -> false
        }
    }

    /**
     * Returns true if a call expression is an IIFE that always throws.
     * Pattern: `(function() { throw X; })()` or `(() => { throw X; })()`
     */
    private fun exprAlwaysThrows(expr: Expression): Boolean {
        if (expr !is CallExpression) return false
        val func = expr.expression
        val funcBody: List<Statement> = when {
            func is FunctionExpression -> func.body?.statements ?: return false
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression as FunctionExpression).body?.statements ?: return false
            func is ArrowFunction -> {
                val body = func.body
                when (body) {
                    is Block -> body.statements
                    is ThrowStatement -> listOf(body)
                    else -> return false
                }
            }
            func is ParenthesizedExpression && func.expression is ArrowFunction -> {
                val body = (func.expression as ArrowFunction).body
                when (body) {
                    is Block -> body.statements
                    else -> return false
                }
            }
            else -> return false
        }
        return funcBody.any { it is ThrowStatement }
    }

    /**
     * Report unreachable code inside an IIFE's body statements.
     * Used for for-loop condition/incrementor that's unreachable.
     */
    private fun reportUnreachableIIFEBody(expr: Expression?, source: String, fileName: String) {
        if (expr == null) return
        val callExpr = expr as? CallExpression ?: return
        val func = callExpr.expression
        val funcBody: List<Statement>? = when {
            func is FunctionExpression -> func.body?.statements
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression as FunctionExpression).body?.statements
            else -> null
        }
        if (!funcBody.isNullOrEmpty()) {
            emitTS7027(funcBody, source, fileName)
        }
    }

    private fun containsBreak(stmt: Statement): Boolean {
        return when (stmt) {
            // Only count UNLABELED breaks. A labeled `break test;` jumps to its
            // labeled target (which is OUTSIDE this loop), so it does NOT fall
            // through to the statement immediately after this loop — for the
            // purposes of "does this loop have an early-exit that would prevent
            // it being infinite/terminating", labeled breaks escape further and
            // are equivalent to a return/throw at this level. Required for
            // reachabilityChecks5/6 f11: `do { do { break test; } while(true); x++; } while(true);`
            // — the inner do's `break test` jumps out beyond the outer do, so
            // x++ is unreachable.
            is BreakStatement -> stmt.label == null
            is Block -> stmt.statements.any { containsBreak(it) }
            is IfStatement -> containsBreak(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsBreak(it) } ?: false)
            is LabeledStatement -> containsBreak(stmt.statement)
            // Don't recurse into nested loops/switches — break applies to them, not the outer
            else -> false
        }
    }

    private fun checkUnreachableInNestedStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        when (stmt) {
            is Block -> checkUnreachableInStatements(stmt.statements, source, fileName, binderResult)
            is IfStatement -> {
                if (isAlwaysTrue(stmt.expression)) {
                    // if(true) { ... } else { ... } — else branch is unreachable
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    val elseStmt = stmt.elseStatement
                    if (elseStmt != null) {
                        // Mark else branch as unreachable
                        val elseStmts = if (elseStmt is Block) elseStmt.statements
                                        else listOf(elseStmt)
                        emitTS7027(elseStmts, source, fileName)
                        // Also recurse into else for inner unreachable checks (but mark outer as unreachable)
                    }
                } else {
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    stmt.elseStatement?.let { checkUnreachableInNestedStatement(it, source, fileName, binderResult) }
                }
            }
            is ForStatement -> {
                // If the for-loop's initializer always throws, the condition and incrementor
                // are unreachable. TypeScript reports TS7027 on the IIFE body statements
                // inside the condition and incrementor expressions.
                val initTerminates = stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> false
                        is Expression -> exprAlwaysThrows(init)
                        else -> false
                    }
                } ?: false
                if (initTerminates) {
                    // Report unreachable code inside IIFE bodies of condition and incrementor
                    reportUnreachableIIFEBody(stmt.condition, source, fileName)
                    reportUnreachableIIFEBody(stmt.incrementor, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is ForInStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ForOfStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is WhileStatement -> {
                if (isAlwaysFalse(stmt.expression)) {
                    // while(false) { ... } — body is unreachable
                    val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements
                                    else listOf(stmt.statement)
                    emitTS7027(bodyStmts, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is DoStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkUnreachableInStatements(clauseStmts, source, fileName, binderResult)
                }
            }
            is TryStatement -> {
                checkUnreachableInStatements(stmt.tryBlock.statements, source, fileName, binderResult)
                stmt.catchClause?.let {
                    checkUnreachableInStatements(it.block.statements, source, fileName, binderResult)
                }
                stmt.finallyBlock?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { checkUnreachableInStatements(it.statements, source, fileName, binderResult) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is Constructor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is GetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is SetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ExpressionStatement -> {
                // Check arrow/function expressions
                when (val expr = stmt.expression) {
                    is ArrowFunction -> when (val body = expr.body) {
                        is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                        else -> {}
                    }
                    is FunctionExpression -> expr.body?.let {
                        checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                    }
                    else -> {}
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    when (val init = decl.initializer) {
                        is ArrowFunction -> when (val body = init.body) {
                            is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                            else -> {}
                        }
                        is FunctionExpression -> init.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body as? ModuleBlock ?: return
                checkUnreachableInStatements(body.statements, source, fileName, binderResult)
            }
            is ReturnStatement -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            is ThrowStatement -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            is ExportAssignment -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            else -> {}
        }
    }

    private fun emitTS7027(stmts: List<Statement>, source: String, fileName: String) {
        if (stmts.isEmpty()) return
        val first = stmts.first()
        // Skip leading whitespace on first statement
        var actualStart = first.pos
        while (actualStart < source.length && source[actualStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            actualStart++
        }
        // For `const enum` declarations, the parser sets pos to the `enum` keyword
        // (since the caller consumes `const` via nextToken() before calling parseEnumDeclaration).
        // Look backwards to include the `const` keyword in the span start.
        actualStart = findConstEnumStart(source, first, actualStart)
        // Compute real span end for the last statement.
        // stmt.end includes one extra "next token" due to how our parser captures end positions.
        // Use a forward scan to find the natural end of the last statement.
        val spanEnd = computeUnreachableSpanEnd(source, stmts.last(), actualStart)
        val length = spanEnd - actualStart
        val (line, character) = getLineAndCharacterOfPosition(source, actualStart)
        diagnostics.add(Diagnostic(
            message = "Unreachable code detected.",
            category = DiagnosticCategory.Error,
            code = 7027,
            fileName = fileName,
            line = line,
            character = character,
            start = actualStart,
            length = length.coerceAtLeast(1),
        ))
    }

    /**
     * For `const enum` declarations, the parser sets `pos` to the `enum` keyword because the
     * caller consumed `const` via `nextToken()` before invoking `parseEnumDeclaration`.
     * This function looks backwards from the node pos to include `const` in the span start.
     */
    private fun findConstEnumStart(source: String, stmt: Statement, currentStart: Int): Int {
        if (stmt !is EnumDeclaration || ModifierFlag.Const !in stmt.modifiers) return currentStart
        // Look backwards from currentStart for "const" keyword
        var pos = currentStart - 1
        // Skip any whitespace/space between const and enum
        while (pos >= 0 && source[pos].let { it == ' ' || it == '\t' }) pos--
        // Check if source[pos-4..pos] == "const"
        if (pos >= 4 && source.substring(pos - 4, pos + 1) == "const") {
            return pos - 4
        }
        return currentStart
    }

    /**
     * Compute the real end of the last unreachable statement, excluding the
     * contaminating "next outer token" that stmt.end includes due to the scanner
     * advancing one token ahead during parsing.
     */
    private fun computeUnreachableSpanEnd(source: String, stmt: Statement, minStart: Int): Int {
        // Find the start of the statement text (after leading trivia)
        var start = stmt.pos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            start++
        }
        start = start.coerceAtLeast(minStart)

        // Forward scan to find natural statement end (avoids the "next token" contamination)
        val naturalEnd = findStatementNaturalEnd(source, start, stmt.end)

        if (naturalEnd < stmt.end) {
            // Found a natural end before stmt.end — the scan terminated cleanly
            return naturalEnd
        }

        // Reached stmt.end without a natural terminator (e.g., ASI case at top level).
        // Trim trailing whitespace from stmt.end.
        var spanEnd = stmt.end
        while (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            spanEnd--
        }

        // If the last char is '}', it may be the contaminating outer closing token.
        // Apply backward trimming to remove it and its preceding whitespace.
        if (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1] == '}') {
            while (spanEnd > start && source[spanEnd - 1].let { it != ' ' && it != '\t' && it != '\n' && it != '\r' }) {
                spanEnd--
            }
            while (spanEnd > start && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
                spanEnd--
            }
        }

        return spanEnd.coerceAtLeast(start + 1)
    }

    /**
     * Scan forward from [start] to find where the statement's content naturally ends,
     * not exceeding [upTo]. Tracks bracket depth to correctly handle nested blocks.
     *
     * Returns position AFTER the closing ';' or '}' that terminates the statement at depth 0.
     * Returns [upTo] if no natural end is found within the range.
     */
    private fun findStatementNaturalEnd(source: String, start: Int, upTo: Int): Int {
        var i = start
        var depth = 0
        var inString = false
        var stringChar = ' '

        while (i < upTo && i < source.length) {
            val ch = source[i]
            if (inString) {
                when {
                    ch == '\\' -> { i += 2; continue }
                    ch == stringChar -> { inString = false; i++ }
                    else -> i++
                }
                continue
            }
            when (ch) {
                '"', '\'' -> { inString = true; stringChar = ch; i++ }
                '`' -> { inString = true; stringChar = ch; i++ }
                '{', '(' , '[' -> { depth++; i++ }
                '}' -> {
                    depth--
                    i++
                    when {
                        depth < 0 -> return i - 1   // outer closing brace — stop BEFORE it
                        depth == 0 -> {
                            // Block closed at top level. Check if a ';' immediately follows
                            // (e.g. `x = function() { ... };` — need to include the ';').
                            var k = i
                            while (k < source.length && source[k].let { it == ' ' || it == '\t' }) k++
                            return if (k < upTo && k < source.length && source[k] == ';') k + 1 else i
                        }
                    }
                }
                ')', ']' -> { depth--; i++ }
                ';' -> { if (depth == 0) return i + 1; else i++ }
                else -> i++
            }
        }
        return i  // reached upTo (e.g., EOF or stmt.end)
    }

    // -----------------------------------------------------------------------
    // Missing function implementation checking (TS2391)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method overload declarations that are missing their
     * implementation. Emits TS2391 "Function implementation is missing or
     * not immediately following the declaration."
     */
    private fun checkMissingImplementations() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — TS8017 handles bodiless functions in JS
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            checkMissingImplInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkMissingImplInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        // Check file-level function declarations
        for (i in statements.indices) {
            val stmt = statements[i]
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null && ModifierFlag.Declare !in stmt.modifiers) {
                        val name = stmt.name?.text ?: continue
                        // Check what follows this overload signature
                        val implResult = findImplementation(statements, i, name)
                        when (implResult) {
                            is ImplResult.Found -> {} // Same name follows
                            is ImplResult.WrongName -> {
                                // Next function has body but different name → TS2389
                                emitTS2389(implResult.nameNode, source, fileName, name)
                            }
                            is ImplResult.Missing -> {
                                emitTS2391(stmt.name!!, source, fileName)
                            }
                        }
                    }
                }
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        checkMissingImplInClass(stmt.members, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        val body = stmt.body as? ModuleBlock ?: continue
                        checkMissingImplInStatements(body.statements, source, fileName)
                    }
                }
                is Block -> checkMissingImplInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkMissingImplInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let {
                        checkMissingImplInStatements(listOf(it), source, fileName)
                    }
                }
                else -> {}
            }
        }
    }

    private sealed class ImplResult {
        data object Found : ImplResult()
        data class WrongName(val nameNode: Node) : ImplResult()
        data object Missing : ImplResult()
    }

    private fun findImplementation(
        statements: List<Statement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        // Look at subsequent statements for a same-name function.
        for (j in fromIdx + 1 until statements.size) {
            val next = statements[j]
            if (next is FunctionDeclaration) {
                if (next.name?.text == name) {
                    return ImplResult.Found // Same name follows
                }
                // Different name with body → TS2389
                if (next.body != null && next.name != null) {
                    return ImplResult.WrongName(next.name!!)
                }
            }
            break // Different statement breaks the chain
        }
        return ImplResult.Missing
    }

    private fun checkMissingImplInClass(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Track methods with bodies for TS2393 duplicate implementation detection
        val methodsWithBody = mutableMapOf<String, MethodDeclaration>()

        for (i in members.indices) {
            val member = members[i]
            if (member is Constructor && member.body == null) {
                // Constructor overload without body — check if a constructor WITH body follows
                val hasImpl = members.subList(i + 1, members.size).any { it is Constructor && it.body != null }
                if (!hasImpl) {
                    // TypeScript emits TS2390 ONLY on the LAST constructor in the overload group
                    // (the implementation would be expected to immediately follow it).
                    // Skip emission if a subsequent member is another bodyless Constructor.
                    val isLastBodylessCtor = members.subList(i + 1, members.size)
                        .none { it is Constructor && it.body == null }
                    if (isLastBodylessCtor) {
                        // Emit TS2390 on the "constructor" keyword span
                        emitTS2390(member, source, fileName)
                    }
                }
            } else if (member is MethodDeclaration) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> continue
                }
                // Include static qualifier in the key to distinguish instance vs static
                val isStatic = ModifierFlag.Static in member.modifiers
                val key = if (isStatic) "static:$name" else name

                if (member.body != null) {
                    val prev = methodsWithBody[key]
                    if (prev != null) {
                        // Duplicate implementation — TS2393 on both
                        emitTS2393(prev.name, source, fileName)
                        emitTS2393(member.name, source, fileName)
                    } else {
                        methodsWithBody[key] = member
                    }
                } else if (ModifierFlag.Abstract !in member.modifiers) {
                    // Overload without body — check for missing implementation
                    val displayName = when (member.name) {
                        is StringLiteralNode -> "\"$name\""
                        else -> name
                    }
                    val implResult = findMethodImplementation(members, i, name)
                    when (implResult) {
                        is ImplResult.Found -> {} // Same name follows
                        is ImplResult.WrongName -> {
                            emitTS2389(implResult.nameNode, source, fileName, displayName)
                        }
                        is ImplResult.Missing -> {
                            emitTS2391(member.name, source, fileName)
                        }
                    }
                }
            }
            // Recurse into nested class declarations
            if (member is PropertyDeclaration) {
                val init = member.initializer
                if (init is ClassExpression) {
                    checkMissingImplInClass(init.members, source, fileName)
                }
            }
        }
    }

    private fun emitTS2393(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> nameNode.text
            is NumericLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Duplicate function implementation.",
            category = DiagnosticCategory.Error,
            code = 2393,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun findMethodImplementation(
        members: List<ClassElement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        for (j in fromIdx + 1 until members.size) {
            val next = members[j]
            if (next is MethodDeclaration) {
                val nextName = when (val n = next.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> null
                }
                if (nextName == name) {
                    return ImplResult.Found
                }
                // Different name with body → TS2389
                if (next.body != null && nextName != null) {
                    return ImplResult.WrongName(next.name)
                }
            }
            break // Non-matching member breaks the chain
        }
        return ImplResult.Missing
    }

    // -----------------------------------------------------------------------
    // Bodyless function return type checking (TS7010)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method declarations without a body that lack a return
     * type annotation. Emits TS7010 when:
     * - The declaration is ambient (declare function) without return type, OR
     * - The declaration is a non-ambient overload with no matching implementation
     *   (same name with body) anywhere in the same scope.
     * This check is suppressed when @strict: false is explicitly set (like TS2454/TS2564).
     */
    private fun checkBodylessFunctionReturnTypesMissing() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            // .d.ts files are checked only when noImplicitAny is on — TS7010 requires
            // noImplicitAny/strict for implicit-any diagnostics in ambient contexts.
            if (isDtsFile(fileName) && !(options.noImplicitAny || options.strict)) continue
            // Skip JS files — TS8017 handles bodiless functions
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            checkTS7010InStatements(result.sourceFile.statements, source, fileName, inAmbientContext = isDtsFile(fileName))
        }
    }

    private fun checkTS7010InStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isAmbientClass: Boolean = false,
        inAmbientContext: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null && stmt.name != null && stmt.type == null) {
                        val name = stmt.name!!.text
                        // Emit TS7010 for all bodyless function declarations (both declare and overloads)
                        // that lack a return type annotation, regardless of whether an implementation exists.
                        emitTS7010(stmt.name!!, name, source, fileName)
                    }
                    stmt.body?.let { checkTS7010InStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    val isAmbient = ModifierFlag.Declare in stmt.modifiers || inAmbientContext
                    // Check methods in class body (recurse with ambient context)
                    for (member in stmt.members) {
                        if (member is MethodDeclaration && member.body == null && member.type == null) {
                            val name = (member.name as? Identifier)?.text
                                ?: (member.name as? StringLiteralNode)?.text
                            if (name != null && isAmbient) {
                                // In ambient classes, only PUBLIC methods get TS7010
                                val isPrivate = ModifierFlag.Private in member.modifiers
                                if (!isPrivate) {
                                    emitTS7010(member.name!!, name, source, fileName)
                                }
                            }
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    // Interface method signatures without return type annotation get TS7010/TS7020/TS7021.
                    // The squiggle covers the full method signature (from name through `;`).
                    for (member in stmt.members) {
                        if (member is MethodDeclaration && member.type == null) {
                            val nameNode = member.name
                            val rawName = (nameNode as? Identifier)?.text
                                ?: (nameNode as? StringLiteralNode)?.text
                                ?: ((nameNode as? ComputedPropertyName)?.expression as? Identifier)?.let { "[${it.text}]" }
                            if (rawName != null) {
                                when {
                                    rawName.isEmpty() -> {
                                        // Call signature `()` — emit TS7020
                                        emitTS7020WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    rawName == "new" -> {
                                        // Construct signature `new()` — emit TS7013
                                        emitTS7013WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    else -> {
                                        // Named method signature (including ComputedPropertyName
                                        // wrapping a single Identifier — displayed as `[id]`) —
                                        // emit TS7010.
                                        emitTS7010WithSpan(member.pos, member.end - member.pos, rawName, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val childAmbient = inAmbientContext || ModifierFlag.Declare in stmt.modifiers
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkTS7010InStatements(body.statements, source, fileName, inAmbientContext = childAmbient)
                    } else if (body is ModuleDeclaration) {
                        checkTS7010InStatements(listOf(body), source, fileName, inAmbientContext = childAmbient)
                    }
                }
                is Block -> checkTS7010InStatements(stmt.statements, source, fileName, inAmbientContext = inAmbientContext)
                is IfStatement -> {
                    checkTS7010InStatements(listOf(stmt.thenStatement), source, fileName, inAmbientContext = inAmbientContext)
                    stmt.elseStatement?.let { checkTS7010InStatements(listOf(it), source, fileName, inAmbientContext = inAmbientContext) }
                }
                is ForStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is ForInStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is ForOfStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is WhileStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is DoStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkTS7010InStatements(clause.statements, source, fileName, inAmbientContext = inAmbientContext)
                            is DefaultClause -> checkTS7010InStatements(clause.statements, source, fileName, inAmbientContext = inAmbientContext)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkTS7010InStatements(stmt.tryBlock.statements, source, fileName, inAmbientContext = inAmbientContext)
                    stmt.catchClause?.block?.let { checkTS7010InStatements(it.statements, source, fileName, inAmbientContext = inAmbientContext) }
                    stmt.finallyBlock?.let { checkTS7010InStatements(it.statements, source, fileName, inAmbientContext = inAmbientContext) }
                }
                is LabeledStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                else -> {}
            }
        }
    }

    /** Check if any function declaration with [name] and a body exists in [statements]. */
    private fun hasImplementationInScope(statements: List<Statement>, name: String): Boolean {
        return statements.any { it is FunctionDeclaration && it.name?.text == name && it.body != null }
    }

    private fun emitTS7010(nameNode: Node, nameText: String, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length + 2 // include quotes
            else -> return
        }
        emitTS7010WithSpan(start, length, nameText, source, fileName)
    }

    private fun emitTS7010WithSpan(start: Int, length: Int, nameText: String, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$nameText', which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7010,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7020: Call signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7020WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Call signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7020,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7013: Construct signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7013WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Construct signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7013,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2390(constructor: Constructor, source: String, fileName: String) {
        // TS2390: "Constructor implementation is missing." — squiggle covers "constructor" keyword
        val pos = constructor.pos
        val length = "constructor".length
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Constructor implementation is missing.",
            category = DiagnosticCategory.Error,
            code = 2390,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = length,
        ))
    }

    private fun emitTS2391(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation is missing or not immediately following the declaration.",
            category = DiagnosticCategory.Error,
            code = 2391,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2389(nameNode: Node, source: String, fileName: String, expectedName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> "\"${nameNode.text}\""
            is NumericLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation name must be '$expectedName'.",
            category = DiagnosticCategory.Error,
            code = 2389,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Argument count checking (TS2554)
    // -----------------------------------------------------------------------

    /**
     * Check call and new expressions for wrong argument counts.
     * Only handles simple, direct function calls and class constructors
     * in the same file. Skips overloaded functions and rest parameters.
     */
    private fun checkArgumentCounts() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // In JS files (allowJs/checkJs), all parameters are implicitly optional (min=0)
            val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx") || fileName.endsWith(".mjs") || fileName.endsWith(".cjs")

            // Build function/class declaration maps for this file
            val funcParams = mutableMapOf<String, FuncParamInfo>()
            val classCtorParams = mutableMapOf<String, FuncParamInfo>()
            collectFuncDecls(result.sourceFile.statements, funcParams, classCtorParams, isJsFile)

            // B95c (round 82): a class with an `extends` base but NO own constructor inherits
            // the base's constructor arity. collectFuncDecls records NOTHING for these (a
            // forward reference like `class derived extends base {}` where `base` is declared
            // later can't be resolved during the single linear pass), so `new derived()` was
            // never arity-checked. Resolve inherited ctors here via a fixpoint (handles forward
            // references and `A extends B extends C` chains). Conservative: a class whose base
            // is unresolvable (imported, mixin-expression base, circular) stays unrecorded → no
            // TS2554, never a false positive.
            val pendingCtorInherit = mutableMapOf<String, String>()
            collectInheritedCtorPending(result.sourceFile.statements, classCtorParams, pendingCtorInherit)
            var inheritChanged = true
            while (inheritChanged && pendingCtorInherit.isNotEmpty()) {
                inheritChanged = false
                val iter = pendingCtorInherit.entries.iterator()
                while (iter.hasNext()) {
                    val e = iter.next()
                    val baseInfo = classCtorParams[e.value]
                    if (baseInfo != null) {
                        classCtorParams[e.key] = baseInfo
                        iter.remove()
                        inheritChanged = true
                    }
                }
            }

            // Walk statements checking call expressions
            checkArgCountInStatements(result.sourceFile.statements, funcParams, classCtorParams, source, fileName)
        }
    }

    private data class FuncParamInfo(
        val minParams: Int,     // required params
        val maxParams: Int,     // total params (required + optional)
        val hasRest: Boolean,   // has ...rest param
        val isOverloaded: Boolean, // has multiple declarations (skip checking)
        val parameters: List<Parameter> = emptyList(), // actual parameter nodes (for related info)
        // B95b: per-overload SIGNATURE arity+type-param info (excludes impl sig). Lets a
        // call with EXPLICIT type args filter the overload set to the generic signatures
        // that can actually accept that many type args, then arity-check against THAT subset.
        val overloadSigs: List<OverloadSig> = emptyList(),
    )

    /** One overload SIGNATURE's arity + type-param shape (for explicit-type-arg filtering). */
    private data class OverloadSig(
        val minParams: Int,
        val maxParams: Int,
        val hasRest: Boolean,
        val typeParamCount: Int,     // total type parameters
        val minTypeParams: Int,      // type parameters without a default (required type args)
        val parameters: List<Parameter>,
    )

    /** Best-effort OverloadSig from an already-collected FuncParamInfo (type-param shape
     *  unknown → treated as non-generic; conservative for explicit-type-arg filtering). */
    private fun overloadSigFromInfo(info: FuncParamInfo): OverloadSig =
        OverloadSig(info.minParams, info.maxParams, info.hasRest, 0, 0, info.parameters)

    private fun overloadSigOf(stmt: FunctionDeclaration, isJsFile: Boolean): OverloadSig {
        val pi = paramInfo(stmt.parameters, isJsFile)
        val tps = stmt.typeParameters
        return OverloadSig(
            minParams = pi.minParams,
            maxParams = pi.maxParams,
            hasRest = pi.hasRest,
            typeParamCount = tps?.size ?: 0,
            minTypeParams = tps?.count { it.default == null } ?: 0,
            parameters = stmt.parameters,
        )
    }

    /** B95c: collect classes that have an `extends` base but no own constructor and are not
     *  already recorded by collectFuncDecls (no-heritage / circular / own-ctor cases). Maps
     *  className → single-Identifier base name for the post-collection inheritance fixpoint. */
    private fun collectInheritedCtorPending(
        statements: List<Statement>,
        classCtorParams: Map<String, FuncParamInfo>,
        pending: MutableMap<String, String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    if (classCtorParams.containsKey(name)) continue
                    if (stmt.members.any { it is Constructor }) continue
                    val extClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseName = (extClause.types.firstOrNull()?.expression as? Identifier)?.text ?: continue
                    pending[name] = baseName
                }
                is ModuleDeclaration -> {
                    val body = stmt.body as? ModuleBlock ?: continue
                    collectInheritedCtorPending(body.statements, classCtorParams, pending)
                }
                else -> {}
            }
        }
    }

    private fun collectFuncDecls(
        statements: List<Statement>,
        funcParams: MutableMap<String, FuncParamInfo>,
        classCtorParams: MutableMap<String, FuncParamInfo>,
        isJsFile: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    if (stmt.body == null) {
                        // B70.10: Body-less FunctionDeclaration. If another declaration of the
                        // same name already exists (or appears later), this is an overload
                        // signature. If it's the SOLE declaration (typical
                        // `declare function f(...)`), treat the signature as authoritative
                        // for arity. Use a two-pass-aware merge: any previously-recorded
                        // info implies an overload, AND we look ahead briefly to see if a
                        // sibling declaration follows.
                        // B95 (round 80): for overload groups, accumulate the arity RANGE
                        // across the overload SIGNATURES (excluding the impl) so a call whose
                        // arg count matches NO overload can fire TS2554. (Was: collapsed to
                        // (0, MAX, rest) which suppressed all overload arity checking.)
                        val thisInfo = paramInfo(stmt.parameters, isJsFile)
                        val thisSig = overloadSigOf(stmt, isJsFile)
                        val existing = funcParams[name]
                        if (existing != null) {
                            val baseMin = if (existing.isOverloaded) existing.minParams else thisInfo.minParams
                            val baseMax = if (existing.isOverloaded) existing.maxParams else thisInfo.maxParams
                            val baseRest = existing.isOverloaded && existing.hasRest
                            // Preserve the FIRST overload signature's parameters — TypeScript's
                            // TS6210 "An argument for 'x' was not provided." points at the first
                            // overload's param at the missing index.
                            val firstParams = if (existing.isOverloaded) existing.parameters else thisInfo.parameters
                            val baseSigs = if (existing.isOverloaded) existing.overloadSigs else listOf(overloadSigFromInfo(existing))
                            funcParams[name] = FuncParamInfo(
                                minParams = minOf(baseMin, thisInfo.minParams),
                                maxParams = maxOf(baseMax, thisInfo.maxParams),
                                hasRest = baseRest || thisInfo.hasRest,
                                isOverloaded = true,
                                parameters = firstParams,
                                overloadSigs = baseSigs + thisSig,
                            )
                            continue
                        }
                        // Look ahead in the same statement list for a sibling declaration.
                        val hasSibling = statements.any { other ->
                            other !== stmt && other is FunctionDeclaration && other.name?.text == name
                        }
                        if (hasSibling) {
                            // Seed the overload group with THIS signature's arity.
                            funcParams[name] = thisInfo.copy(isOverloaded = true, overloadSigs = listOf(thisSig))
                            continue
                        }
                        // Sole declaration — record its real param info
                        funcParams[name] = thisInfo
                        continue
                    }
                    if (funcParams[name]?.isOverloaded == true) continue // impl of an overloaded fn — keep overload arity
                    val info = paramInfo(stmt.parameters, isJsFile)
                    funcParams[name] = info
                }
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    val ctor = stmt.members.filterIsInstance<Constructor>().firstOrNull()
                    if (ctor != null) {
                        val info = paramInfo(ctor.parameters, isJsFile)
                        classCtorParams[name] = info
                    } else if (stmt.heritageClauses.isNullOrEmpty()) {
                        // No explicit constructor and no base class → 0 params
                        classCtorParams[name] = FuncParamInfo(0, 0, hasRest = false, isOverloaded = false)
                    } else if (classHasCircularBase(stmt)) {
                        // 16.4cr: Circular base (e.g. `class S18 extends S18<…>`) — the base
                        // is unresolvable so there's no inherited ctor to defer to. Treat as
                        // no-arg implicit constructor for TS2554 purposes.
                        classCtorParams[name] = FuncParamInfo(0, 0, hasRest = false, isOverloaded = false)
                    }
                    // Skip classes with base class but no explicit constructor —
                    // they inherit the base constructor's param count which we can't resolve
                }
                is ModuleDeclaration -> {
                    val body = stmt.body as? ModuleBlock ?: continue
                    collectFuncDecls(body.statements, funcParams, classCtorParams, isJsFile)
                }
                is VariableStatement -> {
                    // B64.2: const variables initialized with an arrow function or function
                    // expression with NO type annotation (otherwise the annotation's signature
                    // governs the call arity, not the initializer's). Restricted to `const`
                    // because `let`/`var` can be reassigned to a function with different arity.
                    val isConst = stmt.declarationList.flags == SyntaxKind.ConstKeyword
                    if (!isConst) continue
                    for (decl in stmt.declarationList.declarations) {
                        val nameNode = decl.name as? Identifier ?: continue
                        val varName = nameNode.text
                        if (decl.type != null) continue
                        val init = decl.initializer
                        val params: List<Parameter>? = when (init) {
                            is ArrowFunction -> init.parameters
                            is FunctionExpression -> init.parameters
                            else -> null
                        }
                        if (params == null) continue
                        // Don't overwrite an existing entry (e.g. same name as a FunctionDeclaration).
                        if (funcParams.containsKey(varName)) continue
                        funcParams[varName] = paramInfo(params, isJsFile)
                    }
                }
                else -> {}
            }
        }
    }

    private fun paramInfo(parameters: List<Parameter>, isJsFile: Boolean = false): FuncParamInfo {
        var total = 0
        var hasRest = false
        var lastRequiredPos = -1  // 0-based index of last non-optional param
        for (p in parameters) {
            // Skip `this` pseudo-parameter
            if (p.name is Identifier && (p.name as Identifier).text == "this") continue
            if (p.dotDotDotToken) {
                hasRest = true
                continue
            }
            // In JS files (checkJs), all parameters are implicitly optional (min=0, max=N)
            if (!isJsFile && !p.questionToken && p.initializer == null) {
                lastRequiredPos = total
            }
            total++
        }
        // Required = position of last required param + 1.
        // E.g., f(a, b = 0, c) → lastRequiredPos = 2 → required = 3.
        // This ensures optional params before a required one are effectively required.
        val required = lastRequiredPos + 1
        return FuncParamInfo(required, total, hasRest, isOverloaded = false, parameters = parameters)
    }

    private fun checkArgCountInStatements(
        statements: List<Statement>,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        // 17.126: Block-level FunctionDeclarations shadow outer same-named
        // functions for arity-checking. Build an overlay map combining the
        // outer funcParams with any FunctionDeclaration directly in this
        // statement list. This frame goes out of scope when the enclosing
        // call returns, so it doesn't leak past the block boundary.
        val nestedFuncs = statements.asSequence()
            .filterIsInstance<FunctionDeclaration>()
            .filter { it.body != null && it.name != null }
            .toList()
        val effective: Map<String, FuncParamInfo> = if (nestedFuncs.isNotEmpty()) {
            val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                    fileName.endsWith(".mjs") || fileName.endsWith(".cjs")
            val overlay = funcParams.toMutableMap()
            for (fd in nestedFuncs) {
                val name = fd.name?.text ?: continue
                // Don't downgrade overload markers from the outer scope (the
                // overlay is a refinement, not a wholesale replacement).
                if (overlay[name]?.isOverloaded == true) continue
                overlay[name] = paramInfo(fd.parameters, isJsFile)
            }
            overlay
        } else {
            funcParams
        }
        for (stmt in statements) {
            checkArgCountInStatement(stmt, effective, classCtorParams, source, fileName)
        }
    }

    private fun checkArgCountInStatement(
        stmt: Statement,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is IfStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.thenStatement, funcParams, classCtorParams, source, fileName)
                stmt.elseStatement?.let { checkArgCountInStatement(it, funcParams, classCtorParams, source, fileName) }
            }
            is Block -> checkArgCountInStatements(stmt.statements, funcParams, classCtorParams, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                        }
                    }
                    is Expression -> checkArgCountInExpr(init, funcParams, classCtorParams, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                stmt.incrementor?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is ForInStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is ForOfStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is WhileStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is DoStatement -> {
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
            }
            is SwitchStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkArgCountInStatements(clauseStmts, funcParams, classCtorParams, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            is ClassDeclaration -> {
                // Look up base-class ctor info for super() arity checks inside this class's
                // constructor body. Only handles same-file Identifier base names whose ctor
                // params we've already collected.
                val baseCtorInfo: FuncParamInfo? = stmt.heritageClauses
                    ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                    ?.types?.firstOrNull()
                    ?.expression
                    ?.let { (it as? Identifier)?.text }
                    ?.let { classCtorParams[it] }
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is Constructor -> member.body?.let {
                            val prevSuper = argCountSuperCtor
                            argCountSuperCtor = baseCtorInfo
                            try {
                                checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                            } finally {
                                argCountSuperCtor = prevSuper
                            }
                        }
                        is GetAccessor -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is SetAccessor -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is PropertyDeclaration -> member.initializer?.let {
                            checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkArgCountInStatements(stmt.tryBlock.statements, funcParams, classCtorParams, source, fileName)
                stmt.catchClause?.let {
                    checkArgCountInStatements(it.block.statements, funcParams, classCtorParams, source, fileName)
                }
                stmt.finallyBlock?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            is LabeledStatement -> checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is ExportAssignment -> stmt.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkArgCountInExpr(
        expr: Expression,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        if (++argCountDepth > 200) { argCountDepth--; return }
        try { checkArgCountInExprCore(expr, funcParams, classCtorParams, source, fileName) }
        finally { argCountDepth-- }
    }

    private fun checkArgCountInExprCore(
        expr: Expression,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is CallExpression -> {
                // Check the callee
                val calleeName = when (val e = expr.expression) {
                    is Identifier -> e.text
                    else -> null
                }
                if (calleeName != null) {
                    val info = if (calleeName == "super") argCountSuperCtor else funcParams[calleeName]
                    if (info != null && !info.isOverloaded) {
                        val argCount = expr.arguments.size
                        if (!info.hasRest && argCount > info.maxParams) {
                            emitTS2554TooMany(info.minParams, info.maxParams, argCount, expr.arguments, info.maxParams, source, fileName)
                        } else if (argCount < info.minParams) {
                            if (info.hasRest) {
                                emitTS2555TooFew(info.minParams, argCount, expr.expression, source, fileName, info.parameters)
                            } else {
                                emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName, info.parameters)
                            }
                        }
                    } else if (info != null && info.isOverloaded && expr.typeArguments.isNullOrEmpty()) {
                        // B95 (round 80): overload-arity TS2554. Emit ONLY when the call's arg
                        // count is outside the [min, max] arity RANGE of all overload signatures
                        // — i.e. NO overload could match by arity. Within range, an overload may
                        // match (type-based TS2769 handles type mismatches). No related TS6210/6211
                        // (TypeScript omits the "argument for 'x'" hint for overload arity errors).
                        // Skipped when explicit type args are present (those filter overloads to
                        // generic ones, changing the applicable arity — out of scope here).
                        val argCount = expr.arguments.size
                        if (argCount < info.minParams) {
                            emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName, info.parameters)
                        } else if (!info.hasRest && argCount > info.maxParams) {
                            emitTS2554TooMany(info.minParams, info.maxParams, argCount, expr.arguments, info.maxParams, source, fileName)
                        }
                    } else if (info != null && info.isOverloaded && !expr.typeArguments.isNullOrEmpty()
                        && info.overloadSigs.isNotEmpty()
                    ) {
                        // B95b (round 81): overload call WITH explicit type args, e.g.
                        // `foo<string>("hello")` against `foo<T>(a,b)` + `foo(a)`. Explicit type
                        // args filter the overload set to the GENERIC signatures that can accept
                        // this many type args (non-generic overloads are inapplicable). Arity-check
                        // the call against ONLY that applicable subset. functionCall18 case.
                        val typeArgCount = expr.typeArguments!!.size
                        val applicable = info.overloadSigs.filter { sig ->
                            sig.typeParamCount > 0 && typeArgCount in sig.minTypeParams..sig.typeParamCount
                        }
                        if (applicable.isNotEmpty()) {
                            val argCount = expr.arguments.size
                            val gMin = applicable.minOf { it.minParams }
                            val gMax = applicable.maxOf { it.maxParams }
                            val gRest = applicable.any { it.hasRest }
                            // TS6210 "argument for 'x' not provided" only when the applicable subset
                            // is unambiguous (single signature) — matches TypeScript's hint.
                            val relParams = if (applicable.size == 1) applicable[0].parameters else emptyList()
                            if (argCount < gMin) {
                                emitTS2554TooFew(gMin, gMax, argCount, expr.expression, source, fileName, relParams)
                            } else if (!gRest && argCount > gMax) {
                                emitTS2554TooMany(gMin, gMax, argCount, expr.arguments, gMax, source, fileName)
                            }
                        }
                    }
                }
                // Recurse into arguments
                for (arg in expr.arguments) {
                    checkArgCountInExpr(arg, funcParams, classCtorParams, source, fileName)
                }
                checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            }
            is NewExpression -> {
                val className = when (val e = expr.expression) {
                    is Identifier -> e.text
                    else -> null
                }
                if (className != null) {
                    val info = classCtorParams[className]
                    if (info != null && !info.isOverloaded) {
                        val argCount = expr.arguments?.size ?: 0
                        if (!info.hasRest && argCount > info.maxParams) {
                            val args = expr.arguments ?: emptyList()
                            emitTS2554TooMany(info.minParams, info.maxParams, argCount, args, info.maxParams, source, fileName)
                        } else if (argCount < info.minParams) {
                            // B95c (round 82): squiggle the WHOLE `new X(...)` (expr.pos .. after `)`),
                            // not just the class identifier — matches TypeScript. Pass info.parameters
                            // so the TS6210 "argument for 'x' not provided" related info fires (it points
                            // at the ctor's param at the missing index; for an inherited ctor that's the
                            // base class's param).
                            if (info.hasRest) {
                                emitTS2555TooFew(info.minParams, argCount, expr, source, fileName, info.parameters)
                            } else {
                                emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr, source, fileName, info.parameters)
                            }
                        }
                    }
                }
                // Recurse
                expr.arguments?.forEach { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            }
            is BinaryExpression -> {
                // Iterative right-spine walk to prevent StackOverflow on deep chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkArgCountInExpr(current.left, funcParams, classCtorParams, source, fileName)
                    current = current.right
                }
                checkArgCountInExpr(current, funcParams, classCtorParams, source, fileName)
            }
            is ParenthesizedExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is ConditionalExpression -> {
                checkArgCountInExpr(expr.condition, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.whenTrue, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.whenFalse, funcParams, classCtorParams, source, fileName)
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkArgCountInStatements(body.statements, funcParams, classCtorParams, source, fileName)
                    is Expression -> checkArgCountInExpr(body, funcParams, classCtorParams, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) {
                    checkArgCountInExpr(el, funcParams, classCtorParams, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkArgCountInExpr(prop.initializer, funcParams, classCtorParams, source, fileName)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> checkArgCountInExpr(prop.expression, funcParams, classCtorParams, source, fileName)
                        is MethodDeclaration -> prop.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkArgCountInExpr(span.expression, funcParams, classCtorParams, source, fileName)
                }
            }
            is TaggedTemplateExpression -> {
                // Tagged template `f\`...${a}${b}...\`` calls `f([], a, b, ...)`.
                // argCount = 1 (TemplateStringsArray) + spans.size.
                // For unterminated templates, the parser may stop before adding the
                // last span — count an extra substitution when isUnterminated is set.
                val calleeName = (expr.tag as? Identifier)?.text
                if (calleeName != null) {
                    val info = funcParams[calleeName]
                    if (info != null && !info.isOverloaded) {
                        val templateExpr = expr.template as? TemplateExpression
                        val spanCount = templateExpr?.templateSpans?.size ?: 0
                        val unterminatedBonus = if (templateExpr?.isUnterminated == true) 1 else 0
                        val argCount = 1 + spanCount + unterminatedBonus
                        if (!info.hasRest && argCount > info.maxParams) {
                            // Position the diagnostic at the template's end (close-backtick or EOF
                            // for unterminated cases). Length 0 — matches TypeScript's emit.
                            val pos = expr.template.end
                            val (line, character) = getLineAndCharacterOfPosition(source, pos)
                            diagnostics.add(Diagnostic(
                                message = "Expected ${formatExpectedArgs(info.minParams, info.maxParams)} arguments, but got $argCount.",
                                category = DiagnosticCategory.Error,
                                code = 2554,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = pos,
                                length = 0,
                            ))
                        }
                    }
                }
                checkArgCountInExpr(expr.tag, funcParams, classCtorParams, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach { span ->
                    checkArgCountInExpr(span.expression, funcParams, classCtorParams, source, fileName)
                }
            }
            is PropertyAccessExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is ElementAccessExpression -> {
                checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.argumentExpression, funcParams, classCtorParams, source, fileName)
            }
            is PrefixUnaryExpression -> checkArgCountInExpr(expr.operand, funcParams, classCtorParams, source, fileName)
            is PostfixUnaryExpression -> checkArgCountInExpr(expr.operand, funcParams, classCtorParams, source, fileName)
            is TypeAssertionExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is AsExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is SatisfiesExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is NonNullExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is CommaListExpression -> for (el in expr.elements) checkArgCountInExpr(el, funcParams, classCtorParams, source, fileName)
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName) }
                    is Constructor -> m.body?.let { checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName) }
                    is GetAccessor -> m.body?.let { checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName) }
                    is SetAccessor -> m.body?.let { checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                    else -> {}
                }
            }
            is SpreadElement -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is AwaitExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is YieldExpression -> expr.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is VoidExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is TypeOfExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is DeleteExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is TaggedTemplateExpression -> {
                checkArgCountInExpr(expr.tag, funcParams, classCtorParams, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Emit TS2554 for too many arguments.
     * Squiggle covers args[expectedCount] through args.last().
     */
    private fun formatExpectedArgs(minParams: Int, maxParams: Int): String =
        if (minParams != maxParams) "$minParams-$maxParams" else "$maxParams"

    private fun emitTS2554TooMany(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        args: List<Expression>,
        firstExcessIdx: Int,
        source: String,
        fileName: String,
    ) {
        if (firstExcessIdx >= args.size) return
        val firstExcess = args[firstExcessIdx]
        val lastArg = args.last()
        val start = firstExcess.pos
        // Node.end includes the next token's scan position (always 1 char: ',' or ')'),
        // so subtract 1 to get the actual end of the argument text.
        val length = lastArg.end - 1 - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2554TooFew(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Check if the first missing parameter is a binding pattern → emit TS6211 related info
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            // Find the first missing parameter (at index `actual`, skipping `this` params)
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name as Identifier).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is Identifier -> {
                        // TS6210: "An argument for 'x' was not provided."
                        // B95c (round 82): anchor at the PARAMETER's pos (Parameter.pos is captured
                        // before modifiers, so for a parameter-property `public n` it points at
                        // `public` — matching TypeScript), not the name's pos. For a plain param,
                        // Parameter.pos == name.pos so function-call TS6210 is unaffected.
                        val paramStart = missingParam.pos
                        val paramLen = (paramName.pos + paramName.text.length - paramStart).coerceAtLeast(1)
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    /**
     * Emit TS2555 for too few arguments when function has rest parameters.
     * "Expected at least N arguments, but got M."
     */
    private fun emitTS2555TooFew(
        minParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name as Identifier).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is Identifier -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected at least $minParams arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2555,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    // -----------------------------------------------------------------------
    // Implicit this checking (TS2683)
    // -----------------------------------------------------------------------

    /**
     * Check for `this` expressions in functions without a `this:` parameter annotation
     * when noImplicitThis is enabled. Emits TS2683.
     *
     * The "this context" tracks whether `this` is typed (in a class member) or untyped
     * (in a regular function without `this:` param). Arrow functions are transparent —
     * they inherit the outer `this` context.
     *
     * @param shadowFunctionPos when non-null, the position of the function that shadows
     *   an outer typed `this` (for the related TS2738 diagnostic)
     */
    // -----------------------------------------------------------------------
    // TS2526: `this` type outside a class/interface member (B98b, round 82)
    // -----------------------------------------------------------------------
    /** A `this` TYPE (ThisType node) is only valid inside a non-static class/interface member.
     *  Used as an actual type elsewhere — most commonly a type predicate `x is this` in an
     *  OBJECT-LITERAL method — it's TS2526. Narrow + FP-safe: only fires for a ThisType in an
     *  object-literal method/accessor return-type predicate's asserted TYPE (NOT the predicate
     *  SUBJECT `this is X`, which is the OK polymorphic-this form). Class/interface members are
     *  never visited, so valid `this` types there are untouched. */
    private fun checkThisTypeInObjectLiterals() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            result.sourceFile.statements.forEach { walkThisTypeStmt(it, source, fileName) }
        }
    }

    private fun walkThisTypeStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> stmt.declarationList.declarations.forEach { d ->
                d.initializer?.let { walkThisTypeExpr(it, source, fileName) }
            }
            is ExpressionStatement -> walkThisTypeExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { walkThisTypeExpr(it, source, fileName) }
            is Block -> stmt.statements.forEach { walkThisTypeStmt(it, source, fileName) }
            is IfStatement -> {
                walkThisTypeStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkThisTypeStmt(it, source, fileName) }
            }
            is ForStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is ForOfStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is ForInStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is WhileStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is DoStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is FunctionDeclaration -> stmt.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
            else -> {}
        }
    }

    private fun walkThisTypeExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is MethodDeclaration -> {
                        checkThisTypePredicate(prop.type, source, fileName)
                        prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    }
                    is GetAccessor -> {
                        checkThisTypePredicate(prop.type, source, fileName)
                        prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    }
                    is SetAccessor -> prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    is PropertyAssignment -> walkThisTypeExpr(prop.initializer, source, fileName)
                    is SpreadAssignment -> walkThisTypeExpr(prop.expression, source, fileName)
                    else -> {}
                }
            }
            is ParenthesizedExpression -> walkThisTypeExpr(expr.expression, source, fileName)
            is CallExpression -> { walkThisTypeExpr(expr.expression, source, fileName); expr.arguments.forEach { walkThisTypeExpr(it, source, fileName) } }
            is NewExpression -> { walkThisTypeExpr(expr.expression, source, fileName); expr.arguments?.forEach { walkThisTypeExpr(it, source, fileName) } }
            is ArrayLiteralExpression -> expr.elements.forEach { walkThisTypeExpr(it, source, fileName) }
            is BinaryExpression -> {
                // Iterative (worklist) to avoid StackOverflow on deeply-nested chains
                // (e.g. binderBinaryExpressionStress); a crash here would abort JS emit.
                val work = ArrayDeque<Expression>()
                work.addLast(expr)
                while (work.isNotEmpty()) {
                    when (val cur = work.removeLast()) {
                        is BinaryExpression -> { work.addLast(cur.left); work.addLast(cur.right) }
                        else -> walkThisTypeExpr(cur, source, fileName)
                    }
                }
            }
            is ConditionalExpression -> { walkThisTypeExpr(expr.whenTrue, source, fileName); walkThisTypeExpr(expr.whenFalse, source, fileName) }
            is ArrowFunction -> when (val b = expr.body) {
                is Block -> b.statements.forEach { walkThisTypeStmt(it, source, fileName) }
                is Expression -> walkThisTypeExpr(b, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
            is AsExpression -> walkThisTypeExpr(expr.expression, source, fileName)
            is SpreadElement -> walkThisTypeExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    /** Emit TS2526 if [type] is a type predicate whose asserted type is (or contains) a `this`. */
    private fun checkThisTypePredicate(type: TypeNode?, source: String, fileName: String) {
        val pred = type as? TypePredicate ?: return
        val thisPos = findThisTypePos(pred.type) ?: return
        val (line, character) = getLineAndCharacterOfPosition(source, thisPos)
        diagnostics.add(Diagnostic(
            message = "A 'this' type is available only in a non-static member of a class or interface.",
            category = DiagnosticCategory.Error,
            code = 2526,
            fileName = fileName,
            line = line,
            character = character,
            start = thisPos,
            length = 4,
        ))
    }

    /** Position of a `this` ThisType node directly or shallowly nested in [node] (union/array/paren). */
    private fun findThisTypePos(node: TypeNode?): Int? = when (node) {
        is ThisType -> node.pos
        is ParenthesizedType -> findThisTypePos(node.type)
        is ArrayType -> findThisTypePos(node.elementType)
        is UnionType -> node.types.firstNotNullOfOrNull { findThisTypePos(it) }
        is IntersectionType -> node.types.firstNotNullOfOrNull { findThisTypePos(it) }
        else -> null
    }

    private fun checkImplicitThis() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Round 79h: skip JS-like files. Under allowJs/checkJs TypeScript
            // infers `this` from JSDoc `@this`, prototype-assignment and IIFE
            // context, so a bare `this` in a JS file is NOT implicit-any the way
            // it is in a `.ts` file. No JS-file error baseline expects TS2683, so
            // skipping them is FP-safe and prevents regressions on
            // `signaturesUseJSDocForOptionalParameters` / `noParameterReassignmentJSIIFE`.
            if (isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            checkThisInStatements(
                result.sourceFile.statements, source, fileName,
                thisIsTyped = false, // file level — this is 'any' but we don't error at file level
                insideFunction = false, // not inside any function yet
                shadowFunctionPos = -1
            )
        }
    }

    private fun isJsLikeFileName(fileName: String): Boolean =
        fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
            fileName.endsWith(".cjs") || fileName.endsWith(".mjs")

    private fun checkThisInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
        insideArrowFunction: Boolean = false,
    ) {
        for (stmt in statements) {
            checkThisInStatement(stmt, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
        }
    }

    private fun checkThisInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
        insideArrowFunction: Boolean = false,
    ) {
        when (stmt) {
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val hasThisParam = hasThisParameter(stmt.parameters)
                // 17.64: extend 17.63's @this JSDoc detection from FunctionExpression
                // to FunctionDeclaration. JS-like files only.
                val hasJSDocThis = hasJSDocThisTag(stmt.leadingComments, fileName)
                val newThisIsTyped = hasThisParam || hasJSDocThis
                val newShadowPos = if (!newThisIsTyped && thisIsTyped) {
                    // This function shadows a typed this context
                    stmt.name?.pos ?: stmt.pos
                } else if (!newThisIsTyped && !thisIsTyped) {
                    shadowFunctionPos // keep existing shadow info
                } else -1
                stmt.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = newThisIsTyped,
                        insideFunction = true,
                        shadowFunctionPos = newShadowPos,
                        insideArrowFunction = false, // function resets arrow context
                    )
                }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (member in stmt.members) {
                    checkThisInClassElement(member, source, fileName)
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                    }
                }
            }
            is ExpressionStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ReturnStatement -> {
                stmt.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is IfStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInStatement(stmt.thenStatement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                stmt.elseStatement?.let {
                    checkThisInStatement(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is Block -> {
                checkThisInStatements(stmt.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ForStatement -> {
                stmt.initializer?.let {
                    when (it) {
                        is Expression -> checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                        is VariableDeclarationList -> {
                            for (decl in it.declarations) {
                                decl.initializer?.let { init ->
                                    checkThisInExpr(init, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                                }
                            }
                        }
                        else -> {}
                    }
                }
                stmt.condition?.let { checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction) }
                stmt.incrementor?.let { checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction) }
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ForInStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ForOfStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is WhileStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is DoStatement -> {
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is SwitchStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkThisInExpr(clause.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                            checkThisInStatements(clause.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                        }
                        is DefaultClause -> {
                            checkThisInStatements(clause.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> {
                stmt.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is TryStatement -> {
                checkThisInStatements(stmt.tryBlock.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                stmt.catchClause?.let {
                    checkThisInStatements(it.block.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
                stmt.finallyBlock?.let {
                    checkThisInStatements(it.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is LabeledStatement -> {
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> checkThisInStatements(
                        body.statements, source, fileName,
                        thisIsTyped = false, insideFunction = false, shadowFunctionPos = -1
                    )
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun checkThisInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
    ) {
        // Inside class members, `this` is typed — no error
        when (element) {
            is MethodDeclaration -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is Constructor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is GetAccessor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is SetAccessor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is PropertyDeclaration -> {
                // Property initializers: `this` is typed (class context)
                // but function expressions in property initializers create new `this` scope
                element.initializer?.let {
                    checkThisInExpr(
                        it, source, fileName,
                        thisIsTyped = true, insideFunction = false, shadowFunctionPos = -1
                    )
                }
            }
            else -> {}
        }
    }

    private fun checkThisInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
        insideArrowFunction: Boolean = false,
        // Round 79h: set by the CallExpression branch when this expression is a
        // function-expression argument whose contextual callback type declares a
        // `this:` parameter (e.g. `each(xs, function(d){...this...})` against
        // `(this: T, d: T) => T`). Such a `this` is contextually typed, not
        // implicit-any, so TS2683 is suppressed inside the body.
        contextualThisTyped: Boolean = false,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text == "this" && !thisIsTyped) {
                    if (insideFunction) {
                        emitTS2683(expr, source, fileName, shadowFunctionPos)
                    } else if (insideArrowFunction) {
                        // TS7041: arrow function at top level captures global 'this'
                        val start = expr.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "The containing arrow function captures the global value of 'this'.",
                            category = DiagnosticCategory.Error,
                            code = 7041,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = 4,
                        ))
                    }
                }
            }
            is FunctionExpression -> {
                val hasThisParam = hasThisParameter(expr.parameters)
                // 17.63: in JS-like files, a leading JSDoc `@this {Type}` annotation
                // on a function expression types `this` and suppresses TS2683 inside
                // the body — same effect as a `this:` parameter. The exact type
                // doesn't matter for the diagnostic; we only check tag presence.
                val hasJSDocThis = hasJSDocThisTag(expr.leadingComments, fileName)
                val newThisIsTyped = hasThisParam || hasJSDocThis || contextualThisTyped
                val newShadowPos = if (!newThisIsTyped && thisIsTyped) {
                    // This function expression shadows a typed this context
                    expr.name?.pos ?: expr.pos
                } else if (!newThisIsTyped && !thisIsTyped) {
                    shadowFunctionPos
                } else -1
                expr.body.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = newThisIsTyped,
                        insideFunction = true,
                        shadowFunctionPos = newShadowPos,
                        insideArrowFunction = false, // function resets arrow context
                    )
                }
            }
            is ArrowFunction -> {
                // Arrow functions are transparent — inherit outer this context.
                // insideFunction stays as-is: arrows don't create their own this.
                // insideArrowFunction becomes true so TS7041 can fire on `this` inside
                // an arrow at top-level (not enclosed by any regular function).
                when (val body = expr.body) {
                    is Block -> checkThisInStatements(
                        body.statements, source, fileName,
                        thisIsTyped, insideFunction,
                        shadowFunctionPos,
                        insideArrowFunction = true,
                    )
                    is Expression -> checkThisInExpr(
                        body, source, fileName,
                        thisIsTyped, insideFunction,
                        shadowFunctionPos,
                        insideArrowFunction = true,
                    )
                    else -> {}
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    checkThisInClassElement(member, source, fileName)
                }
            }
            is CallExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                expr.arguments.forEachIndexed { i, arg ->
                    // Round 79h: a function-expression argument whose contextual
                    // callback type declares a `this:` parameter has a contextually
                    // typed `this` — suppress TS2683 inside it.
                    val ctxThis = arg is FunctionExpression && callArgHasContextualThis(expr.expression, i)
                    checkThisInExpr(arg, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction, contextualThisTyped = ctxThis)
                }
            }
            is NewExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                expr.arguments?.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkThisInExpr(current.right, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                    current = current.left
                }
                checkThisInExpr(current, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ParenthesizedExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is PropertyAccessExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ElementAccessExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInExpr(expr.argumentExpression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ConditionalExpression -> {
                checkThisInExpr(expr.condition, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInExpr(expr.whenTrue, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                checkThisInExpr(expr.whenFalse, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            val init = prop.initializer
                            if (init is FunctionExpression) {
                                // Function expressions as object literal property values have
                                // typed this (TypeScript infers the object type)
                                init.body.let {
                                    checkThisInStatements(
                                        it.statements, source, fileName,
                                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                                    )
                                }
                            } else {
                                checkThisInExpr(init, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                            }
                        }
                        is MethodDeclaration -> {
                            // Object literal methods have typed this (the object type)
                            prop.body?.let {
                                checkThisInStatements(
                                    it.statements, source, fileName,
                                    thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                                )
                            }
                        }
                        is SpreadAssignment -> {
                            checkThisInExpr(prop.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                        }
                        is ShorthandPropertyAssignment -> {
                            prop.objectAssignmentInitializer?.let {
                                checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                            }
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkThisInExpr(span.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is TaggedTemplateExpression -> {
                checkThisInExpr(expr.tag, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        for (span in template.templateSpans) {
                            checkThisInExpr(span.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                        }
                    }
                    else -> {}
                }
            }
            is PrefixUnaryExpression -> {
                checkThisInExpr(expr.operand, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is PostfixUnaryExpression -> {
                checkThisInExpr(expr.operand, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is TypeOfExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is VoidExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is DeleteExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is AwaitExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is SpreadElement -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is YieldExpression -> {
                expr.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            is AsExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is TypeAssertionExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is SatisfiesExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is NonNullExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
            }
            is CommaListExpression -> {
                expr.elements.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos, insideArrowFunction)
                }
            }
            else -> {}
        }
    }

    private fun hasThisParameter(parameters: List<Parameter>): Boolean {
        val first = parameters.firstOrNull() ?: return false
        val name = first.name
        return name is Identifier && name.text == "this"
    }

    /**
     * Round 79h: a function-expression argument's `this` is contextually typed
     * (and thus NOT implicit-any) when the callee's parameter at [argIndex] is a
     * function type that declares a `this:` parameter — e.g. `$.each(xs,
     * function(d) { ...this... })` where `each`'s callback param is
     * `(this: T, d: T) => T`. Resolves the callee's call signature(s), takes the
     * parameter type at [argIndex], and checks whether it's a function type whose
     * declaration carries a `this` parameter. Conservative: any resolution
     * failure returns false, so TS2683 still fires (never a false suppression).
     */
    private fun callArgHasContextualThis(callee: Expression, argIndex: Int): Boolean {
        return try {
            val calleeType = when (callee) {
                is Identifier -> getTypeOfIdentifier(callee)
                is PropertyAccessExpression -> getTypeOfPropertyAccess(callee)
                else -> return false
            }
            if (calleeType !is Type.Object) return false
            resolveStructuredTypeMembers(calleeType)
            val sigs = calleeType.callSignatures ?: return false
            sigs.any { sig ->
                argIndex < sig.parameters.size &&
                    typeIsFunctionWithThisParam(getTypeOfSymbol(sig.parameters[argIndex]))
            }
        } catch (_: StackOverflowError) {
            false
        }
    }

    /** True when [type] is a function type whose call signature declares a `this:` parameter. */
    private fun typeIsFunctionWithThisParam(type: Type): Boolean {
        if (type !is Type.Object) return false
        val cbSigs = type.callSignatures ?: return false
        return cbSigs.any { cb ->
            signatureDeclarationParameters(cb.declaration)?.let { hasThisParameter(it) } == true
        }
    }

    /** Extract the parameter list from any signature-bearing AST declaration node. */
    private fun signatureDeclarationParameters(node: Node?): List<Parameter>? = when (node) {
        is FunctionType -> node.parameters
        is ConstructorType -> node.parameters
        is FunctionDeclaration -> node.parameters
        is FunctionExpression -> node.parameters
        is ArrowFunction -> node.parameters
        is MethodDeclaration -> node.parameters
        is Constructor -> node.parameters
        else -> null
    }

    // 17.63: detect a leading JSDoc `@this {Type}` annotation on a function
    // expression in a JS-like file. Returns true if any leading MultiLineComment
    // contains the `@this` tag (followed by whitespace/newline/`{` so we don't
    // match `@thisIsNotATag`). The actual type isn't parsed — only tag presence
    // matters for TS2683 suppression.
    private fun hasJSDocThisTag(comments: List<Comment>?, fileName: String): Boolean {
        if (comments.isNullOrEmpty()) return false
        val isJsLike = fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
            fileName.endsWith(".cjs") || fileName.endsWith(".mjs")
        if (!isJsLike) return false
        for (comment in comments) {
            if (comment.kind != SyntaxKind.MultiLineComment) continue
            val ct = comment.text
            if (!ct.startsWith("/**")) continue
            var idx = 0
            while (true) {
                val found = ct.indexOf("@this", idx)
                if (found < 0) break
                val after = if (found + 5 < ct.length) ct[found + 5] else ' '
                if (!(after.isLetterOrDigit() || after == '_')) return true
                idx = found + 5
            }
        }
        return false
    }

    /**
     * Find every namespace/module body across all checked source files and emit
     * TS2331 + TS2683 for each `this` reference that's directly in the body (not
     * nested inside a function/class). Always runs — independent of `noImplicitThis`.
     */
    private fun checkThisInNamespaceBodies() {
        // TS2331 always fires for `this` directly in a namespace/module body
        // (structural error). TS2683 ALSO fires unless `strict: false` was set
        // explicitly — in test default mode (no explicit @strict), TS2683 still
        // fires because TypeScript treats namespace-body `this` as implicit-any.
        val emitTs2683 = !options.strictExplicitlyFalse
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) walkStmtForNamespaceBodies(stmt, source, fileName, emitTs2683)
        }
    }

    private fun walkStmtForNamespaceBodies(stmt: Statement, source: String, fileName: String, emitTs2683: Boolean) {
        when (stmt) {
            is ModuleDeclaration -> when (val b = stmt.body) {
                is ModuleBlock -> {
                    checkThisDirectInNamespaceBody(b.statements, source, fileName, emitTs2683)
                    // Recurse for nested namespaces (those bodies are also namespace bodies).
                    for (s in b.statements) walkStmtForNamespaceBodies(s, source, fileName, emitTs2683)
                }
                else -> {}
            }
            else -> {}
        }
    }

    /**
     * Walk a namespace/module body looking for `this` references that are NOT nested
     * inside a function/class. For each, emit TS2331 ("'this' cannot be referenced
     * in a module or namespace body.") + TS2683 ("'this' implicitly has type 'any'…").
     * Both fire at the same position with the standard `this`-keyword length of 4.
     * Arrow functions are transparent (their `this` inherits from the enclosing
     * scope, which is the namespace body).
     */
    private fun checkThisDirectInNamespaceBody(
        statements: List<Statement>,
        source: String,
        fileName: String,
        emitTs2683: Boolean,
    ) {
        for (stmt in statements) walkStmtForNamespaceThis(stmt, source, fileName, emitTs2683)
    }

    private fun walkStmtForNamespaceThis(stmt: Statement, source: String, fileName: String, emitTs2683: Boolean) {
        when (stmt) {
            is FunctionDeclaration, is ClassDeclaration -> { /* nested function/class — `this` rebinds */ }
            is ExpressionStatement -> walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            is IfStatement -> {
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
                walkStmtForNamespaceThis(stmt.thenStatement, source, fileName, emitTs2683)
                stmt.elseStatement?.let { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
            }
            is Block -> checkThisDirectInNamespaceBody(stmt.statements, source, fileName, emitTs2683)
            is ModuleDeclaration -> when (val b = stmt.body) {
                is ModuleBlock -> checkThisDirectInNamespaceBody(b.statements, source, fileName, emitTs2683)
                else -> {}
            }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
                stmt.condition?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
                stmt.incrementor?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
                walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
            }
            is ForInStatement -> {
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
                walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
            }
            is ForOfStatement -> {
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
                walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
            }
            is WhileStatement -> {
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
                walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
            }
            is DoStatement -> {
                walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
            }
            is SwitchStatement -> {
                walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        walkExprForNamespaceThis(clause.expression, source, fileName, emitTs2683)
                        clause.statements.forEach { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
                    }
                    is DefaultClause -> clause.statements.forEach { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
                stmt.catchClause?.block?.statements?.forEach { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
                stmt.finallyBlock?.statements?.forEach { walkStmtForNamespaceThis(it, source, fileName, emitTs2683) }
            }
            is LabeledStatement -> walkStmtForNamespaceThis(stmt.statement, source, fileName, emitTs2683)
            is ThrowStatement -> stmt.expression?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            is ExportAssignment -> walkExprForNamespaceThis(stmt.expression, source, fileName, emitTs2683)
            else -> {}
        }
    }

    private fun walkExprForNamespaceThis(expr: Expression, source: String, fileName: String, emitTs2683: Boolean) {
        when (expr) {
            is Identifier -> if (expr.text == "this") emitNamespaceThisErrors(expr, source, fileName, emitTs2683)
            is PropertyAccessExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is ElementAccessExpression -> {
                walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
                walkExprForNamespaceThis(expr.argumentExpression, source, fileName, emitTs2683)
            }
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkExprForNamespaceThis(cur, source, fileName, emitTs2683)
                while (rightStack.isNotEmpty()) walkExprForNamespaceThis(rightStack.removeLast(), source, fileName, emitTs2683)
            }
            is CallExpression -> {
                walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
                for (a in expr.arguments) walkExprForNamespaceThis(a, source, fileName, emitTs2683)
            }
            is NewExpression -> {
                walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
                expr.arguments?.let { for (a in it) walkExprForNamespaceThis(a, source, fileName, emitTs2683) }
            }
            is ParenthesizedExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is PrefixUnaryExpression -> walkExprForNamespaceThis(expr.operand, source, fileName, emitTs2683)
            is PostfixUnaryExpression -> walkExprForNamespaceThis(expr.operand, source, fileName, emitTs2683)
            is ConditionalExpression -> {
                walkExprForNamespaceThis(expr.condition, source, fileName, emitTs2683)
                walkExprForNamespaceThis(expr.whenTrue, source, fileName, emitTs2683)
                walkExprForNamespaceThis(expr.whenFalse, source, fileName, emitTs2683)
            }
            is ArrowFunction -> when (val b = expr.body) {
                is Block -> checkThisDirectInNamespaceBody(b.statements, source, fileName, emitTs2683)
                is Expression -> walkExprForNamespaceThis(b, source, fileName, emitTs2683)
                else -> {}
            }
            is AsExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is TypeAssertionExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is SatisfiesExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is NonNullExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkExprForNamespaceThis(prop.initializer, source, fileName, emitTs2683)
                is SpreadAssignment -> walkExprForNamespaceThis(prop.expression, source, fileName, emitTs2683)
                else -> {}
            }
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForNamespaceThis(it.expression, source, fileName, emitTs2683) }
            is TaggedTemplateExpression -> {
                walkExprForNamespaceThis(expr.tag, source, fileName, emitTs2683)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { walkExprForNamespaceThis(it.expression, source, fileName, emitTs2683) }
                    else -> {}
                }
            }
            is SpreadElement -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is AwaitExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is YieldExpression -> expr.expression?.let { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            is DeleteExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is VoidExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is TypeOfExpression -> walkExprForNamespaceThis(expr.expression, source, fileName, emitTs2683)
            is CommaListExpression -> expr.elements.forEach { walkExprForNamespaceThis(it, source, fileName, emitTs2683) }
            // FunctionExpression, ClassExpression: nested function/class rebinds `this` — skip.
            else -> {}
        }
    }

    private fun emitNamespaceThisErrors(thisExpr: Identifier, source: String, fileName: String, emitTs2683: Boolean) {
        val start = thisExpr.pos
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'this' cannot be referenced in a module or namespace body.",
            category = DiagnosticCategory.Error,
            code = 2331,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = 4,
        ))
        if (emitTs2683) {
            diagnostics.add(Diagnostic(
                message = "'this' implicitly has type 'any' because it does not have a type annotation.",
                category = DiagnosticCategory.Error,
                code = 2683,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = 4,
            ))
        }
    }

    private fun emitTS2683(
        thisExpr: Identifier,
        source: String,
        fileName: String,
        shadowFunctionPos: Int,
    ) {
        val start = thisExpr.pos
        val length = 4 // "this".length
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        val related = if (shadowFunctionPos >= 0) {
            val (shadowLine, shadowCol) = getLineAndCharacterOfPosition(source, shadowFunctionPos)
            listOf(Diagnostic(
                message = "An outer value of 'this' is shadowed by this container.",
                category = DiagnosticCategory.Error,
                code = 2738,
                fileName = fileName,
                line = shadowLine,
                character = shadowCol,
            ))
        } else emptyList()

        diagnostics.add(Diagnostic(
            message = "'this' implicitly has type 'any' because it does not have a type annotation.",
            category = DiagnosticCategory.Error,
            code = 2683,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = related,
        ))
    }

    // -----------------------------------------------------------------------
    // Duplicate object literal property checking (TS1117)
    // -----------------------------------------------------------------------

    private fun checkDuplicateObjectLiteralProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForObjectLiterals(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForObjectLiterals(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            walkNodeForObjectLiterals(stmt, source, fileName)
        }
    }

    private fun walkNodeForObjectLiterals(node: Node, source: String, fileName: String, depth: Int = 0) {
        if (depth > 100) return
        when (node) {
            is ObjectLiteralExpression -> {
                checkObjectLiteralDuplicates(node, source, fileName)
                // Also recurse into property values
                for (prop in node.properties) {
                    when (prop) {
                        is PropertyAssignment -> walkNodeForObjectLiterals(prop.initializer, source, fileName, depth + 1)
                        is SpreadAssignment -> walkNodeForObjectLiterals(prop.expression, source, fileName, depth + 1)
                        else -> {}
                    }
                }
            }
            // Skip the left side of assignment expressions (destructuring patterns)
            // but do check the right side
            is VariableStatement -> {
                for (decl in node.declarationList.declarations) {
                    decl.initializer?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
                }
            }
            is ExpressionStatement -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is ReturnStatement -> node.expression?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            is FunctionDeclaration -> node.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (member in node.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is Constructor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is GetAccessor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
                        else -> {}
                    }
                }
            }
            is Block -> walkForObjectLiterals(node.statements, source, fileName)
            is IfStatement -> {
                walkNodeForObjectLiterals(node.thenStatement, source, fileName, depth + 1)
                node.elseStatement?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is ForStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ForInStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ForOfStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is WhileStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is DoStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is SwitchStatement -> {
                for (clause in node.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForObjectLiterals(clause.statements, source, fileName)
                        is DefaultClause -> walkForObjectLiterals(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForObjectLiterals(node.tryBlock.statements, source, fileName)
                node.catchClause?.block?.let { walkForObjectLiterals(it.statements, source, fileName) }
                node.finallyBlock?.let { walkForObjectLiterals(it.statements, source, fileName) }
            }
            is ArrowFunction -> {
                when (val body = node.body) {
                    is Block -> walkForObjectLiterals(body.statements, source, fileName)
                    else -> walkNodeForObjectLiterals(body, source, fileName, depth + 1)
                }
            }
            is FunctionExpression -> node.body.let { walkForObjectLiterals(it.statements, source, fileName) }
            is ParenthesizedExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is BinaryExpression -> {
                // Skip left side of assignment if it's a destructuring pattern
                if (node.operator == SyntaxKind.Equals && (node.left is ObjectLiteralExpression || node.left is ArrayLiteralExpression)) {
                    // Only recurse into the right side
                    walkNodeForObjectLiterals(node.right, source, fileName, depth + 1)
                } else {
                    walkNodeForObjectLiterals(node.left, source, fileName, depth + 1)
                    walkNodeForObjectLiterals(node.right, source, fileName, depth + 1)
                }
            }
            is ConditionalExpression -> {
                walkNodeForObjectLiterals(node.whenTrue, source, fileName, depth + 1)
                walkNodeForObjectLiterals(node.whenFalse, source, fileName, depth + 1)
            }
            is CallExpression -> {
                walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
                node.arguments.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is NewExpression -> {
                node.arguments?.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is ArrayLiteralExpression -> {
                node.elements.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is PropertyAccessExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is ElementAccessExpression -> {
                walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
                walkNodeForObjectLiterals(node.argumentExpression, source, fileName, depth + 1)
            }
            is TemplateExpression -> {
                node.templateSpans.forEach { walkNodeForObjectLiterals(it.expression, source, fileName, depth + 1) }
            }
            is TaggedTemplateExpression -> {
                walkNodeForObjectLiterals(node.tag, source, fileName, depth + 1)
                (node.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkNodeForObjectLiterals(it.expression, source, fileName, depth + 1)
                }
            }
            is LabeledStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ModuleDeclaration -> {
                val body = node.body
                if (body is ModuleBlock) walkForObjectLiterals(body.statements, source, fileName)
            }
            is ExportAssignment -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is SpreadElement -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is AsExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is TypeAssertionExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is SatisfiesExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is NonNullExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is PrefixUnaryExpression -> walkNodeForObjectLiterals(node.operand, source, fileName, depth + 1)
            is PostfixUnaryExpression -> walkNodeForObjectLiterals(node.operand, source, fileName, depth + 1)
            is AwaitExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is YieldExpression -> node.expression?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            is VoidExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is DeleteExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is TypeOfExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is CommaListExpression -> node.elements.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            is ClassExpression -> for (m in node.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
                    else -> {}
                }
            }
            is ThrowStatement -> node.expression?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            else -> {}
        }
    }

    private fun checkObjectLiteralDuplicates(obj: ObjectLiteralExpression, source: String, fileName: String) {
        // Track what kind of property has been seen: 'p' = property/method, 'g' = getter, 's' = setter
        val seen = mutableMapOf<String, Char>()
        // Per-name accessor list (in source order) for the post-pass that emits TS2300/TS1118
        // on duplicate get/set accessors. Each entry is (prop, kind='g'|'s', nameNode).
        val accessorsByName = mutableMapOf<String, MutableList<Triple<Node, Char, Node>>>()
        for (prop in obj.properties) {
            val name = getPropertyName(prop) ?: continue
            val kind = when (prop) {
                is GetAccessor -> 'g'
                is SetAccessor -> 's'
                else -> 'p' // PropertyAssignment, ShorthandPropertyAssignment, MethodDeclaration
            }
            if (kind == 'g' || kind == 's') {
                val nameNode = getPropertyNameNode(prop)
                if (nameNode != null) {
                    accessorsByName.getOrPut(name) { mutableListOf() }.add(Triple(prop, kind, nameNode))
                }
            }
            val prevKind = seen[name]
            val isDuplicate = when {
                prevKind == null -> false
                // getter + setter or setter + getter is OK
                prevKind == 'g' && kind == 's' -> false
                prevKind == 's' && kind == 'g' -> false
                else -> true
            }
            if (isDuplicate) {
                val nameNode = getPropertyNameNode(prop) ?: continue
                val start = nameNode.pos
                val length = getPropertyNameLength(nameNode, name)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "An object literal cannot have multiple properties with the same name.",
                    category = DiagnosticCategory.Error,
                    code = 1117,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            } else {
                seen[name] = kind
            }
        }
        // Post-pass: for each accessor group, if it has more than one getter OR more
        // than one setter, emit TS2300 on every accessor in the group and TS1118 on
        // the SECOND/THIRD/... duplicate (the get-after-get or set-after-set).
        // A clean get+set pair (one of each) emits nothing here.
        for ((name, group) in accessorsByName) {
            val getCount = group.count { it.second == 'g' }
            val setCount = group.count { it.second == 's' }
            val hasDuplicate = getCount > 1 || setCount > 1
            if (!hasDuplicate) continue
            var seenGet = false
            var seenSet = false
            for ((_, kind, nameNode) in group) {
                val start = nameNode.pos
                val length = getPropertyNameLength(nameNode, name)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                if ((kind == 'g' && seenGet) || (kind == 's' && seenSet)) {
                    diagnostics.add(Diagnostic(
                        message = "An object literal cannot have multiple get/set accessors with the same name.",
                        category = DiagnosticCategory.Error,
                        code = 1118,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                diagnostics.add(Diagnostic(
                    message = "Duplicate identifier '$name'.",
                    category = DiagnosticCategory.Error,
                    code = 2300,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                if (kind == 'g') seenGet = true
                if (kind == 's') seenSet = true
            }
        }
    }

    // -----------------------------------------------------------------------
    // Tuple destructuring bounds check (TS2493) — narrow to empty array literal
    // -----------------------------------------------------------------------
    //
    // `let [a, b] = []` cannot bind `a` or `b` — the source tuple has length 0.
    // We only check the case where the initializer is an empty array literal
    // (no elements, no spread). Non-empty literals and non-literal initializers
    // need tuple-type inference which is out of scope here.

    private fun checkTupleDestructuringBounds() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForTupleBounds(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForTupleBounds(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) walkNodeForTupleBounds(stmt, source, fileName, 0)
    }

    private fun walkNodeForTupleBounds(node: Node, source: String, fileName: String, depth: Int) {
        if (depth > 100) return
        when (node) {
            is VariableStatement -> {
                for (decl in node.declarationList.declarations) {
                    checkVarDeclTupleBounds(decl, source, fileName)
                    decl.initializer?.let { walkNodeForTupleBounds(it, source, fileName, depth + 1) }
                }
            }
            is Block -> walkForTupleBounds(node.statements, source, fileName)
            is IfStatement -> {
                walkNodeForTupleBounds(node.thenStatement, source, fileName, depth + 1)
                node.elseStatement?.let { walkNodeForTupleBounds(it, source, fileName, depth + 1) }
            }
            is ForStatement -> node.statement.let { walkNodeForTupleBounds(it, source, fileName, depth + 1) }
            is ForInStatement -> walkNodeForTupleBounds(node.statement, source, fileName, depth + 1)
            is ForOfStatement -> walkNodeForTupleBounds(node.statement, source, fileName, depth + 1)
            is WhileStatement -> walkNodeForTupleBounds(node.statement, source, fileName, depth + 1)
            is DoStatement -> walkNodeForTupleBounds(node.statement, source, fileName, depth + 1)
            is SwitchStatement -> {
                for (clause in node.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForTupleBounds(clause.statements, source, fileName)
                        is DefaultClause -> walkForTupleBounds(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForTupleBounds(node.tryBlock.statements, source, fileName)
                node.catchClause?.block?.let { walkForTupleBounds(it.statements, source, fileName) }
                node.finallyBlock?.let { walkForTupleBounds(it.statements, source, fileName) }
            }
            is LabeledStatement -> walkNodeForTupleBounds(node.statement, source, fileName, depth + 1)
            is ModuleDeclaration -> {
                val body = node.body
                if (body is ModuleBlock) walkForTupleBounds(body.statements, source, fileName)
            }
            is FunctionDeclaration -> node.body?.let { walkForTupleBounds(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (member in node.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForTupleBounds(it.statements, source, fileName) }
                        is Constructor -> member.body?.let { walkForTupleBounds(it.statements, source, fileName) }
                        is GetAccessor -> member.body?.let { walkForTupleBounds(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { walkForTupleBounds(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = node.body) {
                    is Block -> walkForTupleBounds(body.statements, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> walkForTupleBounds(node.body.statements, source, fileName)
            else -> {}
        }
    }

    /**
     * 17.23: TS2493 for destructuring assignment `[a, b, c] = tuple` where the RHS has a
     * static tuple type (`Type.Object` with non-null `tupleElementTypes`) and its length is
     * shorter than the LHS arity. Squiggle covers the offending element via `expressionTrueEnd`.
     * Conservative gates: skip when LHS contains a spread (rest covers the remainder), skip
     * `OmittedExpression` slots (sparse destructuring is intentional), and skip non-tuple RHS.
     */
    private fun checkAssignmentTupleBounds(
        arrayLit: ArrayLiteralExpression, rhs: Expression,
        source: String, fileName: String,
    ) {
        if (arrayLit.elements.any { it is SpreadElement }) return
        val rhsType = try { getTypeOfExpression(rhs) } catch (_: StackOverflowError) { return }
        if (rhsType !is Type.Object) return
        val tupleElems = rhsType.tupleElementTypes ?: return
        val tupleLen = tupleElems.size
        val tupleDisplay = typeToString(rhsType)
        for ((i, el) in arrayLit.elements.withIndex()) {
            if (i < tupleLen) continue
            if (el is OmittedExpression) continue
            val elStart = el.pos
            val elEnd = expressionTrueEnd(el)
            val elLen = (elEnd - elStart).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, elStart)
            diagnostics.add(Diagnostic(
                message = "Tuple type '$tupleDisplay' of length '$tupleLen' has no element at index '$i'.",
                category = DiagnosticCategory.Error,
                code = 2493,
                fileName = fileName,
                line = line,
                character = character,
                start = elStart,
                length = elLen,
            ))
        }
    }

    private fun checkVarDeclTupleBounds(decl: VariableDeclaration, source: String, fileName: String) {
        val pattern = decl.name as? ArrayBindingPattern ?: return
        val init = decl.initializer as? ArrayLiteralExpression ?: return
        // Bail on spread elements — we can't compute the source length statically.
        var knownLen = 0
        for (el in init.elements) {
            if (el is SpreadElement) return
            knownLen++
        }
        for ((i, binding) in pattern.elements.withIndex()) {
            if (binding !is BindingElement) continue  // OmittedExpression etc.
            if (binding.dotDotDotToken) continue  // rest gets the remainder (possibly empty)
            if (binding.initializer != null) continue  // default covers absence
            if (i < knownLen) continue
            val nameNode = binding.name as? Identifier ?: continue
            val namePos = nameNode.pos
            val nameLen = nameNode.text.length
            val (line, character) = getLineAndCharacterOfPosition(source, namePos)
            diagnostics.add(Diagnostic(
                message = "Tuple type '[]' of length '0' has no element at index '$i'.",
                category = DiagnosticCategory.Error,
                code = 2493,
                fileName = fileName,
                line = line,
                character = character,
                start = namePos,
                length = nameLen,
            ))
        }
    }

    private fun getPropertyNameLength(nameNode: Node, name: String): Int {
        return when (nameNode) {
            // `\uXXXX` escape sequences in identifiers (e.g. `a` for `a`) keep the
            // raw source text; use its length so the squiggle covers the whole escape.
            is Identifier -> nameNode.rawText?.length ?: name.length
            is StringLiteralNode -> nameNode.rawText?.let { it.length + 2 } ?: (name.length + 2) // quotes
            is NumericLiteralNode -> nameNode.text.length // use original text length, not normalized name
            is ComputedPropertyName -> {
                // Span covers [expr] — find the closing ] in source
                // Can't use nameNode.end (overshoots by one token).
                // The expression text + brackets: count from pos to closing ']'
                val expr = nameNode.expression
                val exprLen = when (expr) {
                    is NumericLiteralNode -> expr.text.length
                    is StringLiteralNode -> expr.text.length + 2 // quotes
                    is PrefixUnaryExpression -> {
                        val operand = expr.operand
                        if (operand is NumericLiteralNode) 1 + operand.text.length else nameNode.end - nameNode.pos
                    }
                    is Identifier -> expr.text.length
                    is PropertyAccessExpression -> computedExpressionTextLength(expr)
                    else -> return nameNode.end - nameNode.pos
                }
                exprLen + 2 // [expr]
            }
            else -> nameNode.end - nameNode.pos
        }
    }

    private fun getPropertyName(prop: Node): String? {
        return when (prop) {
            is PropertyAssignment -> getPropertyKeyName(prop.name)
            is ShorthandPropertyAssignment -> prop.name.text
            is MethodDeclaration -> getPropertyKeyName(prop.name)
            is GetAccessor -> getPropertyKeyName(prop.name)
            is SetAccessor -> getPropertyKeyName(prop.name)
            else -> null
        }
    }

    /** Evaluate a property key to its string name, including computed property expressions. */
    private fun getPropertyKeyName(name: Node): String? {
        return when (name) {
            is Identifier -> name.text
            is StringLiteralNode -> name.text
            is NumericLiteralNode -> normalizeNumericLiteral(name.text)
            is ComputedPropertyName -> evaluateComputedPropertyName(name.expression)
            else -> null
        }
    }

    /** Normalize a numeric literal text to its canonical string form (e.g., "0b11" → "3"). */
    private fun normalizeNumericLiteral(text: String): String {
        val d = when {
            text.startsWith("0b", ignoreCase = true) -> text.substring(2).toLongOrNull(2)?.toDouble()
            text.startsWith("0o", ignoreCase = true) -> text.substring(2).toLongOrNull(8)?.toDouble()
            text.startsWith("0x", ignoreCase = true) -> text.substring(2).toLongOrNull(16)?.toDouble()
            else -> text.replace("_", "").toDoubleOrNull()
        }
        if (d == null) return text
        return if (d == d.toLong().toDouble() && d >= 0 && d < Long.MAX_VALUE.toDouble()) {
            d.toLong().toString()
        } else {
            d.toString()
        }
    }

    /** Evaluate simple constant computed property expressions to their string key value. */
    private fun evaluateComputedPropertyName(expr: Expression): String? {
        return when (expr) {
            is NumericLiteralNode -> normalizeNumericLiteral(expr.text)
            is StringLiteralNode -> expr.text  // ["+1"] → "+1"
            is PrefixUnaryExpression -> {
                val operand = expr.operand
                if (operand is NumericLiteralNode) {
                    val d = operand.text.toDoubleOrNull() ?: return null
                    val value = when (expr.operator) {
                        SyntaxKind.Plus -> d
                        SyntaxKind.Minus -> -d
                        else -> return null
                    }
                    if (value == value.toLong().toDouble()) value.toLong().toString() else value.toString()
                } else null
            }
            // Identifier and PropertyAccess references — compare syntactically
            // Prefix with __@computed: to avoid conflicts with regular property names
            is Identifier -> "__@computed:${expr.text}"
            is PropertyAccessExpression -> {
                val path = computedPropertyAccessPath(expr) ?: return null
                "__@computed:$path"
            }
            else -> null
        }
    }

    /** Build dotted path string from a property access chain (e.g., E1.A → "E1.A"). */
    private fun computedPropertyAccessPath(expr: Expression): String? {
        return when (expr) {
            is Identifier -> expr.text
            is PropertyAccessExpression -> {
                val base = computedPropertyAccessPath(expr.expression) ?: return null
                "$base.${expr.name.text}"
            }
            else -> null
        }
    }

    /** Compute the text length of a property access expression (e.g., E1.A → 4, keys.E1.A → 9). */
    private fun computedExpressionTextLength(expr: Expression): Int {
        return when (expr) {
            is Identifier -> expr.text.length
            is PropertyAccessExpression -> computedExpressionTextLength(expr.expression) + 1 + expr.name.text.length
            else -> 0
        }
    }

    private fun getPropertyNameNode(prop: Node): Node? {
        return when (prop) {
            is PropertyAssignment -> prop.name
            is ShorthandPropertyAssignment -> prop.name
            is MethodDeclaration -> prop.name
            is GetAccessor -> prop.name
            is SetAccessor -> prop.name
            else -> null
        }
    }

    // -----------------------------------------------------------------------
    // Super before this checking (TS17009)
    // -----------------------------------------------------------------------

    private fun checkSuperBeforeThis() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDerivedConstructors(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForDerivedConstructors(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Check if class extends something (derived class)
                    if (stmt.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true) {
                        for (member in stmt.members) {
                            if (member is Constructor && member.body != null) {
                                checkConstructorThisBeforeSuper(member.body!!.statements, source, fileName)
                                // TS2376: when derived class has initialized properties/param properties,
                                // super() must be the first statement in the constructor
                                val hasInitializedProps = stmt.members.any { m ->
                                    m is PropertyDeclaration && m.initializer != null &&
                                        ModifierFlag.Static !in m.modifiers
                                }
                                val hasParamProps = member.parameters.any { p ->
                                    p.modifiers.any { it == ModifierFlag.Public || it == ModifierFlag.Private ||
                                        it == ModifierFlag.Protected || it == ModifierFlag.Readonly }
                                }
                                if (hasInitializedProps || hasParamProps) {
                                    // Check if super() exists somewhere in the constructor
                                    val hasSuperCall = member.body!!.statements.any { s ->
                                        s is ExpressionStatement && s.expression is CallExpression &&
                                            isSuperIdentifier((s.expression as CallExpression).expression)
                                    }
                                    // Skip prologue directives ("use strict", etc.)
                                    val firstNonPrologueStmt = member.body!!.statements.firstOrNull { s ->
                                        !(s is ExpressionStatement && s.expression is StringLiteralNode)
                                    }
                                    val isSuperFirst = firstNonPrologueStmt is ExpressionStatement &&
                                        firstNonPrologueStmt.expression is CallExpression &&
                                        isSuperIdentifier((firstNonPrologueStmt.expression as CallExpression).expression)
                                    // TS2376 only fires when super IS called, just not as first statement
                                    // (TS2377 handles missing super entirely)
                                    if (hasSuperCall && !isSuperFirst) {
                                        val start = member.pos
                                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                                        diagnostics.add(Diagnostic(
                                            message = "A 'super' call must be the first statement in the constructor to refer to 'super' or 'this' when a derived class contains initialized properties, parameter properties, or private identifiers.",
                                            category = DiagnosticCategory.Error,
                                            code = 2376,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = start,
                                            length = "constructor".length,
                                        ))
                                    }
                                }
                            }
                        }
                    }
                    // Recurse into class members for nested classes
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                            is PropertyDeclaration -> {
                                val init = member.initializer
                                if (init is ClassExpression && init.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true) {
                                    for (m in init.members) {
                                        if (m is Constructor && m.body != null) {
                                            checkConstructorThisBeforeSuper(m.body!!.statements, source, fileName)
                                        }
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForDerivedConstructors(body.statements, source, fileName)
                }
                is Block -> walkForDerivedConstructors(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForDerivedConstructors(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForDerivedConstructors(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> walkForDerivedConstructors(clause.statements, source, fileName)
                            is DefaultClause -> walkForDerivedConstructors(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    walkForDerivedConstructors(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForDerivedConstructors(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun isThisIdentifier(node: Node): Boolean =
        node is Identifier && node.text == "this"

    private fun isSuperIdentifier(node: Node): Boolean =
        node is Identifier && node.text == "super"

    private fun checkConstructorThisBeforeSuper(statements: List<Statement>, source: String, fileName: String) {
        // Walk statements until we find super() call; any this reference before that is TS17009
        for (stmt in statements) {
            // Check for super(this) — this in super call arguments is also an error
            val superCallThisRef = findThisInSuperCallArgs(stmt)
            if (superCallThisRef != null) {
                emitTS17009(superCallThisRef, source, fileName)
                return
            }
            // Check if this statement contains a super() call (and stop if so)
            if (containsSuperCall(stmt)) return
            // Check if this statement references 'this' before super
            val thisRef = findFirstThisReference(stmt)
            if (thisRef != null) {
                emitTS17009(thisRef, source, fileName)
                return // Only report first occurrence
            }
        }
    }

    private fun emitTS17009(thisRef: Identifier, source: String, fileName: String) {
        val start = thisRef.pos
        val length = 4 // "this" is 4 characters
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'super' must be called before accessing 'this' in the constructor of a derived class.",
            category = DiagnosticCategory.Error,
            code = 17009,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** Find 'this' used in super() call arguments. */
    private fun findThisInSuperCallArgs(node: Node): Identifier? {
        if (node !is ExpressionStatement) return null
        val expr = node.expression
        if (expr is CallExpression && isSuperIdentifier(expr.expression)) {
            for (arg in expr.arguments) {
                findFirstThisInExpr(arg)?.let { return it }
            }
        }
        return null
    }

    private fun containsSuperCall(node: Node): Boolean {
        return when (node) {
            is ExpressionStatement -> containsSuperCallInExpr(node.expression)
            else -> false
        }
    }

    private fun containsSuperCallInExpr(expr: Expression): Boolean {
        return when (expr) {
            is CallExpression -> isSuperIdentifier(expr.expression) || containsSuperCallInExpr(expr.expression)
            is BinaryExpression -> containsSuperCallInExpr(expr.left) || containsSuperCallInExpr(expr.right)
            is ParenthesizedExpression -> containsSuperCallInExpr(expr.expression)
            else -> false
        }
    }

    private fun findFirstThisReference(node: Node): Identifier? {
        return when (node) {
            is ExpressionStatement -> findFirstThisInExpr(node.expression)
            is VariableStatement -> {
                for (decl in node.declarationList.declarations) {
                    decl.initializer?.let { findFirstThisInExpr(it) }?.let { return it }
                }
                null
            }
            is ReturnStatement -> node.expression?.let { findFirstThisInExpr(it) }
            is IfStatement -> findFirstThisInExpr(node.expression)
            else -> null
        }
    }

    private fun findFirstThisInExpr(expr: Expression): Identifier? {
        return when {
            isThisIdentifier(expr) -> expr as Identifier
            expr is PropertyAccessExpression -> findFirstThisInExpr(expr.expression)
            expr is CallExpression -> {
                // Check for super(this) — this in arguments is also flagged
                if (isSuperIdentifier(expr.expression)) {
                    // Check arguments for 'this'
                    for (arg in expr.arguments) {
                        findFirstThisInExpr(arg)?.let { return it }
                    }
                    return null
                }
                findFirstThisInExpr(expr.expression)
                    ?: run { for (arg in expr.arguments) { findFirstThisInExpr(arg)?.let { return it } }; null }
            }
            expr is BinaryExpression -> findFirstThisInExpr(expr.left) ?: findFirstThisInExpr(expr.right)
            expr is ParenthesizedExpression -> findFirstThisInExpr(expr.expression)
            expr is ElementAccessExpression -> findFirstThisInExpr(expr.expression)
            expr is ConditionalExpression -> findFirstThisInExpr(expr.condition)
            expr is AsExpression -> findFirstThisInExpr(expr.expression)
            expr is TypeAssertionExpression -> findFirstThisInExpr(expr.expression)
            expr is SpreadElement -> findFirstThisInExpr(expr.expression)
            expr is ArrayLiteralExpression -> {
                for (elem in expr.elements) { findFirstThisInExpr(elem)?.let { return it } }
                null
            }
            expr is ObjectLiteralExpression -> null // Object literal creates new scope for 'this'
            expr is ArrowFunction -> null
            expr is FunctionExpression -> null
            else -> null
        }
    }

    // -----------------------------------------------------------------------
    // Const assignment checking (TS2540)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // Delete operator checking (TS1102/TS2703)
    // -----------------------------------------------------------------------

    /**
     * TS2703: "The operand of a 'delete' operator must be a property reference."
     * Fires unconditionally when delete operand is not a PropertyAccessExpression
     * or ElementAccessExpression.
     *
     * TS1102: "'delete' cannot be called on an identifier in strict mode."
     * Additionally fires when the operand is an Identifier and the code is in strict mode.
     */
    private fun checkDeleteOperator() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isModule = result.sourceFile.statements.any {
                it is ImportDeclaration || it is ExportDeclaration || it is ExportAssignment
            }
            val isStrict = options.target >= ScriptTarget.ES2015 ||
                options.strict == true ||
                options.alwaysStrict == true ||
                isModule ||
                result.sourceFile.statements.firstOrNull()?.let { stmt ->
                    stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                        (stmt.expression as StringLiteralNode).text == "use strict"
                } == true
            walkForDeleteOperator(result.sourceFile.statements, source, fileName, isStrict)
        }
    }

    private fun walkForDeleteOperator(stmts: List<Statement>, source: String, fileName: String, isStrict: Boolean) {
        for (stmt in stmts) walkStmtForDelete(stmt, source, fileName, isStrict)
    }

    private fun walkStmtForDelete(stmt: Statement, source: String, fileName: String, isStrict: Boolean) {
        when (stmt) {
            is ExpressionStatement -> walkExprForDelete(stmt.expression, source, fileName, isStrict)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForDelete(it, source, fileName, isStrict) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForDelete(it, source, fileName, isStrict) }
            is IfStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.thenStatement, source, fileName, isStrict)
                stmt.elseStatement?.let { walkStmtForDelete(it, source, fileName, isStrict) }
            }
            is Block -> walkForDeleteOperator(stmt.statements, source, fileName, isStrict)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkExprForDelete(it, source, fileName, isStrict) }
                stmt.condition?.let { walkExprForDelete(it, source, fileName, isStrict) }
                stmt.incrementor?.let { walkExprForDelete(it, source, fileName, isStrict) }
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is ForInStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is ForOfStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is WhileStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is DoStatement -> {
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
            }
            is SwitchStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) { is CaseClause -> clause.statements; is DefaultClause -> clause.statements; else -> emptyList() }
                    walkForDeleteOperator(stmts2, source, fileName, isStrict)
                }
            }
            is TryStatement -> {
                walkForDeleteOperator(stmt.tryBlock.statements, source, fileName, isStrict)
                stmt.catchClause?.let { walkForDeleteOperator(it.block.statements, source, fileName, isStrict) }
                stmt.finallyBlock?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            }
            is FunctionDeclaration -> stmt.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is Constructor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is GetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is SetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForDeleteOperator(body.statements, source, fileName, isStrict)
            }
            is LabeledStatement -> walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            is ThrowStatement -> stmt.expression?.let { walkExprForDelete(it, source, fileName, isStrict) }
            is ExportAssignment -> stmt.expression?.let { walkExprForDelete(it, source, fileName, isStrict) }
            else -> {}
        }
    }

    private fun walkExprForDelete(expr: Expression, source: String, fileName: String, isStrict: Boolean) {
        when (expr) {
            is DeleteExpression -> {
                val operand = expr.expression
                // Unwrap parentheses
                var inner = operand
                while (inner is ParenthesizedExpression) inner = inner.expression
                val isPropertyRef = inner is PropertyAccessExpression || inner is ElementAccessExpression
                // 16.4eb: TS2790 "The operand of a 'delete' operator must be optional."
                // Fires under strictNullChecks when deleting a known property that isn't
                // declared optional AND whose type doesn't include undefined/any/unknown/never.
                // Index-signature access is skipped (no named property declaration resolves).
                if (strictNullChecks && inner is PropertyAccessExpression) {
                    try {
                        val objType = getTypeOfExpression(inner.expression)
                        if (objType !== anyType && objType !== errorType) {
                            val apparent = getApparentType(objType)
                            val propSym = getPropertyOfType(apparent, inner.name.text)
                            if (propSym != null && !isOptionalProperty(propSym)) {
                                val propType = getTypeOfSymbol(propSym)
                                // Under exactOptionalPropertyTypes, a required property with
                                // `| undefined` in its type still requires optionality to delete.
                                // Under default (exactOptional=false), `T | undefined` is treated
                                // as optional-for-delete purposes.
                                val skipOnUndefinedInType = !options.exactOptionalPropertyTypes
                                if (propType !== anyType && propType !== errorType &&
                                    !propType.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never) &&
                                    (!skipOnUndefinedInType || !typeIncludesUndefinedOrTop(propType))) {
                                    val start = inner.pos
                                    val length = expressionTrueEnd(inner) - start
                                    if (length > 0) {
                                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                                        diagnostics.add(Diagnostic(
                                            message = "The operand of a 'delete' operator must be optional.",
                                            category = DiagnosticCategory.Error,
                                            code = 2790,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = start,
                                            length = length,
                                        ))
                                    }
                                }
                            }
                        }
                    } catch (_: StackOverflowError) { /* circular type */ }
                }
                if (!isPropertyRef) {
                    // TS2703: operand must be property reference
                    val start = inner.pos
                    val length = inner.end - inner.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    if (isStrict && inner is Identifier) {
                        // TS1102: delete on identifier in strict mode
                        diagnostics.add(Diagnostic(
                            message = "'delete' cannot be called on an identifier in strict mode.",
                            category = DiagnosticCategory.Error,
                            code = 1102,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = inner.text.length,
                        ))
                    }
                    diagnostics.add(Diagnostic(
                        message = "The operand of a 'delete' operator must be a property reference.",
                        category = DiagnosticCategory.Error,
                        code = 2703,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = if (inner is Identifier) inner.text.length else (inner.end - inner.pos).coerceAtLeast(1),
                    ))
                }
                // Also recurse into the operand for nested deletes
                walkExprForDelete(operand, source, fileName, isStrict)
            }
            is BinaryExpression -> {
                // Iteratively walk binary chains to avoid StackOverflow on deep trees
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkExprForDelete(current.right, source, fileName, isStrict)
                    current = current.left
                }
                walkExprForDelete(current, source, fileName, isStrict)
            }
            is CallExpression -> {
                walkExprForDelete(expr.expression, source, fileName, isStrict)
                expr.arguments.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            }
            is ParenthesizedExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is ConditionalExpression -> {
                walkExprForDelete(expr.condition, source, fileName, isStrict)
                walkExprForDelete(expr.whenTrue, source, fileName, isStrict)
                walkExprForDelete(expr.whenFalse, source, fileName, isStrict)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> walkForDeleteOperator(body.statements, source, fileName, isStrict)
                is Expression -> walkExprForDelete(body, source, fileName, isStrict)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> walkExprForDelete(prop.initializer, source, fileName, isStrict)
                        is SpreadAssignment -> walkExprForDelete(prop.expression, source, fileName, isStrict)
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { walkExprForDelete(it.expression, source, fileName, isStrict) }
            }
            is CommaListExpression -> expr.elements.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            is AsExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is TypeAssertionExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is SatisfiesExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is NonNullExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is NewExpression -> {
                walkExprForDelete(expr.expression, source, fileName, isStrict)
                expr.arguments?.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            }
            is PropertyAccessExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is ElementAccessExpression -> {
                walkExprForDelete(expr.expression, source, fileName, isStrict)
                walkExprForDelete(expr.argumentExpression, source, fileName, isStrict)
            }
            is PrefixUnaryExpression -> walkExprForDelete(expr.operand, source, fileName, isStrict)
            is PostfixUnaryExpression -> walkExprForDelete(expr.operand, source, fileName, isStrict)
            is SpreadElement -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is AwaitExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is YieldExpression -> expr.expression?.let { walkExprForDelete(it, source, fileName, isStrict) }
            is VoidExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is TypeOfExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is TaggedTemplateExpression -> {
                walkExprForDelete(expr.tag, source, fileName, isStrict)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkExprForDelete(it.expression, source, fileName, isStrict)
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is Constructor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is GetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is SetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is PropertyDeclaration -> member.initializer?.let { walkExprForDelete(it, source, fileName, isStrict) }
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Const assignment checking (TS2588)
    // -----------------------------------------------------------------------

    private fun checkConstAssignment() {
        // Script files (no imports/exports) share a global scope — a `const x` in
        // fileA.ts is visible to `x++` in fileB.ts. Collect top-level immutable
        // bindings from all script files first, then seed each file's check with
        // those shared names. Module files keep their own file-local scope.
        val sharedConsts = mutableMapOf<String, Int>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                    for (decl in stmt.declarationList.declarations) {
                        (decl.name as? Identifier)?.let { sharedConsts.putIfAbsent(it.text, 2588) }
                    }
                }
                if (stmt is ClassDeclaration && stmt.name != null) {
                    sharedConsts.putIfAbsent(stmt.name!!.text, 2629)
                }
                if (stmt is EnumDeclaration) {
                    sharedConsts.putIfAbsent(stmt.name.text, 2628)
                }
                if (stmt is FunctionDeclaration && stmt.name != null) {
                    sharedConsts.putIfAbsent(stmt.name!!.text, 2630)
                }
                if (stmt is ModuleDeclaration && stmt.name is Identifier) {
                    sharedConsts.putIfAbsent((stmt.name as Identifier).text, 2708)
                }
            }
        }
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val seed = if (isModuleFile(result.sourceFile.statements)) mutableMapOf() else sharedConsts.toMutableMap()
            checkConstAssignmentInStatements(result.sourceFile.statements, source, fileName, seed)
        }
    }

    // Map from name -> diagnostic code (2588=const, 2629=class, 2628=enum, 2630=func, 2708=namespace)
    private fun checkConstAssignmentInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        constNames: MutableMap<String, Int>,
    ) {
        for (stmt in statements) {
            // Collect const declarations
            if (stmt is VariableStatement) {
                if (stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier) {
                            constNames[name.text] = 2588
                        }
                    }
                }
            }
            // Collect class names — classes are also immutable bindings (TS2629)
            if (stmt is ClassDeclaration && stmt.name != null) {
                constNames[stmt.name!!.text] = 2629
            }
            // Collect enum names — enums are immutable bindings (TS2628)
            if (stmt is EnumDeclaration) {
                constNames[stmt.name.text] = 2628
            }
            // Collect function names — function declarations are immutable bindings (TS2630)
            if (stmt is FunctionDeclaration && stmt.name != null) {
                constNames[stmt.name!!.text] = 2630
            }
            // Collect namespace names — namespaces are not values (TS2708)
            if (stmt is ModuleDeclaration && stmt.name is Identifier) {
                constNames[(stmt.name as Identifier).text] = 2708
            }
            // Check for assignments to const variables
            checkConstAssignmentInStatement(stmt, source, fileName, constNames)
        }
    }

    private fun checkConstAssignmentInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        constNames: Map<String, Int>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            is IfStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.thenStatement, source, fileName, constNames)
                stmt.elseStatement?.let { checkConstAssignmentInStatement(it, source, fileName, constNames) }
            }
            is Block -> checkConstAssignmentInStatements(stmt.statements, source, fileName, constNames.toMutableMap())
            is ForStatement -> {
                // Collect const in for init
                val forConsts = constNames.toMutableMap()
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        if (init.flags == SyntaxKind.ConstKeyword) {
                            for (decl in init.declarations) {
                                val name = decl.name
                                if (name is Identifier) forConsts[name.text] = 2588
                            }
                        }
                    }
                    is Expression -> checkConstAssignmentInExpr(init, source, fileName, constNames)
                    else -> {}
                }
                stmt.condition?.let { checkConstAssignmentInExpr(it, source, fileName, forConsts) }
                stmt.incrementor?.let { checkConstAssignmentInExpr(it, source, fileName, forConsts) }
                checkConstAssignmentInStatement(stmt.statement, source, fileName, forConsts)
            }
            is ForInStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            }
            is ForOfStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            }
            is WhileStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            }
            is DoStatement -> {
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
            }
            is SwitchStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                for (clause in stmt.caseBlock) {
                    val stmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkConstAssignmentInStatements(stmts, source, fileName, constNames.toMutableMap())
                }
            }
            is TryStatement -> {
                checkConstAssignmentInStatements(stmt.tryBlock.statements, source, fileName, constNames.toMutableMap())
                stmt.catchClause?.block?.let {
                    checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableMap())
                }
                stmt.finallyBlock?.let {
                    checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableMap())
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { checkConstAssignmentInStatements(it.statements, source, fileName, mutableMapOf()) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    // Pass outer constNames so class/enum assignments in methods are caught
                    body?.let { checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableMap()) }
                    if (member is PropertyDeclaration) {
                        member.initializer?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkConstAssignmentInStatements(body.statements, source, fileName, constNames.toMutableMap())
                }
            }
            is LabeledStatement -> checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            is ThrowStatement -> stmt.expression?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            is ExportAssignment -> checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
            else -> {}
        }
    }

    private fun checkConstAssignmentInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        constNames: Map<String, Int>,
    ) {
        when (expr) {
            is BinaryExpression -> {
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    val op = current.operator
                    if (op == SyntaxKind.Equals || op == SyntaxKind.PlusEquals || op == SyntaxKind.MinusEquals
                        || op == SyntaxKind.AsteriskEquals || op == SyntaxKind.SlashEquals
                        || op == SyntaxKind.PercentEquals || op == SyntaxKind.AmpersandEquals
                        || op == SyntaxKind.BarEquals || op == SyntaxKind.CaretEquals
                        || op == SyntaxKind.LessThanLessThanEquals || op == SyntaxKind.GreaterThanGreaterThanEquals
                        || op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals
                        || op == SyntaxKind.AsteriskAsteriskEquals
                        || op == SyntaxKind.BarBarEquals || op == SyntaxKind.AmpersandAmpersandEquals
                        || op == SyntaxKind.QuestionQuestionEquals) {
                        val left = current.left
                        if (left is Identifier && left.text in constNames) {
                            emitReadonlyAssignment(left, source, fileName, constNames[left.text] ?: 2588)
                        }
                        // Check assignment to readonly property (TS2540)
                        checkReadonlyAssignmentTarget(left, source, fileName)
                    }
                    checkConstAssignmentInExpr(current.right, source, fileName, constNames)
                    current = current.left
                }
                checkConstAssignmentInExpr(current, source, fileName, constNames)
            }
            is PrefixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    val operand = unwrapParens(expr.operand)
                    if (operand is Identifier && operand.text in constNames) {
                        emitReadonlyAssignment(operand, source, fileName, constNames[operand.text] ?: 2588)
                    }
                    // Check readonly property (TS2540)
                    checkReadonlyAssignmentTarget(operand, source, fileName)
                }
                checkConstAssignmentInExpr(expr.operand, source, fileName, constNames)
            }
            is PostfixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    val operand = unwrapNonNull(expr.operand)
                    if (operand is Identifier && operand.text in constNames) {
                        emitReadonlyAssignment(operand, source, fileName, constNames[operand.text] ?: 2588)
                    }
                    // Check readonly property (TS2540)
                    checkReadonlyAssignmentTarget(operand, source, fileName)
                }
                checkConstAssignmentInExpr(expr.operand, source, fileName, constNames)
            }
            is CallExpression -> {
                checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
                expr.arguments.forEach { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            }
            is NewExpression -> {
                checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
                expr.arguments?.forEach { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            }
            is ParenthesizedExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is AsExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is SatisfiesExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is NonNullExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is TypeAssertionExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is PropertyAccessExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is ElementAccessExpression -> {
                checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
                checkConstAssignmentInExpr(expr.argumentExpression, source, fileName, constNames)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkConstAssignmentInExpr(prop.initializer, source, fileName, constNames)
                    is SpreadAssignment -> checkConstAssignmentInExpr(prop.expression, source, fileName, constNames)
                    else -> {}
                }
            }
            is SpreadElement -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is TemplateExpression -> expr.templateSpans.forEach { checkConstAssignmentInExpr(it.expression, source, fileName, constNames) }
            is ConditionalExpression -> {
                checkConstAssignmentInExpr(expr.condition, source, fileName, constNames)
                checkConstAssignmentInExpr(expr.whenTrue, source, fileName, constNames)
                checkConstAssignmentInExpr(expr.whenFalse, source, fileName, constNames)
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkConstAssignmentInStatements(body.statements, source, fileName, mutableMapOf())
                    is Expression -> checkConstAssignmentInExpr(body, source, fileName, constNames)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkConstAssignmentInStatements(expr.body.statements, source, fileName, mutableMapOf())
            }
            else -> {}
        }
    }

    private fun unwrapNonNull(expr: Expression): Expression {
        var e = expr
        while (e is NonNullExpression) e = e.expression
        return e
    }

    private fun unwrapParens(expr: Expression): Expression {
        var e = expr
        while (e is ParenthesizedExpression) e = e.expression
        return e
    }

    /** Check if a property access targets a readonly property. */
    private fun isReadonlyPropertyAccess(expr: PropertyAccessExpression, fileName: String? = null): Boolean {
        val objExpr = expr.expression
        val propName = expr.name.text
        // Check namespace/module exports for const variables, and enum member access
        if (objExpr is Identifier) {
            val objName = objExpr.text
            val objSymbol = globals[objName] ?: (if (fileName != null) fileResults[fileName]?.locals?.get(objName) else null)
            if (objSymbol != null) {
                if (objSymbol.flags.hasAny(SymbolFlags.Module)) {
                    val exportSymbol = objSymbol.exports?.get(propName)
                    if (exportSymbol != null && isConstExport(objSymbol, propName)) {
                        return true
                    }
                }
                // Enum members are always readonly (TS2540)
                if (objSymbol.flags.hasAny(SymbolFlags.Enum)) {
                    val exportSymbol = objSymbol.exports?.get(propName)
                    if (exportSymbol != null && exportSymbol.flags.hasAny(SymbolFlags.EnumMember)) {
                        return true
                    }
                }
            }
        }
        // Check interface/class readonly property members via type system
        try {
            val objectType = getTypeOfExpression(objExpr)
            if (objectType === anyType || objectType === errorType) return false
            val prop = getPropertyOfType(objectType, propName) ?: return false
            return isReadonlySymbol(prop)
        } catch (_: StackOverflowError) {
            return false
        }
    }

    /** Check if a symbol is declared readonly. */
    private fun isReadonlySymbol(symbol: Symbol): Boolean {
        return symbol.declarations.any { decl ->
            when (decl) {
                is PropertyDeclaration -> ModifierFlag.Readonly in decl.modifiers
                else -> false
            }
        }
    }

    /** Check if a namespace/module exports a name as a const variable. */
    private fun isConstExport(namespaceSymbol: Symbol, exportName: String): Boolean {
        // Walk the namespace body to find if the export is a const declaration
        for (decl in namespaceSymbol.declarations) {
            val body = when (decl) {
                is ModuleDeclaration -> decl.body
                else -> continue
            }
            val stmts = when (body) {
                is ModuleBlock -> body.statements
                else -> continue
            }
            for (stmt in stmts) {
                if (stmt is VariableStatement && stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                    for (varDecl in stmt.declarationList.declarations) {
                        val name = varDecl.name
                        if (name is Identifier && name.text == exportName) return true
                    }
                }
            }
        }
        return false
    }

    /** Emit TS2540 for assignment to a readonly property. */
    private fun emitTS2540(propName: String, pos: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Cannot assign to '$propName' because it is a read-only property.",
            category = DiagnosticCategory.Error,
            code = 2540,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = length,
        ))
    }

    /** Check if an assignment target is a readonly property and emit TS2540. */
    private fun checkReadonlyAssignmentTarget(target: Expression, source: String, fileName: String) {
        val unwrapped = unwrapParens(target)
        when (unwrapped) {
            is PropertyAccessExpression -> {
                if (isReadonlyPropertyAccess(unwrapped, fileName)) {
                    emitTS2540(unwrapped.name.text, unwrapped.name.pos, unwrapped.name.text.length, source, fileName)
                }
            }
            is ElementAccessExpression -> {
                // m["x"] = value — check if it's a readonly property too
                val arg = unwrapped.argumentExpression
                if (arg is StringLiteralNode && unwrapped.expression is Identifier) {
                    val objName = (unwrapped.expression as Identifier).text
                    val objSymbol = globals[objName]
                    if (objSymbol != null && objSymbol.flags.hasAny(SymbolFlags.Module) &&
                        isConstExport(objSymbol, arg.text)) {
                        emitTS2540(arg.text, arg.pos, (arg.rawText ?: arg.text).length + 2, source, fileName)
                    }
                }
            }
            else -> {}
        }
    }

    private fun emitReadonlyAssignment(id: Identifier, source: String, fileName: String, fallbackCode: Int = 2588) {
        val start = id.pos
        val length = id.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Check symbol type to determine the exact diagnostic code
        // Search file locals, globals, and namespace exports recursively
        val binderResult = fileResults[fileName]
        var symbol = binderResult?.locals?.get(id.text) ?: globals[id.text]
        if (symbol == null && binderResult != null) {
            // Search inside namespace exports
            fun searchExports(table: SymbolTable): Symbol? {
                for ((_, sym) in table) {
                    if (sym.exports != null) {
                        val found = sym.exports!![id.text]
                        if (found != null) return found
                        val deeper = searchExports(sym.exports!!)
                        if (deeper != null) return deeper
                    }
                }
                return null
            }
            symbol = searchExports(binderResult.locals)
        }
        val (message, code) = when {
            symbol?.flags?.hasAny(SymbolFlags.Module) == true ->
                "Cannot use namespace '${id.text}' as a value." to 2708
            symbol?.flags?.hasAny(SymbolFlags.Function) == true ->
                "Cannot assign to '${id.text}' because it is a function." to 2630
            symbol?.flags?.hasAny(SymbolFlags.Class) == true ->
                "Cannot assign to '${id.text}' because it is a class." to 2629
            symbol?.flags?.hasAny(SymbolFlags.Enum) == true ->
                "Cannot assign to '${id.text}' because it is an enum." to 2628
            symbol != null ->
                "Cannot assign to '${id.text}' because it is a constant." to 2588
            else -> {
                // Symbol not found in binder locals — use fallback code from constNames map
                val msg = when (fallbackCode) {
                    2708 -> "Cannot use namespace '${id.text}' as a value."
                    2630 -> "Cannot assign to '${id.text}' because it is a function."
                    2629 -> "Cannot assign to '${id.text}' because it is a class."
                    2628 -> "Cannot assign to '${id.text}' because it is an enum."
                    else -> "Cannot assign to '${id.text}' because it is a constant."
                }
                msg to fallbackCode
            }
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Parameter property checking (TS2369)
    // -----------------------------------------------------------------------

    private fun checkParameterProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForParameterProperties(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForParameterProperties(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    // Function parameters with access modifiers → TS2369
                    checkParamPropsInParams(stmt.parameters, source, fileName)
                    checkInvalidParameterModifiers(stmt.parameters, source, fileName)
                    // Check for param props in type annotations (e.g., return type `(public B) => C`)
                    checkParamPropsInTypeAnnotation(stmt.type, source, fileName)
                    for (p in stmt.parameters) checkParamPropsInTypeAnnotation(p.type, source, fileName)
                    stmt.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is Constructor -> {
                                // Flag parameter properties on constructor declarations without body
                                if (member.body == null) {
                                    checkParamPropsInParams(member.parameters, source, fileName)
                                }
                                // TS1187: parameter property declared with a binding pattern
                                checkBindingPatternParamProperties(member.parameters, source, fileName)
                                // TS1090: invalid modifiers checked on ALL constructors (with or without body)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                // Check for param props in parameter type annotations
                                for (p in member.parameters) checkParamPropsInTypeAnnotation(p.type, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is GetAccessor -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is SetAccessor -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            else -> {}
                        }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        when (val init = decl.initializer) {
                            is ArrowFunction -> checkParamPropsInParams(init.parameters, source, fileName)
                            is FunctionExpression -> {
                                checkParamPropsInParams(init.parameters, source, fileName)
                                walkForParameterProperties(init.body.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ExpressionStatement -> walkForParamPropsInExpr(stmt.expression, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForParameterProperties(body.statements, source, fileName)
                }
                is InterfaceDeclaration -> {
                    // Interface construct signatures `new (public x)` → TS2369
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) {
                            checkParamPropsInParams(member.parameters, source, fileName)
                        }
                    }
                }
                is Block -> walkForParameterProperties(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkParamPropsInTypeAnnotation(type: TypeNode?, source: String, fileName: String) {
        when (type) {
            is FunctionType -> checkParamPropsInParams(type.parameters, source, fileName)
            else -> {}
        }
    }

    private fun walkForParamPropsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkParamPropsInParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> walkForParameterProperties(body.statements, source, fileName)
                    is Expression -> walkForParamPropsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkParamPropsInParams(expr.parameters, source, fileName)
                walkForParameterProperties(expr.body.statements, source, fileName)
            }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> {
                    checkParamPropsInParams(m.parameters, source, fileName)
                    m.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is Constructor -> {
                    // Constructor param-props are legitimate; only check non-param-props
                    checkBindingPatternParamProperties(m.parameters, source, fileName)
                    m.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is GetAccessor -> m.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                is SetAccessor -> {
                    checkParamPropsInParams(m.parameters, source, fileName)
                    m.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is PropertyDeclaration -> m.initializer?.let { walkForParamPropsInExpr(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is AsExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (current is BinaryExpression) { rightStack.addLast(current.right); current = current.left }
                walkForParamPropsInExpr(current, source, fileName)
                while (rightStack.isNotEmpty()) walkForParamPropsInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                walkForParamPropsInExpr(expr.condition, source, fileName)
                walkForParamPropsInExpr(expr.whenTrue, source, fileName)
                walkForParamPropsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkForParamPropsInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { walkForParamPropsInExpr(it, source, fileName) }
            }
            is NewExpression -> {
                walkForParamPropsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkForParamPropsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkForParamPropsInExpr(expr.expression, source, fileName)
                walkForParamPropsInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) walkForParamPropsInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> walkForParamPropsInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> walkForParamPropsInExpr(p.expression, source, fileName)
                is MethodDeclaration -> {
                    checkParamPropsInParams(p.parameters, source, fileName)
                    p.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is GetAccessor -> p.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                is SetAccessor -> {
                    checkParamPropsInParams(p.parameters, source, fileName)
                    p.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                else -> {}
            }
            is SpreadElement -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkForParamPropsInExpr(it, source, fileName) }
            is VoidExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkForParamPropsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkForParamPropsInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkForParamPropsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkForParamPropsInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkForParamPropsInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkForParamPropsInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun isParameterPropertyModifier(flag: ModifierFlag): Boolean =
        flag == ModifierFlag.Public || flag == ModifierFlag.Private ||
        flag == ModifierFlag.Protected || flag == ModifierFlag.Readonly ||
        flag == ModifierFlag.Override

    private fun isInvalidParameterModifier(flag: ModifierFlag): Boolean =
        flag == ModifierFlag.Static || flag == ModifierFlag.Export ||
        flag == ModifierFlag.Async || flag == ModifierFlag.Declare

    private fun modifierFlagKeyword(flag: ModifierFlag): String = when (flag) {
        ModifierFlag.Static -> "static"
        ModifierFlag.Export -> "export"
        ModifierFlag.Async -> "async"
        ModifierFlag.Declare -> "declare"
        ModifierFlag.Public -> "public"
        ModifierFlag.Private -> "private"
        ModifierFlag.Protected -> "protected"
        ModifierFlag.Readonly -> "readonly"
        ModifierFlag.Override -> "override"
        ModifierFlag.Abstract -> "abstract"
        ModifierFlag.Default -> "default"
        ModifierFlag.Const -> "const"
        ModifierFlag.In -> "in"
        ModifierFlag.Out -> "out"
        ModifierFlag.Accessor -> "accessor"
    }

    private fun checkInvalidParameterModifiers(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            for (mod in param.modifiers) {
                if (!isInvalidParameterModifier(mod)) continue
                val keyword = modifierFlagKeyword(mod)
                // Find keyword position in source between param.pos and param.name.pos
                val searchStart = param.pos
                val searchEnd = param.name.pos
                val idx = source.indexOf(keyword, searchStart)
                if (idx < 0 || idx >= searchEnd) continue
                val (line, character) = getLineAndCharacterOfPosition(source, idx)
                diagnostics.add(Diagnostic(
                    message = "'$keyword' modifier cannot appear on a parameter.",
                    category = DiagnosticCategory.Error,
                    code = 1090,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = idx,
                    length = keyword.length,
                ))
            }
        }
    }

    private fun checkParamPropsInParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            if (param.modifiers.any { isParameterPropertyModifier(it) }) {
                // Parameter has access modifier outside constructor implementation → TS2369
                val start = param.pos
                // Skip leading whitespace
                var spanStart = start
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                // Calculate span: from modifier to end of initializer, type, or name
                val rawEnd = param.initializer?.end ?: param.type?.end ?: param.name.end
                var contentEnd = rawEnd
                while (contentEnd > spanStart && contentEnd <= source.length &&
                    source[contentEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' || it == ';' }) {
                    contentEnd--
                }
                val spanEnd = contentEnd
                val length = spanEnd - spanStart
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "A parameter property is only allowed in a constructor implementation.",
                    category = DiagnosticCategory.Error,
                    code = 2369,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
                // Also emit TS7006 when parameter has no type annotation.
                // Fires by default but suppressed when strict is explicitly false.
                val name = param.name
                if (param.type == null && name is Identifier && name.text != "this" &&
                    !options.strictExplicitlyFalse) {
                    diagnostics.add(Diagnostic(
                        message = "Parameter '${name.text}' implicitly has an 'any' type.",
                        category = DiagnosticCategory.Error,
                        code = 7006,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
            }
        }
    }

    /**
     * TS1187: a parameter property (a constructor parameter carrying an accessibility
     * modifier — public/private/protected/readonly/override) may not be declared using
     * an object/array binding pattern. The squiggle spans the whole parameter (modifier
     * through type annotation), mirroring [checkParamPropsInParams]'s span computation.
     */
    private fun checkBindingPatternParamProperties(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            if (!param.modifiers.any { isParameterPropertyModifier(it) }) continue
            val name = param.name
            if (name !is ObjectBindingPattern && name !is ArrayBindingPattern) continue
            var spanStart = param.pos
            while (spanStart < source.length &&
                source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
            val rawEnd = param.initializer?.end ?: param.type?.end ?: param.name.end
            var contentEnd = rawEnd
            while (contentEnd > spanStart && contentEnd <= source.length &&
                source[contentEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' || it == ';' }) {
                contentEnd--
            }
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "A parameter property may not be declared using a binding pattern.",
                category = DiagnosticCategory.Error, code = 1187,
                fileName = fileName, line = line, character = character,
                start = spanStart, length = contentEnd - spanStart,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // Super in non-derived class checking (TS2335)
    // -----------------------------------------------------------------------

    private fun checkSuperInNonDerived() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSuperInNonDerived(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSuperInNonDerived(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val isDerived = stmt.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true
                    if (!isDerived) {
                        // Check all methods/constructors for super references
                        for (member in stmt.members) {
                            val body = when (member) {
                                is MethodDeclaration -> member.body
                                is Constructor -> member.body
                                is GetAccessor -> member.body
                                is SetAccessor -> member.body
                                else -> null
                            }
                            body?.let {
                                findSuperRefsInStatements(it.statements, source, fileName)
                            }
                        }
                    }
                    // Recurse into nested classes (even in derived ones)
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is Constructor -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            else -> null
                        }
                        body?.let { walkForSuperInNonDerived(it.statements, source, fileName) }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForSuperInNonDerived(it.statements, source, fileName) }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForSuperInNonDerived(body.statements, source, fileName)
                }
                is Block -> walkForSuperInNonDerived(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun findSuperRefsInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            findSuperRefsInStatement(stmt, source, fileName)
        }
    }

    private fun findSuperRefsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> findSuperRefsInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { findSuperRefsInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { findSuperRefsInExpr(it, source, fileName) }
            is IfStatement -> {
                findSuperRefsInExpr(stmt.expression, source, fileName)
                findSuperRefsInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { findSuperRefsInStatement(it, source, fileName) }
            }
            is Block -> findSuperRefsInStatements(stmt.statements, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> findSuperRefsInExpr(init, source, fileName)
                    else -> {}
                }
                findSuperRefsInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                findSuperRefsInExpr(stmt.expression, source, fileName)
                findSuperRefsInStatement(stmt.statement, source, fileName)
            }
            else -> {}
        }
    }

    private fun findSuperRefsInExpr(expr: Expression, source: String, fileName: String) {
        when {
            isSuperIdentifier(expr) -> {
                emitTS2335(expr as Identifier, source, fileName)
            }
            expr is PropertyAccessExpression -> {
                if (isSuperIdentifier(expr.expression)) {
                    emitTS2335(expr.expression as Identifier, source, fileName)
                } else {
                    findSuperRefsInExpr(expr.expression, source, fileName)
                }
            }
            expr is CallExpression -> {
                if (isSuperIdentifier(expr.expression)) {
                    emitTS2335(expr.expression as Identifier, source, fileName)
                } else {
                    findSuperRefsInExpr(expr.expression, source, fileName)
                }
                expr.arguments.forEach { findSuperRefsInExpr(it, source, fileName) }
            }
            expr is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    findSuperRefsInExpr(current.right, source, fileName)
                    current = current.left
                }
                findSuperRefsInExpr(current, source, fileName)
            }
            expr is ParenthesizedExpression -> findSuperRefsInExpr(expr.expression, source, fileName)
            expr is ArrowFunction -> {} // Don't recurse into nested functions
            expr is FunctionExpression -> {} // Don't recurse into nested functions
            else -> {}
        }
    }

    private fun emitTS2335(superRef: Identifier, source: String, fileName: String) {
        val start = superRef.pos
        val length = 5 // "super" is 5 characters
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'super' can only be referenced in a derived class.",
            category = DiagnosticCategory.Error,
            code = 2335,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Super in object literal members (TS2659/TS2660)
    // -----------------------------------------------------------------------

    private fun checkSuperInObjectLiterals() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForObjLitSuper(result.sourceFile.statements, source, fileName, superValid = false)
        }
    }

    // [superValid] tracks whether the current LEXICAL scope provides a valid `super`
    // binding (derived-class method/constructor/getter/setter body, or object-literal
    // method/getter/setter body). Arrows preserve it; regular functions reset to false;
    // class members set it from their containing class's `extends` clause. Used to
    // decide whether an ArrowFunction-initialized PropertyAssignment in an object literal
    // should fire TS2660 — the arrow inherits super from the enclosing context, so
    // `obj = { p: () => super.x }` at top level errors but `class B extends A { f() {
    // var obj = { p: () => super.x } } }` is valid.
    private fun walkForObjLitSuper(statements: List<Statement>, source: String, fileName: String, superValid: Boolean) {
        for (stmt in statements) walkObjLitSuperInStmt(stmt, source, fileName, superValid)
    }

    private fun walkObjLitSuperInStmt(stmt: Statement, source: String, fileName: String, superValid: Boolean) {
        when (stmt) {
            is ExpressionStatement -> walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
            is VariableStatement -> stmt.declarationList.declarations.forEach {
                it.initializer?.let { i -> walkObjLitSuperInExpr(i, source, fileName, superValid) }
            }
            is ReturnStatement -> stmt.expression?.let { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            is IfStatement -> {
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
                walkObjLitSuperInStmt(stmt.thenStatement, source, fileName, superValid)
                stmt.elseStatement?.let { walkObjLitSuperInStmt(it, source, fileName, superValid) }
            }
            is Block -> walkForObjLitSuper(stmt.statements, source, fileName, superValid)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkObjLitSuperInExpr(it, source, fileName, superValid) }
                walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
            }
            is WhileStatement -> {
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
                walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
            }
            is DoStatement -> {
                walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
            }
            // Regular functions rebind super (to undefined for object literals).
            is FunctionDeclaration -> stmt.body?.let { walkForObjLitSuper(it.statements, source, fileName, superValid = false) }
            is ClassDeclaration -> {
                val classHasExtends = stmt.heritageClauses
                    ?.any { it.token == SyntaxKind.ExtendsKeyword } == true
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        is Constructor -> member.body
                        is ClassStaticBlockDeclaration -> member.body
                        else -> null
                    }
                    body?.let { walkForObjLitSuper(it.statements, source, fileName, superValid = classHasExtends) }
                    if (member is PropertyDeclaration) {
                        member.initializer?.let { walkObjLitSuperInExpr(it, source, fileName, superValid = classHasExtends) }
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForObjLitSuper(body.statements, source, fileName, superValid)
            }
            is ForInStatement -> {
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
                walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
            }
            is ForOfStatement -> {
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
                walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
            }
            is SwitchStatement -> {
                walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            walkObjLitSuperInExpr(clause.expression, source, fileName, superValid)
                            clause.statements.forEach { walkObjLitSuperInStmt(it, source, fileName, superValid) }
                        }
                        is DefaultClause -> clause.statements.forEach { walkObjLitSuperInStmt(it, source, fileName, superValid) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkObjLitSuperInStmt(it, source, fileName, superValid) }
                stmt.catchClause?.block?.statements?.forEach { walkObjLitSuperInStmt(it, source, fileName, superValid) }
                stmt.finallyBlock?.statements?.forEach { walkObjLitSuperInStmt(it, source, fileName, superValid) }
            }
            is LabeledStatement -> walkObjLitSuperInStmt(stmt.statement, source, fileName, superValid)
            is ThrowStatement -> stmt.expression?.let { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            is ExportAssignment -> walkObjLitSuperInExpr(stmt.expression, source, fileName, superValid)
            else -> {}
        }
    }

    private fun walkObjLitSuperInExpr(expr: Expression, source: String, fileName: String, superValid: Boolean) {
        when (expr) {
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        // Object-literal methods/accessors bind super (via __proto__).
                        is GetAccessor -> {
                            if (options.target < ScriptTarget.ES2015) {
                                prop.body?.let { findObjLitSuperRefs(it.statements, source, fileName, code = 2659) }
                            }
                            prop.body?.let { walkForObjLitSuper(it.statements, source, fileName, superValid = true) }
                        }
                        is SetAccessor -> {
                            if (options.target < ScriptTarget.ES2015) {
                                prop.body?.let { findObjLitSuperRefs(it.statements, source, fileName, code = 2659) }
                            }
                            prop.body?.let { walkForObjLitSuper(it.statements, source, fileName, superValid = true) }
                        }
                        is MethodDeclaration -> {
                            if (options.target < ScriptTarget.ES2015) {
                                prop.body?.let { findObjLitSuperRefs(it.statements, source, fileName, code = 2659) }
                            }
                            prop.body?.let { walkForObjLitSuper(it.statements, source, fileName, superValid = true) }
                        }
                        is PropertyAssignment -> {
                            when (val init = prop.initializer) {
                                is FunctionExpression -> {
                                    // Regular function expression rebinds super → unconditional TS2660.
                                    findObjLitSuperRefs(init.body.statements, source, fileName, code = 2660)
                                    walkForObjLitSuper(init.body.statements, source, fileName, superValid = false)
                                }
                                is ArrowFunction -> {
                                    // Arrow inherits super from the enclosing lexical scope.
                                    // Emit TS2660 only when that scope lacks a super binding.
                                    if (!superValid) {
                                        when (val body = init.body) {
                                            is Block -> findObjLitSuperRefs(body.statements, source, fileName, code = 2660)
                                            is Expression -> findObjLitSuperRefsInExpr(body, source, fileName, code = 2660)
                                            else -> {}
                                        }
                                    }
                                    when (val body = init.body) {
                                        is Block -> walkForObjLitSuper(body.statements, source, fileName, superValid)
                                        is Expression -> walkObjLitSuperInExpr(body, source, fileName, superValid)
                                        else -> {}
                                    }
                                }
                                else -> walkObjLitSuperInExpr(init, source, fileName, superValid)
                            }
                        }
                        is SpreadAssignment -> walkObjLitSuperInExpr(prop.expression, source, fileName, superValid)
                        else -> {}
                    }
                }
            }
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkObjLitSuperInExpr(cur, source, fileName, superValid)
                while (rightStack.isNotEmpty()) walkObjLitSuperInExpr(rightStack.removeLast(), source, fileName, superValid)
            }
            is CallExpression -> {
                walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
                expr.arguments.forEach { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            }
            is NewExpression -> {
                walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
                expr.arguments?.forEach { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            }
            is PropertyAccessExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is ElementAccessExpression -> {
                walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
                walkObjLitSuperInExpr(expr.argumentExpression, source, fileName, superValid)
            }
            is ParenthesizedExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is ConditionalExpression -> {
                walkObjLitSuperInExpr(expr.condition, source, fileName, superValid)
                walkObjLitSuperInExpr(expr.whenTrue, source, fileName, superValid)
                walkObjLitSuperInExpr(expr.whenFalse, source, fileName, superValid)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            // Regular function expression rebinds super.
            is FunctionExpression -> walkForObjLitSuper(expr.body.statements, source, fileName, superValid = false)
            // Arrow function preserves super from outer scope.
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> walkForObjLitSuper(body.statements, source, fileName, superValid)
                    is Expression -> walkObjLitSuperInExpr(body, source, fileName, superValid)
                    else -> {}
                }
            }
            is AsExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is TypeAssertionExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is SatisfiesExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is NonNullExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is PrefixUnaryExpression -> walkObjLitSuperInExpr(expr.operand, source, fileName, superValid)
            is PostfixUnaryExpression -> walkObjLitSuperInExpr(expr.operand, source, fileName, superValid)
            is SpreadElement -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is AwaitExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is YieldExpression -> expr.expression?.let { walkObjLitSuperInExpr(it, source, fileName, superValid) }
            is VoidExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is DeleteExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is TypeOfExpression -> walkObjLitSuperInExpr(expr.expression, source, fileName, superValid)
            is TemplateExpression -> for (span in expr.templateSpans) walkObjLitSuperInExpr(span.expression, source, fileName, superValid)
            is TaggedTemplateExpression -> {
                walkObjLitSuperInExpr(expr.tag, source, fileName, superValid)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkObjLitSuperInExpr(span.expression, source, fileName, superValid)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkObjLitSuperInExpr(e, source, fileName, superValid)
            else -> {}
        }
    }

    private fun findObjLitSuperRefs(statements: List<Statement>, source: String, fileName: String, code: Int) {
        for (stmt in statements) findObjLitSuperRefsInStmt(stmt, source, fileName, code)
    }

    private fun findObjLitSuperRefsInStmt(stmt: Statement, source: String, fileName: String, code: Int) {
        when (stmt) {
            is ExpressionStatement -> findObjLitSuperRefsInExpr(stmt.expression, source, fileName, code)
            is VariableStatement -> stmt.declarationList.declarations.forEach {
                it.initializer?.let { i -> findObjLitSuperRefsInExpr(i, source, fileName, code) }
            }
            is ReturnStatement -> stmt.expression?.let { findObjLitSuperRefsInExpr(it, source, fileName, code) }
            is IfStatement -> {
                findObjLitSuperRefsInExpr(stmt.expression, source, fileName, code)
                findObjLitSuperRefsInStmt(stmt.thenStatement, source, fileName, code)
                stmt.elseStatement?.let { findObjLitSuperRefsInStmt(it, source, fileName, code) }
            }
            is Block -> findObjLitSuperRefs(stmt.statements, source, fileName, code)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { findObjLitSuperRefsInExpr(it, source, fileName, code) }
                findObjLitSuperRefsInStmt(stmt.statement, source, fileName, code)
            }
            is WhileStatement -> {
                findObjLitSuperRefsInExpr(stmt.expression, source, fileName, code)
                findObjLitSuperRefsInStmt(stmt.statement, source, fileName, code)
            }
            else -> {}
        }
    }

    private fun findObjLitSuperRefsInExpr(expr: Expression, source: String, fileName: String, code: Int) {
        when {
            isSuperIdentifier(expr) -> emitObjLitSuperError(expr as Identifier, source, fileName, code)
            expr is PropertyAccessExpression -> {
                if (isSuperIdentifier(expr.expression)) emitObjLitSuperError(expr.expression as Identifier, source, fileName, code)
                else findObjLitSuperRefsInExpr(expr.expression, source, fileName, code)
            }
            expr is CallExpression -> {
                if (isSuperIdentifier(expr.expression)) emitObjLitSuperError(expr.expression as Identifier, source, fileName, code)
                else findObjLitSuperRefsInExpr(expr.expression, source, fileName, code)
                expr.arguments.forEach { findObjLitSuperRefsInExpr(it, source, fileName, code) }
            }
            expr is BinaryExpression -> {
                // B64.8: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                findObjLitSuperRefsInExpr(cur, source, fileName, code)
                while (rightStack.isNotEmpty()) findObjLitSuperRefsInExpr(rightStack.removeLast(), source, fileName, code)
            }
            expr is ParenthesizedExpression -> findObjLitSuperRefsInExpr(expr.expression, source, fileName, code)
            // Nested object literals are handled by walkObjLitSuperInExpr separately — don't double-emit.
            expr is ObjectLiteralExpression -> {}
            // Arrow inherits super; FunctionExpression rebinds. Don't descend (separate walker handles them).
            expr is ArrowFunction -> {}
            expr is FunctionExpression -> {}
            else -> {}
        }
    }

    private fun emitObjLitSuperError(superRef: Identifier, source: String, fileName: String, code: Int) {
        val start = superRef.pos
        val length = 5 // "super"
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val message = if (code == 2659)
            "'super' is only allowed in members of object literal expressions when option 'target' is 'ES2015' or higher."
        else
            "'super' can only be referenced in members of derived classes or object literal expressions."
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Illegal super(...) calls in nested functions inside constructors (TS2337)
    // -----------------------------------------------------------------------

    private fun checkIllegalSuperCallsInNestedFunctions() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForIllegalSuperCalls(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForIllegalSuperCalls(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Process this class's constructors.
                    for (member in stmt.members) {
                        if (member is Constructor) {
                            member.body?.let { findNestedSuperCalls(it.statements, source, fileName, inNestedFn = false) }
                        }
                    }
                    // Property initializers run in constructor scope but a `super(...)`
                    // call there is still illegal — TypeScript treats it as TS2337
                    // ("outside constructors"). Walk each PropertyDeclaration.initializer
                    // with inNestedFn=true so direct `super(...)` calls fire.
                    for (member in stmt.members) {
                        if (member is PropertyDeclaration) {
                            member.initializer?.let { init ->
                                findNestedSuperCallsInExpr(init, source, fileName, inNestedFn = true)
                            }
                        }
                    }
                    // Recurse into nested classes via member bodies.
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            is Constructor -> member.body
                            is ClassStaticBlockDeclaration -> member.body
                            else -> null
                        }
                        body?.let { walkForIllegalSuperCalls(it.statements, source, fileName) }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { body ->
                    // 17.197: top-level FunctionDeclaration bodies cannot
                    // contain `super(...)` calls. Walk for direct super
                    // calls (treat as `inNestedFn = true`) AND continue the
                    // class-search recursion via walkForIllegalSuperCalls.
                    findNestedSuperCalls(body.statements, source, fileName, inNestedFn = true)
                    walkForIllegalSuperCalls(body.statements, source, fileName)
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForIllegalSuperCalls(body.statements, source, fileName)
                }
                is Block -> walkForIllegalSuperCalls(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForIllegalSuperCalls(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForIllegalSuperCalls(listOf(it), source, fileName) }
                }
                is ForStatement, is WhileStatement, is DoStatement -> {} // bodies don't typically contain class decls; skip
                else -> {}
            }
        }
    }

    /** Walks the constructor body looking for `super(...)` calls. Once we descend into
     * a nested function/arrow/object-literal-method body, [inNestedFn] becomes true and
     * any `super(...)` call there fires TS2337. */
    private fun findNestedSuperCalls(
        statements: List<Statement>,
        source: String,
        fileName: String,
        inNestedFn: Boolean,
    ) {
        for (stmt in statements) findNestedSuperCallsInStmt(stmt, source, fileName, inNestedFn)
    }

    private fun findNestedSuperCallsInStmt(stmt: Statement, source: String, fileName: String, inNestedFn: Boolean) {
        when (stmt) {
            is ExpressionStatement -> findNestedSuperCallsInExpr(stmt.expression, source, fileName, inNestedFn)
            is VariableStatement -> stmt.declarationList.declarations.forEach {
                it.initializer?.let { i -> findNestedSuperCallsInExpr(i, source, fileName, inNestedFn) }
            }
            is ReturnStatement -> stmt.expression?.let { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
            is IfStatement -> {
                findNestedSuperCallsInExpr(stmt.expression, source, fileName, inNestedFn)
                findNestedSuperCallsInStmt(stmt.thenStatement, source, fileName, inNestedFn)
                stmt.elseStatement?.let { findNestedSuperCallsInStmt(it, source, fileName, inNestedFn) }
            }
            is Block -> findNestedSuperCalls(stmt.statements, source, fileName, inNestedFn)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
                findNestedSuperCallsInStmt(stmt.statement, source, fileName, inNestedFn)
            }
            is WhileStatement -> {
                findNestedSuperCallsInExpr(stmt.expression, source, fileName, inNestedFn)
                findNestedSuperCallsInStmt(stmt.statement, source, fileName, inNestedFn)
            }
            is DoStatement -> {
                findNestedSuperCallsInStmt(stmt.statement, source, fileName, inNestedFn)
                findNestedSuperCallsInExpr(stmt.expression, source, fileName, inNestedFn)
            }
            is ThrowStatement -> stmt.expression?.let { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
            else -> {}
        }
    }

    private fun findNestedSuperCallsInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        inNestedFn: Boolean,
    ) {
        when (expr) {
            is CallExpression -> {
                if (inNestedFn && isSuperIdentifier(expr.expression)) {
                    emitTS2337(expr.expression as Identifier, source, fileName)
                } else if (!isSuperIdentifier(expr.expression)) {
                    findNestedSuperCallsInExpr(expr.expression, source, fileName, inNestedFn)
                }
                expr.arguments.forEach { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
            }
            is BinaryExpression -> {
                // B64.8: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                findNestedSuperCallsInExpr(cur, source, fileName, inNestedFn)
                while (rightStack.isNotEmpty()) findNestedSuperCallsInExpr(rightStack.removeLast(), source, fileName, inNestedFn)
            }
            is PropertyAccessExpression -> findNestedSuperCallsInExpr(expr.expression, source, fileName, inNestedFn)
            is ElementAccessExpression -> {
                findNestedSuperCallsInExpr(expr.expression, source, fileName, inNestedFn)
                findNestedSuperCallsInExpr(expr.argumentExpression, source, fileName, inNestedFn)
            }
            is ParenthesizedExpression -> findNestedSuperCallsInExpr(expr.expression, source, fileName, inNestedFn)
            is ConditionalExpression -> {
                findNestedSuperCallsInExpr(expr.condition, source, fileName, inNestedFn)
                findNestedSuperCallsInExpr(expr.whenTrue, source, fileName, inNestedFn)
                findNestedSuperCallsInExpr(expr.whenFalse, source, fileName, inNestedFn)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
            is NewExpression -> {
                findNestedSuperCallsInExpr(expr.expression, source, fileName, inNestedFn)
                expr.arguments?.forEach { findNestedSuperCallsInExpr(it, source, fileName, inNestedFn) }
            }
            is FunctionExpression -> {
                // Entering nested function — `super()` inside is illegal.
                findNestedSuperCalls(expr.body.statements, source, fileName, inNestedFn = true)
            }
            is ArrowFunction -> {
                // Entering nested arrow — even though arrows inherit lexical `this`/`super`,
                // `super()` (the constructor call) is still illegal in arrow inside constructor.
                val body = expr.body
                if (body is Block) findNestedSuperCalls(body.statements, source, fileName, inNestedFn = true)
                else if (body is Expression) findNestedSuperCallsInExpr(body, source, fileName, inNestedFn = true)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is GetAccessor -> prop.body?.let { findNestedSuperCalls(it.statements, source, fileName, inNestedFn = true) }
                        is SetAccessor -> prop.body?.let { findNestedSuperCalls(it.statements, source, fileName, inNestedFn = true) }
                        is MethodDeclaration -> prop.body?.let { findNestedSuperCalls(it.statements, source, fileName, inNestedFn = true) }
                        is PropertyAssignment -> findNestedSuperCallsInExpr(prop.initializer, source, fileName, inNestedFn)
                        is SpreadAssignment -> findNestedSuperCallsInExpr(prop.expression, source, fileName, inNestedFn)
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    private fun emitTS2337(superRef: Identifier, source: String, fileName: String) {
        val start = superRef.pos
        val length = 5 // "super"
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Super calls are not permitted outside constructors or in nested functions inside constructors.",
            category = DiagnosticCategory.Error,
            code = 2337,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2660: super references in regular-function rebinding scopes
    // -----------------------------------------------------------------------

    /** Walks every file looking for `super` references inside regular-function bodies
     * (which rebind super) or arrow bodies whose enclosing scope rebinds super. Class
     * member bodies are entered but the direct level is skipped — TS2335 covers
     * non-derived class methods, and derived class methods have valid super. We only
     * emit when descending past a function/expression boundary that rebinds super. */
    private fun checkSuperRefInRebindingScope() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Top-level statements: super rebound (none available).
            walkSuperRebindStmts(result.sourceFile.statements, source, fileName, rebound = true)
        }
    }

    private fun walkSuperRebindStmts(statements: List<Statement>, source: String, fileName: String, rebound: Boolean) {
        for (stmt in statements) walkSuperRebindStmt(stmt, source, fileName, rebound)
    }

    private fun walkSuperRebindStmt(stmt: Statement, source: String, fileName: String, rebound: Boolean) {
        when (stmt) {
            is ExpressionStatement -> walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
            is VariableStatement -> stmt.declarationList.declarations.forEach {
                it.initializer?.let { i -> walkSuperRebindExpr(i, source, fileName, rebound) }
            }
            is ReturnStatement -> stmt.expression?.let { walkSuperRebindExpr(it, source, fileName, rebound) }
            is IfStatement -> {
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
                walkSuperRebindStmt(stmt.thenStatement, source, fileName, rebound)
                stmt.elseStatement?.let { walkSuperRebindStmt(it, source, fileName, rebound) }
            }
            is Block -> walkSuperRebindStmts(stmt.statements, source, fileName, rebound)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkSuperRebindExpr(it, source, fileName, rebound) }
                walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
            }
            is WhileStatement -> {
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
                walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
            }
            is DoStatement -> {
                walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
            }
            is ThrowStatement -> stmt.expression?.let { walkSuperRebindExpr(it, source, fileName, rebound) }
            // Regular function body: super rebound to undefined.
            is FunctionDeclaration -> stmt.body?.let { walkSuperRebindStmts(it.statements, source, fileName, rebound = true) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        is Constructor -> member.body
                        is ClassStaticBlockDeclaration -> member.body
                        else -> null
                    }
                    // Direct level of class member body is NOT a rebinding scope —
                    // super is valid for derived classes (TS2335 fires for non-derived,
                    // separately). Walk into nested constructs which MAY rebind.
                    body?.let { walkSuperRebindStmts(it.statements, source, fileName, rebound = false) }
                    if (member is PropertyDeclaration) {
                        // Property initializers run in constructor scope — not rebinding.
                        member.initializer?.let { walkSuperRebindExpr(it, source, fileName, rebound = false) }
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkSuperRebindStmts(body.statements, source, fileName, rebound)
            }
            is ForInStatement -> {
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
                walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
            }
            is ForOfStatement -> {
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
                walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
            }
            is SwitchStatement -> {
                walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        walkSuperRebindExpr(clause.expression, source, fileName, rebound)
                        clause.statements.forEach { walkSuperRebindStmt(it, source, fileName, rebound) }
                    }
                    is DefaultClause -> clause.statements.forEach { walkSuperRebindStmt(it, source, fileName, rebound) }
                    else -> {}
                }
            }
            is TryStatement -> {
                walkSuperRebindStmts(stmt.tryBlock.statements, source, fileName, rebound)
                stmt.catchClause?.block?.statements?.let { walkSuperRebindStmts(it, source, fileName, rebound) }
                stmt.finallyBlock?.statements?.let { walkSuperRebindStmts(it, source, fileName, rebound) }
            }
            is LabeledStatement -> walkSuperRebindStmt(stmt.statement, source, fileName, rebound)
            is ExportAssignment -> walkSuperRebindExpr(stmt.expression, source, fileName, rebound)
            else -> {}
        }
    }

    private fun walkSuperRebindExpr(expr: Expression, source: String, fileName: String, rebound: Boolean) {
        // Direct super reference at this position — emit if we're in a rebinding scope.
        if (isSuperIdentifier(expr) && rebound) {
            emitTS2660InRebindingScope(expr as Identifier, source, fileName)
            return
        }
        when (expr) {
            // Regular function expression body: super rebinds.
            is FunctionExpression -> walkSuperRebindStmts(expr.body.statements, source, fileName, rebound = true)
            // Arrow body: preserve outer rebinding state.
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> walkSuperRebindStmts(body.statements, source, fileName, rebound)
                is Expression -> walkSuperRebindExpr(body, source, fileName, rebound)
                else -> {}
            }
            // Object literals are owned by checkSuperInObjectLiterals (17.99/17.101) for
            // direct super refs in their members. Skip entirely to avoid double emission.
            is ObjectLiteralExpression -> {}
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkSuperRebindExpr(cur, source, fileName, rebound)
                while (rightStack.isNotEmpty()) walkSuperRebindExpr(rightStack.removeLast(), source, fileName, rebound)
            }
            is CallExpression -> {
                // `super(...)` call is TS2337 territory (handled by checkIllegalSuperCallsInNestedFunctions
                // and similar). Don't emit TS2660 for super-as-callee here.
                if (!isSuperIdentifier(expr.expression)) walkSuperRebindExpr(expr.expression, source, fileName, rebound)
                expr.arguments.forEach { walkSuperRebindExpr(it, source, fileName, rebound) }
            }
            is NewExpression -> {
                walkSuperRebindExpr(expr.expression, source, fileName, rebound)
                expr.arguments?.forEach { walkSuperRebindExpr(it, source, fileName, rebound) }
            }
            is PropertyAccessExpression -> {
                if (!isSuperIdentifier(expr.expression)) walkSuperRebindExpr(expr.expression, source, fileName, rebound)
                else if (rebound) emitTS2660InRebindingScope(expr.expression as Identifier, source, fileName)
            }
            is ElementAccessExpression -> {
                if (!isSuperIdentifier(expr.expression)) walkSuperRebindExpr(expr.expression, source, fileName, rebound)
                else if (rebound) emitTS2660InRebindingScope(expr.expression as Identifier, source, fileName)
                walkSuperRebindExpr(expr.argumentExpression, source, fileName, rebound)
            }
            is ParenthesizedExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is ConditionalExpression -> {
                walkSuperRebindExpr(expr.condition, source, fileName, rebound)
                walkSuperRebindExpr(expr.whenTrue, source, fileName, rebound)
                walkSuperRebindExpr(expr.whenFalse, source, fileName, rebound)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkSuperRebindExpr(it, source, fileName, rebound) }
            is PrefixUnaryExpression -> walkSuperRebindExpr(expr.operand, source, fileName, rebound)
            is PostfixUnaryExpression -> walkSuperRebindExpr(expr.operand, source, fileName, rebound)
            is AsExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is TypeAssertionExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is SatisfiesExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is NonNullExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is SpreadElement -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is AwaitExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is YieldExpression -> expr.expression?.let { walkSuperRebindExpr(it, source, fileName, rebound) }
            is VoidExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is DeleteExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is TypeOfExpression -> walkSuperRebindExpr(expr.expression, source, fileName, rebound)
            is TemplateExpression -> for (span in expr.templateSpans) walkSuperRebindExpr(span.expression, source, fileName, rebound)
            is TaggedTemplateExpression -> {
                walkSuperRebindExpr(expr.tag, source, fileName, rebound)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkSuperRebindExpr(span.expression, source, fileName, rebound)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkSuperRebindExpr(e, source, fileName, rebound)
            else -> {}
        }
    }

    private fun emitTS2660InRebindingScope(superRef: Identifier, source: String, fileName: String) {
        val start = superRef.pos
        val length = 5
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'super' can only be referenced in members of derived classes or object literal expressions.",
            category = DiagnosticCategory.Error,
            code = 2660,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2715: Abstract property access in constructor
    // -----------------------------------------------------------------------

    /** Walks every file looking for `this.X` references inside constructor bodies
     * or class-field initializers, where X is an abstract member of the surrounding
     * class. Nested function/arrow bodies are skipped (their `this` use is deferred,
     * so the abstract member has been initialized by then). */
    private fun checkAbstractMemberAccessInConstructor() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val classMap = buildClassDeclarationMap(result.sourceFile.statements)
            walkClassesForAbstractAccess(result.sourceFile.statements, source, fileName, classMap)
        }
    }

    private fun buildClassDeclarationMap(stmts: List<Statement>): Map<String, ClassDeclaration> {
        val map = mutableMapOf<String, ClassDeclaration>()
        fun walk(stmts: List<Statement>) {
            for (stmt in stmts) {
                when (stmt) {
                    is ClassDeclaration -> stmt.name?.let { map[it.text] = stmt }
                    is ModuleDeclaration -> {
                        val body = stmt.body
                        if (body is ModuleBlock) walk(body.statements)
                    }
                    is Block -> walk(stmt.statements)
                    is FunctionDeclaration -> stmt.body?.let { walk(it.statements) }
                    else -> {}
                }
            }
        }
        walk(stmts)
        return map
    }

    /**
     * Returns a map of abstract property name → declaring class name.
     * Includes own abstract properties and inherited abstract properties (recursively),
     * minus those concretely declared in this class.
     */
    private fun collectAbstractPropertyNames(
        cls: ClassDeclaration,
        classMap: Map<String, ClassDeclaration>,
        visited: MutableSet<String> = mutableSetOf(),
    ): Map<String, String> {
        val result = mutableMapOf<String, String>()
        val ownClassName = cls.name?.text ?: "<anonymous>"
        // Own abstract properties.
        for (member in cls.members) {
            if (member !is PropertyDeclaration) continue
            if (ModifierFlag.Abstract !in member.modifiers) continue
            getMemberName(member.name)?.let { result[it] = ownClassName }
        }
        // Inherited abstract properties from base class, minus those concretely shadowed in this class.
        val baseName = cls.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression
            ?.let { (it as? Identifier)?.text }
        if (baseName != null && baseName !in visited) {
            visited.add(baseName)
            classMap[baseName]?.let { base ->
                val inherited = collectAbstractPropertyNames(base, classMap, visited).toMutableMap()
                // Remove names concretely declared in cls (any kind: PropertyDeclaration without abstract,
                // MethodDeclaration, GetAccessor, SetAccessor) — those override the inherited abstract.
                for (member in cls.members) {
                    val (name, isAbstract) = when (member) {
                        is PropertyDeclaration -> getMemberName(member.name) to (ModifierFlag.Abstract in member.modifiers)
                        is MethodDeclaration -> getMemberName(member.name) to (ModifierFlag.Abstract in member.modifiers)
                        is GetAccessor -> getMemberName(member.name) to (ModifierFlag.Abstract in member.modifiers)
                        is SetAccessor -> getMemberName(member.name) to (ModifierFlag.Abstract in member.modifiers)
                        else -> null to true
                    }
                    if (name != null && !isAbstract) inherited.remove(name)
                }
                // Inherited entries do NOT overwrite own — own takes precedence (re-declared abstract uses cls's name).
                for ((k, v) in inherited) if (k !in result) result[k] = v
            }
        }
        return result
    }

    private fun walkClassesForAbstractAccess(
        stmts: List<Statement>,
        source: String,
        fileName: String,
        classMap: Map<String, ClassDeclaration>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val abstractMap = collectAbstractPropertyNames(stmt, classMap)
                    processClassForAbstractAccess(stmt.members, stmt.name?.text, abstractMap, source, fileName, classMap)
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val init = decl.initializer ?: continue
                        if (init is ClassExpression) {
                            val nameOverride = init.name?.text
                                ?: (decl.name as? Identifier)?.text
                            // ClassExpression — own abstract names only (no parent map for inheritance through identifier).
                            val abstractMap = mutableMapOf<String, String>()
                            val effectiveName = nameOverride ?: "<class>"
                            for (member in init.members) {
                                if (member is PropertyDeclaration && ModifierFlag.Abstract in member.modifiers) {
                                    getMemberName(member.name)?.let { abstractMap[it] = effectiveName }
                                }
                            }
                            processClassForAbstractAccess(init.members, nameOverride, abstractMap, source, fileName, classMap)
                        } else {
                            walkExprForNestedClasses(init, source, fileName, classMap)
                        }
                    }
                }
                is ExpressionStatement -> walkExprForNestedClasses(stmt.expression, source, fileName, classMap)
                is FunctionDeclaration -> stmt.body?.let { walkClassesForAbstractAccess(it.statements, source, fileName, classMap) }
                is Block -> walkClassesForAbstractAccess(stmt.statements, source, fileName, classMap)
                is IfStatement -> {
                    walkClassesForAbstractAccess(listOf(stmt.thenStatement), source, fileName, classMap)
                    stmt.elseStatement?.let { walkClassesForAbstractAccess(listOf(it), source, fileName, classMap) }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkClassesForAbstractAccess(body.statements, source, fileName, classMap)
                }
                is ReturnStatement -> stmt.expression?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                is ForStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is ForInStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is ForOfStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is WhileStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is DoStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is SwitchStatement -> {
                    walkExprForNestedClasses(stmt.expression, source, fileName, classMap)
                    for (clause in stmt.caseBlock) {
                        val clauseStmts = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkClassesForAbstractAccess(clauseStmts, source, fileName, classMap)
                    }
                }
                is TryStatement -> {
                    walkClassesForAbstractAccess(stmt.tryBlock.statements, source, fileName, classMap)
                    stmt.catchClause?.let { walkClassesForAbstractAccess(it.block.statements, source, fileName, classMap) }
                    stmt.finallyBlock?.let { walkClassesForAbstractAccess(it.statements, source, fileName, classMap) }
                }
                is LabeledStatement -> walkClassesForAbstractAccess(listOf(stmt.statement), source, fileName, classMap)
                is ThrowStatement -> stmt.expression?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                is ExportAssignment -> walkExprForNestedClasses(stmt.expression, source, fileName, classMap)
                else -> {}
            }
        }
    }

    private fun walkExprForNestedClasses(expr: Expression, source: String, fileName: String, classMap: Map<String, ClassDeclaration>) {
        when (expr) {
            is ClassExpression -> {
                val abstractMap = mutableMapOf<String, String>()
                val effectiveName = expr.name?.text ?: "<class>"
                for (member in expr.members) {
                    if (member is PropertyDeclaration && ModifierFlag.Abstract in member.modifiers) {
                        getMemberName(member.name)?.let { abstractMap[it] = effectiveName }
                    }
                }
                processClassForAbstractAccess(expr.members, expr.name?.text, abstractMap, source, fileName, classMap)
            }
            is ParenthesizedExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkExprForNestedClasses(cur, source, fileName, classMap)
                while (rightStack.isNotEmpty()) walkExprForNestedClasses(rightStack.removeLast(), source, fileName, classMap)
            }
            is CallExpression -> {
                walkExprForNestedClasses(expr.expression, source, fileName, classMap)
                expr.arguments.forEach { walkExprForNestedClasses(it, source, fileName, classMap) }
            }
            is NewExpression -> {
                walkExprForNestedClasses(expr.expression, source, fileName, classMap)
                expr.arguments?.forEach { walkExprForNestedClasses(it, source, fileName, classMap) }
            }
            is AsExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is TypeAssertionExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is SatisfiesExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is NonNullExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is ConditionalExpression -> {
                walkExprForNestedClasses(expr.condition, source, fileName, classMap)
                walkExprForNestedClasses(expr.whenTrue, source, fileName, classMap)
                walkExprForNestedClasses(expr.whenFalse, source, fileName, classMap)
            }
            is PropertyAccessExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is ElementAccessExpression -> {
                walkExprForNestedClasses(expr.expression, source, fileName, classMap)
                walkExprForNestedClasses(expr.argumentExpression, source, fileName, classMap)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForNestedClasses(it, source, fileName, classMap) }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> walkExprForNestedClasses(prop.initializer, source, fileName, classMap)
                    is SpreadAssignment -> walkExprForNestedClasses(prop.expression, source, fileName, classMap)
                    else -> {}
                }
            }
            is SpreadElement -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is PrefixUnaryExpression -> walkExprForNestedClasses(expr.operand, source, fileName, classMap)
            is PostfixUnaryExpression -> walkExprForNestedClasses(expr.operand, source, fileName, classMap)
            is AwaitExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is YieldExpression -> expr.expression?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
            is VoidExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is DeleteExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is TypeOfExpression -> walkExprForNestedClasses(expr.expression, source, fileName, classMap)
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForNestedClasses(it.expression, source, fileName, classMap) }
            is TaggedTemplateExpression -> {
                walkExprForNestedClasses(expr.tag, source, fileName, classMap)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkExprForNestedClasses(it.expression, source, fileName, classMap)
                }
            }
            is CommaListExpression -> expr.elements.forEach { walkExprForNestedClasses(it, source, fileName, classMap) }
            // round 43 iter16: function-like body recursion so `() => class C {...}` and
            // `function() { return class C {...} }` reach nested ClassExpression.
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> body.statements.forEach { stmt ->
                    if (stmt is ExpressionStatement) walkExprForNestedClasses(stmt.expression, source, fileName, classMap)
                    else if (stmt is ReturnStatement) stmt.expression?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                    else if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                    }
                }
                is Expression -> walkExprForNestedClasses(body, source, fileName, classMap)
                else -> {}
            }
            is FunctionExpression -> for (stmt in expr.body.statements) {
                if (stmt is ExpressionStatement) walkExprForNestedClasses(stmt.expression, source, fileName, classMap)
                else if (stmt is ReturnStatement) stmt.expression?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                else if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { walkExprForNestedClasses(it, source, fileName, classMap) }
                }
            }
            else -> {}
        }
    }

    private fun processClassForAbstractAccess(
        members: List<ClassElement>,
        className: String?,
        abstractMap: Map<String, String>,
        source: String,
        fileName: String,
        classMap: Map<String, ClassDeclaration>,
    ) {
        // Recurse into nested classes inside member bodies (always, regardless of abstractMap).
        for (member in members) {
            val body = when (member) {
                is MethodDeclaration -> member.body
                is GetAccessor -> member.body
                is SetAccessor -> member.body
                is Constructor -> member.body
                is ClassStaticBlockDeclaration -> member.body
                else -> null
            }
            body?.let { walkClassesForAbstractAccess(it.statements, source, fileName, classMap) }
        }

        if (abstractMap.isEmpty() || className == null) return

        // Walk constructor body for `this.X` accesses.
        for (member in members) {
            if (member is Constructor) {
                member.body?.let {
                    findAbstractAccessInStmts(it.statements, source, fileName, abstractMap, className, inDeferredFn = false)
                }
            }
        }
        // Walk non-abstract field initializers for `this.X` accesses.
        for (member in members) {
            if (member !is PropertyDeclaration) continue
            if (ModifierFlag.Abstract in member.modifiers) continue
            if (ModifierFlag.Static in member.modifiers) continue
            val init = member.initializer ?: continue
            findAbstractAccessInExpr(init, source, fileName, abstractMap, className, inDeferredFn = false)
        }
    }

    private fun findAbstractAccessInStmts(
        stmts: List<Statement>,
        source: String,
        fileName: String,
        abstractMap: Map<String, String>,
        className: String,
        inDeferredFn: Boolean,
    ) {
        for (stmt in stmts) findAbstractAccessInStmt(stmt, source, fileName, abstractMap, className, inDeferredFn)
    }

    private fun findAbstractAccessInStmt(
        stmt: Statement,
        source: String,
        fileName: String,
        abstractMap: Map<String, String>,
        className: String,
        inDeferredFn: Boolean,
    ) {
        when (stmt) {
            is ExpressionStatement -> findAbstractAccessInExpr(stmt.expression, source, fileName, abstractMap, className, inDeferredFn)
            is VariableStatement -> stmt.declarationList.declarations.forEach { decl ->
                // Destructuring `let { x, y } = this` (only when initializer is `this`).
                val name = decl.name
                val init = decl.initializer
                if (!inDeferredFn && name is ObjectBindingPattern && init is Identifier && init.text == "this") {
                    for (element in name.elements) {
                        emitTS2715ForBindingElement(element, source, fileName, abstractMap, className)
                    }
                }
                init?.let { i -> findAbstractAccessInExpr(i, source, fileName, abstractMap, className, inDeferredFn) }
            }
            is ReturnStatement -> stmt.expression?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            is IfStatement -> {
                findAbstractAccessInExpr(stmt.expression, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInStmt(stmt.thenStatement, source, fileName, abstractMap, className, inDeferredFn)
                stmt.elseStatement?.let { findAbstractAccessInStmt(it, source, fileName, abstractMap, className, inDeferredFn) }
            }
            is Block -> findAbstractAccessInStmts(stmt.statements, source, fileName, abstractMap, className, inDeferredFn)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
                stmt.condition?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
                stmt.incrementor?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
                findAbstractAccessInStmt(stmt.statement, source, fileName, abstractMap, className, inDeferredFn)
            }
            is WhileStatement -> {
                findAbstractAccessInExpr(stmt.expression, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInStmt(stmt.statement, source, fileName, abstractMap, className, inDeferredFn)
            }
            is DoStatement -> {
                findAbstractAccessInStmt(stmt.statement, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInExpr(stmt.expression, source, fileName, abstractMap, className, inDeferredFn)
            }
            is ThrowStatement -> stmt.expression?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            is SwitchStatement -> {
                findAbstractAccessInExpr(stmt.expression, source, fileName, abstractMap, className, inDeferredFn)
                stmt.caseBlock.forEach { clause ->
                    when (clause) {
                        is CaseClause -> {
                            findAbstractAccessInExpr(clause.expression, source, fileName, abstractMap, className, inDeferredFn)
                            findAbstractAccessInStmts(clause.statements, source, fileName, abstractMap, className, inDeferredFn)
                        }
                        is DefaultClause -> findAbstractAccessInStmts(clause.statements, source, fileName, abstractMap, className, inDeferredFn)
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    private fun findAbstractAccessInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        abstractMap: Map<String, String>,
        className: String,
        inDeferredFn: Boolean,
    ) {
        when (expr) {
            is PropertyAccessExpression -> {
                val recv = expr.expression
                if (!inDeferredFn && recv is Identifier && recv.text == "this") {
                    abstractMap[expr.name.text]?.let { emitTS2715(expr.name, source, fileName, it) }
                }
                // Always recurse into receiver (chained access like `this.prop.foo`).
                findAbstractAccessInExpr(recv, source, fileName, abstractMap, className, inDeferredFn)
            }
            is ElementAccessExpression -> {
                findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInExpr(expr.argumentExpression, source, fileName, abstractMap, className, inDeferredFn)
            }
            is BinaryExpression -> {
                // Destructuring assignment `({ x, y } = this)`.
                val left = expr.left
                val right = expr.right
                if (!inDeferredFn
                    && expr.operator == SyntaxKind.Equals
                    && left is ObjectLiteralExpression
                    && right is Identifier
                    && right.text == "this"
                ) {
                    for (prop in left.properties) {
                        emitTS2715ForObjectAssignmentProp(prop, source, fileName, abstractMap, className)
                    }
                } else {
                    findAbstractAccessInExpr(expr.left, source, fileName, abstractMap, className, inDeferredFn)
                    findAbstractAccessInExpr(expr.right, source, fileName, abstractMap, className, inDeferredFn)
                }
            }
            is CallExpression -> {
                findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
                expr.arguments.forEach { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            }
            is NewExpression -> {
                findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
                expr.arguments?.forEach { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            }
            is ParenthesizedExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is ConditionalExpression -> {
                findAbstractAccessInExpr(expr.condition, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInExpr(expr.whenTrue, source, fileName, abstractMap, className, inDeferredFn)
                findAbstractAccessInExpr(expr.whenFalse, source, fileName, abstractMap, className, inDeferredFn)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            is PrefixUnaryExpression -> findAbstractAccessInExpr(expr.operand, source, fileName, abstractMap, className, inDeferredFn)
            is PostfixUnaryExpression -> findAbstractAccessInExpr(expr.operand, source, fileName, abstractMap, className, inDeferredFn)
            is SpreadElement -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is TaggedTemplateExpression -> {
                findAbstractAccessInExpr(expr.tag, source, fileName, abstractMap, className, inDeferredFn)
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { findAbstractAccessInExpr(it.expression, source, fileName, abstractMap, className, inDeferredFn) }
            }
            is FunctionExpression -> {
                // Nested function rebinds this; descend with inDeferredFn=true so `this.X` accesses inside don't fire.
                findAbstractAccessInStmts(expr.body.statements, source, fileName, abstractMap, className, inDeferredFn = true)
            }
            is ArrowFunction -> {
                // Arrow body deferred — `this` access inside is OK (initializer runs later).
                val body = expr.body
                if (body is Block) findAbstractAccessInStmts(body.statements, source, fileName, abstractMap, className, inDeferredFn = true)
                else if (body is Expression) findAbstractAccessInExpr(body, source, fileName, abstractMap, className, inDeferredFn = true)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> findAbstractAccessInExpr(prop.initializer, source, fileName, abstractMap, className, inDeferredFn)
                        is SpreadAssignment -> findAbstractAccessInExpr(prop.expression, source, fileName, abstractMap, className, inDeferredFn)
                        is GetAccessor -> prop.body?.let { findAbstractAccessInStmts(it.statements, source, fileName, abstractMap, className, inDeferredFn = true) }
                        is SetAccessor -> prop.body?.let { findAbstractAccessInStmts(it.statements, source, fileName, abstractMap, className, inDeferredFn = true) }
                        is MethodDeclaration -> prop.body?.let { findAbstractAccessInStmts(it.statements, source, fileName, abstractMap, className, inDeferredFn = true) }
                        else -> {}
                    }
                }
            }
            is ClassExpression -> {
                val nestedAbstract = mutableMapOf<String, String>()
                val effectiveName = expr.name?.text ?: "<class>"
                for (member in expr.members) {
                    if (member is PropertyDeclaration && ModifierFlag.Abstract in member.modifiers) {
                        getMemberName(member.name)?.let { nestedAbstract[it] = effectiveName }
                    }
                }
                processClassForAbstractAccess(expr.members, expr.name?.text, nestedAbstract, source, fileName, emptyMap())
            }
            is AsExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is TypeAssertionExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is NonNullExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is AwaitExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is YieldExpression -> expr.expression?.let { findAbstractAccessInExpr(it, source, fileName, abstractMap, className, inDeferredFn) }
            is DeleteExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is TypeOfExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            is VoidExpression -> findAbstractAccessInExpr(expr.expression, source, fileName, abstractMap, className, inDeferredFn)
            else -> {}
        }
    }

    private fun emitTS2715ForBindingElement(
        element: BindingElement,
        source: String,
        fileName: String,
        abstractMap: Map<String, String>,
        @Suppress("UNUSED_PARAMETER") className: String,
    ) {
        // Property name = propertyName ?? name (when name is Identifier shorthand).
        val keyNode: Node? = element.propertyName ?: (element.name as? Identifier)
        when (keyNode) {
            is Identifier -> abstractMap[keyNode.text]?.let { emitTS2715Generic(keyNode.pos, keyNode.text.length, keyNode.text, source, fileName, it) }
            is StringLiteralNode -> abstractMap[keyNode.text]?.let { emitTS2715Generic(keyNode.pos, (keyNode.rawText?.length ?: keyNode.text.length) + 2, keyNode.text, source, fileName, it) }
            is NumericLiteralNode -> abstractMap[keyNode.text]?.let { emitTS2715Generic(keyNode.pos, keyNode.text.length, keyNode.text, source, fileName, it) }
            else -> {}
        }
    }

    private fun emitTS2715ForObjectAssignmentProp(
        prop: Node,
        source: String,
        fileName: String,
        abstractMap: Map<String, String>,
        @Suppress("UNUSED_PARAMETER") className: String,
    ) {
        when (prop) {
            is ShorthandPropertyAssignment -> abstractMap[prop.name.text]?.let { emitTS2715Generic(prop.name.pos, prop.name.text.length, prop.name.text, source, fileName, it) }
            is PropertyAssignment -> {
                when (val n = prop.name) {
                    is Identifier -> abstractMap[n.text]?.let { emitTS2715Generic(n.pos, n.text.length, n.text, source, fileName, it) }
                    is StringLiteralNode -> abstractMap[n.text]?.let { emitTS2715Generic(n.pos, (n.rawText?.length ?: n.text.length) + 2, n.text, source, fileName, it) }
                    is NumericLiteralNode -> abstractMap[n.text]?.let { emitTS2715Generic(n.pos, n.text.length, n.text, source, fileName, it) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun emitTS2715Generic(start: Int, length: Int, propName: String, source: String, fileName: String, className: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Abstract property '$propName' in class '$className' cannot be accessed in the constructor.",
            category = DiagnosticCategory.Error,
            code = 2715,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2715(nameNode: Identifier, source: String, fileName: String, className: String) {
        val start = nameNode.pos
        val length = nameNode.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Abstract property '${nameNode.text}' in class '$className' cannot be accessed in the constructor.",
            category = DiagnosticCategory.Error,
            code = 2715,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS1253: abstract members in non-abstract class
    // TS7008: abstract property without annotation in non-ambient class
    // -----------------------------------------------------------------------

    private fun checkAbstractMemberContext() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkClassesForAbstractContext(result.sourceFile.statements, source, fileName, inAmbient = false)
        }
    }

    private fun walkClassesForAbstractContext(
        stmts: List<Statement>,
        source: String,
        fileName: String,
        inAmbient: Boolean,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val isAmbientClass = inAmbient || ModifierFlag.Declare in stmt.modifiers
                    val classIsAbstract = ModifierFlag.Abstract in stmt.modifiers
                    processClassForAbstractContext(stmt.members, classIsAbstract, isAmbientClass, source, fileName)
                    // Recurse into nested classes inside member bodies.
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            is Constructor -> member.body
                            is ClassStaticBlockDeclaration -> member.body
                            else -> null
                        }
                        body?.let { walkClassesForAbstractContext(it.statements, source, fileName, isAmbientClass) }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val init = decl.initializer ?: continue
                        walkExprForAbstractContext(init, source, fileName, inAmbient)
                    }
                }
                is ExpressionStatement -> walkExprForAbstractContext(stmt.expression, source, fileName, inAmbient)
                is FunctionDeclaration -> stmt.body?.let { walkClassesForAbstractContext(it.statements, source, fileName, inAmbient) }
                is Block -> walkClassesForAbstractContext(stmt.statements, source, fileName, inAmbient)
                is IfStatement -> {
                    walkClassesForAbstractContext(listOf(stmt.thenStatement), source, fileName, inAmbient)
                    stmt.elseStatement?.let { walkClassesForAbstractContext(listOf(it), source, fileName, inAmbient) }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    val nowAmbient = inAmbient || ModifierFlag.Declare in stmt.modifiers
                    if (body is ModuleBlock) walkClassesForAbstractContext(body.statements, source, fileName, nowAmbient)
                }
                is ReturnStatement -> stmt.expression?.let { walkExprForAbstractContext(it, source, fileName, inAmbient) }
                is ForStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is ForInStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is ForOfStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is WhileStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is DoStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is SwitchStatement -> {
                    walkExprForAbstractContext(stmt.expression, source, fileName, inAmbient)
                    for (clause in stmt.caseBlock) {
                        val clauseStmts = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkClassesForAbstractContext(clauseStmts, source, fileName, inAmbient)
                    }
                }
                is TryStatement -> {
                    walkClassesForAbstractContext(stmt.tryBlock.statements, source, fileName, inAmbient)
                    stmt.catchClause?.let { walkClassesForAbstractContext(it.block.statements, source, fileName, inAmbient) }
                    stmt.finallyBlock?.let { walkClassesForAbstractContext(it.statements, source, fileName, inAmbient) }
                }
                is LabeledStatement -> walkClassesForAbstractContext(listOf(stmt.statement), source, fileName, inAmbient)
                is ThrowStatement -> stmt.expression?.let { walkExprForAbstractContext(it, source, fileName, inAmbient) }
                is ExportAssignment -> walkExprForAbstractContext(stmt.expression, source, fileName, inAmbient)
                else -> {}
            }
        }
    }

    private fun walkExprForAbstractContext(expr: Expression, source: String, fileName: String, inAmbient: Boolean) {
        when (expr) {
            is ClassExpression -> {
                val classIsAbstract = ModifierFlag.Abstract in expr.modifiers
                processClassForAbstractContext(expr.members, classIsAbstract, inAmbient, source, fileName)
                for (member in expr.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        is Constructor -> member.body
                        is ClassStaticBlockDeclaration -> member.body
                        else -> null
                    }
                    body?.let { walkClassesForAbstractContext(it.statements, source, fileName, inAmbient) }
                }
            }
            is ParenthesizedExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkExprForAbstractContext(cur, source, fileName, inAmbient)
                while (rightStack.isNotEmpty()) walkExprForAbstractContext(rightStack.removeLast(), source, fileName, inAmbient)
            }
            is CallExpression -> {
                walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
                expr.arguments.forEach { walkExprForAbstractContext(it, source, fileName, inAmbient) }
            }
            is NewExpression -> {
                walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
                expr.arguments?.forEach { walkExprForAbstractContext(it, source, fileName, inAmbient) }
            }
            is AsExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is TypeAssertionExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is SatisfiesExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is NonNullExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is ConditionalExpression -> {
                walkExprForAbstractContext(expr.condition, source, fileName, inAmbient)
                walkExprForAbstractContext(expr.whenTrue, source, fileName, inAmbient)
                walkExprForAbstractContext(expr.whenFalse, source, fileName, inAmbient)
            }
            is PropertyAccessExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is ElementAccessExpression -> {
                walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
                walkExprForAbstractContext(expr.argumentExpression, source, fileName, inAmbient)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForAbstractContext(it, source, fileName, inAmbient) }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> walkExprForAbstractContext(prop.initializer, source, fileName, inAmbient)
                    is SpreadAssignment -> walkExprForAbstractContext(prop.expression, source, fileName, inAmbient)
                    else -> {}
                }
            }
            is SpreadElement -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is PrefixUnaryExpression -> walkExprForAbstractContext(expr.operand, source, fileName, inAmbient)
            is PostfixUnaryExpression -> walkExprForAbstractContext(expr.operand, source, fileName, inAmbient)
            is AwaitExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is YieldExpression -> expr.expression?.let { walkExprForAbstractContext(it, source, fileName, inAmbient) }
            is VoidExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is DeleteExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is TypeOfExpression -> walkExprForAbstractContext(expr.expression, source, fileName, inAmbient)
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForAbstractContext(it.expression, source, fileName, inAmbient) }
            is TaggedTemplateExpression -> {
                walkExprForAbstractContext(expr.tag, source, fileName, inAmbient)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkExprForAbstractContext(it.expression, source, fileName, inAmbient)
                }
            }
            is CommaListExpression -> expr.elements.forEach { walkExprForAbstractContext(it, source, fileName, inAmbient) }
            // round 43 iter17: function-like body recursion (mirror of iter14-16 pattern).
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> walkClassesForAbstractContext(body.statements, source, fileName, inAmbient)
                is Expression -> walkExprForAbstractContext(body, source, fileName, inAmbient)
                else -> {}
            }
            is FunctionExpression -> walkClassesForAbstractContext(expr.body.statements, source, fileName, inAmbient)
            else -> {}
        }
    }

    private fun processClassForAbstractContext(
        members: List<ClassElement>,
        classIsAbstract: Boolean,
        isAmbient: Boolean,
        source: String,
        fileName: String,
    ) {
        for (member in members) {
            val (memberModifiers, memberPos, isProperty, hasType, hasInit, memberName) = when (member) {
                is PropertyDeclaration -> AbstractMemberInfo(member.modifiers, member.pos, true, member.type != null, member.initializer != null, member.name as? Identifier)
                is MethodDeclaration -> AbstractMemberInfo(member.modifiers, member.pos, false, true, false, member.name as? Identifier)
                is GetAccessor -> AbstractMemberInfo(member.modifiers, member.pos, false, true, false, member.name as? Identifier)
                is SetAccessor -> AbstractMemberInfo(member.modifiers, member.pos, false, true, false, member.name as? Identifier)
                else -> continue
            }
            if (ModifierFlag.Abstract !in memberModifiers) continue
            // TS1244 (methods/accessors) / TS1253 (properties): abstract member in non-abstract, non-ambient class
            if (!classIsAbstract && !isAmbient) {
                emitAbstractMemberInNonAbstractClass(memberPos, isProperty, source, fileName)
            }
            // TS7008: abstract property without type annotation in non-ambient class — implicit any
            // Emits regardless of class abstractness; needs noImplicitAny/strict.
            if (isProperty && !hasType && !hasInit && !isAmbient
                && (options.noImplicitAny || options.strict)
                && memberName != null && memberName.text.isNotEmpty()) {
                val (line, character) = getLineAndCharacterOfPosition(source, memberName.pos)
                diagnostics.add(Diagnostic(
                    message = "Member '${memberName.text}' implicitly has an 'any' type.",
                    category = DiagnosticCategory.Error,
                    code = 7008,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = memberName.pos,
                    length = memberName.text.length,
                ))
            }
        }
    }

    private data class AbstractMemberInfo(
        val modifiers: Set<ModifierFlag>,
        val pos: Int,
        val isProperty: Boolean,
        val hasType: Boolean,
        val hasInit: Boolean,
        val name: Identifier?,
    )

    private fun emitAbstractMemberInNonAbstractClass(memberPos: Int, isProperty: Boolean, source: String, fileName: String) {
        // Find the 'abstract' keyword position by searching forward from memberPos.
        // The parser's pos may include leading trivia, so search up to a reasonable bound.
        val searchStart = maxOf(0, memberPos)
        val searchEnd = minOf(source.length, memberPos + 200)
        val idx = source.indexOf("abstract", searchStart)
        if (idx < 0 || idx >= searchEnd) return
        // Verify it's a complete word (not part of another identifier).
        val before = if (idx > 0) source[idx - 1] else ' '
        val after = if (idx + 8 < source.length) source[idx + 8] else ' '
        if (before.isLetterOrDigit() || before == '_' || before == '$') return
        if (after.isLetterOrDigit() || after == '_' || after == '$') return
        val (line, character) = getLineAndCharacterOfPosition(source, idx)
        // TS1244 for methods/accessors, TS1253 for properties.
        val (msg, code) = if (isProperty)
            "Abstract properties can only appear within an abstract class." to 1253
        else
            "Abstract methods can only appear within an abstract class." to 1244
        diagnostics.add(Diagnostic(
            message = msg,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = idx,
            length = 8,
        ))
    }

    // -----------------------------------------------------------------------
    // Const without initializer checking (TS1155)
    // -----------------------------------------------------------------------

    private fun checkConstWithoutInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForConstWithoutInit(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForConstWithoutInit(statements: List<Statement>, source: String, fileName: String, isAmbient: Boolean = false) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags == SyntaxKind.ConstKeyword
                        && !isAmbient && ModifierFlag.Declare !in stmt.modifiers) {
                        for (decl in stmt.declarationList.declarations) {
                            if (decl.initializer == null) {
                                // const without initializer
                                val nameNode = decl.name
                                if (nameNode is Identifier) {
                                    val start = nameNode.pos
                                    val length = nameNode.text.length
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "'const' declarations must be initialized.",
                                        category = DiagnosticCategory.Error,
                                        code = 1155,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is Constructor -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            else -> null
                        }
                        body?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                    }
                }
                is Block -> walkForConstWithoutInit(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    val childAmbient = isAmbient || ModifierFlag.Declare in stmt.modifiers
                    if (body is ModuleBlock) walkForConstWithoutInit(body.statements, source, fileName, childAmbient)
                }
                is IfStatement -> {
                    walkForConstWithoutInit(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForConstWithoutInit(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    // Check initializer for const without init: for(const c9; ...)
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.ConstKeyword) {
                        for (decl in init.declarations) {
                            if (decl.initializer == null) {
                                val nameNode = decl.name
                                if (nameNode is Identifier) {
                                    val start = nameNode.pos
                                    val length = nameNode.text.length
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "'const' declarations must be initialized.",
                                        category = DiagnosticCategory.Error,
                                        code = 1155,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                    }
                    walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                }
                is WhileStatement -> walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        val stmts = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkForConstWithoutInit(stmts, source, fileName)
                    }
                }
                is TryStatement -> {
                    walkForConstWithoutInit(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Destructuring declaration without initializer (TS1182)
    // -----------------------------------------------------------------------

    private fun checkDestructuringWithoutInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDestructuringWithoutInit(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForDestructuringWithoutInit(statements: List<Statement>, source: String, fileName: String, isAmbient: Boolean = false) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (isAmbient || ModifierFlag.Declare in stmt.modifiers) continue
                    for (decl in stmt.declarationList.declarations) {
                        emitTs1182IfMissingInit(decl, source, fileName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForDestructuringWithoutInit(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is Constructor -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            else -> null
                        }
                        body?.let { walkForDestructuringWithoutInit(it.statements, source, fileName) }
                    }
                }
                is Block -> walkForDestructuringWithoutInit(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    val childAmbient = isAmbient || ModifierFlag.Declare in stmt.modifiers
                    if (body is ModuleBlock) walkForDestructuringWithoutInit(body.statements, source, fileName, childAmbient)
                }
                is IfStatement -> {
                    walkForDestructuringWithoutInit(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForDestructuringWithoutInit(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    // for(var [a]=x;;) — check the variable declarations in init
                    val init = stmt.initializer
                    if (init is VariableDeclarationList) {
                        for (decl in init.declarations) {
                            emitTs1182IfMissingInit(decl, source, fileName)
                        }
                    }
                    walkForDestructuringWithoutInit(listOf(stmt.statement), source, fileName)
                }
                is ForOfStatement -> {
                    // for-of's initializer is the iteration variable — TS1182 does NOT apply.
                    // Only descend into the body.
                    walkForDestructuringWithoutInit(listOf(stmt.statement), source, fileName)
                }
                is ForInStatement -> {
                    // for-in's initializer is the iteration variable — TS1182 does NOT apply.
                    walkForDestructuringWithoutInit(listOf(stmt.statement), source, fileName)
                }
                is WhileStatement -> walkForDestructuringWithoutInit(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForDestructuringWithoutInit(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        val stmts = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkForDestructuringWithoutInit(stmts, source, fileName)
                    }
                }
                is TryStatement -> {
                    walkForDestructuringWithoutInit(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkForDestructuringWithoutInit(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForDestructuringWithoutInit(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    private fun emitTs1182IfMissingInit(decl: VariableDeclaration, source: String, fileName: String) {
        if (decl.initializer != null) return
        val name = decl.name
        if (name !is ObjectBindingPattern && name !is ArrayBindingPattern) return
        val start = name.pos
        val length = computeBindingPatternSpan(source, start, name)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "A destructuring declaration must have an initializer.",
            category = DiagnosticCategory.Error,
            code = 1182,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        // TS7031: Binding element implicitly has 'any' type — fires only when (a) noImplicitAny/strict,
        // (b) the VariableDeclaration has no type annotation, (c) the binding element has no default
        // initializer of its own. Mirrors TS7031 for function parameters at Checker.kt:~11178.
        if (!(options.noImplicitAny || options.strict)) return
        if (decl.type != null) return
        val elements: List<BindingElement> = when (name) {
            is ArrayBindingPattern -> name.elements.filterIsInstance<BindingElement>()
            is ObjectBindingPattern -> name.elements
            else -> emptyList()
        }
        for (elt in elements) {
            if (elt.initializer != null) continue
            val eltName = elt.name as? Identifier ?: continue
            if (eltName.text.isEmpty()) continue
            val s = eltName.pos
            val (l, c) = getLineAndCharacterOfPosition(source, s)
            diagnostics.add(Diagnostic(
                message = "Binding element '${eltName.text}' implicitly has an 'any' type.",
                category = DiagnosticCategory.Error,
                code = 7031,
                fileName = fileName,
                line = l,
                character = c,
                start = s,
                length = eltName.text.length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // Reserved word identifier checking (TS1359)
    // -----------------------------------------------------------------------

    private val reservedWords = setOf("await", "yield", "void", "delete", "typeof",
        "instanceof", "in", "of", "new", "return", "throw", "case", "switch",
        "if", "else", "for", "while", "do", "try", "catch", "finally",
        "with", "debugger", "var", "let", "const", "class", "function",
        "import", "export", "default", "extends", "implements", "enum",
        "interface", "package", "private", "protected", "public", "static")

    private fun checkReservedWordIdentifiers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForReservedWords(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForReservedWords(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (ModifierFlag.Async in stmt.modifiers) {
                        checkAwaitParams(stmt.parameters, source, fileName)
                    }
                    stmt.body?.let { walkForReservedWords(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                if (ModifierFlag.Async in member.modifiers) {
                                    checkAwaitParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            }
                            is Constructor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        when (val init = decl.initializer) {
                            is ArrowFunction -> {
                                if (ModifierFlag.Async in init.modifiers) {
                                    checkAwaitParams(init.parameters, source, fileName)
                                }
                            }
                            is FunctionExpression -> {
                                if (ModifierFlag.Async in init.modifiers) {
                                    checkAwaitParams(init.parameters, source, fileName)
                                }
                                walkForReservedWords(init.body.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ExpressionStatement -> walkForReservedWordsInExpr(stmt.expression, source, fileName)
                is Block -> walkForReservedWords(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForReservedWords(body.statements, source, fileName)
                }
                // Check enum names that are reserved words
                is EnumDeclaration -> {
                    val name = stmt.name.text
                    if (name == "void" || name == "await" || name == "yield") {
                        emitTS1359(stmt.name, source, fileName, name)
                    }
                }
                is IfStatement -> {
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                    walkForReservedWords(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForReservedWords(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    stmt.condition?.let { walkForReservedWordsInExpr(it, source, fileName) }
                    stmt.incrementor?.let { walkForReservedWordsInExpr(it, source, fileName) }
                    walkForReservedWords(listOf(stmt.statement), source, fileName)
                }
                is ForInStatement -> {
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                    walkForReservedWords(listOf(stmt.statement), source, fileName)
                }
                is ForOfStatement -> {
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                    walkForReservedWords(listOf(stmt.statement), source, fileName)
                }
                is WhileStatement -> {
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                    walkForReservedWords(listOf(stmt.statement), source, fileName)
                }
                is DoStatement -> {
                    walkForReservedWords(listOf(stmt.statement), source, fileName)
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                }
                is SwitchStatement -> {
                    walkForReservedWordsInExpr(stmt.expression, source, fileName)
                    for (clause in stmt.caseBlock) {
                        val clauseStmts = when (clause) {
                            is CaseClause -> {
                                walkForReservedWordsInExpr(clause.expression, source, fileName)
                                clause.statements
                            }
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkForReservedWords(clauseStmts, source, fileName)
                    }
                }
                is TryStatement -> {
                    walkForReservedWords(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForReservedWords(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForReservedWords(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForReservedWords(listOf(stmt.statement), source, fileName)
                is ThrowStatement -> stmt.expression?.let { walkForReservedWordsInExpr(it, source, fileName) }
                is ReturnStatement -> stmt.expression?.let { walkForReservedWordsInExpr(it, source, fileName) }
                is ExportAssignment -> walkForReservedWordsInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun walkForReservedWordsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                if (ModifierFlag.Async in expr.modifiers) {
                    checkAwaitParams(expr.parameters, source, fileName)
                }
                when (val body = expr.body) {
                    is Block -> walkForReservedWords(body.statements, source, fileName)
                    is Expression -> walkForReservedWordsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                if (ModifierFlag.Async in expr.modifiers) {
                    checkAwaitParams(expr.parameters, source, fileName)
                }
                walkForReservedWords(expr.body.statements, source, fileName)
            }
            is ClassExpression -> for (member in expr.members) when (member) {
                is MethodDeclaration -> {
                    if (ModifierFlag.Async in member.modifiers) checkAwaitParams(member.parameters, source, fileName)
                    member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                }
                is Constructor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                is GetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                is SetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                is PropertyDeclaration -> member.initializer?.let { walkForReservedWordsInExpr(it, source, fileName) }
                else -> {}
            }
            is BinaryExpression -> {
                var current: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (current is BinaryExpression) { rightStack.addLast(current.right); current = current.left }
                walkForReservedWordsInExpr(current, source, fileName)
                while (rightStack.isNotEmpty()) walkForReservedWordsInExpr(rightStack.removeLast(), source, fileName)
            }
            is ParenthesizedExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is AsExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                walkForReservedWordsInExpr(expr.condition, source, fileName)
                walkForReservedWordsInExpr(expr.whenTrue, source, fileName)
                walkForReservedWordsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkForReservedWordsInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { walkForReservedWordsInExpr(it, source, fileName) }
            }
            is NewExpression -> {
                walkForReservedWordsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkForReservedWordsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkForReservedWordsInExpr(expr.expression, source, fileName)
                walkForReservedWordsInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) walkForReservedWordsInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> walkForReservedWordsInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> walkForReservedWordsInExpr(p.expression, source, fileName)
                is MethodDeclaration -> {
                    if (ModifierFlag.Async in p.modifiers) checkAwaitParams(p.parameters, source, fileName)
                    p.body?.let { walkForReservedWords(it.statements, source, fileName) }
                }
                is GetAccessor -> p.body?.let { walkForReservedWords(it.statements, source, fileName) }
                is SetAccessor -> p.body?.let { walkForReservedWords(it.statements, source, fileName) }
                else -> {}
            }
            is SpreadElement -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkForReservedWordsInExpr(it, source, fileName) }
            is VoidExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkForReservedWordsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkForReservedWordsInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkForReservedWordsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkForReservedWordsInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkForReservedWordsInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkForReservedWordsInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun checkAwaitParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            val name = param.name
            if (name is Identifier && name.text == "await") {
                emitTS1359(name, source, fileName, "await")
            }
        }
    }

    private fun emitTS1359(nameNode: Identifier, source: String, fileName: String, word: String) {
        val start = nameNode.pos
        val length = word.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Identifier expected. '$word' is a reserved word that cannot be used here.",
            category = DiagnosticCategory.Error,
            code = 1359,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // TS6131: Cannot compile modules using option 'outFile' unless '--module' is 'amd' or 'system'
    // Only emitted when module kind is NOT explicitly set (defaulted from target).
    // When module is explicitly set, TS6082 handles the conflict at the configuration level.
    private fun checkOutFileModuleConflict() {
        if (options.outFile == null) return
        // When 'out' is set (removed option), TS5102 handles it — don't add TS6131
        if (options.out != null) return
        // When module is explicitly set, TS6082 handles it (from TypeScriptCompiler.kt)
        if (options.module != null) return
        val effectiveModule = options.effectiveModule
        if (effectiveModule == ModuleKind.AMD || effectiveModule == ModuleKind.System
            || effectiveModule == ModuleKind.UMD) return
        if (effectiveModule == ModuleKind.None) return

        // TypeScript emits TS6131 only once per compilation (first eligible file with exports)
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            // Find the first export module statement (not import-only)
            val firstExportStmt = findFirstExportStatement(result.sourceFile.statements)
                ?: continue

            // Determine diagnostic span based on statement type
            val (spanStart, spanLength) = getModuleStatementSpan(firstExportStmt, source)
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Cannot compile modules using option 'outFile' unless the '--module' flag is 'amd' or 'system'.",
                category = DiagnosticCategory.Error,
                code = 6131,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLength,
            ))
            break // Only emit once per compilation
        }
    }

    /** Find the first export statement (not import-only). Used for TS6131 which fires only on exports. */
    private fun findFirstExportStatement(statements: List<Statement>): Statement? {
        for (stmt in statements) {
            when (stmt) {
                is ExportDeclaration -> return stmt
                is ExportAssignment -> return stmt
                else -> {
                    val modifiers = when (stmt) {
                        is FunctionDeclaration -> stmt.modifiers
                        is ClassDeclaration -> stmt.modifiers
                        is VariableStatement -> stmt.modifiers
                        is EnumDeclaration -> stmt.modifiers
                        is InterfaceDeclaration -> stmt.modifiers
                        is TypeAliasDeclaration -> stmt.modifiers
                        is ModuleDeclaration -> stmt.modifiers
                        else -> emptySet()
                    }
                    if (ModifierFlag.Export in modifiers) return stmt
                }
            }
        }
        return null
    }

    private fun findFirstModuleStatement(statements: List<Statement>): Statement? {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return stmt
                is ImportEqualsDeclaration -> return stmt
                is ExportDeclaration -> return stmt
                is ExportAssignment -> return stmt
                else -> {
                    val modifiers = when (stmt) {
                        is FunctionDeclaration -> stmt.modifiers
                        is ClassDeclaration -> stmt.modifiers
                        is VariableStatement -> stmt.modifiers
                        is EnumDeclaration -> stmt.modifiers
                        is InterfaceDeclaration -> stmt.modifiers
                        is TypeAliasDeclaration -> stmt.modifiers
                        is ModuleDeclaration -> stmt.modifiers
                        else -> emptySet()
                    }
                    if (ModifierFlag.Export in modifiers) return stmt
                }
            }
        }
        return null
    }

    /**
     * Get the diagnostic span for a module statement.
     * For class/function/enum/interface: span covers the name identifier.
     * For variable statements and imports: span covers the entire statement including export keyword.
     */
    /** Get text span for a statement, stopping at semicolon or end of text content (before comments). */
    private fun getStatementTextSpan(stmt: Statement, source: String): Pair<Int, Int> {
        var start = stmt.pos
        // Skip leading whitespace
        while (start < source.length && source[start] in " \t\r\n") start++
        // Find end: stop at semicolon or comment start
        val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
        var end = start
        var i = start
        while (i < lineEnd) {
            val ch = source[i]
            if (ch == ';') {
                end = i + 1
                break
            }
            if (ch == '/' && i + 1 < lineEnd && (source[i + 1] == '/' || source[i + 1] == '*')) {
                // Comment starts — end before it, trim trailing whitespace
                while (end > start && source[end - 1] in " \t") end--
                break
            }
            end = i + 1
            i++
        }
        return Pair(start, (end - start).coerceAtLeast(1))
    }

    private fun getModuleStatementSpan(stmt: Statement, source: String): Pair<Int, Int> {
        // For class/function declarations, use the name identifier position
        when (stmt) {
            is ClassDeclaration -> stmt.name?.let {
                return Pair(it.pos, it.text.length)
            }
            is FunctionDeclaration -> stmt.name?.let {
                return Pair(it.pos, it.text.length)
            }
            is EnumDeclaration -> {
                return Pair(stmt.name.pos, stmt.name.text.length)
            }
            is InterfaceDeclaration -> {
                return Pair(stmt.name.pos, stmt.name.text.length)
            }
            else -> {}
        }
        // For everything else (export var, import, export =, etc.), use the full statement span.
        // The statement pos may start after the 'export' keyword, so search backwards for it.
        var start = stmt.pos
        if (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) {
            // Find the 'export' keyword before the var/let/const keyword
            var p = start - 1
            while (p >= 0 && source[p] in " \t\r\n") p--
            // p should now be at the 't' of 'export'
            if (p >= 5 && source.substring(p - 5, p + 1) == "export") {
                start = p - 5
            }
        }
        // Find the end of actual content (before trailing whitespace/newline)
        var end = stmt.end
        while (end > start && end - 1 < source.length && source[end - 1] in " \t\r\n") end--
        return Pair(start, (end - start).coerceAtLeast(1))
    }

    // TS1185: Merge conflict marker encountered
    private fun checkConflictMarkers() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            // Scan for conflict markers at the start of lines
            var i = 0
            while (i < source.length) {
                // Check if we're at the start of a line (position 0 or preceded by newline)
                if (i == 0 || source[i - 1] == '\n') {
                    val ch = source[i]
                    val isMarker = when (ch) {
                        '<' -> i + 6 < source.length && source.substring(i, i + 7) == "<<<<<<<"
                        '=' -> i + 6 < source.length && source.substring(i, i + 7) == "======="
                        '>' -> i + 6 < source.length && source.substring(i, i + 7) == ">>>>>>>"
                        '|' -> i + 6 < source.length && source.substring(i, i + 7) == "|||||||"
                        else -> false
                    }
                    if (isMarker) {
                        val (line, character) = getLineAndCharacterOfPosition(source, i)
                        diagnostics.add(Diagnostic(
                            message = "Merge conflict marker encountered.",
                            category = DiagnosticCategory.Error,
                            code = 1185,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = i,
                            length = 7,
                        ))
                    }
                }
                i++
            }
        }
    }

    // TS1148: Cannot use imports, exports, or module augmentations when '--module' is 'none'
    // Only fires for pre-ES2015 targets — ES2015+ supports module syntax natively
    private fun checkModuleNoneConflict() {
        if (options.module != ModuleKind.None) return
        if (options.target >= ScriptTarget.ES2015) return

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            val firstModuleStmt = findFirstModuleStatement(result.sourceFile.statements)
                ?: continue

            val (spanStart, spanLength) = getModuleStatementSpan(firstModuleStmt, source)
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Cannot use imports, exports, or module augmentations when '--module' is 'none'.",
                category = DiagnosticCategory.Error,
                code = 1148,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLength,
            ))
        }
    }

    // TS1218: Export assignment is not supported when '--module' flag is 'system'
    private fun checkExportAssignmentInSystem() {
        if (options.effectiveModule != ModuleKind.System) return

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ExportAssignment && stmt.isExportEquals) {
                    // Span covers just `export = expr;` (skip comments/trailing whitespace)
                    val (spanStart, spanLength) = getStatementTextSpan(stmt, source)
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "Export assignment is not supported when '--module' flag is 'system'.",
                        category = DiagnosticCategory.Error,
                        code = 1218,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = spanLength,
                    ))
                }
            }
        }
    }

    // TS2441: Duplicate identifier 'exports'/'require'. Compiler reserves name in top level scope.
    // Applies to CJS/AMD/UMD/System module formats where exports/require are runtime variables.
    private fun checkReservedModuleNames() {
        // Skip when no emit (no runtime conflict possible)
        if (options.noEmit) return
        val module = options.effectiveModule
        // Only applies to module formats that use exports/require at runtime
        if (module != ModuleKind.CommonJS && module != ModuleKind.AMD
            && module != ModuleKind.UMD && module != ModuleKind.System) return

        val reservedNames = setOf("exports", "require")

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue

            for (stmt in result.sourceFile.statements) {
                // Check top-level function/class/enum/variable declarations
                // Skip ambient (declare) declarations — they don't conflict at runtime
                val names = mutableListOf<Identifier>()
                when (stmt) {
                    is FunctionDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) stmt.name?.let { names.add(it) }
                    }
                    is ClassDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) stmt.name?.let { names.add(it) }
                    }
                    is EnumDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) names.add(stmt.name)
                    }
                    is VariableStatement -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) {
                            for (decl in stmt.declarationList.declarations) {
                                val n = decl.name
                                if (n is Identifier) names.add(n)
                            }
                        }
                    }
                    is ImportEqualsDeclaration -> {
                        // import exports = m.c; import require = m.c;
                        names.add(stmt.name)
                    }
                    is ModuleDeclaration -> {
                        // export namespace exports {} / export namespace require {}
                        // Skip uninstantiated namespaces (only types/interfaces) — no runtime conflict
                        if (ModifierFlag.Declare !in stmt.modifiers && stmt.name is Identifier
                            && isNamespaceInstantiated(stmt)) names.add(stmt.name as Identifier)
                    }
                    else -> {}
                }
                for (name in names) {
                    if (name.text in reservedNames) {
                        val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Duplicate identifier '${name.text}'. Compiler reserves name '${name.text}' in top level scope of a module.",
                            category = DiagnosticCategory.Error,
                            code = 2441,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                        ))
                    }
                }
            }
        }
    }

    // TS1216: __esModule is reserved as an exported marker when transforming ECMAScript modules
    private fun checkEsModuleReservedExport() {
        if (options.noEmit) return
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier && name.text == "__esModule") {
                            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                            diagnostics.add(Diagnostic(
                                message = "Identifier expected. '__esModule' is reserved as an exported marker when transforming ECMAScript modules.",
                                category = DiagnosticCategory.Error,
                                code = 1216,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = name.pos,
                                length = name.text.length,
                            ))
                        }
                    }
                }
            }
        }
    }

    // TS18028: Private identifiers are only available when targeting ES2015+
    private fun checkPrivateIdentifiersTarget() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkPrivateIdentifiersInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkPrivateIdentifiersInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkPrivateIdentifiersInClass(stmt.members, source, fileName)
                    // Recurse into class member bodies for nested classes
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                            is Constructor -> m.body?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                            is GetAccessor -> m.body?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                            is SetAccessor -> m.body?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                            is PropertyDeclaration -> {
                                val init = m.initializer
                                if (init is ClassExpression) checkPrivateIdentifiersInClass(init.members, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ExpressionStatement -> {
                    val expr = stmt.expression
                    if (expr is ClassExpression) checkPrivateIdentifiersInClass(expr.members, source, fileName)
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val init = decl.initializer
                        if (init is ClassExpression) checkPrivateIdentifiersInClass(init.members, source, fileName)
                    }
                }
                is Block -> checkPrivateIdentifiersInStatements(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) checkPrivateIdentifiersInStatements(body.statements, source, fileName)
                }
                is FunctionDeclaration -> stmt.body?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                is IfStatement -> {
                    checkPrivateIdentifiersInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkPrivateIdentifiersInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkPrivateIdentifiersInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkPrivateIdentifiersInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkPrivateIdentifiersInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkPrivateIdentifiersInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkPrivateIdentifiersInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkPrivateIdentifiersInClass(members: List<ClassElement>, source: String, fileName: String) {
        for (member in members) {
            val name = when (member) {
                is PropertyDeclaration -> member.name as? Identifier
                is MethodDeclaration -> member.name as? Identifier
                is GetAccessor -> member.name as? Identifier
                is SetAccessor -> member.name as? Identifier
                else -> null
            } ?: continue
            if (!name.text.startsWith("#")) continue
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Private identifiers are only available when targeting ECMAScript 2015 and higher.",
                category = DiagnosticCategory.Error,
                code = 18028,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = name.text.length,
            ))
        }
    }

    // TS1250: Function declarations not allowed inside blocks in strict mode targeting ES5
    // TypeScript fires this for target < ES2015 (raw target, not effective) regardless of
    // explicit strict mode — block-scoped functions are undefined behavior in ES5.
    private fun checkBlockScopedFunctionDeclarations() {
        if (options.target > ScriptTarget.ES5) return
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName

            checkBlockFuncDeclInStatements(result.sourceFile.statements, source, fileName, inBlock = false, inClassMethod = false)
        }
    }

    private fun checkBlockFuncDeclInStatements(
        statements: List<Statement>, source: String, fileName: String, inBlock: Boolean, inClassMethod: Boolean
    ) {
        for (stmt in statements) {
            if (inBlock && stmt is FunctionDeclaration) {
                val name = stmt.name ?: continue
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                val (code, message) = if (inClassMethod) {
                    1251 to "Function declarations are not allowed inside blocks in strict mode when targeting 'ES5'. Class definitions are automatically in strict mode."
                } else {
                    1250 to "Function declarations are not allowed inside blocks in strict mode when targeting 'ES5'."
                }
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = code,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = name.pos,
                    length = name.text.length,
                ))
                // Don't recurse into the function body (new scope, not a block)
                continue
            }
            // Recurse into blocks
            checkBlockFuncDeclInStatement(stmt, source, fileName, inClassMethod)
        }
    }

    private fun checkBlockFuncDeclInStatement(stmt: Statement, source: String, fileName: String, inClassMethod: Boolean) {
        when (stmt) {
            is IfStatement -> {
                val thenStmt = stmt.thenStatement
                if (thenStmt is Block) {
                    checkBlockFuncDeclInStatements(thenStmt.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
                val elseStmt = stmt.elseStatement
                if (elseStmt is Block) {
                    checkBlockFuncDeclInStatements(elseStmt.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                } else if (elseStmt != null) {
                    checkBlockFuncDeclInStatement(elseStmt, source, fileName, inClassMethod)
                }
            }
            is ForStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is ForInStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is ForOfStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is WhileStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is DoStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is Block -> {
                // Standalone block
                checkBlockFuncDeclInStatements(stmt.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
            }
            is TryStatement -> {
                checkBlockFuncDeclInStatements(stmt.tryBlock.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                stmt.catchClause?.let { catch ->
                    checkBlockFuncDeclInStatements(catch.block.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
                stmt.finallyBlock?.let { finally_ ->
                    checkBlockFuncDeclInStatements(finally_.statements, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is LabeledStatement -> {
                checkBlockFuncDeclInStatement(stmt.statement, source, fileName, inClassMethod)
            }
            is SwitchStatement -> {
                // Each case/default clause body is effectively a block scope.
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkBlockFuncDeclInStatements(clauseStmts, source, fileName, inBlock = true, inClassMethod = inClassMethod)
                }
            }
            is FunctionDeclaration -> {
                // Recurse into function bodies (new scope, reset inBlock = false)
                stmt.body?.let { checkBlockFuncDeclInStatements(it.statements, source, fileName, inBlock = false, inClassMethod = false) }
            }
            is ClassDeclaration -> {
                // Recurse into class method bodies with inClassMethod = true
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkBlockFuncDeclInStatements(it.statements, source, fileName, inBlock = false, inClassMethod = true)
                        }
                        is Constructor -> member.body?.let {
                            checkBlockFuncDeclInStatements(it.statements, source, fileName, inBlock = false, inClassMethod = true)
                        }
                        is GetAccessor -> member.body?.let {
                            checkBlockFuncDeclInStatements(it.statements, source, fileName, inBlock = false, inClassMethod = true)
                        }
                        is SetAccessor -> member.body?.let {
                            checkBlockFuncDeclInStatements(it.statements, source, fileName, inBlock = false, inClassMethod = true)
                        }
                        else -> {}
                    }
                }
            }
            // Don't recurse into modules
            else -> {}
        }
    }

    // TS1191: An import declaration cannot have modifiers
    private fun checkImportModifiers() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ImportDeclaration && ModifierFlag.Export in stmt.modifiers) {
                    // Squiggle covers the 'export' keyword which precedes 'import'
                    // Search backwards from stmt.pos to find 'export'
                    var exportPos = stmt.pos
                    val searchStart = maxOf(0, stmt.pos - 20)
                    val prefix = source.substring(searchStart, stmt.pos)
                    val idx = prefix.lastIndexOf("export")
                    if (idx >= 0) exportPos = searchStart + idx
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    diagnostics.add(Diagnostic(
                        message = "An import declaration cannot have modifiers.",
                        category = DiagnosticCategory.Error,
                        code = 1191,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = exportPos,
                        length = 6, // "export"
                    ))
                }
                // TS1079: 'declare' modifier cannot be used with import declarations.
                // For ImportEqualsDeclaration, suppress when TS1029 (export-before-declare order)
                // is also firing — the baseline merges to TS1029 only.
                val importMods = when (stmt) {
                    is ImportDeclaration -> stmt.modifiers
                    is ImportEqualsDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers) null else stmt.modifiers
                    }
                    else -> null
                }
                if (importMods != null && ModifierFlag.Declare in importMods) {
                    // Find the 'declare' keyword position
                    val searchStart2 = maxOf(0, stmt.pos - 20)
                    val prefix2 = source.substring(searchStart2, stmt.pos)
                    val idx2 = prefix2.lastIndexOf("declare")
                    val declarePos = if (idx2 >= 0) searchStart2 + idx2 else stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, declarePos)
                    diagnostics.add(Diagnostic(
                        message = "A 'declare' modifier cannot be used with an import declaration.",
                        category = DiagnosticCategory.Error,
                        code = 1079,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = declarePos,
                        length = 7, // "declare"
                    ))
                }
                // 16.0: TS1120 — `declare export = X` or `export export = X` (modifiers on export assignment).
                // For `export = X` (isExportEquals=true), ANY modifier is invalid.
                // For `export default X` (isExportEquals=false), Export+Default are normal; Declare is invalid.
                val invalidExportAssignmentMod = stmt is ExportAssignment && (
                    (stmt.isExportEquals && (ModifierFlag.Declare in stmt.modifiers || ModifierFlag.Export in stmt.modifiers)) ||
                    (!stmt.isExportEquals && ModifierFlag.Declare in stmt.modifiers)
                )
                // 16.0: TS1035 — `module 'X' {}` without declare (only ambient modules can use quoted names)
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode &&
                    ModifierFlag.Declare !in stmt.modifiers) {
                    val nameNode = stmt.name as StringLiteralNode
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Only ambient modules can use quoted names.",
                        category = DiagnosticCategory.Error,
                        code = 1035,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = nameNode.pos,
                        length = nameNode.text.length + 2,
                    ))
                }
                if (invalidExportAssignmentMod) {
                    val stmt = stmt as ExportAssignment
                    // Find the FIRST modifier keyword in the source (whichever comes first textually)
                    val searchStart3 = maxOf(0, stmt.pos - 20)
                    val prefix3 = source.substring(searchStart3, stmt.pos + 8)
                    val declareIdx = if (ModifierFlag.Declare in stmt.modifiers) prefix3.indexOf("declare") else -1
                    val exportIdx = if (ModifierFlag.Export in stmt.modifiers) prefix3.indexOf("export") else -1
                    val (kwIdx, kw) = when {
                        declareIdx >= 0 && exportIdx >= 0 -> if (declareIdx < exportIdx) declareIdx to "declare" else exportIdx to "export"
                        declareIdx >= 0 -> declareIdx to "declare"
                        exportIdx >= 0 -> exportIdx to "export"
                        else -> -1 to ""
                    }
                    if (kwIdx >= 0) {
                        val keywordPos = searchStart3 + kwIdx
                        val (line, character) = getLineAndCharacterOfPosition(source, keywordPos)
                        diagnostics.add(Diagnostic(
                            message = "An export assignment cannot have modifiers.",
                            category = DiagnosticCategory.Error,
                            code = 1120,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = keywordPos,
                            length = kw.length,
                        ))
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Block-scoped variable use before declaration (TS2448/TS2450)
    // -----------------------------------------------------------------------

    private fun checkUseBeforeDeclaration() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUBDInStatements(result.sourceFile.statements, source, fileName)
        }
        // Cross-file: check if top-level identifiers reference block-scoped decls in later files
        if (binderResults.size > 1) {
            checkCrossFileUseBeforeDeclaration()
        }
    }

    private data class CrossFileBlockDecl(
        val fileIdx: Int,
        val pos: Int,
        val name: String,
        val source: String,
        val fileName: String,
    )

    /**
     * Cross-file TS2448: when file1 uses identifier `x` at top level,
     * and `x` is declared with let/const in a later file2, emit TS2448.
     *
     * Pre-builds a map of first-occurrence block-scoped decls across all
     * non-d.ts files (file order = binderResults order = build.gradle test
     * harness order — the same order TypeScript's test framework uses).
     * Then walks each file's top-level statements collecting identifier
     * uses; for any use whose name has a cross-file decl in a LATER file
     * AND is not a local of the using file, emits TS2448.
     *
     * Walks bare `Identifier` ExpressionStatements (`c;`), assignment-LHS /
     * RHS in BinaryExpressions (`a = 10`, `x.p = a + b`), and
     * ParenthesizedExpressions. Other expression shapes
     * (CallExpression / NewExpression etc.) are not walked here — TS2448
     * for those at top level isn't covered by the existing baselines and
     * widening risks regressing tests not yet investigated.
     */
    private fun checkCrossFileUseBeforeDeclaration() {
        val firstDeclByName = HashMap<String, CrossFileBlockDecl>()
        for ((fileIdx, result) in binderResults.withIndex()) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && ModifierFlag.Declare !in stmt.modifiers) {
                    val kind = stmt.declarationList.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in stmt.declarationList.declarations) {
                            val nameNode = d.name
                            if (nameNode is Identifier && nameNode.text !in firstDeclByName) {
                                firstDeclByName[nameNode.text] = CrossFileBlockDecl(
                                    fileIdx, nameNode.pos, nameNode.text, source, fileName,
                                )
                            }
                        }
                    }
                }
            }
        }
        if (firstDeclByName.isEmpty()) return
        for ((fileIdx, result) in binderResults.withIndex()) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // TypeScript only emits cross-file TS2448 when the use site is
            // a TS file. JS use sites (`b = 30` in b.js referencing `let b`
            // in a later a.ts) do not error, even with `--allowJs` (see
            // baseline `jsFileCompilationLetDeclarationOrder`).
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".cjs") || fileName.endsWith(".mjs")) continue
            val source = result.sourceFile.text
            val localNames = result.locals.keys
            for (stmt in result.sourceFile.statements) {
                if (stmt is ExpressionStatement) {
                    checkCrossFileUBDInExpr(
                        stmt.expression, fileIdx, localNames, source, fileName, firstDeclByName,
                    )
                }
            }
        }
    }

    private fun checkCrossFileUBDInExpr(
        expr: Expression,
        useFileIdx: Int,
        localNames: Set<String>,
        source: String,
        fileName: String,
        firstDeclByName: Map<String, CrossFileBlockDecl>,
    ) {
        when (expr) {
            is Identifier -> {
                val name = expr.text
                if (name in localNames) return
                val decl = firstDeclByName[name] ?: return
                if (decl.fileIdx > useFileIdx) {
                    emitCrossFileTS2448(
                        expr, name, source, fileName,
                        decl.pos, decl.name, decl.source, decl.fileName,
                    )
                }
            }
            is BinaryExpression -> {
                // B64.7: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkCrossFileUBDInExpr(cur, useFileIdx, localNames, source, fileName, firstDeclByName)
                while (rightStack.isNotEmpty()) checkCrossFileUBDInExpr(rightStack.removeLast(), useFileIdx, localNames, source, fileName, firstDeclByName)
            }
            is ParenthesizedExpression -> checkCrossFileUBDInExpr(
                expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName,
            )
            is AsExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is TypeAssertionExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is SatisfiesExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is NonNullExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is ConditionalExpression -> {
                checkCrossFileUBDInExpr(expr.condition, useFileIdx, localNames, source, fileName, firstDeclByName)
                checkCrossFileUBDInExpr(expr.whenTrue, useFileIdx, localNames, source, fileName, firstDeclByName)
                checkCrossFileUBDInExpr(expr.whenFalse, useFileIdx, localNames, source, fileName, firstDeclByName)
            }
            is CallExpression -> {
                checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
                expr.arguments.forEach { checkCrossFileUBDInExpr(it, useFileIdx, localNames, source, fileName, firstDeclByName) }
            }
            is NewExpression -> {
                checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
                expr.arguments?.forEach { checkCrossFileUBDInExpr(it, useFileIdx, localNames, source, fileName, firstDeclByName) }
            }
            is PropertyAccessExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is ElementAccessExpression -> {
                checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
                checkCrossFileUBDInExpr(expr.argumentExpression, useFileIdx, localNames, source, fileName, firstDeclByName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkCrossFileUBDInExpr(it, useFileIdx, localNames, source, fileName, firstDeclByName) }
            is SpreadElement -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is PrefixUnaryExpression -> checkCrossFileUBDInExpr(expr.operand, useFileIdx, localNames, source, fileName, firstDeclByName)
            is PostfixUnaryExpression -> checkCrossFileUBDInExpr(expr.operand, useFileIdx, localNames, source, fileName, firstDeclByName)
            is AwaitExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is YieldExpression -> expr.expression?.let { checkCrossFileUBDInExpr(it, useFileIdx, localNames, source, fileName, firstDeclByName) }
            is VoidExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is DeleteExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is TypeOfExpression -> checkCrossFileUBDInExpr(expr.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
            is TemplateExpression -> expr.templateSpans.forEach { checkCrossFileUBDInExpr(it.expression, useFileIdx, localNames, source, fileName, firstDeclByName) }
            is TaggedTemplateExpression -> {
                checkCrossFileUBDInExpr(expr.tag, useFileIdx, localNames, source, fileName, firstDeclByName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkCrossFileUBDInExpr(it.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkCrossFileUBDInExpr(it, useFileIdx, localNames, source, fileName, firstDeclByName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkCrossFileUBDInExpr(prop.initializer, useFileIdx, localNames, source, fileName, firstDeclByName)
                    is SpreadAssignment -> checkCrossFileUBDInExpr(prop.expression, useFileIdx, localNames, source, fileName, firstDeclByName)
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun emitCrossFileTS2448(
        useNode: Identifier, name: String, useSource: String, useFileName: String,
        declPos: Int, declName: String, declSource: String, declFileName: String,
    ) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(useSource, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(declSource, declPos)
        diagnostics.add(Diagnostic(
            message = "Block-scoped variable '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2448,
            fileName = useFileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$declName' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = declFileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = declName.length,
            )),
        ))
    }

    private fun checkUBDInStatements(stmts: List<Statement>, source: String, fileName: String) {
        // Collect all let/const/enum declaration names in this block with their positions
        val blockScopedDecls = collectBlockScopedDeclsEx(stmts, source)
        // Remove names that also have hoisted declarations (function/var) in the same scope
        // because hoisted declarations make the name available before its let/const decl
        val hoistedNames = mutableSetOf<String>()
        for (stmt in stmts) {
            if (stmt is FunctionDeclaration && stmt.name != null) {
                hoistedNames.add(stmt.name!!.text)
            }
            if (stmt is VariableStatement && stmt.declarationList.flags == SyntaxKind.VarKeyword) {
                for (d in stmt.declarationList.declarations) {
                    if (d.name is Identifier) hoistedNames.add((d.name as Identifier).text)
                }
            }
        }
        for (name in hoistedNames) blockScopedDecls.remove(name)

        for (stmt in stmts) {
            checkUBDForwardRefs(stmt, blockScopedDecls, source, fileName)
            checkUBDInStatement(stmt, source, fileName, blockScopedDecls)
        }
    }

    /** Check all identifier usages in this statement for forward references to block-scoped declarations */
    private fun checkUBDForwardRefs(stmt: Statement, blockDecls: Map<String, BlockScopedDecl>, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
            is VariableStatement -> {
                val kind = stmt.declarationList.flags
                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                    for (d in stmt.declarationList.declarations) {
                        // Self-referencing initializers (let x = x)
                        val selfNames = mutableMapOf<String, Int>()
                        collectSelfRefNames(d.name, selfNames)
                        d.initializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                        checkUBDInBindingDefaults(d.name, selfNames, source, fileName)
                        // Forward refs to OTHER block-scoped decls (let a = x; let x;)
                        d.initializer?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
                    }
                } else {
                    // var declarations: check for forward refs to block-scoped decls
                    for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
                    }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
            is IfStatement -> {
                checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
                checkUBDForwardRefs(stmt.thenStatement, blockDecls, source, fileName)
                stmt.elseStatement?.let { checkUBDForwardRefs(it, blockDecls, source, fileName) }
            }
            is WhileStatement -> {
                checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
                // Don't check body — it runs after condition, which may include the decl
            }
            is ClassDeclaration -> {
                // Check heritage (extends) clause for forward references
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (typeExpr in clause.types) {
                            checkUBDForwardInExpr(typeExpr.expression, blockDecls, source, fileName)
                        }
                    }
                }
                // Static property initializers evaluate at class-declaration time — check for
                // forward refs to other classes. Instance-property initializers evaluate in the
                // constructor (deferred), so they're safe.
                for (member in stmt.members) {
                    if (member is PropertyDeclaration &&
                        ModifierFlag.Static in member.modifiers) {
                        member.initializer?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName, inStaticInit = true) }
                    }
                }
            }
            is SwitchStatement -> checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
            is LabeledStatement -> checkUBDForwardRefs(stmt.statement, blockDecls, source, fileName)
            else -> {}
        }
    }

    /** Check expression for forward references to block-scoped declarations.
     * `inStaticInit` is true when walking a class static-property initializer;
     * TS2729 for forward-referenced receivers fires only in that context. */
    private fun checkUBDForwardInExpr(expr: Expression, blockDecls: Map<String, BlockScopedDecl>, source: String, fileName: String, inStaticInit: Boolean = false) {
        when (expr) {
            is Identifier -> {
                val decl = blockDecls[expr.text]
                if (decl != null && expr.pos < decl.pos) {
                    when {
                        decl.isNamespace -> {} // namespaces have a hoisted binding; no TS2448/2449/2450 on the name itself
                        decl.isEnum -> emitTS2450(expr, decl.pos, expr.text, source, fileName)
                        decl.isClass -> emitTS2449(expr, decl.pos, expr.text, source, fileName)
                        else -> emitTS2448(expr, decl.pos, expr.text, source, fileName, decl.isConst, decl.hasInitializer, decl.isUnreachable)
                    }
                }
            }
            is BinaryExpression -> {
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUBDForwardInExpr(current.right, blockDecls, source, fileName, inStaticInit)
                    current = current.left
                }
                checkUBDForwardInExpr(current, blockDecls, source, fileName, inStaticInit)
            }
            is PrefixUnaryExpression -> checkUBDForwardInExpr(expr.operand, blockDecls, source, fileName, inStaticInit)
            is PostfixUnaryExpression -> checkUBDForwardInExpr(expr.operand, blockDecls, source, fileName, inStaticInit)
            is ParenthesizedExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is ConditionalExpression -> {
                checkUBDForwardInExpr(expr.condition, blockDecls, source, fileName, inStaticInit)
                checkUBDForwardInExpr(expr.whenTrue, blockDecls, source, fileName, inStaticInit)
                checkUBDForwardInExpr(expr.whenFalse, blockDecls, source, fileName, inStaticInit)
            }
            is CallExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
                for (arg in expr.arguments) checkUBDForwardInExpr(arg, blockDecls, source, fileName, inStaticInit)
            }
            is PropertyAccessExpression -> {
                // TS2729 for forward-referenced receivers: if the base identifier refers
                // to a block-scoped entity whose initializer runs later in the same
                // top-level sequence, accessing its members before that point reads
                // before initialization. Fires for: class statics, enum members, const
                // object-literal properties, and non-ambient namespace exports.
                // Only in class static-initializer contexts — in regular code the
                // TS2448/2449/2450 on the bare receiver identifier is sufficient.
                if (inStaticInit) {
                    val base = expr.expression
                    if (base is Identifier) {
                        val baseDecl = blockDecls[base.text]
                        if (baseDecl != null && base.pos < baseDecl.pos) {
                            val propName = expr.name.text
                            val propDeclPos = findForwardRefMemberPos(baseDecl, propName)
                            if (propDeclPos != null) {
                                emitTS2729CrossClass(expr.name, propName, propDeclPos, source, fileName)
                            }
                        }
                    }
                }
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            }
            is ElementAccessExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
                checkUBDForwardInExpr(expr.argumentExpression, blockDecls, source, fileName, inStaticInit)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkUBDForwardInExpr(el, blockDecls, source, fileName, inStaticInit)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkUBDForwardInExpr(prop.initializer, blockDecls, source, fileName, inStaticInit)
                    is SpreadAssignment -> checkUBDForwardInExpr(prop.expression, blockDecls, source, fileName, inStaticInit)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkUBDForwardInExpr(span.expression, blockDecls, source, fileName, inStaticInit)
            }
            is TypeOfExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is NonNullExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is SpreadElement -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is NewExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
                expr.arguments?.forEach { checkUBDForwardInExpr(it, blockDecls, source, fileName, inStaticInit) }
            }
            is AsExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is TypeAssertionExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is SatisfiesExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is VoidExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is DeleteExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is AwaitExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName, inStaticInit)
            is YieldExpression -> expr.expression?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName, inStaticInit) }
            is TaggedTemplateExpression -> {
                checkUBDForwardInExpr(expr.tag, blockDecls, source, fileName, inStaticInit)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkUBDForwardInExpr(it.expression, blockDecls, source, fileName, inStaticInit)
                }
            }
            is CommaListExpression -> for (el in expr.elements) checkUBDForwardInExpr(el, blockDecls, source, fileName, inStaticInit)
            // B83.6: ClassExpression — static property initializers evaluate at
            // class-definition time (i.e. when the surrounding expression evaluates).
            // Walk them for forward-ref detection. Instance-property initializers
            // run inside the constructor (deferred), so they're safe.
            // Mirrors the ClassDeclaration branch in checkUBDForwardRefs.
            is ClassExpression -> {
                expr.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (typeExpr in clause.types) {
                            checkUBDForwardInExpr(typeExpr.expression, blockDecls, source, fileName, inStaticInit)
                        }
                    }
                }
                for (member in expr.members) {
                    if (member is PropertyDeclaration &&
                        ModifierFlag.Static in member.modifiers) {
                        member.initializer?.let {
                            checkUBDForwardInExpr(it, blockDecls, source, fileName, inStaticInit = true)
                        }
                    }
                }
            }
            // Don't recurse into functions/arrows (they capture lazily)
            is ArrowFunction, is FunctionExpression -> {}
            else -> {}
        }
    }

    private data class BlockScopedDecl(
        val pos: Int,
        val isEnum: Boolean = false,
        val isClass: Boolean = false,
        val isConst: Boolean = false,
        val hasInitializer: Boolean = false,
        val isNamespace: Boolean = false,
        val classNode: ClassDeclaration? = null,
        val enumNode: EnumDeclaration? = null,
        val constInitObjLit: ObjectLiteralExpression? = null,
        val namespaceNode: ModuleDeclaration? = null,
        /** B78.1: declaration sits in unreachable code (after a top-level `return`/`throw`
         * at the same statement-list level). Used to widen TS2454 co-emission for
         * const-with-initializer: TypeScript fires TS2454 for `const x = init`
         * used-before-declaration ONLY when the declaration is unreachable (its
         * initializer will never run in the live flow); reachable const-with-init
         * just fires TS2448 (matches typeGuardNarrowsIndexedAccessOfKnownProperty10
         * which expects only TS2448 for `const id = ...` used out-of-order in the
         * same reachable arrow body). */
        val isUnreachable: Boolean = false,
    )

    private fun collectBlockScopedDeclsEx(stmts: List<Statement>, source: String): MutableMap<String, BlockScopedDecl> {
        val decls = mutableMapOf<String, BlockScopedDecl>()
        var unreachable = false
        for (stmt in stmts) {
            collectBlockScopedDeclEx(stmt, decls, source, unreachable)
            // B78.1: top-level `return`/`throw` marks all subsequent same-list stmts unreachable.
            if (stmt is ReturnStatement || stmt is ThrowStatement) unreachable = true
        }
        return decls
    }

    private fun collectBlockScopedDeclEx(stmt: Statement, decls: MutableMap<String, BlockScopedDecl>, source: String, unreachable: Boolean = false) {
        when (stmt) {
            is VariableStatement -> {
                // declare const/let have no temporal dead zone (they're ambient)
                if (ModifierFlag.Declare in stmt.modifiers) return
                val kind = stmt.declarationList.flags
                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                    val isConstDecl = kind == SyntaxKind.ConstKeyword
                    for (d in stmt.declarationList.declarations) {
                        val objLit = if (isConstDecl) d.initializer as? ObjectLiteralExpression else null
                        collectBindingNamesEx(d.name, decls, isConst = isConstDecl, hasInit = d.initializer != null, constInitObjLit = objLit, isUnreachable = unreachable)
                    }
                }
            }
            is EnumDeclaration -> {
                // declare enum has no temporal dead zone
                if (ModifierFlag.Declare in stmt.modifiers) return
                // const enum values are inlined at compile time — no temporal dead zone
                // EXCEPT with isolatedModules/verbatimModuleSyntax, where inlining is suppressed
                val isConst = ModifierFlag.Const in stmt.modifiers
                if (!isConst || options.isolatedModules || options.verbatimModuleSyntax) {
                    decls[stmt.name.text] = BlockScopedDecl(stmt.name.pos, isEnum = true, enumNode = stmt, isUnreachable = unreachable)
                }
            }
            is ClassDeclaration -> {
                // declare class has no temporal dead zone
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    val name = stmt.name
                    if (name != null) {
                        decls[name.text] = BlockScopedDecl(name.pos, isClass = true, classNode = stmt, isUnreachable = unreachable)
                    }
                }
            }
            is ModuleDeclaration -> {
                // Track non-ambient namespaces only for member-access forward-ref detection.
                // The namespace identifier itself doesn't trigger use-before-decl (namespaces
                // have a hoisted binding); only `Namespace.X` before the namespace's IIFE runs
                // is a TS2729.
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    val nameNode = stmt.name
                    if (nameNode is Identifier) {
                        decls[nameNode.text] = BlockScopedDecl(nameNode.pos, isNamespace = true, namespaceNode = stmt, isUnreachable = unreachable)
                    }
                }
            }
            else -> {}
        }
    }

    /** Collect binding names into a simple name -> pos map for self-reference checks */
    private fun collectSelfRefNames(name: Node, decls: MutableMap<String, Int>) {
        when (name) {
            is Identifier -> decls[name.text] = name.pos
            is ObjectBindingPattern -> for (el in name.elements) {
                collectSelfRefNames(el.name, decls)
            }
            is ArrayBindingPattern -> for (el in name.elements) {
                if (el is BindingElement) collectSelfRefNames(el.name, decls)
            }
            else -> {}
        }
    }

    private fun collectBindingNamesEx(name: Node, decls: MutableMap<String, BlockScopedDecl>, isConst: Boolean = false, hasInit: Boolean = false, constInitObjLit: ObjectLiteralExpression? = null, isUnreachable: Boolean = false) {
        when (name) {
            is Identifier -> decls[name.text] = BlockScopedDecl(name.pos, isConst = isConst, hasInitializer = hasInit, constInitObjLit = constInitObjLit, isUnreachable = isUnreachable)
            is ObjectBindingPattern -> for (el in name.elements) {
                collectBindingNamesEx(el.name, decls, isConst, hasInit, isUnreachable = isUnreachable)
            }
            is ArrayBindingPattern -> for (el in name.elements) {
                if (el is BindingElement) collectBindingNamesEx(el.name, decls, isConst, hasInit, isUnreachable = isUnreachable)
            }
            else -> {}
        }
    }

    /** Recurse into nested block scopes (functions, classes, blocks) */
    private fun checkUBDInStatement(stmt: Statement, source: String, fileName: String, blockDecls: Map<String, BlockScopedDecl>) {
        when (stmt) {
            is VariableStatement -> {
                // Recurse into nested scopes in initializers
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkUBDInExprForNested(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkUBDInExprForNested(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkUBDInExprForNested(it, source, fileName) }
            is IfStatement -> {
                checkUBDInStatement(stmt.thenStatement, source, fileName, blockDecls)
                stmt.elseStatement?.let { checkUBDInStatement(it, source, fileName, blockDecls) }
            }
            is Block -> checkUBDInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkUBDInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkUBDInExprForNested(it, source, fileName) }
                    is GetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                // Self-references in for-loop let/const initializers
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            d.initializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            checkUBDInInitializer(stmt.expression, selfNames, source, fileName)
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            checkUBDInInitializer(stmt.expression, selfNames, source, fileName)
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is WhileStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is DoStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                checkUBDInStatements(clauseStmts, source, fileName)
            }
            is TryStatement -> {
                checkUBDInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkUBDInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkUBDInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkUBDInStatements(it.statements, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { checkUBDInExprForNested(it, source, fileName) }
            is ExportAssignment -> stmt.expression?.let { checkUBDInExprForNested(it, source, fileName) }
            else -> {}
        }
    }

    /** Check defaults in destructuring binding patterns for self-references */
    private fun checkUBDInBindingDefaults(name: Node, selfNames: Map<String, Int>, source: String, fileName: String) {
        // For binding patterns, earlier elements are available in later element defaults.
        // Only check each element's initializer against names that are NOT yet initialized
        // (i.e. the current element's own name and later elements, but not earlier ones).
        when (name) {
            is ObjectBindingPattern -> {
                val remaining = selfNames.toMutableMap()
                for (el in name.elements) {
                    el.initializer?.let { checkUBDInInitializer(it, remaining, source, fileName) }
                    checkUBDInBindingDefaults(el.name, remaining, source, fileName)
                    val elNames = mutableMapOf<String, Int>()
                    collectSelfRefNames(el.name, elNames)
                    for (n in elNames.keys) remaining.remove(n)
                }
            }
            is ArrayBindingPattern -> {
                val remaining = selfNames.toMutableMap()
                for (el in name.elements) {
                    if (el is BindingElement) {
                        el.initializer?.let { checkUBDInInitializer(it, remaining, source, fileName) }
                        checkUBDInBindingDefaults(el.name, remaining, source, fileName)
                        val elNames = mutableMapOf<String, Int>()
                        collectSelfRefNames(el.name, elNames)
                        for (n in elNames.keys) remaining.remove(n)
                    }
                }
            }
            else -> {}
        }
    }

    /** Check an initializer expression for references to the variable being declared */
    private fun checkUBDInInitializer(expr: Expression, selfNames: Map<String, Int>, source: String, fileName: String) {
        when (expr) {
            is Identifier -> {
                val declPos = selfNames[expr.text]
                if (declPos != null) {
                    emitTS2448(expr, declPos, expr.text, source, fileName)
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUBDInInitializer(current.right, selfNames, source, fileName)
                    current = current.left
                }
                checkUBDInInitializer(current, selfNames, source, fileName)
            }
            is PrefixUnaryExpression -> checkUBDInInitializer(expr.operand, selfNames, source, fileName)
            is PostfixUnaryExpression -> checkUBDInInitializer(expr.operand, selfNames, source, fileName)
            is ParenthesizedExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is ConditionalExpression -> {
                checkUBDInInitializer(expr.condition, selfNames, source, fileName)
                checkUBDInInitializer(expr.whenTrue, selfNames, source, fileName)
                checkUBDInInitializer(expr.whenFalse, selfNames, source, fileName)
            }
            is CallExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                for (arg in expr.arguments) checkUBDInInitializer(arg, selfNames, source, fileName)
            }
            is NewExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                expr.arguments?.forEach { checkUBDInInitializer(it, selfNames, source, fileName) }
            }
            is PropertyAccessExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is ElementAccessExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                checkUBDInInitializer(expr.argumentExpression, selfNames, source, fileName)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkUBDInInitializer(el, selfNames, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkUBDInInitializer(prop.initializer, selfNames, source, fileName)
                    is ShorthandPropertyAssignment -> {
                        // Shorthand { x } where x is a self-ref
                        val declPos = selfNames[prop.name.text]
                        if (declPos != null) {
                            emitTS2448(prop.name, declPos, prop.name.text, source, fileName)
                        }
                        prop.objectAssignmentInitializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                    }
                    is SpreadAssignment -> checkUBDInInitializer(prop.expression, selfNames, source, fileName)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkUBDInInitializer(span.expression, selfNames, source, fileName)
            }
            is TypeOfExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is NonNullExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is SpreadElement -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is VoidExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is DeleteExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is AsExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is TypeAssertionExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is SatisfiesExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            // Arrow functions, function expressions — DON'T recurse into bodies (lazy evaluation)
            is ArrowFunction, is FunctionExpression -> {}
            else -> {}
        }
    }

    /** Recurse into nested scopes (functions, classes) to find new block-scoped declarations */
    private fun checkUBDInExprForNested(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkUBDInStatements(body.statements, source, fileName)
                is Expression -> checkUBDInExprForNested(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkUBDInStatements(it.statements, source, fileName) }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkUBDInExprForNested(it, source, fileName) }
                    else -> {}
                }
            }
            is ParenthesizedExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is AsExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is SatisfiesExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is NonNullExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    checkUBDInExprForNested(cur.right, source, fileName)
                    cur = cur.left
                }
                checkUBDInExprForNested(cur, source, fileName)
            }
            is ConditionalExpression -> {
                checkUBDInExprForNested(expr.condition, source, fileName)
                checkUBDInExprForNested(expr.whenTrue, source, fileName)
                checkUBDInExprForNested(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkUBDInExprForNested(expr.expression, source, fileName)
                expr.arguments.forEach { checkUBDInExprForNested(it, source, fileName) }
            }
            is NewExpression -> {
                checkUBDInExprForNested(expr.expression, source, fileName)
                expr.arguments?.forEach { checkUBDInExprForNested(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkUBDInExprForNested(expr.expression, source, fileName)
                checkUBDInExprForNested(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkUBDInExprForNested(it, source, fileName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkUBDInExprForNested(prop.initializer, source, fileName)
                    is SpreadAssignment -> checkUBDInExprForNested(prop.expression, source, fileName)
                    is MethodDeclaration -> prop.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is GetAccessor -> prop.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is SetAccessor -> prop.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is SpreadElement -> checkUBDInExprForNested(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkUBDInExprForNested(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkUBDInExprForNested(expr.operand, source, fileName)
            is AwaitExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkUBDInExprForNested(it, source, fileName) }
            is VoidExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is DeleteExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is TypeOfExpression -> checkUBDInExprForNested(expr.expression, source, fileName)
            is TemplateExpression -> expr.templateSpans.forEach { checkUBDInExprForNested(it.expression, source, fileName) }
            is TaggedTemplateExpression -> {
                checkUBDInExprForNested(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkUBDInExprForNested(it.expression, source, fileName)
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkUBDInExprForNested(it, source, fileName) }
            else -> {}
        }
    }

    private fun emitTS2448(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String, isConst: Boolean = false, hasInitializer: Boolean = false, isUnreachableDecl: Boolean = false) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Block-scoped variable '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2448,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
        // Co-emit TS2454: "Variable 'x' is used before being assigned."
        // TypeScript emits both TS2448 and TS2454 at the same position when the declaration
        // has an initializer (the variable WILL be assigned, but the use is before that point).
        // For `let`: any forward use of an initialized `let x = init` co-emits TS2454.
        // For `const`: only when the declaration is in unreachable code (e.g. after a top-level
        // `return`/`throw`) — TypeScript treats the const's initializer as never running, so the
        // forward use is effectively "used before being assigned". Reachable `const x = init`
        // used out-of-order in the same scope (e.g. typeGuardNarrowsIndexedAccessOfKnownProperty10)
        // fires only TS2448 because the const WILL be assigned by the time the live program
        // reaches that use site at runtime (TDZ runtime error, but not a use-before-assigned
        // flow analysis result). B78.1.
        if (strictNullChecks && hasInitializer && (!isConst || isUnreachableDecl)) {
            diagnostics.add(Diagnostic(
                message = "Variable '$name' is used before being assigned.",
                category = DiagnosticCategory.Error,
                code = 2454,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun emitTS2450(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Enum '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2450,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
    }

    private fun emitTS2449(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String) {
        // B18.3 v3: suppress TS2449 for classes in an ambient-namespace circular
        // base chain — TypeScript only emits TS2506 there. Non-ambient cycles
        // (`recursiveBaseCheck3_ts`) fire BOTH, and aren't tracked in this set.
        if (ambientCyclicBaseClassNamesByFile[fileName]?.contains(name) == true) return
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Class '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2449,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
    }

    /** Return the declaration position of `propName` inside a forward-referenced
     * block-scoped entity (class static, enum member, const-assigned object literal
     * property, or namespace export), or null if no such member exists. */
    private fun findForwardRefMemberPos(baseDecl: BlockScopedDecl, propName: String): Int? {
        baseDecl.classNode?.let { classNode ->
            val staticProp = classNode.members.firstOrNull { m ->
                m is PropertyDeclaration &&
                    ModifierFlag.Static in m.modifiers &&
                    (m.name as? Identifier)?.text == propName
            } as? PropertyDeclaration
            if (staticProp != null) {
                return (staticProp.name as? Identifier)?.pos ?: staticProp.pos
            }
        }
        baseDecl.enumNode?.let { enumNode ->
            val member = enumNode.members.firstOrNull { (it.name as? Identifier)?.text == propName }
            if (member != null) {
                return (member.name as? Identifier)?.pos ?: member.pos
            }
        }
        baseDecl.constInitObjLit?.let { objLit ->
            for (prop in objLit.properties) {
                val propIdName = when (prop) {
                    is PropertyAssignment -> (prop.name as? Identifier)?.text
                    is ShorthandPropertyAssignment -> prop.name.text
                    is MethodDeclaration -> (prop.name as? Identifier)?.text
                    else -> null
                }
                if (propIdName == propName) {
                    val pos = when (prop) {
                        is PropertyAssignment -> (prop.name as? Identifier)?.pos ?: prop.pos
                        is ShorthandPropertyAssignment -> prop.name.pos
                        is MethodDeclaration -> (prop.name as? Identifier)?.pos ?: prop.pos
                        else -> prop.pos
                    }
                    return pos
                }
            }
        }
        baseDecl.namespaceNode?.let { nsNode ->
            val body = nsNode.body
            if (body is ModuleBlock) {
                for (s in body.statements) {
                    if (s is VariableStatement && ModifierFlag.Export in s.modifiers) {
                        for (d in s.declarationList.declarations) {
                            val n = d.name
                            if (n is Identifier && n.text == propName) {
                                return n.pos
                            }
                        }
                    }
                }
            }
        }
        return null
    }

    private fun emitTS2729CrossClass(useNode: Identifier, propName: String, propDeclPos: Int, source: String, fileName: String) {
        val start = useNode.pos
        val length = propName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, propDeclPos)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' is used before its initialization.",
            category = DiagnosticCategory.Error,
            code = 2729,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$propName' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = propDeclPos,
                length = propName.length,
            )),
        ))
    }

    // -----------------------------------------------------------------------
    // Setter parameter count (TS1049)
    // -----------------------------------------------------------------------

    private fun checkSetterParameterCount() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkSetterInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkSetterInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkSetterInStatement(stmt, source, fileName)
    }

    /**
     * TS2808: "A get accessor must be at least as accessible as the setter".
     * Fires on BOTH getter and setter when the getter's visibility is more restrictive
     * than the setter's (e.g. `private get X` + `public set X`). Ignores cases without
     * a matching pair.
     *
     * Accessibility level: private=1, protected=2, public=3 (default).
     */
    private fun checkAccessorVisibilityMismatch(members: List<ClassElement>, source: String, fileName: String) {
        fun accessorName(node: NameNode): String? = when (node) {
            is Identifier -> node.text
            is StringLiteralNode -> node.text
            is NumericLiteralNode -> node.text
            else -> null
        }
        fun accessLevel(mods: Set<ModifierFlag>): Int = when {
            ModifierFlag.Private in mods -> 1
            ModifierFlag.Protected in mods -> 2
            else -> 3
        }
        val getters = mutableMapOf<Pair<String, Boolean>, GetAccessor>()
        val setters = mutableMapOf<Pair<String, Boolean>, SetAccessor>()
        for (m in members) {
            when (m) {
                is GetAccessor -> accessorName(m.name)?.let {
                    getters[it to (ModifierFlag.Static in m.modifiers)] = m
                }
                is SetAccessor -> accessorName(m.name)?.let {
                    setters[it to (ModifierFlag.Static in m.modifiers)] = m
                }
                else -> {}
            }
        }
        for ((key, g) in getters) {
            val s = setters[key] ?: continue
            if (accessLevel(g.modifiers) < accessLevel(s.modifiers)) {
                for ((nameNode, _) in listOf(g.name to true, s.name to false)) {
                    val start = if (nameNode is Identifier) nameNode.pos else 0
                    val length = if (nameNode is Identifier) nameNode.text.length else 3
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "A get accessor must be at least as accessible as the setter",
                        category = DiagnosticCategory.Error,
                        code = 2808,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }
    }

    private fun checkSetterInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                checkAccessorVisibilityMismatch(stmt.members, source, fileName)
                for (m in stmt.members) {
                    if (m is SetAccessor) {
                        checkSetterParams(m.name, m.parameters, source, fileName)
                        // TS1095: set accessor cannot have a return type annotation
                        if (m.type != null) {
                            val nameNode = m.name
                            val start = if (nameNode is Identifier) nameNode.pos else m.pos
                            val length = if (nameNode is Identifier) nameNode.text.length else 3
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "A 'set' accessor cannot have a return type annotation.",
                                category = DiagnosticCategory.Error,
                                code = 1095,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                    if (m is GetAccessor && m.parameters.isNotEmpty()) {
                        // TS1054: get accessor cannot have parameters
                        val nameNode = m.name
                        val start = if (nameNode is Identifier) nameNode.pos else m.pos
                        val length = if (nameNode is Identifier) nameNode.text.length else 3
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "A 'get' accessor cannot have parameters.",
                            category = DiagnosticCategory.Error,
                            code = 1054,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    // Recurse into methods/constructors
                    when (m) {
                        is MethodDeclaration -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> checkSetterInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkSetterInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkSetterInExpr(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { checkSetterInStatements(it.statements, source, fileName) }
            is Block -> checkSetterInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkSetterInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkSetterInStatement(it, source, fileName) }
            }
            is ForStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is TryStatement -> {
                checkSetterInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkSetterInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkSetterInStatements(it.statements, source, fileName) }
            }
            is SwitchStatement -> for (c in stmt.caseBlock) {
                when (c) {
                    is CaseClause -> checkSetterInStatements(c.statements, source, fileName)
                    is DefaultClause -> checkSetterInStatements(c.statements, source, fileName)
                    else -> {}
                }
            }
            is LabeledStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkSetterInStatements(it.statements, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { checkSetterInExpr(it, source, fileName) }
            is ExportAssignment -> checkSetterInExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun checkSetterInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    if (prop is SetAccessor) {
                        checkSetterParams(prop.name, prop.parameters, source, fileName)
                    }
                    if (prop is GetAccessor && prop.parameters.isNotEmpty()) {
                        val nameNode = prop.name
                        val start = if (nameNode is Identifier) nameNode.pos else prop.pos
                        val length = if (nameNode is Identifier) nameNode.text.length else 3
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "A 'get' accessor cannot have parameters.",
                            category = DiagnosticCategory.Error,
                            code = 1054,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    // Recurse into property initializers / method bodies so nested object
                    // literals with setters are checked.
                    when (prop) {
                        is PropertyAssignment -> checkSetterInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> checkSetterInExpr(prop.expression, source, fileName)
                        is MethodDeclaration -> prop.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is GetAccessor -> prop.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is SetAccessor -> prop.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkSetterInStatements(body.statements, source, fileName)
                is Expression -> checkSetterInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkSetterInStatements(it.statements, source, fileName) }
            is ClassExpression -> {
                for (m in expr.members) {
                    if (m is SetAccessor) {
                        checkSetterParams(m.name, m.parameters, source, fileName)
                    }
                    when (m) {
                        is MethodDeclaration -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is PropertyDeclaration -> m.initializer?.let { checkSetterInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is AsExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (current is BinaryExpression) { rightStack.addLast(current.right); current = current.left }
                checkSetterInExpr(current, source, fileName)
                while (rightStack.isNotEmpty()) checkSetterInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkSetterInExpr(expr.condition, source, fileName)
                checkSetterInExpr(expr.whenTrue, source, fileName)
                checkSetterInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkSetterInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkSetterInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkSetterInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkSetterInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkSetterInExpr(expr.expression, source, fileName)
                checkSetterInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkSetterInExpr(e, source, fileName)
            is SpreadElement -> checkSetterInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkSetterInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkSetterInExpr(expr.operand, source, fileName)
            is AwaitExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkSetterInExpr(it, source, fileName) }
            is VoidExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkSetterInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkSetterInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) checkSetterInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkSetterInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun checkSetterParams(name: Node, params: List<Parameter>, source: String, fileName: String) {
        // Count non-comment-placeholder params
        val realParams = params.count { !it.isCommentPlaceholder }
        if (realParams != 1) {
            val nameId = when (name) {
                is Identifier -> name
                is ComputedPropertyName -> null // skip computed names
                else -> null
            }
            val start = nameId?.pos ?: name.pos
            val length = if (nameId != null) nameId.text.length else (name.end - 1 - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "A 'set' accessor must have exactly one parameter.",
                category = DiagnosticCategory.Error,
                code = 1049,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // Duplicate modifiers (TS1030)
    // -----------------------------------------------------------------------

    private fun checkDuplicateModifiers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkDupModInStatements(result.sourceFile.statements, source, fileName, inAmbientContext = false)
        }
    }

    private fun checkDupModInStatements(stmts: List<Statement>, source: String, fileName: String, inAmbientContext: Boolean = false) {
        for (stmt in stmts) checkDupModInStatement(stmt, source, fileName, inAmbientContext)
    }

    private fun checkDupModInStatement(stmt: Statement, source: String, fileName: String, inAmbientContext: Boolean = false) {
        when (stmt) {
            is ClassDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                for (m in stmt.members) {
                    when (m) {
                        is PropertyDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        is MethodDeclaration -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        is Constructor -> m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        is GetAccessor -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        is SetAccessor -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is FunctionDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                stmt.body?.let { checkDupModInStatements(it.statements, source, fileName) }
            }
            is VariableStatement -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is InterfaceDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                for (m in stmt.members) {
                    when (m) {
                        is PropertyDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        is MethodDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        else -> {}
                    }
                }
            }
            is EnumDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is TypeAliasDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is ModuleDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                val nowAmbient = inAmbientContext || ModifierFlag.Declare in stmt.modifiers
                (stmt.body as? ModuleBlock)?.let { checkDupModInStatements(it.statements, source, fileName, nowAmbient) }
            }
            is Block -> checkDupModInStatements(stmt.statements, source, fileName, inAmbientContext)
            is IfStatement -> {
                checkDupModInStatement(stmt.thenStatement, source, fileName, inAmbientContext)
                stmt.elseStatement?.let { checkDupModInStatement(it, source, fileName, inAmbientContext) }
            }
            is ExportDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is ImportDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            // B61.4: also walk ImportEqualsDeclaration for modifier ordering checks
            // (e.g. `declare export import a = x.c;` should emit TS1029).
            is ImportEqualsDeclaration -> {
                // B61.5g: Skip TS1029 (modifier ordering) for declare+export import-equals
                // when inside ambient context — TS1038 fires instead.
                if (!inAmbientContext) {
                    checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                }
                // B61.5e: TS1044 for class-only modifiers (public/private/protected/static)
                // on module/namespace elements like import-equals.
                checkInvalidImportEqualsModifiers(stmt, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * B61.5e: Emit TS1044 for class-only modifiers (public/private/protected/static) on
     * an ImportEqualsDeclaration. These modifiers are not allowed on module/namespace
     * elements. Scans backwards from stmt.pos through the modifier keywords.
     */
    private fun checkInvalidImportEqualsModifiers(
        stmt: ImportEqualsDeclaration,
        source: String,
        fileName: String,
    ) {
        val classOnlyMods = setOf("public", "private", "protected", "static")
        val allowedMods = setOf("export", "declare", "public", "private", "protected", "static",
            "abstract", "async", "readonly", "override", "const", "accessor")
        // Find leftmost modifier position by scanning backwards from stmt.pos
        var pos = stmt.pos
        while (pos > 0) {
            var p = pos - 1
            while (p >= 0 && source[p].isWhitespace()) p--
            if (p < 0) break
            var found = false
            for (kw in allowedMods) {
                val kwStart = p + 1 - kw.length
                if (kwStart >= 0 &&
                    source.substring(kwStart, kwStart + kw.length) == kw &&
                    (kwStart == 0 || !source[kwStart - 1].isLetterOrDigit())) {
                    pos = kwStart
                    found = true
                    break
                }
            }
            if (!found) break
        }
        // Now scan forward from pos and emit TS1044 for class-only modifiers
        val end = (stmt.pos + 200).coerceAtMost(source.length)
        while (pos < end) {
            while (pos < end && source[pos].isWhitespace()) pos++
            if (pos >= end) break
            var matched = false
            for (kw in allowedMods) {
                if (pos + kw.length <= source.length &&
                    source.substring(pos, pos + kw.length) == kw &&
                    (pos + kw.length >= source.length || !source[pos + kw.length].isLetterOrDigit())) {
                    if (kw in classOnlyMods) {
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'$kw' modifier cannot appear on a module or namespace element.",
                            category = DiagnosticCategory.Error,
                            code = 1044,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    pos += kw.length
                    matched = true
                    break
                }
            }
            if (!matched) break
        }
    }

    private fun checkModifiers(modifiers: Set<ModifierFlag>, source: String, fileName: String, stmtPos: Int) {
        if (modifiers.size <= 1) {
            // Only 1 modifier in the set — could still be a duplicate if parser deduped
            // (e.g. `declare declare var x` → modifiers = {Declare}).
            // Only 'declare' and 'export' can appear as duplicates via parseDeclareDeclaration
            // (other keywords like 'protected' can be property names, so skip)
            if (modifiers.isEmpty() || (ModifierFlag.Declare !in modifiers && ModifierFlag.Export !in modifiers)) return
        }
        // Check for duplicate modifiers by scanning the source text around the statement
        // Find the modifier keyword positions
        val modifierKeywords = listOf("export", "default", "declare", "abstract", "async",
            "static", "readonly", "public", "private", "protected", "override", "const", "accessor")
        // Scan backwards from stmtPos to find modifier keywords that precede the declaration keyword
        // (needed because parseDeclareDeclaration consumes 'declare' before creating the statement)
        var pos = stmtPos
        while (pos > 0) {
            // Skip whitespace backwards
            var p = pos - 1
            while (p >= 0 && source[p].isWhitespace()) p--
            if (p < 0) break
            // Try to match a modifier keyword ending at p+1
            var found = false
            for (kw in modifierKeywords) {
                val kwStart = p + 1 - kw.length
                if (kwStart >= 0 &&
                    source.substring(kwStart, kwStart + kw.length) == kw &&
                    (kwStart == 0 || !source[kwStart - 1].isLetterOrDigit())) {
                    pos = kwStart
                    found = true
                    break
                }
            }
            if (!found) break
        }
        // B69.6: After backward scan, validate that pos is at a true modifier-
        // sequence start (preceded only by whitespace going back to start of file
        // OR another known modifier). Without this, `let E = {...} as const\n
        // export const o8 = ...` walks the backward scan into `as const`'s `const`
        // (matches the keyword regex), then the forward scan crosses the newline
        // and finds BOTH the prev-statement `const` AND the current-statement
        // `const`, emitting FP TS1030 at the current-statement `const`.
        run {
            var validStart = pos
            while (validStart > 0 && source[validStart - 1].isWhitespace()) validStart--
            if (validStart > 0 && source[validStart - 1].isLetterOrDigit()) return
        }
        val seen = mutableSetOf<String>()
        val end = (stmtPos + 200).coerceAtMost(source.length) // scan up to 200 chars
        while (pos < end) {
            // Skip whitespace
            while (pos < end && source[pos].isWhitespace()) pos++
            if (pos >= end) break
            // Try to match a modifier keyword
            var matched = false
            for (kw in modifierKeywords) {
                if (pos + kw.length <= source.length &&
                    source.substring(pos, pos + kw.length) == kw &&
                    (pos + kw.length >= source.length || !source[pos + kw.length].isLetterOrDigit())) {
                    if (kw in seen) {
                        // TS1030 is suppressed for 'static' as member name:
                        // When 'static' appears twice (e.g., `static static foo` or `public static static bar()`),
                        // the second 'static' is used as the member name. TypeScript emits TS1434 at that
                        // position instead of TS1030, so we skip TS1030 for 'static' duplicates.
                        if (kw != "static") {
                            // Duplicate modifier
                            val (line, character) = getLineAndCharacterOfPosition(source, pos)
                            diagnostics.add(Diagnostic(
                                message = "'$kw' modifier already seen.",
                                category = DiagnosticCategory.Error,
                                code = 1030,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = pos,
                                length = kw.length,
                            ))
                        }
                    }
                    // Check ordering: visibility modifiers must precede static
                    if ((kw == "public" || kw == "private" || kw == "protected") && "static" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'$kw' modifier must precede 'static' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    // export must precede default
                    if (kw == "export" && "default" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'export' modifier must precede 'default' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    // export must precede declare
                    if (kw == "export" && "declare" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'export' modifier must precede 'declare' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    seen.add(kw)
                    pos += kw.length
                    matched = true
                    break
                }
            }
            if (!matched) break // Hit a non-modifier token → done
        }
    }

    // -----------------------------------------------------------------------
    // Rest parameter must be last (TS1014)
    // -----------------------------------------------------------------------

    private fun checkRestParameterLast() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkRestLastInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkRestLastInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkRestLastInStatement(stmt, source, fileName)
    }

    private fun checkRestLastInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkRestLastInParams(stmt.parameters, source, fileName)
                stmt.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is GetAccessor -> m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    is SetAccessor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is ExpressionStatement -> checkRestLastInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkRestLastInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkRestLastInExpr(it, source, fileName) }
            is Block -> checkRestLastInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkRestLastInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkRestLastInStatement(it, source, fileName) }
            }
            is ForStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkRestLastInStatements(c.statements, source, fileName)
                    is DefaultClause -> checkRestLastInStatements(c.statements, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkRestLastInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkRestLastInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkRestLastInExpr(it, source, fileName) }
            is ExportAssignment -> checkRestLastInExpr(stmt.expression, source, fileName)
            is InterfaceDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> checkRestLastInParams(m.parameters, source, fileName)
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkRestLastInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkRestLastInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkRestLastInParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkRestLastInStatements(body.statements, source, fileName)
                    is Expression -> checkRestLastInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkRestLastInParams(expr.parameters, source, fileName)
                expr.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is GetAccessor -> m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    is SetAccessor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is PropertyDeclaration -> m.initializer?.let { checkRestLastInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is ParenthesizedExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is AsExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                checkRestLastInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkRestLastInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkRestLastInExpr(expr.condition, source, fileName)
                checkRestLastInExpr(expr.whenTrue, source, fileName)
                checkRestLastInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkRestLastInExpr(expr.expression, source, fileName)
                for (a in expr.arguments) checkRestLastInExpr(a, source, fileName)
            }
            is NewExpression -> {
                checkRestLastInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkRestLastInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkRestLastInExpr(expr.expression, source, fileName)
                checkRestLastInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkRestLastInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkRestLastInExpr(prop.initializer, source, fileName)
                    is SpreadAssignment -> checkRestLastInExpr(prop.expression, source, fileName)
                    is MethodDeclaration -> {
                        checkRestLastInParams(prop.parameters, source, fileName)
                        prop.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is GetAccessor -> prop.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    is SetAccessor -> {
                        checkRestLastInParams(prop.parameters, source, fileName)
                        prop.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is SpreadElement -> checkRestLastInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkRestLastInExpr(it, source, fileName) }
            is VoidExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkRestLastInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkRestLastInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkRestLastInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkRestLastInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) checkRestLastInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkRestLastInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun checkRestLastInParams(params: List<Parameter>, source: String, fileName: String) {
        val realParams = params.filter { !it.isCommentPlaceholder }
        for (i in 0 until realParams.size - 1) {
            val param = realParams[i]
            if (param.dotDotDotToken) {
                // B18.2: suppress TS1014 when the FOLLOWING parameter was created via
                // B17.7's comma-recovery — the parser already emitted TS1005 for the
                // malformed `...x y` shape, and TypeScript treats it as the sole diagnostic.
                if (realParams[i + 1].commaRecovered) continue
                val name = param.name
                // TS1014 span covers only `...` (3 chars), not the param name
                val start = if (name is Identifier) name.pos - 3 else param.pos
                val length = 3  // just the `...` token
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "A rest parameter must be last in a parameter list.",
                    category = DiagnosticCategory.Error,
                    code = 1014,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // Rest element with property name in binding patterns (TS2566)
    // -----------------------------------------------------------------------

    private fun checkRestElementPropertyNames() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkRestElemPropNamesInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkRestElemPropNamesInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkRestElemPropNamesInStatement(stmt, source, fileName)
    }

    private fun checkRestElemPropNamesInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                checkRestElemPropNamesInBinding(d.name, source, fileName)
                d.initializer?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
            }
            is ExpressionStatement -> checkRestElemPropNamesInExpr(stmt.expression, source, fileName)
            is FunctionDeclaration -> {
                for (p in stmt.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                stmt.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is Constructor -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is GetAccessor -> m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                is SetAccessor -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is PropertyDeclaration -> m.initializer?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
                else -> {}
            }
            is Block -> checkRestElemPropNamesInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkRestElemPropNamesInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkRestElemPropNamesInStatement(it, source, fileName) }
            }
            is ForStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) for (d in init.declarations) checkRestElemPropNamesInBinding(d.name, source, fileName)
                checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) for (d in init.declarations) checkRestElemPropNamesInBinding(d.name, source, fileName)
                checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) for (d in init.declarations) checkRestElemPropNamesInBinding(d.name, source, fileName)
                checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkRestElemPropNamesInStatements(c.statements, source, fileName)
                    is DefaultClause -> checkRestElemPropNamesInStatements(c.statements, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkRestElemPropNamesInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkRestElemPropNamesInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkRestElemPropNamesInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
            is ExportAssignment -> checkRestElemPropNamesInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkRestElemPropNamesInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                for (p in expr.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkRestElemPropNamesInStatements(body.statements, source, fileName)
                    is Expression -> checkRestElemPropNamesInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                for (p in expr.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                expr.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
            }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is Constructor -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is GetAccessor -> m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                is SetAccessor -> {
                    for (p in m.parameters) checkRestElemPropNamesInBinding(p.name, source, fileName)
                    m.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is PropertyDeclaration -> m.initializer?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is AsExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right); cur = cur.left
                }
                // The left-most can be an Identifier for destructuring assignment — handled by BinaryExpression's right walk
                // Object destructuring assignment shows up as BinaryExpression with `=` operator and ObjectLiteralExpression on left.
                // Handle that case by checking each binary expression directly.
                checkRestElemPropNamesInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkRestElemPropNamesInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkRestElemPropNamesInExpr(expr.condition, source, fileName)
                checkRestElemPropNamesInExpr(expr.whenTrue, source, fileName)
                checkRestElemPropNamesInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkRestElemPropNamesInExpr(expr.expression, source, fileName)
                for (a in expr.arguments) checkRestElemPropNamesInExpr(a, source, fileName)
            }
            is NewExpression -> {
                checkRestElemPropNamesInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkRestElemPropNamesInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkRestElemPropNamesInExpr(expr.expression, source, fileName)
                checkRestElemPropNamesInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkRestElemPropNamesInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> checkRestElemPropNamesInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> checkRestElemPropNamesInExpr(p.expression, source, fileName)
                is MethodDeclaration -> {
                    for (param in p.parameters) checkRestElemPropNamesInBinding(param.name, source, fileName)
                    p.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                is GetAccessor -> p.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                is SetAccessor -> {
                    for (param in p.parameters) checkRestElemPropNamesInBinding(param.name, source, fileName)
                    p.body?.let { checkRestElemPropNamesInStatements(it.statements, source, fileName) }
                }
                else -> {}
            }
            is SpreadElement -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkRestElemPropNamesInExpr(it, source, fileName) }
            is VoidExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkRestElemPropNamesInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkRestElemPropNamesInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkRestElemPropNamesInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkRestElemPropNamesInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkRestElemPropNamesInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) checkRestElemPropNamesInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkRestElemPropNamesInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun checkRestElemPropNamesInBinding(node: Node, source: String, fileName: String) {
        when (node) {
            is ObjectBindingPattern -> for (elem in node.elements) {
                // TS2566: rest element cannot have a property name — e.g., { ...a: b }
                if (elem.dotDotDotToken && elem.propertyName != null) {
                    // The squiggle is at the binding name (after the colon), not the property name
                    val nameNode = elem.name
                    val start = when (nameNode) {
                        is Identifier -> nameNode.pos
                        else -> nameNode.pos
                    }
                    val length = when (nameNode) {
                        is Identifier -> nameNode.text.length
                        else -> 1
                    }
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "A rest element cannot have a property name.",
                        category = DiagnosticCategory.Error,
                        code = 2566,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                // Recurse into nested binding patterns
                checkRestElemPropNamesInBinding(elem.name, source, fileName)
            }
            is ArrayBindingPattern -> for (elem in node.elements) {
                if (elem is BindingElement) checkRestElemPropNamesInBinding(elem.name, source, fileName)
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Implementation in ambient context (TS1183)
    // -----------------------------------------------------------------------

    private fun checkAmbientImplementation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAmbientInStatements(result.sourceFile.statements, source, fileName, isAmbient = false)
        }
    }

    // TS2436: Ambient module declaration cannot specify relative module name.
    // Only fires in script context (non-module files). Module augmentation in module files is allowed.
    private fun checkAmbientRelativeModuleNames() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // Only check script files (not module files — module augmentation allows relative paths)
            if (isModuleFile(stmts)) continue
            for (stmt in stmts) {
                if (stmt !is ModuleDeclaration) continue
                if (ModifierFlag.Declare !in stmt.modifiers) continue
                val nameNode = stmt.name as? StringLiteralNode ?: continue
                val modulePath = nameNode.text
                // A module name is "relative" (per TS isExternalModuleNameRelative) if it is
                // path-relative (`./`, `../`) OR a rooted disk path (POSIX/UNC `/`/`\`, or a
                // drive-letter root `c:/`, `c:\`, or bare `c:`). B98.r10: `declare module "b:/block"`
                // is rooted (TS2436) but `declare module "b:block"` is NOT (drive-letter without a
                // following slash → not rooted, no error).
                val isRelative = modulePath.startsWith("./") || modulePath.startsWith("../") ||
                    modulePath.startsWith(".\\") || modulePath.startsWith("..\\")
                val isRooted = modulePath.startsWith("/") || modulePath.startsWith("\\") ||
                    (modulePath.length >= 2 && modulePath[1] == ':' && modulePath[0].isLetter() &&
                        (modulePath.length == 2 || modulePath[2] == '/' || modulePath[2] == '\\'))
                if (isRelative || isRooted) {
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Ambient module declaration cannot specify relative module name.",
                        category = DiagnosticCategory.Error,
                        code = 2436,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = nameNode.pos,
                        length = (nameNode.rawText?.length ?: modulePath.length) + 2,
                    ))
                }
            }
        }
    }

    private fun checkAmbientInStatements(stmts: List<Statement>, source: String, fileName: String, isAmbient: Boolean) {
        for (stmt in stmts) checkAmbientInStatement(stmt, source, fileName, isAmbient)
    }

    private fun checkAmbientInStatement(stmt: Statement, source: String, fileName: String, isAmbient: Boolean) {
        val isDeclare = when (stmt) {
            is ClassDeclaration -> ModifierFlag.Declare in stmt.modifiers
            is FunctionDeclaration -> ModifierFlag.Declare in stmt.modifiers
            is ModuleDeclaration -> ModifierFlag.Declare in stmt.modifiers
            else -> false
        }
        val ambient = isAmbient || isDeclare

        when (stmt) {
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is Constructor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is GetAccessor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is SetAccessor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        else -> {}
                    }
                }
            }
            is FunctionDeclaration -> {
                if (ambient && stmt.body != null) {
                    emitTS1183(stmt.body!!, source, fileName)
                }
                if (!ambient) stmt.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
            }
            is InterfaceDeclaration -> {
                // Interface members are always ambient
                for (m in stmt.members) {
                    when (m) {
                        is GetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        is SetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        is MethodDeclaration -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        else -> {}
                    }
                }
            }
            is TypeAliasDeclaration -> {
                // Type literal members with bodies — walk the type
                checkAmbientInType(stmt.type, source, fileName)
            }
            is ModuleDeclaration -> {
                // TS2436 handled separately in checkAmbientRelativeModuleNames()
                (stmt.body as? ModuleBlock)?.let { checkAmbientInStatements(it.statements, source, fileName, ambient) }
            }
            is Block -> checkAmbientInStatements(stmt.statements, source, fileName, isAmbient)
            is IfStatement -> {
                checkAmbientInStatement(stmt.thenStatement, source, fileName, isAmbient)
                stmt.elseStatement?.let { checkAmbientInStatement(it, source, fileName, isAmbient) }
            }
            is ForStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is ForInStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is ForOfStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is WhileStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is DoStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkAmbientInStatements(c.statements, source, fileName, isAmbient)
                    is DefaultClause -> checkAmbientInStatements(c.statements, source, fileName, isAmbient)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkAmbientInStatements(stmt.tryBlock.statements, source, fileName, isAmbient)
                stmt.catchClause?.let { checkAmbientInStatements(it.block.statements, source, fileName, isAmbient) }
                stmt.finallyBlock?.let { checkAmbientInStatements(it.statements, source, fileName, isAmbient) }
            }
            is LabeledStatement -> checkAmbientInStatement(stmt.statement, source, fileName, isAmbient)
            is ThrowStatement -> stmt.expression?.let { checkAmbientInExpr(it, source, fileName) }
            is ExportAssignment -> checkAmbientInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkAmbientInExpr(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkAmbientInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkAmbientInExpr(it, source, fileName) }
            else -> {}
        }
    }

    private fun checkAmbientInType(type: TypeNode, source: String, fileName: String) {
        if (type is TypeLiteral) {
            for (m in type.members) {
                when (m) {
                    is GetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    is SetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    is MethodDeclaration -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    else -> {}
                }
            }
        }
    }

    private fun checkAmbientInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ClassExpression -> {
                // Class expressions themselves are not ambient
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        is Constructor -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        // round 42 iter8: Get/SetAccessor body recursion + PropertyDeclaration init
                        is GetAccessor -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        is SetAccessor -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        is PropertyDeclaration -> m.initializer?.let { checkAmbientInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkAmbientInStatements(body.statements, source, fileName, false)
                is Expression -> checkAmbientInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
            is ParenthesizedExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is AsExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                checkAmbientInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkAmbientInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkAmbientInExpr(expr.condition, source, fileName)
                checkAmbientInExpr(expr.whenTrue, source, fileName)
                checkAmbientInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkAmbientInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkAmbientInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkAmbientInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkAmbientInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkAmbientInExpr(expr.expression, source, fileName)
                checkAmbientInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkAmbientInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> checkAmbientInExpr(p.initializer, source, fileName)
                    is SpreadAssignment -> checkAmbientInExpr(p.expression, source, fileName)
                    is MethodDeclaration -> p.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                    is GetAccessor -> p.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                    is SetAccessor -> p.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                    else -> {}
                }
            }
            is SpreadElement -> checkAmbientInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkAmbientInExpr(it, source, fileName) }
            is PrefixUnaryExpression -> checkAmbientInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkAmbientInExpr(expr.operand, source, fileName)
            is VoidExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkAmbientInExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkAmbientInExpr(span.expression, source, fileName)
            // round 42 iter8: TaggedTemplateExpression — recurse into tag + template spans
            is TaggedTemplateExpression -> {
                checkAmbientInExpr(expr.tag, source, fileName)
                val template = expr.template
                if (template is TemplateExpression) {
                    for (span in template.templateSpans) checkAmbientInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkAmbientInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun emitTS1183(body: Block, source: String, fileName: String) {
        // Skip synthetic empty bodies created by parser error recovery (pos = -1)
        if (body.pos < 0) return
        // Squiggle on the opening `{` only (1 char)
        val start = body.pos
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "An implementation cannot be declared in ambient contexts.",
            category = DiagnosticCategory.Error,
            code = 1183,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = 1,
        ))
    }

    // -----------------------------------------------------------------------
    // Arguments collision with rest parameters (TS2396)
    // -----------------------------------------------------------------------

    private fun checkArgumentsCollision() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isModule = isModuleFile(result.sourceFile.statements)
            checkArgsCollisionInStatements(result.sourceFile.statements, source, fileName, isModule)
        }
    }

    private fun checkArgsCollisionInStatements(stmts: List<Statement>, source: String, fileName: String, isModule: Boolean = false) {
        for (stmt in stmts) checkArgsCollisionInStatement(stmt, source, fileName, isModule)
    }

    private fun checkArgsCollisionInStatement(stmt: Statement, source: String, fileName: String, isModule: Boolean = false) {
        when (stmt) {
            is FunctionDeclaration -> {
                // Only check implementations (have body), skip overload signatures and declare
                if (stmt.body != null && ModifierFlag.Declare !in stmt.modifiers) {
                    checkArgsCollisionInParams(stmt.parameters, source, fileName, isModule)
                }
                stmt.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is ClassDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            if (!isDeclare && m.body != null) checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                            m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        }
                        is Constructor -> {
                            if (!isDeclare && m.body != null) checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                            m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        }
                        is GetAccessor -> m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        is SetAccessor -> m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> checkArgsCollisionInExpr(stmt.expression, source, fileName, isModule)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            }
            is ReturnStatement -> stmt.expression?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            is Block -> checkArgsCollisionInStatements(stmt.statements, source, fileName, isModule)
            is IfStatement -> {
                checkArgsCollisionInStatement(stmt.thenStatement, source, fileName, isModule)
                stmt.elseStatement?.let { checkArgsCollisionInStatement(it, source, fileName, isModule) }
            }
            is ForStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is ForInStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is ForOfStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is WhileStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is DoStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkArgsCollisionInStatements(c.statements, source, fileName, isModule)
                    is DefaultClause -> checkArgsCollisionInStatements(c.statements, source, fileName, isModule)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkArgsCollisionInStatements(stmt.tryBlock.statements, source, fileName, isModule)
                stmt.catchClause?.let { checkArgsCollisionInStatements(it.block.statements, source, fileName, isModule) }
                stmt.finallyBlock?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is LabeledStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is ThrowStatement -> stmt.expression?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            is ExportAssignment -> checkArgsCollisionInExpr(stmt.expression, source, fileName, isModule)
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    (stmt.body as? ModuleBlock)?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                }
            }
            else -> {}
        }
    }

    private fun checkArgsCollisionInExpr(expr: Expression, source: String, fileName: String, isModule: Boolean = false) {
        when (expr) {
            is ArrowFunction -> {
                checkArgsCollisionInParams(expr.parameters, source, fileName, isModule)
                when (val body = expr.body) {
                    is Block -> checkArgsCollisionInStatements(body.statements, source, fileName, isModule)
                    is Expression -> checkArgsCollisionInExpr(body, source, fileName, isModule)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkArgsCollisionInParams(expr.parameters, source, fileName, isModule)
                expr.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                        m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is Constructor -> {
                        checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                        m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is GetAccessor -> m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    is SetAccessor -> {
                        checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                        m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is PropertyDeclaration -> m.initializer?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
                    else -> {}
                }
            }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is MethodDeclaration -> {
                        checkArgsCollisionInParams(prop.parameters, source, fileName, isModule)
                        prop.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is GetAccessor -> prop.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    is SetAccessor -> {
                        checkArgsCollisionInParams(prop.parameters, source, fileName, isModule)
                        prop.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is PropertyAssignment -> checkArgsCollisionInExpr(prop.initializer, source, fileName, isModule)
                    is SpreadAssignment -> checkArgsCollisionInExpr(prop.expression, source, fileName, isModule)
                    else -> {}
                }
            }
            is ParenthesizedExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is AsExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is TypeAssertionExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is SatisfiesExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is NonNullExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is BinaryExpression -> {
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    checkArgsCollisionInExpr(cur.right, source, fileName, isModule)
                    cur = cur.left
                }
                checkArgsCollisionInExpr(cur, source, fileName, isModule)
            }
            is ConditionalExpression -> {
                checkArgsCollisionInExpr(expr.whenTrue, source, fileName, isModule)
                checkArgsCollisionInExpr(expr.whenFalse, source, fileName, isModule)
            }
            is CallExpression -> {
                checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
                expr.arguments.forEach { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            }
            is NewExpression -> {
                checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
                expr.arguments?.forEach { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            }
            is PropertyAccessExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is ElementAccessExpression -> {
                checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
                checkArgsCollisionInExpr(expr.argumentExpression, source, fileName, isModule)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            is SpreadElement -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is PrefixUnaryExpression -> checkArgsCollisionInExpr(expr.operand, source, fileName, isModule)
            is PostfixUnaryExpression -> checkArgsCollisionInExpr(expr.operand, source, fileName, isModule)
            is AwaitExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is YieldExpression -> expr.expression?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            is VoidExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is DeleteExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is TypeOfExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            is TemplateExpression -> expr.templateSpans.forEach { checkArgsCollisionInExpr(it.expression, source, fileName, isModule) }
            is TaggedTemplateExpression -> {
                checkArgsCollisionInExpr(expr.tag, source, fileName, isModule)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkArgsCollisionInExpr(it.expression, source, fileName, isModule)
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            else -> {}
        }
    }

    private fun checkArgsCollisionInParams(params: List<Parameter>, source: String, fileName: String, isModule: Boolean = false) {
        val hasRest = params.any { it.dotDotDotToken && !it.isCommentPlaceholder }
        // In module files (strict mode), "arguments" is always invalid as a parameter name (TS1215)
        // In non-module files, only check when rest params exist (TS2396)
        if (!hasRest && !isModule) return
        // Check each parameter for "arguments" name
        for (param in params) {
            if (param.isCommentPlaceholder) continue
            val name = param.name
            if (name is Identifier && name.text == "arguments") {
                // Span includes type annotation and modifier if present
                // For parameter properties (public/private/protected/readonly arguments),
                // start from the modifier position
                val hasParamModifier = param.modifiers.isNotEmpty()
                val start = if (param.dotDotDotToken) name.pos - 3
                    else if (hasParamModifier) param.pos
                    else name.pos
                val end = if (param.type != null) {
                    // end position is after the type text, minus trailing trivia
                    param.type!!.end - 1
                } else if (param.dotDotDotToken) {
                    name.pos + name.text.length
                } else {
                    name.pos + name.text.length
                }
                val length = (end - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                if (isModule) {
                    diagnostics.add(Diagnostic(
                        message = "Invalid use of 'arguments'. Modules are automatically in strict mode.",
                        category = DiagnosticCategory.Error,
                        code = 1215,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                } else {
                    diagnostics.add(Diagnostic(
                        message = "Duplicate identifier 'arguments'. Compiler uses 'arguments' to initialize rest parameters.",
                        category = DiagnosticCategory.Error,
                        code = 2396,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Initializers in ambient contexts (TS1039)
    // -----------------------------------------------------------------------

    private fun checkAmbientInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            // In .d.ts files every top-level declaration is implicitly ambient, so
            // initializers anywhere must emit TS1039 even without an explicit `declare`.
            val topLevelAmbient = isDtsFile(fileName)
            checkAmbientInitInStatements(result.sourceFile.statements, source, fileName, isAmbient = topLevelAmbient)
        }
    }

    /**
     * Returns true if the expression qualifies as a constant for ambient enum member initializers.
     * TS1066 fires when this returns false inside a declare enum.
     */
    private fun isConstantEnumMemberExpr(expr: Expression): Boolean = when (expr) {
        is NumericLiteralNode -> true
        is StringLiteralNode -> true
        is PrefixUnaryExpression -> (expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) &&
            expr.operand is NumericLiteralNode
        is BinaryExpression -> isConstantEnumMemberExpr(expr.left) && isConstantEnumMemberExpr(expr.right)
        is ParenthesizedExpression -> isConstantEnumMemberExpr(expr.expression)
        else -> false
    }

    /**
     * Computes the true end position of an expression in source text.
     *
     * In this AST, node.end includes the start of the NEXT scanned token
     * (because the parser calls getEnd() after nextToken()). This helper
     * recovers the actual end of the expression text by examining the
     * rightmost leaf of the expression tree.
     */
    private fun expressionTrueEnd(expr: Expression): Int = when (expr) {
        is NumericLiteralNode -> expr.pos + expr.text.length
        is BigIntLiteralNode -> expr.pos + expr.text.length
        is StringLiteralNode -> {
            val quoteCount = if (expr.isUnterminated) 1 else 2
            val content = expr.rawText ?: expr.text
            expr.pos + content.length + quoteCount
        }
        is Identifier -> expr.pos + expr.text.length
        is PrefixUnaryExpression -> expressionTrueEnd(expr.operand)
        is PostfixUnaryExpression -> expressionTrueEnd(expr.operand) + 2 // +2 for ++/-- chars
        is BinaryExpression -> expressionTrueEnd(expr.right)
        is ParenthesizedExpression -> {
            // Synthetic paren from instantiation expression (`obj.fn<T>`): use the
            // recorded type-args end so the squiggle covers `obj.fn<T>` (not just `obj.fn`).
            if (expr.instantiationEnd != null) expr.instantiationEnd!!
            else expressionTrueEnd(expr.expression) + 1 // +1 for closing )
        }
        is PropertyAccessExpression -> expr.name.pos + expr.name.text.length
        is ElementAccessExpression -> expressionTrueEnd(expr.argumentExpression) + 1 // +1 for ]
        is NonNullExpression -> expressionTrueEnd(expr.expression) + 1 // +1 for !
        is CallExpression -> {
            // end of closing ) after arguments
            if (expr.arguments.isNotEmpty()) expressionTrueEnd(expr.arguments.last()) + 1
            else if (!expr.typeArguments.isNullOrEmpty()) {
                // `f<T>()` — start from last type arg's end (already past `>`) + `()`
                expr.typeArguments!!.last().end + 2
            }
            else expressionTrueEnd(expr.expression) + 2 // +2 for empty `()`
        }
        is NewExpression -> {
            // new Foo() — end of closing ) after arguments
            if (expr.arguments?.isNotEmpty() == true) expressionTrueEnd(expr.arguments!!.last()) + 1
            else if (expr.arguments != null) {
                // `new Foo<T>()` or `new Foo()` — include type args when present
                if (!expr.typeArguments.isNullOrEmpty()) expr.typeArguments!!.last().end + 2
                else expressionTrueEnd(expr.expression) + 2 // +2 for ()
            }
            else if (!expr.typeArguments.isNullOrEmpty()) {
                // `new Foo<T>` (no parens, no args)
                expr.typeArguments!!.last().end
            }
            else expressionTrueEnd(expr.expression)
        }
        is ObjectLiteralExpression -> {
            // closeBracePos is position of `}`, +1 for the char itself
            if (expr.closeBracePos >= 0) expr.closeBracePos + 1 else expr.end
        }
        is ArrayLiteralExpression -> {
            // Last element end + closing `]`
            if (expr.elements.isNotEmpty()) expressionTrueEnd(expr.elements.last()) + 1
            else expr.pos + 2 // empty `[]`
        }
        is ArrowFunction -> {
            // Arrow function body end
            val body = expr.body
            when (body) {
                // Use closeBracePos when available (block.end overshoots by the next
                // token's pos, which can include trailing whitespace before the next
                // token — e.g. `(x) => { ... } )` overshoots by the space between
                // `}` and `)`. `closeBracePos + 1` lands exactly after `}`.
                is Block -> if (body.closeBracePos >= 0) body.closeBracePos + 1 else body.end - 1
                is Expression -> expressionTrueEnd(body)
                else -> expr.end
            }
        }
        is TypeOfExpression -> expressionTrueEnd(expr.expression)
        is VoidExpression -> expressionTrueEnd(expr.expression)
        is AwaitExpression -> expressionTrueEnd(expr.expression)
        is DeleteExpression -> expressionTrueEnd(expr.expression)
        is YieldExpression -> expr.expression?.let { expressionTrueEnd(it) } ?: (expr.pos + 5) // "yield"
        is SpreadElement -> expressionTrueEnd(expr.expression)
        is TypeAssertionExpression -> expressionTrueEnd(expr.expression)
        // For `as`, the end is after the type annotation; expr.end may overshoot
        // by one token, so prefer `type.end` when available, else fallback.
        is AsExpression -> expr.end
        // `expr satisfies T` — the satisfies type is the trailing token, so the
        // squiggle should cover through the type-annotation end.
        is SatisfiesExpression -> expr.type.end
        // round 42 iter3: NoSubstitutionTemplateLiteralNode is a backtick-quoted
        // string with no spans. End = `pos + text.length + quoteCount` matches
        // StringLiteralNode's pattern. Conservative: prefer expr.end when text
        // is empty (rare AST shape).
        is NoSubstitutionTemplateLiteralNode -> {
            if (expr.text.isEmpty()) expr.end
            else {
                val quoteCount = if (expr.isUnterminated) 1 else 2
                expr.pos + expr.text.length + quoteCount
            }
        }
        // round 42 iter19: TaggedTemplateExpression delegates to the template node's
        // expressionTrueEnd (which handles NoSubstitutionTemplateLiteralNode via iter3).
        // For TemplateExpression-template, falls back to the template's `.end` (overshoots
        // slightly but better than the tag's broader expr.end). Type args between tag and
        // template are part of the template's pos range.
        is TaggedTemplateExpression -> {
            when (val t = expr.template) {
                is Expression -> expressionTrueEnd(t)
                else -> expr.end
            }
        }
        else -> expr.end // fallback — may overshoot by one token for complex expressions
    }

    /** Check if an expression is a simple literal (allowed in `declare const x = ...`). */
    private fun isLiteralExpression(expr: Expression): Boolean = when (expr) {
        is NumericLiteralNode -> true
        is StringLiteralNode -> true
        is BigIntLiteralNode -> true
        is PrefixUnaryExpression -> expr.operator == SyntaxKind.Minus && isLiteralExpression(expr.operand)
        else -> false
    }

    private fun checkAmbientInitInStatements(stmts: List<Statement>, source: String, fileName: String, isAmbient: Boolean) {
        for (stmt in stmts) {
            val isDeclare = when (stmt) {
                is VariableStatement -> ModifierFlag.Declare in stmt.modifiers
                is ClassDeclaration -> ModifierFlag.Declare in stmt.modifiers
                is ModuleDeclaration -> ModifierFlag.Declare in stmt.modifiers
                is EnumDeclaration -> ModifierFlag.Declare in stmt.modifiers
                else -> false
            }
            val ambient = isAmbient || isDeclare
            when (stmt) {
                is EnumDeclaration -> {
                    if (ambient) {
                        for (member in stmt.members) {
                            val init = member.initializer ?: continue
                            if (!isConstantEnumMemberExpr(init)) {
                                val start = init.pos
                                val length = (expressionTrueEnd(init) - start).coerceAtLeast(1)
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "In ambient enum declarations member initializer must be constant expression.",
                                    category = DiagnosticCategory.Error,
                                    code = 1066,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                    }
                }
                is VariableStatement -> {
                    if (ambient) {
                        // TypeScript allows `declare const x = 123` (without type annotation) —
                        // the literal initializer serves as the type annotation.
                        // With explicit type annotation, TS1039 still fires.
                        val isConst = stmt.declarationList.flags == SyntaxKind.ConstKeyword
                        for (d in stmt.declarationList.declarations) {
                            val init = d.initializer ?: continue
                            // Skip TS1039 for `declare const x = <literal>` without type annotation
                            if (isConst && d.type == null && isLiteralExpression(init)) continue
                            val start = init.pos
                            val length = (init.end - 1 - start).coerceAtLeast(1)
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            // TS1254 for `declare const x = <non-literal>` without type annotation
                            val useTs1254 = isConst && d.type == null && !isLiteralExpression(init)
                            diagnostics.add(Diagnostic(
                                message = if (useTs1254) "A 'const' initializer in an ambient context must be a string or numeric literal or literal enum reference."
                                    else "Initializers are not allowed in ambient contexts.",
                                category = DiagnosticCategory.Error,
                                code = if (useTs1254) 1254 else 1039,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                is ClassDeclaration -> {
                    checkClassMemberModifiersForAmbient(stmt.members, ambient, source, fileName)
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let {
                        checkAmbientInitInStatements(it.statements, source, fileName, ambient)
                    }
                }
                is Block -> checkAmbientInitInStatements(stmt.statements, source, fileName, isAmbient)
                is FunctionDeclaration -> stmt.body?.let { checkAmbientInitInStatements(it.statements, source, fileName, false) }
                is IfStatement -> {
                    checkAmbientInitInStatements(listOf(stmt.thenStatement), source, fileName, isAmbient)
                    stmt.elseStatement?.let { checkAmbientInitInStatements(listOf(it), source, fileName, isAmbient) }
                }
                is ForStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                is ForInStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                is ForOfStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                is WhileStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                is DoStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkAmbientInitInStatements(clause.statements, source, fileName, isAmbient)
                        is DefaultClause -> checkAmbientInitInStatements(clause.statements, source, fileName, isAmbient)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    checkAmbientInitInStatements(stmt.tryBlock.statements, source, fileName, isAmbient)
                    stmt.catchClause?.let { checkAmbientInitInStatements(it.block.statements, source, fileName, isAmbient) }
                    stmt.finallyBlock?.let { checkAmbientInitInStatements(it.statements, source, fileName, isAmbient) }
                }
                is LabeledStatement -> checkAmbientInitInStatements(listOf(stmt.statement), source, fileName, isAmbient)
                else -> {}
            }
            // Also walk VariableStatement initializers for ClassExpressions (not ambient).
            if (stmt is VariableStatement) {
                for (d in stmt.declarationList.declarations) {
                    val init = d.initializer ?: continue
                    visitExprForClassExpression(init, ambient, source, fileName)
                }
            }
        }
    }

    /**
     * Emit TS1039 and TS1031 on class members. Used for both ClassDeclaration and ClassExpression.
     */
    private fun checkClassMemberModifiersForAmbient(
        members: List<ClassElement>, ambient: Boolean, source: String, fileName: String,
    ) {
        for (m in members) {
            if (m is PropertyDeclaration && m.initializer != null) {
                val memberAmbient = ambient || ModifierFlag.Declare in m.modifiers
                if (memberAmbient) {
                    val init = m.initializer!!
                    val start = init.pos
                    val length = (init.end - 1 - start).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Initializers are not allowed in ambient contexts.",
                        category = DiagnosticCategory.Error,
                        code = 1039,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            val exportStart = getModifierKeywordStart(m, "export", source) ?: continue
            val (line, character) = getLineAndCharacterOfPosition(source, exportStart)
            diagnostics.add(Diagnostic(
                message = "'export' modifier cannot appear on class elements of this kind.",
                category = DiagnosticCategory.Error,
                code = 1031,
                fileName = fileName,
                line = line,
                character = character,
                start = exportStart,
                length = 6,
            ))
        }
    }

    /** Walk an expression looking for ClassExpressions (and recurse into their members). */
    private fun visitExprForClassExpression(
        expr: Expression, ambient: Boolean, source: String, fileName: String,
    ) {
        when (expr) {
            is ClassExpression -> {
                checkClassMemberModifiersForAmbient(expr.members, ambient, source, fileName)
            }
            is ParenthesizedExpression -> visitExprForClassExpression(expr.expression, ambient, source, fileName)
            is BinaryExpression -> {
                visitExprForClassExpression(expr.left, ambient, source, fileName)
                visitExprForClassExpression(expr.right, ambient, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * If the class element has the given modifier flag, return the source position of the
     * modifier keyword (located by scanning backwards from the element's `pos` through the source
     * text). Returns null if the modifier isn't present or can't be located.
     */
    private fun getModifierKeywordStart(element: ClassElement, keyword: String, source: String): Int? {
        val mods = when (element) {
            is PropertyDeclaration -> element.modifiers
            is MethodDeclaration -> element.modifiers
            is Constructor -> element.modifiers
            is GetAccessor -> element.modifiers
            is SetAccessor -> element.modifiers
            else -> return null
        }
        val flag = when (keyword) {
            "export" -> ModifierFlag.Export
            "declare" -> ModifierFlag.Declare
            else -> return null
        }
        if (flag !in mods) return null
        val idx = source.indexOf(keyword, startIndex = element.pos)
        return if (idx in element.pos..<element.end) idx else null
    }

    // -----------------------------------------------------------------------
    // Multiple defaults in switch (TS1113)
    // -----------------------------------------------------------------------

    private fun checkMultipleDefaults() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkMultiDefaultsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkMultiDefaultsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkMultiDefaultsInStatement(stmt, source, fileName)
    }

    private fun checkMultiDefaultsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is SwitchStatement -> {
                var defaultSeen = false
                var errorEmitted = false
                for (c in stmt.caseBlock) {
                    if (c is DefaultClause) {
                        if (defaultSeen && !errorEmitted) {
                            val start = c.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "A 'default' clause cannot appear more than once in a 'switch' statement.",
                                category = DiagnosticCategory.Error,
                                code = 1113,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = 8, // "default:"
                            ))
                            errorEmitted = true
                        }
                        defaultSeen = true
                        checkMultiDefaultsInStatements(c.statements, source, fileName)
                    } else if (c is CaseClause) {
                        checkMultiDefaultsInStatements(c.statements, source, fileName)
                    }
                }
            }
            is Block -> checkMultiDefaultsInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkMultiDefaultsInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is IfStatement -> {
                checkMultiDefaultsInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkMultiDefaultsInStatement(it, source, fileName) }
            }
            is ForStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is TryStatement -> {
                checkMultiDefaultsInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkMultiDefaultsInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkMultiDefaultsInExpr(it, source, fileName) }
            is ExportAssignment -> checkMultiDefaultsInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkMultiDefaultsInExpr(it, source, fileName) }
            is ExpressionStatement -> checkMultiDefaultsInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkMultiDefaultsInExpr(it, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkMultiDefaultsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkMultiDefaultsInStatements(body.statements, source, fileName)
                is Expression -> checkMultiDefaultsInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            is ClassExpression -> for (member in expr.members) when (member) {
                is MethodDeclaration -> member.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is Constructor -> member.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is GetAccessor -> member.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is SetAccessor -> member.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> member.initializer?.let { checkMultiDefaultsInExpr(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is AsExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                checkMultiDefaultsInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkMultiDefaultsInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkMultiDefaultsInExpr(expr.condition, source, fileName)
                checkMultiDefaultsInExpr(expr.whenTrue, source, fileName)
                checkMultiDefaultsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkMultiDefaultsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkMultiDefaultsInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkMultiDefaultsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkMultiDefaultsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkMultiDefaultsInExpr(expr.expression, source, fileName)
                checkMultiDefaultsInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkMultiDefaultsInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> checkMultiDefaultsInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> checkMultiDefaultsInExpr(p.expression, source, fileName)
                is MethodDeclaration -> p.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is GetAccessor -> p.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                is SetAccessor -> p.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                else -> {}
            }
            is SpreadElement -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkMultiDefaultsInExpr(it, source, fileName) }
            is VoidExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkMultiDefaultsInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkMultiDefaultsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkMultiDefaultsInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkMultiDefaultsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkMultiDefaultsInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) checkMultiDefaultsInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkMultiDefaultsInExpr(e, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Switch/case literal-type comparability (TS2678)
    // -----------------------------------------------------------------------

    /**
     * Emits TS2678 "Type '<case>' is not comparable to type '<switch>'" when the
     * switch expression is a `const X = <literal>` (narrow literal type) and a case
     * clause uses a different literal of the same primitive kind.
     *
     * Narrow scope: only tracks const bindings in the SAME enclosing block as the
     * switch statement. Literal kinds: numeric, string, true, false, bigint.
     * `let`/`var` bindings are NOT tracked — they widen to their primitive type.
     */
    data class ConstLiteralBinding(val kind: String, val display: String)

    private fun literalKindDisplay(e: Expression): ConstLiteralBinding? = when (e) {
        is NumericLiteralNode -> ConstLiteralBinding("number", e.text)
        is StringLiteralNode -> ConstLiteralBinding("string", "\"${e.text}\"")
        is BigIntLiteralNode -> ConstLiteralBinding("bigint", e.text)
        is Identifier -> when (e.text) {
            "true" -> ConstLiteralBinding("boolean", "true")
            "false" -> ConstLiteralBinding("boolean", "false")
            else -> null
        }
        is PrefixUnaryExpression -> if (e.operator == SyntaxKind.Minus && e.operand is NumericLiteralNode) {
            ConstLiteralBinding("number", "-${(e.operand as NumericLiteralNode).text}")
        } else null
        else -> null
    }

    /**
     * Set of types a switch expression can match.
     * Each entry is (kind, exactDisplay) — exactDisplay=null means any value of that kind matches.
     * `display` is the human-readable form rendered in TS2678 messages.
     */
    private data class SwitchAllowedSet(val entries: List<Pair<String, String?>>, val display: String) {
        fun allows(b: ConstLiteralBinding): Boolean = entries.any { (k, exact) ->
            b.kind == k && (exact == null || exact == b.display)
        }
    }

    private fun allowedSetFromBinding(b: ConstLiteralBinding): SwitchAllowedSet =
        SwitchAllowedSet(listOf(b.kind to b.display), b.display)

    /** Extract a SwitchAllowedSet from a type-annotation node (UnionType or KeywordType / LiteralType).
     *  Returns null if the annotation contains anything we can't classify (Object, Reference, etc.). */
    private fun allowedSetFromTypeAnnotation(t: TypeNode, source: String): SwitchAllowedSet? {
        val types: List<TypeNode> = when (t) {
            is UnionType -> t.types
            else -> listOf(t)
        }
        val entries = mutableListOf<Pair<String, String?>>()
        val displayParts = mutableListOf<String>()
        for (tn in types) {
            when (tn) {
                is KeywordTypeNode -> when (tn.kind) {
                    SyntaxKind.NumberKeyword -> { entries.add("number" to null); displayParts.add("number") }
                    SyntaxKind.StringKeyword -> { entries.add("string" to null); displayParts.add("string") }
                    SyntaxKind.BooleanKeyword -> { entries.add("boolean" to null); displayParts.add("boolean") }
                    SyntaxKind.BigIntKeyword -> { entries.add("bigint" to null); displayParts.add("bigint") }
                    else -> return null
                }
                is LiteralType -> {
                    val b = literalKindDisplay(tn.literal) ?: return null
                    entries.add(b.kind to b.display)
                    displayParts.add(b.display)
                }
                else -> return null
            }
        }
        return SwitchAllowedSet(entries, displayParts.joinToString(" | "))
    }

    private fun checkSwitchCaseComparable() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkSwitchCaseComparable(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkSwitchCaseComparable(stmts: List<Statement>, source: String, fileName: String) {
        val constBindings = mutableMapOf<String, ConstLiteralBinding>()
        // Variables declared with explicit type annotation (e.g. `declare var r: number | "hello"`).
        val annotatedBindings = mutableMapOf<String, SwitchAllowedSet>()
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                        for (d in stmt.declarationList.declarations) {
                            val name = d.name as? Identifier ?: continue
                            // Skip when there's a type annotation that would widen the literal
                            if (d.type != null) continue
                            val init = d.initializer ?: continue
                            val binding = literalKindDisplay(init) ?: continue
                            constBindings[name.text] = binding
                        }
                    }
                    // Pick up type-annotated declarations regardless of `var`/`let`/`const`.
                    for (d in stmt.declarationList.declarations) {
                        val name = d.name as? Identifier ?: continue
                        val ann = d.type ?: continue
                        val allowed = allowedSetFromTypeAnnotation(ann, source) ?: continue
                        annotatedBindings[name.text] = allowed
                    }
                    // Walk initializers for nested switch/blocks
                    for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { walkSwitchCaseComparableInExpr(it, source, fileName) }
                    }
                }
                is SwitchStatement -> {
                    // Check case clauses if the switch expression resolves to a known set of types.
                    val expr = stmt.expression
                    val allowed: SwitchAllowedSet? = when (expr) {
                        is Identifier -> annotatedBindings[expr.text]
                            ?: constBindings[expr.text]?.let { allowedSetFromBinding(it) }
                        else -> literalKindDisplay(expr)?.let { allowedSetFromBinding(it) }
                    }
                    if (allowed != null) {
                        for (c in stmt.caseBlock) {
                            if (c !is CaseClause) continue
                            // 17.198: TS2678 for `case <ClassIdent>` — class identifier
                            // resolves to `typeof Class`, never comparable to a literal
                            // type. Display: `typeof <ClassName>`.
                            val caseExpr = c.expression
                            if (caseExpr is Identifier) {
                                val sym = globals[caseExpr.text]
                                val isPureClass = sym != null && sym.flags.hasAny(SymbolFlags.Class) &&
                                    !sym.flags.hasAny(SymbolFlags.Module or SymbolFlags.Alias or SymbolFlags.Variable or SymbolFlags.Function) &&
                                    sym.declarations.size == 1 &&
                                    sym.valueDeclaration is ClassDeclaration
                                if (isPureClass) {
                                    val (line, character) = getLineAndCharacterOfPosition(source, caseExpr.pos)
                                    diagnostics.add(Diagnostic(
                                        message = "Type 'typeof ${caseExpr.text}' is not comparable to type '${allowed.display}'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2678,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = caseExpr.pos,
                                        length = caseExpr.text.length,
                                    ))
                                    continue
                                }
                            }
                            val caseBinding = literalKindDisplay(c.expression) ?: continue
                            // Emit TS2678 when the case literal is NOT in the allowed set.
                            if (!allowed.allows(caseBinding)) {
                                val (line, character) = getLineAndCharacterOfPosition(source, c.expression.pos)
                                val length = when (val ce = c.expression) {
                                    is NumericLiteralNode -> ce.text.length
                                    is StringLiteralNode -> ce.text.length + 2
                                    is BigIntLiteralNode -> ce.text.length
                                    is Identifier -> ce.text.length
                                    is PrefixUnaryExpression -> if (ce.operand is NumericLiteralNode) 1 + (ce.operand as NumericLiteralNode).text.length else 1
                                    else -> 1
                                }
                                diagnostics.add(Diagnostic(
                                    message = "Type '${caseBinding.display}' is not comparable to type '${allowed.display}'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2678,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = c.expression.pos,
                                    length = length,
                                ))
                            }
                        }
                    }
                    // Recurse into case statement bodies
                    for (c in stmt.caseBlock) {
                        when (c) {
                            is CaseClause -> walkSwitchCaseComparable(c.statements, source, fileName)
                            is DefaultClause -> walkSwitchCaseComparable(c.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is Block -> walkSwitchCaseComparable(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkSwitchCaseComparableStmt(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { walkSwitchCaseComparableStmt(it, source, fileName) }
                }
                is ForStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is ForInStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is ForOfStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is WhileStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is DoStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is TryStatement -> {
                    walkSwitchCaseComparable(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkSwitchCaseComparable(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                }
                is FunctionDeclaration -> stmt.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is ClassDeclaration -> for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                        else -> {}
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is ExpressionStatement -> walkSwitchCaseComparableInExpr(stmt.expression, source, fileName)
                is LabeledStatement -> walkSwitchCaseComparableStmt(stmt.statement, source, fileName)
                is ReturnStatement -> stmt.expression?.let { walkSwitchCaseComparableInExpr(it, source, fileName) }
                is ThrowStatement -> stmt.expression?.let { walkSwitchCaseComparableInExpr(it, source, fileName) }
                is ExportAssignment -> walkSwitchCaseComparableInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun walkSwitchCaseComparableStmt(stmt: Statement, source: String, fileName: String) {
        walkSwitchCaseComparable(listOf(stmt), source, fileName)
    }

    private fun walkSwitchCaseComparableInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> walkSwitchCaseComparable(body.statements, source, fileName)
                is Expression -> walkSwitchCaseComparableInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
            is ClassExpression -> for (member in expr.members) when (member) {
                is MethodDeclaration -> member.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is Constructor -> member.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is GetAccessor -> member.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is SetAccessor -> member.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is PropertyDeclaration -> member.initializer?.let { walkSwitchCaseComparableInExpr(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is AsExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkSwitchCaseComparableInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) walkSwitchCaseComparableInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                walkSwitchCaseComparableInExpr(expr.condition, source, fileName)
                walkSwitchCaseComparableInExpr(expr.whenTrue, source, fileName)
                walkSwitchCaseComparableInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) walkSwitchCaseComparableInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkSwitchCaseComparableInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
                walkSwitchCaseComparableInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) walkSwitchCaseComparableInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> walkSwitchCaseComparableInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> walkSwitchCaseComparableInExpr(p.expression, source, fileName)
                is MethodDeclaration -> p.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is GetAccessor -> p.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                is SetAccessor -> p.body?.let { walkSwitchCaseComparable(it.statements, source, fileName) }
                else -> {}
            }
            is SpreadElement -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkSwitchCaseComparableInExpr(it, source, fileName) }
            is VoidExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkSwitchCaseComparableInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkSwitchCaseComparableInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkSwitchCaseComparableInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkSwitchCaseComparableInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkSwitchCaseComparableInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkSwitchCaseComparableInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkSwitchCaseComparableInExpr(e, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Interface property initializers (TS1246)
    // -----------------------------------------------------------------------

    private fun checkInterfacePropertyInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                checkInterfacePropInit(stmt, source, fileName)
            }
        }
    }

    // -----------------------------------------------------------------------
    // Await in non-async context (TS1308) / for await in non-async (TS1103)
    // -----------------------------------------------------------------------

    /**
     * Tracks the enclosing function for the "Did you mean to mark this function as 'async'?" related info.
     */
    private data class FuncRef(val pos: Int, val length: Int)

    private fun makeAsyncRelated(funcRef: FuncRef?, source: String, fileName: String): List<Diagnostic> {
        if (funcRef == null) return emptyList()
        val (relLine, relChar) = getLineAndCharacterOfPosition(source, funcRef.pos)
        return listOf(Diagnostic(
            message = "Did you mean to mark this function as 'async'?",
            category = DiagnosticCategory.Message,
            code = 1356,
            fileName = fileName,
            line = relLine,
            character = relChar,
            start = funcRef.pos,
            length = funcRef.length,
        ))
    }

    private fun checkAwaitContext() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Top level of modules is OK for await
            val isModule = result.sourceFile.statements.any { stmt ->
                stmt is ImportDeclaration || stmt is ExportDeclaration ||
                (stmt is ExportAssignment) ||
                (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) ||
                (stmt is FunctionDeclaration && ModifierFlag.Export in stmt.modifiers) ||
                (stmt is ClassDeclaration && ModifierFlag.Export in stmt.modifiers)
            }
            checkAwaitInStatements(result.sourceFile.statements, source, fileName, isAsync = isModule)
        }
    }

    private fun checkAwaitInStatements(stmts: List<Statement>, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        for (stmt in stmts) checkAwaitInStatement(stmt, source, fileName, isAsync, enclosingFunc)
    }

    private fun checkAwaitInStatement(stmt: Statement, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        when (stmt) {
            is ExpressionStatement -> checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ReturnStatement -> stmt.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is FunctionDeclaration -> {
                val async = ModifierFlag.Async in stmt.modifiers
                val funcRef = if (!async && stmt.name != null) FuncRef(stmt.name.pos, stmt.name.text.length) else null
                stmt.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, funcRef) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            val async = ModifierFlag.Async in m.modifiers
                            val mRef = if (!async) { val mid = m.name as? Identifier; if (mid != null) FuncRef(mid.pos, mid.text.length) else null } else null
                            m.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, mRef) }
                        }
                        is Constructor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is PropertyDeclaration -> m.initializer?.let { checkAwaitInExpr(it, source, fileName, false, null) }
                        is GetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is SetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        else -> {}
                    }
                }
            }
            is Block -> checkAwaitInStatements(stmt.statements, source, fileName, isAsync, enclosingFunc)
            is IfStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.thenStatement, source, fileName, isAsync, enclosingFunc)
                stmt.elseStatement?.let { checkAwaitInStatement(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ForStatement -> {
                stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> for (d in init.declarations) {
                            d.initializer?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
                        }
                        is Expression -> checkAwaitInExpr(init, source, fileName, isAsync, enclosingFunc)
                        else -> {}
                    }
                }
                stmt.condition?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
                stmt.incrementor?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is ForOfStatement -> {
                if (stmt.awaitModifier && !isAsync) {
                    // TS1103: 'for await' loops are only allowed within async functions and at the top levels of modules.
                    val forStart = stmt.pos
                    val awaitIdx = source.indexOf("await", forStart)
                    if (awaitIdx >= 0 && awaitIdx < forStart + 20) {
                        val (line, character) = getLineAndCharacterOfPosition(source, awaitIdx)
                        diagnostics.add(Diagnostic(
                            message = "'for await' loops are only allowed within async functions and at the top levels of modules.",
                            category = DiagnosticCategory.Error,
                            code = 1103,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = awaitIdx,
                            length = 5, // "await"
                            relatedInformation = makeAsyncRelated(enclosingFunc, source, fileName),
                        ))
                    }
                }
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is ForInStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is WhileStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is DoStatement -> {
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
            }
            is TryStatement -> {
                checkAwaitInStatements(stmt.tryBlock.statements, source, fileName, isAsync, enclosingFunc)
                stmt.catchClause?.let { checkAwaitInStatements(it.block.statements, source, fileName, isAsync, enclosingFunc) }
                stmt.finallyBlock?.let { checkAwaitInStatements(it.statements, source, fileName, isAsync, enclosingFunc) }
            }
            is SwitchStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> {
                            checkAwaitInExpr(c.expression, source, fileName, isAsync, enclosingFunc)
                            checkAwaitInStatements(c.statements, source, fileName, isAsync, enclosingFunc)
                        }
                        is DefaultClause -> checkAwaitInStatements(c.statements, source, fileName, isAsync, enclosingFunc)
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is LabeledStatement -> checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            is ExportAssignment -> checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAwaitInStatements(it.statements, source, fileName, isAsync, enclosingFunc) }
            else -> {}
        }
    }

    private fun checkAwaitInExpr(expr: Expression, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        when (expr) {
            is AwaitExpression -> {
                if (!isAsync) {
                    val start = expr.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val relatedInfo = makeAsyncRelated(enclosingFunc, source, fileName)
                    diagnostics.add(Diagnostic(
                        message = "'await' expressions are only allowed within async functions and at the top levels of modules.",
                        category = DiagnosticCategory.Error,
                        code = 1308,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = 5, // "await"
                        relatedInformation = relatedInfo,
                    ))
                }
                expr.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ArrowFunction -> {
                val async = ModifierFlag.Async in expr.modifiers
                // For the related info, point to the opening paren of the params
                val arrowRef = if (!async) {
                    val paramStart = if (expr.hasParenthesizedParameters) {
                        // Find the '(' — typically at expr.pos or just before parameters
                        val firstParam = expr.parameters.firstOrNull()
                        if (firstParam != null) {
                            // The '(' is right before the first parameter
                            val searchStart = expr.pos
                            val parenIdx = source.indexOf('(', searchStart)
                            if (parenIdx >= 0 && parenIdx < firstParam.pos) parenIdx else expr.pos
                        } else expr.pos
                    } else expr.pos
                    FuncRef(paramStart, 1) // just the '(' character
                } else null
                when (val body = expr.body) {
                    is Block -> checkAwaitInStatements(body.statements, source, fileName, async, arrowRef)
                    is Expression -> checkAwaitInExpr(body, source, fileName, async, arrowRef)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                val async = ModifierFlag.Async in expr.modifiers
                val fRef = if (!async) {
                    if (expr.name != null) FuncRef(expr.name.pos, expr.name.text.length)
                    else FuncRef(expr.pos, 8) // "function" keyword length
                } else null
                expr.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, fRef) }
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            val async = ModifierFlag.Async in m.modifiers
                            val mRef = if (!async) { val mid = m.name as? Identifier; if (mid != null) FuncRef(mid.pos, mid.text.length) else null } else null
                            m.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, mRef) }
                        }
                        is Constructor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is PropertyDeclaration -> m.initializer?.let { checkAwaitInExpr(it, source, fileName, false, null) }
                        is GetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is SetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        else -> {}
                    }
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkAwaitInExpr(current.right, source, fileName, isAsync, enclosingFunc)
                    current = current.left
                }
                checkAwaitInExpr(current, source, fileName, isAsync, enclosingFunc)
            }
            is CallExpression -> {
                // 17.175: TS2311 — `await(...)` in a sync function parses as
                // CallExpression with Identifier "await" as callee. The `await`
                // keyword is reserved only in async/module contexts; outside,
                // it's a regular identifier — but referencing it here is almost
                // certainly a missing-async mistake.
                val callee = expr.expression
                if (!isAsync && callee is Identifier && callee.text == "await") {
                    val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                    diagnostics.add(Diagnostic(
                        message = "Cannot find name 'await'. Did you mean to write this in an async function?",
                        category = DiagnosticCategory.Error,
                        code = 2311,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = callee.pos,
                        length = 5,
                    ))
                }
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                for (arg in expr.arguments) checkAwaitInExpr(arg, source, fileName, isAsync, enclosingFunc)
            }
            is NewExpression -> {
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                expr.arguments?.forEach { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ParenthesizedExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is ConditionalExpression -> {
                checkAwaitInExpr(expr.condition, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.whenTrue, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.whenFalse, source, fileName, isAsync, enclosingFunc)
            }
            is PropertyAccessExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is ElementAccessExpression -> {
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.argumentExpression, source, fileName, isAsync, enclosingFunc)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkAwaitInExpr(el, source, fileName, isAsync, enclosingFunc)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkAwaitInExpr(prop.initializer, source, fileName, isAsync, enclosingFunc)
                    is SpreadAssignment -> checkAwaitInExpr(prop.expression, source, fileName, isAsync, enclosingFunc)
                    is MethodDeclaration -> {
                        val async = ModifierFlag.Async in prop.modifiers
                        val pRef = if (!async) { val pid = prop.name as? Identifier; if (pid != null) FuncRef(pid.pos, pid.text.length) else null } else null
                        prop.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, pRef) }
                    }
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkAwaitInExpr(span.expression, source, fileName, isAsync, enclosingFunc)
            }
            is PrefixUnaryExpression -> checkAwaitInExpr(expr.operand, source, fileName, isAsync, enclosingFunc)
            is PostfixUnaryExpression -> checkAwaitInExpr(expr.operand, source, fileName, isAsync, enclosingFunc)
            is SpreadElement -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is NonNullExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is AsExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is TypeAssertionExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is SatisfiesExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is YieldExpression -> expr.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is TaggedTemplateExpression -> {
                checkAwaitInExpr(expr.tag, source, fileName, isAsync, enclosingFunc)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkAwaitInExpr(it.expression, source, fileName, isAsync, enclosingFunc)
                }
            }
            is VoidExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is DeleteExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is TypeOfExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is CommaListExpression -> for (el in expr.elements) checkAwaitInExpr(el, source, fileName, isAsync, enclosingFunc)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2397: Declaration name conflicts with built-in global identifier
    // -----------------------------------------------------------------------

    private fun checkBuiltinGlobalConflict() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // In module files, top-level declarations are module-scoped — they don't conflict
            // with built-in globals like `globalThis`. TS2397 only fires in script files.
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            checkBuiltinGlobalInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkBuiltinGlobalInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier && name.text in BUILTIN_GLOBAL_CONFLICT_NAMES) {
                            reportBuiltinGlobalConflict(name, source, fileName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val name = stmt.name
                    if (name is Identifier && name.text in BUILTIN_GLOBAL_CONFLICT_NAMES) {
                        reportBuiltinGlobalConflict(name, source, fileName)
                    }
                    (stmt.body as? ModuleBlock)?.let { checkBuiltinGlobalInStatements(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    private fun reportBuiltinGlobalConflict(name: Identifier, source: String, fileName: String) {
        val start = name.pos
        val length = name.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Declaration name conflicts with built-in global identifier '${name.text}'.",
            category = DiagnosticCategory.Error,
            code = 2397,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Interface property initializer checking (TS1246)
    // -----------------------------------------------------------------------

    private fun checkInterfacePropInit(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                for (m in stmt.members) {
                    if (m is PropertyDeclaration && m.initializer != null) {
                        val init = m.initializer!!
                        val start = init.pos
                        val length = (init.end - 1 - start).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "An interface property cannot have an initializer.",
                            category = DiagnosticCategory.Error,
                            code = 1246,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) checkInterfacePropInit(s, source, fileName)
            }
            is Block -> for (s in stmt.statements) checkInterfacePropInit(s, source, fileName)
            is IfStatement -> {
                checkInterfacePropInit(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkInterfacePropInit(it, source, fileName) }
            }
            is ForStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            is ForInStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            is ForOfStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            is WhileStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            is DoStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                when (clause) {
                    is CaseClause -> for (s in clause.statements) checkInterfacePropInit(s, source, fileName)
                    is DefaultClause -> for (s in clause.statements) checkInterfacePropInit(s, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkInterfacePropInit(s, source, fileName)
                stmt.catchClause?.let { for (s in it.block.statements) checkInterfacePropInit(s, source, fileName) }
                stmt.finallyBlock?.let { for (s in it.statements) checkInterfacePropInit(s, source, fileName) }
            }
            is LabeledStatement -> checkInterfacePropInit(stmt.statement, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1166 / TS1169: Computed property names in classes / interfaces must
    // refer to literal or 'unique symbol' types.
    // -----------------------------------------------------------------------

    private fun checkComputedPropertyNameLiteral() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                checkComputedPropNameInStmt(stmt, source, fileName)
            }
        }
    }

    private fun checkComputedPropNameInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> for (m in stmt.members) {
                if (m is PropertyDeclaration) {
                    val name = m.name
                    if (name is ComputedPropertyName && !isLiteralLikeExpr(name.expression)) {
                        emitComputedPropNameNonLiteral(name, source, fileName, 1169,
                            "A computed property name in an interface must refer to an expression whose type is a literal type or a 'unique symbol' type.")
                    }
                }
            }
            is ClassDeclaration -> for (m in stmt.members) {
                if (m is PropertyDeclaration) {
                    val name = m.name
                    if (name is ComputedPropertyName && !isLiteralLikeExpr(name.expression)) {
                        emitComputedPropNameNonLiteral(name, source, fileName, 1166,
                            "A computed property name in a class property declaration must have a simple literal type or a 'unique symbol' type.")
                    }
                }
                // round 42 iter4: recurse into nested member bodies so nested
                // Class/Interface declarations inside member bodies are also covered.
                when (m) {
                    is MethodDeclaration -> m.body?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
                    is Constructor -> m.body?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
                    is GetAccessor -> m.body?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
                    is SetAccessor -> m.body?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName)
            }
            is Block -> for (s in stmt.statements) checkComputedPropNameInStmt(s, source, fileName)
            is IfStatement -> {
                checkComputedPropNameInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkComputedPropNameInStmt(it, source, fileName) }
            }
            is ForStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is ForInStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is WhileStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is DoStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                when (clause) {
                    is CaseClause -> for (s in clause.statements) checkComputedPropNameInStmt(s, source, fileName)
                    is DefaultClause -> for (s in clause.statements) checkComputedPropNameInStmt(s, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkComputedPropNameInStmt(s, source, fileName)
                stmt.catchClause?.let { for (s in it.block.statements) checkComputedPropNameInStmt(s, source, fileName) }
                stmt.finallyBlock?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
            }
            is LabeledStatement -> checkComputedPropNameInStmt(stmt.statement, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { for (s in it.statements) checkComputedPropNameInStmt(s, source, fileName) }
            else -> {}
        }
    }

    /** Conservative check: only obviously non-literal expressions return false.
     * Returns true for patterns TypeScript typically accepts (literals,
     * negative-literal unary, and dotted names like `Symbol.iterator` or
     * `NS.x` which may resolve to unique-symbol / literal const types).
     * Returning true avoids a false-positive TS1166/TS1169 on patterns we
     * can't verify without full type inference. */
    private fun isLiteralLikeExpr(expr: Expression): Boolean {
        return when (expr) {
            is StringLiteralNode -> true
            is NumericLiteralNode -> true
            is BigIntLiteralNode -> true
            is NoSubstitutionTemplateLiteralNode -> true
            is Identifier -> expr.text == "true" || expr.text == "false" || expr.text == "null" || expr.text == "undefined" ||
                // Accept other identifiers conservatively — they could resolve to unique-symbol consts or literal-type vars
                true
            is PrefixUnaryExpression -> expr.operand is NumericLiteralNode || expr.operand is BigIntLiteralNode
            is PropertyAccessExpression -> true // Symbol.iterator, NS.x etc. — accept conservatively
            is ParenthesizedExpression -> isLiteralLikeExpr(expr.expression)
            is BinaryExpression -> false
            is CallExpression -> false
            is ObjectLiteralExpression -> false
            is ArrayLiteralExpression -> false
            is FunctionExpression -> false
            is ArrowFunction -> false
            is NewExpression -> false
            else -> true // unknown node types — be conservative
        }
    }

    private fun emitComputedPropNameNonLiteral(
        name: ComputedPropertyName, source: String, fileName: String,
        code: Int, message: String,
    ) {
        val start = name.pos
        val closeIdx = source.indexOf(']', name.expression.pos)
        if (closeIdx < 0) return
        val length = closeIdx + 1 - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // B9.4: TS2537 — Type '{}' has no matching index signature for type 'X'.
    //
    // Fires for computed-property destructuring inside an ObjectBindingPattern
    // parameter that defaulted to `{}` via B9.2 (no annotation, no initializer).
    // -----------------------------------------------------------------------

    private fun checkBindingPatternComputedIndexSig() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkB94InStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkB94InStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkB94InStmt(stmt, source, fileName)
    }

    private fun walkB94InStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                decl.initializer?.let { walkB94InExpr(it, source, fileName) }
            }
            is ExpressionStatement -> walkB94InExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { walkB94InExpr(it, source, fileName) }
            is FunctionDeclaration -> {
                stmt.body?.let { walkB94InStmts(it.statements, source, fileName) }
                for (param in stmt.parameters) {
                    param.initializer?.let { walkB94InExpr(it, source, fileName) }
                }
            }
            is ClassDeclaration -> for (member in stmt.members) when (member) {
                is MethodDeclaration -> member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                is Constructor -> member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                is PropertyDeclaration -> member.initializer?.let { walkB94InExpr(it, source, fileName) }
                is GetAccessor -> member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                is SetAccessor -> member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                else -> {}
            }
            is Block -> walkB94InStmts(stmt.statements, source, fileName)
            is IfStatement -> {
                walkB94InExpr(stmt.expression, source, fileName)
                walkB94InStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkB94InStmt(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.initializer?.let { walkB94InExpr(it, source, fileName) }
                    }
                    is Expression -> walkB94InExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { walkB94InExpr(it, source, fileName) }
                stmt.incrementor?.let { walkB94InExpr(it, source, fileName) }
                walkB94InStmt(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                walkB94InExpr(stmt.expression, source, fileName)
                walkB94InStmt(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                walkB94InExpr(stmt.expression, source, fileName)
                walkB94InStmt(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                walkB94InExpr(stmt.expression, source, fileName)
                walkB94InStmt(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                walkB94InStmt(stmt.statement, source, fileName)
                walkB94InExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                walkB94InExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        walkB94InExpr(clause.expression, source, fileName)
                        walkB94InStmts(clause.statements, source, fileName)
                    }
                    is DefaultClause -> walkB94InStmts(clause.statements, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                walkB94InStmts(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkB94InStmts(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkB94InStmts(it.statements, source, fileName) }
            }
            is LabeledStatement -> walkB94InStmt(stmt.statement, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                walkB94InStmts(it.statements, source, fileName)
            }
            is ThrowStatement -> stmt.expression?.let { walkB94InExpr(it, source, fileName) }
            is ExportAssignment -> walkB94InExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkB94InExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                emitB94ForFnLikeParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> walkB94InStmts(body.statements, source, fileName)
                    is Expression -> walkB94InExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                emitB94ForFnLikeParams(expr.parameters, source, fileName)
                walkB94InStmts(expr.body.statements, source, fileName)
            }
            is ParenthesizedExpression -> walkB94InExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                walkB94InExpr(expr.condition, source, fileName)
                walkB94InExpr(expr.whenTrue, source, fileName)
                walkB94InExpr(expr.whenFalse, source, fileName)
            }
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkB94InExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) walkB94InExpr(rightStack.removeLast(), source, fileName)
            }
            is CallExpression -> {
                walkB94InExpr(expr.expression, source, fileName)
                expr.arguments.forEach { walkB94InExpr(it, source, fileName) }
            }
            is NewExpression -> {
                walkB94InExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkB94InExpr(it, source, fileName) }
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkB94InExpr(it, source, fileName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkB94InExpr(prop.initializer, source, fileName)
                is SpreadAssignment -> walkB94InExpr(prop.expression, source, fileName)
                is MethodDeclaration -> {
                    emitB94ForFnLikeParams(prop.parameters, source, fileName)
                    prop.body?.let { walkB94InStmts(it.statements, source, fileName) }
                }
                is GetAccessor -> prop.body?.let { walkB94InStmts(it.statements, source, fileName) }
                is SetAccessor -> {
                    emitB94ForFnLikeParams(prop.parameters, source, fileName)
                    prop.body?.let { walkB94InStmts(it.statements, source, fileName) }
                }
                else -> {}
            }
            is ClassExpression -> for (member in expr.members) when (member) {
                is MethodDeclaration -> {
                    emitB94ForFnLikeParams(member.parameters, source, fileName)
                    member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                }
                is Constructor -> {
                    emitB94ForFnLikeParams(member.parameters, source, fileName)
                    member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                }
                is PropertyDeclaration -> member.initializer?.let { walkB94InExpr(it, source, fileName) }
                is GetAccessor -> member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                is SetAccessor -> {
                    emitB94ForFnLikeParams(member.parameters, source, fileName)
                    member.body?.let { walkB94InStmts(it.statements, source, fileName) }
                }
                else -> {}
            }
            is AsExpression -> walkB94InExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkB94InExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkB94InExpr(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { walkB94InExpr(it, source, fileName) }
            is TemplateExpression -> for (span in expr.templateSpans) walkB94InExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkB94InExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkB94InExpr(span.expression, source, fileName)
                }
            }
            is SpreadElement -> walkB94InExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkB94InExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkB94InExpr(it, source, fileName) }
            is VoidExpression -> walkB94InExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkB94InExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkB94InExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkB94InExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkB94InExpr(expr.operand, source, fileName)
            is PropertyAccessExpression -> walkB94InExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkB94InExpr(expr.expression, source, fileName)
                walkB94InExpr(expr.argumentExpression, source, fileName)
            }
            is TypeAssertionExpression -> walkB94InExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    private fun emitB94ForFnLikeParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            // Trigger ONLY when the parameter shape matches B9.2's `{}` default
            // (binding-pattern name + no annotation + no initializer). Annotated
            // / defaulted patterns have a real declared type; checking those
            // against an index signature requires the full structural-comparison
            // path and is out of scope for B9.4.
            if (param.type != null) continue
            if (param.initializer != null) continue
            val pattern = param.name as? ObjectBindingPattern ?: continue
            for (element in pattern.elements) {
                val computed = element.propertyName as? ComputedPropertyName ?: continue
                val indexExpr = computed.expression
                // Skip literal-type computed names (`[2]`, `["a"]`, `` [`key`] ``).
                // TypeScript treats those as property-name lookups against the empty
                // `{}` type, not index-signature lookups — TS2537 doesn't fire.
                if (isLiteralComputedKeyExpr(indexExpr)) continue
                val indexType = try { getTypeOfExpression(indexExpr) } catch (_: Throwable) { continue }
                if (indexType === errorType || indexType === anyType) continue
                // Only emit when the index type is a primitive that would require
                // an index signature to match. TypeScript displays the widened
                // form (`'a'` → `string`).
                val widened = getWidenedLiteralType(indexType)
                val typeDisplay = typeToString(widened)
                if (typeDisplay.isEmpty()) continue
                val start = indexExpr.pos
                val length = expressionTrueEnd(indexExpr) - start
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '{}' has no matching index signature for type '$typeDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2537,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    private fun isLiteralComputedKeyExpr(expr: Expression): Boolean = when (expr) {
        is StringLiteralNode -> true
        is NumericLiteralNode -> true
        is BigIntLiteralNode -> true
        is NoSubstitutionTemplateLiteralNode -> true
        is PrefixUnaryExpression -> (expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) &&
            (expr.operand is NumericLiteralNode || expr.operand is BigIntLiteralNode)
        is ParenthesizedExpression -> isLiteralComputedKeyExpr(expr.expression)
        else -> false
    }

    // -----------------------------------------------------------------------
    // TS1294: `erasableSyntaxOnly` — narrow scope, TypeAssertion only
    // -----------------------------------------------------------------------

    private fun checkErasableSyntaxOnly() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                walkTypeAssertionsInStmt(stmt, source, fileName, ::emitErasableTypeAssertion)
            }
        }
    }

    private fun walkTypeAssertionsInStmt(
        stmt: Statement, source: String, fileName: String,
        onAssertion: (TypeAssertionExpression, String, String) -> Unit,
    ) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
            }
            is ExpressionStatement -> walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
            is Block -> for (s in stmt.statements) walkTypeAssertionsInStmt(s, source, fileName, onAssertion)
            is IfStatement -> {
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
                walkTypeAssertionsInStmt(stmt.thenStatement, source, fileName, onAssertion)
                stmt.elseStatement?.let { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
            }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                    it.initializer?.let { i -> walkTypeAssertionsInExpr(i, source, fileName, onAssertion) }
                }
                stmt.condition?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                stmt.incrementor?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
            }
            is ForInStatement -> {
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
                walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
            }
            is ForOfStatement -> {
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
                walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
            }
            is WhileStatement -> {
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
                walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
            }
            is DoStatement -> {
                walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
            }
            is LabeledStatement -> walkTypeAssertionsInStmt(stmt.statement, source, fileName, onAssertion)
            is ExportAssignment -> walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
            is ReturnStatement -> stmt.expression?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
            is ThrowStatement -> stmt.expression?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) walkTypeAssertionsInStmt(s, source, fileName, onAssertion)
                stmt.catchClause?.block?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                stmt.finallyBlock?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
            }
            is SwitchStatement -> {
                walkTypeAssertionsInExpr(stmt.expression, source, fileName, onAssertion)
                for (clause in stmt.caseBlock) {
                    (clause as? CaseClause)?.expression?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                    val stmts = (clause as? CaseClause)?.statements ?: (clause as? DefaultClause)?.statements
                    stmts?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                }
            }
            is FunctionDeclaration -> stmt.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is Constructor -> m.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is GetAccessor -> m.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is SetAccessor -> m.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is PropertyDeclaration -> m.initializer?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
            else -> {}
        }
    }

    private fun walkTypeAssertionsInExpr(
        expr: Expression, source: String, fileName: String,
        onAssertion: (TypeAssertionExpression, String, String) -> Unit,
    ) {
        when (expr) {
            is TypeAssertionExpression -> {
                onAssertion(expr, source, fileName)
                walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            }
            is ParenthesizedExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is BinaryExpression -> {
                // Flatten the left-spine iteratively to avoid StackOverflow on
                // deeply nested binary chains (`a + b + c + ... + z`).
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                walkTypeAssertionsInExpr(cur, source, fileName, onAssertion)
                while (rightStack.isNotEmpty()) {
                    walkTypeAssertionsInExpr(rightStack.removeLast(), source, fileName, onAssertion)
                }
            }
            is CallExpression -> {
                walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
                for (a in expr.arguments) walkTypeAssertionsInExpr(a, source, fileName, onAssertion)
            }
            is NewExpression -> {
                walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
                expr.arguments?.forEach { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
            }
            is PropertyAccessExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is ElementAccessExpression -> {
                walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
                walkTypeAssertionsInExpr(expr.argumentExpression, source, fileName, onAssertion)
            }
            is ConditionalExpression -> {
                walkTypeAssertionsInExpr(expr.condition, source, fileName, onAssertion)
                walkTypeAssertionsInExpr(expr.whenTrue, source, fileName, onAssertion)
                walkTypeAssertionsInExpr(expr.whenFalse, source, fileName, onAssertion)
            }
            is PrefixUnaryExpression -> walkTypeAssertionsInExpr(expr.operand, source, fileName, onAssertion)
            is PostfixUnaryExpression -> walkTypeAssertionsInExpr(expr.operand, source, fileName, onAssertion)
            is ArrayLiteralExpression -> for (e in expr.elements) walkTypeAssertionsInExpr(e, source, fileName, onAssertion)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> walkTypeAssertionsInExpr(p.initializer, source, fileName, onAssertion)
                    is SpreadAssignment -> walkTypeAssertionsInExpr(p.expression, source, fileName, onAssertion)
                    is MethodDeclaration -> p.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is GetAccessor -> p.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    is SetAccessor -> p.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                    else -> {}
                }
            }
            is SpreadElement -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is YieldExpression -> expr.expression?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
            is AwaitExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            // B65.3: recurse through `void` / `typeof` / `delete` / non-null assertion
            // so a TypeAssertionExpression nested inside (e.g. `typeof <T>expr`) is
            // still visited by the TS2352 walker.
            is VoidExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is TypeOfExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is DeleteExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is NonNullExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is AsExpression -> {
                if (inNullCastOverlapPass) {
                    emitTS2352IfNullAsReadonlyTuple(expr, source, fileName)
                    emitTS2352IfNullAsCast(expr, source, fileName)
                }
                walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            }
            is SatisfiesExpression -> walkTypeAssertionsInExpr(expr.expression, source, fileName, onAssertion)
            is TemplateExpression -> for (span in expr.templateSpans) walkTypeAssertionsInExpr(span.expression, source, fileName, onAssertion)
            is TaggedTemplateExpression -> {
                walkTypeAssertionsInExpr(expr.tag, source, fileName, onAssertion)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkTypeAssertionsInExpr(span.expression, source, fileName, onAssertion)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkTypeAssertionsInExpr(e, source, fileName, onAssertion)
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> body.statements.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                is Expression -> walkTypeAssertionsInExpr(body, source, fileName, onAssertion)
                else -> {}
            }
            is FunctionExpression -> expr.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
            is ClassExpression -> for (member in expr.members) when (member) {
                is MethodDeclaration -> member.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                is Constructor -> member.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                is GetAccessor -> member.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                is SetAccessor -> member.body?.statements?.forEach { walkTypeAssertionsInStmt(it, source, fileName, onAssertion) }
                is PropertyDeclaration -> member.initializer?.let { walkTypeAssertionsInExpr(it, source, fileName, onAssertion) }
                else -> {}
            }
            else -> {}
        }
    }

    private fun emitErasableTypeAssertion(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        val start = expr.pos
        val length = (expr.headerEnd - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This syntax is not allowed when 'erasableSyntaxOnly' is enabled.",
            category = DiagnosticCategory.Error,
            code = 1294,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2352: Type assertion from 'null' to a named Class/Interface
    // -----------------------------------------------------------------------

    /**
     * Emits TS2352 "Conversion of type 'null' to type 'X' may be a mistake because
     * neither type sufficiently overlaps with the other." for `<T>null` casts where
     * T is a named Interface/Class (not a TypeAlias, and not any/unknown). `null!`
     * is skipped — the NonNullExpression wraps the null literal and shouldn't match.
     */
    /** B87.2 (round 73): when true, the [walkTypeAssertionsInExpr] AsExpression
     *  branch also runs the narrow `undefined/null as readonly [tuple]` TS2352
     *  check. Only the null-cast-overlap pass sets it — the unrelated erasable-
     *  syntax pass leaves it false, so no double emission. */
    private var inNullCastOverlapPass = false

    private fun checkNullTypeAssertionOverlap() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            val savedPass = inNullCastOverlapPass
            inNullCastOverlapPass = true
            try {
                for (stmt in result.sourceFile.statements) {
                    walkTypeAssertionsInStmt(stmt, source, fileName, ::emitTS2352IfNullCast)
                }
            } finally {
                inNullCastOverlapPass = savedPass
                currentFileLocals = savedLocals
            }
        }
    }

    /**
     * B87.2 (round 73): TS2352 for `undefined as readonly [...]` / `null as readonly [...]`
     * AsExpression casts. The shared [walkTypeAssertionsInExpr] visits AsExpression but
     * only forwards TypeAssertionExpression to the emit callback, so AsExpression casts
     * were never checked. Narrowly gated: source is bare `undefined`/`null`/`void <expr>`,
     * target is `readonly [tuple]` (TypeOperator over a TupleType) — neither sufficiently
     * overlaps. Span = the whole `<src> as <type>` (expr.pos .. tightEnd).
     */
    private fun emitTS2352IfNullAsReadonlyTuple(expr: AsExpression, source: String, fileName: String) {
        var inner: Expression = expr.expression
        if (inner is ParenthesizedExpression) inner = inner.expression
        val srcLit: String = when {
            inner is Identifier && (inner.text == "undefined" || inner.text == "null") -> inner.text
            inner is VoidExpression -> "undefined"
            else -> return
        }
        val t = expr.type
        if (t !is TypeOperator || t.operator != SyntaxKind.ReadonlyKeyword) return
        if (t.type !is TupleType) return
        // formatTypeForDisplay doesn't render the `readonly` TypeOperator, so build
        // `readonly <tuple>` explicitly from the inner tuple's display.
        val tupleDisplay = formatTypeForDisplay(t.type) ?: return
        val targetDisplay = "readonly $tupleDisplay"
        val start = expr.pos
        val end = if (expr.tightEnd > start) expr.tightEnd else expr.end
        val length = (end - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Conversion of type '$srcLit' to type '$targetDisplay' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2352IfNullCast(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        emitTS2352NullishCastCore(
            expr.expression, expr.type, expr.pos, expressionTrueEnd(expr.expression), source, fileName,
        )
    }

    /** B95d (round 82): `undefined as number` / `null as Foo` AsExpression form. The shared
     *  [walkTypeAssertionsInExpr] visits AsExpression but only forwards TypeAssertionExpression
     *  to the emit callback, so `as` casts were never checked by [emitTS2352IfNullCast]. Same
     *  gate; span = the whole `<src> as <type>` (expr.pos .. tightEnd). */
    private fun emitTS2352IfNullAsCast(expr: AsExpression, source: String, fileName: String) {
        val spanEnd = if (expr.tightEnd > expr.pos) expr.tightEnd else expr.end
        emitTS2352NullishCastCore(expr.expression, expr.type, expr.pos, spanEnd, source, fileName)
    }

    /** Shared core for TS2352 nullish/primitive-mismatch cast diagnostics (both `<T>x` and
     *  `x as T` forms). [rawInner] = source expr, [typeNode] = target type, span = [spanStart]..[spanEnd]. */
    private fun emitTS2352NullishCastCore(
        rawInner: Expression, typeNode: TypeNode, spanStart: Int, spanEnd: Int, source: String, fileName: String,
    ) {
        // B51.6: also catch `<FuncType>(undefined)` casts (matching
        // `defaultValueInFunctionTypes_ts`). Source must be a bare `null` or
        // `undefined` Identifier; unwrap one level of ParenthesizedExpression.
        // B65.3: also accept a `VoidExpression` source (`void <expr>` always
        // produces `undefined`) — display as `undefined`.
        // B65.4: also accept Identifier source whose declared type is a
        // concrete primitive different from the target primitive
        // (`<boolean>(n)` where `n: number`).
        var inner: Expression = rawInner
        if (inner is ParenthesizedExpression) inner = inner.expression
        val identType: Type? = if (inner is Identifier && inner.text != "null" && inner.text != "undefined") {
            try { getTypeOfIdentifier(inner) } catch (_: StackOverflowError) { null }
        } else null
        val sourceLit: String = when {
            inner is Identifier && (inner.text == "null" || inner.text == "undefined") -> inner.text
            inner is VoidExpression -> "undefined"
            identType is Type.Intrinsic && identType.intrinsicName in
                setOf("number", "string", "boolean", "bigint", "symbol") -> identType.intrinsicName
            else -> return
        }
        // 17.109: Compute the display name and gate on type-shape.
        // Allowed shapes (`null` doesn't sufficiently overlap):
        //   - TypeReference to named Class or Interface (not TypeAlias)
        //   - FunctionType, ConstructorType (function/constructor type expressions)
        //   - TypeLiteral with at least one member (object/call/construct/index sig)
        // Skipped: lib `Object`/`Function` (accept null-like values), TypeAlias,
        // empty `{}`, and any other type form.
        val name: String = when (typeNode) {
            is TypeReference -> {
                val typeName = typeNode.typeName as? Identifier ?: return
                val n = typeName.text
                val sym = currentFileLocals?.get(n) ?: globals[n] ?: return
                val isClassOrInterface = sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)
                        && !sym.flags.hasAny(SymbolFlags.TypeAlias or SymbolFlags.Module)
                if (!isClassOrInterface) return
                // Skip lib-declared Object/Function — their interfaces accept null-like values.
                if (n == "Object" || n == "Function") return
                n
            }
            is FunctionType, is ConstructorType -> formatTypeForDisplay(typeNode) ?: return
            is TypeLiteral -> {
                // Skip empty `{}` — too permissive (Object-like).
                if (typeNode.members.isEmpty()) return
                formatTypeForDisplay(typeNode) ?: return
            }
            is ArrayType, is TupleType -> formatTypeForDisplay(typeNode) ?: return
            // B65.3: primitive keyword targets when source is `void <expr>` (always undefined)
            // — `<number>void foo` is TS2352. Skip `any`/`unknown`/`void`/`null`/`undefined`
            // (those overlap with undefined).
            is KeywordTypeNode -> {
                val tgtName = when (typeNode.kind) {
                    SyntaxKind.NumberKeyword -> "number"
                    SyntaxKind.StringKeyword -> "string"
                    SyntaxKind.BooleanKeyword -> "boolean"
                    SyntaxKind.BigIntKeyword -> "bigint"
                    SyntaxKind.SymbolKeyword -> "symbol"
                    SyntaxKind.NeverKeyword -> "never"
                    SyntaxKind.ObjectKeyword -> "object"
                    else -> return
                }
                // B65.4: when the source is a typed primitive Identifier, only fire
                // when source and target primitives are DIFFERENT (`<number>n` where
                // `n: number` is a no-op, not an error).
                if (identType != null && sourceLit == tgtName) return
                tgtName
            }
            else -> return
        }

        val length = (spanEnd - spanStart).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
        diagnostics.add(Diagnostic(
            message = "Conversion of type '$sourceLit' to type '$name' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = spanStart,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // B60.3: TS2352 for `<TypeParam>concrete-subtype` casts
    // -----------------------------------------------------------------------
    /**
     * Emits TS2352 "Conversion of type 'X' to type 'T' may be a mistake..."
     * for `<T>expr` casts where:
     *   - T is a TypeParam (in the enclosing function/method's scope)
     *   - T has a constraint C
     *   - expr's type S is a STRICT subtype of C — i.e. assignable to C
     *     but C NOT assignable to S
     * The "strict subtype" gate prevents firing for `<T>a` where a's type IS
     * the constraint (no overlap mismatch). The chain matches B60.2's
     * "constraint-assignable" form.
     *
     * Walks per-function so TypeParams from the enclosing function are visible.
     */
    private fun checkTypeParamStrictSubtypeCast() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                walkStmtsForTypeParamCasts(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    private fun walkStmtsForTypeParamCasts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val savedScope = currentTypeParamScope
                    val tps = stmt.typeParameters
                    if (!tps.isNullOrEmpty()) {
                        val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                        val newOnes = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
                        for (tp in tps) {
                            val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                                val p = Type.TypeParam()
                                p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                                p
                            }
                            scope[tp.name.text] = typeParam
                            newOnes.add(tp to typeParam)
                        }
                        currentTypeParamScope = scope
                        for ((tp, typeParam) in newOnes) {
                            if (typeParam.constraint == null) {
                                tp.constraint?.let { typeParam.constraint = getTypeFromTypeNode(it) }
                            }
                        }
                    }
                    try {
                        stmt.body?.statements?.let { walkStmtsForTypeParamCasts(it, source, fileName) }
                    } finally {
                        currentTypeParamScope = savedScope
                    }
                }
                is ClassDeclaration -> {
                    // B60.18: push class's TypeParams onto scope so member bodies can see them.
                    val savedClassScope = currentTypeParamScope
                    val savedClassAst = currentTypeParamAstForOps
                    val classTps = stmt.typeParameters
                    if (!classTps.isNullOrEmpty()) {
                        val scope = currentTypeParamScope?.toMutableMap() ?: mutableMapOf()
                        val astScope = currentTypeParamAstForOps?.toMutableMap() ?: mutableMapOf()
                        val newOnes = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
                        for (tp in classTps) {
                            val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                                val p = Type.TypeParam()
                                p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                                p
                            }
                            scope[tp.name.text] = typeParam
                            astScope[tp.name.text] = tp
                            newOnes.add(tp to typeParam)
                        }
                        currentTypeParamScope = scope
                        currentTypeParamAstForOps = astScope
                        for ((tp, typeParam) in newOnes) {
                            if (typeParam.constraint == null) {
                                tp.constraint?.let {
                                    try { typeParam.constraint = getTypeFromTypeNode(it) }
                                    catch (_: StackOverflowError) { /* circular */ }
                                }
                            }
                        }
                    }
                    try {
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { body ->
                                val savedScope = currentTypeParamScope
                                val savedAst = currentTypeParamAstForOps
                                val savedLocalTypes = currentLocalTypes
                                val tps = m.typeParameters
                                if (!tps.isNullOrEmpty()) {
                                    val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                                    val astScope = currentTypeParamAstForOps?.toMutableMap() ?: mutableMapOf()
                                    val newOnes = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
                                    for (tp in tps) {
                                        val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                                            val p = Type.TypeParam()
                                            p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                                            p
                                        }
                                        scope[tp.name.text] = typeParam
                                        astScope[tp.name.text] = tp
                                        newOnes.add(tp to typeParam)
                                    }
                                    currentTypeParamScope = scope
                                    currentTypeParamAstForOps = astScope
                                    for ((tp, typeParam) in newOnes) {
                                        if (typeParam.constraint == null) {
                                            tp.constraint?.let { typeParam.constraint = getTypeFromTypeNode(it) }
                                        }
                                    }
                                }
                                // Populate currentLocalTypes with parameter types so
                                // assertion-walker can resolve `<T>param` source.
                                currentLocalTypes = currentLocalTypes.toMutableMap()
                                for (param in m.parameters) {
                                    val paramName = param.name as? Identifier ?: continue
                                    val paramType = param.type ?: continue
                                    try {
                                        val resolved = getTypeFromTypeNode(paramType)
                                        if (resolved !== errorType && resolved !== anyType) {
                                            currentLocalTypes[paramName.text] = resolved
                                        }
                                    } catch (_: StackOverflowError) { /* circular */ }
                                }
                                try {
                                    walkStmtsForTypeParamCasts(body.statements, source, fileName)
                                } finally {
                                    currentTypeParamScope = savedScope
                                    currentTypeParamAstForOps = savedAst
                                    currentLocalTypes = savedLocalTypes
                                }
                            }
                            is Constructor -> m.body?.statements?.let { walkStmtsForTypeParamCasts(it, source, fileName) }
                            else -> {}
                        }
                    }
                    } finally {
                        currentTypeParamScope = savedClassScope
                        currentTypeParamAstForOps = savedClassAst
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.let {
                    walkStmtsForTypeParamCasts(it, source, fileName)
                }
                else -> walkTypeAssertionsInStmt(stmt, source, fileName, ::emitTS2352IfTypeParamStrictSubtypeCast)
            }
        }
    }

    private fun emitTS2352IfTypeParamStrictSubtypeCast(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        val typeNode = expr.type as? TypeReference ?: return
        val typeName = typeNode.typeName as? Identifier ?: return
        // Target must be a TypeParam in scope.
        val tp = currentTypeParamScope?.get(typeName.text) ?: return
        // B60.18: TypeParam→TypeParam cast where both are unconstrained and differ.
        // Emit TS2352 with "'T' could be instantiated with an arbitrary type..." chain
        // and TS2208 "This type parameter might need an `extends T` constraint." on src.
        if (tp.constraint == null) {
            val srcType = try { getTypeOfExpression(expr.expression) } catch (_: Throwable) { return }
            if (srcType !is Type.TypeParam) return
            if (srcType === tp) return
            if (srcType.constraint != null) return  // src is constrained; different shape
            val srcName = srcType.symbol?.name ?: return
            val tgtName = typeName.text
            if (srcName == tgtName) return
            val srcTpDecl = currentTypeParamAstForOps?.get(srcName)
            val start = expr.pos
            val endPos = expressionTrueEnd(expr.expression)
            val length = (endPos - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            val related = mutableListOf<Diagnostic>()
            if (srcTpDecl != null) {
                val (relLine, relChar) = getLineAndCharacterOfPosition(source, srcTpDecl.name.pos)
                related.add(Diagnostic(
                    message = "This type parameter might need an `extends $tgtName` constraint.",
                    category = DiagnosticCategory.Message, code = 2208,
                    fileName = fileName, line = relLine, character = relChar,
                    start = srcTpDecl.name.pos, length = srcTpDecl.name.text.length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Conversion of type '$srcName' to type '$tgtName' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                category = DiagnosticCategory.Error, code = 2352,
                fileName = fileName, line = line, character = character,
                start = start, length = length,
                messageChain = listOf(
                    "  '$tgtName' could be instantiated with an arbitrary type which could be unrelated to '$srcName'.",
                ),
                relatedInformation = if (related.isEmpty()) emptyList() else related.toList(),
            ))
            return
        }
        val constraint = tp.constraint ?: return
        if (constraint === anyType || constraint === errorType) return
        // Get source expression's type.
        val srcType = try { getTypeOfExpression(expr.expression) } catch (_: Throwable) { return }
        if (srcType === anyType || srcType === errorType) return
        if (srcType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
        // B60.18b: src is also a constrained TypeParam different from tgt — emit
        // TS2352 with "X is assignable to the constraint of type T, but T could be
        // instantiated with a different subtype of constraint Y". Both sides relate
        // via apparent type (per CLAUDE.md gotcha) so the strict-subtype check below
        // wouldn't fire — handle this case explicitly.
        if (srcType is Type.TypeParam && srcType !== tp) {
            val srcConstraint = srcType.constraint
            if (srcConstraint != null && srcConstraint !== anyType && srcConstraint !== errorType) {
                val srcAssignableToTgtConstraint = try { checkTypeRelatedTo(srcConstraint, constraint, assignableRelation) }
                    catch (_: Throwable) { false }
                if (srcAssignableToTgtConstraint) {
                    val srcName = srcType.symbol?.name ?: return
                    val tgtName = typeName.text
                    if (srcName != tgtName) {
                        val start = expr.pos
                        val endPos = expressionTrueEnd(expr.expression)
                        val length = (endPos - start).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        val constraintDisplay = typeToString(constraint)
                        diagnostics.add(Diagnostic(
                            message = "Conversion of type '$srcName' to type '$tgtName' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                            category = DiagnosticCategory.Error, code = 2352,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                            messageChain = listOf(
                                "  '$srcName' is assignable to the constraint of type '$tgtName', but '$tgtName' could be instantiated with a different subtype of constraint '$constraintDisplay'.",
                            ),
                        ))
                        return
                    }
                }
            }
        }
        // Strict subtype: src ≤ constraint AND constraint NOT ≤ src.
        val srcToConstraint = try { checkTypeRelatedTo(srcType, constraint, assignableRelation) }
            catch (_: Throwable) { return }
        if (!srcToConstraint) return
        val constraintToSrc = try { checkTypeRelatedTo(constraint, srcType, assignableRelation) }
            catch (_: Throwable) { return }
        if (constraintToSrc) return  // bidirectional → sufficient overlap
        // Emit TS2352 at the assertion span.
        val start = expr.pos
        val endPos = expressionTrueEnd(expr.expression)
        val length = (endPos - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val srcDisplay = typeToString(srcType)
        val tpName = typeName.text
        val constraintDisplay = typeToString(constraint)
        diagnostics.add(Diagnostic(
            message = "Conversion of type '$srcDisplay' to type '$tpName' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf("  '$srcDisplay' is assignable to the constraint of type '$tpName', but '$tpName' could be instantiated with a different subtype of constraint '$constraintDisplay'."),
        ))
    }

    // -----------------------------------------------------------------------
    // B60.10: TS2313 "Type parameter 'T' has a circular constraint"
    // -----------------------------------------------------------------------
    /**
     * Walks all functions/classes/interfaces/type-aliases and reports TS2313
     * when a TypeParam's constraint chain cycles back to itself.
     * Direct self-reference: `<T extends T>`. Indirect cycle:
     * `<T extends U, U extends T>` (not yet handled — direct only for now).
     */
    private fun checkTypeParamCircularConstraint() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkStmtsForCircularConstraint(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkStmtsForCircularConstraint(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    checkTypeParamsCircular(stmt.typeParameters, source, fileName)
                    stmt.body?.statements?.let { walkStmtsForCircularConstraint(it, source, fileName) }
                }
                is ClassDeclaration -> {
                    checkTypeParamsCircular(stmt.typeParameters, source, fileName)
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> {
                                checkTypeParamsCircular(m.typeParameters, source, fileName)
                                m.body?.statements?.let { walkStmtsForCircularConstraint(it, source, fileName) }
                            }
                            is Constructor -> m.body?.statements?.let { walkStmtsForCircularConstraint(it, source, fileName) }
                            is GetAccessor -> m.body?.statements?.let { walkStmtsForCircularConstraint(it, source, fileName) }
                            is SetAccessor -> m.body?.statements?.let { walkStmtsForCircularConstraint(it, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    checkTypeParamsCircular(stmt.typeParameters, source, fileName)
                }
                is TypeAliasDeclaration -> {
                    checkTypeParamsCircular(stmt.typeParameters, source, fileName)
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.let {
                    walkStmtsForCircularConstraint(it, source, fileName)
                }
                is Block -> walkStmtsForCircularConstraint(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkStmtsForCircularConstraint(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkStmtsForCircularConstraint(listOf(it), source, fileName) }
                }
                is ForStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkStmtsForCircularConstraint(clause.statements, source, fileName)
                        is DefaultClause -> walkStmtsForCircularConstraint(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkStmtsForCircularConstraint(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkStmtsForCircularConstraint(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkStmtsForCircularConstraint(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkStmtsForCircularConstraint(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkTypeParamsCircular(tps: List<TypeParameter>?, source: String, fileName: String) {
        if (tps.isNullOrEmpty()) return
        val byName = tps.associateBy { it.name.text }
        for (tp in tps) {
            // Walk constraint chain up to 8 levels looking for back-reference.
            val visited = mutableSetOf(tp.name.text)
            var cur: TypeParameter? = tp
            var depth = 0
            while (cur != null && depth++ < 8) {
                val cnstr = cur.constraint as? TypeReference ?: break
                val cnstrName = (cnstr.typeName as? Identifier)?.text ?: break
                if (cnstrName in visited) {
                    // Circular: emit TS2313 at the constraint TypeReference's position.
                    val cnstrPos = cnstr.pos
                    val cnstrLen = cnstrName.length
                    val (line, char) = getLineAndCharacterOfPosition(source, cnstrPos)
                    diagnostics.add(Diagnostic(
                        message = "Type parameter '${tp.name.text}' has a circular constraint.",
                        category = DiagnosticCategory.Error,
                        code = 2313,
                        fileName = fileName,
                        line = line,
                        character = char,
                        start = cnstrPos,
                        length = cnstrLen,
                    ))
                    break
                }
                visited.add(cnstrName)
                cur = byName[cnstrName]
            }
        }
    }

    // -----------------------------------------------------------------------
    // B60.12: TS2349 / TS2351 / TS2339 for operations on effectively-unconstrained
    // TypeParam-typed expressions.
    // -----------------------------------------------------------------------
    /**
     * For `var x: T` where T is an effectively-unconstrained TypeParam (no
     * constraint, or self-circular `T extends T`):
     *   x.foo  → TS2339 "Property 'foo' does not exist on type 'T'."
     *   x()    → TS2349 + chain "Type '{}' has no call signatures."
     *   new x()→ TS2351 + chain "Type '{}' has no construct signatures."
     *
     * TypeScript's apparent type for such a TypeParam is `{}`, which has no
     * call/construct signatures and no own properties.
     */
    private fun checkTypeParamTypedOps() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                walkStmtsForTypeParamOps(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    private fun walkStmtsForTypeParamOps(stmts: List<Statement>, source: String, fileName: String) {
        val emptyVars = mutableMapOf<String, TypeParameter>()
        for (stmt in stmts) walkStmtForTypeParamOps(stmt, source, fileName, emptyVars)
    }

    private fun walkStmtForTypeParamOps(
        stmt: Statement, source: String, fileName: String,
        tpVars: MutableMap<String, TypeParameter>,
    ) {
        when (stmt) {
            is ClassDeclaration -> {
                val savedScope = currentTypeParamScope
                val savedAst = currentTypeParamAstForOps
                val tps = stmt.typeParameters
                if (!tps.isNullOrEmpty()) {
                    val scope = currentTypeParamScope?.toMutableMap() ?: mutableMapOf()
                    val astScope = currentTypeParamAstForOps?.toMutableMap() ?: mutableMapOf()
                    val newOnes = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
                    for (tp in tps) {
                        val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                            val p = Type.TypeParam()
                            p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                            p
                        }
                        scope[tp.name.text] = typeParam
                        astScope[tp.name.text] = tp
                        newOnes.add(tp to typeParam)
                    }
                    currentTypeParamScope = scope
                    currentTypeParamAstForOps = astScope
                    for ((tp, typeParam) in newOnes) {
                        if (typeParam.constraint == null) {
                            tp.constraint?.let {
                                try { typeParam.constraint = getTypeFromTypeNode(it) }
                                catch (_: StackOverflowError) { /* circular */ }
                            }
                        }
                    }
                }
                try {
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> walkFnLikeBodyForTypeParamOps(
                                m.typeParameters, m.parameters, m.body?.statements, source, fileName,
                            )
                            is Constructor -> walkFnLikeBodyForTypeParamOps(
                                null, m.parameters, m.body?.statements, source, fileName,
                            )
                            is GetAccessor -> walkFnLikeBodyForTypeParamOps(
                                null, null, m.body?.statements, source, fileName,
                            )
                            is SetAccessor -> walkFnLikeBodyForTypeParamOps(
                                null, m.parameters, m.body?.statements, source, fileName,
                            )
                            else -> {}
                        }
                    }
                } finally {
                    currentTypeParamScope = savedScope
                    currentTypeParamAstForOps = savedAst
                }
            }
            is FunctionDeclaration -> walkFnLikeBodyForTypeParamOps(
                stmt.typeParameters, stmt.parameters, stmt.body?.statements, source, fileName,
            )
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    val typeRef = decl.type as? TypeReference
                    val varName = (decl.name as? Identifier)?.text ?: continue
                    // Annotated `var x: U` form.
                    if (typeRef != null) {
                        val typeName = (typeRef.typeName as? Identifier)?.text ?: continue
                        val tp = currentTypeParamScope?.get(typeName) ?: continue
                        val tpAst = currentTypeParamAstForOps?.get(typeName) ?: continue
                        if (!isTypeParamUnconstrainedOrExplicitAny(tp, tpAst)) continue
                        tpVars[varName] = tpAst
                        continue
                    }
                    // B63.37: Inferred TypeParam from initializer. Two narrow patterns:
                    //   (a) `var y = x` where x is itself a tracked TypeParam-typed var.
                    //   (b) `var y = f(x)` where f is a generic function with a single
                    //       type parameter T and at least one bare-T param, called with
                    //       x being a tracked TypeParam-typed var — and f's return type
                    //       is also bare T. The inferred return is the TypeParam of x.
                    val init = decl.initializer ?: continue
                    if (decl.type != null) continue
                    when (init) {
                        is Identifier -> {
                            val srcTp = tpVars[init.text] ?: continue
                            tpVars[varName] = srcTp
                        }
                        is CallExpression -> {
                            val callee = init.expression as? Identifier ?: continue
                            val callArgs = init.arguments ?: continue
                            val tpName = callArgs.firstNotNullOfOrNull { arg ->
                                (arg as? Identifier)?.let { tpVars[it.text]?.name?.text }
                            } ?: continue
                            val tpAst = currentTypeParamAstForOps?.get(tpName) ?: continue
                            // Verify callee is a generic function with single TP and bare-T return.
                            val sym = currentFileLocals?.get(callee.text)
                                ?: globals[callee.text] ?: continue
                            val fnDecl = sym.declarations.firstOrNull { it is FunctionDeclaration }
                                as? FunctionDeclaration ?: continue
                            val fnTps = fnDecl.typeParameters ?: continue
                            if (fnTps.size != 1) continue
                            val fnReturnTypeRef = fnDecl.type as? TypeReference ?: continue
                            val fnReturnName = (fnReturnTypeRef.typeName as? Identifier)?.text ?: continue
                            if (fnReturnName != fnTps[0].name.text) continue
                            tpVars[varName] = tpAst
                        }
                        else -> {}
                    }
                }
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { emitTypeParamTypedOps(it, tpVars, source, fileName) }
                }
            }
            is ExpressionStatement -> emitTypeParamTypedOps(stmt.expression, tpVars, source, fileName)
            is ReturnStatement -> stmt.expression?.let { emitTypeParamTypedOps(it, tpVars, source, fileName) }
            is IfStatement -> {
                emitTypeParamTypedOps(stmt.expression, tpVars, source, fileName)
                walkStmtForTypeParamOps(stmt.thenStatement, source, fileName, tpVars)
                stmt.elseStatement?.let { walkStmtForTypeParamOps(it, source, fileName, tpVars) }
            }
            is Block -> {
                for (s in stmt.statements) walkStmtForTypeParamOps(s, source, fileName, tpVars)
            }
            is ForStatement -> {
                stmt.condition?.let { emitTypeParamTypedOps(it, tpVars, source, fileName) }
                stmt.incrementor?.let { emitTypeParamTypedOps(it, tpVars, source, fileName) }
                walkStmtForTypeParamOps(stmt.statement, source, fileName, tpVars)
            }
            is WhileStatement -> {
                emitTypeParamTypedOps(stmt.expression, tpVars, source, fileName)
                walkStmtForTypeParamOps(stmt.statement, source, fileName, tpVars)
            }
            is DoStatement -> {
                emitTypeParamTypedOps(stmt.expression, tpVars, source, fileName)
                walkStmtForTypeParamOps(stmt.statement, source, fileName, tpVars)
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) walkStmtForTypeParamOps(s, source, fileName, tpVars)
                stmt.catchClause?.block?.statements?.forEach {
                    walkStmtForTypeParamOps(it, source, fileName, tpVars)
                }
                stmt.finallyBlock?.statements?.forEach {
                    walkStmtForTypeParamOps(it, source, fileName, tpVars)
                }
            }
            is ThrowStatement -> stmt.expression?.let { emitTypeParamTypedOps(it, tpVars, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.let {
                for (s in it) walkStmtForTypeParamOps(s, source, fileName, tpVars)
            }
            else -> {}
        }
    }

    private fun walkFnLikeBodyForTypeParamOps(
        ownTps: List<TypeParameter>?, parameters: List<Parameter>?,
        bodyStmts: List<Statement>?,
        source: String, fileName: String,
    ) {
        if (bodyStmts == null) return
        val savedScope = currentTypeParamScope
        val savedAst = currentTypeParamAstForOps
        if (!ownTps.isNullOrEmpty()) {
            val scope = currentTypeParamScope?.toMutableMap() ?: mutableMapOf()
            val astScope = currentTypeParamAstForOps?.toMutableMap() ?: mutableMapOf()
            val newOnes = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
            for (tp in ownTps) {
                val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                    val p = Type.TypeParam()
                    p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                    p
                }
                scope[tp.name.text] = typeParam
                astScope[tp.name.text] = tp
                newOnes.add(tp to typeParam)
            }
            currentTypeParamScope = scope
            currentTypeParamAstForOps = astScope
            for ((tp, typeParam) in newOnes) {
                if (typeParam.constraint == null) {
                    tp.constraint?.let {
                        try { typeParam.constraint = getTypeFromTypeNode(it) }
                        catch (_: StackOverflowError) { /* circular */ }
                    }
                }
            }
        }
        try {
            val bodyVars = mutableMapOf<String, TypeParameter>()
            // Track parameters typed as effectively-unconstrained (or `extends any`) TypeParams.
            if (parameters != null) {
                for (p in parameters) {
                    val typeRef = p.type as? TypeReference ?: continue
                    val typeName = (typeRef.typeName as? Identifier)?.text ?: continue
                    val tp = currentTypeParamScope?.get(typeName) ?: continue
                    val tpAst = currentTypeParamAstForOps?.get(typeName) ?: continue
                    if (!isTypeParamUnconstrainedOrExplicitAny(tp, tpAst)) continue
                    val paramName = (p.name as? Identifier)?.text ?: continue
                    bodyVars[paramName] = tpAst
                }
            }
            for (s in bodyStmts) walkStmtForTypeParamOps(s, source, fileName, bodyVars)
        } finally {
            currentTypeParamScope = savedScope
            currentTypeParamAstForOps = savedAst
        }
    }

    private fun isTypeParamEffectivelyUnconstrained(tp: Type.TypeParam): Boolean {
        val c = tp.constraint ?: return true
        // Self-circular: constraint resolves to the same Type.TypeParam.
        return c === tp
    }

    /** Like [isTypeParamEffectivelyUnconstrained] but ALSO accepts EXPLICIT `extends any`
     *  (constraint AST is `KeywordTypeNode(AnyKeyword)`) and `T extends SelfRecursiveAlias<...>`
     *  (alias body references its own name — the instantiation produces no useful
     *  apparent type). Used by the property-access walker — we must distinguish these
     *  cases from anyType-via-error-recovery (`T extends typeof undeclared`) where
     *  TypeScript doesn't emit property-access errors. */
    private fun isTypeParamUnconstrainedOrExplicitAny(tp: Type.TypeParam, tpDecl: TypeParameter?): Boolean {
        if (isTypeParamEffectivelyUnconstrained(tp)) return true
        val c = tpDecl?.constraint ?: return false
        if (tp.constraint === anyType && c is KeywordTypeNode && c.kind == SyntaxKind.AnyKeyword) return true
        // `T extends RecursiveAlias<...>` — detect by walking the alias body for self-reference.
        if (c is TypeReference) {
            val name = (c.typeName as? Identifier)?.text ?: return false
            val sym = currentFileLocals?.get(name) ?: globals[name] ?: return false
            if (!sym.flags.hasAny(SymbolFlags.TypeAlias)) return false
            val decl = sym.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration ?: return false
            return aliasBodyReferencesName(decl.type, name)
        }
        return false
    }

    /** Walks a TypeNode looking for a TypeReference to [name]. Used by
     *  [isTypeParamUnconstrainedOrExplicitAny] to detect direct self-recursive type aliases. */
    private fun aliasBodyReferencesName(node: TypeNode?, name: String): Boolean {
        if (node == null) return false
        return when (node) {
            is TypeReference -> {
                val ident = node.typeName as? Identifier
                if (ident?.text == name) return true
                node.typeArguments?.any { aliasBodyReferencesName(it, name) } == true
            }
            is ArrayType -> aliasBodyReferencesName(node.elementType, name)
            is UnionType -> node.types.any { aliasBodyReferencesName(it, name) }
            is IntersectionType -> node.types.any { aliasBodyReferencesName(it, name) }
            is ParenthesizedType -> aliasBodyReferencesName(node.type, name)
            is TupleType -> node.elements.any { aliasBodyReferencesName(it, name) }
            is TypeLiteral -> node.members.any { m ->
                when (m) {
                    is PropertyDeclaration -> aliasBodyReferencesName(m.type, name)
                    is IndexSignature -> aliasBodyReferencesName(m.type, name)
                    is MethodDeclaration -> aliasBodyReferencesName(m.type, name) ||
                        m.parameters.any { aliasBodyReferencesName(it.type, name) }
                    else -> false
                }
            }
            else -> false
        }
    }

    private fun emitTypeParamTypedOps(
        expr: Expression, tpVars: Map<String, TypeParameter>, source: String, fileName: String,
    ) {
        when (expr) {
            is PropertyAccessExpression -> {
                val recv = expr.expression
                val recvTp = (recv as? Identifier)?.let { tpVars[it.text] }
                if (recvTp != null) {
                    val tpName = recvTp.name.text
                    val propName = expr.name.text
                    // Under strictNullChecks, TypeParam apparent = unknown → every property
                    // access fires TS2339. Under non-strict, apparent = `{}` which inherits
                    // Object.prototype methods — skip those property names so we don't FP on
                    // `t.toString` / `t.valueOf` / etc. for unconstrained T.
                    val isObjectProtoMember = propName in OBJECT_PROTOTYPE_IMPLICIT
                    val shouldEmit = propName.isNotEmpty() &&
                        (strictNullChecks || !isObjectProtoMember)
                    if (shouldEmit) {
                        val (line, character) = getLineAndCharacterOfPosition(source, expr.name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '$tpName'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = expr.name.pos, length = propName.length,
                        ))
                    }
                } else {
                    emitTypeParamTypedOps(expr.expression, tpVars, source, fileName)
                }
            }
            is CallExpression -> {
                val callee = expr.expression
                val calleeTp = (callee as? Identifier)?.let { tpVars[it.text] }
                if (calleeTp != null) {
                    val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error, code = 2349,
                        fileName = fileName, line = line, character = character,
                        start = callee.pos, length = (callee as Identifier).text.length,
                        messageChain = listOf("  Type '{}' has no call signatures."),
                    ))
                } else {
                    // B60.12c: detect `f(t)` where t is bare effectively-unconstrained TP arg
                    // and f's param is a constrained TP. Emit TS2345 + TS2208 related info.
                    emitTs2345ForBareTpArgToConstrainedTpParam(expr, tpVars, source, fileName)
                    emitTypeParamTypedOps(callee, tpVars, source, fileName)
                }
                for (arg in expr.arguments) emitTypeParamTypedOps(arg, tpVars, source, fileName)
            }
            is NewExpression -> {
                val callee = expr.expression
                val calleeTp = (callee as? Identifier)?.let { tpVars[it.text] }
                if (calleeTp != null) {
                    val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error, code = 2351,
                        fileName = fileName, line = line, character = character,
                        start = callee.pos, length = (callee as Identifier).text.length,
                        messageChain = listOf("  Type '{}' has no construct signatures."),
                    ))
                } else {
                    emitTypeParamTypedOps(callee, tpVars, source, fileName)
                }
                expr.arguments?.let { for (arg in it) emitTypeParamTypedOps(arg, tpVars, source, fileName) }
            }
            is BinaryExpression -> {
                // Flatten the left-spine iteratively to avoid StackOverflow on
                // deeply nested binary chains.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                emitTypeParamTypedOps(cur, tpVars, source, fileName)
                while (rightStack.isNotEmpty()) {
                    emitTypeParamTypedOps(rightStack.removeLast(), tpVars, source, fileName)
                }
            }
            is ElementAccessExpression -> {
                // Note: `x[1]` on a TypeParam is NOT diagnosed by TypeScript here —
                // TypeParam apparent type `{}` permits indexing through fallback rules.
                emitTypeParamTypedOps(expr.expression, tpVars, source, fileName)
                emitTypeParamTypedOps(expr.argumentExpression, tpVars, source, fileName)
            }
            is ParenthesizedExpression -> emitTypeParamTypedOps(expr.expression, tpVars, source, fileName)
            is PrefixUnaryExpression -> emitTypeParamTypedOps(expr.operand, tpVars, source, fileName)
            is PostfixUnaryExpression -> emitTypeParamTypedOps(expr.operand, tpVars, source, fileName)
            is ConditionalExpression -> {
                emitTypeParamTypedOps(expr.condition, tpVars, source, fileName)
                emitTypeParamTypedOps(expr.whenTrue, tpVars, source, fileName)
                emitTypeParamTypedOps(expr.whenFalse, tpVars, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * B60.12c: For `f(t)` where `t` is a bare effectively-unconstrained TypeParam
     * variable (in tpVars) and `f` is a top-level FunctionDeclaration with a TP
     * parameter that has a non-trivial constraint, emit TS2345 with the param
     * displayed as its constraint, plus TS2208 related info pointing to `t`'s
     * TypeParam declaration suggesting `extends <constraint>`.
     */
    private fun emitTs2345ForBareTpArgToConstrainedTpParam(
        expr: CallExpression, tpVars: Map<String, TypeParameter>,
        source: String, fileName: String,
    ) {
        val callee = expr.expression as? Identifier ?: return
        val sym = currentFileLocals?.get(callee.text) ?: globals[callee.text] ?: return
        val fnDecl = sym.declarations.firstOrNull() as? FunctionDeclaration ?: return
        val fnTps = fnDecl.typeParameters ?: return
        if (fnTps.isEmpty()) return
        val fnTpsByName = fnTps.associateBy { it.name.text }
        for ((argIdx, arg) in expr.arguments.withIndex()) {
            if (arg !is Identifier) continue
            val argTp = tpVars[arg.text] ?: continue
            if (argIdx >= fnDecl.parameters.size) continue
            val param = fnDecl.parameters[argIdx]
            val paramType = param.type as? TypeReference ?: continue
            val paramTpName = (paramType.typeName as? Identifier)?.text ?: continue
            val paramTp = fnTpsByName[paramTpName] ?: continue
            val constraintNode = paramTp.constraint ?: continue
            // Skip self-circular constraint
            val constraintIsSelfRef = (constraintNode as? TypeReference)?.let {
                (it.typeName as? Identifier)?.text == paramTpName
            } == true
            if (constraintIsSelfRef) continue
            // Prefer AST-based display so type aliases like `Record<string, any>` render
            // without requiring full generic alias instantiation infrastructure.
            val astDisplay = formatTypeForDisplay(constraintNode)
            val constraintDisplay = if (astDisplay != null && astDisplay != "{ ; }") astDisplay
            else {
                val constraintType = try { getTypeFromTypeNode(constraintNode) }
                catch (_: StackOverflowError) { continue }
                if (constraintType === errorType) continue
                typeToString(constraintType)
            }
            val argTpName = argTp.name.text
            val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
            val related = mutableListOf<Diagnostic>()
            val (decLine, decChar) = getLineAndCharacterOfPosition(source, argTp.name.pos)
            related.add(Diagnostic(
                message = "This type parameter might need an `extends $constraintDisplay` constraint.",
                category = DiagnosticCategory.Message, code = 2208,
                fileName = fileName, line = decLine, character = decChar,
                start = argTp.name.pos, length = argTp.name.text.length,
            ))
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argTpName' is not assignable to parameter of type '$constraintDisplay'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = line, character = character,
                start = arg.pos, length = arg.text.length,
                relatedInformation = related,
            ))
        }
    }

    /**
     * Emits TS2352 for `<Foo<X>>foo` casts where `foo` already has type `Foo<Y>`
     * (same generic target) and the type-arg pair X/Y is non-comparable in both
     * directions. Narrow gate: skips Any/Unknown/Never/Void/error/TypeParam args
     * to avoid FPs in partially-resolved generic contexts.
     */
    private fun checkSameTargetReferenceCastOverlap() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            val savedCheckFileName = currentCheckFileName
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                for (stmt in result.sourceFile.statements) {
                    walkTypeAssertionsInStmt(stmt, source, fileName, ::emitTS2352IfSameTargetMismatch)
                    walkTypeAssertionsInStmt(stmt, source, fileName, ::emitTS2352IfFunctionReturnMismatch)
                }
            } finally {
                currentFileLocals = savedLocals
                currentCheckFileName = savedCheckFileName
            }
        }
    }

    private fun emitTS2352IfSameTargetMismatch(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        val inner = expr.expression
        val typeNode = expr.type
        val sourceType = try { getTypeOfExpression(inner) } catch (_: StackOverflowError) { return }
        val targetType = try { getTypeFromTypeNode(typeNode) } catch (_: StackOverflowError) { return }
        if (sourceType !is Type.Reference) return
        if (targetType !is Type.Reference) return
        if (sourceType.target !== targetType.target) return
        val sourceArgs = sourceType.resolvedTypeArguments ?: return
        val targetArgs = targetType.resolvedTypeArguments ?: return
        if (sourceArgs.size != targetArgs.size) return
        if (sourceArgs.isEmpty()) return
        for (a in sourceArgs) {
            if (a is Type.TypeParam) return
            if (a.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never or TypeFlags.Void)) return
        }
        for (a in targetArgs) {
            if (a is Type.TypeParam) return
            if (a.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never or TypeFlags.Void)) return
        }
        for (i in sourceArgs.indices) {
            val s = sourceArgs[i]
            val t = targetArgs[i]
            val sToT = try { checkTypeRelatedTo(s, t, assignableRelation) } catch (_: StackOverflowError) { return }
            if (sToT) continue
            val tToS = try { checkTypeRelatedTo(t, s, assignableRelation) } catch (_: StackOverflowError) { return }
            if (tToS) continue
            // 17.82: For array-to-array casts where the source is an array literal AND
            // an element is an object literal with excess properties relative to the
            // target's element type, prefer the excess-property chain at the excess
            // prop's position. Cf. arrayCast_ts: `<{id:number}[]>[{foo:"s"}]` should
            // emit TS2352 at `foo` (col 23, 3 chars) with chain "Object literal may
            // only specify known properties, and 'foo' does not exist in type
            // '{ id: number; }'." rather than the whole-cast position with a
            // "type X is not comparable to type Y" chain.
            if (inner is ArrayLiteralExpression && sourceType.target.symbol?.name == "Array" &&
                targetType.target.symbol?.name == "Array" && t is Type.Object) {
                try { resolveStructuredTypeMembers(t) } catch (_: StackOverflowError) { return }
                val targetPropNames = collectTargetPropertyNames(t)
                if (targetPropNames != null) {
                    for (elem in inner.elements) {
                        if (elem !is ObjectLiteralExpression) continue
                        for (prop in elem.properties) {
                            if (prop !is PropertyAssignment) continue
                            val propName = when (val n = prop.name) {
                                is Identifier -> n.text
                                is StringLiteralNode -> n.text
                                else -> continue
                            }
                            if (propName !in targetPropNames) {
                                val propPos = prop.name.pos
                                val (eLine, eChar) = getLineAndCharacterOfPosition(source, propPos)
                                diagnostics.add(Diagnostic(
                                    message = "Conversion of type '${typeToString(sourceType)}' to type '${typeToString(targetType)}' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                                    messageChain = listOf("  Object literal may only specify known properties, and '$propName' does not exist in type '${typeToString(t)}'."),
                                    category = DiagnosticCategory.Error,
                                    code = 2352,
                                    fileName = fileName,
                                    line = eLine,
                                    character = eChar,
                                    start = propPos,
                                    length = propName.length,
                                ))
                                return
                            }
                        }
                    }
                }
            }
            val start = expr.pos
            val endPos = expressionTrueEnd(inner)
            val length = (endPos - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Conversion of type '${typeToString(sourceType)}' to type '${typeToString(targetType)}' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                messageChain = listOf("  Type '${typeToString(s)}' is not comparable to type '${typeToString(t)}'."),
                category = DiagnosticCategory.Error,
                code = 2352,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            return
        }
    }

    /**
     * B95h (round 82): TS2352 for a FUNCTION-typed cast whose call-signature RETURN type is a
     * different primitive than the target call signature's — `<{ (): number; }> function() {
     * return "err"; }` (source `() => string`). Emits the whole-cast span + chain "Type
     * 'string' is not comparable to type 'number'." Conservative: both sides single-or-first
     * call sig, both returns distinct primitive intrinsics. (contextualTyping39/41.)
     */
    private fun emitTS2352IfFunctionReturnMismatch(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        var inner: Expression = expr.expression
        if (inner is ParenthesizedExpression) inner = inner.expression
        if (inner !is FunctionExpression && inner !is ArrowFunction) return
        val sourceType = try { getTypeOfExpression(inner) } catch (_: StackOverflowError) { return }
        if (sourceType !is Type.Object) return
        val srcSigs = sourceType.callSignatures ?: return
        if (srcSigs.isEmpty()) return
        val targetType = try { getTypeFromTypeNode(expr.type) } catch (_: StackOverflowError) { return }
        if (targetType !is Type.Object) return
        val tgtSigs = targetType.callSignatures ?: return
        if (tgtSigs.isEmpty()) return
        val srcRet = srcSigs[0].resolvedReturnType ?: return
        val tgtRet = tgtSigs[0].resolvedReturnType ?: return
        val prims = setOf("string", "number", "boolean", "bigint", "symbol")
        if (srcRet !is Type.Intrinsic || tgtRet !is Type.Intrinsic) return
        if (srcRet.intrinsicName !in prims || tgtRet.intrinsicName !in prims) return
        if (srcRet.intrinsicName == tgtRet.intrinsicName) return
        val start = expr.pos
        // Span = the whole `<T> <source>` cast. `expressionTrueEnd` has no FunctionExpression case
        // (overshoots by 1 via the default, which also leaks through the ParenthesizedExpression
        // case), so compute the end from the unwrapped function body's `}` (`closeBracePos + 1`)
        // plus one for each wrapping paren — handles both `<T> function(){...}` (39) and
        // `<T> (function(){...})` (41, the `)` after `}`).
        val parenLayers = if (expr.expression is ParenthesizedExpression) 1 else 0
        val innerBlock: Block? = when (inner) {
            is FunctionExpression -> inner.body
            is ArrowFunction -> inner.body as? Block
            else -> null
        }
        val endPos = if (innerBlock != null && innerBlock.closeBracePos >= 0) {
            innerBlock.closeBracePos + 1 + parenLayers
        } else {
            expressionTrueEnd(expr.expression)
        }
        val length = (endPos - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Conversion of type '${typeToString(sourceType)}' to type '${typeToString(targetType)}' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            messageChain = listOf("  Type '${srcRet.intrinsicName}' is not comparable to type '${tgtRet.intrinsicName}'."),
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Emits TS2352 for `<C<X>>arr` casts where `arr` is array-typed and `C` is a different
     * named class with at least one required non-prototype property. Conservative gates:
     * source target.symbol.name == "Array"; target target is a Class (Type.Interface with
     * SymbolFlags.Class) different from Array; first missing prop drives the chain message.
     */
    private fun checkArrayToClassCastOverlap() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            val savedCheckFileName = currentCheckFileName
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                for (stmt in result.sourceFile.statements) {
                    walkTypeAssertionsInStmt(stmt, source, fileName, ::emitTS2352IfArrayToClassMismatch)
                }
            } finally {
                currentFileLocals = savedLocals
                currentCheckFileName = savedCheckFileName
            }
        }
    }

    private fun emitTS2352IfArrayToClassMismatch(
        expr: TypeAssertionExpression, source: String, fileName: String,
    ) {
        val inner = expr.expression
        val typeNode = expr.type
        // Empty array literal `[]` is inferred as `anyType` by getTypeOfArrayLiteral, so
        // synthesize a `never[]` Type.Reference for the comparison and display.
        val sourceType: Type = if (inner is ArrayLiteralExpression && inner.elements.isEmpty()) {
            getArrayType(neverType)
        } else {
            try { getTypeOfExpression(inner) } catch (_: StackOverflowError) { return }
        }
        val targetType = try { getTypeFromTypeNode(typeNode) } catch (_: StackOverflowError) { return }
        if (sourceType !is Type.Reference) return
        if (sourceType.target.symbol?.name != "Array") return
        if (targetType !is Type.Reference) return
        val targetClass = targetType.target
        if (targetClass.symbol?.name == "Array") return
        val classSym = targetClass.symbol ?: return
        if (!classSym.flags.hasAny(SymbolFlags.Class)) return
        try { resolveStructuredTypeMembers(sourceType) } catch (_: StackOverflowError) { return }
        try { resolveStructuredTypeMembers(targetType) } catch (_: StackOverflowError) { return }
        val sourceMembers = sourceType.members ?: return
        val targetProps = targetType.properties ?: return
        var firstMissing: Symbol? = null
        for (prop in targetProps) {
            if (isOptionalProperty(prop)) continue
            if (prop.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (prop.name !in sourceMembers) {
                firstMissing = prop
                break
            }
        }
        if (firstMissing == null) return
        val sourceDisplay = typeToString(sourceType)
        val targetDisplay = typeToString(targetType)
        val start = expr.pos
        val endPos = expressionTrueEnd(inner)
        val length = (endPos - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val related = mutableListOf<Diagnostic>()
        val firstDecl = firstMissing.declarations.firstOrNull()
        if (firstDecl != null) {
            val declPos = when (firstDecl) {
                is PropertyDeclaration -> firstDecl.name.pos
                is MethodDeclaration -> firstDecl.name.let { (it as? Identifier)?.pos ?: firstDecl.pos }
                else -> firstDecl.pos
            }
            val (resolvedFile, resolvedSource) = resolveDeclarationSourceFile(declPos)
            val declFile = resolvedFile ?: fileName
            val declSource = resolvedSource ?: source
            val isLib = isLibFileName(declFile)
            val (dline, dchar) = if (isLib) {
                Pair(null as Int?, null as Int?)
            } else {
                val p = getLineAndCharacterOfPosition(declSource, declPos)
                Pair(p.first, p.second)
            }
            related.add(Diagnostic(
                message = "'${firstMissing.name}' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = declFile,
                line = dline,
                character = dchar,
                start = declPos,
                length = firstMissing.name.length,
            ))
        }
        diagnostics.add(Diagnostic(
            message = "Conversion of type '$sourceDisplay' to type '$targetDisplay' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            messageChain = listOf("  Property '${firstMissing.name}' is missing in type '$sourceDisplay' but required in type '$targetDisplay'."),
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = related,
        ))
    }

    /**
     * TS2352: "Conversion of type 'undefined' to type 'T' may be a mistake..."
     * for `/** @type {T} */ (void 0)` casts in JS-like files where the target
     * type is a named non-primitive (uppercase identifier). The cast source
     * is `void 0` (or any `VoidExpression`) which evaluates to `undefined`;
     * casting to a non-overlapping type prompts TypeScript's "convert to
     * unknown first" diagnostic.
     *
     * Squiggle is positioned at the type name inside the JSDoc comment text
     * (not on the cast expression itself), matching TypeScript's baseline.
     * Position is computed by scanning the source backwards from the
     * ParenthesizedExpression's `(` for the most recent `@type {NAME` pattern.
     */
    private fun checkJSDocVoidCastNonOverlap() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val isJsLike = fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".cjs") || fileName.endsWith(".mjs")
            if (!isJsLike) continue
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                walkJSDocVoidCastInStmt(stmt, source, fileName)
            }
        }
    }

    private fun walkJSDocVoidCastInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> walkJSDocVoidCastInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkJSDocVoidCastInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkJSDocVoidCastInExpr(it, source, fileName) }
            is Block -> stmt.statements.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
            is IfStatement -> {
                walkJSDocVoidCastInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkJSDocVoidCastInStmt(it, source, fileName) }
            }
            is ForStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is ForInStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is WhileStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is DoStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                when (clause) {
                    is CaseClause -> clause.statements.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
                    is DefaultClause -> clause.statements.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
                stmt.catchClause?.block?.statements?.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
            }
            is LabeledStatement -> walkJSDocVoidCastInStmt(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { walkJSDocVoidCastInExpr(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { it.statements.forEach { s -> walkJSDocVoidCastInStmt(s, source, fileName) } }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.let { it.statements.forEach { s -> walkJSDocVoidCastInStmt(s, source, fileName) } }
                is Constructor -> m.body?.let { it.statements.forEach { s -> walkJSDocVoidCastInStmt(s, source, fileName) } }
                is GetAccessor -> m.body?.let { it.statements.forEach { s -> walkJSDocVoidCastInStmt(s, source, fileName) } }
                is SetAccessor -> m.body?.let { it.statements.forEach { s -> walkJSDocVoidCastInStmt(s, source, fileName) } }
                is PropertyDeclaration -> m.initializer?.let { walkJSDocVoidCastInExpr(it, source, fileName) }
                else -> {}
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
            is ExportAssignment -> walkJSDocVoidCastInExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkJSDocVoidCastInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ParenthesizedExpression -> {
                emitTS2352IfJSDocVoidCast(expr, source, fileName)
                walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            }
            is BinaryExpression -> {
                // Iterative left-spine flatten — handles assignment RHS (e.g.
                // `module.exports = /** @type {T} */(void 0)`) plus chained binary ops.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkJSDocVoidCastInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) walkJSDocVoidCastInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                walkJSDocVoidCastInExpr(expr.condition, source, fileName)
                walkJSDocVoidCastInExpr(expr.whenTrue, source, fileName)
                walkJSDocVoidCastInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkJSDocVoidCastInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) walkJSDocVoidCastInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                walkJSDocVoidCastInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkJSDocVoidCastInExpr(it, source, fileName) }
            }
            is ArrayLiteralExpression -> for (el in expr.elements) walkJSDocVoidCastInExpr(el, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkJSDocVoidCastInExpr(prop.initializer, source, fileName)
                is SpreadAssignment -> walkJSDocVoidCastInExpr(prop.expression, source, fileName)
                else -> {}
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> body.statements.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
                is Expression -> walkJSDocVoidCastInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.statements?.forEach { walkJSDocVoidCastInStmt(it, source, fileName) }
            is PropertyAccessExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkJSDocVoidCastInExpr(expr.expression, source, fileName)
                walkJSDocVoidCastInExpr(expr.argumentExpression, source, fileName)
            }
            is PrefixUnaryExpression -> walkJSDocVoidCastInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkJSDocVoidCastInExpr(expr.operand, source, fileName)
            is SpreadElement -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkJSDocVoidCastInExpr(it, source, fileName) }
            is AsExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkJSDocVoidCastInExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkJSDocVoidCastInExpr(span.expression, source, fileName)
            is CommaListExpression -> for (e in expr.elements) walkJSDocVoidCastInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun emitTS2352IfJSDocVoidCast(
        expr: ParenthesizedExpression, source: String, fileName: String,
    ) {
        val castType = expr.jsdocCastType ?: return
        if (expr.expression !is VoidExpression) return
        val typeName = (castType as? TypeReference)?.typeName as? Identifier ?: return
        val name = typeName.text
        if (name.isEmpty() || !name[0].isUpperCase()) return
        if (name in JSDOC_VOID_CAST_SKIP_NAMES) return
        // Find the name's source position by scanning backwards from `(` for `@type {NAME`.
        val parenPos = expr.pos
        val searchStart = (parenPos - 256).coerceAtLeast(0)
        if (searchStart >= parenPos) return
        val searchText = source.substring(searchStart, parenPos)
        val pattern = "@type {$name"
        val idxInSearch = searchText.lastIndexOf(pattern)
        if (idxInSearch < 0) return
        val nameStart = searchStart + idxInSearch + "@type {".length
        val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
        diagnostics.add(Diagnostic(
            message = "Conversion of type 'undefined' to type '$name' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
            category = DiagnosticCategory.Error,
            code = 2352,
            fileName = fileName,
            line = line,
            character = character,
            start = nameStart,
            length = name.length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2744: Type parameter defaults can only reference previously declared
    // type parameters.
    // -----------------------------------------------------------------------

    /**
     * Emits TS2744 for any TypeParameter whose default TypeNode references a
     * type parameter in the same list at an index >= its own (self-reference
     * or forward reference). Squiggle is at the first offending Identifier,
     * length = identifier.text.length.
     *
     * Only references to same-list type parameter NAMES trigger this; outer
     * scopes (enclosing class/interface name, other type params in enclosing
     * scopes) are fine.
     */
    private fun checkTypeParameterDefaults() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                walkTParamDefaultsInStmts(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    private fun walkTParamDefaultsInStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkTParamDefaultsInStmt(stmt, source, fileName)
    }

    private fun walkTParamDefaultsInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                stmt.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                stmt.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                for (p in stmt.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                stmt.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                stmt.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                for (member in stmt.members) walkTParamDefaultsInClassMember(member, source, fileName)
            }
            is InterfaceDeclaration -> {
                stmt.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                for (member in stmt.members) walkTParamDefaultsInClassMember(member, source, fileName)
            }
            is TypeAliasDeclaration -> {
                stmt.typeParameters?.let { validateTParamDefaults(it, source, fileName, stmt.name.text) }
                walkTParamDefaultsInType(stmt.type, source, fileName)
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                d.initializer?.let { walkTParamDefaultsInExpr(it, source, fileName) }
            }
            is ExpressionStatement -> walkTParamDefaultsInExpr(stmt.expression, source, fileName)
            is Block -> walkTParamDefaultsInStmts(stmt.statements, source, fileName)
            is IfStatement -> {
                walkTParamDefaultsInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkTParamDefaultsInStmt(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                        d.initializer?.let { walkTParamDefaultsInExpr(it, source, fileName) }
                    }
                    is Expression -> walkTParamDefaultsInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { walkTParamDefaultsInExpr(it, source, fileName) }
                stmt.incrementor?.let { walkTParamDefaultsInExpr(it, source, fileName) }
                walkTParamDefaultsInStmt(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                walkTParamDefaultsInExpr(stmt.expression, source, fileName)
                walkTParamDefaultsInStmt(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                walkTParamDefaultsInExpr(stmt.expression, source, fileName)
                walkTParamDefaultsInStmt(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                walkTParamDefaultsInExpr(stmt.expression, source, fileName)
                walkTParamDefaultsInStmt(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                walkTParamDefaultsInStmt(stmt.statement, source, fileName)
                walkTParamDefaultsInExpr(stmt.expression, source, fileName)
            }
            is TryStatement -> {
                walkTParamDefaultsInStmts(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.statements?.let { walkTParamDefaultsInStmts(it, source, fileName) }
                stmt.finallyBlock?.statements?.let { walkTParamDefaultsInStmts(it, source, fileName) }
            }
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                val stmts = (clause as? CaseClause)?.statements ?: (clause as? DefaultClause)?.statements
                stmts?.let { walkTParamDefaultsInStmts(it, source, fileName) }
            }
            is LabeledStatement -> walkTParamDefaultsInStmt(stmt.statement, source, fileName)
            is ReturnStatement -> stmt.expression?.let { walkTParamDefaultsInExpr(it, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { walkTParamDefaultsInExpr(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.let {
                walkTParamDefaultsInStmts(it, source, fileName)
            }
            is ExportAssignment -> walkTParamDefaultsInExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkTParamDefaultsInClassMember(member: ClassElement, source: String, fileName: String) {
        when (member) {
            is MethodDeclaration -> {
                member.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                member.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                for (p in member.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                member.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
            }
            is Constructor -> {
                for (p in member.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                member.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
            }
            is GetAccessor -> {
                member.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                member.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
            }
            is SetAccessor -> {
                for (p in member.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                member.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
            }
            is PropertyDeclaration -> {
                member.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                member.initializer?.let { walkTParamDefaultsInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    private fun walkTParamDefaultsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                expr.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                expr.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                for (p in expr.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                (expr.body as? Block)?.statements?.let { walkTParamDefaultsInStmts(it, source, fileName) }
            }
            is FunctionExpression -> {
                expr.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                expr.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                for (p in expr.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                expr.body?.statements?.let { walkTParamDefaultsInStmts(it, source, fileName) }
            }
            is ClassExpression -> {
                expr.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                for (member in expr.members) walkTParamDefaultsInClassMember(member, source, fileName)
            }
            is ParenthesizedExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkTParamDefaultsInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) walkTParamDefaultsInExpr(rightStack.removeLast(), source, fileName)
            }
            is CallExpression -> {
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
                for (a in expr.arguments) walkTParamDefaultsInExpr(a, source, fileName)
            }
            is NewExpression -> {
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkTParamDefaultsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
                walkTParamDefaultsInExpr(expr.argumentExpression, source, fileName)
            }
            is ConditionalExpression -> {
                walkTParamDefaultsInExpr(expr.condition, source, fileName)
                walkTParamDefaultsInExpr(expr.whenTrue, source, fileName)
                walkTParamDefaultsInExpr(expr.whenFalse, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) walkTParamDefaultsInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> walkTParamDefaultsInExpr(p.initializer, source, fileName)
                    is SpreadAssignment -> walkTParamDefaultsInExpr(p.expression, source, fileName)
                    is MethodDeclaration -> {
                        p.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                        p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                        for (param in p.parameters) param.type?.let { walkTParamDefaultsInType(it, source, fileName) }
                        p.body?.let { walkTParamDefaultsInStmts(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is TypeAssertionExpression -> {
                walkTParamDefaultsInType(expr.type, source, fileName)
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
            }
            is AsExpression -> {
                walkTParamDefaultsInType(expr.type, source, fileName)
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
            }
            is SatisfiesExpression -> {
                walkTParamDefaultsInType(expr.type, source, fileName)
                walkTParamDefaultsInExpr(expr.expression, source, fileName)
            }
            is NonNullExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is SpreadElement -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkTParamDefaultsInExpr(it, source, fileName) }
            is VoidExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkTParamDefaultsInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkTParamDefaultsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkTParamDefaultsInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) walkTParamDefaultsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                walkTParamDefaultsInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkTParamDefaultsInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkTParamDefaultsInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun walkTParamDefaultsInType(type: TypeNode, source: String, fileName: String) {
        when (type) {
            is FunctionType -> {
                type.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                walkTParamDefaultsInType(type.type, source, fileName)
                for (p in type.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
            }
            is ConstructorType -> {
                type.typeParameters?.let { validateTParamDefaults(it, source, fileName) }
                walkTParamDefaultsInType(type.type, source, fileName)
                for (p in type.parameters) p.type?.let { walkTParamDefaultsInType(it, source, fileName) }
            }
            is UnionType -> for (t in type.types) walkTParamDefaultsInType(t, source, fileName)
            is IntersectionType -> for (t in type.types) walkTParamDefaultsInType(t, source, fileName)
            is ArrayType -> walkTParamDefaultsInType(type.elementType, source, fileName)
            is TupleType -> for (e in type.elements) walkTParamDefaultsInType(e, source, fileName)
            is ParenthesizedType -> walkTParamDefaultsInType(type.type, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { walkTParamDefaultsInType(it, source, fileName) }
            is TypeLiteral -> for (m in type.members) walkTParamDefaultsInClassMember(m, source, fileName)
            else -> {}
        }
    }

    private fun validateTParamDefaults(
        tparams: List<TypeParameter>,
        source: String,
        fileName: String,
        parentAliasName: String? = null,
    ) {
        if (tparams.isEmpty()) return
        // TS2368: reserved primitive/intrinsic type names cannot be used as type
        // parameter names (e.g. `foo<string>(x: string)`). The set mirrors what
        // TypeScript flags as "reserved type names" via Identifier.originalKeywordKind.
        for (tp in tparams) {
            val tpName = tp.name.text
            if (tpName in RESERVED_TYPE_PARAM_NAMES) {
                val start = tp.name.pos
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type parameter name cannot be '$tpName'.",
                    category = DiagnosticCategory.Error,
                    code = 2368,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = tpName.length,
                ))
            }
        }
        val names = tparams.map { it.name.text }
        var anyCircular = false
        for (i in tparams.indices) {
            val tp = tparams[i]
            val default = tp.default ?: continue
            // Find the first Identifier reference in the default whose name matches
            // a type parameter at index >= i.
            val offender = findForwardTParamRef(default, names, i) ?: continue
            val start = offender.pos
            val length = offender.text.length.coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type parameter defaults can only reference previously declared type parameters.",
                category = DiagnosticCategory.Error,
                code = 2744,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            anyCircular = true
        }
        // For TypeAliases with circular defaults, track the symbol so that later
        // display of `Name` (without type args) renders as `Name<any, ..., any>`
        // to match TypeScript's substitution-on-invalid-default behavior.
        if (anyCircular && parentAliasName != null) {
            val sym = currentFileLocals?.get(parentAliasName)
            if (sym != null && sym.flags.hasAny(SymbolFlags.TypeAlias)) {
                circularDefaultTypeParamCount[sym.id] = tparams.size
            }
        }
    }

    /**
     * Walks a TypeNode looking for the first Identifier reference whose text
     * matches a type parameter name at index >= ownIdx. Returns the offending
     * Identifier (or null if none).
     */
    private fun findForwardTParamRef(type: TypeNode, names: List<String>, ownIdx: Int): Identifier? {
        when (type) {
            is TypeReference -> {
                val tn = type.typeName
                if (tn is Identifier) {
                    val idx = names.indexOf(tn.text)
                    if (idx >= ownIdx) return tn
                }
                type.typeArguments?.forEach { ta ->
                    findForwardTParamRef(ta, names, ownIdx)?.let { return it }
                }
            }
            is UnionType -> for (t in type.types) findForwardTParamRef(t, names, ownIdx)?.let { return it }
            is IntersectionType -> for (t in type.types) findForwardTParamRef(t, names, ownIdx)?.let { return it }
            is ArrayType -> return findForwardTParamRef(type.elementType, names, ownIdx)
            is TupleType -> for (e in type.elements) findForwardTParamRef(e, names, ownIdx)?.let { return it }
            is ParenthesizedType -> return findForwardTParamRef(type.type, names, ownIdx)
            is FunctionType -> {
                // Type params introduced by the FunctionType shadow outer names inside it.
                val inner = type.typeParameters?.map { it.name.text } ?: emptyList()
                if (inner.isEmpty()) {
                    for (p in type.parameters) p.type?.let {
                        findForwardTParamRef(it, names, ownIdx)?.let { id -> return id }
                    }
                    return findForwardTParamRef(type.type, names, ownIdx)
                }
                // Otherwise skip — inner scope.
            }
            else -> {}
        }
        return null
    }

    // -----------------------------------------------------------------------
    // TS1015: Parameter cannot have question mark and initializer
    // -----------------------------------------------------------------------

    private fun checkOptionalParamWithInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForOptionalParams(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForOptionalParams(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkForOptionalParamsInStmt(stmt, source, fileName)
    }

    private fun walkForOptionalParamsInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkParamsForTS1015(stmt.parameters, source, fileName)
                stmt.body?.let { walkForOptionalParams(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is GetAccessor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is SetAccessor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    walkForOptionalParamsInExpr(decl.initializer, source, fileName)
                }
            }
            is ExpressionStatement -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForOptionalParams(it.statements, source, fileName) }
            is Block -> walkForOptionalParams(stmt.statements, source, fileName)
            is ReturnStatement -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            is IfStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                walkForOptionalParamsInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkForOptionalParamsInStmt(it, source, fileName) }
            }
            is ForStatement -> {
                stmt.condition?.let { walkForOptionalParamsInExpr(it, source, fileName) }
                stmt.incrementor?.let { walkForOptionalParamsInExpr(it, source, fileName) }
                walkForOptionalParamsInStmt(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                walkForOptionalParamsInStmt(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                walkForOptionalParamsInStmt(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                walkForOptionalParamsInStmt(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                walkForOptionalParamsInStmt(stmt.statement, source, fileName)
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> {
                            walkForOptionalParamsInExpr(clause.expression, source, fileName)
                            clause.statements
                        }
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    walkForOptionalParams(clauseStmts, source, fileName)
                }
            }
            is TryStatement -> {
                walkForOptionalParams(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForOptionalParams(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForOptionalParams(it.statements, source, fileName) }
            }
            is LabeledStatement -> walkForOptionalParamsInStmt(stmt.statement, source, fileName)
            is ThrowStatement -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            is ExportAssignment -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkForOptionalParamsInExpr(expr: Expression?, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkParamsForTS1015(expr.parameters, source, fileName, requireType = false)
                when (val body = expr.body) {
                    is Block -> walkForOptionalParams(body.statements, source, fileName)
                    is Expression -> walkForOptionalParamsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkParamsForTS1015(expr.parameters, source, fileName, requireType = false)
                walkForOptionalParams(expr.body.statements, source, fileName)
            }
            is ParenthesizedExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is AsExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is NewExpression -> {
                walkForOptionalParamsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { walkForOptionalParamsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkForOptionalParamsInExpr(expr.expression, source, fileName)
                walkForOptionalParamsInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkForOptionalParamsInExpr(it, source, fileName) }
            is TemplateExpression -> expr.templateSpans.forEach { walkForOptionalParamsInExpr(it.expression, source, fileName) }
            is TaggedTemplateExpression -> {
                walkForOptionalParamsInExpr(expr.tag, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { walkForOptionalParamsInExpr(it.expression, source, fileName) }
                    else -> {}
                }
            }
            is SpreadElement -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkForOptionalParamsInExpr(it, source, fileName) }
            is PrefixUnaryExpression -> walkForOptionalParamsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkForOptionalParamsInExpr(expr.operand, source, fileName)
            is CommaListExpression -> expr.elements.forEach { walkForOptionalParamsInExpr(it, source, fileName) }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkForOptionalParamsInExpr(current.right, source, fileName)
                    current = current.left
                }
                walkForOptionalParamsInExpr(current, source, fileName)
            }
            is ConditionalExpression -> {
                walkForOptionalParamsInExpr(expr.condition, source, fileName)
                walkForOptionalParamsInExpr(expr.whenTrue, source, fileName)
                walkForOptionalParamsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkForOptionalParamsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) walkForOptionalParamsInExpr(arg, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(prop.parameters, source, fileName)
                            prop.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is PropertyAssignment -> walkForOptionalParamsInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> walkForOptionalParamsInExpr(prop.expression, source, fileName)
                        is GetAccessor -> prop.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        is SetAccessor -> {
                            checkParamsForTS1015(prop.parameters, source, fileName)
                            prop.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is GetAccessor -> member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        is SetAccessor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is PropertyDeclaration -> member.initializer?.let { walkForOptionalParamsInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is VoidExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    private fun checkParamsForTS1015(params: List<Parameter>, source: String, fileName: String, requireType: Boolean = true) {
        for (param in params) {
            if (param.questionToken && param.initializer != null) {
                // In function/method/constructor declarations, TS1015 only fires when type annotation is present
                // or when the parameter has an access modifier (parameter property).
                // In arrow/function expressions, it fires regardless.
                val isParamProperty = param.modifiers.any { it == ModifierFlag.Public || it == ModifierFlag.Private || it == ModifierFlag.Protected || it == ModifierFlag.Readonly }
                if (requireType && param.type == null && !isParamProperty) continue
                val name = param.name
                val start = name.pos
                val length = when (name) {
                    is Identifier -> name.text.length
                    else -> (name.end - 1 - start).coerceAtLeast(1)
                }
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Parameter cannot have question mark and initializer.",
                    category = DiagnosticCategory.Error,
                    code = 1015,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1052: A 'set' accessor parameter cannot have an initializer
    // -----------------------------------------------------------------------

    private fun checkSetAccessorInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSetAccessorInit(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSetAccessorInit(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        if (member is SetAccessor && member.parameters.any { it.initializer != null }) {
                            val name = member.name
                            val start = name.pos
                            val length = when (name) {
                                is Identifier -> name.text.length
                                else -> (name.end - 1 - start).coerceAtLeast(1)
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "A 'set' accessor parameter cannot have an initializer.",
                                category = DiagnosticCategory.Error,
                                code = 1052,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForSetAccessorInit(it.statements, source, fileName) }
                is Block -> walkForSetAccessorInit(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForSetAccessorInit(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForSetAccessorInit(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForSetAccessorInit(clause.statements, source, fileName)
                        is DefaultClause -> walkForSetAccessorInit(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForSetAccessorInit(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForSetAccessorInit(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForSetAccessorInit(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForSetAccessorInit(listOf(stmt.statement), source, fileName)
                is FunctionDeclaration -> stmt.body?.let { walkForSetAccessorInit(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1053: A 'set' accessor cannot have rest parameter
    // -----------------------------------------------------------------------

    private fun checkSetAccessorRestParameter() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSetAccessorRest(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSetAccessorRest(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        if (member is SetAccessor) {
                            for (param in member.parameters) {
                                if (param.dotDotDotToken) {
                                    // Squiggle on `...` (3 chars), at name.pos - 3
                                    val namePos = when (val n = param.name) {
                                        is Identifier -> n.pos
                                        else -> param.pos
                                    }
                                    val start = namePos - 3
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "A 'set' accessor cannot have rest parameter.",
                                        category = DiagnosticCategory.Error,
                                        code = 1053,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = 3,
                                    ))
                                }
                            }
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForSetAccessorRest(it.statements, source, fileName) }
                is Block -> walkForSetAccessorRest(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForSetAccessorRest(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForSetAccessorRest(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForSetAccessorRest(clause.statements, source, fileName)
                        is DefaultClause -> walkForSetAccessorRest(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForSetAccessorRest(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForSetAccessorRest(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForSetAccessorRest(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForSetAccessorRest(listOf(stmt.statement), source, fileName)
                is FunctionDeclaration -> stmt.body?.let { walkForSetAccessorRest(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2404: The left-hand side of a 'for...in' statement cannot use a type annotation
    // -----------------------------------------------------------------------

    private fun checkForInLhsTypeAnnotation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForInLhsType(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForInLhsType(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ForInStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList) {
                        for (decl in init.declarations) {
                            if (decl.type == null) continue
                            // TypeScript squiggles the variable name, not the `:`.
                            val namePos = decl.name.pos
                            val nameLen = when (val n = decl.name) {
                                is Identifier -> n.text.length.coerceAtLeast(1)
                                else -> 1
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, namePos)
                            diagnostics.add(Diagnostic(
                                message = "The left-hand side of a 'for...in' statement cannot use a type annotation.",
                                category = DiagnosticCategory.Error,
                                code = 2404,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = namePos,
                                length = nameLen,
                            ))
                        }
                    }
                }
                is Block -> walkForInLhsType(stmt.statements, source, fileName)
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForInLhsType(it.statements, source, fileName) }
                is FunctionDeclaration -> stmt.body?.let { walkForInLhsType(it.statements, source, fileName) }
                is IfStatement -> {
                    walkForInLhsType(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForInLhsType(listOf(it), source, fileName) }
                }
                is WhileStatement -> walkForInLhsType(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForInLhsType(listOf(stmt.statement), source, fileName)
                is ForStatement -> walkForInLhsType(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForInLhsType(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForInLhsType(clause.statements, source, fileName)
                        is DefaultClause -> walkForInLhsType(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForInLhsType(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForInLhsType(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForInLhsType(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForInLhsType(listOf(stmt.statement), source, fileName)
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1036: Statements are not allowed in ambient contexts
    // -----------------------------------------------------------------------

    private fun checkAmbientStatements() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && ModifierFlag.Declare in stmt.modifiers) {
                    val body = stmt.body
                    if (body is ModuleBlock) checkStatementsInAmbient(body.statements, source, fileName)
                }
            }
        }
    }

    private fun isValidAmbientStatement(stmt: Statement): Boolean = when (stmt) {
        is VariableStatement -> true
        is FunctionDeclaration -> true
        is ClassDeclaration -> true
        is InterfaceDeclaration -> true
        is TypeAliasDeclaration -> true
        is EnumDeclaration -> true
        is ModuleDeclaration -> true
        is ImportDeclaration -> true
        is ImportEqualsDeclaration -> true
        is ExportDeclaration -> true
        is ExportAssignment -> true
        else -> false
    }

    private fun checkStatementsInAmbient(stmts: List<Statement>, source: String, fileName: String) {
        var reported = false
        for (stmt in stmts) {
            if (!reported && !isValidAmbientStatement(stmt)) {
                reported = true
                // Report TS1036 — squiggle on the first token of the statement
                val start = stmt.pos
                val stmtEnd = stmt.end
                // Skip leading whitespace/trivia
                var spanStart = start
                while (spanStart < stmtEnd && spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                if (spanStart >= source.length) continue
                // Find the length of the first token (keyword or semicolon)
                var spanEnd = spanStart
                if (source[spanEnd] == ';') {
                    spanEnd++ // empty statement — just the semicolon
                } else {
                    while (spanEnd < source.length && source[spanEnd].isLetterOrDigit()) spanEnd++
                }
                val length = (spanEnd - spanStart).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "Statements are not allowed in ambient contexts.",
                    category = DiagnosticCategory.Error,
                    code = 1036,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
            }
            // Recurse into nested namespaces (including non-declare ones inside declare)
            if (stmt is ModuleDeclaration) {
                val body = stmt.body
                if (body is ModuleBlock) checkStatementsInAmbient(body.statements, source, fileName)
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1038: A 'declare' modifier cannot be used in an already ambient context
    // -----------------------------------------------------------------------
    //
    // Fires for any declaration carrying the `declare` modifier when nested
    // inside a `declare namespace` body. (Top-level declarations in `.d.ts`
    // files are NOT flagged — TypeScript treats `declare` at file scope as
    // standard practice in declaration files.)

    private fun checkRedundantDeclareModifier() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            walkRedundantDeclare(result.sourceFile.statements, source, fileName, inAmbientNamespace = false)
        }
    }

    private fun statementHasDeclareModifier(stmt: Statement): Boolean = when (stmt) {
        is VariableStatement -> ModifierFlag.Declare in stmt.modifiers
        is FunctionDeclaration -> ModifierFlag.Declare in stmt.modifiers
        is ClassDeclaration -> ModifierFlag.Declare in stmt.modifiers
        is InterfaceDeclaration -> ModifierFlag.Declare in stmt.modifiers
        is TypeAliasDeclaration -> ModifierFlag.Declare in stmt.modifiers
        is EnumDeclaration -> ModifierFlag.Declare in stmt.modifiers
        is ModuleDeclaration -> ModifierFlag.Declare in stmt.modifiers
        // B61.5g: ImportEqualsDeclaration with declare in ambient context → TS1038.
        is ImportEqualsDeclaration -> ModifierFlag.Declare in stmt.modifiers
        else -> false
    }

    private fun walkRedundantDeclare(
        stmts: List<Statement>,
        source: String,
        fileName: String,
        inAmbientNamespace: Boolean,
    ) {
        for (stmt in stmts) {
            if (inAmbientNamespace && statementHasDeclareModifier(stmt)) {
                // Locate the `declare` keyword span. The parser captures
                // `stmt.pos` at the START of the declaration KEYWORD (var /
                // function / class / namespace) — `declare` is consumed before
                // `parseXyzDeclaration` is called, so the keyword's position
                // sits BEHIND `stmt.pos`. Search backward through trivia to
                // find the `e` then the start of `declare`.
                val DECLARE = "declare"
                val limit = (stmt.pos - 64).coerceAtLeast(0)
                var declareStart = -1
                var idx = stmt.pos.coerceAtMost(source.length) - DECLARE.length
                while (idx >= limit) {
                    if (idx >= 0 && idx + DECLARE.length <= source.length
                        && source.regionMatches(idx, DECLARE, 0, DECLARE.length)) {
                        val before = if (idx > 0) source[idx - 1] else ' '
                        val after = source[idx + DECLARE.length]
                        // Must be word-bounded on both sides.
                        if (!before.isLetterOrDigit() && before != '_' && before != '$'
                            && !after.isLetterOrDigit() && after != '_' && after != '$') {
                            declareStart = idx
                            break
                        }
                    }
                    idx--
                }
                if (declareStart >= 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, declareStart)
                    diagnostics.add(Diagnostic(
                        message = "A 'declare' modifier cannot be used in an already ambient context.",
                        category = DiagnosticCategory.Error,
                        code = 1038,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = declareStart,
                        length = DECLARE.length,
                    ))
                }
            }
            if (stmt is ModuleDeclaration) {
                val nowAmbient = inAmbientNamespace || ModifierFlag.Declare in stmt.modifiers
                (stmt.body as? ModuleBlock)?.let {
                    walkRedundantDeclare(it.statements, source, fileName, nowAmbient)
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2371: A parameter initializer is only allowed in a function or
    //         constructor implementation
    // -----------------------------------------------------------------------

    private fun checkParameterInitializerInNonImpl() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForParamInitNonImpl(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForParamInitNonImpl(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null) {
                        reportTS2371ForParams(stmt.parameters, source, fileName)
                    }
                    stmt.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                if (member.body == null) {
                                    reportTS2371ForParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                            }
                            is Constructor -> {
                                if (member.body == null) {
                                    reportTS2371ForParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                            }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) {
                            reportTS2371ForParams(member.parameters, source, fileName)
                        }
                    }
                }
                is VariableStatement -> {
                    // Check function type annotations in variable declarations
                    // e.g., var f: (a = 3) => number
                    for (decl in stmt.declarationList.declarations) {
                        checkFunctionTypeParams(decl.type, source, fileName)
                        // Also check initializers for type assertions with function types
                        checkExprForFunctionTypeParams(decl.initializer, source, fileName)
                    }
                }
                is TypeAliasDeclaration -> {
                    checkFunctionTypeParams(stmt.type, source, fileName)
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                }
                is Block -> walkForParamInitNonImpl(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForParamInitNonImpl(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForParamInitNonImpl(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForParamInitNonImpl(clause.statements, source, fileName)
                        is DefaultClause -> walkForParamInitNonImpl(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForParamInitNonImpl(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForParamInitNonImpl(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForParamInitNonImpl(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkFunctionTypeParams(type: TypeNode?, source: String, fileName: String) {
        when (type) {
            is FunctionType -> reportTS2371ForParams(type.parameters, source, fileName)
            is ConstructorType -> reportTS2371ForParams(type.parameters, source, fileName)
            is ParenthesizedType -> checkFunctionTypeParams(type.type, source, fileName)
            is UnionType -> for (t in type.types) checkFunctionTypeParams(t, source, fileName)
            is IntersectionType -> for (t in type.types) checkFunctionTypeParams(t, source, fileName)
            is ArrayType -> checkFunctionTypeParams(type.elementType, source, fileName)
            is TupleType -> for (el in type.elements) checkFunctionTypeParams(el, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { checkFunctionTypeParams(it, source, fileName) }
            is ConditionalType -> {
                checkFunctionTypeParams(type.checkType, source, fileName)
                checkFunctionTypeParams(type.extendsType, source, fileName)
                checkFunctionTypeParams(type.trueType, source, fileName)
                checkFunctionTypeParams(type.falseType, source, fileName)
            }
            is IndexedAccessType -> {
                checkFunctionTypeParams(type.objectType, source, fileName)
                checkFunctionTypeParams(type.indexType, source, fileName)
            }
            is TypeOperator -> checkFunctionTypeParams(type.type, source, fileName)
            is RestType -> checkFunctionTypeParams(type.type, source, fileName)
            is OptionalType -> checkFunctionTypeParams(type.type, source, fileName)
            is NamedTupleMember -> checkFunctionTypeParams(type.type, source, fileName)
            is TypeLiteral -> for (m in type.members) when (m) {
                is PropertyDeclaration -> checkFunctionTypeParams(m.type, source, fileName)
                is MethodDeclaration -> {
                    for (p in m.parameters) checkFunctionTypeParams(p.type, source, fileName)
                    checkFunctionTypeParams(m.type, source, fileName)
                }
                is IndexSignature -> checkFunctionTypeParams(m.type, source, fileName)
                else -> {}
            }
            else -> {}
        }
    }

    private fun checkExprForFunctionTypeParams(expr: Expression?, source: String, fileName: String) {
        when (expr) {
            is TypeAssertionExpression -> checkFunctionTypeParams(expr.type, source, fileName)
            is AsExpression -> checkFunctionTypeParams(expr.type, source, fileName)
            is SatisfiesExpression -> {
                checkFunctionTypeParams(expr.type, source, fileName)
                checkExprForFunctionTypeParams(expr.expression, source, fileName)
            }
            is ParenthesizedExpression -> checkExprForFunctionTypeParams(expr.expression, source, fileName)
            is NonNullExpression -> checkExprForFunctionTypeParams(expr.expression, source, fileName)
            else -> {}
        }
    }

    private fun reportTS2371ForParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            val init = param.initializer
            if (init != null) {
                // Param-level default: `(a = 1)` / `(a: T = 1)`.
                // Span starts at beginning of parameter (including access modifiers like 'public')
                var spanStart = param.pos
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                // Span from spanStart to initializer end, trimming trailing trivia
                var spanEnd = init.end
                while (spanEnd > spanStart && spanEnd <= source.length &&
                    source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' || it == ';' }) {
                    spanEnd--
                }
                val length = (spanEnd - spanStart).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "A parameter initializer is only allowed in a function or constructor implementation.",
                    category = DiagnosticCategory.Error,
                    code = 2371,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
            }
            // B51.3: Binding-pattern defaults: `({first = 0}: T)` — TS2371 fires for
            // each binding-element with a default initializer (recursive for nested
            // patterns). Squiggle on the binding-element's name (not the whole
            // param), matching TypeScript's baseline span.
            reportTS2371ForBindingPattern(param.name, source, fileName)
        }
    }

    private fun reportTS2371ForBindingPattern(name: Expression, source: String, fileName: String) {
        val pattern = when (name) {
            is ObjectBindingPattern -> name.elements
            is ArrayBindingPattern -> name.elements
            else -> return
        }
        for (el in pattern) {
            if (el !is BindingElement) continue
            if (el.initializer != null) {
                val nameNode = el.name
                val (start, len) = when (nameNode) {
                    is Identifier -> nameNode.pos to nameNode.text.length
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        // For nested patterns, span covers the pattern's name part.
                        // Use the binding-element's position as approximate start.
                        var s = el.pos
                        while (s < source.length && source[s].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) s++
                        s to 1
                    }
                    else -> continue
                }
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "A parameter initializer is only allowed in a function or constructor implementation.",
                    category = DiagnosticCategory.Error,
                    code = 2371,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = len,
                ))
            }
            // Recurse into nested patterns
            if (el.name is ObjectBindingPattern || el.name is ArrayBindingPattern) {
                reportTS2371ForBindingPattern(el.name, source, fileName)
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2373: Parameter 'X' cannot reference identifier 'Y' declared after it.
    // Narrow: later-parameter references only (body-var case is deferred because
    // of TS2304 interaction under ES2015+ parameter-scope rules).
    // -----------------------------------------------------------------------

    private fun checkParamInitForwardRef() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForParamInitForwardRef(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForParamInitForwardRef(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    stmt.body?.let { body ->
                        checkForwardRefsInParams(stmt.parameters, source, fileName, body)
                        walkForParamInitForwardRef(body.statements, source, fileName)
                    }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { body ->
                                checkForwardRefsInParams(member.parameters, source, fileName, body)
                                walkForParamInitForwardRef(body.statements, source, fileName)
                            }
                            is Constructor -> member.body?.let { body ->
                                checkForwardRefsInParams(member.parameters, source, fileName, body)
                                walkForParamInitForwardRef(body.statements, source, fileName)
                            }
                            is GetAccessor -> member.body?.let { body ->
                                walkForParamInitForwardRef(body.statements, source, fileName)
                            }
                            is SetAccessor -> member.body?.let { body ->
                                checkForwardRefsInParams(member.parameters, source, fileName, body)
                                walkForParamInitForwardRef(body.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForParamInitForwardRef(it.statements, source, fileName) }
                is Block -> walkForParamInitForwardRef(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForParamInitForwardRef(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForParamInitForwardRef(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForParamInitForwardRef(clause.statements, source, fileName)
                        is DefaultClause -> walkForParamInitForwardRef(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForParamInitForwardRef(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.statements?.let { walkForParamInitForwardRef(it, source, fileName) }
                    stmt.finallyBlock?.statements?.let { walkForParamInitForwardRef(it, source, fileName) }
                }
                is LabeledStatement -> walkForParamInitForwardRef(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkForwardRefsInParams(
        params: List<Parameter>,
        source: String,
        fileName: String,
        body: Block? = null,
    ) {
        if (params.isEmpty()) return
        val paramNames = params.map { (it.name as? Identifier)?.text }
        val paramNameSet = paramNames.filterNotNull().toSet()
        // Under ES5, `var` declarations hoist into the function scope — shared with
        // parameters — so a param initializer like `y = b` where `b` is declared
        // `var b` in the body resolves to the hoisted body-var. The existing TS2304
        // path (checkUnresolvedInFunctionLike) suppresses TS2304 for this case under
        // ES5; TypeScript instead fires TS2373 ("parameter ... cannot reference X
        // declared after it") + TS2454 ("used before being assigned"). Collect the
        // hoisted body-var names that aren't shadowed by param names.
        val bodyVarRefs: Set<String> = if (body != null && options.target < ScriptTarget.ES2015) {
            val names = mutableSetOf<String>()
            collectHoistedVarNamesFromStmts(body.statements, names)
            names - paramNameSet
        } else emptySet()
        if (params.size < 2 && bodyVarRefs.isEmpty()) return
        for (i in params.indices) {
            val p = params[i]
            val pName = paramNames[i] ?: continue
            val init = p.initializer ?: continue
            val laterParams = mutableSetOf<String>()
            for (j in (i + 1)..<params.size) {
                paramNames[j]?.let { laterParams.add(it) }
            }
            val allRefs = laterParams + bodyVarRefs
            if (allRefs.isEmpty()) continue
            findForwardParamRefs(init, pName, allRefs, source, fileName, bodyVarRefs)
        }
    }

    /** Collect hoisted `var` declaration names from a statement list into [out].
     *  Simpler alternative to the NameScope-based [collectHoistedVarNames] — used
     *  by the ES5 param-forward-ref check. Recurses through block/if/loops but
     *  does NOT descend into nested function bodies (each has its own scope). */
    private fun collectHoistedVarNamesFromStmts(stmts: List<Statement>, out: MutableSet<String>) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags == SyntaxKind.VarKeyword) {
                        for (decl in stmt.declarationList.declarations) {
                            (decl.name as? Identifier)?.text?.let { out.add(it) }
                        }
                    }
                }
                is Block -> collectHoistedVarNamesFromStmts(stmt.statements, out)
                is IfStatement -> {
                    collectHoistedVarNamesFromStmts(listOf(stmt.thenStatement), out)
                    stmt.elseStatement?.let { collectHoistedVarNamesFromStmts(listOf(it), out) }
                }
                is ForStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) (decl.name as? Identifier)?.text?.let { out.add(it) }
                    }
                    collectHoistedVarNamesFromStmts(listOf(stmt.statement), out)
                }
                is ForInStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) (decl.name as? Identifier)?.text?.let { out.add(it) }
                    }
                    collectHoistedVarNamesFromStmts(listOf(stmt.statement), out)
                }
                is ForOfStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.VarKeyword) {
                        for (decl in init.declarations) (decl.name as? Identifier)?.text?.let { out.add(it) }
                    }
                    collectHoistedVarNamesFromStmts(listOf(stmt.statement), out)
                }
                is WhileStatement -> collectHoistedVarNamesFromStmts(listOf(stmt.statement), out)
                is DoStatement -> collectHoistedVarNamesFromStmts(listOf(stmt.statement), out)
                is TryStatement -> {
                    collectHoistedVarNamesFromStmts(stmt.tryBlock.statements, out)
                    stmt.catchClause?.block?.statements?.let { collectHoistedVarNamesFromStmts(it, out) }
                    stmt.finallyBlock?.statements?.let { collectHoistedVarNamesFromStmts(it, out) }
                }
                else -> {}
            }
        }
    }

    /** Walk an expression tree and emit TS2373 for Identifier references that resolve
     * to a later parameter. Skips nested function/arrow/class bodies (they have their
     * own scope and aren't evaluated during param initialization).
     *
     * [bodyVarRefs] (ES5 only) names a subset of [laterParams] that correspond to
     * hoisted body `var` declarations rather than later function parameters. When
     * the matched identifier is in this subset, also emit TS2454 ("used before
     * being assigned"). */
    private fun findForwardParamRefs(
        expr: Expression,
        currentParamName: String,
        laterParams: Set<String>,
        source: String,
        fileName: String,
        bodyVarRefs: Set<String> = emptySet(),
    ) {
        when (expr) {
            is Identifier -> {
                val name = expr.text
                if (name in laterParams) {
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                    diagnostics.add(Diagnostic(
                        message = "Parameter '$currentParamName' cannot reference identifier '$name' declared after it.",
                        category = DiagnosticCategory.Error,
                        code = 2373,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.pos,
                        length = name.length,
                    ))
                    if (name in bodyVarRefs) {
                        diagnostics.add(Diagnostic(
                            message = "Variable '$name' is used before being assigned.",
                            category = DiagnosticCategory.Error,
                            code = 2454,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = expr.pos,
                            length = name.length,
                        ))
                    }
                }
            }
            is BinaryExpression -> {
                findForwardParamRefs(expr.left, currentParamName, laterParams, source, fileName, bodyVarRefs)
                findForwardParamRefs(expr.right, currentParamName, laterParams, source, fileName, bodyVarRefs)
            }
            is PrefixUnaryExpression -> findForwardParamRefs(expr.operand, currentParamName, laterParams, source, fileName, bodyVarRefs)
            is PostfixUnaryExpression -> findForwardParamRefs(expr.operand, currentParamName, laterParams, source, fileName, bodyVarRefs)
            is ParenthesizedExpression -> findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
            is ConditionalExpression -> {
                findForwardParamRefs(expr.condition, currentParamName, laterParams, source, fileName, bodyVarRefs)
                findForwardParamRefs(expr.whenTrue, currentParamName, laterParams, source, fileName, bodyVarRefs)
                findForwardParamRefs(expr.whenFalse, currentParamName, laterParams, source, fileName, bodyVarRefs)
            }
            is CallExpression -> {
                // IIFE: `(() => z)()` or `(function() { return z })()` — the callee body
                // evaluates immediately. Descend into it so later-param refs fire here too.
                // Skip generator IIFEs (return a Generator without running the body) and
                // async IIFEs (TypeScript's baseline treats these as OK in param-init scope).
                val callee = (expr.expression as? ParenthesizedExpression)?.expression ?: expr.expression
                when (callee) {
                    is ArrowFunction -> {
                        val isAsync = ModifierFlag.Async in callee.modifiers
                        // Exclude laterParams that the IIFE's own params shadow — otherwise
                        // `((z) => z)()` would falsely flag the inner `z` against an outer `z` param.
                        val inner = laterParams - callee.parameters.mapNotNull { (it.name as? Identifier)?.text }.toSet()
                        if (!isAsync && !callee.asteriskToken && inner.isNotEmpty()) {
                            when (val body = callee.body) {
                                is Expression -> findForwardParamRefs(body, currentParamName, inner, source, fileName, bodyVarRefs)
                                is Block -> findForwardParamRefsInBlock(body, currentParamName, inner, source, fileName, bodyVarRefs)
                                else -> {}
                            }
                        }
                    }
                    is FunctionExpression -> {
                        val isAsync = ModifierFlag.Async in callee.modifiers
                        val inner = laterParams - callee.parameters.mapNotNull { (it.name as? Identifier)?.text }.toSet()
                        if (!isAsync && !callee.asteriskToken && inner.isNotEmpty()) {
                            findForwardParamRefsInBlock(callee.body, currentParamName, inner, source, fileName, bodyVarRefs)
                        }
                    }
                    else -> findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                }
                expr.arguments.forEach { findForwardParamRefs(it, currentParamName, laterParams, source, fileName, bodyVarRefs) }
            }
            is NewExpression -> {
                findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                expr.arguments?.forEach { findForwardParamRefs(it, currentParamName, laterParams, source, fileName, bodyVarRefs) }
            }
            is PropertyAccessExpression -> findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
            is ElementAccessExpression -> {
                findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                findForwardParamRefs(expr.argumentExpression, currentParamName, laterParams, source, fileName, bodyVarRefs)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { findForwardParamRefs(it, currentParamName, laterParams, source, fileName, bodyVarRefs) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            // Computed property keys evaluate eagerly when the object literal is built.
                            (prop.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                            findForwardParamRefs(prop.initializer, currentParamName, laterParams, source, fileName, bodyVarRefs)
                        }
                        is ShorthandPropertyAssignment -> findForwardParamRefs(prop.name, currentParamName, laterParams, source, fileName, bodyVarRefs)
                        is MethodDeclaration -> {
                            // Only the computed key evaluates eagerly; the method body is deferred.
                            (prop.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        is GetAccessor -> {
                            (prop.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        is SetAccessor -> {
                            (prop.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        else -> {}
                    }
                }
            }
            is SpreadElement -> findForwardParamRefs(expr.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
            is ClassExpression -> {
                // Eagerly evaluated at class-expr eval time (= param-init time):
                //   - computed property/method/accessor keys (always)
                //   - static field initializers
                //   - static blocks
                // Deferred (NOT walked):
                //   - method/accessor/constructor BODIES
                //   - instance field initializers
                //   - constructor parameter defaults
                for (member in expr.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            (member.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                            if (ModifierFlag.Static in member.modifiers) {
                                member.initializer?.let {
                                    findForwardParamRefs(it, currentParamName, laterParams, source, fileName, bodyVarRefs)
                                }
                            }
                        }
                        is MethodDeclaration -> {
                            (member.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        is GetAccessor -> {
                            (member.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        is SetAccessor -> {
                            (member.name as? ComputedPropertyName)?.let {
                                findForwardParamRefs(it.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                            }
                        }
                        is ClassStaticBlockDeclaration -> {
                            findForwardParamRefsInBlock(member.body, currentParamName, laterParams, source, fileName, bodyVarRefs)
                        }
                        else -> {}
                    }
                }
            }
            // Skip ArrowFunction, FunctionExpression — own scope, not immediately evaluated.
            // Skip TypeAssertionExpression / AsExpression — TypeScript doesn't fire in type positions.
            else -> {}
        }
    }

    /** Walk an IIFE body (Block) for TS2373 later-param refs. Only return-statement
     *  expressions and top-level expression statements are walked — nested blocks/
     *  functions would re-create scopes we don't model here. */
    private fun findForwardParamRefsInBlock(
        body: Block,
        currentParamName: String,
        laterParams: Set<String>,
        source: String,
        fileName: String,
        bodyVarRefs: Set<String> = emptySet(),
    ) {
        for (stmt in body.statements) {
            when (stmt) {
                is ReturnStatement -> stmt.expression?.let {
                    findForwardParamRefs(it, currentParamName, laterParams, source, fileName, bodyVarRefs)
                }
                is ExpressionStatement -> findForwardParamRefs(stmt.expression, currentParamName, laterParams, source, fileName, bodyVarRefs)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1212: Strict mode reserved word as identifier
    // -----------------------------------------------------------------------

    private fun checkStrictModeReservedWords() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Determine if file is in strict mode:
            // - target >= ES2015 (implicit strict)
            // - "use strict" prologue directive
            // - module file (ESM is strict)
            val isModule = isModuleFile(result.sourceFile.statements)
            val hasUseStrict = result.sourceFile.statements.firstOrNull()?.let { stmt ->
                stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                    (stmt.expression as StringLiteralNode).text == "use strict"
            } == true
            // Use effectiveTarget so ES3/ES5 targets also fire TS1212 for binding names
            // (TypeScript fires TS1212 for reserved words in binding positions at all targets)
            val isStrict = options.effectiveTarget >= ScriptTarget.ES2015 ||
                options.strict == true ||
                options.alwaysStrict == true ||
                isModule ||
                hasUseStrict
            // For expression-position TS1212: fire when explicitly strict, NOT just target >= ES2015.
            // Target alone doesn't make file-level code strict — only classes, modules, and explicit flags do.
            // When alwaysStrict is explicitly false, suppress the target-based strictness.
            val isExpressionStrict = if (options.alwaysStrict == false && options.strictExplicitlyFalse) {
                // Explicitly non-strict: only fire if module or has "use strict"
                isModule || hasUseStrict
            } else {
                options.target >= ScriptTarget.ES2015 ||
                    options.strict == true ||
                    options.alwaysStrict == true ||
                    isModule ||
                    hasUseStrict
            }
            // TS2480 runs unconditionally; TS1212 runs in let/const contexts even without global strict
            walkForStrictReserved(result.sourceFile.statements, source, fileName, isStrict = isStrict, isExpressionStrict = isExpressionStrict, isModule = isModule)
        }
    }

    private fun walkForStrictReserved(stmts: List<Statement>, source: String, fileName: String, inClass: Boolean = false, isStrict: Boolean = true, isExpressionStrict: Boolean = isStrict, isModule: Boolean = false) {
        for (stmt in stmts) walkStmtForStrictReserved(stmt, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
    }

    private fun walkStmtForStrictReserved(stmt: Statement, source: String, fileName: String, inClass: Boolean = false, isStrict: Boolean = true, isExpressionStrict: Boolean = isStrict, isModule: Boolean = false) {
        when (stmt) {
            is VariableStatement -> {
                val isLetOrConst = stmt.declarationList.flags == SyntaxKind.LetKeyword || stmt.declarationList.flags == SyntaxKind.ConstKeyword
                for (decl in stmt.declarationList.declarations) {
                    // TS1212 fires in strict mode OR in let/const declarations (let/const implies strict for reserved words)
                    if (isStrict || isLetOrConst) checkNodeForStrictReserved(decl.name, source, fileName, inClass, isModule)
                    // TS2480 fires unconditionally for 'let' in let/const declarations
                    checkLetInLetOrConst(decl.name, stmt.declarationList.flags, source, fileName)
                }
            }
            is FunctionDeclaration -> if (isStrict) {
                val name = stmt.name
                if (name != null) checkIdentForStrictReserved(name, source, fileName, inClass, isModule)
                checkParamsForStrictReserved(stmt.parameters, source, fileName, inClass, isModule)
                stmt.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass, isStrict, isExpressionStrict, isModule) }
            }
            is ClassDeclaration -> if (isStrict) {
                val name = stmt.name
                if (name != null) checkIdentForStrictReserved(name, source, fileName, inClass, isModule)
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            checkParamsForStrictReserved(member.parameters, source, fileName, inClass = true, isModule = isModule)
                            member.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass = true, isStrict = isStrict, isExpressionStrict = isExpressionStrict, isModule = isModule) }
                        }
                        is Constructor -> {
                            checkParamsForStrictReserved(member.parameters, source, fileName, inClass = true, isModule = isModule)
                            member.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass = true, isStrict = isStrict, isExpressionStrict = isExpressionStrict, isModule = isModule) }
                        }
                        else -> {}
                    }
                }
            }
            is InterfaceDeclaration -> if (isStrict) {
                checkIdentForStrictReserved(stmt.name, source, fileName, inClass, isModule)
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> checkParamsForStrictReserved(member.parameters, source, fileName, inClass, isModule)
                        is Constructor -> checkParamsForStrictReserved(member.parameters, source, fileName, inClass, isModule)
                        is IndexSignature -> checkParamsForStrictReserved(member.parameters, source, fileName, inClass, isModule)
                        else -> {}
                    }
                }
            }
            is EnumDeclaration -> if (isStrict) {
                checkIdentForStrictReserved(stmt.name, source, fileName, inClass, isModule)
            }
            is ImportEqualsDeclaration -> if (isStrict) {
                checkIdentForStrictReserved(stmt.name, source, fileName, inClass, isModule)
            }
            is ImportDeclaration -> if (isStrict) {
                val clause = stmt.importClause
                if (clause != null) {
                    clause.name?.let { checkIdentForStrictReserved(it, source, fileName, inClass, isModule) }
                    when (val bindings = clause.namedBindings) {
                        is NamespaceImport -> checkIdentForStrictReserved(bindings.name, source, fileName, inClass, isModule)
                        is NamedImports -> for (spec in bindings.elements) checkIdentForStrictReserved(spec.name, source, fileName, inClass, isModule)
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> if (isStrict) {
                val name = stmt.name
                checkExprForStrictReservedIdents(name, source, fileName, inClass)
                val body = stmt.body
                when (body) {
                    is ModuleBlock -> walkForStrictReserved(body.statements, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
                    is ModuleDeclaration -> walkStmtForStrictReserved(body, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
                    else -> {}
                }
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val isLetOrConst = init.flags == SyntaxKind.LetKeyword || init.flags == SyntaxKind.ConstKeyword
                    for (d in init.declarations) {
                        if (isStrict || isLetOrConst) checkNodeForStrictReserved(d.name, source, fileName, inClass, isModule)
                        checkLetInLetOrConst(d.name, init.flags, source, fileName)
                    }
                }
                walkStmtForStrictReserved(stmt.statement, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val isLetOrConst = init.flags == SyntaxKind.LetKeyword || init.flags == SyntaxKind.ConstKeyword
                    for (d in init.declarations) {
                        if (isStrict || isLetOrConst) checkNodeForStrictReserved(d.name, source, fileName, inClass, isModule)
                        checkLetInLetOrConst(d.name, init.flags, source, fileName)
                    }
                }
                walkStmtForStrictReserved(stmt.statement, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
            }
            is Block -> walkForStrictReserved(stmt.statements, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
            is IfStatement -> {
                walkStmtForStrictReserved(stmt.thenStatement, source, fileName, inClass, isStrict, isExpressionStrict, isModule)
                stmt.elseStatement?.let { walkStmtForStrictReserved(it, source, fileName, inClass, isStrict, isExpressionStrict, isModule) }
            }
            is ExpressionStatement -> if (isExpressionStrict) {
                // TS1212 for reserved words in expression position only when explicitly strict
                // (alwaysStrict, "use strict", module, strict:true) — NOT just target >= ES2015.
                checkExprForStrictReserved(stmt.expression, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkNodeForStrictReserved(node: Node, source: String, fileName: String, inClass: Boolean = false, isModule: Boolean = false) {
        when (node) {
            is Identifier -> checkIdentForStrictReserved(node, source, fileName, inClass, isModule)
            is ObjectBindingPattern -> {
                for (el in node.elements) {
                    checkNodeForStrictReserved(el.name, source, fileName, inClass, isModule)
                }
            }
            is ArrayBindingPattern -> {
                for (el in node.elements) {
                    if (el is BindingElement) checkNodeForStrictReserved(el.name, source, fileName, inClass, isModule)
                }
            }
            else -> {}
        }
    }

    /** B18.2: iterate parameters checking strict-reserved names while suppressing
     *  diagnostics on a rest parameter that is immediately followed by a parameter
     *  created via B17.7's comma-recovery (e.g. `(...public rest)`). TypeScript
     *  treats the parser's TS1005 as the only diagnostic for this shape. */
    private fun checkParamsForStrictReserved(
        params: List<Parameter>,
        source: String, fileName: String,
        inClass: Boolean = false, isModule: Boolean = false,
    ) {
        for ((i, p) in params.withIndex()) {
            val next = params.getOrNull(i + 1)
            if (p.dotDotDotToken && next?.commaRecovered == true) continue
            checkNodeForStrictReserved(p.name, source, fileName, inClass, isModule)
        }
    }

    /** Check all identifiers in an expression tree for strict-mode reserved words */
    private fun checkExprForStrictReservedIdents(expr: Expression, source: String, fileName: String, inClass: Boolean = false) {
        when (expr) {
            is Identifier -> checkIdentForStrictReserved(expr, source, fileName, inClass)
            is PropertyAccessExpression -> {
                checkExprForStrictReservedIdents(expr.expression, source, fileName, inClass)
                checkIdentForStrictReserved(expr.name, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkExprForStrictReserved(expr: Expression, source: String, fileName: String, inClass: Boolean = false) {
        when (expr) {
            is Identifier -> {
                if (expr.text in STRICT_MODE_RESERVED_WORDS) {
                    // Only in assignment context (let = 30)
                    // Actually, all uses of reserved words as identifiers in expressions count
                    reportTS1212(expr, source, fileName, inClass)
                }
            }
            is BinaryExpression -> {
                checkExprForStrictReserved(expr.left, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkIdentForStrictReserved(id: Identifier, source: String, fileName: String, inClass: Boolean = false, isModule: Boolean = false) {
        if (id.text in STRICT_MODE_RESERVED_WORDS) {
            reportTS1212(id, source, fileName, inClass, isModule)
        }
    }

    private fun reportTS1212(id: Identifier, source: String, fileName: String, inClass: Boolean = false, isModule: Boolean = false) {
        val start = id.pos
        val length = id.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        when {
            inClass -> diagnostics.add(Diagnostic(
                message = "Identifier expected. '${id.text}' is a reserved word in strict mode. Class definitions are automatically in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1213,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            isModule -> diagnostics.add(Diagnostic(
                message = "Identifier expected. '${id.text}' is a reserved word in strict mode. Modules are automatically in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1214,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            else -> diagnostics.add(Diagnostic(
                message = "Identifier expected. '${id.text}' is a reserved word in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1212,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /** TS2480: 'let' is not allowed to be used as a name in 'let' or 'const' declarations. */
    private fun checkLetInLetOrConst(name: Node, flags: SyntaxKind, source: String, fileName: String) {
        if (name !is Identifier || name.text != "let") return
        if (flags != SyntaxKind.LetKeyword && flags != SyntaxKind.ConstKeyword) return
        val start = name.pos
        val length = name.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'let' is not allowed to be used as a name in 'let' or 'const' declarations.",
            category = DiagnosticCategory.Error,
            code = 2480,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2414/TS2427: Class/Interface name cannot be 'undefined'
    // -----------------------------------------------------------------------

    private fun checkUndefinedClassInterfaceName() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUndefinedNamesInStmts(result.sourceFile.statements, source, fileName)
        }
    }

    /**
     * 17.196: TS1163 — `yield` outside a generator function body. Walks
     * function bodies tracking generator (asterisk) state. ArrowFunction is
     * always non-generator. Function/Method declarations + expressions track
     * via `asteriskToken`.
     */
    private fun walkYieldInStmts(stmts: List<Statement>, source: String, fileName: String, isGenerator: Boolean) {
        for (stmt in stmts) walkYieldInStmt(stmt, source, fileName, isGenerator)
    }

    private fun walkYieldInStmt(stmt: Statement, source: String, fileName: String, isGenerator: Boolean) {
        when (stmt) {
            is ExpressionStatement -> walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
            }
            is ReturnStatement -> stmt.expression?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
            is FunctionDeclaration -> {
                stmt.body?.let { walkYieldInStmts(it.statements, source, fileName, stmt.asteriskToken) }
            }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.let {
                    walkYieldInStmts(it.statements, source, fileName, m.asteriskToken)
                }
                is Constructor -> m.body?.let { walkYieldInStmts(it.statements, source, fileName, false) }
                is GetAccessor -> m.body?.let { walkYieldInStmts(it.statements, source, fileName, false) }
                is SetAccessor -> m.body?.let { walkYieldInStmts(it.statements, source, fileName, false) }
                is PropertyDeclaration -> m.initializer?.let { walkYieldInExpr(it, source, fileName, false) }
                else -> {}
            }
            is Block -> walkYieldInStmts(stmt.statements, source, fileName, isGenerator)
            is IfStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                walkYieldInStmt(stmt.thenStatement, source, fileName, isGenerator)
                stmt.elseStatement?.let { walkYieldInStmt(it, source, fileName, isGenerator) }
            }
            is ForStatement -> {
                stmt.condition?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
                stmt.incrementor?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
                walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            }
            is ForInStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            }
            is ForOfStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            }
            is WhileStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            }
            is DoStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            }
            is SwitchStatement -> {
                walkYieldInExpr(stmt.expression, source, fileName, isGenerator)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        walkYieldInExpr(clause.expression, source, fileName, isGenerator)
                        walkYieldInStmts(clause.statements, source, fileName, isGenerator)
                    }
                    is DefaultClause -> walkYieldInStmts(clause.statements, source, fileName, isGenerator)
                    else -> {}
                }
            }
            is TryStatement -> {
                walkYieldInStmts(stmt.tryBlock.statements, source, fileName, isGenerator)
                stmt.catchClause?.block?.let { walkYieldInStmts(it.statements, source, fileName, isGenerator) }
                stmt.finallyBlock?.let { walkYieldInStmts(it.statements, source, fileName, isGenerator) }
            }
            is ThrowStatement -> stmt.expression?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
            is LabeledStatement -> walkYieldInStmt(stmt.statement, source, fileName, isGenerator)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                walkYieldInStmts(it.statements, source, fileName, false)
            }
            else -> {}
        }
    }

    private fun walkYieldInExpr(expr: Expression, source: String, fileName: String, isGenerator: Boolean) {
        when (expr) {
            is YieldExpression -> {
                if (!isGenerator) {
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                    diagnostics.add(Diagnostic(
                        message = "A 'yield' expression is only allowed in a generator body.",
                        category = DiagnosticCategory.Error,
                        code = 1163,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.pos,
                        length = 5,
                    ))
                }
                expr.expression?.let { walkYieldInExpr(it, source, fileName, isGenerator) }
            }
            is ArrowFunction -> when (val body = expr.body) {
                // Arrow functions cannot be generators
                is Block -> walkYieldInStmts(body.statements, source, fileName, false)
                is Expression -> walkYieldInExpr(body, source, fileName, false)
                else -> {}
            }
            is FunctionExpression -> {
                expr.body.let { walkYieldInStmts(it.statements, source, fileName, expr.asteriskToken) }
            }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let {
                    walkYieldInStmts(it.statements, source, fileName, m.asteriskToken)
                }
                is Constructor -> m.body?.let { walkYieldInStmts(it.statements, source, fileName, false) }
                else -> {}
            }
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkYieldInExpr(cur, source, fileName, isGenerator)
                while (rightStack.isNotEmpty()) walkYieldInExpr(rightStack.removeLast(), source, fileName, isGenerator)
            }
            is CallExpression -> {
                walkYieldInExpr(expr.expression, source, fileName, isGenerator)
                for (arg in expr.arguments) walkYieldInExpr(arg, source, fileName, isGenerator)
            }
            is NewExpression -> {
                walkYieldInExpr(expr.expression, source, fileName, isGenerator)
                expr.arguments?.forEach { walkYieldInExpr(it, source, fileName, isGenerator) }
            }
            is ParenthesizedExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is ConditionalExpression -> {
                walkYieldInExpr(expr.condition, source, fileName, isGenerator)
                walkYieldInExpr(expr.whenTrue, source, fileName, isGenerator)
                walkYieldInExpr(expr.whenFalse, source, fileName, isGenerator)
            }
            is PropertyAccessExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is ElementAccessExpression -> {
                walkYieldInExpr(expr.expression, source, fileName, isGenerator)
                walkYieldInExpr(expr.argumentExpression, source, fileName, isGenerator)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) walkYieldInExpr(el, source, fileName, isGenerator)
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkYieldInExpr(prop.initializer, source, fileName, isGenerator)
                is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let {
                    walkYieldInExpr(it, source, fileName, isGenerator)
                }
                is SpreadAssignment -> walkYieldInExpr(prop.expression, source, fileName, isGenerator)
                is MethodDeclaration -> prop.body?.let {
                    walkYieldInStmts(it.statements, source, fileName, prop.asteriskToken)
                }
                else -> {}
            }
            is PrefixUnaryExpression -> walkYieldInExpr(expr.operand, source, fileName, isGenerator)
            is PostfixUnaryExpression -> walkYieldInExpr(expr.operand, source, fileName, isGenerator)
            is SpreadElement -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is NonNullExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is AsExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is TypeAssertionExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is SatisfiesExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is AwaitExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is VoidExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is DeleteExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is TypeOfExpression -> walkYieldInExpr(expr.expression, source, fileName, isGenerator)
            is TemplateExpression -> for (span in expr.templateSpans) walkYieldInExpr(span.expression, source, fileName, isGenerator)
            is TaggedTemplateExpression -> {
                walkYieldInExpr(expr.tag, source, fileName, isGenerator)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkYieldInExpr(span.expression, source, fileName, isGenerator)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkYieldInExpr(e, source, fileName, isGenerator)
            else -> {}
        }
    }

    private fun checkUndefinedNamesInStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name
                    if (name != null && name.text in PREDEFINED_TYPE_NAMES) {
                        val start = name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Class name cannot be '${name.text}'.",
                            category = DiagnosticCategory.Error,
                            code = 2414,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = name.text.length,
                        ))
                    }
                }
                is InterfaceDeclaration -> {
                    if (stmt.name.text in PREDEFINED_TYPE_NAMES) {
                        val start = stmt.name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Interface name cannot be '${stmt.name.text}'.",
                            category = DiagnosticCategory.Error,
                            code = 2427,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = stmt.name.text.length,
                        ))
                    }
                }
                is TypeAliasDeclaration -> {
                    // 17.195: TS2457 — type alias name cannot be a reserved
                    // type keyword (e.g. `type undefined = string`).
                    if (stmt.name.text in PREDEFINED_TYPE_NAMES) {
                        val start = stmt.name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Type alias name cannot be '${stmt.name.text}'.",
                            category = DiagnosticCategory.Error,
                            code = 2457,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = stmt.name.text.length,
                        ))
                    }
                }
                is FunctionDeclaration -> {
                    // 17.196: walk for yield-in-non-generator (TS1163).
                    val isGenerator = stmt.asteriskToken
                    stmt.body?.let { walkYieldInStmts(it.statements, source, fileName, isGenerator) }
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { checkUndefinedNamesInStmts(it.statements, source, fileName) }
                }
                is Block -> checkUndefinedNamesInStmts(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkUndefinedNamesInStmts(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkUndefinedNamesInStmts(listOf(it), source, fileName) }
                }
                is ForStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkUndefinedNamesInStmts(clause.statements, source, fileName)
                        is DefaultClause -> checkUndefinedNamesInStmts(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    checkUndefinedNamesInStmts(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { checkUndefinedNamesInStmts(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkUndefinedNamesInStmts(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkUndefinedNamesInStmts(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2528: A module cannot have multiple default exports
    // -----------------------------------------------------------------------

    private enum class DefaultDeclKind { DECL, REEXPORT, REF_TYPE, EXPR }

    private fun checkMultipleDefaultExports() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            // Classify default exports:
            // - DECL: ClassDeclaration, FunctionDeclaration, InterfaceDeclaration (all are "declaration forms")
            //         or ExportAssignment with Identifier pointing to a value symbol
            // - REF_TYPE: ExportAssignment with Identifier pointing to a type-only symbol
            // - EXPR: ExportAssignment with non-Identifier expression (literal, complex expr)
            // ts2528Start/Length: position for TS2528 diagnostic (identifier for ExportAssignment-id, else same as ts2323)
            // ts2323Start/Length: position for TS2323 diagnostic (whole statement for ExportAssignment, else same as ts2528)
            data class DefaultExportInfo(
                val stmt: Statement,
                val start: Int, val length: Int, // for TS2528
                val ts2323Start: Int, val ts2323Length: Int, // for TS2323 (may differ for ExportAssignment)
                val kind: DefaultDeclKind,
            )
            val defaults = mutableListOf<DefaultExportInfo>()

            fun isTypeOnlyIdentifier(name: String): Boolean {
                val sym = result.locals[name] ?: return false
                return !sym.flags.hasAny(SymbolFlags.Value)
            }

            fun exprStmtSpan(stmt: ExportAssignment): Pair<Int, Int> {
                // Whole-statement span for TS2323 on `export default <expr>`:
                // from start of "export" keyword to end of expression (+ optional semicolon).
                // Cannot use stmt.end because our parser's `end` includes lookahead position.
                var spanStart = stmt.pos
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                val expr = stmt.expression
                // Use expression text length to find expression end without lookahead artifacts
                val exprTextEnd = when (expr) {
                    is Identifier -> expr.pos + expr.text.length
                    else -> {
                        // For complex expressions, find the end by scanning the expression manually
                        var end = expr.pos
                        // Skip past non-newline, non-semicolon chars to find expression end
                        while (end < source.length && source[end] != '\n' && source[end] != '\r' && source[end] != ';') end++
                        end
                    }
                }
                var spanEnd = exprTextEnd
                while (spanEnd < source.length && source[spanEnd].let { it == ' ' || it == '\t' }) spanEnd++
                if (spanEnd < source.length && source[spanEnd] == ';') spanEnd++
                return spanStart to (spanEnd - spanStart).coerceAtLeast(1)
            }

            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ExportAssignment -> {
                        if (!stmt.isExportEquals) {
                            val expr = stmt.expression
                            if (expr is Identifier) {
                                // `export default identifier` — classify by whether identifier is value or type-only
                                // TS2528 reports at identifier, TS2323 reports at whole statement
                                val kind = if (isTypeOnlyIdentifier(expr.text)) DefaultDeclKind.REF_TYPE else DefaultDeclKind.DECL
                                val (ts2323Start, ts2323Len) = exprStmtSpan(stmt)
                                defaults.add(DefaultExportInfo(stmt, expr.pos, expr.text.length, ts2323Start, ts2323Len, kind))
                            } else {
                                // `export default <complex expr>` → report at start of whole statement
                                val (spanStart, spanLength) = exprStmtSpan(stmt)
                                defaults.add(DefaultExportInfo(stmt, spanStart, spanLength, spanStart, spanLength, DefaultDeclKind.EXPR))
                            }
                        }
                    }
                    is FunctionDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // TypeScript reports at function name. For anonymous functions, at "export" keyword.
                            val name = stmt.name
                            if (name != null) {
                                defaults.add(DefaultExportInfo(stmt, name.pos, name.text.length, name.pos, name.text.length, DefaultDeclKind.DECL))
                            } else {
                                // Anonymous function: FunctionDeclaration.pos = "function" keyword position.
                                // We need the "export" keyword which precedes "default function".
                                // Search backwards from stmt.pos for "export".
                                val exportStart = findExportKeywordBefore(source, stmt.pos)
                                defaults.add(DefaultExportInfo(stmt, exportStart, 6, exportStart, 6, DefaultDeclKind.DECL))
                            }
                        }
                    }
                    is ClassDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // TypeScript reports at class name. For anonymous classes, at "export" keyword.
                            val name = stmt.name
                            if (name != null) {
                                defaults.add(DefaultExportInfo(stmt, name.pos, name.text.length, name.pos, name.text.length, DefaultDeclKind.DECL))
                            } else {
                                // Anonymous class: ClassDeclaration.pos = "class" keyword position.
                                // We need the "export" keyword which precedes "default class".
                                val exportStart = findExportKeywordBefore(source, stmt.pos)
                                defaults.add(DefaultExportInfo(stmt, exportStart, 6, exportStart, 6, DefaultDeclKind.DECL))
                            }
                        }
                    }
                    is InterfaceDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // `export default interface Foo {}` — declaration form, always DECL
                            defaults.add(DefaultExportInfo(stmt, stmt.name.pos, stmt.name.text.length, stmt.name.pos, stmt.name.text.length, DefaultDeclKind.DECL))
                        }
                    }
                    is ExportDeclaration -> {
                        // `export { default } from 'mod'` or `export { X as default } from 'mod'`
                        // These are re-exports of `default` — classified as REEXPORT.
                        val clause = stmt.exportClause
                        if (clause is NamedExports) {
                            for (spec in clause.elements) {
                                if (spec.name.text == "default") {
                                    // spec.name.pos includes leading trivia; skip whitespace to get token start
                                    var specStart = spec.name.pos
                                    while (specStart < source.length && source[specStart].let { it == ' ' || it == '\t' }) specStart++
                                    defaults.add(DefaultExportInfo(stmt, specStart, spec.name.text.length, specStart, spec.name.text.length, DefaultDeclKind.REEXPORT))
                                }
                            }
                        }
                    }
                    else -> {}
                }
            }

            if (defaults.size < 2) continue

            // Determine how to report: TS2323 vs TS2528
            // TS2323 fires when there are ≥2 DECL/REEXPORT forms.
            // TS2528 fires when any non-DECL form (REEXPORT, REF_TYPE, or EXPR) is present.
            // When ALL forms are DECL (no REEXPORT/REF_TYPE/EXPR): emit TS2323 only (no TS2528).
            // Function overloads with the same name count as 1 DECL for TS2323.
            val overloadNames = mutableSetOf<String>()
            var declCount = 0
            for (info in defaults) {
                if (info.kind == DefaultDeclKind.DECL || info.kind == DefaultDeclKind.REEXPORT) {
                    val stmt = info.stmt
                    if (stmt is FunctionDeclaration && stmt.name != null) {
                        val name = stmt.name!!.text
                        if (name in overloadNames) continue // don't count duplicate overloads
                        overloadNames.add(name)
                    }
                    declCount++
                }
            }
            val hasNonDeclInline = defaults.any { it.kind != DefaultDeclKind.DECL }
            val emitTs2323 = declCount >= 2
            val emitTs2528 = hasNonDeclInline || !emitTs2323

            // TS2393: Duplicate function implementation — fires for multiple anonymous
            // `export default function(){}` declarations (they all have a body but no name).
            val anonFuncDefaults = defaults.filter { d ->
                val fd = d.stmt as? FunctionDeclaration ?: return@filter false
                fd.name == null && fd.body != null
            }
            if (anonFuncDefaults.size >= 2) {
                for (anonD in anonFuncDefaults) {
                    val (ts2393Line, ts2393Char) = getLineAndCharacterOfPosition(source, anonD.start)
                    diagnostics.add(Diagnostic(
                        message = "Duplicate function implementation.",
                        category = DiagnosticCategory.Error,
                        code = 2393,
                        fileName = fileName,
                        line = ts2393Line,
                        character = ts2393Char,
                        start = anonD.start,
                        length = anonD.length,
                    ))
                }
            }

            val lastIdx = defaults.size - 1
            val lastStmt = defaults[lastIdx].stmt
            // When the last export is a FunctionDeclaration, it acts as the "canonical" binding:
            // all preceding exports point to it with TS2752 "The first export default is here.",
            // and the last export points back with TS2753 "Another export default is here."
            // In all other cases, preceding exports point to the last with TS2753/TS6204,
            // and the last export points to all preceding with TS2752.
            val lastIsFunctionDecl = lastStmt is FunctionDeclaration

            for (i in defaults.indices) {
                val d = defaults[i]
                val (line, character) = getLineAndCharacterOfPosition(source, d.start)
                val isLast = i == lastIdx

                // TS2323: fires for DECL/REEXPORT forms when declCount >= 2.
                // For DECL forms: all non-last get TS2323; last gets TS2323 only if it's a
                // "real declaration" (ClassDecl/FuncDecl/InterfaceDecl), not an ExportAssignment.
                // For REEXPORT forms: only non-last get TS2323 (last re-export gets only TS2528).
                // The span for TS2323 uses ts2323Start/ts2323Length (whole statement for ExportAssignment).
                if (emitTs2323 && (d.kind == DefaultDeclKind.DECL || d.kind == DefaultDeclKind.REEXPORT)) {
                    val isRealDecl = d.stmt !is ExportAssignment && d.kind != DefaultDeclKind.REEXPORT
                    if (!isLast || isRealDecl) {
                        val (ts2323Line, ts2323Char) = getLineAndCharacterOfPosition(source, d.ts2323Start)
                        diagnostics.add(Diagnostic(
                            message = "Cannot redeclare exported variable 'default'.",
                            category = DiagnosticCategory.Error,
                            code = 2323,
                            fileName = fileName,
                            line = ts2323Line,
                            character = ts2323Char,
                            start = d.ts2323Start,
                            length = d.ts2323Length,
                        ))
                    }
                }

                if (!emitTs2528) continue

                val relatedInfoList = mutableListOf<Diagnostic>()

                if (!isLast) {
                    // Non-last export: point to the last one
                    val relD = defaults[lastIdx]
                    val (relLine, relChar) = getLineAndCharacterOfPosition(source, relD.start)
                    val relCode: Int
                    val relMessage: String
                    if (lastIsFunctionDecl) {
                        // Last is FD: preceding exports use TS2752 "The first export default is here."
                        relCode = 2752
                        relMessage = "The first export default is here."
                    } else if (i == 0) {
                        // First export: TS2753 "Another export default is here."
                        relCode = 2753
                        relMessage = "Another export default is here."
                    } else {
                        // Non-first, non-last: TS6204 "and here."
                        relCode = 6204
                        relMessage = "and here."
                    }
                    relatedInfoList.add(Diagnostic(
                        message = relMessage,
                        category = DiagnosticCategory.Message,
                        code = relCode,
                        fileName = fileName,
                        line = relLine,
                        character = relChar,
                        start = relD.start,
                        length = relD.length,
                    ))
                } else {
                    // Last export: point to all previous ones
                    for (j in 0 until lastIdx) {
                        val relD = defaults[j]
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, relD.start)
                        val relCode: Int
                        val relMessage: String
                        if (lastIsFunctionDecl) {
                            // Last is FD: use TS2753 "Another export default is here."
                            relCode = 2753
                            relMessage = "Another export default is here."
                        } else {
                            // Normal case: use TS2752 "The first export default is here."
                            relCode = 2752
                            relMessage = "The first export default is here."
                        }
                        relatedInfoList.add(Diagnostic(
                            message = relMessage,
                            category = DiagnosticCategory.Message,
                            code = relCode,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = relD.start,
                            length = relD.length,
                        ))
                    }
                }

                diagnostics.add(Diagnostic(
                    message = "A module cannot have multiple default exports.",
                    category = DiagnosticCategory.Error,
                    code = 2528,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = d.start,
                    length = d.length,
                    relatedInformation = relatedInfoList,
                ))
            }
        }
    }

    /**
     * Find the position of the `export` keyword that appears before a given position.
     * Used when FunctionDeclaration/ClassDeclaration.pos is the keyword position (e.g. `function`)
     * but we need the `export` keyword position for anonymous declarations.
     */
    private fun findExportKeywordBefore(source: String, stmtPos: Int): Int {
        // Search backwards from stmtPos for "export" keyword.
        // The pattern is "export default function/class" where stmtPos = function/class position.
        val searchStart = (stmtPos - 30).coerceAtLeast(0)
        val idx = source.lastIndexOf("export", stmtPos)
        return if (idx in searchStart..stmtPos) idx else stmtPos
    }

    // -----------------------------------------------------------------------
    // TS2377: Constructors for derived classes must contain a 'super' call
    // -----------------------------------------------------------------------

    private fun checkDerivedConstructorSuper() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            try {
                walkForDerivedSuper(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = null
            }
        }
    }

    private fun walkForDerivedSuper(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkClassDerivedSuper(stmt.heritageClauses, stmt.members, source, fileName, stmt.name)
                    // Recurse into class members for nested classes
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            is Constructor -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            is GetAccessor -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            is SetAccessor -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        when (val init = d.initializer) {
                            is ClassExpression -> {
                                checkClassDerivedSuper(init.heritageClauses, init.members, source, fileName, init.name)
                            }
                            is FunctionExpression -> walkForDerivedSuper(init.body.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForDerivedSuper(it.statements, source, fileName) }
                is Block -> walkForDerivedSuper(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForDerivedSuper(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForDerivedSuper(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForDerivedSuper(clause.statements, source, fileName)
                        is DefaultClause -> walkForDerivedSuper(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForDerivedSuper(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForDerivedSuper(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForDerivedSuper(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForDerivedSuper(listOf(stmt.statement), source, fileName)
                is ThrowStatement -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassDerivedSuper(expr.heritageClauses, expr.members, source, fileName, expr.name)
                        is FunctionExpression -> walkForDerivedSuper(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForDerivedSuper(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                is ExportAssignment -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassDerivedSuper(expr.heritageClauses, expr.members, source, fileName, expr.name)
                        is FunctionExpression -> walkForDerivedSuper(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForDerivedSuper(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                is ReturnStatement -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassDerivedSuper(expr.heritageClauses, expr.members, source, fileName, expr.name)
                        is FunctionExpression -> walkForDerivedSuper(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForDerivedSuper(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                else -> {}
            }
        }
    }

    private fun checkClassDerivedSuper(
        heritageClauses: List<HeritageClause>?,
        members: List<ClassElement>,
        source: String,
        fileName: String,
        classNameNode: Identifier? = null,
    ) {
        // Check if class extends something (skip null extends — `class X extends null` is special)
        val extendsClause = heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
        if (extendsClause == null) return
        val extendsExpr = extendsClause.types.firstOrNull()?.expression
        val extendsNull = extendsExpr is Identifier && extendsExpr.text == "null"

        if (extendsNull) {
            // For `class X extends null`, any super() call is TS17005.
            for (member in members) {
                if (member is Constructor && member.body != null) {
                    findSuperCallWithLength(member.body!!.statements)?.let { (superCallPos, len) ->
                        val (line, character) = getLineAndCharacterOfPosition(source, superCallPos)
                        diagnostics.add(Diagnostic(
                            message = "A constructor cannot contain a 'super' call when its class extends 'null'.",
                            category = DiagnosticCategory.Error,
                            code = 17005,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = superCallPos,
                            length = len,
                        ))
                    }
                }
            }
            // TS2417: "Class static side 'typeof C' incorrectly extends base class static side 'null'"
            // fires only when the class is declaration-merged with an interface of the same name.
            // Without the merged interface, TypeScript suppresses this error (see classExtendsNull /
            // classExtendsNull3 baselines which only emit TS17005 / TS2531 without TS2417).
            if (classNameNode != null) {
                val className = classNameNode.text
                val hasMergedInterface = currentFileLocals?.get(className)?.declarations?.any {
                    it is InterfaceDeclaration
                } == true
                if (hasMergedInterface) {
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Class static side 'typeof $className' incorrectly extends base class static side 'null'.",
                        category = DiagnosticCategory.Error,
                        code = 2417,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = className.length,
                    ))
                }
            }
            return
        }

        // 16.4cv: TS2336/TS17011 — `super.X` referenced in a constructor parameter
        // default. By definition, parameter initializers run before the constructor
        // body, so `super()` cannot have been called yet. Both diagnostics fire on
        // the same `super` keyword. Narrow scope: walks each Constructor's params,
        // looks for Identifier("super") inside any initializer.
        for (member in members) {
            if (member !is Constructor) continue
            for (param in member.parameters) {
                val init = param.initializer ?: continue
                collectSuperKeywordPositions(init).forEach { superPos ->
                    val (line, character) = getLineAndCharacterOfPosition(source, superPos)
                    diagnostics.add(Diagnostic(
                        message = "'super' cannot be referenced in constructor arguments.",
                        category = DiagnosticCategory.Error,
                        code = 2336,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = superPos,
                        length = 5,
                    ))
                    diagnostics.add(Diagnostic(
                        message = "'super' must be called before accessing a property of 'super' in the constructor of a derived class.",
                        category = DiagnosticCategory.Error,
                        code = 17011,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = superPos,
                        length = 5,
                    ))
                }
            }
        }

        // 16.4cw: `new super(...)` inside a constructor body. `super` (without `()`)
        // refers to the prototype, which has no construct signatures — TS2351. And
        // since this is a property-style access on `super`, TS17011 applies as well
        // (the call to `super()` proper hasn't happened yet at this point in eval).
        // Emits both at the `super` keyword position (length 5), with a chain on
        // TS2351 displaying the resolved base type (e.g. `A<number, string>`).
        val baseDisplay = run {
            val first = extendsClause.types.firstOrNull() ?: return@run null
            val baseName = (first.expression as? Identifier)?.text ?: return@run null
            val typeArgs = first.typeArguments
            if (typeArgs.isNullOrEmpty()) baseName
            else {
                val argNames = typeArgs.map { formatTypeForDisplay(it) }
                if (argNames.any { it == null }) baseName
                else "$baseName<${argNames.joinToString(", ")}>"
            }
        }
        for (member in members) {
            if (member !is Constructor) continue
            val body = member.body ?: continue
            for (stmt in body.statements) {
                collectNewSuperPositions(stmt).forEach { superPos ->
                    val (line, character) = getLineAndCharacterOfPosition(source, superPos)
                    val chain = if (baseDisplay != null) {
                        listOf("  Type '$baseDisplay' has no construct signatures.")
                    } else emptyList()
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error,
                        code = 2351,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = superPos,
                        length = 5,
                        messageChain = chain,
                    ))
                    diagnostics.add(Diagnostic(
                        message = "'super' must be called before accessing a property of 'super' in the constructor of a derived class.",
                        category = DiagnosticCategory.Error,
                        code = 17011,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = superPos,
                        length = 5,
                    ))
                }
            }
        }

        // B51.5: TS17011 — `super(super.X())` pattern. Inside the args of the
        // FIRST super(...) call in a constructor body, any `super.X` property
        // access fires TS17011 (the property access on super happens BEFORE
        // the super call completes). Squiggle on the `super.X` expression
        // span (covers `super.blah` for `super.blah()`).
        for (member in members) {
            if (member !is Constructor) continue
            val body = member.body ?: continue
            for (stmt in body.statements) {
                val superCall = findSuperCallInExpr(stmt) ?: continue
                for (arg in superCall.arguments) {
                    collectSuperPropertyAccessPositions(arg).forEach { (pos, len) ->
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'super' must be called before accessing a property of 'super' in the constructor of a derived class.",
                            category = DiagnosticCategory.Error,
                            code = 17011,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = pos,
                            length = len,
                        ))
                    }
                }
                break // only first super(...) per constructor
            }
        }

        // Find constructors with bodies that don't contain super()
        for (member in members) {
            if (member is Constructor && member.body != null) {
                val hasSuperCall = statementsContainSuperCall(member.body!!.statements)
                if (!hasSuperCall) {
                    // Find "constructor" keyword position
                    val ctorPos = member.pos
                    var spanStart = ctorPos
                    while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                    val idx = source.indexOf("constructor", spanStart)
                    if (idx < 0 || idx > spanStart + 20) continue
                    spanStart = idx
                    // Span covers just "constructor" keyword (11 chars)
                    val length = 11
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "Constructors for derived classes must contain a 'super' call.",
                        category = DiagnosticCategory.Error,
                        code = 2377,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
            }
        }
    }

    private fun statementsContainSuperCall(stmts: List<Statement>): Boolean {
        for (stmt in stmts) {
            if (stmtContainsSuperCall(stmt)) return true
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2322 + TS2409: `return null` in derived class constructor
    // -----------------------------------------------------------------------

    private fun checkDerivedConstructorReturnNull() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForCtorReturnNull(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForCtorReturnNull(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkClassCtorReturnNull(stmt.heritageClauses, stmt.members, source, fileName, stmt.name?.text)
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                            is Constructor -> m.body?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                            is GetAccessor -> m.body?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                            is SetAccessor -> m.body?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        when (val init = d.initializer) {
                            is ClassExpression -> checkClassCtorReturnNull(init.heritageClauses, init.members, source, fileName, init.name?.text)
                            is FunctionExpression -> walkForCtorReturnNull(init.body.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                is Block -> walkForCtorReturnNull(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkForCtorReturnNull(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForCtorReturnNull(listOf(it), source, fileName) }
                }
                is ForStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForCtorReturnNull(clause.statements, source, fileName)
                        is DefaultClause -> walkForCtorReturnNull(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkForCtorReturnNull(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { walkForCtorReturnNull(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForCtorReturnNull(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkForCtorReturnNull(listOf(stmt.statement), source, fileName)
                is ThrowStatement -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassCtorReturnNull(expr.heritageClauses, expr.members, source, fileName, expr.name?.text)
                        is FunctionExpression -> walkForCtorReturnNull(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForCtorReturnNull(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                is ExportAssignment -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassCtorReturnNull(expr.heritageClauses, expr.members, source, fileName, expr.name?.text)
                        is FunctionExpression -> walkForCtorReturnNull(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForCtorReturnNull(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                is ReturnStatement -> {
                    when (val expr = stmt.expression) {
                        is ClassExpression -> checkClassCtorReturnNull(expr.heritageClauses, expr.members, source, fileName, expr.name?.text)
                        is FunctionExpression -> walkForCtorReturnNull(expr.body.statements, source, fileName)
                        is ArrowFunction -> when (val body = expr.body) {
                            is Block -> walkForCtorReturnNull(body.statements, source, fileName)
                            else -> {}
                        }
                        else -> {}
                    }
                }
                else -> {}
            }
        }
    }

    private fun checkClassCtorReturnNull(
        heritageClauses: List<HeritageClause>?,
        members: List<ClassElement>,
        source: String,
        fileName: String,
        className: String?,
    ) {
        val extendsClause = heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword } ?: return
        val extendsExpr = extendsClause.types.firstOrNull()?.expression
        // Skip `class X extends null` (handled elsewhere).
        if (extendsExpr is Identifier && extendsExpr.text == "null") return
        if (className == null) return
        for (member in members) {
            if (member !is Constructor) continue
            val body = member.body ?: continue
            findReturnNullsInStatements(body.statements) { returnPos ->
                val (line, character) = getLineAndCharacterOfPosition(source, returnPos)
                diagnostics.add(Diagnostic(
                    message = "Type 'null' is not assignable to type '$className'.",
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = returnPos,
                    length = 6, // "return"
                ))
                diagnostics.add(Diagnostic(
                    message = "Return type of constructor signature must be assignable to the instance type of the class.",
                    category = DiagnosticCategory.Error,
                    code = 2409,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = returnPos,
                    length = 6,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2322 + TS2409 + TS2208: generic class constructor returning a value
    // typed as one of the class's own UNCONSTRAINED type parameters.
    //   class B<T> { constructor() { var x: T; return x; } }
    // The returned `T` is not assignable to the instance type `B<T>` (an
    // unconstrained TP could be instantiated with anything). Narrowly gated to
    // `return <ident>` where ident is a local var declared `var ident: TP` and
    // TP is a class type param with no constraint — primitive returns
    // (`return 1`, ignored by JS) and assignable returns are not flagged.
    // -----------------------------------------------------------------------

    private fun checkConstructorReturnTypeParam() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForCtorReturnTypeParam(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForCtorReturnTypeParam(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkClassCtorReturnTypeParam(stmt.typeParameters, stmt.members, source, fileName, stmt.name?.text)
                    for (m in stmt.members) when (m) {
                        is MethodDeclaration -> m.body?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                        else -> {}
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    when (val init = d.initializer) {
                        is ClassExpression -> checkClassCtorReturnTypeParam(init.typeParameters, init.members, source, fileName, init.name?.text)
                        is FunctionExpression -> walkForCtorReturnTypeParam(init.body.statements, source, fileName)
                        else -> {}
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForCtorReturnTypeParam(it.statements, source, fileName) }
                is Block -> walkForCtorReturnTypeParam(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkClassCtorReturnTypeParam(
        typeParameters: List<TypeParameter>?,
        members: List<ClassElement>,
        source: String,
        fileName: String,
        className: String?,
    ) {
        if (className == null) return
        val tps = typeParameters ?: return
        if (tps.isEmpty()) return
        val unconstrained = tps.filter { it.constraint == null }.associateBy { it.name.text }
        if (unconstrained.isEmpty()) return
        val instanceDisplay = "$className<${tps.joinToString(", ") { it.name.text }}>"
        for (member in members) {
            if (member !is Constructor) continue
            val body = member.body ?: continue
            // var name -> annotation type-param name (only bare `var x: TP` with TP an unconstrained class TP)
            val varTpName = mutableMapOf<String, String>()
            collectCtorVarTypeParamAnnotations(body.statements, unconstrained.keys, varTpName)
            if (varTpName.isEmpty()) continue
            findReturnIdentsInStatements(body.statements) { returnPos, identName ->
                val tpName = varTpName[identName] ?: return@findReturnIdentsInStatements
                val tpDecl = unconstrained[tpName] ?: return@findReturnIdentsInStatements
                val (line, character) = getLineAndCharacterOfPosition(source, returnPos)
                val (relLine, relChar) = getLineAndCharacterOfPosition(source, tpDecl.name.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$tpName' is not assignable to type '$instanceDisplay'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = character,
                    start = returnPos, length = 6,
                    relatedInformation = listOf(Diagnostic(
                        message = "This type parameter might need an `extends $instanceDisplay` constraint.",
                        category = DiagnosticCategory.Message, code = 2208,
                        fileName = fileName, line = relLine, character = relChar,
                        start = tpDecl.name.pos, length = tpDecl.name.text.length,
                    )),
                ))
                diagnostics.add(Diagnostic(
                    message = "Return type of constructor signature must be assignable to the instance type of the class.",
                    category = DiagnosticCategory.Error, code = 2409,
                    fileName = fileName, line = line, character = character,
                    start = returnPos, length = 6,
                ))
            }
        }
    }

    /** Collect `var name: TP` declarations (TP a bare TypeReference whose name is in [tpNames])
     *  within [stmts], not descending into nested functions/classes. */
    private fun collectCtorVarTypeParamAnnotations(
        stmts: List<Statement>, tpNames: Set<String>, out: MutableMap<String, String>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    val n = d.name as? Identifier ?: continue
                    val tr = d.type as? TypeReference ?: continue
                    val tn = tr.typeName as? Identifier ?: continue
                    if (tr.typeArguments.isNullOrEmpty() && tn.text in tpNames) out[n.text] = tn.text
                }
                is Block -> collectCtorVarTypeParamAnnotations(stmt.statements, tpNames, out)
                is IfStatement -> {
                    collectCtorVarTypeParamAnnotations(listOf(stmt.thenStatement), tpNames, out)
                    stmt.elseStatement?.let { collectCtorVarTypeParamAnnotations(listOf(it), tpNames, out) }
                }
                is ForStatement -> collectCtorVarTypeParamAnnotations(listOf(stmt.statement), tpNames, out)
                is WhileStatement -> collectCtorVarTypeParamAnnotations(listOf(stmt.statement), tpNames, out)
                is TryStatement -> {
                    collectCtorVarTypeParamAnnotations(stmt.tryBlock.statements, tpNames, out)
                    stmt.catchClause?.let { collectCtorVarTypeParamAnnotations(it.block.statements, tpNames, out) }
                    stmt.finallyBlock?.let { collectCtorVarTypeParamAnnotations(it.statements, tpNames, out) }
                }
                else -> {}
            }
        }
    }

    private fun findReturnIdentsInStatements(stmts: List<Statement>, callback: (Int, String) -> Unit) {
        for (stmt in stmts) findReturnIdentsInStmt(stmt, callback)
    }

    private fun findReturnIdentsInStmt(stmt: Statement, callback: (Int, String) -> Unit) {
        when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression
                if (expr is Identifier) callback(stmt.pos, expr.text)
            }
            is Block -> findReturnIdentsInStatements(stmt.statements, callback)
            is IfStatement -> {
                findReturnIdentsInStmt(stmt.thenStatement, callback)
                stmt.elseStatement?.let { findReturnIdentsInStmt(it, callback) }
            }
            is SwitchStatement -> for (clause in stmt.caseBlock) when (clause) {
                is CaseClause -> clause.statements.forEach { findReturnIdentsInStmt(it, callback) }
                is DefaultClause -> clause.statements.forEach { findReturnIdentsInStmt(it, callback) }
                else -> {}
            }
            is ForStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            is ForInStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            is ForOfStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            is WhileStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            is DoStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            is TryStatement -> {
                findReturnIdentsInStatements(stmt.tryBlock.statements, callback)
                stmt.catchClause?.let { findReturnIdentsInStatements(it.block.statements, callback) }
                stmt.finallyBlock?.let { findReturnIdentsInStatements(it.statements, callback) }
            }
            is LabeledStatement -> findReturnIdentsInStmt(stmt.statement, callback)
            else -> {}
        }
    }

    private fun findReturnNullsInStatements(stmts: List<Statement>, callback: (Int) -> Unit) {
        for (stmt in stmts) findReturnNullsInStmt(stmt, callback)
    }

    private fun findReturnNullsInStmt(stmt: Statement, callback: (Int) -> Unit) {
        when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression
                if (expr is Identifier && expr.text == "null") callback(stmt.pos)
            }
            is Block -> findReturnNullsInStatements(stmt.statements, callback)
            is IfStatement -> {
                findReturnNullsInStmt(stmt.thenStatement, callback)
                stmt.elseStatement?.let { findReturnNullsInStmt(it, callback) }
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach { findReturnNullsInStmt(it, callback) }
                        is DefaultClause -> clause.statements.forEach { findReturnNullsInStmt(it, callback) }
                        else -> {}
                    }
                }
            }
            is ForStatement -> findReturnNullsInStmt(stmt.statement, callback)
            is ForInStatement -> findReturnNullsInStmt(stmt.statement, callback)
            is ForOfStatement -> findReturnNullsInStmt(stmt.statement, callback)
            is WhileStatement -> findReturnNullsInStmt(stmt.statement, callback)
            is DoStatement -> findReturnNullsInStmt(stmt.statement, callback)
            is TryStatement -> {
                findReturnNullsInStatements(stmt.tryBlock.statements, callback)
                stmt.catchClause?.let { findReturnNullsInStatements(it.block.statements, callback) }
                stmt.finallyBlock?.let { findReturnNullsInStatements(it.statements, callback) }
            }
            is LabeledStatement -> findReturnNullsInStmt(stmt.statement, callback)
            else -> {}
        }
    }

    /** Returns the position of the first super() call in stmts, or null if none. */
    private fun findSuperCallInStatements(stmts: List<Statement>): Int? {
        for (stmt in stmts) {
            findSuperCallInStmt(stmt)?.let { return it }
        }
        return null
    }

    private fun findSuperCallInStmt(stmt: Statement): Int? = when (stmt) {
        is ExpressionStatement -> findSuperCallInExpr(stmt.expression)
        is Block -> findSuperCallInStatements(stmt.statements)
        is IfStatement -> findSuperCallInStmt(stmt.thenStatement) ?: stmt.elseStatement?.let { findSuperCallInStmt(it) }
        is ForStatement -> findSuperCallInStmt(stmt.statement)
        is ForInStatement -> findSuperCallInStmt(stmt.statement)
        is ForOfStatement -> findSuperCallInStmt(stmt.statement)
        is WhileStatement -> findSuperCallInStmt(stmt.statement)
        is DoStatement -> findSuperCallInStmt(stmt.statement)
        is SwitchStatement -> {
            var found: Int? = null
            for (clause in stmt.caseBlock) {
                if (found != null) break
                when (clause) {
                    is CaseClause -> for (s in clause.statements) {
                        findSuperCallInStmt(s)?.let { found = it; break }
                    }
                    is DefaultClause -> for (s in clause.statements) {
                        findSuperCallInStmt(s)?.let { found = it; break }
                    }
                    else -> {}
                }
            }
            found
        }
        is TryStatement -> findSuperCallInStatements(stmt.tryBlock.statements)
            ?: stmt.catchClause?.block?.statements?.let { findSuperCallInStatements(it) }
            ?: stmt.finallyBlock?.statements?.let { findSuperCallInStatements(it) }
        is LabeledStatement -> findSuperCallInStmt(stmt.statement)
        is ReturnStatement -> stmt.expression?.let { findSuperCallInExpr(it) }
        is ThrowStatement -> stmt.expression?.let { findSuperCallInExpr(it) }
        else -> null
    }

    private fun findSuperCallInExpr(expr: Expression): Int? = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            if (callee is Identifier && callee.text == "super") callee.pos.takeIf { it >= 0 }
            else findSuperCallInExpr(callee)
        }
        is ParenthesizedExpression -> findSuperCallInExpr(expr.expression)
        else -> null
    }

    /**
     * 16.4cw: Collect positions of every `new super(...)` callee anywhere within a
     * statement subtree. Returns the position of the `super` identifier (length 5).
     * Used for TS2351/TS17011 in constructor bodies.
     */
    private fun collectNewSuperPositions(stmt: Statement): List<Int> {
        val out = mutableListOf<Int>()
        fun walkExpr(e: Expression?) {
            e ?: return
            when (e) {
                is NewExpression -> {
                    val callee = e.expression
                    if (callee is Identifier && callee.text == "super") {
                        out.add(callee.pos)
                    } else walkExpr(callee)
                    e.arguments?.forEach { walkExpr(it) }
                }
                is CallExpression -> { walkExpr(e.expression); e.arguments.forEach { walkExpr(it) } }
                is PropertyAccessExpression -> walkExpr(e.expression)
                is ElementAccessExpression -> { walkExpr(e.expression); walkExpr(e.argumentExpression) }
                is BinaryExpression -> { walkExpr(e.left); walkExpr(e.right) }
                is ConditionalExpression -> { walkExpr(e.condition); walkExpr(e.whenTrue); walkExpr(e.whenFalse) }
                is ParenthesizedExpression -> walkExpr(e.expression)
                is PrefixUnaryExpression -> walkExpr(e.operand)
                is PostfixUnaryExpression -> walkExpr(e.operand)
                is TypeAssertionExpression -> walkExpr(e.expression)
                is AsExpression -> walkExpr(e.expression)
                is NonNullExpression -> walkExpr(e.expression)
                is ArrayLiteralExpression -> e.elements.forEach { walkExpr(it) }
                is SpreadElement -> walkExpr(e.expression)
                is YieldExpression -> e.expression?.let { walkExpr(it) }
                is AwaitExpression -> walkExpr(e.expression)
                is VoidExpression -> walkExpr(e.expression)
                is TypeOfExpression -> walkExpr(e.expression)
                is DeleteExpression -> walkExpr(e.expression)
                else -> {}
            }
        }
        fun walkStmt(s: Statement?) {
            s ?: return
            when (s) {
                is ExpressionStatement -> walkExpr(s.expression)
                is VariableStatement -> for (d in s.declarationList.declarations) walkExpr(d.initializer)
                is ReturnStatement -> walkExpr(s.expression)
                is IfStatement -> { walkExpr(s.expression); walkStmt(s.thenStatement); walkStmt(s.elseStatement) }
                is Block -> s.statements.forEach { walkStmt(it) }
                is ForStatement -> {
                    when (val init = s.initializer) {
                        is VariableDeclarationList -> for (d in init.declarations) walkExpr(d.initializer)
                        is Expression -> walkExpr(init)
                        else -> {}
                    }
                    walkExpr(s.condition); walkExpr(s.incrementor); walkStmt(s.statement)
                }
                is WhileStatement -> { walkExpr(s.expression); walkStmt(s.statement) }
                is DoStatement -> { walkStmt(s.statement); walkExpr(s.expression) }
                is ThrowStatement -> walkExpr(s.expression)
                is SwitchStatement -> {
                    walkExpr(s.expression)
                    for (c in s.caseBlock) {
                        when (c) {
                            is CaseClause -> { walkExpr(c.expression); c.statements.forEach { walkStmt(it) } }
                            is DefaultClause -> c.statements.forEach { walkStmt(it) }
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    s.tryBlock.statements.forEach { walkStmt(it) }
                    s.catchClause?.block?.statements?.forEach { walkStmt(it) }
                    s.finallyBlock?.statements?.forEach { walkStmt(it) }
                }
                else -> {}
            }
        }
        walkStmt(stmt)
        return out
    }

    /**
     * 16.4cv: Collect the positions of every `super` keyword that appears anywhere
     * within an expression tree (not just at the head of a property/call chain).
     * Used by the TS2336/TS17011 check on constructor parameter initializers.
     */
    /** B51.5: Find the FIRST `super(...)` call expression in a statement (top-level
     *  ExpressionStatement). Returns the CallExpression or null. */
    private fun findSuperCallInExpr(stmt: Statement): CallExpression? {
        if (stmt !is ExpressionStatement) return null
        val expr = stmt.expression
        if (expr !is CallExpression) return null
        val callee = expr.expression
        if (callee is Identifier && callee.text == "super") return expr
        return null
    }

    /** B51.5: Collect `super.X` PropertyAccessExpression positions (start, length)
     *  within an expression. Used for TS17011 emission in `super(super.X())` patterns. */
    private fun collectSuperPropertyAccessPositions(expr: Expression?): List<Pair<Int, Int>> {
        val out = mutableListOf<Pair<Int, Int>>()
        fun walk(e: Expression?) {
            e ?: return
            when (e) {
                is PropertyAccessExpression -> {
                    val recv = e.expression
                    if (recv is Identifier && recv.text == "super") {
                        // Span: just `super` (5 chars), matching baseline convention.
                        out.add(recv.pos to 5)
                    } else walk(recv)
                }
                is ElementAccessExpression -> { walk(e.expression); walk(e.argumentExpression) }
                is CallExpression -> { walk(e.expression); e.arguments.forEach { walk(it) } }
                is NewExpression -> { walk(e.expression); e.arguments?.forEach { walk(it) } }
                is BinaryExpression -> { walk(e.left); walk(e.right) }
                is ConditionalExpression -> { walk(e.condition); walk(e.whenTrue); walk(e.whenFalse) }
                is ParenthesizedExpression -> walk(e.expression)
                is PrefixUnaryExpression -> walk(e.operand)
                is PostfixUnaryExpression -> walk(e.operand)
                is TypeAssertionExpression -> walk(e.expression)
                is AsExpression -> walk(e.expression)
                is NonNullExpression -> walk(e.expression)
                is ArrayLiteralExpression -> e.elements.forEach { walk(it) }
                is SpreadElement -> walk(e.expression)
                is YieldExpression -> e.expression?.let { walk(it) }
                is AwaitExpression -> walk(e.expression)
                else -> {}
            }
        }
        walk(expr)
        return out
    }

    private fun collectSuperKeywordPositions(expr: Expression): List<Int> {
        val out = mutableListOf<Int>()
        fun walk(e: Expression?) {
            e ?: return
            when (e) {
                is Identifier -> if (e.text == "super") out.add(e.pos)
                is PropertyAccessExpression -> walk(e.expression)
                is ElementAccessExpression -> { walk(e.expression); walk(e.argumentExpression) }
                is CallExpression -> { walk(e.expression); e.arguments.forEach { walk(it) } }
                is NewExpression -> { walk(e.expression); e.arguments?.forEach { walk(it) } }
                is BinaryExpression -> { walk(e.left); walk(e.right) }
                is ConditionalExpression -> { walk(e.condition); walk(e.whenTrue); walk(e.whenFalse) }
                is ParenthesizedExpression -> walk(e.expression)
                is PrefixUnaryExpression -> walk(e.operand)
                is PostfixUnaryExpression -> walk(e.operand)
                is TypeAssertionExpression -> walk(e.expression)
                is AsExpression -> walk(e.expression)
                is NonNullExpression -> walk(e.expression)
                is ArrayLiteralExpression -> e.elements.forEach { walk(it) }
                is SpreadElement -> walk(e.expression)
                is YieldExpression -> e.expression?.let { walk(it) }
                is AwaitExpression -> walk(e.expression)
                is VoidExpression -> walk(e.expression)
                is TypeOfExpression -> walk(e.expression)
                is DeleteExpression -> walk(e.expression)
                else -> {}
            }
        }
        walk(expr)
        return out
    }

    /**
     * Returns a pair of (startPos, length) for a super() call expression,
     * where startPos is the start of 'super' and length covers 'super()'.
     */
    private fun findSuperCallWithLength(stmts: List<Statement>): Pair<Int, Int>? {
        for (stmt in stmts) {
            findSuperCallWithLengthInStmt(stmt)?.let { return it }
        }
        return null
    }

    private fun findSuperCallWithLengthInStmt(stmt: Statement): Pair<Int, Int>? = when (stmt) {
        is ExpressionStatement -> findSuperCallWithLengthInExpr(stmt.expression)
        is Block -> findSuperCallWithLength(stmt.statements)
        is IfStatement -> findSuperCallWithLengthInStmt(stmt.thenStatement) ?: stmt.elseStatement?.let { findSuperCallWithLengthInStmt(it) }
        else -> null
    }

    private fun findSuperCallWithLengthInExpr(expr: Expression): Pair<Int, Int>? = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            if (callee is Identifier && callee.text == "super" && callee.pos >= 0) {
                // expr.end is one past the token AFTER ')' (usually ';'). Subtract 1 to get just 'super(...)'.
                val rawLen = expr.end - callee.pos
                Pair(callee.pos, (rawLen - 1).coerceAtLeast(7))
            } else findSuperCallWithLengthInExpr(callee)
        }
        is ParenthesizedExpression -> findSuperCallWithLengthInExpr(expr.expression)
        else -> null
    }

    private fun stmtContainsSuperCall(stmt: Statement): Boolean = when (stmt) {
        is ExpressionStatement -> exprContainsSuperCall(stmt.expression)
        is IfStatement -> {
            exprContainsSuperCall(stmt.expression) ||
                stmtContainsSuperCall(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtContainsSuperCall(it) } == true)
        }
        is Block -> stmt.statements.any { stmtContainsSuperCall(it) }
        is ForStatement -> stmtContainsSuperCall(stmt.statement)
        is WhileStatement -> stmtContainsSuperCall(stmt.statement)
        is SwitchStatement -> stmt.caseBlock.any { clause ->
            when (clause) {
                is CaseClause -> clause.statements.any { stmtContainsSuperCall(it) }
                is DefaultClause -> clause.statements.any { stmtContainsSuperCall(it) }
                else -> false
            }
        }
        is TryStatement -> {
            stmt.tryBlock.statements.any { stmtContainsSuperCall(it) } ||
                (stmt.catchClause?.block?.statements?.any { stmtContainsSuperCall(it) } == true) ||
                (stmt.finallyBlock?.statements?.any { stmtContainsSuperCall(it) } == true)
        }
        is ReturnStatement -> stmt.expression?.let { exprContainsSuperCall(it) } == true
        is VariableStatement -> stmt.declarationList.declarations.any { d ->
            d.initializer?.let { exprContainsSuperCall(it) } == true
        }
        else -> false
    }

    private fun exprContainsSuperCall(expr: Expression): Boolean = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            (callee is Identifier && callee.text == "super") || exprContainsSuperCall(callee)
        }
        is BinaryExpression -> exprContainsSuperCall(expr.left) || exprContainsSuperCall(expr.right)
        is ParenthesizedExpression -> exprContainsSuperCall(expr.expression)
        is ConditionalExpression -> exprContainsSuperCall(expr.whenTrue) || exprContainsSuperCall(expr.whenFalse)
        else -> false
    }

    // -----------------------------------------------------------------------
    // TS2303: Circular definition of import alias
    // -----------------------------------------------------------------------

    private fun checkCircularImportAlias() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCircularAliasInStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkCircularAliasInStmts(stmts: List<Statement>, source: String, fileName: String) {
        // Collect import= declarations with identifier references within this scope
        val importMap = mutableMapOf<String, ImportEqualsDeclaration>()
        for (stmt in stmts) {
            if (stmt is ImportEqualsDeclaration && stmt.moduleReference is Identifier) {
                importMap[stmt.name.text] = stmt
            }
        }

        // For each import, follow the chain to detect cycles
        val reported = mutableSetOf<String>()
        for ((name, decl) in importMap) {
            if (name in reported) continue
            val visited = mutableListOf(name)
            var current = (decl.moduleReference as Identifier).text
            while (current in importMap && current !in reported) {
                if (current in visited) {
                    // Cycle detected — report on the first import in the cycle
                    val cycleStart = visited.indexOf(current)
                    for (i in cycleStart until visited.size) {
                        val cycleName = visited[i]
                        val cycleDecl = importMap[cycleName] ?: continue
                        if (cycleName in reported) continue
                        reported.add(cycleName)
                        val start = cycleDecl.pos
                        var spanStart = start
                        while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                        // Find the semicolon at end of statement
                        val semiIdx = source.indexOf(';', spanStart)
                        val spanEnd = if (semiIdx in spanStart..cycleDecl.end) semiIdx + 1 else {
                            var e = cycleDecl.end
                            while (e > spanStart && e <= source.length && source[e - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) e--
                            e
                        }
                        val length = (spanEnd - spanStart).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                        diagnostics.add(Diagnostic(
                            message = "Circular definition of import alias '$cycleName'.",
                            category = DiagnosticCategory.Error,
                            code = 2303,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = spanStart,
                            length = length,
                        ))
                        break // TypeScript only reports on the first import in the cycle
                    }
                    break
                }
                visited.add(current)
                val nextDecl = importMap[current] ?: break
                current = (nextDecl.moduleReference as Identifier).text
            }
        }

        // Recurse into namespaces / function bodies / class member bodies / nested blocks
        for (stmt in stmts) {
            when (stmt) {
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                is FunctionDeclaration -> stmt.body?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is Block -> checkCircularAliasInStmts(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkCircularAliasInStmts(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkCircularAliasInStmts(listOf(it), source, fileName) }
                }
                is ForStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkCircularAliasInStmts(clause.statements, source, fileName)
                            is DefaultClause -> checkCircularAliasInStmts(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkCircularAliasInStmts(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkCircularAliasInStmts(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2303: Circular definition of import alias — `export =`/`require` cycle
    // -----------------------------------------------------------------------
    //
    // Handles the shape `import self = require("M"); export = self;` (an
    // ExternalModuleReference, distinct from `checkCircularImportAlias` which
    // only handles entity-name `import X = Y.Z` references). The self-import
    // re-exports module M; if following the `require → export = self` chain
    // (across ambient `declare module "X"` blocks AND real file modules) loops
    // back to a previously-visited module, the alias definition is circular.
    //
    // Report position (matches TypeScript): the cycle is "entered" at the
    // module that some NON-cycle file imports (the entry). For an AMBIENT entry
    // the error lands on the entry module's self-import; for a FILE entry it
    // lands on the entry's predecessor in the cycle (the self-import whose
    // `require` points back to the entry).

    private class SelfExportModule(
        val key: String,
        val importNode: ImportEqualsDeclaration,
        val source: String,
        val fileName: String,
        val nextSpec: String,
        val contextFileName: String,
    )

    /** If [statements] (a file's top-level or an ambient module body) contains
     *  `export = NAME` where NAME is an `import NAME = require("spec")`
     *  declaration in the same scope, return a [SelfExportModule] describing
     *  that re-export edge; otherwise null. */
    private fun buildSelfExportModule(
        statements: List<Statement>,
        key: String,
        fileName: String,
        source: String,
    ): SelfExportModule? {
        val exportEq = statements.filterIsInstance<ExportAssignment>().firstOrNull { it.isExportEquals } ?: return null
        val exprName = (exportEq.expression as? Identifier)?.text ?: return null
        val imp = statements.filterIsInstance<ImportEqualsDeclaration>().firstOrNull {
            it.name.text == exprName && it.moduleReference is ExternalModuleReference
        } ?: return null
        val spec = ((imp.moduleReference as ExternalModuleReference).expression as? StringLiteralNode)?.text ?: return null
        return SelfExportModule(key, imp, source, fileName, spec, fileName)
    }

    private fun checkCircularExportEqualsImportAlias() {
        // Collect all ambient module names (to route bare specifiers to ambient keys).
        val ambientNames = mutableSetOf<String>()
        for (result in binderResults) {
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode) {
                    ambientNames.add((stmt.name as StringLiteralNode).text)
                }
            }
        }

        // Collect self-export modules (file-level + ambient bodies), insertion order = declaration order.
        val modules = LinkedHashMap<String, SelfExportModule>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            buildSelfExportModule(result.sourceFile.statements, "file:$fileName", fileName, source)?.let { modules[it.key] = it }
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode) {
                    val body = stmt.body as? ModuleBlock ?: continue
                    val key = "ambient:" + (stmt.name as StringLiteralNode).text
                    buildSelfExportModule(body.statements, key, fileName, source)?.let { modules[it.key] = it }
                }
            }
        }
        if (modules.isEmpty()) return

        fun nextKey(m: SelfExportModule): String? {
            if (m.nextSpec in ambientNames) return "ambient:" + m.nextSpec
            val resolved = resolveModuleSpecifierRelative(m.nextSpec, m.contextFileName)
                ?: resolveModuleSpecifier(m.nextSpec)
            return if (resolved != null) "file:$resolved" else null
        }

        // Resolve a single `import X = require(spec)` declaration to a module key (for entry detection).
        fun importTargetKey(imp: ImportEqualsDeclaration, contextFile: String): String? {
            val ref = imp.moduleReference as? ExternalModuleReference ?: return null
            val spec = (ref.expression as? StringLiteralNode)?.text ?: return null
            if (spec in ambientNames) return "ambient:$spec"
            val resolved = resolveModuleSpecifierRelative(spec, contextFile) ?: resolveModuleSpecifier(spec)
            return if (resolved != null) "file:$resolved" else null
        }

        // Find, for a given cycle, the "entry" module: a cycle member imported by an
        // `import X = require(...)` whose container is NOT in the cycle.
        fun findEntry(cycle: Set<String>): String? {
            for (result in binderResults) {
                val fn = result.sourceFile.fileName
                val containerKey = "file:$fn"
                // file-level imports
                for (stmt in result.sourceFile.statements) {
                    if (stmt is ImportEqualsDeclaration) {
                        val tgt = importTargetKey(stmt, fn)
                        if (tgt != null && tgt in cycle && containerKey !in cycle) return tgt
                    }
                    if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode) {
                        val modKey = "ambient:" + (stmt.name as StringLiteralNode).text
                        val body = stmt.body as? ModuleBlock
                        if (body != null) {
                            for (inner in body.statements) {
                                if (inner is ImportEqualsDeclaration) {
                                    val tgt = importTargetKey(inner, fn)
                                    if (tgt != null && tgt in cycle && modKey !in cycle) return tgt
                                }
                            }
                        }
                    }
                }
            }
            return null
        }

        val emittedCycles = mutableSetOf<Set<String>>()
        for ((startKey, _) in modules) {
            val path = mutableListOf<String>()
            var cur: String? = startKey
            while (cur != null && cur in modules) {
                if (cur in path) {
                    val idx = path.indexOf(cur)
                    val cycle = path.subList(idx, path.size).toSet()
                    if (cycle in emittedCycles) break
                    emittedCycles.add(cycle)
                    // Determine the entry (a cycle member imported from outside the cycle).
                    val entry = findEntry(cycle) ?: break
                    val reportKey = if (entry.startsWith("ambient:")) {
                        entry
                    } else {
                        // FILE entry: report the predecessor (member whose next == entry).
                        cycle.firstOrNull { k -> modules[k]?.let { nextKey(it) } == entry } ?: entry
                    }
                    modules[reportKey]?.let { emitTS2303ForExportEqualsCycle(it) }
                    break
                }
                path.add(cur)
                cur = nextKey(modules[cur]!!)
            }
        }
    }

    /** Emit TS2303 on a self-import `import NAME = require("...")`, squiggle spanning
     *  the declaration up to the closing `)` of `require(...)` (no trailing `;`). */
    private fun emitTS2303ForExportEqualsCycle(m: SelfExportModule) {
        val source = m.source
        var spanStart = m.importNode.pos
        while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
        val refExpr = (m.importNode.moduleReference as ExternalModuleReference).expression
        val refPos = (refExpr as? StringLiteralNode)?.pos ?: spanStart
        val closeParen = source.indexOf(')', refPos)
        var spanEnd = if (closeParen >= spanStart) closeParen + 1 else m.importNode.end
        // Include a trailing `;` if it immediately follows the `require(...)` (TypeScript
        // squiggles the whole statement including the semicolon).
        var probe = spanEnd
        while (probe < source.length && source[probe].let { it == ' ' || it == '\t' }) probe++
        if (probe < source.length && source[probe] == ';') spanEnd = probe + 1
        val length = (spanEnd - spanStart).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
        diagnostics.add(Diagnostic(
            message = "Circular definition of import alias '${m.importNode.name.text}'.",
            category = DiagnosticCategory.Error,
            code = 2303,
            fileName = m.fileName,
            line = line,
            character = character,
            start = spanStart,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS1108: A 'return' statement can only be used within a function body
    // -----------------------------------------------------------------------

    private fun checkReturnOutsideFunction() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkReturnInTopLevel(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkReturnInTopLevel(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ReturnStatement -> {
                    val start = stmt.pos
                    var spanStart = start
                    while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                    // Span covers just the 'return' keyword
                    val length = 6 // "return".length
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "A 'return' statement can only be used within a function body.",
                        category = DiagnosticCategory.Error,
                        code = 1108,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
                is IfStatement -> {
                    checkReturnInTopLevelStmt(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { checkReturnInTopLevelStmt(it, source, fileName) }
                }
                is Block -> checkReturnInTopLevel(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    // Return inside namespace body is also invalid
                    val body = stmt.body
                    if (body is ModuleBlock) checkReturnInTopLevel(body.statements, source, fileName)
                }
                // Don't recurse into functions/classes — returns are valid there
                else -> {}
            }
        }
    }

    private fun checkReturnInTopLevelStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ReturnStatement -> {
                val start = stmt.pos
                var spanStart = start
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                // Span covers just the 'return' keyword (6 chars), not the expression
                val length = 6 // "return".length
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "A 'return' statement can only be used within a function body.",
                    category = DiagnosticCategory.Error,
                    code = 1108,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
            }
            is Block -> checkReturnInTopLevel(stmt.statements, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1101: 'with' statements are not allowed in strict mode
    // TS2410: The 'with' statement is not supported
    // -----------------------------------------------------------------------

    private fun checkWithStatements() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Strict mode: fires when alwaysStrict is not explicitly false
            val isStrict = options.alwaysStrict != false
            walkForWithStatements(result.sourceFile.statements, source, fileName, isStrict, isInAsync = false, isInWith = false)
        }
    }

    private fun walkForWithStatements(stmts: List<Statement>, source: String, fileName: String, isStrict: Boolean, isInAsync: Boolean, isInWith: Boolean) {
        for (stmt in stmts) {
            walkStmtForWithStatements(stmt, source, fileName, isStrict, isInAsync, isInWith)
        }
    }

    private fun walkStmtForWithStatements(stmt: Statement, source: String, fileName: String, isStrict: Boolean, isInAsync: Boolean, isInWith: Boolean) {
        when (stmt) {
            is WithStatement -> {
                var spanStart = stmt.pos
                while (spanStart < source.length && source[spanStart].isWhitespace()) spanStart++
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                if (isStrict) {
                    // TS1101: span = just the 'with' keyword (4 chars)
                    diagnostics.add(Diagnostic(
                        message = "'with' statements are not allowed in strict mode.",
                        category = DiagnosticCategory.Error,
                        code = 1101,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = 4, // "with".length
                    ))
                }
                // Only emit TS1300 and TS2410 for the outermost 'with' in a chain (not nested withs).
                if (!isInWith) {
                    if (isInAsync) {
                        // TS1300: 'with' not allowed in async function block
                        diagnostics.add(Diagnostic(
                            message = "'with' statements are not allowed in an async function block.",
                            category = DiagnosticCategory.Error,
                            code = 1300,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = spanStart,
                            length = 4,
                        ))
                    }
                    // TS2410: span = from 'with' to closing ')' of the condition.
                    // Find the matching ')' by scanning forward from 'with ' and tracking depth.
                    // Only emit TS2410 if the with statement is well-formed (balanced parens).
                    var spanEnd2 = spanStart + 4 // skip 'with'
                    while (spanEnd2 < source.length && source[spanEnd2] != '(') spanEnd2++
                    var depth = 0
                    var balanced = false
                    while (spanEnd2 < source.length) {
                        when (source[spanEnd2]) {
                            '(' -> { depth++; spanEnd2++ }
                            ')' -> {
                                spanEnd2++ // include the ')'
                                if (--depth == 0) { balanced = true; break }
                            }
                            else -> spanEnd2++
                        }
                    }
                    if (balanced) {
                        val ts2410Length = spanEnd2 - spanStart
                        diagnostics.add(Diagnostic(
                            message = "The 'with' statement is not supported. All symbols in a 'with' block will have type 'any'.",
                            category = DiagnosticCategory.Error,
                            code = 2410,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = spanStart,
                            length = ts2410Length,
                        ))
                    }
                }
                // Recurse into the body statement — now inside a with, TS2410 and TS1300 suppressed
                walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith = true)
            }
            is Block -> walkForWithStatements(stmt.statements, source, fileName, isStrict, isInAsync, isInWith)
            is IfStatement -> {
                walkStmtForWithStatements(stmt.thenStatement, source, fileName, isStrict, isInAsync, isInWith)
                stmt.elseStatement?.let { walkStmtForWithStatements(it, source, fileName, isStrict, isInAsync, isInWith) }
            }
            is ForStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            is ForInStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            is ForOfStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            is WhileStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            is DoStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    walkForWithStatements(stmts2, source, fileName, isStrict, isInAsync, isInWith)
                }
            }
            is TryStatement -> {
                walkForWithStatements(stmt.tryBlock.statements, source, fileName, isStrict, isInAsync, isInWith)
                stmt.catchClause?.block?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync, isInWith) }
                stmt.finallyBlock?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync, isInWith) }
            }
            is LabeledStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict, isInAsync, isInWith)
            // Function bodies: recurse, tracking async context, resetting isInWith
            is FunctionDeclaration -> {
                val fnIsAsync = ModifierFlag.Async in stmt.modifiers
                stmt.body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = fnIsAsync, isInWith = false) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val memberIsAsync = member is MethodDeclaration && ModifierFlag.Async in member.modifiers
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = memberIsAsync, isInWith = false) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForWithStatements(body.statements, source, fileName, isStrict, isInAsync = false, isInWith = false)
            }
            is ExpressionStatement -> walkExprForWithStatements(stmt.expression, source, fileName, isStrict, isInWith)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForWithStatements(it, source, fileName, isStrict, isInWith) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForWithStatements(it, source, fileName, isStrict, isInWith) }
            is ThrowStatement -> stmt.expression?.let { walkExprForWithStatements(it, source, fileName, isStrict, isInWith) }
            is ExportAssignment -> walkExprForWithStatements(stmt.expression, source, fileName, isStrict, isInWith)
            else -> {}
        }
    }

    private fun walkExprForWithStatements(expr: Expression, source: String, fileName: String, isStrict: Boolean, isInWith: Boolean) {
        when (expr) {
            is FunctionExpression -> {
                val fnIsAsync = ModifierFlag.Async in expr.modifiers
                walkForWithStatements(expr.body.statements, source, fileName, isStrict, isInAsync = fnIsAsync, isInWith = false)
            }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForWithStatements(body.statements, source, fileName, isStrict, isInAsync = false, isInWith = false)
                else if (body is Expression) walkExprForWithStatements(body, source, fileName, isStrict, isInWith)
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    val memberIsAsync = member is MethodDeclaration && ModifierFlag.Async in member.modifiers
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = memberIsAsync, isInWith = false) }
                }
            }
            is ParenthesizedExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is AsExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is TypeAssertionExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is SatisfiesExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is NonNullExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkExprForWithStatements(cur, source, fileName, isStrict, isInWith)
                while (rightStack.isNotEmpty()) walkExprForWithStatements(rightStack.removeLast(), source, fileName, isStrict, isInWith)
            }
            is ConditionalExpression -> {
                walkExprForWithStatements(expr.condition, source, fileName, isStrict, isInWith)
                walkExprForWithStatements(expr.whenTrue, source, fileName, isStrict, isInWith)
                walkExprForWithStatements(expr.whenFalse, source, fileName, isStrict, isInWith)
            }
            is CallExpression -> {
                walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
                for (arg in expr.arguments) walkExprForWithStatements(arg, source, fileName, isStrict, isInWith)
            }
            is NewExpression -> {
                walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
                expr.arguments?.forEach { walkExprForWithStatements(it, source, fileName, isStrict, isInWith) }
            }
            is PropertyAccessExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is ElementAccessExpression -> {
                walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
                walkExprForWithStatements(expr.argumentExpression, source, fileName, isStrict, isInWith)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) walkExprForWithStatements(e, source, fileName, isStrict, isInWith)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> walkExprForWithStatements(p.initializer, source, fileName, isStrict, isInWith)
                    is SpreadAssignment -> walkExprForWithStatements(p.expression, source, fileName, isStrict, isInWith)
                    is MethodDeclaration -> {
                        val mAsync = ModifierFlag.Async in p.modifiers
                        p.body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = mAsync, isInWith = false) }
                    }
                    is GetAccessor -> p.body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = false, isInWith = false) }
                    is SetAccessor -> p.body?.let { walkForWithStatements(it.statements, source, fileName, isStrict, isInAsync = false, isInWith = false) }
                    else -> {}
                }
            }
            is SpreadElement -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is PrefixUnaryExpression -> walkExprForWithStatements(expr.operand, source, fileName, isStrict, isInWith)
            is PostfixUnaryExpression -> walkExprForWithStatements(expr.operand, source, fileName, isStrict, isInWith)
            is AwaitExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is YieldExpression -> expr.expression?.let { walkExprForWithStatements(it, source, fileName, isStrict, isInWith) }
            is VoidExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is DeleteExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is TypeOfExpression -> walkExprForWithStatements(expr.expression, source, fileName, isStrict, isInWith)
            is TemplateExpression -> for (span in expr.templateSpans) walkExprForWithStatements(span.expression, source, fileName, isStrict, isInWith)
            is TaggedTemplateExpression -> {
                walkExprForWithStatements(expr.tag, source, fileName, isStrict, isInWith)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) walkExprForWithStatements(span.expression, source, fileName, isStrict, isInWith)
                }
            }
            is CommaListExpression -> for (e in expr.elements) walkExprForWithStatements(e, source, fileName, isStrict, isInWith)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2815: 'arguments' in class field initializers / static blocks
    // -----------------------------------------------------------------------

    /**
     * TS2815: "'arguments' cannot be referenced in property initializers
     * or class static initialization blocks."
     * Fires when `arguments` appears in:
     *   - PropertyDeclaration initializers (including arrow functions inside)
     *   - ClassStaticBlockDeclaration bodies
     * Does NOT fire inside regular function expressions/declarations (they have their own `arguments`).
     * Fires unconditionally (not gated by strict/noImplicitAny).
     */
    private fun checkArgumentsInClassFieldInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            findClassesForTS2815InStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun findClassesForTS2815InStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        checkClassMembersForTS2815(stmt.members, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) findClassesForTS2815InStatements(body.statements, source, fileName)
                }
                is FunctionDeclaration -> {
                    stmt.body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                }
                is Block -> findClassesForTS2815InStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    findClassesForTS2815InStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { findClassesForTS2815InStatements(listOf(it), source, fileName) }
                }
                is ReturnStatement -> {
                    stmt.expression?.let { findClassesForTS2815InExpr(it, source, fileName) }
                }
                is ExpressionStatement -> findClassesForTS2815InExpr(stmt.expression, source, fileName)
                is ForStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> findClassesForTS2815InStatements(clause.statements, source, fileName)
                        is DefaultClause -> findClassesForTS2815InStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    findClassesForTS2815InStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { findClassesForTS2815InStatements(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> findClassesForTS2815InStatements(listOf(stmt.statement), source, fileName)
                is ThrowStatement -> stmt.expression?.let { findClassesForTS2815InExpr(it, source, fileName) }
                is ExportAssignment -> findClassesForTS2815InExpr(stmt.expression, source, fileName)
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { findClassesForTS2815InExpr(it, source, fileName) }
                    }
                }
                else -> {}
            }
        }
    }

    private fun findClassesForTS2815InExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ClassExpression -> {
                if (ModifierFlag.Declare !in expr.modifiers) {
                    checkClassMembersForTS2815(expr.members, source, fileName)
                }
            }
            is NewExpression -> {
                findClassesForTS2815InExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { findClassesForTS2815InExpr(it, source, fileName) }
            }
            is CallExpression -> {
                findClassesForTS2815InExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) findClassesForTS2815InExpr(arg, source, fileName)
            }
            is ParenthesizedExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is AsExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is NonNullExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                findClassesForTS2815InExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) findClassesForTS2815InExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                findClassesForTS2815InExpr(expr.condition, source, fileName)
                findClassesForTS2815InExpr(expr.whenTrue, source, fileName)
                findClassesForTS2815InExpr(expr.whenFalse, source, fileName)
            }
            is PropertyAccessExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                findClassesForTS2815InExpr(expr.expression, source, fileName)
                findClassesForTS2815InExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) findClassesForTS2815InExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> findClassesForTS2815InExpr(p.initializer, source, fileName)
                    is SpreadAssignment -> findClassesForTS2815InExpr(p.expression, source, fileName)
                    else -> {}
                }
            }
            is SpreadElement -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> findClassesForTS2815InExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> findClassesForTS2815InExpr(expr.operand, source, fileName)
            is AwaitExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { findClassesForTS2815InExpr(it, source, fileName) }
            is VoidExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is DeleteExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is TypeOfExpression -> findClassesForTS2815InExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) findClassesForTS2815InExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                findClassesForTS2815InExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) findClassesForTS2815InExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) findClassesForTS2815InExpr(e, source, fileName)
            // FunctionExpression/ArrowFunction as the TOP-LEVEL return — look for class inside
            is FunctionExpression -> {
                findClassesForTS2815InStatements(expr.body.statements, source, fileName)
            }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) findClassesForTS2815InStatements(body.statements, source, fileName)
                else if (body is Expression) findClassesForTS2815InExpr(body, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkClassMembersForTS2815(members: List<ClassElement>, source: String, fileName: String) {
        for (member in members) {
            when (member) {
                is PropertyDeclaration -> {
                    // Check initializer expression — not method bodies
                    member.initializer?.let { checkExprForTS2815Arguments(it, source, fileName) }
                }
                is ClassStaticBlockDeclaration -> {
                    // Check static block body
                    checkStatementsForTS2815Arguments(member.body.statements, source, fileName)
                }
                else -> {
                    // Constructor, MethodDeclaration, GetAccessor, SetAccessor — skip (they have their own arguments)
                    // But recurse into nested classes
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                }
            }
        }
    }

    /**
     * Walk an expression in a "class field initializer context" — looking for `arguments` identifiers.
     * Stop recursing into FunctionExpression/FunctionDeclaration bodies (they have their own arguments).
     * Arrow functions DO propagate the class field context.
     */
    private fun checkExprForTS2815Arguments(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is Identifier -> {
                if (expr.text == "arguments") {
                    emitTS2815(expr.pos, source, fileName)
                }
            }
            is ArrowFunction -> {
                // Arrow functions: parameters with defaults, body
                for (param in expr.parameters) {
                    param.initializer?.let { checkExprForTS2815Arguments(it, source, fileName) }
                }
                val body = expr.body
                if (body is Block) checkStatementsForTS2815Arguments(body.statements, source, fileName)
                else if (body is Expression) checkExprForTS2815Arguments(body, source, fileName)
            }
            // FunctionExpression: has own `arguments` — do not emit TS2815, but look for inner classes
            is FunctionExpression -> {
                findClassesForTS2815InStatements(expr.body.statements, source, fileName)
            }
            // ClassExpression inside field initializer — recurse into its members
            is ClassExpression -> {
                checkClassMembersForTS2815(expr.members, source, fileName)
            }
            // Other complex expressions — recurse
            is CallExpression -> {
                checkExprForTS2815Arguments(expr.expression, source, fileName)
                for (arg in expr.arguments) checkExprForTS2815Arguments(arg, source, fileName)
            }
            is NewExpression -> {
                checkExprForTS2815Arguments(expr.expression, source, fileName)
                expr.arguments?.forEach { checkExprForTS2815Arguments(it, source, fileName) }
            }
            is BinaryExpression -> {
                checkExprForTS2815Arguments(expr.left, source, fileName)
                checkExprForTS2815Arguments(expr.right, source, fileName)
            }
            is PropertyAccessExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkExprForTS2815Arguments(expr.expression, source, fileName)
                checkExprForTS2815Arguments(expr.argumentExpression, source, fileName)
            }
            is ParenthesizedExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkExprForTS2815Arguments(expr.condition, source, fileName)
                checkExprForTS2815Arguments(expr.whenTrue, source, fileName)
                checkExprForTS2815Arguments(expr.whenFalse, source, fileName)
            }
            is PrefixUnaryExpression -> checkExprForTS2815Arguments(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkExprForTS2815Arguments(expr.operand, source, fileName)
            is TypeAssertionExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is AsExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is SatisfiesExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is NonNullExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is AwaitExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkExprForTS2815Arguments(it, source, fileName) }
            is DeleteExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is VoidExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is TypeOfExpression -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { checkExprForTS2815Arguments(it, source, fileName) }
            is SpreadElement -> checkExprForTS2815Arguments(expr.expression, source, fileName)
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkExprForTS2815Arguments(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> {
                            // no initializer to check
                        }
                        is SpreadAssignment -> checkExprForTS2815Arguments(prop.expression, source, fileName)
                        is MethodDeclaration -> {
                            // Method in object literal — has its own arguments
                            prop.body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                        }
                        is GetAccessor -> prop.body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                        is SetAccessor -> prop.body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrayLiteralExpression -> {
                for (elem in expr.elements) checkExprForTS2815Arguments(elem, source, fileName)
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) checkExprForTS2815Arguments(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkExprForTS2815Arguments(expr.tag, source, fileName)
                val tmpl = expr.template
                if (tmpl is TemplateExpression) {
                    for (span in tmpl.templateSpans) checkExprForTS2815Arguments(span.expression, source, fileName)
                }
            }
            else -> {}
        }
    }

    /**
     * Walk statements in a "class field initializer context" (like static block bodies).
     * Stops recursing at FunctionDeclaration bodies.
     */
    private fun checkStatementsForTS2815Arguments(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkStatementForTS2815Arguments(stmt, source, fileName)
    }

    private fun checkStatementForTS2815Arguments(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkExprForTS2815Arguments(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkExprForTS2815Arguments(it, source, fileName) }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkExprForTS2815Arguments(it, source, fileName) }
                }
            }
            is Block -> checkStatementsForTS2815Arguments(stmt.statements, source, fileName)
            is IfStatement -> {
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
                checkStatementForTS2815Arguments(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkStatementForTS2815Arguments(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkExprForTS2815Arguments(it, source, fileName) }
                        }
                    }
                    is Expression -> checkExprForTS2815Arguments(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkExprForTS2815Arguments(it, source, fileName) }
                stmt.incrementor?.let { checkExprForTS2815Arguments(it, source, fileName) }
                checkStatementForTS2815Arguments(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
                checkStatementForTS2815Arguments(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
                checkStatementForTS2815Arguments(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
                checkStatementForTS2815Arguments(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkStatementForTS2815Arguments(stmt.statement, source, fileName)
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkExprForTS2815Arguments(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> { checkExprForTS2815Arguments(clause.expression, source, fileName); clause.statements }
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkStatementsForTS2815Arguments(clauseStmts, source, fileName)
                }
            }
            is TryStatement -> {
                checkStatementsForTS2815Arguments(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { checkStatementsForTS2815Arguments(it.statements, source, fileName) }
                stmt.finallyBlock?.let { checkStatementsForTS2815Arguments(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkExprForTS2815Arguments(it, source, fileName) }
            is LabeledStatement -> checkStatementForTS2815Arguments(stmt.statement, source, fileName)
            // FunctionDeclaration inside static block: has own arguments — skip body but recurse for inner classes
            is FunctionDeclaration -> {
                stmt.body?.let { findClassesForTS2815InStatements(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    checkClassMembersForTS2815(stmt.members, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun emitTS2815(start: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'arguments' cannot be referenced in property initializers or class static initialization blocks.",
            category = DiagnosticCategory.Error,
            code = 2815,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = "arguments".length,
        ))
    }

