    // TS1114: Duplicate label
    // -----------------------------------------------------------------------

    private fun checkDuplicateLabels() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDuplicateLabels(result.sourceFile.statements, source, fileName, mutableSetOf())
        }
    }

    private fun walkForDuplicateLabels(stmts: List<Statement>, source: String, fileName: String, activeLabels: MutableSet<String>) {
        for (stmt in stmts) walkStmtForDupLabels(stmt, source, fileName, activeLabels)
    }

    private fun walkStmtForDupLabels(stmt: Statement, source: String, fileName: String, activeLabels: MutableSet<String>) {
        when (stmt) {
            is LabeledStatement -> {
                val label = stmt.label.text
                if (label in activeLabels) {
                    val start = stmt.label.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Duplicate label '$label'.",
                        category = DiagnosticCategory.Error,
                        code = 1114,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = label.length,
                    ))
                }
                activeLabels.add(label)
                walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
                activeLabels.remove(label)
            }
            is FunctionDeclaration -> {
                // New label scope inside functions
                stmt.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        is Constructor -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        is GetAccessor -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        is SetAccessor -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        else -> {}
                    }
                }
            }
            is Block -> walkForDuplicateLabels(stmt.statements, source, fileName, activeLabels)
            is IfStatement -> {
                walkStmtForDupLabels(stmt.thenStatement, source, fileName, activeLabels)
                stmt.elseStatement?.let { walkStmtForDupLabels(it, source, fileName, activeLabels) }
            }
            is ForStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is ForInStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is ForOfStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is WhileStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is DoStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> walkForDuplicateLabels(c.statements, source, fileName, activeLabels)
                        is DefaultClause -> walkForDuplicateLabels(c.statements, source, fileName, activeLabels)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForDuplicateLabels(stmt.tryBlock.statements, source, fileName, activeLabels)
                stmt.catchClause?.let { walkForDuplicateLabels(it.block.statements, source, fileName, activeLabels) }
                stmt.finallyBlock?.let { walkForDuplicateLabels(it.statements, source, fileName, activeLabels) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForDuplicateLabels(it.statements, source, fileName, activeLabels) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1099: Type argument list cannot be empty
    // -----------------------------------------------------------------------

    private fun checkEmptyTypeArguments() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForEmptyTypeArgs(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForEmptyTypeArgs(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForEmptyTypeArgs(stmt, source, fileName)
    }

    private fun walkStmtForEmptyTypeArgs(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
                    else -> {}
                }
            }
            is Block -> walkForEmptyTypeArgs(stmt.statements, source, fileName)
            is IfStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                walkStmtForEmptyTypeArgs(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForEmptyTypeArgs(it, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> for (d in init.declarations) d.initializer?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
                    is Expression -> walkExprForEmptyTypeArgs(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
                stmt.incrementor?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
                walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            walkExprForEmptyTypeArgs(clause.expression, source, fileName)
                            walkForEmptyTypeArgs(clause.statements, source, fileName)
                        }
                        is DefaultClause -> walkForEmptyTypeArgs(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForEmptyTypeArgs(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
            }
            is LabeledStatement -> walkStmtForEmptyTypeArgs(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            is ExportAssignment -> walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkExprForEmptyTypeArgs(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is CallExpression -> {
                if (expr.typeArguments != null && expr.typeArguments.isEmpty()) {
                    reportEmptyTypeArgs(expr, source, fileName)
                }
                walkExprForEmptyTypeArgs(expr.expression, source, fileName)
                for (arg in expr.arguments) walkExprForEmptyTypeArgs(arg, source, fileName)
            }
            is NewExpression -> {
                if (expr.typeArguments != null && expr.typeArguments.isEmpty()) {
                    reportEmptyTypeArgs(expr, source, fileName)
                }
                walkExprForEmptyTypeArgs(expr.expression, source, fileName)
                expr.arguments?.forEach { walkExprForEmptyTypeArgs(it, source, fileName) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkExprForEmptyTypeArgs(current.right, source, fileName)
                    current = current.left
                }
                walkExprForEmptyTypeArgs(current, source, fileName)
            }
            is ParenthesizedExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is ConditionalExpression -> {
                walkExprForEmptyTypeArgs(expr.condition, source, fileName)
                walkExprForEmptyTypeArgs(expr.whenTrue, source, fileName)
                walkExprForEmptyTypeArgs(expr.whenFalse, source, fileName)
            }
            is PropertyAccessExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkExprForEmptyTypeArgs(expr.expression, source, fileName)
                walkExprForEmptyTypeArgs(expr.argumentExpression, source, fileName)
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> walkForEmptyTypeArgs(body.statements, source, fileName)
                    is Expression -> walkExprForEmptyTypeArgs(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> walkForEmptyTypeArgs(expr.body.statements, source, fileName)
            is AsExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is SatisfiesExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is NonNullExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is PrefixUnaryExpression -> walkExprForEmptyTypeArgs(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkExprForEmptyTypeArgs(expr.operand, source, fileName)
            is SpreadElement -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is AwaitExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForEmptyTypeArgs(it, source, fileName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkExprForEmptyTypeArgs(prop.initializer, source, fileName)
                is SpreadAssignment -> walkExprForEmptyTypeArgs(prop.expression, source, fileName)
                else -> {}
            }
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForEmptyTypeArgs(it.expression, source, fileName) }
            is TaggedTemplateExpression -> {
                walkExprForEmptyTypeArgs(expr.tag, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { walkExprForEmptyTypeArgs(it.expression, source, fileName) }
                    else -> {}
                }
            }
            is CommaListExpression -> expr.elements.forEach { walkExprForEmptyTypeArgs(it, source, fileName) }
            else -> {}
        }
    }

    private fun reportEmptyTypeArgs(expr: Node, source: String, fileName: String) {
        // Find the `<>` in source — search from the expression start (not end, which may
        // overshoot past `<` due to parser position semantics after nextToken())
        val searchStart = when (expr) {
            is CallExpression -> expr.expression.pos
            is NewExpression -> expr.expression.pos
            else -> expr.pos
        }
        val ltIdx = source.indexOf("<>", searchStart)
        if (ltIdx < 0) return
        emitTS1099(ltIdx, source, fileName)
    }

    private fun emitTS1099(start: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type argument list cannot be empty.",
            category = DiagnosticCategory.Error,
            code = 1099,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = 2, // "<>"
        ))
    }

    // -----------------------------------------------------------------------
    // TS2354: importHelpers without tslib
    // -----------------------------------------------------------------------

    private fun checkImportHelpersWithoutTslib() {
        if (!options.importHelpers) return
        // Check if tslib is available in the compilation files
        // With classic/AMD/System resolution, tslib.d.ts in root is found.
        // With node/nodenext resolution, tslib must be in node_modules/tslib/.
        val moduleRes = options.moduleResolution?.lowercase()
        val effectiveModuleRes = moduleRes ?: run {
            when (options.module) {
                ModuleKind.CommonJS -> "node10"
                ModuleKind.Node16, ModuleKind.Node18, ModuleKind.Node20 -> "node16"
                ModuleKind.NodeNext -> "nodenext"
                ModuleKind.System, ModuleKind.AMD, ModuleKind.UMD -> "classic"
                else -> "node10"
            }
        }
        val isClassicResolution = effectiveModuleRes == "classic"
        // Check for ambient module "tslib" declaration — counts as found regardless of resolution
        val hasAmbientTslib = binderResults.any { result ->
            result.sourceFile.statements.any { stmt ->
                stmt is ModuleDeclaration && (stmt.name as? StringLiteralNode)?.text == "tslib"
            }
        }
        val hasTslib = hasAmbientTslib || if (isClassicResolution) {
            // 16.4do: Classic resolution (AMD/System/UMD) does NOT search node_modules
            // — only accepts tslib.d.ts in the root/baseUrl. Tests that provide tslib
            // ONLY via `node_modules/tslib/index.d.ts` still need TS2354 under classic.
            binderResults.any { result ->
                val fn = result.sourceFile.fileName
                fn.contains("tslib") && !(fn.contains("node_modules") || fn.contains("node-modules"))
            }
        } else {
            // Modern resolution: only node_modules/tslib/ counts
            binderResults.any { result ->
                val fn = result.sourceFile.fileName
                (fn.contains("node_modules") || fn.contains("node-modules")) && fn.contains("tslib")
            }
        }
        if (hasTslib) return

        val em = options.effectiveModule
        // esModuleInterop helpers needed for CJS/AMD/UMD/NodeNext (not System/ES) modules
        val needsEsmHelpers = options.esModuleInterop && (em == ModuleKind.CommonJS || em == ModuleKind.AMD ||
                em == ModuleKind.UMD || em.isNodeNext)
        // Class extends helpers needed when target < ES2015 (raw target)
        val needsExtendsHelper = options.target <= ScriptTarget.ES5
        // Decorator helpers always needed when experimentalDecorators is set
        val needsDecoratorHelper = options.experimentalDecorators

        if (!needsEsmHelpers && !needsExtendsHelper && !needsDecoratorHelper) return

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            val isModule = isModuleFile(result.sourceFile.statements)
            val ts2354StartCount = diagnostics.count { it.code == 2354 && it.fileName == fileName }

            for (stmt in result.sourceFile.statements) {
                if (diagnostics.count { it.code == 2354 && it.fileName == fileName } > ts2354StartCount) break
                when (stmt) {
                    is ExportDeclaration -> if (needsEsmHelpers) {
                        if (stmt.moduleSpecifier != null && !stmt.isTypeOnly) {
                            val clause = stmt.exportClause
                            if (clause is NamedExports) {
                                for (spec in clause.elements) {
                                    if (spec.isTypeOnly) continue
                                    val importedName = (spec.propertyName ?: spec.name).text
                                    if (importedName == "default") {
                                        val startNode = spec.propertyName ?: spec.name
                                        val endNode = if (spec.propertyName != null) spec.name else spec.name
                                        val spanStart = startNode.pos
                                        val spanLen = if (spec.propertyName != null) {
                                            endNode.pos + endNode.text.length - spanStart
                                        } else {
                                            startNode.text.length
                                        }
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                    is ImportDeclaration -> if (needsEsmHelpers) {
                        if (stmt.importClause?.isTypeOnly != true) {
                            val clause = stmt.importClause ?: continue
                            val bindings = clause.namedBindings
                            // import * as X from "..." needs __importStar
                            if (bindings is NamespaceImport) {
                                // Span covers whole import statement (from import keyword to semicolon)
                                val spanStart = stmt.pos
                                // Find end of statement line (up to and including semicolon)
                                val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                                val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                                emitTS2354(spanStart, spanLen, source, fileName)
                            }
                            // import { default as X } from "..." needs __importDefault
                            if (bindings is NamedImports) {
                                for (spec in bindings.elements) {
                                    if (spec.isTypeOnly) continue
                                    val importedName = (spec.propertyName ?: spec.name).text
                                    if (importedName == "default") {
                                        val startNode = spec.propertyName ?: spec.name
                                        val endNode = if (spec.propertyName != null) spec.name else spec.name
                                        val spanStart = startNode.pos
                                        val spanLen = if (spec.propertyName != null) {
                                            endNode.pos + endNode.text.length - spanStart
                                        } else {
                                            startNode.text.length
                                        }
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                    is ClassDeclaration -> {
                        var emittedForClass = false
                        // Class extends with target < ES2015 needs __extends helper (module files only)
                        if (needsExtendsHelper && isModule) {
                            val heritageClauses = stmt.heritageClauses
                            if (heritageClauses != null) {
                                for (clause in heritageClauses) {
                                    if (clause.token == SyntaxKind.ExtendsKeyword && clause.types.isNotEmpty()) {
                                        val spanStart = clause.pos
                                        val firstType = clause.types.first()
                                        val typeEnd = expressionTrueEnd(firstType.expression)
                                        val spanLen = typeEnd - spanStart
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                        emittedForClass = true
                                    }
                                }
                            }
                        }
                        // Decorators need __decorate helper (module files only) — skip if already emitted
                        if (!emittedForClass && needsDecoratorHelper && isModule) {
                            checkDecoratorHelperOnClass(stmt, source, fileName)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    private fun emitTS2354(spanStart: Int, spanLen: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
        diagnostics.add(Diagnostic(
            message = "This syntax requires an imported helper but module 'tslib' cannot be found.",
            category = DiagnosticCategory.Error,
            code = 2354,
            fileName = fileName,
            line = line,
            character = character,
            start = spanStart,
            length = spanLen,
        ))
    }

    private fun checkDecoratorHelperOnClass(stmt: ClassDeclaration, source: String, fileName: String) {
        // Check if the class or any of its members have decorators
        val firstDecorator = stmt.decorators?.firstOrNull()
        if (firstDecorator != null) {
            // Span covers the decorator expression including @
            // e.g., "@dec" → 4 chars
            val decoratorSpan = getDecoratorSpan(firstDecorator, source)
            emitTS2354(decoratorSpan.first, decoratorSpan.second, source, fileName)
            return
        }
        // Also check member decorators (methods, properties, parameters)
        for (member in stmt.members) {
            val memberDec = when (member) {
                is MethodDeclaration -> member.decorators?.firstOrNull()
                is PropertyDeclaration -> member.decorators?.firstOrNull()
                is GetAccessor -> member.decorators?.firstOrNull()
                is SetAccessor -> member.decorators?.firstOrNull()
                else -> null
            }
            if (memberDec != null) {
                val spanStart = memberDec.pos
                val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                emitTS2354(spanStart, spanLen, source, fileName)
                return
            }
            // Check parameter decorators
            val params = when (member) {
                is MethodDeclaration -> member.parameters
                is Constructor -> member.parameters
                else -> emptyList()
            }
            for (param in params) {
                val paramDec = param.decorators?.firstOrNull()
                if (paramDec != null) {
                    val spanStart = paramDec.pos
                    val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                    val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                    emitTS2354(spanStart, spanLen, source, fileName)
                    return
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2343: Missing helper in tslib
    // -----------------------------------------------------------------------

    /**
     * Check for TS2343: "This syntax requires an imported helper named '__X' which does
     * not exist in 'tslib'. Consider upgrading your version of 'tslib'."
     * Fires when importHelpers=true, tslib IS found, but the required helper is not exported.
     */
    private fun checkMissingTslibHelpers() {
        if (!options.importHelpers) return
        // Find tslib file in compilation — use same resolution logic as checkImportHelpersWithoutTslib
        val moduleRes = options.moduleResolution?.lowercase()
        val effectiveModuleRes = moduleRes ?: run {
            when (options.module) {
                ModuleKind.CommonJS -> "node10"
                ModuleKind.Node16, ModuleKind.Node18, ModuleKind.Node20 -> "node16"
                ModuleKind.NodeNext -> "nodenext"
                ModuleKind.System, ModuleKind.AMD, ModuleKind.UMD -> "classic"
                else -> "node10"
            }
        }
        val isClassicResolution2 = effectiveModuleRes == "classic"
        // Check for ambient module "tslib" declaration — counts as found regardless of resolution
        val ambientTslibResult = binderResults.firstOrNull { result ->
            result.sourceFile.statements.any { stmt ->
                stmt is ModuleDeclaration && (stmt.name as? StringLiteralNode)?.text == "tslib"
            }
        }
        val tslibResult = ambientTslibResult ?: if (isClassicResolution2) {
            binderResults.firstOrNull { it.sourceFile.fileName.contains("tslib") }
        } else {
            binderResults.firstOrNull { result ->
                val fn = result.sourceFile.fileName
                (fn.contains("node_modules") || fn.contains("node-modules")) && fn.contains("tslib")
            }
        } ?: return
        // Get what tslib exports
        val tslibExports = getTslibExports(tslibResult.sourceFile)

        val isEs5Target = options.target <= ScriptTarget.ES5
        val hasDecorators = options.experimentalDecorators || options.emitDecoratorMetadata

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Only check module files (files with import/export statements)
            val isModule = isModuleFile(result.sourceFile.statements)
            if (!isModule) continue
            val source = result.sourceFile.text

            for (stmt in result.sourceFile.statements) {
                checkStmtForMissingHelper(stmt, source, fileName, tslibExports, isEs5Target, hasDecorators)
            }
        }
    }

    private fun checkStmtForMissingHelper(
        stmt: Statement,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
        isEs5Target: Boolean,
        hasDecorators: Boolean,
    ) {
        when (stmt) {
            is ExportDeclaration -> {
                // export * from "X" → needs __exportStar (not for System modules — they inline it)
                val em = options.effectiveModule
                val isSystemOrAmd = em == ModuleKind.System || em == ModuleKind.AMD || em == ModuleKind.UMD
                if (!isSystemOrAmd && stmt.exportClause == null && stmt.moduleSpecifier != null && !stmt.isTypeOnly) {
                    if ("__exportStar" !in tslibExports) {
                        // Span: from stmt.pos to after ';' (inclusive)
                        val semiPos = source.indexOf(';', stmt.pos)
                        val spanLen = if (semiPos >= 0) (semiPos + 1) - stmt.pos else 1
                        emitTS2343("__exportStar", stmt.pos, spanLen, source, fileName)
                    }
                }
            }
            is ClassDeclaration -> {
                // class B extends A → needs __extends (ES5 only)
                if (isEs5Target && stmt.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword && it.types.isNotEmpty() } == true) {
                    if ("__extends" !in tslibExports) {
                        // Span: position of "extends X" (the heritage clause text)
                        val extendsClause = stmt.heritageClauses!!.first { it.token == SyntaxKind.ExtendsKeyword }
                        val extendsType = extendsClause.types.first()
                        // Find "extends" keyword position: it's before the expression
                        val extendsPos = extendsClause.pos
                        // Span: from "extends" to end of expression name
                        val ident = extendsType.expression as? Identifier
                        val exprEnd = if (ident != null) {
                            ident.pos + ident.text.length
                        } else {
                            source.indexOf(')', extendsType.expression.pos) + 1
                        }
                        val spanLen = exprEnd - extendsPos
                        emitTS2343("__extends", extendsPos, spanLen.coerceAtLeast(1), source, fileName)
                    }
                }
                // @dec class C → needs __decorate and __metadata
                if (hasDecorators && stmt.decorators?.isNotEmpty() == true) {
                    val decorator = stmt.decorators!!.first()
                    val decoratorSpan = getDecoratorSpan(decorator, source)
                    if ("__decorate" !in tslibExports) {
                        emitTS2343("__decorate", decoratorSpan.first, decoratorSpan.second, source, fileName)
                    }
                    if ("__metadata" !in tslibExports && options.emitDecoratorMetadata) {
                        emitTS2343("__metadata", decoratorSpan.first, decoratorSpan.second, source, fileName)
                    }
                    // Check parameters with decorators
                    checkParameterDecoratorsForHelper(stmt.members, source, fileName, tslibExports, hasDecorators)
                } else if (hasDecorators) {
                    checkParameterDecoratorsForHelper(stmt.members, source, fileName, tslibExports, hasDecorators)
                }
                // Check for private field access helpers (#field)
                checkClassMembersForPrivateFields(stmt.members, source, fileName, tslibExports)
            }
            is VariableStatement -> {
                // Walk variable declarations for spread/rest patterns
                for (decl in stmt.declarationList.declarations) {
                    checkExprForMissingHelper(decl.initializer, source, fileName, tslibExports, isEs5Target)
                    checkBindingForMissingHelper(decl.name, source, fileName, tslibExports)
                }
            }
            is FunctionDeclaration -> {
                // async function * f() → needs __asyncGenerator, __await, and __generator (ES5)
                if (ModifierFlag.Async in stmt.modifiers && stmt.asteriskToken) {
                    // TypeScript reports the diagnostic at the function name position (not the '*')
                    val namePos = stmt.name?.pos
                    if (namePos != null) {
                        val nameLen = stmt.name!!.text.length
                        if ("__asyncGenerator" !in tslibExports) {
                            emitTS2343("__asyncGenerator", namePos, nameLen, source, fileName)
                        }
                        if ("__await" !in tslibExports) {
                            emitTS2343("__await", namePos, nameLen, source, fileName)
                        }
                        if (isEs5Target && "__generator" !in tslibExports) {
                            emitTS2343("__generator", namePos, nameLen, source, fileName)
                        }
                    }
                    // Walk body for yield* statements
                    stmt.body?.let {
                        checkBlockForAsyncDelegator(it, source, fileName, tslibExports)
                    }
                }
            }
            is ExpressionStatement -> {
                checkExprForMissingHelper(stmt.expression, source, fileName, tslibExports, isEs5Target)
            }
            else -> {}
        }
    }

    /** Walk a Block looking for YieldExpression with asteriskToken = true inside an async generator. */
    private fun checkBlockForAsyncDelegator(
        block: Block,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        for (stmt in block.statements) {
            checkStmtForAsyncDelegator(stmt, source, fileName, tslibExports)
        }
    }

    private fun checkStmtForAsyncDelegator(
        stmt: Statement,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
            is ReturnStatement -> stmt.expression?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
                }
            }
            // round 42 iter13: broader statement coverage for yield* detection inside
            // nested control flow within an async generator body.
            is Block -> for (s in stmt.statements) checkStmtForAsyncDelegator(s, source, fileName, tslibExports)
            is IfStatement -> {
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
                checkStmtForAsyncDelegator(stmt.thenStatement, source, fileName, tslibExports)
                stmt.elseStatement?.let { checkStmtForAsyncDelegator(it, source, fileName, tslibExports) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> for (d in init.declarations) {
                        d.initializer?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
                    }
                    is Expression -> checkExprForAsyncDelegator(init, source, fileName, tslibExports)
                    else -> {}
                }
                stmt.condition?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
                stmt.incrementor?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
                checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
            }
            is ForInStatement -> {
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
                checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
            }
            is ForOfStatement -> {
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
                checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
            }
            is WhileStatement -> {
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
                checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
            }
            is DoStatement -> {
                checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
            }
            is SwitchStatement -> {
                checkExprForAsyncDelegator(stmt.expression, source, fileName, tslibExports)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> {
                            checkExprForAsyncDelegator(clause.expression, source, fileName, tslibExports)
                            clause.statements
                        }
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    for (s in clauseStmts) checkStmtForAsyncDelegator(s, source, fileName, tslibExports)
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkStmtForAsyncDelegator(s, source, fileName, tslibExports)
                stmt.catchClause?.block?.let { for (s in it.statements) checkStmtForAsyncDelegator(s, source, fileName, tslibExports) }
                stmt.finallyBlock?.let { for (s in it.statements) checkStmtForAsyncDelegator(s, source, fileName, tslibExports) }
            }
            is LabeledStatement -> checkStmtForAsyncDelegator(stmt.statement, source, fileName, tslibExports)
            is ThrowStatement -> stmt.expression?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
            else -> {}
        }
    }

    private fun checkExprForAsyncDelegator(
        expr: Expression,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        when (expr) {
            is YieldExpression -> {
                if (expr.asteriskToken) {
                    // yield* expr → needs __asyncDelegator and __asyncValues
                    val yieldPos = expr.pos
                    val yieldLen = "yield".length  // just "yield" keyword span (5 chars)
                    if ("__asyncDelegator" !in tslibExports) {
                        emitTS2343("__asyncDelegator", yieldPos, yieldLen, source, fileName)
                    }
                    if ("__asyncValues" !in tslibExports) {
                        emitTS2343("__asyncValues", yieldPos, yieldLen, source, fileName)
                    }
                }
                // round 42 iter13: recurse into yield's expression so `yield*` nested
                // inside another expression context still fires.
                expr.expression?.let { checkExprForAsyncDelegator(it, source, fileName, tslibExports) }
            }
            // round 42 iter13: broader expression coverage so yield* inside conditional /
            // wrapper / binary contexts is reached.
            is ParenthesizedExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is AsExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is TypeAssertionExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is SatisfiesExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is NonNullExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                checkExprForAsyncDelegator(cur, source, fileName, tslibExports)
                while (rightStack.isNotEmpty()) checkExprForAsyncDelegator(rightStack.removeLast(), source, fileName, tslibExports)
            }
            is ConditionalExpression -> {
                checkExprForAsyncDelegator(expr.condition, source, fileName, tslibExports)
                checkExprForAsyncDelegator(expr.whenTrue, source, fileName, tslibExports)
                checkExprForAsyncDelegator(expr.whenFalse, source, fileName, tslibExports)
            }
            is CallExpression -> {
                checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
                for (a in expr.arguments) checkExprForAsyncDelegator(a, source, fileName, tslibExports)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkExprForAsyncDelegator(e, source, fileName, tslibExports)
            is SpreadElement -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is AwaitExpression -> checkExprForAsyncDelegator(expr.expression, source, fileName, tslibExports)
            is CommaListExpression -> for (e in expr.elements) checkExprForAsyncDelegator(e, source, fileName, tslibExports)
            else -> {}
        }
    }

    /** Check class members for private field access helpers. */
    private fun checkClassMembersForPrivateFields(
        members: List<ClassElement>,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        for (member in members) {
            val body = when (member) {
                is MethodDeclaration -> member.body
                is GetAccessor -> member.body
                is SetAccessor -> member.body
                is Constructor -> member.body
                else -> null
            }
            body?.let { checkBlockForPrivateFieldAccess(it, source, fileName, tslibExports) }
        }
    }

    private fun checkBlockForPrivateFieldAccess(
        block: Block,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        for (stmt in block.statements) {
            checkStmtForPrivateFieldAccess(stmt, source, fileName, tslibExports)
        }
    }

    private fun checkStmtForPrivateFieldAccess(
        stmt: Statement,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, isAssignmentLhs = false)
            is ReturnStatement -> stmt.expression?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
                }
            }
            is IfStatement -> {
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
                checkStmtForPrivateFieldAccess(stmt.thenStatement, source, fileName, tslibExports)
                stmt.elseStatement?.let { checkStmtForPrivateFieldAccess(it, source, fileName, tslibExports) }
            }
            is Block -> checkBlockForPrivateFieldAccess(stmt, source, fileName, tslibExports)
            // round 42 iter6: broaden statement coverage so private-field access
            // (#field) inside For/ForIn/ForOf/While/Do/Switch/Try/Labeled/Throw/
            // ExportAssignment also triggers TS2343 when tslib helpers are missing.
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> for (d in init.declarations) {
                        d.initializer?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
                    }
                    is Expression -> checkExprForPrivateFieldAccess(init, source, fileName, tslibExports, false)
                    else -> {}
                }
                stmt.condition?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
                stmt.incrementor?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
                checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
            }
            is ForInStatement -> {
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
                checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
            }
            is ForOfStatement -> {
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
                checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
            }
            is WhileStatement -> {
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
                checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
            }
            is DoStatement -> {
                checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
            }
            is SwitchStatement -> {
                checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> {
                            checkExprForPrivateFieldAccess(clause.expression, source, fileName, tslibExports, false)
                            clause.statements
                        }
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    for (s in clauseStmts) checkStmtForPrivateFieldAccess(s, source, fileName, tslibExports)
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkStmtForPrivateFieldAccess(s, source, fileName, tslibExports)
                stmt.catchClause?.block?.let { for (s in it.statements) checkStmtForPrivateFieldAccess(s, source, fileName, tslibExports) }
                stmt.finallyBlock?.let { for (s in it.statements) checkStmtForPrivateFieldAccess(s, source, fileName, tslibExports) }
            }
            is LabeledStatement -> checkStmtForPrivateFieldAccess(stmt.statement, source, fileName, tslibExports)
            is ThrowStatement -> stmt.expression?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            is ExportAssignment -> checkExprForPrivateFieldAccess(stmt.expression, source, fileName, tslibExports, false)
            else -> {}
        }
    }

    private fun checkExprForPrivateFieldAccess(
        expr: Expression,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
        isAssignmentLhs: Boolean,
    ) {
        when (expr) {
            is BinaryExpression -> {
                val isAssignment = expr.operator == SyntaxKind.Equals ||
                    expr.operator == SyntaxKind.PlusEquals ||
                    expr.operator == SyntaxKind.MinusEquals ||
                    expr.operator == SyntaxKind.AsteriskEquals ||
                    expr.operator == SyntaxKind.SlashEquals
                if (expr.operator == SyntaxKind.InKeyword) {
                    // #field in obj → __classPrivateFieldIn
                    val lhs = expr.left
                    if (lhs is Identifier && lhs.text.startsWith('#')) {
                        if ("__classPrivateFieldIn" !in tslibExports) {
                            emitTS2343("__classPrivateFieldIn", lhs.pos, lhs.text.length, source, fileName)
                        }
                    }
                    checkExprForPrivateFieldAccess(expr.right, source, fileName, tslibExports, false)
                } else {
                    checkExprForPrivateFieldAccess(expr.left, source, fileName, tslibExports, isAssignment)
                    checkExprForPrivateFieldAccess(expr.right, source, fileName, tslibExports, false)
                }
            }
            is PropertyAccessExpression -> {
                val name = expr.name
                if (name.text.startsWith('#')) {
                    // this.#field — detect Set (assignment LHS) vs Get (read)
                    val spanStart = expr.pos
                    // span = "this.#field" = expr.pos to name.pos + name.text.length
                    val spanEnd = name.pos + name.text.length
                    val spanLen = spanEnd - spanStart
                    if (isAssignmentLhs) {
                        if ("__classPrivateFieldSet" !in tslibExports) {
                            emitTS2343("__classPrivateFieldSet", spanStart, spanLen.coerceAtLeast(1), source, fileName)
                        }
                    } else {
                        if ("__classPrivateFieldGet" !in tslibExports) {
                            emitTS2343("__classPrivateFieldGet", spanStart, spanLen.coerceAtLeast(1), source, fileName)
                        }
                    }
                } else {
                    checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
                }
            }
            // Value-preserving wrappers — `(expr)` propagates isAssignmentLhs; `expr!`,
            // `expr as T`, `<T>expr`, `expr satisfies T` are still valid assignment
            // targets and preserve the LHS context for private-field set detection.
            is ParenthesizedExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, isAssignmentLhs)
            is NonNullExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, isAssignmentLhs)
            is AsExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, isAssignmentLhs)
            is TypeAssertionExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, isAssignmentLhs)
            is SatisfiesExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, isAssignmentLhs)
            is CallExpression -> {
                checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
                expr.arguments.forEach { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            }
            is NewExpression -> {
                checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
                expr.arguments?.forEach { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            }
            is ElementAccessExpression -> {
                checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
                checkExprForPrivateFieldAccess(expr.argumentExpression, source, fileName, tslibExports, false)
            }
            is PrefixUnaryExpression -> {
                // ++this.#x / --this.#x → Set (private field assignment)
                val isAssignOp = expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus
                checkExprForPrivateFieldAccess(expr.operand, source, fileName, tslibExports, isAssignOp)
            }
            is PostfixUnaryExpression -> {
                val isAssignOp = expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus
                checkExprForPrivateFieldAccess(expr.operand, source, fileName, tslibExports, isAssignOp)
            }
            is ConditionalExpression -> {
                checkExprForPrivateFieldAccess(expr.condition, source, fileName, tslibExports, false)
                checkExprForPrivateFieldAccess(expr.whenTrue, source, fileName, tslibExports, false)
                checkExprForPrivateFieldAccess(expr.whenFalse, source, fileName, tslibExports, false)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> checkExprForPrivateFieldAccess(prop.initializer, source, fileName, tslibExports, false)
                is SpreadAssignment -> checkExprForPrivateFieldAccess(prop.expression, source, fileName, tslibExports, false)
                else -> {}
            }
            is SpreadElement -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
            is AwaitExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
            is YieldExpression -> expr.expression?.let { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            is DeleteExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
            is VoidExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
            is TypeOfExpression -> checkExprForPrivateFieldAccess(expr.expression, source, fileName, tslibExports, false)
            is TemplateExpression -> expr.templateSpans.forEach { checkExprForPrivateFieldAccess(it.expression, source, fileName, tslibExports, false) }
            // round 42 iter7: TaggedTemplateExpression — recurse into tag + template spans
            // so `tag`...${this.#x}...`` triggers TS2343 on the private-field access.
            is TaggedTemplateExpression -> {
                checkExprForPrivateFieldAccess(expr.tag, source, fileName, tslibExports, false)
                val template = expr.template
                if (template is TemplateExpression) {
                    template.templateSpans.forEach { checkExprForPrivateFieldAccess(it.expression, source, fileName, tslibExports, false) }
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkExprForPrivateFieldAccess(it, source, fileName, tslibExports, false) }
            else -> {}
        }
    }

    private fun checkParameterDecoratorsForHelper(
        members: List<ClassElement>,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
        hasDecorators: Boolean,
    ) {
        if (!hasDecorators) return
        for (member in members) {
            val params = when (member) {
                is MethodDeclaration -> member.parameters
                is Constructor -> member.parameters
                else -> continue
            }
            for (param in params) {
                val decs = param.decorators ?: continue
                if (decs.isEmpty()) continue
                val decorator = decs.first()
                val decoratorSpan = getDecoratorSpan(decorator, source)
                if ("__param" !in tslibExports) {
                    emitTS2343("__param", decoratorSpan.first, decoratorSpan.second, source, fileName)
                }
            }
        }
    }

    private fun checkExprForMissingHelper(
        expr: Expression?,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
        isEs5Target: Boolean,
    ) {
        if (expr == null) return
        when (expr) {
            is TaggedTemplateExpression -> {
                // id`template` → needs __makeTemplateObject (ES5 only)
                if (isEs5Target && "__makeTemplateObject" !in tslibExports) {
                    val tagStart = expr.tag.pos
                    val template = expr.template
                    val templateEnd = when (template) {
                        is NoSubstitutionTemplateLiteralNode -> template.pos + template.text.length + 2
                        else -> template.end // fallback
                    }
                    val spanLen = templateEnd - tagStart
                    emitTS2343("__makeTemplateObject", tagStart, spanLen.coerceAtLeast(1), source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is SpreadAssignment -> {
                            // { ...o } → needs __assign (ES5 only)
                            if (isEs5Target && "__assign" !in tslibExports) {
                                // Span: position of "..." + name
                                val spreadPos = prop.pos
                                val spreadExpr = prop.expression
                                val endPos = if (spreadExpr is Identifier) {
                                    spreadExpr.pos + spreadExpr.text.length
                                } else {
                                    spreadExpr.pos + 1
                                }
                                val spanLen = endPos - spreadPos
                                emitTS2343("__assign", spreadPos, spanLen.coerceAtLeast(1), source, fileName)
                            }
                        }
                        // round 42 iter17: recurse into PropertyAssignment values so nested
                        // ObjectLiteral with `...` spread inside `{ a: { ...o } }` is reached.
                        is PropertyAssignment -> checkExprForMissingHelper(prop.initializer, source, fileName, tslibExports, isEs5Target)
                        else -> {}
                    }
                }
            }
            // round 42 iter17: wrapper unwrap so `({...o})` / `(...) as T` etc. still
            // trigger the TaggedTemplate / SpreadAssignment helper detection.
            is ParenthesizedExpression -> checkExprForMissingHelper(expr.expression, source, fileName, tslibExports, isEs5Target)
            is AsExpression -> checkExprForMissingHelper(expr.expression, source, fileName, tslibExports, isEs5Target)
            is TypeAssertionExpression -> checkExprForMissingHelper(expr.expression, source, fileName, tslibExports, isEs5Target)
            is SatisfiesExpression -> checkExprForMissingHelper(expr.expression, source, fileName, tslibExports, isEs5Target)
            is NonNullExpression -> checkExprForMissingHelper(expr.expression, source, fileName, tslibExports, isEs5Target)
            else -> {}
        }
    }

    private fun checkBindingForMissingHelper(
        binding: Expression,
        source: String,
        fileName: String,
        tslibExports: Set<String>,
    ) {
        when (binding) {
            is ObjectBindingPattern -> {
                for (element in binding.elements) {
                    if (element is BindingElement && element.dotDotDotToken) {
                        // { ...x } → needs __rest
                        if ("__rest" !in tslibExports) {
                            // Span: position of the identifier 'x' (1 char for simple names)
                            val nameNode = element.name
                            val nameStart = nameNode.pos
                            val nameLen = (nameNode as? Identifier)?.text?.length ?: 1
                            emitTS2343("__rest", nameStart, nameLen, source, fileName)
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /** Returns the span (start, length) of a decorator including the `@` sign. */
    private fun getDecoratorSpan(decorator: Decorator, source: String): Pair<Int, Int> {
        val start = decorator.pos
        val expr = decorator.expression
        val endPos = when (expr) {
            is Identifier -> expr.pos + expr.text.length
            is CallExpression -> {
                // Find closing paren
                source.indexOf(')', expr.pos).let { if (it >= 0) it + 1 else expr.pos + 1 }
            }
            else -> start + 4 // fallback: @dec = 4 chars
        }
        // Include the "@" sign in the span
        val spanLen = endPos - start
        return Pair(start, spanLen.coerceAtLeast(1))
    }

    /** Returns the set of exported names from a tslib source file. */
    private fun getTslibExports(file: SourceFile): Set<String> {
        val exports = mutableSetOf<String>()
        for (stmt in file.statements) {
            when (stmt) {
                is ExportDeclaration -> {
                    val clause = stmt.exportClause
                    if (clause is NamedExports) {
                        for (spec in clause.elements) {
                            exports.add(spec.name.text)
                        }
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Export in stmt.modifiers) stmt.name?.let { exports.add(it.text) }
                }
                is VariableStatement -> {
                    if (ModifierFlag.Export in stmt.modifiers) {
                        for (decl in stmt.declarationList.declarations) {
                            val n = decl.name
                            if (n is Identifier) exports.add(n.text)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    // declare module "tslib" { ... }
                    val name = stmt.name
                    if (name is StringLiteralNode && name.text == "tslib") {
                        val body = stmt.body
                        if (body is ModuleBlock) {
                            for (inner in body.statements) {
                                when (inner) {
                                    is FunctionDeclaration -> {
                                        if (ModifierFlag.Export in inner.modifiers || ModifierFlag.Declare in inner.modifiers) {
                                            inner.name?.let { exports.add(it.text) }
                                        }
                                    }
                                    is VariableStatement -> {
                                        for (decl in inner.declarationList.declarations) {
                                            val n = decl.name
                                            if (n is Identifier) exports.add(n.text)
                                        }
                                    }
                                    else -> {}
                                }
                            }
                        }
                    }
                }
                else -> {}
            }
        }
        return exports
    }

    private fun emitTS2343(helperName: String, spanStart: Int, spanLen: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
        diagnostics.add(Diagnostic(
            message = "This syntax requires an imported helper named '$helperName' which does not exist in 'tslib'. Consider upgrading your version of 'tslib'.",
            category = DiagnosticCategory.Error,
            code = 2343,
            fileName = fileName,
            line = line,
            character = character,
            start = spanStart,
            length = spanLen,
        ))
    }

    // -----------------------------------------------------------------------
    // TS7028: Unused label
    // -----------------------------------------------------------------------

    private fun checkUnusedLabels() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForUnusedLabels(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForUnusedLabels(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForUnusedLabels(stmt, source, fileName)
    }

    private fun walkStmtForUnusedLabels(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is LabeledStatement -> {
                val labelName = stmt.label.text
                // Check if this label is used by any break/continue within the labeled statement
                if (!isLabelUsed(labelName, stmt.statement)) {
                    val start = stmt.label.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Unused label.",
                        category = DiagnosticCategory.Error,
                        code = 7028,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = labelName.length,
                    ))
                }
                // Recurse into the labeled statement
                walkStmtForUnusedLabels(stmt.statement, source, fileName)
            }
            is Block -> walkForUnusedLabels(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForUnusedLabels(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForUnusedLabels(it, source, fileName) }
            }
            is ForStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForUnusedLabels(clause.statements, source, fileName)
                        is DefaultClause -> walkForUnusedLabels(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForUnusedLabels(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForUnusedLabels(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForUnusedLabels(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> {
                // New label scope inside function body
                stmt.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is PropertyDeclaration -> m.initializer?.let { walkExprForUnusedLabels(it, source, fileName) }
                        is ClassStaticBlockDeclaration -> walkForUnusedLabels(m.body.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForUnusedLabels(it.statements, source, fileName) }
            is ExpressionStatement -> walkExprForUnusedLabels(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForUnusedLabels(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForUnusedLabels(it, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { walkExprForUnusedLabels(it, source, fileName) }
            is ExportAssignment -> walkExprForUnusedLabels(stmt.expression, source, fileName)
            else -> {}
        }
    }

    private fun walkExprForUnusedLabels(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> expr.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForUnusedLabels(body.statements, source, fileName)
                else if (body is Expression) walkExprForUnusedLabels(body, source, fileName)
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is AsExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is SatisfiesExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is NonNullExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is CallExpression -> {
                walkExprForUnusedLabels(expr.expression, source, fileName)
                expr.arguments.forEach { walkExprForUnusedLabels(it, source, fileName) }
            }
            is NewExpression -> {
                walkExprForUnusedLabels(expr.expression, source, fileName)
                expr.arguments?.forEach { walkExprForUnusedLabels(it, source, fileName) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkExprForUnusedLabels(current.right, source, fileName)
                    current = current.left
                }
                walkExprForUnusedLabels(current, source, fileName)
            }
            is ConditionalExpression -> {
                walkExprForUnusedLabels(expr.condition, source, fileName)
                walkExprForUnusedLabels(expr.whenTrue, source, fileName)
                walkExprForUnusedLabels(expr.whenFalse, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForUnusedLabels(it, source, fileName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkExprForUnusedLabels(prop.initializer, source, fileName)
                is SpreadAssignment -> walkExprForUnusedLabels(prop.expression, source, fileName)
                is MethodDeclaration -> prop.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                else -> {}
            }
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForUnusedLabels(it.expression, source, fileName) }
            is SpreadElement -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is PropertyAccessExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkExprForUnusedLabels(expr.expression, source, fileName)
                walkExprForUnusedLabels(expr.argumentExpression, source, fileName)
            }
            is PrefixUnaryExpression -> walkExprForUnusedLabels(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkExprForUnusedLabels(expr.operand, source, fileName)
            is AwaitExpression -> walkExprForUnusedLabels(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkExprForUnusedLabels(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Returns true if a break or continue referencing [labelName] exists in [stmt].
     * Does NOT recurse into nested function boundaries (those create new label scopes).
     */
    private fun isLabelUsed(labelName: String, stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> stmt.label?.text == labelName
            is ContinueStatement -> stmt.label?.text == labelName
            is Block -> stmt.statements.any { isLabelUsed(labelName, it) }
            is IfStatement -> isLabelUsed(labelName, stmt.thenStatement) ||
                (stmt.elseStatement?.let { isLabelUsed(labelName, it) } ?: false)
            is LabeledStatement -> isLabelUsed(labelName, stmt.statement)
            is ForStatement -> isLabelUsed(labelName, stmt.statement)
            is ForInStatement -> isLabelUsed(labelName, stmt.statement)
            is ForOfStatement -> isLabelUsed(labelName, stmt.statement)
            is WhileStatement -> isLabelUsed(labelName, stmt.statement)
            is DoStatement -> isLabelUsed(labelName, stmt.statement)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> clause.statements.any { isLabelUsed(labelName, it) }
                    is DefaultClause -> clause.statements.any { isLabelUsed(labelName, it) }
                    else -> false
                }
            }
            is TryStatement -> stmt.tryBlock.statements.any { isLabelUsed(labelName, it) } ||
                (stmt.catchClause?.block?.statements?.any { isLabelUsed(labelName, it) } ?: false) ||
                (stmt.finallyBlock?.statements?.any { isLabelUsed(labelName, it) } ?: false)
            // Do NOT recurse into function declarations/expressions — new label scope
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // TS7029: Fallthrough case in switch
    // -----------------------------------------------------------------------

    private fun checkFallthroughCases() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForFallthroughCases(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForFallthroughCases(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForFallthroughCases(stmt, source, fileName)
    }

    private fun walkStmtForFallthroughCases(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is SwitchStatement -> {
                checkSwitchForFallthrough(stmt, source, fileName)
                // Recurse into case clause bodies too
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForFallthroughCases(clause.statements, source, fileName)
                        is DefaultClause -> walkForFallthroughCases(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is Block -> walkForFallthroughCases(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForFallthroughCases(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForFallthroughCases(it, source, fileName) }
            }
            is LabeledStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is TryStatement -> {
                walkForFallthroughCases(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForFallthroughCases(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForFallthroughCases(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> stmt.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> walkExprForFallthroughCases(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForFallthroughCases(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForFallthroughCases(it, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { walkExprForFallthroughCases(it, source, fileName) }
            is ExportAssignment -> stmt.expression?.let { walkExprForFallthroughCases(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForFallthroughCases(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun walkExprForFallthroughCases(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> expr.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForFallthroughCases(body.statements, source, fileName)
                else if (body is Expression) walkExprForFallthroughCases(body, source, fileName)
            }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is Constructor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is GetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { walkExprForFallthroughCases(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is AsExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is SatisfiesExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is NonNullExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is CallExpression -> {
                walkExprForFallthroughCases(expr.expression, source, fileName)
                expr.arguments.forEach { walkExprForFallthroughCases(it, source, fileName) }
            }
            is NewExpression -> {
                walkExprForFallthroughCases(expr.expression, source, fileName)
                expr.arguments?.forEach { walkExprForFallthroughCases(it, source, fileName) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkExprForFallthroughCases(current.right, source, fileName)
                    current = current.left
                }
                walkExprForFallthroughCases(current, source, fileName)
            }
            is ConditionalExpression -> {
                walkExprForFallthroughCases(expr.condition, source, fileName)
                walkExprForFallthroughCases(expr.whenTrue, source, fileName)
                walkExprForFallthroughCases(expr.whenFalse, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForFallthroughCases(it, source, fileName) }
            is ObjectLiteralExpression -> for (prop in expr.properties) when (prop) {
                is PropertyAssignment -> walkExprForFallthroughCases(prop.initializer, source, fileName)
                is SpreadAssignment -> walkExprForFallthroughCases(prop.expression, source, fileName)
                is MethodDeclaration -> prop.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is GetAccessor -> prop.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                is SetAccessor -> prop.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                else -> {}
            }
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForFallthroughCases(it.expression, source, fileName) }
            is TaggedTemplateExpression -> {
                walkExprForFallthroughCases(expr.tag, source, fileName)
                val t = expr.template
                if (t is TemplateExpression) {
                    for (span in t.templateSpans) walkExprForFallthroughCases(span.expression, source, fileName)
                }
            }
            is SpreadElement -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is PropertyAccessExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkExprForFallthroughCases(expr.expression, source, fileName)
                walkExprForFallthroughCases(expr.argumentExpression, source, fileName)
            }
            is PrefixUnaryExpression -> walkExprForFallthroughCases(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkExprForFallthroughCases(expr.operand, source, fileName)
            is AwaitExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkExprForFallthroughCases(it, source, fileName) }
            is VoidExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is DeleteExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is TypeOfExpression -> walkExprForFallthroughCases(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { walkExprForFallthroughCases(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Check a switch statement for fallthrough cases (TS7029).
     * A case clause falls through if it has statements but doesn't end with a terminating statement.
     * Empty case clauses (no statements) are allowed to fall through.
     * TypeScript reports TS7029 on the CURRENT case clause that falls through (not the next one).
     */
    private fun checkSwitchForFallthrough(stmt: SwitchStatement, source: String, fileName: String) {
        val clauses = stmt.caseBlock
        for (i in clauses.indices) {
            val clause = clauses[i]
            val clauseStmts = when (clause) {
                is CaseClause -> clause.statements
                is DefaultClause -> clause.statements
                else -> continue
            }
            // Only check non-last clauses — last clause doesn't fall through anywhere
            if (i == clauses.size - 1) continue
            // Empty clauses (no statements) are allowed to fall through
            if (clauseStmts.isEmpty()) continue
            // Check if the clause definitely terminates
            if (!clauseStmtsTerminate(clauseStmts)) {
                // Report on the CURRENT clause's case/default keyword
                val clauseStart = when (clause) {
                    is CaseClause -> clause.pos
                    is DefaultClause -> clause.pos
                    else -> continue
                }
                val (line, character) = getLineAndCharacterOfPosition(source, clauseStart)
                // Span covers "case X:" or "default:" header
                val colonIdx = source.indexOf(':', clauseStart)
                val spanEnd = if (colonIdx >= 0) colonIdx + 1 else clauseStart + 4
                val spanLen = spanEnd - clauseStart
                diagnostics.add(Diagnostic(
                    message = "Fallthrough case in switch.",
                    category = DiagnosticCategory.Error,
                    code = 7029,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = clauseStart,
                    length = spanLen,
                ))
            }
        }
    }

    /**
     * Returns true if a list of statements definitely terminates on ALL code paths.
     */
    private fun clauseStmtsTerminate(stmts: List<Statement>): Boolean {
        // A clause terminates if any statement in it definitely terminates on all paths
        return stmts.any { isDefinitelyTerminating(it) }
    }

    // -----------------------------------------------------------------------
    // TS7030: Not all code paths return a value / TS2355
    // -----------------------------------------------------------------------

    private fun checkImplicitReturns() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — return type checks (TS2355/TS7030/TS2366) don't apply
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            walkForImplicitReturns(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkTypePredicateNullableRecovery() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkTPNRStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkTPNRStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkTPNRStmt(stmt, source, fileName)
    }

    private fun walkTPNRStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkTPNRForCallable(stmt.parameters, stmt.type, source, fileName)
                stmt.body?.let { walkTPNRStmts(it.statements, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> {
                    checkTPNRForCallable(m.parameters, m.type, source, fileName)
                    m.body?.let { walkTPNRStmts(it.statements, source, fileName) }
                }
                is Constructor -> m.body?.let { walkTPNRStmts(it.statements, source, fileName) }
                is GetAccessor -> {
                    checkTPNRForCallable(emptyList(), m.type, source, fileName)
                    m.body?.let { walkTPNRStmts(it.statements, source, fileName) }
                }
                is SetAccessor -> m.body?.let { walkTPNRStmts(it.statements, source, fileName) }
                else -> {}
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkTPNRStmts(it.statements, source, fileName) }
            is Block -> walkTPNRStmts(stmt.statements, source, fileName)
            is IfStatement -> {
                walkTPNRStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkTPNRStmt(it, source, fileName) }
            }
            is LabeledStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is ForStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is ForInStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is ForOfStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is WhileStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is DoStatement -> walkTPNRStmt(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> walkTPNRStmts(c.statements, source, fileName)
                    is DefaultClause -> walkTPNRStmts(c.statements, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                walkTPNRStmts(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkTPNRStmts(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkTPNRStmts(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkTPNRForCallable(
        parameters: List<Parameter>,
        returnType: TypeNode?,
        source: String,
        fileName: String
    ) {
        val predicate = returnType as? TypePredicate ?: return
        val predType = predicate.type ?: return
        val paramName = (predicate.parameterName as? Identifier)?.text
            ?: (predicate.parameterName as? TypeReference)?.let { (it.typeName as? Identifier)?.text }
            ?: return
        // Look for `?` between the `is` keyword and predType.pos — indicates `?T` recovery.
        val gapStart = (predicate.parameterName as? Identifier)?.end
            ?: (predicate.parameterName as? TypeReference)?.end
            ?: return
        val gapEnd = predType.pos
        if (gapStart < 0 || gapEnd <= gapStart || gapEnd > source.length) return
        val gap = source.substring(gapStart, gapEnd)
        val qOffset = gap.indexOf('?')
        if (qOffset < 0) return
        val qAbs = gapStart + qOffset
        // Find param by name to get its declared type.
        val param = parameters.firstOrNull { (it.name as? Identifier)?.text == paramName } ?: return
        val paramTypeNode = param.type ?: return
        val paramTypeStr = formatTypeForDisplay(paramTypeNode) ?: return
        val predTypeStr = formatTypeForDisplay(predType) ?: return
        // Conservative gate: only emit when param type doesn't already permit null
        // (i.e., paramTypeStr doesn't contain "null"). Avoids spurious errors on
        // `a: T | null` + `a is ?T` cases (where the predicate is still valid).
        if (paramTypeStr.contains("null")) return
        val nullableSrc = "$predTypeStr | null"
        val (line, character) = getLineAndCharacterOfPosition(source, qAbs)
        // Length spans `?<typeText>` — predType.end overshoots (it's set after the
        // scanner advanced past the next token), so derive from display text length.
        val length = (predType.pos - qAbs) + predTypeStr.length
        diagnostics.add(Diagnostic(
            message = "A type predicate's type must be assignable to its parameter's type.",
            category = DiagnosticCategory.Error,
            code = 2677,
            fileName = fileName,
            line = line,
            character = character,
            start = qAbs,
            length = length,
            messageChain = listOf(
                "  Type '$nullableSrc' is not assignable to type '$paramTypeStr'.",
                "    Type 'null' is not assignable to type '$paramTypeStr'.",
            ),
        ))
    }

    private fun walkForImplicitReturns(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForImplicitReturns(stmt, source, fileName)
    }

    private fun walkStmtForImplicitReturns(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> checkFunctionForImplicitReturn(stmt, source, fileName)
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> checkMethodForImplicitReturn(m, source, fileName)
                        is Constructor -> {} // constructors don't need return value checks
                        is GetAccessor -> checkGetAccessorForImplicitReturn(m, source, fileName)
                        is SetAccessor -> {} // setters don't return
                        else -> {}
                    }
                }
            }
            is Block -> walkForImplicitReturns(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForImplicitReturns(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForImplicitReturns(it, source, fileName) }
            }
            is LabeledStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForImplicitReturns(clause.statements, source, fileName)
                        is DefaultClause -> walkForImplicitReturns(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForImplicitReturns(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForImplicitReturns(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForImplicitReturns(it.statements, source, fileName) }
            }
            is ExpressionStatement -> walkExprForImplicitReturns(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForImplicitReturns(it, source, fileName) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForImplicitReturns(body.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun walkExprForImplicitReturns(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> {
                checkFuncExprForImplicitReturn(expr, source, fileName)
            }
            is ArrowFunction -> {
                checkArrowForImplicitReturn(expr, source, fileName)
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> checkMethodForImplicitReturn(m, source, fileName)
                        is GetAccessor -> checkGetAccessorForImplicitReturn(m, source, fileName)
                        is PropertyDeclaration -> m.initializer?.let { walkExprForImplicitReturns(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is GetAccessor -> checkGetAccessorForImplicitReturn(prop, source, fileName)
                        is MethodDeclaration -> checkMethodForImplicitReturn(prop, source, fileName)
                        is FunctionExpression -> checkFuncExprForImplicitReturn(prop, source, fileName)
                        is PropertyAssignment -> walkExprForImplicitReturns(prop.initializer, source, fileName)
                        is SpreadAssignment -> walkExprForImplicitReturns(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            // 16.0: Recurse into nested expressions to visit arrows in call args, etc.
            is CallExpression -> {
                walkExprForImplicitReturns(expr.expression, source, fileName)
                for (arg in expr.arguments) walkExprForImplicitReturns(arg, source, fileName)
            }
            is NewExpression -> {
                walkExprForImplicitReturns(expr.expression, source, fileName)
                expr.arguments?.forEach { walkExprForImplicitReturns(it, source, fileName) }
            }
            is ParenthesizedExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkExprForImplicitReturns(cur, source, fileName)
                while (rightStack.isNotEmpty()) walkExprForImplicitReturns(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                walkExprForImplicitReturns(expr.condition, source, fileName)
                walkExprForImplicitReturns(expr.whenTrue, source, fileName)
                walkExprForImplicitReturns(expr.whenFalse, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForImplicitReturns(it, source, fileName) }
            is SpreadElement -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is AsExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is NonNullExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is SatisfiesExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is PropertyAccessExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                walkExprForImplicitReturns(expr.expression, source, fileName)
                walkExprForImplicitReturns(expr.argumentExpression, source, fileName)
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                walkExprForImplicitReturns(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                walkExprForImplicitReturns(expr.tag, source, fileName)
                val t = expr.template
                if (t is TemplateExpression) {
                    for (span in t.templateSpans) walkExprForImplicitReturns(span.expression, source, fileName)
                }
            }
            is PrefixUnaryExpression -> walkExprForImplicitReturns(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkExprForImplicitReturns(expr.operand, source, fileName)
            is AwaitExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkExprForImplicitReturns(it, source, fileName) }
            is VoidExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is DeleteExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is TypeOfExpression -> walkExprForImplicitReturns(expr.expression, source, fileName)
            is CommaListExpression -> for (e in expr.elements) walkExprForImplicitReturns(e, source, fileName)
            else -> {}
        }
    }

    /**
     * Get the return type annotation node position/length for a function, for TS7030 diagnostic span.
     */
    private fun checkFunctionForImplicitReturn(decl: FunctionDeclaration, source: String, fileName: String) {
        val body = decl.body ?: return
        if (decl.asteriskToken) return // generators always return an iterator — no implicit-return check
        val retType = decl.type
        val isAsync = ModifierFlag.Async in decl.modifiers
        // Set current function params for exhaustive switch detection
        val savedParams = currentFunctionParams
        currentFunctionParams = decl.parameters
        try {
            checkBodyForImplicitReturn(body, retType, isAsync, decl.name?.let { FuncRef(it.pos, it.text.length) }, source, fileName)
        } finally {
            currentFunctionParams = savedParams
        }
        // TS7023: indirect self-reference in return expressions of an un-annotated function.
        if (retType == null && !isAsync) {
            val name = decl.name
            if (name is Identifier) {
                checkIndirectSelfReferenceReturn(name.text, name.pos, name.text.length, body.statements, source, fileName)
            }
        }
        // Recurse into body for nested functions
        walkForImplicitReturns(body.statements, source, fileName)
    }

    /**
     * TS7023: "'X' implicitly has return type 'any' because it does not have a return type
     * annotation and is referenced directly or indirectly in one of its return expressions."
     *
     * Narrow rule: emit when every `return expr;` in the body references the function's own
     * name AND at least one reference is in a non-direct-call position (i.e. the expression is
     * NOT just `self(...)` or `self` at the top level of the return expression).
     *
     * Rationale: direct self-recursion (`return self(...)`) is typed as `never` by TS and does
     * not trigger TS7023. Indirect references (e.g. `return [self][0]();`, `return self;`,
     * `return {x: self};`) cause TS's inference to get stuck → TS7023.
     *
     * Does NOT recurse into nested function/arrow/class bodies when collecting returns or
     * checking self-references.
     */
    private fun checkIndirectSelfReferenceReturn(
        name: String,
        namePos: Int,
        nameLength: Int,
        stmts: List<Statement>,
        source: String,
        fileName: String,
    ) {
        val returns = mutableListOf<Expression?>()
        collectReturnExpressions(stmts, returns)
        if (returns.isEmpty()) return
        var allHaveSelfRef = true
        var anyIndirect = false
        for (expr in returns) {
            if (expr == null) {
                allHaveSelfRef = false
                break
            }
            if (!exprContainsIdentifier(expr, name)) {
                allHaveSelfRef = false
                break
            }
            if (!isDirectSelfCall(expr, name) && !isDirectSelfRef(expr, name)) {
                anyIndirect = true
            }
        }
        if (!allHaveSelfRef || !anyIndirect) return
        val (line, character) = getLineAndCharacterOfPosition(source, namePos)
        diagnostics.add(Diagnostic(
            message = "'$name' implicitly has return type 'any' because it does not have a return type annotation and is referenced directly or indirectly in one of its return expressions.",
            category = DiagnosticCategory.Error,
            code = 7023,
            fileName = fileName,
            line = line,
            character = character,
            start = namePos,
            length = nameLength,
        ))
    }

    private fun collectReturnExpressions(stmts: List<Statement>, out: MutableList<Expression?>) {
        for (stmt in stmts) collectReturnExpressionsFromStmt(stmt, out)
    }

    private fun collectReturnExpressionsFromStmt(stmt: Statement, out: MutableList<Expression?>) {
        when (stmt) {
            is ReturnStatement -> out.add(stmt.expression)
            is Block -> collectReturnExpressions(stmt.statements, out)
            is IfStatement -> {
                collectReturnExpressionsFromStmt(stmt.thenStatement, out)
                stmt.elseStatement?.let { collectReturnExpressionsFromStmt(it, out) }
            }
            is WhileStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is DoStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is ForStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is ForInStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is ForOfStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is LabeledStatement -> collectReturnExpressionsFromStmt(stmt.statement, out)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> collectReturnExpressions(clause.statements, out)
                        is DefaultClause -> collectReturnExpressions(clause.statements, out)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                collectReturnExpressions(stmt.tryBlock.statements, out)
                stmt.catchClause?.let { collectReturnExpressions(it.block.statements, out) }
                stmt.finallyBlock?.let { collectReturnExpressions(it.statements, out) }
            }
            else -> {} // do NOT recurse into nested FunctionDeclaration / ClassDeclaration / etc.
        }
    }

    /** Direct self-call: `self(...)` at the top level of the return expression. */
    private fun isDirectSelfCall(expr: Expression, name: String): Boolean {
        return expr is CallExpression && expr.expression is Identifier && (expr.expression as Identifier).text == name
    }

    /** Direct self-reference: `self` at the top level (no wrapping expressions). */
    private fun isDirectSelfRef(expr: Expression, name: String): Boolean {
        return expr is Identifier && expr.text == name
    }

    /**
     * True if [expr] contains an [Identifier] with [name] anywhere (excluding nested
     * function/arrow/class bodies, which define their own scope).
     */
    private fun exprContainsIdentifier(expr: Expression?, name: String): Boolean {
        if (expr == null) return false
        return when (expr) {
            is Identifier -> expr.text == name
            is CallExpression -> exprContainsIdentifier(expr.expression, name)
                || expr.arguments.any { exprContainsIdentifier(it, name) }
            is NewExpression -> exprContainsIdentifier(expr.expression, name)
                || (expr.arguments?.any { exprContainsIdentifier(it, name) } ?: false)
            is PropertyAccessExpression -> exprContainsIdentifier(expr.expression, name)
            is ElementAccessExpression -> exprContainsIdentifier(expr.expression, name)
                || exprContainsIdentifier(expr.argumentExpression, name)
            is ParenthesizedExpression -> exprContainsIdentifier(expr.expression, name)
            is BinaryExpression -> exprContainsIdentifier(expr.left, name)
                || exprContainsIdentifier(expr.right, name)
            is ConditionalExpression -> exprContainsIdentifier(expr.condition, name)
                || exprContainsIdentifier(expr.whenTrue, name)
                || exprContainsIdentifier(expr.whenFalse, name)
            is ArrayLiteralExpression -> expr.elements.any { exprContainsIdentifier(it, name) }
            is SpreadElement -> exprContainsIdentifier(expr.expression, name)
            is PrefixUnaryExpression -> exprContainsIdentifier(expr.operand, name)
            is PostfixUnaryExpression -> exprContainsIdentifier(expr.operand, name)
            is AsExpression -> exprContainsIdentifier(expr.expression, name)
            is TypeAssertionExpression -> exprContainsIdentifier(expr.expression, name)
            is NonNullExpression -> exprContainsIdentifier(expr.expression, name)
            is ObjectLiteralExpression -> expr.properties.any { prop ->
                when (prop) {
                    is PropertyAssignment -> exprContainsIdentifier(prop.initializer, name)
                    is ShorthandPropertyAssignment -> prop.name.text == name
                    is SpreadAssignment -> exprContainsIdentifier(prop.expression, name)
                    else -> false
                }
            }
            // Do NOT recurse into FunctionExpression/ArrowFunction/ClassExpression bodies —
            // those have their own scopes and any `self` reference inside is unrelated.
            else -> false
        }
    }

    private fun checkMethodForImplicitReturn(decl: MethodDeclaration, source: String, fileName: String) {
        val body = decl.body ?: return
        if (decl.asteriskToken) return // generators always return an iterator — no implicit-return check
        val retType = decl.type
        val isAsync = ModifierFlag.Async in decl.modifiers
        val nameNode = decl.name
        val nameRef = when (nameNode) {
            is Identifier -> FuncRef(nameNode.pos, nameNode.text.length)
            else -> null
        }
        val savedParams = currentFunctionParams
        currentFunctionParams = decl.parameters
        try {
            checkBodyForImplicitReturn(body, retType, isAsync, nameRef, source, fileName)
        } finally {
            currentFunctionParams = savedParams
        }
        walkForImplicitReturns(body.statements, source, fileName)
    }

    /**
     * Match `<expr> as T` where <expr> is an ObjectLiteralExpression containing
     * any PropertyAssignment whose value is bare `this` (Identifier "this").
     * Narrow trigger for TS7023 on getters returning self-referential object
     * literals.
     */
    private fun isAsExprWrappingObjLitWithThis(expr: Expression): Boolean {
        if (expr !is AsExpression) return false
        val obj = expr.expression as? ObjectLiteralExpression ?: return false
        return obj.properties.any { prop ->
            when (prop) {
                is PropertyAssignment -> {
                    val init = prop.initializer
                    init is Identifier && init.text == "this"
                }
                else -> false
            }
        }
    }

    private fun checkGetAccessorForImplicitReturn(decl: GetAccessor, source: String, fileName: String) {
        val body = decl.body ?: return
        // Skip error-recovery sentinel bodies (pos = -1, created when `{` was missing)
        if (body.pos == -1) return
        val retType = decl.type
        val nameNode = decl.name
        val nameRef = when (nameNode) {
            is Identifier -> FuncRef(nameNode.pos, nameNode.text.length)
            else -> null
        }
        // TS2378: A 'get' accessor must return a value.
        // Fires when getter body has no return statement and no throw statement.
        // Both `return;` and `throw X;` suppress this diagnostic.
        val hasAnyReturnOrThrow = bodyHasAnyReturn(body.statements) || bodyHasThrow(body.statements)
        if (!hasAnyReturnOrThrow && nameNode is Identifier) {
            val start = nameNode.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "A 'get' accessor must return a value.",
                category = DiagnosticCategory.Error,
                code = 2378,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = nameNode.text.length,
            ))
        }
        checkBodyForImplicitReturn(body, retType, false, nameRef, source, fileName)
        // TS7023 for getters without return type annotation whose body returns an
        // expression containing `this` inside an object literal or array literal.
        // Inferred return type would cycle: `get foo() { return { x: this }; }` in
        // class C → inferred type `{ x: C }` references C which has `foo` → cycle.
        // Narrow gate: return is `as <Type>` AsExpression wrapping ObjectLiteral with
        // any property value being a bare `this` keyword Identifier. Matches the
        // exact `trivialSubtypeReductionNoStructuralCheck_ts` shape; avoids FP on
        // simple `return this`/`return this.field` (no cycle) and `return undefined`.
        if (retType == null && nameNode is Identifier) {
            val returnExprs = mutableListOf<Expression?>()
            collectReturnExpressions(body.statements, returnExprs)
            val cycleViaThisInObjLit = returnExprs.isNotEmpty() && returnExprs.all { ret ->
                ret != null && isAsExprWrappingObjLitWithThis(ret)
            }
            if (cycleViaThisInObjLit) {
                val start = nameNode.pos
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "'${nameNode.text}' implicitly has return type 'any' because it does not have a return type annotation and is referenced directly or indirectly in one of its return expressions.",
                    category = DiagnosticCategory.Error,
                    code = 7023,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = nameNode.text.length,
                ))
            }
        }
        // Getters without type annotation: if body has value returns but doesn't always return,
        // emit TS2366 (TypeScript infers non-void return type from the body).
        if (retType == null && strictNullChecks) {
            val hasValueReturn = bodyHasReturnWithValue(body.statements, anyExpr = false)
            val alwaysReturns = bodyAlwaysReturns(body.statements)
            if (hasValueReturn && !alwaysReturns && nameNode is Identifier) {
                val start = nameNode.pos
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Function lacks ending return statement and return type does not include 'undefined'.",
                    category = DiagnosticCategory.Error,
                    code = 2366,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = nameNode.text.length,
                ))
            }
        }
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkFuncExprForImplicitReturn(expr: FunctionExpression, source: String, fileName: String) {
        val body = expr.body ?: return
        if (expr.asteriskToken) return // generators always return an iterator
        val retType = expr.type
        val isAsync = ModifierFlag.Async in expr.modifiers
        val nameRef = expr.name?.let { FuncRef(it.pos, it.text.length) }
        val savedParams = currentFunctionParams
        currentFunctionParams = expr.parameters
        try {
            checkBodyForImplicitReturn(body, retType, isAsync, nameRef, source, fileName)
        } finally {
            currentFunctionParams = savedParams
        }
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkArrowForImplicitReturn(expr: ArrowFunction, source: String, fileName: String) {
        val bodyNode = expr.body
        // 16.0: Concise body (single expression) — check it against return type annotation.
        // E.g., `(arg): number => 'foo'` should emit TS2322 at 'foo'.
        if (bodyNode is Expression && expr.type != null) {
            checkArrowConciseBodyReturnType(expr, bodyNode, source, fileName)
            return
        }
        if (bodyNode !is Block) return
        val retType = expr.type
        val isAsync = ModifierFlag.Async in expr.modifiers
        val savedParams = currentFunctionParams
        currentFunctionParams = expr.parameters
        try {
            checkBodyForImplicitReturn(bodyNode, retType, isAsync, null, source, fileName)
            // TS7030 for no-retType async arrow under noImplicitReturns: async wraps body return
            // in a Promise, so any return-with-value implies non-void inferred return type.
            // Use liberal expression counting (anyExpr=true) to capture `return callExpr()` as well.
            if (retType == null && isAsync && options.noImplicitReturns) {
                val hasValueReturn = bodyHasReturnWithValue(bodyNode.statements, anyExpr = true)
                val alwaysReturns = bodyAlwaysReturns(bodyNode.statements)
                if (hasValueReturn && !alwaysReturns) {
                    // For async arrows, back up over the `async` keyword (modifiers lose pos
                    // in the AST). Scan backwards from expr.pos past whitespace, then look for `async`.
                    var startPos = expr.pos
                    var i = startPos - 1
                    while (i >= 0 && (source[i] == ' ' || source[i] == '\t')) i--
                    if (i >= 4 && source.substring(i - 4, i + 1) == "async") {
                        startPos = i - 4
                    }
                    val nl = source.indexOf('\n', startPos)
                    val endPos = if (nl == -1) source.length else nl
                    val length = endPos - startPos
                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                    diagnostics.add(Diagnostic(
                        message = "Not all code paths return a value.",
                        category = DiagnosticCategory.Error,
                        code = 7030,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = startPos,
                        length = length,
                    ))
                }
            }
        } finally {
            currentFunctionParams = savedParams
        }
        walkForImplicitReturns(bodyNode.statements, source, fileName)
    }

    /**
     * 16.0: Check arrow function concise body expression against the declared
     * return type annotation. Catches `(arg): number => 'foo'` style errors.
     */
    private fun checkArrowConciseBodyReturnType(
        arrow: ArrowFunction, body: Expression, source: String, fileName: String
    ) {
        val retTypeNode = arrow.type ?: return
        try {
            val targetType = getTypeFromTypeNode(retTypeNode)
            if (targetType === anyType || targetType === errorType) return
            // B69.1: Per-branch conditional return-expression checking. Mirrors
            // TypeScript's behavior of checking each branch of `cond ? a : b`
            // against the declared return type independently, so each side gets
            // its own TS2322 diagnostic at its own position.
            if (checkConditionalReturnBranches(body, targetType, retTypeNode, source, fileName)) return
            val bodyType = getTypeOfExpression(body)
            if (bodyType === anyType || bodyType === errorType) return
            // Skip null/undefined sources — strictNullChecks mismatch with TypeScript test defaults.
            if (bodyType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
            if (!canUseTypeEngine(bodyType, targetType)) return
            if (checkTypeRelatedTo(bodyType, targetType, assignableRelation)) return
            // Object literal — emit TS2353 if excess props instead
            if (body is ObjectLiteralExpression) {
                val displayTarget = formatTypeForDisplay(retTypeNode) ?: typeToString(targetType)
                if (checkExcessProperties(body, bodyType, targetType, displayTarget, source, fileName)) return
            }
            val displaySource = typeToString(bodyType)
            val displayTarget = formatTypeForDisplay(retTypeNode) ?: typeToString(targetType)
            val start = body.pos
            val length = expressionTrueEnd(body) - start
            if (length <= 0) return
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * B69.1: If `expr` (after unwrapping parens) is a ConditionalExpression, check
     * each branch (whenTrue / whenFalse) independently against [targetType] and
     * emit per-branch TS2322 at the branch's inner expression position. Mirrors
     * TypeScript's behavior — `cond ? 1 : 2` against return type `3` emits two
     * separate errors, not one aggregated error.
     *
     * Returns `true` if either branch emitted a diagnostic; caller should suppress
     * the outer aggregated emission in that case.
     *
     * Skips any branch whose type is `any`/`error` (e.g. `getAny()`).
     * Recurses through ParenthesizedExpression wrappers to land the squiggle on
     * the innermost expression. AsExpression / non-Conditional expressions fall
     * through (return false) so the caller emits its normal outer-level error.
     */
    private fun checkConditionalReturnBranches(
        expr: Expression?,
        targetType: Type,
        targetNode: TypeNode,
        source: String,
        fileName: String,
    ): Boolean {
        if (expr == null) return false
        val unwrapped = unwrapParens(expr)
        if (unwrapped !is ConditionalExpression) return false
        var emitted = false
        for (branch in listOf(unwrapped.whenTrue, unwrapped.whenFalse)) {
            val inner = unwrapParens(branch)
            // Recurse into nested conditionals: `cond ? (a ? b : c) : d` — each leaf
            // branch should be checked individually.
            if (inner is ConditionalExpression) {
                if (checkConditionalReturnBranches(inner, targetType, targetNode, source, fileName)) emitted = true
                continue
            }
            // Compute branch type with literal preservation when target contains literals.
            val branchType = try {
                if (propTypeContainsLiteral(targetType)) {
                    literalTypeOfExpression(inner) ?: getTypeOfExpression(inner)
                } else getTypeOfExpression(inner)
            } catch (_: StackOverflowError) { continue }
            if (branchType === anyType || branchType === errorType) continue
            if (branchType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) continue
            if (!canUseTypeEngine(branchType, targetType)) continue
            if (checkTypeRelatedTo(branchType, targetType, assignableRelation)) continue
            val displaySource = typeToString(branchType)
            val displayTarget = formatTypeForDisplay(targetNode) ?: typeToString(targetType)
            val start = inner.pos
            val length = expressionTrueEnd(inner) - start
            if (length <= 0) continue
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            emitted = true
        }
        return emitted
    }

    /**
     * Check a function body for TS7030 / TS2355 (not all code paths return a value).
     *
     * TypeScript's rules:
     * - With explicit non-void return type: report at the return type annotation.
     *   - TS2355 if the body has NO return-with-value statements anywhere.
     *   - TS7030 if the body has SOME return-with-value statements but not all paths return.
     * - Without return type (or void-like): report TS7030 at the function name.
     *   - Only when the body has SOME return-with-value statements but not all paths return.
     */
    private fun checkBodyForImplicitReturn(
        body: Block,
        retType: TypeNode?,
        isAsync: Boolean,
        funcNameRef: FuncRef?,
        source: String,
        fileName: String,
    ) {
        // Check if the return type annotation is present and classify it:
        // - "truly-void": void/any/never (and unions containing them) → suppress all checks
        // - "pure-undefined": exactly `undefined` keyword (not a union) → suppress all checks
        // - "nullable": union containing undefined but not void/any/never (e.g. `string | undefined`) → TS7030 if hasAnyReturn
        // - "non-void": all other types (number, string, unknown, non-nullable unions) → trigger TS2355/TS2366/TS7030
        // - null (no annotation): use function name position for TS7030
        val retTypeName = retType?.let { getTypeNodeName(it, isAsync) }
        val retTypeClass = when {
            retType == null -> null
            retTypeName == null -> "non-void"  // unknown type (complex type we can't parse) → treat as non-void
            isVoidLikeTypeName(retTypeName) && retTypeName != "undefined" && !(retTypeName == "unknown" && options.noImplicitReturns) -> "truly-void"  // void/any/never/unknown (unknown only when !noImplicitReturns)
            retTypeName == "undefined" -> {
                // "pure-undefined": the return type is exactly `undefined`, satisfied by implicit
                // return. For async, also accept `Promise<undefined>` since async-unwrap pulls out
                // a bare `undefined` keyword.
                // "nullable": a UNION containing undefined alongside non-undefined non-void types
                // (e.g. `undefined | number`) — implicit return only satisfies the `undefined`
                // member, so TS2355 must fire when there are no explicit returns. Mirrors `Promise<undefined | number>`.
                val unwrappedArg = if (isAsync && retType is TypeReference
                    && (retType.typeName as? Identifier)?.text == "Promise"
                    && retType.typeArguments?.size == 1) retType.typeArguments[0] else null
                when {
                    retType is KeywordTypeNode -> "pure-undefined"
                    unwrappedArg is KeywordTypeNode -> "pure-undefined"
                    else -> "nullable"
                }
            }
            else -> "non-void"  // number, string, unknown, union, function-type, etc.
        }

        // truly-void and pure-undefined return types suppress all implicit-return checks
        if (retTypeClass == "truly-void" || retTypeClass == "pure-undefined") return

        // 17.135: suppress all implicit-return checks when the return type
        // annotation is a bare `TypeReference` with an `Identifier` name, AND
        // we have already emitted a TS2304 ("Cannot find name") diagnostic for
        // that same identifier position. TypeScript treats unresolved-name
        // annotations as any-like for implicit-return purposes — adding
        // TS2355/TS2366 on top of an existing TS2304 would be redundant noise
        // pointing to the same span. Using the existing-diagnostic probe (vs.
        // a name-resolution probe) avoids regressions for namespace-internal
        // type names that aren't in `globals` but aren't actually unresolved
        // (the binder routes them through their containing namespace's
        // exports — for those, no TS2304 fires, and this branch doesn't
        // trigger).
        if (retType is TypeReference && retType.typeArguments.isNullOrEmpty()) {
            val refIdent = retType.typeName as? Identifier
            if (refIdent != null) {
                val refStart = refIdent.pos
                val hasTs2304 = diagnostics.any {
                    it.code == 2304 && it.start == refStart && it.fileName == fileName
                }
                if (hasTs2304) return
                // Mirror for TS2314: generic type used without required type args
                // (e.g. `): MemberName {` where MemberName<A,B,C>). TypeScript also
                // suppresses TS2355/TS2366/TS7030 in this case because the return type
                // is treated as malformed at the type level — emitting TS2355 on top
                // would be redundant noise pointing to the same span.
                val hasTs2314 = diagnostics.any {
                    it.code == 2314 && it.start == refStart && it.fileName == fileName
                }
                if (hasTs2314) return
            }
        }

        // If the function always returns/throws on all paths, check for problematic empty returns
        val alwaysReturns = bodyAlwaysReturns(body.statements)
        if (alwaysReturns) {
            // Case 1: explicit non-void return type + body always returns via empty returns → TS7030 at each empty return
            if (retTypeClass == "non-void" && retType != null) {
                reportEmptyReturnsInBody(body.statements, source, fileName)
            }
            // Case 2: no explicit return type, but some paths return values and some do empty returns → TS7030 at empty returns
            // B51.4: gate on noImplicitReturns. Without that compiler flag, an empty
            // `return;` in an unannotated function implicitly returns `undefined`,
            // which widens the inferred return to `fn-type | undefined` — a legal
            // mixed-return shape. TypeScript only emits TS7030 in this case when
            // noImplicitReturns is set (cf. controlFlowForFunctionLike1_ts).
            if (retType == null && options.noImplicitReturns) {
                val hasValueReturn = bodyHasReturnWithValue(body.statements, anyExpr = false)
                if (hasValueReturn) {
                    reportEmptyReturnsInBody(body.statements, source, fileName)
                }
            }
            return
        }

        // Determine if the body has any return-with-value statement.
        // When an explicit return type annotation is present, use liberal counting (any `return <expr>`,
        // including `return undefined`, `return callExpr()`). Without annotation, use strict counting
        // (only syntactically non-void expressions, excluding `return undefined` identifier).
        val hasAnyReturn = bodyHasReturnWithValue(body.statements, anyExpr = retType != null)

        // A type is "definitely non-nullable" for TS2366: it's non-void AND not unknown AND not nullable
        val isDefinitelyNonNullable = retTypeClass == "non-void" && retTypeName != "unknown"

        // For explicit return type annotations: report at the return type annotation
        if (retType != null) {
            // "nullable" (union containing undefined, e.g. `undefined | number`):
            //   - !hasAnyReturn → TS2355 (function with such a type still must return a value).
            //     TypeScript treats `undefined | T` as requiring an explicit return because
            //     the implicit `undefined` only satisfies the `undefined` member, not the `T` member.
            //   - hasAnyReturn → falls through to TS7030 (mixed returns).
            if (retTypeClass == "nullable" && !hasAnyReturn) {
                val start = retType.pos
                val spanLen = getRetTypeSpanLength(source, start)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "A function whose declared type is neither 'undefined', 'void', nor 'any' must return a value.",
                    category = DiagnosticCategory.Error,
                    code = 2355,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = spanLen,
                ))
                return
            }

            val start = retType.pos
            val spanLen = getRetTypeSpanLength(source, start)
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            when {
                // TS2366: non-nullable return type with some value returns under strictNullChecks,
                // or noImplicitReturns without value returns outside try blocks.
                // "Function lacks ending return statement and return type does not include 'undefined'."
                // Under strictNullChecks, undefined is NOT assignable to non-nullable types,
                // so implicit return (returning undefined) is a type error.
                isDefinitelyNonNullable && hasAnyReturn && strictNullChecks -> {
                    diagnostics.add(Diagnostic(
                        message = "Function lacks ending return statement and return type does not include 'undefined'.",
                        category = DiagnosticCategory.Error,
                        code = 2366,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
                hasAnyReturn && (strictNullChecks || options.noImplicitReturns) -> {
                    // TS7030: some paths return with a value, some don't (for nullable/unknown return types)
                    // Only fires when strictNullChecks is on (undefined not assignable) or noImplicitReturns is set.
                    // Without either, implicit return of undefined is always valid.
                    diagnostics.add(Diagnostic(
                        message = "Not all code paths return a value.",
                        category = DiagnosticCategory.Error,
                        code = 7030,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
                retTypeClass == "non-void" && !hasAnyReturn -> {
                    // TS2355: function has non-void return type but never returns (no return statements at all)
                    diagnostics.add(Diagnostic(
                        message = "A function whose declared type is neither 'undefined', 'void', nor 'any' must return a value.",
                        category = DiagnosticCategory.Error,
                        code = 2355,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
            }
            return
        }

        // No explicit return type: TS7030 at function name only when noImplicitReturns is set
        // Without noImplicitReturns, TypeScript does NOT report TS7030 for unannotated functions
        // even when they have mixed returns (some paths return, some don't).
        if (options.noImplicitReturns && hasAnyReturn && funcNameRef != null) {
            val (line, character) = getLineAndCharacterOfPosition(source, funcNameRef.pos)
            diagnostics.add(Diagnostic(
                message = "Not all code paths return a value.",
                category = DiagnosticCategory.Error,
                code = 7030,
                fileName = fileName,
                line = line,
                character = character,
                start = funcNameRef.pos,
                length = funcNameRef.length,
            ))
        }
    }

    /**
     * Report TS7030 at each empty `return;` statement in the body (and nested blocks).
     * Used when a function with non-void return type has all paths covered by return statements
     * but some returns are empty (returning undefined implicitly).
     * Does NOT recurse into nested function bodies.
     */
    private fun reportEmptyReturnsInBody(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            reportEmptyReturnsInStmt(stmt, source, fileName)
        }
    }

    private fun reportEmptyReturnsInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ReturnStatement -> {
                if (stmt.expression == null) {
                    // Empty return; in non-void function
                    val (line, character) = getLineAndCharacterOfPosition(source, stmt.pos)
                    diagnostics.add(Diagnostic(
                        message = "Not all code paths return a value.",
                        category = DiagnosticCategory.Error,
                        code = 7030,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmt.pos,
                        length = "return".length,
                    ))
                }
            }
            is Block -> reportEmptyReturnsInBody(stmt.statements, source, fileName)
            is IfStatement -> {
                reportEmptyReturnsInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { reportEmptyReturnsInStmt(it, source, fileName) }
            }
            is ForStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is ForInStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is WhileStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is DoStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> reportEmptyReturnsInBody(clause.statements, source, fileName)
                        is DefaultClause -> reportEmptyReturnsInBody(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                reportEmptyReturnsInBody(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { reportEmptyReturnsInBody(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { reportEmptyReturnsInBody(it.statements, source, fileName) }
            }
            is LabeledStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            // Don't recurse into nested function declarations/expressions (they have their own checks)
            is FunctionDeclaration -> {}
            else -> {}
        }
    }

    /**
     * Returns true if the body contains a throw statement. Used for TS2378 suppression.
     */
    private fun bodyHasThrow(stmts: List<Statement>): Boolean {
        return stmts.any { stmtHasThrow(it) }
    }

    private fun stmtHasThrow(stmt: Statement): Boolean {
        return when (stmt) {
            is ThrowStatement -> true
            is Block -> bodyHasThrow(stmt.statements)
            is IfStatement -> stmtHasThrow(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtHasThrow(it) } ?: false)
            is TryStatement -> bodyHasThrow(stmt.tryBlock.statements)
            is LabeledStatement -> stmtHasThrow(stmt.statement)
            else -> false
        }
    }

    /**
     * Returns true if the body contains ANY return statement (with or without expression).
     * Does NOT recurse into nested function bodies. Used for TS2378 (getter must return).
     */
    private fun bodyHasAnyReturn(stmts: List<Statement>): Boolean {
        return stmts.any { stmtHasAnyReturn(it) }
    }

    private fun stmtHasAnyReturn(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is Block -> bodyHasAnyReturn(stmt.statements)
            is IfStatement -> stmtHasAnyReturn(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtHasAnyReturn(it) } ?: false)
            is WhileStatement -> stmtHasAnyReturn(stmt.statement)
            is ForStatement -> stmtHasAnyReturn(stmt.statement)
            is ForInStatement -> stmtHasAnyReturn(stmt.statement)
            is ForOfStatement -> stmtHasAnyReturn(stmt.statement)
            is DoStatement -> stmtHasAnyReturn(stmt.statement)
            is LabeledStatement -> stmtHasAnyReturn(stmt.statement)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> bodyHasAnyReturn(clause.statements)
                    is DefaultClause -> bodyHasAnyReturn(clause.statements)
                    else -> false
                }
            }
            is TryStatement -> bodyHasAnyReturn(stmt.tryBlock.statements) ||
                (stmt.catchClause?.let { bodyHasAnyReturn(it.block.statements) } ?: false) ||
                (stmt.finallyBlock?.let { bodyHasAnyReturn(it.statements) } ?: false)
            else -> false
        }
    }

    /**
     * Returns true if the body contains any `return <expr>` statement.
     * When [anyExpr] is true: counts any non-null expression (even `return undefined`, `return callExpr()`).
     * When [anyExpr] is false (default): uses [isNonVoidExpression] filter (conservative).
     * Does NOT recurse into nested function bodies.
     */
    private fun bodyHasReturnWithValue(stmts: List<Statement>, anyExpr: Boolean = false): Boolean {
        return stmts.any { stmtHasReturnWithValue(it, anyExpr) }
    }

    /**
     * Returns true if an expression is syntactically non-void (definitely not void type).
     * Used to filter out `return voidFunc()` cases where we can't know if void without type info.
     * Conservative: call expressions return false (might be void), literals return true.
     */
    private fun isNonVoidExpression(expr: Expression): Boolean {
        return when (expr) {
            is NumericLiteralNode -> true
            is StringLiteralNode -> true
            is RegularExpressionLiteralNode -> true
            is Identifier -> expr.text != "undefined"
            is BinaryExpression -> true  // arithmetic/comparison/string concat
            is PrefixUnaryExpression -> true
            is PostfixUnaryExpression -> true
            is ArrayLiteralExpression -> true
            is ObjectLiteralExpression -> true
            is NewExpression -> true
            is ParenthesizedExpression -> isNonVoidExpression(expr.expression)
            is ConditionalExpression -> true  // ternary always has a value
            is TemplateExpression -> true
            is NoSubstitutionTemplateLiteralNode -> true
            // CallExpression might return void — skip counting these without type info
            is CallExpression -> false
            // TypeAssertionExpression (<T>expr): count unless cast type is any/void/undefined
            is TypeAssertionExpression -> {
                val typeName = getTypeNodeName(expr.type, false)
                // unknown is non-void here — `as unknown` is an explicit cast producing a value
                typeName != null && (typeName == "unknown" || !isVoidLikeTypeName(typeName))
            }
            // AsExpression (expr as T): count unless asserted type is any/void/undefined
            is AsExpression -> {
                val typeName = getTypeNodeName(expr.type, false)
                typeName != null && (typeName == "unknown" || !isVoidLikeTypeName(typeName))
            }
            else -> false  // conservative
        }
    }

    private fun stmtHasReturnWithValue(stmt: Statement, anyExpr: Boolean = false): Boolean {
        return when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression ?: return false
                if (anyExpr) true else isNonVoidExpression(expr)
            }
            is Block -> bodyHasReturnWithValue(stmt.statements, anyExpr)
            is IfStatement -> stmtHasReturnWithValue(stmt.thenStatement, anyExpr) ||
                (stmt.elseStatement?.let { stmtHasReturnWithValue(it, anyExpr) } ?: false)
            is WhileStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForInStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForOfStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is DoStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is LabeledStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> bodyHasReturnWithValue(clause.statements, anyExpr)
                    is DefaultClause -> bodyHasReturnWithValue(clause.statements, anyExpr)
                    else -> false
                }
            }
            is TryStatement -> bodyHasReturnWithValue(stmt.tryBlock.statements, anyExpr) ||
                (stmt.catchClause?.let { bodyHasReturnWithValue(it.block.statements, anyExpr) } ?: false) ||
                (stmt.finallyBlock?.let { bodyHasReturnWithValue(it.statements, anyExpr) } ?: false)
            // Do NOT recurse into nested function expressions
            else -> false
        }
    }

    /**
     * Returns true if the body has any return-with-value statement OUTSIDE of try blocks.
     * Used to distinguish TS2366 (no value returns outside try) from TS7030 (mixed returns).
     * Returns inside try blocks don't count — TypeScript handles these as "protected paths."
     */
    private fun hasAnyReturnOutsideTry(stmts: List<Statement>): Boolean {
        for (stmt in stmts) {
            if (stmtHasReturnWithValueOutsideTry(stmt)) return true
        }
        return false
    }

    private fun stmtHasReturnWithValueOutsideTry(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression ?: return false
                // anyExpr=true: any return with expression counts (we only call with retType!=null)
                true
            }
            is Block -> hasAnyReturnOutsideTry(stmt.statements)
            is IfStatement -> stmtHasReturnWithValueOutsideTry(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtHasReturnWithValueOutsideTry(it) } ?: false)
            is WhileStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForInStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForOfStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is DoStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is LabeledStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> hasAnyReturnOutsideTry(clause.statements)
                    is DefaultClause -> hasAnyReturnOutsideTry(clause.statements)
                    else -> false
                }
            }
            // TryStatement: returns inside try/catch/finally are "protected" — don't count
            is TryStatement -> false
            else -> false
        }
    }

    /**
     * Computes the actual span length of a return type annotation starting at [start] in [source].
     * TypeNode.end includes the next scanned token (the `{` of the body), so we must scan forward
     * to find the actual end of the type text.
     * Tracks nesting depth so spaces inside `()`, `<>`, `[]` do not break the scan.
     */
    private fun getRetTypeSpanLength(source: String, start: Int): Int {
        if (start >= source.length) return 0
        var i = start
        var depth = 0
        while (i < source.length) {
            val ch = source[i]
            when {
                ch == '<' || ch == '[' || ch == '(' -> { depth++; i++ }
                ch == '>' || ch == ']' || ch == ')' || ch == '}' -> {
                    if (depth > 0) { depth--; i++ }
                    else break // unmatched close = end of type
                }
                ch == '{' -> {
                    if (i == start) { depth++; i++ } // TypeLiteral `{}` — enter it
                    else break // start of body block
                }
                ch == '\n' || ch == '\r' -> {
                    if (depth > 0) i++ // inside delimiters: continue past newlines (multi-line types)
                    else break
                }
                depth > 0 -> i++ // inside delimiters: consume everything
                ch == ',' || ch == ';' -> break
                ch == '=' -> {
                    // `=>` is the arrow in a function type like `(A) => B` — consume it
                    if (source.getOrNull(i + 1) == '>') { i += 2 }
                    else break // plain `=` ends the type
                }
                ch == '>' -> i++ // part of `=>` arrow (consumed after `=`)
                ch == '|' || ch == '&' || ch == '.' -> i++
                ch.isLetterOrDigit() || ch == '_' || ch == '$' -> i++
                ch == ' ' || ch == '\t' -> {
                    // At depth 0: space is valid inside union/intersection ("number | string")
                    // or before `=>` in a function type
                    val next = source.getOrNull(i + 1)
                    if (next != null && (next == '|' || next == '&' || next == '[' || next == '=' || next.isLetter())) {
                        i++ // part of multi-word type or function type arrow
                    } else {
                        break
                    }
                }
                ch == '?' -> i++ // optional types
                else -> break
            }
        }
        return (i - start).coerceAtLeast(1)
    }

    /**
     * Returns true if the type name represents void, undefined, or any.
     */
    private fun isVoidLikeTypeName(name: String): Boolean {
        return name == "void" || name == "undefined" || name == "any" || name == "never" || name == "unknown"
    }

    /**
     * Extracts the textual name of a type node for basic void/undefined/any check.
     */
    private fun getTypeNodeName(node: TypeNode, isAsync: Boolean): String? {
        return when (node) {
            is TypeReference -> {
                val typeName = node.typeName
                val baseName = when (typeName) {
                    is Identifier -> typeName.text
                    is QualifiedName -> typeName.right.text
                    else -> null
                }
                // For async functions, Promise<void> and Promise<any> are void-like
                if (isAsync && baseName == "Promise" && node.typeArguments?.size == 1) {
                    val argName = getTypeNodeName(node.typeArguments[0], false)
                    return if (argName != null && isVoidLikeTypeName(argName)) argName else baseName
                }
                baseName
            }
            is KeywordTypeNode -> when (node.kind) {
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.UndefinedKeyword -> "undefined"
                // number, string, boolean, bigint, symbol, object, unknown, null
                // are all non-void types — return a non-null name so we report
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is UnionType -> {
                // Union type classification for TS2355/TS7030/TS2366:
                // - Contains void/any/never → truly void-like, suppress all checks ("void")
                // - Contains undefined (but not void) → nullable union, suppress TS2355/TS2366
                //   but NOT TS7030 (e.g. `string | undefined`) → return "undefined"
                // - No void/any/never/undefined → non-nullable union, may trigger TS7030 → return "union"
                val memberNames = node.types.mapNotNull { getTypeNodeName(it, false) }
                when {
                    memberNames.any { it == "void" || it == "any" || it == "never" } -> "void"
                    memberNames.any { it == "undefined" } -> "undefined"
                    memberNames.isEmpty() -> null
                    else -> "union" // non-nullable union (e.g. `string | number`)
                }
            }
            is FunctionType -> "function-type"  // definitively non-void (a function type is always an object)
            else -> null
        }
    }

    /**
     * Returns true if a list of statements always returns/throws on all paths.
     * Used for TS7030 checking.
     */
    private fun bodyAlwaysReturns(stmts: List<Statement>): Boolean {
        // If no statements, doesn't always return
        if (stmts.isEmpty()) return false
        // Walk through statements — find if some statement definitely terminates
        for (stmt in stmts) {
            if (statementAlwaysReturns(stmt)) return true
        }
        return false
    }

    /**
     * Returns true if this statement always returns/throws on all code paths.
     */
    private fun statementAlwaysReturns(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is ThrowStatement -> true
            is BreakStatement -> false  // break transfers control out of loop/switch, not "returns"
            is ContinueStatement -> false
            is Block -> bodyAlwaysReturns(stmt.statements)
            is IfStatement -> {
                val thenRet = statementAlwaysReturns(stmt.thenStatement)
                val elseBranch = stmt.elseStatement
                thenRet && elseBranch != null && statementAlwaysReturns(elseBranch)
            }
            is WhileStatement -> {
                // while(true) with no break always terminates (infinite loop or always throws/returns)
                isAlwaysTrue(stmt.expression) && !containsBreakOrReturn(stmt.statement)
            }
            is ForStatement -> {
                // for(;;) with no break always terminates
                stmt.condition == null && !containsBreakOrReturn(stmt.statement)
            }
            is DoStatement -> {
                // do {} while (false) - body must always return
                statementAlwaysReturns(stmt.statement) ||
                    (isAlwaysTrue(stmt.expression) && !containsBreakOrReturn(stmt.statement))
            }
            is SwitchStatement -> {
                // Switch always returns if it has a default clause and all clauses return
                val hasDefault = stmt.caseBlock.any { it is DefaultClause }
                if (!hasDefault) {
                    // No default: check for exhaustive typeof switch covering all 8 values
                    if (stmt.expression is TypeOfExpression && switchAlwaysReturns(stmt.caseBlock)) {
                        val typeofValues = setOf("string", "number", "bigint", "boolean", "symbol", "undefined", "object", "function")
                        val caseClauses = stmt.caseBlock.filterIsInstance<CaseClause>()
                        val coveredValues = caseClauses.mapNotNull { (it.expression as? StringLiteralNode)?.text }.toSet()
                        if (coveredValues.containsAll(typeofValues)) return true
                    }
                    // No default: check for exhaustive switch on a string/boolean literal type parameter
                    if (isExhaustiveLiteralSwitch(stmt)) return true
                    return false
                }
                // Check that every clause either falls through to one that returns or returns itself
                switchAlwaysReturns(stmt.caseBlock)
            }
            is LabeledStatement -> statementAlwaysReturns(stmt.statement)
            is TryStatement -> {
                // try/catch: if both try and catch return, the whole statement returns
                val tryRet = bodyAlwaysReturns(stmt.tryBlock.statements)
                val catchRet = stmt.catchClause?.let { bodyAlwaysReturns(it.block.statements) } ?: true
                tryRet && catchRet
            }
            is ExpressionStatement -> {
                // IIFE or function call that always throws — check for iife pattern
                when (val expr = stmt.expression) {
                    is CallExpression -> {
                        val func = expr.expression
                        when (func) {
                            is FunctionExpression -> {
                                func.body?.let { bodyAlwaysReturns(it.statements) } ?: false
                            }
                            is ArrowFunction -> {
                                val body = func.body
                                when (body) {
                                    is Block -> bodyAlwaysReturns(body.statements)
                                    is ThrowStatement -> true
                                    else -> false
                                }
                            }
                            else -> false
                        }
                    }
                    else -> false
                }
            }
            else -> false
        }
    }

    /**
     * Check if a switch statement without a default clause is exhaustive given the current
     * function's literal-type parameters. E.g., `switch(bar) { case "a": return 1; }` where
     * `bar: "a"` is exhaustive (all values covered).
     *
     * Uses `currentFunctionParams` to look up parameter types.
     */
    private fun isExhaustiveLiteralSwitch(stmt: SwitchStatement): Boolean {
        // The switch expression must be a simple identifier
        val exprIdent = stmt.expression as? Identifier ?: return false
        val paramName = exprIdent.text

        // Find a matching parameter in currentFunctionParams
        val param = currentFunctionParams.firstOrNull { p ->
            (p.name as? Identifier)?.text == paramName
        } ?: return false

        // The parameter must have a type annotation
        val typeNode = param.type ?: return false

        // Collect all literal values from the parameter type annotation
        val requiredValues = collectLiteralTypeValues(typeNode)
        if (requiredValues.isEmpty()) return false

        // Collect all case clause literal values using same representation as collectLiteralTypeValues
        val caseClauses = stmt.caseBlock.filterIsInstance<CaseClause>()
        val coveredValues = mutableSetOf<String>()
        for (clause in caseClauses) {
            val literal = when (val e = clause.expression) {
                is StringLiteralNode -> "\"${e.text}\""
                is NumericLiteralNode -> e.text
                is Identifier -> when (e.text) {
                    "true" -> "true"
                    "false" -> "false"
                    else -> null
                }
                is PrefixUnaryExpression -> {
                    val operand = e.operand
                    if (e.operator == SyntaxKind.Minus && operand is NumericLiteralNode) {
                        "-${operand.text}"
                    } else null
                }
                else -> null
            } ?: continue
            coveredValues.add(literal)
        }

        // The switch is exhaustive if all required values are covered AND all clauses return
        if (!coveredValues.containsAll(requiredValues)) return false
        return switchAlwaysReturns(stmt.caseBlock)
    }

    /**
     * Collect literal type values from a type annotation node.
     * Returns a set of string representations (e.g., `"\"a\""`, `"1"`, `"true"`, `"false"`).
     * Returns empty if the type is not a literal or union of literals.
     */
    private fun collectLiteralTypeValues(typeNode: TypeNode): Set<String> {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                // `boolean` has exactly two literal values: true and false
                SyntaxKind.BooleanKeyword -> setOf("true", "false")
                else -> emptySet()
            }
            is LiteralType -> {
                // LiteralType wraps string/number/boolean literals and keyword true/false
                when (val lit = typeNode.literal) {
                    is Identifier -> when (lit.text) {
                        "true" -> setOf("true")
                        "false" -> setOf("false")
                        else -> emptySet()
                    }
                    is StringLiteralNode -> setOf("\"${lit.text}\"")
                    is NumericLiteralNode -> setOf(lit.text)
                    is PrefixUnaryExpression -> {
                        // Negative number literals like -1
                        val operand = lit.operand
                        if (lit.operator == SyntaxKind.Minus && operand is NumericLiteralNode) {
                            setOf("-${operand.text}")
                        } else emptySet()
                    }
                    else -> emptySet()
                }
            }
            is UnionType -> {
                val result = mutableSetOf<String>()
                for (t in typeNode.types) {
                    val vals = collectLiteralTypeValues(t)
                    if (vals.isEmpty()) return emptySet() // non-literal constituent → not exhaustive
                    result.addAll(vals)
                }
                result
            }
            else -> emptySet()
        }
    }

    private fun switchAlwaysReturns(clauses: List<Node>): Boolean {
        // Each clause either terminates or falls through to a clause that terminates
        // Simple: check that there's a path through all clauses that always returns
        val clauseTerminates = clauses.map { clause ->
            when (clause) {
                is CaseClause -> bodyAlwaysReturns(clause.statements)
                is DefaultClause -> bodyAlwaysReturns(clause.statements)
                else -> false
            }
        }
        // Find the last clause — it must terminate (or the one before that falls through to it)
        // Actually: switches always return if every "fall-through chain" ends in a return
        // Simple heuristic: if every non-empty clause terminates, it always returns
        return clauses.all { clause ->
            val stmts = when (clause) {
                is CaseClause -> clause.statements
                is DefaultClause -> clause.statements
                else -> emptyList()
            }
            stmts.isEmpty() || bodyAlwaysReturns(stmts)
        }
    }

    private fun containsBreakOrReturn(stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> true
            is ReturnStatement -> true
            is Block -> stmt.statements.any { containsBreakOrReturn(it) }
            is IfStatement -> containsBreakOrReturn(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsBreakOrReturn(it) } ?: false)
            is LabeledStatement -> containsBreakOrReturn(stmt.statement)
            // Recurse into nested loops/switches looking for LABELED breaks
            // (unlabeled break exits the inner loop only — doesn't affect outer)
            // or return statements (those exit the enclosing function entirely).
            // Required for reachabilityChecks5/6 f11: `do { do { break test; } while(true) } while(true)`
            // — the inner do's `break test` escapes the outer do too, so the outer
            // do is NOT a truly-infinite loop and the function does NOT always return.
            is WhileStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is DoStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForInStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForOfStatement -> containsLabeledBreakOrReturn(stmt.statement)
            else -> false
        }
    }

    /**
     * Like [containsBreakOrReturn] but unlabeled breaks are NOT counted — only
     * labeled breaks (which escape further than the immediately-enclosing loop)
     * and return statements. Used by [containsBreakOrReturn] when recursing into
     * nested loops to ask "would something inside this nested loop ALSO exit the
     * outer loop?".
     */
    private fun containsLabeledBreakOrReturn(stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> stmt.label != null  // only LABELED breaks escape further
            is ReturnStatement -> true
            is Block -> stmt.statements.any { containsLabeledBreakOrReturn(it) }
            is IfStatement -> containsLabeledBreakOrReturn(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsLabeledBreakOrReturn(it) } ?: false)
            is LabeledStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is WhileStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is DoStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForInStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is ForOfStatement -> containsLabeledBreakOrReturn(stmt.statement)
            is TryStatement -> {
                stmt.tryBlock.statements.any { containsLabeledBreakOrReturn(it) } ||
                (stmt.catchClause?.block?.statements?.any { containsLabeledBreakOrReturn(it) } ?: false) ||
                (stmt.finallyBlock?.statements?.any { containsLabeledBreakOrReturn(it) } ?: false)
            }
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // TS1156 — block-scoped declarations outside blocks
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // TS2481: var shadowing outer block-scoped name
    // -----------------------------------------------------------------------

    /**
     * TS2481: "Cannot initialize outer scoped variable 'x' in the same scope as block scoped declaration 'x'."
     * Fires when a `var` in an inner scope has the same name as a `let`/`const` in an outer block scope
     * within the same function.
     */
    private fun checkOuterScopeVarShadowing() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Walk file-level statements with empty outer scope chain (isTopLevel=true)
            walkBodyForVarShadowing(result.sourceFile.statements, source, fileName, mutableListOf(), isTopLevel = true)
        }
    }

    /**
     * Walk a function body (or file-level statements) looking for `var` declarations
     * that shadow outer `let`/`const` names.
     * [outerScopes]: list of sets of let/const names in each outer block scope
     */
    private fun walkBodyForVarShadowing(
        stmts: List<Statement>,
        source: String,
        fileName: String,
        outerScopes: MutableList<MutableSet<String>>,
        isTopLevel: Boolean = false
    ) {
        // Collect the let/const names at THIS block level.
        val currentScope = mutableSetOf<String>()
        collectLetConstNamesInStmts(stmts, currentScope)
        // Walk statements:
        // - At the file/function TOP LEVEL (isTopLevel=true): var+let at same level fires TS2300, not TS2481.
        //   So don't include currentScope when checking var.
        // - Inside a BLOCK (isTopLevel=false): var+let/const in same block fires TS2481.
        //   Include currentScope when checking var.
        for (stmt in stmts) {
            walkStmtForVarShadowing(stmt, source, fileName, outerScopes, currentScope, isTopLevel)
        }
    }

    /**
     * Collect all let/const names declared directly in these statements (not recursing into nested blocks).
     */
    private fun collectLetConstNamesInStmts(stmts: List<Statement>, out: MutableSet<String>) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    val kind = stmt.declarationList.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in stmt.declarationList.declarations) {
                            collectVarBindingNames(d.name, out)
                        }
                    }
                }
                else -> {} // Other statements don't add block-scoped names at this level
            }
        }
    }

    /** Collect identifier names from a binding pattern (Expression that is Identifier/ObjectBinding/ArrayBinding). */
    private fun collectVarBindingNames(binding: Expression, out: MutableSet<String>) {
        when (binding) {
            is Identifier -> out.add(binding.text)
            is ObjectBindingPattern -> for (el in binding.elements) {
                if (el is BindingElement) collectVarBindingNames(el.name, out)
            }
            is ArrayBindingPattern -> for (el in binding.elements) {
                if (el is BindingElement) collectVarBindingNames(el.name, out)
            }
            else -> {}
        }
    }

    /**
     * Walk a single statement for TS2481 var shadowing.
     * [outerScopes]: block-scoped names from ALL strictly enclosing blocks.
     * [currentScope]: let/const names from the CURRENT block level.
     * [isTopLevel]: true if at file/function top level (same-scope var+let fires TS2300, not TS2481).
     */
    private fun walkStmtForVarShadowing(
        stmt: Statement,
        source: String,
        fileName: String,
        outerScopes: MutableList<MutableSet<String>>,
        currentScope: MutableSet<String>,
        isTopLevel: Boolean = false
    ) {
        when (stmt) {
            is VariableStatement -> {
                val kind = stmt.declarationList.flags
                if (kind != SyntaxKind.LetKeyword && kind != SyntaxKind.ConstKeyword) {
                    // var declaration: check against outer scopes always.
                    // Also check against currentScope UNLESS we're at the top level
                    // (top-level var+let fires TS2300, not TS2481).
                    for (d in stmt.declarationList.declarations) {
                        checkVarDeclForShadowing(d.name, source, fileName, outerScopes,
                            extraScope = if (isTopLevel) null else currentScope)
                    }
                }
            }
            is ForStatement -> {
                // Check for-init var/let/const declarations
                val init = stmt.initializer
                val loopScope = mutableSetOf<String>()
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        // for (let v; ...) — v is block-scoped to the for loop (add to loop scope)
                        for (d in init.declarations) collectVarBindingNames(d.name, loopScope)
                    } else {
                        // for (var v = 0; ...) — check for shadowing
                        for (d in init.declarations) {
                            checkVarDeclForShadowing(d.name, source, fileName, outerScopes)
                        }
                    }
                }
                // The body executes within the loop scope (includes for-let variables).
                // Add currentScope as outer (since we're now one level deeper).
                outerScopes.add(currentScope)
                outerScopes.add(loopScope)
                val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements else listOf(stmt.statement)
                for (s in bodyStmts) walkStmtForVarShadowing(s, source, fileName, outerScopes, mutableSetOf())
                outerScopes.removeAt(outerScopes.lastIndex) // remove loopScope
                outerScopes.removeAt(outerScopes.lastIndex) // remove currentScope
            }
            is ForInStatement -> {
                // for (let/const x in ...) or for (var x in ...)
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    val loopScope = mutableSetOf<String>()
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) collectVarBindingNames(d.name, loopScope)
                    } else {
                        // var: check for shadowing
                        for (d in init.declarations) {
                            checkVarDeclForShadowing(d.name, source, fileName, outerScopes)
                        }
                    }
                    // Push currentScope as outer before walking body
                    outerScopes.add(currentScope)
                    outerScopes.add(loopScope)
                    val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements else listOf(stmt.statement)
                    for (s in bodyStmts) walkStmtForVarShadowing(s, source, fileName, outerScopes, mutableSetOf())
                    outerScopes.removeAt(outerScopes.lastIndex) // remove loopScope
                    outerScopes.removeAt(outerScopes.lastIndex) // remove currentScope
                }
            }
            is ForOfStatement -> {
                // for (let/const x of ...) or for (var x of ...)
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    val loopScope = mutableSetOf<String>()
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) collectVarBindingNames(d.name, loopScope)
                    } else {
                        // var: check for shadowing
                        for (d in init.declarations) {
                            checkVarDeclForShadowing(d.name, source, fileName, outerScopes)
                        }
                    }
                    // Push currentScope as outer before walking body
                    outerScopes.add(currentScope)
                    outerScopes.add(loopScope)
                    val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements else listOf(stmt.statement)
                    for (s in bodyStmts) walkStmtForVarShadowing(s, source, fileName, outerScopes, mutableSetOf())
                    outerScopes.removeAt(outerScopes.lastIndex) // remove loopScope
                    outerScopes.removeAt(outerScopes.lastIndex) // remove currentScope
                }
            }
            is Block -> {
                // Nested block: add currentScope as outer before recursing
                outerScopes.add(currentScope)
                walkBodyForVarShadowing(stmt.statements, source, fileName, outerScopes)
                outerScopes.removeAt(outerScopes.lastIndex)
            }
            is IfStatement -> {
                // Walk both branches as inner block scopes (even if no braces)
                outerScopes.add(currentScope)
                val thenStmts = if (stmt.thenStatement is Block) (stmt.thenStatement as Block).statements else listOf(stmt.thenStatement)
                walkBodyForVarShadowing(thenStmts, source, fileName, outerScopes)
                val elseStmt = stmt.elseStatement
                if (elseStmt != null) {
                    val elseStmts = if (elseStmt is Block) (elseStmt as Block).statements else listOf(elseStmt)
                    walkBodyForVarShadowing(elseStmts, source, fileName, outerScopes)
                }
                outerScopes.removeAt(outerScopes.lastIndex)
            }
            is WhileStatement -> {
                outerScopes.add(currentScope)
                val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements else listOf(stmt.statement)
                walkBodyForVarShadowing(bodyStmts, source, fileName, outerScopes)
                outerScopes.removeAt(outerScopes.lastIndex)
            }
            is DoStatement -> {
                outerScopes.add(currentScope)
                val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements else listOf(stmt.statement)
                walkBodyForVarShadowing(bodyStmts, source, fileName, outerScopes)
                outerScopes.removeAt(outerScopes.lastIndex)
            }
            is TryStatement -> {
                outerScopes.add(currentScope)
                walkBodyForVarShadowing(stmt.tryBlock.statements, source, fileName, outerScopes)
                stmt.catchClause?.let { walkBodyForVarShadowing(it.block.statements, source, fileName, outerScopes) }
                stmt.finallyBlock?.let { walkBodyForVarShadowing(it.statements, source, fileName, outerScopes) }
                outerScopes.removeAt(outerScopes.lastIndex)
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Switch clauses share one scope (they don't get separate scopes)
                    for (s in clauseStmts) walkStmtForVarShadowing(s, source, fileName, outerScopes, currentScope)
                }
            }
            is LabeledStatement -> walkStmtForVarShadowing(stmt.statement, source, fileName, outerScopes, currentScope)
            // Function/class declarations start fresh function scopes — don't recurse with current chain
            is FunctionDeclaration -> {
                // Function body is a new top-level scope (isTopLevel=true)
                stmt.body?.let { walkBodyForVarShadowing(it.statements, source, fileName, mutableListOf(), isTopLevel = true) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    // Method bodies are new top-level scopes
                    body?.let { walkBodyForVarShadowing(it.statements, source, fileName, mutableListOf(), isTopLevel = true) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                // Module block is a new top-level scope
                if (body is ModuleBlock) walkBodyForVarShadowing(body.statements, source, fileName, mutableListOf(), isTopLevel = true)
            }
            else -> {}
        }
    }

    /**
     * Check a var binding expression against the current outer scopes for TS2481.
     * [outerScopes]: strictly enclosing block scopes.
     * [extraScope]: the current block scope (checked only when inside a block, not at top level).
     * Emits TS2481 if the name exists in any of the checked scopes.
     */
    private fun checkVarDeclForShadowing(
        binding: Expression,
        source: String,
        fileName: String,
        outerScopes: MutableList<MutableSet<String>>,
        extraScope: MutableSet<String>? = null
    ) {
        when (binding) {
            is Identifier -> {
                val name = binding.text
                var found = false
                if (extraScope != null && name in extraScope) found = true
                if (!found) {
                    for (scope in outerScopes) {
                        if (name in scope) { found = true; break }
                    }
                }
                if (found) {
                    val start = binding.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot initialize outer scoped variable '$name' in the same scope as block scoped declaration '$name'.",
                        category = DiagnosticCategory.Error,
                        code = 2481,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = name.length,
                    ))
                }
            }
            is ObjectBindingPattern -> for (el in binding.elements) {
                if (el is BindingElement) checkVarDeclForShadowing(el.name, source, fileName, outerScopes, extraScope)
            }
            is ArrayBindingPattern -> for (el in binding.elements) {
                if (el is BindingElement) checkVarDeclForShadowing(el.name, source, fileName, outerScopes, extraScope)
            }
            else -> {}
        }
    }

    /**
     * TS1156: `const`/`let`/`type`/`interface` declarations can only be
     * declared inside a block. Fires when they appear as the single-statement
     * body of `if`/`else`/`while`/`do`/`for`/`for-in`/`for-of`.
     */
    private fun checkBlockScopedDeclarationsInSingleBody() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForBlockScopeViolations(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForBlockScopeViolations(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            walkBlockScopeInStatement(stmt, source, fileName)
        }
    }

    private fun walkBlockScopeInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is IfStatement -> {
                checkEmbeddedForBlockScope(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkEmbeddedForBlockScope(it, source, fileName) }
                // Also recurse into blocks
                if (stmt.thenStatement is Block) walkForBlockScopeViolations((stmt.thenStatement as Block).statements, source, fileName)
                stmt.elseStatement?.let { if (it is Block) walkForBlockScopeViolations((it as Block).statements, source, fileName) }
                // Recurse into non-block embedded (which may be labeled etc.)
                if (stmt.thenStatement !is Block) walkBlockScopeInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { if (it !is Block) walkBlockScopeInStatement(it, source, fileName) }
            }
            is WhileStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is Block -> walkForBlockScopeViolations(stmt.statements, source, fileName)
            is LabeledStatement -> walkBlockScopeInStatement(stmt.statement, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                val body = when (m) {
                    is MethodDeclaration -> m.body
                    is Constructor -> m.body
                    is GetAccessor -> m.body
                    is SetAccessor -> m.body
                    else -> null
                }
                body?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForBlockScopeViolations(body.statements, source, fileName)
            }
            is TryStatement -> {
                walkForBlockScopeViolations(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForBlockScopeViolations(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    walkForBlockScopeViolations(stmts2, source, fileName)
                }
            }
            else -> {}
        }
    }

    /**
     * Check if [embedded] is a block-scoped declaration (const/let/type/interface)
     * that's the direct single-statement body of a control flow statement.
     */
    private fun checkEmbeddedForBlockScope(embedded: Statement, source: String, fileName: String) {
        if (embedded is Block) return  // Block is fine
        // Strip through LabeledStatement layers to find the actual declaration
        var stmt: Statement = embedded
        while (stmt is LabeledStatement) stmt = stmt.statement
        when (stmt) {
            is VariableStatement -> {
                val keyword = stmt.declarationList.flags
                val kwName = when (keyword) {
                    SyntaxKind.ConstKeyword -> "const"
                    SyntaxKind.LetKeyword -> "let"
                    else -> return  // var is allowed
                }
                reportBlockScopeViolation(stmt, stmt.pos, source, fileName, kwName, useFullStmtSpan = true)
            }
            is TypeAliasDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameStart = stmt.name.pos
                val nameLen = stmt.name.text.length
                reportBlockScopeViolationAt(nameStart, nameLen, source, fileName, "type")
            }
            is InterfaceDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameStart = stmt.name.pos
                val nameLen = stmt.name.text.length
                reportBlockScopeViolationAt(nameStart, nameLen, source, fileName, "interface")
            }
            else -> {}
        }
    }

    private fun reportBlockScopeViolation(
        stmt: Statement, stmtPos: Int, source: String, fileName: String,
        kwName: String, useFullStmtSpan: Boolean
    ) {
        // start = position of keyword (const/let)
        var start = stmtPos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) start++
        val length = if (useFullStmtSpan) {
            // Span = entire statement text on the same line (up to `;`)
            // Find the `;` position
            var end = start
            while (end < source.length && source[end] != '\n' && source[end] != '\r') end++
            // Trim trailing whitespace
            while (end > start && source[end - 1].let { it == ' ' || it == '\t' || it == '\r' }) end--
            end - start
        } else {
            kwName.length
        }
        reportBlockScopeViolationAt(start, length, source, fileName, kwName)
    }

    private fun reportBlockScopeViolationAt(start: Int, length: Int, source: String, fileName: String, kwName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$kwName' declarations can only be declared inside a block.",
            category = DiagnosticCategory.Error,
            code = 1156,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Type assignability checking (TS2322)
    // -----------------------------------------------------------------------

    /**
     * Determine if the Type engine can safely compare source and target types.
     * Returns true when both types are concrete (non-any, non-error) and the
     * comparison won't produce false positives from incomplete resolution.
     */
    /**
     * 17.14b: True when `t` represents a CLASS instance shape — Type.Interface or
     * Type.Reference whose underlying symbol has the `Class` flag. Used by the
     * `canUseTypeEngine` exemption for class-instance vs class-instance comparison
     * (e.g. `interfaceX → classY<T,U>` for the `assignmentCompatability39-42` family).
     *
     * Restricted to Class (not Interface) on purpose: an interface target with an
     * explicit construct signature (`interface Constructor<T> { new(...): T }`) must
     * keep the existing skip — source-as-bare-class-identifier evaluates to the
     * instance type in our checker (no typeof-Class inference), so structural
     * comparison against `Constructor<B<bool>>` would FP-emit "missing prototype"
     * (regresses `genericInheritedDefaultConstructors_ts`).
     *
     * Excludes Type.Object that merely carries a class symbol via
     * `getTypeOfSymbolForTypeQuery` (those are constructor-side shapes for `typeof C`).
     */
    private fun isClassOrInterfaceInstanceType(t: Type): Boolean {
        return when (t) {
            is Type.Reference -> {
                val ts = t.target.symbol
                ts != null && ts.flags.hasAny(SymbolFlags.Class)
            }
            is Type.Interface -> {
                val ts = t.symbol
                ts != null && ts.flags.hasAny(SymbolFlags.Class)
            }
            else -> false
        }
    }

    private fun canUseTypeEngine(sourceType: Type, targetType: Type): Boolean {
        // Never compare when either side is unresolved
        if (sourceType === anyType || sourceType === errorType) return false
        if (targetType === anyType || targetType === errorType) return false
        // "Primitive-like" = intrinsic or literal types (string, number, boolean, "hello", 42, etc.)
        val sourceIsPrimitive = sourceType is Type.Intrinsic || sourceType is Type.StringLiteral ||
            sourceType is Type.NumberLiteral || sourceType is Type.BigIntLiteral
        val targetIsPrimitive = targetType is Type.Intrinsic || targetType is Type.StringLiteral ||
            targetType is Type.NumberLiteral || targetType is Type.BigIntLiteral
        val sourceIsNullish = sourceType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
        // null/undefined → anything non-error (strictNullChecks handling in relation engine)
        if (sourceIsNullish) return true
        // Primitive ↔ Primitive (intrinsic↔intrinsic, literal↔literal, literal↔intrinsic, etc.)
        if (sourceIsPrimitive && targetIsPrimitive) return true
        // Object/Interface/Reference → Primitive target (never assignable)
        if (sourceType is Type.Object && targetIsPrimitive) return true
        // Primitive → Object target (only for anonymous objects/type literals, not named interfaces)
        // Named interface/class targets need proper structural comparison to avoid FPs
        if (sourceIsPrimitive && targetType is Type.Object && targetType.symbol == null) return true
        // Union source → primitive target (safe: primitives don't need control flow narrowing)
        // Skip Union → Object/Interface targets since those often need narrowing we don't implement
        if (sourceType is Type.Union && targetIsPrimitive) {
            val hasNullish = sourceType.types.any { it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) }
            if (!hasNullish) return true
        }
        if (sourceType is Type.Intersection) return true
        // Anything → Union/Intersection target
        if (targetType is Type.Union || targetType is Type.Intersection) return true
        // Function→function: both sides have call signatures.
        // Resolve members lazily first — named interfaces may have unresolved call sigs.
        if (sourceType is Type.Object && targetType is Type.Object) {
            resolveStructuredTypeMembers(sourceType)
            resolveStructuredTypeMembers(targetType)
            if (!sourceType.callSignatures.isNullOrEmpty() &&
                !targetType.callSignatures.isNullOrEmpty()) return true
        }
        // Tuple targets: only safe when source is clearly incompatible (function/primitive)
        // Array→tuple needs contextual typing (not yet implemented) so skip those
        if (targetType is Type.Object && targetType.tupleElementTypes != null) {
            if (sourceIsPrimitive) return true
            if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty()) return true
        }
        // Tuple sources: safe to compare against primitive targets
        if (sourceType is Type.Object && sourceType.tupleElementTypes != null && targetIsPrimitive) return true
        // TypeParam targets (for generic constraint checking)
        if (sourceIsPrimitive && targetType is Type.TypeParam) return true
        // Primitive → named Object target (never structurally compatible)
        if (sourceIsPrimitive && targetType is Type.Object && targetType.symbol != null) return true
        // Object↔Object structural comparison — safe with recursive cycle detection (7.0).
        if (sourceType is Type.Object && targetType is Type.Object) {
            val sourceIsArray = isArrayLikeType(sourceType)
            // Array→tuple needs contextual typing — skip
            if (sourceIsArray && targetType.tupleElementTypes != null) return false
            // Skip types with unresolved type parameters (incomplete generic instantiation)
            if (hasUnresolvedTypeParams(sourceType) || hasUnresolvedTypeParams(targetType)) return false
            resolveStructuredTypeMembers(sourceType)
            resolveStructuredTypeMembers(targetType)
            // Skip class-instance vs constructor-type comparison (typeof C / new() => T).
            // EXCEPTION: when the relevant side IS a class/interface instance type
            // (Type.Interface, OR Type.Reference whose target carries Class/Interface flag),
            // `objectTypeRelatedTo`'s `isClassInstance`-style logic should run — so an
            // interface instance assigned to a generic class instance is a valid structural
            // comparison (assignmentCompatability39-42 family). The check explicitly excludes
            // Type.Object with a class symbol but no Interface kind (e.g. `typeof C` from
            // `getTypeOfSymbolForTypeQuery` — keep the existing skip there).
            val targetIsClassInstance = isClassOrInterfaceInstanceType(targetType)
            val sourceIsClassInstance = isClassOrInterfaceInstanceType(sourceType)
            if (sourceType.constructSignatures.isNullOrEmpty() &&
                !targetType.constructSignatures.isNullOrEmpty() && !targetIsClassInstance) return false
            if (!sourceType.constructSignatures.isNullOrEmpty() &&
                targetType.constructSignatures.isNullOrEmpty() && !sourceIsClassInstance) return false
            // Empty source object {} — only skip if target also has no required properties
            // (empty→non-empty should fail, empty→empty is trivially assignable)
            if (sourceType.symbol == null && sourceType.properties.isNullOrEmpty() &&
                sourceType.callSignatures.isNullOrEmpty() && sourceType.constructSignatures.isNullOrEmpty()) {
                if (targetType.properties.isNullOrEmpty()) return false
                // Target has properties — let the comparison through (will correctly fail)
            }
            // Skip when target has malformed members (empty name) from unresolved mapped types
            val targetProps = targetType.properties
            if (targetProps != null && targetProps.any { it.name.isEmpty() }) return false
            // Skip interface→interface where target extends source (narrowing scenario)
            if (sourceType is Type.Interface && targetType is Type.Interface) {
                val targetBases = targetType.baseTypes
                if (targetBases != null && targetBases.any { it === sourceType }) return false
            }
            return true
        }
        // TypeParam ↔ Object (for generic constraint checking)
        if (sourceIsPrimitive && targetType is Type.TypeParam) return true
        if (sourceType is Type.Object && targetType is Type.TypeParam) return true
        // B60.8: constrained TypeParam source → primitive target. Apparent type
        // (the constraint) is compared via structuredTypeRelatedTo. Narrow: only
        // when constraint exists AND is non-error/any — without that, apparent
        // type is {} and comparison would be unsound for primitive targets.
        if (sourceType is Type.TypeParam && targetIsPrimitive) {
            val cnstr = sourceType.constraint
            if (cnstr != null && cnstr !== errorType && cnstr !== anyType) return true
        }
        return false
    }

    /** Check if an Object type looks like an unresolved array type (empty after member resolution). */
    private fun isArrayLikeType(type: Type.Object): Boolean {
        // Array types from getArrayType() are currently empty Object() with no symbol
        // Real array types from TypeReference[Array<T>] have the globalArrayType symbol
        if (type.symbol?.name == "Array" || type.symbol?.name == "ReadonlyArray") return true
        // Tuple types with element types are OK — they have proper members
        if (type.tupleElementTypes != null) return false
        // If it's a Reference whose target is the global array, skip
        if (type is Type.Reference && type.target?.symbol?.name == "Array") return true
        return false
    }

    /** Check if a type's display name contains unresolved type parameters (e.g. "B<V>"). */
    private fun hasUnresolvedTypeParams(type: Type.Object): Boolean {
        if (type is Type.Reference) {
            // Check if any type argument is a TypeParam
            val args = type.resolvedTypeArguments
            if (args != null) {
                return args.any { it is Type.TypeParam }
            }
        }
        return false
    }

    private fun checkTypeAssignability() {
        val diagnosticsBefore = diagnostics.size
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val varTypes = mutableMapOf<String, String>()
            currentLocalTypes = mutableMapOf()
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            currentFlowGraph = result.flowGraph
            checkTypeAssignabilityInStatements(result.sourceFile.statements, source, fileName, varTypes, returnType = null, typeParams = emptySet())
            currentFlowGraph = null
        }
        // Post-filter: suppress TS2322 for null/undefined→NamedType when the named type
        // also has TS2304 (unresolved) or TS2314 (wrong type arg count) in the same file
        // Collect type names with errors per file: "$fileName" -> set of type names
        val errorTypeNames = mutableMapOf<String, MutableSet<String>>()
        for (d in diagnostics) {
            val fn = d.fileName ?: continue
            val msg = d.message ?: continue
            when (d.code) {
                2304 -> {
                    // "Cannot find name 'X'." → extract X
                    val match = Regex("Cannot find name '([^']+)'").find(msg)
                    match?.groupValues?.get(1)?.let { errorTypeNames.getOrPut(fn) { mutableSetOf() }.add(it) }
                }
                2314 -> {
                    // "Generic type 'X<T>' requires N type argument(s)." → extract X
                    val match = Regex("Generic type '([^<']+)").find(msg)
                    match?.groupValues?.get(1)?.let { errorTypeNames.getOrPut(fn) { mutableSetOf() }.add(it) }
                }
            }
        }
        if (errorTypeNames.isNotEmpty()) {
            val newDiags = diagnostics.filterIndexed { idx, d ->
                if (idx >= diagnosticsBefore && d.code == 2322) {
                    val fn = d.fileName
                    val msg = d.message ?: ""
                    // Extract target type name from "Type 'X' is not assignable to type 'Y'."
                    val targetMatch = Regex("not assignable to type '([^']+)'").find(msg)
                    val targetName = targetMatch?.groupValues?.get(1)
                    if (fn != null && targetName != null) {
                        val errorNames = errorTypeNames[fn]
                        // Also check base name (strip type args): "Two<number>" → "Two"
                        val baseName = targetName.substringBefore('<')
                        errorNames == null || (targetName !in errorNames && baseName !in errorNames)
                    } else true
                } else true
            }
            if (newDiags.size != diagnostics.size) {
                diagnostics.clear()
                diagnostics.addAll(newDiags)
            }
        }
        // Post-filter: suppress TS7030 at positions where TS2322 fires (bare return → undefined)
        val ts2322Positions = mutableSetOf<String>()
        for (d in diagnostics) {
            if (d.code == 2322) {
                ts2322Positions.add("${d.fileName}:${d.start}")
            }
        }
        if (ts2322Positions.isNotEmpty()) {
            val filtered = diagnostics.filter { d ->
                !(d.code == 7030 && "${d.fileName}:${d.start}" in ts2322Positions)
            }
            if (filtered.size != diagnostics.size) {
                diagnostics.clear()
                diagnostics.addAll(filtered)
            }
        }
    }

    private fun checkTypeAssignabilityInStatements(
        statements: List<Statement>, source: String, fileName: String,
        varTypes: MutableMap<String, String>, returnType: String?,
        typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkVarDeclAssignability(decl, source, fileName, varTypes, typeParams)
                        decl.initializer?.let { walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams) }
                    }
                }
                is ExpressionStatement -> {
                    checkAssignmentExpression(stmt.expression, source, fileName, varTypes, typeParams)
                    walkFunctionBodiesInExpr(stmt.expression, source, fileName, varTypes, typeParams)
                }
                is ReturnStatement -> {
                    if (returnType != null || returnTypeNode != null) {
                        checkReturnAssignability(stmt, returnType ?: "", source, fileName, varTypes, typeParams, returnTypeNode)
                    }
                    // 16.0: Recurse into assignment expressions inside return value
                    // to catch `return obj = { excess }` TS2353 patterns.
                    stmt.expression?.let { retExpr ->
                        if (retExpr is BinaryExpression && retExpr.operator == SyntaxKind.Equals) {
                            checkAssignmentExpression(retExpr, source, fileName, varTypes, typeParams)
                        }
                    }
                }
                is FunctionDeclaration -> {
                    checkFunctionBody(stmt.body, stmt.type, stmt.parameters, stmt.typeParameters, source, fileName, varTypes,
                        isAsync = ModifierFlag.Async in stmt.modifiers)
                }
                is Block -> checkTypeAssignabilityInStatements(stmt.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams, returnTypeNode)
                is IfStatement -> {
                    checkTypeAssignabilityInStmt(stmt.thenStatement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                    stmt.elseStatement?.let { checkTypeAssignabilityInStmt(it, source, fileName, varTypes, returnType, typeParams, returnTypeNode) }
                }
                is ForStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ForInStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ForOfStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is WhileStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is DoStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ClassDeclaration -> {
                    val classTypeParams = collectTypeParamNames(stmt.typeParameters)
                    // B55.2: push class TypeParam declarations into the scope map so
                    // methods/getters/setters can reference them for TS2208 related info.
                    val savedClassTypeParamDecls = currentTypeParamDecls
                    if (!stmt.typeParameters.isNullOrEmpty()) {
                        val merged = savedClassTypeParamDecls.toMutableMap()
                        for (tp in stmt.typeParameters!!) merged[tp.name.text] = tp
                        currentTypeParamDecls = merged
                    }
                    try {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                // B85.1b: Populate `this.X` types from class property declarations
                                // into the local varTypes map only (NOT currentLocalTypes), so method
                                // bodies can resolve `this._foo` chains via the lightweight type map.
                                // Mirror of Constructor (47633) and SetAccessor (47691) varTypes push.
                                // Skip the currentLocalTypes push deliberately — Constructor/SetAccessor
                                // bodies legitimately assign through this.X, but method bodies broadcast
                                // those types to many checker walkers and would cause TS2322/TS2339 FPs.
                                // Net-zero expected; unblocks B85.1d (element-access TS2322).
                                val methodTypes = varTypes.toMutableMap()
                                for (m in stmt.members) {
                                    if (m is PropertyDeclaration) {
                                        val propType = m.type?.let { resolveSimpleTypeName(it) }
                                        val propName = (m.name as? Identifier)?.text
                                        if (propType != null && propName != null) {
                                            methodTypes["this.$propName"] = propType
                                        }
                                    }
                                }
                                checkFunctionBody(member.body, member.type, member.parameters, member.typeParameters, source, fileName, methodTypes, classTypeParams,
                                    isAsync = ModifierFlag.Async in member.modifiers)
                            }
                            is Constructor -> member.body?.let { body ->
                                val ctorTypes = varTypes.toMutableMap()
                                val savedLocalTypes = currentLocalTypes
                                currentLocalTypes = currentLocalTypes.toMutableMap()
                                // Populate this.prop types from class property declarations
                                for (m in stmt.members) {
                                    if (m is PropertyDeclaration) {
                                        val propType = m.type?.let { resolveSimpleTypeName(it) }
                                        val propName = (m.name as? Identifier)?.text
                                        if (propType != null && propName != null) {
                                            ctorTypes["this.$propName"] = propType
                                        }
                                        // Also populate Type engine local type map for this.prop
                                        if (propName != null && m.type != null) {
                                            try {
                                                val resolvedType = getTypeFromTypeNode(m.type!!)
                                                if (resolvedType !== anyType && resolvedType !== errorType) {
                                                    currentLocalTypes["this.$propName"] = resolvedType
                                                }
                                            } catch (_: StackOverflowError) {}
                                        }
                                    }
                                }
                                // Also add constructor parameter types
                                for (p in member.parameters) {
                                    val pName = (p.name as? Identifier)?.text
                                    val pType = p.type?.let { resolveSimpleTypeName(it) }
                                    if (pName != null && pType != null) ctorTypes[pName] = pType
                                    // Also populate Type engine local type map
                                    if (pName != null && p.type != null) {
                                        try {
                                            val resolvedType = getTypeFromTypeNode(p.type!!)
                                            if (resolvedType !== anyType && resolvedType !== errorType) {
                                                currentLocalTypes[pName] = resolvedType
                                            }
                                        } catch (_: StackOverflowError) {}
                                    }
                                }
                                checkTypeAssignabilityInStatements(body.statements, source, fileName, ctorTypes, returnType = null, classTypeParams)
                                currentLocalTypes = savedLocalTypes
                            }
                            is GetAccessor -> {
                                // B63.5: When a getter has no return-type annotation, but the
                                // class has a paired setter for the same property with a typed
                                // param, use the setter's param type as the effective return
                                // type so `return X` is checked against it. Matches TypeScript's
                                // accessor-pair return-type bridging.
                                val effectiveReturnType = member.type ?: run {
                                    val getterName = (member.name as? Identifier)?.text
                                    if (getterName == null) null else {
                                        val pairedSetter = stmt.members.firstOrNull { sm ->
                                            sm is SetAccessor && (sm.name as? Identifier)?.text == getterName
                                        } as? SetAccessor
                                        pairedSetter?.parameters?.firstOrNull()?.type
                                    }
                                }
                                checkFunctionBody(member.body, effectiveReturnType, emptyList(), null, source, fileName, varTypes, classTypeParams)
                            }
                            is SetAccessor -> {
                                // B54.1: SetAccessor bodies were previously falling into the
                                // `else -> {}` branch, so `this.X = v` assignments inside
                                // setters were not checked at all. Mirror the Constructor
                                // handler pattern: populate `this.X` types from class properties
                                // and setter parameters, then walk body for assignability.
                                member.body?.let { body ->
                                    val setterTypes = varTypes.toMutableMap()
                                    val savedLocalTypes = currentLocalTypes
                                    currentLocalTypes = currentLocalTypes.toMutableMap()
                                    for (m in stmt.members) {
                                        if (m is PropertyDeclaration) {
                                            val propType = m.type?.let { resolveSimpleTypeName(it) }
                                            val propName = (m.name as? Identifier)?.text
                                            if (propType != null && propName != null) {
                                                setterTypes["this.$propName"] = propType
                                            }
                                            if (propName != null && m.type != null) {
                                                try {
                                                    val resolvedType = getTypeFromTypeNode(m.type!!)
                                                    if (resolvedType !== anyType && resolvedType !== errorType) {
                                                        currentLocalTypes["this.$propName"] = resolvedType
                                                    }
                                                } catch (_: StackOverflowError) {}
                                            }
                                        }
                                    }
                                    // B63.5: When setter's param has no annotation, look up
                                    // paired getter's return-type annotation and use it as the
                                    // param type. Matches TypeScript's accessor-pair param-type
                                    // bridging.
                                    val setterName = (member.name as? Identifier)?.text
                                    val pairedGetterType: TypeNode? = if (setterName != null) {
                                        val pg = stmt.members.firstOrNull { sm ->
                                            sm is GetAccessor && (sm.name as? Identifier)?.text == setterName
                                        } as? GetAccessor
                                        pg?.type
                                    } else null
                                    for (p in member.parameters) {
                                        val pName = (p.name as? Identifier)?.text
                                        val effectiveParamType = p.type ?: pairedGetterType
                                        val pType = effectiveParamType?.let { resolveSimpleTypeName(it) }
                                        if (pName != null && pType != null) setterTypes[pName] = pType
                                        if (pName != null && effectiveParamType != null) {
                                            try {
                                                val resolvedType = getTypeFromTypeNode(effectiveParamType)
                                                if (resolvedType !== anyType && resolvedType !== errorType) {
                                                    currentLocalTypes[pName] = resolvedType
                                                }
                                            } catch (_: StackOverflowError) {}
                                        }
                                    }
                                    checkTypeAssignabilityInStatements(body.statements, source, fileName, setterTypes, returnType = null, classTypeParams)
                                    currentLocalTypes = savedLocalTypes
                                }
                            }
                            is PropertyDeclaration -> {
                                val init = member.initializer
                                val typeAnnotation = member.type
                                if (init != null && typeAnnotation != null) {
                                    val propName = member.name
                                    if (propName is Identifier) {
                                        checkPropertyInitAssignability(propName, typeAnnotation, init, source, fileName, classTypeParams)
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                    } finally {
                        currentTypeParamDecls = savedClassTypeParamDecls
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    // Push the namespace symbol onto the inference stack so identifier /
                    // type-name lookups inside the body can resolve namespace-internal
                    // declarations via [lookupTypeSymbolInInferenceNamespace] /
                    // [lookupInInferenceNamespace]. Without this, an annotation like
                    // `var t: IStateToken[]` inside `namespace M { interface IStateToken {} }`
                    // resolves IStateToken to errorType (since IStateToken isn't in
                    // file-locals or globals), which then masks downstream TS2322s
                    // because errorType has TypeFlags.Any in `isSimpleTypeRelatedTo`.
                    val nameNode = stmt.name
                    val moduleSymbol = if (nameNode is Identifier) {
                        currentFileLocals?.get(nameNode.text) ?: globals[nameNode.text]
                    } else null
                    val pushed = if (moduleSymbol != null && moduleSymbol.flags.hasAny(SymbolFlags.Module)) {
                        inferenceNamespaceStack.addLast(moduleSymbol)
                        true
                    } else false
                    try {
                        if (body is ModuleBlock) checkTypeAssignabilityInStatements(body.statements, source, fileName, varTypes.toMutableMap(), returnType = null, emptySet())
                    } finally {
                        if (pushed) inferenceNamespaceStack.removeLast()
                    }
                }
                is TryStatement -> {
                    checkTypeAssignabilityInStatements(stmt.tryBlock.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                    stmt.catchClause?.block?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                    stmt.finallyBlock?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                }
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                            is DefaultClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                            else -> {}
                        }
                    }
                }
                is LabeledStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                else -> {}
            }
        }
    }

    private fun collectTypeParamNames(typeParameters: List<TypeParameter>?): Set<String> {
        if (typeParameters == null || typeParameters.isEmpty()) return emptySet()
        return typeParameters.mapNotNull { it.name.text }.toSet()
    }

    private fun checkFunctionBody(
        body: Block?, returnTypeNode: TypeNode?, parameters: List<Parameter>,
        funcTypeParams: List<TypeParameter>?,
        source: String, fileName: String, varTypes: MutableMap<String, String>,
        outerTypeParams: Set<String> = emptySet(),
        isAsync: Boolean = false,
    ) {
        body?.let {
            val innerTypes = varTypes.toMutableMap()
            // Save outer local types and create inner scope copy
            val savedLocalTypes = currentLocalTypes
            currentLocalTypes = currentLocalTypes.toMutableMap()
            // 16.4dp: Non-arrow function body — `arguments` binds to the implicit
            // IArguments parameter here. `checkAssignmentExpression` consults this
            // flag to emit TS2322 for `arguments = <primitive>`.
            val savedInFunc = inNonArrowFunctionBody
            inNonArrowFunctionBody = true
            val savedAsync = inAsyncFunctionBody
            inAsyncFunctionBody = isAsync
            // B55.2: populate TypeParam decls for the current scope so emitTS2322
            // can emit TS2208 related info pointing back to the source TypeParam.
            val savedTypeParamDecls = currentTypeParamDecls
            if (!funcTypeParams.isNullOrEmpty()) {
                val merged = savedTypeParamDecls.toMutableMap()
                for (tp in funcTypeParams) merged[tp.name.text] = tp
                currentTypeParamDecls = merged
            }
            // B60.1: push function's TypeParams onto currentTypeParamScope before
            // resolving parameter type annotations. Without this, names like `U` in
            // `T1<U>` resolve to errorType, which makes the generic-alias substitution
            // gate (Checker.kt:~41755 `if (resolvedArgs.none { it === errorType })`)
            // skip substitution — falling back to the un-substituted alias body and
            // losing the alias-display registration. Fixes the OUTER-tuple alias
            // display for tests like `inferFromNestedSameShapeTuple_ts` where
            // `function qq<U>(x: T1<U>)` should display `x`'s type as `T1<U>` not
            // `[number, T1<{ x: any; }>]`. TypeParam instances interned via
            // typeParamInternCache by AST position so they match what getTypeOfFunction
            // produces.
            val savedTypeParamScope = currentTypeParamScope
            if (!funcTypeParams.isNullOrEmpty()) {
                val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                // Two-pass: (1) intern all TypeParams and put in scope BEFORE resolving
                // constraints (constraints may reference other TypeParams of the same sig).
                // (2) resolve constraint/default with scope active.
                val newTps = mutableListOf<Pair<TypeParameter, Type.TypeParam>>()
                for (tp in funcTypeParams) {
                    val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                        val p = Type.TypeParam()
                        p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                        p
                    }
                    scope[tp.name.text] = typeParam
                    newTps.add(tp to typeParam)
                }
                currentTypeParamScope = scope
                for ((tp, typeParam) in newTps) {
                    if (typeParam.constraint == null) {
                        tp.constraint?.let { typeParam.constraint = getTypeFromTypeNode(it) }
                    }
                    if (typeParam.default == null) {
                        tp.default?.let { typeParam.default = getTypeFromTypeNode(it) }
                    }
                }
            }
            try {
                for (param in parameters) {
                    val paramType = param.type
                    val paramName = param.name
                    // 16.4ei: `function fst({ s } = t) {}` where t has nullable-union type —
                    // destructuring pattern as parameter name with a default initializer.
                    if (paramName is ObjectBindingPattern && param.initializer != null) {
                        checkDestructuringFromNullableUnion(paramName, param.initializer, source, fileName)
                    }
                    if (paramType != null && paramName is Identifier) {
                        // Rest parameter with clearly-non-array type annotation: TS2370 fires
                        // but the parameter's runtime type is effectively any[] — skip local
                        // type so downstream checks (TS2339 element access, TS2345 argument)
                        // treat it as any[].
                        if (param.dotDotDotToken && nonArrayKeywordText(paramType) != null) continue
                        val t = resolveSimpleTypeName(paramType)
                        if (t != null) innerTypes[paramName.text] = t
                        // Also populate Type engine local type map
                        try {
                            val resolvedType = getTypeFromTypeNode(paramType)
                            if (resolvedType !== anyType && resolvedType !== errorType) {
                                // B85.1a: optional param `value?: T` (without initializer) has effective
                                // type `T | undefined`. Mirrors `resolveUncalledParamType` (Checker.kt:25081).
                                val effectiveType = if (param.questionToken && param.initializer == null) {
                                    getUnionType(listOf(resolvedType, undefinedType))
                                } else resolvedType
                                currentLocalTypes[paramName.text] = effectiveType
                            }
                        } catch (_: StackOverflowError) { /* circular type */ }
                    }
                }
            } finally {
                currentTypeParamScope = savedTypeParamScope
            }
            val retType = if (returnTypeNode != null) resolveSimpleTypeName(returnTypeNode) else null
            val allTypeParams = outerTypeParams + collectTypeParamNames(funcTypeParams)
            try {
                checkTypeAssignabilityInStatements(it.statements, source, fileName, innerTypes, retType, allTypeParams, returnTypeNode)
            } finally {
                inNonArrowFunctionBody = savedInFunc
                inAsyncFunctionBody = savedAsync
                currentTypeParamDecls = savedTypeParamDecls
            }
            // Restore outer local types
            currentLocalTypes = savedLocalTypes
        }
    }

    /**
     * 16.4dv: Recursively walk an expression and invoke `checkFunctionBody` on any
     * FunctionExpression / ArrowFunction (with Block body) found. This lets TS2322
     * (and the other assignment-style checks) fire inside function bodies that
     * appear as array/object literal members, call arguments, etc. — contexts that
     * the statement-scoped walker doesn't otherwise descend into.
     *
     * Walked containers: ArrayLiteral, ObjectLiteral property initializers,
     * ParenthesizedExpression, BinaryExpression, CallExpression args,
     * NewExpression args, ConditionalExpression, SpreadElement.
     */
    private fun walkFunctionBodiesInExpr(
        expr: Expression, source: String, fileName: String,
        varTypes: MutableMap<String, String>, typeParams: Set<String>
    ) {
        when (expr) {
            is FunctionExpression -> {
                checkFunctionBody(expr.body, expr.type, expr.parameters, expr.typeParameters, source, fileName, varTypes, typeParams,
                    isAsync = ModifierFlag.Async in expr.modifiers)
            }
            is ArrowFunction -> {
                (expr.body as? Block)?.let { body ->
                    checkFunctionBody(body, expr.type, expr.parameters, expr.typeParameters, source, fileName, varTypes, typeParams,
                        isAsync = ModifierFlag.Async in expr.modifiers)
                }
            }
            is ArrayLiteralExpression -> expr.elements.forEach {
                walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams)
            }
            is ObjectLiteralExpression -> expr.properties.forEach { prop ->
                when (prop) {
                    is PropertyAssignment -> walkFunctionBodiesInExpr(prop.initializer, source, fileName, varTypes, typeParams)
                    is SpreadAssignment -> walkFunctionBodiesInExpr(prop.expression, source, fileName, varTypes, typeParams)
                    else -> {}
                }
            }
            is ParenthesizedExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is AsExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is TypeAssertionExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is SatisfiesExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is NonNullExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is BinaryExpression -> {
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                walkFunctionBodiesInExpr(cur, source, fileName, varTypes, typeParams)
                while (rightStack.isNotEmpty()) walkFunctionBodiesInExpr(rightStack.removeLast(), source, fileName, varTypes, typeParams)
            }
            is CallExpression -> {
                walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
                expr.arguments.forEach {
                    walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams)
                }
            }
            is NewExpression -> {
                walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
                expr.arguments?.forEach {
                    walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams)
                }
            }
            is ConditionalExpression -> {
                walkFunctionBodiesInExpr(expr.condition, source, fileName, varTypes, typeParams)
                walkFunctionBodiesInExpr(expr.whenTrue, source, fileName, varTypes, typeParams)
                walkFunctionBodiesInExpr(expr.whenFalse, source, fileName, varTypes, typeParams)
            }
            is SpreadElement -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is AwaitExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is YieldExpression -> expr.expression?.let { walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams) }
            is VoidExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is DeleteExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is TypeOfExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is PropertyAccessExpression -> walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
            is ElementAccessExpression -> {
                walkFunctionBodiesInExpr(expr.expression, source, fileName, varTypes, typeParams)
                walkFunctionBodiesInExpr(expr.argumentExpression, source, fileName, varTypes, typeParams)
            }
            is PrefixUnaryExpression -> walkFunctionBodiesInExpr(expr.operand, source, fileName, varTypes, typeParams)
            is PostfixUnaryExpression -> walkFunctionBodiesInExpr(expr.operand, source, fileName, varTypes, typeParams)
            is TemplateExpression -> expr.templateSpans.forEach {
                walkFunctionBodiesInExpr(it.expression, source, fileName, varTypes, typeParams)
            }
            is TaggedTemplateExpression -> {
                walkFunctionBodiesInExpr(expr.tag, source, fileName, varTypes, typeParams)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkFunctionBodiesInExpr(it.expression, source, fileName, varTypes, typeParams)
                }
            }
            is CommaListExpression -> expr.elements.forEach {
                walkFunctionBodiesInExpr(it, source, fileName, varTypes, typeParams)
            }
            else -> {}
        }
    }

    private fun checkTypeAssignabilityInStmt(
        stmt: Statement, source: String, fileName: String,
        varTypes: MutableMap<String, String>, returnType: String?,
        typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        when (stmt) {
            is Block -> checkTypeAssignabilityInStatements(stmt.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams, returnTypeNode)
            is ExpressionStatement -> checkAssignmentExpression(stmt.expression, source, fileName, varTypes, typeParams)
            is ReturnStatement -> {
                if (returnType != null || returnTypeNode != null) checkReturnAssignability(stmt, returnType ?: "", source, fileName, varTypes, typeParams, returnTypeNode)
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkVarDeclAssignability(decl, source, fileName, varTypes, typeParams)
                }
            }
            is IfStatement -> {
                // Apply control flow narrowing in then-branch
                val narrowed = extractNullNarrowing(stmt.expression)
                if (narrowed != null) {
                    val savedLocalTypes = currentLocalTypes
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    val (varName, narrowedType) = narrowed
                    currentLocalTypes[varName] = narrowedType
                    checkTypeAssignabilityInStmt(stmt.thenStatement, source, fileName, varTypes, returnType, typeParams)
                    currentLocalTypes = savedLocalTypes
                } else {
                    checkTypeAssignabilityInStmt(stmt.thenStatement, source, fileName, varTypes, returnType, typeParams)
                }
                stmt.elseStatement?.let { checkTypeAssignabilityInStmt(it, source, fileName, varTypes, returnType, typeParams) }
            }
            is ForStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is ForInStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is ForOfStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is WhileStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is DoStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                        is DefaultClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkTypeAssignabilityInStatements(stmt.tryBlock.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                stmt.catchClause?.block?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                stmt.finallyBlock?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
            }
            is LabeledStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            else -> {}
        }
    }

    /**
     * Extract null/undefined narrowing from an if-condition.
     * Handles: `x !== null`, `x != null`, `x !== undefined`, `x != undefined`,
     * `null !== x`, `null != x`, `typeof x === "string"`, truthiness `if (x)`.
     * Returns (varName, narrowedType) or null if no narrowing applicable.
     */
    private fun extractNullNarrowing(expr: Expression): Pair<String, Type>? {
        // Handle `x !== null`, `x != null`, `x !== undefined`, `x != undefined`
        if (expr is BinaryExpression) {
            val op = expr.operator
            if (op == SyntaxKind.ExclamationEquals || op == SyntaxKind.ExclamationEqualsEquals) {
                val (varExpr, nullExpr) = when {
                    expr.right is Identifier && ((expr.right as Identifier).text == "null" || (expr.right as Identifier).text == "undefined") ->
                        expr.left to expr.right
                    expr.left is Identifier && ((expr.left as Identifier).text == "null" || (expr.left as Identifier).text == "undefined") ->
                        expr.right to expr.left
                    else -> return null
                }
                val varName = (varExpr as? Identifier)?.text ?: return null
                val nullName = (nullExpr as Identifier).text
                val varType = currentLocalTypes[varName] ?: return null
                if (varType !is Type.Union) return null
                // Remove null and/or undefined from the union
                val isLooseEquality = op == SyntaxKind.ExclamationEquals
                val filtered = varType.types.filter { t ->
                    when {
                        nullName == "null" && isLooseEquality -> !t.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
                        nullName == "null" -> !t.flags.hasAny(TypeFlags.Null)
                        nullName == "undefined" && isLooseEquality -> !t.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
                        nullName == "undefined" -> !t.flags.hasAny(TypeFlags.Undefined)
                        else -> true
                    }
                }
                return when {
                    filtered.isEmpty() -> null
                    filtered.size == 1 -> varName to filtered[0]
                    else -> varName to getUnionType(filtered)
                }
            }
        }
        // Handle `typeof x === "string"` (and !==)
        if (expr is BinaryExpression) {
            val op = expr.operator
            if (op == SyntaxKind.EqualsEqualsEquals || op == SyntaxKind.ExclamationEqualsEquals) {
                val (typeofExpr, litExpr) = when {
                    expr.left is TypeOfExpression && expr.right is StringLiteralNode -> expr.left to expr.right
                    expr.right is TypeOfExpression && expr.left is StringLiteralNode -> expr.right to expr.left
                    else -> null to null
                }
                if (typeofExpr is TypeOfExpression && litExpr is StringLiteralNode) {
                    val varId = typeofExpr.expression as? Identifier ?: return null
                    val varName = varId.text
                    val typeGuard = litExpr.text
                    // For === checks, narrow to the typeof type in the then-branch
                    if (op == SyntaxKind.EqualsEqualsEquals) {
                        val narrowedType = typeofTypeGuardToType(typeGuard) ?: return null
                        return varName to narrowedType
                    }
                    // For !== checks, narrow by removing the typeof type in the then-branch
                    if (op == SyntaxKind.ExclamationEqualsEquals) {
                        val varType = currentLocalTypes[varName] ?: return null
                        if (varType !is Type.Union) return null
                        val guardFlags = typeofTypeGuardFlags(typeGuard) ?: return null
                        val filtered = varType.types.filter { !it.flags.hasAny(guardFlags) }
                        return when {
                            filtered.isEmpty() -> null
                            filtered.size == 1 -> varName to filtered[0]
                            else -> varName to getUnionType(filtered)
                        }
                    }
                }
            }
        }
        // Handle truthiness: `if (x)` → narrow by removing null/undefined
        if (expr is Identifier) {
            val varName = expr.text
            val varType = currentLocalTypes[varName] ?: return null
            if (varType !is Type.Union) return null
            val filtered = varType.types.filter { !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) }
            return when {
                filtered.isEmpty() || filtered.size == varType.types.size -> null
                filtered.size == 1 -> varName to filtered[0]
                else -> varName to getUnionType(filtered)
            }
        }
        return null
    }

    /** Map typeof type guard string to the corresponding Type. */
    private fun typeofTypeGuardToType(guard: String): Type? {
        return when (guard) {
            "string" -> stringType
            "number" -> numberType
            "boolean" -> booleanType
            "symbol" -> esSymbolType
            "bigint" -> bigintType
            "undefined" -> undefinedType
            "function" -> anyType // function type — too broad to narrow precisely
            "object" -> anyType // object type — too broad to narrow precisely
            else -> null
        }
    }

    /** Map typeof type guard string to TypeFlags for removal from a union. */
    private fun typeofTypeGuardFlags(guard: String): TypeFlags? {
        return when (guard) {
            "string" -> TypeFlags.StringLike
            "number" -> TypeFlags.NumberLike
            "boolean" -> TypeFlags.BooleanLike
            "symbol" -> TypeFlags.ESSymbol or TypeFlags.UniqueESSymbol
            "bigint" -> TypeFlags.BigIntLike
            "undefined" -> TypeFlags.Undefined
            "function" -> TypeFlags.None // can't reliably identify function types by flags
            "object" -> TypeFlags.None // can't reliably identify object types by flags
            else -> null
        }
    }

    private fun checkVarDeclAssignability(
        decl: VariableDeclaration, source: String, fileName: String,
        varTypes: MutableMap<String, String>, typeParams: Set<String>
    ) {
        val name = decl.name
        if (name is ObjectBindingPattern) {
            checkDestructuringFromNullableUnion(name, decl.initializer, source, fileName)
            checkDestructuringPrivateAccess(name, decl.initializer, source, fileName)
        }
        if (name !is Identifier) return

        // For unannotated variables with initializers, infer and store the type
        // in currentLocalTypes so downstream references can resolve it.
        // Do NOT change getTypeOfVariableOrProperty (causes TS2403 FPs).
        val typeAnnotation = decl.type
        if (typeAnnotation == null) {
            val init = decl.initializer ?: return
            try {
                val inferred = getTypeOfExpression(init)
                // 16.0: Allow void from explicit super()/CallExpression — for super(...)
                // returning void, we want `x = 5` later to fire TS2322. Filter void
                // only when source is null/undefined identifier (already handled).
                val isFromCall = init is CallExpression
                if (inferred !== anyType && inferred !== errorType &&
                    !inferred.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
                    (isFromCall || !inferred.flags.hasAny(TypeFlags.Void))) {
                    // Widen literal types: 42 → number, "hello" → string
                    val widened = when (inferred) {
                        is Type.StringLiteral -> stringType
                        is Type.NumberLiteral -> numberType
                        is Type.BigIntLiteral -> bigintType
                        trueType, falseType -> booleanType
                        else -> inferred
                    }
                    currentLocalTypes[name.text] = widened
                }
            } catch (_: StackOverflowError) {}
            return
        }

        // Maintain old varTypes tracking for checkAssignmentExpression/checkReturnAssignability
        val declaredTypeStr = resolveSimpleTypeName(typeAnnotation)
        if (declaredTypeStr != null) varTypes[name.text] = declaredTypeStr

        // Populate local type map for Type engine identifier resolution.
        // First-decl wins: when multiple declarations of the same name exist
        // (e.g. `var x: T;` followed by `declare var x: T;`), keep the FIRST
        // resolved annotation. Matches the Binder's valueDeclaration semantics
        // (set on first creation, never overwritten — see Binder.kt:355). Without
        // first-wins, downstream "declared here" hints (TS6500/TS2728) point to
        // the LATER declaration's resolved Type.Object copy instead of the source
        // of truth.
        try {
            if (currentLocalTypes[name.text] == null) {
                val resolvedVarType = getTypeFromTypeNode(typeAnnotation)
                if (resolvedVarType !== anyType && resolvedVarType !== errorType) {
                    currentLocalTypes[name.text] = resolvedVarType
                }
            }
        } catch (_: StackOverflowError) { /* circular type */ }

        val init = decl.initializer ?: return

        // `null!` / `undefined!` (NonNullExpression of a literal null/undefined) is
        // commonly used as a "trust me" cast under strictNullChecks. The non-null
        // assertion makes the value satisfy any target type. Skip the assignability
        // check for this exact shape.
        if (init is NonNullExpression) {
            val inner = init.expression
            val isNullishLit = (inner is Identifier && (inner.text == "null" || inner.text == "undefined"))
            if (isNullishLit) return
        }

        // B85.3: Narrow shape for `aliasUsageInOrExpression`-style tests:
        // `var f: { x: I } = TypeAssertion ? { x: moduleA } : null` where moduleA
        // is an `import = require("./Y")` alias to another file. The expected
        // TS2322 displays the source as `{ x: typeof import("Y"); } | null`,
        // which requires structural ternary→union resolution + module-alias
        // qualification. Existing infra (canUseTypeEngine, propertiesRelatedTo)
        // either passes (because moduleA resolves to anyType) or doesn't emit
        // the expected display. This narrow pattern emits the diagnostic
        // directly when the shape matches.
        if (init is ConditionalExpression && typeAnnotation is TypeLiteral) {
            val whenFalse = init.whenFalse
            val isNullBranch = whenFalse is Identifier && whenFalse.text == "null"
            val whenTrue = init.whenTrue
            if (isNullBranch && whenTrue is ObjectLiteralExpression) {
                // Match each PropertyAssignment in the object literal against the
                // corresponding PropertyDeclaration in the type literal. If at
                // least one PropertyAssignment's value is a module-alias Identifier,
                // emit the qualified display.
                val olProps = whenTrue.properties.filterIsInstance<PropertyAssignment>()
                val tlProps = typeAnnotation.members.filterIsInstance<PropertyDeclaration>()
                if (olProps.isNotEmpty() && tlProps.isNotEmpty()) {
                    val propParts = mutableListOf<String>()
                    var anyModuleAlias = false
                    var matched = true
                    for (tlProp in tlProps) {
                        val tlName = (tlProp.name as? Identifier)?.text ?: run { matched = false; break }
                        val olProp = olProps.firstOrNull { (it.name as? Identifier)?.text == tlName } ?: run { matched = false; break }
                        val olValue = olProp.initializer
                        val modName = if (olValue is Identifier) tryGetModuleImportNameForExpr(olValue) else null
                        if (modName != null) {
                            anyModuleAlias = true
                            propParts.add("$tlName: typeof import(\"$modName\");")
                        } else {
                            // Fall back to the value's primitive display if simple.
                            val vt = try { getTypeOfExpression(olValue) } catch (_: Throwable) { null }
                            if (vt == null || vt === anyType || vt === errorType) { matched = false; break }
                            propParts.add("$tlName: ${typeToString(getWidenedLiteralType(vt))};")
                        }
                    }
                    if (matched && anyModuleAlias) {
                        val targetDisplay = formatTypeForDisplay(typeAnnotation) ?: run {
                            // Build manual `{ x: IFace; }` shape
                            val parts = tlProps.mapNotNull { tlProp ->
                                val tlName = (tlProp.name as? Identifier)?.text ?: return@mapNotNull null
                                val tlTypeDisplay = tlProp.type?.let { formatTypeForDisplay(it) } ?: return@mapNotNull null
                                "$tlName: $tlTypeDisplay;"
                            }
                            if (parts.size != tlProps.size) null else "{ ${parts.joinToString(" ")} }"
                        }
                        if (targetDisplay != null) {
                            val sourceDisplay = "{ ${propParts.joinToString(" ")} } | null"
                            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                            val chain = mutableListOf<String>()
                            chain.add("  Type 'null' is not assignable to type '$targetDisplay'.")
                            diagnostics.add(Diagnostic(
                                message = "Type '$sourceDisplay' is not assignable to type '$targetDisplay'.",
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = name.pos,
                                length = name.text.length,
                                messageChain = chain,
                            ))
                            // Don't `return` — let the existing TS2352 / TS2873 walkers fire
                            // on the condition expression (those are handled elsewhere).
                        }
                    }
                }
            }
        }

        // Use the Type-based engine (Phase 4) for clear-cut cases
        try {
            val targetType = getTypeFromTypeNode(typeAnnotation)
            // Class-Identifier-as-value with construct-sig target — `const foo: { new(): Foo } = Foo`.
            // canUseTypeEngine skips class-instance-vs-constructor comparisons, so this case
            // would otherwise fall through to the string fallback (no chain). Display the
            // source as `typeof X` and emit a construct-signature mismatch elaboration.
            if (init is Identifier &&
                targetType is Type.Object &&
                !targetType.constructSignatures.isNullOrEmpty()
            ) {
                val initSym = currentFileLocals?.get(init.text) ?: globals[init.text]
                if (initSym != null && initSym.flags.hasAny(SymbolFlags.Class) &&
                    !initSym.flags.hasAny(SymbolFlags.Variable)
                ) {
                    val srcCtorType = buildClassValueConstructorTypeForDisplay(initSym)
                    if (srcCtorType != null) {
                        val sourceSig = srcCtorType.constructSignatures!!.first()
                        val targetSig = targetType.constructSignatures!!.first()
                        val ok = signatureRelatedTo(sourceSig, targetSig, assignableRelation)
                        if (!ok) {
                            val displaySource = "typeof ${initSym.name}"
                            val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                            val chain = getConstructMismatchElaboration(srcCtorType, targetType)
                            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = name.pos,
                                length = name.text.length,
                                messageChain = chain,
                            ))
                            return
                        }
                    }
                }
            }
            // Set contextual type for function expression parameter inference
            val savedContextual = contextualType
            if (targetType is Type.Object && (init is ArrowFunction || init is FunctionExpression)) {
                contextualType = targetType
            }
            // 17.66: contextual literal preservation. When the target type contains
            // literal types (e.g. `"x" | "y"`, `keyof typeof obj`), and the init is
            // a literal-typed expression (string/number/bigint/template literal,
            // true/false, or unary-minus on a numeric), preserve the literal type
            // instead of widening to the primitive. This mirrors TypeScript's
            // bidirectional contextual-typing rule and produces the correct source
            // display for TS2322 (`Type '"z"'` vs `Type 'string'`).
            val rawSourceTypeRaw = if (propTypeContainsLiteral(targetType)) {
                literalTypeOfExpression(init) ?: getTypeOfExpression(init)
            } else {
                getTypeOfExpression(init)
            }
            contextualType = savedContextual
            // 17.43: contextual literal preservation — when init is a generic
            // call whose substituted return type contains a widened-string/
            // number/bigint property and the var-decl's annotation has a
            // literal-typed property at the same name, recover the literal
            // type from the original arg AST. Mirrors TypeScript's contextual-
            // type-aware widening rule. No-op for non-CallExpression inits or
            // non-matching shapes.
            val rawSourceType = applyContextualLiteralPreservation(rawSourceTypeRaw, targetType, init)
            // Phase 17 / Blocker #1 step 2: narrow the source type via flow graph
            // when the target is a primitive-shaped type (never, intrinsic, or
            // a literal). Object/Interface/Reference targets still use the raw
            // type — narrowing into those would interact with structural-
            // comparison gaps and is deferred.
            val sourceType = if ((init is Identifier || init is PropertyAccessExpression) &&
                isNarrowableTarget(targetType)) {
                getNarrowedTypeForReference(rawSourceType, init)
            } else rawSourceType
            lastMissingPropertyName = null // reset before comparison
            lastMissingIndexSigKind = null // reset before comparison (17.74)
            // 17.31f: bypass `canUseTypeEngine`'s nullish-Union gate when the init is a
            // CallExpression — its return type came from a generic-arg-inference pipeline
            // (17.31a–e), not a narrowable identifier/property-access, so the relation
            // engine's strictNullChecks-aware nullish→primitive rejection is appropriate.
            // PropertyAccess/Identifier sources still take the gated path so missing
            // narrowing on `obj.prop` doesn't FP under the same shape.
            val canUseRaw = canUseTypeEngine(sourceType, targetType)
            val callBypass = !canUseRaw && init is CallExpression && sourceType is Type.Union &&
                strictNullChecks &&
                (targetType is Type.Intrinsic || targetType is Type.StringLiteral ||
                    targetType is Type.NumberLiteral || targetType is Type.BigIntLiteral)
            val canUse = canUseRaw || callBypass
            val isAssignable = canUse && checkTypeRelatedTo(sourceType, targetType, assignableRelation)
            // B87.6b (round 73): array-VARIABLE source → tuple target tuple-arity TS2322 for
            // VAR-DECL — completes the tuple-arity feature uniformly with the async-return
            // path (B87.6). `var x: [number] = someNumberArray` → "Target allows only N
            // element(s) but source may have more." Gated: source is an `Array` Reference,
            // target is a tuple `Type.Object` (`tupleElementTypes != null`), init is NOT an
            // array literal (literals are checked element-wise elsewhere and ARE tuple-
            // assignable), and not already assignable. Emits at the var name.
            if (init !is ArrayLiteralExpression &&
                sourceType is Type.Reference && sourceType.target.symbol?.name == "Array" &&
                targetType is Type.Object && targetType !is Type.Reference &&
                targetType.tupleElementTypes != null && !isAssignable &&
                !checkTypeRelatedTo(sourceType, targetType, assignableRelation)
            ) {
                val n = targetType.tupleElementTypes!!.size
                val displaySource = typeToString(sourceType)
                val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = character,
                    start = name.pos, length = name.text.length,
                    messageChain = listOf("  Target allows only $n element(s) but source may have more."),
                ))
                return
            }
            // B87.4b (round 73): class-instance source → interface/class target
            // missing-property for VAR-DECL — completes the missing-property TS2741/2739
            // feature uniformly (the assignment path B87.4 + the argument path 17.29
            // already emit it; var-decl was the remaining gap, leaving an asymmetry
            // where `i = c` errors but `var i: I = c` doesn't). `canUseTypeEngine` blocks
            // named→named, so this fires only when the class source genuinely lacks the
            // target's required members. Missing-property is NAME-presence only (no
            // recursion → safe; full-suite verified net-zero, zero regressions). Emits at
            // the var name, mirroring the existing var-decl TS2741 position (~48973).
            if (!canUse && sourceType is Type.Interface && targetType is Type.Interface &&
                sourceType.symbol?.flags?.hasAny(SymbolFlags.Class) == true &&
                sourceType.callSignatures.isNullOrEmpty() && targetType.callSignatures.isNullOrEmpty()
            ) {
                val missing = try { collectMissingProperties(sourceType, targetType) }
                    catch (_: StackOverflowError) { emptyList() }
                if (missing.isNotEmpty()) {
                    val displaySource = typeToString(sourceType)
                    val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                    val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                    if (missing.size >= 2) {
                        diagnostics.add(Diagnostic(
                            message = formatTs2740Message(displaySource, displayTarget, missing),
                            category = DiagnosticCategory.Error,
                            code = if (missing.size <= 4) 2739 else 2740,
                            fileName = fileName, line = line, character = character,
                            start = name.pos, length = name.text.length,
                        ))
                    } else {
                        val mpName = missing[0]
                        val mpSym = try { getPropertyOfType(targetType, mpName) } catch (_: StackOverflowError) { null }
                        val declaringDisplay = getDeclaringTypeDisplay(mpSym, targetType, displayTarget)
                        val relatedInfo = mpSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                        diagnostics.add(Diagnostic(
                            message = "Property '$mpName' is missing in type '$displaySource' but required in type '$declaringDisplay'.",
                            category = DiagnosticCategory.Error, code = 2741,
                            fileName = fileName, line = line, character = character,
                            start = name.pos, length = name.text.length,
                            relatedInformation = listOfNotNull(relatedInfo),
                        ))
                    }
                    return
                }
            }
            // Excess property check for fresh object literals (TS2353).
            // Fires even when assignability passes (e.g., {b: 0, a: 0} → {b: number}).
            if (canUse && init is ObjectLiteralExpression) {
                val displayTarget = excessPropDisplayTarget(targetType, typeAnnotation)
                if (checkExcessProperties(init, sourceType, targetType, displayTarget, source, fileName)) {
                    return // TS2353 emitted — skip TS2741/TS2322
                }
            }
            // 16.0: Array literal initializer — contextual TS2353 for each object element
            // against the declared element type. `let x: { id: number }[] = [{ id: 1, name: "a" }]`.
            checkArrayLiteralElementExcessProps(init, targetType, source, fileName)
            // Suppress the outer "Type 'X[]' is not assignable to type 'Y[]'." TS2322
            // when the source is an array literal and the target is an array type.
            // Per-element TS2322/TS2353 from `checkArrayLiteralElementExcessProps` (or
            // the element-mismatch walker) already covers the specific mismatches;
            // the outer diagnostic would just duplicate them. Matches TypeScript's
            // baseline for tests like `contextualTyping21_ts`.
            if (canUse && !isAssignable && init is ArrayLiteralExpression &&
                targetType is Type.Reference && targetType.target.symbol?.name == "Array"
            ) {
                return
            }
            if (canUse && !isAssignable) {
                // B69.7: Widen literal source for display when target type doesn't
                // contain literal members (mirrors B69.5 in checkAssignmentExpression).
                // `var b: Boolean = true` displays as `Type 'boolean' is not
                // assignable to type 'Boolean'`, not `'true'`.
                val displaySourceType = if (propTypeContainsLiteral(targetType)) sourceType
                    else getWidenedLiteralType(sourceType)
                val displaySource = typeToString(displaySourceType)
                // Use annotation text for display (handles generics correctly)
                val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                // 17.216: Suppress TS2322 when assigning a function expression/arrow
                // to an anonymous multi-overload target (Type.Object with 2+ call
                // signatures, no construct sigs, no properties, no symbol).
                // TypeScript uses contextual typing here: the function expression
                // takes the shape of one overload (typically the last/widest), and
                // doesn't need to satisfy ALL overloads. Our checker does the
                // strict structural compare and rejects — false positive. Narrow
                // gate avoids regressing single-call-sig and named-interface
                // function-type targets (where the strict comparison IS correct).
                if ((init is FunctionExpression || init is ArrowFunction) &&
                    targetType is Type.Object &&
                    targetType.symbol == null &&
                    targetType.constructSignatures.isNullOrEmpty() &&
                    targetType.properties.isNullOrEmpty() &&
                    (targetType.callSignatures?.size ?: 0) >= 2
                ) {
                    return
                }
                // Special case: source has call signatures, target does not (non-function target).
                // TypeScript emits TS2322 AT the initializer position (not the variable name) and
                // attaches related TS6212 "Did you mean to call this expression?" — this is the
                // "you probably forgot `()`" hint, e.g. `let x: Dog = getRover;` where `getRover`
                // is `() => Dog`. The hint does NOT apply when the target is also function-like
                // (handled by the function→function elaboration path below).
                val srcIsFunc = sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty()
                val tgtIsFunc = targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()
                val tgtIsNewable = targetType is Type.Object && !targetType.constructSignatures.isNullOrEmpty()
                // Only emit TS6212 if calling `source()` would produce a value assignable to
                // the target — i.e., one of the call signatures' return types is assignable.
                // Without this guard, tests like `let b: [string] = () => void` get a bogus
                // "Did you mean to call this expression?" (calling would give void, still incompatible).
                // B51.2: skip when source's return type is `any`/`error` — those trivially
                // match anything and would cause FP TS6212 for fn-vs-fn cases where the
                // function-mismatch elaboration is the correct handler (e.g.
                // typeParameterConstrainedToOuterTypeParameter_ts's
                // `var b: B<string> = a` where A<string>'s call sig has inferred `any` return).
                val callingHelps = srcIsFunc && (sourceType as Type.Object).callSignatures?.any { sig ->
                    val rt = sig.resolvedReturnType ?: return@any false
                    if (rt === anyType || rt === errorType) return@any false
                    checkTypeRelatedTo(rt, targetType, assignableRelation)
                } == true
                if (srcIsFunc && !tgtIsNewable && callingHelps &&
                    init !is ArrowFunction && init !is FunctionExpression) {
                    val initStart = init.pos
                    val initEnd = expressionTrueEnd(init)
                    val (iLine, iCol) = getLineAndCharacterOfPosition(source, initStart)
                    val msg = "Type '$displaySource' is not assignable to type '$displayTarget'."
                    val related = Diagnostic(
                        message = "Did you mean to call this expression?",
                        category = DiagnosticCategory.Message, code = 6212,
                        fileName = fileName, line = iLine, character = iCol,
                        start = initStart, length = initEnd - initStart,
                    )
                    val chain = mutableListOf<String>()
                    if (tgtIsFunc) {
                        chain.addAll(getFunctionMismatchElaboration(sourceType as Type.Object, targetType as Type.Object))
                    }
                    diagnostics.add(Diagnostic(
                        message = msg,
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = iLine, character = iCol,
                        start = initStart, length = initEnd - initStart,
                        messageChain = chain,
                        relatedInformation = listOf(related),
                    ))
                    return
                }
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                // Compute outer-level missing properties directly. `lastMissingPropertyName`
                // can leak from inner comparisons (e.g. `IToken[]` vs `IStateToken[]` —
                // the inner Animal vs Giraffe comparison sets it to "g" or "state" but
                // the OUTER missing-prop set on `Animal[]` vs `Giraffe[]` is empty since
                // Array members all match). Mirroring the assignment path: gate TS2741/
                // TS2739/TS2740 on `allMissing.isNotEmpty()` and let the chain path
                // handle inner-level missing-property elaboration via the elaboration
                // chain.
                val allMissing = collectMissingProperties(sourceType, targetType)
                val missingPropSym = if (allMissing.isNotEmpty() && targetType is Type.Object) {
                    lastMissingPropertySymbol ?: targetType.properties?.find { it.name == allMissing[0] }
                } else null
                if (allMissing.isNotEmpty()) {
                    // B50.10: TS2696 when source is the lib `Object` interface and target
                    // is some specific named class/interface (with missing properties).
                    if (shouldEmitTs2696ForObject(sourceType, targetType)) {
                        val chainLine = "  " + formatTs2740Message(displaySource, displayTarget, allMissing)
                        diagnostics.add(Diagnostic(
                            message = "The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?",
                            category = DiagnosticCategory.Error,
                            code = 2696,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                            messageChain = listOf(chainLine),
                        ))
                    } else if (allMissing.size >= 2) {
                        // TS2739 for 2-4 missing, TS2740 for 5+
                        diagnostics.add(Diagnostic(
                            message = formatTs2740Message(displaySource, displayTarget, allMissing),
                            category = DiagnosticCategory.Error,
                            code = if (allMissing.size <= 4) 2739 else 2740,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                        ))
                    } else {
                        // TS2741: Property 'X' is missing in type 'Y' but required in type 'Z'.
                        val missingProp = allMissing[0]
                        val declaringDisplay = getDeclaringTypeDisplay(missingPropSym, targetType, displayTarget)
                        val message = "Property '$missingProp' is missing in type '$displaySource' but required in type '$declaringDisplay'."
                        val relatedInfo = missingPropSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                        diagnostics.add(Diagnostic(
                            message = message,
                            category = DiagnosticCategory.Error,
                            code = 2741,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                            relatedInformation = listOfNotNull(relatedInfo),
                        ))
                    }
                } else {
                // Per-property TS2322 + TS6500 for object-literal var initializers.
                // When the source is `{ k: v, ... }` and target is an object type, prefer
                // emitting one TS2322 per mismatched property at the property key (matching
                // tsc) instead of a single var-name TS2322 with a chain.
                if (init is ObjectLiteralExpression && sourceType is Type.Object && targetType is Type.Object) {
                    if (emitPerPropertyMismatchesForObjectLiteral(init, sourceType, targetType, displayTarget, source, fileName)) {
                        return
                    }
                }
                val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                val chain = mutableListOf<String>()
                lastChainMissingPropSymbol = null // ensure relatedInfo doesn't pick up stale state
                // Function→function: add specific elaboration (return/param mismatch)
                if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                    targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()) {
                    chain.addAll(getFunctionMismatchElaboration(sourceType, targetType))
                    // 17.155: When fn-vs-fn call signature matches but target ALSO has
                    // construct signatures that source lacks, the relation engine still
                    // returned `false` (construct sigs unsatisfied). Emit the construct-
                    // sig elaboration line so the chain is non-empty. Covers
                    // `var a: I4 = function(){...}` where I4 has both call and construct
                    // signatures and the function expression matches the call sig but
                    // not the construct sig. Skip for class/interface instance targets
                    // (their construct sigs belong to the static side).
                    if (chain.isEmpty() &&
                        !targetType.constructSignatures.isNullOrEmpty() &&
                        sourceType.constructSignatures.isNullOrEmpty() &&
                        !isClassOrInterfaceInstanceType(targetType)) {
                        getNonConstructibleElaboration(sourceType, targetType)
                            ?.let { chain.addAll(it) }
                    }
                } else if (sourceType is Type.Union) {
                    // Union source: find the failing constituent for elaboration.
                    // For `never` targets, TypeScript picks the FIRST failing
                    // member (`narrowingUnionToNeverAssigment_ts`); for other
                    // targets we keep the historical "last failing" picker.
                    val pickFirst = targetType === neverType
                    var pickedFailing: Type? = null
                    for (constituent in sourceType.types) {
                        if (!checkTypeRelatedTo(constituent, targetType, assignableRelation)) {
                            pickedFailing = constituent
                            if (pickFirst) break
                        }
                    }
                    if (pickedFailing != null) {
                        val constStr = typeToString(pickedFailing)
                        chain.add("  Type '$constStr' is not assignable to type '$displayTarget'.")
                    }
                } else {
                    // Object→Object: property-level elaboration (16.1)
                    // 17.42: Intersection→Object also goes through the chain helper.
                    if ((sourceType is Type.Object || sourceType is Type.Intersection) &&
                        targetType is Type.Object) {
                        lastChainMissingPropSymbol = null
                        val propElab = getPropertyElaborationChain(sourceType, targetType)
                        if (propElab != null) chain.addAll(propElab)
                    }
                    // B50.3: Object → Union target — find best-matching constituent
                    // (Object constituent that shares the most property names with source)
                    // and emit a 2-level chain: outer line names source vs constituent,
                    // deeper lines come from getPropertyElaborationChain.
                    if (chain.isEmpty() && sourceType is Type.Object &&
                        targetType is Type.Union) {
                        val best = findBestUnionConstituent(sourceType, targetType)
                        if (best != null && best is Type.Object) {
                            val outerLine = "  Type '${typeToString(sourceType)}' is not assignable to type '${typeToString(best)}'."
                            chain.add(outerLine)
                            val deeper = getPropertyElaborationChain(sourceType, best)
                            if (deeper != null) chain.addAll(deeper.map { "  $it" })
                        }
                    }
                    // 17.74: Missing index signature elaboration (mirrors the
                    // assignment-expression path at ~34861 and the property-access
                    // path at ~35285). Fires for function-vs-ArrayLike-shape:
                    // `func: () => void` → `ArrayLike<any>` produces
                    // "  Index signature for type '() => void' is missing in type '() => void'."
                    if (chain.isEmpty() && lastMissingIndexSigKind != null) {
                        chain.add("  Index signature for type '$lastMissingIndexSigKind' is missing in type '$displaySource'.")
                    }
                    // For non-literal, non-call expressions, TypeScript duplicates the message as elaboration
                    if (chain.isEmpty()) {
                    val needsElaboration = !isSimpleLiteral(init) &&
                        init !is CallExpression && init !is NewExpression &&
                        init !is DeleteExpression && init !is AwaitExpression &&
                        init !is BinaryExpression && init !is ParenthesizedExpression &&
                        init !is ElementAccessExpression && init !is AsExpression &&
                        init !is TypeAssertionExpression &&
                        init !is PropertyAccessExpression &&
                        init !is ArrayLiteralExpression && init !is ObjectLiteralExpression
                    if (needsElaboration) chain.add("  $message")
                    }
                    if (targetType is Type.TypeParam) {
                        val targetName = targetType.symbol?.name ?: "T"
                        // B60.2: when target TypeParam has a constraint AND source is
                        // assignable to that constraint, use the "constraint-assignable"
                        // chain form ("X is assignable to the constraint of type T, but
                        // T could be instantiated with a different subtype of constraint C").
                        // Otherwise fall back to the "arbitrary type unrelated" form.
                        val constraint = targetType.constraint
                        // B62.1: When source is a fresh-literal-shaped anonymous Type.Object
                        // with excess props relative to the constraint, TypeScript emits the
                        // "arbitrary unrelated" form (excess-property check overrides the
                        // structural-assignability result). Matches `errorElaborationDivesIntoApparentlyPresentPropsOnly`.
                        val constraintOk = constraint != null && try {
                            checkTypeRelatedTo(sourceType, constraint, assignableRelation) &&
                                !anonymousObjectHasExcessVsConstraint(sourceType, constraint)
                        } catch (_: Throwable) { false }
                        if (constraintOk) {
                            chain.add("  '$displaySource' is assignable to the constraint of type '$targetName', but '$targetName' could be instantiated with a different subtype of constraint '${typeToString(constraint!!)}'.")
                            // B60.6d: lib `Object` source hint
                            if (displaySource == "Object") {
                                chain.add("    The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?")
                            }
                        } else {
                            chain.add("  '$targetName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                        }
                    } else if (typeParams.isNotEmpty()) {
                        val targetBaseName = displayTarget.substringBefore('<')
                        if (targetBaseName in typeParams) {
                            chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                        }
                    }
                }
                val chainRelatedInfo = lastChainMissingPropSymbol?.let { createPropertyDeclaredHereRelatedInfo(it) }
                // B60.11: TS2208 related info for TypeParam source mismatch — mirrors
                // B60.10's checkReturnAssignability extension into the var-decl path.
                val tpRelatedInfo = mutableListOf<Diagnostic>()
                if (sourceType is Type.TypeParam) {
                    val srcName = sourceType.symbol?.name
                    val srcTpDecl = srcName?.let { currentTypeParamDecls[it] }
                    if (srcTpDecl != null) {
                        val isCircular = (srcTpDecl.constraint as? TypeReference)?.let {
                            (it.typeName as? Identifier)?.text == srcName
                        } == true
                        val effectivelyUnconstrained = srcTpDecl.constraint == null || isCircular
                        if (effectivelyUnconstrained) {
                            val decPos = srcTpDecl.name.pos
                            val decLen = srcTpDecl.name.text.length
                            val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                            tpRelatedInfo.add(Diagnostic(
                                message = "This type parameter might need an `extends $displayTarget` constraint.",
                                category = DiagnosticCategory.Message,
                                code = 2208,
                                fileName = fileName,
                                line = relLine,
                                character = relChar,
                                start = decPos,
                                length = decLen,
                            ))
                        }
                    }
                }
                val allRelated = listOfNotNull(chainRelatedInfo) + tpRelatedInfo
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = name.pos,
                    length = name.text.length,
                    messageChain = chain,
                    relatedInformation = allRelated,
                ))
                } // end else (not missing property)
                return // Type engine handled it — skip old system
            }
        } catch (_: StackOverflowError) {
            // Circular type resolution — fall through to old system
        }

        // Fallback to old string-based system for remaining cases
        if (declaredTypeStr != null) {
            val exprType = inferSimpleExprType(init, varTypes)
            if (exprType != null && !isAssignableTo(exprType, declaredTypeStr)) {
                emitTS2322(name.pos, name.text.length, exprType, declaredTypeStr, source, fileName, hasElaboration = !isSimpleLiteral(init), typeParams = typeParams)
            }
        }
    }

    /**
     * TS2339 for `var {n, ...rest} = x` where x's type is a union containing
     * `undefined` or `null`. TypeScript considers the property access invalid
     * because not every union member has the property.
     *
     * Only fires when the initializer's type is a Type.Union with a Null or
     * Undefined constituent — exactly matches TypeScript's rule. Skipped for
     * rest elements (propertyName=null, dotDotDotToken=true) and nested
     * patterns. Message format: `Property 'n' does not exist on type
     * '{ n: number; } | undefined'.`
     */
    private fun checkDestructuringFromNullableUnion(
        pattern: ObjectBindingPattern,
        initializer: Expression?,
        source: String,
        fileName: String,
    ) {
        val init = initializer ?: return
        val initType = try { getTypeOfExpression(init) } catch (_: StackOverflowError) { return }
        if (initType !is Type.Union) return
        val hasNullOrUndefined = initType.types.any {
            it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
        }
        if (!hasNullOrUndefined) return
        // TypeScript puts null/undefined at the end of union display
        val ordered = initType.types.sortedBy {
            if (it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) 1 else 0
        }
        val display = ordered.joinToString(" | ") { typeToString(it) }
        for (el in pattern.elements) {
            if (el !is BindingElement) continue
            if (el.dotDotDotToken) continue
            val propNode = el.propertyName ?: el.name
            val propName = when (propNode) {
                is Identifier -> propNode.text
                is StringLiteralNode -> propNode.text
                else -> continue
            }
            val squiggleStart = propNode.pos
            val squiggleLen = when (propNode) {
                is Identifier -> propNode.text.length
                is StringLiteralNode -> (propNode.rawText?.length ?: propNode.text.length) + 2
                else -> continue
            }
            val (line, character) = getLineAndCharacterOfPosition(source, squiggleStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$display'.",
                category = DiagnosticCategory.Error,
                code = 2339,
                fileName = fileName,
                line = line,
                character = character,
                start = squiggleStart,
                length = squiggleLen,
            ))
        }
    }

    /**
     * 17.95: TS2341 for destructuring patterns that extract a private property from
     * a class instance — `const { p: p3 } = new C()`, `const { "p": p0 } = new C()`,
     * `const { ["p"]: p1 } = new C()`, `const { [nameP]: p2 } = new C()` (where
     * `const nameP = "p"`). Mirrors TypeScript's behavior: the destructure is
     * structurally a property access, so private-member accessibility applies.
     */
    private fun checkDestructuringPrivateAccess(
        pattern: ObjectBindingPattern,
        initializer: Expression?,
        source: String,
        fileName: String,
    ) {
        val init = initializer ?: return
        val initType = try { getTypeOfExpression(init) } catch (_: StackOverflowError) { return }
        if (initType !is Type.Interface) return
        resolveStructuredTypeMembers(initType)
        for (el in pattern.elements) {
            if (el.dotDotDotToken) continue
            val propNode = el.propertyName ?: el.name
            val resolved = resolveDestructuringPropName(propNode, source, fileName) ?: continue
            val (propName, squiggleStart, squiggleLen) = resolved
            val prop = getPropertyOfType(initType, propName) ?: continue
            val declNode = prop.valueDeclaration ?: prop.declarations.firstOrNull() ?: continue
            if (!isMemberPrivate(declNode)) continue
            val (_, displayName) = findPrivateDeclaringClassInfo(initType, propName) ?: continue
            val (line, character) = getLineAndCharacterOfPosition(source, squiggleStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' is private and only accessible within class '$displayName'.",
                category = DiagnosticCategory.Error,
                code = 2341,
                fileName = fileName,
                line = line,
                character = character,
                start = squiggleStart,
                length = squiggleLen,
            ))
        }
    }

    /**
     * Resolve the property name being destructured + the squiggle (start, length).
     * Returns Triple(propName, squiggleStart, squiggleLen) or null if not statically resolvable.
     * Computed names like `[nameP]` resolve `nameP` via [findConstStringValue] if it's a top-level
     * `const NAME = "literal"`.
     */
    private fun resolveDestructuringPropName(
        propNode: Node, source: String, fileName: String,
    ): Triple<String, Int, Int>? = when (propNode) {
        is Identifier -> Triple(propNode.text, propNode.pos, propNode.text.length)
        is StringLiteralNode -> Triple(
            propNode.text, propNode.pos,
            (propNode.rawText?.length ?: propNode.text.length) + 2,
        )
        is ComputedPropertyName -> {
            val expr = propNode.expression
            val name = when (expr) {
                is StringLiteralNode -> expr.text
                is NoSubstitutionTemplateLiteralNode -> expr.text
                is Identifier -> findConstStringValue(expr.text, fileName)
                else -> null
            }
            if (name == null) null else {
                // ComputedPropertyName.pos may overshoot backward into trivia and
                // expr.end may overshoot forward (one-token rule). Compute the span
                // by finding `[` forward from propNode.pos, then bracket-match to `]`.
                val lbracket = source.indexOf('[', propNode.pos)
                if (lbracket < 0) null else {
                    var depth = 1
                    var i = lbracket + 1
                    while (i < source.length && depth > 0) {
                        when (source[i]) {
                            '[' -> depth++
                            ']' -> depth--
                        }
                        i++
                    }
                    Triple(name, lbracket, i - lbracket)
                }
            }
        }
        else -> null
    }

    /** Walk the file's top-level `const X = "literal"` decls; return the literal value or null. */
    private fun findConstStringValue(name: String, fileName: String): String? {
        val result = binderResults.find { it.sourceFile.fileName == fileName } ?: return null
        for (stmt in result.sourceFile.statements) {
            if (stmt !is VariableStatement) continue
            if (stmt.declarationList.flags != SyntaxKind.ConstKeyword) continue
            for (d in stmt.declarationList.declarations) {
                val n = d.name as? Identifier ?: continue
                if (n.text != name) continue
                return when (val init = d.initializer) {
                    is StringLiteralNode -> init.text
                    is NoSubstitutionTemplateLiteralNode -> init.text
                    else -> null
                }
            }
        }
        return null
    }

    /** Check property initializer assignability (class member: `x: Type = value`). */
    private fun checkPropertyInitAssignability(
        propName: Identifier, typeAnnotation: TypeNode, init: Expression,
        source: String, fileName: String, typeParams: Set<String>
    ) {
        try {
            val targetType = getTypeFromTypeNode(typeAnnotation)
            val sourceType = getTypeOfExpression(init)
            lastMissingPropertyName = null
            val canUse = canUseTypeEngine(sourceType, targetType)
            // Excess property check for fresh object literals (TS2353)
            if (canUse && init is ObjectLiteralExpression) {
                val displayTarget = excessPropDisplayTarget(targetType, typeAnnotation)
                if (checkExcessProperties(init, sourceType, targetType, displayTarget, source, fileName)) {
                    return // TS2353 emitted
                }
            }
            // 16.0: Array literal class property initializer — TS2353 for each element
            val initialDiagsBeforeElemCheck = diagnostics.size
            checkArrayLiteralElementExcessProps(init, targetType, source, fileName)
            // 17.81: When per-element diagnostics fired (TS2741/TS2322 from
            // checkArrayLiteralElementExcessProps), suppress the outer
            // class-property-level TS2741/TS2322 — per-element already covers the
            // specific mismatches at the precise position. Mirrors var-decl path
            // suppression at ~34146 for ArrayLiteralExpression vs Array target.
            if (init is ArrayLiteralExpression && targetType is Type.Reference &&
                targetType.target.symbol?.name == "Array" &&
                diagnostics.size > initialDiagsBeforeElemCheck) {
                return
            }
            if (canUse && !checkTypeRelatedTo(sourceType, targetType, assignableRelation)) {
                val displaySource = typeToString(sourceType)
                val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                val (line, character) = getLineAndCharacterOfPosition(source, propName.pos)
                val missingProp = lastMissingPropertyName
                val missingPropSym = lastMissingPropertySymbol
                if (missingProp != null) {
                    val allMissing = collectMissingProperties(sourceType, targetType)
                    if (allMissing.size >= 2) {
                        diagnostics.add(Diagnostic(
                            message = formatTs2740Message(displaySource, displayTarget, allMissing),
                            category = DiagnosticCategory.Error,
                            code = if (allMissing.size <= 4) 2739 else 2740,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = propName.pos,
                            length = propName.text.length,
                        ))
                    } else {
                        val declaringDisplay = getDeclaringTypeDisplay(missingPropSym, targetType, displayTarget)
                        val relatedInfo = missingPropSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                        diagnostics.add(Diagnostic(
                            message = "Property '$missingProp' is missing in type '$displaySource' but required in type '$declaringDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 2741,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = propName.pos,
                            length = propName.text.length,
                            relatedInformation = listOfNotNull(relatedInfo),
                        ))
                    }
                } else {
                val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                val chain = mutableListOf<String>()
                if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                    targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()) {
                    chain.addAll(getFunctionMismatchElaboration(sourceType, targetType))
                } else if (sourceType is Type.Union) {
                    var lastFailing: Type? = null
                    for (constituent in sourceType.types) {
                        if (!checkTypeRelatedTo(constituent, targetType, assignableRelation)) {
                            lastFailing = constituent
                        }
                    }
                    if (lastFailing != null) {
                        val constStr = typeToString(lastFailing)
                        chain.add("  Type '$constStr' is not assignable to type '$displayTarget'.")
                    }
                } else if (sourceType is Type.Object && targetType is Type.Object) {
                    // Object→Object: property-level elaboration (16.1)
                    val propElab = getPropertyElaborationChain(sourceType, targetType)
                    if (propElab != null) chain.addAll(propElab)
                }
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propName.pos,
                    length = propName.text.length,
                    messageChain = chain,
                ))
                }
            }
        } catch (_: StackOverflowError) {
            // Circular type resolution — skip
        }
    }

    private fun checkReturnAssignability(
        stmt: ReturnStatement, returnType: String, source: String, fileName: String,
        varTypes: Map<String, String>, typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        val expr = stmt.expression

        // If the declared return type is a TypeReference with a QualifiedName whose
        // leftmost is unresolvable AND has a spelling-suggestion target (meaning
        // TS2833 likely fired on the qualifier in `checkTypeNameResolved`), skip
        // TS2322 — otherwise the string-based path matches the stripped last-name
        // against an unrelated top-level symbol. Scoped to "suggestion-available"
        // to avoid suppressing the nested-namespace case where the qualifier is
        // reachable via scope chain (globals/currentFileLocals don't include
        // nested-namespace siblings, so a `!in globals` check alone is too broad).
        if (returnTypeNode is TypeReference) {
            val tn = returnTypeNode.typeName
            if (tn is QualifiedName) {
                var leftmost: Node = tn
                while (leftmost is QualifiedName) leftmost = leftmost.left
                if (leftmost is Identifier) {
                    val lname = leftmost.text
                    if (lname !in globals && currentFileLocals?.get(lname) == null) {
                        val suggestion = getSpellingSuggestionFromNames(
                            lname, collectNamespaceNames(fileName)
                        )
                        if (suggestion != null) return
                    }
                }
            }
        }
        // Try new Type-based engine when returnTypeNode is available
        if (returnTypeNode != null) {
            try {
                val targetType = getTypeFromTypeNode(returnTypeNode)
                // B69.1: Per-branch conditional return-expression checking. Must run
                // BEFORE the standard aggregated check so per-branch positions land
                // instead of one outer error.
                if (targetType !== anyType && targetType !== errorType &&
                    checkConditionalReturnBranches(expr, targetType, returnTypeNode, source, fileName)) {
                    return
                }
                // 16.0: contextual typing — set return type as context for arrow/function
                // return expressions so their params get typed from the expected signature.
                val savedContextual = contextualType
                val useCtx = targetType is Type.Object && (expr is ArrowFunction || expr is FunctionExpression)
                if (useCtx) contextualType = targetType
                // 17.70: contextual literal preservation for return-statement source —
                // mirrors 17.66 (var-decl init) / 17.67 (call arg). When return type
                // contains literal types and the return expression is a literal,
                // preserve the literal instead of widening to the primitive.
                val sourceType = try {
                    if (expr != null) {
                        val widened = getTypeOfExpression(expr)
                        if (propTypeContainsLiteral(targetType)) {
                            literalTypeOfExpression(expr) ?: widened
                        } else widened
                    } else undefinedType
                } finally {
                    if (useCtx) contextualType = savedContextual
                }
                // B87.1 (round 73): async-generic-return — `async function f<T>(...):
                // Promise<T>` returning a value whose (awaited) type is a UNION that
                // includes the bare unconstrained type parameter T PLUS other (non-
                // TypeParam) constituents. TypeScript reports the value as not
                // assignable to T ("could be instantiated with an arbitrary type").
                // Display: non-TP members first, then each TP member wrapped as
                // `Awaited<name>` (the await unwrap of `T | Yadda` leaves `Awaited<T> |
                // Yadda`). Narrowly gated to avoid touching the global relation/scope:
                // unconstrained TP, Promise<bareTP> return annotation, union source.
                run {
                    if (!inAsyncFunctionBody) return@run
                    val rtn = returnTypeNode as? TypeReference ?: return@run
                    if ((rtn.typeName as? Identifier)?.text != "Promise") return@run
                    val pArgs = rtn.typeArguments ?: return@run
                    if (pArgs.size != 1) return@run
                    val innerRef = pArgs[0] as? TypeReference ?: return@run
                    if (innerRef.typeArguments?.isNotEmpty() == true) return@run
                    val tpName = (innerRef.typeName as? Identifier)?.text ?: return@run
                    if (tpName !in typeParams) return@run
                    val u = sourceType as? Type.Union ?: return@run
                    val tpMembers = u.types.filter { it is Type.TypeParam && typeToString(it) == tpName }
                    val nonTp = u.types.filter { it !is Type.TypeParam }
                    if (tpMembers.isEmpty() || nonTp.isEmpty()) return@run
                    if (nonTp.any { it === anyType || it === errorType }) return@run
                    if (tpMembers.any { (it as Type.TypeParam).constraint != null }) return@run
                    val srcDisplay = (nonTp.map { typeToString(it) } +
                        tpMembers.map { "Awaited<${typeToString(it)}>" }).joinToString(" | ")
                    val (bl, bc) = getLineAndCharacterOfPosition(source, stmt.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$srcDisplay' is not assignable to type '$tpName'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = bl,
                        character = bc,
                        start = stmt.pos,
                        length = 6,
                        messageChain = listOf(
                            "  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$srcDisplay'."
                        ),
                    ))
                    return
                }
                // 16.0: Fresh-literal excess check for `return X = { excess }` — the
                // literal flows through the assignment into the return value.
                if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals) {
                    val chainedLit = findChainedObjectLiteral(expr)
                    if (chainedLit != null) {
                        val litType = getTypeOfExpression(chainedLit)
                        if (canUseTypeEngine(litType, targetType)) {
                            val displayTarget = excessPropDisplayTarget(targetType, returnTypeNode)
                            checkExcessProperties(chainedLit, litType, targetType, displayTarget, source, fileName)
                        }
                    }
                }
                // Also the case `return { excess }` where expr is directly a literal
                if (expr is ObjectLiteralExpression && canUseTypeEngine(sourceType, targetType)) {
                    val displayTarget = excessPropDisplayTarget(targetType, returnTypeNode)
                    if (checkExcessProperties(expr, sourceType, targetType, displayTarget, source, fileName)) {
                        return // TS2353 emitted
                    }
                }
                // B87.4c (round 73): class-instance source → interface/class return-type
                // missing-property — completes the TS2741/2739 feature for the RETURN
                // position (uniform with assignment B87.4 / var-decl B87.4b / argument
                // 17.29). canUseTypeEngine blocks named→named, so `function f(): I { return
                // c }` where class C lacks I's required members emits nothing. Name-presence
                // only (no recursion → safe). Sync functions only (async return-type is
                // Promise<T>, handled by the unwrap path below). Emits at the `return` keyword.
                if (!inAsyncFunctionBody && expr != null &&
                    sourceType is Type.Interface && targetType is Type.Interface &&
                    sourceType.symbol?.flags?.hasAny(SymbolFlags.Class) == true &&
                    sourceType.callSignatures.isNullOrEmpty() && targetType.callSignatures.isNullOrEmpty() &&
                    !canUseTypeEngine(sourceType, targetType)
                ) {
                    val missing = try { collectMissingProperties(sourceType, targetType) }
                        catch (_: StackOverflowError) { emptyList() }
                    if (missing.isNotEmpty()) {
                        val displaySource = typeToString(sourceType)
                        val displayTarget = formatTypeForDisplay(returnTypeNode) ?: typeToString(targetType)
                        val (line, character) = getLineAndCharacterOfPosition(source, stmt.pos)
                        if (missing.size >= 2) {
                            diagnostics.add(Diagnostic(
                                message = formatTs2740Message(displaySource, displayTarget, missing),
                                category = DiagnosticCategory.Error,
                                code = if (missing.size <= 4) 2739 else 2740,
                                fileName = fileName, line = line, character = character,
                                start = stmt.pos, length = 6,
                            ))
                        } else {
                            val mpName = missing[0]
                            val mpSym = try { getPropertyOfType(targetType, mpName) } catch (_: StackOverflowError) { null }
                            val declaringDisplay = getDeclaringTypeDisplay(mpSym, targetType, displayTarget)
                            val relatedInfo = mpSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                            diagnostics.add(Diagnostic(
                                message = "Property '$mpName' is missing in type '$displaySource' but required in type '$declaringDisplay'.",
                                category = DiagnosticCategory.Error, code = 2741,
                                fileName = fileName, line = line, character = character,
                                start = stmt.pos, length = 6,
                                relatedInformation = listOfNotNull(relatedInfo),
                            ))
                        }
                        return
                    }
                }
                if (canUseTypeEngine(sourceType, targetType) && !checkTypeRelatedTo(sourceType, targetType, assignableRelation)) {
                    // Async-function returns: declared `Promise<T>` accepts `T` directly.
                    // The returned value is implicitly wrapped in a Promise at runtime,
                    // so the assignability check must compare against `T` (the awaited
                    // form) rather than `Promise<T>`. Without this, `async function f():
                    // Promise<number> { return 1 }` spuriously emits TS2322.
                    if (inAsyncFunctionBody && targetType is Type.Reference &&
                        targetType.target.symbol?.name == "Promise") {
                        val args = targetType.resolvedTypeArguments
                        if (args != null && args.size == 1) {
                            val awaited = args[0]
                            if (awaited === anyType || awaited === errorType ||
                                checkTypeRelatedTo(sourceType, awaited, assignableRelation)) {
                                return // assignable to awaited form — no diagnostic
                            }
                            // B87.6 (round 73): source not assignable to the AWAITED form.
                            // NARROW tuple-arity case: array source (`any[]`/`T[]`) vs a tuple
                            // awaited target (e.g. `Promise<[]>` → awaited `[]`) — TypeScript
                            // reports against the awaited tuple with "Target allows only N
                            // element(s) but source may have more.", NOT the Promise<T> shape.
                            // (`promiseEmptyTupleNoException`.) Other async-return mismatches
                            // fall through to the existing Promise<T> emission below.
                            if (sourceType is Type.Reference && sourceType.target.symbol?.name == "Array" &&
                                awaited is Type.Object && awaited !is Type.Reference &&
                                awaited.tupleElementTypes != null
                            ) {
                                val n = awaited.tupleElementTypes!!.size
                                val (tl, tc) = getLineAndCharacterOfPosition(source, stmt.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type '${typeToString(sourceType)}' is not assignable to type '${typeToString(awaited)}'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = tl,
                                    character = tc,
                                    start = stmt.pos,
                                    length = 6,
                                    messageChain = listOf("  Target allows only $n element(s) but source may have more."),
                                ))
                                return
                            }
                        }
                    }
                    // Widen literal source for display when target type doesn't contain
                    // literal members (mirrors B69.7 in checkVarDeclAssignability).
                    // `return true` against return type `string` displays as
                    // `Type 'boolean' is not assignable to type 'string'`, not `'true'`.
                    val displaySourceType = if (propTypeContainsLiteral(targetType)) sourceType
                        else getWidenedLiteralType(sourceType)
                    val displaySource = typeToString(displaySourceType)
                    val displayTarget = formatTypeForDisplay(returnTypeNode) ?: typeToString(targetType)
                    val returnKeywordLength = 6
                    val (line, character) = getLineAndCharacterOfPosition(source, stmt.pos)
                    // B49.3: TS2739/TS2740 missing-properties emission for return-statement
                    // assignability, mirroring the var-decl/assignment paths. When the source
                    // is missing 2+ properties of the target, emit TS2739 (no truncation, all
                    // properties listed) or TS2740 (with "and N more" truncation, when 6+ are
                    // missing) instead of the generic TS2322. The threshold mirrors
                    // formatTs2740Message: truncation kicks in for size > 5. Skip for source
                    // unions / function-typed sources (those have their own elaboration
                    // paths) and for Type.Reference sources (handled by class/interface
                    // structural elaboration elsewhere).
                    if (sourceType is Type.Object && targetType is Type.Object &&
                        sourceType.callSignatures.isNullOrEmpty() &&
                        targetType.callSignatures.isNullOrEmpty() &&
                        sourceType !is Type.Reference) {
                        val allMissing = collectMissingProperties(sourceType, targetType)
                        if (allMissing.size >= 2) {
                            diagnostics.add(Diagnostic(
                                message = formatTs2740Message(displaySource, displayTarget, allMissing),
                                category = DiagnosticCategory.Error,
                                code = if (allMissing.size <= 5) 2739 else 2740,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = stmt.pos,
                                length = returnKeywordLength,
                            ))
                            return
                        }
                    }
                    val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                    val chain = mutableListOf<String>()
                    // Object→Object: property-level or function elaboration (16.1)
                    if (sourceType is Type.Object && targetType is Type.Object) {
                        if (!sourceType.callSignatures.isNullOrEmpty() && !targetType.callSignatures.isNullOrEmpty()) {
                            chain.addAll(getFunctionMismatchElaboration(sourceType, targetType))
                        } else {
                            val propElab = getPropertyElaborationChain(sourceType, targetType)
                            if (propElab != null) chain.addAll(propElab)
                        }
                    } else if (sourceType is Type.Union) {
                        // Union source: find the last failing constituent for elaboration
                        // (mirrors the var-decl path at checkVarDeclAssignability).
                        var lastFailingConstituent: Type? = null
                        for (constituent in sourceType.types) {
                            if (!checkTypeRelatedTo(constituent, targetType, assignableRelation)) {
                                lastFailingConstituent = constituent
                            }
                        }
                        if (lastFailingConstituent != null) {
                            chain.add("  Type '${typeToString(lastFailingConstituent)}' is not assignable to type '$displayTarget'.")
                        }
                    }
                    // B60.6f (mirror): TS2208 related info for TypeParam source mismatch.
                    val relatedInfo = mutableListOf<Diagnostic>()
                    if (sourceType is Type.TypeParam) {
                        val srcName = sourceType.symbol?.name
                        val srcTpDecl = srcName?.let { currentTypeParamDecls[it] }
                        if (srcTpDecl != null) {
                            // Treat self-circular constraint as effectively unconstrained.
                            val isCircular = (srcTpDecl.constraint as? TypeReference)?.let {
                                (it.typeName as? Identifier)?.text == srcName
                            } == true
                            val effectivelyUnconstrained = srcTpDecl.constraint == null || isCircular
                            if (effectivelyUnconstrained) {
                                val decPos = srcTpDecl.name.pos
                                val decLen = srcTpDecl.name.text.length
                                val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                                relatedInfo.add(Diagnostic(
                                    message = "This type parameter might need an `extends $displayTarget` constraint.",
                                    category = DiagnosticCategory.Message,
                                    code = 2208,
                                    fileName = fileName,
                                    line = relLine,
                                    character = relChar,
                                    start = decPos,
                                    length = decLen,
                                ))
                            }
                        }
                    }
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmt.pos,
                        length = returnKeywordLength,
                        messageChain = chain,
                        relatedInformation = if (relatedInfo.isEmpty()) emptyList() else relatedInfo.toList(),
                    ))
                    return
                }
            } catch (_: StackOverflowError) {
                // Fall through to old system
            }
        }

        // Fallback to old string-based system (skip when returnType is empty — means only returnTypeNode was available)
        if (returnType.isEmpty()) return
        val exprType = if (expr != null) {
            inferSimpleExprType(expr, varTypes)
                // For return statements: also check varTypes for identifier expressions
                // (safe here because return type is always a declared type, not a complex union)
                ?: (expr as? Identifier)?.let { varTypes[it.text] }
                ?: return
        } else {
            "undefined"
        }
        if (!isAssignableTo(exprType, returnType, typeParams)) {
            val returnKeywordLength = 6
            val isLiteral = expr == null || isSimpleLiteral(expr)
            emitTS2322(stmt.pos, returnKeywordLength, exprType, returnType, source, fileName, hasElaboration = !isLiteral, typeParams = typeParams)
        }
    }

    private fun checkAssignmentExpression(expr: Expression, source: String, fileName: String, varTypes: MutableMap<String, String>, typeParams: Set<String>) {
        if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals) {
            // Recurse into chained assignments first: a = b = c = null
            // Each assignment in the chain gets checked independently
            if (expr.right is BinaryExpression) {
                checkAssignmentExpression(expr.right, source, fileName, varTypes, typeParams)
            }
            // 16.4dp: `arguments = <primitive>` inside a non-arrow function body fires
            // TS2322 because `arguments` is the implicit `IArguments` parameter. Only
            // emit when the RHS is clearly a primitive (number/string/boolean literal
            // or their widened forms) — conservative to avoid FPs when IArguments
            // could legitimately be assigned (e.g., from another function's arguments).
            if (inNonArrowFunctionBody && expr.left is Identifier &&
                (expr.left as Identifier).text == "arguments"
            ) {
                try {
                    val rhsType = getTypeOfExpression(expr.right)
                    if (rhsType !== anyType && rhsType !== errorType && isSimpleCheckableType(rhsType)) {
                        val argsName = (expr.left as Identifier).text
                        val pos = (expr.left as Identifier).pos
                        val len = argsName.length
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "Type '${typeToString(getWidenedLiteralType(rhsType))}' is not assignable to type 'IArguments'.",
                            category = DiagnosticCategory.Error,
                            code = 2322,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = pos,
                            length = len,
                        ))
                        return // one error per assignment
                    }
                } catch (_: StackOverflowError) { /* circular */ }
            }
            val target = expr.left
            // 16.4dr: `X.prototype.method = function(){...}` — an extension
            // point where the property type can come from a module-augmented
            // interface declaration. Resolve the method type on X's instance
            // interface and compare with RHS function type. Emits TS2322 with
            // function-mismatch elaboration chain.
            if (target is PropertyAccessExpression) {
                val inner = target.expression
                if (inner is PropertyAccessExpression &&
                    inner.name.text == "prototype" &&
                    inner.expression is Identifier
                ) {
                    try {
                        val className = (inner.expression as Identifier).text
                        val rawSym = currentFileLocals?.get(className) ?: globals[className]
                        val classSymbol = rawSym?.let {
                            if (it.flags.hasAny(SymbolFlags.Alias)) resolveAliasTarget(it) else it
                        }
                        if (classSymbol != null) {
                            val classType = getDeclaredTypeOfSymbol(classSymbol)
                            if (classType is Type.Interface) {
                                resolveStructuredTypeMembers(classType)
                                val methodSym = classType.members?.get(target.name.text)
                                if (methodSym != null) {
                                    val methodType = getTypeOfSymbol(methodSym)
                                    if (methodType is Type.Object && !methodType.callSignatures.isNullOrEmpty()) {
                                        val rhsType = getTypeOfExpression(expr.right)
                                        // 16.4dr: For `function(){ return undefined; }` RHS, our
                                        // getTypeOfFunctionExpression reports return type as anyType
                                        // (no body-return inference). Detect this narrow pattern and
                                        // treat the return as undefinedType for comparison purposes.
                                        val inferredSrcReturn = (expr.right as? FunctionExpression)?.let { fe ->
                                            val stmts = fe.body?.statements
                                            if (stmts != null && stmts.size == 1) {
                                                val only = stmts[0]
                                                if (only is ReturnStatement && only.expression is Identifier &&
                                                    (only.expression as Identifier).text == "undefined") {
                                                    undefinedType
                                                } else null
                                            } else null
                                        }
                                        if (rhsType is Type.Object && !rhsType.callSignatures.isNullOrEmpty() &&
                                            inferredSrcReturn != null
                                        ) {
                                            val tgtSig = methodType.callSignatures!!.first()
                                            val tgtReturn = tgtSig.resolvedReturnType ?: anyType
                                            if (tgtReturn !== anyType && tgtReturn !== errorType &&
                                                !tgtReturn.flags.hasAny(TypeFlags.Void or TypeFlags.Undefined or TypeFlags.Null) &&
                                                !checkTypeRelatedTo(inferredSrcReturn, tgtReturn, assignableRelation)
                                            ) {
                                            val lhsStart = inner.expression.pos
                                            val lhsEnd = expressionTrueEnd(target)
                                            val lhsLen = lhsEnd - lhsStart
                                            if (lhsLen > 0) {
                                                // Manually format display as () => <return> since our
                                                // rhsType.callSigs.first() has return=anyType; we know
                                                // the real return is inferredSrcReturn.
                                                val displaySource = "() => ${typeToString(inferredSrcReturn)}"
                                                val displayTarget = "() => ${typeToString(tgtReturn)}"
                                                val (line, character) = getLineAndCharacterOfPosition(source, lhsStart)
                                                val chain = mutableListOf<String>()
                                                chain.add("  Type '${typeToString(inferredSrcReturn)}' is not assignable to type '${typeToString(tgtReturn)}'.")
                                                diagnostics.add(Diagnostic(
                                                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                                    category = DiagnosticCategory.Error,
                                                    code = 2322,
                                                    fileName = fileName,
                                                    line = line,
                                                    character = character,
                                                    start = lhsStart,
                                                    length = lhsLen,
                                                    messageChain = chain,
                                                ))
                                                return
                                            }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } catch (_: StackOverflowError) { /* circular */ }
                }
            }
            if (target is Identifier) {
                // B73.1: cross-file `typeof import("X")` display for module-alias
                // assignments. Two narrow shapes:
                //   (1) target was initialized from a module alias (`var x = moduleA`)
                //       and RHS is a primitive → emit TS2322 with module target display
                //   (2) target has primitive type (`var y = 1`) and RHS is a module
                //       alias (`y = moduleA`) → emit TS2322 with module source display
                try {
                    val rhsModuleName = tryGetModuleImportNameForExpr(expr.right)
                    val targetSym = currentFileLocals?.get(target.text) ?: globals[target.text]
                    val targetInitModuleName = run {
                        val initExpr = (targetSym?.valueDeclaration as? VariableDeclaration)
                            ?.takeIf { it.type == null }
                            ?.initializer ?: return@run null
                        tryGetModuleImportNameForExpr(initExpr)
                    }
                    if (targetInitModuleName != null && rhsModuleName == null) {
                        // Shape (1): target is `typeof import("X")`, RHS is something else.
                        // Emit only when RHS is a simple primitive literal — conservative.
                        val rhsType = try { getTypeOfExpression(expr.right) } catch (_: Throwable) { null }
                        if (rhsType != null && rhsType !== anyType && rhsType !== errorType &&
                            isSimpleCheckableType(rhsType)) {
                            val displaySource = typeToString(getWidenedLiteralType(rhsType))
                            val displayTarget = "typeof import(\"$targetInitModuleName\")"
                            val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = target.pos,
                                length = target.text.length,
                            ))
                            return
                        }
                    } else if (rhsModuleName != null && targetInitModuleName == null) {
                        // Shape (2): RHS is `typeof import("X")`. Check if target has a
                        // primitive type from currentLocalTypes / annotation.
                        var targetTypeForCheck: Type? = null
                        val tDecl = targetSym?.valueDeclaration ?: targetSym?.declarations?.firstOrNull()
                        val tAnno = (tDecl as? VariableDeclaration)?.type
                            ?: (tDecl as? Parameter)?.type
                            ?: (tDecl as? PropertyDeclaration)?.type
                        if (tAnno != null) {
                            targetTypeForCheck = try { getTypeFromTypeNode(tAnno) } catch (_: Throwable) { null }
                        }
                        if (targetTypeForCheck == null || targetTypeForCheck === anyType || targetTypeForCheck === errorType) {
                            currentLocalTypes[target.text]?.let { lt ->
                                if (lt !== anyType && lt !== errorType) targetTypeForCheck = lt
                            }
                        }
                        if (targetTypeForCheck != null && targetTypeForCheck !== anyType && targetTypeForCheck !== errorType &&
                            isSimpleCheckableType(targetTypeForCheck!!)) {
                            val displaySource = "typeof import(\"$rhsModuleName\")"
                            val displayTarget = typeToString(targetTypeForCheck!!)
                            val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = target.pos,
                                length = target.text.length,
                            ))
                            return
                        }
                    }
                } catch (_: StackOverflowError) { /* circular */ }
                // Try new Type-based engine for file-level and local variables
                try {
                    var targetType: Type? = null
                    var typeAnnotation: TypeNode? = null
                    val symbol = globals[target.text]
                    if (symbol != null) {
                        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
                        typeAnnotation = (decl as? VariableDeclaration)?.type
                            ?: (decl as? Parameter)?.type
                            ?: (decl as? PropertyDeclaration)?.type
                        if (typeAnnotation != null) {
                            targetType = getTypeFromTypeNode(typeAnnotation)
                        }
                    }
                    // Also check local type scope for function-local variables
                    if (targetType == null || targetType === anyType || targetType === errorType) {
                        currentLocalTypes[target.text]?.let { localType ->
                            if (localType !== anyType && localType !== errorType) {
                                targetType = localType
                            }
                        }
                    }
                    if (targetType != null && targetType !== anyType && targetType !== errorType) {
                        val tt = targetType!!
                        // B8.1: target is `never` because its annotation is an
                        // intersection that reduced due to a conflicting private
                        // property. Emit TS2322 with `never` display + chain so the
                        // standard emission path doesn't print `Type 'X' is not
                        // assignable to type 'A & B'.` (the un-reduced form).
                        if (tt === neverType) {
                            val reductionReason = findIntersectionReductionForExpr(target)
                            if (reductionReason != null) {
                                val sourceType = getTypeOfExpression(expr.right)
                                val displaySource = typeToString(getWidenedLiteralType(sourceType))
                                val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type 'never'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = target.pos,
                                    length = target.text.length,
                                    messageChain = listOf(intersectionReductionChainMessage(reductionReason)),
                                ))
                                return
                            }
                        }
                        // Class-Identifier-as-value RHS with construct-sig target — `d = C`.
                        // Mirrors the var-decl branch in checkVarDeclAssignability (17.8a):
                        // canUseTypeEngine skips class-instance-vs-constructor comparisons,
                        // so without a special-case the assignment falls through and emits
                        // no diagnostic. Display the source as `typeof X` and emit the
                        // construct-signature mismatch elaboration chain.
                        val rhs = expr.right
                        if (rhs is Identifier &&
                            tt is Type.Object &&
                            !tt.constructSignatures.isNullOrEmpty()
                        ) {
                            val rhsSym = currentFileLocals?.get(rhs.text) ?: globals[rhs.text]
                            if (rhsSym != null && rhsSym.flags.hasAny(SymbolFlags.Class) &&
                                !rhsSym.flags.hasAny(SymbolFlags.Variable)
                            ) {
                                val srcCtorType = buildClassValueConstructorTypeForDisplay(rhsSym)
                                if (srcCtorType != null) {
                                    val sourceSig = srcCtorType.constructSignatures!!.first()
                                    val targetSig = tt.constructSignatures!!.first()
                                    val ok = signatureRelatedTo(sourceSig, targetSig, assignableRelation)
                                    if (!ok) {
                                        val displaySource = "typeof ${rhsSym.name}"
                                        val displayTarget = if (typeAnnotation != null) formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt) else typeToString(tt)
                                        val chain = getConstructMismatchElaboration(srcCtorType, tt)
                                        val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                        diagnostics.add(Diagnostic(
                                            message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                            category = DiagnosticCategory.Error,
                                            code = 2322,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = target.pos,
                                            length = target.text.length,
                                            messageChain = chain,
                                        ))
                                        return
                                    }
                                }
                            }
                        }
                        // Set contextual type for function expression parameter inference.
                        // B52.4 extends to ObjectLiteralExpression so per-property contextual
                        // typing flows into nested arrow function parameters via
                        // getTypeOfObjectLiteral's per-property contextualType push.
                        val savedContextual = contextualType
                        if (tt is Type.Object && (expr.right is ArrowFunction || expr.right is FunctionExpression ||
                                expr.right is ObjectLiteralExpression)) {
                            contextualType = tt
                        }
                        // 17.66: contextual literal preservation for assignment RHS — when
                        // target is a literal-containing type and RHS is a literal expression,
                        // preserve the literal instead of widening to the primitive (matches
                        // TypeScript's bidirectional contextual-typing rule).
                        val sourceType = if (propTypeContainsLiteral(tt)) {
                            literalTypeOfExpression(expr.right) ?: getTypeOfExpression(expr.right)
                        } else {
                            getTypeOfExpression(expr.right)
                        }
                        contextualType = savedContextual
                        lastMissingPropertyName = null
                        lastMissingIndexSigKind = null
                        // 17.111: Mirror of 17.14a's PropertyAccess branch for plain
                        // Identifier-target assignment. canUseTypeEngine returns false
                        // when source lacks construct sigs but target requires them
                        // (Checker.kt:35168), short-circuiting the standard relation
                        // path so TS2322 never fires. Detect the construct-sig mismatch
                        // directly and emit TS2322 + "provides no match for the
                        // signature 'new ...'" chain. Source must be a "concrete
                        // shape": either callable (has callSignatures) or has at
                        // least one declared property — both forms clearly lack
                        // construct sigs. This excludes opaque sources like
                        // import-aliased `export = Class` whose effective type
                        // resolves to an empty Type.Object we can't introspect.
                        // 17.235 (2026-05-13): widened to also accept property-only
                        // sources (e.g. `{x:number}` against `{new():any}`). Skip
                        // when target is a class/iface instance (its construct sigs
                        // are static-side; instance structural compares should
                        // follow the regular path).
                        if (tt is Type.Object && !tt.constructSignatures.isNullOrEmpty() &&
                            !isClassOrInterfaceInstanceType(tt) &&
                            sourceType is Type.Object &&
                            (!sourceType.callSignatures.isNullOrEmpty() ||
                                (!isClassOrInterfaceInstanceType(sourceType) && !sourceType.properties.isNullOrEmpty())) &&
                            sourceType.constructSignatures.isNullOrEmpty()) {
                            val srcCtorElab = getNonConstructibleElaboration(sourceType, tt)
                            if (srcCtorElab != null) {
                                val displaySource = typeToString(sourceType)
                                val displayTarget = if (typeAnnotation != null)
                                    formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt)
                                    else typeToString(tt)
                                val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = target.pos,
                                    length = target.text.length,
                                    messageChain = srcCtorElab,
                                ))
                                return
                            }
                        }
                        // 17.112: Symmetric to 17.111 — target has callSignatures
                        // (function type) but no constructSignatures; source is a
                        // concrete-shape Type.Object lacking callSignatures (either
                        // constructible or property-only). canUseTypeEngine may or
                        // may not short-circuit depending on source shape, but
                        // emitting the chain here directly via getCallableMismatchElaboration
                        // ensures "  Type 'X' provides no match for the signature '(): T'."
                        // is added regardless of whether the standard path would
                        // have produced an empty chain. 17.235 (2026-05-13): widened
                        // to also accept property-only sources (e.g. `{x:number}`
                        // against `{():void}`).
                        if (tt is Type.Object && !tt.callSignatures.isNullOrEmpty() &&
                            tt.constructSignatures.isNullOrEmpty() &&
                            sourceType is Type.Object &&
                            (!sourceType.constructSignatures.isNullOrEmpty() ||
                                (!isClassOrInterfaceInstanceType(sourceType) && !sourceType.properties.isNullOrEmpty())) &&
                            sourceType.callSignatures.isNullOrEmpty()) {
                            val srcCallElab = getCallableMismatchElaboration(sourceType, tt)
                            if (srcCallElab != null) {
                                val displaySource = typeToString(sourceType)
                                val displayTarget = if (typeAnnotation != null)
                                    formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt)
                                    else typeToString(tt)
                                val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = target.pos,
                                    length = target.text.length,
                                    messageChain = srcCallElab,
                                ))
                                return
                            }
                        }
                        // B71.3: `b = {}` where `b: Boolean` (or other primitive wrapper) —
                        // empty object literal assignment to a wrapper interface. The
                        // standard structural compare passes trivially because
                        // OBJECT_PROTOTYPE_PROPERTIES (toString/valueOf/etc.) are filtered
                        // out in `propertiesRelatedTo`. TypeScript emits TS2322 with chain:
                        //   "  The types returned by 'valueOf()' are incompatible between these types."
                        //   "    Type 'Object' is not assignable to type 'boolean'."
                        // because source's apparent valueOf returns `Object` but target's
                        // wrapper interface declares `valueOf(): <primitive>`. Narrow gate:
                        // (a) RHS is an empty ObjectLiteralExpression `{}`; (b) target is
                        // a named wrapper interface. Other shapes still go through the
                        // standard path.
                        if (expr.right is ObjectLiteralExpression &&
                            (expr.right as ObjectLiteralExpression).properties.isEmpty() &&
                            tt is Type.Interface && tt !is Type.Reference
                        ) {
                            val targetName = tt.symbol?.name
                            if (targetName in WRAPPER_INTERFACE_NAMES) {
                                val primitive = when (targetName) {
                                    "Boolean" -> "boolean"
                                    "Number" -> "number"
                                    "String" -> "string"
                                    "BigInt" -> "bigint"
                                    "Symbol" -> "symbol"
                                    else -> null
                                }
                                if (primitive != null) {
                                    val displaySource = typeToString(sourceType)
                                    val displayTarget = if (typeAnnotation != null)
                                        formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt)
                                        else typeToString(tt)
                                    val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                    val chain = listOf(
                                        "  The types returned by 'valueOf()' are incompatible between these types.",
                                        "    Type 'Object' is not assignable to type '$primitive'.",
                                    )
                                    diagnostics.add(Diagnostic(
                                        message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2322,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = target.pos,
                                        length = target.text.length,
                                        messageChain = chain,
                                    ))
                                    return
                                }
                            }
                        }
                        // B86.7d: reverse-direction nullable-source TS2322. `canUseTypeEngine`
                        // returns false for Union-source → Object/Interface target (it skips
                        // those because most need control-flow narrowing we don't implement),
                        // so a genuinely-illegal `y = x` where `x: T | null | undefined` and
                        // `y: T` (T non-nullable) currently emits nothing. Add a VERY narrow
                        // emit for exactly that case: source is a Union literally containing a
                        // nullish constituent (null/undefined/void) that the target does NOT
                        // include, the nullish constituent fails assignability to the target,
                        // and strictNullChecks is on. The chain names the failing nullish
                        // constituent (matches `elaboratedErrorsOnNullableTargets01` line 6).
                        // Gate is deliberately not "source union not assignable to target" —
                        // that would fire for narrowed-union / contextual-typing cases that are
                        // legitimately assignable; we ONLY fire when the unambiguous cause is a
                        // nullish member missing from the (non-nullable) target.
                        if (strictNullChecks && sourceType is Type.Union &&
                            (tt is Type.Object || tt is Type.Interface) &&
                            !typeIncludesUndefined(tt) && !typeIncludesNull(tt)
                        ) {
                            // First nullish constituent (in flags-value order undefined<null,
                            // matching TypeScript's reported `undefined`) that fails assignability.
                            val failingNullish = sourceType.types.firstOrNull {
                                isNullishConstituent(it) &&
                                    !checkTypeRelatedTo(it, tt, assignableRelation)
                            }
                            if (failingNullish != null) {
                                val displaySource = typeToString(sourceType)
                                val displayTarget = if (typeAnnotation != null)
                                    formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt)
                                    else typeToString(tt)
                                val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = target.pos,
                                    length = target.text.length,
                                    messageChain = listOf(
                                        "  Type '${typeToString(failingNullish)}' is not assignable to type '$displayTarget'.",
                                    ),
                                ))
                                return
                            }
                        }
                        // B87.6c (round 73): array-VARIABLE source → tuple target tuple-arity
                        // TS2322 for ASSIGNMENT — completes the tuple-arity diagnostic uniformly
                        // (async-return B87.6 + var-decl B87.6b + assignment B87.6c). `x = arr`
                        // where `x: [number]`, `arr: number[]` → "Target allows only N element(s)
                        // but source may have more." Gated: RHS not an array literal (literals are
                        // tuple-assignable element-wise), source is `Array` Reference, target is a
                        // tuple `Type.Object`, not already assignable. Emits at the LHS identifier.
                        if (expr.right !is ArrayLiteralExpression &&
                            sourceType is Type.Reference && sourceType.target.symbol?.name == "Array" &&
                            tt is Type.Object && tt !is Type.Reference && tt.tupleElementTypes != null &&
                            !checkTypeRelatedTo(sourceType, tt, assignableRelation)
                        ) {
                            val n = tt.tupleElementTypes!!.size
                            val displaySource = typeToString(sourceType)
                            val displayTarget = if (typeAnnotation != null)
                                formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt) else typeToString(tt)
                            val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                                category = DiagnosticCategory.Error, code = 2322,
                                fileName = fileName, line = line, character = character,
                                start = target.pos, length = target.text.length,
                                messageChain = listOf("  Target allows only $n element(s) but source may have more."),
                            ))
                            return
                        }
                        // B87.4 (round 73): class-instance source → interface/class target
                        // missing-property. `canUseTypeEngine` blocks named→named structural
                        // comparison (recursive-expansion risk), so `i = c` / `d = c` where the
                        // source class lacks members the target requires emit nothing. Missing-
                        // property is NAME-presence only (no recursion into property types), so a
                        // narrow additive check is safe: source is a class instance, target is a
                        // class/interface, and `collectMissingProperties` (which handles inherited
                        // + Object.prototype members) reports ≥1 required member absent from source.
                        if (sourceType is Type.Interface && tt is Type.Interface &&
                            sourceType.symbol?.flags?.hasAny(SymbolFlags.Class) == true &&
                            sourceType.callSignatures.isNullOrEmpty() && tt.callSignatures.isNullOrEmpty()
                        ) {
                            val missing = try { collectMissingProperties(sourceType, tt) }
                                catch (_: StackOverflowError) { emptyList() }
                            if (missing.isNotEmpty()) {
                                val displaySource = typeToString(sourceType)
                                val displayTarget = if (typeAnnotation != null)
                                    formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt) else typeToString(tt)
                                val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                                if (missing.size >= 2) {
                                    diagnostics.add(Diagnostic(
                                        message = formatTs2740Message(displaySource, displayTarget, missing),
                                        category = DiagnosticCategory.Error,
                                        code = if (missing.size <= 4) 2739 else 2740,
                                        fileName = fileName, line = line, character = character,
                                        start = target.pos, length = target.text.length,
                                    ))
                                } else {
                                    val mpName = missing[0]
                                    val mpSym = try { getPropertyOfType(tt, mpName) } catch (_: StackOverflowError) { null }
                                    val declaringDisplay = getDeclaringTypeDisplay(mpSym, tt, displayTarget)
                                    val relatedInfo = mpSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                                    diagnostics.add(Diagnostic(
                                        message = "Property '$mpName' is missing in type '$displaySource' but required in type '$declaringDisplay'.",
                                        category = DiagnosticCategory.Error, code = 2741,
                                        fileName = fileName, line = line, character = character,
                                        start = target.pos, length = target.text.length,
                                        relatedInformation = listOfNotNull(relatedInfo),
                                    ))
                                }
                                return
                            }
                        }
                        val canUse = canUseTypeEngine(sourceType, tt)
                        val isAssignable = canUse && checkTypeRelatedTo(sourceType, tt, assignableRelation)
                        // Excess property check for object literal assignments (TS2353)
                        if (canUse && expr.right is ObjectLiteralExpression) {
                            val displayTarget = excessPropDisplayTarget(tt, typeAnnotation)
                            if (checkExcessProperties(expr.right as ObjectLiteralExpression, sourceType, tt, displayTarget, source, fileName)) {
                                return // TS2353 emitted
                            }
                        }
                        // 16.0: Chained assignment fresh-literal excess check.
                        // `obj1 = obj2 = { excess }` — the fresh object literal flows
                        // through the chain; check excess against OUR target too.
                        if (expr.right is BinaryExpression) {
                            val chainedLit = findChainedObjectLiteral(expr.right)
                            if (chainedLit != null) {
                                try {
                                    val litType = getTypeOfExpression(chainedLit)
                                    if (canUseTypeEngine(litType, tt)) {
                                        val displayTarget = excessPropDisplayTarget(tt, typeAnnotation)
                                        checkExcessProperties(chainedLit, litType, tt, displayTarget, source, fileName)
                                    }
                                } catch (_: StackOverflowError) { /* circular */ }
                            }
                        }
                        // 16.0: Array literal assignment — contextual TS2353 for each object element
                        checkArrayLiteralElementExcessProps(expr.right, tt, source, fileName)
                        // Suppress outer "Type 'X[]' is not assignable to type 'Y[]'." TS2322
                        // when source is an array literal and target is array — per-element
                        // diagnostics already cover it. See matching comment in the var-decl
                        // path above (`contextualTyping21_ts` test).
                        if (canUse && !isAssignable && expr.right is ArrayLiteralExpression &&
                            tt is Type.Reference && tt.target.symbol?.name == "Array"
                        ) {
                            return
                        }
                        if (canUse && !isAssignable) {
                            // B69.5: Widen literal source for display when target type
                            // doesn't contain literal members. TypeScript shows `boolean`
                            // (widened) not `false` when target is `{ [n: number]: any }`
                            // (no literal context). When target preserves literal (e.g.
                            // `false` or `true | false`), keep the literal display.
                            val displaySourceType = if (propTypeContainsLiteral(tt)) sourceType
                                else getWidenedLiteralType(sourceType)
                            val displaySource = typeToString(displaySourceType)
                            // 17.80: For NumberLiteral targets with infinite/NaN value, prefer
                            // the resolved type display (`'Infinity'` / `'-Infinity'` / `'NaN'`)
                            // over the type-annotation alias name. TypeScript expands type
                            // aliases to their resolved form when displaying intrinsic-like
                            // numeric values (cf. fakeInfinity1_ts: `type A = 1e999;` displays
                            // as `'Infinity'` not `'A'`).
                            val resolvedDisplay = typeToString(tt)
                            val isIntrinsicNumericLiteral = resolvedDisplay == "Infinity" ||
                                resolvedDisplay == "-Infinity" || resolvedDisplay == "NaN"
                            // B50.6: When the resolved type is a pure function type AND has
                            // no alias-display registered (so B50.5 deliberately unfolded it),
                            // prefer the unfolded `typeToString` form over the annotation text.
                            // Matches `nestedCallbackErrorNotFlattened_ts`'s expected unfolded
                            // display for the `Cb<Cb<...>>` chain.
                            val isPureFuncNoAlias = tt is Type.Object &&
                                !tt.callSignatures.isNullOrEmpty() &&
                                tt.properties.isNullOrEmpty() &&
                                tt.members.isNullOrEmpty() &&
                                tt.constructSignatures.isNullOrEmpty() &&
                                tt.id !in aliasDisplayMap
                            // B86.7b: when target is a nullable Union (`A | null | undefined`)
                            // and source is non-nullable, strip the outer nullish constituents
                            // from BOTH the display and the chain comparison so we report the
                            // structural mismatch against the underlying shape (matches TypeScript's
                            // `elaboratedErrorsOnNullableTargets01` baseline shape). The helper
                            // returns `tt` unchanged when not applicable.
                            val ttForDisplay = stripNullishFromDisplayTarget(tt, sourceType)
                            val displayTarget = if (isIntrinsicNumericLiteral) resolvedDisplay
                                else if (isPureFuncNoAlias) resolvedDisplay
                                else if (ttForDisplay !== tt) typeToString(ttForDisplay)
                                else if (typeAnnotation != null) formatTypeForDisplay(typeAnnotation!!) ?: resolvedDisplay
                                else resolvedDisplay
                            val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                            // 16.4bf: Compute missing-property set directly rather than relying on
                            // `lastMissingPropertyName` side-effect — a cached Ternary.False result
                            // from `checkTypeRelatedTo` skips setting it, causing second+ occurrences
                            // of the same comparison to fall through to TS2322 instead of TS2741.
                            val allMissing = if (sourceType is Type.Object && tt is Type.Object) {
                                collectMissingProperties(sourceType, tt)
                            } else emptyList()
                            val missingPropSym = lastMissingPropertySymbol
                                ?: if (allMissing.isNotEmpty() && tt is Type.Object) {
                                    tt.properties?.find { it.name == allMissing[0] }
                                } else null
                            if (allMissing.isNotEmpty()) {
                                if (shouldEmitTs2696ForObject(sourceType, tt)) {
                                    val chainLine = "  " + formatTs2740Message(displaySource, displayTarget, allMissing)
                                    diagnostics.add(Diagnostic(
                                        message = "The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?",
                                        category = DiagnosticCategory.Error,
                                        code = 2696,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = target.pos,
                                        length = target.text.length,
                                        messageChain = listOf(chainLine),
                                    ))
                                } else if (allMissing.size >= 2) {
                                    diagnostics.add(Diagnostic(
                                        message = formatTs2740Message(displaySource, displayTarget, allMissing),
                                        category = DiagnosticCategory.Error,
                                        code = if (allMissing.size <= 4) 2739 else 2740,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = target.pos,
                                        length = target.text.length,
                                    ))
                                } else {
                                    val missingProp = allMissing[0]
                                    val declaringDisplay = getDeclaringTypeDisplay(missingPropSym, tt, displayTarget)
                                    val relatedInfo = missingPropSym?.let { createPropertyDeclaredHereRelatedInfo(it) }
                                    // B53.1: cross-file disambiguation. When source and target are
                                    // different interfaces sharing the same display name but declared
                                    // in different files, render `import("<basename>").<name>` so the
                                    // diagnostic is unambiguous. Matches TypeScript's behavior for
                                    // `import * as A from './a'` / `B from './b'` with same-named types.
                                    var qualSource = displaySource
                                    var qualDeclaring = declaringDisplay
                                    if (qualSource == qualDeclaring) {
                                        val srcSym = (sourceType as? Type.Interface)?.symbol
                                        val tgtSym = (tt as? Type.Interface)?.symbol
                                        if (srcSym != null && tgtSym != null && srcSym !== tgtSym) {
                                            val srcImport = getSymbolImportName(srcSym)
                                            val tgtImport = getSymbolImportName(tgtSym)
                                            if (srcImport != null && tgtImport != null && srcImport != tgtImport) {
                                                qualSource = "import(\"$srcImport\").$qualSource"
                                                qualDeclaring = "import(\"$tgtImport\").$qualDeclaring"
                                            }
                                        }
                                    }
                                    diagnostics.add(Diagnostic(
                                        message = "Property '$missingProp' is missing in type '$qualSource' but required in type '$qualDeclaring'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2741,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = target.pos,
                                        length = target.text.length,
                                        relatedInformation = listOfNotNull(relatedInfo),
                                    ))
                                }
                                return
                            }
                            val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                            val chain = mutableListOf<String>()
                            lastChainMissingPropSymbol = null // ensure relatedInfo doesn't pick up stale state
                            // Wrapper interface (Number/String/Boolean/Symbol/BigInt) → primitive:
                            // emit "X is a primitive, but Y is a wrapper object. Prefer using X when
                            // possible." TypeScript adds this advisory chain line whenever the source
                            // is a named wrapper interface and the target is the matching primitive.
                            val wrapperElab = getWrapperToPrimitiveElaboration(sourceType, displayTarget)
                            if (wrapperElab != null) {
                                chain.add(wrapperElab)
                            } else
                            // Function→function: add specific elaboration
                            if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                                tt is Type.Object && !tt.callSignatures.isNullOrEmpty()) {
                                chain.addAll(getFunctionMismatchElaboration(sourceType, tt))
                            } else if (sourceType is Type.Union) {
                                // Union source: find the last failing constituent (matches TypeScript)
                                var lastFailing: Type? = null
                                for (constituent in sourceType.types) {
                                    if (!checkTypeRelatedTo(constituent, tt, assignableRelation)) {
                                        lastFailing = constituent
                                    }
                                }
                                if (lastFailing != null) {
                                    val constStr = typeToString(lastFailing)
                                    chain.add("  Type '$constStr' is not assignable to type '$displayTarget'.")
                                }
                            } else {
                                // Object→Object: property-level elaboration (16.1)
                                // B86.7b: use the (possibly stripped) ttForDisplay so when target
                                // was `A | null | undefined`, we still get the property chain
                                // against the underlying `A`.
                                val ttForChain = ttForDisplay
                                if (sourceType is Type.Object && ttForChain is Type.Object) {
                                    lastChainMissingPropSymbol = null
                                    val propElab = getPropertyElaborationChain(sourceType, ttForChain)
                                    if (propElab != null) chain.addAll(propElab)
                                }
                                // 16.4cn: Missing index signature elaboration
                                if (chain.isEmpty() && lastMissingIndexSigKind != null) {
                                    chain.add("  Index signature for type '$lastMissingIndexSigKind' is missing in type '$displaySource'.")
                                }
                                if (chain.isEmpty()) {
                                if (tt is Type.TypeParam) {
                                    val targetName = tt.symbol?.name ?: "T"
                                    // B60.2: same logic as the var-decl path at ~39819.
                                    // B62.1: excess-property override (see helper docstring).
                                    val constraint = tt.constraint
                                    val constraintOk = constraint != null && try {
                                        checkTypeRelatedTo(sourceType, constraint, assignableRelation) &&
                                            !anonymousObjectHasExcessVsConstraint(sourceType, constraint)
                                    } catch (_: Throwable) { false }
                                    if (constraintOk) {
                                        chain.add("  '$displaySource' is assignable to the constraint of type '$targetName', but '$targetName' could be instantiated with a different subtype of constraint '${typeToString(constraint!!)}'.")
                                        // B60.6d: lib `Object` source hint
                                        if (displaySource == "Object") {
                                            chain.add("    The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?")
                                        }
                                    } else {
                                        chain.add("  '$targetName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                                    }
                                } else if (sourceType is Type.TypeParam) {
                                    // B60.5: source is TypeParam — emit apparent-type chain.
                                    // "Type '<constraint>' is not assignable to type '<target>'."
                                    // Gate: constraint non-null, non-error, non-any. Skip if
                                    // constraint IS the target (trivially equal). Bypass alias
                                    // display so `T extends Table` (where Table = TableClass)
                                    // expands to `TableClass<any>` not `Table`.
                                    val srcConstraint = sourceType.constraint
                                    if (srcConstraint != null && srcConstraint !== errorType && srcConstraint !== anyType && srcConstraint !== tt) {
                                        // Temporarily mark the constraint as in-progress so
                                        // typeToString skips aliasDisplayMap lookup.
                                        typeToStringInProgress.add(srcConstraint.id)
                                        val apparentDisplay = try { typeToString(srcConstraint) }
                                            finally { typeToStringInProgress.remove(srcConstraint.id) }
                                        if (apparentDisplay != displaySource) {
                                            chain.add("  Type '$apparentDisplay' is not assignable to type '$displayTarget'.")
                                        }
                                    }
                                } else if (typeParams.isNotEmpty()) {
                                    val targetBaseName = displayTarget.substringBefore('<')
                                    if (targetBaseName in typeParams) {
                                        chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                                    }
                                }
                                }
                            }
                            val chainRelatedInfo = lastChainMissingPropSymbol?.let { createPropertyDeclaredHereRelatedInfo(it) }
                            diagnostics.add(Diagnostic(
                                message = message,
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = target.pos,
                                length = target.text.length,
                                messageChain = chain,
                                relatedInformation = listOfNotNull(chainRelatedInfo),
                            ))
                            return // Type engine handled it — skip old system
                        }
                    }
                } catch (_: StackOverflowError) {
                    // Circular type resolution — fall through to old system
                }

                // Fallback to old string-based system
                val declaredType = varTypes[target.text]
                if (declaredType != null) {
                    // B54.7 (probe re-enable for regression-identification): fallback to varTypes
                    // lookup for Identifier RHS when same-base parameterized refs.
                    val isParameterizedRefTarget = declaredType.startsWith("@") && declaredType.contains('<')
                    val rhsAsIdent = expr.right as? Identifier
                    val rhsVarType = rhsAsIdent?.let { varTypes[it.text] }
                    val isSameBaseRhs = rhsVarType != null &&
                        rhsVarType.startsWith("@") && rhsVarType.contains('<') &&
                        rhsVarType.substringBefore('<') == declaredType.substringBefore('<')
                    // B60.6b: also fall back for bare TypeParam target with bare TypeParam RHS
                    // (`x: T = y: U`) — both must be in the typeParams scope. Mirrors the
                    // same-base-ref fallback for the bare case.
                    val tgtBareName = if (declaredType.startsWith("@") && !declaredType.contains('<'))
                        declaredType.removePrefix("@") else null
                    val rhsBareName = if (rhsVarType != null && rhsVarType.startsWith("@") && !rhsVarType.contains('<'))
                        rhsVarType.removePrefix("@") else null
                    val isBareTypeParamMismatch = tgtBareName != null && rhsBareName != null &&
                        tgtBareName != rhsBareName &&
                        tgtBareName in typeParams && rhsBareName in typeParams
                    // B60.7b: also fall back for bare TypeParam RHS → named non-TypeParam target.
                    // E.g. `z: Object = x: T` where T is bare TypeParam (in scope, unconstrained).
                    // Needs the gate from B60.7 to fire — keep targets to Object/Function.
                    val isTypeParamToNamed = tgtBareName != null && rhsBareName != null &&
                        rhsBareName in typeParams && tgtBareName !in typeParams &&
                        (tgtBareName == "Object" || tgtBareName == "Function")
                    val exprType = inferSimpleExprType(expr.right, varTypes)
                        ?: if (isParameterizedRefTarget && isSameBaseRhs) rhsVarType
                            else if (isBareTypeParamMismatch) rhsVarType
                            else if (isTypeParamToNamed) rhsVarType
                            else null
                    if (exprType != null && !isAssignableTo(exprType, declaredType, typeParams)) {
                        emitTS2322(target.pos, target.text.length, exprType, declaredType, source, fileName, hasElaboration = !isSimpleLiteral(expr.right), typeParams = typeParams)
                    }
                }
            } else if (target is PropertyAccessExpression && (target.expression as? Identifier)?.text == "this") {
                // this.prop = value — look up class property type from varTypes
                val propName = target.name.text
                val declaredType = varTypes["this.$propName"]
                if (declaredType != null) {
                    // B54.2: fall back to direct varTypes lookup for Identifier RHS when
                    // inferSimpleExprType deliberately returns null (its standard gate skips
                    // identifier lookup to avoid FPs with enum/union targets). For `this.X = v`
                    // assignments inside setters/methods, the parameter type IS reliably stored
                    // in varTypes by the class-body walker, and the RHS-narrower runs in a
                    // fresh per-member scope so FP risk is bounded.
                    val exprType = inferSimpleExprType(expr.right, varTypes)
                        ?: (expr.right as? Identifier)?.let { varTypes[it.text] }
                    if (exprType != null && !isAssignableTo(exprType, declaredType)) {
                        // Squiggle spans "this.prop" (the entire PropertyAccessExpression)
                        val squiggleStart = target.expression.pos
                        val squiggleLength = target.name.pos + target.name.text.length - squiggleStart
                        emitTS2322(squiggleStart, squiggleLength, exprType, declaredType, source, fileName, hasElaboration = !isSimpleLiteral(expr.right), typeParams = typeParams)
                    }
                }
            } else if (target is PropertyAccessExpression) {
                // 16.0: x.prop = value — resolve target prop type via type engine and check assignability.
                checkPropertyAccessAssignment(target, expr.right, source, fileName)
            } else if (target is ElementAccessExpression) {
                // B85.1d: obj[key] = value — narrowly-gated TS2322 for index-signature value mismatch.
                checkElementAccessAssignment(target, expr.right, source, fileName, varTypes)
            }
        }
    }

    /**
     * B85.1d: Check `obj[key] = value` assignments against an index signature's value type.
     * Currently narrowly scoped: only fires when the receiver chain bottoms out at `this`
     * (so the leaf property type comes from `varTypes["this.X"]`, populated by B85.1b in the
     * method-decl walker), and the resolved receiver type carries a stringIndexInfo. Reuses
     * B85.1c's namespace-export BFS helper to walk namespace-internal type refs that
     * `currentFileLocals` doesn't carry directly. Pairs with B85.1a (optional-param `| undefined`
     * wrap in `currentLocalTypes`) so an optional param `value?: string` resolves to
     * `string | undefined` and the check fires correctly.
     *
     * Bails silently for any shape outside the gate — no FP risk.
     */
    private fun checkElementAccessAssignment(
        target: ElementAccessExpression, value: Expression, source: String, fileName: String,
        varTypes: Map<String, String>
    ) {
        try {
            // Only handle PropertyAccess receivers rooted at `this` for now — the most common
            // shape and the one B85.1b's varTypes population is designed for.
            val receiverExpr = target.expression as? PropertyAccessExpression ?: return
            val receiverType = resolveReceiverTypeForElementAccess(receiverExpr, varTypes) ?: return
            if (receiverType !is Type.Object) return
            resolveStructuredTypeMembers(receiverType)
            val stringIdx = receiverType.stringIndexInfo ?: return
            val indexValueType = stringIdx.type
            if (indexValueType === anyType || indexValueType === errorType) return
            val rhsType = getTypeOfExpression(value)
            if (rhsType === anyType || rhsType === errorType) return
            // Use the existing relation engine.
            if (checkTypeRelatedTo(rhsType, indexValueType, assignableRelation)) return
            // Emit TS2322 at the entire element-access span.
            val start = target.expression.pos
            val end = expressionTrueEnd(target)
            val length = (end - start).coerceAtLeast(1)
            val displaySrc = typeToString(rhsType)
            val displayTgt = typeToString(indexValueType)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            // For union sources containing undefined where target excludes it, append
            // the standard "Type 'undefined' is not assignable to ..." chain line.
            val chain = mutableListOf<String>()
            if (rhsType is Type.Union && rhsType.types.any { it === undefinedType }) {
                chain.add("  Type 'undefined' is not assignable to type '$displayTgt'.")
            }
            diagnostics.add(Diagnostic(
                message = "Type '$displaySrc' is not assignable to type '$displayTgt'.",
                messageChain = chain,
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = line,
                character = character,
                length = length,
            ))
        } catch (_: StackOverflowError) {}
    }

    /**
     * B85.1d helper: resolve the type of a PropertyAccess chain whose root is `this`,
     * consulting [varTypes] for the leaf `this.X` type-name and walking property lookups
     * for each subsequent `.Y` step. Pushes [inferenceNamespaceStack] around each
     * intermediate resolution so namespace-internal type refs resolve correctly.
     */
    private fun resolveReceiverTypeForElementAccess(
        expr: PropertyAccessExpression, varTypes: Map<String, String>
    ): Type? {
        val inner = expr.expression
        // Base case: this.X
        if (inner is Identifier && inner.text == "this") {
            val typeName = varTypes["this.${expr.name.text}"] ?: return null
            // Strip "@" prefix from resolveSimpleTypeName encoding; bail on parameterized types.
            if (!typeName.startsWith("@")) return null
            val bare = typeName.removePrefix("@")
            if (bare.contains('<')) return null
            return resolveTypeNameViaNamespaceExports(bare)
        }
        // B85.1e: Identifier-rooted case `varName.X` — look up `varName` in varTypes.
        if (inner is Identifier) {
            val typeName = varTypes[inner.text] ?: return null
            if (!typeName.startsWith("@")) return null
            val bare = typeName.removePrefix("@")
            if (bare.contains('<')) return null
            val baseType = resolveTypeNameViaNamespaceExports(bare) ?: return null
            val baseObj = baseType as? Type.Object ?: return null
            resolveStructuredTypeMembers(baseObj)
            val propSym = baseObj.members?.get(expr.name.text) ?: return null
            val pushed = baseObj.symbol?.let { pushInferenceNamespaceFor(it) } ?: false
            try {
                val propType = getTypeOfSymbol(propSym)
                return propType.takeIf { it !== anyType && it !== errorType }
            } finally {
                if (pushed) inferenceNamespaceStack.removeLast()
            }
        }
        // Recursive case: this.X.Y
        val innerPA = inner as? PropertyAccessExpression ?: return null
        val baseType = resolveReceiverTypeForElementAccess(innerPA, varTypes) ?: return null
        val baseObj = baseType as? Type.Object ?: return null
        resolveStructuredTypeMembers(baseObj)
        val propSym = baseObj.members?.get(expr.name.text) ?: return null
        // Push the base type's symbol's parent so type refs in the prop's annotation
        // resolve against the enclosing namespace.
        val pushed = baseObj.symbol?.let { pushInferenceNamespaceFor(it) } ?: false
        try {
            val propType = getTypeOfSymbol(propSym)
            return propType.takeIf { it !== anyType && it !== errorType }
        } finally {
            if (pushed) inferenceNamespaceStack.removeLast()
        }
    }

    /**
     * B85.1d helper: resolve a bare type name via current file's locals or — when not at
     * the top level — via BFS through namespace exports (B85.1c's helper). Pushes the
     * enclosing namespace so the resolved type's member-resolution can see sibling types.
     */
    private fun resolveTypeNameViaNamespaceExports(typeName: String): Type? {
        val fileLocals = currentFileLocals ?: return null
        fileLocals[typeName]?.let {
            if (it.flags.hasAny(SymbolFlags.Type)) {
                val pushed = pushInferenceNamespaceFor(it)
                try {
                    return getDeclaredTypeOfSymbol(it).takeIf { t -> t !== anyType && t !== errorType }
                } finally {
                    if (pushed) inferenceNamespaceStack.removeLast()
                }
            }
        }
        val symbol = findSymbolInNamespaceExports(typeName, fileLocals.values) ?: return null
        val pushed = pushInferenceNamespaceFor(symbol)
        try {
            return getDeclaredTypeOfSymbol(symbol).takeIf { it !== anyType && it !== errorType }
        } finally {
            if (pushed) inferenceNamespaceStack.removeLast()
        }
    }

    /**
     * 16.0: For a generic class instance (Type.Reference with Interface target that has
     * type parameters), resolve the property's declared type with the class's type
     * parameters installed in scope, then apply the type mapper to produce the
     * instantiated prop type. Returns null if the object type isn't a generic instance
     * or if resolution fails.
     */
    private fun resolveGenericPropertyType(objType: Type.Object, propSym: Symbol): Type? {
        val ref = objType as? Type.Reference ?: return null
        // Cache result per (objType.id, propSym.id). With Type.Reference interning,
        // logically-identical Refs share an id, so repeated calls during deep generic
        // recursion hit the cache instead of re-allocating Symbols/Signatures/Type.Object
        // (matters for Promise/IPromise overload-permutation comparisons).
        val cacheKey = packRelationKey(ref.id, propSym.id)
        state.resolvedPropertyTypes[cacheKey]?.let { return it }
        val computed = resolveGenericPropertyTypeWorker(ref, propSym)
        if (computed != null) state.resolvedPropertyTypes[cacheKey] = computed
        return computed
    }

    private fun resolveGenericPropertyTypeWorker(ref: Type.Reference, propSym: Symbol): Type? {
        val target = ref.target as? Type.Interface ?: return null
        val typeParams = target.typeParameters ?: return null
        val typeArgs = ref.resolvedTypeArguments ?: return null
        if (typeParams.size != typeArgs.size || typeParams.isEmpty()) return null
        val decl = propSym.valueDeclaration ?: propSym.declarations.firstOrNull() ?: return null
        // 16.0n: Safe cases — either the property is declared directly on the target,
        // or all base-type arguments are unspecialized (pass-through T). This avoids
        // incorrect substitution for `class D<T> extends C<string>` where x on C has
        // T=string, not D's T.
        val targetSym = target.symbol ?: return null
        val isDirectMember = targetSym.declarations.any { tDecl ->
            val classMembers = when (tDecl) {
                is ClassDeclaration -> tDecl.members
                is InterfaceDeclaration -> tDecl.members
                else -> return@any false
            }
            // Direct top-level member, OR a constructor parameter property whose
            // Parameter node lives inside one of the class's Constructor members.
            classMembers.any { it === decl } || classMembers.any { m ->
                m is Constructor && m.parameters.any { it === decl }
            }
        }
        if (!isDirectMember) {
            // Blocker #1 step (d): Inherited property — walk base chain.
            // Instantiate each base via ref's type-param mapper (mapping target's T →
            // ref's typeArg), then recurse into resolveGenericPropertyType on the
            // concrete base. This handles both passthrough (`Array<T> extends IFoo<T>`)
            // and specialized (`class B<U> extends A<string>`) inheritance uniformly:
            // each step applies its own class's mapper to the base's type args, so the
            // property's declared type is resolved in the scope where it was actually
            // declared (A's scope for B extends A).
            val bases = target.baseTypes
            if (bases.isNullOrEmpty()) return null
            val outerMapper = createTypeMapper(typeParams, typeArgs)
            for (base in bases) {
                if (base !is Type.Reference) continue
                val concreteBase = try {
                    instantiateType(base, outerMapper) as? Type.Reference ?: continue
                } catch (_: StackOverflowError) { continue }
                if (concreteBase.id == ref.id) continue
                val result = resolveGenericPropertyType(concreteBase, propSym)
                if (result != null) return result
            }
            return null
        }
        val scope = mutableMapOf<String, Type.TypeParam>()
        currentTypeParamScope?.let { scope.putAll(it) }
        for (tp in typeParams) {
            val name = tp.symbol?.name ?: continue
            scope[name] = tp
        }
        val saved = currentTypeParamScope
        currentTypeParamScope = scope
        return try {
            val mapper = createTypeMapper(typeParams, typeArgs)
            when (decl) {
                is PropertyDeclaration -> {
                    val declType = decl.type ?: return null
                    val rawType = getTypeFromTypeNode(declType)
                    if (rawType === errorType || rawType === anyType) null
                    else if (rawType is Type.Object && rawType !is Type.Reference && rawType !is Type.Interface
                        && (!rawType.callSignatures.isNullOrEmpty() || !rawType.constructSignatures.isNullOrEmpty())) {
                        // 17.39: Function-typed property — substitute outer typeArgs into the
                        // inner sig's TypeParam constraints/defaults + params + return type.
                        // Without this, `interface I<S> { f: <T extends S>(x: T) => void }`'s
                        // f.signature.T retains constraint `S` (un-substituted) at the call site,
                        // blocking 16.4ds per-property elaboration of arg-vs-constraint and 16.4i
                        // TS2345-via-constraint emission. Safe to mutate rawType in-place because
                        // getTypeFromTypeNode bypasses its cache when currentTypeParamScope != null
                        // (active here from the lines above), so rawType is always freshly allocated.
                        substituteOuterTypeArgsInGenericFnObject(rawType, mapper)
                        rawType
                    } else instantiateType(rawType, mapper)
                }
                is GetAccessor -> {
                    val declType = decl.type ?: return null
                    val rawType = getTypeFromTypeNode(declType)
                    if (rawType === errorType || rawType === anyType) null
                    else instantiateType(rawType, mapper)
                }
                is Parameter -> {
                    val declType = decl.type ?: return null
                    val rawType = getTypeFromTypeNode(declType)
                    if (rawType === errorType || rawType === anyType) null
                    else instantiateType(rawType, mapper)
                }
                is MethodDeclaration -> {
                    // 16.0n: Build an instantiated method type (Type.Object with call signatures)
                    // with return/param types substituted. Scope is active so T in declarations
                    // resolves to the target's TypeParam, which the mapper then substitutes.
                    val methodDecls = propSym.declarations.filterIsInstance<MethodDeclaration>()
                    val overloadDecls = methodDecls.filter { it.body == null }
                    val implDecl = methodDecls.find { it.body != null }
                    val sigDecls = if (overloadDecls.isNotEmpty()) overloadDecls else listOfNotNull(implDecl)
                    if (sigDecls.isEmpty()) return null
                    val sigs = sigDecls.map { md ->
                        // 16.4h: Preserve method's own type params with constraints
                        // instantiated via the class mapper — so `<U extends T>` on a
                        // method of C<T>, when accessed via x: C<number>, becomes
                        // `<U extends number>` for TS2344 checking on explicit type args.
                        val methodTypeParams = md.typeParameters?.map { tpDecl ->
                            Type.TypeParam().also { tp ->
                                tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                            }
                        }
                        val savedMethodScope = currentTypeParamScope
                        if (!methodTypeParams.isNullOrEmpty()) {
                            val methodScope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                            methodTypeParams.forEachIndexed { i, tp ->
                                methodScope[md.typeParameters!![i].name.text] = tp
                            }
                            currentTypeParamScope = methodScope
                        }
                        try {
                            methodTypeParams?.forEachIndexed { i, tp ->
                                val tpDecl = md.typeParameters!![i]
                                tpDecl.constraint?.let { cNode ->
                                    val raw = getTypeFromTypeNode(cNode)
                                    tp.constraint = if (raw === errorType) raw
                                                    else instantiateType(raw, mapper)
                                }
                                tpDecl.default?.let { dNode ->
                                    val raw = getTypeFromTypeNode(dNode)
                                    tp.default = if (raw === errorType) raw
                                                 else instantiateType(raw, mapper)
                                }
                            }
                            val rawReturn = md.type?.let { getTypeFromTypeNode(it) }
                                ?: inferSimpleReturnTypeFromBody(md, target)
                                ?: md.body?.let {
                                    if (!bodyHasReturnValue(it)) voidType else null
                                }
                                ?: anyType
                            val returnType = if (rawReturn === errorType) anyType
                                             else instantiateType(rawReturn, mapper)
                            val params = md.parameters.mapNotNull { p ->
                                val pName = (p.name as? Identifier)?.text ?: return@mapNotNull null
                                if (pName == "this") return@mapNotNull null
                                val sym = Symbol(SymbolFlags.FunctionScopedVariable, pName)
                                sym.declarations.add(p)
                                sym.valueDeclaration = p
                                val rawParamType = p.type?.let { getTypeFromTypeNode(it) } ?: anyType
                                val paramType = if (rawParamType === errorType) anyType
                                                else if (rawParamType is Type.Object
                                                    && rawParamType !is Type.Reference
                                                    && rawParamType !is Type.Interface
                                                    && (!rawParamType.callSignatures.isNullOrEmpty()
                                                        || !rawParamType.constructSignatures.isNullOrEmpty())) {
                                                    // B81.1d: function-typed parameter (e.g.
                                                    // `compareFn?: (a: T, b: T) => number`). Plain
                                                    // instantiateType is a no-op for function-shaped
                                                    // Type.Object (see CLAUDE.md instantiateType
                                                    // gotcha). Use the in-place sig walker so callers
                                                    // resolving the method's param type for contextual
                                                    // inference (B81.1b FunctionExpression branch) see
                                                    // the substituted inner sig.
                                                    substituteOuterTypeArgsInGenericFnObject(rawParamType, mapper)
                                                    rawParamType
                                                } else instantiateType(rawParamType, mapper)
                                symbolTypes[sym.id] = paramType
                                sym
                            }
                            Signature(
                                declaration = md,
                                typeParameters = methodTypeParams,
                                parameters = params,
                                resolvedReturnType = returnType,
                                minArgumentCount = md.parameters.count {
                                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                                },
                            )
                        } finally {
                            currentTypeParamScope = savedMethodScope
                        }
                    }
                    val fnType = Type.Object()
                    fnType.callSignatures = sigs
                    fnType.properties = emptyList()
                    fnType
                }
                else -> null
            }
        } catch (_: StackOverflowError) {
            null
        } finally {
            currentTypeParamScope = saved
        }
    }

    /**
     * Blocker #1 step (c): narrow return-type-from-body inference for methods
     * with no return annotation. Caller must have set up `currentTypeParamScope`
     * so type-arg references like `T` resolve to the enclosing class's
     * canonical Type.TypeParam (subsequent `instantiateType` then substitutes
     * the target's concrete args). Returns null for unhandled patterns —
     * callers fall back to `anyType`.
     *
     * Currently handles single-statement bodies of the form:
     * - `return new X<...>(...)` — class/interface ref construction
     * - `return <stringLit>` / `return <numLit>` / `return -<numLit>`
     *   / `return true|false` — primitive literal returns
     *
     * Unblocks cases like `a.clone()` on `a: MyList<string>` where `clone()`
     * in `class MyList<T>` returns `new MyList<T>(…)`, so the inferred return
     * type is `MyList<T>` which substitutes to `MyList<string>` at the call
     * site. The primitive-literal cases improve TS2322 elaboration depth on
     * generic interface-method comparison (e.g. `class A<T> implements
     * Comparable<T> { compareTo(other: T) { return 1; } }` — without literal
     * inference, the elaboration shows `(other: number) => any` instead of
     * `(other: number) => number` and downstream parameter-mismatch chain lines
     * are suppressed by the trivial-any return-type compatibility shortcut).
     */
    private fun inferSimpleReturnTypeFromBody(md: MethodDeclaration, enclosingClass: Type.Interface? = null): Type? {
        val stmts = md.body?.statements ?: return null
        // B4.1: locate the body's single top-level ReturnStatement. Multi-statement
        // bodies like `function clone() { console.log("..."); return new MyList<T>(...) }`
        // should still produce inferred return type when exactly one top-level
        // ReturnStatement carries an expression. No recursion into nested blocks /
        // if-bodies / loops — those have multiple paths that LUB-aware inference
        // can't handle yet, and falling back to anyType is correct there.
        var retStmt: ReturnStatement? = null
        for (s in stmts) {
            if (s is ReturnStatement) {
                if (retStmt != null) return null  // 2+ top-level returns: bail
                retStmt = s
            }
        }
        if (retStmt == null) return null
        val retExpr = retStmt.expression ?: return null
        return when (retExpr) {
            is StringLiteralNode -> stringType
            is NoSubstitutionTemplateLiteralNode -> stringType
            is NumericLiteralNode -> numberType
            is PrefixUnaryExpression ->
                if (retExpr.operand is NumericLiteralNode) numberType else null
            is Identifier -> when (retExpr.text) {
                "true", "false" -> booleanType
                else -> {
                    // B4.2: `return paramName` where param has explicit type annotation.
                    // `currentTypeParamScope` is already set up by the caller
                    // (`resolveGenericPropertyType` arm at Checker.kt ~39548) to include
                    // both the class's type params and the method's own type params, so
                    // `getTypeFromTypeNode` correctly resolves `T` references. The caller
                    // then substitutes via `instantiateType(rawReturn, mapper)` to map
                    // class TypeParams to the target's concrete type args. Only fires
                    // when (a) the identifier matches a parameter name exactly and
                    // (b) the parameter has an explicit type annotation — un-annotated
                    // params fall through to `null` so the caller falls back to anyType.
                    // errorType resolution (unresolvable type names) is also filtered to
                    // null at the caller via `if (rawReturn === errorType) anyType`.
                    val matchedParam = md.parameters.find {
                        (it.name as? Identifier)?.text == retExpr.text
                    }
                    val annotation = matchedParam?.type ?: return null
                    val resolved = try { getTypeFromTypeNode(annotation) } catch (_: StackOverflowError) { null }
                    if (resolved === errorType || resolved === anyType) null else resolved
                }
            }
            is NewExpression -> {
                val callee = retExpr.expression as? Identifier ?: return null
                try {
                    val calleeType = getTypeOfIdentifier(callee)
                    if (calleeType !is Type.Interface) return null
                    val typeParams = calleeType.typeParameters
                    val typeArgs = retExpr.typeArguments
                    // Non-generic target: return the interface itself (only when no typeArgs were supplied).
                    if (typeParams.isNullOrEmpty()) {
                        return if (typeArgs.isNullOrEmpty()) calleeType else null
                    }
                    if (typeArgs == null || typeArgs.size != typeParams.size) return null
                    val resolvedArgs = typeArgs.map { getTypeFromTypeNode(it) }
                    if (resolvedArgs.any { it === errorType }) return null
                    getOrInternReference(calleeType, resolvedArgs)
                } catch (_: StackOverflowError) {
                    null
                }
            }
            is PropertyAccessExpression -> {
                // B4.3: `return this.field` — look up the field on the enclosing class.
                // Only fires when (a) caller passed `enclosingClass`, (b) the receiver is
                // `ThisExpression`, (c) the field is a PropertyDeclaration on the same
                // class with an explicit type annotation. Conservative scope: skips
                // inherited properties (which would need base-chain mapper application)
                // and accessor declarations (get/set semantics differ).
                if (enclosingClass == null) return null
                val receiver = retExpr.expression as? Identifier ?: return null
                if (receiver.text != "this") return null
                val fieldName = retExpr.name.text
                val classDecls = enclosingClass.symbol?.declarations ?: return null
                for (cDecl in classDecls) {
                    val members = when (cDecl) {
                        is ClassDeclaration -> cDecl.members
                        is InterfaceDeclaration -> cDecl.members
                        else -> continue
                    }
                    val match = members.firstOrNull {
                        it is PropertyDeclaration &&
                            (it.name as? Identifier)?.text == fieldName
                    } as? PropertyDeclaration ?: continue
                    val annotation = match.type ?: return null
                    return try {
                        val raw = getTypeFromTypeNode(annotation)
                        if (raw === errorType || raw === anyType) null else raw
                    } catch (_: StackOverflowError) { null }
                }
                null
            }
            else -> null
        }
    }

    /**
     * 16.0: Check assignability of value to a property access target like `x.prop = value`.
     * Resolves x's type, looks up the property symbol, gets its declared type, and emits
     * TS2322 if value type isn't assignable.
     */
    private fun checkPropertyAccessAssignment(
        target: PropertyAccessExpression, value: Expression, source: String, fileName: String
    ) {
        try {
            val propName = target.name.text
            // Namespace-property fallback: when target is `Namespace.member` (or
            // `Outer.Inner.member`), resolve the namespace symbol's exported member
            // directly. Required because `getTypeOfExpression(Namespace_Identifier)`
            // returns anyType (Module-flagged symbols have no Type representation),
            // which would short-circuit the existing Type.Object path.
            val nsBaseSymbol: Symbol? = when (val baseExpr = target.expression) {
                is Identifier -> currentFileLocals?.get(baseExpr.text) ?: globals[baseExpr.text]
                is PropertyAccessExpression -> resolvePropertyAccessToSymbol(baseExpr)
                else -> null
            }
            var propType: Type? = null
            // Whether the resolved property is an accessor (get/set) — for these, our
            // write-type resolution (setter param type) does NOT substitute the class's
            // type args into the setter annotation (e.g. `set foo(s: T | undefined)` on
            // `Test1<string>` resolves to `string`, NOT `string | undefined`), so the
            // null/undefined-falls-through path below would FP. Bail for nullish RHS on
            // accessor properties (divergentAccessorsTypes2). Plain data fields are fine.
            var propIsAccessor = false
            if (nsBaseSymbol != null && nsBaseSymbol.flags.hasAny(SymbolFlags.Module)) {
                val exportSym = nsBaseSymbol.exports?.get(propName)
                if (exportSym != null) {
                    val resolved = getTypeOfSymbol(exportSym)
                    if (resolved !== anyType && resolved !== errorType) propType = resolved
                }
            }
            if (propType == null) {
                val objType = getTypeOfExpression(target.expression)
                if (objType === anyType || objType === errorType) return
                // 17.72: Intersection-typed receiver — compute write type as the
                // intersection of per-constituent write types (setter param types
                // OR regular property types), distribute over unions, and reduce
                // literal-vs-primitive subtype pairs. Gate on at least one
                // constituent contributing via SetAccessor — preserves existing
                // behavior for plain property intersections.
                if (objType is Type.Intersection) {
                    if (checkIntersectionPropertyAssignment(target, value, objType, propName, source, fileName)) return
                    return
                }
                if (objType !is Type.Object) return
                resolveStructuredTypeMembers(objType)
                val propSym = objType.members?.get(propName) ?: return
                // B54.5: For accessor pairs (get + set), `x.x = v` uses the SETTER's
                // parameter type for the write check (NOT the getter return type). Pairs
                // with B54.6's accessor-pair-declarations merging — together they let
                // checkPropertyAccessAssignment detect a write context against a setter.
                val setAccessorDecl = propSym.declarations.firstOrNull { it is SetAccessor } as? SetAccessor
                propIsAccessor = setAccessorDecl != null ||
                    propSym.declarations.any { it is GetAccessor }
                val setterParamTypeNode = setAccessorDecl?.parameters?.firstOrNull()?.type
                val setterResolvedType = setterParamTypeNode?.let {
                    try { getTypeFromTypeNode(it) } catch (_: StackOverflowError) { null }
                }
                // 16.0: For generic class instance types (Type.Reference with type args),
                // resolve the property's declared type with the class's type parameters in
                // scope, then apply the type mapper. This produces the correctly instantiated
                // prop type (e.g. `T → string` for `new Test1<string>()`).
                // B82.1-ext (iter8): When receiver is a class instance (Type.Interface,
                // not Reference) and the resolved property comes from a GENERIC base
                // (e.g. `class D extends C<string>` writing `d.x = v` where `x` is
                // declared on `C<T>`), use findInheritedBaseRef + resolveGenericPropertyType
                // to substitute the base's type args into the property's type. Mirrors
                // the pattern from getTypeOfPropertyAccess (Checker.kt:~54400).
                // Gate: prop.parent must differ from objType.symbol (only inherited members).
                val inheritedResolved: Type? = if (objType is Type.Interface && objType !is Type.Reference) {
                    val propParent = propSym.parent
                    if (propParent != null && propParent !== objType.symbol) {
                        findInheritedBaseRef(objType, propParent)?.let { baseRef ->
                            resolveGenericPropertyType(baseRef, propSym)
                        }
                    } else null
                } else null
                val resolved = setterResolvedType?.takeIf { it !== anyType && it !== errorType }
                    ?: inheritedResolved
                    ?: resolveGenericPropertyType(objType, propSym) ?: getTypeOfSymbol(propSym)
                if (resolved === anyType || resolved === errorType) return
                propType = resolved
            }
            val pt = propType
            val valueType = getTypeOfExpression(value)
            if (valueType === anyType || valueType === errorType) return
            // void source: bail unconditionally (no test exercises void-property-assign).
            if (valueType.flags.hasAny(TypeFlags.Void)) return
            // null/undefined source: under strictNullChecks this IS an error against a
            // non-nullable property target (e.g. `a.id = null` where `id: number`, including
            // the chained `a.id = b.value = null` shape — chainedAssignment3). Bail only when
            // strictNullChecks is off (null/undefined assignable to everything) or when the
            // target legitimately accepts null/undefined; otherwise fall through to the relation
            // check below, which fails and emits "Type 'null' is not assignable to type 'X'.".
            if (valueType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) {
                if (!strictNullChecks || propIsAccessor ||
                    typeIncludesNull(pt) || typeIncludesUndefined(pt)) return
            }
            // 17.14a: Non-constructible source vs constructible target — `canUseTypeEngine`'s
            // gate at ~31688 short-circuits this case to skip class-instance vs constructor-type
            // comparisons, but TypeScript flags the assignment with a "provides no match for
            // the signature 'new ...'" elaboration. Handle directly before the gate fires.
            // Skip when target is a class/interface instance type — its construct signatures
            // belong to the static side, and instance↔instance comparisons should go through
            // the regular relation path with property-mismatch elaboration.
            if (pt is Type.Object && !pt.constructSignatures.isNullOrEmpty() &&
                !isClassOrInterfaceInstanceType(pt)) {
                val srcCtorElab = getNonConstructibleElaboration(valueType, pt)
                if (srcCtorElab != null) {
                    val displaySource = typeToString(valueType)
                    val displayTarget = typeToString(pt)
                    val start = target.expression.pos
                    val length = target.name.pos + target.name.text.length - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = srcCtorElab,
                    ))
                    return
                }
            }
            if (!canUseTypeEngine(valueType, pt)) return
            lastMissingIndexSigKind = null
            if (checkTypeRelatedTo(valueType, pt, assignableRelation)) return
            // Object literal — emit TS2353 for excess instead
            if (value is ObjectLiteralExpression) {
                val displayTarget = typeToString(pt)
                if (checkExcessProperties(value, valueType, pt, displayTarget, source, fileName)) return
            }
            val displaySource = typeToString(valueType)
            val displayTarget = typeToString(pt)
            // Property-level elaboration chain (16.1) — adds "Types of property 'X' are
            // incompatible." + nested type chain when source/target are both objects.
            val chain = mutableListOf<String>()
            if (valueType is Type.Object && pt is Type.Object) {
                lastChainMissingPropSymbol = null
                getPropertyElaborationChain(valueType, pt)?.let { chain.addAll(it) }
            }
            // Missing index signature elaboration (mirrors var-decl path at ~33177): when
            // the relation failed because target has a string/number index signature that
            // source doesn't, emit "Index signature for type '<kind>' is missing in type 'X'.".
            if (chain.isEmpty() && lastMissingIndexSigKind != null) {
                chain.add("  Index signature for type '${lastMissingIndexSigKind}' is missing in type '$displaySource'.")
            }
            // 17.10a: When source isn't callable but target is, emit
            // "Type 'X' provides no match for the signature 'sig'." — matches
            // TypeScript's elaboration for non-callable source vs callable target
            // (e.g. interface instance assigned to a function-typed property).
            if (chain.isEmpty()) {
                getCallableMismatchElaboration(valueType, pt)?.let { chain.addAll(it) }
            }
            // Squiggle spans the whole property access `obj.prop`
            val start = target.expression.pos
            val length = target.name.pos + target.name.text.length - start
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
                messageChain = chain.toList(),
            ))
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * 17.72: Handle property assignment on an intersection-typed receiver.
     * Walks the intersection's constituents (each a Type.Object), looks up the
     * property's WRITE type on each (SetAccessor's param type for getter/setter
     * pairs, or the property type for regular properties), then reduces the
     * intersection of write types via [reduceIntersectionForWriteType] (which
     * distributes over unions and applies literal/primitive subtype reduction).
     *
     * Gated on at least one constituent contributing via SetAccessor — without
     * this gate, plain property intersections like `{x: number} & {x: string}`
     * would emit new diagnostics, regressing existing tests.
     *
     * Returns `true` if a TS2322 was emitted (caller should return), `false` if
     * the path didn't apply (caller may continue but typically returns since
     * we've already handled the intersection case).
     */
    private fun checkIntersectionPropertyAssignment(
        target: PropertyAccessExpression,
        value: Expression,
        intersection: Type.Intersection,
        propName: String,
        source: String,
        fileName: String,
    ): Boolean {
        val writeTypes = mutableListOf<Type>()
        var hasSetterContribution = false
        var hasReadOnlyConstituent = false
        for (constituent in intersection.types) {
            if (constituent !is Type.Object) continue
            try { resolveStructuredTypeMembers(constituent) } catch (_: StackOverflowError) { continue }
            // Symbol with declarations (Class/Interface) — walk class members
            // directly to find SetAccessor / GetAccessor / PropertyDeclaration.
            val constSym = constituent.symbol ?: continue
            var setterDecl: SetAccessor? = null
            var getterDecl: GetAccessor? = null
            var propertyDecl: PropertyDeclaration? = null
            for (decl in constSym.declarations) {
                val classMembers = when (decl) {
                    is ClassDeclaration -> decl.members
                    is InterfaceDeclaration -> decl.members
                    else -> continue
                }
                for (m in classMembers) {
                    when (m) {
                        is SetAccessor -> if (getMemberName(m.name) == propName) setterDecl = m
                        is GetAccessor -> if (getMemberName(m.name) == propName) getterDecl = m
                        is PropertyDeclaration -> if (getMemberName(m.name) == propName) propertyDecl = m
                        else -> {}
                    }
                }
            }
            // Also inspect type-literal members when the constituent is an
            // anonymous object type (e.g. `type T = { get x(): string; set x(v: ...): void }`).
            // These don't have a Class/InterfaceDeclaration but do have a
            // TypeLiteral whose members were processed by resolveAnonymousTypeMembers.
            val writeType: Type? = when {
                setterDecl != null -> {
                    hasSetterContribution = true
                    val firstParam = setterDecl.parameters.firstOrNull()
                    firstParam?.type?.let { getTypeFromTypeNode(it) }
                }
                getterDecl != null && propertyDecl == null -> {
                    // Read-only — track but contribute null so intersection skips this constituent.
                    // Writing to a read-only property fires TS2540 elsewhere.
                    hasReadOnlyConstituent = true
                    null
                }
                propertyDecl != null -> {
                    val propSym = constituent.members?.get(propName)
                    if (propSym == null) null
                    else {
                        val resolved = resolveGenericPropertyType(constituent, propSym)
                            ?: getTypeOfSymbol(propSym)
                        if (resolved !== anyType && resolved !== errorType) resolved else null
                    }
                }
                else -> null
            }
            if (writeType != null && writeType !== errorType && writeType !== anyType) {
                writeTypes.add(writeType)
            }
        }
        // Gate: only emit when at least one setter contributed. This preserves
        // existing behavior for plain property intersections.
        if (!hasSetterContribution) return false
        if (hasReadOnlyConstituent) return false  // Skip — read-only intersection emits TS2540
        if (writeTypes.isEmpty()) return false

        val reducedTarget = reduceIntersectionForWriteType(writeTypes)
        if (reducedTarget === anyType || reducedTarget === errorType) return false
        if (reducedTarget.flags.hasAny(TypeFlags.Never)) return false  // Can't write anything; defer to TS2540

        // 17.72: When target contains literal types, preserve the value's literal
        // type instead of widening to the primitive — same pattern as 17.66/17.67
        // for var-decl init / assignment RHS / call arg sites. Required so
        // `i.prop2 = 42` where reducedTarget==`42` succeeds (42 ≡ 42), and so
        // failing assignments display the literal source (e.g. `'"hello"'` not
        // `'string'`).
        val valueType = if (propTypeContainsLiteral(reducedTarget)) {
            literalTypeOfExpression(value) ?: getTypeOfExpression(value)
        } else {
            getTypeOfExpression(value)
        }
        if (valueType === anyType || valueType === errorType) return false
        if (valueType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return false

        if (checkTypeRelatedTo(valueType, reducedTarget, assignableRelation)) return false

        val displaySource = typeToString(valueType)
        val displayTarget = typeToString(reducedTarget)
        val start = target.expression.pos
        val length = target.name.pos + target.name.text.length - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
            category = DiagnosticCategory.Error,
            code = 2322,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return true
    }

    /**
     * Reduce an intersection of types by pairwise distribution over unions and
     * primitive/literal subtype reduction. Used by [checkIntersectionPropertyAssignment].
     *
     * - `(A | B) & C` → `(A & C) | (B & C)` (distribute)
     * - `42 & number` → `42` (literal subtype of primitive)
     * - `string & number` → `never` (incompatible primitive flags)
     * - `"a" & "b"` → `never` (different literal values, same kind)
     */
    private fun reduceIntersectionForWriteType(types: List<Type>): Type {
        if (types.isEmpty()) return unknownType
        var current: Type = types[0]
        for (i in 1 until types.size) {
            current = intersectTwoTypesForWrite(current, types[i])
            if (current.flags.hasAny(TypeFlags.Never)) return neverType
        }
        return current
    }

    private fun intersectTwoTypesForWrite(a: Type, b: Type): Type {
        if (a === b) return a
        if (a.flags.hasAny(TypeFlags.Never) || b.flags.hasAny(TypeFlags.Never)) return neverType
        if (a.flags.hasAny(TypeFlags.Any)) return b
        if (b.flags.hasAny(TypeFlags.Any)) return a
        if (a.flags.hasAny(TypeFlags.Unknown)) return b
        if (b.flags.hasAny(TypeFlags.Unknown)) return a

        // Distribute over Union: (X | Y) & Z = (X & Z) | (Y & Z)
        if (a is Type.Union) {
            val mapped = a.types.map { intersectTwoTypesForWrite(it, b) }
            return getUnionType(mapped)
        }
        if (b is Type.Union) {
            val mapped = b.types.map { intersectTwoTypesForWrite(a, it) }
            return getUnionType(mapped)
        }

        // Both non-union, non-special — apply primitive / literal pairwise reduction.
        val literalFlags = TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral
        val primFlags = TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.BigInt or TypeFlags.ESSymbol
        val aIsLit = a.flags.hasAny(literalFlags)
        val bIsLit = b.flags.hasAny(literalFlags)
        val aIsPrim = a.flags.hasAny(primFlags)
        val bIsPrim = b.flags.hasAny(primFlags)

        if (aIsLit && bIsPrim) return if (literalMatchesPrimitive(a, b)) a else neverType
        if (bIsLit && aIsPrim) return if (literalMatchesPrimitive(b, a)) b else neverType
        if (aIsLit && bIsLit) {
            // Same kind?
            if (a is Type.StringLiteral && b is Type.StringLiteral) {
                return if (a.value == b.value) a else neverType
            }
            if (a is Type.NumberLiteral && b is Type.NumberLiteral) {
                return if (a.value == b.value) a else neverType
            }
            if (a is Type.BigIntLiteral && b is Type.BigIntLiteral) {
                return if (a.value == b.value) a else neverType
            }
            if (a is Type.Intrinsic && b is Type.Intrinsic &&
                a.flags.hasAny(TypeFlags.BooleanLiteral) && b.flags.hasAny(TypeFlags.BooleanLiteral)) {
                return if (a.intrinsicName == b.intrinsicName) a else neverType
            }
            // Different literal kinds → incompatible
            return neverType
        }
        if (aIsPrim && bIsPrim) {
            // Same primitive flag → take one; different → never.
            val af = a.flags.value and primFlags.value
            val bf = b.flags.value and primFlags.value
            return if (af == bf) a else neverType
        }

        // General case (object types, etc.) — fall back to plain intersection.
        return getIntersectionType(listOf(a, b))
    }

    private fun literalMatchesPrimitive(literal: Type, primitive: Type): Boolean = when {
        literal.flags.hasAny(TypeFlags.StringLiteral) && primitive.flags.hasAny(TypeFlags.String) -> true
        literal.flags.hasAny(TypeFlags.NumberLiteral) && primitive.flags.hasAny(TypeFlags.Number) -> true
        literal.flags.hasAny(TypeFlags.BooleanLiteral) && primitive.flags.hasAny(TypeFlags.Boolean) -> true
        literal.flags.hasAny(TypeFlags.BigIntLiteral) && primitive.flags.hasAny(TypeFlags.BigInt) -> true
        else -> false
    }

    /**
     * 17.10a: Elaboration line for non-callable source vs callable target.
     * Returns "  Type 'X' provides no match for the signature 'sig'." when the
     * source has NO call signatures while the target has at least one — covers
     * the assignmentCompatability24/33/34 family and similar patterns.
     * Returns null when not applicable (caller falls through to other elaboration paths).
     */
    private fun getCallableMismatchElaboration(source: Type, target: Type): List<String>? {
        if (target !is Type.Object) return null
        try { resolveStructuredTypeMembers(target) } catch (_: StackOverflowError) { return null }
        val targetSigs = target.callSignatures
        if (targetSigs.isNullOrEmpty()) return null
        // 17.74: Skip primitive sources — TypeScript emits the "provides no match
        // for the signature" chain only for object-shaped sources lacking a call
        // signature, not for primitives like `string`, `number`, etc. (cf.
        // assignToFn.ts where `x.f = "hello"` against `f: (n:number)=>boolean`
        // expects the bare TS2322 with no chain).
        if (source is Type.Intrinsic || source is Type.StringLiteral ||
            source is Type.NumberLiteral || source is Type.BigIntLiteral) return null
        // Source must be non-callable (no own call sigs)
        val sourceObj = source as? Type.Object
        if (sourceObj != null) {
            try { resolveStructuredTypeMembers(sourceObj) } catch (_: StackOverflowError) { return null }
            if (!sourceObj.callSignatures.isNullOrEmpty()) return null
        }
        val targetSig = targetSigs.first()
        return listOf(
            "  Type '${typeToString(source)}' provides no match for the signature '${signatureToStringColon(targetSig, isConstruct = false)}'."
        )
    }

    /**
     * 17.14a: Mirror of [getCallableMismatchElaboration] for the construct-sig case.
     * Returns "  Type 'X' provides no match for the signature 'new <T>(p: T): R'."
     * when the source has NO construct signatures while the target has at least one
     * — covers the assignmentCompatability37/38 family (interface-instance source vs
     * `{ new <T>(p: T): any }` target).
     */
    private fun getNonConstructibleElaboration(source: Type, target: Type): List<String>? {
        if (target !is Type.Object) return null
        try { resolveStructuredTypeMembers(target) } catch (_: StackOverflowError) { return null }
        val targetSigs = target.constructSignatures
        if (targetSigs.isNullOrEmpty()) return null
        val sourceObj = source as? Type.Object
        if (sourceObj != null) {
            try { resolveStructuredTypeMembers(sourceObj) } catch (_: StackOverflowError) { return null }
            if (!sourceObj.constructSignatures.isNullOrEmpty()) return null
        }
        val targetSig = targetSigs.first()
        return listOf(
            "  Type '${typeToString(source)}' provides no match for the signature '${signatureToStringColon(targetSig, isConstruct = true)}'."
        )
    }

    // -----------------------------------------------------------------------
    // Type resolution from TypeNodes (Phase 4 — semantic Type objects)
    // -----------------------------------------------------------------------

    /**
     * Convert an AST TypeNode into a semantic [Type] object.
     * Results are cached in [nodeTypes].
     *
     * 16.0: When [currentTypeParamScope] is active, bypass the cache — the same node
     * may resolve differently depending on the enclosing class/interface's type
     * parameters in scope (e.g. `T` means different things in different classes).
     *
     * Also bypass the cache when [inferenceNamespaceStack] is active — namespace-aware
     * lookup in [getTypeFromTypeReference] resolves type names against the enclosing
     * namespace's exports, which may differ from the un-scoped resolution that would
     * have been cached.
     */
    private fun getTypeFromTypeNode(node: TypeNode): Type {
        val cacheable = currentTypeParamScope == null && inferenceNamespaceStack.isEmpty() &&
            currentTypeAliasArgs == null
        if (cacheable) {
            nodeTypes[node]?.let { return it }
        }
        val type = getTypeFromTypeNodeWorker(node)
        if (cacheable) {
            nodeTypes[node] = type
        }
        return type
    }

    private fun getTypeFromTypeNodeWorker(node: TypeNode): Type {
        return when (node) {
            is KeywordTypeNode -> getTypeFromKeyword(node.kind)
            is TypeReference -> getTypeFromTypeReference(node)
            is UnionType -> getUnionType(node.types.map { getTypeFromTypeNode(it) })
            is IntersectionType -> {
                val resolved = node.types.map { getTypeFromTypeNode(it) }
                val result = getIntersectionType(resolved)
                // B8.1: capture reduction reason when getIntersectionType returned never
                // due to a private-conflict between class constituents. Cache is keyed by
                // the AST IntersectionType node; downstream TS2322 / TS2339 emission
                // looks up the variable's annotation node to recover the chain text.
                if (result === neverType) {
                    val conflictProp = findConflictingPrivateInIntersection(resolved)
                    if (conflictProp != null) {
                        val displayString = formatTypeForDisplay(node) ?: resolved.joinToString(" & ") { typeToString(it) }
                        state.intersectionReductionReasons[node] = IntersectionReductionReason(
                            displayString = displayString,
                            conflictingPropName = conflictProp,
                        )
                    }
                }
                result
            }
            is ArrayType -> getArrayType(getTypeFromTypeNode(node.elementType))
            is TupleType -> getTupleType(node)
            is LiteralType -> getTypeFromLiteralTypeNode(node)
            is FunctionType -> getFunctionTypeFromNode(node)
            is ConstructorType -> getFunctionTypeFromConstructorNode(node)
            is TypeQuery -> getTypeFromTypeQuery(node)
            is ParenthesizedType -> getTypeFromTypeNode(node.type)
            is ThisType -> anyType // TODO: proper this-type resolution
            is TypePredicate -> booleanType
            is TypeLiteral -> getTypeFromTypeLiteral(node)
            is TypeOperator -> getTypeFromTypeOperator(node)
            is IndexedAccessType -> getTypeFromIndexedAccess(node)
            is ConditionalType -> getTypeFromConditionalType(node)
            is MappedType -> getTypeFromMappedType(node)
            is TemplateLiteralType -> {
                // B65.1: preserve source-text rendering for TS2339 / TS2345 /
                // TS2322 messages. Parser stashes the raw source slice (including
                // backticks) in `head.rawText` (no real spans built). Each call
                // to this branch (post-nodeTypes-cache check) mints a fresh
                // Type.Intrinsic so distinct call sites get distinct ids, but
                // all carry TypeFlags.String so assignability is unchanged.
                val raw = node.head.rawText
                if (raw.isNullOrEmpty()) {
                    stringType
                } else {
                    val t = Type.Intrinsic(TypeFlags.String, "string")
                    templateLiteralDisplay[t.id] = raw
                    t
                }
            }
            is InferType -> anyType // only valid inside conditional types
            is RestType -> getTypeFromTypeNode(node.type) // unwrap rest
            is NamedTupleMember -> getTypeFromTypeNode(node.type) // unwrap named tuple member
            is OptionalType -> getTypeFromTypeNode(node.type) // unwrap optional (adds undefined)
            is ImportType -> anyType // TODO: import types
            is TemplateLiteralTypeSpan -> anyType // shouldn't be visited directly
        }
    }

    /** Map keyword SyntaxKind to intrinsic type singleton. */
    private fun getTypeFromKeyword(kind: SyntaxKind): Type {
        return when (kind) {
            SyntaxKind.NumberKeyword -> numberType
            SyntaxKind.StringKeyword -> stringType
            SyntaxKind.BooleanKeyword -> booleanType
            SyntaxKind.VoidKeyword -> voidType
            SyntaxKind.AnyKeyword -> anyType
            SyntaxKind.UnknownKeyword -> unknownType
            SyntaxKind.NeverKeyword -> neverType
            SyntaxKind.ObjectKeyword -> nonPrimitiveType
            SyntaxKind.SymbolKeyword -> esSymbolType
            SyntaxKind.BigIntKeyword -> bigintType
            SyntaxKind.UndefinedKeyword -> undefinedType
            SyntaxKind.NullKeyword -> nullType
            SyntaxKind.TrueKeyword -> trueType
            SyntaxKind.FalseKeyword -> falseType
            else -> errorType
        }
    }

    /** Resolve a TypeReference node (e.g., `Foo`, `Array<string>`, `A.B`) to a Type. */
    /** B50.3: Pick the union constituent that shares the MOST property names with
     *  `source` for source-vs-union elaboration. Returns null if no Object-shaped
     *  constituent shares any properties (e.g. `string | number` target). For ties,
     *  the first matching constituent wins. */
    private fun findBestUnionConstituent(source: Type.Object, target: Type.Union): Type? {
        resolveStructuredTypeMembers(source)
        val sourcePropNames = source.properties?.map { it.name }?.toSet() ?: return null
        if (sourcePropNames.isEmpty()) return null
        var best: Type? = null
        var bestScore = -1
        for (c in target.types) {
            if (c !is Type.Object) continue
            resolveStructuredTypeMembers(c)
            val constNames = c.properties?.map { it.name }?.toSet() ?: continue
            val shared = sourcePropNames.intersect(constNames).size
            if (shared > bestScore) {
                bestScore = shared
                best = c
            }
        }
        return if (bestScore > 0) best else null
    }

    /** B50.1: True for alias body types that are function-shaped: `FunctionType`,
     *  `ConstructorType`, `ParenthesizedType` around one of those, or `TypeLiteral`
     *  whose ONLY members are call signatures. The B50.1 substitution skips these
     *  because the comparison engine compares them via callSignatures, where
     *  un-inferred TypeParams (from generic function-call return-types) collide
     *  with the now-concrete alias args — producing FP TS2322. */
    private fun isFunctionTypeAliasBody(t: TypeNode): Boolean {
        return when (t) {
            is FunctionType, is ConstructorType -> true
            is ParenthesizedType -> isFunctionTypeAliasBody(t.type)
            is TypeLiteral -> t.members.isNotEmpty() && t.members.all { m ->
                m is MethodDeclaration && (m.name as? Identifier)?.text == ""
            }
            else -> false
        }
    }

    private fun getTypeFromTypeReference(node: TypeReference): Type {
        val name = getTypeReferenceLastName(node.typeName) ?: return errorType
        // Check for built-in generic types
        when (name) {
            "Array" -> {
                val typeArgs = node.typeArguments
                if (typeArgs != null && typeArgs.size == 1) {
                    return getArrayType(getTypeFromTypeNode(typeArgs[0]))
                }
            }
            "ReadonlyArray" -> {
                val typeArgs = node.typeArguments
                if (typeArgs != null && typeArgs.size == 1) {
                    val elt = getTypeFromTypeNode(typeArgs[0])
                    val roTarget = globalReadonlyArrayType ?: globalArrayType
                    return getOrInternReference(roTarget, listOf(elt))
                }
            }
        }
        // 16.0: Check enclosing class/interface type parameter scope before globals
        currentTypeParamScope?.get(name)?.let { return it }
        // B50.1: Check generic type alias arg-substitution map. Inside a type alias
        // body resolution (when the outer `getTypeFromTypeReference` pushed the alias's
        // type parameters → concrete arg types), a body-internal `TypeReference(T)`
        // resolves directly to the concrete type bound for T.
        currentTypeAliasArgs?.get(name)?.let { return it }
        // Look up the symbol — try qualified name resolution, then file-locals
        // (namespace-aware), then globals. Namespace-aware lookup walks the
        // [inferenceNamespaceStack]'s top entry's parent chain to resolve type
        // names declared inside an enclosing `namespace M { interface I {} }`
        // context — required for lazy variable type-resolution where the var's
        // annotation references a namespace-local interface.
        val symbol = resolveTypeNameToSymbol(node.typeName)
            ?: (node.typeName as? Identifier)?.let { lookupTypeSymbolInInferenceNamespace(it.text) }
            ?: globals[name]
        if (symbol != null) {
            // B50.1: Generic type alias instantiation. When the symbol is a TypeAlias
            // and the reference supplies type args matching the alias's arity, re-resolve
            // the alias body in a context that maps alias type-parameter names to the
            // concrete arg types. This fixes the long-standing gap where `Foo<string>`
            // and `Foo<number>` produced structurally identical types (T resolved to
            // errorType because the body was resolved without a type-param scope push).
            // Recursion guarded by depth limit; circular aliases bail to errorType.
            //
            // Gate: skip FunctionType / ConstructorType / TypeLiteral-with-only-call-sigs
            // aliases (e.g. `Mapper<T,U> = (x:T)=>U`). Instantiating those into concrete
            // function types lets the relation engine fire FP TS2322 when a generic
            // function-call result (whose TypeParams are still un-inferred) is compared
            // against them — generic argument inference (Blocker #2) is not yet
            // implemented, so the inferred T/U would otherwise resolve to errorType
            // and silently pass. Object/Union/Intersection alias bodies are safe.
            if (symbol.flags.hasAny(SymbolFlags.TypeAlias)) {
                val typeArgs = node.typeArguments
                if (!typeArgs.isNullOrEmpty()) {
                    val decl = symbol.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                    val declTPs = decl?.typeParameters
                    if (decl != null && !declTPs.isNullOrEmpty() && declTPs.size == typeArgs.size &&
                        !isFunctionTypeAliasBody(decl.type)
                    ) {
                        val resolvedArgs = typeArgs.map { getTypeFromTypeNode(it) }
                        if (resolvedArgs.none { it === errorType }) {
                            // B57.1b: skip substitution when any arg fails its constraint.
                            // Prevents FP TS2589 on `Foo<"false", {}>` where the constraint
                            // `T extends "true"` is unsatisfied (TS2344 emitted elsewhere).
                            // Without this, the recursive alias body still expands 10
                            // levels deep and (wrongly) emits TS2589.
                            var constraintFails = false
                            for (i in declTPs.indices) {
                                val tpConstraintNode = declTPs[i].constraint
                                if (tpConstraintNode != null) {
                                    val constraintType = try { getTypeFromTypeNode(tpConstraintNode) }
                                        catch (_: Throwable) { errorType }
                                    if (constraintType !== anyType && constraintType !== errorType) {
                                        if (!checkTypeRelatedTo(resolvedArgs[i], constraintType, assignableRelation)) {
                                            constraintFails = true
                                            break
                                        }
                                    }
                                }
                            }
                            if (constraintFails) return errorType
                            if (typeAliasResolutionDepth >= 10) {
                                // B57.1: signal depth-bail to outer callers so they can
                                // emit TS2589 at the annotation position.
                                deepInstantiationBailed = true
                                return errorType
                            }
                            // B58.3: intern substitution results so identical (symbol, args)
                            // calls return the same Type instance — keeps aliasDisplayMap
                            // entries stable across re-resolution.
                            val cacheKey = "${symbol.id}|${resolvedArgs.joinToString(",") { it.id.toString() }}"
                            substitutionResultCache[cacheKey]?.let { return it }
                            val saved = currentTypeAliasArgs
                            try {
                                val argMap = mutableMapOf<String, Type>()
                                saved?.let { argMap.putAll(it) }
                                for (i in declTPs.indices) {
                                    argMap[declTPs[i].name.text] = resolvedArgs[i]
                                }
                                currentTypeAliasArgs = argMap
                                typeAliasResolutionDepth++
                                val result = getTypeFromTypeNode(decl.type)
                                // B50.2: register alias-display info so typeToString
                                // renders `Foo<string>` instead of the structural form.
                                // CRITICAL filters:
                                //  - skip singleton intrinsics (anyType etc) shared across corpus
                                //  - B50.5: skip pure function-typed results (call signatures only,
                                //    no properties/members) — TypeScript unfolds those at display
                                //    time. The `noAlias` indirection trick (`type Cb<T> =
                                //    {x: () => T}["x"]`) in `nestedCallbackErrorNotFlattened_ts`
                                //    deliberately prevents alias-symbol creation; we mirror that.
                                val isPureFunctionType = result is Type.Object &&
                                    !result.callSignatures.isNullOrEmpty() &&
                                    result.properties.isNullOrEmpty() &&
                                    result.members.isNullOrEmpty() &&
                                    result.constructSignatures.isNullOrEmpty()
                                if (result !== errorType && result !is Type.Intrinsic &&
                                    result !is Type.StringLiteral && result !is Type.NumberLiteral &&
                                    result !is Type.BigIntLiteral && !isPureFunctionType
                                ) {
                                    aliasDisplayMap[result.id] = symbol.name to resolvedArgs
                                    // B58.3: cache for future calls with same (symbol, args).
                                    substitutionResultCache[cacheKey] = result
                                }
                                return result
                            } finally {
                                currentTypeAliasArgs = saved
                                typeAliasResolutionDepth--
                            }
                        }
                    }
                }
            }
            val declaredType = getDeclaredTypeOfSymbol(symbol)
            // If the type has type parameters and the reference has type arguments,
            // create a generic instantiation (Type.Reference)
            if (declaredType is Type.Interface) {
                val typeParams = declaredType.typeParameters
                val typeArgs = node.typeArguments
                if (typeParams != null && typeParams.isNotEmpty() && typeArgs != null && typeArgs.isNotEmpty()) {
                    val resolvedArgs = typeArgs.map { getTypeFromTypeNode(it) }
                    // Only create Reference if all args resolved (no errorType)
                    if (resolvedArgs.none { it === errorType }) {
                        return getOrInternReference(declaredType, resolvedArgs)
                    }
                }
            }
            return declaredType
        }
        // Not found — return errorType (TS2304 handles the diagnostic separately)
        return errorType
    }

    /** Get the declared type of a symbol (class, interface, enum, type alias, etc.). */
    private fun getDeclaredTypeOfSymbol(symbol: Symbol): Type {
        declaredTypes[symbol.id]?.let { return it }
        val type = getDeclaredTypeOfSymbolWorker(symbol)
        declaredTypes[symbol.id] = type
        return type
    }

    private fun getDeclaredTypeOfSymbolWorker(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface) -> {
                getDeclaredTypeOfClassOrInterface(symbol)
            }
            flags.hasAny(SymbolFlags.TypeAlias) -> {
                // Store sentinel in cache first to prevent circular type alias StackOverflow
                declaredTypes[symbol.id] = errorType
                val decl = symbol.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                val resolved = if (decl != null) getTypeFromTypeNode(decl.type) else errorType
                declaredTypes[symbol.id] = resolved
                // B50.4: register alias-name display for non-generic type aliases
                // whose body resolved to a NEW Type.Object (NOT Union/Intersection).
                // Union/Intersection bodies are excluded because TypeScript often
                // unfolds those at display time (e.g. `Wrapper = Foo & Bar` → emit
                // `'Foo & Bar'` not `'Wrapper'` in TS2416 baselines).
                // B50.7: Intersection bodies ARE registered IF they contain a Union
                // constituent (`Common = X | Y; A = Common & {foo:1}` → display `A`,
                // not the distributed structural form). Flat intersections of named
                // types stay unfolded.
                val shouldRegister = resolved is Type.Object && resolved !is Type.Reference ||
                    (resolved is Type.Intersection && resolved.types.any { it is Type.Union })
                if (decl != null && decl.typeParameters.isNullOrEmpty() &&
                    shouldRegister && !aliasDisplayMap.containsKey(resolved.id)
                ) {
                    // B86.4: qualify alias name with enclosing namespace path
                    // (e.g. `Foo.Yep` instead of `Yep` for type alias declared inside
                    // `namespace Foo`). Matches TypeScript's display when two same-named
                    // aliases live in different namespaces and appear in the same union
                    // (e.g. `Foo.Yep | Bar.Yep` not `Yep | Yep`).
                    val segments = mutableListOf(symbol.name)
                    var cur = symbol.parent
                    while (cur != null && cur.flags.hasAny(SymbolFlags.Module or SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)) {
                        segments.add(0, cur.name)
                        cur = cur.parent
                    }
                    aliasDisplayMap[resolved.id] = segments.joinToString(".") to emptyList()
                }
                resolved
            }
            flags.hasAny(SymbolFlags.Enum) -> {
                // Enums are both a type and a value — return an object type
                val enumType = Type.Object()
                enumType.symbol = symbol
                enumType
            }
            flags.hasAny(SymbolFlags.Alias) -> {
                // Import alias — resolve to target symbol's declared type
                val target = resolveAliasTarget(symbol)
                if (target != null && target !== symbol) getDeclaredTypeOfSymbol(target) else anyType
            }
            flags.hasAny(SymbolFlags.TypeParameter) -> {
                // B59.6: intern by AST position of the TypeParameter declaration so
                // that repeated symbol-based lookups return the SAME Type.TypeParam
                // instance — matching `getTypeParametersOfSymbol` (B59.3) and other
                // interned sites. Without interning, downstream id-based caches
                // (`substitutionResultCache`, `referenceCache`) miss across calls.
                val tpDecl = symbol.declarations.firstOrNull { it is TypeParameter } as? TypeParameter
                if (tpDecl != null) {
                    typeParamInternCache.getOrPut(tpDecl.pos) {
                        val tp = Type.TypeParam()
                        tp.symbol = symbol
                        tp
                    }
                } else {
                    val typeParam = Type.TypeParam()
                    typeParam.symbol = symbol
                    typeParam
                }
            }
            else -> anyType
        }
    }

    /**
     * Build an InterfaceType from class/interface declarations.
     * Collects type parameters and resolves base types (extends/implements).
     * Members are NOT resolved yet (lazy, done in resolveStructuredTypeMembers).
     */
    private fun getDeclaredTypeOfClassOrInterface(symbol: Symbol): Type.Interface {
        val interfaceType = Type.Interface()
        interfaceType.symbol = symbol
        // Store in cache BEFORE resolving base types to prevent circular reference StackOverflow
        declaredTypes[symbol.id] = interfaceType
        // Collect type parameters from the first class/interface declaration
        val decl = symbol.declarations.firstOrNull {
            it is ClassDeclaration || it is InterfaceDeclaration
        }
        if (decl != null) {
            val typeParams = when (decl) {
                is ClassDeclaration -> decl.typeParameters
                is InterfaceDeclaration -> decl.typeParameters
                else -> null
            }
            if (typeParams != null && typeParams.isNotEmpty()) {
                interfaceType.typeParameters = typeParams.map { tp ->
                    val param = Type.TypeParam()
                    param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                    tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                    tp.default?.let { param.default = getTypeFromTypeNode(it) }
                    param
                }
            }
            // 16.0n: Eagerly resolve heritage from all CURRENTLY visible declarations.
            // For types like Array (where user may add `extends X` via a merged declaration
            // after this type was first cached), resolveInterfaceMembers will re-resolve if
            // baseTypes is still empty at member resolution time.
            resolveBaseTypesLazy(interfaceType)
        }
        return interfaceType
    }

    /** 16.0n: Resolve base types from heritage clauses across ALL declarations.
     *  Called lazily from resolveInterfaceMembers. */
    private fun resolveBaseTypesLazy(type: Type.Interface) {
        val symbol = type.symbol ?: return
        val savedScope = currentTypeParamScope
        val tps = type.typeParameters
        if (!tps.isNullOrEmpty()) {
            val scope = mutableMapOf<String, Type.TypeParam>()
            savedScope?.let { scope.putAll(it) }
            for (tp in tps) tp.symbol?.name?.let { scope[it] = tp }
            currentTypeParamScope = scope
        }
        try {
            val baseTypes = mutableListOf<Type>()
            for (d in symbol.declarations) {
                val heritageClauses = when (d) {
                    is ClassDeclaration -> d.heritageClauses
                    is InterfaceDeclaration -> d.heritageClauses
                    else -> null
                } ?: continue
                for (clause in heritageClauses) {
                    // `implements` clauses are structural constraints, not base types —
                    // they must not contribute members to the class's instance type.
                    // (Otherwise a class `implements I` would silently "inherit" I's
                    //  members even when the class doesn't declare them, masking TS2420
                    //  and TS2344 via-constraint failures.)
                    if (clause.token == SyntaxKind.ImplementsKeyword) continue
                    for (exprWithArgs in clause.types) {
                        val baseType = getTypeFromBaseTypeExpression(exprWithArgs)
                        if (baseType !== errorType) {
                            baseTypes.add(baseType)
                        }
                    }
                }
            }
            if (baseTypes.isNotEmpty()) type.baseTypes = baseTypes
        } finally {
            currentTypeParamScope = savedScope
        }
    }

    /**
     * Resolve a heritage-clause base expression (Identifier or PropertyAccessExpression)
     * to a Symbol. For `Foo.I1`, walks `Foo`'s `exports` to find `I1` but only when
     * `I1` is actually exported (i.e., would be accessible from outside `Foo`). For
     * multi-segment `A.B.C`, recursively resolves the parent then walks exports.
     * Returns null when not exported (caller should also emit TS2694).
     */
    private fun resolveHeritageBaseSymbol(expr: Expression): Symbol? {
        return when (expr) {
            is Identifier -> globals[expr.text]
            is PropertyAccessExpression -> {
                val parent = resolveHeritageBaseSymbol(expr.expression) ?: return null
                val resolvedParent = resolveAlias(parent)
                val propName = (expr.name as? Identifier)?.text ?: return null
                val memberSym = resolvedParent.exports?.get(propName) ?: return null
                // Implicit-export rules:
                //  - Sub-namespaces (Module flag) are always accessible (parent.Sub usage).
                //  - `declare namespace` members are implicitly exported (any decl carries Declare).
                // Otherwise require explicit `export` modifier on the member declaration.
                if (memberSym.flags.hasAny(SymbolFlags.Module)) return memberSym
                val parentIsAmbient = resolvedParent.declarations.any {
                    it is ModuleDeclaration && ModifierFlag.Declare in it.modifiers
                }
                if (parentIsAmbient) return memberSym
                val memberIsExported = memberSym.flags.hasAny(SymbolFlags.ExportValue) ||
                    memberSym.declarations.any { d ->
                        when (d) {
                            is FunctionDeclaration -> ModifierFlag.Export in d.modifiers
                            is ClassDeclaration -> ModifierFlag.Export in d.modifiers
                            is InterfaceDeclaration -> ModifierFlag.Export in d.modifiers
                            is TypeAliasDeclaration -> ModifierFlag.Export in d.modifiers
                            is EnumDeclaration -> ModifierFlag.Export in d.modifiers
                            is ModuleDeclaration -> ModifierFlag.Export in d.modifiers
                            else -> false
                        }
                    } ||
                    // VariableStatement export check: scan parent module body
                    resolvedParent.declarations.any { nsDecl ->
                        val body = (nsDecl as? ModuleDeclaration)?.body as? ModuleBlock
                        body?.statements?.any { stmt ->
                            stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers &&
                                stmt.declarationList.declarations.any { vd ->
                                    vd.name is Identifier && (vd.name as Identifier).text == propName
                                }
                        } == true
                    }
                if (!memberIsExported) return null
                memberSym
            }
            else -> null
        }
    }

    /** Resolve a base type expression (e.g., `extends Foo<T>`) to a Type. */
    private fun getTypeFromBaseTypeExpression(expr: ExpressionWithTypeArguments): Type {
        val baseExpr = expr.expression
        val symbol = when (baseExpr) {
            is Identifier -> globals[baseExpr.text]
            is PropertyAccessExpression -> resolveHeritageBaseSymbol(baseExpr)
            else -> return errorType
        } ?: return errorType
        val declared = getDeclaredTypeOfSymbol(symbol)
        // 16.0n: Honor type arguments on the base: `extends Foo<X>` → Type.Reference(Foo, [X]).
        // Type args are resolved with the enclosing interface's type params in scope.
        if (declared is Type.Interface) {
            val typeArgs = expr.typeArguments
            if (!typeArgs.isNullOrEmpty()) {
                val resolvedArgs = typeArgs.map { getTypeFromTypeNode(it) }
                if (resolvedArgs.none { it === errorType }) {
                    return getOrInternReference(declared, resolvedArgs)
                }
            }
        }
        return declared
    }

    // -----------------------------------------------------------------------
    // Symbol type resolution (Phase 4 item 2a)
    // -----------------------------------------------------------------------

    /**
     * Get the type of a symbol (variable, parameter, function, class, etc.).
     * Cached in [symbolTypes].
     */
    private fun getTypeOfSymbol(symbol: Symbol): Type {
        symbolTypes[symbol.id]?.let { return it }
        val type = getTypeOfSymbolWorker(symbol)
        symbolTypes[symbol.id] = type
        return type
    }

    private fun getTypeOfSymbolWorker(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property) -> getTypeOfVariableOrProperty(symbol)
            flags.hasAny(SymbolFlags.Function) -> getTypeOfFunction(symbol)
            flags.hasAny(SymbolFlags.Class) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Interface) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Enum) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.TypeAlias) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Alias) -> {
                // Import alias — resolve to target symbol's type
                val target = resolveAliasTarget(symbol)
                if (target != null && target !== symbol) getTypeOfSymbol(target) else anyType
            }
            flags.hasAny(SymbolFlags.TypeParameter) -> getDeclaredTypeOfSymbol(symbol)
            else -> anyType
        }
    }

    /** Get the type of a variable or property from its declaration. */
    private fun getTypeOfVariableOrProperty(symbol: Symbol): Type {
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull() ?: return anyType
        return when (decl) {
            is VariableDeclaration -> {
                // Push the containing namespace (if any) so both annotation type
                // resolution AND initializer inference can resolve namespace-local
                // names via [getTypeOfIdentifier]/[getTypeFromTypeReference]'s
                // namespace-aware fallback.
                val pushed = pushInferenceNamespaceFor(symbol)
                try {
                    // Type annotation takes priority
                    decl.type?.let { return getTypeFromTypeNode(it) }
                    // Infer from initializer (widened: literals → base types)
                    decl.initializer?.let { init ->
                        val inferred = inferTypeFromInitializer(init)
                        if (inferred !== anyType && inferred !== errorType) return inferred
                    }
                } finally {
                    if (pushed) inferenceNamespaceStack.removeLast()
                }
                anyType
            }
            is Parameter -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                // Infer from default value
                decl.initializer?.let { init ->
                    val inferred = inferTypeFromInitializer(init)
                    if (inferred !== anyType && inferred !== errorType) return inferred
                }
                // B9.2: structural default for un-annotated binding-pattern parameters
                // — `{}` for ObjectBindingPattern, `any[]` for ArrayBindingPattern.
                // Only reachable when B9.1's `forSignatureDisplay = true` synthesis
                // produced a FunctionScopedVariable symbol carrying a binding-pattern
                // Parameter as its valueDeclaration. Matches TypeScript's display
                // convention for `({a}) => ...` showing `({ a }: {}) => ...`.
                when (decl.name) {
                    is ObjectBindingPattern -> return Type.Object().also { it.properties = emptyList() }
                    is ArrayBindingPattern -> return getArrayType(anyType)
                    else -> {}
                }
                anyType
            }
            is PropertyDeclaration -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                // Infer from initializer
                decl.initializer?.let { init ->
                    val inferred = inferTypeFromInitializer(init)
                    if (inferred !== anyType && inferred !== errorType) return inferred
                }
                anyType
            }
            is MethodDeclaration -> {
                // Named method — create a function type with call signature(s).
                // Skip unnamed members (call/construct signatures) — those are
                // tracked separately, not as property types.
                val methodName = (decl.name as? Identifier)?.text
                if (methodName.isNullOrEmpty() || methodName == "new") return anyType
                val fnType = Type.Object()
                // Collect all method declarations for overloads (same name)
                val methodDecls = symbol.declarations.filterIsInstance<MethodDeclaration>()
                val overloadDecls = methodDecls.filter { it.body == null }
                val implDecl = methodDecls.find { it.body != null }
                val sigDecls = if (overloadDecls.isNotEmpty()) overloadDecls else listOfNotNull(implDecl)
                fnType.callSignatures = if (sigDecls.isNotEmpty()) {
                    sigDecls.map { md ->
                        // 17.11c: Mirror getTypeOfFunction (line ~33988) — push the method's
                        // typeParameters into currentTypeParamScope BEFORE resolving param
                        // type annotations / return type / constraints. Without this, type
                        // names like `T` in `c: Array<T>` resolved via global lookup → errorType,
                        // making `Array<T>` resolve as `Array<error>`. Cache resolved param
                        // types in `symbolTypes` so later `getTypeOfSymbol(paramSymbol)` calls
                        // return the in-scope-resolved type even after the scope is restored.
                        val typeParams = md.typeParameters?.map { tp ->
                            val param = Type.TypeParam()
                            param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                            param
                        }
                        val savedScope = currentTypeParamScope
                        if (typeParams != null && typeParams.isNotEmpty()) {
                            val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                            typeParams.forEachIndexed { i, tp ->
                                scope[md.typeParameters!![i].name.text] = tp
                            }
                            currentTypeParamScope = scope
                        }
                        // Resolve constraints/defaults AFTER scope is set
                        typeParams?.forEachIndexed { i, tp ->
                            md.typeParameters!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                            md.typeParameters!![i].default?.let { tp.default = getTypeFromTypeNode(it) }
                        }
                        val returnType = md.type?.let { getTypeFromTypeNode(it) } ?: anyType
                        val paramSymbols = getParameterSymbols(md.parameters)
                        for ((pi, param) in paramSymbols.withIndex()) {
                            if (pi < md.parameters.size) {
                                md.parameters[pi].type?.let { typeNode ->
                                    symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                                }
                            }
                        }
                        currentTypeParamScope = savedScope
                        Signature(
                            declaration = md,
                            typeParameters = typeParams,
                            parameters = paramSymbols,
                            resolvedReturnType = returnType,
                            minArgumentCount = md.parameters.count {
                                !it.questionToken && !it.dotDotDotToken && it.initializer == null
                            },
                        )
                    }
                } else {
                    val returnType = decl.type?.let { getTypeFromTypeNode(it) } ?: anyType
                    listOf(Signature(
                        declaration = decl,
                        parameters = getParameterSymbols(decl.parameters),
                        resolvedReturnType = returnType,
                        minArgumentCount = decl.parameters.count {
                            !it.questionToken && !it.dotDotDotToken && it.initializer == null
                        },
                    ))
                }
                fnType
            }
            is GetAccessor -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                anyType
            }
            else -> anyType
        }
    }

    /** Get the type of a function symbol — creates an ObjectType with call signatures.
     *  For overloaded functions, collects all visible overload signatures (body-less declarations).
     *  If no overloads, uses the single implementation declaration.
     */
    private fun getTypeOfFunction(symbol: Symbol): Type {
        val fnType = Type.Object()
        fnType.symbol = symbol
        // Collect all function declarations for this symbol
        val funcDecls = symbol.declarations.filterIsInstance<FunctionDeclaration>()
        if (funcDecls.isEmpty()) return anyType

        // Separate overload signatures (no body) from implementation (has body)
        val overloadDecls = funcDecls.filter { it.body == null }
        val implDecl = funcDecls.find { it.body != null }

        // Use overload signatures if present (they are the visible API),
        // otherwise use the implementation declaration
        val sigDecls = if (overloadDecls.isNotEmpty()) overloadDecls else listOfNotNull(implDecl)
        if (sigDecls.isEmpty()) return anyType

        val signatures = sigDecls.map { decl ->
            // 16.4: Create type parameters FIRST, then set currentTypeParamScope
            // so that parameter types (e.g. T[]) resolve T to the same Type.TypeParam
            // objects used in the signature. This enables type argument instantiation.
            // B59.4: intern by TypeParameter AST position (matches B59.1/B59.2/B59.3
            // pattern at Checker.kt:~37183/~51854/~59118). Distinct overloads of the
            // same function get distinct TypeParam instances because their TypeParameter
            // AST nodes have distinct source positions.
            val typeParams = decl.typeParameters?.map { tp ->
                typeParamInternCache.getOrPut(tp.pos) {
                    val param = Type.TypeParam()
                    param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                    param
                }
            }
            val savedScope = currentTypeParamScope
            if (typeParams != null && typeParams.isNotEmpty()) {
                val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                typeParams.forEachIndexed { i, tp ->
                    scope[decl.typeParameters!![i].name.text] = tp
                }
                currentTypeParamScope = scope
            }
            // Resolve constraints AFTER scope is set (constraints may reference other type params)
            // Guard against clobbering already-set constraint/default from another interning site.
            typeParams?.forEachIndexed { i, tp ->
                if (tp.constraint == null) {
                    decl.typeParameters!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                }
                if (tp.default == null) {
                    decl.typeParameters!![i].default?.let { tp.default = getTypeFromTypeNode(it) }
                }
            }
            // 17.25: When the function has a body and contains no return statement at all,
            // infer return type as `void`. Mirrors TypeScript's `function f() {}` → `() => void`.
            // Conservative: only when there are zero return statements. Functions with mixed
            // returns (some bare `return`, some with values) keep the anyType default.
            // B64.1: When the body returns a value that's recognizable as a known primitive
            // (number from arithmetic, string from string literal, etc.), use that inferred
            // type. Lets `function f() { return x * 2 }` infer `() => number` so a caller's
            // `f().length` fires TS2339 against the primitive `number`.
            val returnType = decl.type?.let { getTypeFromTypeNode(it) }
                ?: decl.body?.let { if (bodyHasNoReturn(it)) voidType else null }
                ?: decl.body?.let { inferReturnTypeFromBody(it) }
                ?: anyType
            // Resolve parameter types eagerly within the type param scope
            val paramSymbols = getParameterSymbols(decl.parameters)
            for ((pi, param) in paramSymbols.withIndex()) {
                if (pi < decl.parameters.size) {
                    decl.parameters[pi].type?.let { typeNode ->
                        symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                    }
                }
            }
            currentTypeParamScope = savedScope
            Signature(
                declaration = decl,
                typeParameters = typeParams,
                parameters = paramSymbols,
                resolvedReturnType = returnType,
                minArgumentCount = decl.parameters.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                },
            )
        }
        fnType.callSignatures = signatures
        return fnType
    }

    /**
     * Create Symbol objects for function/method parameters.
     * Each Parameter AST node gets a corresponding Symbol with FunctionScopedVariable flag.
     * This is needed for type checking of call arguments (TS2345).
     *
     * B9.1: When [forSignatureDisplay] is true, synthesize a placeholder symbol for
     * `ObjectBindingPattern` / `ArrayBindingPattern` parameters so the resulting
     * Signature carries the correct arity for display (`(_: T) => U` instead of
     * `() => U`). Default-false preserves the pre-B9.1 silent-drop behavior at
     * non-display call sites (function declarations, methods, constructors, type
     * literals) where arity may already be authoritative downstream.
     */
    private fun getParameterSymbols(
        params: List<Parameter>,
        forSignatureDisplay: Boolean = false,
    ): List<Symbol> {
        return params.mapNotNull { param ->
            // Skip `this` pseudo-parameter
            val name = when (val n = param.name) {
                is Identifier -> if (n.text == "this") return@mapNotNull null else n.text
                is ObjectBindingPattern, is ArrayBindingPattern -> {
                    if (!forSignatureDisplay) return@mapNotNull null
                    "" // placeholder; formatParameter renders binding-pattern decls via `_`
                }
                else -> return@mapNotNull null
            }
            val sym = Symbol(SymbolFlags.FunctionScopedVariable, name)
            sym.declarations.add(param)
            sym.valueDeclaration = param
            sym
        }
    }

    /** Resolve an import alias to its target symbol, with cycle detection. */
    private fun resolveAliasTarget(symbol: Symbol): Symbol? {
        // Use the checker-local LinkStore target if available
        getSymbolTarget(symbol)?.let { return it }
        // Trigger full cross-file resolution if no cached target
        if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            return try {
                val resolved = resolveAlias(symbol)
                if (resolved !== symbol) resolved else null
            } catch (_: StackOverflowError) { null }
        }
        return null
    }

    // -----------------------------------------------------------------------
    // Lazy member resolution (Phase 4 item 2c)
    // -----------------------------------------------------------------------

    /**
     * Lazily resolve an ObjectType's members, properties, and signatures.
     * After this call, type.members/properties/callSignatures are populated.
     */
    private fun resolveStructuredTypeMembers(type: Type.Object) {
        if (type.properties != null) return // already resolved
        when (type) {
            is Type.Interface -> resolveInterfaceMembers(type)
            is Type.Reference -> resolveReferenceMembers(type)
            else -> resolveAnonymousTypeMembers(type)
        }
    }

    /** Resolve members of an interface/class type from its declarations + base types. */
    private fun resolveInterfaceMembers(type: Type.Interface) {
        val symbol = type.symbol ?: run {
            type.properties = emptyList()
            return
        }
        // 16.0n: Re-resolve baseTypes if empty — declarations may have been merged
        // after the first eager resolution (e.g. user's `interface Array<T> extends IFoo<T>`
        // merging with the built-in Array which was cached at init with no heritage).
        if (type.baseTypes == null) resolveBaseTypesLazy(type)
        val members = symbolTable()
        // Static-side mirror of [members]. Step 1 (dual-population): every member
        // we add to [members] that carries ModifierFlag.Static is ALSO added here.
        // Behavior is unchanged at this step — consumers still read from [members].
        val staticMembers = symbolTable()
        val ownCallSignatures = mutableListOf<Signature>()
        val ownConstructSignatures = mutableListOf<Signature>()
        val inheritedCallSignatures = mutableListOf<Signature>()
        val inheritedConstructSignatures = mutableListOf<Signature>()
        var stringIndexInfo: IndexInfo? = null
        var numberIndexInfo: IndexInfo? = null

        // Inherit from base types
        val inheritedMemberNames = mutableSetOf<String>()
        type.baseTypes?.forEach { baseType ->
            if (baseType is Type.Object) {
                resolveStructuredTypeMembers(baseType)
                baseType.members?.forEach { (name, sym) ->
                    if (name !in members) {
                        members[name] = sym
                        inheritedMemberNames.add(name)
                    }
                }
                // Class-side inheritance for `class C extends B`: B's statics are
                // inherited as C's statics (mirrors how members inherit). Interface
                // base types have no statics, so `it.staticMembers` is null there.
                if (baseType is Type.Interface) {
                    baseType.staticMembers?.forEach { (name, sym) ->
                        if (name !in staticMembers) staticMembers[name] = sym
                    }
                }
                baseType.callSignatures?.let { inheritedCallSignatures.addAll(it) }
                baseType.constructSignatures?.let { inheritedConstructSignatures.addAll(it) }
                if (stringIndexInfo == null) stringIndexInfo = baseType.stringIndexInfo
                if (numberIndexInfo == null) numberIndexInfo = baseType.numberIndexInfo
            }
        }

        // Collect members from all declarations of this symbol
        for (decl in symbol.declarations) {
            val classMembers = when (decl) {
                is ClassDeclaration -> decl.members
                is InterfaceDeclaration -> decl.members
                else -> continue
            }
            // B85.2: target-version member filter for builtin lib declarations.
            // When `decl` is a top-level statement of the embedded [BUILTIN_LIB_SOURCE]
            // AND a member's `(interfaceName, memberName)` is in [LIB_MIN_TARGET] with
            // a minimum target > the current `options.target`, drop that member. Aligns
            // lib member counts with TypeScript baselines for `@target: es2015` (e.g.
            // `arrayAssignmentTest*` "and 25 more" instead of "and 29 more").
            val ifaceName = symbol.name
            val isBuiltinDecl = decl in builtinLibDecls
            for (member in classMembers) {
                if (isBuiltinDecl) {
                    val memberName = when (member) {
                        is PropertyDeclaration -> getMemberName(member.name)
                        is MethodDeclaration -> getMemberName(member.name)
                        is GetAccessor -> getMemberName(member.name)
                        is SetAccessor -> getMemberName(member.name)
                        else -> null
                    }
                    if (memberName != null) {
                        val minTarget = LIB_MIN_TARGET["$ifaceName.$memberName"]
                        if (minTarget != null && options.target < minTarget) continue
                    }
                }
                when (member) {
                    is PropertyDeclaration -> {
                        val name = getMemberName(member.name) ?: continue
                        val propSymbol = Symbol(SymbolFlags.Property, name)
                        propSymbol.declarations.add(member)
                        propSymbol.valueDeclaration = member
                        propSymbol.parent = symbol
                        members[name] = propSymbol
                        // Step 1 dual-population: mirror static members onto staticMembers
                        // while keeping them in [members] (no behavior change yet).
                        if (ModifierFlag.Static in member.modifiers) {
                            staticMembers[name] = propSymbol
                        }
                    }
                    is MethodDeclaration -> {
                        val name = getMemberName(member.name) ?: continue
                        // Call signatures (empty name) and construct signatures ("new") are
                        // tracked as signatures, not as named properties.
                        if (name.isEmpty() || name == "new") {
                            // 17.153: Push the enclosing interface's typeParameters into scope
                            // so that `T` references in the call/construct signature's return
                            // type and parameter type annotations resolve to the interface's
                            // TypeParam (instead of falling through to errorType). Pre-resolve
                            // param types into [symbolTypes] so later instantiation through
                            // `getTypeOfSymbol(paramSym)` returns the in-scope-resolved type.
                            // Mirrors the named-method branch in `getTypeOfSymbolWorker`
                            // (line ~38876), but uses the enclosing interface's TPs since
                            // call/construct sigs don't declare their own typeParameters.
                            val savedSigScope = currentTypeParamScope
                            val ifaceTps = type.typeParameters
                            val sigOwnTps = member.typeParameters?.map { tp ->
                                val tpType = Type.TypeParam()
                                tpType.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                                tpType
                            }
                            if (!ifaceTps.isNullOrEmpty() || !sigOwnTps.isNullOrEmpty()) {
                                val scope = (savedSigScope?.toMutableMap() ?: mutableMapOf())
                                ifaceTps?.forEach { tp -> tp.symbol?.name?.let { scope[it] = tp } }
                                sigOwnTps?.forEachIndexed { i, tp ->
                                    scope[member.typeParameters!![i].name.text] = tp
                                }
                                currentTypeParamScope = scope
                            }
                            // Resolve sig-own TP constraints/defaults under combined scope
                            sigOwnTps?.forEachIndexed { i, tp ->
                                member.typeParameters!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                                member.typeParameters!![i].default?.let { tp.default = getTypeFromTypeNode(it) }
                            }
                            val returnType = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                            val paramSymbols = getParameterSymbols(member.parameters)
                            for ((pi, param) in paramSymbols.withIndex()) {
                                if (pi < member.parameters.size) {
                                    member.parameters[pi].type?.let { typeNode ->
                                        symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                                    }
                                }
                            }
                            currentTypeParamScope = savedSigScope
                            val newSig = Signature(
                                declaration = member,
                                typeParameters = sigOwnTps,
                                parameters = paramSymbols,
                                resolvedReturnType = returnType,
                                minArgumentCount = member.parameters.count {
                                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                                },
                            )
                            if (name.isEmpty()) ownCallSignatures.add(newSig)
                            else ownConstructSignatures.add(newSig)
                            continue
                        }
                        // 16.4l: If the name came from a base type, this is an override —
                        // create a NEW symbol so we don't mutate the base's symbol's
                        // `declarations` list. Otherwise reuse the symbol to support
                        // overloaded methods declared on the same class.
                        val existingFromBase = name in inheritedMemberNames
                        val methodSymbol = if (existingFromBase) {
                            val fresh = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                            members[name] = fresh
                            inheritedMemberNames.remove(name)
                            fresh
                        } else {
                            members.getOrPut(name) {
                                Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                            }
                        }
                        methodSymbol.declarations.add(member)
                        if (methodSymbol.valueDeclaration == null) {
                            methodSymbol.valueDeclaration = member
                        }
                        if (methodSymbol.parent == null) methodSymbol.parent = symbol
                        // Step 1 dual-population: static methods also live on staticMembers.
                        if (ModifierFlag.Static in member.modifiers) {
                            staticMembers[name] = methodSymbol
                        }
                    }
                    is Constructor -> {
                        val returnType = type as Type
                        val sig = Signature(
                            declaration = member,
                            parameters = getParameterSymbols(member.parameters),
                            resolvedReturnType = returnType,
                            minArgumentCount = member.parameters.count {
                                !it.questionToken && !it.dotDotDotToken && it.initializer == null
                            },
                        )
                        ownConstructSignatures.add(sig)
                        // Also add parameter properties as members
                        for (param in member.parameters) {
                            if (param.modifiers.isNotEmpty() && param.name is Identifier) {
                                val paramName = (param.name as Identifier).text
                                val propSymbol = Symbol(SymbolFlags.Property, paramName)
                                propSymbol.declarations.add(param)
                                propSymbol.valueDeclaration = param
                                propSymbol.parent = symbol
                                members[paramName] = propSymbol
                            }
                        }
                    }
                    is GetAccessor -> {
                        val name = getMemberName(member.name) ?: continue
                        val existing = members[name]
                        val sym = if (existing != null) {
                            // B54.6: accessor-pair declaration merging — if a SetAccessor was
                            // bound first, append this GetAccessor's declaration to the same
                            // symbol so checkPropertyAccessAssignment / typeOfAccessor can find
                            // both. Without this, propSym.declarations carries only the first
                            // accessor, breaking write-context setter-param type extraction.
                            if (member !in existing.declarations) existing.declarations.add(member)
                            existing
                        } else {
                            Symbol(SymbolFlags.Property, name).also {
                                it.declarations.add(member)
                                it.valueDeclaration = member
                                it.parent = symbol
                                members[name] = it
                            }
                        }
                        if (ModifierFlag.Static in member.modifiers) {
                            staticMembers[name] = sym
                        }
                    }
                    is SetAccessor -> {
                        val name = getMemberName(member.name) ?: continue
                        val existing = members[name]
                        val sym = if (existing != null) {
                            // B54.6: see comment in GetAccessor branch.
                            if (member !in existing.declarations) existing.declarations.add(member)
                            existing
                        } else {
                            Symbol(SymbolFlags.Property, name).also {
                                it.declarations.add(member)
                                it.valueDeclaration = member
                                it.parent = symbol
                                members[name] = it
                            }
                        }
                        if (ModifierFlag.Static in member.modifiers) {
                            staticMembers[name] = sym
                        }
                    }
                    is IndexSignature -> {
                        // 16.0n: Push this interface's type parameters into scope so that
                        // `[n: number]: T` resolves T to our TypeParam (allowing later
                        // instantiation via the reference mapper).
                        val savedIdxScope = currentTypeParamScope
                        val idxTps = type.typeParameters
                        if (!idxTps.isNullOrEmpty()) {
                            val scope = mutableMapOf<String, Type.TypeParam>()
                            savedIdxScope?.let { scope.putAll(it) }
                            for (tp in idxTps) tp.symbol?.name?.let { scope[it] = tp }
                            currentTypeParamScope = scope
                        }
                        val (keyType, valueType) = try {
                            val keyParam = member.parameters.firstOrNull()
                            val kt = keyParam?.type?.let { getTypeFromTypeNode(it) } ?: stringType
                            val vt = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                            kt to vt
                        } finally {
                            currentTypeParamScope = savedIdxScope
                        }
                        val info = IndexInfo(keyType, valueType, member.modifiers.contains(ModifierFlag.Readonly), member)
                        if (keyType === numberType) {
                            numberIndexInfo = info
                        } else {
                            stringIndexInfo = info
                        }
                    }
                    is SemicolonClassElement, is ClassStaticBlockDeclaration -> { /* skip */ }
                }
            }
        }

        // Also include exports from the symbol (for namespace merges, etc.)
        // Also include exports from the symbol (for namespace merges, etc.)
        // Skip call signature ("") and construct signature ("new") members —
        // these are already tracked as signatures from the member loop above.
        symbol.members?.forEach { (name, sym) ->
            if (name.isEmpty() || name == "new") return@forEach // already handled in member loop
            if (name !in members) members[name] = sym
        }

        type.members = members
        type.properties = members.values.toList()
        // Step 1 dual-population: staticMembers is the static-side mirror. Empty
        // staticMembers stays empty (not null) for class declarations so callers
        // can distinguish "no static side" (pure interface — null) from "class
        // without statics" (empty map). Only ClassDeclaration carries a static side.
        type.staticMembers = if (symbol.declarations.any { it is ClassDeclaration }) {
            staticMembers
        } else null
        // Inherited signatures first, then own — matches the implicit ordering before
        // call signatures were resolved from the member loop. getReturnTypeOfCallExpression
        // uses sigs[0], so inherited-first preserves backward compatibility.
        val callSignatures = inheritedCallSignatures + ownCallSignatures
        // 17.91: Constructor overload visibility — when a class declares both
        // body-less overload signatures AND body-having implementation(s), only
        // the overload signatures are externally visible (TypeScript convention).
        // Without this, `new Foo(...)` falls through to the impl sig (often
        // `(x: any)`) and silences TS2769 "no overload matches this call".
        // Construct signatures from interface `new(...)` members keep their
        // existing visibility (they're not Constructor decls).
        val ctorOverloads = ownConstructSignatures.filter {
            val d = it.declaration
            d is Constructor && d.body == null
        }
        val ctorImpls = ownConstructSignatures.filter {
            val d = it.declaration
            d is Constructor && d.body != null
        }
        val nonCtorConstructSigs = ownConstructSignatures.filter { it.declaration !is Constructor }
        val visibleCtorSigs = if (ctorOverloads.isNotEmpty() && ctorImpls.isNotEmpty()) {
            ctorOverloads
        } else {
            ctorOverloads + ctorImpls
        }
        val constructSignatures = inheritedConstructSignatures + visibleCtorSigs + nonCtorConstructSigs
        type.callSignatures = callSignatures.ifEmpty { null }
        type.constructSignatures = constructSignatures.ifEmpty { null }
        type.stringIndexInfo = stringIndexInfo
        type.numberIndexInfo = numberIndexInfo
    }

    /** Resolve members of a generic type reference by instantiating target members. */
    private fun resolveReferenceMembers(type: Type.Reference) {
        resolveStructuredTypeMembers(type.target)
        val typeParams = type.target.typeParameters
        val typeArgs = type.resolvedTypeArguments
        // If we have both type parameters and arguments, instantiate members with mapper
        if (typeParams != null && typeParams.isNotEmpty() && typeArgs != null && typeArgs.isNotEmpty()) {
            val mapper = createTypeMapper(typeParams, typeArgs)
            // Instantiate properties
            val targetProps = type.target.properties
            if (targetProps != null) {
                val newMembers = symbolTable()
                val newProps = mutableListOf<Symbol>()
                for (prop in targetProps) {
                    val propType = getTypeOfSymbol(prop)
                    val instantiated = instantiateType(propType, mapper)
                    if (instantiated !== propType) {
                        // Create new symbol with instantiated type
                        val newProp = Symbol(prop.flags, prop.name)
                        newProp.declarations.addAll(prop.declarations)
                        newProp.valueDeclaration = prop.valueDeclaration
                        symbolTypes[newProp.id] = instantiated
                        newProps.add(newProp)
                        newMembers[newProp.name] = newProp
                    } else {
                        newProps.add(prop)
                        newMembers[prop.name] = prop
                    }
                }
                type.properties = newProps
                type.members = newMembers
            } else {
                type.properties = type.target.properties
                type.members = type.target.members
            }
            // Instantiate call signatures
            type.callSignatures = type.target.callSignatures?.map { instantiateSignature(it, mapper) }
            type.constructSignatures = type.target.constructSignatures?.map { instantiateSignature(it, mapper) }
            // Instantiate index signatures
            type.stringIndexInfo = type.target.stringIndexInfo?.let {
                val instType = instantiateType(it.type, mapper)
                if (instType !== it.type) IndexInfo(it.keyType, instType, it.isReadonly, it.declaration)
                else it
            }
            type.numberIndexInfo = type.target.numberIndexInfo?.let {
                val instType = instantiateType(it.type, mapper)
                if (instType !== it.type) IndexInfo(it.keyType, instType, it.isReadonly, it.declaration)
                else it
            }
        } else {
            // No type parameters or args — just copy from target
            type.members = type.target.members
            type.properties = type.target.properties
            type.callSignatures = type.target.callSignatures
            type.constructSignatures = type.target.constructSignatures
            type.stringIndexInfo = type.target.stringIndexInfo
            type.numberIndexInfo = type.target.numberIndexInfo
        }
    }

    /** Resolve members of an anonymous object type (object literal type, function type, etc.). */
    private fun resolveAnonymousTypeMembers(type: Type.Object) {
        // For anonymous types created by getFunctionTypeFromNode etc., signatures are already set
        if (type.properties == null) {
            type.properties = type.members?.values?.toList() ?: emptyList()
        }
    }

    /** Extract the name string from a member name node (Identifier, StringLiteral, NumericLiteral). */
    private fun getMemberName(name: NameNode): String? {
        return when (name) {
            is Identifier -> name.text
            is StringLiteralNode -> name.text
            is NumericLiteralNode -> name.text
            is ComputedPropertyName -> null // dynamic — can't resolve statically
            else -> null
        }
    }

    /**
     * Get the properties of a type, triggering lazy resolution if needed.
     */
    private fun getPropertiesOfType(type: Type): List<Symbol> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.properties ?: emptyList()
        }
        if (type is Type.Union) {
            // TODO: intersection of constituent properties
            return emptyList()
        }
        return emptyList()
    }

    /**
     * Look up a property by name on a type.
     */
    private fun getPropertyOfType(type: Type, name: String): Symbol? {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.members?.get(name)
        }
        if (type is Type.Union) {
            // Property exists on a union if it exists on every constituent
            for (constituent in type.types) {
                val prop = getPropertyOfType(constituent, name) ?: return null
            }
            // TODO: return merged property symbol
            return type.types.firstNotNullOfOrNull { getPropertyOfType(it, name) }
        }
        return null
    }

    /**
     * Get the static-side member set of a class-shaped Type.Object, or null when
     * the type has no static side (interfaces, anonymous objects, primitives).
     * For Type.Reference whose target is a Type.Interface, returns the target's
     * staticMembers. Used by structural-comparison consumers that need to filter
     * static members from instance-side iterations (instance↔instance comparison
     * must not see `static foo()` on either side).
     */
    private fun getStaticMembersOfType(type: Type.Object): SymbolTable? = when (type) {
        is Type.Interface -> type.staticMembers
        is Type.Reference -> type.target.staticMembers
        else -> null
    }

    // -----------------------------------------------------------------------
    // Expression type inference (Phase 4 item 3a)
    // -----------------------------------------------------------------------

    /**
     * Get the type of an expression. This is the main entry point for
     * expression type inference, replacing the string-based inferSimpleExprType.
     */
    private fun getTypeOfExpression(expr: Expression): Type {
        return when (expr) {
            // Literals
            is NumericLiteralNode -> numberType
            is StringLiteralNode -> stringType
            is NoSubstitutionTemplateLiteralNode -> stringType
            is TemplateExpression -> stringType
            is RegularExpressionLiteralNode -> anyType // TODO: RegExp type
            is BigIntLiteralNode -> bigintType

            // Identifiers
            is Identifier -> getTypeOfIdentifier(expr)

            // Property access
            is PropertyAccessExpression -> getTypeOfPropertyAccess(expr)
            is ElementAccessExpression -> getTypeOfElementAccess(expr)

            // Unary expressions
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.Exclamation -> booleanType
                SyntaxKind.Minus -> {
                    // -42 → NumberLiteral(-42), -1n → BigIntLiteral("-1")
                    when (val operand = expr.operand) {
                        is NumericLiteralNode -> Type.NumberLiteral(-(operand.text.toDoubleOrNull() ?: 0.0))
                        is BigIntLiteralNode -> Type.BigIntLiteral("-${operand.text.removeSuffix("n")}")
                        else -> numberType
                    }
                }
                SyntaxKind.Plus, SyntaxKind.Tilde -> numberType
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> numberType
                else -> anyType
            }
            is PostfixUnaryExpression -> numberType // x++, x--
            is TypeOfExpression -> stringType
            is VoidExpression -> undefinedType
            is DeleteExpression -> booleanType

            // Binary expressions
            is BinaryExpression -> getTypeOfBinaryExpression(expr)

            // Type assertions / casts
            is AsExpression -> getTypeFromTypeNode(expr.type)
            is TypeAssertionExpression -> getTypeFromTypeNode(expr.type)
            is SatisfiesExpression -> getTypeOfExpression(expr.expression)
            is NonNullExpression -> getTypeOfExpression(expr.expression) // strips null/undefined

            // Parenthesized — honor JSDoc type cast `/** @type {T} */ (expr)` when present.
            is ParenthesizedExpression ->
                if (expr.jsdocCastType != null) {
                    try { getTypeFromTypeNode(expr.jsdocCastType) } catch (_: Throwable) { anyType }
                } else getTypeOfExpression(expr.expression)

            // Literals that create objects
            is ArrayLiteralExpression -> getTypeOfArrayLiteral(expr)
            is ObjectLiteralExpression -> getTypeOfObjectLiteral(expr)

            // Call expressions — resolve return type from signature
            is CallExpression -> getReturnTypeOfCallExpression(expr)
            is NewExpression -> getReturnTypeOfNewExpression(expr)

            // Arrow / function
            is ArrowFunction -> getTypeOfArrowFunction(expr)
            is FunctionExpression -> getTypeOfFunctionExpression(expr)

            // Conditional
            is ConditionalExpression -> {
                // Result is union of true/false branches
                val trueT = getTypeOfExpression(expr.whenTrue)
                val falseT = getTypeOfExpression(expr.whenFalse)
                if (trueT === falseT) trueT else getUnionType(listOf(trueT, falseT))
            }

            // Comma list expression — type of last element
            is CommaListExpression -> if (expr.elements.isNotEmpty()) getTypeOfExpression(expr.elements.last()) else anyType

            // Class expression
            is ClassExpression -> anyType // TODO: class type

            // Spread
            is SpreadElement -> getTypeOfExpression(expr.expression)

            // Await: unwrap one level of Promise<X> -> X; non-Promise operands
            // await to their own type (await of a non-thenable is the value). A
            // bare/unknown operand stays anyType (prior behavior) to avoid cascade.
            // B87.1b (round 73): partial Awaited resolution — full recursive Awaited<>
            // (nested promises / thenables / union distribution) still TODO.
            is AwaitExpression -> {
                val t = getTypeOfExpression(expr.expression)
                when {
                    t === anyType || t === errorType -> t
                    t is Type.Reference && t.target.symbol?.name == "Promise" ->
                        t.resolvedTypeArguments?.getOrNull(0) ?: anyType
                    else -> t
                }
            }

            // Yield
            is YieldExpression -> anyType // TODO: generator return type

            // Tagged template
            is TaggedTemplateExpression -> anyType // TODO: call signature return type

            else -> anyType
        }
    }

    /** Get the type of an identifier expression. */
    private fun getTypeOfIdentifier(id: Identifier): Type {
        return when (id.text) {
            "undefined" -> undefinedType
            "null" -> nullType
            "true" -> trueType
            "false" -> falseType
            "NaN", "Infinity" -> numberType
            else -> {
                // Check local scope first (populated during TS2322 checking walk)
                currentLocalTypes[id.text]?.let { return it }
                // Check pre-built file-level type map (covers annotated file-level declarations)
                currentCheckFileName?.let { fn ->
                    fileLocalTypeMaps[fn]?.get(id.text)?.let { return it }
                }
                // Check file-level locals symbol table (for symbols not in type map)
                currentFileLocals?.get(id.text)?.let { symbol ->
                    val type = getTypeOfSymbol(symbol)
                    if (type !== anyType && type !== errorType) return type
                }
                // Namespace-aware fallback: when this lookup happens during lazy
                // initializer-type inference for a namespace-scoped variable, walk
                // the enclosing namespace symbol's parent chain and consult each
                // namespace's `exports` table. Required for patterns like:
                //   namespace M { var x: T = ...; export var y = x; }
                // where `x` is bound in `M.exports` (not in file locals/globals).
                lookupInInferenceNamespace(id.text)?.let { return it }
                // Then look up symbol in globals
                val symbol = globals[id.text]
                if (symbol != null) getTypeOfSymbol(symbol) else anyType
            }
        }
    }

    /** If a containing namespace was pushed by [pushInferenceNamespaceFor], walk its
     *  parent chain looking for [name] in each namespace's `exports`. Returns the
     *  resolved non-error type, or `null` if no namespace lookup applies/succeeds. */
    private fun lookupInInferenceNamespace(name: String): Type? {
        var current: Symbol? = inferenceNamespaceStack.lastOrNull() ?: return null
        while (current != null && current.flags.hasAny(SymbolFlags.Module)) {
            val exp = current.exports?.get(name)
            if (exp != null) {
                val type = getTypeOfSymbol(exp)
                if (type !== anyType && type !== errorType) return type
            }
            current = current.parent
        }
        return null
    }

    /** Type-position counterpart of [lookupInInferenceNamespace]. Walks the
     *  inference-namespace stack's top entry's parent chain looking for a type
     *  symbol (Class/Interface/Enum/TypeAlias) named [name] in each namespace's
     *  `exports`. Returns the resolved symbol or `null`. Used by
     *  [getTypeFromTypeReference] so that an annotation like `var x: I = ...`
     *  inside `namespace M { interface I {} }` resolves I correctly. */
    private fun lookupTypeSymbolInInferenceNamespace(name: String): Symbol? {
        var current: Symbol? = inferenceNamespaceStack.lastOrNull() ?: return null
        while (current != null && current.flags.hasAny(SymbolFlags.Module)) {
            val exp = current.exports?.get(name)
            if (exp != null && exp.flags.hasAny(SymbolFlags.Type)) return exp
            current = current.parent
        }
        return null
    }

    /** Push [symbol]'s parent onto [inferenceNamespaceStack] if the parent is a
     *  namespace symbol (carries [SymbolFlags.Module]). Returns true when pushed
     *  — caller is responsible for popping in a finally block. */
    private fun pushInferenceNamespaceFor(symbol: Symbol): Boolean {
        val parent = symbol.parent ?: return false
        if (!parent.flags.hasAny(SymbolFlags.Module)) return false
        inferenceNamespaceStack.addLast(parent)
        return true
    }

    // -----------------------------------------------------------------------
    // Control-flow narrowing (Phase 17 / Blocker #1 step 2 — minimal v1)
    //
    // [getNarrowedTypeForReference] takes a declared type for an identifier
    // reference and the reference expression, looks up the [FlowNode] from the
    // current file's flow graph, and walks antecedents to apply narrowing.
    //
    // Currently supports a narrow set of operations sufficient for assignment-
    // to-`never` cases like `narrowingUnionToNeverAssigment_ts`:
    //   - `===` / `!==` / `==` / `!=` against literal types narrows union
    //   - `&&` / `||` of those (via De Morgan)
    //   - FlowBranchLabel joins (union of antecedent narrowings)
    //   - FlowStart / FlowAssignment / FlowCall / FlowSwitchClause /
    //     FlowArrayMutation / FlowLoopLabel: pass-through (no narrowing yet)
    //
    // Caller is responsible for opting in (e.g., only on `never` targets) so
    // narrowing remains conservative until step 2's broader emission-site
    // adoption lands. -----------------------------------------------------
    // -----------------------------------------------------------------------

    /**
     * True if narrowing should be applied for var-decl assignability against
     * this target. Excludes Object/Interface/Reference targets to avoid
     * interactions with structural-comparison gaps.
     */
    private fun isNarrowableTarget(target: Type): Boolean = when (target) {
        is Type.Intrinsic -> true
        is Type.StringLiteral -> true
        is Type.NumberLiteral -> true
        is Type.BigIntLiteral -> true
        else -> target === neverType
    }

    /** Look up the [FlowNode] recorded for a node's reference position. */
    private fun getFlowAt(node: Node): FlowNode? {
        val graph = currentFlowGraph ?: return null
        return graph.nodeToFlow[nodeKey(node)]
    }

    /**
     * Compute the narrowed type for an identifier reference at [expr], starting
     * from its [declaredType]. Only attempts narrowing if a flow node exists;
     * returns [declaredType] unchanged when narrowing isn't applicable.
     *
     * Conservative bound: walks at most [NARROW_MAX_DEPTH] antecedents to keep
     * the helper cheap.
     */
    private fun getNarrowedTypeForReference(declaredType: Type, expr: Expression): Type {
        // 17.34: PropertyAccess narrowing for paths like `A._a`. The path is
        // serialized as a dotted string; the narrowing helpers compare the
        // condition expression's path against this string. Identifiers stay
        // on the same path as before (path = name); PropertyAccess chains
        // produce paths like "A._a" or "this.field". Returns null for shapes
        // that aren't a pure Identifier-or-PropertyAccess chain (calls, parens,
        // element-access, etc.) — those bail to declared type.
        val path = getReferencePath(expr) ?: return declaredType
        val flow = getFlowAt(expr) ?: return declaredType
        val seen = mutableSetOf<Int>()
        return narrowTypeFromFlow(declaredType, flow, path, seen, depth = 0)
    }

    /**
     * B81.1a (2026-05-26): Loop-aware variant of [getNarrowedTypeForReference].
     *
     * Uses [narrowTypeFromFlowFollowLoopEntry] instead of [narrowTypeFromFlow]
     * so reads INSIDE a loop body see the narrowing established at loop entry
     * (via `antecedents[0]`), rather than the declared type wash-out at
     * FlowLoopLabel. Suitable for property-path narrowing — see B81.1c (the
     * TS18048 emitter) for the intended caller.
     *
     * Gate: opt-in by NEW callers only. The existing TS2339 / TS2454 / TS2532
     * paths still call [getNarrowedTypeForReference] to preserve their
     * conservative semantics. Broader adoption of loop-entry narrowing in
     * those paths is risky (back-edge property reassignment is not yet
     * tracked) — see B78.2 / FlowLoopLabel-back-edge gotcha for the
     * underlying soundness concern.
     */
    private fun getNarrowedTypeForReferenceFollowLoopEntry(
        declaredType: Type, expr: Expression,
    ): Type {
        val path = getReferencePath(expr) ?: return declaredType
        val flow = getFlowAt(expr) ?: return declaredType
        val seen = mutableSetOf<Int>()
        return narrowTypeFromFlowFollowLoopEntry(declaredType, flow, path, seen, depth = 0)
    }

    /**
     * Serialize a reference expression as a dotted path. Returns null for
     * shapes that can't be encoded (e.g., element access, call expressions).
     * Used by 17.34 PropertyAccess narrowing.
     */
    private fun getReferencePath(expr: Expression): String? = when (expr) {
        is Identifier -> expr.text
        is PropertyAccessExpression -> {
            val receiverPath = getReferencePath(expr.expression) ?: return null
            "$receiverPath.${expr.name.text}"
        }
        // `(x)` and `(x).prop` should narrow identically to `x` / `x.prop` — the parens
        // are syntactic noise. Skip synthetic-paren instantiation-expression markers,
        // since those represent a separate semantic op the narrower shouldn't merge.
        is ParenthesizedExpression -> if (expr.instantiationEnd == null) getReferencePath(expr.expression) else null
        // `x!` non-null assertion preserves the reference; `(x as T)` and `(x satisfies T)`
        // are pure type-system operations — the runtime reference is unchanged.
        is NonNullExpression -> getReferencePath(expr.expression)
        is AsExpression -> getReferencePath(expr.expression)
        is SatisfiesExpression -> getReferencePath(expr.expression)
        is TypeAssertionExpression -> getReferencePath(expr.expression)
        else -> null
    }

    private fun narrowTypeFromFlow(
        declaredType: Type, flowNode: FlowNode, name: String,
        seen: MutableSet<Int>, depth: Int,
    ): Type {
        if (depth >= NARROW_MAX_DEPTH) return declaredType
        if (!seen.add(flowNode.id)) return declaredType
        return when (flowNode) {
            is FlowStart -> declaredType
            is FlowUnreachable -> neverType
            is FlowCondition -> {
                val antecedent = narrowTypeFromFlow(declaredType, flowNode.antecedent, name, seen, depth + 1)
                applyConditionNarrowing(antecedent, flowNode.expression, flowNode.isTrue, name)
            }
            is FlowBranchLabel -> {
                if (flowNode.antecedents.isEmpty()) return neverType
                val branchTypes = flowNode.antecedents.map {
                    narrowTypeFromFlow(declaredType, it, name, mutableSetOf<Int>().apply { addAll(seen) }, depth + 1)
                }
                getUnionType(branchTypes)
            }
            // Loop / assignment / call / switch / array mutation: pass-through for now.
            // Loop back-edge handling would require widening to declared on cycle —
            // for the current scope, recursing into the antecedent is safe because
            // the FlowGraphBuilder doesn't create unbounded antecedent chains.
            is FlowLoopLabel -> {
                if (flowNode.antecedents.isEmpty()) return declaredType
                // Conservative: fall back to declared type at loop joins to avoid
                // back-edge widening complexity.
                declaredType
            }
            is FlowAssignment -> {
                // 17.30b: When the assignment binds [name] AND the RHS is a literal
                // (string/number/bigint/template/true/false/null/undefined), narrow
                // [declaredType] using the RHS's literal type. Conservative gate on
                // literal AST shapes (via [literalTypeOfExpression]) avoids recursion
                // through getTypeOfExpression on identifier/call RHSes during
                // narrowing — purely structural lookup.
                val antecedent = narrowTypeFromFlow(declaredType, flowNode.antecedent, name, seen, depth + 1)
                val rhsLiteralType = if (flowAssignmentTargetsName(flowNode.node, name))
                    getLiteralRhsTypeForAssignment(flowNode.node) else null
                if (rhsLiteralType != null) narrowUnionByRhsAssignment(antecedent, rhsLiteralType)
                else antecedent
            }
            is FlowCall -> {
                val antecedent = narrowTypeFromFlow(declaredType, flowNode.antecedent, name, seen, depth + 1)
                // round 43 iter3: assert-function narrowing — when the call's callee is
                // `function assertX(x): asserts x is T`, after the call returns, x is
                // narrowed to T. Pass-through (no narrowing) when the callee isn't an
                // assertion function.
                narrowByAssertCall(antecedent, flowNode.node, name) ?: antecedent
            }
            is FlowSwitchClause -> {
                val antecedent = narrowTypeFromFlow(declaredType, flowNode.antecedent, name, seen, depth + 1)
                // round 43 iter5: switch-case discriminant narrowing. When `switch (X) { case <lit>: ... }`
                // and X's reference path matches [name], narrow [antecedent] (a union)
                // by filtering to members assignable from the case literal.
                narrowBySwitchClause(antecedent, flowNode, name) ?: antecedent
            }
            is FlowArrayMutation -> narrowTypeFromFlow(declaredType, flowNode.antecedent, name, seen, depth + 1)
        }
    }

    /**
     * Extract the RHS literal type for a FlowAssignment node, or null when the
     * RHS isn't a recognized literal shape. Reuses [literalTypeOfExpression]
     * which already handles strings/numbers/bigints/templates/true/false/null/
     * undefined and unary-minus on numerics.
     *
     * Recognized assignment shapes:
     *   - VariableDeclaration with initializer  (`var x = "foo"`)
     *   - BinaryExpression with `=` operator    (`x = "foo"`)
     * Compound assignments (`+=`, `-=`, etc.) and unary `++`/`--` are
     * intentionally skipped — their result types depend on the LHS's prior type
     * and would need a value-aware computation rather than a syntactic literal lookup.
     */
    private fun getLiteralRhsTypeForAssignment(node: Node): Type? {
        val rhs: Expression? = when (node) {
            is VariableDeclaration -> node.initializer
            is BinaryExpression -> if (node.operator == SyntaxKind.Equals) node.right else null
            else -> null
        }
        return rhs?.let { literalTypeOfExpression(it) }
    }

    /**
     * Narrow a Union [declared] by filtering to members compatible with [rhsType]
     * (a recently-assigned literal). Non-union types are returned unchanged —
     * RHS narrowing only refines unions; collapsing a flat type to a more
     * precise literal would risk over-narrowing in downstream assignability.
     */
    private fun narrowUnionByRhsAssignment(declared: Type, rhsType: Type): Type {
        if (declared !is Type.Union) return declared
        val filtered = declared.types.filter {
            checkTypeRelatedTo(rhsType, it, assignableRelation)
        }
        return when {
            filtered.isEmpty() -> declared
            filtered.size == declared.types.size -> declared
            filtered.size == 1 -> filtered[0]
            else -> getUnionType(filtered)
        }
    }

    /**
     * Apply narrowing for a condition expression at the given polarity.
     * Handles `&&`/`||` recursively (De Morgan) and `===`/`!==`/`==`/`!=`
     * against literal values.
     */
    private fun applyConditionNarrowing(
        t: Type, expr: Expression, isTrue: Boolean, name: String,
    ): Type {
        return when (expr) {
            is ParenthesizedExpression -> applyConditionNarrowing(t, expr.expression, isTrue, name)
            // Value-preserving wrappers (`x as T`, `<T>x`, `x satisfies T`, `x!`) do not
            // change the runtime reference — narrow the inner expression.
            is AsExpression -> applyConditionNarrowing(t, expr.expression, isTrue, name)
            is TypeAssertionExpression -> applyConditionNarrowing(t, expr.expression, isTrue, name)
            is SatisfiesExpression -> applyConditionNarrowing(t, expr.expression, isTrue, name)
            is NonNullExpression -> applyConditionNarrowing(t, expr.expression, isTrue, name)
            is PrefixUnaryExpression -> if (expr.operator == SyntaxKind.Exclamation) {
                applyConditionNarrowing(t, expr.operand, !isTrue, name)
            } else t
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.BarBar -> if (isTrue) {
                    // `a || b` is true if a or b is true: result is union
                    val tA = applyConditionNarrowing(t, expr.left, true, name)
                    val tB = applyConditionNarrowing(t, expr.right, true, name)
                    getUnionType(listOf(tA, tB))
                } else {
                    // !(a || b) ⇔ !a && !b
                    val tA = applyConditionNarrowing(t, expr.left, false, name)
                    applyConditionNarrowing(tA, expr.right, false, name)
                }
                SyntaxKind.AmpersandAmpersand -> if (isTrue) {
                    // `a && b` true: both true
                    val tA = applyConditionNarrowing(t, expr.left, true, name)
                    applyConditionNarrowing(tA, expr.right, true, name)
                } else {
                    // !(a && b) ⇔ !a || !b
                    val tA = applyConditionNarrowing(t, expr.left, false, name)
                    val tB = applyConditionNarrowing(t, expr.right, false, name)
                    getUnionType(listOf(tA, tB))
                }
                // round 44 iter9: nullish coalescing `a ?? b`. When truthy, EITHER
                // a is non-null/undefined (and truthy), OR a is null/undefined and b is truthy.
                // The combined narrowing on the truthy side requires either side to narrow
                // `name` to non-null/undefined assignability. Simpler: union of both sides'
                // truthy narrowings (matches `||` semantics for the union direction).
                SyntaxKind.QuestionQuestion -> if (isTrue) {
                    val tA = applyConditionNarrowing(t, expr.left, true, name)
                    val tB = applyConditionNarrowing(t, expr.right, true, name)
                    getUnionType(listOf(tA, tB))
                } else {
                    // `a ?? b` falsy iff a is null/undefined AND b is falsy.
                    // Narrow `name` to falsy on both sides.
                    val tA = applyConditionNarrowing(t, expr.left, false, name)
                    applyConditionNarrowing(tA, expr.right, false, name)
                }
                SyntaxKind.EqualsEqualsEquals,
                SyntaxKind.EqualsEquals -> narrowByEquality(t, expr, equal = isTrue, name)
                SyntaxKind.ExclamationEqualsEquals,
                SyntaxKind.ExclamationEquals -> narrowByEquality(t, expr, equal = !isTrue, name)
                SyntaxKind.InstanceOfKeyword -> narrowByInstanceOf(t, expr, isMatch = isTrue, name)
                SyntaxKind.InKeyword -> narrowByInOperator(t, expr, hasProp = isTrue, name)
                else -> t
            }
            is CallExpression -> {
                // round 44 iter16: Boolean(x) call narrows x identically to direct truthiness.
                // (Number(x) and String(x) coercion calls do NOT preserve narrowing semantics —
                // Number("abc") = NaN (falsy), String(undefined) = "undefined" (truthy) — so
                // they're intentionally excluded.)
                val callee = unwrapParensExpr(expr.expression)
                if (callee is Identifier && callee.text == "Boolean" && expr.arguments.size == 1) {
                    val arg = expr.arguments[0]
                    if (getReferencePath(arg) == name) return narrowByTruthiness(t, truthy = isTrue)
                }
                narrowByCallPredicate(t, expr, isMatch = isTrue, name)
            }
            is Identifier -> if (expr.text == name) narrowByTruthiness(t, truthy = isTrue) else t
            // 17.34: PropertyAccess truthiness narrowing — `if (A._a) { ... A._a ... }`
            // narrows `A._a` from `T | undefined | null` to `T` on the truthy side.
            // Path comparison gates by structural identity of the dotted reference path.
            is PropertyAccessExpression -> {
                if (getReferencePath(expr) == name) narrowByTruthiness(t, truthy = isTrue)
                // round 43 iter11: optional-chain receiver narrowing —
                // `if (obj?.x) { ... obj ... }` narrows obj to non-null/undefined on
                // the truthy side. The `?.` short-circuits when obj is null/undefined,
                // so for the condition to be truthy, obj must NOT be null/undefined.
                else if (expr.questionDotToken && isTrue && getReferencePath(expr.expression) == name) {
                    narrowByExcludingNullUndefined(t)
                }
                // round 44 iter5: multi-level optional-chain — `if (obj?.x?.y)` truthy
                // implies the WHOLE chain didn't short-circuit, so any intermediate path
                // referenced by [name] is non-null. Walk the chain looking for a
                // questionDotToken intermediate matching [name].
                else if (isTrue) {
                    var cur: Expression = expr.expression
                    while (cur is PropertyAccessExpression) {
                        if (cur.questionDotToken && getReferencePath(cur.expression) == name) {
                            return narrowByExcludingNullUndefined(t)
                        }
                        if (getReferencePath(cur) == name && expr.questionDotToken) {
                            // Direct ancestor matches name AND the outer expr is optional-chain
                            return narrowByExcludingNullUndefined(t)
                        }
                        cur = cur.expression
                    }
                    t
                } else t
            }
            else -> t
        }
    }

    /**
     * Narrow [t] by truthiness. On truthy positions remove members that
     * are always falsy (undefined, null, void, false, "", 0, 0n). On
     * falsy positions remove members that are definitely truthy
     * (object-like types: Object / Interface / Reference; literal-truthy:
     * non-empty StringLiteral, non-zero NumberLiteral, true,
     * non-zero BigIntLiteral). Primitive intrinsics like `string`/`number`
     * are kept on both sides — they could be either the empty/zero
     * variant or the non-empty/non-zero variant.
     */
    /**
     * round 43 iter11: helper for optional-chain receiver narrowing. Removes
     * null/undefined/void from a union; returns t unchanged for non-union or
     * when no nullish members are present. Returns neverType if all members
     * are nullish (shouldn't normally happen — caller should bail).
     */
    private fun narrowByExcludingNullUndefined(t: Type): Type {
        if (t !is Type.Union) return t
        val filtered = t.types.filter {
            !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)
        }
        return when {
            filtered.isEmpty() -> t  // conservative — don't return never
            filtered.size == t.types.size -> t  // no narrowing
            filtered.size == 1 -> filtered[0]
            else -> getUnionType(filtered)
        }
    }

    private fun narrowByTruthiness(t: Type, truthy: Boolean): Type {
        return if (truthy) {
            when {
                isDefinitelyFalsyMember(t) -> neverType
                t is Type.Union -> {
                    val kept = t.types.filter { !isDefinitelyFalsyMember(it) }
                    when {
                        kept.isEmpty() -> neverType
                        kept.size == t.types.size -> t
                        else -> getUnionType(kept)
                    }
                }
                else -> t
            }
        } else {
            when {
                isDefinitelyTruthyMember(t) -> neverType
                t is Type.Union -> {
                    val kept = t.types.filter { !isDefinitelyTruthyMember(it) }
                    when {
                        kept.isEmpty() -> neverType
                        kept.size == t.types.size -> t
                        else -> getUnionType(kept)
                    }
                }
                else -> t
            }
        }
    }

    private fun isDefinitelyFalsyMember(t: Type): Boolean = when {
        t === undefinedType || t === nullType || t === voidType || t === falseType -> true
        t is Type.StringLiteral -> t.value.isEmpty()
        t is Type.NumberLiteral -> t.value == 0.0
        t is Type.BigIntLiteral -> isZeroBigIntLiteral(t.value)
        else -> false
    }

    private fun isDefinitelyTruthyMember(t: Type): Boolean = when {
        t is Type.Object || t is Type.Interface || t is Type.Reference -> true
        t === trueType -> true
        t is Type.StringLiteral -> t.value.isNotEmpty()
        t is Type.NumberLiteral -> t.value != 0.0
        t is Type.BigIntLiteral -> !isZeroBigIntLiteral(t.value)
        else -> false
    }

    private fun isZeroBigIntLiteral(value: String): Boolean =
        value == "0" || value == "0n"

    /**
     * Narrow `t` by a `predFn(name)` call where `predFn` is declared with a type
     * predicate return type (`function predFn(x): x is T`). `isMatch=true`
     * (then-branch) keeps types assignable to T; `false` (else-branch) removes
     * them. Mirrors `narrowByInstanceOf` shape — the only difference is how the
     * target type is resolved (from the predicate annotation rather than the
     * instanceof RHS).
     *
     * Falls back to `t` unchanged if the callee isn't a function with a
     * non-asserting type predicate, or if the matching argument isn't an
     * Identifier matching [name]. `asserts` predicates are skipped — those
     * narrow only on the assertion path, not via the boolean return.
     */
    /**
     * round 43 iter8: helper for narrowByAssertCall — resolve a PropertyAccess
     * callee to its method declaration. Returns null when the receiver type
     * doesn't resolve, the property isn't a method, or the property is not
     * directly declared on the receiver's interface/class.
     */
    private fun resolvePropertyMethodDecl(access: PropertyAccessExpression): Node? {
        val recvType = try { getTypeOfExpression(access.expression) } catch (_: StackOverflowError) { return null }
        if (recvType === anyType || recvType === errorType) return null
        val propName = access.name.text
        val sym = getPropertyOfType(recvType, propName) ?: return null
        return sym.valueDeclaration ?: sym.declarations.firstOrNull { it is MethodDeclaration }
    }

    /**
     * round 43 iter5: switch-case discriminant narrowing. When `switch (X) { case <lit>: ... }`
     * and [name] matches X's reference path, collect all case literals in
     * [flowNode.clauseStart, flowNode.clauseEnd) range and filter [t] (a union)
     * to members assignable from any of those literals. Returns null when the
     * switch subject doesn't match [name] or no usable case literals are found.
     */
    private fun narrowBySwitchClause(t: Type, flowNode: FlowSwitchClause, name: String): Type? {
        val subjectPath = getReferencePath(flowNode.switchStatement.expression) ?: return null
        // round 43 iter10: discriminant-parent narrowing — `switch (x.kind) { case "a": ... }`
        // narrows x (the receiver) by filtering union members whose `kind` property is
        // assignable from the case literal.
        val (matchesDirectly, discriminantName) = when {
            subjectPath == name -> true to null
            subjectPath.startsWith("$name.") && subjectPath.indexOf('.', name.length + 1) < 0 -> {
                // single-level property access (e.g., "x.kind" when name == "x"); the
                // discriminant property is the part after "name."
                false to subjectPath.substring(name.length + 1)
            }
            else -> return null
        }
        // Collect literal types from cases in the [clauseStart, clauseEnd) range.
        val literalTypes = mutableListOf<Type>()
        val clauses = flowNode.switchStatement.caseBlock
        var idx = 0
        for (clause in clauses) {
            if (idx >= flowNode.clauseEnd) break
            if (idx >= flowNode.clauseStart) {
                when (clause) {
                    is CaseClause -> literalTypeOfExpression(clause.expression)?.let { literalTypes.add(it) }
                    is DefaultClause -> {
                        // Default clause — no narrowing possible from this clause alone.
                        return null
                    }
                    else -> {}
                }
            }
            idx++
        }
        if (literalTypes.isEmpty()) return null
        if (t !is Type.Union) return null
        val filtered = if (matchesDirectly) {
            // Direct path: filter by member-assignable-from-literal.
            t.types.filter { member ->
                literalTypes.any { lit -> checkTypeRelatedTo(lit, member, assignableRelation) }
            }
        } else {
            // Discriminant-property path: filter by member's [discriminantName] property
            // being assignable from any case literal.
            val discriminant = discriminantName ?: return null
            t.types.filter { member ->
                val propSym = getPropertyOfType(member, discriminant) ?: return@filter true
                val propType = try { getTypeOfSymbol(propSym) } catch (_: StackOverflowError) { return@filter true }
                if (propType === anyType || propType === errorType) true
                else literalTypes.any { lit -> checkTypeRelatedTo(lit, propType, assignableRelation) }
            }
        }
        return when {
            filtered.isEmpty() -> null
            filtered.size == 1 -> filtered[0]
            filtered.size == t.types.size -> null
            else -> getUnionType(filtered)
        }
    }

    /**
     * round 43 iter3: assert-function narrowing after a call returns. For
     * `function assertX(x): asserts x is T` (assertsModifier=true), when the
     * call's first matching arg path is [name], narrow [t] to T (target type).
     * For `asserts x` (no `is T` clause), narrow nullable types by excluding
     * null/undefined (the assertion proves x is non-null after return). Returns
     * null when callee isn't an assert function or arg doesn't match.
     */
    private fun narrowByAssertCall(t: Type, expr: CallExpression, name: String): Type? {
        // Unwrap value-preserving wrappers around the callee.
        var callee: Expression = expr.expression
        while (true) {
            callee = when (callee) {
                is ParenthesizedExpression -> if (callee.instantiationEnd == null) callee.expression else return null
                is NonNullExpression -> callee.expression
                is AsExpression -> callee.expression
                is TypeAssertionExpression -> callee.expression
                is SatisfiesExpression -> callee.expression
                else -> break
            }
        }
        // round 43 iter8: PropertyAccess callee — `obj.assertMethod(x)` where
        // `obj`'s type has a method `assertMethod` with `asserts x is T` return.
        val decl: Node? = when (callee) {
            is Identifier -> {
                val symbol = currentFileLocals?.get(callee.text) ?: globals[callee.text] ?: return null
                symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
            }
            is PropertyAccessExpression -> resolvePropertyMethodDecl(callee)
            else -> return null
        } ?: return null
        val (params, returnTypeNode) = when (decl) {
            is FunctionDeclaration -> decl.parameters to decl.type
            is MethodDeclaration -> decl.parameters to decl.type
            else -> return null
        }
        val predicate = returnTypeNode as? TypePredicate ?: return null
        if (!predicate.assertsModifier) return null
        val predicateParamName = when (val pn = predicate.parameterName) {
            is Identifier -> pn.text
            is TypeReference -> (pn.typeName as? Identifier)?.text
            else -> null
        } ?: return null
        val paramIdx = params.indexOfFirst { (it.name as? Identifier)?.text == predicateParamName }
        if (paramIdx < 0) return null
        val arg = expr.arguments.getOrNull(paramIdx) ?: return null
        if (getReferencePath(arg) != name) return null
        // `asserts x` without `is T` clause — narrow by excluding null/undefined.
        val targetTypeNode = predicate.type ?: return run {
            if (t is Type.Union) {
                val filtered = t.types.filter { !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) }
                if (filtered.isEmpty()) neverType
                else if (filtered.size == 1) filtered[0]
                else getUnionType(filtered)
            } else t
        }
        val targetType = try { getTypeFromTypeNode(targetTypeNode) } catch (_: StackOverflowError) { return null }
        if (targetType === errorType || targetType === anyType) return null
        // After assertion succeeds, narrow to target type.
        if (t is Type.Union) {
            val filtered = t.types.filter { checkTypeRelatedTo(it, targetType, assignableRelation) }
            return when {
                filtered.isEmpty() -> targetType
                filtered.size == 1 -> filtered[0]
                else -> getUnionType(filtered)
            }
        }
        val matches = checkTypeRelatedTo(t, targetType, assignableRelation)
        return if (matches) t else targetType
    }

    private fun narrowByCallPredicate(
        t: Type, expr: CallExpression, isMatch: Boolean, name: String,
    ): Type {
        // Unwrap value-preserving wrappers around the callee so `(isFoo)(x)`,
        // `isFoo!(x)`, `(isFoo as F)(x)` narrow identically to `isFoo(x)`.
        var callee: Expression = expr.expression
        while (true) {
            callee = when (callee) {
                is ParenthesizedExpression -> if ((callee as ParenthesizedExpression).instantiationEnd == null) (callee as ParenthesizedExpression).expression else return t
                is NonNullExpression -> (callee as NonNullExpression).expression
                is AsExpression -> (callee as AsExpression).expression
                is TypeAssertionExpression -> (callee as TypeAssertionExpression).expression
                is SatisfiesExpression -> (callee as SatisfiesExpression).expression
                else -> break
            }
        }
        // round 43 iter9: PropertyAccess callee — `obj.isMethod(x)` where
        // `obj`'s type has a method `isMethod` with `x is T` return type.
        val decl: Node? = when (callee) {
            is Identifier -> {
                val symbol = currentFileLocals?.get(callee.text) ?: globals[callee.text] ?: return t
                symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
            }
            is PropertyAccessExpression -> resolvePropertyMethodDecl(callee)
            else -> return t
        } ?: return t
        val (params, returnTypeNode) = when (decl) {
            is FunctionDeclaration -> decl.parameters to decl.type
            is MethodDeclaration -> decl.parameters to decl.type
            else -> return t
        }
        val predicate = returnTypeNode as? TypePredicate ?: return t
        if (predicate.assertsModifier) return t
        val targetTypeNode = predicate.type ?: return t
        // Parser quirk: `c is C1` parses `c` as a TypeReference (the LHS is parsed
        // by parseIntersectionOrHigherType before `is` is recognized). Extract the
        // parameter name from either Identifier or TypeReference shape.
        val predicateParamName = when (val pn = predicate.parameterName) {
            is Identifier -> pn.text
            is TypeReference -> (pn.typeName as? Identifier)?.text
            else -> null
        } ?: return t
        val paramIdx = params.indexOfFirst { (it.name as? Identifier)?.text == predicateParamName }
        if (paramIdx < 0) return t
        val arg = expr.arguments.getOrNull(paramIdx) ?: return t
        // 17.34b: path-based comparison so `predFn(A._a)` matches when name="A._a".
        if (getReferencePath(arg) != name) return t
        val targetType = try { getTypeFromTypeNode(targetTypeNode) } catch (_: StackOverflowError) { return t }
        if (targetType === errorType || targetType === anyType) return t
        if (t is Type.Union) {
            val filtered = if (isMatch) {
                t.types.filter { checkTypeRelatedTo(it, targetType, assignableRelation) }
            } else {
                t.types.filter { !checkTypeRelatedTo(it, targetType, assignableRelation) }
            }
            return getUnionType(filtered)
        }
        val matches = checkTypeRelatedTo(t, targetType, assignableRelation)
        return when {
            matches == isMatch -> t
            isMatch -> targetType
            else -> neverType
        }
    }

    /**
     * Narrow `t` by an `name instanceof Class` check. `isMatch=true` keeps types
     * assignable from the class (filtered out of a union); `false` removes them.
     * Resolves the RHS expression to a class type via `getDeclaredTypeOfSymbol`
     * — supports identifier and qualified-name references to a class. Falls
     * back to `t` unchanged if the RHS doesn't resolve to an object type.
     */
    private fun narrowByInstanceOf(
        t: Type, expr: BinaryExpression, isMatch: Boolean, name: String,
    ): Type {
        // 17.34b: path-based comparison so `A._a instanceof Class` matches when name="A._a".
        if (getReferencePath(expr.left) != name) return t
        val classType = resolveInstanceOfRhsType(expr.right) ?: return t
        if (t is Type.Union) {
            val filtered = if (isMatch) {
                t.types.filter { isInstanceOfClass(it, classType) }
            } else {
                t.types.filter { !isInstanceOfClass(it, classType) }
            }
            return getUnionType(filtered)
        }
        val matches = isInstanceOfClass(t, classType)
        return when {
            matches == isMatch -> t
            isMatch -> classType
            // matches=true, isMatch=false: source IS the class but we're in the
            // !instanceof branch — contradiction → narrow to never. Mirrors
            // narrowByTypeOfGuard's same-shape behavior for typeof tags.
            else -> neverType
        }
    }

    /**
     * Symbol-identity instanceof check: `t` is an instance of `cls` iff t and cls
     * are the same class symbol, or t's extends chain includes cls. This differs
     * from structural assignability — two structurally-identical classes with
     * distinct symbols (e.g. `class C1 { x: string }; class C3 { x: string }`)
     * are NOT instances of each other at runtime, even though they're mutually
     * assignable. Falls back to assignability for non-Interface shapes (e.g. when
     * narrowing a non-class instance type like `string`).
     */
    private fun isInstanceOfClass(t: Type, cls: Type): Boolean {
        if (t !is Type.Interface || cls !is Type.Interface) {
            return checkTypeRelatedTo(t, cls, assignableRelation)
        }
        if (t.symbol != null && t.symbol === cls.symbol) return true
        return t.baseTypes?.any { isInstanceOfClass(it, cls) } ?: false
    }

    /**
     * Narrow `t` by a `"prop" in name` check. `hasProp=true` (positive branch):
     * keep types whose own property set includes `prop`. `hasProp=false` (else
     * branch): keep types that don't have `prop`. The LHS of `in` must be a
     * StringLiteral / NumericLiteral / NoSubstitutionTemplateLiteral and the
     * RHS must be the identifier matching [name]. Falls back to `t` unchanged
     * for non-literal LHS or non-matching RHS.
     *
     * Implementation note: TypeScript's actual `in` narrowing is subtler around
     * intersection types and Record-like types — this surgical version handles
     * the common Type.Object / Type.Interface union case and is intentionally
     * conservative on edge shapes (returns `t` rather than risk over-narrowing).
     */
    private fun narrowByInOperator(
        t: Type, expr: BinaryExpression, hasProp: Boolean, name: String,
    ): Type {
        // RHS (right of `in`) must be the path we're narrowing.
        // 17.34b: path-based comparison so `'k' in A._a` matches when name="A._a".
        if (getReferencePath(expr.right) != name) return t
        // LHS (left of `in`) must be a literal property name we can statically resolve.
        // Unwrap parens so `("k") in obj` narrows identically to `"k" in obj`.
        val propName: String = when (val left = unwrapParensExpr(expr.left)) {
            is StringLiteralNode -> left.text
            is NoSubstitutionTemplateLiteralNode -> left.text
            is NumericLiteralNode -> left.text
            else -> return t
        }
        if (t is Type.Union) {
            val filtered = if (hasProp) {
                t.types.filter { typeHasOwnProperty(it, propName) }
            } else {
                t.types.filter { !typeHasOwnProperty(it, propName) }
            }
            return getUnionType(filtered)
        }
        // Non-union: contradiction → never; otherwise unchanged.
        val present = typeHasOwnProperty(t, propName)
        return when {
            present == hasProp -> t
            // present=true, hasProp=false: source HAS the prop but we're in
            // the !in branch — contradiction → never. Mirrors instanceof/typeof.
            !hasProp -> neverType
            // present=false, hasProp=true: source DOESN'T have the prop but
            // we're in the `in` branch — TypeScript widens to source &
            // Record<prop, unknown>; we just keep `t` (conservative).
            else -> t
        }
    }

    /**
     * True if [type] has an own property named [propName]. Looks up the
     * property via [getPropertyOfType] for object/interface/reference types.
     * Returns false for primitives / union / intersection / any / never —
     * `narrowByInOperator` handles unions before reaching this.
     */
    private fun typeHasOwnProperty(type: Type, propName: String): Boolean {
        if (type !is Type.Object) return false
        return try {
            getPropertyOfType(type, propName) != null
        } catch (_: StackOverflowError) { false }
    }

    /**
     * Resolve the RHS of an `instanceof` to its instance type. For `x instanceof C`
     * where C is a class, returns the class instance type. Returns null if C
     * isn't a class symbol or the RHS isn't a recognized class reference.
     */
    private fun resolveInstanceOfRhsType(expr: Expression): Type? {
        // Unwrap value-preserving wrappers so `x instanceof (C)` / `x instanceof C!`
        // narrows the same as `x instanceof C`.
        var e = expr
        while (true) {
            e = when (e) {
                is ParenthesizedExpression -> if (e.instantiationEnd == null) e.expression else return null
                is NonNullExpression -> e.expression
                is AsExpression -> e.expression
                is TypeAssertionExpression -> e.expression
                is SatisfiesExpression -> e.expression
                else -> break
            }
        }
        val symbol = when (e) {
            is Identifier -> currentFileLocals?.get(e.text) ?: globals[e.text]
            else -> null
        } ?: return null
        if (!symbol.flags.hasAny(SymbolFlags.Class)) return null
        return try {
            getDeclaredTypeOfSymbol(symbol).takeIf { it !== anyType && it !== errorType }
        } catch (_: StackOverflowError) { null }
    }

    /**
     * Narrow type [t] given a `===`/`==`/`!==`/`!=` comparison. [equal] is the
     * effective polarity (true means "expression evaluates to equal").
     * Handles `typeof x === "string"` first, then `x.constructor === Class`,
     * then falls back to `x === literal` direct equality narrowing.
     */
    private fun narrowByEquality(
        t: Type, expr: BinaryExpression, equal: Boolean, name: String,
    ): Type {
        tryNarrowByTypeOf(t, expr, equal, name)?.let { return it }
        narrowByConstructorEquals(t, expr, equal, name)?.let { return it }
        narrowByDiscriminantProperty(t, expr, equal, name)?.let { return it }

        // 17.34b: path-based comparison so PropertyAccess sources (`A._a`) match
        // alongside bare Identifiers. `getReferencePath` returns null for shapes
        // that aren't pure Identifier-or-PropertyAccess chains, so calls/parens/
        // element-access on either side of `===` won't accidentally match.
        val leftIsRef = getReferencePath(expr.left) == name
        val rightIsRef = getReferencePath(expr.right) == name
        val other = when {
            leftIsRef && !rightIsRef -> expr.right
            rightIsRef && !leftIsRef -> expr.left
            else -> return t
        }
        val literalType = literalTypeOfExpression(other) ?: return t
        return narrowUnionByLiteral(t, literalType, keep = equal)
    }

    /**
     * Discriminated-union narrowing through property-equality.
     * Pattern: `name.propX === literal` (or `!==`, or symmetric).
     *
     * For each Union member, look up `propX`'s declared type. If it's a literal
     * type, compare against the RHS literal: positive branch keeps members whose
     * `propX` matches; negative branch drops members whose `propX` exactly matches.
     *
     * Conservative gates (returns null / keeps member unchanged):
     * - `t` must be a Type.Union (no narrowing on a single type — could regress).
     * - LHS or RHS must be `name.propX` PropertyAccessExpression with Identifier name.
     * - Other side must be a recognizable literal expression.
     * - Members without the property are kept (can't prove the comparison false).
     * - Members whose propX is non-literal (e.g. `string` instead of `'a'`) are
     *   kept (could match any value).
     * - Returns null if the expression doesn't match the discriminant shape, so
     *   callers fall through to direct-equality narrowing.
     */
    private fun narrowByDiscriminantProperty(
        t: Type, expr: BinaryExpression, equal: Boolean, name: String,
    ): Type? {
        if (t !is Type.Union) return null
        val propAccess: PropertyAccessExpression
        val literalSide: Expression
        when {
            isDiscriminantAccessOf(expr.left, name) -> {
                propAccess = unwrapParensExpr(expr.left) as PropertyAccessExpression
                literalSide = expr.right
            }
            isDiscriminantAccessOf(expr.right, name) -> {
                propAccess = unwrapParensExpr(expr.right) as PropertyAccessExpression
                literalSide = expr.left
            }
            else -> return null
        }
        val propName = (propAccess.name as? Identifier)?.text ?: return null
        if (propName.isEmpty()) return null
        val literalType = literalTypeOfExpression(literalSide) ?: return null
        val filtered = t.types.filter { member ->
            val apparent = try { getApparentType(member) } catch (_: StackOverflowError) { return@filter true }
            if (apparent !is Type.Object) return@filter true
            val propSym = try { getPropertyOfType(apparent, propName) } catch (_: StackOverflowError) { return@filter true }
                ?: return@filter true
            val propType = try { getTypeOfSymbol(propSym) } catch (_: StackOverflowError) { return@filter true }
            if (propType === anyType || propType === errorType || propType === unknownType) return@filter true
            if (!isLiteralKindForDiscriminant(propType)) return@filter true
            val matches = literalsEqualForDiscriminant(propType, literalType)
            if (equal) matches else !matches
        }
        return getUnionType(filtered)
    }

    private fun isDiscriminantAccessOf(expr: Expression, name: String): Boolean {
        val unwrapped = unwrapParensExpr(expr)
        if (unwrapped !is PropertyAccessExpression) return false
        // 17.34b: path-based comparison so `A._a.kind === ...` matches when name="A._a".
        return getReferencePath(unwrapped.expression) == name && unwrapped.name is Identifier
    }

    private fun isLiteralKindForDiscriminant(t: Type): Boolean =
        t is Type.StringLiteral || t is Type.NumberLiteral || t is Type.BigIntLiteral ||
            t === trueType || t === falseType

    private fun literalsEqualForDiscriminant(a: Type, b: Type): Boolean = when {
        a is Type.StringLiteral && b is Type.StringLiteral -> a.value == b.value
        a is Type.NumberLiteral && b is Type.NumberLiteral -> a.value == b.value
        a is Type.BigIntLiteral && b is Type.BigIntLiteral -> a.value == b.value
        a === trueType && b === trueType -> true
        a === falseType && b === falseType -> true
        else -> false
    }

    /**
     * Narrow `t` by an `x.constructor === Class` / `x["constructor"] === Class`
     * (or `!==`) comparison. Mirrors TypeScript's `.constructor`-identity
     * narrowing: at runtime, `obj.constructor` is the exact class symbol the
     * object was constructed with — so `obj.constructor === C` narrows `obj` to
     * types whose class symbol is exactly `C` (NOT subclasses). Distinct from
     * `instanceof`, which DOES include subclasses.
     *
     * Returns null if the expression isn't a `name.constructor === ClassRef`
     * (or symmetric, or bracket-form) shape, so callers can fall through to
     * other narrowers.
     *
     * Positive branch (equal=true): for unions, filter to members with exact
     * class symbol match; for non-unions, narrow to `classType` if not already
     * the exact class. Negative branch (equal=false): TypeScript does NOT
     * narrow — `var.constructor !== C` only excludes "this specific instance's
     * constructor was C", which is too weak to remove a class member from the
     * union (subclass instances and reassigned `.constructor` values exist).
     * Return `t` unchanged.
     */
    private fun narrowByConstructorEquals(
        t: Type, expr: BinaryExpression, equal: Boolean, name: String,
    ): Type? {
        val classExpr = when {
            isConstructorAccessOf(expr.left, name) -> expr.right
            isConstructorAccessOf(expr.right, name) -> expr.left
            else -> return null
        }
        val classType = resolveInstanceOfRhsType(classExpr) ?: return null
        val classSymbol = (classType as? Type.Interface)?.symbol ?: return null
        if (!equal) return t
        if (t is Type.Union) {
            return getUnionType(t.types.filter { hasExactClassSymbol(it, classSymbol) })
        }
        return if (hasExactClassSymbol(t, classSymbol)) t else classType
    }

    private fun isConstructorAccessOf(expr: Expression, name: String): Boolean {
        val unwrapped = unwrapParensExpr(expr)
        val obj: Expression
        val isProp: Boolean
        when (unwrapped) {
            is PropertyAccessExpression -> {
                obj = unwrapped.expression
                val propName = unwrapped.name
                isProp = propName is Identifier && propName.text == "constructor"
            }
            is ElementAccessExpression -> {
                obj = unwrapped.expression
                val arg = unwrapParensExpr(unwrapped.argumentExpression)
                isProp = (arg is StringLiteralNode && arg.text == "constructor") ||
                        (arg is NoSubstitutionTemplateLiteralNode && arg.text == "constructor")
            }
            else -> return false
        }
        if (!isProp) return false
        // 17.34b: path-based comparison so `(A._a).constructor` matches when name="A._a".
        return getReferencePath(obj) == name
    }

    private fun hasExactClassSymbol(t: Type, classSymbol: Symbol): Boolean {
        return t is Type.Interface && t.symbol === classSymbol
    }

    /**
     * Try to narrow `t` for a `typeof name === "tag"` (or `!==`) comparison.
     * Returns the narrowed type if the expression matches, or `null` if the
     * expression isn't a typeof-against-string-literal comparison on `name`.
     */
    private fun tryNarrowByTypeOf(
        t: Type, expr: BinaryExpression, equal: Boolean, name: String,
    ): Type? {
        val leftTypeofRef = isTypeOfRef(expr.left, name)
        val rightTypeofRef = isTypeOfRef(expr.right, name)
        if (!leftTypeofRef && !rightTypeofRef) return null
        val literalSide = unwrapParensExpr(if (leftTypeofRef) expr.right else expr.left)
        val guard = when (literalSide) {
            is StringLiteralNode -> literalSide.text
            is NoSubstitutionTemplateLiteralNode -> literalSide.text
            else -> return null
        }
        return narrowByTypeOfGuard(t, guard, isMatch = equal)
    }

    private fun isTypeOfRef(expr: Expression, name: String): Boolean {
        // `(typeof x) === "string"` should narrow identically to `typeof x === "string"`.
        val unwrapped = unwrapParensExpr(expr)
        if (unwrapped !is TypeOfExpression) return false
        // 17.34b: path-based comparison so `typeof A._a` matches when name="A._a".
        return getReferencePath(unwrapped.expression) == name
    }

    /**
     * Narrow `t` by a typeof tag (`"string"` / `"number"` / etc.). For unions,
     * filters constituents by their TypeFlags. For non-unions, returns `t` if
     * the type matches the tag and `isMatch` is true (or doesn't match and
     * `isMatch` is false), else returns `never`. `"function"` and `"object"`
     * tags fall back to `t` unchanged (can't be filtered by flags alone).
     */
    private fun narrowByTypeOfGuard(t: Type, guard: String, isMatch: Boolean): Type {
        val flags = typeofTypeGuardFlags(guard) ?: return t
        if (flags == TypeFlags.None) return t
        if (t is Type.Union) {
            val filtered = if (isMatch) {
                t.types.filter { it.flags.hasAny(flags) }
            } else {
                t.types.filter { !it.flags.hasAny(flags) }
            }
            return getUnionType(filtered)
        }
        val typeMatches = t.flags.hasAny(flags)
        return if (typeMatches == isMatch) t else neverType
    }

    /**
     * Extract a literal Type from an expression (string/number/boolean/null/undefined).
     * Returns null for non-literal expressions — narrowing only applies to literal comparisons.
     */
    private fun literalTypeOfExpression(expr: Expression): Type? = when (expr) {
        is StringLiteralNode -> Type.StringLiteral(expr.text)
        is NoSubstitutionTemplateLiteralNode -> Type.StringLiteral(expr.text)
        is NumericLiteralNode -> Type.NumberLiteral(expr.text.toDoubleOrNull() ?: return null)
        is PrefixUnaryExpression -> if (expr.operator == SyntaxKind.Minus && expr.operand is NumericLiteralNode) {
            Type.NumberLiteral(-((expr.operand as NumericLiteralNode).text.toDoubleOrNull() ?: return null))
        } else null
        is BigIntLiteralNode -> Type.BigIntLiteral(expr.text.removeSuffix("n"))
        is Identifier -> when (expr.text) {
            "true" -> trueType
            "false" -> falseType
            "null" -> nullType
            "undefined" -> undefinedType
            else -> null
        }
        // ConditionalExpression with two literal-typed branches: return union of literals
        // so contextual literal preservation (e.g. `const x: 0 | 1 = cond ? 0 : 1`) sees the
        // narrow source type instead of widening through `getTypeOfExpression`.
        is ConditionalExpression -> {
            val t = literalTypeOfExpression(expr.whenTrue)
            val f = literalTypeOfExpression(expr.whenFalse)
            if (t != null && f != null) getUnionType(listOf(t, f)) else null
        }
        is ParenthesizedExpression -> literalTypeOfExpression(expr.expression)
        // B70.5: `expr!` (non-null assertion) preserves literal type — `(0 as const)!` is `0`.
        is NonNullExpression -> literalTypeOfExpression(expr.expression)
        // `expr as const` preserves the literal — `0 as const` is `0`, not `number`.
        // Other `as T` casts don't preserve (the cast intentionally changes the type),
        // so only the `const` keyword form is treated as literal-preserving here.
        is AsExpression -> {
            val t = expr.type
            if (t is TypeReference && (t.typeName as? Identifier)?.text == "const") {
                literalTypeOfExpression(expr.expression)
            } else null
        }
        // `expr satisfies T` is a pure-type-check: the runtime expression and its
        // type are unchanged. Preserve literal type for source literal preservation.
        is SatisfiesExpression -> literalTypeOfExpression(expr.expression)
        else -> null
    }

    /**
     * Narrow union [t] by [literalType]. When [keep] is true (== comparison
     * with isTrue), keep only members assignable from [literalType]. When
     * [keep] is false (!= comparison with isTrue, or == with isFalse), remove
     * members exactly matching [literalType].
     */
    private fun narrowUnionByLiteral(t: Type, literalType: Type, keep: Boolean): Type {
        if (t !is Type.Union) {
            // For non-union, narrowing-by-literal still applies for the keep=false case
            // (e.g., `s: string` and `s !== "x"` doesn't change `s`'s type).
            return t
        }
        return if (keep) {
            // round 45 iter1: positive narrowing — for each member, if it exactly matches
            // the literal, keep it; if it's a SUPERTYPE of the literal (e.g., `string`
            // supertype of `"abc"`), replace with the literal; otherwise remove.
            // Without supertype substitution, `s: string | null` narrowed by `s === "abc"`
            // would filter to empty → neverType, losing precision.
            val kept = mutableListOf<Type>()
            for (member in t.types) {
                when {
                    areLiteralTypesEquivalent(member, literalType) -> kept.add(member)
                    isLiteralAssignableToMember(literalType, member) -> kept.add(literalType)
                    // else: remove (not assignable, not equal)
                }
            }
            if (kept.isEmpty()) t else getUnionType(kept)
        } else {
            getUnionType(t.types.filter { !areLiteralTypesEquivalent(it, literalType) })
        }
    }

    /**
     * round 45 iter1 helper: true when [literal] is assignable to [member]. Used for
     * positive-narrowing supertype substitution. Recognizes:
     * - string literal → stringType
     * - number literal → numberType
     * - bigint literal → bigintType
     * - trueType/falseType → booleanType
     * - nullType / undefinedType → any/unknown
     */
    private fun isLiteralAssignableToMember(literal: Type, member: Type): Boolean {
        return when {
            literal is Type.StringLiteral && member === stringType -> true
            literal is Type.NumberLiteral && member === numberType -> true
            literal is Type.BigIntLiteral && member === bigintType -> true
            (literal === trueType || literal === falseType) && member === booleanType -> true
            member === anyType || member === unknownType -> true
            else -> false
        }
    }

    /**
     * True if two literal types match (same value). Conservative: returns false
     * for non-literal types — narrowing only removes/keeps exact literal matches.
     */
    private fun areLiteralTypesEquivalent(a: Type, b: Type): Boolean = when {
        a is Type.StringLiteral && b is Type.StringLiteral -> a.value == b.value
        a is Type.NumberLiteral && b is Type.NumberLiteral -> a.value == b.value
        a is Type.BigIntLiteral && b is Type.BigIntLiteral -> a.value == b.value
        a === trueType && b === trueType -> true
        a === falseType && b === falseType -> true
        a === nullType && b === nullType -> true
        a === undefinedType && b === undefinedType -> true
        else -> false
    }

    /** Get the type of an object literal expression as an anonymous object type. */
    private fun getTypeOfObjectLiteral(expr: ObjectLiteralExpression): Type {
        val members = symbolTable()
        val properties = mutableListOf<Symbol>()
        // B52.4: When the outer assignment / arg position provides a contextual type
        // (set in checkAssignmentExpression / checkVarDecl / call-arg paths), propagate
        // each matching property type into the property initializer so nested arrow
        // function parameters get inferred from the contextual call signature.
        // Without this, `b3 = { f: (n) => 0 }` displays the source as `{ f: (n: any) => any }`
        // instead of `{ f: (n: number) => number }`.
        val ctxObj = (contextualType as? Type.Object)?.also {
            try { resolveStructuredTypeMembers(it) } catch (_: StackOverflowError) {}
        }
        for (prop in expr.properties) {
            when (prop) {
                is PropertyAssignment -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> continue
                    }
                    val propCtx = ctxObj?.members?.get(name)?.let { sym ->
                        try { getTypeOfSymbol(sym) } catch (_: StackOverflowError) { null }
                    }
                    val savedCtx = contextualType
                    val useCtx = propCtx != null && propCtx !== anyType && propCtx !== errorType &&
                        (prop.initializer is ArrowFunction || prop.initializer is FunctionExpression)
                    if (useCtx) contextualType = propCtx
                    val propType = try {
                        getTypeOfExpression(prop.initializer)
                    } finally {
                        if (useCtx) contextualType = savedCtx
                    }
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is ShorthandPropertyAssignment -> {
                    val name = prop.name.text
                    val propType = getTypeOfExpression(prop.name)
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is MethodDeclaration -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    val sym = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    // Method type — create function type with call signature
                    val returnType = prop.type?.let { getTypeFromTypeNode(it) } ?: anyType
                    val params = getParameterSymbols(prop.parameters)
                    val sig = Signature(
                        declaration = prop,
                        parameters = params,
                        resolvedReturnType = returnType,
                        minArgumentCount = prop.parameters.count {
                            !it.questionToken && !it.dotDotDotToken && it.initializer == null
                        },
                    )
                    val methodType = Type.Object()
                    methodType.callSignatures = listOf(sig)
                    methodType.properties = emptyList()
                    symbolTypes[sym.id] = methodType
                }
                is SpreadAssignment -> continue // spread not yet supported
                is GetAccessor -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> continue
                    }
                    val existing = members[name]
                    val sym = existing ?: Symbol(SymbolFlags.Property, name).also {
                        members[name] = it
                        properties.add(it)
                    }
                    sym.declarations.add(prop)
                    if (sym.valueDeclaration == null) sym.valueDeclaration = prop
                    if (existing == null) {
                        val getterReturn = prop.type?.let { getTypeFromTypeNode(it) } ?: anyType
                        symbolTypes[sym.id] = getterReturn
                    }
                }
                is SetAccessor -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> continue
                    }
                    val existing = members[name]
                    val sym = existing ?: Symbol(SymbolFlags.Property, name).also {
                        members[name] = it
                        properties.add(it)
                    }
                    sym.declarations.add(prop)
                    if (sym.valueDeclaration == null) sym.valueDeclaration = prop
                    if (existing == null) {
                        val paramType = prop.parameters.firstOrNull()?.type
                            ?.let { getTypeFromTypeNode(it) } ?: anyType
                        symbolTypes[sym.id] = paramType
                    }
                }
                else -> continue
            }
        }
        val objType = Type.Object()
        objType.members = members
        objType.properties = properties
        return objType
    }

    /** Get the type of an array literal expression. */
    private fun getTypeOfArrayLiteral(expr: ArrayLiteralExpression): Type {
        if (expr.elements.isEmpty()) return getArrayType(anyType) // empty array → any[] (B87.6)
        // Infer element type as union of all element types
        val elementTypes = mutableListOf<Type>()
        for (el in expr.elements) {
            if (el is SpreadElement) return anyType // spread not yet supported
            val t = getTypeOfExpression(el)
            if (t === anyType || t === errorType) return anyType // can't determine
            if (t !in elementTypes) elementTypes.add(t)
        }
        // For a homogeneous array, element type is the single type
        // For heterogeneous, it's a union
        val elementType = when (elementTypes.size) {
            0 -> anyType
            1 -> elementTypes[0]
            else -> getUnionType(elementTypes)
        }
        return getArrayType(elementType)
    }

    /** B52.4: Narrow helper — return `nullType` only when the block body's first
     * `return` statement returns the `null` literal. Used as a final fallback for
     * arrow-function return-type inference so `(a) => { return null; }` displays
     * as `(a: any) => null` to match TypeScript's contextual-typing baselines
     * (e.g. `assignmentCompatBug2_ts`). Scoped to ArrowFunction only — the broader
     * `inferReturnTypeFromBody` is shared with FunctionDeclaration / MethodDeclaration
     * / GetAccessor where adding `null` would risk widespread regressions. */
    private fun inferArrowReturnNullLiteral(body: Block): Type? {
        for (stmt in body.statements) {
            if (stmt is ReturnStatement) {
                val e = stmt.expression ?: continue
                return if (e is Identifier && e.text == "null") nullType else null
            }
        }
        return null
    }

    /** Get the type of an arrow function expression. */
    private fun getTypeOfArrowFunction(expr: ArrowFunction): Type {
        val params = getParameterSymbols(expr.parameters, forSignatureDisplay = true)
        // Apply contextual typing: infer parameter types from contextual call signature.
        // B83.4f-c: do this BEFORE return-type inference so the body's identifier
        // resolution (`getTypeOfIdentifier` reads `currentLocalTypes`) sees concrete
        // param types. Without this, `(x: number) => { return x.toFixed() }` infers
        // its body return as `any` (x is invisible → `x.toFixed()` → `any`) instead of
        // `string`, leaving the arg type `(x: number) => any` and masking TS2345.
        applyContextualParameterTypes(params, expr.parameters)
        val returnType = expr.type?.let { getTypeFromTypeNode(it) } ?: run {
            val body = expr.body
            // B83.4f-c: push each named param's resolved type into `currentLocalTypes`
            // (save/restore) so `inferReturnTypeFromBody` resolves body identifiers
            // referencing the params to their concrete (annotated or contextual) types.
            val savedLocalTypes = currentLocalTypes
            currentLocalTypes = currentLocalTypes.toMutableMap()
            try {
                for (p in params) {
                    if (p.name.isEmpty()) continue
                    val pt = getTypeOfSymbol(p)
                    if (pt !== anyType && pt !== errorType) currentLocalTypes[p.name] = pt
                }
                when {
                    body is Block && !hasReturnWithExpression(body) -> voidType
                    // B52.4: Infer return type from simple `return <literal>` patterns so an
                    // un-annotated arrow `(n) => { return 0; }` in an object literal whose
                    // target is `{ f(n: number): number }` displays as `(n: number) => number`
                    // instead of `(n: any) => any`. Falls back to a narrow `return null;`
                    // check to handle the wrapper-target case (TS displays `() => null` for
                    // an arrow whose only return is the null literal).
                    body is Block -> inferReturnTypeFromBody(body)
                        ?: inferArrowReturnNullLiteral(body)
                        ?: anyType
                    // Widen concise-body `=> undefined` literal to `any` (mirrors variable-initializer widening).
                    body is Identifier && body.text == "undefined" -> anyType
                    body != null -> getTypeOfExpression(body as Expression) // concise body: () => expr
                    else -> anyType
                }
            } finally {
                currentLocalTypes = savedLocalTypes
            }
        }
        val sig = Signature(
            declaration = expr,
            parameters = params,
            resolvedReturnType = returnType,
            minArgumentCount = expr.parameters.count {
                (it.name as? Identifier)?.text != "this" &&
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        val fnType = Type.Object()
        fnType.callSignatures = listOf(sig)
        fnType.properties = emptyList()
        return fnType
    }

    /** Get the type of a function expression. */
    private fun getTypeOfFunctionExpression(expr: FunctionExpression): Type {
        // 17.10a: Build the function-expression's own type parameters and push them
        // into the type-param scope so `<Tstring>(a: Tstring): Tstring` resolves the
        // `Tstring` annotations to our TypeParam (instead of falling through to global
        // lookup → errorType → display `(a: error) => any`).
        val sigTypeParams = expr.typeParameters?.map { tpDecl ->
            // B59.1 extension: intern by TypeParameter AST position.
            typeParamInternCache.getOrPut(tpDecl.pos) {
                Type.TypeParam().also { tp ->
                    tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                }
            }
        }
        val savedScope = currentTypeParamScope
        if (!sigTypeParams.isNullOrEmpty()) {
            val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
            sigTypeParams.forEachIndexed { i, tp ->
                scope[expr.typeParameters!![i].name.text] = tp
            }
            currentTypeParamScope = scope
        }
        val params = getParameterSymbols(expr.parameters, forSignatureDisplay = true)
        val returnType: Type
        try {
            sigTypeParams?.forEachIndexed { i, tp ->
                expr.typeParameters!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                expr.typeParameters!![i].default?.let { tp.default = getTypeFromTypeNode(it) }
            }
            // Eagerly resolve param types within the scope and cache via symbolTypes
            // — later `getTypeOfSymbol(p)` calls won't have the scope active.
            // Skip leading `this` pseudo-parameter when mapping symbol index → AST index.
            val thisOffset = if (expr.parameters.firstOrNull()?.let { (it.name as? Identifier)?.text } == "this") 1 else 0
            for ((pi, param) in params.withIndex()) {
                val astIdx = pi + thisOffset
                if (astIdx < expr.parameters.size) {
                    expr.parameters[astIdx].type?.let { typeNode ->
                        symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                    }
                }
            }
            returnType = expr.type?.let { getTypeFromTypeNode(it) }
                ?: when {
                    expr.body == null -> anyType
                    !hasReturnWithExpression(expr.body!!) -> voidType
                    else -> inferReturnTypeFromFunctionExpressionBody(expr, params) ?: anyType
                }
        } finally {
            currentTypeParamScope = savedScope
        }
        // Apply contextual typing: infer parameter types from contextual call signature
        applyContextualParameterTypes(params, expr.parameters)
        val sig = Signature(
            declaration = expr,
            typeParameters = sigTypeParams,
            parameters = params,
            resolvedReturnType = returnType,
            minArgumentCount = expr.parameters.count {
                (it.name as? Identifier)?.text != "this" &&
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        val fnType = Type.Object()
        fnType.callSignatures = listOf(sig)
        fnType.properties = emptyList()
        return fnType
    }

    /**
     * 17.10a: Narrow return-type-from-body inference for function expressions
     * with no return annotation. Currently handles `return <param-identifier>`
     * — the simplest case that matters for generic identity-like functions
     * `function f<T>(a: T) { return a; }`. Returns null for unhandled patterns.
     */
    private fun inferReturnTypeFromFunctionExpressionBody(
        expr: FunctionExpression, params: List<Symbol>,
    ): Type? {
        val body = expr.body ?: return null
        val stmts = body.statements
        // B4.4: mirror B4.1 — accept multi-statement bodies with exactly one top-level
        // ReturnStatement. Skips bodies with zero or 2+ top-level returns (returns
        // nested in if/while/for branches don't count — those have multiple paths
        // that LUB-aware inference can't handle yet).
        var retStmt: ReturnStatement? = null
        for (s in stmts) {
            if (s is ReturnStatement) {
                if (retStmt != null) return null
                retStmt = s
            }
        }
        if (retStmt == null) return null
        val retExpr = retStmt.expression ?: return null
        if (retExpr is Identifier) {
            val match = params.firstOrNull { it.name == retExpr.text }
            if (match != null) {
                val pt = symbolTypes[match.id]
                if (pt != null) return pt
            }
            // Fall through to literal inference for non-param identifier returns.
        }
        // 17.154: `return new C()` infers the constructed instance type. Bounded to
        // FunctionExpression single-stmt-body single-return case so regression risk
        // stays narrow. Improves display from `() => any` to `() => C` for patterns
        // like `var a: I4 = function() { return new C2(); }` (interfaceImplementation1).
        if (retExpr is NewExpression) {
            try {
                val t = getReturnTypeOfNewExpression(retExpr)
                if (t !== anyType && t !== errorType) return t
            } catch (_: Throwable) { /* fall through */ }
        }
        return inferReturnTypeFromBody(body)
    }

    /**
     * Apply contextual parameter types from the current contextual type's call signature.
     * For each unannotated parameter, if the contextual type has a matching parameter
     * with a known type, set it via symbolTypes.
     */
    private fun applyContextualParameterTypes(params: List<Symbol>, astParams: List<Parameter>) {
        val ctx = contextualType ?: return
        if (ctx !is Type.Object) return
        resolveStructuredTypeMembers(ctx)
        val ctxSigs = ctx.callSignatures
        if (ctxSigs.isNullOrEmpty()) return
        val ctxSig = ctxSigs[0] // Use first call signature
        val ctxParams = ctxSig.parameters
        for ((i, param) in params.withIndex()) {
            if (i >= ctxParams.size) break
            // Only apply if parameter has no type annotation
            val astParam = astParams.getOrNull(i + if (astParams.firstOrNull()?.let { (it.name as? Identifier)?.text } == "this") 1 else 0)
            if (astParam?.type != null) continue // has explicit type annotation
            val ctxParamType = getTypeOfSymbol(ctxParams[i])
            // B86.1b-2: substitute via inference mapper if available. When an outer
            // caller (B86.1b-3, not yet landed) has populated currentInferenceMapper
            // with TP→concrete mappings, replace a bare Type.TypeParam ctxParamType
            // with its mapped value. Guard: skip mapping to anyType/errorType per
            // iter17's lesson — those would propagate as silent failures downstream.
            val substitutedCtxParamType = if (ctxParamType is Type.TypeParam) {
                val mapped = currentInferenceMapper?.get(ctxParamType)
                if (mapped != null && mapped !== anyType && mapped !== errorType) mapped else ctxParamType
            } else ctxParamType
            if (substitutedCtxParamType !== anyType && substitutedCtxParamType !== errorType) {
                symbolTypes[param.id] = substitutedCtxParamType
            }
        }
    }

    /** Check if a block contains any return statement with an expression. */
    private fun hasReturnWithExpression(block: Block): Boolean {
        for (stmt in block.statements) {
            if (stmt is ReturnStatement && stmt.expression != null) return true
            // Don't recurse into nested functions — they have their own return scope
        }
        return false
    }

    /** Get the return type of a call expression by resolving the callee's call signature. */
    private fun getReturnTypeOfCallExpression(expr: CallExpression): Type {
        // 16.0: super(...) call inside a constructor returns void
        if (expr.expression is Identifier && (expr.expression as Identifier).text == "super") return voidType
        // Unwrap value-preserving wrappers before classifying the callee.
        // `(fn)()`, `fn!()`, and `(fn satisfies T)()` should resolve like `fn()`.
        var callee: Expression = expr.expression
        while (true) {
            callee = when (callee) {
                is ParenthesizedExpression -> if (callee.instantiationEnd == null) callee.expression else break
                is NonNullExpression -> callee.expression
                is SatisfiesExpression -> callee.expression
                else -> break
            }
        }
        val calleeType = when (callee) {
            is Identifier -> getTypeOfIdentifier(callee)
            is PropertyAccessExpression -> getTypeOfPropertyAccess(callee)
            else -> return anyType
        }
        if (calleeType === anyType || calleeType === errorType) return anyType
        if (calleeType !is Type.Object) return anyType
        resolveStructuredTypeMembers(calleeType)
        val sigs = calleeType.callSignatures
        if (sigs.isNullOrEmpty()) return anyType
        // 16.4: Explicit type arguments on call expression — instantiate the signature
        val typeArgs = expr.typeArguments
        if (typeArgs != null && typeArgs.isNotEmpty()) {
            // B57.3d (b): mirror substep (a)'s NewExpression wrap. Save/reset
            // deepInstantiationBailed around explicit-type-arg resolution; on bail,
            // record the call expression for deferred TS2589 emission via
            // [flushDeepBailNewExpressionEmits]. Save/restore so the bail flag does
            // NOT propagate up (which would over-emit at the enclosing annotation).
            val savedBail = deepInstantiationBailed
            val savedMappedInfo = mappedTypeCircularInfo
            deepInstantiationBailed = false
            mappedTypeCircularInfo = null
            val resolvedTypeArgs = try {
                typeArgs.map { getTypeFromTypeNode(it) }
            } catch (_: StackOverflowError) { null }
            if (deepInstantiationBailed) {
                recordDeepBailExpression(expr)
            }
            mappedTypeCircularInfo = savedMappedInfo
            deepInstantiationBailed = savedBail
            if (resolvedTypeArgs != null && resolvedTypeArgs.none { it === errorType }) {
                // Find a signature with matching type parameter count
                val matchingSig = sigs.firstOrNull { sig ->
                    val tp = sig.typeParameters
                    tp != null && tp.size == resolvedTypeArgs.size
                }
                if (matchingSig?.typeParameters != null) {
                    val mapper = createTypeMapper(matchingSig.typeParameters!!, resolvedTypeArgs)
                    val instantiated = instantiateSignature(matchingSig, mapper)
                    return instantiated.resolvedReturnType ?: anyType
                }
            }
        }
        // Single signature — simple resolution
        if (sigs.size == 1) {
            val sig = sigs[0]
            // 17.31a: single-typeParam inference for non-overloaded sigs without
            // explicit type args. Substitute T into the return type so downstream
            // (e.g. `var n: number = identity("hi")`) sees the inferred result.
            if (typeArgs.isNullOrEmpty() && !sig.typeParameters.isNullOrEmpty()) {
                val mapper = tryInferSingleTypeParamFromArgs(sig, expr.arguments, forReturnType = true)
                if (mapper != null) {
                    val rt = sig.resolvedReturnType ?: return anyType
                    return instantiateType(rt, mapper)
                }
            }
            return sig.resolvedReturnType ?: anyType
        }
        // Multiple signatures on interfaces — skip overload resolution (inherited overloads
        // with specialized string literal params need proper literal type matching)
        if (calleeType is Type.Interface) return anyType
        // Multiple signatures on functions — attempt overload resolution
        return resolveCallOverload(sigs, expr.arguments)?.resolvedReturnType ?: anyType
    }

    /**
     * Basic overload resolution: try each signature in order, return the first that matches
     * the call's argument count. If argument types are available, prefer the best type match.
     */
    private fun resolveCallOverload(signatures: List<Signature>, args: List<Expression>): Signature? {
        val argCount = args.size
        // First pass: find overloads matching by arity
        val arityMatches = signatures.filter { sig ->
            val maxParams = sig.parameters.size
            argCount >= sig.minArgumentCount && argCount <= maxParams
        }
        if (arityMatches.isEmpty()) {
            // No arity match — try with rest parameters (last param is rest)
            val restMatches = signatures.filter { sig ->
                val lastParam = sig.parameters.lastOrNull()
                val hasRest = lastParam != null && lastParam.declarations.any { d ->
                    d is Parameter && d.dotDotDotToken
                }
                argCount >= sig.minArgumentCount && (argCount <= sig.parameters.size || hasRest)
            }
            return restMatches.firstOrNull() ?: signatures.lastOrNull()
        }
        if (arityMatches.size == 1) return arityMatches[0]
        // Multiple arity matches — try type-based resolution
        for (sig in arityMatches) {
            var allMatch = true
            for ((i, arg) in args.withIndex()) {
                if (i >= sig.parameters.size) break
                val paramType = getTypeOfSymbol(sig.parameters[i])
                if (paramType === anyType || paramType === errorType) continue
                // Prefer the non-widened literal type so a string/number-literal arg can
                // select a specialized literal-param overload (e.g. createElement('canvas')
                // → the `(tagName: 'canvas'): Derived1` overload, not the `(tagName: string)`
                // fallback). Falls through to the widened type for non-literal args.
                val argType = literalTypeOfExpression(arg) ?: getTypeOfExpression(arg)
                if (argType === anyType || argType === errorType) continue
                if (!isSimpleTypeRelatedTo(argType, paramType) &&
                    !checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                    allMatch = false
                    break
                }
            }
            if (allMatch) return sig
        }
        // No type match — return first arity match
        return arityMatches[0]
    }

    /**
     * 17.14b: Infer type args from a `new` expression's argument list.
     * For each class-level type parameter, find the FIRST constructor parameter
     * whose declared type annotation is exactly that TypeParam (TypeReference
     * named with the same identifier, no own typeArgs), and use the widened
     * type of the corresponding call argument as the inferred type.
     *
     * Returns null when:
     *   - The class has no Constructor declaration (default ctor).
     *   - Any TypeParam isn't covered by a direct-TypeReference param.
     *   - Any inferred arg type resolves to errorType.
     *
     * Conservative on purpose — doesn't infer through nested generic types
     * (e.g. `Array<T>` would not yield T from `[1, 2, 3]`).
     */
    private fun inferTypeArgsFromConstructorCall(
        classType: Type.Interface,
        typeParams: List<Type.TypeParam>,
        args: List<Expression>,
    ): List<Type>? {
        val classDecl = classType.symbol?.valueDeclaration as? ClassDeclaration ?: return null
        val ctor = classDecl.members.firstOrNull { it is Constructor } as? Constructor ?: return null
        val ctorParams = ctor.parameters
        val result = mutableListOf<Type>()
        for (tp in typeParams) {
            val tpName = tp.symbol?.name ?: return null
            var inferredType: Type? = null
            for (i in ctorParams.indices) {
                if (i >= args.size) break
                val paramTypeNode = ctorParams[i].type ?: continue
                if (paramTypeNode is TypeReference) {
                    val tn = paramTypeNode.typeName
                    if (tn is Identifier && tn.text == tpName &&
                        paramTypeNode.typeArguments.isNullOrEmpty()) {
                        inferredType = widenType(getTypeOfExpression(args[i]))
                        break
                    }
                }
            }
            if (inferredType == null || inferredType === errorType) return null
            result.add(inferredType)
        }
        return result
    }

    /**
     * 17.31a / 17.31b: Single-typeParam inference for non-overloaded call signatures.
     *
     * Conservative gate: only fires when (a) sig has exactly one type parameter,
     * (b) every parameter type is either a bare reference to that TypeParam OR a
     * fully concrete type (no nested T in Reference/Union/Intersection — function-
     * type params containing T are tolerated since they only act as inference
     * sources for context-sensitive arrows).
     *
     * 17.31b extension: gathers candidates from EVERY bare-T positional param,
     * not just the first. When candidates have incompatible base types (e.g.
     * `g("", 3)` with literal candidates `""` and `3`), and the sig has a
     * function-type parameter mentioning T (signaling TypeScript's literal-
     * preserving two-pass inference is appropriate), this helper emits TS2345
     * directly at the failing arg position using LITERAL-form display
     * (`'3' is not assignable to '""'`) and returns null so the standard arg-
     * check loop doesn't double-emit. Without a function-type-T param, the
     * widened first-candidate substitution path is used (same as 17.31a),
     * letting the standard loop emit the widened display.
     *
     * For non-conflicting multi-arg cases (same base type), substitutes T with
     * the widened first-candidate type — covers `g("hello", "world", x => x)`
     * where best-common-type is `string` and both args pass.
     *
     * Matches `f<T>(x: T): T` called with `f("hi")` → T=string (the "widened"
     * form, since [getTypeOfExpression] returns wrapper-typed values for string
     * and number literals). Doesn't infer through `Array<T>` / object members /
     * unions — those are explicitly out of scope (handled later by 17.31d).
     *
     * [source] and [fileName] are optional — when null (return-type inference
     * call site), the literal-aware emission is skipped and the helper just
     * returns null on conflict-with-preserveLiterals.
     */
    private fun tryInferSingleTypeParamFromArgs(
        sig: Signature,
        args: List<Expression>,
        source: String? = null,
        fileName: String? = null,
        forReturnType: Boolean = false,
    ): TypeMapper? {
        val tps = sig.typeParameters ?: return null
        if (tps.isEmpty()) return null
        val params = sig.parameters
        if (params.isEmpty() || args.isEmpty()) return null

        // 17.31d/e gate: every parameter type must be either (a) a bare
        // reference to one of our type params, (b) the rest-of-`tp_i[]` shape
        // (last param only), (d) [17.31e] non-rest `Array<tp_i>`, or (c) fully
        // concrete — i.e. mentions NONE of our type params anywhere. Bails on
        // other nested-TP shapes (`(x:T)=>U`, `Map<T,U>`, unions/intersections
        // containing TPs) — those need richer inference.
        val tpsSet = tps.toSet()
        for ((idx, p) in params.withIndex()) {
            val pt = try { getTypeOfSymbol(p) } catch (_: StackOverflowError) { return null }
            if (pt === errorType) return null
            val isRest = (p.valueDeclaration as? Parameter)?.dotDotDotToken == true
            // (a) bare-some-tp_i
            if (pt is Type.TypeParam && pt in tpsSet) continue
            // (b) rest-of-tp_i[] (last param only, contributes one candidate per
            // trailing arg via 17.31c logic)
            if (isRest && idx == params.size - 1 &&
                tps.any { isArrayOfTypeParam(pt, it) }) continue
            // (d) 17.31e: non-rest `Array<tp_i>`
            if (!isRest && tps.any { isArrayOfTypeParam(pt, it) }) continue
            // (e) 17.38: anonymous Type.Object with all members typed as some tp_i
            if (!isRest && isAnonymousObjectWithTypeParamMembers(pt, tpsSet)) continue
            // (f) B83.1: bare `(x: tp_i) => <concrete>` function-typed param.
            // Anonymous Type.Object with exactly 1 callSig, single bare-TP-typed
            // Identifier param, return type either voidType OR fully concrete
            // (mentions NO TP). Narrow gate — multi-param / TP-in-return / multiple
            // callSigs / ctorSigs all bail.
            if (!isRest && fnTypedParamBareTpMatch(pt, tpsSet) != null) continue
            // (g) B83.3: multi-param `(x: tp_i, y: tp_j, ...) => <concrete>`
            // callback. Each slot is either bare-TP-from-tps or fully concrete;
            // at least one slot must be bare TP. Return-type TP-mentions allowed
            // in the sig-acceptance gate (per-TP gathering applies the narrower
            // currentTp gate).
            if (!isRest && fnTypedParamMultiBareTpMatch(pt, tpsSet) != null) continue
            // (h) B83.4i: callback whose params are ALL concrete (mention no TP) and
            // whose return type is exactly a bare TP in tps — e.g. the post-receiver-
            // substitution `(value: number, index: number, array: number[]) => U`
            // shape of `Array.map<U>`. Candidate gathering for the return-TP happens in
            // pass-2's B83.4i branch (re-types the un-annotated lambda body). Accept the
            // sig here so we don't bail at gate (c).
            if (!isRest && fnTypedParamConcreteParamsBareReturnTp(pt, tpsSet) != null) continue
            // (c) fully concrete — must not mention ANY of our TPs
            if (tps.any { typeMentionsTypeParam(pt, it) }) return null
        }

        // 17.31d: per-typeParam candidate gathering. Each TP gets its own
        // candidate list (gathered from positions where param IS exactly that TP
        // or rest-of-that-TP[]). Conflict detection runs independently per TP.
        // Build a multi-mapper covering every TP that can be inferred from at
        // least one arg position; return null if any TP has no candidates
        // (uninferable) so the bare-TypeParam continue path keeps firing.
        data class Candidate(val argIdx: Int, val widenedType: Type, val literalType: Type?, val fromObjLit: Boolean = false)
        val mapperPairs = mutableListOf<Pair<Type.TypeParam, Type>>()

        // B83.4a (two-pass anchor/callback split): pass-1 gathers candidates from
        // "easy" anchor positions (bare-T, rest-T[], Array<T>, anonymous-object-of-T
        // members); pass-2 gathers from callback positions (B83.1 gate (f)
        // function-typed param shape). Currently both passes contribute to the same
        // `candidates` list per-TP (preserving net-zero behavior with existing single-
        // pass logic) and run inline per-TP. Restructure prepares for B83.4b+ where
        // pass-2 will consult pass-1's partial mapper to back-propagate inferred
        // anchor TPs into un-annotated lambda param-type inference.
        for (tp in tps) {
            val candidates = mutableListOf<Candidate>()
            // Pass 1: anchor positions (non-callback).
            for (i in params.indices) {
                if (i >= args.size) break
                val pt = try { getTypeOfSymbol(params[i]) } catch (_: StackOverflowError) { return null }
                val isRest = (params[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                val isBareT = pt === tp
                val isRestT = isRest && i == params.size - 1 && isArrayOfTypeParam(pt, tp)
                // 17.31e: non-rest `Array<tp>` — extract element type from same-target
                // Array Reference call arg (no per-rest-arg fan-out).
                val isArrayT = !isRest && isArrayOfTypeParam(pt, tp)
                // 17.38: anonymous Object literal with all-TypeParam members — gather
                // candidates from the arg ObjectLiteralExpression's same-named property
                // values for members typed as the current `tp`.
                val isObjLitOfT = !isRest && !isBareT && !isRestT && !isArrayT &&
                    isAnonymousObjectWithTypeParamMembers(pt, tpsSet)
                val isFnTypedOfT = false  // B83.4a: pass-1 skips fn-typed (handled in pass-2)
                if (!isBareT && !isRestT && !isArrayT && !isObjLitOfT && !isFnTypedOfT) continue
                fun isNamedLikeAtom(t: Type): Boolean =
                    t is Type.Interface || t is Type.Reference || t is Type.Intrinsic ||
                        t.flags.hasAny(
                            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
                            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
                            TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
                        )
                val argRange = if (isRestT) i until args.size else i..i
                for (ai in argRange) {
                    if (ai >= args.size) break
                    val arg = args[ai]
                    if (arg is SpreadElement) continue
                    // 17.38: object-literal-of-T inference — walk arg's properties matching
                    // pt's tp-typed members; LUB-as-Union over collected widened types.
                    // Branches BEFORE the standard rawArgType bail because the arg as a whole
                    // is a Type.Object, but its property values may include `undefined` /
                    // string-literal / etc. that the standard bail would reject.
                    if (isObjLitOfT) {
                        if (arg !is ObjectLiteralExpression) continue
                        val ptObj = pt as? Type.Object ?: continue
                        val ptMembers = ptObj.members ?: continue
                        val collectedTypes = mutableListOf<Type>()
                        for ((memberName, memberSym) in ptMembers) {
                            val mt = try { getTypeOfSymbol(memberSym) } catch (_: StackOverflowError) { return null }
                            if (mt !== tp) continue
                            val propAssign = arg.properties.firstOrNull { p ->
                                p is PropertyAssignment && getPropertyKeyName(p.name) == memberName
                            } as? PropertyAssignment
                            if (propAssign == null) continue
                            val rawValue = try { getTypeOfExpression(propAssign.initializer) }
                                catch (_: StackOverflowError) { return null }
                            if (rawValue === anyType || rawValue === errorType) return null
                            collectedTypes.add(widenType(rawValue))
                        }
                        if (collectedTypes.isEmpty()) continue
                        val argType = if (collectedTypes.size == 1) collectedTypes[0]
                                      else getUnionType(collectedTypes)
                        if (argType === anyType || argType === errorType) return null
                        val isNamedLike = isNamedLikeAtom(argType) ||
                            (argType is Type.Union && argType.types.all { isNamedLikeAtom(it) })
                        if (!isNamedLike) return null
                        candidates.add(Candidate(ai, argType, null, fromObjLit = true))
                        continue
                    }
                    // B83.1 gate (f) candidate extraction: arg's callback supplies tp via
                    // its single Identifier-named parameter's type annotation. Bail when
                    // arg is not an ArrowFunction/FunctionExpression, when the callback's
                    // arity or shape doesn't match, when the lambda's param lacks an
                    // annotation, or when the annotated type fails to resolve cleanly
                    // (anyType/errorType/null/undefined/void). Skip the standard rawArgType
                    // path because lambda exprs typically have anonymous Type.Object types
                    // that the named-like gate below would reject.
                    if (isFnTypedOfT) {
                        val argParams = when (arg) {
                            is ArrowFunction -> arg.parameters
                            is FunctionExpression -> arg.parameters
                            else -> null
                        } ?: continue
                        if (argParams.size != 1) continue
                        val lp = argParams[0]
                        if (lp.dotDotDotToken) continue
                        if (lp.name !is Identifier) continue
                        val lpTypeNode = lp.type ?: continue
                        val lpType = try { getTypeFromTypeNode(lpTypeNode) } catch (_: StackOverflowError) { return null }
                        if (lpType === anyType || lpType === errorType) return null
                        if (lpType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return null
                        val widened = widenType(lpType)
                        if (!isNamedLikeAtom(widened) &&
                            !(widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) return null
                        candidates.add(Candidate(ai, widened, null))
                        continue
                    }
                    // 17.37: empty array literal `[]` arg for `Array<tp>` param infers tp = `never`.
                    // `getTypeOfArrayLiteral` returns anyType for empty arrays (can't infer element
                    // type), but TypeScript's spec-mandated behavior here is to fall back to never
                    // for inference — the array contains no elements that could constrain the
                    // element type. Skip the standard rawArgType anyType bail in this narrow case.
                    if (isArrayT && arg is ArrayLiteralExpression && arg.elements.isEmpty()) {
                        candidates.add(Candidate(ai, neverType, null))
                        continue
                    }
                    val rawArgType = try { getTypeOfExpression(arg) } catch (_: StackOverflowError) { return null }
                    if (rawArgType === anyType || rawArgType === errorType) return null
                    if (rawArgType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return null
                    // 17.31e: for `Array<tp>` param, the inference candidate is the
                    // arg's element type (extracted from same-target `Array<X>` ref).
                    // Bail when arg isn't a same-target Array Reference (e.g. plain
                    // `Type.Object` or `Type.Reference Set<X>`) — too many edge cases
                    // for this conservative substep.
                    val argType = if (isArrayT) {
                        if (rawArgType !is Type.Reference) return null
                        if (rawArgType.target?.symbol?.name != "Array") return null
                        val refArgs = rawArgType.resolvedTypeArguments ?: return null
                        if (refArgs.size != 1) return null
                        val element = refArgs[0]
                        // 17.31f: widen Union constituents (`widenType` falls through on Union),
                        // so `Array<undefined | "def">` infers T = `string | undefined` rather
                        // than bailing at the named-like gate below. Single-type elements still
                        // go through the existing widenType path.
                        if (element is Type.Union) getUnionType(element.types.map { widenType(it) })
                        else widenType(element)
                    } else rawArgType
                    if (argType === anyType || argType === errorType) return null
                    if (argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return null
                    // 17.31a refinement: only fire when the inferred type is a "named-like"
                    // type (Interface, Reference, Intrinsic / literal) AND, when T has a
                    // constraint, the inferred type satisfies it. Anonymous Type.Object
                    // results (object literals like `{x: null}`) go through the bare-T
                    // path so existing per-property constraint elaborations (16.4ds /
                    // 16.4dt) keep firing — substitution would erase paramType's TypeParam
                    // identity and skip those branches.
                    val isNamedLike = isNamedLikeAtom(argType) ||
                        // 17.31f: Union-of-named-likes from the isArrayT path. Anonymous-Object
                        // members in heterogeneous-array elements (e.g. `[{a:1}, "def"]` →
                        // `Array<{a:1} | "def">`) are still rejected because `{a:1}` widens to
                        // an anonymous Type.Object that fails this check.
                        (isArrayT && argType is Type.Union && argType.types.all { isNamedLikeAtom(it) })
                    // 17.41: at the return-type call site, allow anonymous Type.Object
                    // arg types (substitute T into the return type for downstream display).
                    // Arg-vs-param call site keeps the bail (forReturnType=false default) so
                    // 16.4ds / 16.4dt per-property elaborations keep firing on object-literal
                    // args. Net-zero on the suite alone — pairs with intersection elaboration
                    // (follow-up substep) to flip `errorMessagesIntersectionTypes01/02_ts`.
                    if (!isNamedLike && !forReturnType) return null
                    // 17.31e: for Array<tp> path the literal type is null (we don't have
                    // a single literal to attach to the array's element type).
                    val literal = if (isArrayT) null else literalTypeOfExpression(arg)
                    candidates.add(Candidate(ai, argType, literal))
                }
            }
            // Pass 2 (B83.4a): callback (B83.1 gate (f)) positions. Walks the same
            // params/args but only collects candidates from function-typed param
            // shapes (anonymous Type.Object with 1 callSig whose single Identifier
            // param is exactly `tp`). Currently bails at `lp.type ?: continue` for
            // un-annotated lambdas — B83.4b/c/d will replace that bail with
            // contextual back-propagation from the partial mapper assembled by
            // pass-1 across other TPs. Net-zero in isolation: produces the same
            // candidate set as the pre-restructure single-pass loop for any sig
            // shape that reaches gate (f).
            fun isNamedLikeAtom(t: Type): Boolean =
                t is Type.Interface || t is Type.Reference || t is Type.Intrinsic ||
                    t.flags.hasAny(
                        TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
                        TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
                        TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
                    )
            for (i in params.indices) {
                if (i >= args.size) break
                val pt = try { getTypeOfSymbol(params[i]) } catch (_: StackOverflowError) { return null }
                val isRest = (params[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                if (isRest) continue
                if (pt === tp) continue
                if (isArrayOfTypeParam(pt, tp)) continue
                if (isAnonymousObjectWithTypeParamMembers(pt, tpsSet)) continue
                val isFnTypedOfT = fnTypedParamBareTpMatch(pt, tpsSet, currentTp = tp) === tp
                // B83.3: multi-param callback fallback. Returns slot list with
                // the current `tp` appearing in at least one slot; null slots
                // are concrete params we ignore for THIS tp's candidate gathering.
                val multiSlots = if (!isFnTypedOfT) {
                    fnTypedParamMultiBareTpMatch(pt, tpsSet, currentTp = tp)
                        ?.takeIf { slots -> slots.any { it === tp } }
                } else null
                // B83.4d-quick (NEW 2026-05-27): callback-return-tp inference for the
                // shape `f<S,T>(arg1: S, cb: (x: S) => T): T` (S already inferred via
                // pass-1, T comes from the un-annotated lambda's concise body re-typed
                // under `currentLocalTypes[lp.name] = mapper(S)`). Triggered ONLY when
                // (a) the existing isFnTypedOfT / multiSlots paths don't apply (callback
                // param isn't current `tp`), (b) the callback param IS some OTHER tp
                // (otherTp ∈ tps, otherTp != tp), (c) callback return type MENTIONS the
                // current tp, (d) otherTp is already in mapperPairs (inferred earlier),
                // (e) the lambda is concise-body (single expression — NOT Block), (f)
                // lambda has exactly 1 Identifier param, no annotation. Narrow gate;
                // intentionally skips Block bodies and multi-param shapes (B83.4 follow-up).
                if (!isFnTypedOfT && multiSlots == null) {
                    val fnObj = pt as? Type.Object
                    val callbackSig = fnObj?.callSignatures?.singleOrNull()
                    val callbackParam = callbackSig?.parameters?.singleOrNull()
                    val callbackParamType = callbackParam?.let {
                        try { getTypeOfSymbol(it) } catch (_: StackOverflowError) { null }
                    }
                    val callbackReturn = callbackSig?.resolvedReturnType
                    val otherTp = (callbackParamType as? Type.TypeParam)
                        ?.takeIf { it in tpsSet && it !== tp }
                    val otherTpMapped = otherTp?.let { o -> mapperPairs.firstOrNull { it.first === o }?.second }
                    // B83.4i (NEW 2026-05-28): callback-return-TP inference when the
                    // callback params are FULLY CONCRETE (mention NO TP) and the
                    // callback RETURN type is exactly the current `tp`. This is the
                    // `Array.map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[]`
                    // shape after the receiver's T is already substituted to a concrete
                    // type (so the callback param `value` is `number`, not a TP). The
                    // existing B83.4b/d-quick branches require a callback PARAM that is a
                    // TP to anchor from; here there is none — the only TP is the return
                    // `U`. Re-type the un-annotated lambda's (concise OR single-return)
                    // body under `currentLocalTypes[paramName] = <concrete sig param type>`
                    // for each lambda param, and use the widened body type as the
                    // candidate for `tp`. Gate NARROWLY: anonymous fn-shaped Type.Object,
                    // single callSig, callback return type IS exactly `tp` (not a nested
                    // mention), every callback param type concrete (no TP mention), lambda
                    // param count matches the callback's, all params un-annotated
                    // Identifier names, no rest params, `tp` not yet anchored.
                    if (fnObj != null && callbackSig != null && callbackReturn === tp &&
                        otherTp == null && mapperPairs.none { it.first === tp } &&
                        callbackSig.parameters.isNotEmpty() &&
                        fnObj !is Type.Interface && fnObj !is Type.Reference &&
                        fnObj.symbol == null &&
                        fnObj.constructSignatures.isNullOrEmpty() &&
                        fnObj.members.isNullOrEmpty() &&
                        fnObj.stringIndexInfo == null && fnObj.numberIndexInfo == null) {
                        // Resolve each callback param type; all must be concrete (no TP mention).
                        val sigParamTypes = mutableListOf<Type>()
                        var concreteOk = true
                        for (sp in callbackSig.parameters) {
                            if ((sp.valueDeclaration as? Parameter)?.dotDotDotToken == true) { concreteOk = false; break }
                            val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { concreteOk = false; break }
                            if (spt === anyType || spt === errorType) { concreteOk = false; break }
                            if (tps.any { typeMentionsTypeParam(spt, it) }) { concreteOk = false; break }
                            sigParamTypes.add(spt)
                        }
                        if (concreteOk) {
                            val arg = args[i]
                            val (argParamsLocal, argBody) = when (arg) {
                                is ArrowFunction -> arg.parameters to arg.body
                                is FunctionExpression -> arg.parameters to arg.body
                                else -> null to null
                            }
                            // Lambda may declare FEWER params than the callback shape
                            // (e.g. `(value, index, array) => ...` vs `s => ...`) — bind
                            // only the lambda's declared params to the leading sig params.
                            if (argParamsLocal != null && argBody != null &&
                                argParamsLocal.isNotEmpty() &&
                                argParamsLocal.size <= sigParamTypes.size) {
                                val lpNames = mutableListOf<String>()
                                var lpOk = true
                                for (lp in argParamsLocal) {
                                    val lpName = (lp.name as? Identifier)?.text
                                    if (lp.dotDotDotToken || lpName == null || lp.type != null) {
                                        lpOk = false; break
                                    }
                                    lpNames.add(lpName)
                                }
                                if (lpOk) {
                                    val effectiveBodyExpr: Expression? = when (argBody) {
                                        is Block -> {
                                            var retStmt: ReturnStatement? = null
                                            var multi = false
                                            for (s in argBody.statements) {
                                                if (s is ReturnStatement) {
                                                    if (retStmt != null) { multi = true; break }
                                                    retStmt = s
                                                }
                                            }
                                            if (multi) null else retStmt?.expression
                                        }
                                        is Expression -> argBody
                                        else -> null
                                    }
                                    if (effectiveBodyExpr != null) {
                                        val savedLocalTypes = currentLocalTypes
                                        currentLocalTypes = currentLocalTypes.toMutableMap()
                                        for ((idx, name) in lpNames.withIndex()) {
                                            currentLocalTypes[name] = sigParamTypes[idx]
                                        }
                                        val bodyType = try {
                                            getTypeOfExpression(effectiveBodyExpr)
                                        } catch (_: StackOverflowError) {
                                            null
                                        } finally {
                                            currentLocalTypes = savedLocalTypes
                                        }
                                        if (bodyType != null && bodyType !== anyType && bodyType !== errorType &&
                                            !bodyType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) {
                                            val widened = widenType(bodyType)
                                            if (isNamedLikeAtom(widened) ||
                                                (widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) {
                                                candidates.add(Candidate(i, widened, null))
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // B83.4b (NEW 2026-05-27): multi-param callback parallel of B83.4d-quick.
                    // Shape: `f<S,T,U>(arg1: S, arg2: T, cb: (x: S, y: T) => U): U` — S and T
                    // already inferred via pass-1's anchor positions, U comes from the un-
                    // annotated lambda's body re-typed under `currentLocalTypes[x]=mapper(S),
                    // currentLocalTypes[y]=mapper(T)`. Gate: (a) multi-param callback (2+ params),
                    // (b) ALL callback params are bare TPs in tps and all DIFFERENT from current
                    // `tp` (pure callback-return-tp shape — no current-tp slot to gather from),
                    // (c) ALL those TPs already in mapperPairs, (d) callback return MENTIONS the
                    // current tp, (e) lambda has matching param count, all un-annotated Identifier
                    // names. Narrow: rejects mixed shapes (some slots = current tp, some other).
                    if (fnObj != null && callbackSig != null && callbackReturn != null &&
                        callbackSig.parameters.size >= 2 &&
                        typeMentionsTypeParam(callbackReturn, tp) &&
                        fnObj !is Type.Interface && fnObj !is Type.Reference &&
                        fnObj.symbol == null &&
                        fnObj.constructSignatures.isNullOrEmpty() &&
                        fnObj.members.isNullOrEmpty() &&
                        fnObj.stringIndexInfo == null && fnObj.numberIndexInfo == null) {
                        // Collect per-slot resolved (otherTp, mappedType) pairs; bail if any
                        // slot isn't a bare TP in tps, equals current tp, or isn't in mapperPairs.
                        val slotMapped = mutableListOf<Type>()
                        val slotTps = mutableListOf<Type.TypeParam>()
                        var slotsOk = true
                        for (sp in callbackSig.parameters) {
                            if ((sp.valueDeclaration as? Parameter)?.dotDotDotToken == true) { slotsOk = false; break }
                            val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { slotsOk = false; break }
                            val slotTp = spt as? Type.TypeParam
                            if (slotTp == null || slotTp !in tpsSet || slotTp === tp) { slotsOk = false; break }
                            val mapped = mapperPairs.firstOrNull { it.first === slotTp }?.second
                            if (mapped == null) { slotsOk = false; break }
                            slotMapped.add(mapped)
                            slotTps.add(slotTp)
                        }
                        if (slotsOk) {
                            val arg = args[i]
                            val (argParamsLocal, argBody) = when (arg) {
                                is ArrowFunction -> arg.parameters to arg.body
                                is FunctionExpression -> arg.parameters to arg.body
                                else -> null to null
                            }
                            if (argParamsLocal != null && argBody != null &&
                                argParamsLocal.size == callbackSig.parameters.size) {
                                // Validate ALL lambda params: Identifier-named, no dotDotDot, no annotation.
                                val lpNames = mutableListOf<String>()
                                var lpOk = true
                                for (lp in argParamsLocal) {
                                    val lpName = (lp.name as? Identifier)?.text
                                    if (lp.dotDotDotToken || lpName == null || lp.type != null) {
                                        lpOk = false; break
                                    }
                                    lpNames.add(lpName)
                                }
                                if (lpOk) {
                                    val effectiveBodyExpr: Expression? = when (argBody) {
                                        is Block -> {
                                            var retStmt: ReturnStatement? = null
                                            var multi = false
                                            for (s in argBody.statements) {
                                                if (s is ReturnStatement) {
                                                    if (retStmt != null) { multi = true; break }
                                                    retStmt = s
                                                }
                                            }
                                            if (multi) null else retStmt?.expression
                                        }
                                        is Expression -> argBody
                                        else -> null
                                    }
                                    if (effectiveBodyExpr != null) {
                                        val savedLocalTypes = currentLocalTypes
                                        currentLocalTypes = currentLocalTypes.toMutableMap()
                                        for ((idx, name) in lpNames.withIndex()) {
                                            currentLocalTypes[name] = slotMapped[idx]
                                        }
                                        // B86.1b-3 (multi-param): publish ALL slot TP→mapped bindings to
                                        // currentInferenceMapper so any nested ArrowFunction body re-typing
                                        // path (e.g. applyContextualParameterTypes for a nested callback)
                                        // can substitute outer TPs for their concrete mappings. Mirror of
                                        // the single-param branch below.
                                        val savedMapper = currentInferenceMapper
                                        val newMapper = (savedMapper ?: emptyMap()).toMutableMap()
                                        for ((idx, slotTpVal) in slotTps.withIndex()) {
                                            val slotType = slotMapped[idx]
                                            if (slotType !== anyType && slotType !== errorType) {
                                                newMapper[slotTpVal] = slotType
                                            }
                                        }
                                        currentInferenceMapper = newMapper
                                        val bodyType = try {
                                            getTypeOfExpression(effectiveBodyExpr)
                                        } catch (_: StackOverflowError) {
                                            null
                                        } finally {
                                            currentLocalTypes = savedLocalTypes
                                            currentInferenceMapper = savedMapper
                                        }
                                        if (bodyType != null && bodyType !== anyType && bodyType !== errorType &&
                                            !bodyType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) {
                                            val widened = widenType(bodyType)
                                            if (isNamedLikeAtom(widened) ||
                                                (widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) {
                                                candidates.add(Candidate(i, widened, null))
                                            } else if (widened is Type.TypeParam && widened === tp &&
                                                mapperPairs.none { it.first === tp }) {
                                                // B83.4c (NEW 2026-05-27): identity-anchor for body-bare-tp shape.
                                                // When un-annotated lambda body's resolved type IS exactly the current
                                                // tp (no anchor yet in mapperPairs), add `tp` as a self-anchor candidate.
                                                // Handles e.g. body `[x, x]` typed as `[tp, tp]` where the tuple wrapper
                                                // would already pass the named-like check; this catches the bare-tp leaf case
                                                // that the named-like gate silently drops. Gate excludes TPs already
                                                // anchored elsewhere (would create redundant identity candidate).
                                                candidates.add(Candidate(i, tp, null))
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (fnObj != null && otherTp != null && otherTpMapped != null &&
                        callbackReturn != null && typeMentionsTypeParam(callbackReturn, tp) &&
                        fnObj !is Type.Interface && fnObj !is Type.Reference &&
                        fnObj.symbol == null &&
                        fnObj.constructSignatures.isNullOrEmpty() &&
                        fnObj.members.isNullOrEmpty() &&
                        fnObj.stringIndexInfo == null && fnObj.numberIndexInfo == null) {
                        val arg = args[i]
                        val (argParamsLocal, argBody) = when (arg) {
                            is ArrowFunction -> arg.parameters to arg.body
                            is FunctionExpression -> arg.parameters to arg.body
                            else -> null to null
                        }
                        if (argParamsLocal != null && argParamsLocal.size == 1 && argBody != null) {
                            val lp = argParamsLocal[0]
                            val lpName = (lp.name as? Identifier)?.text
                            if (!lp.dotDotDotToken && lpName != null && lp.type == null) {
                                // B83.4d-quick-Block (NEW): extend the concise-body inference
                                // path to Block bodies with EXACTLY one top-level
                                // ReturnStatement whose expression we can type-re-resolve
                                // under the pushed currentLocalTypes. Multi-return / no-return
                                // bodies still bail. Mirrors the inferReturnTypeFromBody
                                // single-return-extraction pattern (single-return is the
                                // tractable shape).
                                val effectiveBodyExpr: Expression? = when (argBody) {
                                    is Block -> {
                                        var retStmt: ReturnStatement? = null
                                        var multi = false
                                        for (s in argBody.statements) {
                                            if (s is ReturnStatement) {
                                                if (retStmt != null) { multi = true; break }
                                                retStmt = s
                                            }
                                        }
                                        if (multi) null else retStmt?.expression
                                    }
                                    is Expression -> argBody
                                    else -> null
                                }
                                if (effectiveBodyExpr != null) {
                                    val savedLocalTypes = currentLocalTypes
                                    currentLocalTypes = currentLocalTypes.toMutableMap()
                                    currentLocalTypes[lpName] = otherTpMapped
                                    // B86.1b-3 (single-param): publish the same TP→mapped binding to
                                    // currentInferenceMapper so any nested ArrowFunction body re-typing
                                    // path (e.g. applyContextualParameterTypes for a nested callback)
                                    // can substitute the outer TP for its concrete mapping. Narrow gate:
                                    // single-param branch only this iteration; multi-param branch
                                    // (~line 54515) deferred to a follow-up iteration.
                                    val savedMapper = currentInferenceMapper
                                    val newMapper = (savedMapper ?: emptyMap()).toMutableMap()
                                    newMapper[otherTp] = otherTpMapped
                                    currentInferenceMapper = newMapper
                                    val bodyType = try {
                                        getTypeOfExpression(effectiveBodyExpr)
                                    } catch (_: StackOverflowError) {
                                        null
                                    } finally {
                                        currentLocalTypes = savedLocalTypes
                                        currentInferenceMapper = savedMapper
                                    }
                                    if (bodyType != null && bodyType !== anyType && bodyType !== errorType &&
                                        !bodyType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) {
                                        val widened = widenType(bodyType)
                                        if (isNamedLikeAtom(widened) ||
                                            (widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) {
                                            candidates.add(Candidate(i, widened, null))
                                        } else if (widened is Type.TypeParam && widened === tp &&
                                            mapperPairs.none { it.first === tp }) {
                                            // B83.4c (NEW 2026-05-27): identity-anchor — mirror of the
                                            // multi-param branch (see ~line 54393). Catches body-bare-tp
                                            // shape that the named-like gate would silently drop.
                                            candidates.add(Candidate(i, tp, null))
                                        }
                                    }
                                }
                            }
                        }
                    }
                    continue
                }
                val arg = args[i]
                if (arg is SpreadElement) continue
                val argParams = when (arg) {
                    is ArrowFunction -> arg.parameters
                    is FunctionExpression -> arg.parameters
                    else -> null
                } ?: continue
                if (isFnTypedOfT) {
                    // B83.1 single-param case.
                    if (argParams.size != 1) continue
                    val lp = argParams[0]
                    if (lp.dotDotDotToken) continue
                    if (lp.name !is Identifier) continue
                    val lpTypeNode = lp.type ?: continue
                    val lpType = try { getTypeFromTypeNode(lpTypeNode) } catch (_: StackOverflowError) { return null }
                    if (lpType === anyType || lpType === errorType) return null
                    if (lpType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return null
                    val widened = widenType(lpType)
                    if (!isNamedLikeAtom(widened) &&
                        !(widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) return null
                    candidates.add(Candidate(i, widened, null))
                } else {
                    // B83.3 multi-param case. Match lambda's parameter count to
                    // the callback shape's parameter count exactly. For each slot
                    // matching `tp`, gather a candidate from the lambda's
                    // corresponding annotated param. Bail (continue) on
                    // un-annotated lambda — B83.4 territory.
                    val slots = multiSlots!!
                    if (argParams.size != slots.size) continue
                    var bailed = false
                    val newCandidates = mutableListOf<Candidate>()
                    for ((slotIdx, slotTp) in slots.withIndex()) {
                        if (slotTp !== tp) continue
                        val lp = argParams[slotIdx]
                        if (lp.dotDotDotToken) { bailed = true; break }
                        if (lp.name !is Identifier) { bailed = true; break }
                        val lpTypeNode = lp.type
                        if (lpTypeNode == null) { bailed = true; break }
                        val lpType = try { getTypeFromTypeNode(lpTypeNode) }
                            catch (_: StackOverflowError) { return null }
                        if (lpType === anyType || lpType === errorType) return null
                        if (lpType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return null
                        val widened = widenType(lpType)
                        if (!isNamedLikeAtom(widened) &&
                            !(widened is Type.Union && widened.types.all { isNamedLikeAtom(it) })) return null
                        newCandidates.add(Candidate(i, widened, null))
                    }
                    if (bailed) continue
                    candidates.addAll(newCandidates)
                }
            }
            if (candidates.isEmpty()) return null

            // 17.37: an empty-array literal's `never` candidate is a "wildcard" —
            // it conveys no element-type information, so ignore it in inference
            // when at least one concrete candidate is available. Without this,
            // `f<T>(arr: T[], elemnt: T)` called with `f([], 3)` would infer
            // T=never (anchor on `[]`), then check arg[1]=`3` against never and
            // fire spurious TS2345 — but TypeScript correctly infers T=number
            // from the second arg. Only when EVERY candidate is never (e.g.
            // `foo([])` single-arg) does the never substitution apply.
            val nonNeverCands = candidates.filter { it.widenedType !== neverType }
                .ifEmpty { candidates }
            // B52.3: prioritize non-objLit candidates over object-literal-of-T candidates.
            // An object literal's per-property contributions form a UNION (e.g. `{x:3, y:""}`
            // → `number | string`); a bare-T arg with concrete value (e.g. `m: T = 4`) is a
            // STRONGER anchor. When both shapes contribute, the anchor wins so the union
            // doesn't subsume the concrete inference, letting per-property TS2322 fire at
            // the violating property. When only objLit candidates exist (e.g. widenToAny1
            // `foo1({x: undefined, y: "def"})`), order is unchanged — the union still wins.
            val effectiveCandidates = nonNeverCands.sortedBy { if (it.fromObjLit) 1 else 0 }

            val first = effectiveCandidates[0]
            val firstWidened = first.widenedType

            // Constraint check: inferred type (widened first candidate) must satisfy
            // tp's constraint. Protects 16.4i (constrained TypeParam emits TS2345 with
            // constraint as effective param type) from being bypassed.
            val constraint = tp.constraint
            if (constraint != null) {
                val ok = try {
                    checkTypeRelatedTo(firstWidened, constraint, assignableRelation)
                } catch (_: StackOverflowError) { return null }
                if (!ok) return null
            }

            // 17.31b multi-arg conflict detection: scan subsequent candidates, find
            // the first that is mutually non-assignable with the widened first
            // candidate. Same-base-different-literal cases (e.g. ["hello", "world"])
            // resolve via widening — both become `string` and the assignability
            // check between widened forms passes trivially. Cross-base cases
            // (number vs string, Giraffe vs Elephant) trigger conflict handling.
            var conflictAt = -1
            for (i in 1 until effectiveCandidates.size) {
                val ci = effectiveCandidates[i]
                val ok = try {
                    checkTypeRelatedTo(ci.widenedType, firstWidened, assignableRelation) ||
                        checkTypeRelatedTo(firstWidened, ci.widenedType, assignableRelation)
                } catch (_: StackOverflowError) { false }
                if (!ok) {
                    conflictAt = i
                    break
                }
            }

            if (conflictAt >= 0 && source != null && fileName != null &&
                tparamMentionedInFunctionTypeDeep(sig, tp)) {
                // Context-sensitive sig (function-type-T param) signals TypeScript's
                // literal-preserving inference. Emit TS2345 directly at the failing
                // arg position with LITERAL-form display, then return null so the
                // standard arg-check loop doesn't fire its own widened TS2345 at
                // the same position. Bare-T params silently pass the standard check
                // (T is unconstrained → apparent type {} → everything assignable).
                val conflictCand = effectiveCandidates[conflictAt]
                val arg = args[conflictCand.argIdx]
                val argDisplay = typeToString(conflictCand.literalType ?: conflictCand.widenedType)
                val paramDisplay = typeToString(first.literalType ?: first.widenedType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argDisplay' is not assignable to parameter of type '$paramDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                return null
            }

            // Default path: substitute tp with the widened first candidate. For
            // multi-arg conflict without preserveLiterals, this matches 17.31a's
            // first-arg-wins behavior (e.g. `bar(1, "")` substitutes T=number,
            // then standard loop emits 'string' vs 'number' at arg[1]).
            mapperPairs.add(tp to firstWidened)
        }

        if (mapperPairs.isEmpty()) return null
        return createTypeMapper(mapperPairs.map { it.first }, mapperPairs.map { it.second })
    }

    /**
     * B86.1b-4 (2026-05-28): anchor-only PARTIAL inference for CONSUMER-side
     * contextual-param substitution. Unlike [tryInferSingleTypeParamFromArgs]
     * (which requires EVERY type param to be inferable and returns null if any
     * isn't), this gathers candidates ONLY from non-callback "anchor" positions
     * (bare-`T`, rest-`T[]`, non-rest `Array<T>`) and returns a mapper covering
     * whatever subset of TPs got at least one anchor candidate. Return-position
     * TPs of callback params (the `U` in `(x:T)=>U`) are intentionally NOT
     * inferred here — the point is to let the un-annotated lambda's param (`x:T`)
     * resolve to its concrete anchor type during the diagnostic walk so a body
     * like `x.length` fires TS2339 when `T` is `number`.
     *
     * Used by the CallExpression `argCtxTypes` block in [checkPropertyAccessInExpr]
     * as a fallback when the full mapper from [tryInferSingleTypeParamFromArgs] is
     * null (the common case for callback-return-position shapes whose body errors).
     * Narrow: only single-arg-position bare-`T` / rest-`T[]` / `Array<T>` anchors,
     * widened candidate must be named-like, first-candidate-wins (no conflict
     * detection — this is best-effort contextual typing, not diagnostic emission).
     * Returns null when no anchor TP is inferable.
     */
    private fun tryInferAnchorTypeParamsForContext(
        sig: Signature,
        args: List<Expression>,
    ): TypeMapper? {
        val tps = sig.typeParameters ?: return null
        if (tps.isEmpty()) return null
        val params = sig.parameters
        if (params.isEmpty() || args.isEmpty()) return null
        val tpsSet = tps.toSet()
        fun isNamedLikeAtom(t: Type): Boolean =
            t is Type.Interface || t is Type.Reference || t is Type.Intrinsic ||
                t.flags.hasAny(
                    TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
                    TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
                    TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
                )
        val mapperPairs = mutableListOf<Pair<Type.TypeParam, Type>>()
        for (tp in tps) {
            var anchored: Type? = null
            for (i in params.indices) {
                if (i >= args.size) break
                val pt = try { getTypeOfSymbol(params[i]) } catch (_: StackOverflowError) { return null }
                val isRest = (params[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                val isBareT = pt === tp
                val isRestT = isRest && i == params.size - 1 && isArrayOfTypeParam(pt, tp)
                val isArrayT = !isRest && isArrayOfTypeParam(pt, tp)
                if (!isBareT && !isRestT && !isArrayT) continue
                val argRange = if (isRestT) i until args.size else i..i
                for (ai in argRange) {
                    if (ai >= args.size) break
                    val arg = args[ai]
                    if (arg is SpreadElement) continue
                    if (isArrayT && arg is ArrayLiteralExpression && arg.elements.isEmpty()) continue
                    val rawArgType = try { getTypeOfExpression(arg) } catch (_: StackOverflowError) { return null }
                    if (rawArgType === anyType || rawArgType === errorType) continue
                    if (rawArgType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) continue
                    val argType = if (isArrayT) {
                        if (rawArgType !is Type.Reference) continue
                        if (rawArgType.target?.symbol?.name != "Array") continue
                        val refArgs = rawArgType.resolvedTypeArguments ?: continue
                        if (refArgs.size != 1) continue
                        val element = refArgs[0]
                        if (element is Type.Union) getUnionType(element.types.map { widenType(it) })
                        else widenType(element)
                    } else widenType(rawArgType)
                    if (argType === anyType || argType === errorType) continue
                    if (argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) continue
                    val isNamedLike = isNamedLikeAtom(argType) ||
                        (argType is Type.Union && argType.types.all { isNamedLikeAtom(it) })
                    if (!isNamedLike) continue
                    // First anchor candidate wins for this TP.
                    if (anchored == null) anchored = argType
                }
                if (anchored != null) break
            }
            if (anchored != null) {
                val constraint = tp.constraint
                if (constraint != null) {
                    val ok = try { checkTypeRelatedTo(anchored, constraint, assignableRelation) }
                        catch (_: StackOverflowError) { false }
                    if (!ok) continue
                }
                mapperPairs.add(tp to anchored)
            }
        }
        if (mapperPairs.isEmpty()) return null
        return createTypeMapper(mapperPairs.map { it.first }, mapperPairs.map { it.second })
    }

    /**
     * 17.31b helper: true when [sig] has any parameter whose type is a function
     * shape (Type.Object with call/construct signatures) that mentions [tp] in
     * its parameter or return positions. Used to detect TypeScript's "context-
     * sensitive call" pattern (e.g. `f<T>(a:T, c:(t:T)=>T)`) where literal-
     * preserving inference is appropriate.
     */
    private fun tparamMentionedInFunctionType(sig: Signature, tp: Type.TypeParam): Boolean {
        for (p in sig.parameters) {
            val pt = try { getTypeOfSymbol(p) } catch (_: StackOverflowError) { continue }
            if (pt !is Type.Object) continue
            val sigs = (pt.callSignatures ?: emptyList()) + (pt.constructSignatures ?: emptyList())
            if (sigs.isEmpty()) continue
            for (s in sigs) {
                for (sp in s.parameters) {
                    val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { continue }
                    if (typeMentionsTypeParam(spt, tp)) return true
                }
                val rt = s.resolvedReturnType ?: continue
                if (typeMentionsTypeParam(rt, tp)) return true
            }
        }
        return false
    }

    /**
     * B83.4d-deepgate (round 73): deep variant of [tparamMentionedInFunctionType].
     * Recurses into NESTED function-shaped Type.Object (call/construct signatures'
     * param + return types) so shapes like `b: () => (a: T) => void` are detected
     * as mentioning [tp]. The shallow [typeMentionsTypeParam] deliberately does NOT
     * descend into function shapes (CLAUDE.md gotcha), which is why the shallow
     * helper misses fixed-type-parameter callbacks whose T sits inside a RETURNED
     * function type (TypeScript's fixed-type-parameter rule applies there too).
     * Used ONLY to widen the conflict-branch literal-display gate in
     * [tryInferSingleTypeParamFromArgs]. Cycle-guarded by a visited-id set so
     * self-referential function shapes don't recurse forever. Superset of the
     * shallow helper (also matches the direct `(t:T)=>T` case).
     */
    private fun tparamMentionedInFunctionTypeDeep(sig: Signature, tp: Type.TypeParam): Boolean {
        val seen = HashSet<Int>()
        fun mentionsDeep(t: Type): Boolean {
            when (t) {
                is Type.TypeParam -> return t === tp
                is Type.Reference -> return (t.resolvedTypeArguments ?: emptyList()).any { mentionsDeep(it) }
                is Type.Union -> return t.types.any { mentionsDeep(it) }
                is Type.Intersection -> return t.types.any { mentionsDeep(it) }
                is Type.Object -> {
                    if (!seen.add(t.id)) return false
                    val sigs = (t.callSignatures ?: emptyList()) + (t.constructSignatures ?: emptyList())
                    for (s in sigs) {
                        for (sp in s.parameters) {
                            val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { continue }
                            if (mentionsDeep(spt)) return true
                        }
                        val rt = s.resolvedReturnType
                        if (rt != null && mentionsDeep(rt)) return true
                    }
                    return false
                }
                else -> return false
            }
        }
        for (p in sig.parameters) {
            val pt = try { getTypeOfSymbol(p) } catch (_: StackOverflowError) { continue }
            if (pt !is Type.Object) continue
            val sigs = (pt.callSignatures ?: emptyList()) + (pt.constructSignatures ?: emptyList())
            if (sigs.isEmpty()) continue
            if (mentionsDeep(pt)) return true
        }
        return false
    }

    /**
     * B83.4d (round 73): for the consumer-side contextual-typing substitution,
     * compute a literal-preserving OVERRIDE mapper for TypeScript's fixed-type-
     * parameter rule. A type parameter that (a) is mentioned inside a function-
     * typed parameter (deep — incl. nested returned function types) AND (b) has
     * CONFLICTING bare-`T` anchor candidates (e.g. `f<T>(x:T, b:()=>(a:T)=>void,
     * y:T)` called `f('', ..., 1)`) is FIXED by TypeScript to the FIRST anchor
     * candidate UNWIDENED (the literal `""`), not the widened common type — so
     * the callback param `a` is contextually typed `""` and `a.foo` reports
     * TS2339 on `""`. Returns a mapper from such TPs to their unwidened first
     * literal, or null when no TP qualifies. Kept SEPARATE from the widened
     * inference mapper (which return-type inference + JS-emit contextual
     * this-binding rely on, per the B83.4d-literal CLAUDE.md gotcha) so the
     * literal is confined to this call's contextual-param typing for display.
     */
    private fun computeFixedConflictLiteralMapper(sig: Signature, args: List<Expression>): TypeMapper? {
        val tps = sig.typeParameters ?: return null
        if (tps.isEmpty()) return null
        val params = sig.parameters
        if (params.isEmpty() || args.isEmpty()) return null
        val pairs = mutableListOf<Pair<Type.TypeParam, Type>>()
        for (tp in tps) {
            if (!tparamMentionedInFunctionTypeDeep(sig, tp)) continue
            var firstLiteral: Type? = null
            var firstWidened: Type? = null
            var conflict = false
            for (i in params.indices) {
                if (i >= args.size) break
                val pt = try { getTypeOfSymbol(params[i]) } catch (_: StackOverflowError) { return null }
                if (pt !== tp) continue  // bare-T anchor positions only
                val arg = args[i]
                if (arg is SpreadElement) continue
                val raw = try { getTypeOfExpression(arg) } catch (_: StackOverflowError) { return null }
                if (raw === anyType || raw === errorType) continue
                if (raw.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) continue
                // Prefer the unwidened LITERAL form (`""`/`1`) for the fixed-type
                // display; getTypeOfExpression already widens under @strict:false.
                val literal = try { literalTypeOfExpression(arg) } catch (_: StackOverflowError) { null } ?: raw
                val widened = widenType(raw)
                if (firstWidened == null) {
                    firstLiteral = literal
                    firstWidened = widened
                } else {
                    val ok = try {
                        checkTypeRelatedTo(widened, firstWidened, assignableRelation) ||
                            checkTypeRelatedTo(firstWidened, widened, assignableRelation)
                    } catch (_: StackOverflowError) { true }
                    if (!ok) conflict = true
                }
            }
            if (conflict && firstLiteral != null) pairs.add(tp to firstLiteral)
        }
        if (pairs.isEmpty()) return null
        return createTypeMapper(pairs.map { it.first }, pairs.map { it.second })
    }

    /**
     * 17.31c/e helper: true when [type] is `Array<T>` (`T[]`) — used for both
     * rest-of-`T[]` (17.31c) and non-rest `T[]` (17.31e) inference shapes.
     * Requires the Reference's target to be the lib `Array` symbol and its
     * single resolved type argument to be the very TypeParam [tp].
     */
    private fun isArrayOfTypeParam(type: Type, tp: Type.TypeParam): Boolean {
        if (type !is Type.Reference) return false
        if (type.target?.symbol?.name != "Array") return false
        val args0 = type.resolvedTypeArguments ?: return false
        return args0.size == 1 && args0[0] === tp
    }

    /**
     * 17.38 / B52.2 helper: true when [type] is an anonymous Type.Object where
     * AT LEAST ONE member is a bare reference to some TypeParam in [tps], and
     * every OTHER member is fully concrete (mentions NO TP in [tps]). Used to
     * gate `foo<T>(f: { x: T; y: T })` style inference (17.38, all-TP form) AND
     * the mixed `foo<T>(f: { v: T; name: string })` form (B52.2). T is gathered
     * from the matching arg's property values via [tryInferSingleTypeParamFromArgs]'s
     * isObjLitOfT branch — concrete members are skipped during gathering. Excludes
     * Type.Interface / Type.Reference (named types) and Type.Object with
     * call/construct sigs (function-shaped). Members whose type MENTIONS a TP
     * indirectly (e.g. `{ v: Array<T> }`) bail to avoid complex inference shapes.
     */
    private fun isAnonymousObjectWithTypeParamMembers(type: Type, tps: Set<Type.TypeParam>): Boolean {
        if (type !is Type.Object) return false
        if (type is Type.Interface) return false
        if (type is Type.Reference) return false
        if (type.symbol != null) return false
        if (type.callSignatures?.isNotEmpty() == true) return false
        if (type.constructSignatures?.isNotEmpty() == true) return false
        if (type.stringIndexInfo != null || type.numberIndexInfo != null) return false
        val members = type.members ?: return false
        if (members.isEmpty()) return false
        var hasTpMember = false
        for (sym in members.values) {
            val mt = try { getTypeOfSymbol(sym) } catch (_: StackOverflowError) { return false }
            if (mt is Type.TypeParam && mt in tps) {
                hasTpMember = true
            } else if (tps.any { typeMentionsTypeParam(mt, it) }) {
                // Member mentions a TP but isn't a bare TP — too complex for this helper.
                return false
            }
            // else: concrete member (no TP mention) — OK, will be skipped during gathering.
        }
        return hasTpMember
    }

    /**
     * B83.1 helper: returns the matched `Type.TypeParam` when [type] is an
     * anonymous function-typed shape `(x: tp_i) => <concrete>` where `tp_i ∈ [tps]`.
     * Specifically: Type.Object with exactly ONE callSignature, no constructSignatures,
     * no other members/index sigs/symbol, where the single callSig has exactly ONE
     * parameter whose type is a bare `Type.TypeParam ∈ tps`, AND the return type
     * is either `voidType` OR fully concrete (mentions NO TP in [tps]).
     *
     * Used by gate (f) of [tryInferSingleTypeParamFromArgs] to allow inference of
     * `tp_i` from the matching arg's `(x: <annotated>) => ...` callback shape
     * (the callback's parameter annotation supplies the inference candidate).
     *
     * Returns null when shape doesn't match — narrow gate by design: multi-param
     * callbacks, TP-in-return, multiple call/construct sigs, named function-type
     * aliases (Type.Interface / Reference), or callbacks where the inner param
     * is not a bare TP all fail this gate.
     */
    private fun fnTypedParamBareTpMatch(
        type: Type,
        tps: Set<Type.TypeParam>,
        currentTp: Type.TypeParam? = null,
    ): Type.TypeParam? {
        if (type !is Type.Object) return null
        if (type is Type.Interface) return null
        if (type is Type.Reference) return null
        if (type.symbol != null) return null
        if (type.constructSignatures?.isNotEmpty() == true) return null
        if (type.stringIndexInfo != null || type.numberIndexInfo != null) return null
        if (type.members?.isNotEmpty() == true) return null
        val sigs = type.callSignatures ?: return null
        if (sigs.size != 1) return null
        val sig = sigs[0]
        if (sig.parameters.size != 1) return null
        val pt = try { getTypeOfSymbol(sig.parameters[0]) } catch (_: StackOverflowError) { return null }
        if (pt !is Type.TypeParam || pt !in tps) return null
        val rt = sig.resolvedReturnType ?: return null
        // B83.2: when currentTp is provided, only that TP's mention in return type
        // causes bail (other TPs in `tps` are allowed — they get inferred via their
        // own per-tp iteration via other arg positions or via gate (f) when their
        // own callback shape matches). When currentTp is null (param-walk pre-check
        // at the sig-acceptance gate), accept any function-typed bare-TP-param shape
        // regardless of return-type TP mentions — sig is acceptable; per-tp gathering
        // decides which TPs actually get inference from it.
        if (rt !== voidType) {
            if (currentTp != null) {
                if (typeMentionsTypeParam(rt, currentTp)) return null
            }
            // currentTp == null: no return-type TP-mention bail (B83.2 relaxation).
        }
        return pt
    }

    /**
     * B83.4i helper: recognizes a function-typed param whose parameters are ALL
     * fully concrete (mention NO TP from [tps]) and whose RETURN type is exactly
     * a bare TP from [tps]. This is the post-receiver-substitution shape of
     * `Array.map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[]`
     * — after `resolveGenericPropertyType` maps `T→number`, the callback param
     * `value` is concrete `number` and the only remaining TP is the return `U`.
     *
     * Returns the return-position TP (the `U`) when the shape matches, else null.
     * Narrow gate: anonymous Type.Object, single callSig, at least one param, no
     * construct sigs / index sigs / members / symbol. Used by gate (h) of
     * [tryInferSingleTypeParamFromArgs] so the sig is ACCEPTED (not bailed at gate
     * (c)); per-tp candidate gathering for the return TP happens in pass-2's
     * B83.4i body-retyping branch.
     */
    private fun fnTypedParamConcreteParamsBareReturnTp(
        type: Type,
        tps: Set<Type.TypeParam>,
    ): Type.TypeParam? {
        if (type !is Type.Object) return null
        if (type is Type.Interface) return null
        if (type is Type.Reference) return null
        if (type.symbol != null) return null
        if (type.constructSignatures?.isNotEmpty() == true) return null
        if (type.stringIndexInfo != null || type.numberIndexInfo != null) return null
        if (type.members?.isNotEmpty() == true) return null
        val sigs = type.callSignatures ?: return null
        if (sigs.size != 1) return null
        val sig = sigs[0]
        if (sig.parameters.isEmpty()) return null
        // All callback params must be concrete (mention no TP).
        for (sp in sig.parameters) {
            val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { return null }
            if (tps.any { typeMentionsTypeParam(spt, it) }) return null
        }
        val rt = sig.resolvedReturnType ?: return null
        // Return type must be exactly a bare TP from tps.
        return if (rt is Type.TypeParam && rt in tps) rt else null
    }

    /**
     * B83.3 helper: multi-param callback recognition for the B83.1 gate-(f) family.
     * Accepts an anonymous Type.Object with exactly 1 callSig whose parameters are
     * each EITHER (a) bare-TP-typed (any TP from [tps]) OR (b) fully concrete
     * (mention NO TP from [tps]). At least one parameter must be a bare TP.
     *
     * Return type follows the same per-currentTp gate as [fnTypedParamBareTpMatch]:
     * when [currentTp] is provided, only that TP's appearance in the return causes
     * bail; when null, return-type TP-mentions are accepted (sig-acceptance gate).
     *
     * Returns a list mapping each callback parameter slot to either the bare TP
     * occupying that slot, or null for concrete slots. Returns null when the shape
     * does NOT match (multi-param with all concrete, single-param shape, ctor-sigs,
     * named function-types, members present, etc.). The single-param shape is
     * intentionally NOT matched here — [fnTypedParamBareTpMatch] handles that
     * case and is checked first at call sites.
     */
    private fun fnTypedParamMultiBareTpMatch(
        type: Type,
        tps: Set<Type.TypeParam>,
        currentTp: Type.TypeParam? = null,
    ): List<Type.TypeParam?>? {
        if (type !is Type.Object) return null
        if (type is Type.Interface) return null
        if (type is Type.Reference) return null
        if (type.symbol != null) return null
        if (type.constructSignatures?.isNotEmpty() == true) return null
        if (type.stringIndexInfo != null || type.numberIndexInfo != null) return null
        if (type.members?.isNotEmpty() == true) return null
        val sigs = type.callSignatures ?: return null
        if (sigs.size != 1) return null
        val sig = sigs[0]
        if (sig.parameters.size < 2) return null  // single-param handled by fnTypedParamBareTpMatch
        val slots = mutableListOf<Type.TypeParam?>()
        var anyBareTp = false
        for (sp in sig.parameters) {
            // Rest params disallowed in this gate — bare-TP would conflict with
            // rest-of-tp[] anchor positions handled separately.
            if ((sp.valueDeclaration as? Parameter)?.dotDotDotToken == true) return null
            val spt = try { getTypeOfSymbol(sp) } catch (_: StackOverflowError) { return null }
            if (spt is Type.TypeParam && spt in tps) {
                slots.add(spt)
                anyBareTp = true
            } else if (tps.any { typeMentionsTypeParam(spt, it) }) {
                // Param mentions a TP but is NOT a bare TP (e.g. Array<T>, (x:T)=>U).
                // Too complex for this gate; bail.
                return null
            } else {
                slots.add(null)  // fully concrete slot
            }
        }
        if (!anyBareTp) return null
        val rt = sig.resolvedReturnType ?: return null
        if (rt !== voidType) {
            if (currentTp != null) {
                if (typeMentionsTypeParam(rt, currentTp)) return null
            }
        }
        return slots
    }

    /**
     * B62.1 helper: true when [source] is an anonymous (fresh-literal-shaped)
     * Type.Object with at least one property that does NOT exist in
     * [constraint]'s members. Used to filter "constraint subtype" elaboration
     * chain emission in TS2322: for `function f<T extends {a:string}>(x: T) { x = {a, b, c} }`,
     * source `{a, b, c}` has excess `b`/`c` relative to constraint `{a:string}`,
     * so TypeScript emits the "arbitrary unrelated" chain (not "constraint subtype")
     * — matches the `errorElaborationDivesIntoApparentlyPresentPropsOnly` baseline.
     *
     * Gated on: (a) source is anonymous Type.Object (no symbol, not Reference,
     * not Interface), (b) constraint is a concrete Type.Object with no
     * string/number index signature (an index signature accepts any extra props).
     * `errorType` / `anyType` constraints fall through (return false) — no
     * excess-prop check applies when the constraint is `any`-like.
     */
    private fun anonymousObjectHasExcessVsConstraint(source: Type, constraint: Type): Boolean {
        if (source !is Type.Object) return false
        if (source is Type.Reference || source is Type.Interface) return false
        if (source.symbol != null) return false
        if (constraint !is Type.Object) return false
        val srcMembers = source.members ?: return false
        val cnstrMembers = constraint.members ?: return false
        if (constraint.stringIndexInfo != null || constraint.numberIndexInfo != null) return false
        return srcMembers.keys.any { it !in cnstrMembers }
    }

    /**
     * 17.43: Apply contextual literal preservation when `init` is a generic
     * call whose substituted return type produced an anonymous Type.Object
     * whose property types were widened (e.g. `string` from
     * `getTypeOfObjectLiteral` on `{fooProp: "frizzlebizzle"}`). When the
     * var-decl's [targetType] has a literal-typed property at the same
     * name, replace the source's widened property with the literal type
     * recovered from the original arg AST via [literalTypeOfExpression].
     *
     * Mirrors TypeScript's contextual-type-aware literal preservation rule:
     * a fresh string/number literal stays as a literal type when the
     * contextually-typed location has any literal members of the same
     * base, otherwise it widens. Operates on the substituted source so
     * existing chain elaboration + display picks up the preserved literal.
     *
     * Returns [sourceType] unchanged when the pattern doesn't apply.
     */
    private fun applyContextualLiteralPreservation(
        sourceType: Type,
        targetType: Type,
        init: Expression,
    ): Type {
        if (init !is CallExpression) return sourceType
        if (sourceType !is Type.Object && sourceType !is Type.Intersection) return sourceType
        if (targetType !is Type.Object) return sourceType
        // Find the first ObjectLiteralExpression arg.
        val objLitArg = init.arguments.firstOrNull { it is ObjectLiteralExpression }
            as? ObjectLiteralExpression ?: return sourceType
        val literalsByName = mutableMapOf<String, Type>()
        for (prop in objLitArg.properties) {
            if (prop !is PropertyAssignment) continue
            val name = getPropertyKeyName(prop.name) ?: continue
            val lit = literalTypeOfExpression(prop.initializer) ?: continue
            literalsByName[name] = lit
        }
        if (literalsByName.isEmpty()) return sourceType
        val constituents = if (sourceType is Type.Intersection) sourceType.types else listOf(sourceType)
        var changed = false
        val newConstituents = constituents.map { c ->
            // Skip named types (Interface/Reference) — only anonymous Object
            // constituents come from a fresh substituted-T inference.
            if (c !is Type.Object || c is Type.Interface || c is Type.Reference) return@map c
            if (c.symbol != null) return@map c
            val members = c.members ?: return@map c
            var memberChanged = false
            val newMembers = mutableMapOf<String, Symbol>()
            for ((name, sym) in members) {
                val literal = literalsByName[name]
                if (literal != null) {
                    val targetProp = try { getPropertyOfType(targetType, name) }
                        catch (_: StackOverflowError) { null }
                    val targetPropType = targetProp?.let {
                        try { getTypeOfSymbol(it) } catch (_: StackOverflowError) { null }
                    }
                    val srcType = symbolTypes[sym.id] ?: try { getTypeOfSymbol(sym) }
                        catch (_: StackOverflowError) { null }
                    if (targetPropType != null && srcType != null &&
                        propTypeContainsLiteral(targetPropType) &&
                        literalWidensTo(literal, srcType)
                    ) {
                        val newSym = Symbol(sym.flags, sym.name)
                        sym.declarations.forEach { newSym.declarations.add(it) }
                        newSym.valueDeclaration = sym.valueDeclaration
                        newSym.parent = sym.parent
                        symbolTypes[newSym.id] = literal
                        newMembers[name] = newSym
                        memberChanged = true
                        continue
                    }
                }
                newMembers[name] = sym
            }
            if (!memberChanged) return@map c
            changed = true
            val newObj = Type.Object()
            newObj.members = newMembers
            newObj.properties = newMembers.values.toList()
            newObj.callSignatures = c.callSignatures
            newObj.constructSignatures = c.constructSignatures
            newObj.stringIndexInfo = c.stringIndexInfo
            newObj.numberIndexInfo = c.numberIndexInfo
            newObj
        }
        if (!changed) return sourceType
        return if (sourceType is Type.Intersection) getIntersectionType(newConstituents) else newConstituents[0]
    }

    /** 17.43 helper: true if [propType] is a literal type or contains literal members. */
    private fun propTypeContainsLiteral(propType: Type): Boolean = when {
        propType is Type.StringLiteral -> true
        propType is Type.NumberLiteral -> true
        propType is Type.BigIntLiteral -> true
        propType is Type.Intrinsic && propType.flags.hasAny(
            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
                TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral
        ) -> true
        propType is Type.Union -> propType.types.any { propTypeContainsLiteral(it) }
        else -> false
    }

    /** 17.43 helper: true if [literal] widens to [base] (e.g. StringLiteral → stringType). */
    private fun literalWidensTo(literal: Type, base: Type): Boolean = when {
        literal is Type.StringLiteral -> base === stringType
        literal is Type.NumberLiteral -> base === numberType
        literal is Type.BigIntLiteral -> base === bigintType
        literal === trueType || literal === falseType -> base === booleanType
        else -> false
    }

    /** True if [type] structurally references [tp] (recurses into Reference/Union/Intersection). */
    private fun typeMentionsTypeParam(type: Type, tp: Type.TypeParam): Boolean {
        return when (type) {
            is Type.TypeParam -> type === tp
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return false
                args.any { typeMentionsTypeParam(it, tp) }
            }
            is Type.Union -> type.types.any { typeMentionsTypeParam(it, tp) }
            is Type.Intersection -> type.types.any { typeMentionsTypeParam(it, tp) }
            else -> false
        }
    }

    /** Get the return type of a new expression by resolving the construct signature. */
    private fun getReturnTypeOfNewExpression(expr: NewExpression): Type {
        // Unwrap value-preserving wrappers: `new (Foo)()`, `new Foo!()`,
        // `new (Foo satisfies T)()` should resolve like `new Foo()`.
        var callee: Expression = expr.expression
        while (true) {
            callee = when (callee) {
                is ParenthesizedExpression -> if (callee.instantiationEnd == null) callee.expression else break
                is NonNullExpression -> callee.expression
                is SatisfiesExpression -> callee.expression
                else -> break
            }
        }
        val calleeType = when (callee) {
            is Identifier -> getTypeOfIdentifier(callee)
            // `new M.C()` / `new A.B.C()`: resolve the namespace-qualified CLASS to its
            // declared (instance) type. Gated strictly on SymbolFlags.Class so only a
            // genuine qualified class resolves — qualified functions/namespaces/vars fall
            // through to anyType (prior behavior), keeping the FP surface minimal.
            is PropertyAccessExpression -> {
                val sym = try { resolveQualifiedValueSymbol(callee) } catch (_: StackOverflowError) { null }
                if (sym != null && sym.flags.hasAny(SymbolFlags.Class)) {
                    try { getDeclaredTypeOfSymbol(sym) } catch (_: StackOverflowError) { return anyType }
                } else return anyType
            }
            else -> return anyType
        }
        if (calleeType === anyType || calleeType === errorType) return anyType
        // For new expressions, the return type is the class type itself.
        // 16.0: honor explicit type arguments (e.g. `new Test1<string>()`) by
        // creating a Type.Reference with the resolved type arguments so property
        // accesses on the instance see instantiated types.
        if (calleeType is Type.Interface) {
            val typeParams = calleeType.typeParameters
            val typeArgs = expr.typeArguments
            if (typeParams != null && typeParams.isNotEmpty() && typeArgs != null && typeArgs.isNotEmpty()) {
                try {
                    // B57.3d (a): save/reset deepInstantiationBailed around the
                    // explicit type-arg resolution loop. If a bail fires while
                    // resolving (e.g. mapped-type recursion in a generic-class
                    // type-arg shape), capture the expression position via
                    // [recordDeepBailNewExpression]; the diagnostic is emitted
                    // later by [flushDeepBailNewExpressionEmits] (from
                    // [getDiagnostics]). Save/restore so the bail flag does NOT
                    // propagate up to outer callers (which would over-emit
                    // TS2589 at the enclosing alias/var/property annotation).
                    val savedBail = deepInstantiationBailed
                    val savedMappedInfo = mappedTypeCircularInfo
                    deepInstantiationBailed = false
                    mappedTypeCircularInfo = null
                    val resolvedArgs = typeArgs.map { getTypeFromTypeNode(it) }
                    if (deepInstantiationBailed) {
                        recordDeepBailNewExpression(expr)
                    }
                    mappedTypeCircularInfo = savedMappedInfo
                    deepInstantiationBailed = savedBail
                    if (resolvedArgs.none { it === errorType }) {
                        return getOrInternReference(calleeType, resolvedArgs)
                    }
                } catch (_: StackOverflowError) { /* circular */ }
            }
            // 17.14b: Generic argument inference from constructor call.
            // `new Foo<T,U>(arg1, arg2)` infers T,U from arg types matching the
            // class's constructor parameters' direct TypeReference annotations.
            // Conservative: only matches when a constructor param's type annotation
            // is exactly `T` (TypeReference whose name == typeParam.name, no own
            // typeArgs). Doesn't infer through nested types like `Array<T>`.
            val newArgs = expr.arguments
            if (typeParams != null && typeParams.isNotEmpty() && typeArgs.isNullOrEmpty() &&
                !newArgs.isNullOrEmpty()) {
                try {
                    val inferred = inferTypeArgsFromConstructorCall(calleeType, typeParams, newArgs)
                    if (inferred != null && inferred.size == typeParams.size && inferred.none { it === errorType }) {
                        return getOrInternReference(calleeType, inferred)
                    }
                } catch (_: StackOverflowError) { /* circular */ }
            }
            // B56.1: `new C()` with no type args and no inferrable args — default
            // TypeParams to `unknown` (or declared `default`) under strict mode.
            // B56.3/B56.4 (probed/reverted): broadening to also fire when newArgs
            // is non-empty (or no-constructor) regressed 1 test in each case.
            // The un-instantiated calleeType is structurally compatible with some
            // targets in ways that C<unknown> isn't.
            if (typeParams != null && typeParams.isNotEmpty() && typeArgs.isNullOrEmpty() &&
                newArgs.isNullOrEmpty() && strictNullChecks
            ) {
                try {
                    val args: List<Type> = typeParams.map { tp ->
                        val def = tp.default
                        when {
                            def != null && def !== errorType -> def
                            else -> unknownType
                        }
                    }
                    if (args.none { it === errorType }) {
                        return getOrInternReference(calleeType, args)
                    }
                } catch (_: StackOverflowError) { /* circular */ }
            }
            // 16.4gi: "Constructor interface" pattern — `declare var Object: ObjectConstructor`
            // where `interface ObjectConstructor { new(): Object }`. The new-expression's
            // return type is the construct signature's return type, not the constructor
            // interface itself. Class instance types (also Type.Interface) don't have
            // construct signatures (see CLAUDE.md "Class construct signatures are static-side
            // only"), so they fall through to `return calleeType` unchanged.
            if (typeArgs.isNullOrEmpty()) {
                try {
                    resolveStructuredTypeMembers(calleeType)
                    val sigs = calleeType.constructSignatures
                    if (!sigs.isNullOrEmpty()) {
                        val ret = sigs[0].resolvedReturnType
                        if (ret != null && ret !== errorType) return ret
                    }
                } catch (_: StackOverflowError) { /* circular */ }
            }
            return calleeType
        }
        if (calleeType !is Type.Object) return anyType
        resolveStructuredTypeMembers(calleeType)
        val sigs = calleeType.constructSignatures
        if (sigs.isNullOrEmpty()) return anyType
        return sigs[0].resolvedReturnType ?: anyType
    }

    /**
     * B81.1d: Resolve a callee expression of the form `this.a.b.c` using the
     * [enclosingClassType] as the head type (rather than `getTypeOfIdentifier`
     * which returns `anyType` for `this`). Returns null when:
     * - chain head is not bare `this`
     * - [enclosingClassType] is null
     * - any segment fails to resolve
     * - the final type is `anyType` / `errorType`
     *
     * Mirrors [resolveUncalledOperandType] in spirit but uses the callee's
     * enclosingClassType passed through `checkPropertyAccessInExpr`. Narrow
     * scope by design — only the contextual-argument-type computation for
     * CallExpression callees consults this; broader use risks regressions.
     */
    private fun resolveCalleeChainWithThis(
        callee: PropertyAccessExpression, enclosingClassType: Type?,
    ): Type? {
        if (enclosingClassType == null) return null
        // Collect path segments [head, p1, p2, ...]
        val rev = mutableListOf<String>()
        var cur: Expression = callee
        while (cur is PropertyAccessExpression) {
            rev.add(cur.name.text)
            cur = cur.expression
            while (cur is ParenthesizedExpression) cur = cur.expression
        }
        if (cur !is Identifier || cur.text != "this") return null
        val segs = rev.reversed()
        // Walk segments starting from enclosingClassType
        var t: Type = enclosingClassType
        for (seg in segs) {
            if (t === anyType || t === errorType) return null
            val app = try { getApparentType(t) } catch (_: Throwable) { return null }
            val prop = try { getPropertyOfType(app, seg) } catch (_: Throwable) { null } ?: return null
            t = try {
                if (app is Type.Reference) {
                    resolveGenericPropertyType(app, prop) ?: getTypeOfSymbol(prop)
                } else {
                    getTypeOfSymbol(prop)
                }
            } catch (_: Throwable) { return null }
        }
        if (t === anyType || t === errorType) return null
        return t
    }

    /** Get the type of a property access expression (e.g., `obj.prop`). */
    private fun getTypeOfPropertyAccess(expr: PropertyAccessExpression): Type {
        val raw = computeRawTypeOfPropertyAccess(expr)
        // 17.34d: Apply flow-graph narrowing for expression-context property
        // reads (e.g. `A._a.length` after `if (A._a)` narrows `A._a` to `string`).
        // Conservative gate: only narrow Union types — narrowing a non-Union
        // can't refine. Path gate via [getReferencePath] avoids non-pure chains
        // (calls/parens/element-access). When [currentFlowGraph] is null
        // (outside expression-checking phases) [getNarrowedTypeForReference]
        // returns [raw] unchanged, so this is a no-op for symbol-type
        // resolution paths.
        if (raw is Type.Union && getReferencePath(expr) != null) {
            return getNarrowedTypeForReference(raw, expr)
        }
        return raw
    }

    private fun computeRawTypeOfPropertyAccess(expr: PropertyAccessExpression): Type {
        val rawObjectType = getTypeOfExpression(expr.expression)
        // B1.1: Narrow Union receivers via flow-graph state. Inside
        // `if (x && x.foo)`, the binder records the receiver `x` of `x.foo`
        // (RHS of `&&`) at a FlowCondition that asserts `x` is truthy — so
        // narrowing drops `undefined`/`null`/falsy members and `getPropertyOfType`
        // succeeds on the refined receiver instead of bailing on the Union.
        // Conservative gates: receiver must be a pure Identifier-or-PropertyAccess
        // chain (so [getReferencePath] is non-null), and only Union receivers are
        // narrowed — non-Unions can't be refined by condition-based narrowing.
        val objectType: Type =
            if (rawObjectType is Type.Union && getReferencePath(expr.expression) != null) {
                getNarrowedTypeForReference(rawObjectType, expr.expression)
            } else rawObjectType
        val propName = expr.name.text
        // B83.4e: For Union receivers, map each constituent through
        // `getApparentType` (so primitives → wrapper interface) and look up the
        // property on each. If EVERY constituent has the property, return the
        // union of their resolved types. This unblocks `(string|number).toString()`
        // and similar union-of-primitives method calls — previously fell through
        // to `anyType` because `getApparentType(union)` returns the union
        // unchanged and `getPropertyOfType` on the union recurses into each
        // primitive (Type.Intrinsic, not Type.Object) → returns null.
        if (objectType is Type.Union && objectType !== anyType && objectType !== errorType) {
            val propTypes = mutableListOf<Type>()
            var allHaveProp = true
            for (constituent in objectType.types) {
                val apparent = getApparentType(constituent)
                val prop = getPropertyOfType(apparent, propName)
                if (prop == null) {
                    allHaveProp = false
                    break
                }
                val propType = if (apparent is Type.Reference) {
                    resolveGenericPropertyType(apparent, prop) ?: getTypeOfSymbol(prop)
                } else {
                    getTypeOfSymbol(prop)
                }
                propTypes.add(propType)
            }
            if (allHaveProp && propTypes.isNotEmpty()) {
                return if (propTypes.size == 1) propTypes[0] else getUnionType(propTypes)
            }
            // fall through to standard handling for the non-Union case below
            // (which will hit the original `getApparentType(union)` no-op +
            // `getPropertyOfType(union)` "all constituents" path → null → anyType).
        }
        // If object resolved, check its apparent type for the property
        if (objectType !== anyType && objectType !== errorType) {
            val apparentType = getApparentType(objectType)
            val prop = getPropertyOfType(apparentType, propName)
            if (prop != null) {
                // 16.0n: For a generic Type.Reference (e.g. `arr: string[]` = Array<string>),
                // instantiate the property's type with the target's type params mapped to
                // the reference's type args. Reuses the helper used by assignment checking.
                if (apparentType is Type.Reference) {
                    resolveGenericPropertyType(apparentType, prop)?.let { return it }
                }
                // B82.1: Inherited-method type-substitution. When receiver is a
                // class instance (Type.Interface, not Reference) and the resolved
                // property comes from a GENERIC base (e.g. `class D extends C<string>`
                // calling `d.bar()` where `bar` is declared on `C<T>`), we must
                // substitute the base's type args into the property's type. Walk
                // the receiver's baseTypes for a Type.Reference whose target.symbol
                // matches the prop's parent (declaring class), then delegate to
                // resolveGenericPropertyType which already handles substitution.
                // Gate: prop.parent must differ from apparentType.symbol (only fires
                // for inherited members, not own members).
                if (apparentType is Type.Interface && apparentType !is Type.Reference) {
                    val propParent = prop.parent
                    if (propParent != null && propParent !== apparentType.symbol) {
                        findInheritedBaseRef(apparentType, propParent)?.let { baseRef ->
                            resolveGenericPropertyType(baseRef, prop)?.let { return it }
                        }
                    }
                }
                return getTypeOfSymbol(prop)
            }
        }
        // Fallback: try namespace/module lookup for property access
        val objExpr = expr.expression
        val nsSymbol = when (objExpr) {
            is Identifier -> currentFileLocals?.get(objExpr.text) ?: globals[objExpr.text]
            is PropertyAccessExpression -> {
                // Chained access: resolve the intermediate namespace symbol
                resolvePropertyAccessToSymbol(objExpr)
            }
            else -> null
        }
        if (nsSymbol != null && nsSymbol.flags.hasAny(SymbolFlags.Module)) {
            val exportSym = nsSymbol.exports?.get(propName)
            if (exportSym != null) return getTypeOfSymbol(exportSym)
        }
        // For resolved non-anyType objects, the property wasn't found — return anyType
        return anyType
    }

    /** Resolve a property access expression to its symbol (for namespace chaining). */
    private fun resolvePropertyAccessToSymbol(expr: PropertyAccessExpression): Symbol? {
        val baseSymbol = when (val base = expr.expression) {
            is Identifier -> currentFileLocals?.get(base.text) ?: globals[base.text]
            is PropertyAccessExpression -> resolvePropertyAccessToSymbol(base)
            else -> null
        }
        if (baseSymbol != null && baseSymbol.flags.hasAny(SymbolFlags.Module)) {
            return baseSymbol.exports?.get(expr.name.text)
        }
        return null
    }

    /** Get the type of an element access expression (e.g., `obj["prop"]`, `arr[0]`). */
    private fun getTypeOfElementAccess(expr: ElementAccessExpression): Type {
        val objectType = getTypeOfExpression(expr.expression)
        if (objectType === anyType || objectType === errorType) return anyType
        val rawIndexExpr = expr.argumentExpression ?: return anyType
        // Unwrap parens: `obj[("prop")]` should resolve like `obj["prop"]`.
        val indexExpr = unwrapParensExpr(rawIndexExpr)
        // String literal key: obj["prop"] → resolve as named property
        if (indexExpr is StringLiteralNode) {
            val prop = getPropertyOfType(objectType, indexExpr.text)
            if (prop != null) return getTypeOfSymbol(prop)
        }
        // Numeric literal key: arr[0] → resolve for tuple types
        if (indexExpr is NumericLiteralNode && objectType is Type.Object) {
            resolveStructuredTypeMembers(objectType)
            val idx = indexExpr.text
            val prop = objectType.members?.get(idx)
            if (prop != null) return getTypeOfSymbol(prop)
            // Check number index signature
            val numIdx = objectType.numberIndexInfo
            if (numIdx != null) return numIdx.type
        }
        // Check index signatures on the apparent type
        val apparent = getApparentType(objectType)
        if (apparent is Type.Object) {
            resolveStructuredTypeMembers(apparent)
            val indexType = getTypeOfExpression(indexExpr)
            if (indexType.flags.hasAny(TypeFlags.StringLike)) {
                val strIdx = apparent.stringIndexInfo
                if (strIdx != null) return strIdx.type
                // B70.3: string indexing on Array<T> returns T (JS arrays support
                // string keys that auto-convert to numeric). Without this, `arr[i]`
                // where `i: string` returns `anyType`, blocking downstream TS7053
                // emission for `arr[i][j]` patterns. Mirrors TypeScript's behavior.
                if (apparent is Type.Reference && apparent.target?.symbol?.name == "Array") {
                    apparent.resolvedTypeArguments?.firstOrNull()?.let { return it }
                }
            }
            if (indexType.flags.hasAny(TypeFlags.NumberLike)) {
                val numIdx = apparent.numberIndexInfo
                if (numIdx != null) return numIdx.type
            }
        }
        return anyType
    }

    /** Get the type of a binary expression. */
    private fun getTypeOfBinaryExpression(expr: BinaryExpression): Type {
        return when (expr.operator) {
            // Arithmetic → number
            SyntaxKind.Plus -> {
                // Plus is special: string + any = string, any + string = string
                val leftType = getTypeOfExpression(expr.left)
                val rightType = getTypeOfExpression(expr.right)
                if (leftType.flags.hasAny(TypeFlags.StringLike) || rightType.flags.hasAny(TypeFlags.StringLike)) {
                    stringType
                } else if (leftType.flags.hasAny(TypeFlags.NumberLike) && rightType.flags.hasAny(TypeFlags.NumberLike)) {
                    numberType
                } else if (leftType.flags.hasAny(TypeFlags.BigIntLike) && rightType.flags.hasAny(TypeFlags.BigIntLike)) {
                    bigintType
                } else {
                    anyType // could be string or number
                }
            }
            SyntaxKind.Minus, SyntaxKind.Asterisk, SyntaxKind.Slash,
            SyntaxKind.Percent, SyntaxKind.AsteriskAsterisk,
            SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret,
            SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
            SyntaxKind.GreaterThanGreaterThanGreaterThan -> numberType

            // Comparison → boolean
            SyntaxKind.LessThan, SyntaxKind.GreaterThan,
            SyntaxKind.LessThanEquals, SyntaxKind.GreaterThanEquals,
            SyntaxKind.EqualsEquals, SyntaxKind.ExclamationEquals,
            SyntaxKind.EqualsEqualsEquals, SyntaxKind.ExclamationEqualsEquals,
            SyntaxKind.InstanceOfKeyword, SyntaxKind.InKeyword -> booleanType

            // Assignment → type of left
            SyntaxKind.Equals -> getTypeOfExpression(expr.right)
            SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
            SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals,
            SyntaxKind.PercentEquals, SyntaxKind.AsteriskAsteriskEquals,
            SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals, SyntaxKind.CaretEquals,
            SyntaxKind.LessThanLessThanEquals, SyntaxKind.GreaterThanGreaterThanEquals,
            SyntaxKind.GreaterThanGreaterThanGreaterThanEquals -> getTypeOfExpression(expr.left)
            // Logical assignment ops — type is the union of LHS (kept) and RHS (assigned).
            SyntaxKind.AmpersandAmpersandEquals, SyntaxKind.BarBarEquals,
            SyntaxKind.QuestionQuestionEquals -> {
                val leftT = getTypeOfExpression(expr.left)
                val rightT = getTypeOfExpression(expr.right)
                if (leftT === rightT) leftT else getUnionType(listOf(leftT, rightT))
            }

            // Logical → union of operands
            SyntaxKind.AmpersandAmpersand -> getTypeOfExpression(expr.right)
            SyntaxKind.BarBar -> {
                val leftT = getTypeOfExpression(expr.left)
                val rightT = getTypeOfExpression(expr.right)
                if (leftT === rightT) leftT else getUnionType(listOf(leftT, rightT))
            }
            SyntaxKind.QuestionQuestion -> {
                val leftT = getTypeOfExpression(expr.left)
                val rightT = getTypeOfExpression(expr.right)
                if (leftT === rightT) leftT else getUnionType(listOf(leftT, rightT))
            }

            // Comma → type of right
            SyntaxKind.Comma -> getTypeOfExpression(expr.right)

            else -> anyType
        }
    }

    /**
     * B82.1: Walk a class/interface receiver's base-types chain BFS-style looking
     * for a [Type.Reference] whose `target.symbol === declaringSymbol`. Used to
     * find the concrete generic instantiation of an inherited property's
     * declaring class so [resolveGenericPropertyType] can substitute its type
     * args into the property's declared type. Returns the first match (most
     * specific direct base wins). Returns null when no base matches — caller
     * falls back to raw `getTypeOfSymbol(prop)`.
     */
    private fun findInheritedBaseRef(type: Type.Interface, declaringSymbol: Symbol): Type.Reference? {
        val visited = mutableSetOf<Int>()
        val queue = ArrayDeque<Type>()
        type.baseTypes?.forEach { queue.addLast(it) }
        while (queue.isNotEmpty()) {
            val cur = queue.removeFirst()
            if (!visited.add(cur.id)) continue
            if (cur is Type.Reference && cur.target.symbol === declaringSymbol) {
                return cur
            }
            // Walk further up the chain — handles multi-level inheritance like
            // `class E extends D` where D extends C<string>: E's baseTypes contain
            // D (Type.Interface, no generic), and D's baseTypes contain C<string>.
            when (cur) {
                is Type.Reference -> cur.target.baseTypes?.forEach { queue.addLast(it) }
                is Type.Interface -> cur.baseTypes?.forEach { queue.addLast(it) }
                else -> {}
            }
        }
        return null
    }

    /**
     * Get the apparent type of a type — for type parameters, this is the constraint;
     * for primitives, this is the corresponding wrapper type.
     */
    private fun getApparentType(type: Type): Type {
        return when {
            type is Type.TypeParam -> type.constraint?.let { getApparentType(it) } ?: anyType
            type.flags.hasAny(TypeFlags.StringLike) -> getBuiltinWrapperType("String") { stringWrapperType } ?.also { stringWrapperType = it } ?: anyType
            type.flags.hasAny(TypeFlags.NumberLike) -> getBuiltinWrapperType("Number") { numberWrapperType } ?.also { numberWrapperType = it } ?: anyType
            type.flags.hasAny(TypeFlags.BooleanLike) -> getBuiltinWrapperType("Boolean") { booleanWrapperType } ?.also { booleanWrapperType = it } ?: anyType
            else -> type
        }
    }

    /**
     * Wrapper interface (Number/String/Boolean/Symbol/BigInt) → primitive elaboration.
     * Returns the chain line "  'X' is a primitive, but 'Y' is a wrapper object. Prefer
     * using 'X' when possible." when source is a named wrapper interface and the displayed
     * target is exactly the matching primitive name. Returns null otherwise.
     */
    private fun getWrapperToPrimitiveElaboration(sourceType: Type, displayTarget: String): String? {
        if (sourceType !is Type.Interface) return null
        val sourceName = sourceType.symbol?.name ?: return null
        val primitive = when (sourceName) {
            "String" -> "string"
            "Number" -> "number"
            "Boolean" -> "boolean"
            "Symbol" -> "symbol"
            "BigInt" -> "bigint"
            else -> return null
        }
        if (displayTarget != primitive) return null
        return "  '$primitive' is a primitive, but '$sourceName' is a wrapper object. Prefer using '$primitive' when possible."
    }

    /**
     * B83.4h: resolve the type of an Object.prototype member (toString/valueOf/...)
     * from the built-in `Object` interface. Used to compare a source object literal's
     * own prototype-named property against the inherited signature. Returns null if the
     * Object interface isn't resolvable or the member isn't found.
     */
    private fun getObjectPrototypeMemberType(memberName: String): Type? {
        val symbol = globals["Object"] ?: return null
        if (!symbol.flags.hasAny(SymbolFlags.Interface)) return null
        val type = getDeclaredTypeOfSymbol(symbol)
        if (type === errorType || type !is Type.Object) return null
        resolveStructuredTypeMembers(type)
        val memberSym = type.members?.get(memberName) ?: return null
        val memberType = getTypeOfSymbol(memberSym)
        if (memberType === anyType || memberType === errorType) return null
        return memberType
    }

    /** Resolve a built-in wrapper type from globals, caching the result. */
    private inline fun getBuiltinWrapperType(name: String, cached: () -> Type?): Type? {
        cached()?.let { return it }
        val symbol = globals[name] ?: return null
        if (!symbol.flags.hasAny(SymbolFlags.Interface)) return null
        val type = getDeclaredTypeOfSymbol(symbol)
        if (type === errorType) return null
        // Ensure members are resolved
        if (type is Type.Object) resolveStructuredTypeMembers(type)
        return type
    }

    /**
     * Get a display-friendly string for a Type (used in diagnostic messages).
     */
    /**
     * Format a single parameter as `name: type` / `name?: type | undefined` / `...name: type`
     * depending on modifiers on its declaration. Shared by signatureToString / signatureToStringColon
     * so arrow and colon forms render params identically.
     */
    private fun formatParameter(p: Symbol): String {
        val decl = p.valueDeclaration as? Parameter
        // B9.5: binding-pattern parameters render as their source-slice
        // reconstruction (e.g. `{ [foo.bar]: c }` for `{[foo.bar]: c}`). For
        // AST shapes the helper can't reconstruct, falls back to `_` (the
        // pre-B9.5 placeholder).
        val displayName: String = when (val name = decl?.name) {
            is ObjectBindingPattern, is ArrayBindingPattern -> formatBindingPatternFromAst(name as Node)
            else -> p.name
        }
        val resolvedType = getTypeOfSymbol(p)
        // 17.24: When the resolved type is errorType (e.g. unresolved name like
        // `items: ItemSet`), prefer rendering from the AST type-node so the displayed
        // form preserves the source name (e.g. `ItemSet`) instead of `error`.
        // 17.238: For an unresolved TypeReference with a QualifiedName typeName
        // (e.g. `fs.Stats`), render the full dotted path — TypeScript's TS2345
        // baseline shows `fs.Stats`, not just `Stats`. Resolved-type displays go
        // through `typeToString` which uses the rightmost segment, matching
        // TypeScript's convention for known types like `X.Y.Z` → `Z`.
        val pType = if (resolvedType === errorType) {
            val tn = decl?.type
            if (tn is TypeReference && tn.typeName is QualifiedName && tn.typeArguments.isNullOrEmpty()) {
                formatTypeReferenceName(tn.typeName) ?: formatTypeForDisplay(tn) ?: "any"
            } else {
                tn?.let { formatTypeForDisplay(it) } ?: "any"
            }
        } else {
            resolvedType.let { if (it === anyType) "any" else typeToString(it) }
        }
        return when {
            decl?.dotDotDotToken == true -> "...$displayName: $pType"
            decl?.questionToken == true -> {
                // 17.15a: Drop `| undefined` when the param type is a function/constructor
                // type — the form `name?: T => U | undefined` would parse as a function
                // returning `U | undefined`. TypeScript's display convention drops
                // `| undefined` for fn-type params to avoid the precedence ambiguity.
                val isFnType = decl.type is FunctionType || decl.type is ConstructorType ||
                    (resolvedType is Type.Object && resolvedType !is Type.Reference &&
                        resolvedType !is Type.Interface &&
                        resolvedType.symbol == null &&
                        !resolvedType.callSignatures.isNullOrEmpty() &&
                        resolvedType.properties.isNullOrEmpty())
                if (isFnType) "$displayName?: $pType" else "$displayName?: $pType | undefined"
            }
            else -> "$displayName: $pType"
        }
    }

    /**
     * B9.5: Reconstruct a binding-pattern parameter's display string from its AST.
     * Used by `formatParameter` and `signatureToString(sig)` to render parameters
     * declared with ObjectBindingPattern / ArrayBindingPattern names as their
     * source-equivalent (e.g. `{ [foo.bar]: c }`, `[a, b]`, `{ a, b: renamed }`).
     * For AST shapes outside the supported set, returns `_` (the pre-B9.5
     * fallback) so display strings degrade gracefully.
     */
    private fun formatBindingPatternFromAst(node: Node): String = when (node) {
        is ObjectBindingPattern -> {
            val parts = node.elements.map { formatBindingElementFromAst(it) }
            if (parts.isEmpty()) "{}" else "{ ${parts.joinToString(", ")} }"
        }
        is ArrayBindingPattern -> {
            val parts = node.elements.map { e ->
                when (e) {
                    is BindingElement -> formatBindingElementFromAst(e)
                    is OmittedExpression -> ""
                    else -> "_"
                }
            }
            "[${parts.joinToString(", ")}]"
        }
        else -> "_"
    }

    private fun formatBindingElementFromAst(el: BindingElement): String {
        val nameStr = when (val n = el.name) {
            is Identifier -> n.text
            is ObjectBindingPattern, is ArrayBindingPattern -> formatBindingPatternFromAst(n as Node)
            else -> "_"
        }
        val dotDot = if (el.dotDotDotToken) "..." else ""
        val propName = el.propertyName
        return when {
            propName == null -> "$dotDot$nameStr"
            propName is Identifier && el.name is Identifier && propName.text == (el.name as Identifier).text ->
                "$dotDot$nameStr"
            propName is Identifier -> "${propName.text}: $dotDot$nameStr"
            propName is StringLiteralNode -> "\"${propName.text}\": $dotDot$nameStr"
            propName is NumericLiteralNode -> "${propName.text}: $dotDot$nameStr"
            propName is ComputedPropertyName -> {
                val inner = formatExprForBindingDisplay(propName.expression) ?: return "_"
                "[$inner]: $dotDot$nameStr"
            }
            else -> "_"
        }
    }

    private fun formatExprForBindingDisplay(expr: Expression): String? = when (expr) {
        is Identifier -> expr.text
        is StringLiteralNode -> "\"${expr.text}\""
        is NumericLiteralNode -> expr.text
        is BigIntLiteralNode -> expr.text
        is NoSubstitutionTemplateLiteralNode -> "`${expr.text}`"
        is PropertyAccessExpression -> {
            val left = formatExprForBindingDisplay(expr.expression) ?: return null
            "$left.${expr.name.text}"
        }
        is ElementAccessExpression -> {
            val left = formatExprForBindingDisplay(expr.expression) ?: return null
            val arg = formatExprForBindingDisplay(expr.argumentExpression) ?: return null
            "$left[$arg]"
        }
        is ParenthesizedExpression -> formatExprForBindingDisplay(expr.expression)
        is PrefixUnaryExpression -> {
            if ((expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) &&
                (expr.operand is NumericLiteralNode || expr.operand is BigIntLiteralNode)) {
                val op = if (expr.operator == SyntaxKind.Minus) "-" else "+"
                "$op${formatExprForBindingDisplay(expr.operand)}"
            } else null
        }
        else -> null
    }

    /** 17.10c: Format a Type.TypeParam as `name` or `name extends Constraint`. */
    private fun typeParamToString(tp: Type.TypeParam): String {
        val name = tp.symbol?.name ?: "T"
        val cons = tp.constraint
        return if (cons != null && cons !== errorType) "$name extends ${typeToString(cons)}" else name
    }

    /**
     * Extract the `this:` parameter declaration from a Signature's declaration AST,
     * if present. TypeScript's display format includes `this: T` as the first parameter
     * for function types declared with a `this`-typed pseudo-parameter.
     */
    private fun extractThisParam(sig: Signature): String? {
        val decl = sig.declaration ?: return null
        val astParams: List<Parameter> = when (decl) {
            is FunctionExpression -> decl.parameters
            is ArrowFunction -> decl.parameters
            is FunctionDeclaration -> decl.parameters
            is MethodDeclaration -> decl.parameters
            is FunctionType -> decl.parameters
            is ConstructorType -> decl.parameters
            else -> return null
        }
        val first = astParams.firstOrNull() ?: return null
        if ((first.name as? Identifier)?.text != "this") return null
        val typeStr = first.type?.let { formatTypeForDisplay(it) } ?: "any"
        return "this: $typeStr"
    }

    /** Format a signature as a string like `(x: number) => string` or `new (x: number) => Foo`. */
    private fun signatureToString(sig: Signature, isConstruct: Boolean): String {
        val prefix = if (isConstruct) {
            if (sig.isAbstract) "abstract new " else "new "
        } else ""
        val tps = sig.typeParameters
        val tpStr = if (!tps.isNullOrEmpty()) {
            "<${tps.joinToString(", ") { typeParamToString(it) }}>"
        } else ""
        val thisStr = extractThisParam(sig)
        val paramParts = sig.parameters.map { formatParameter(it) }
        val params = (if (thisStr != null) listOf(thisStr) + paramParts else paramParts).joinToString(", ")
        val retType = sig.resolvedReturnType?.let { typeToString(it) } ?: "any"
        return "$prefix$tpStr($params) => $retType"
    }

    /** Format a signature using colon notation like `(x: number): string` for use in `{ }` blocks. */
    private fun signatureToStringColon(sig: Signature, isConstruct: Boolean): String {
        val prefix = if (isConstruct) {
            if (sig.isAbstract) "abstract new " else "new "
        } else ""
        val tps = sig.typeParameters
        val tpStr = if (!tps.isNullOrEmpty()) {
            "<${tps.joinToString(", ") { typeParamToString(it) }}>"
        } else ""
        val thisStr = extractThisParam(sig)
        val paramParts = sig.parameters.map { formatParameter(it) }
        val params = (if (thisStr != null) listOf(thisStr) + paramParts else paramParts).joinToString(", ")
        val retType = sig.resolvedReturnType?.let { typeToString(it) } ?: "any"
        return "$prefix$tpStr($params): $retType"
    }

    private fun typeToString(type: Type): String {
        // B50.2: alias-display preservation. When a Type was produced by the B50.1
        // generic-alias-substitution path, render with the alias name + arg display
        // instead of the structural form. Recursion guarded via [typeToStringInProgress].
        if (type.id !in typeToStringInProgress) {
            aliasDisplayMap[type.id]?.let { (aliasName, aliasArgs) ->
                typeToStringInProgress.add(type.id)
                try {
                    return if (aliasArgs.isNotEmpty()) {
                        "$aliasName<${aliasArgs.joinToString(", ") { typeToString(it) }}>"
                    } else aliasName
                } finally {
                    typeToStringInProgress.remove(type.id)
                }
            }
        }
        return when (type) {
            // B58.1: render errorType as "any" (matches TypeScript's display behavior;
            // TypeScript doesn't expose an "error" type name in diagnostics — when type
            // resolution fails, the slot is shown as `any`).
            is Type.Intrinsic -> when {
                type === errorType -> "any"
                // B65.1: template-literal-type-sourced intrinsic — render source text.
                templateLiteralDisplay[type.id] != null -> templateLiteralDisplay[type.id]!!
                else -> type.intrinsicName
            }
            is Type.StringLiteral -> "\"${type.value}\""
            is Type.NumberLiteral -> type.toString()
            is Type.BigIntLiteral -> type.toString()
            // Interface and Reference must be checked BEFORE Object (they extend Object)
            is Type.Interface -> {
                val name = type.symbol?.name ?: "Interface"
                val tps = type.typeParameters
                if (tps != null && tps.isNotEmpty()) {
                    // B60.9: when each TypeParam has a default, render the defaults
                    // instead of the TypeParam names. Matches TypeScript's display
                    // of `Table = TableClass` (where `class TableClass<S = any>`)
                    // as `TableClass<any>` not `TableClass<S>`.
                    "$name<${tps.joinToString(", ") { tp -> tp.default?.let { typeToString(it) } ?: tp.symbol?.name ?: "T" }}>"
                } else name
            }
            is Type.Reference -> {
                val args = type.resolvedTypeArguments
                // Array types display as T[] (not Array<T>)
                if (type.target === globalArrayType && args != null && args.size == 1) {
                    val elemStr = typeToString(args[0])
                    // Parenthesize union/intersection element types: (A | B)[] not A | B[]
                    if (args[0] is Type.Union || args[0] is Type.Intersection) "($elemStr)[]"
                    else "$elemStr[]"
                } else if (globalReadonlyArrayType != null &&
                    type.target === globalReadonlyArrayType && args != null && args.size == 1) {
                    // ReadonlyArray<T> displays as `readonly T[]` (shorthand) to match TypeScript.
                    val elemStr = typeToString(args[0])
                    if (args[0] is Type.Union || args[0] is Type.Intersection) "readonly ($elemStr)[]"
                    else "readonly $elemStr[]"
                } else {
                    val target = type.target.symbol?.name ?: "Object"
                    if (args != null && args.isNotEmpty()) {
                        "$target<${args.joinToString(", ") { typeToString(it) }}>"
                    } else target
                }
            }
            is Type.Object -> {
                // Tuple type: display as [T1, T2, ...]
                val tupleElems = type.tupleElementTypes
                if (tupleElems != null) {
                    return "[${tupleElems.joinToString(", ") { typeToString(it) }}]"
                }
                val callSigs = type.callSignatures
                val ctorSigs = type.constructSignatures
                val hasSignatures = !callSigs.isNullOrEmpty() || !ctorSigs.isNullOrEmpty()
                val hasProperties = !type.properties.isNullOrEmpty()
                // When type has BOTH signatures AND properties, use object literal format
                // e.g. { (): string; prop: number; }
                if (hasSignatures && hasProperties) {
                    val parts = mutableListOf<String>()
                    callSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = false)) }
                    ctorSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = true)) }
                    val props = type.properties!!
                    for (p in props) {
                        val propType = symbolTypes[p.id]
                        parts.add("${p.name}: ${if (propType != null) typeToString(propType) else "any"}")
                    }
                    "{ ${parts.joinToString("; ")}; }"
                } else if (hasSignatures) {
                    val totalSigs = (callSigs?.size ?: 0) + (ctorSigs?.size ?: 0)
                    if (totalSigs == 1) {
                        // Single signature: arrow format
                        if (!callSigs.isNullOrEmpty()) signatureToString(callSigs.first(), isConstruct = false)
                        else signatureToString(ctorSigs!!.first(), isConstruct = true)
                    } else {
                        // Multiple signatures: object format { (sig): ret; ... }
                        val parts = mutableListOf<String>()
                        callSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = false)) }
                        ctorSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = true)) }
                        "{ ${parts.joinToString("; ")}; }"
                    }
                } else {
                    val sym = type.symbol
                    if (sym != null) sym.name
                    else {
                        // Anonymous object type — format as { prop: type; ... }
                        val parts = mutableListOf<String>()
                        // Index signatures first
                        type.stringIndexInfo?.let { info ->
                            val readonly = if (info.isReadonly) "readonly " else ""
                            val paramName = (info.declaration as? IndexSignature)?.parameters?.firstOrNull()
                                ?.let { (it.name as? Identifier)?.text } ?: "x"
                            parts.add("${readonly}[$paramName: string]: ${typeToString(info.type)}")
                        }
                        type.numberIndexInfo?.let { info ->
                            val readonly = if (info.isReadonly) "readonly " else ""
                            val paramName = (info.declaration as? IndexSignature)?.parameters?.firstOrNull()
                                ?.let { (it.name as? Identifier)?.text } ?: "x"
                            parts.add("${readonly}[$paramName: number]: ${typeToString(info.type)}")
                        }
                        // Properties
                        val props = type.properties
                        if (props != null) {
                            for (p in props) {
                                val propType = symbolTypes[p.id]
                                val typeStr = if (propType != null) typeToString(propType) else "any"
                                val displayName = formatPropertyDisplayName(p)
                                // 16.0: Optional properties render as `name?: type | undefined`
                                // matching TypeScript's display convention.
                                if (isOptionalProperty(p)) {
                                    parts.add("$displayName?: $typeStr | undefined")
                                } else {
                                    parts.add("$displayName: $typeStr")
                                }
                            }
                        }
                        if (parts.isNotEmpty()) "{ ${parts.joinToString("; ")}; }" else "{}"
                    }
                }
            }
            is Type.Union -> {
                // TypeScript convention: nullish (null/undefined/void) members render LAST,
                // function/constructor-typed members render parenthesized so the `|` is unambiguous.
                fun nullishRank(t: Type): Int = when {
                    t is Type.Intrinsic && t.intrinsicName == "null" -> 1
                    t is Type.Intrinsic && t.intrinsicName == "undefined" -> 2
                    t is Type.Intrinsic && t.intrinsicName == "void" -> 3
                    else -> 0
                }
                val ordered = type.types.sortedBy { nullishRank(it) }
                ordered.joinToString(" | ") { m ->
                    val s = typeToString(m)
                    val needsParen = m is Type.Object &&
                        m.tupleElementTypes == null &&
                        m.properties.isNullOrEmpty() &&
                        ((m.callSignatures?.size ?: 0) + (m.constructSignatures?.size ?: 0)) == 1
                    if (needsParen) "($s)" else s
                }
            }
            is Type.Intersection -> type.types.joinToString(" & ") { typeToString(it) }
            is Type.TypeParam -> type.symbol?.name ?: "T"
        }
    }

    /**
     * 17.29: Like [typeToString], but qualifies named class/interface types nested inside
     * namespaces with their containing namespace path (e.g. `m.variable` instead of `variable`).
     * Walks `symbol.parent` while the parent is a Module/NamespaceModule symbol. Falls back to
     * [typeToString] for non-Interface types and for Interface types whose symbol has no
     * namespace parent. Used in the 17.29 same-name-different-scope class arg-mismatch path
     * so display matches TypeScript's qualified rendering for namespace-nested classes.
     */
    private fun typeToStringQualified(type: Type): String {
        if (type !is Type.Interface) return typeToString(type)
        val sym = type.symbol ?: return typeToString(type)
        if (sym.parent == null) return typeToString(type)
        val segments = mutableListOf(sym.name)
        var cur = sym.parent
        while (cur != null && cur.flags.hasAny(SymbolFlags.Module or SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)) {
            segments.add(0, cur.name)
            cur = cur.parent
        }
        if (segments.size == 1) return typeToString(type)
        val tps = type.typeParameters
        val name = segments.joinToString(".")
        return if (tps != null && tps.isNotEmpty()) {
            "$name<${tps.joinToString(", ") { it.symbol?.name ?: "T" }}>"
        } else name
    }

    // -----------------------------------------------------------------------
    // TS2394: Overload signature not compatible with implementation
    // -----------------------------------------------------------------------

    private fun checkOverloadSignatureCompatibility() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkOverloadsInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkOverloadsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        // Group function declarations by name
        val funcGroups = mutableMapOf<String, MutableList<FunctionDeclaration>>()
        for (stmt in stmts) {
            if (stmt is FunctionDeclaration && stmt.name != null) {
                funcGroups.getOrPut(stmt.name!!.text) { mutableListOf() }.add(stmt)
            }
        }

        for ((name, decls) in funcGroups) {
            val impl = decls.firstOrNull { it.body != null } ?: continue
            val overloads = decls.filter { it.body == null }
            if (overloads.isEmpty()) continue

            // 17.208: TS2384 (ambient/non-ambient) and TS2383 (export/non-export)
            // for function overload groups. Compare each overload to the impl;
            // emit on the OVERLOAD whose modifier disagrees with the impl.
            val implAmbient = ModifierFlag.Declare in impl.modifiers
            val implExported = ModifierFlag.Export in impl.modifiers
            for (overload in overloads) {
                val nameNode = overload.name ?: continue
                val olAmbient = ModifierFlag.Declare in overload.modifiers
                val olExported = ModifierFlag.Export in overload.modifiers
                if (olAmbient != implAmbient) {
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Overload signatures must all be ambient or non-ambient.",
                        category = DiagnosticCategory.Error,
                        code = 2384,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = nameNode.pos,
                        length = nameNode.text.length,
                    ))
                }
                if (olExported != implExported) {
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Overload signatures must all be exported or non-exported.",
                        category = DiagnosticCategory.Error,
                        code = 2383,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = nameNode.pos,
                        length = nameNode.text.length,
                    ))
                }
            }

            for ((idx, overload) in overloads.withIndex()) {
                // Skip duplicate overloads (same param types as a previously-reported one)
                if (idx > 0 && isDuplicateOverload(overload, overloads[idx - 1])) continue
                if (!isOverloadCompatibleWithImpl(overload, impl)) {
                    val nameNode = overload.name ?: continue
                    val start = nameNode.pos
                    val length = nameNode.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val implNameNode = impl.name ?: continue
                    val implStart = implNameNode.pos
                    val (implLine, implChar) = getLineAndCharacterOfPosition(source, implStart)
                    diagnostics.add(Diagnostic(
                        message = "This overload signature is not compatible with its implementation signature.",
                        category = DiagnosticCategory.Error,
                        code = 2394,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        relatedInformation = listOf(Diagnostic(
                            message = "The implementation signature is declared here.",
                            category = DiagnosticCategory.Message,
                            code = 2750,
                            fileName = fileName,
                            line = implLine,
                            character = implChar,
                            start = implStart,
                            length = implNameNode.text.length,
                        )),
                    ))
                    // TypeScript reports TS2394 once per overload group, on the first
                    // incompatible signature. Subsequent overloads in the same group
                    // (whether same root cause or different) are not flagged.
                    break
                }
            }
        }

        // Recurse into nested blocks
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Check method overloads in classes
                    checkMethodOverloadsInClass(stmt.members, source, fileName)
                    checkMultipleConstructorImpls(stmt.members, source, fileName)
                    checkConstructorOverloadCompatibility(stmt.members, source, fileName)
                }
                is Block -> checkOverloadsInStatements(stmt.statements, source, fileName)
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                    checkOverloadsInStatements(it.statements, source, fileName)
                }
                is InterfaceDeclaration -> checkInterfaceMemberOptionalOverloads(stmt.members, source, fileName)
                is FunctionDeclaration -> stmt.body?.let { checkOverloadsInStatements(it.statements, source, fileName) }
                is IfStatement -> {
                    checkOverloadsInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkOverloadsInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkOverloadsInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkOverloadsInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkOverloadsInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkOverloadsInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkOverloadsInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkOverloadsInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // B76.1: TS1235 — namespace declaration only allowed at top level
    // -----------------------------------------------------------------------

    /**
     * TS1235: "A namespace declaration is only allowed at the top level of a
     * namespace or module."
     *
     * Fires for `namespace X { ... }` (and the deprecated `module X { ... }`
     * identifier form) when found inside a non-top-level lexical context —
     * function bodies, blocks, control-flow constructs, etc. The top-level of
     * a file and the bodies of other namespace declarations are allowed.
     */
    private fun checkNamespaceTopLevelOnly() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Top-level statements: recurse into namespace bodies (still top-level
            // for this purpose), but flag any namespace found via the non-top
            // recursion path. Use sibling-aware iteration so legacy `module {`
            // / `declare module {` anonymous-namespace bodies are skipped.
            walkSiblingsForTopLevel(result.sourceFile.statements, source, fileName, atTopLevel = true)
        }
    }

    private fun isJsLikeFile(fileName: String): Boolean =
        fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
            fileName.endsWith(".mjs") || fileName.endsWith(".cjs")

    /**
     * Walk a list of sibling statements, recursing into each one with
     * [walkNamespaceTopLevel] at the given [atTopLevel]. Skips Blocks that
     * appear immediately after a bare `module` / `namespace` / `declare`
     * identifier expression statement (legacy anonymous-namespace syntax
     * `module { ... }` / `declare module { ... }` — these are NOT real
     * statement blocks; TypeScript treats their body content as ambient
     * namespace contents and does not emit TS1231/1232/1233/1234/1258/1184
     * inside them).
     */
    private fun walkSiblingsForTopLevel(stmts: List<Statement>, source: String, fileName: String, atTopLevel: Boolean) {
        var i = 0
        while (i < stmts.size) {
            val stmt = stmts[i]
            val isLegacyAnonModuleBlock = stmt is Block &&
                i > 0 &&
                isBareModuleLikeIdentExprStmt(stmts[i - 1])
            if (!isLegacyAnonModuleBlock) {
                walkNamespaceTopLevel(stmt, source, fileName, atTopLevel)
            }
            i++
        }
    }

    private fun isBareModuleLikeIdentExprStmt(stmt: Statement): Boolean {
        if (stmt !is ExpressionStatement) return false
        val ident = stmt.expression as? Identifier ?: return false
        return ident.text == "module" || ident.text == "namespace" || ident.text == "declare"
    }

    /**
     * Find the source offset of a specific keyword (`export`, `import`, `declare`,
     * `namespace`, `module`) starting at or after [startPos]. Only matches as a
     * word boundary (preceded by non-letter, followed by non-letter). Returns
     * null if not found within the next 64 chars (defensive cap to avoid
     * scanning past the statement end in pathological cases).
     */
    private fun findKeywordPos(source: String, startPos: Int, keyword: String): Int? {
        var i = startPos
        val limit = minOf(source.length, startPos + 64)
        while (i + keyword.length <= limit) {
            if (source.regionMatches(i, keyword, 0, keyword.length)) {
                val before = if (i == 0) ' ' else source[i - 1]
                val after = if (i + keyword.length >= source.length) ' ' else source[i + keyword.length]
                if (!before.isLetterOrDigit() && before != '_' && before != '$' &&
                    !after.isLetterOrDigit() && after != '_' && after != '$') {
                    return i
                }
            }
            i++
        }
        return null
    }

    /**
     * Scan backwards from [startPos] (exclusive) up to 64 chars looking for
     * [keyword] as a word-boundary match. Used to locate `declare` keyword
     * before a `ModuleDeclaration.pos` (which points at `module`/`namespace`,
     * not the leading `declare` consumed in parseDeclareDeclaration).
     */
    private fun findKeywordPosBackward(source: String, startPos: Int, keyword: String): Int? {
        val lowerLimit = maxOf(0, startPos - 64)
        var i = startPos - keyword.length
        while (i >= lowerLimit) {
            if (source.regionMatches(i, keyword, 0, keyword.length)) {
                val before = if (i == 0) ' ' else source[i - 1]
                val after = if (i + keyword.length >= source.length) ' ' else source[i + keyword.length]
                if (!before.isLetterOrDigit() && before != '_' && before != '$' &&
                    !after.isLetterOrDigit() && after != '_' && after != '$') {
                    return i
                }
            }
            i--
        }
        return null
    }

    private fun walkNamespaceTopLevel(stmt: Statement, source: String, fileName: String, atTopLevel: Boolean) {
        when (stmt) {
            is ModuleDeclaration -> {
                // Ambient `declare namespace X { }` is allowed anywhere (e.g.
                // module augmentations and ambient blocks may nest). Skip when
                // declare modifier is present (but NOT for string-named modules
                // — those get TS1234 instead).
                val isAmbient = ModifierFlag.Declare in stmt.modifiers ||
                    stmt.body == null
                // String-literal-named modules (`declare module "X" { }`) are
                // ambient module declarations — TS1234 if non-top-level.
                val isStringModule = stmt.name is StringLiteralNode
                if (!atTopLevel && isStringModule) {
                    // B76.2: TS1234 — ambient module declaration only allowed
                    // at top level of a file. Squiggle at `declare` keyword (length 7).
                    // ModuleDeclaration.pos is at the `module` keyword (parseDeclareDeclaration
                    // already consumed `declare` before delegating). Scan backwards to find it.
                    val declarePos = findKeywordPosBackward(source, stmt.pos, "declare") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, declarePos)
                    diagnostics.add(Diagnostic(
                        message = "An ambient module declaration is only allowed at the top level in a file.",
                        category = DiagnosticCategory.Error,
                        code = 1234,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = declarePos,
                        length = 7,
                    ))
                } else if (!atTopLevel && !isAmbient && !isStringModule) {
                    // For `export namespace N`, the squiggle covers `export`
                    // (length 6) — scan backward from stmt.pos (which points at
                    // `namespace` since parseExportDeclaration delegated to
                    // parseModuleDeclaration after consuming `export`). For
                    // plain `namespace M`, squiggle covers `namespace` (length 9)
                    // at stmt.pos.
                    val (start, length) = if (ModifierFlag.Export in stmt.modifiers) {
                        val exportPos = findKeywordPosBackward(source, stmt.pos, "export") ?: stmt.pos
                        exportPos to 6
                    } else stmt.pos to 9
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "A namespace declaration is only allowed at the top level of a namespace or module.",
                        category = DiagnosticCategory.Error,
                        code = 1235,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                // Recurse into body — namespace bodies are "top level" for nested namespaces.
                (stmt.body as? ModuleBlock)?.let { block ->
                    walkSiblingsForTopLevel(block.statements, source, fileName, atTopLevel = true)
                }
            }
            is ExportAssignment -> {
                if (!atTopLevel) {
                    val exportPos = findKeywordPos(source, stmt.pos, "export") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    // B76.2: TS1258 for `export default ...`, TS1231 for `export = ...`.
                    val isDefault = ModifierFlag.Default in stmt.modifiers && !stmt.isExportEquals
                    if (isDefault) {
                        diagnostics.add(Diagnostic(
                            message = "A default export must be at the top level of a file or module declaration.",
                            category = DiagnosticCategory.Error,
                            code = 1258,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exportPos,
                            length = 6, // "export"
                        ))
                    } else {
                        diagnostics.add(Diagnostic(
                            message = "An export assignment must be at the top level of a file or module declaration.",
                            category = DiagnosticCategory.Error,
                            code = 1231,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exportPos,
                            length = 6, // "export"
                        ))
                    }
                }
            }
            is ExportDeclaration -> {
                if (!atTopLevel) {
                    val exportPos = findKeywordPos(source, stmt.pos, "export") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    diagnostics.add(Diagnostic(
                        message = "An export declaration can only be used at the top level of a namespace or module.",
                        category = DiagnosticCategory.Error,
                        code = 1233,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = exportPos,
                        length = 6, // "export"
                    ))
                }
            }
            is ImportDeclaration -> {
                // TS1232 fires for .ts/.tsx files; .js/.jsx files use TS1473
                // (emitted by checkImportNotAtTopLevel). Avoid double-emission.
                if (!atTopLevel && !isJsLikeFile(fileName)) {
                    val importPos = findKeywordPos(source, stmt.pos, "import") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, importPos)
                    diagnostics.add(Diagnostic(
                        message = "An import declaration can only be used at the top level of a namespace or module.",
                        category = DiagnosticCategory.Error,
                        code = 1232,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = importPos,
                        length = 6, // "import"
                    ))
                }
            }
            is ImportEqualsDeclaration -> {
                if (!atTopLevel && !isJsLikeFile(fileName)) {
                    val importPos = findKeywordPos(source, stmt.pos, "import") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, importPos)
                    diagnostics.add(Diagnostic(
                        message = "An import declaration can only be used at the top level of a namespace or module.",
                        category = DiagnosticCategory.Error,
                        code = 1232,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = importPos,
                        length = 6, // "import"
                    ))
                }
            }
            is FunctionDeclaration -> {
                // B76.2: TS1184 — `export` / `export default` modifiers on
                // FunctionDeclaration at non-top-level position. Squiggle at
                // `export` keyword (length 6). FunctionDeclaration.pos is at
                // `function` (parseExportDeclaration delegated after consuming
                // `export`), so scan backward to locate the `export`.
                if (!atTopLevel && ModifierFlag.Export in stmt.modifiers) {
                    val exportPos = findKeywordPosBackward(source, stmt.pos, "export") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    diagnostics.add(Diagnostic(
                        message = "Modifiers cannot appear here.",
                        category = DiagnosticCategory.Error,
                        code = 1184,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = exportPos,
                        length = 6, // "export"
                    ))
                }
                stmt.body?.let { body ->
                    // Skip recursion when the body is malformed (missing `}` —
                    // detected by closeBracePos either being -1 or landing
                    // at/past EOF). The parser already emitted TS1005 and
                    // TypeScript suppresses further nested-context diagnostics
                    // (e.g. exportInFunction.ts: only TS1005 expected).
                    if (body.closeBracePos < 0 || body.closeBracePos >= source.length) return@let
                    walkSiblingsForTopLevel(body.statements, source, fileName, atTopLevel = false)
                }
            }
            is ClassDeclaration -> {
                // B76.2: TS1184 — `export` / `export default` modifiers on
                // ClassDeclaration at non-top-level position. ClassDeclaration.pos
                // is at `class` (parseExportDeclaration delegated after consuming
                // `export`), so scan backward to locate the `export`.
                if (!atTopLevel && ModifierFlag.Export in stmt.modifiers) {
                    val exportPos = findKeywordPosBackward(source, stmt.pos, "export") ?: stmt.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    diagnostics.add(Diagnostic(
                        message = "Modifiers cannot appear here.",
                        category = DiagnosticCategory.Error,
                        code = 1184,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = exportPos,
                        length = 6, // "export"
                    ))
                }
                // Class methods/getters/setters/constructors have function bodies
                // — namespace declarations inside them are not at the top level.
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { b ->
                            walkSiblingsForTopLevel(b.statements, source, fileName, atTopLevel = false)
                        }
                        is Constructor -> member.body?.let { b ->
                            walkSiblingsForTopLevel(b.statements, source, fileName, atTopLevel = false)
                        }
                        is GetAccessor -> member.body?.let { b ->
                            walkSiblingsForTopLevel(b.statements, source, fileName, atTopLevel = false)
                        }
                        is SetAccessor -> member.body?.let { b ->
                            walkSiblingsForTopLevel(b.statements, source, fileName, atTopLevel = false)
                        }
                        else -> {}
                    }
                }
            }
            is Block -> {
                walkSiblingsForTopLevel(stmt.statements, source, fileName, atTopLevel = false)
            }
            is IfStatement -> {
                walkNamespaceTopLevel(stmt.thenStatement, source, fileName, atTopLevel = false)
                stmt.elseStatement?.let { walkNamespaceTopLevel(it, source, fileName, atTopLevel = false) }
            }
            is ForStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            is ForInStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            is ForOfStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            is WhileStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            is DoStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (inner in clause.statements) walkNamespaceTopLevel(inner, source, fileName, atTopLevel = false)
                        is DefaultClause -> for (inner in clause.statements) walkNamespaceTopLevel(inner, source, fileName, atTopLevel = false)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (inner in stmt.tryBlock.statements) walkNamespaceTopLevel(inner, source, fileName, atTopLevel = false)
                stmt.catchClause?.block?.statements?.forEach { walkNamespaceTopLevel(it, source, fileName, atTopLevel = false) }
                stmt.finallyBlock?.statements?.forEach { walkNamespaceTopLevel(it, source, fileName, atTopLevel = false) }
            }
            is LabeledStatement -> walkNamespaceTopLevel(stmt.statement, source, fileName, atTopLevel = false)
            else -> {}
        }
    }

    /**
     * 17.208: TS2386 — within an interface, method overloads grouped by name
     * must all agree on the optional `?` token. When the group spans both
     * optional and required signatures, emit TS2386 on each member whose
     * `questionToken` differs from the FIRST member in the group.
     */
    private fun checkInterfaceMemberOptionalOverloads(members: List<ClassElement>, source: String, fileName: String) {
        val methodGroups = mutableMapOf<String, MutableList<MethodDeclaration>>()
        for (m in members) {
            if (m is MethodDeclaration) {
                val name = when (val n = m.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> continue
                }
                methodGroups.getOrPut(name) { mutableListOf() }.add(m)
            }
        }
        for ((_, decls) in methodGroups) {
            if (decls.size < 2) continue
            val firstOptional = decls.first().questionToken
            for (md in decls.drop(1)) {
                if (md.questionToken == firstOptional) continue
                val nameNode = md.name
                val nameText = when (nameNode) {
                    is Identifier -> nameNode.text
                    is StringLiteralNode -> nameNode.text
                    else -> continue
                }
                val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Overload signatures must all be optional or required.",
                    category = DiagnosticCategory.Error,
                    code = 2386,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = nameNode.pos,
                    length = nameText.length,
                ))
            }
        }
    }

    /**
     * Emit TS2392 "Multiple constructor implementations are not allowed." when a class has 2+
     * constructors with bodies. TypeScript allows 1 implementation + N overload signatures
     * (signatures have no body). When 2+ implementations exist, TS2392 fires on EVERY
     * constructor declaration in the class — including the body-less overload signatures —
     * because the overload pair model becomes invalid as a whole.
     * Squiggle covers the `constructor` keyword.
     */
    private fun checkMultipleConstructorImpls(members: List<ClassElement>, source: String, fileName: String) {
        val ctors = members.filterIsInstance<Constructor>()
        val impls = ctors.filter { it.body != null }
        if (impls.size < 2) return
        val keyword = "constructor"
        for (ctor in ctors) {
            val kwStart = source.indexOf(keyword, startIndex = ctor.pos).takeIf { it >= 0 && it < ctor.end } ?: continue
            val (line, character) = getLineAndCharacterOfPosition(source, kwStart)
            diagnostics.add(Diagnostic(
                message = "Multiple constructor implementations are not allowed.",
                category = DiagnosticCategory.Error,
                code = 2392,
                fileName = fileName,
                line = line,
                character = character,
                start = kwStart,
                length = keyword.length,
            ))
        }
    }

    /**
     * 17.211: TS2394 — overload constructor signature must be compatible with
     * the implementation. Mirrors `checkMethodOverloadsInClass`'s arity check
     * (impl's required-arg count ≤ overload's total params) but for ctors.
     * Squiggle covers the `constructor` keyword on the overload (length 11).
     * Skip when there's no impl or when there are 2+ impls (TS2392 fires).
     *
     * Also handles TS2300 for duplicate parameter-property names: when the
     * overload AND the impl both declare a parameter property with the same
     * name, the parameter property creates a class field both times. The
     * resulting duplicate field declaration emits TS2300 on the impl's
     * parameter name (TypeScript's chosen position for the second
     * declaration).
     */
    private fun checkConstructorOverloadCompatibility(members: List<ClassElement>, source: String, fileName: String) {
        val ctors = members.filterIsInstance<Constructor>()
        val impls = ctors.filter { it.body != null }
        if (impls.size != 1) return
        val impl = impls[0]
        val overloads = ctors.filter { it.body == null }
        if (overloads.isEmpty()) return
        val keyword = "constructor"
        for (overload in overloads) {
            if (isSignatureCompatible(overload.parameters, null, impl.parameters, null)) continue
            val kwStart = source.indexOf(keyword, startIndex = overload.pos).takeIf { it >= 0 && it < overload.end } ?: continue
            val (line, character) = getLineAndCharacterOfPosition(source, kwStart)
            val implKwStart = source.indexOf(keyword, startIndex = impl.pos).takeIf { it >= 0 && it < impl.end } ?: continue
            val (implLine, implChar) = getLineAndCharacterOfPosition(source, implKwStart)
            diagnostics.add(Diagnostic(
                message = "This overload signature is not compatible with its implementation signature.",
                category = DiagnosticCategory.Error,
                code = 2394,
                fileName = fileName,
                line = line,
                character = character,
                start = kwStart,
                length = keyword.length,
                relatedInformation = listOf(Diagnostic(
                    message = "The implementation signature is declared here.",
                    category = DiagnosticCategory.Message,
                    code = 2750,
                    fileName = fileName,
                    line = implLine,
                    character = implChar,
                    start = implKwStart,
                    length = keyword.length,
                )),
            ))
            // TypeScript reports TS2394 once per overload group, on the first
            // incompatible signature. Mirror the method-overload behavior.
            break
        }
        // 17.211: TS2300 for duplicate parameter-property names across an
        // overload + impl pair. Only the IMPL position is squiggled (matches
        // TypeScript's baseline behavior: second declaration gets the
        // diagnostic).
        for (overload in overloads) {
            val overloadPropNames = overload.parameters
                .filter { isParameterProperty(it) && it.name is Identifier }
                .map { (it.name as Identifier).text }
                .toSet()
            for (implParam in impl.parameters) {
                if (!isParameterProperty(implParam)) continue
                val implName = implParam.name as? Identifier ?: continue
                if (implName.text !in overloadPropNames) continue
                val (line, character) = getLineAndCharacterOfPosition(source, implName.pos)
                diagnostics.add(Diagnostic(
                    message = "Duplicate identifier '${implName.text}'.",
                    category = DiagnosticCategory.Error,
                    code = 2300,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = implName.pos,
                    length = implName.text.length,
                ))
            }
        }
    }

    private fun checkMethodOverloadsInClass(members: List<ClassElement>, source: String, fileName: String) {
        // Group methods by name
        val methodGroups = mutableMapOf<String, MutableList<MethodDeclaration>>()
        for (member in members) {
            if (member is MethodDeclaration) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> continue
                }
                methodGroups.getOrPut(name) { mutableListOf() }.add(member)
            }
        }

        for ((name, decls) in methodGroups) {
            // 17.177: TS2385 — overload signatures must agree on access
            // modifier (public/private/protected). Compute the access flag
            // for each declaration; treat absence as "public" (the implicit
            // default). When the group spans more than one access level,
            // emit TS2385 on the FIRST overload's name. Fires regardless of
            // whether an implementation exists in the group.
            if (decls.size >= 2) {
                fun accessOf(md: MethodDeclaration): String = when {
                    ModifierFlag.Private in md.modifiers -> "private"
                    ModifierFlag.Protected in md.modifiers -> "protected"
                    else -> "public"
                }
                val distinctAccess = decls.map { accessOf(it) }.toSet()
                if (distinctAccess.size > 1) {
                    val first = decls.first()
                    val nameNode = first.name
                    val nameText = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> null
                    }
                    if (nameText != null) {
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Overload signatures must all be public, private or protected.",
                            category = DiagnosticCategory.Error,
                            code = 2385,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = nameText.length,
                        ))
                    }
                }
            }
            val impl = decls.firstOrNull { it.body != null } ?: continue
            val overloads = decls.filter { it.body == null }
            if (overloads.isEmpty()) continue

            for (overload in overloads) {
                if (!isMethodOverloadCompatibleWithImpl(overload, impl)) {
                    val nameNode = overload.name
                    val nameText = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> continue
                    }
                    val start = nameNode.pos
                    val length = nameText.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val implNameNode = impl.name
                    val implStart = implNameNode.pos
                    val implText = when (implNameNode) {
                        is Identifier -> implNameNode.text
                        is StringLiteralNode -> implNameNode.text
                        else -> continue
                    }
                    val (implLine, implChar) = getLineAndCharacterOfPosition(source, implStart)
                    diagnostics.add(Diagnostic(
                        message = "This overload signature is not compatible with its implementation signature.",
                        category = DiagnosticCategory.Error,
                        code = 2394,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        relatedInformation = listOf(Diagnostic(
                            message = "The implementation signature is declared here.",
                            category = DiagnosticCategory.Message,
                            code = 2750,
                            fileName = fileName,
                            line = implLine,
                            character = implChar,
                            start = implStart,
                            length = implText.length,
                        )),
                    ))
                    // Match TypeScript's "first incompatible only" behavior per group.
                    break
                }
            }
        }
    }

    /** Check if two consecutive overloads have identical parameter structure */
    private fun isDuplicateOverload(a: FunctionDeclaration, b: FunctionDeclaration): Boolean {
        if (a.parameters.size != b.parameters.size) return false
        for (i in a.parameters.indices) {
            val aType = a.parameters[i].type
            val bType = b.parameters[i].type
            if (aType == null && bType == null) continue
            if (aType == null || bType == null) return false
            // Compare keyword types
            if (aType is KeywordTypeNode && bType is KeywordTypeNode) {
                if (aType.kind != bType.kind) return false
            } else if (aType::class != bType::class) {
                return false
            }
        }
        return true
    }

    private fun isOverloadCompatibleWithImpl(overload: FunctionDeclaration, impl: FunctionDeclaration): Boolean {
        return isSignatureCompatible(overload.parameters, overload.type, impl.parameters, impl.type)
    }

    private fun isMethodOverloadCompatibleWithImpl(overload: MethodDeclaration, impl: MethodDeclaration): Boolean {
        return isSignatureCompatible(overload.parameters, overload.type, impl.parameters, impl.type)
    }

    /**
     * Conservative compatibility check between an overload signature and its implementation.
     * Returns true if compatible (or unknown), false only when clearly incompatible.
     */
    private fun isSignatureCompatible(
        overloadParams: List<Parameter>,
        overloadReturnType: TypeNode?,
        implParams: List<Parameter>,
        implReturnType: TypeNode?,
    ): Boolean {
        // Parameter count check: implementation must accept the number of args the overload promises
        val overloadTotalParams = overloadParams.size
        val implMinParams = implParams.count { !it.questionToken && it.initializer == null && !it.dotDotDotToken }
        if (implMinParams > overloadTotalParams) {
            return false
        }

        // Return type check: compare keyword types
        if (overloadReturnType != null && implReturnType != null) {
            if (!isTypeNodeCompatible(overloadReturnType, implReturnType)) {
                return false
            }
        }

        // Parameter type check: compare matching parameters by keyword type
        val commonCount = minOf(overloadParams.size, implParams.size)
        for (i in 0 until commonCount) {
            val overloadType = overloadParams[i].type ?: continue
            val implType = implParams[i].type ?: continue
            if (!isParamTypeCompatible(overloadType, implType)) {
                return false
            }
        }

        return true
    }

    /**
     * Check if overload return type is compatible with implementation return type.
     * Conservative: returns true unless [overloadType] is clearly NOT assignable to
     * [implType]. Recognizes:
     *   - Keyword↔Keyword (different intrinsics → false; any/never escape clauses)
     *   - LiteralType↔LiteralType (different literal values → false)
     *   - LiteralType→KeywordType (e.g. `"hi"` is assignable to `string`)
     *   - KeywordType→LiteralType (e.g. `string` is NOT assignable to `"hi"`)
     *   - FunctionType↔FunctionType (recursive: contravariant params + covariant return)
     */
    private fun isTypeNodeCompatible(overloadType: TypeNode, implType: TypeNode): Boolean {
        // LiteralType vs LiteralType: compare wrapped literal values.
        if (overloadType is LiteralType && implType is LiteralType) {
            return literalExpressionEquals(overloadType.literal, implType.literal)
        }
        // LiteralType (narrower) vs KeywordType (broader): assignable when the literal's
        // shape matches the keyword (e.g. string-literal → string keyword).
        if (overloadType is LiteralType && implType is KeywordTypeNode) {
            return literalAssignableToKeyword(overloadType.literal, implType.kind)
        }
        // KeywordType (broader) vs LiteralType (narrower): NOT assignable, unless
        // the source is `any` or `never` which escape both directions.
        if (overloadType is KeywordTypeNode && implType is LiteralType) {
            return overloadType.kind == SyntaxKind.AnyKeyword ||
                overloadType.kind == SyntaxKind.NeverKeyword
        }
        // FunctionType↔FunctionType: recurse with parameter contravariance + return covariance.
        if (overloadType is FunctionType && implType is FunctionType) {
            val commonCount = minOf(overloadType.parameters.size, implType.parameters.size)
            for (i in 0 until commonCount) {
                val overloadInner = overloadType.parameters[i].type ?: continue
                val implInner = implType.parameters[i].type ?: continue
                // Contravariance: impl's inner param must be assignable to overload's inner.
                if (!isTypeNodeCompatible(implInner, overloadInner)) return false
            }
            if (!isTypeNodeCompatible(overloadType.type, implType.type)) return false
            return true
        }
        // 17.186: TypeLiteral↔TypeLiteral — structurally compare PropertyDeclaration
        // members by name + type. Returns false only when we're confident there's a
        // mismatch (different member sets, or matching name with incompatible type
        // recursively). Other member kinds (MethodDeclaration, IndexSignature, etc.)
        // bail to true (conservative — incompatibility there isn't reliably
        // detectable without full structural comparison).
        if (overloadType is TypeLiteral && implType is TypeLiteral) {
            val overloadProps = overloadType.members.filterIsInstance<PropertyDeclaration>()
            val implProps = implType.members.filterIsInstance<PropertyDeclaration>()
            if (overloadProps.size != overloadType.members.size ||
                implProps.size != implType.members.size) return true
            if (overloadProps.size != implProps.size) return false
            val overloadByName = overloadProps.associateBy { (it.name as? Identifier)?.text ?: return true }
            val implByName = implProps.associateBy { (it.name as? Identifier)?.text ?: return true }
            if (overloadByName.keys != implByName.keys) return false
            for ((name, oProp) in overloadByName) {
                val iProp = implByName[name]!!
                val oT = oProp.type ?: continue
                val iT = iProp.type ?: continue
                if (!isTypeNodeCompatible(oT, iT)) return false
            }
            return true
        }
        // Keyword vs Keyword (existing keyword-only logic)
        if (overloadType !is KeywordTypeNode || implType !is KeywordTypeNode) return true
        val overloadKind = overloadType.kind
        val implKind = implType.kind
        if (overloadKind == implKind) return true
        // 'any' implementation is compatible with everything
        if (implKind == SyntaxKind.AnyKeyword) return true
        // 'any' overload is compatible with any implementation
        if (overloadKind == SyntaxKind.AnyKeyword) return true
        // 'void' and 'undefined' are interchangeable
        if ((overloadKind == SyntaxKind.VoidKeyword && implKind == SyntaxKind.UndefinedKeyword) ||
            (overloadKind == SyntaxKind.UndefinedKeyword && implKind == SyntaxKind.VoidKeyword)) return true
        // Different intrinsic types are incompatible
        return false
    }

    /**
     * Check if overload parameter type is compatible with implementation parameter type.
     * Conservative: only flag clearly incompatible intrinsic types.
     */
    private fun isParamTypeCompatible(overloadType: TypeNode, implType: TypeNode): Boolean {
        // Same logic as return type compatibility for keyword types
        return isTypeNodeCompatible(overloadType, implType)
    }

    /**
     * Compare two literal-type expressions for equality. Returns true only when the
     * AST shapes are the same and their text representations match. The parser maps
     * `true`/`false`/`null`/`undefined` literals to `Identifier` (see [parsePrimaryExpression]),
     * and negative numerics to `PrefixUnaryExpression(Minus, NumericLiteralNode)`.
     */
    private fun literalExpressionEquals(a: Expression, b: Expression): Boolean {
        return when {
            a is StringLiteralNode && b is StringLiteralNode -> a.text == b.text
            a is NoSubstitutionTemplateLiteralNode && b is NoSubstitutionTemplateLiteralNode -> a.text == b.text
            a is StringLiteralNode && b is NoSubstitutionTemplateLiteralNode -> a.text == b.text
            a is NoSubstitutionTemplateLiteralNode && b is StringLiteralNode -> a.text == b.text
            a is NumericLiteralNode && b is NumericLiteralNode -> a.text == b.text
            a is BigIntLiteralNode && b is BigIntLiteralNode -> a.text == b.text
            a is Identifier && b is Identifier -> a.text == b.text
            a is PrefixUnaryExpression && b is PrefixUnaryExpression ->
                a.operator == b.operator && literalExpressionEquals(a.operand, b.operand)
            else -> false
        }
    }

    /** Whether a literal-type expression value is assignable to the given keyword type. */
    private fun literalAssignableToKeyword(literal: Expression, keyword: SyntaxKind): Boolean {
        return when (keyword) {
            SyntaxKind.AnyKeyword, SyntaxKind.UnknownKeyword -> true
            SyntaxKind.StringKeyword ->
                literal is StringLiteralNode || literal is NoSubstitutionTemplateLiteralNode
            SyntaxKind.NumberKeyword ->
                literal is NumericLiteralNode ||
                (literal is PrefixUnaryExpression && literal.operand is NumericLiteralNode)
            SyntaxKind.BooleanKeyword ->
                literal is Identifier && (literal.text == "true" || literal.text == "false")
            SyntaxKind.BigIntKeyword -> literal is BigIntLiteralNode
            else -> true // unknown — conservative
        }
    }

    // -----------------------------------------------------------------------
    // TS2506: 'X' is referenced directly or indirectly in its own base expression
    // -----------------------------------------------------------------------

    private fun checkCircularBaseClasses() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkCircularBaseInStatements(result.sourceFile.statements, source, fileName,
                    inAmbientNamespace = false, namespacePath = emptyList())
            } catch (_: StackOverflowError) {}
        }
    }

    /** B18.3 v3: dry-run of [checkCircularBaseClasses] for the AMBIENT-namespace
     *  case only — populates [ambientCyclicBaseClassNamesByFile] so TS2449 can
     *  be suppressed for those classes. Runs BEFORE [checkUseBeforeDeclaration].
     *  The main [checkCircularBaseClasses] still runs later to emit TS2506. */
    private fun populateAmbientCyclicBaseClasses() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            try {
                collectAmbientCyclicNamesIn(result.sourceFile.statements, fileName,
                    inAmbientNamespace = false, namespacePath = emptyList())
            } catch (_: StackOverflowError) {}
        }
    }

    private fun collectAmbientCyclicNamesIn(
        statements: List<Statement>, fileName: String,
        inAmbientNamespace: Boolean, namespacePath: List<String>,
    ) {
        if (inAmbientNamespace) {
            // Collect class extends targets in this scope (qualified or bare).
            val classExtends = mutableMapOf<String, String>()
            for (stmt in statements) {
                if (stmt !is ClassDeclaration) continue
                val name = stmt.name?.text ?: continue
                val extendsClause = stmt.heritageClauses?.firstOrNull {
                    it.token == SyntaxKind.ExtendsKeyword
                } ?: continue
                val baseExpr = extendsClause.types.firstOrNull()?.expression ?: continue
                val baseName = resolveBaseNameInNamespace(baseExpr, namespacePath) ?: continue
                classExtends[name] = baseName
            }
            for ((className, _) in classExtends) {
                if (chainCyclesBackTo(className, classExtends)) {
                    ambientCyclicBaseClassNamesByFile.getOrPut(fileName) { mutableSetOf() }.add(className)
                }
            }
        }
        // Recurse into nested modules, extending namespace path.
        for (stmt in statements) {
            if (stmt is ModuleDeclaration) {
                val body = stmt.body
                if (body is ModuleBlock) {
                    val newPath = appendNamespacePath(namespacePath, stmt.name)
                    val nestedAmbient = inAmbientNamespace || ModifierFlag.Declare in stmt.modifiers
                    collectAmbientCyclicNamesIn(body.statements, fileName,
                        nestedAmbient, newPath)
                }
            }
        }
    }

    private fun chainCyclesBackTo(className: String, classExtends: Map<String, String>): Boolean {
        val visited = mutableSetOf<String>()
        var current: String? = className
        while (current != null) {
            if (!visited.add(current)) return current == className
            current = classExtends[current]
        }
        return false
    }

    private fun resolveBaseNameInNamespace(baseExpr: Expression, namespacePath: List<String>): String? {
        return when (baseExpr) {
            is Identifier -> baseExpr.text
            is PropertyAccessExpression -> {
                // For qualified extends like `NS.Sub.C`, only treat as in-scope when
                // the qualifier matches the enclosing namespace path exactly.
                // Otherwise (e.g. `A.B.Base.W` from a DIFFERENT namespace) skip —
                // see `declFileWithClassNameConflictingWithClassReferredByExtendsClause_ts`.
                val parts = mutableListOf<String>()
                var cur: Expression = baseExpr
                while (cur is PropertyAccessExpression) {
                    parts.add(0, cur.name.text)
                    cur = cur.expression
                }
                if (cur !is Identifier) return null
                val tail = parts.removeAt(parts.lastIndex)
                val qualifier = listOf(cur.text) + parts
                if (qualifier == namespacePath) tail else null
            }
            else -> null
        }
    }

    private fun appendNamespacePath(path: List<String>, name: Expression): List<String> {
        val parts = mutableListOf<String>()
        var cur: Expression = name
        while (cur is PropertyAccessExpression) {
            parts.add(0, cur.name.text)
            cur = cur.expression
        }
        if (cur is Identifier) parts.add(0, cur.text)
        return path + parts
    }

    private fun checkCircularBaseInStatements(
        statements: List<Statement>, source: String, fileName: String,
        inAmbientNamespace: Boolean, namespacePath: List<String>,
    ) {
        // Collect all class names and their extends targets in this scope
        val classExtends = mutableMapOf<String, String>() // className → baseClassName
        val classDecls = mutableMapOf<String, ClassDeclaration>()
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    classDecls[name] = stmt
                    val extendsClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseExpr = extendsClause.types.firstOrNull()?.expression ?: continue
                    // B18.3 v3: bare identifier always counts; qualified extends only
                    // counts inside an ambient namespace whose path matches the qualifier.
                    val baseName: String? = when (baseExpr) {
                        is Identifier -> baseExpr.text
                        is PropertyAccessExpression ->
                            if (inAmbientNamespace) resolveBaseNameInNamespace(baseExpr, namespacePath) else null
                        else -> null
                    }
                    if (baseName == null) continue
                    classExtends[name] = baseName
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val newPath = appendNamespacePath(namespacePath, stmt.name)
                        val nestedAmbient = inAmbientNamespace || ModifierFlag.Declare in stmt.modifiers
                        checkCircularBaseInStatements(body.statements, source, fileName,
                            nestedAmbient, newPath)
                    }
                }
                else -> {}
            }
        }
        // For each class, follow the extends chain to detect cycles
        for ((className, _) in classExtends) {
            val visited = mutableSetOf<String>()
            var current: String? = className
            while (current != null) {
                if (!visited.add(current)) {
                    // Cycle detected — emit TS2506 for all classes in the cycle
                    if (current == className) {
                        val decl = classDecls[className] ?: break
                        val nameNode = decl.name ?: break
                        val start = nameNode.pos
                        val length = nameNode.text.length
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "'$className' is referenced directly or indirectly in its own base expression.",
                            category = DiagnosticCategory.Error,
                            code = 2506,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    break
                }
                current = classExtends[current]
            }
        }
    }

    /** Returns true when the class declaration's own name is reachable through its `extends`
     *  chain (self-reference or mutual cycle). Used by TS2339-on-NewExpression to decide
     *  whether to treat the class as having "no usable base members" — a safe approximation
     *  matching TypeScript's behavior of TS2506-flagged classes being unresolvable structurally.
     *  Walks only class extends (not interface implements). */
    private fun classHasCircularBase(classDecl: ClassDeclaration): Boolean {
        val startName = classDecl.name?.text ?: return false
        val visited = mutableSetOf<String>()
        fun baseName(name: String): String? {
            val sym = globals[name] ?: return null
            val decl = sym.declarations.firstOrNull() as? ClassDeclaration ?: return null
            val extClause = decl.heritageClauses?.firstOrNull {
                it.token == SyntaxKind.ExtendsKeyword
            } ?: return null
            val baseExpr = extClause.types.firstOrNull()?.expression ?: return null
            return (baseExpr as? Identifier)?.text
        }
        var current: String? = baseName(startName)
        while (current != null) {
            if (current == startName) return true
            if (!visited.add(current)) return false
            current = baseName(current)
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2310: Type 'X' recursively references itself as a base type.
    //   Fires for interfaces whose extends graph contains a cycle through the
    //   interface's name. Covers direct self-reference (`interface I extends I`)
    //   and mutual cycles (`interface A extends B; interface B extends A;`).
    //   Complements TS2506 which handles class extends cycles.
    // -----------------------------------------------------------------------

    private fun checkCircularInterfaceBases() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkCircularInterfaceBasesInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {}
        }
    }

    // TS2456 — direct self-referencing type alias (e.g. `type X = X`).
    // The simple syntactic check: top-level RHS contains a TypeReference whose
    // typeName matches the alias name (possibly inside Union/Intersection/
    // ParenthesizedType/Array). Generic instantiation cases like `Array<X>` are
    // legal (TypeScript treats them as Array<X> where X is the alias's own
    // parameter), so we limit the descent to non-generic argument positions.
    private fun checkCircularTypeAlias() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCircularTypeAliasInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkCircularTypeAliasInStatements(
        statements: List<Statement>, source: String, fileName: String,
    ) {
        // Names introduced by *named* imports (`import { X }` / `import * as X`) at the
        // file scope. When a TypeAlias's name matches one of these, the TS2440 path
        // in `checkImportConflictsWithLocal` covers the diagnostic and the alias's
        // apparent self-reference is just resolving to the imported binding rather
        // than a true cycle — suppress TS2456 to mirror TypeScript's output shape.
        //
        // Default imports (`import X from "..."`) are intentionally excluded: TypeScript
        // does NOT fire TS2440 in that shape, and TS2456 IS expected (e.g. types3.ts in
        // `commonJsExportTypeDeclarationError`: `import test from "./test"; type test = test;`).
        val importedNames = mutableSetOf<String>()
        for (s in statements) {
            if (s !is ImportDeclaration) continue
            val clause = s.importClause ?: continue
            if (clause.isTypeOnly) continue
            when (val nb = clause.namedBindings) {
                is NamespaceImport -> importedNames.add(nb.name.text)
                is NamedImports -> for (el in nb.elements) {
                    if (!el.isTypeOnly) importedNames.add(el.name.text)
                }
                else -> {}
            }
        }
        for (stmt in statements) {
            when (stmt) {
                is TypeAliasDeclaration -> {
                    val aliasName = stmt.name.text
                    if (aliasName in importedNames) continue
                    if (typeNodeDirectlyReferencesName(stmt.type, aliasName)) {
                        val pos = stmt.name.pos
                        val length = aliasName.length
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "Type alias '${aliasName}' circularly references itself.",
                            category = DiagnosticCategory.Error,
                            code = 2456,
                            fileName = fileName,
                            line = line, character = character,
                            start = pos, length = length,
                        ))
                    }
                    // TS2577: scan for FunctionType return types that recursively reference
                    // the alias (with or without type args) — distinct from TS2456 which only
                    // fires for direct identifier self-cycles. Walk the alias body looking
                    // for FunctionType nodes whose return type contains the alias name.
                    checkFunctionReturnTypeCircular(stmt.type, aliasName, source, fileName)
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkCircularTypeAliasInStatements(body.statements, source, fileName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is Block -> checkCircularTypeAliasInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkCircularTypeAliasInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkCircularTypeAliasInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkCircularTypeAliasInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkCircularTypeAliasInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkCircularTypeAliasInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkCircularTypeAliasInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkCircularTypeAliasInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    /**
     * Returns true if [type] contains a top-level TypeReference whose name equals
     * [target] WITHOUT being inside a generic argument list. Walks through Union /
     * Intersection / ParenthesizedType, all of which preserve the
     * "direct self-reference" semantics that trigger TS2456.
     *
     * B63.10: ArrayType is NOT recursed through — `type A = A[]` is `Array<A>`,
     * a generic instantiation whose recursive `A` lives inside a type argument list,
     * which TypeScript does NOT treat as a direct cycle. Mirrors the TypeReference
     * branch's `typeArguments.isNullOrEmpty()` guard. Suppresses FP TS2456 on
     * `type A = "number" | "null" | A[]` (recursiveTupleTypeInference_ts) and
     * `type T1 = 1 | Promise<T1> | T1[]` (unresolvableSelfReferencingAwaitedUnion_ts);
     * both tests still fail on unrelated missing diagnostics but our diagnostic
     * surface no longer carries the FP.
     */
    /**
     * TS2577: Recursively scan a type node for FunctionType / ConstructorType
     * nodes whose return type references [target] (the enclosing type alias
     * name). Emits TS2577 at the return type's position. Unlike
     * [typeNodeDirectlyReferencesName] (TS2456), this detection treats
     * generic-instantiation references like `Target<X>` as matching.
     */
    private fun checkFunctionReturnTypeCircular(
        type: TypeNode?, target: String,
        source: String, fileName: String,
    ) {
        if (type == null) return
        when (type) {
            is FunctionType -> {
                if (typeNodeContainsName(type.type, target)) {
                    val rPos = type.type.pos
                    // Trim trailing whitespace/closing-punctuation past the actual type span.
                    // Node.end typically points past the NEXT token's scan position; for a
                    // tuple `[...]`, the true end is right after the `]`. Walk back skipping
                    // whitespace + `?` + `;` + `,`.
                    var rEnd = type.type.end
                    while (rEnd > rPos && source.getOrNull(rEnd - 1)?.let {
                        it == ' ' || it == '\t' || it == '\n' || it == '\r' ||
                        it == '?' || it == ',' || it == ';'
                    } == true) rEnd--
                    val length = (rEnd - rPos).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, rPos)
                    diagnostics.add(Diagnostic(
                        message = "Return type annotation circularly references itself.",
                        category = DiagnosticCategory.Error,
                        code = 2577,
                        fileName = fileName,
                        line = line, character = character,
                        start = rPos, length = length,
                    ))
                }
                checkFunctionReturnTypeCircular(type.type, target, source, fileName)
                type.parameters.forEach { p -> p.type?.let { checkFunctionReturnTypeCircular(it, target, source, fileName) } }
            }
            is UnionType -> type.types.forEach { checkFunctionReturnTypeCircular(it, target, source, fileName) }
            is IntersectionType -> type.types.forEach { checkFunctionReturnTypeCircular(it, target, source, fileName) }
            is ParenthesizedType -> checkFunctionReturnTypeCircular(type.type, target, source, fileName)
            is ConditionalType -> {
                checkFunctionReturnTypeCircular(type.checkType, target, source, fileName)
                checkFunctionReturnTypeCircular(type.extendsType, target, source, fileName)
                checkFunctionReturnTypeCircular(type.trueType, target, source, fileName)
                checkFunctionReturnTypeCircular(type.falseType, target, source, fileName)
            }
            is TupleType -> type.elements.forEach { checkFunctionReturnTypeCircular(it, target, source, fileName) }
            is ArrayType -> checkFunctionReturnTypeCircular(type.elementType, target, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { checkFunctionReturnTypeCircular(it, target, source, fileName) }
            else -> {}
        }
    }

    /**
     * Walk a type node looking for ANY occurrence of a TypeReference named [target]
     * (with or without type args). Recurses through union/intersection/tuple/array/
     * function/conditional/typeref-args, etc.
     */
    private fun typeNodeContainsName(type: TypeNode?, target: String): Boolean {
        if (type == null) return false
        return when (type) {
            is TypeReference -> {
                val name = (type.typeName as? Identifier)?.text
                if (name == target) return true
                type.typeArguments?.any { typeNodeContainsName(it, target) } == true
            }
            is UnionType -> type.types.any { typeNodeContainsName(it, target) }
            is IntersectionType -> type.types.any { typeNodeContainsName(it, target) }
            is ParenthesizedType -> typeNodeContainsName(type.type, target)
            is TupleType -> type.elements.any { typeNodeContainsName(it, target) }
            is ArrayType -> typeNodeContainsName(type.elementType, target)
            is RestType -> typeNodeContainsName(type.type, target)
            is ConditionalType -> typeNodeContainsName(type.checkType, target) ||
                typeNodeContainsName(type.extendsType, target) ||
                typeNodeContainsName(type.trueType, target) ||
                typeNodeContainsName(type.falseType, target)
            is FunctionType -> typeNodeContainsName(type.type, target) ||
                type.parameters.any { p -> typeNodeContainsName(p.type, target) }
            else -> false
        }
    }

    private fun typeNodeDirectlyReferencesName(type: TypeNode?, target: String): Boolean {
        if (type == null) return false
        return when (type) {
            is TypeReference -> {
                val name = (type.typeName as? Identifier)?.text
                // Direct identifier match with NO type arguments — `type X = X`.
                // (Generic instantiations like `Array<X>` aren't direct cycles in TypeScript's
                // sense — those resolve via the parameter list.)
                name == target && type.typeArguments.isNullOrEmpty()
            }
            is UnionType -> type.types.any { typeNodeDirectlyReferencesName(it, target) }
            is IntersectionType -> type.types.any { typeNodeDirectlyReferencesName(it, target) }
            is ParenthesizedType -> typeNodeDirectlyReferencesName(type.type, target)
            else -> false
        }
    }

    private fun checkCircularInterfaceBasesInStatements(
        statements: List<Statement>, source: String, fileName: String,
    ) {
        // Collect all interface declarations in this scope (including merged ones under the same name)
        // Map name → list of extends-base-names collected across all declarations.
        val interfaceExtends = mutableMapOf<String, MutableList<String>>()
        // Keep one declaration per name for diagnostic positioning; later declarations overwrite
        // but that's fine for position purposes — TypeScript emits at EACH declaration's name.
        val interfaceDecls = mutableMapOf<String, MutableList<InterfaceDeclaration>>()
        for (stmt in statements) {
            when (stmt) {
                is InterfaceDeclaration -> {
                    val name = stmt.name.text
                    interfaceDecls.getOrPut(name) { mutableListOf() }.add(stmt)
                    val extList = interfaceExtends.getOrPut(name) { mutableListOf() }
                    val extendsClauses = stmt.heritageClauses?.filter {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    for (clause in extendsClauses) {
                        for (typeExpr in clause.types) {
                            val baseName = when (val tn = typeExpr.expression) {
                                is Identifier -> tn.text
                                else -> null
                            } ?: continue
                            extList.add(baseName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let {
                        checkCircularInterfaceBasesInStatements(it.statements, source, fileName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is Block -> checkCircularInterfaceBasesInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkCircularInterfaceBasesInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkCircularInterfaceBasesInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkCircularInterfaceBasesInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkCircularInterfaceBasesInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkCircularInterfaceBasesInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkCircularInterfaceBasesInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkCircularInterfaceBasesInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
        if (interfaceExtends.isEmpty()) return

        // For each interface, check whether it is reachable from itself through the extends graph.
        // Uses DFS with visited set to avoid re-traversing; matches TypeScript's "cycle through self"
        // semantics: `interface A extends B; interface B extends C` — A cycles only if C → A.
        fun isSelfReferencing(start: String): Boolean {
            val visited = mutableSetOf<String>()
            fun dfs(cur: String): Boolean {
                val exts = interfaceExtends[cur] ?: return false
                for (next in exts) {
                    if (next == start) return true
                    if (!visited.add(next)) continue
                    if (dfs(next)) return true
                }
                return false
            }
            return dfs(start)
        }

        for ((name, decls) in interfaceDecls) {
            if (!isSelfReferencing(name)) continue
            // Emit TS2310 at EACH declaration's name (merged interfaces get one per declaration).
            for (decl in decls) {
                val nameNode = decl.name
                val start = nameNode.pos
                val length = nameNode.text.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                // Display name: include type parameters if present, matching TypeScript's format.
                val typeParamText = decl.typeParameters?.takeIf { it.isNotEmpty() }?.joinToString(", ") {
                    it.name.text
                }?.let { "<$it>" } ?: ""
                diagnostics.add(Diagnostic(
                    message = "Type '$name$typeParamText' recursively references itself as a base type.",
                    category = DiagnosticCategory.Error,
                    code = 2310,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2310 (extension): class self-reference through default-type-arg
    // indexed-access cycle.
    //   Pattern:
    //     class Base<C, T = C['someProp']> { ... }
    //     class Foo extends Base<Foo> { ... }
    //   `Foo extends Base<Foo>` substitutes C = Foo, then must evaluate the
    //   default `T = Foo['someProp']` — which requires Foo's shape, which
    //   depends on this base. Cycle. The existing `checkCircularInterfaceBases`
    //   only walks name-level interface extends; this helper adds the narrow
    //   class-default-indexed-access pattern. Gate is intentionally tight to
    //   avoid CRTP false positives (`class Foo extends Base<Foo>` where
    //   Base<T extends Base<T>> uses CONSTRAINTS not DEFAULTS is fine).
    // -----------------------------------------------------------------------

    private fun checkCircularClassBaseViaDefaultTypeArg() {
        val classDecls = mutableMapOf<String, ClassDeclaration>()
        for (result in binderResults) {
            collectTopLevelClassDeclarations(result.sourceFile.statements, classDecls)
        }
        if (classDecls.isEmpty()) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCircularClassBaseInStatements(result.sourceFile.statements, classDecls, source, fileName)
        }
    }

    private fun collectTopLevelClassDeclarations(
        statements: List<Statement>, out: MutableMap<String, ClassDeclaration>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> stmt.name?.let { out.putIfAbsent(it.text, stmt) }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                    collectTopLevelClassDeclarations(it.statements, out)
                }
                else -> {}
            }
        }
    }

    private fun checkCircularClassBaseInStatements(
        statements: List<Statement>,
        classDecls: Map<String, ClassDeclaration>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val className = stmt.name?.text ?: continue
                    val extendsClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseExpr = extendsClause.types.firstOrNull() ?: continue
                    val baseName = (baseExpr.expression as? Identifier)?.text ?: continue
                    val typeArgs = baseExpr.typeArguments ?: continue
                    // Position(s) where the deriving class self-references in extends type args.
                    val selfPositions = typeArgs.withIndex().filter { (_, ta) ->
                        val tr = ta as? TypeReference ?: return@filter false
                        (tr.typeName as? Identifier)?.text == className
                    }.map { it.index }
                    if (selfPositions.isEmpty()) continue
                    val baseClass = classDecls[baseName] ?: continue
                    val baseTps = baseClass.typeParameters ?: continue
                    if (baseTps.isEmpty()) continue
                    // Collect names of base type params at self-reference positions —
                    // those are bound to the deriving class.
                    val selfBoundTpNames = selfPositions.mapNotNull {
                        baseTps.getOrNull(it)?.name?.text
                    }.toSet()
                    if (selfBoundTpNames.isEmpty()) continue
                    // Look for a default type-arg whose body indexed-accesses any of
                    // the self-bound type params (directly or nested).
                    val cycle = baseTps.any { tp ->
                        tp.default?.let {
                            defaultIndexesIntoTypeParam(it, selfBoundTpNames)
                        } == true
                    }
                    if (!cycle) continue
                    val nameNode = stmt.name ?: continue
                    val start = nameNode.pos
                    val length = nameNode.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type '$className' recursively references itself as a base type.",
                        category = DiagnosticCategory.Error,
                        code = 2310,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                    checkCircularClassBaseInStatements(it.statements, classDecls, source, fileName)
                }
                is FunctionDeclaration -> stmt.body?.let {
                    checkCircularClassBaseInStatements(it.statements, classDecls, source, fileName)
                }
                is Block -> checkCircularClassBaseInStatements(stmt.statements, classDecls, source, fileName)
                is IfStatement -> {
                    checkCircularClassBaseInStatements(listOf(stmt.thenStatement), classDecls, source, fileName)
                    stmt.elseStatement?.let { checkCircularClassBaseInStatements(listOf(it), classDecls, source, fileName) }
                }
                is ForStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                is ForInStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                is ForOfStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                is WhileStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                is DoStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkCircularClassBaseInStatements(clause.statements, classDecls, source, fileName)
                            is DefaultClause -> checkCircularClassBaseInStatements(clause.statements, classDecls, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkCircularClassBaseInStatements(stmt.tryBlock.statements, classDecls, source, fileName)
                    stmt.catchClause?.block?.let { checkCircularClassBaseInStatements(it.statements, classDecls, source, fileName) }
                    stmt.finallyBlock?.let { checkCircularClassBaseInStatements(it.statements, classDecls, source, fileName) }
                }
                is LabeledStatement -> checkCircularClassBaseInStatements(listOf(stmt.statement), classDecls, source, fileName)
                else -> {}
            }
        }
    }

    private fun defaultIndexesIntoTypeParam(
        node: TypeNode, names: Set<String>,
    ): Boolean = when (node) {
        is IndexedAccessType -> {
            val obj = node.objectType
            val hit = obj is TypeReference && (obj.typeName as? Identifier)?.text in names
            hit || defaultIndexesIntoTypeParam(node.objectType, names) ||
                defaultIndexesIntoTypeParam(node.indexType, names)
        }
        is TypeReference -> node.typeArguments?.any { defaultIndexesIntoTypeParam(it, names) } == true
        else -> false
    }

    // -----------------------------------------------------------------------
    // TS2507: Type is not a constructor function type
    // -----------------------------------------------------------------------

    private fun checkNonConstructorExtends() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkNonConstructorExtendsInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkNonConstructorExtendsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        // Collect names declared in this scope
        val classNames = mutableSetOf<String>()
        val functionNames = mutableSetOf<String>()
        val funcDecls = mutableMapOf<String, FunctionDeclaration>()
        val varDecls = mutableMapOf<String, VariableDeclaration>() // variable name → declaration
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> stmt.name?.let { classNames.add(it.text) }
                is FunctionDeclaration -> stmt.name?.let {
                    functionNames.add(it.text)
                    funcDecls[it.text] = stmt
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val name = (decl.name as? Identifier)?.text ?: continue
                        varDecls[name] = decl
                    }
                }
                else -> {}
            }
        }

        // Check class extends clauses
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val extendsClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseExpr = extendsClause.types.firstOrNull()?.expression ?: continue
                    // 17.199: TS2507 for `extends Ns.x` where Ns is a namespace
                    // and x is a primitive var. PropertyAccessExpression with
                    // Identifier receiver, look up Ns in globals as a Module
                    // symbol, find x in exports, infer type from its
                    // declaration.
                    if (baseExpr is PropertyAccessExpression && baseExpr.expression is Identifier) {
                        val nsIdent = baseExpr.expression as Identifier
                        val nsSym = globals[nsIdent.text]
                        if (nsSym != null && nsSym.flags.hasAny(SymbolFlags.Module) &&
                            !nsSym.flags.hasAny(SymbolFlags.Class)) {
                            val memberSym = nsSym.exports?.get(baseExpr.name.text)
                            val memberDecl = memberSym?.valueDeclaration as? VariableDeclaration
                            if (memberDecl != null) {
                                val typeName = inferSimpleVarType(memberDecl)
                                if (typeName != null) {
                                    val start = baseExpr.pos
                                    // Span includes Ns.x — from receiver pos to property name end.
                                    val length = (baseExpr.name.pos + baseExpr.name.text.length - start).coerceAtLeast(1)
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "Type '$typeName' is not a constructor function type.",
                                        category = DiagnosticCategory.Error,
                                        code = 2507,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                    continue
                                }
                            }
                        }
                    }
                    val baseName = (baseExpr as? Identifier)?.text ?: continue
                    // 17.202: TS2507 for `class C extends Foo` where Foo is a
                    // FunctionDeclaration. Display: `(<params>) => <returnType>`.
                    // Only fires when the scope has a function with this name AND
                    // no class merge (a class with the same name would be the actual
                    // ctor target).
                    if (baseName in functionNames && baseName !in classNames) {
                        val funcDecl = funcDecls[baseName]
                        if (funcDecl != null) {
                            val typeName = formatFunctionTypeForExtends(funcDecl)
                            val start = baseExpr.pos
                            val length = baseName.length
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type '$typeName' is not a constructor function type.",
                                category = DiagnosticCategory.Error,
                                code = 2507,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                        continue
                    }
                    // Only flag if this scope has a variable with this name (shadowing any outer class)
                    val varDecl = varDecls[baseName] ?: continue
                    // Skip if the scope also has a class or function with this name (merge)
                    if (baseName in classNames || baseName in functionNames) continue
                    // Determine the type name from the variable's type annotation or initializer
                    val typeName = inferSimpleVarType(varDecl)
                    if (typeName != null) {
                        val start = baseExpr.pos
                        val length = baseName.length
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Type '$typeName' is not a constructor function type.",
                            category = DiagnosticCategory.Error,
                            code = 2507,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkNonConstructorExtendsInStatements(body.statements, source, fileName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkNonConstructorExtendsInStatements(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkNonConstructorExtendsInStatements(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { checkNonConstructorExtendsInStatements(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { checkNonConstructorExtendsInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkNonConstructorExtendsInStatements(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                else -> {}
            }
        }
    }

    /** Infer the simple primitive type name of a variable declaration.
     *  Only returns primitive types (number, string, boolean) to avoid FPs
     *  with named types that might be constructor interfaces. */
    /**
     * 17.202: Format a function's type for the TS2507 extends-function error
     * display. Mirrors TypeScript's `(<params>) => <returnType>` format.
     * Parameters: name + (optional `?`) + `: type` (or no type → assumed
     * implicit any). Return type: from annotation or inferred void if body
     * has no `return value`.
     */
    private fun formatFunctionTypeForExtends(decl: FunctionDeclaration): String {
        val paramStr = decl.parameters.joinToString(", ") { p ->
            val name = (p.name as? Identifier)?.text ?: "_"
            val opt = if (p.questionToken) "?" else ""
            val typeStr = p.type?.let { formatTypeForDisplay(it) ?: "any" } ?: "any"
            "$name$opt: $typeStr"
        }
        val retStr = decl.type?.let { formatTypeForDisplay(it) ?: "any" } ?: run {
            // Infer from body: void if no return-with-value, else any.
            val body = decl.body
            if (body == null || !bodyHasReturnValue(body)) "void" else "any"
        }
        return "($paramStr) => $retStr"
    }

    private fun inferSimpleVarType(decl: VariableDeclaration): String? {
        // From type annotation — only primitive keywords
        val typeNode = decl.type
        if (typeNode is KeywordTypeNode) {
            return when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                else -> null
            }
        }
        // Named type annotations (TypeReference) could be constructor types — skip
        if (typeNode != null) return null
        // From initializer
        val init = decl.initializer ?: return null
        return when (init) {
            is NumericLiteralNode -> "number"
            is StringLiteralNode -> "string"
            is PrefixUnaryExpression -> if (init.operand is NumericLiteralNode) "number" else null
            else -> null
        }
    }

    // -----------------------------------------------------------------------
    // TS2302: Static members cannot reference class type parameters
    // -----------------------------------------------------------------------

    private fun checkStaticMembersReferenceTypeParams() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkTS2302InStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkTS2302InStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                val typeParams = stmt.typeParameters
                if (typeParams != null && typeParams.isNotEmpty()) {
                    val typeParamNames = typeParams.map { it.name.text }.toSet()
                    for (member in stmt.members) {
                        checkTS2302InClassMember(member, typeParamNames, source, fileName)
                    }
                }
                // Recurse into member bodies for nested class declarations
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { for (s in it.statements) checkTS2302InStatement(s, source, fileName) }
                        is Constructor -> member.body?.let { for (s in it.statements) checkTS2302InStatement(s, source, fileName) }
                        is GetAccessor -> member.body?.let { for (s in it.statements) checkTS2302InStatement(s, source, fileName) }
                        is SetAccessor -> member.body?.let { for (s in it.statements) checkTS2302InStatement(s, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.let {
                    for (s in it.statements) checkTS2302InStatement(s, source, fileName)
                }
            }
            is FunctionDeclaration -> stmt.body?.let { for (s in it.statements) checkTS2302InStatement(s, source, fileName) }
            is Block -> for (s in stmt.statements) checkTS2302InStatement(s, source, fileName)
            is IfStatement -> {
                checkTS2302InStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkTS2302InStatement(it, source, fileName) }
            }
            is ForStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            is DoStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (s in clause.statements) checkTS2302InStatement(s, source, fileName)
                        is DefaultClause -> for (s in clause.statements) checkTS2302InStatement(s, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkTS2302InStatement(s, source, fileName)
                stmt.catchClause?.block?.statements?.forEach { checkTS2302InStatement(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkTS2302InStatement(it, source, fileName) }
            }
            is LabeledStatement -> checkTS2302InStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    private fun checkTS2302InClassMember(member: ClassElement, typeParamNames: Set<String>, source: String, fileName: String) {
        val isStatic = when (member) {
            is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
            is MethodDeclaration -> ModifierFlag.Static in member.modifiers
            is GetAccessor -> ModifierFlag.Static in member.modifiers
            is SetAccessor -> ModifierFlag.Static in member.modifiers
            else -> false
        }
        if (!isStatic) return
        when (member) {
            is PropertyDeclaration -> {
                member.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                member.initializer?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            }
            is MethodDeclaration -> {
                // Exclude method's own type parameters (they shadow class type params)
                val effectiveNames = member.typeParameters?.let { tps ->
                    typeParamNames - tps.map { it.name.text }.toSet()
                } ?: typeParamNames
                if (effectiveNames.isEmpty()) return
                for (param in member.parameters) {
                    param.type?.let { findTypeParamRefsInType(it, effectiveNames, source, fileName) }
                }
                member.type?.let { findTypeParamRefsInType(it, effectiveNames, source, fileName) }
                // Walk method body — static method bodies cannot reference class type params
                // either (e.g. `var entry: List<T>` or `new List<T>()` inside the body).
                member.body?.statements?.forEach { findTypeParamRefsInStatement(it, effectiveNames, source, fileName) }
            }
            is GetAccessor -> {
                member.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                member.body?.statements?.forEach { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
            }
            is SetAccessor -> {
                for (param in member.parameters) {
                    param.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                }
                member.body?.statements?.forEach { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
            }
            else -> {}
        }
    }

    /** Walk a type node tree to find references to class type parameters. */
    private fun findTypeParamRefsInType(typeNode: TypeNode, typeParamNames: Set<String>, source: String, fileName: String) {
        when (typeNode) {
            is TypeReference -> {
                val name = typeNode.typeName
                if (name is Identifier && name.text in typeParamNames) {
                    emitTS2302(name, source, fileName)
                }
                typeNode.typeArguments?.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
            }
            is ArrayType -> findTypeParamRefsInType(typeNode.elementType, typeParamNames, source, fileName)
            is UnionType -> typeNode.types.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
            is IntersectionType -> typeNode.types.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
            is ParenthesizedType -> findTypeParamRefsInType(typeNode.type, typeParamNames, source, fileName)
            is FunctionType -> {
                typeNode.parameters.forEach { p -> p.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) } }
                findTypeParamRefsInType(typeNode.type, typeParamNames, source, fileName)
            }
            is ConstructorType -> {
                typeNode.parameters.forEach { p -> p.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) } }
                findTypeParamRefsInType(typeNode.type, typeParamNames, source, fileName)
            }
            is TypeLiteral -> {
                for (m in typeNode.members) {
                    when (m) {
                        is PropertyDeclaration -> m.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                        is MethodDeclaration -> {
                            m.parameters.forEach { p -> p.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) } }
                            m.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                        }
                        is IndexSignature -> m.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                        else -> {}
                    }
                }
            }
            is TupleType -> typeNode.elements.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
            is OptionalType -> findTypeParamRefsInType(typeNode.type, typeParamNames, source, fileName)
            is RestType -> findTypeParamRefsInType(typeNode.type, typeParamNames, source, fileName)
            is ConditionalType -> {
                findTypeParamRefsInType(typeNode.checkType, typeParamNames, source, fileName)
                findTypeParamRefsInType(typeNode.extendsType, typeParamNames, source, fileName)
                findTypeParamRefsInType(typeNode.trueType, typeParamNames, source, fileName)
                findTypeParamRefsInType(typeNode.falseType, typeParamNames, source, fileName)
            }
            is TypeQuery -> {} // typeof x — no type parameter references
            is IndexedAccessType -> {
                findTypeParamRefsInType(typeNode.objectType, typeParamNames, source, fileName)
                findTypeParamRefsInType(typeNode.indexType, typeParamNames, source, fileName)
            }
            else -> {} // LiteralType, KeywordType, etc.
        }
    }

    /** Walk a statement (and nested blocks) to find type parameter references in type annotations. */
    private fun findTypeParamRefsInStatement(stmt: Statement, typeParamNames: Set<String>, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                    decl.initializer?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
                }
            }
            is ExpressionStatement -> findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
            is ReturnStatement -> stmt.expression?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            is Block -> stmt.statements.forEach { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
            is IfStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                findTypeParamRefsInStatement(stmt.thenStatement, typeParamNames, source, fileName)
                stmt.elseStatement?.let { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                            decl.initializer?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
                        }
                    }
                    is Expression -> findTypeParamRefsInExpr(init, typeParamNames, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
                stmt.incrementor?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
                findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            }
            is ForInStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            }
            is ForOfStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            }
            is WhileStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            }
            is DoStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            }
            is SwitchStatement -> {
                findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            findTypeParamRefsInExpr(clause.expression, typeParamNames, source, fileName)
                            clause.statements.forEach { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
                        }
                        is DefaultClause -> clause.statements.forEach { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                findTypeParamRefsInStatement(stmt.tryBlock, typeParamNames, source, fileName)
                stmt.catchClause?.block?.let { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
                stmt.finallyBlock?.let { findTypeParamRefsInStatement(it, typeParamNames, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            is LabeledStatement -> findTypeParamRefsInStatement(stmt.statement, typeParamNames, source, fileName)
            is ExportAssignment -> findTypeParamRefsInExpr(stmt.expression, typeParamNames, source, fileName)
            else -> {}
        }
    }

    /** Walk an expression to find type parameter references in embedded type annotations. */
    private fun findTypeParamRefsInExpr(expr: Expression, typeParamNames: Set<String>, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                expr.parameters.forEach { p -> p.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) } }
                expr.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                when (val body = expr.body) {
                    is Expression -> findTypeParamRefsInExpr(body, typeParamNames, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.parameters.forEach { p -> p.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) } }
                expr.type?.let { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
            }
            is ParenthesizedExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is BinaryExpression -> {
                // B64.7: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                findTypeParamRefsInExpr(cur, typeParamNames, source, fileName)
                while (rightStack.isNotEmpty()) findTypeParamRefsInExpr(rightStack.removeLast(), typeParamNames, source, fileName)
            }
            is ConditionalExpression -> {
                findTypeParamRefsInExpr(expr.condition, typeParamNames, source, fileName)
                findTypeParamRefsInExpr(expr.whenTrue, typeParamNames, source, fileName)
                findTypeParamRefsInExpr(expr.whenFalse, typeParamNames, source, fileName)
            }
            is CallExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                expr.typeArguments?.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                expr.arguments.forEach { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            }
            is NewExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                expr.typeArguments?.forEach { findTypeParamRefsInType(it, typeParamNames, source, fileName) }
                expr.arguments?.forEach { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            }
            is AsExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                findTypeParamRefsInType(expr.type, typeParamNames, source, fileName)
            }
            is TypeAssertionExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                findTypeParamRefsInType(expr.type, typeParamNames, source, fileName)
            }
            is SatisfiesExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                findTypeParamRefsInType(expr.type, typeParamNames, source, fileName)
            }
            is PropertyAccessExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is ElementAccessExpression -> {
                findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
                findTypeParamRefsInExpr(expr.argumentExpression, typeParamNames, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { findTypeParamRefsInExpr(it, typeParamNames, source, fileName) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> findTypeParamRefsInExpr(prop.initializer, typeParamNames, source, fileName)
                        is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let {
                            findTypeParamRefsInExpr(it, typeParamNames, source, fileName)
                        }
                        is SpreadAssignment -> findTypeParamRefsInExpr(prop.expression, typeParamNames, source, fileName)
                        else -> {}
                    }
                }
            }
            is PrefixUnaryExpression -> findTypeParamRefsInExpr(expr.operand, typeParamNames, source, fileName)
            is PostfixUnaryExpression -> findTypeParamRefsInExpr(expr.operand, typeParamNames, source, fileName)
            is NonNullExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is SpreadElement -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is DeleteExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is TypeOfExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is VoidExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            is AwaitExpression -> findTypeParamRefsInExpr(expr.expression, typeParamNames, source, fileName)
            else -> {} // literals, identifiers, etc.
        }
    }

    private fun emitTS2302(nameNode: Identifier, source: String, fileName: String) {
        val start = nameNode.pos
        val length = nameNode.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Static members cannot reference class type parameters.",
            category = DiagnosticCategory.Error,
            code = 2302,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2320: Interface cannot simultaneously extend types with conflicting members
    // -----------------------------------------------------------------------

    private fun checkInterfaceMultiBaseConflicts() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                for (stmt in result.sourceFile.statements) {
                    checkMultiBaseInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    private fun checkMultiBaseInStatement(stmt: Statement, source: String, fileName: String) {
        // round 44 iter6: recurse into ClassDeclaration member bodies so nested
        // InterfaceDeclaration inside class method/accessor/constructor bodies is
        // reached for TS2320 multi-extends-conflict check.
        if (stmt is ClassDeclaration) {
            for (member in stmt.members) {
                when (member) {
                    is MethodDeclaration -> member.body?.let { for (s in it.statements) checkMultiBaseInStatement(s, source, fileName) }
                    is Constructor -> member.body?.let { for (s in it.statements) checkMultiBaseInStatement(s, source, fileName) }
                    is GetAccessor -> member.body?.let { for (s in it.statements) checkMultiBaseInStatement(s, source, fileName) }
                    is SetAccessor -> member.body?.let { for (s in it.statements) checkMultiBaseInStatement(s, source, fileName) }
                    else -> {}
                }
            }
            return
        }
        when (stmt) {
            is InterfaceDeclaration -> {
                val extendsClauses = stmt.heritageClauses?.filter { it.token == SyntaxKind.ExtendsKeyword } ?: return
                // Collect all base type names from extends clauses
                val baseTypeExprs = extendsClauses.flatMap { it.types }
                if (baseTypeExprs.size < 2) return // Need 2+ base types
                val ifaceName = stmt.name.text

                // Own members override base member conflicts — skip names this interface declares itself.
                val ownMemberNames = stmt.members.mapNotNull {
                    when (it) {
                        is PropertyDeclaration -> (it.name as? Identifier)?.text
                        is MethodDeclaration -> (it.name as? Identifier)?.text
                        else -> null
                    }
                }.toSet()

                // Collect properties from each base type
                data class BaseProperty(val baseName: String, val isPrivate: Boolean, val propType: TypeNode?, val isOptional: Boolean = false, val isMethod: Boolean = false, val typeArgs: List<TypeNode>? = null, val hasTypeParams: Boolean = false)
                val propSources = mutableMapOf<String, MutableList<BaseProperty>>()

                for (typeExpr in baseTypeExprs) {
                    val effectiveTypeArgs: List<TypeNode>? = typeExpr.typeArguments
                    // 16.4cu: Resolve both bare Identifier (`extends Mover`) and qualified
                    // PropertyAccessExpression (`extends NS.Mover`) base types. For qualified,
                    // the base name displayed in the diagnostic is the rightmost segment.
                    val (baseName, baseSymbol) = when (val be = typeExpr.expression) {
                        is Identifier -> {
                            val sym = globals[be.text] ?: currentFileLocals?.get(be.text) ?: continue
                            be.text to sym
                        }
                        is PropertyAccessExpression -> {
                            val sym = resolvePropertyAccessToSymbol(be) ?: continue
                            be.name.text to sym
                        }
                        else -> continue
                    }
                    // B67.4: For display in TS2320 message, use the source-text base
                    // expression so generic refs render as `A<string>` not just `A`.
                    // Falls back to symbol-resolved name for non-generic-typed extends.
                    val baseDisplay = if (effectiveTypeArgs != null && effectiveTypeArgs.isNotEmpty()) {
                        val argTexts = effectiveTypeArgs.joinToString(", ") {
                            source.substring(it.pos, it.end).trim()
                        }
                        "$baseName<$argTexts>"
                    } else baseName
                    // Get members from all declarations (class or interface)
                    for (decl in baseSymbol.declarations) {
                        val members: List<Any> = when (decl) {
                            is ClassDeclaration -> decl.members
                            is InterfaceDeclaration -> decl.members.toList()
                            else -> continue
                        }
                        for (member in members) {
                            val propName: String
                            val isPrivate: Boolean
                            val propType: TypeNode?
                            val isOpt: Boolean
                            val isMethod: Boolean
                            var memberHasTypeParams = false
                            when (member) {
                                is PropertyDeclaration -> {
                                    propName = (member.name as? Identifier)?.text ?: continue
                                    isPrivate = ModifierFlag.Private in member.modifiers
                                    propType = member.type
                                    isOpt = member.questionToken
                                    isMethod = false
                                }
                                is MethodDeclaration -> {
                                    propName = (member.name as? Identifier)?.text ?: continue
                                    isPrivate = ModifierFlag.Private in member.modifiers
                                    propType = member.type
                                    isOpt = member.questionToken
                                    isMethod = true
                                    memberHasTypeParams = !member.typeParameters.isNullOrEmpty()
                                }
                                else -> continue
                            }
                            propSources.getOrPut(propName) { mutableListOf() }
                                .add(BaseProperty(baseDisplay, isPrivate, propType, isOpt, isMethod, effectiveTypeArgs, memberHasTypeParams))
                        }
                    }
                }

                // Check for conflicts: same property from different bases
                for ((propName, sources) in propSources) {
                    // Skip names this interface declares itself — own declaration resolves the conflict.
                    if (propName in ownMemberNames) continue
                    val distinctBases = sources.map { it.baseName }.distinct()
                    if (distinctBases.size < 2) continue // Same base — no conflict
                    val hasPrivate = sources.any { it.isPrivate }

                    val base1 = distinctBases[0]
                    val base2 = distinctBases[1]

                    // Conflict reason:
                    // - Any-private sources → always conflict (distinct privacy).
                    // - B67.4: Optionality mismatch (one optional, one not) → conflict.
                    // - B67.4: Methods (call signatures with potentially different generic typeParameters)
                    //   → fall through to type-based check; if either has a typeParameters
                    //   list and the other doesn't, that's a structural difference → conflict.
                    // - B67.4: Different parent typeArgs lists (`A<string>` vs `A<number>`) on
                    //   the same base symbol → conflict (substituted property types diverge).
                    // - All-public + matching optionality → conflict ONLY when types differ.
                    val src1 = sources.first { it.baseName == base1 }
                    val src2 = sources.first { it.baseName == base2 }
                    val conflict = if (hasPrivate) {
                        true
                    } else if (src1.isOptional != src2.isOptional) {
                        true
                    } else if (src1.isMethod && src2.isMethod && src1.hasTypeParams != src2.hasTypeParams) {
                        // B97 (round 80): a generic method `f<T>(x:T):T` and a non-generic
                        // `f(x:any):any` of the same name from two bases are NOT identical
                        // (different type-parameter lists). The plain type-node comparison
                        // below can't see this (the generic return type `T` resolves to
                        // errorType without the method's TP scope), so flag it explicitly.
                        true
                    } else if (src1.typeArgs != null && src2.typeArgs != null && src1.typeArgs.size == src2.typeArgs.size && src1.typeArgs.isNotEmpty()) {
                        // Same base, different type args: parent types substituted differently.
                        // Mismatch if any pair of type args disagrees by source text.
                        var anyMismatch = false
                        for (i in src1.typeArgs.indices) {
                            val a = source.substring(src1.typeArgs[i].pos, src1.typeArgs[i].end).trim()
                            val b = source.substring(src2.typeArgs[i].pos, src2.typeArgs[i].end).trim()
                            if (a != b) { anyMismatch = true; break }
                        }
                        anyMismatch
                    } else {
                        // Compare two distinct bases' first-declaration types.
                        val t0Node = src1.propType
                        val t1Node = src2.propType
                        if (t0Node != null && t1Node != null) {
                            try {
                                val t0 = getTypeFromTypeNode(t0Node)
                                val t1 = getTypeFromTypeNode(t1Node)
                                if (t0 === errorType || t1 === errorType) false
                                else !checkTypeRelatedTo(t0, t1, assignableRelation) &&
                                    !checkTypeRelatedTo(t1, t0, assignableRelation)
                            } catch (_: StackOverflowError) { false }
                        } else false
                    }
                    if (!conflict) continue

                    val nameNode = stmt.name
                    val start = nameNode.pos
                    val length = nameNode.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Interface '$ifaceName' cannot simultaneously extend types '$base1' and '$base2'.",
                        category = DiagnosticCategory.Error,
                        code = 2320,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = listOf("  Named property '$propName' of types '$base1' and '$base2' are not identical."),
                    ))
                    return // One TS2320 per interface
                }
            }
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
            }
            is FunctionDeclaration -> stmt.body?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        is Constructor -> member.body?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        is GetAccessor -> member.body?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        is SetAccessor -> member.body?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is Block -> stmt.statements.forEach { checkMultiBaseInStatement(it, source, fileName) }
            is IfStatement -> {
                checkMultiBaseInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkMultiBaseInStatement(it, source, fileName) }
            }
            is ForStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        is DefaultClause -> clause.statements.forEach { checkMultiBaseInStatement(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { checkMultiBaseInStatement(it, source, fileName) }
                stmt.catchClause?.block?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
            }
            is LabeledStatement -> checkMultiBaseInStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2411: Property type not assignable to index type
    // -----------------------------------------------------------------------

    private fun checkIndexSignatureProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkIndexSigInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    /**
     * B98.r13: TS7022 "'X' implicitly has type 'any' because it does not have a type annotation
     * and is referenced directly or indirectly in its own initializer." — fires for an
     * un-annotated `var/let/const X = { … X … }` (or `[ … X … ]`) whose OBJECT/ARRAY-LITERAL
     * initializer references X. Restricted to object/array literals because only there is the
     * inferred type genuinely circular (the referenced type is embedded directly) — a call/`new`
     * with an annotated return type breaks the circularity and must NOT fire. We DO NOT descend
     * into nested function/arrow/class bodies (deferred references). Gated `!strictExplicitlyFalse`.
     */
    private fun checkRecursiveLiteralVariables() {
        if (options.strictExplicitlyFalse) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                checkRecursiveLiteralVarInStatement(stmt, source, fileName)
            }
        }
    }

    private fun checkRecursiveLiteralVarInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue                       // annotated → not implicit-any
                    val name = (decl.name as? Identifier)?.text ?: continue
                    val init = decl.initializer
                    if (init !is ObjectLiteralExpression && init !is ArrayLiteralExpression) continue
                    if (!objectInitializerSelfReferences(init, name)) continue
                    val (line, character) = getLineAndCharacterOfPosition(source, decl.name.pos)
                    diagnostics.add(Diagnostic(
                        message = "'$name' implicitly has type 'any' because it does not have a type annotation and is referenced directly or indirectly in its own initializer.",
                        category = DiagnosticCategory.Error,
                        code = 7022,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = decl.name.pos,
                        length = name.length,
                    ))
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach {
                checkRecursiveLiteralVarInStatement(it, source, fileName)
            }
            else -> {}
        }
    }

    /** True if [expr] references [name] directly inside an object/array literal value position
     *  (descending only through literals/spreads/parens — NOT function/arrow/class bodies). */
    private fun objectInitializerSelfReferences(expr: Expression?, name: String): Boolean {
        if (expr == null) return false
        return when (expr) {
            is Identifier -> expr.text == name
            is ParenthesizedExpression -> objectInitializerSelfReferences(expr.expression, name)
            is SpreadElement -> objectInitializerSelfReferences(expr.expression, name)
            is ArrayLiteralExpression -> expr.elements.any { objectInitializerSelfReferences(it, name) }
            is ObjectLiteralExpression -> expr.properties.any { p ->
                when (p) {
                    is PropertyAssignment -> objectInitializerSelfReferences(p.initializer, name)
                    is ShorthandPropertyAssignment -> p.name.text == name
                    is SpreadAssignment -> objectInitializerSelfReferences(p.expression, name)
                    else -> false
                }
            }
            else -> false
        }
    }

    private fun checkIndexSigInStatement(stmt: Statement, source: String, fileName: String) {
        // 17.159: Handle TypeAliasDeclaration whose body is a TypeLiteral — surface
        // index-sig diagnostics for `type X<T> = { [k: T]: ... }` patterns. The
        // outer typeParameter names propagate so we can distinguish TS1337
        // (generic type-parameter param type) from TS1268 (other invalid kinds).
        if (stmt is TypeAliasDeclaration) {
            val typeParamNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
            val literal = stmt.type as? TypeLiteral ?: return
            checkIndexSigsInMembers(literal.members, typeParamNames, source, fileName)
            return
        }
        // B68.4: VariableStatement with TypeLiteral annotation — surface index-sig
        // diagnostics for `var x: { [k: any]: T }` patterns. Each decl's annotation
        // is checked independently.
        if (stmt is VariableStatement) {
            for (decl in stmt.declarationList.declarations) {
                val literal = decl.type as? TypeLiteral ?: continue
                checkIndexSigsInMembers(literal.members, emptySet(), source, fileName)
            }
            return
        }
        val members: List<ClassElement> = when (stmt) {
            is ClassDeclaration -> stmt.members
            is InterfaceDeclaration -> stmt.members.filterIsInstance<ClassElement>()
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.statements?.forEach { checkIndexSigInStatement(it, source, fileName) }
                return
            }
            else -> return
        }
        checkIndexSigsInMembers(members, emptySet(), source, fileName)

        // TS2374: Duplicate index signatures by key type (string/number/symbol).
        // Emit once per each duplicate (including the first) — matches TypeScript.
        val indexSigs = members.filterIsInstance<IndexSignature>()
        if (indexSigs.size > 1) {
            val byKey = mutableMapOf<String, MutableList<IndexSignature>>()
            for (sig in indexSigs) {
                // Only well-formed signatures: exactly one parameter, no `?` / `...`.
                // Malformed shapes (multiple params, rest params, optional) already fire
                // TS1017/TS1096/TS1097 — TypeScript doesn't double-report TS2374 for them.
                if (sig.parameters.size != 1) continue
                val param = sig.parameters[0]
                if (param.dotDotDotToken || param.questionToken) continue
                val keyKind = (param.type as? KeywordTypeNode)?.kind ?: continue
                val key = when (keyKind) {
                    SyntaxKind.StringKeyword -> "string"
                    SyntaxKind.NumberKeyword -> "number"
                    SyntaxKind.SymbolKeyword -> "symbol"
                    else -> continue
                }
                byKey.getOrPut(key) { mutableListOf() }.add(sig)
            }
            for ((key, sigs) in byKey) {
                if (sigs.size < 2) continue
                for (sig in sigs) {
                    val start = sig.pos
                    // Span through the trailing `;` if present — matches baseline squiggle.
                    // Search from sig.pos (not sig.end) because node.end overshoots by one token
                    // and may skip past this signature's `;` into the next sig's text.
                    val semiIdx = source.indexOf(';', start)
                    val end = if (semiIdx >= 0 && semiIdx - start < 80) semiIdx + 1 else sig.end
                    val length = (end - start).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Duplicate index signature for type '$key'.",
                        category = DiagnosticCategory.Error,
                        code = 2374,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }

        // 17.191: TS2411 for numeric-name properties incompatible with a
        // number index signature. `class C { 0: number; [x:number]: RegExp; }`
        // — the property `0` matches the number index sig but its type
        // (number) isn't assignable to the index value type (RegExp).
        // Conservative gate: only fires for PropertyDeclaration with a
        // NumericLiteralNode name (the test target shape) and a non-any
        // index value type.
        val numberIndexSig = members.filterIsInstance<IndexSignature>().firstOrNull { sig ->
            sig.parameters.firstOrNull()?.type?.let { it is KeywordTypeNode && it.kind == SyntaxKind.NumberKeyword } == true
        }
        val numberIndexType = numberIndexSig?.type?.let { getTypeFromTypeNode(it) }
        if (numberIndexType != null && numberIndexType !== anyType && numberIndexType !== errorType) {
            for (member in members) {
                if (member !is PropertyDeclaration) continue
                val nameNode = member.name as? NumericLiteralNode ?: continue
                val propTypeNode = member.type ?: continue
                val propType = getTypeFromTypeNode(propTypeNode)
                if (propType === anyType || propType === errorType) continue
                if (!checkTypeRelatedTo(propType, numberIndexType, assignableRelation)) {
                    val propTypeDisplay = formatTypeForDisplay(propTypeNode) ?: typeToString(propType)
                    val indexTypeDisplay = typeToString(numberIndexType)
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Property '${nameNode.text}' of type '$propTypeDisplay' is not assignable to 'number' index type '$indexTypeDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2411,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = nameNode.pos,
                        length = nameNode.text.length,
                    ))
                }
            }
        }

        // Find string index signature: [s: string]: T (also check base class)
        var stringIndexSig = members.filterIsInstance<IndexSignature>().firstOrNull { sig ->
            sig.parameters.firstOrNull()?.type?.let { it is KeywordTypeNode && it.kind == SyntaxKind.StringKeyword } == true
        }
        // If not found locally, check base class
        if (stringIndexSig == null && stmt is ClassDeclaration) {
            val baseName = stmt.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                ?.types?.firstOrNull()?.expression
                ?.let { (it as? Identifier)?.text }
            if (baseName != null) {
                val baseSymbol = globals[baseName]
                val baseDecl = baseSymbol?.declarations?.filterIsInstance<ClassDeclaration>()?.firstOrNull()
                stringIndexSig = baseDecl?.members?.filterIsInstance<IndexSignature>()?.firstOrNull { sig ->
                    sig.parameters.firstOrNull()?.type?.let { it is KeywordTypeNode && it.kind == SyntaxKind.StringKeyword } == true
                }
            }
        }
        val stringIndexType = stringIndexSig?.type?.let { getTypeFromTypeNode(it) }
        if (stringIndexType == null || stringIndexType === anyType || stringIndexType === errorType) return

        // 16.4ez: TS2411 for methods — when the string index type is primitive (not a
        // function/callable type), a method property is never assignable. Emit once per
        // method NAME (at the first overload declaration), with display built from all
        // overload signatures. Narrow: only fires when stringIndexType is a primitive.
        val stringIndexTypeIsPrimitive = stringIndexType.flags.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or TypeFlags.BigInt
        )
        if (stringIndexTypeIsPrimitive) {
            val methodsByName = linkedMapOf<String, MutableList<MethodDeclaration>>()
            for (m in members) {
                if (m is MethodDeclaration) {
                    val nm = (m.name as? Identifier)?.text ?: continue
                    if (nm.startsWith("#")) continue
                    // Skip call signatures (name == "") and construct signatures (name == "new") —
                    // per CLAUDE.md, interface call/construct signatures are encoded as
                    // MethodDeclaration with special names; they aren't regular properties.
                    if (nm.isEmpty() || nm == "new") continue
                    // Skip static methods — they belong to the class's static side, not instance.
                    if (ModifierFlag.Static in m.modifiers) continue
                    methodsByName.getOrPut(nm) { mutableListOf() }.add(m)
                }
            }
            for ((methodName, overloads) in methodsByName) {
                val firstDecl = overloads.first()
                val sigStrings = overloads.map { md ->
                    val retType = md.type?.let { formatTypeForDisplay(it) ?: typeToString(getTypeFromTypeNode(it)) } ?: "any"
                    "(): $retType" // narrow: only zero-arg overloads for this test
                }
                // Only fire when all overloads took no parameters (narrow safety — otherwise
                // the display could miss-represent parameterized overloads).
                if (overloads.any { it.parameters.isNotEmpty() }) continue
                val propTypeDisplay = "{ ${sigStrings.joinToString("; ")}; }"
                val indexTypeDisplay = typeToString(stringIndexType)
                // Squiggle covers the first overload's full text through its trailing `;`.
                val start = firstDecl.pos
                val semiIdx = source.indexOf(';', start)
                val end = if (semiIdx >= 0 && semiIdx - start < 80) semiIdx + 1 else firstDecl.end
                val length = (end - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Property '$methodName' of type '$propTypeDisplay' is not assignable to 'string' index type '$indexTypeDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2411,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }

        // Method-overload tracking — skip TS2411 for methods declared more than once
        // (interface overload signatures); the simple synthesis below would only see one.
        val methodNameCounts = mutableMapOf<String, Int>()
        for (m in members) {
            if (m is MethodDeclaration) {
                val nm = (m.name as? Identifier)?.text ?: continue
                methodNameCounts[nm] = (methodNameCounts[nm] ?: 0) + 1
            }
        }
        // Check each named property against the string index type
        for (member in members) {
            val propName: String
            val propTypeNode: TypeNode?
            val nameNode: Node
            // For MethodDeclaration: squiggle covers full decl through trailing `;`.
            var methodSquiggle = false
            when (member) {
                is PropertyDeclaration -> {
                    // Skip private fields (#name) — they're not accessible via index operator
                    val propIdent = member.name
                    if (propIdent is Identifier && propIdent.text.startsWith("#")) continue
                    nameNode = member.name
                    propName = when (val n = member.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    propTypeNode = member.type
                }
                is MethodDeclaration -> {
                    // Methods only checked when string-index is callable (function-type).
                    // The `stringIndexTypeIsPrimitive` branch above handles the primitive case
                    // with a different display format; defer to it there.
                    if (stringIndexTypeIsPrimitive) continue
                    nameNode = member.name ?: continue
                    propName = when (val n = member.name) {
                        is Identifier -> n.text
                        else -> continue
                    }
                    if (propName.isEmpty() || propName == "new") continue // call/construct sigs
                    if (propName.startsWith("#")) continue
                    if (ModifierFlag.Static in member.modifiers) continue
                    // Skip overloaded methods — single-decl synthesis below misses the others.
                    if ((methodNameCounts[propName] ?: 0) > 1) continue
                    // Synthesize FunctionType TypeNode from the method's params + return.
                    val retNode = member.type
                        ?: KeywordTypeNode(SyntaxKind.AnyKeyword, member.pos, member.end)
                    propTypeNode = FunctionType(
                        typeParameters = member.typeParameters,
                        parameters = member.parameters,
                        type = retNode,
                        pos = member.pos,
                        end = member.end,
                    )
                    methodSquiggle = true
                }
                else -> continue
            }
            if (propTypeNode == null) continue // properties without explicit type
            val propType = getTypeFromTypeNode(propTypeNode)
            if (propType === anyType || propType === errorType) continue

            if (!checkTypeRelatedTo(propType, stringIndexType, assignableRelation)) {
                val propTypeDisplay = formatTypeForDisplay(propTypeNode) ?: typeToString(propType)
                val indexTypeDisplay = typeToString(stringIndexType)
                val start: Int
                val length: Int
                if (methodSquiggle && member is MethodDeclaration) {
                    val nameStart = (member.name as Identifier).pos
                    val semiIdx = source.indexOf(';', nameStart)
                    val end = if (semiIdx >= 0 && semiIdx - nameStart < 80) semiIdx + 1 else member.end
                    start = nameStart
                    length = (end - nameStart).coerceAtLeast(1)
                } else when (nameNode) {
                    is Identifier -> { start = nameNode.pos; length = nameNode.text.length }
                    is StringLiteralNode -> { start = nameNode.pos; length = nameNode.text.length + 2 }
                    else -> continue
                }
                // String literal property names include quotes in the display
                val displayName = if (nameNode is StringLiteralNode) "\"$propName\"" else propName
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Property '$displayName' of type '$propTypeDisplay' is not assignable to 'string' index type '$indexTypeDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2411,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    /**
     * 17.159: TS1268 / TS1337 emission for index-signature parameter types.
     * Shared between class/interface/module members (with `outerTypeParamNames` empty)
     * and TypeAliasDeclaration TypeLiteral members (with the alias's type-param names).
     * When the param type is a TypeReference whose name matches an outer type param,
     * emits TS1337 ("cannot be a literal type or generic type"). Otherwise emits
     * TS1268 (the long-standing path, "must be string/number/symbol/template literal").
     */
    private fun checkIndexSigsInMembers(
        members: List<ClassElement>, outerTypeParamNames: Set<String>,
        source: String, fileName: String,
    ) {
        val allowedIndexTypes = setOf(SyntaxKind.StringKeyword, SyntaxKind.NumberKeyword, SyntaxKind.SymbolKeyword)
        for (sig in members.filterIsInstance<IndexSignature>()) {
            if (sig.parameters.size != 1) continue
            val param = sig.parameters[0]
            if (param.dotDotDotToken || param.questionToken) continue
            val pType = param.type ?: continue
            val isAllowed = when (pType) {
                is KeywordTypeNode -> pType.kind in allowedIndexTypes
                is TemplateLiteralType -> true
                is ArrayType -> true
                else -> false
            }
            if (isAllowed) continue
            // TS1337: parameter type is a generic (TypeReference to a TypeParameter)
            // or a literal type — TypeScript suggests using a mapped object type instead.
            val isGeneric = pType is TypeReference && pType.typeName is Identifier &&
                outerTypeParamNames.contains((pType.typeName as Identifier).text)
            val isLiteral = pType is LiteralType
            val (code, message) = if (isGeneric || isLiteral) {
                1337 to "An index signature parameter type cannot be a literal type or generic type. Consider using a mapped object type instead."
            } else {
                1268 to "An index signature parameter type must be 'string', 'number', 'symbol', or a template literal type."
            }
            val start = param.name.pos
            val nameLen = when (val n = param.name) {
                is Identifier -> n.text.length
                else -> param.name.end - param.name.pos
            }
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = message,
                category = DiagnosticCategory.Error,
                code = code,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = nameLen,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // TS2511: Cannot create an instance of an abstract class
    // -----------------------------------------------------------------------

    private fun checkAbstractClassInstantiation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                // Collect abstract class names visible at file level
                val abstractClasses = mutableSetOf<String>()
                collectAbstractClassNames(result.sourceFile.statements, abstractClasses)
                // Also check globals for abstract classes from other files
                for ((name, sym) in globals) {
                    if (isAbstractClass(sym)) abstractClasses.add(name)
                }
                // Build type alias map for `typeof X` resolution through aliases.
                val typeAliases = mutableMapOf<String, TypeNode>()
                collectTypeAliases(result.sourceFile.statements, typeAliases)
                // Identify variable/parameter names whose type annotation resolves to "abstract-constructible"
                // (i.e. typeof X for some abstract X, or a union containing one).
                val typeofAbstractVars = mutableSetOf<String>()
                collectTypeofAbstractVars(result.sourceFile.statements, abstractClasses, typeAliases, typeofAbstractVars)
                checkAbstractInStmts(result.sourceFile.statements, source, fileName, abstractClasses, typeofAbstractVars)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun collectTypeAliases(stmts: List<Statement>, aliases: MutableMap<String, TypeNode>) {
        for (stmt in stmts) {
            when (stmt) {
                is TypeAliasDeclaration -> aliases[stmt.name.text] = stmt.type
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) collectTypeAliases(body.statements, aliases)
                }
                is Block -> collectTypeAliases(stmt.statements, aliases)
                is FunctionDeclaration -> stmt.body?.let { collectTypeAliases(it.statements, aliases) }
                else -> {}
            }
        }
    }

    /** Returns true if [type] denotes a constructor whose target may be abstract — i.e. `typeof X`
     * where X is an abstract class, or a union/parenthesized variant containing one. */
    private fun typeNodeIsAbstractConstructible(
        type: TypeNode,
        abstractClasses: Set<String>,
        typeAliases: Map<String, TypeNode>,
        visited: MutableSet<String> = mutableSetOf(),
    ): Boolean {
        return when (type) {
            is TypeQuery -> {
                val expr = type.exprName
                expr is Identifier && expr.text in abstractClasses
            }
            is UnionType -> type.types.any { typeNodeIsAbstractConstructible(it, abstractClasses, typeAliases, visited) }
            is ParenthesizedType -> typeNodeIsAbstractConstructible(type.type, abstractClasses, typeAliases, visited)
            is TypeReference -> {
                val tname = type.typeName
                if (tname is Identifier) {
                    if (tname.text in visited) return false
                    val aliasType = typeAliases[tname.text] ?: return false
                    visited.add(tname.text)
                    typeNodeIsAbstractConstructible(aliasType, abstractClasses, typeAliases, visited)
                } else false
            }
            else -> false
        }
    }

    private fun collectTypeofAbstractVars(
        stmts: List<Statement>,
        abstractClasses: Set<String>,
        typeAliases: Map<String, TypeNode>,
        out: MutableSet<String>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name as? Identifier ?: continue
                        val type = decl.type ?: continue
                        if (typeNodeIsAbstractConstructible(type, abstractClasses, typeAliases)) {
                            out.add(name.text)
                        }
                    }
                }
                is FunctionDeclaration -> {
                    for (param in stmt.parameters) {
                        val pname = param.name as? Identifier ?: continue
                        val ptype = param.type ?: continue
                        if (typeNodeIsAbstractConstructible(ptype, abstractClasses, typeAliases)) {
                            out.add(pname.text)
                        }
                    }
                    stmt.body?.let { collectTypeofAbstractVars(it.statements, abstractClasses, typeAliases, out) }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) collectTypeofAbstractVars(body.statements, abstractClasses, typeAliases, out)
                }
                is Block -> collectTypeofAbstractVars(stmt.statements, abstractClasses, typeAliases, out)
                else -> {}
            }
        }
    }

    private fun collectAbstractClassNames(stmts: List<Statement>, names: MutableSet<String>) {
        for (stmt in stmts) {
            if (stmt is ClassDeclaration && stmt.name != null && ModifierFlag.Abstract in stmt.modifiers) {
                names.add(stmt.name!!.text)
            }
        }
    }

    private fun checkAbstractInStmts(stmts: List<Statement>, source: String, fileName: String, abstractClasses: MutableSet<String>, typeofAbstractVars: Set<String>) {
        // Collect abstract class names declared in this block
        val saved = abstractClasses.toSet()
        collectAbstractClassNames(stmts, abstractClasses)
        // Also remove names shadowed by non-abstract classes in this scope
        for (stmt in stmts) {
            if (stmt is ClassDeclaration && stmt.name != null && ModifierFlag.Abstract !in stmt.modifiers) {
                abstractClasses.remove(stmt.name!!.text)
            }
        }
        for (stmt in stmts) {
            checkAbstractInStmt(stmt, source, fileName, abstractClasses, typeofAbstractVars)
        }
        // Restore scope
        abstractClasses.clear()
        abstractClasses.addAll(saved)
    }

    private fun checkAbstractInStmt(stmt: Statement, source: String, fileName: String, abstractClasses: MutableSet<String>, typeofAbstractVars: Set<String>) {
        when (stmt) {
            is ExpressionStatement -> checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is VariableStatement -> {
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
            is IfStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInStmt(stmt.thenStatement, source, fileName, abstractClasses, typeofAbstractVars)
                stmt.elseStatement?.let { checkAbstractInStmt(it, source, fileName, abstractClasses, typeofAbstractVars) }
            }
            is Block -> checkAbstractInStmts(stmt.statements, source, fileName, abstractClasses, typeofAbstractVars)
            is FunctionDeclaration -> stmt.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                    is Constructor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                    is PropertyDeclaration -> m.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                    is GetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                    is SetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                    else -> {}
                }
            }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    d.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                }
                stmt.condition?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                stmt.incrementor?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is WhileStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is DoStatement -> {
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is SwitchStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
                for (c in stmt.caseBlock) {
                    val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    checkAbstractInStmts(clauseStmts, source, fileName, abstractClasses, typeofAbstractVars)
                }
            }
            is TryStatement -> {
                checkAbstractInStmts(stmt.tryBlock.statements, source, fileName, abstractClasses, typeofAbstractVars)
                stmt.catchClause?.let { checkAbstractInStmts(it.block.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                stmt.finallyBlock?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
            }
            is ThrowStatement -> stmt.expression?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
            is ForInStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is ForOfStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is LabeledStatement -> checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses, typeofAbstractVars)
            is ExportAssignment -> checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
            else -> {}
        }
    }

    private fun checkAbstractInExpr(expr: Expression, source: String, fileName: String, abstractClasses: MutableSet<String>, typeofAbstractVars: Set<String>) {
        when (expr) {
            is NewExpression -> {
                val callee = expr.expression
                if (callee is Identifier && (callee.text in abstractClasses || callee.text in typeofAbstractVars)) {
                    val start = expr.pos
                    val exprEnd = expressionTrueEnd(expr)
                    val length = exprEnd - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot create an instance of an abstract class.",
                        category = DiagnosticCategory.Error,
                        code = 2511,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                for (arg in expr.arguments ?: emptyList()) {
                    checkAbstractInExpr(arg, source, fileName, abstractClasses, typeofAbstractVars)
                }
            }
            is BinaryExpression -> {
                checkAbstractInExpr(expr.left, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInExpr(expr.right, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is CallExpression -> {
                // Detect `[A, B, ...].map((cls) => new cls())` pattern: when the receiver is an
                // ArrayLiteralExpression containing abstract-class identifiers, the callback
                // parameter inherits "abstract-constructible" state so `new param()` fires TS2511.
                val callee = expr.expression
                val handledArrayMap = if (callee is PropertyAccessExpression && callee.name.text == "map") {
                    val recv = callee.expression
                    if (recv is ArrayLiteralExpression && expr.arguments.size == 1) {
                        val elementsContainAbstract = recv.elements.any { el ->
                            el is Identifier && (el.text in abstractClasses || el.text in typeofAbstractVars)
                        }
                        if (elementsContainAbstract) {
                            val arg = expr.arguments[0]
                            val paramName = when (arg) {
                                is ArrowFunction -> (arg.parameters.firstOrNull()?.name as? Identifier)?.text
                                is FunctionExpression -> (arg.parameters.firstOrNull()?.name as? Identifier)?.text
                                else -> null
                            }
                            val argBody: Node? = when (arg) {
                                is ArrowFunction -> arg.body
                                is FunctionExpression -> arg.body
                                else -> null
                            }
                            if (paramName != null && argBody != null) {
                                val extendedSet = typeofAbstractVars + paramName
                                when (argBody) {
                                    is Block -> checkAbstractInStmts(argBody.statements, source, fileName, abstractClasses, extendedSet)
                                    is Expression -> checkAbstractInExpr(argBody, source, fileName, abstractClasses, extendedSet)
                                    else -> {}
                                }
                                // Recurse into the array literal's elements for any other diagnostics.
                                for (el in recv.elements) checkAbstractInExpr(el, source, fileName, abstractClasses, typeofAbstractVars)
                                true
                            } else false
                        } else false
                    } else false
                } else false
                if (!handledArrayMap) {
                    checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
                    for (arg in expr.arguments) checkAbstractInExpr(arg, source, fileName, abstractClasses, typeofAbstractVars)
                }
            }
            is ParenthesizedExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is ConditionalExpression -> {
                checkAbstractInExpr(expr.condition, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInExpr(expr.whenTrue, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInExpr(expr.whenFalse, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is ArrowFunction -> expr.body?.let {
                when (it) {
                    is Block -> checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars)
                    is Expression -> checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars)
                    else -> {}
                }
            }
            is FunctionExpression -> expr.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
            is ArrayLiteralExpression -> for (el in expr.elements) checkAbstractInExpr(el, source, fileName, abstractClasses, typeofAbstractVars)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkAbstractInExpr(prop.initializer, source, fileName, abstractClasses, typeofAbstractVars)
                    is SpreadAssignment -> checkAbstractInExpr(prop.expression, source, fileName, abstractClasses, typeofAbstractVars)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkAbstractInExpr(span.expression, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is TaggedTemplateExpression -> {
                checkAbstractInExpr(expr.tag, source, fileName, abstractClasses, typeofAbstractVars)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) {
                        checkAbstractInExpr(span.expression, source, fileName, abstractClasses, typeofAbstractVars)
                    }
                }
            }
            is AsExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is TypeAssertionExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is SatisfiesExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is PrefixUnaryExpression -> checkAbstractInExpr(expr.operand, source, fileName, abstractClasses, typeofAbstractVars)
            is PostfixUnaryExpression -> checkAbstractInExpr(expr.operand, source, fileName, abstractClasses, typeofAbstractVars)
            is PropertyAccessExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is ElementAccessExpression -> {
                checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
                checkAbstractInExpr(expr.argumentExpression, source, fileName, abstractClasses, typeofAbstractVars)
            }
            is SpreadElement -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is AwaitExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is YieldExpression -> expr.expression?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
            is VoidExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is DeleteExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is NonNullExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is TypeOfExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses, typeofAbstractVars)
            is CommaListExpression -> for (e in expr.elements) checkAbstractInExpr(e, source, fileName, abstractClasses, typeofAbstractVars)
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                is Constructor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                is GetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                is SetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses, typeofAbstractVars) }
                is PropertyDeclaration -> m.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses, typeofAbstractVars) }
                else -> {}
            }
            else -> {}
        }
    }

    private fun isAbstractClass(symbol: Symbol): Boolean {
        for (decl in symbol.declarations) {
            if (decl is ClassDeclaration && ModifierFlag.Abstract in decl.modifiers) {
                return true
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2420: Class incorrectly implements interface
    // -----------------------------------------------------------------------

    private fun checkClassImplementsInterface() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                for (stmt in result.sourceFile.statements) {
                    checkImplementsClausesInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkImplementsClausesInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                checkImplementsClauses(stmt, source, fileName)
                // Recurse into class member bodies for nested classes
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { for (s in it.statements) checkImplementsClausesInStatement(s, source, fileName) }
                        is Constructor -> member.body?.let { for (s in it.statements) checkImplementsClausesInStatement(s, source, fileName) }
                        is GetAccessor -> member.body?.let { for (s in it.statements) checkImplementsClausesInStatement(s, source, fileName) }
                        is SetAccessor -> member.body?.let { for (s in it.statements) checkImplementsClausesInStatement(s, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkImplementsClausesInStatement(s, source, fileName)
                }
            }
            is FunctionDeclaration -> stmt.body?.let { for (s in it.statements) checkImplementsClausesInStatement(s, source, fileName) }
            is Block -> for (s in stmt.statements) checkImplementsClausesInStatement(s, source, fileName)
            is IfStatement -> {
                checkImplementsClausesInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkImplementsClausesInStatement(it, source, fileName) }
            }
            is ForStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (s in clause.statements) checkImplementsClausesInStatement(s, source, fileName)
                        is DefaultClause -> for (s in clause.statements) checkImplementsClausesInStatement(s, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkImplementsClausesInStatement(s, source, fileName)
                stmt.catchClause?.block?.statements?.forEach { checkImplementsClausesInStatement(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkImplementsClausesInStatement(it, source, fileName) }
            }
            is LabeledStatement -> checkImplementsClausesInStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    private fun checkImplementsClauses(classDecl: ClassDeclaration, source: String, fileName: String) {
        val implementsClauses = classDecl.heritageClauses?.filter {
            it.token == SyntaxKind.ImplementsKeyword
        } ?: return
        if (implementsClauses.isEmpty()) return

        val classNameRaw = classDecl.name?.text ?: return
        // 17.55: Include class type parameters in display name (e.g. `ObservableArray<T>`)
        // to match TypeScript's TS2420/TS2720 message format for generic classes.
        val classTypeParamSuffix = classDecl.typeParameters?.takeIf { it.isNotEmpty() }
            ?.mapNotNull { tp -> (tp.name as? Identifier)?.text }
            ?.takeIf { it.isNotEmpty() }
            ?.let { "<${it.joinToString(", ")}>" } ?: ""
        val className = classNameRaw + classTypeParamSuffix

        // Collect class's OWN declared member names (not inherited from interfaces)
        val classMemberNames = mutableSetOf<String>()
        for (member in classDecl.members) {
            val memberName = when (member) {
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                is Constructor -> {
                    // Parameter properties count as class members
                    for (param in member.parameters) {
                        if (param.modifiers.isNotEmpty() && param.name is Identifier) {
                            classMemberNames.add((param.name as Identifier).text)
                        }
                    }
                    null
                }
                is IndexSignature -> null // handled separately
                else -> null
            }
            if (memberName != null) classMemberNames.add(memberName)
        }
        // 16.4l: Also include members inherited via `extends` base class — a class that
        // extends C inherits C's members and therefore satisfies `implements C`.
        classDecl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }?.let { extClause ->
            for (baseExpr in extClause.types) {
                val baseName = when (val bn = baseExpr.expression) {
                    is Identifier -> bn.text
                    is PropertyAccessExpression -> (bn.name as? Identifier)?.text
                    else -> null
                } ?: continue
                val baseSym = globals[baseName] ?: continue
                val baseType = getDeclaredTypeOfSymbol(baseSym) as? Type.Object ?: continue
                resolveStructuredTypeMembers(baseType)
                baseType.properties?.forEach { classMemberNames.add(it.name) }
            }
        }

        // Check if class has index signatures
        val hasStringIndex = classDecl.members.any {
            it is IndexSignature && it.parameters.firstOrNull()?.type?.let { t ->
                t is KeywordTypeNode && t.kind == SyntaxKind.StringKeyword
            } == true
        }
        val hasNumberIndex = classDecl.members.any {
            it is IndexSignature && it.parameters.firstOrNull()?.type?.let { t ->
                t is KeywordTypeNode && t.kind == SyntaxKind.NumberKeyword
            } == true
        }

        for (clause in implementsClauses) {
            typeExprLoop@ for (typeExpr in clause.types) {
                val baseIfaceName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue
                // Self-implements: `class X implements X` is tautological at the point
                // of declaration — the class always satisfies its own declared shape.
                // Module augmentations may extend the interface side with additional
                // members; those are satisfied at runtime via prototype mutation
                // (a pattern TypeScript accepts and which TS9026 separately flags
                // under --isolatedDeclarations). Skipping prevents an FP TS2720
                // whenever the class's interface representation has been merged with
                // an augmentation that adds members not present in the class body.
                if (baseIfaceName == classNameRaw && typeExpr.typeArguments.isNullOrEmpty()) {
                    continue@typeExprLoop
                }
                val ifaceSymbol = when (val tn = typeExpr.expression) {
                    is PropertyAccessExpression -> resolveHeritageBaseSymbol(tn)
                    else -> globals[baseIfaceName]
                } ?: continue
                // 16.4l: Handle both interface (TS2420) and class (TS2720) targets.
                val isClassTarget = ifaceSymbol.flags.hasAny(SymbolFlags.Class) &&
                    !ifaceSymbol.flags.hasAny(SymbolFlags.Interface)
                val isInterfaceTarget = ifaceSymbol.flags.hasAny(SymbolFlags.Interface)
                if (!isClassTarget && !isInterfaceTarget) continue
                val ifaceType = getDeclaredTypeOfSymbol(ifaceSymbol)
                if (ifaceType !is Type.Object) continue
                resolveStructuredTypeMembers(ifaceType)
                // 16.4k: Include type arguments in the displayed interface name
                // (e.g. `Comparable<string>` not just `Comparable`).
                // 17.55: Use array shorthand `T[]` / `readonly T[]` for `Array<T>` /
                // `ReadonlyArray<T>` to match TypeScript's display convention.
                val ifaceName = typeExpr.typeArguments?.takeIf { it.isNotEmpty() }?.let { args ->
                    val argStrs = args.map { formatTypeForDisplay(it) ?: return@let null }
                    when {
                        baseIfaceName == "Array" && argStrs.size == 1 -> "${argStrs[0]}[]"
                        baseIfaceName == "ReadonlyArray" && argStrs.size == 1 -> "readonly ${argStrs[0]}[]"
                        else -> "$baseIfaceName<${argStrs.joinToString(", ")}>"
                    }
                } ?: baseIfaceName
                val diagCode = if (isClassTarget) 2720 else 2420
                val targetKindWord = if (isClassTarget) "class" else "interface"

                // Collect all missing required properties first.
                // For class targets, also skip static-only members (they belong on the
                // constructor side, not the instance side). We detect this from the
                // source AST declarations since the class-member resolver currently
                // includes static members in the instance property list.
                fun isStaticOnlyProperty(sym: Symbol): Boolean {
                    if (!isClassTarget) return false
                    val decls = sym.declarations
                    if (decls.isEmpty()) return false
                    return decls.all { d ->
                        when (d) {
                            is PropertyDeclaration -> ModifierFlag.Static in d.modifiers
                            is MethodDeclaration -> ModifierFlag.Static in d.modifiers
                            is GetAccessor -> ModifierFlag.Static in d.modifiers
                            is SetAccessor -> ModifierFlag.Static in d.modifiers
                            else -> false
                        }
                    }
                }
                val ifaceProps = ifaceType.properties ?: continue
                val missingProps = mutableListOf<Symbol>()
                for (ifaceProp in ifaceProps) {
                    val propName = ifaceProp.name
                    // 17.55: Skip Object.prototype members (toString, valueOf, etc.) — every
                    // JS object inherits them via the prototype chain, so they're never
                    // truly "missing". Mirrors the filter in `propertiesRelatedTo` /
                    // `collectMissingProperties`.
                    if (propName in OBJECT_PROTOTYPE_PROPERTIES) continue
                    if (propName !in classMemberNames &&
                        !isOptionalProperty(ifaceProp) &&
                        !isStaticOnlyProperty(ifaceProp)) {
                        missingProps.add(ifaceProp)
                    }
                }
                if (missingProps.isNotEmpty()) {
                    val classNameNode = classDecl.name ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    val message = if (isClassTarget) {
                        "Class '$className' incorrectly implements class '$ifaceName'. Did you mean to extend '$ifaceName' and inherit its members as a subclass?"
                    } else {
                        "Class '$className' incorrectly implements $targetKindWord '$ifaceName'."
                    }
                    val chain = mutableListOf<String>()
                    val relatedInfo: List<Diagnostic>
                    if (missingProps.size >= 2) {
                        // TS2740-style chain: "Type 'D' is missing the following properties from type 'I': foo, bar"
                        val missingNames = missingProps.map { it.name }
                        chain.add("  " + formatTs2740Message(className, ifaceName, missingNames))
                        relatedInfo = emptyList()
                    } else {
                        val firstMissing = missingProps[0]
                        chain.add("  Property '${firstMissing.name}' is missing in type '$className' but required in type '$ifaceName'.")
                        // TS2728 related info: point to interface property declaration
                        relatedInfo = firstMissing.valueDeclaration?.let { decl ->
                            val declPos = when (decl) {
                                is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                else -> decl.pos
                            }
                            val declLength = when (decl) {
                                is PropertyDeclaration -> (decl.name as? Identifier)?.text?.length ?: firstMissing.name.length
                                is MethodDeclaration -> (decl.name as? Identifier)?.text?.length ?: firstMissing.name.length
                                else -> firstMissing.name.length
                            }
                            val (rl, rc) = getLineAndCharacterOfPosition(source, declPos)
                            listOf(Diagnostic(
                                message = "'${firstMissing.name}' is declared here.",
                                category = DiagnosticCategory.Message,
                                code = 2728,
                                fileName = fileName,
                                line = rl,
                                character = rc,
                                start = declPos,
                                length = declLength,
                            ))
                        } ?: emptyList()
                    }
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error,
                        code = diagCode,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = classNameRaw.length,
                        messageChain = chain,
                        relatedInformation = relatedInfo,
                    ))
                    // 17.155: One TS2420/TS2720 per implements TARGET, not per class.
                    // `class C implements I1, I2` may emit a separate TS2420 for each
                    // failing interface. Continue to the next typeExpr in the same
                    // clause (and into subsequent clauses) instead of returning.
                    continue@typeExprLoop
                }
                // Check each existing property
                for (ifaceProp in ifaceProps) {
                    val propName = ifaceProp.name
                    if (propName in classMemberNames) {
                        // Property exists — check if it's private (interface members are always public)
                        val classMember = classDecl.members.firstOrNull { m ->
                            when (m) {
                                is PropertyDeclaration -> (m.name as? Identifier)?.text == propName
                                is MethodDeclaration -> (m.name as? Identifier)?.text == propName
                                else -> false
                            }
                        }
                        val isPrivate = when (classMember) {
                            is PropertyDeclaration -> ModifierFlag.Private in classMember.modifiers
                            is MethodDeclaration -> ModifierFlag.Private in classMember.modifiers
                            else -> false
                        }
                        // 17.54: When the property is inherited (no own member), walk the extends
                        // chain to find where it's declared and whether that declaration is private.
                        val rawInheritedPrivate: String? = if (!isPrivate && classMember == null) {
                            findInheritedPrivateProperty(classDecl, propName)
                        } else null
                        // Suppress when the interface ALSO inherits from the same base — the
                        // private declaration is shared, not "separate".
                        val inheritedPrivate: String? = if (rawInheritedPrivate != null &&
                                !symbolTransitivelyExtends(ifaceSymbol, rawInheritedPrivate)) {
                            rawInheritedPrivate
                        } else null
                        val privateInTypeName: String? = when {
                            isPrivate -> className
                            inheritedPrivate != null -> inheritedPrivate
                            else -> null
                        }
                        if (privateInTypeName != null) {
                            val classNameNode = classDecl.name ?: continue
                            val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                            val message = if (isClassTarget) {
                                "Class '$className' incorrectly implements class '$ifaceName'. Did you mean to extend '$ifaceName' and inherit its members as a subclass?"
                            } else {
                                "Class '$className' incorrectly implements $targetKindWord '$ifaceName'."
                            }
                            // Check if the interface property is also private (inherited from a class)
                            val ifacePropDecl = ifaceProp.valueDeclaration ?: ifaceProp.declarations.firstOrNull()
                            val ifacePropIsPrivate = ifacePropDecl != null && isMemberPrivate(ifacePropDecl)
                            // 17.56: Mirror of the TS2415 type-mismatch suppression — when the
                            // class's own private and the interface's inherited private have
                            // DIFFERENT types, suppress TS2420 (TS2416 type-mismatch fires
                            // separately and is the correct primary diagnostic).
                            if (isPrivate && ifacePropIsPrivate && classMember != null && ifacePropDecl != null) {
                                val derivedT = getTypeOfMemberDecl(classMember)
                                val baseT = getTypeOfMemberDecl(ifacePropDecl)
                                if (derivedT != null && baseT != null &&
                                    derivedT !== anyType && baseT !== anyType) {
                                    val widenedDerived = widenType(derivedT)
                                    val widenedBase = widenType(baseT)
                                    if (widenedDerived !== anyType && widenedBase !== anyType &&
                                        (!checkTypeRelatedTo(widenedDerived, widenedBase, assignableRelation) ||
                                            !checkTypeRelatedTo(widenedBase, widenedDerived, assignableRelation))) {
                                        continue
                                    }
                                }
                            }
                            val chain = if (ifacePropIsPrivate) {
                                mutableListOf("  Types have separate declarations of a private property '$propName'.")
                            } else {
                                mutableListOf("  Property '$propName' is private in type '$privateInTypeName' but not in type '$ifaceName'.")
                            }
                            diagnostics.add(Diagnostic(
                                message = message,
                                category = DiagnosticCategory.Error,
                                code = diagCode,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = classNameNode.pos,
                                length = classNameRaw.length,
                                messageChain = chain,
                            ))
                            continue@typeExprLoop
                        }
                    }
                }

                // B82.1b: For `class D extends C<X> implements C<Y>` (or similar class-implements-class
                // with different generic args), compare each method's substituted return type from the
                // implements-target against the same method's substituted type from the class's extends-
                // base. If incompatible → emit TS2720 with "The types returned by 'name()' are incompatible"
                // chain. Narrow gate: only fires when (a) target is a CLASS (not interface),
                // (b) implements typeExpr has type args (resolves to Type.Reference), and (c) the class
                // EXTENDS the same class symbol with DIFFERENT type args (the `D extends C<X> implements
                // C<Y>` shape that motivates this diagnostic). Anything broader risks FP cascading.
                if (isClassTarget && !typeExpr.typeArguments.isNullOrEmpty()) {
                    val implTargetRef = getTypeFromBaseTypeExpression(typeExpr) as? Type.Reference
                    val classSym = globals[classNameRaw]
                    val classDeclaredType = classSym?.let { getDeclaredTypeOfSymbol(it) } as? Type.Interface
                    if (implTargetRef != null && classDeclaredType != null) {
                        // Find the class's extends-base ref for the same target symbol.
                        // findInheritedBaseRef walks baseTypes BFS so multi-level (E extends D extends C<X>)
                        // is supported. The gate requires DIFFERENT type args between extends and implements
                        // — if args match, the implements is trivially satisfied via the extends chain.
                        val extendsBaseRef = findInheritedBaseRef(classDeclaredType, ifaceSymbol)
                        val argsDiffer = extendsBaseRef != null &&
                            implTargetRef.resolvedTypeArguments != extendsBaseRef.resolvedTypeArguments
                        if (extendsBaseRef != null && argsDiffer) {
                            // Walk iface properties, find first mismatch, emit TS2720 with chain.
                            var emitted = false
                            propLoop@ for (ifaceProp in ifaceProps) {
                                if (emitted) break
                                if (ifaceProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                                if (isOptionalProperty(ifaceProp)) continue
                                if (isStaticOnlyProperty(ifaceProp)) continue
                                val expectedType = resolveGenericPropertyType(implTargetRef, ifaceProp) ?: continue
                                val actualType = resolveGenericPropertyType(extendsBaseRef, ifaceProp) ?: continue
                                if (expectedType === errorType || actualType === errorType) continue
                                if (expectedType === anyType || actualType === anyType) continue
                                // For methods (function-typed properties with call signatures), compare
                                // return types directly; this gives the "types returned by 'X()' are
                                // incompatible" chain format. For non-method properties, fall through to
                                // the standard property-incompatibility chain.
                                val expectedSig = (expectedType as? Type.Object)?.callSignatures?.firstOrNull()
                                val actualSig = (actualType as? Type.Object)?.callSignatures?.firstOrNull()
                                if (expectedSig != null && actualSig != null) {
                                    val expectedRet = expectedSig.resolvedReturnType ?: continue
                                    val actualRet = actualSig.resolvedReturnType ?: continue
                                    if (!checkTypeRelatedTo(actualRet, expectedRet, assignableRelation)) {
                                        val actualStr = typeToString(actualRet)
                                        val expectedStr = typeToString(expectedRet)
                                        val classNameNode = classDecl.name ?: continue
                                        val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                                        val message = "Class '$className' incorrectly implements class '$ifaceName'. Did you mean to extend '$ifaceName' and inherit its members as a subclass?"
                                        val chain = mutableListOf(
                                            "  The types returned by '${ifaceProp.name}()' are incompatible between these types.",
                                            "    Type '$actualStr' is not assignable to type '$expectedStr'."
                                        )
                                        diagnostics.add(Diagnostic(
                                            message = message,
                                            category = DiagnosticCategory.Error,
                                            code = 2720,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = classNameNode.pos,
                                            length = classNameRaw.length,
                                            messageChain = chain,
                                        ))
                                        emitted = true
                                    }
                                } else if (expectedSig == null && actualSig == null) {
                                    // Plain property: compare types directly.
                                    if (!checkTypeRelatedTo(actualType, expectedType, assignableRelation)) {
                                        val actualStr = typeToString(actualType)
                                        val expectedStr = typeToString(expectedType)
                                        val classNameNode = classDecl.name ?: continue
                                        val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                                        val message = "Class '$className' incorrectly implements class '$ifaceName'. Did you mean to extend '$ifaceName' and inherit its members as a subclass?"
                                        val chain = mutableListOf(
                                            "  Types of property '${ifaceProp.name}' are incompatible.",
                                            "    Type '$actualStr' is not assignable to type '$expectedStr'."
                                        )
                                        diagnostics.add(Diagnostic(
                                            message = message,
                                            category = DiagnosticCategory.Error,
                                            code = 2720,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = classNameNode.pos,
                                            length = classNameRaw.length,
                                            messageChain = chain,
                                        ))
                                        emitted = true
                                    }
                                }
                            }
                            if (emitted) continue@typeExprLoop
                        }
                    }
                }

                // Check index signatures
                val ifaceStringIdx = ifaceType.stringIndexInfo
                val ifaceNumberIdx = ifaceType.numberIndexInfo
                fun implementsMessage(): String = if (isClassTarget) {
                    "Class '$className' incorrectly implements class '$ifaceName'. Did you mean to extend '$ifaceName' and inherit its members as a subclass?"
                } else {
                    "Class '$className' incorrectly implements $targetKindWord '$ifaceName'."
                }
                if (ifaceNumberIdx != null && !hasNumberIndex && !hasStringIndex) {
                    val classNameNode = classDecl.name ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    val chain = mutableListOf("  Index signature for type 'number' is missing in type '$className'.")
                    diagnostics.add(Diagnostic(
                        message = implementsMessage(),
                        category = DiagnosticCategory.Error,
                        code = diagCode,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = classNameRaw.length,
                        messageChain = chain,
                    ))
                    continue@typeExprLoop
                }
                if (ifaceStringIdx != null && !hasStringIndex) {
                    val classNameNode = classDecl.name ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    val chain = mutableListOf("  Index signature for type 'string' is missing in type '$className'.")
                    diagnostics.add(Diagnostic(
                        message = implementsMessage(),
                        category = DiagnosticCategory.Error,
                        code = diagCode,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = classNameRaw.length,
                        messageChain = chain,
                    ))
                    continue@typeExprLoop
                }
            }
        }
    }

    // 17.54: Walks the extends chain from `classDecl` to find a base class that
    // declares `propName` as `private`. Returns the base class name if found, else
    // null. Returns null also when the first base class declaring the property
    // declares it as public (later derivations would shadow further bases).
    private fun findInheritedPrivateProperty(classDecl: ClassDeclaration, propName: String): String? {
        val extClause = classDecl.heritageClauses?.firstOrNull {
            it.token == SyntaxKind.ExtendsKeyword
        } ?: return null
        for (baseExpr in extClause.types) {
            val baseName = when (val bn = baseExpr.expression) {
                is Identifier -> bn.text
                is PropertyAccessExpression -> (bn.name as? Identifier)?.text
                else -> null
            } ?: continue
            val baseSym = globals[baseName] ?: continue
            val baseClassDecl = baseSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: continue
            val baseMember = baseClassDecl.members.firstOrNull { m ->
                when (m) {
                    is PropertyDeclaration -> (m.name as? Identifier)?.text == propName
                    is MethodDeclaration -> (m.name as? Identifier)?.text == propName
                    else -> false
                }
            }
            if (baseMember != null) {
                val isPrivate = when (baseMember) {
                    is PropertyDeclaration -> ModifierFlag.Private in baseMember.modifiers
                    is MethodDeclaration -> ModifierFlag.Private in baseMember.modifiers
                    else -> false
                }
                return if (isPrivate) baseName else null
            }
            val recursive = findInheritedPrivateProperty(baseClassDecl, propName)
            if (recursive != null) return recursive
        }
        return null
    }

    // 17.54: Walk the extends chain of a class- or interface-symbol to determine
    // whether `targetBaseName` appears anywhere in the transitive chain. Used to
    // suppress TS2420 when both class and interface inherit the same private
    // declaration from a shared base — the property's declaration is the SAME, not
    // "separate", so TypeScript does not emit a privacy mismatch.
    private fun symbolTransitivelyExtends(sym: Symbol, targetBaseName: String, visited: MutableSet<Int> = mutableSetOf()): Boolean {
        if (sym.id in visited) return false
        visited.add(sym.id)
        for (decl in sym.declarations) {
            val heritage = when (decl) {
                is InterfaceDeclaration -> decl.heritageClauses
                is ClassDeclaration -> decl.heritageClauses
                else -> null
            } ?: continue
            for (clause in heritage) {
                if (clause.token != SyntaxKind.ExtendsKeyword) continue
                for (typeExpr in clause.types) {
                    val name = when (val tn = typeExpr.expression) {
                        is Identifier -> tn.text
                        is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                        else -> null
                    } ?: continue
                    if (name == targetBaseName) return true
                    val parentSym = globals[name] ?: continue
                    if (symbolTransitivelyExtends(parentSym, targetBaseName, visited)) return true
                }
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2430: Interface incorrectly extends interface
    // -----------------------------------------------------------------------

    private fun checkInterfaceExtendsInterface() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkInterfaceExtendsInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkInterfaceExtendsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                checkInterfaceExtendsPrimitive(stmt, source, fileName)
                checkInterfaceExtendsClauses(stmt, source, fileName)
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName)
            }
            is FunctionDeclaration -> stmt.body?.let { for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName) }
                        is Constructor -> member.body?.let { for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName) }
                        is GetAccessor -> member.body?.let { for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName) }
                        is SetAccessor -> member.body?.let { for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName) }
                        else -> {}
                    }
                }
            }
            is Block -> for (s in stmt.statements) checkInterfaceExtendsInStatement(s, source, fileName)
            is IfStatement -> {
                checkInterfaceExtendsInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkInterfaceExtendsInStatement(it, source, fileName) }
            }
            is ForStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (s in clause.statements) checkInterfaceExtendsInStatement(s, source, fileName)
                        is DefaultClause -> for (s in clause.statements) checkInterfaceExtendsInStatement(s, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkInterfaceExtendsInStatement(s, source, fileName)
                stmt.catchClause?.block?.statements?.forEach { checkInterfaceExtendsInStatement(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkInterfaceExtendsInStatement(it, source, fileName) }
            }
            is LabeledStatement -> checkInterfaceExtendsInStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    /**
     * TS2840: "An interface cannot extend a primitive type like 'X'. It can only extend other
     * named object types." Fires when an `extends` heritage clause names a primitive type
     * keyword (number/string/boolean/bigint/symbol). The parser produces these as plain
     * Identifier expressions in heritage position.
     */
    private fun checkInterfaceExtendsPrimitive(ifaceDecl: InterfaceDeclaration, source: String, fileName: String) {
        val extendsClauses = ifaceDecl.heritageClauses?.filter {
            it.token == SyntaxKind.ExtendsKeyword
        } ?: return
        for (clause in extendsClauses) {
            for (typeExpr in clause.types) {
                val expr = typeExpr.expression
                if (expr !is Identifier) continue
                if (expr.text !in PRIMITIVE_HERITAGE_NAMES) continue
                val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                diagnostics.add(Diagnostic(
                    message = "An interface cannot extend a primitive type like '${expr.text}'. It can only extend other named object types.",
                    category = DiagnosticCategory.Error,
                    code = 2840,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = expr.pos,
                    length = expr.text.length,
                ))
            }
        }
    }

    private fun checkInterfaceExtendsClauses(ifaceDecl: InterfaceDeclaration, source: String, fileName: String) {
        val extendsClauses = ifaceDecl.heritageClauses?.filter {
            it.token == SyntaxKind.ExtendsKeyword
        } ?: return
        if (extendsClauses.isEmpty()) return

        val derivedName = ifaceDecl.name.text

        // Collect derived interface's property types from AST
        val derivedProps = mutableMapOf<String, TypeNode>()
        // B63.3: Also collect derived methods for arity-based TS2430.
        val derivedMethods = mutableMapOf<String, MethodDeclaration>()
        for (member in ifaceDecl.members) {
            if (member is MethodDeclaration) {
                val mname = (member.name as? Identifier)?.text
                if (mname != null) derivedMethods[mname] = member
            }
            val (name, type) = getMemberNameAndType(member) ?: continue
            if (type != null) derivedProps[name] = type
        }
        if (derivedProps.isEmpty() && derivedMethods.isEmpty()) return

        for (clause in extendsClauses) {
            for (typeExpr in clause.types) {
                val baseName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue

                val baseSymbol = when (val tn = typeExpr.expression) {
                    is PropertyAccessExpression -> resolveHeritageBaseSymbol(tn)
                    else -> globals[baseName]
                } ?: continue
                if (!baseSymbol.flags.hasAny(SymbolFlags.Interface)) continue

                // Get base interface type and resolve members
                val baseType = getDeclaredTypeOfSymbol(baseSymbol)
                if (baseType !is Type.Object) continue
                resolveStructuredTypeMembers(baseType)
                val baseProps = baseType.properties ?: continue

                // Compare each derived property against matching base property
                for (baseProp in baseProps) {
                    val propName = baseProp.name
                    val derivedType = derivedProps[propName]

                    // B63.3: method-vs-method TS2430 with arity mismatch chain.
                    // For `interface Foo { f(): T }` + `interface Bar extends Foo { f(a: U): T }`,
                    // the derived's method requires MORE params than base provides — fire TS2430
                    // with "Target signature provides too few arguments" chain.
                    if (baseProp.flags.hasAny(SymbolFlags.Function)) {
                        val derivedMd = derivedMethods[propName]
                        if (derivedMd != null) {
                            val baseMd = baseProp.declarations.firstOrNull { it is MethodDeclaration } as? MethodDeclaration
                            if (baseMd != null && baseProp.declarations.count { it is MethodDeclaration } == 1) {
                                val derivedRequired = derivedMd.parameters.count {
                                    !it.questionToken && it.initializer == null && !it.dotDotDotToken
                                }
                                val baseMax = baseMd.parameters.count { !it.dotDotDotToken }
                                val baseHasRest = baseMd.parameters.any { it.dotDotDotToken }
                                if (!baseHasRest && derivedRequired > baseMax) {
                                    val derivedSig = methodSigDisplay(derivedMd)
                                    val baseSig = methodSigDisplay(baseMd)
                                    emitTS2430WithMethodArityChain(
                                        ifaceDecl.name, derivedName, baseName, propName,
                                        derivedSig, baseSig, derivedRequired, baseMax,
                                        source, fileName,
                                    )
                                    return
                                }
                            }
                        }
                        continue
                    }
                    if (derivedType == null) continue

                    // Get base property's type
                    val basePropType = getTypeOfSymbol(baseProp)
                    if (basePropType === anyType || basePropType === errorType) continue

                    // Get the base type name for error message
                    val baseTypeName = typeToString(basePropType)

                    // Get derived type name from AST type node
                    val derivedTypeName = typeNodeToSimpleName(derivedType) ?: continue

                    // Skip if same type name
                    if (derivedTypeName == baseTypeName) continue

                    // Check if clearly incompatible using keyword types
                    if (derivedType is KeywordTypeNode) {
                        val derivedSemanticType = getTypeFromKeyword(derivedType.kind)
                        if (derivedSemanticType !== anyType && derivedSemanticType !== errorType) {
                            // Use structural comparison
                            if (!isTypeAssignableTo(derivedSemanticType, basePropType)) {
                                emitTS2430(ifaceDecl.name, derivedName, baseName, propName,
                                    derivedTypeName, baseTypeName, source, fileName)
                                return // One TS2430 per interface per base
                            }
                        }
                    } else {
                        // For non-keyword types, use string comparison as fallback
                        // Only flag if both are simple known type names that differ
                        val derivedResolvedType = getTypeFromTypeNodeSafe(derivedType)
                        if (derivedResolvedType != null && derivedResolvedType !== anyType && derivedResolvedType !== errorType) {
                            if (!isTypeAssignableTo(derivedResolvedType, basePropType)) {
                                emitTS2430(ifaceDecl.name, derivedName, baseName, propName,
                                    derivedTypeName, baseTypeName, source, fileName)
                                return
                            }
                        }
                    }
                }
            }
        }
    }

    private fun getMemberNameAndType(member: ClassElement): Pair<String, TypeNode?>? {
        return when (member) {
            is PropertyDeclaration -> {
                val name = (member.name as? Identifier)?.text ?: return null
                name to member.type
            }
            is MethodDeclaration -> {
                val name = (member.name as? Identifier)?.text ?: return null
                name to member.type // return type
            }
            else -> null
        }
    }

    private fun typeNodeToSimpleName(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.ObjectKeyword -> "object"
                else -> null
            }
            is TypeReference -> (typeNode.typeName as? Identifier)?.text
            else -> null
        }
    }

    private fun getTypeFromTypeNodeSafe(typeNode: TypeNode): Type? {
        return try {
            getTypeFromTypeNode(typeNode)
        } catch (_: StackOverflowError) {
            null
        }
    }

    private fun emitTS2430(
        nameNode: Identifier, derivedName: String, baseName: String, propName: String,
        derivedTypeName: String, baseTypeName: String, source: String, fileName: String,
    ) {
        val start = nameNode.pos
        val length = derivedName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Interface '$derivedName' incorrectly extends interface '$baseName'.",
            category = DiagnosticCategory.Error,
            code = 2430,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf(
                "  Types of property '$propName' are incompatible.",
                "    Type '$derivedTypeName' is not assignable to type '$baseTypeName'.",
            ),
        ))
    }

    /** B63.3: TS2430 for method-vs-method arity mismatch (derived requires more args than base accepts). */
    private fun emitTS2430WithMethodArityChain(
        nameNode: Identifier, derivedName: String, baseName: String, propName: String,
        derivedSig: String, baseSig: String, derivedRequired: Int, baseMax: Int,
        source: String, fileName: String,
    ) {
        val start = nameNode.pos
        val length = derivedName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Interface '$derivedName' incorrectly extends interface '$baseName'.",
            category = DiagnosticCategory.Error,
            code = 2430,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf(
                "  Types of property '$propName' are incompatible.",
                "    Type '$derivedSig' is not assignable to type '$baseSig'.",
                "      Target signature provides too few arguments. Expected $derivedRequired or more, but got $baseMax.",
            ),
        ))
    }

    /** B63.3: render a MethodDeclaration's call-signature as `(p: T, ...) => R` for display. */
    private fun methodSigDisplay(md: MethodDeclaration): String {
        val params = md.parameters.joinToString(", ") { p ->
            val pname = (p.name as? Identifier)?.text ?: "_"
            val ptype = p.type?.let { formatTypeForDisplay(it) } ?: "any"
            val q = if (p.questionToken) "?" else ""
            val rest = if (p.dotDotDotToken) "..." else ""
            "$rest$pname$q: $ptype"
        }
        val ret = md.type?.let { formatTypeForDisplay(it) } ?: "any"
        return "($params) => $ret"
    }

    /**
     * Like [methodSigDisplay] but for derived members that may lack a return type annotation —
     * derives a display from the body's return shape (return literal → string/number/boolean,
     * no return value → void, anything else → any). Used by TS2416 predicate-mismatch chains so
     * `method3() { return true }` displays as `() => boolean` rather than the `() => any` we
     * intentionally inferred for assignment safety (see CLAUDE.md TS2416 gotcha).
     */
    private fun methodSigDisplayWithBodyReturn(md: MethodDeclaration): String {
        val params = md.parameters.joinToString(", ") { p ->
            val pname = (p.name as? Identifier)?.text ?: "_"
            val ptype = p.type?.let { formatTypeForDisplay(it) } ?: "any"
            val q = if (p.questionToken) "?" else ""
            val rest = if (p.dotDotDotToken) "..." else ""
            "$rest$pname$q: $ptype"
        }
        val ret = methodSigReturnDisplay(md)
        return "($params) => $ret"
    }

    /**
     * Like [methodSigColonDisplay] but prefixes the method's own type parameters
     * (`<S extends T>`) — used to render overload-set members in the TS2416 base-type
     * union display `{ <S extends T>(p): this is S[]; (p): boolean; }` (B86.13).
     */
    private fun methodSigColonDisplayWithTypeParams(md: MethodDeclaration): String {
        val tp = md.typeParameters?.takeIf { it.isNotEmpty() }?.let { tps ->
            "<" + tps.joinToString(", ") { p ->
                val name = p.name.text
                val constraint = p.constraint?.let { formatTypeForDisplay(it) }
                if (constraint != null) "$name extends $constraint" else name
            } + ">"
        } ?: ""
        return tp + methodSigColonDisplay(md)
    }

    /** Display a method as `(params): returnType` — used in the "Signature '...' must be a type predicate." chain. */
    private fun methodSigColonDisplay(md: MethodDeclaration): String {
        val params = md.parameters.joinToString(", ") { p ->
            val pname = (p.name as? Identifier)?.text ?: "_"
            val ptype = p.type?.let { formatTypeForDisplay(it) } ?: "any"
            val q = if (p.questionToken) "?" else ""
            val rest = if (p.dotDotDotToken) "..." else ""
            "$rest$pname$q: $ptype"
        }
        val ret = methodSigReturnDisplay(md)
        return "($params): $ret"
    }

    private fun methodSigReturnDisplay(md: MethodDeclaration): String {
        md.type?.let { return formatTypeForDisplay(it) ?: "any" }
        val body = md.body ?: return "any"
        if (!bodyHasReturnValue(body)) return "void"
        for (stmt in body.statements) {
            if (stmt is ReturnStatement) {
                val expr = stmt.expression
                if (expr != null) {
                    return when (expr) {
                        is StringLiteralNode -> "string"
                        is NumericLiteralNode -> "number"
                        is Identifier -> when (expr.text) {
                            "true", "false" -> "boolean"
                            else -> "any"
                        }
                        else -> "any"
                    }
                }
            }
        }
        return "any"
    }

    // -----------------------------------------------------------------------
    // TS2729: Property used before its initialization
    // -----------------------------------------------------------------------

    private fun checkPropertyUseBeforeInit() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkPropertyUseBeforeInitInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) { }
        }
    }

    private fun checkPropertyUseBeforeInitInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> checkClassPropertyUseBeforeInit(stmt, source, fileName)
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let {
                    for (s in it.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
                }
            }
            is IfStatement -> {
                checkPropertyUseBeforeInitInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkPropertyUseBeforeInitInStatement(it, source, fileName) }
            }
            is ForStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> for (s in c.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
                    is DefaultClause -> for (s in c.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
                    else -> {}
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
                stmt.catchClause?.block?.statements?.forEach { checkPropertyUseBeforeInitInStatement(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkPropertyUseBeforeInitInStatement(it, source, fileName) }
            }
            is LabeledStatement -> checkPropertyUseBeforeInitInStatement(stmt.statement, source, fileName)
            is Block -> {
                for (s in stmt.statements) checkPropertyUseBeforeInitInStatement(s, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkClassPropertyUseBeforeInit(classDecl: ClassDeclaration, source: String, fileName: String) {
        // Determine which properties are inherited from base classes (extends, not implements)
        val inheritedNames = mutableSetOf<String>()
        classDecl.heritageClauses?.forEach { clause ->
            if (clause.token != SyntaxKind.ExtendsKeyword) return@forEach
            for (typeExpr in clause.types) {
                val baseName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue
                val baseSymbol = globals[baseName] ?: continue
                collectInheritedPropertyNames(baseSymbol, inheritedNames)
            }
        }

        // Collect property declarations in order, tracking which are "initialized"
        data class PropInfo(val name: String, val pos: Int, val hasInit: Boolean, val hasExcl: Boolean, val hasQuestion: Boolean, val isStatic: Boolean)
        val props = mutableListOf<PropInfo>()
        for (member in classDecl.members) {
            when (member) {
                is PropertyDeclaration -> {
                    val name = (member.name as? Identifier)?.text ?: continue
                    val isStatic = ModifierFlag.Static in member.modifiers
                    props.add(PropInfo(
                        name = name,
                        pos = (member.name as Identifier).pos,
                        hasInit = member.initializer != null,
                        hasExcl = member.exclamationToken,
                        hasQuestion = member.questionToken,
                        isStatic = isStatic,
                    ))
                }
                else -> {}
            }
        }

        // For each property with an initializer, check for this.X references
        val className = classDecl.name?.text
        for ((idx, prop) in props.withIndex()) {
            if (prop.hasInit) {
                // Find the initializer node
                val initExpr = classDecl.members.filterIsInstance<PropertyDeclaration>()
                    .find { (it.name as? Identifier)?.text == prop.name && (ModifierFlag.Static in it.modifiers) == prop.isStatic }
                    ?.initializer ?: continue

                // Collect this.X references (not inside arrow/function)
                val refs = mutableListOf<Pair<String, Int>>() // (propName, pos of propName)
                collectThisPropertyRefs(initExpr, refs, prop.isStatic, className)

                for ((refName, refPos) in refs) {
                    // Check if refName is inherited from base class
                    if (refName in inheritedNames) continue

                    // Find the property declaration for refName
                    val refProp = props.find { it.name == refName && it.isStatic == prop.isStatic }
                    if (refProp == null) continue // not a class property (might be inherited or doesn't exist)

                    // Check if refProp is initialized before the current prop
                    val refIdx = props.indexOf(refProp)
                    val isBeforeInit = if (refIdx < idx) {
                        // Declared ABOVE: error only if it has no initializer of its own,
                        // no `!`, AND is not OPTIONAL. A non-optional, un-initialized
                        // property (e.g. `abstract prop: string`) read by an earlier-running
                        // field IS use-before-init; an OPTIONAL `p5?: number` is legitimately
                        // `undefined` so reading it is fine.
                        !refProp.hasInit && !refProp.hasExcl && !refProp.hasQuestion
                    } else {
                        // Declared below or self-reference — an error (unless has `!`)
                        !refProp.hasExcl
                    }

                    if (isBeforeInit) {
                        val (line, character) = getLineAndCharacterOfPosition(source, refPos)
                        val length = refName.length
                        diagnostics.add(Diagnostic(
                            message = "Property '$refName' is used before its initialization.",
                            category = DiagnosticCategory.Error,
                            code = 2729,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = refPos,
                            length = length,
                            relatedInformation = listOf(Diagnostic(
                                message = "'$refName' is declared here.",
                                category = DiagnosticCategory.Message,
                                code = 2728,
                                fileName = fileName,
                                line = getLineAndCharacterOfPosition(source, refProp.pos).first,
                                character = getLineAndCharacterOfPosition(source, refProp.pos).second,
                                start = refProp.pos,
                                length = refName.length,
                            )),
                        ))
                    }
                }
            }
        }
    }

    /** Collect inherited property names from base class chain (extends only). */
    private fun collectInheritedPropertyNames(symbol: Symbol, names: MutableSet<String>) {
        for (decl in symbol.declarations) {
            if (decl !is ClassDeclaration) continue
            for (member in decl.members) {
                if (member is PropertyDeclaration) {
                    val name = (member.name as? Identifier)?.text ?: continue
                    names.add(name)
                }
                if (member is MethodDeclaration) {
                    val name = (member.name as? Identifier)?.text ?: continue
                    names.add(name)
                }
            }
            // Recurse into base classes
            decl.heritageClauses?.forEach { clause ->
                if (clause.token != SyntaxKind.ExtendsKeyword) return@forEach
                for (typeExpr in clause.types) {
                    val baseName = when (val tn = typeExpr.expression) {
                        is Identifier -> tn.text
                        else -> null
                    } ?: continue
                    val baseSymbol = globals[baseName] ?: continue
                    collectInheritedPropertyNames(baseSymbol, names)
                }
            }
        }
    }

    /** Collect this.X (or ClassName.X for statics) property references in an expression.
     *  Skips inside arrow functions and function expressions (deferred evaluation). */
    private fun collectThisPropertyRefs(
        expr: Node, refs: MutableList<Pair<String, Int>>,
        isStatic: Boolean, className: String?,
        // True once recursion has descended through an object-spread (`...{...}`).
        // TypeScript does NOT report use-before-init for a getter/setter/method
        // computed name nested inside a spread object (`...{get [D.D]() {}}`), only
        // for a DIRECT object-literal accessor/method. A direct PropertyAssignment
        // computed name still fires regardless.
        viaSpread: Boolean = false,
    ) {
        when (expr) {
            is PropertyAccessExpression -> {
                val obj = expr.expression
                val isRelevant = if (isStatic) {
                    // For static props: ClassName.X
                    obj is Identifier && className != null && obj.text == className
                } else {
                    // For instance props: this.X
                    obj is Identifier && obj.text == "this"
                }
                if (isRelevant) {
                    refs.add(expr.name.text to expr.name.pos)
                }
                // Also recurse into the expression and name
                collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            }
            // Skip arrow functions and function expressions (deferred evaluation)
            is ArrowFunction -> return
            is FunctionExpression -> return
            // Recurse into subexpressions
            is CallExpression -> {
                collectThisPropertyRefs(expr.expression, refs, isStatic, className)
                expr.arguments?.forEach { collectThisPropertyRefs(it, refs, isStatic, className) }
            }
            is BinaryExpression -> {
                // A simple assignment `this.X = ...` WRITES X — that is not a "use" of
                // X (TypeScript doesn't flag it). Skip the direct ref of the LHS name but
                // still recurse into the receiver (so `this.a.b = ...` still counts a use
                // of `this.a`) and the RHS.
                val left = expr.left
                val isWriteTargetRef = expr.operator == SyntaxKind.Equals &&
                    left is PropertyAccessExpression &&
                    (if (isStatic) (left.expression as? Identifier)?.text == className
                     else (left.expression as? Identifier)?.text == "this")
                if (isWriteTargetRef) {
                    collectThisPropertyRefs((left as PropertyAccessExpression).expression, refs, isStatic, className)
                } else {
                    collectThisPropertyRefs(expr.left, refs, isStatic, className)
                }
                collectThisPropertyRefs(expr.right, refs, isStatic, className)
            }
            is ConditionalExpression -> {
                collectThisPropertyRefs(expr.condition, refs, isStatic, className)
                collectThisPropertyRefs(expr.whenTrue, refs, isStatic, className)
                collectThisPropertyRefs(expr.whenFalse, refs, isStatic, className)
            }
            is ParenthesizedExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is PrefixUnaryExpression -> collectThisPropertyRefs(expr.operand, refs, isStatic, className)
            is PostfixUnaryExpression -> collectThisPropertyRefs(expr.operand, refs, isStatic, className)
            is NewExpression -> {
                collectThisPropertyRefs(expr.expression, refs, isStatic, className)
                expr.arguments?.forEach { collectThisPropertyRefs(it, refs, isStatic, className) }
            }
            is ElementAccessExpression -> {
                collectThisPropertyRefs(expr.expression, refs, isStatic, className)
                collectThisPropertyRefs(expr.argumentExpression, refs, isStatic, className)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            prop.name?.let { if (it is ComputedPropertyName) collectThisPropertyRefs(it.expression, refs, isStatic, className) }
                            collectThisPropertyRefs(prop.initializer, refs, isStatic, className)
                        }
                        is SpreadAssignment -> collectThisPropertyRefs(prop.expression, refs, isStatic, className, viaSpread = true)
                        is ShorthandPropertyAssignment -> {}
                        // A computed name on a DIRECT object-literal method/accessor is
                        // evaluated eagerly (`{ get [this.X]() {} }`), so `this.X` there is a
                        // use. Inside a spread (`...{get [D.D]() {}}`) TypeScript does NOT
                        // report it — gate on !viaSpread. The accessor/method BODY is
                        // deferred and intentionally not recursed.
                        is MethodDeclaration -> if (!viaSpread) (prop.name as? ComputedPropertyName)?.let { collectThisPropertyRefs(it.expression, refs, isStatic, className) }
                        is GetAccessor -> if (!viaSpread) (prop.name as? ComputedPropertyName)?.let { collectThisPropertyRefs(it.expression, refs, isStatic, className) }
                        is SetAccessor -> if (!viaSpread) (prop.name as? ComputedPropertyName)?.let { collectThisPropertyRefs(it.expression, refs, isStatic, className) }
                        else -> {}
                    }
                }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { collectThisPropertyRefs(it, refs, isStatic, className) }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { span ->
                    collectThisPropertyRefs(span.expression, refs, isStatic, className)
                }
            }
            is AsExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is NonNullExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is SpreadElement -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is TypeAssertionExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is TaggedTemplateExpression -> {
                collectThisPropertyRefs(expr.tag, refs, isStatic, className)
            }
            is AwaitExpression -> expr.expression?.let { collectThisPropertyRefs(it, refs, isStatic, className) }
            is VoidExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is TypeOfExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is DeleteExpression -> collectThisPropertyRefs(expr.expression, refs, isStatic, className)
            is YieldExpression -> expr.expression?.let { collectThisPropertyRefs(it, refs, isStatic, className) }
            is ClassExpression -> {
                // Heritage-clause expressions (`class extends this.X`) are evaluated
                // eagerly when the class expression is created, so `this.X` / `ClassName.X`
                // there is a use — for instance props too (not just static). The class
                // BODY is deferred and intentionally not recursed.
                expr.heritageClauses?.forEach { clause ->
                    for (typeExpr in clause.types) {
                        collectThisPropertyRefs(typeExpr.expression, refs, isStatic, className)
                    }
                }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2416: Property type incompatible with base type
    // -----------------------------------------------------------------------

    private fun checkPropertyOverride() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                for (stmt in result.sourceFile.statements) {
                    checkPropertyOverrideInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkPropertyOverrideInStatement(stmt: Statement, source: String, fileName: String, enclosingNs: List<Symbol> = emptyList()) {
        when (stmt) {
            is ClassDeclaration -> {
                checkClassPropertyOverrides(stmt, source, fileName, enclosingNs)
                // Recurse into nested class declarations in member bodies
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is Constructor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is GetAccessor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is SetAccessor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    // Track the enclosing namespace so heritage-base names declared inside
                    // it shadow same-named globals (see checkClassPropertyOverrides).
                    val nameNode = stmt.name
                    val moduleSymbol = if (nameNode is Identifier && ModifierFlag.Declare !in stmt.modifiers) {
                        if (enclosingNs.isNotEmpty()) enclosingNs.last().exports?.get(nameNode.text)
                        else currentFileLocals?.get(nameNode.text) ?: globals[nameNode.text]
                    } else null
                    val childNs = if (moduleSymbol != null && moduleSymbol.flags.hasAny(SymbolFlags.Module))
                        enclosingNs + moduleSymbol else enclosingNs
                    for (s in body.statements) checkPropertyOverrideInStatement(s, source, fileName, childNs)
                }
            }
            is FunctionDeclaration -> stmt.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
            is Block -> for (s in stmt.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
            is IfStatement -> {
                checkPropertyOverrideInStatement(stmt.thenStatement, source, fileName, enclosingNs)
                stmt.elseStatement?.let { checkPropertyOverrideInStatement(it, source, fileName, enclosingNs) }
            }
            is ForStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            is ForInStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            is ForOfStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            is WhileStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            is DoStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (s in clause.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
                        is DefaultClause -> for (s in clause.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
                stmt.catchClause?.block?.statements?.forEach { checkPropertyOverrideInStatement(it, source, fileName, enclosingNs) }
                stmt.finallyBlock?.statements?.forEach { checkPropertyOverrideInStatement(it, source, fileName, enclosingNs) }
            }
            is LabeledStatement -> checkPropertyOverrideInStatement(stmt.statement, source, fileName, enclosingNs)
            // round 44 iter1: walk ExpressionStatement / ReturnStatement / VariableStatement
            // initializers so ClassExpression nested in arrow/function bodies is reached for
            // TS2416 override checks.
            is ExpressionStatement -> checkPropertyOverrideInExpr(stmt.expression, source, fileName, enclosingNs)
            is ReturnStatement -> stmt.expression?.let { checkPropertyOverrideInExpr(it, source, fileName, enclosingNs) }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkPropertyOverrideInExpr(it, source, fileName, enclosingNs) }
            }
            else -> {}
        }
    }

    private fun checkPropertyOverrideInExpr(expr: Expression, source: String, fileName: String, enclosingNs: List<Symbol> = emptyList()) {
        when (expr) {
            is ClassExpression -> {
                // Build a synthetic ClassDeclaration check by inlining the logic.
                // Easier: walk members and run the same heritage-aware override check.
                checkClassExprPropertyOverrides(expr, source, fileName)
                // Recurse into nested member bodies.
                for (member in expr.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is Constructor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is GetAccessor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is SetAccessor -> member.body?.let { for (s in it.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs) }
                        is PropertyDeclaration -> member.initializer?.let { checkPropertyOverrideInExpr(it, source, fileName, enclosingNs) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> for (s in body.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
                is Expression -> checkPropertyOverrideInExpr(body, source, fileName, enclosingNs)
                else -> {}
            }
            is FunctionExpression -> for (s in expr.body.statements) checkPropertyOverrideInStatement(s, source, fileName, enclosingNs)
            is ParenthesizedExpression -> checkPropertyOverrideInExpr(expr.expression, source, fileName, enclosingNs)
            is AsExpression -> checkPropertyOverrideInExpr(expr.expression, source, fileName, enclosingNs)
            is TypeAssertionExpression -> checkPropertyOverrideInExpr(expr.expression, source, fileName, enclosingNs)
            is SatisfiesExpression -> checkPropertyOverrideInExpr(expr.expression, source, fileName, enclosingNs)
            is NonNullExpression -> checkPropertyOverrideInExpr(expr.expression, source, fileName, enclosingNs)
            else -> {}
        }
    }

    private fun checkClassExprPropertyOverrides(classExpr: ClassExpression, source: String, fileName: String) {
        // Adapter: convert ClassExpression into something checkClassPropertyOverrides can
        // operate on. The function takes ClassDeclaration but only reads heritage/name/members
        // — none of which are unique to ClassDeclaration. Easier: skip the check for
        // ClassExpression (TypeScript also runs override checks on class expressions, but
        // our adapter would require restructuring checkClassPropertyOverrides). Conservative
        // no-op for now — the recursion into member bodies still applies.
        // (Out of scope for this iteration — only the recursion is the value here.)
    }

    private fun checkClassPropertyOverrides(classDecl: ClassDeclaration, source: String, fileName: String, enclosingNs: List<Symbol> = emptyList()) {
        val heritageClauses = classDecl.heritageClauses ?: return
        val rawClassName = classDecl.name?.text ?: return
        val classTypeParams = classDecl.typeParameters
        val className = if (classTypeParams != null && classTypeParams.isNotEmpty()) {
            "$rawClassName<${classTypeParams.joinToString(", ") { it.name.text }}>"
        } else rawClassName

        // Push class type params into scope so member declarations like `target: T` resolve
        // T to the class's canonical Type.TypeParam instead of errorType. Without this,
        // `class MyEvent<T> extends BaseEvent { target: T; }` would have `derivedType = errorType`
        // which trivially passes the TS2416 check.
        val savedScope = currentTypeParamScope
        if (classTypeParams != null && classTypeParams.isNotEmpty()) {
            val classSymbol = globals[rawClassName]
            val classType = classSymbol?.let {
                try { getDeclaredTypeOfSymbol(it) as? Type.Interface } catch (_: StackOverflowError) { null }
            }
            val canonicalTypeParams = classType?.typeParameters
            if (canonicalTypeParams != null && canonicalTypeParams.size == classTypeParams.size) {
                val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                canonicalTypeParams.forEachIndexed { i, tp ->
                    scope[classTypeParams[i].name.text] = tp
                }
                currentTypeParamScope = scope
            }
        }
        try {

        for (clause in heritageClauses) {
            for (typeExpr in clause.types) {
                val tnExpr = typeExpr.expression
                val baseName = when (tnExpr) {
                    is Identifier -> tnExpr.text
                    is PropertyAccessExpression -> (tnExpr.name as? Identifier)?.text
                    else -> null
                } ?: continue

                // Resolve the heritage base name with namespace awareness: a class
                // declared inside `namespace M` whose base name is also declared in M
                // must bind to M's member, not the global of the same name (e.g.
                // `namespace M { interface I1 {item:string} class C implements I1 {...} }`
                // — C's base is M.I1, not the outer `interface I1 {item:number}`). Bare
                // names consult the enclosing-namespace chain innermost-first; qualified
                // names (`M2.M3.I1`) resolve through the value-position dotted-name resolver.
                // Falls back to `globals[baseName]` (prior behavior) when not shadowed.
                val baseSymbol = run {
                    when (tnExpr) {
                        is Identifier -> {
                            for (ns in enclosingNs.asReversed()) {
                                val s = ns.exports?.get(tnExpr.text)
                                if (s != null && s.flags.hasAny(SymbolFlags.Interface or SymbolFlags.Class)) {
                                    return@run s
                                }
                            }
                            globals[tnExpr.text]
                        }
                        is PropertyAccessExpression -> resolveQualifiedValueSymbol(tnExpr) ?: globals[baseName]
                        else -> globals[baseName]
                    }
                } ?: continue
                val baseTypeRawOriginal = getDeclaredTypeOfSymbol(baseSymbol)
                // 17.50: For `class C implements Wrapper` where `type Wrapper = Foo & Bar`
                // (Type.Intersection of class/interface types), build a synthetic merged
                // Type.Object so the existing TS2416 / TS2423 / TS2425 / TS2426 walk applies.
                // Display the base type as the intersection ("Foo & Bar"), not the synthetic
                // merged shape. Implements-only — `extends` accepts a single class.
                val isIntersectionImplements = clause.token == SyntaxKind.ImplementsKeyword &&
                    baseTypeRawOriginal is Type.Intersection
                val baseTypeRaw: Type.Object = when {
                    isIntersectionImplements -> {
                        val constituents = (baseTypeRawOriginal as Type.Intersection).types
                            .mapNotNull { it as? Type.Object }
                        if (constituents.isEmpty()) continue
                        val merged = symbolTable()
                        for (c in constituents) {
                            resolveStructuredTypeMembers(c)
                            c.members?.forEach { (n, s) -> merged[n] = s }
                        }
                        Type.Object().apply {
                            members = merged
                            properties = merged.values.toList()
                        }
                    }
                    baseTypeRawOriginal is Type.Object -> baseTypeRawOriginal
                    else -> continue
                }
                // Instantiate generic base when heritage clause supplies type args
                // (`implements IFoo<number>`, `extends List<string>`). Without this,
                // member comparison runs against the raw generic interface and
                // `foo(x: T): T` looks like `(x: T) => T` instead of `(x: number) => number`,
                // masking TS2416 mismatches in concrete generic implementations.
                val baseType: Type.Object = run {
                    val args = typeExpr.typeArguments
                    if (baseTypeRaw is Type.Interface && baseTypeRaw !is Type.Reference &&
                        !args.isNullOrEmpty()) {
                        val tparams = baseTypeRaw.typeParameters
                        if (!tparams.isNullOrEmpty() && tparams.size == args.size) {
                            try {
                                val resolved = args.map { getTypeFromTypeNode(it) }
                                if (resolved.none { it === errorType }) {
                                    return@run getOrInternReference(baseTypeRaw, resolved)
                                }
                            } catch (_: StackOverflowError) {}
                        }
                    }
                    baseTypeRaw
                }
                resolveStructuredTypeMembers(baseType)
                val baseMembers = baseType.members ?: continue

                val baseTypeName = if (isIntersectionImplements) {
                    typeToString(baseTypeRawOriginal)
                } else {
                    typeToString(baseType)
                }

                // TS2415: Check private member conflicts (only for extends, not implements)
                if (clause.token == SyntaxKind.ExtendsKeyword) {
                    val ts2415Emitted = checkClassExtendsPrivateConflicts(
                        classDecl, baseName, baseType, baseMembers, source, fileName
                    )
                    if (ts2415Emitted) continue // skip TS2416 checks for this base
                }

                // Collect method names that appear multiple times (overloads) — skip these
                val overloadedMethods = mutableMapOf<String, Int>()
                for (member in classDecl.members) {
                    if (member is MethodDeclaration) {
                        val name = (member.name as? Identifier)?.text ?: continue
                        overloadedMethods[name] = (overloadedMethods[name] ?: 0) + 1
                    }
                }

                for (member in classDecl.members) {
                    // Skip static members
                    val isStatic = when (member) {
                        is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                        is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                        is GetAccessor -> ModifierFlag.Static in member.modifiers
                        is SetAccessor -> ModifierFlag.Static in member.modifiers
                        else -> true
                    }
                    if (isStatic) continue

                    val memberName = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        is GetAccessor -> (member.name as? Identifier)?.text
                        is SetAccessor -> (member.name as? Identifier)?.text
                        else -> null
                    } ?: continue

                    // Skip overloaded methods (need full overload resolution)
                    if (member is MethodDeclaration && (overloadedMethods[memberName] ?: 0) > 1) continue

                    val basePropSymbol = baseMembers[memberName] ?: continue

                    // Skip if base member has multiple declarations (overloads)
                    if (basePropSymbol.declarations.size > 1) {
                        // B86.13: predicate-overload mismatch. When the base member is an
                        // OVERLOAD SET and at least one overload's return type is a non-asserting
                        // type predicate (e.g. `every<S extends T>(...): this is S[]`), a derived
                        // override that is NOT itself a type predicate must still be flagged
                        // (TS2416) — the derived can never satisfy the predicate overload. The
                        // sibling non-predicate overload (e.g. `filter(...): T[]`) does NOT trigger
                        // this, so `filter` stays clean while `every` fires. Mirrors B68.6 but for
                        // the multi-declaration base case, with the overload-union base display.
                        val derivedMd = member as? MethodDeclaration
                        if (derivedMd != null && (derivedMd.type as? TypePredicate) == null) {
                            val baseOverloads = basePropSymbol.declarations.filterIsInstance<MethodDeclaration>()
                            val predicateOverload = baseOverloads.firstOrNull { ov ->
                                (ov.type as? TypePredicate)?.let { !it.assertsModifier } == true
                            }
                            if (predicateOverload != null && baseOverloads.size == basePropSymbol.declarations.size) {
                                val nameNode = derivedMd.name
                                val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                                val unionDisplay = "{ " +
                                    baseOverloads.joinToString("; ") { methodSigColonDisplayWithTypeParams(it) } +
                                    "; }"
                                val derivedDisplay = methodSigDisplayWithBodyReturn(derivedMd)
                                val sigColon = methodSigColonDisplay(derivedMd)
                                diagnostics.add(Diagnostic(
                                    message = "Property '$memberName' in type '$className' is not assignable to the same property in base type '$baseTypeName'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2416,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = nameNode.pos,
                                    length = memberName.length,
                                    messageChain = listOf(
                                        "  Type '$derivedDisplay' is not assignable to type '$unionDisplay'.",
                                        "    Signature '$sigColon' must be a type predicate.",
                                    ),
                                ))
                            }
                        }
                        continue
                    }

                    val baseDecl = basePropSymbol.valueDeclaration ?: basePropSymbol.declarations.firstOrNull() ?: continue

                    // Shape-mismatch diagnostics (TS2423/TS2425/TS2426) take priority over TS2416.
                    // These fire when base and derived disagree on member category (property/method/accessor)
                    // regardless of type assignability — emit BEFORE type resolution so cases where we
                    // can't resolve types (e.g. accessor whose return type we can't infer from body) still fire.
                    val nameNode = when (member) {
                        is PropertyDeclaration -> member.name
                        is MethodDeclaration -> member.name
                        is GetAccessor -> member.name
                        is SetAccessor -> member.name
                        else -> null
                    } ?: continue
                    val shapeDiag = classMemberShapeMismatchDiagnostic(
                        baseDecl, member, memberName, baseTypeName, className,
                        isImplements = clause.token == SyntaxKind.ImplementsKeyword,
                    )
                    // Only emit shape diagnostic ONCE per method (skip for the paired setter when
                    // the getter already emitted — baseline expects one TS2423 per accessor override).
                    val isSetAccessorWithGet = member is SetAccessor &&
                        classDecl.members.any { it is GetAccessor && (it.name as? Identifier)?.text == memberName }
                    if (shapeDiag != null && !isSetAccessorWithGet) {
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = shapeDiag.second,
                            category = DiagnosticCategory.Error,
                            code = shapeDiag.first,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = memberName.length,
                        ))
                        // TS2423/TS2426 allow TS2416 to fire in parallel when types also disagree
                        // (e.g. accessor→method overrides). TS2425 (property→method) suppresses TS2416
                        // because the declared types are necessarily equal by construction.
                        // Fall through and let TS2416 fire if applicable.
                    }

                    val derivedType = getTypeOfMemberDecl(member) ?: continue
                    // For Type.Reference bases, use getPropertyTypeForRelation to obtain the
                    // mapper-instantiated property type. `getTypeOfMemberDecl(baseDecl)` returns
                    // the raw declared type (`(x: T) => T`); we need the substituted form
                    // (`(x: number) => number`) so TS2416 fires for `implements IFoo<number>`
                    // when the override has the wrong signature.
                    val basePropType = if (baseType is Type.Reference) {
                        getPropertyTypeForRelation(baseType, basePropSymbol)
                    } else {
                        getTypeOfMemberDecl(baseDecl) ?: continue
                    }

                    if (derivedType === anyType || basePropType === anyType) continue

                    // B68.6: type-predicate mismatch — when the base method's return type is a
                    // non-asserting `this is X` predicate, the derived must also be a type predicate.
                    // The raw assignability check sees both signatures returning boolean (TypePredicate
                    // resolves to booleanType via getTypeFromTypeNode), so a derived `(): boolean`
                    // override silently passes structurally. This block detects that and forces TS2416
                    // with the "must be a type predicate" chain.
                    val baseMethodDecl = baseDecl as? MethodDeclaration
                    val derivedMethodDecl = member as? MethodDeclaration
                    val basePredicate = baseMethodDecl?.type as? TypePredicate
                    val derivedPredicate = derivedMethodDecl?.type as? TypePredicate
                    val isPredicateMismatch = basePredicate != null &&
                        !basePredicate.assertsModifier &&
                        derivedMethodDecl != null &&
                        derivedPredicate == null

                    val baseDisplayForChain = if (isPredicateMismatch && baseMethodDecl != null) {
                        methodSigDisplay(baseMethodDecl)
                    } else {
                        typeToString(basePropType)
                    }
                    val derivedDisplayForChain = if (isPredicateMismatch && derivedMethodDecl != null) {
                        methodSigDisplayWithBodyReturn(derivedMethodDecl)
                    } else {
                        typeToString(derivedType)
                    }

                    val assignable = checkTypeRelatedTo(derivedType, basePropType, assignableRelation)

                    if (!assignable || isPredicateMismatch) {
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        val message = "Property '$memberName' in type '$className' is not assignable to the same property in base type '$baseTypeName'."
                        val chain = mutableListOf<String>()
                        chain.add("  Type '$derivedDisplayForChain' is not assignable to type '$baseDisplayForChain'.")

                        // TS2208 related info: when derived is an unconstrained TypeParam declared
                        // on this class, hint that adding `extends {}` might resolve the mismatch.
                        val relatedInfo = mutableListOf<Diagnostic>()
                        if (isPredicateMismatch && derivedMethodDecl != null) {
                            val sigColon = methodSigColonDisplay(derivedMethodDecl)
                            chain.add("    Signature '$sigColon' must be a type predicate.")
                        } else {
                            // Add signature elaboration for function types
                            // (also populates `relatedInfo` with TS2208 when base has a
                            // method-level TypeParam that derived overrides with a concrete type).
                            addSignatureElaboration(derivedType, basePropType, chain, relatedInfo, fileName, source, classTypeParams)
                        }
                        if (derivedType is Type.TypeParam && derivedType.constraint == null &&
                            classTypeParams != null) {
                            val tpName = derivedType.symbol?.name
                            val tpDecl = classTypeParams.firstOrNull { it.name.text == tpName }
                            if (tpDecl != null) {
                                val tpPos = tpDecl.name.pos
                                val (tpLine, tpChar) = getLineAndCharacterOfPosition(source, tpPos)
                                relatedInfo.add(Diagnostic(
                                    message = "This type parameter might need an `extends {}` constraint.",
                                    category = DiagnosticCategory.Message,
                                    code = 2208,
                                    fileName = fileName,
                                    line = tpLine,
                                    character = tpChar,
                                    start = tpPos,
                                    length = tpDecl.name.text.length,
                                ))
                            }
                        }

                        diagnostics.add(Diagnostic(
                            message = message,
                            category = DiagnosticCategory.Error,
                            code = 2416,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = memberName.length,
                            messageChain = chain,
                            relatedInformation = relatedInfo,
                        ))
                    }
                }

                // TS2417: Check static side extends (only for extends, not implements)
                if (clause.token == SyntaxKind.ExtendsKeyword) {
                    checkClassStaticSideExtends(classDecl, rawClassName, baseName, baseSymbol, source, fileName)
                }
            }
        }
        } finally {
            currentTypeParamScope = savedScope
        }
    }

    /**
     * Determine whether a member in the derived class disagrees with the base's declaration on
     * member category (property / method / accessor). Returns the (code, message) pair, or null
     * when no shape mismatch applies. Takes priority over TS2416 because TypeScript emits these
     * specific codes instead of the generic "not assignable" message.
     */
    private fun classMemberShapeMismatchDiagnostic(
        baseDecl: Node,
        derivedMember: ClassElement,
        memberName: String,
        baseTypeName: String,
        derivedClassName: String,
        isImplements: Boolean = false,
    ): Pair<Int, String>? {
        val baseKind = when (baseDecl) {
            // Property with function-type annotation counts as "property", not "function"
            is PropertyDeclaration -> "property"
            is MethodDeclaration -> "function"
            is GetAccessor, is SetAccessor -> "accessor"
            else -> return null
        }
        val derivedKind = when (derivedMember) {
            is PropertyDeclaration -> "property"
            is MethodDeclaration -> "function"
            is GetAccessor, is SetAccessor -> "accessor"
            else -> return null
        }
        if (baseKind == derivedKind) return null

        // TS2423: base function → derived accessor
        // TS2425: base property → derived function
        // TS2426: base accessor → derived function
        // TS2610/TS2611: related but different (get-only vs set-only override) — not handled here.
        val code = when {
            baseKind == "function" && derivedKind == "accessor" -> 2423
            baseKind == "property" && derivedKind == "function" -> 2425
            baseKind == "accessor" && derivedKind == "function" -> 2426
            else -> return null
        }
        // TS2425 is class-property-vs-class-method runtime conflict (instance field shadows
        // prototype method). Interfaces don't have prototype semantics — function-typed
        // properties are structurally compatible with method declarations under `implements`.
        if (code == 2425 && isImplements) return null
        val baseWord = "instance member $baseKind"
        val derivedWord = "instance member $derivedKind"
        val msg = "Class '$baseTypeName' defines $baseWord '$memberName', " +
            "but extended class '$derivedClassName' defines it as $derivedWord."
        return code to msg
    }

    /**
     * TS2415: Check private member conflicts between derived class and base class.
     * Returns true if a TS2415 diagnostic was emitted (so TS2416 should be skipped).
     */
    private fun checkClassExtendsPrivateConflicts(
        classDecl: ClassDeclaration,
        baseName: String,
        baseType: Type.Object,
        baseMembers: SymbolTable,
        source: String,
        fileName: String,
    ): Boolean {
        val rawClassName = classDecl.name?.text ?: return false
        val classNameNode = classDecl.name ?: return false

        // Collect derived class members including constructor parameter properties
        data class DerivedMember(val name: String, val isPrivate: Boolean, val node: ClassElement)
        val derivedMembers = mutableListOf<DerivedMember>()
        for (member in classDecl.members) {
            when (member) {
                is PropertyDeclaration -> {
                    if (ModifierFlag.Static in member.modifiers) continue
                    val name = (member.name as? Identifier)?.text ?: continue
                    derivedMembers.add(DerivedMember(name, ModifierFlag.Private in member.modifiers, member))
                }
                is MethodDeclaration -> {
                    if (ModifierFlag.Static in member.modifiers) continue
                    val name = (member.name as? Identifier)?.text ?: continue
                    derivedMembers.add(DerivedMember(name, ModifierFlag.Private in member.modifiers, member))
                }
                is GetAccessor -> {
                    if (ModifierFlag.Static in member.modifiers) continue
                    val name = (member.name as? Identifier)?.text ?: continue
                    derivedMembers.add(DerivedMember(name, ModifierFlag.Private in member.modifiers, member))
                }
                is SetAccessor -> {
                    if (ModifierFlag.Static in member.modifiers) continue
                    val name = (member.name as? Identifier)?.text ?: continue
                    derivedMembers.add(DerivedMember(name, ModifierFlag.Private in member.modifiers, member))
                }
                is Constructor -> {
                    // Constructor parameter properties (public/private/protected p: T)
                    for (param in member.parameters) {
                        if (param.modifiers.isEmpty()) continue
                        val name = (param.name as? Identifier)?.text ?: continue
                        derivedMembers.add(DerivedMember(name, ModifierFlag.Private in param.modifiers, member))
                    }
                }
                else -> continue
            }
        }

        for (dm in derivedMembers) {
            val memberName = dm.name
            val baseMemberSym = baseMembers[memberName] ?: continue
            val baseDecl = baseMemberSym.valueDeclaration ?: baseMemberSym.declarations.firstOrNull() ?: continue

            val derivedIsPrivate = dm.isPrivate
            val baseIsPrivate = isMemberPrivate(baseDecl)

            if (!derivedIsPrivate && !baseIsPrivate) continue

            val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
            val chain = mutableListOf<String>()

            if (derivedIsPrivate && baseIsPrivate) {
                // 17.56: Suppress TS2415 "separate declarations" when the override has a
                // DIFFERENT type than the base — TS2416 type-mismatch is the correct
                // primary diagnostic for that case (TypeScript's behavior for
                // `interfaceExtendsClassWithPrivate2`'s `D2` whose `private x = ""` shadows
                // `C`'s `private x = 1`). When types match, TS2415 still fires (e.g. `D`'s
                // `private x = 2` shadowing `private x = 1` — same type, separate decl).
                val derivedT = getTypeOfMemberDecl(dm.node)
                val baseT = getTypeOfMemberDecl(baseDecl)
                if (derivedT != null && baseT != null &&
                    derivedT !== anyType && baseT !== anyType) {
                    val widenedDerived = widenType(derivedT)
                    val widenedBase = widenType(baseT)
                    if (widenedDerived !== anyType && widenedBase !== anyType &&
                        (!checkTypeRelatedTo(widenedDerived, widenedBase, assignableRelation) ||
                            !checkTypeRelatedTo(widenedBase, widenedDerived, assignableRelation))) {
                        // Types differ — skip TS2415 emission; TS2416 walk will fire.
                        continue
                    }
                }
                // Both private from different classes → separate declarations
                chain.add("  Types have separate declarations of a private property '$memberName'.")
            } else {
                // One is private, other isn't
                // Find the declaring class for the base member (may be grandparent)
                val baseDeclaringClass = if (baseIsPrivate) {
                    findPrivateDeclaringClassName(baseType, memberName) ?: baseName
                } else {
                    findDeclaringClassName(baseType, memberName) ?: baseName
                }
                val privateTypeName = if (baseIsPrivate) baseDeclaringClass else rawClassName
                val publicTypeName = if (baseIsPrivate) rawClassName else baseDeclaringClass
                chain.add("  Property '$memberName' is private in type '$privateTypeName' but not in type '$publicTypeName'.")
            }

            diagnostics.add(Diagnostic(
                message = "Class '$rawClassName' incorrectly extends base class '$baseName'.",
                category = DiagnosticCategory.Error,
                code = 2415,
                fileName = fileName,
                line = line,
                character = character,
                start = classNameNode.pos,
                length = rawClassName.length,
                messageChain = chain,
            ))
            return true // Only report first conflict per class
        }
        return false
    }

    /**
     * TS2417: Check static side of derived class against base class static side.
     * Compares static members + namespace exports for type incompatibility and private conflicts.
     */
    private fun checkClassStaticSideExtends(
        classDecl: ClassDeclaration,
        rawClassName: String,
        baseName: String,
        baseSymbol: Symbol,
        source: String,
        fileName: String,
    ) {
        val classNameNode = classDecl.name ?: return

        // Collect derived class static members from AST
        data class StaticInfo(val isPrivate: Boolean, val isCallable: Boolean, val node: Node)
        val derivedStatics = mutableMapOf<String, StaticInfo>()
        for (member in classDecl.members) {
            val isStatic = when (member) {
                is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                is GetAccessor -> ModifierFlag.Static in member.modifiers
                is SetAccessor -> ModifierFlag.Static in member.modifiers
                else -> false
            }
            if (!isStatic) continue
            val name = when (member) {
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                else -> null
            } ?: continue
            if (name == "prototype") continue
            val isPrivate = isMemberPrivate(member)
            val isCallable = member is MethodDeclaration
            derivedStatics[name] = StaticInfo(isPrivate, isCallable, member)
        }

        // Check namespace exports for the derived class symbol (clodule pattern)
        val derivedSymbol = globals[rawClassName]
        if (derivedSymbol != null && derivedSymbol.exports != null) {
            for ((exportName, exportSym) in derivedSymbol.exports!!) {
                if (exportName in derivedStatics) continue // AST member takes priority
                val decl = exportSym.valueDeclaration ?: exportSym.declarations.firstOrNull() ?: continue
                val isCallable = decl is FunctionDeclaration
                derivedStatics[exportName] = StaticInfo(isPrivate = false, isCallable = isCallable, node = decl)
            }
        }

        // Collect base class static members from AST declarations
        val baseStatics = mutableMapOf<String, StaticInfo>()
        for (decl in baseSymbol.declarations) {
            if (decl !is ClassDeclaration) continue
            for (member in decl.members) {
                val isStatic = when (member) {
                    is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                    is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                    is GetAccessor -> ModifierFlag.Static in member.modifiers
                    is SetAccessor -> ModifierFlag.Static in member.modifiers
                    else -> false
                }
                if (!isStatic) continue
                val name = when (member) {
                    is PropertyDeclaration -> (member.name as? Identifier)?.text
                    is MethodDeclaration -> (member.name as? Identifier)?.text
                    is GetAccessor -> (member.name as? Identifier)?.text
                    is SetAccessor -> (member.name as? Identifier)?.text
                    else -> null
                } ?: continue
                if (name == "prototype") continue
                val isPrivate = isMemberPrivate(member)
                val isCallable = member is MethodDeclaration
                baseStatics[name] = StaticInfo(isPrivate, isCallable, member)
            }
        }

        // Check namespace exports for the base class symbol
        if (baseSymbol.exports != null) {
            for ((exportName, exportSym) in baseSymbol.exports!!) {
                if (exportName in baseStatics) continue
                val decl = exportSym.valueDeclaration ?: exportSym.declarations.firstOrNull() ?: continue
                val isCallable = decl is FunctionDeclaration
                baseStatics[exportName] = StaticInfo(isPrivate = false, isCallable = isCallable, node = decl)
            }
        }

        // Compare each overlapping static member
        for ((memberName, derivedInfo) in derivedStatics) {
            val baseInfo = baseStatics[memberName] ?: continue

            val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
            val chain = mutableListOf<String>()

            // 17.18: Namespace-vs-namespace comparison for clodule (class+namespace) merges.
            // When both sides are ModuleDeclarations, find a base-side EXPORTED member that
            // the derived namespace doesn't export. Emits TS2417 with the property-missing
            // chain. First-only emission (mirrors private/type-mismatch branches below).
            if (derivedInfo.node is ModuleDeclaration && baseInfo.node is ModuleDeclaration) {
                val derivedNs = derivedSymbol?.exports?.get(memberName)
                val baseNs = baseSymbol.exports?.get(memberName)
                if (derivedNs != null && baseNs != null) {
                    val baseNsExports = baseNs.exports
                    if (baseNsExports != null) {
                        for ((exportName, baseMemberSym) in baseNsExports) {
                            if (!isNameExportedFromNamespace(baseNs, exportName)) continue
                            if (isNameExportedFromNamespace(derivedNs, exportName)) continue
                            chain.add("  Types of property '$memberName' are incompatible.")
                            chain.add("    Property '$exportName' is missing in type 'typeof $rawClassName.$memberName' but required in type 'typeof $baseName.$memberName'.")
                            val related = mutableListOf<Diagnostic>()
                            val baseDecl = baseMemberSym.valueDeclaration ?: baseMemberSym.declarations.firstOrNull()
                            val baseDeclNamePos = when (baseDecl) {
                                is FunctionDeclaration -> baseDecl.name?.pos
                                is VariableDeclaration -> (baseDecl.name as? Identifier)?.pos
                                is ClassDeclaration -> baseDecl.name?.pos
                                is InterfaceDeclaration -> baseDecl.name.pos
                                is EnumDeclaration -> baseDecl.name.pos
                                is ModuleDeclaration -> (baseDecl.name as? Identifier)?.pos
                                else -> null
                            }
                            if (baseDeclNamePos != null) {
                                val (resolvedFile, resolvedSource) = resolveDeclarationSourceFile(baseDeclNamePos)
                                val declFile = resolvedFile ?: fileName
                                val declSource = resolvedSource ?: source
                                val (declLine, declChar) = getLineAndCharacterOfPosition(declSource, baseDeclNamePos)
                                related.add(Diagnostic(
                                    message = "'$exportName' is declared here.",
                                    category = DiagnosticCategory.Message,
                                    code = 2728,
                                    fileName = declFile,
                                    line = declLine,
                                    character = declChar,
                                    start = baseDeclNamePos,
                                    length = exportName.length,
                                ))
                            }
                            diagnostics.add(Diagnostic(
                                message = "Class static side 'typeof $rawClassName' incorrectly extends base class static side 'typeof $baseName'.",
                                category = DiagnosticCategory.Error,
                                code = 2417,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = classNameNode.pos,
                                length = rawClassName.length,
                                messageChain = chain,
                                relatedInformation = related,
                            ))
                            return
                        }
                    }
                }
                continue // both ns; no missing export → skip the type-equality fallthrough
            }

            // Check private conflicts
            if (derivedInfo.isPrivate || baseInfo.isPrivate) {
                if (derivedInfo.isPrivate && baseInfo.isPrivate) {
                    chain.add("  Types have separate declarations of a private property '$memberName'.")
                } else {
                    val privateType = if (baseInfo.isPrivate) baseName else rawClassName
                    val publicType = if (baseInfo.isPrivate) rawClassName else baseName
                    chain.add("  Property '$memberName' is private in type '$privateType' but not in type '$publicType'.")
                }
                diagnostics.add(Diagnostic(
                    message = "Class static side 'typeof $rawClassName' incorrectly extends base class static side 'typeof $baseName'.",
                    category = DiagnosticCategory.Error,
                    code = 2417,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = classNameNode.pos,
                    length = rawClassName.length,
                    messageChain = chain,
                ))
                return // Only report first conflict
            }

            // Check type compatibility
            val derivedType = getStaticMemberType(derivedInfo.node) ?: continue
            val baseType = getStaticMemberType(baseInfo.node) ?: continue
            if (derivedType === anyType || baseType === anyType) continue

            if (!checkTypeRelatedTo(derivedType, baseType, assignableRelation)) {
                // Determine elaboration format
                if (derivedInfo.isCallable && baseInfo.isCallable) {
                    // Both are methods/functions — compare return types
                    val derivedReturn = getReturnTypeOfCallable(derivedInfo.node)
                    val baseReturn = getReturnTypeOfCallable(baseInfo.node)
                    if (derivedReturn != null && baseReturn != null) {
                        chain.add("  The types returned by '$memberName()' are incompatible between these types.")
                        chain.add("    Type '${typeToString(derivedReturn)}' is not assignable to type '${typeToString(baseReturn)}'.")
                    } else {
                        chain.add("  Types of property '$memberName' are incompatible.")
                        chain.add("    Type '${typeToString(derivedType)}' is not assignable to type '${typeToString(baseType)}'.")
                    }
                } else {
                    chain.add("  Types of property '$memberName' are incompatible.")
                    chain.add("    Type '${typeToString(derivedType)}' is not assignable to type '${typeToString(baseType)}'.")
                }

                diagnostics.add(Diagnostic(
                    message = "Class static side 'typeof $rawClassName' incorrectly extends base class static side 'typeof $baseName'.",
                    category = DiagnosticCategory.Error,
                    code = 2417,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = classNameNode.pos,
                    length = rawClassName.length,
                    messageChain = chain,
                ))
                return // Only report first conflict
            }
        }
    }

    /** Get the type of a static member (AST node), handling FunctionDeclaration for namespace exports. */
    private fun getStaticMemberType(node: Node): Type? = when (node) {
        is FunctionDeclaration -> {
            val hasBodyNoReturn = node.body != null && !bodyHasReturnValue(node.body!!)
            buildMethodType(node.parameters, node.type, node.typeParameters, hasBody = hasBodyNoReturn, bodyNode = node.body)
        }
        is VariableDeclaration -> node.type?.let { getTypeFromTypeNode(it) }
        else -> getTypeOfMemberDecl(node)
    }

    /** Get the return type of a callable node (method or function declaration). */
    private fun getReturnTypeOfCallable(node: Node): Type? = when (node) {
        is MethodDeclaration -> {
            node.type?.let { getTypeFromTypeNode(it) }
                ?: node.body?.let { inferReturnTypeFromBody(it) }
                ?: if (node.body != null && !bodyHasReturnValue(node.body!!)) voidType else null
        }
        is FunctionDeclaration -> {
            node.type?.let { getTypeFromTypeNode(it) }
                ?: node.body?.let { inferReturnTypeFromBody(it) }
                ?: if (node.body != null && !bodyHasReturnValue(node.body!!)) voidType else null
        }
        else -> null
    }

    /** Check if a class member (AST node) has the `private` modifier. */
    private fun isMemberPrivate(node: Node): Boolean = when (node) {
        is PropertyDeclaration -> ModifierFlag.Private in node.modifiers
        is MethodDeclaration -> ModifierFlag.Private in node.modifiers
        is GetAccessor -> ModifierFlag.Private in node.modifiers
        is SetAccessor -> ModifierFlag.Private in node.modifiers
        is Parameter -> ModifierFlag.Private in node.modifiers
        else -> false
    }

    /** Walk the base type chain to find the class name where a member is declared as private. */
    private fun findPrivateDeclaringClassName(type: Type.Object, memberName: String): String? {
        if (type is Type.Interface) {
            val symbol = type.symbol
            if (symbol != null) {
                for (decl in symbol.declarations) {
                    val members = when (decl) {
                        is ClassDeclaration -> decl.members
                        else -> continue
                    }
                    for (member in members) {
                        val name = when (member) {
                            is PropertyDeclaration -> (member.name as? Identifier)?.text
                            is MethodDeclaration -> (member.name as? Identifier)?.text
                            is GetAccessor -> (member.name as? Identifier)?.text
                            is SetAccessor -> (member.name as? Identifier)?.text
                            else -> null
                        }
                        if (name == memberName && isMemberPrivate(member)) {
                            return symbol.name
                        }
                    }
                }
            }
            // Walk base types
            type.baseTypes?.forEach { bt ->
                if (bt is Type.Object) {
                    val result = findPrivateDeclaringClassName(bt, memberName)
                    if (result != null) return result
                }
            }
        }
        return null
    }

    /** Walk the base type chain to find the class name where a member is declared (any visibility). */
    private fun findDeclaringClassName(type: Type.Object, memberName: String): String? {
        if (type is Type.Interface) {
            val symbol = type.symbol
            if (symbol != null) {
                for (decl in symbol.declarations) {
                    val members = when (decl) {
                        is ClassDeclaration -> decl.members
                        else -> continue
                    }
                    for (member in members) {
                        val name = when (member) {
                            is PropertyDeclaration -> (member.name as? Identifier)?.text
                            is MethodDeclaration -> (member.name as? Identifier)?.text
                            is GetAccessor -> (member.name as? Identifier)?.text
                            is SetAccessor -> (member.name as? Identifier)?.text
                            else -> null
                        }
                        if (name == memberName) return symbol.name
                    }
                }
            }
            type.baseTypes?.forEach { bt ->
                if (bt is Type.Object) {
                    val result = findDeclaringClassName(bt, memberName)
                    if (result != null) return result
                }
            }
        }
        return null
    }

    /** Get the type of a class member from its AST declaration. */
    private fun getTypeOfMemberDecl(decl: Node): Type? {
        return when (decl) {
            is PropertyDeclaration -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                // Infer type from initializer if no annotation
                decl.initializer?.let { init ->
                    val t = getTypeOfExpression(init)
                    if (t !== anyType) t else null
                }
            }
            is MethodDeclaration -> {
                // Use void return for methods with body that don't return a value
                val hasBodyNoReturn = decl.body != null && !bodyHasReturnValue(decl.body!!)
                buildMethodType(decl.parameters, decl.type, decl.typeParameters, hasBody = hasBodyNoReturn, bodyNode = decl.body)
            }
            is GetAccessor -> decl.type?.let { getTypeFromTypeNode(it) } ?: decl.body?.let { inferReturnTypeFromBody(it) }
            is SetAccessor -> decl.parameters.firstOrNull()?.type?.let { getTypeFromTypeNode(it) }
            is Parameter -> decl.type?.let { getTypeFromTypeNode(it) }
            else -> null
        }
    }

    /** Build a function type (Object with call signature) from method parameters and return type. */
    private fun buildMethodType(
        params: List<Parameter>,
        returnTypeNode: TypeNode?,
        typeParams: List<TypeParameter>? = null,
        hasBody: Boolean = false,
        bodyNode: Node? = null,
    ): Type {
        val fnType = Type.Object()
        val defaultReturn = if (hasBody) voidType else anyType
        val inferredReturn = if (returnTypeNode == null && bodyNode != null) inferReturnTypeFromBody(bodyNode) else null
        val returnType = returnTypeNode?.let { getTypeFromTypeNode(it) } ?: inferredReturn ?: defaultReturn
        val typeParameters = typeParams?.map { tp ->
            // B59.1: intern by TypeParameter node position. Same source-level <U>
            // returns the same Type.TypeParam instance across multiple sig resolutions.
            typeParamInternCache.getOrPut(tp.pos) {
                val param = Type.TypeParam()
                param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                tp.default?.let { param.default = getTypeFromTypeNode(it) }
                param
            }
        }
        // Build parameter symbols with initializer type inference
        val paramSymbols = params.mapNotNull { param ->
            val name = when (val n = param.name) {
                is Identifier -> if (n.text == "this") return@mapNotNull null else n.text
                else -> return@mapNotNull null
            }
            val sym = Symbol(SymbolFlags.FunctionScopedVariable, name)
            sym.declarations.add(param)
            sym.valueDeclaration = param
            // If no type annotation, infer from initializer
            if (param.type == null && param.initializer != null) {
                val initType = getTypeOfExpression(param.initializer!!)
                if (initType !== anyType) {
                    symbolTypes[sym.id] = initType
                }
            }
            sym
        }
        val sig = Signature(
            typeParameters = typeParameters,
            parameters = paramSymbols,
            resolvedReturnType = returnType,
            minArgumentCount = params.count {
                !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        fnType.callSignatures = listOf(sig)
        return fnType
    }

    /** Check if a function body contains any `return expr` (return with a value). */
    private fun bodyHasReturnValue(body: Node): Boolean {
        return when (body) {
            is ReturnStatement -> body.expression != null
            is Block -> body.statements.any { bodyHasReturnValue(it) }
            is IfStatement -> bodyHasReturnValue(body.thenStatement) ||
                (body.elseStatement?.let { bodyHasReturnValue(it) } ?: false)
            is SwitchStatement -> body.caseBlock.any { node ->
                if (node is CaseClause) node.statements.any { bodyHasReturnValue(it) }
                else if (node is DefaultClause) node.statements.any { bodyHasReturnValue(it) }
                else false
            }
            else -> false
        }
    }

    /** Infer a simple return type from a method/function body (single return with literal). */
    private fun inferReturnTypeFromBody(body: Node): Type? {
        val block = body as? Block ?: return null
        for (stmt in block.statements) {
            if (stmt is ReturnStatement) {
                val rawExpr = stmt.expression ?: continue
                // Unwrap parens — `return (1)` should infer same as `return 1`.
                // Also unwrap value-preserving wrappers: `return x!`, `return x satisfies T`.
                // Note: `return x as T` is NOT unwrapped — the asserted type should
                // be the return type (handled by getTypeOfExpression's AsExpression branch).
                var expr = rawExpr
                while (true) {
                    expr = when (expr) {
                        is ParenthesizedExpression -> expr.expression
                        is NonNullExpression -> expr.expression
                        is SatisfiesExpression -> expr.expression
                        else -> break
                    }
                }
                return when (expr) {
                    is StringLiteralNode -> stringType
                    is NoSubstitutionTemplateLiteralNode -> stringType
                    is NumericLiteralNode -> numberType
                    is BigIntLiteralNode -> bigintType
                    is Identifier -> when (expr.text) {
                        "true", "false" -> booleanType
                        else -> null
                    }
                    is PrefixUnaryExpression -> when (expr.operator) {
                        SyntaxKind.Exclamation -> booleanType
                        SyntaxKind.Tilde -> numberType
                        SyntaxKind.Minus, SyntaxKind.Plus, SyntaxKind.PlusPlus, SyntaxKind.MinusMinus ->
                            if (expr.operand is NumericLiteralNode) numberType else numberType
                        else -> null
                    }
                    is PostfixUnaryExpression -> numberType  // x++ / x-- always number
                    // B83.4f-b: `return foo(...)` / `return x.toFixed()` — infer the call's
                    // return type. Load-bearing for contextual-callback shapes like
                    // `(x: number) => { return x.toFixed() }` (must infer `string`, not `any`,
                    // so the callback's `(x:number)=>string` ≠ `(x:number)=>Date` mismatch
                    // can fire TS2345). Mirrors the NewExpression branch above: only return a
                    // CONCRETE result (non-any/error) so the existing `?: anyType` fallback is
                    // unchanged for unresolvable calls. getReturnTypeOfCallExpression resolves
                    // the callee via getTypeOfIdentifier / getTypeOfPropertyAccess, which
                    // consult currentLocalTypes (where contextual typing has pushed `x: number`).
                    is CallExpression -> {
                        try {
                            val t = getReturnTypeOfCallExpression(expr)
                            if (t !== anyType && t !== errorType) t else null
                        } catch (_: Throwable) { null }
                    }
                    is TypeOfExpression -> stringType
                    is VoidExpression -> undefinedType
                    is DeleteExpression -> booleanType
                    is NewExpression -> {
                        // 17.156: mirror 17.154's FunctionExpression inference into the
                        // broader callable family (MethodDeclaration / FunctionDeclaration /
                        // GetAccessor). `class Foo { make() { return new Bar(); } }` infers
                        // `() => Bar` instead of `() => any`. Cycle protection in
                        // getReturnTypeOfNewExpression is wrapped in try/catch.
                        try {
                            val t = getReturnTypeOfNewExpression(expr)
                            if (t !== anyType && t !== errorType) t else null
                        } catch (_: Throwable) { null }
                    }
                    is BinaryExpression -> {
                        // B64.1: arithmetic binary ops always produce `number`. JS spec
                        // for `*` `/` `%` `-` `**` `<<` `>>` `>>>` `&` `|` `^` returns a
                        // number value regardless of operand types (any non-number coerces
                        // or NaN — the result TYPE is still number). Skip `+` (ambiguous:
                        // string concat) and assignment ops. Lets `function f(x): unknown
                        // { return x * 2 }` infer return type `number` so a caller
                        // `f(...).length` correctly fires TS2339.
                        when (expr.operator) {
                            SyntaxKind.Asterisk, SyntaxKind.Slash, SyntaxKind.Percent,
                            SyntaxKind.Minus, SyntaxKind.AsteriskAsterisk,
                            SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
                            SyntaxKind.GreaterThanGreaterThanGreaterThan,
                            SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret -> numberType
                            // Comparison/equality ops always produce boolean.
                            SyntaxKind.LessThan, SyntaxKind.GreaterThan,
                            SyntaxKind.LessThanEquals, SyntaxKind.GreaterThanEquals,
                            SyntaxKind.EqualsEquals, SyntaxKind.ExclamationEquals,
                            SyntaxKind.EqualsEqualsEquals, SyntaxKind.ExclamationEqualsEquals,
                            SyntaxKind.InstanceOfKeyword, SyntaxKind.InKeyword -> booleanType
                            else -> null
                        }
                    }
                    // round 42 iter18: when both branches of a conditional are simple
                    // literals of the same primitive kind, infer that primitive as the
                    // return type. Conservative — bails when either branch is non-literal.
                    is ConditionalExpression -> {
                        fun litKind(e: Expression): Type? = when (e) {
                            is StringLiteralNode, is NoSubstitutionTemplateLiteralNode -> stringType
                            is NumericLiteralNode -> numberType
                            is BigIntLiteralNode -> bigintType
                            is Identifier -> when (e.text) {
                                "true", "false" -> booleanType
                                else -> null
                            }
                            else -> null
                        }
                        val t = litKind(expr.whenTrue)
                        val f = litKind(expr.whenFalse)
                        if (t != null && t === f) t else null
                    }
                    else -> null
                }
            }
        }
        return null
    }

    /**
     * 17.25: Returns true when the body block contains no `ReturnStatement` anywhere
     * (recursively into nested if/loop/switch/try/labeled/block bodies, but NOT into
     * nested function/arrow/class bodies — those have their own return-type analysis).
     * Used to default an unannotated function's return type to `void` instead of `any`.
     */
    private fun bodyHasNoReturn(body: Node): Boolean {
        if (body !is Block) return false
        return !nodeContainsReturn(body)
    }

    private fun nodeContainsReturn(node: Node): Boolean {
        return when (node) {
            is ReturnStatement -> true
            is Block -> node.statements.any { nodeContainsReturn(it) }
            is IfStatement -> nodeContainsReturn(node.thenStatement) ||
                (node.elseStatement?.let { nodeContainsReturn(it) } ?: false)
            is ForStatement -> nodeContainsReturn(node.statement)
            is ForInStatement -> nodeContainsReturn(node.statement)
            is ForOfStatement -> nodeContainsReturn(node.statement)
            is WhileStatement -> nodeContainsReturn(node.statement)
            is DoStatement -> nodeContainsReturn(node.statement)
            is SwitchStatement -> node.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> clause.statements.any { nodeContainsReturn(it) }
                    is DefaultClause -> clause.statements.any { nodeContainsReturn(it) }
                    else -> false
                }
            }
            is TryStatement -> nodeContainsReturn(node.tryBlock) ||
                (node.catchClause?.block?.let { nodeContainsReturn(it) } ?: false) ||
                (node.finallyBlock?.let { nodeContainsReturn(it) } ?: false)
            is LabeledStatement -> nodeContainsReturn(node.statement)
            is WithStatement -> nodeContainsReturn(node.statement)
            // Don't recurse into nested function/arrow/class bodies — their return
            // statements belong to those inner scopes, not the enclosing function.
            else -> false
        }
    }

    /** Add signature-level elaboration for function type mismatches in TS2416 chains. */
    private fun addSignatureElaboration(
        derivedType: Type,
        basePropType: Type,
        chain: MutableList<String>,
        relatedInfo: MutableList<Diagnostic>? = null,
        fileName: String? = null,
        source: String? = null,
        classTypeParams: List<TypeParameter>? = null,
    ) {
        if (derivedType !is Type.Object || basePropType !is Type.Object) return
        val derivedSigs = derivedType.callSignatures
        val baseSigs = basePropType.callSignatures
        if (derivedSigs.isNullOrEmpty() || baseSigs.isNullOrEmpty()) return
        val derivedSig = derivedSigs.first()
        val baseSig = baseSigs.first()
        // Check parameter count mismatch
        if (derivedSig.minArgumentCount > baseSig.parameters.size) {
            chain.add("    Target signature provides too few arguments. Expected ${derivedSig.parameters.size} or more, but got ${baseSig.parameters.size}.")
            return
        }
        // Check parameter type mismatches (contravariant: base.param must be assignable
        // to derived.param). Emit a "Types of parameters 'x' and 'y' are incompatible"
        // chain for the FIRST failing pair so the elaboration matches TypeScript's
        // baseline format for TS2416 method-override mismatches like
        // `class IntFooBad implements IFoo<number> { foo(x: string) ... }`.
        val pairCount = minOf(derivedSig.parameters.size, baseSig.parameters.size)
        for (i in 0 until pairCount) {
            val derivedParam = derivedSig.parameters[i]
            val baseParam = baseSig.parameters[i]
            val derivedParamType = getTypeOfSymbol(derivedParam)
            val baseParamType = getTypeOfSymbol(baseParam)
            if (derivedParamType === anyType || baseParamType === anyType) continue
            if (!checkTypeRelatedTo(baseParamType, derivedParamType, assignableRelation)) {
                chain.add("    Types of parameters '${derivedParam.name}' and '${baseParam.name}' are incompatible.")
                chain.add("      Type '${typeToString(baseParamType)}' is not assignable to type '${typeToString(derivedParamType)}'.")
                // When derived's param is a TypeParam (e.g. `f(a: T)` on a generic
                // class) and base's param is a concrete type, the override is unsound
                // because T can be instantiated to any subtype of its constraint —
                // the caller's concrete value may not be compatible with T's
                // chosen instantiation. TypeScript adds this hint in the chain.
                if (derivedParamType is Type.TypeParam && baseParamType !is Type.TypeParam) {
                    chain.add("        '${typeToString(derivedParamType)}' could be instantiated with an arbitrary type which could be unrelated to '${typeToString(baseParamType)}'.")
                }
                // TS2208 related info: when the BASE method has a method-level
                // TypeParam in this position and the derived overrides with a
                // concrete type, TypeScript hints that the base TypeParam might
                // need an `extends <derivedType>` constraint to allow the override.
                // Only emit when relatedInfo collector is present (TS2416 path).
                // 17.78: Also fall back to the TypeParam's symbol declarations for
                // INTERFACE-level / class-level TypeParams (not just method-level) —
                // e.g. `interface IFoo<T>` where `T` appears in `foo(x:T):T` is an
                // interface-level TypeParam, not a method-level one.
                if (relatedInfo != null && fileName != null && source != null &&
                    baseParamType is Type.TypeParam && derivedParamType !is Type.TypeParam) {
                    val baseDecl = baseSig.declaration
                    val baseTpName = baseParamType.symbol?.name
                    val baseTpDecls = (baseDecl as? MethodDeclaration)?.typeParameters
                    val methodLevelDecl = baseTpDecls?.firstOrNull { it.name.text == baseTpName }
                    // 17.78: Fall back to the derived class's typeParameters by NAME —
                    // when base's param TypeParam is substituted via heritage clause
                    // type arg into the derived class's own T, the symbol.declarations
                    // chain doesn't carry through (instantiation creates fresh Symbols).
                    // Looking up by name in `classTypeParams` recovers the correct
                    // declaration position. Cf. implementGenericWithMismatchedTypes_ts
                    // where C<T> implements IFoo<T> — IFoo's T gets substituted to C's
                    // T, and the TS2208 hint should point to C<T>'s T at line 7:9.
                    val classLevelDecl = classTypeParams?.firstOrNull { it.name.text == baseTpName }
                    val tpDecl = methodLevelDecl ?: classLevelDecl
                        ?: baseParamType.symbol?.declarations?.firstOrNull() as? TypeParameter
                    if (tpDecl != null) {
                        val tpPos = tpDecl.name.pos
                        val (tpLine, tpChar) = getLineAndCharacterOfPosition(source, tpPos)
                        relatedInfo.add(Diagnostic(
                            message = "This type parameter might need an `extends ${typeToString(derivedParamType)}` constraint.",
                            category = DiagnosticCategory.Message,
                            code = 2208,
                            fileName = fileName,
                            line = tpLine,
                            character = tpChar,
                            start = tpPos,
                            length = tpDecl.name.text.length,
                        ))
                    }
                }
                return
            }
        }
        // Check return type mismatch
        val sourceReturn = derivedSig.resolvedReturnType ?: anyType
        val targetReturn = baseSig.resolvedReturnType ?: anyType
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, assignableRelation)) {
            chain.add("    Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
            // 17.78: When base's return is a TypeParam and derived's return is a
            // concrete type, the override is unsound — T can be instantiated to any
            // type unrelated to the concrete return. Add the "could be instantiated"
            // advisory chain line + TS2208 related info pointing to the TypeParam's
            // declaration site (mirror of the param-mismatch branch above for the
            // return-type case). Cf. implementGenericWithMismatchedTypes_ts where
            // `class C2<T> implements IFoo2<T> { foo<Tstring>(x: Tstring): number }`
            // mismatches `(x: T) => T`'s return — the `T` in the BASE interface's
            // declaration carries the TS2208 hint.
            // 17.78: TS2208 hint is NOT emitted for return-type mismatches —
            // adding `T extends number` constraint wouldn't fix `number → T` (the
            // assignability is in the wrong direction). TypeScript adds only the
            // "could be instantiated" chain line in this case.
            if (targetReturn is Type.TypeParam && sourceReturn !is Type.TypeParam) {
                val tpName = typeToString(targetReturn)
                chain.add("      '$tpName' could be instantiated with an arbitrary type which could be unrelated to '${typeToString(sourceReturn)}'.")
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2344: Type does not satisfy the constraint
    // -----------------------------------------------------------------------

    private fun checkTypeArgumentConstraints() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                checkConstraintsInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkConstraintsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            // Visit type nodes in declarations
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                    }
                }
                is FunctionDeclaration -> {
                    // Push function's TypeParam scope so `T` references in parameter
                    // and return type annotations resolve to the function's typeParam,
                    // not a shadowed global. Without this, `function tem<T extends
                    // number>(t: T): I<T>` would see `I<T>` resolve T to the global
                    // `class T` if any (or errorType) and emit FP TS2344.
                    val savedScope = currentTypeParamScope
                    try {
                        val scope = (savedScope?.toMutableMap() ?: mutableMapOf())
                        stmt.typeParameters?.forEach { tp ->
                            val name = tp.name.text
                            val typeParam = typeParamInternCache.getOrPut(tp.pos) {
                                val p = Type.TypeParam()
                                p.symbol = Symbol(SymbolFlags.TypeParameter, name)
                                p
                            }
                            tp.constraint?.let {
                                if (typeParam.constraint == null) typeParam.constraint = getTypeFromTypeNode(it)
                            }
                            tp.default?.let {
                                if (typeParam.default == null) typeParam.default = getTypeFromTypeNode(it)
                            }
                            scope[name] = typeParam
                        }
                        currentTypeParamScope = if (scope.isEmpty()) null else scope
                        stmt.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                        stmt.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                        stmt.body?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                    } finally {
                        currentTypeParamScope = savedScope
                    }
                }
                is ClassDeclaration -> {
                    stmt.heritageClauses?.forEach { clause ->
                        clause.types.forEach { checkConstraintsInExprWithTypeArgs(it, source, fileName, stmts) }
                    }
                    if (extendsClauseIsNonGeneric(stmt) && classMergedWithInterface(stmt, stmts)) {
                        for (member in stmt.members) {
                            if (member is Constructor) {
                                member.body?.let { body ->
                                    for (s in body.statements) {
                                        emitTs2346ForSuperCallsInStmt(s, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                    for (member in stmt.members) {
                        when (member) {
                            is PropertyDeclaration -> member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                            is MethodDeclaration -> {
                                member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                                member.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                            }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    stmt.heritageClauses?.forEach { clause ->
                        clause.types.forEach { checkConstraintsInExprWithTypeArgs(it, source, fileName, stmts) }
                    }
                    for (member in stmt.members) {
                        when (member) {
                            is PropertyDeclaration -> member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                            is MethodDeclaration -> {
                                member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                                member.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                            }
                            else -> {}
                        }
                    }
                }
                is TypeAliasDeclaration -> {
                    // B98a (round 82): for a generic alias whose body is an import-type
                    // (`type Bar<T> = import('./m').Foo<T>`), push Bar's OWN type params into
                    // scope so the args resolve to Bar's (unconstrained) TypeParams — only then
                    // does `checkConstraintsForTypeArgs` see argType = TypeParam (not errorType)
                    // and fire TS2344 when Foo's constraint isn't satisfied. Narrow gate
                    // (`stmt.type is ImportType`) → no impact on other type-alias constraint checks.
                    val tps = stmt.typeParameters
                    if (stmt.type is ImportType && !tps.isNullOrEmpty()) {
                        val savedTpScope = currentTypeParamScope
                        val savedTpDecls = currentTypeParamDecls
                        try {
                            val scope = (savedTpScope?.toMutableMap() ?: mutableMapOf())
                            val decls = savedTpDecls.toMutableMap()
                            for (tp in tps) {
                                val p = typeParamInternCache.getOrPut(tp.pos) {
                                    Type.TypeParam().also { it.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text) }
                                }
                                tp.constraint?.let { p.constraint = getTypeFromTypeNode(it) }
                                scope[tp.name.text] = p
                                decls[tp.name.text] = tp  // for the TS2208 hint position
                            }
                            currentTypeParamScope = scope
                            currentTypeParamDecls = decls
                            checkConstraintsInTypeNode(stmt.type, source, fileName)
                        } finally {
                            currentTypeParamScope = savedTpScope
                            currentTypeParamDecls = savedTpDecls
                        }
                    } else {
                        checkConstraintsInTypeNode(stmt.type, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                }
                is Block -> checkConstraintsInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkConstraintsInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkConstraintsInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                        d.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                    }
                    checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                }
                is ForInStatement -> checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkConstraintsInStatements(clause.statements, source, fileName)
                            is DefaultClause -> checkConstraintsInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkConstraintsInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkConstraintsInStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkConstraintsInExprWithTypeArgs(node: ExpressionWithTypeArguments, source: String, fileName: String, siblings: List<Statement>? = null) {
        val typeArgs = node.typeArguments ?: return
        when (val expr = node.expression) {
            is Identifier -> {
                val name = expr.text
                // TS2315: check if type is not generic (only for class/interface/type alias/module, not variables)
                if (name !in BUILTIN_GENERICS) {
                    val symbol = globals[name]
                    if (symbol != null && symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Module)) {
                        val typeParams = getTypeParametersOfSymbol(symbol)
                        if (typeParams == null || typeParams.isEmpty()) {
                            val start = node.pos
                            // node.end overshoots — compute true end from last type arg
                            val lastArg = typeArgs.last()
                            val length = lastArg.end - start
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type '$name' is not generic.",
                                category = DiagnosticCategory.Error,
                                code = 2315,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                checkConstraintsForTypeArgs(name, typeArgs, source, fileName)
            }
            is CallExpression -> {
                // TS2315 for `class C extends fn()<T,U>` when `fn` is a local FunctionDeclaration
                // whose body returns a non-generic ClassExpression. Narrow surgical case — only
                // fires when callee is an Identifier resolving to a sibling FunctionDeclaration
                // with a single `return ClassExpression` body and the returned class has no
                // type parameters.
                val callee = expr.expression as? Identifier ?: return
                val sibs = siblings ?: return
                val calleeName = callee.text
                val fnDecl = sibs.firstNotNullOfOrNull { s ->
                    (s as? FunctionDeclaration)?.takeIf { it.name?.text == calleeName }
                } ?: return
                val body = fnDecl.body ?: return
                val returnedClass = body.statements.firstNotNullOfOrNull { s ->
                    (s as? ReturnStatement)?.expression as? ClassExpression
                } ?: return
                if (!returnedClass.typeParameters.isNullOrEmpty()) return
                val className = returnedClass.name?.text ?: return
                val start = node.pos
                val lastArgEnd = typeArgs.last().end
                val gtIdx = source.indexOf('>', lastArgEnd - 1)
                val length = if (gtIdx >= 0) gtIdx + 1 - start else (lastArgEnd - start)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '$className' is not generic.",
                    category = DiagnosticCategory.Error,
                    code = 2315,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
            else -> {}
        }
    }

    /**
     * 16.4db: True iff the class is merged with a same-name InterfaceDeclaration. Combined
     * with `extendsClauseIsNonGeneric` to gate TS2346: TS only emits TS2346 on super() in
     * this pattern when the merged class+interface produces an unresolvable construct
     * signature; bare `class B extends NonGeneric<T>` (no interface merge) keeps the base
     * ctor sig and super() resolves normally.
     */
    private fun classMergedWithInterface(cls: ClassDeclaration, siblings: List<Statement>): Boolean {
        val name = cls.name?.text ?: return false
        return siblings.any { it is InterfaceDeclaration && it.name.text == name }
    }

    /**
     * 16.4db: Mirrors the TS2315 condition in `checkConstraintsInExprWithTypeArgs` for the
     * `extends` clause of a class. Used to gate TS2346 emission on `super()` calls when the
     * declared base type is non-generic but type arguments were provided.
     */
    private fun extendsClauseIsNonGeneric(cls: ClassDeclaration): Boolean {
        val extendsClause = cls.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword } ?: return false
        val baseExpr = extendsClause.types.firstOrNull() ?: return false
        val typeArgs = baseExpr.typeArguments ?: return false
        if (typeArgs.isEmpty()) return false
        val name = (baseExpr.expression as? Identifier)?.text ?: return false
        if (name in BUILTIN_GENERICS) return false
        val symbol = globals[name] ?: return false
        if (!symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Module)) return false
        val typeParams = getTypeParametersOfSymbol(symbol)
        return typeParams == null || typeParams.isEmpty()
    }

    /**
     * 16.4db: Walk a statement subtree for `super(...)` CallExpressions and emit TS2346
     * "Call target does not contain any signatures." at the `super` identifier (length 5).
     * Fires only from `extendsClauseIsNonGeneric`-gated path — the resolved base ctor signature
     * is unavailable when the declared base is non-generic-with-typeargs.
     */
    private fun emitTs2346ForSuperCallsInStmt(stmt: Statement, source: String, fileName: String) {
        fun walkExpr(e: Expression?) {
            e ?: return
            when (e) {
                is CallExpression -> {
                    val callee = e.expression
                    if (callee is Identifier && callee.text == "super" && callee.pos >= 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                        diagnostics.add(Diagnostic(
                            message = "Call target does not contain any signatures.",
                            category = DiagnosticCategory.Error,
                            code = 2346,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = callee.pos,
                            length = 5,
                        ))
                    } else {
                        walkExpr(callee)
                    }
                    e.arguments.forEach { walkExpr(it) }
                }
                is PropertyAccessExpression -> walkExpr(e.expression)
                is ElementAccessExpression -> { walkExpr(e.expression); walkExpr(e.argumentExpression) }
                is BinaryExpression -> { walkExpr(e.left); walkExpr(e.right) }
                is ConditionalExpression -> { walkExpr(e.condition); walkExpr(e.whenTrue); walkExpr(e.whenFalse) }
                is ParenthesizedExpression -> walkExpr(e.expression)
                is PrefixUnaryExpression -> walkExpr(e.operand)
                is PostfixUnaryExpression -> walkExpr(e.operand)
                is NewExpression -> { walkExpr(e.expression); e.arguments?.forEach { walkExpr(it) } }
                is TypeAssertionExpression -> walkExpr(e.expression)
                is AsExpression -> walkExpr(e.expression)
                is NonNullExpression -> walkExpr(e.expression)
                is ArrayLiteralExpression -> e.elements.forEach { walkExpr(it) }
                is SpreadElement -> walkExpr(e.expression)
                is YieldExpression -> e.expression?.let { walkExpr(it) }
                is AwaitExpression -> walkExpr(e.expression)
                is VoidExpression -> walkExpr(e.expression)
                is TypeOfExpression -> walkExpr(e.expression)
                is DeleteExpression -> walkExpr(e.expression)
                else -> {}
            }
        }
        fun walkStmt(s: Statement?) {
            s ?: return
            when (s) {
                is ExpressionStatement -> walkExpr(s.expression)
                is Block -> s.statements.forEach { walkStmt(it) }
                is IfStatement -> { walkExpr(s.expression); walkStmt(s.thenStatement); walkStmt(s.elseStatement) }
                is ForStatement -> walkStmt(s.statement)
                is WhileStatement -> walkStmt(s.statement)
                is DoStatement -> walkStmt(s.statement)
                is ReturnStatement -> walkExpr(s.expression)
                is VariableStatement -> s.declarationList.declarations.forEach { walkExpr(it.initializer) }
                is TryStatement -> {
                    walkStmt(s.tryBlock)
                    s.catchClause?.block?.let { walkStmt(it) }
                    s.finallyBlock?.let { walkStmt(it) }
                }
                is SwitchStatement -> s.caseBlock.forEach { c ->
                    when (c) {
                        is CaseClause -> c.statements.forEach { walkStmt(it) }
                        is DefaultClause -> c.statements.forEach { walkStmt(it) }
                        else -> {}
                    }
                }
                else -> {}
            }
        }
        walkStmt(stmt)
    }

    private fun checkConstraintsInTypeNode(node: TypeNode, source: String, fileName: String) {
        when (node) {
            is TypeReference -> {
                val typeArgs = node.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    val name = getTypeReferenceLastName(node.typeName)
                    if (name != null) {
                        // TS2315: check if type is not generic (only for type declarations, not variables)
                        if (name !in BUILTIN_GENERICS) {
                            val symbol = resolveTypeNameToSymbol(node.typeName) ?: globals[name]
                            if (symbol != null && symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Module)) {
                                val typeParams = getTypeParametersOfSymbol(symbol)
                                if (typeParams == null || typeParams.isEmpty()) {
                                    // Type is not generic but type arguments were provided
                                    val start = node.pos
                                    // node.end overshoots — compute true end from last type arg
                                    // lastArg.end already points past the arg; the '>' is at lastArg.end
                                    val lastArg = typeArgs.last()
                                    val length = lastArg.end - start
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "Type '$name' is not generic.",
                                        category = DiagnosticCategory.Error,
                                        code = 2315,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                        checkConstraintsForTypeArgs(name, typeArgs, source, fileName)
                    }
                    // Recurse into type arguments
                    typeArgs.forEach { checkConstraintsInTypeNode(it, source, fileName) }
                }
            }
            is UnionType -> node.types.forEach { checkConstraintsInTypeNode(it, source, fileName) }
            is IntersectionType -> node.types.forEach { checkConstraintsInTypeNode(it, source, fileName) }
            is ArrayType -> checkConstraintsInTypeNode(node.elementType, source, fileName)
            is FunctionType -> {
                checkConstraintsInTypeNode(node.type, source, fileName)
                node.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
            }
            is ParenthesizedType -> checkConstraintsInTypeNode(node.type, source, fileName)
            is ImportType -> {
                // B98a (round 82): `import('./mod').Foo<T>` — constraint-check the type args
                // against the cross-file generic `Foo` (available in `globals` via the init-time
                // cross-file merge). The enclosing type alias's own type params must be in scope
                // for the args to resolve — see the TypeAliasDeclaration ImportType scope push.
                val qualName = (node.qualifier as? Identifier)?.text
                val importArgs = node.typeArguments
                if (qualName != null && !importArgs.isNullOrEmpty()) {
                    checkConstraintsForTypeArgs(qualName, importArgs, source, fileName, emitTypeParamHint = true)
                    importArgs.forEach { checkConstraintsInTypeNode(it, source, fileName) }
                }
            }
            else -> {}
        }
    }

    private fun checkConstraintsForTypeArgs(
        typeName: String, typeArgs: List<TypeNode>,
        source: String, fileName: String,
        // B98a: when true (import-type path only), a failing UNCONSTRAINED-TypeParam arg also
        // gets a TS2208 "might need an `extends X` constraint" hint at its declaration. Gated
        // off for the TypeReference path to avoid changing its existing TS2344 baselines.
        emitTypeParamHint: Boolean = false,
    ) {
        // Skip built-in generics (Array, Promise, etc.)
        if (typeName in BUILTIN_GENERICS) return

        val symbol = globals[typeName] ?: return
        // 16.4gc: Get type parameter DECLARATIONS and resolve constraints with the
        // fresh TypeParam objects pushed onto scope — this way TypeParam references
        // inside a constraint (e.g. `T` inside `{ a: T }` for `U extends { a: T }`)
        // resolve to the same fresh TypeParam instances we return, so a TypeMapper
        // keyed on those instances can substitute them at display time.
        val typeParamNodes = getTypeParameterDeclarationsOfSymbol(symbol) ?: return
        if (typeParamNodes.isEmpty()) return
        val typeParams = typeParamNodes.map { tp ->
            // B59.1 extension: intern by TypeParameter AST position.
            typeParamInternCache.getOrPut(tp.pos) {
                val p = Type.TypeParam()
                p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                p
            }
        }
        val savedScope = currentTypeParamScope
        try {
            val scope = (savedScope?.toMutableMap() ?: mutableMapOf())
            typeParamNodes.forEachIndexed { i, tp -> scope[tp.name.text] = typeParams[i] }
            currentTypeParamScope = scope
            typeParamNodes.forEachIndexed { i, tp ->
                tp.constraint?.let { typeParams[i].constraint = getTypeFromTypeNode(it) }
                tp.default?.let { typeParams[i].default = getTypeFromTypeNode(it) }
            }
        } finally {
            currentTypeParamScope = savedScope
        }

        val argTypes = typeArgs.map { getTypeFromTypeNode(it) }
        val mapper = createTypeMapper(typeParams, argTypes)

        val len = minOf(typeArgs.size, typeParams.size)
        for (i in 0 until len) {
            val typeParam = typeParams[i]
            val constraint = typeParam.constraint ?: continue
            val argType = argTypes[i]
            if (argType === anyType || argType === errorType) continue
            val instantiatedConstraint = instantiateType(constraint, mapper)
            if (instantiatedConstraint === anyType || instantiatedConstraint === errorType) continue

            if (!checkTypeRelatedTo(argType, instantiatedConstraint, assignableRelation)) {
                // TS allows primitive type arguments to satisfy object-shape constraints
                // via apparent type: `string` has the String wrapper's members (`length`,
                // `charAt`, etc.), so `A<string>` where A's param extends `{ length: number }`
                // is fine. Only apply this bail-out at the TS2344 emission site to avoid
                // affecting other relation-based checks.
                if (instantiatedConstraint is Type.Object &&
                    argType.flags.hasAny(TypeFlags.StringLike or TypeFlags.NumberLike or TypeFlags.BooleanLike)) {
                    val apparent = getApparentType(argType)
                    if (apparent !== argType && apparent is Type.Object &&
                        checkTypeRelatedTo(apparent, instantiatedConstraint, assignableRelation)) {
                        continue
                    }
                }
                // Tuple types structurally satisfy `Array<X>` / `ReadonlyArray<X>`
                // constraints — tuples extend the array prototype. Our structural
                // comparison doesn't always recognize this so add a narrow bail-out.
                if (argType is Type.Object && argType.tupleElementTypes != null &&
                    instantiatedConstraint is Type.Reference) {
                    val tName = instantiatedConstraint.target.symbol?.name
                    if (tName == "Array" || tName == "ReadonlyArray") continue
                }
                // TypeParam source with constraint: check the constraint chain against
                // the target constraint. `function f<T extends number>(...) { I<T> }`
                // where I's TypeParam extends number — T's constraint IS number, which
                // trivially satisfies the `extends number` constraint. Use
                // `argType.constraint` directly (not `getApparentType` which would
                // wrap primitives to their interface). Only fires when source HAS a
                // constraint (unconstrained T → would over-skip and lose genuine
                // TS2344 cases).
                if (argType is Type.TypeParam && argType.constraint != null) {
                    val cnst = argType.constraint!!
                    if (cnst !== anyType && cnst !== errorType &&
                        checkTypeRelatedTo(cnst, instantiatedConstraint, assignableRelation)) {
                        continue
                    }
                }
                val argNode = typeArgs[i]
                val argDisplay = formatTypeForDisplay(argNode) ?: typeToString(argType)
                // 16.4gc: constraint display with TypeParam substitution (see 16.4gb)
                val constraintDisplay = typeToStringWithMapper(instantiatedConstraint, mapper)
                // 16.4gc: source-span squiggle (see 16.4gb)
                var trueEnd = argNode.end
                while (trueEnd > argNode.pos && source.getOrNull(trueEnd - 1)?.let {
                    it == ' ' || it == '\t' || it == '\n' || it == '\r' ||
                    it == ',' || it == '>' || it == ')' || it == ';'
                } == true) trueEnd--
                val length = if (trueEnd > argNode.pos) trueEnd - argNode.pos else argDisplay.length
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, argNode.pos)
                val message = "Type '$argDisplay' does not satisfy the constraint '$constraintDisplay'."
                val chain = mutableListOf<String>()
                val relatedInfo = mutableListOf<Diagnostic>()

                // B98a: TS2208 hint for an unconstrained-TypeParam arg (import-type path only).
                if (emitTypeParamHint && argType is Type.TypeParam && argType.constraint == null) {
                    val argName = ((argNode as? TypeReference)?.typeName as? Identifier)?.text
                    val tpDecl = argName?.let { currentTypeParamDecls[it] }
                    if (tpDecl != null) {
                        val tpPos = tpDecl.name.pos
                        val (tl, tc) = getLineAndCharacterOfPosition(source, tpPos)
                        relatedInfo.add(Diagnostic(
                            message = "This type parameter might need an `extends $constraintDisplay` constraint.",
                            category = DiagnosticCategory.Message,
                            code = 2208,
                            fileName = fileName,
                            line = tl,
                            character = tc,
                            start = tpPos,
                            length = tpDecl.name.text.length,
                        ))
                    }
                }

                // Add elaboration for missing properties (structural Object vs Object)
                var emittedMissing = false
                if (argType is Type.Object && instantiatedConstraint is Type.Object) {
                    resolveStructuredTypeMembers(argType)
                    resolveStructuredTypeMembers(instantiatedConstraint)
                    val constraintProps = instantiatedConstraint.properties ?: emptyList()
                    val argMembers = argType.members
                    for (cp in constraintProps) {
                        if (isOptionalProperty(cp)) continue
                        if (cp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                        if (argMembers == null || cp.name !in argMembers) {
                            chain.add("  Property '${cp.name}' is missing in type '$argDisplay' but required in type '$constraintDisplay'.")
                            // TS2728 related info: point to constraint property declaration
                            cp.valueDeclaration?.let { decl ->
                                val declPos = when (decl) {
                                    is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                    is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                    else -> decl.pos
                                }
                                val declLength = when (decl) {
                                    is PropertyDeclaration -> (decl.name as? Identifier)?.text?.length ?: cp.name.length
                                    is MethodDeclaration -> (decl.name as? Identifier)?.text?.length ?: cp.name.length
                                    else -> cp.name.length
                                }
                                val (rl, rc) = getLineAndCharacterOfPosition(source, declPos)
                                relatedInfo.add(Diagnostic(
                                    message = "'${cp.name}' is declared here.",
                                    category = DiagnosticCategory.Message,
                                    code = 2728,
                                    fileName = fileName,
                                    line = rl,
                                    character = rc,
                                    start = declPos,
                                    length = declLength,
                                ))
                            }
                            emittedMissing = true
                            break
                        }
                    }
                    // 16.4gc: property-type-mismatch elaboration (see 16.4gb) — only
                    // when no missing-property chain was already emitted.
                    if (!emittedMissing) {
                        val cProps = instantiatedConstraint.properties ?: emptyList()
                        val argMembersMap = argType.members ?: emptyMap()
                        for (cp in cProps) {
                            val ap = argMembersMap[cp.name] ?: continue
                            val cpType = symbolTypes[cp.id] ?: continue
                            val apType = symbolTypes[ap.id] ?: continue
                            val cpTypeInst = instantiateType(cpType, mapper)
                            if (cpTypeInst === anyType || cpTypeInst === errorType) continue
                            if (!checkTypeRelatedTo(apType, cpTypeInst, assignableRelation)) {
                                val cpDisplay = typeToStringWithMapper(cpType, mapper)
                                chain.add("  Types of property '${cp.name}' are incompatible.")
                                chain.add("    Type '${typeToString(apType)}' is not assignable to type '$cpDisplay'.")
                                break
                            }
                        }
                    }
                }

                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2344,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = argNode.pos,
                    length = length,
                    messageChain = chain,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * Return the TypeParameterDeclaration AST nodes for a symbol (class, interface,
     * type alias, or function). Used by [checkConstraintsForTypeArgs] to re-resolve
     * constraints in a scope populated with fresh TypeParams, so the returned TypeParam
     * instances match references inside constraints and a TypeMapper can substitute them.
     */
    private fun getTypeParameterDeclarationsOfSymbol(symbol: Symbol): List<TypeParameter>? {
        val resolved = if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            try { resolveAlias(symbol) } catch (_: StackOverflowError) { symbol }
        } else symbol
        for (decl in resolved.declarations) {
            val typeParamNodes = when (decl) {
                is ClassDeclaration -> decl.typeParameters
                is InterfaceDeclaration -> decl.typeParameters
                is TypeAliasDeclaration -> decl.typeParameters
                is FunctionDeclaration -> decl.typeParameters
                else -> null
            } ?: continue
            if (typeParamNodes.isEmpty()) continue
            return typeParamNodes
        }
        return null
    }

    /** Get type parameters from a symbol's declarations (class, interface, or type alias). */
    private fun getTypeParametersOfSymbol(symbol: Symbol): List<Type.TypeParam>? {
        // Follow alias if this is an import alias
        val resolved = if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            try { resolveAlias(symbol) } catch (_: StackOverflowError) { symbol }
        } else symbol
        for (decl in resolved.declarations) {
            val typeParamNodes = when (decl) {
                is ClassDeclaration -> decl.typeParameters
                is InterfaceDeclaration -> decl.typeParameters
                is TypeAliasDeclaration -> decl.typeParameters
                is FunctionDeclaration -> decl.typeParameters
                else -> null
            } ?: continue
            if (typeParamNodes.isEmpty()) continue
            return typeParamNodes.map { tp ->
                // B59.3: intern by AST position so this TypeParam shares identity with
                // other interning sites (B59.1+B59.2 at Checker.kt ~37183 / ~37214 /
                // ~37247 / ~37573 / ~37724 / ~46475 / ~51854 / ~58215 / ~58562 / ~58909).
                // Callers of getTypeParametersOfSymbol only check emptiness, not identity,
                // so identity is invariant for the existing TS2315 consumers — but shared
                // identity reduces churn for any future identity-sensitive consumer.
                val param = typeParamInternCache.getOrPut(tp.pos) {
                    val p = Type.TypeParam()
                    p.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                    p
                }
                // Guard against clobbering already-set constraint/default from another site.
                if (param.constraint == null) {
                    tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                }
                if (param.default == null) {
                    tp.default?.let { param.default = getTypeFromTypeNode(it) }
                }
                param
            }
        }
        return null
    }

    // -----------------------------------------------------------------------
    // TS2339: Property does not exist on type (Phase 4 item 5a)
    // -----------------------------------------------------------------------

    private fun checkPropertyAccess() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip .js files — property access patterns differ
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            currentFlowGraph = result.flowGraph
            try {
                checkPropertyAccessInStatements(
                    result.sourceFile.statements, source, fileName,
                    enclosingClassType = null
                )
            } catch (_: StackOverflowError) {
                // Circular type resolution in complex files — skip gracefully
            }
            currentFlowGraph = null
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkPropertyAccessInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        for (stmt in stmts) checkPropertyAccessInStatement(stmt, source, fileName, enclosingClassType)
    }

    private fun checkPropertyAccessInStatement(
        stmt: Statement, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        when (stmt) {
            is ClassDeclaration -> {
                // Check heritage clause property access (e.g. extends M.B)
                stmt.heritageClauses?.forEach { clause ->
                    clause.types.forEach { ewta ->
                        checkPropertyAccessInExpr(ewta.expression, source, fileName, enclosingClassType)
                    }
                }
                // Resolve the class type for "this" inside class body.
                // For namespace-nested classes, walk the enclosing-namespace stack
                // (populated by the ModuleDeclaration branch) and consult each
                // namespace's `exports` table — the binder puts namespace-internal
                // classes there, not directly in `globals`.
                val classType = if (stmt.name != null) {
                    var symbol: Symbol? = null
                    for (ns in propertyAccessEnclosingNamespaces.asReversed()) {
                        symbol = ns.exports?.get(stmt.name.text)
                        if (symbol != null) break
                    }
                    if (symbol == null) symbol = globals[stmt.name.text]
                    // B83.5: block-scoped classes (declared inside `while`/`for`/etc.
                    // bodies) are NOT bound by the binder — `bindStatement` only
                    // descends into namespace bodies, not block statements. To
                    // restore TS2339/TS2551 checking for `this.X` accesses inside
                    // such classes (anonymousClassExpression2_ts shape: `while (0) {
                    // class B { methodB() { this.methodA; /*err*/ } } }`), synthesize
                    // a transient Symbol that points at the AST declaration and let
                    // `getDeclaredTypeOfClassOrInterface` build the Type.Interface
                    // from it. The synthetic symbol is never published to the binder's
                    // tables — used only for this check pass.
                    if (symbol == null) {
                        val syn = Symbol(SymbolFlags.Class, stmt.name.text)
                        syn.declarations.add(stmt)
                        symbol = syn
                    }
                    getDeclaredTypeOfSymbol(symbol)
                } else null
                val savedStatic = inStaticClassMethod
                inStaticClassMethod = false
                for (member in stmt.members) {
                    checkPropertyAccessInClassMember(member, source, fileName, classType)
                }
                inStaticClassMethod = savedStatic
            }
            is InterfaceDeclaration -> { /* No runtime property access in interfaces */ }
            is FunctionDeclaration -> {
                stmt.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    val savedParamBindings = currentParamBindingNames
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    currentParamBindingNames = currentParamBindingNames.toMutableSet()
                    populateParameterLocalTypes(stmt.parameters)
                    checkPropertyAccessInStatements(body.statements, source, fileName, enclosingClassType = null)
                    currentLocalTypes = savedLocalTypes
                    currentParamBindingNames = savedParamBindings
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        checkPropertyAccessInExpr(it, source, fileName, enclosingClassType)
                    }
                }
            }
            is ExpressionStatement -> checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
            is ReturnStatement -> stmt.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is IfStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.thenStatement, source, fileName, enclosingClassType)
                stmt.elseStatement?.let { checkPropertyAccessInStatement(it, source, fileName, enclosingClassType) }
            }
            is Block -> checkPropertyAccessInStatements(stmt.statements, source, fileName, enclosingClassType)
            is ForStatement -> {
                stmt.condition?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
                stmt.incrementor?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is ForInStatement -> {
                // B70.2: for-in loop variable is always `string`. Push into currentLocalTypes
                // so body walkers (TS7053 etc.) see the correct primitive type instead of
                // falling back to `anyType` via getTypeOfIdentifier's globals lookup.
                val forInVarName = when (val init = stmt.initializer) {
                    is Identifier -> init.text
                    is VariableDeclarationList -> (init.declarations.firstOrNull()?.name as? Identifier)?.text
                    else -> null
                }
                val prevType = forInVarName?.let { currentLocalTypes[it] }
                val hadPrev = forInVarName != null && currentLocalTypes.containsKey(forInVarName)
                if (forInVarName != null) currentLocalTypes[forInVarName] = stringType
                try {
                    checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
                } finally {
                    if (forInVarName != null) {
                        if (hadPrev) currentLocalTypes[forInVarName] = prevType!!
                        else currentLocalTypes.remove(forInVarName)
                    }
                }
            }
            is ForOfStatement -> {
                // B70.4: for-of loop variable types as the iterable's element type
                // (Array<T> → T, string → string). Push into currentLocalTypes for the
                // body walk. Conservative: only handle Array<T> Reference and string
                // iterables — other shapes (Iterable, generators) fall through.
                val forOfVarName = when (val init = stmt.initializer) {
                    is Identifier -> init.text
                    is VariableDeclarationList -> (init.declarations.firstOrNull()?.name as? Identifier)?.text
                    else -> null
                }
                val elemType: Type? = if (forOfVarName != null) {
                    try {
                        val iterableT = getTypeOfExpression(stmt.expression)
                        when {
                            iterableT === stringType -> stringType
                            iterableT is Type.Reference && iterableT.target?.symbol?.name == "Array" ->
                                iterableT.resolvedTypeArguments?.firstOrNull()
                            else -> null
                        }
                    } catch (_: StackOverflowError) { null }
                } else null
                val prevType = forOfVarName?.let { currentLocalTypes[it] }
                val hadPrev = forOfVarName != null && currentLocalTypes.containsKey(forOfVarName)
                if (forOfVarName != null && elemType != null) currentLocalTypes[forOfVarName] = elemType
                try {
                    checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
                } finally {
                    if (forOfVarName != null && elemType != null) {
                        if (hadPrev) currentLocalTypes[forOfVarName] = prevType!!
                        else currentLocalTypes.remove(forOfVarName)
                    }
                }
            }
            is WhileStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is DoStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is SwitchStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkPropertyAccessInExpr(clause.expression, source, fileName, enclosingClassType)
                            checkPropertyAccessInStatements(clause.statements, source, fileName, enclosingClassType)
                        }
                        is DefaultClause -> {
                            checkPropertyAccessInStatements(clause.statements, source, fileName, enclosingClassType)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkPropertyAccessInStatements(stmt.tryBlock.statements, source, fileName, enclosingClassType)
                stmt.catchClause?.block?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType) }
                stmt.finallyBlock?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType) }
            }
            is ThrowStatement -> stmt.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is WithStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is LabeledStatement -> checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            is ModuleDeclaration -> {
                // B15.1: Track enclosing namespace symbols in a local stack so nested
                // class lookups (e.g. for `this`-access in `checkMemberAccessMissing`)
                // can resolve namespace-internal classes via `namespaceSymbol.exports`.
                // Uses a dedicated stack — pushing onto the shared `inferenceNamespaceStack`
                // would broaden namespace-aware identifier resolution to value expressions
                // like `MemberName.create(...)` inside the class body, causing FPs where
                // `MemberName` (the class constructor) would resolve to its INSTANCE type
                // and trigger TS2576 on every static-method access.
                val nameNode = stmt.name
                val moduleSymbol = if (nameNode is Identifier && ModifierFlag.Declare !in stmt.modifiers) {
                    if (propertyAccessEnclosingNamespaces.isNotEmpty())
                        propertyAccessEnclosingNamespaces.last().exports?.get(nameNode.text)
                    else
                        currentFileLocals?.get(nameNode.text) ?: globals[nameNode.text]
                } else null
                val pushed = if (moduleSymbol != null && moduleSymbol.flags.hasAny(SymbolFlags.Module)) {
                    propertyAccessEnclosingNamespaces.addLast(moduleSymbol)
                    true
                } else false
                try {
                    (stmt.body as? ModuleBlock)?.let {
                        checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType)
                    }
                } finally {
                    if (pushed) propertyAccessEnclosingNamespaces.removeLast()
                }
            }
            is ExportAssignment -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
            }
            is TypeAliasDeclaration -> {
                // B1.3: TS2532 "Object is possibly 'undefined'." for `typeof X.Y.Z`
                // chains in the type body where an intermediate access dereferences a
                // possibly-undefined receiver. The Flow.kt binder records currentFlow
                // at the TypeAlias position so we can apply path-based narrowing.
                if (strictNullChecks) {
                    walkTypeNodeForUndefinedTypeQueryChain(stmt.type, source, fileName, atNode = stmt)
                }
            }
            else -> { /* no property access in other statement types */ }
        }
    }

    private fun checkPropertyAccessInClassMember(
        member: ClassElement, source: String, fileName: String,
        classType: Type?,
    ) {
        val isStatic = when (member) {
            is MethodDeclaration -> ModifierFlag.Static in member.modifiers
            is GetAccessor -> ModifierFlag.Static in member.modifiers
            is SetAccessor -> ModifierFlag.Static in member.modifiers
            is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
            else -> false
        }
        // Skip static this check when method has explicit `this` parameter (this: Type)
        val hasExplicitThisParam = when (member) {
            is MethodDeclaration -> member.parameters.firstOrNull()?.name.let {
                it is Identifier && it.text == "this"
            }
            else -> false
        }
        val savedStatic = inStaticClassMethod
        if (isStatic && !hasExplicitThisParam) inStaticClassMethod = true
        when (member) {
            is MethodDeclaration -> {
                member.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    val savedParamBindings = currentParamBindingNames
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    currentParamBindingNames = currentParamBindingNames.toMutableSet()
                    populateParameterLocalTypes(member.parameters)
                    checkPropertyAccessInStatements(body.statements, source, fileName, classType)
                    currentLocalTypes = savedLocalTypes
                    currentParamBindingNames = savedParamBindings
                }
            }
            is Constructor -> {
                member.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    val savedParamBindings = currentParamBindingNames
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    currentParamBindingNames = currentParamBindingNames.toMutableSet()
                    populateParameterLocalTypes(member.parameters)
                    checkPropertyAccessInStatements(body.statements, source, fileName, classType)
                    currentLocalTypes = savedLocalTypes
                    currentParamBindingNames = savedParamBindings
                }
            }
            is GetAccessor -> {
                member.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, classType)
                }
            }
            is SetAccessor -> {
                member.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    val savedParamBindings = currentParamBindingNames
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    currentParamBindingNames = currentParamBindingNames.toMutableSet()
                    populateParameterLocalTypes(member.parameters)
                    checkPropertyAccessInStatements(body.statements, source, fileName, classType)
                    currentLocalTypes = savedLocalTypes
                    currentParamBindingNames = savedParamBindings
                }
            }
            is PropertyDeclaration -> {
                member.initializer?.let {
                    checkPropertyAccessInExpr(it, source, fileName, classType)
                }
            }
            else -> {}
        }
        inStaticClassMethod = savedStatic
    }

    private fun checkPropertyAccessInExpr(
        expr: Expression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        when (expr) {
            is PropertyAccessExpression -> {
                // First recurse into subexpressions
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                // Now check this property access
                checkSinglePropertyAccess(expr, source, fileName, enclosingClassType)
            }
            is CallExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                // 16.0: contextual typing for call arguments — propagate param types
                // into object literals / arrow function params so un-annotated arrow
                // parameters can be typed from the contextual signature.
                val argCtxTypes: List<Type?>? = run {
                    if (expr.arguments.isNullOrEmpty()) return@run null
                    try {
                        val callee = expr.expression
                        val calleeType = when (callee) {
                            is Identifier -> getTypeOfIdentifier(callee)
                            is PropertyAccessExpression -> {
                                // B81.1d: `this`-receiver gap for contextual-param
                                // inference. `getTypeOfPropertyAccess(this.x.sort)` →
                                // `getTypeOfIdentifier("this")` returns anyType, so the
                                // contextual chain breaks. When the callee chain's head
                                // is `this` and we have enclosingClassType from the class-
                                // body walker, manually walk the chain using
                                // enclosingClassType as the head — mirroring
                                // resolveUncalledOperandType. Narrow gate: head=`this`,
                                // enclosingClassType != null, all segments resolve.
                                resolveCalleeChainWithThis(callee, enclosingClassType)
                                    ?: getTypeOfPropertyAccess(callee)
                            }
                            else -> return@run null
                        }
                        if (calleeType !is Type.Object) return@run null
                        resolveStructuredTypeMembers(calleeType)
                        val sigs = calleeType.callSignatures
                        if (sigs.isNullOrEmpty()) return@run null
                        // Single signature: use its parameter types directly.
                        // Multiple overloads: per-arg-position, only adopt the first
                        // overload's param type if EVERY overload has a callable
                        // function type at that position (matches TS's contextual
                        // signature behavior for callback overloads — used by
                        // `callb((a) => {...})` patterns).
                        if (sigs.size == 1) {
                            val sig = sigs[0]
                            // B86.1b (activation, 2026-05-28): for a single-signature
                            // GENERIC callee with no explicit type args (e.g.
                            // `map<T,U>(arr: T[], cb: (x: T) => U)` called as
                            // `map([1,""], x => x.foo())`), infer the type-arg mapper
                            // from the arguments and substitute it into each arg's
                            // contextual param type. This turns a bare-TP contextual
                            // type `(x: T) => U` into the concrete `(x: number|string)
                            // => U`, so the un-annotated lambda param `x` resolves to
                            // the concrete type during the diagnostic walk (TS2339 etc.)
                            // rather than staying an opaque TypeParam. Closes the
                            // temporal-inversion gap: the inference mapper produced inside
                            // tryInferSingleTypeParamFromArgs (a return-type-only helper,
                            // torn down in finally) was never visible to this diagnostic
                            // pass. We re-run the inference here, in-pass, and apply it
                            // directly to the propagated contextual types. Gate: only when
                            // the sig has type params AND no explicit type args (explicit
                            // args are handled by their own checking path).
                            val inferMapper: TypeMapper? =
                                if (expr.typeArguments.isNullOrEmpty() && !sig.typeParameters.isNullOrEmpty()) {
                                    val full = try { tryInferSingleTypeParamFromArgs(sig, expr.arguments!!, forReturnType = true) }
                                        catch (_: StackOverflowError) { null }
                                    // B86.1b-4 fallback: when the full mapper is null (e.g. a
                                    // callback-return-position TP `U` is uninferable because the
                                    // lambda body errors), use the partial anchor-only mapper so
                                    // the lambda's PARAM `(x:T)` still resolves to its concrete
                                    // anchor type during the diagnostic walk (TS2339 in the body).
                                    full ?: try { tryInferAnchorTypeParamsForContext(sig, expr.arguments!!) }
                                        catch (_: StackOverflowError) { null }
                                } else null
                            // B83.4d: literal-preserving OVERRIDE for fixed-type-parameter
                            // conflict TPs (e.g. `f<T>(x:T, b:()=>(a:T)=>void, y:T)` called
                            // with conflicting `''`/`1`). TypeScript fixes T to the unwidened
                            // first literal `""`, so the callback param `a` is contextually
                            // typed `""` and `a.foo` reports TS2339 on `""` (not `string`).
                            // Composed over inferMapper: literal wins for conflict TPs, the
                            // widened mapper covers the rest. Confined to contextual-param
                            // typing for THIS call (restored after the arg walk) so the literal
                            // never leaks into return-type inference / JS-emit per the gotcha.
                            val litMapper: TypeMapper? =
                                if (expr.typeArguments.isNullOrEmpty() && !sig.typeParameters.isNullOrEmpty())
                                    try { computeFixedConflictLiteralMapper(sig, expr.arguments!!) }
                                        catch (_: StackOverflowError) { null }
                                else null
                            val ctxMapper: TypeMapper? = when {
                                litMapper == null -> inferMapper
                                inferMapper == null -> litMapper
                                else -> TypeMapper { tp -> litMapper.map(tp) ?: inferMapper.map(tp) }
                            }
                            expr.arguments!!.mapIndexed { i, _ ->
                                if (i < sig.parameters.size) {
                                    val ptRaw = getTypeOfSymbol(sig.parameters[i])
                                    val pt = if (ctxMapper != null && ptRaw !== anyType && ptRaw !== errorType) {
                                        try { instantiateContextualParamType(ptRaw, ctxMapper) } catch (_: StackOverflowError) { ptRaw }
                                    } else ptRaw
                                    if (pt === anyType || pt === errorType) null else pt
                                } else null
                            }
                        } else {
                            expr.arguments!!.mapIndexed { i, _ ->
                                val candidates = sigs.mapNotNull { sig ->
                                    if (i < sig.parameters.size) {
                                        val pt = getTypeOfSymbol(sig.parameters[i])
                                        if (pt === anyType || pt === errorType) null else pt
                                    } else null
                                }
                                if (candidates.size != sigs.size) null
                                else if (candidates.all { it is Type.Object && !it.callSignatures.isNullOrEmpty() }) candidates[0]
                                else null
                            }
                        }
                    } catch (_: StackOverflowError) { null }
                }
                expr.arguments?.forEachIndexed { i, arg ->
                    val savedCtx = contextualType
                    val argCtx = argCtxTypes?.getOrNull(i)
                    if (argCtx != null) contextualType = argCtx else contextualType = null
                    try {
                        checkPropertyAccessInExpr(arg, source, fileName, enclosingClassType)
                    } finally {
                        contextualType = savedCtx
                    }
                }
            }
            is BinaryExpression -> {
                // B64.5: iterative left-spine flatten. Preserve TS2493 emission for
                // assignment-target ArrayLiteral on each spine node before flattening.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    if (cur.operator == SyntaxKind.Equals && cur.left is ArrayLiteralExpression) {
                        checkAssignmentTupleBounds(cur.left as ArrayLiteralExpression, cur.right, source, fileName)
                    }
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkPropertyAccessInExpr(cur, source, fileName, enclosingClassType)
                while (rightStack.isNotEmpty()) checkPropertyAccessInExpr(rightStack.removeLast(), source, fileName, enclosingClassType)
            }
            is ConditionalExpression -> {
                checkPropertyAccessInExpr(expr.condition, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.whenTrue, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.whenFalse, source, fileName, enclosingClassType)
            }
            is ParenthesizedExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is ArrowFunction -> {
                val savedLocalTypes = currentLocalTypes
                val savedParamBindings = currentParamBindingNames
                currentLocalTypes = currentLocalTypes.toMutableMap()
                currentParamBindingNames = currentParamBindingNames.toMutableSet()
                populateParameterLocalTypes(expr.parameters)
                // 16.0: contextual param inference for un-annotated arrow parameters
                val ctxType = contextualType
                // B83.4d: when this arrow's body is an EXPRESSION (concise body) and its
                // contextual type is a single-call-sig function, the body is contextually
                // typed by that signature's RETURN type. Propagate it so a callback-
                // returning-a-callback shape `() => (a => a.foo)` carries the inner
                // contextual `(a: T) => void` into the inner arrow. Default to null.
                var bodyCtx: Type? = null
                if (ctxType is Type.Object) {
                    try {
                        resolveStructuredTypeMembers(ctxType)
                        val sigs = ctxType.callSignatures
                        if (sigs != null && sigs.size == 1) {
                            val sig = sigs[0]
                            for ((i, param) in expr.parameters.withIndex()) {
                                if (param.type != null) continue
                                if (i >= sig.parameters.size) break
                                val pName = param.name as? Identifier ?: continue
                                val pType = try { getTypeOfSymbol(sig.parameters[i]) } catch (_: StackOverflowError) { continue }
                                if (pType === anyType || pType === errorType) continue
                                currentLocalTypes[pName.text] = pType
                            }
                            if (expr.body is Expression) {
                                val ret = sig.resolvedReturnType
                                if (ret != null && ret !== anyType && ret !== errorType) bodyCtx = ret
                            }
                        }
                    } catch (_: StackOverflowError) { /* circular */ }
                }
                val savedCtx = contextualType
                contextualType = bodyCtx
                try {
                    expr.body.let { body ->
                        when (body) {
                            is Block -> checkPropertyAccessInStatements(body.statements, source, fileName, enclosingClassType)
                            is Expression -> checkPropertyAccessInExpr(body, source, fileName, enclosingClassType)
                            else -> {}
                        }
                    }
                } finally {
                    contextualType = savedCtx
                }
                currentLocalTypes = savedLocalTypes
                currentParamBindingNames = savedParamBindings
            }
            is NewExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                expr.arguments?.forEach { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            }
            is ElementAccessExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.argumentExpression, source, fileName, enclosingClassType)
                checkSingleElementAccess(expr, source, fileName, enclosingClassType)
            }
            is AsExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is NonNullExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is PrefixUnaryExpression -> checkPropertyAccessInExpr(expr.operand, source, fileName, enclosingClassType)
            is TemplateExpression -> {
                expr.templateSpans.forEach { span ->
                    checkPropertyAccessInExpr(span.expression, source, fileName, enclosingClassType)
                }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            }
            is ObjectLiteralExpression -> {
                // 16.0: propagate contextual type into each property value so nested
                // arrow function params can be typed from the contextual member types.
                val ctxObj = contextualType as? Type.Object
                if (ctxObj != null) {
                    try { resolveStructuredTypeMembers(ctxObj) } catch (_: StackOverflowError) {}
                }
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            val propName = when (val n = prop.name) {
                                is Identifier -> n.text
                                is StringLiteralNode -> n.text
                                else -> null
                            }
                            val propCtx = if (propName != null && ctxObj != null) {
                                ctxObj.members?.get(propName)?.let { sym ->
                                    try { getTypeOfSymbol(sym) } catch (_: StackOverflowError) { null }
                                }
                            } else null
                            val savedCtx = contextualType
                            contextualType = if (propCtx != null && propCtx !== anyType && propCtx !== errorType) propCtx else null
                            try {
                                checkPropertyAccessInExpr(prop.initializer, source, fileName, enclosingClassType)
                            } finally {
                                contextualType = savedCtx
                            }
                        }
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> {
                            val savedCtx = contextualType
                            contextualType = null
                            try {
                                checkPropertyAccessInExpr(prop.expression, source, fileName, enclosingClassType)
                            } finally {
                                contextualType = savedCtx
                            }
                        }
                        else -> {}
                    }
                }
            }
            is TaggedTemplateExpression -> {
                checkPropertyAccessInExpr(expr.tag, source, fileName, enclosingClassType)
            }
            is TypeAssertionExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is SpreadElement -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is AwaitExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is DeleteExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is VoidExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is TypeOfExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is PostfixUnaryExpression -> checkPropertyAccessInExpr(expr.operand, source, fileName, enclosingClassType)
            is SatisfiesExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is YieldExpression -> expr.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is FunctionExpression -> {
                val savedLocalTypes = currentLocalTypes
                val savedParamBindings = currentParamBindingNames
                currentLocalTypes = currentLocalTypes.toMutableMap()
                currentParamBindingNames = currentParamBindingNames.toMutableSet()
                // 16.0: shadow outer vars with unannotated function-expression params
                // so `(s: string) => ... || function (s) { s.aaa }` does not falsely
                // type the inner `s` from the outer scope.
                for (param in expr.parameters) {
                    // B83.4i: register destructured-param binding names for the
                    // call-inferred-var TS2339 shadow gate (see populateParameterLocalTypes).
                    if (param.name is ArrayBindingPattern || param.name is ObjectBindingPattern) {
                        collectBindingNames(param.name, currentParamBindingNames)
                    }
                    val pName = (param.name as? Identifier)?.text ?: continue
                    if (param.type != null) {
                        try {
                            val pt = getTypeFromTypeNode(param.type!!)
                            if (pt !== anyType && pt !== errorType) {
                                currentLocalTypes[pName] = pt
                                continue
                            }
                        } catch (_: StackOverflowError) {}
                    }
                    // Unannotated param: remove any outer binding so property access falls back to `any`
                    currentLocalTypes.remove(pName)
                }
                // B81.1b: contextual param inference for un-annotated function-expression
                // parameters — mirror the ArrowFunction infrastructure above. When the
                // FunctionExpression appears as an argument to a CallExpression whose
                // callee has a single call signature, propagate the corresponding param
                // type into `currentLocalTypes` so property access checks can find
                // optional members and emit TS18048 etc.
                val ctxType = contextualType
                if (ctxType is Type.Object) {
                    try {
                        resolveStructuredTypeMembers(ctxType)
                        val sigs = ctxType.callSignatures
                        if (sigs != null && sigs.size == 1) {
                            val sig = sigs[0]
                            for ((i, param) in expr.parameters.withIndex()) {
                                if (param.type != null) continue
                                if (i >= sig.parameters.size) break
                                val pName = param.name as? Identifier ?: continue
                                val pType = try { getTypeOfSymbol(sig.parameters[i]) } catch (_: StackOverflowError) { continue }
                                if (pType === anyType || pType === errorType) continue
                                currentLocalTypes[pName.text] = pType
                            }
                        }
                    } catch (_: StackOverflowError) { /* circular */ }
                }
                val savedCtx = contextualType
                contextualType = null
                try {
                    expr.body?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType = null) }
                } finally {
                    contextualType = savedCtx
                }
                currentLocalTypes = savedLocalTypes
                currentParamBindingNames = savedParamBindings
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2341: Private member accessibility check
    // -----------------------------------------------------------------------

    /**
     * Check if a property access violates private member accessibility.
     * Returns true if TS2341 was emitted (caller should skip TS2339 check).
     */
    private fun checkPrivateMemberAccess(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ): Boolean {
        if (expr.expression !is Identifier) return false
        val identName = (expr.expression as Identifier).text
        val propName = expr.name.text

        if (identName == "this") {
            // this.prop — check if accessing private member from base class
            if (enclosingClassType == null) return false
            if (enclosingClassType !is Type.Interface) return false
            resolveStructuredTypeMembers(enclosingClassType)
            val prop = getPropertyOfType(enclosingClassType, propName) ?: return false
            val decl = prop.valueDeclaration ?: prop.declarations.firstOrNull() ?: return false
            if (!isMemberPrivate(decl)) return false
            val (declaringName, displayName) = findPrivateDeclaringClassInfo(enclosingClassType, propName) ?: return false
            val enclosingName = enclosingClassType.symbol?.name ?: return false
            if (enclosingName == declaringName) return false // access within same class is OK
            emitTS2341(expr, propName, displayName, source, fileName)
            return true
        }

        if (identName == "super") {
            // super.prop — a private METHOD in a base type is a TS2341 error.
            // Data-property accesses via super get TS2340 instead (emitted elsewhere),
            // so don't double-report for private data properties.
            if (enclosingClassType !is Type.Interface) return false
            resolveStructuredTypeMembers(enclosingClassType)
            for (base in enclosingClassType.baseTypes ?: emptyList()) {
                if (base !is Type.Interface) continue
                resolveStructuredTypeMembers(base)
                val prop = getPropertyOfType(base, propName) ?: continue
                val decl = prop.valueDeclaration ?: prop.declarations.firstOrNull() ?: continue
                if (decl !is MethodDeclaration) continue
                if (!isMemberPrivate(decl)) continue
                val (_, displayName) = findPrivateDeclaringClassInfo(base, propName) ?: continue
                emitTS2341(expr, propName, displayName, source, fileName)
                return true
            }
            return false
        }

        val identSymbol = globals[identName] ?: return false

        if (identSymbol.flags.hasAny(SymbolFlags.Class)) {
            // Static access: C.prop — check static private members
            return checkStaticPrivateMemberAccess(expr, identSymbol, propName, source, fileName, enclosingClassType)
        }

        if (identSymbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
            // Instance access: c.prop — resolve type, check if property is private
            var exprType = getTypeOfSymbol(identSymbol)
            if (exprType === anyType) {
                // Try to infer from `new X()` initializer
                exprType = tryInferNewExpressionType(identSymbol) ?: return false
            }
            if (exprType === errorType || exprType === unknownType) return false
            if (exprType !is Type.Interface) return false
            resolveStructuredTypeMembers(exprType)
            val prop = getPropertyOfType(exprType, propName) ?: return false
            val decl = prop.valueDeclaration ?: prop.declarations.firstOrNull() ?: return false
            if (!isMemberPrivate(decl)) return false
            val (declaringName, displayName) = findPrivateDeclaringClassInfo(exprType, propName) ?: return false
            val enclosingName = (enclosingClassType as? Type.Object)?.symbol?.name
            if (enclosingName == declaringName) return false
            emitTS2341(expr, propName, displayName, source, fileName)
            return true
        }

        return false
    }

    /** Check static private member access: C.prop where C is a class symbol. */
    private fun checkStaticPrivateMemberAccess(
        expr: PropertyAccessExpression, classSymbol: Symbol, propName: String,
        source: String, fileName: String, enclosingClassType: Type?,
    ): Boolean {
        for (decl in classSymbol.declarations) {
            if (decl !is ClassDeclaration) continue
            for (member in decl.members) {
                val isStatic = when (member) {
                    is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                    is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                    is GetAccessor -> ModifierFlag.Static in member.modifiers
                    is SetAccessor -> ModifierFlag.Static in member.modifiers
                    else -> false
                }
                if (!isStatic) continue
                val memberName = when (member) {
                    is PropertyDeclaration -> (member.name as? Identifier)?.text
                    is MethodDeclaration -> (member.name as? Identifier)?.text
                    is GetAccessor -> (member.name as? Identifier)?.text
                    is SetAccessor -> (member.name as? Identifier)?.text
                    else -> null
                }
                if (memberName == propName && isMemberPrivate(member)) {
                    val enclosingName = (enclosingClassType as? Type.Object)?.symbol?.name
                    if (enclosingName == classSymbol.name) return false // access within same class
                    val displayName = getClassNameWithTypeParams(classSymbol)
                    emitTS2341(expr, propName, displayName, source, fileName)
                    return true
                }
            }
        }
        return false
    }

    /** Emit TS2341: Property 'X' is private and only accessible within class 'Y'. */
    private fun emitTS2341(
        expr: PropertyAccessExpression, propName: String, className: String,
        source: String, fileName: String,
    ) {
        val start = expr.name.pos
        val length = expr.name.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' is private and only accessible within class '$className'.",
            category = DiagnosticCategory.Error,
            code = 2341,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** Get class name with type parameters for error messages (e.g., "D<T>"). */
    private fun getClassNameWithTypeParams(symbol: Symbol): String {
        for (decl in symbol.declarations) {
            if (decl is ClassDeclaration) {
                val typeParams = decl.typeParameters
                if (typeParams != null && typeParams.isNotEmpty()) {
                    val params = typeParams.joinToString(", ") { it.name.text }
                    return "${symbol.name}<$params>"
                }
            }
        }
        return symbol.name
    }

    /**
     * Find the declaring class of a private member, returning (rawName, displayNameWithTypeParams).
     * Walks base type chain to find the class where the member is declared as private.
     */
    private fun findPrivateDeclaringClassInfo(type: Type.Object, memberName: String): Pair<String, String>? {
        if (type is Type.Interface) {
            val symbol = type.symbol
            if (symbol != null) {
                for (decl in symbol.declarations) {
                    val members = when (decl) {
                        is ClassDeclaration -> decl.members
                        else -> continue
                    }
                    // Collect all members with matching name and check if ALL are private.
                    // For get/set accessor pairs, if getter is public but setter is private,
                    // the property is not fully private (reads are allowed).
                    var foundAnyWithName = false
                    var allPrivate = true
                    for (member in members) {
                        val name = when (member) {
                            is PropertyDeclaration -> (member.name as? Identifier)?.text
                            is MethodDeclaration -> (member.name as? Identifier)?.text
                            is GetAccessor -> (member.name as? Identifier)?.text
                            is SetAccessor -> (member.name as? Identifier)?.text
                            else -> null
                        }
                        if (name == memberName) {
                            foundAnyWithName = true
                            if (!isMemberPrivate(member)) {
                                allPrivate = false
                            }
                        }
                    }
                    // Also check constructor parameter properties
                    for (member in members) {
                        if (member is Constructor) {
                            for (param in member.parameters) {
                                val paramName = (param.name as? Identifier)?.text
                                if (paramName == memberName) {
                                    foundAnyWithName = true
                                    if (ModifierFlag.Private !in param.modifiers) {
                                        allPrivate = false
                                    }
                                }
                            }
                        }
                    }
                    if (foundAnyWithName && allPrivate) {
                        return Pair(symbol.name, getClassNameWithTypeParams(symbol))
                    }
                }
            }
            // Walk base types
            type.baseTypes?.forEach { bt ->
                if (bt is Type.Object) {
                    val result = findPrivateDeclaringClassInfo(bt, memberName)
                    if (result != null) return result
                }
            }
        }
        return null
    }

    /** Try to infer the type from a `new X()` or `new A.B()` initializer. */
    private fun tryInferNewExpressionType(symbol: Symbol): Type? {
        val decl = symbol.valueDeclaration ?: return null
        if (decl !is VariableDeclaration) return null
        val init = decl.initializer ?: return null
        if (init !is NewExpression) return null
        val classSymbol = when (val expr = init.expression) {
            is Identifier -> globals[expr.text]
            is PropertyAccessExpression -> {
                val obj = expr.expression
                if (obj is Identifier) {
                    val nsSym = globals[obj.text]
                    if (nsSym != null && nsSym.flags.hasAny(SymbolFlags.Module)) {
                        nsSym.exports?.get(expr.name.text)
                    } else null
                } else null
            }
            else -> null
        }
        if (classSymbol == null || !classSymbol.flags.hasAny(SymbolFlags.Class)) return null
        return try { getDeclaredTypeOfSymbol(classSymbol) } catch (_: StackOverflowError) { null }
    }

    /**
     * TS2340: Only public and protected methods of the base class are accessible via 'super'.
     * In ES5, super can only be used to access methods — properties/getters/setters are not
     * accessible because downlevel emit can't support [[Get]] on super for accessors.
     */
    private fun checkSuperPropertyAccessES5(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        val propName = expr.name.text
        if (enclosingClassType == null) return
        if (enclosingClassType !is Type.Interface) return
        // Find the base class type
        val baseTypes = enclosingClassType.baseTypes
        if (baseTypes.isNullOrEmpty()) return
        // B50.9: In static context, `super` refers to `typeof BaseClass` (constructor side).
        // Only static members are accessible; non-static members should fall through to TS2339
        // ("Property 'x' does not exist on type 'typeof C'.") instead of TS2340 (which is
        // about instance-side method-vs-non-method discrimination).
        val isStaticContext = inStaticClassMethod
        for (baseType in baseTypes) {
            if (baseType !is Type.Interface) continue
            resolveStructuredTypeMembers(baseType)
            // Find the member in the base class
            val baseSym = baseType.symbol ?: continue
            for (decl in baseSym.declarations) {
                if (decl !is ClassDeclaration) continue
                for (member in decl.members) {
                    val memberName = when (member) {
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is GetAccessor -> (member.name as? Identifier)?.text
                        is SetAccessor -> (member.name as? Identifier)?.text
                        else -> null
                    }
                    if (memberName != propName) continue
                    val memberIsStatic = when (member) {
                        is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                        is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                        is GetAccessor -> ModifierFlag.Static in member.modifiers
                        is SetAccessor -> ModifierFlag.Static in member.modifiers
                        else -> false
                    }
                    // B50.9: Static-context vs instance-context lookup.
                    // - Static context + non-static member: skip (falls through to TS2339).
                    // - Instance context + static member that's a method/property/accessor:
                    //   emit TS2576 with "Did you mean to access the static member 'C.x'?".
                    if (isStaticContext && !memberIsStatic) continue
                    if (!isStaticContext && memberIsStatic) {
                        val start = expr.name.pos
                        val length = propName.length
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        val baseClassName = baseSym.declarations.firstOrNull { it is ClassDeclaration }
                            .let { (it as? ClassDeclaration)?.name?.text }
                        val suggestion = if (baseClassName != null) " Did you mean to access the static member '${baseClassName}.${propName}' instead?" else ""
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${baseType.symbol?.name ?: "unknown"}'.$suggestion",
                            category = DiagnosticCategory.Error,
                            code = 2576,
                            fileName = fileName,
                            line = line, character = character,
                            start = start, length = length,
                        ))
                        return
                    }
                    // Methods are OK via super, properties/getters/setters are not
                    if (member is MethodDeclaration) return // found as method — no error
                    val start = expr.name.pos
                    val length = propName.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    // TS2576: Static member accessed via super — use different message
                    val isStatic = member is PropertyDeclaration &&
                        ModifierFlag.Static in (member as PropertyDeclaration).modifiers
                    if (isStatic) {
                        // Get enclosing class name for the suggestion
                        val baseClassName = baseSym.declarations.firstOrNull { it is ClassDeclaration }
                            .let { (it as? ClassDeclaration)?.name?.text }
                        val suggestion = if (baseClassName != null) " Did you mean to access the static member '${baseClassName}.${propName}' instead?" else ""
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${baseType.symbol?.name ?: "unknown"}'.$suggestion",
                            category = DiagnosticCategory.Error,
                            code = 2576,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    } else {
                        // Non-method, non-static member — emit TS2340
                        diagnostics.add(Diagnostic(
                            message = "Only public and protected methods of the base class are accessible via the 'super' keyword.",
                            category = DiagnosticCategory.Error,
                            code = 2340,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    return
                }
            }
        }
    }

    /** 16.4ef: TS2855 "Class field 'X' defined by the parent class is not accessible in the
     *  child class via super." For ES2015+ targets, class fields (PropertyDeclaration without
     *  `declare` / `static`) are installed on the instance via `Object.defineProperty` in the
     *  constructor. `super.field` doesn't walk to the base instance's shadowed field — it
     *  reads the prototype chain, which has no such slot, yielding `undefined` at runtime.
     *  Methods, getters/setters, static members, and ambient `declare` properties are fine. */
    private fun checkSuperFieldAccessES2015Plus(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        val propName = expr.name.text
        if (enclosingClassType == null) return
        if (enclosingClassType !is Type.Interface) return
        val baseTypes = enclosingClassType.baseTypes ?: return
        if (baseTypes.isEmpty()) return
        // B50.9: track static context so static-vs-instance access mismatches emit
        // the right diagnostic (TS2576 for instance-context-accesses-static, TS2339
        // for static-context-accesses-instance via emitTs2339ForMissingSuperMember).
        val isStaticContext = inStaticClassMethod
        for (baseType in baseTypes) {
            if (baseType !is Type.Interface) continue
            val baseSym = baseType.symbol ?: continue
            for (decl in baseSym.declarations) {
                if (decl !is ClassDeclaration) continue
                for (member in decl.members) {
                    // B50.9: Also consider MethodDeclaration for static-vs-instance mismatch.
                    if (member !is PropertyDeclaration && member !is MethodDeclaration) continue
                    val memberName = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text ?: continue
                        is MethodDeclaration -> (member.name as? Identifier)?.text ?: continue
                        else -> continue
                    }
                    if (memberName != propName) continue
                    // Ambient `declare` properties don't have class-field semantics → skip.
                    if (member is PropertyDeclaration && ModifierFlag.Declare in member.modifiers) return
                    val memberIsStatic = when (member) {
                        is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                        is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                        else -> false
                    }
                    // B50.9: skip same-side member (handled by emitTs2339ForMissingSuperMember
                    // falling through to TS2339), keep only cross-side mismatch checks.
                    if (memberIsStatic == isStaticContext) {
                        // Same side — only PropertyDeclaration falls through to the
                        // TS2855 branch below; static methods on static side are OK.
                        if (member is MethodDeclaration) return
                        // For PropertyDeclaration, proceed to TS2855/TS2576 below.
                    }
                    val start = expr.name.pos
                    val length = propName.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    // Static members accessed via `super` → TS2576 with "did you mean static" hint,
                    // matching the existing ES5 branch. Non-static class fields → TS2855.
                    if (memberIsStatic && !isStaticContext) {
                        val baseClassName = baseSym.declarations.firstOrNull { it is ClassDeclaration }
                            .let { (it as? ClassDeclaration)?.name?.text }
                        val suggestion = if (baseClassName != null) " Did you mean to access the static member '${baseClassName}.${propName}' instead?" else ""
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${baseType.symbol?.name ?: "unknown"}'.$suggestion",
                            category = DiagnosticCategory.Error,
                            code = 2576,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    } else if (member is PropertyDeclaration && !memberIsStatic && !isStaticContext) {
                        diagnostics.add(Diagnostic(
                            message = "Class field '$propName' defined by the parent class is not accessible in the child class via super.",
                            category = DiagnosticCategory.Error,
                            code = 2855,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    return
                }
            }
        }
    }

    /**
     * Check a single property access expression for TS2341 and TS2339.
     * TS2341 is checked first (private member accessibility).
     */
    /** Populate currentLocalTypes with resolved parameter types for TS2339/TS2345 checking. */
    /**
     * 17.73: Push a function-like's type parameters into [currentTypeParamScope]
     * so subsequent `getTypeFromTypeNode("T")` calls resolve to Type.TypeParam.
     * Returns the previous scope so the caller can restore it via finally.
     * Constraints are resolved AFTER all type params are inserted (so `<T, U extends T>`
     * works). When [typeParameters] is null/empty, no scope change is made.
     */
    private fun pushFunctionTypeParamsScope(typeParameters: List<TypeParameter>?): Map<String, Type.TypeParam>? {
        val saved = currentTypeParamScope
        if (typeParameters.isNullOrEmpty()) return saved
        val scope = (saved?.toMutableMap() ?: mutableMapOf())
        for (tpDecl in typeParameters) {
            val tp = Type.TypeParam()
            tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
            scope[tpDecl.name.text] = tp
        }
        currentTypeParamScope = scope
        // Resolve constraints AFTER all type params are in scope (so siblings can refer to each other).
        for (tpDecl in typeParameters) {
            val tp = scope[tpDecl.name.text] ?: continue
            tpDecl.constraint?.let {
                try { tp.constraint = getTypeFromTypeNode(it) } catch (_: StackOverflowError) {}
            }
            tpDecl.default?.let {
                try { tp.default = getTypeFromTypeNode(it) } catch (_: StackOverflowError) {}
            }
        }
        return saved
    }

    private fun populateParameterLocalTypes(parameters: List<Parameter>) {
        for (param in parameters) {
            val paramName = param.name
            val paramType = param.type
            if (paramType != null && paramName is Identifier) {
                // Rest parameter with clearly-non-array type: skip (TS2370 fires at declaration;
                // runtime type is effectively any[] so downstream checks should not use the
                // erroneous annotation).
                if (param.dotDotDotToken && nonArrayKeywordText(paramType) != null) continue
                try {
                    val resolvedType = getTypeFromTypeNode(paramType)
                    if (resolvedType !== anyType && resolvedType !== errorType) {
                        currentLocalTypes[paramName.text] = resolvedType
                    }
                } catch (_: StackOverflowError) { /* circular type */ }
            } else if (paramName is ArrayBindingPattern || paramName is ObjectBindingPattern) {
                // B83.4i: register destructured-param binding NAMES (e.g. `[x]` / `{x}`)
                // into the shadow tracker so a same-named file-level `var x = foo(...)`
                // (call-inferred) does NOT drive TS2339 on `x.prop` inside this body.
                // Without this the binding name is invisible to the shadow checks (the
                // simple-identifier branch above skips patterns), and a primitive-typed
                // file var would FP-fire (functionOverloads43: `function foo([x]:...){
                // return x.a }` + `var x = foo(...)`). Records into a side set rather than
                // currentLocalTypes to avoid changing identifier type resolution.
                collectBindingNames(paramName, currentParamBindingNames)
            }
        }
    }

    private fun checkSinglePropertyAccess(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        // 17.201: TS1209 — `new A?.b()` where the `?.` chains off a NewExpression
        // with NO arguments list. Parser shape: PropertyAccessExpression with
        // `questionDotToken == true`, expression == `NewExpression(arguments == null)`.
        // Squiggle on the `?.` token (length 2), located by searching forward
        // from the receiver expression's source position.
        if (expr.questionDotToken && expr.expression is NewExpression) {
            val recv = expr.expression as NewExpression
            if (recv.arguments == null) {
                val ctor = recv.expression
                val ctorName = (ctor as? Identifier)?.text
                val didYouMean = if (ctorName != null) " Did you mean to call '$ctorName()'?" else ""
                // Search backward from `expr.name.pos` for the `?.` token (always
                // immediately precedes the property name, possibly with whitespace).
                var i = (expr.name.pos - 1).coerceAtMost(source.length - 1)
                while (i >= 0 && source[i] != '?') {
                    if (!source[i].isWhitespace() && source[i] != '.') break
                    i--
                }
                if (i >= 0 && source[i] == '?') {
                    val (line, character) = getLineAndCharacterOfPosition(source, i)
                    diagnostics.add(Diagnostic(
                        message = "Invalid optional chain from new expression.$didYouMean",
                        category = DiagnosticCategory.Error,
                        code = 1209,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = i,
                        length = 2,
                    ))
                }
            }
        }
        // 17.190: TS2339 — `.prototype` on a NewExpression instance (e.g.
        // `new Object().prototype`). Instances never have a `prototype`
        // property; only the constructor side does. Display uses the
        // constructor's name (Identifier) to mirror TypeScript's baseline.
        if (expr.name.text == "prototype") {
            var recv: Expression = expr.expression
            while (recv is ParenthesizedExpression) recv = recv.expression
            if (recv is NewExpression) {
                val ctor = recv.expression
                if (ctor is Identifier) {
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Property 'prototype' does not exist on type '${ctor.text}'.",
                        category = DiagnosticCategory.Error,
                        code = 2339,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.name.pos,
                        length = expr.name.text.length,
                    ))
                    return
                }
            }
        }
        // === 17.44: TS2532 "Object is possibly 'undefined'" for non-optional access
        // on a synthetic-paren receiver produced by an instantiation expression that
        // breaks an optional chain (e.g. `a?.b<c>.d`). The synthetic paren is tagged
        // by the parser via [ParenthesizedExpression.instantiationEnd]; without the
        // narrow tag this would over-fire for every `(a?.b).c` style access. ===
        emitTs2532ForOptionalChainInstantiationReceiver(expr, source, fileName)

        // === B81.1c: TS18048 "'X.Y' is possibly 'undefined'." for non-optional access
        // on a PropertyAccess receiver whose own property is optional (e.g.
        // `foo.a.b` where `a?` is optional). Consults loop-aware flow narrowing
        // so reads INSIDE a loop body see narrowing established at loop entry
        // (e.g. `if (foo.a) { for(...) { foo.a.b ... } }` suppresses). ===
        emitTs18048ForOptionalPropertyAccessReceiver(expr, source, fileName)

        // === TS2340 (ES5) / TS2855 (ES2015+): super property access restriction ===
        if (expr.expression is Identifier && (expr.expression as Identifier).text == "super") {
            if (options.target <= ScriptTarget.ES5) {
                checkSuperPropertyAccessES5(expr, source, fileName, enclosingClassType)
            } else {
                checkSuperFieldAccessES2015Plus(expr, source, fileName, enclosingClassType)
            }
            // 16.4ex: emit TS2339 when the property doesn't exist on the base class.
            if (emitTs2339ForMissingSuperMember(expr, source, fileName, enclosingClassType)) return
        }

        // === TS2748: Cannot access ambient const enums when 'isolatedModules' is enabled ===
        // Fires for `E.X` where E is a `declare const enum E { ... }` declaration in a non-.d.ts file,
        // under @isolatedModules. With @preserveConstEnums, the ambient const enum is preserved at
        // runtime as an object (TypeScript still allows the access). Without it, the access has
        // no runtime referent — isolatedModules transpilation requires per-file independence so
        // cross-file ambient const enums cannot be inlined.
        if (options.isolatedModules && !options.preserveConstEnums) {
            val receiver = expr.expression
            if (receiver is Identifier) {
                val sym = resolveNamePath(receiver.text, binderResults.firstOrNull { it.sourceFile.fileName == fileName } ?: return)
                if (sym != null) {
                    val target = resolveAlias(sym)
                    val isAmbientConstEnum = target.declarations.any { decl ->
                        decl is EnumDeclaration &&
                            ModifierFlag.Const in decl.modifiers &&
                            ModifierFlag.Declare in decl.modifiers
                    }
                    if (isAmbientConstEnum) {
                        val (line, character) = getLineAndCharacterOfPosition(source, receiver.pos)
                        diagnostics.add(Diagnostic(
                            message = "Cannot access ambient const enums when 'isolatedModules' is enabled.",
                            category = DiagnosticCategory.Error,
                            code = 2748,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = receiver.pos,
                            length = receiver.text.length,
                        ))
                    }
                }
            }
        }

        // === TS2341: Private member accessibility check ===
        if (checkPrivateMemberAccess(expr, source, fileName, enclosingClassType)) return

        // === TS2339/TS2551: Property does not exist check ===
        checkMemberAccessMissing(
            objectExprIn = expr.expression,
            propName = expr.name.text,
            diagStart = expr.name.pos,
            diagLength = expr.name.text.length,
            source = source,
            fileName = fileName,
            enclosingClassType = enclosingClassType,
            emitTs2728RelatedInfo = true,
        )
    }

    /**
     * 16.4ex: TS2339 for `super.X` where X isn't a member of any base class in the chain.
     * Gated on: enclosing class has at least one non-empty baseType; propName not in the
     * Object.prototype implicit list. Walks the base chain via `getPropertyOfType`, which
     * already handles inherited members. Returns true if emitted (so the caller can bail
     * before the generic member-access check runs).
     */
    private fun emitTs2339ForMissingSuperMember(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ): Boolean {
        val propName = expr.name.text
        if (propName.isEmpty()) return false
        if (propName in OBJECT_PROTOTYPE_IMPLICIT) return false
        if (enclosingClassType !is Type.Interface) return false
        val baseTypes = enclosingClassType.baseTypes ?: return false
        if (baseTypes.isEmpty()) return false
        // B50.9: In static context, super refers to `typeof BaseClass`; look up only
        // static members. Display as `typeof <BaseName>` instead of `<BaseName>`.
        val isStaticContext = inStaticClassMethod
        var baseDisplay: String? = null
        for (base in baseTypes) {
            if (base !is Type.Interface) return false // unknown base shape — be conservative
            if (baseDisplay == null) baseDisplay = base.symbol?.name
            try { resolveStructuredTypeMembers(base) } catch (_: StackOverflowError) { return false }
            if (isStaticContext) {
                // Static lookup — check the static-side member table only.
                if (base.staticMembers?.get(propName) != null) return false
            } else {
                if (getPropertyOfType(base, propName) != null) return false
                // Also walk base's base chain (resolveStructuredTypeMembers may not have
                // merged inherited members — be thorough).
                if (basePropertyInheritedChain(base, propName, mutableSetOf())) return false
            }
        }
        val display = baseDisplay ?: return false
        val displayName = if (isStaticContext) "typeof $display" else display
        val start = expr.name.pos
        val length = propName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$displayName'.",
            category = DiagnosticCategory.Error,
            code = 2339,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return true
    }

    private fun basePropertyInheritedChain(
        base: Type.Interface, propName: String, visited: MutableSet<Int>,
    ): Boolean {
        if (!visited.add(base.id)) return false
        val chain = base.baseTypes ?: return false
        for (b in chain) {
            if (b !is Type.Interface) return false
            try { resolveStructuredTypeMembers(b) } catch (_: StackOverflowError) { return false }
            if (getPropertyOfType(b, propName) != null) return true
            if (basePropertyInheritedChain(b, propName, visited)) return true
        }
        return false
    }

    /**
     * 17.44: Emit TS2532 "Object is possibly 'undefined'." for non-optional property
     * access on a synthetic-paren receiver produced when an instantiation expression
     * (`expr<T>`) breaks an optional chain. The parser inserts a [ParenthesizedExpression]
     * with [ParenthesizedExpression.instantiationEnd] populated for these cases (see
     * Parser.kt's `LessThan -> ... Dot, QuestionDot ->` branch). Without the breaking
     * `<T>`, `a?.b.d` is a single optional chain — `.d` continues the chain and the
     * whole expression is `(typeof A.b.d) | undefined`, no TS2532. WITH the `<T>`,
     * `a?.b<c>.d` becomes `((a?.b)).d` — the receiver `(a?.b)` could be undefined,
     * and the non-optional `.d` then dereferences potential undefined → TS2532.
     *
     * Conservative gating beyond the synthetic-paren marker: outer access is
     * non-optional (otherwise the chain continues and TS2532 doesn't apply); the
     * optional-chain root operand's type contains `undefined` or `null` (otherwise
     * `?.` is statically unnecessary and the receiver is non-undefined); strict null
     * checks are enabled (TS2532 is gated on strictNullChecks per TypeScript's spec).
     * Squiggle: from `receiver.pos` to `receiver.instantiationEnd`, covering
     * `expr<T>` exactly (excludes the trailing `.`).
     */
    private fun emitTs2532ForOptionalChainInstantiationReceiver(
        expr: PropertyAccessExpression, source: String, fileName: String,
    ) {
        if (expr.questionDotToken) return
        if (!strictNullChecks) return
        val receiver = expr.expression
        if (receiver !is ParenthesizedExpression) return
        val instEnd = receiver.instantiationEnd ?: return
        // The synthetic-paren marker already proves the inner expression contains
        // an optional chain (the parser only wraps in this case). We don't try to
        // verify the chain root's type is `T | undefined`: `typeof Namespace`
        // currently resolves to `anyType` in our checker, which would defeat the
        // check. The instantiation-paren pattern is so rare in the test corpus
        // (1 test) that the risk of over-firing is bounded; rely on the
        // parser-level marker as the gate.
        if (findOptionalChainRootOperand(receiver) == null) return
        val start = receiver.pos
        val length = instEnd - receiver.pos
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Object is possibly 'undefined'.",
            category = DiagnosticCategory.Error,
            code = 2532,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * B81.1c: Emit TS18048 "'X.Y' is possibly 'undefined'." for non-optional access
     * `recv.prop` where `recv` is itself a `PropertyAccessExpression` whose property
     * is OPTIONAL on its declared object type. Uses the loop-aware narrowing helper
     * (B81.1a) so reads inside a loop body see narrowing established at loop entry.
     *
     * Gates (conservative — narrow scope to avoid the iter12 regressions):
     *  - strictNullChecks enabled (TS18048 follows the strict-mode gate).
     *  - Outer access is non-optional (`!questionDotToken`) — `recv?.prop` would
     *    continue the chain, no diagnostic.
     *  - Receiver is `PropertyAccessExpression` with non-`?.` token (the `?.` form
     *    means the chain originated optional; falls under TS18047 territory).
     *  - Receiver's property's owning symbol is optional (`questionToken` on the
     *    declaration). Looked up via the receiver-of-receiver's apparent type.
     *  - After flow narrowing (`getNarrowedTypeForReferenceFollowLoopEntry`)
     *    the receiver type STILL includes `undefined` — suppression via narrowing
     *    (e.g. `if (foo.a)` truthy branch) avoids the FP.
     *
     * Squiggle: receiver's true text span (covers `foo.a` exactly).
     */
    private fun emitTs18048ForOptionalPropertyAccessReceiver(
        expr: PropertyAccessExpression, source: String, fileName: String,
    ) {
        if (!strictNullChecks) return
        if (expr.questionDotToken) return
        val recvExpr = expr.expression
        // Resolve receiver shape: PropertyAccess `foo.a` (original B81.1c) or
        // ElementAccess `foo["a"]` with a string-literal index (B81.1c-EAext).
        // Capture receiver-of-receiver, property name, narrowed-path display,
        // and squiggle span via the local `recvInfo` shape.
        val info = when (recvExpr) {
            is PropertyAccessExpression -> {
                if (recvExpr.questionDotToken) return
                ReceiverInfo(
                    recvOfRecv = recvExpr.expression,
                    propName = recvExpr.name.text,
                    spanStart = recvExpr.pos,
                    spanEnd = recvExpr.name.pos + recvExpr.name.text.length,
                    narrowExpr = recvExpr,
                )
            }
            is ElementAccessExpression -> {
                if (recvExpr.questionDotToken) return
                val arg = recvExpr.argumentExpression as? StringLiteralNode ?: return
                // Span ends at the closing `]` — argumentExpression.end + 1 covers it
                // (mirrors `expressionTrueEnd`'s ElementAccess branch). Fall back to
                // recvExpr.end if the argument-end position is unreliable.
                val span = expressionTrueEnd(recvExpr)
                ReceiverInfo(
                    recvOfRecv = recvExpr.expression,
                    propName = arg.text,
                    spanStart = recvExpr.pos,
                    spanEnd = span,
                    narrowExpr = recvExpr,
                )
            }
            else -> return
        }
        // Resolve receiver-of-receiver's apparent type to find the property symbol.
        val recvOfRecvType = try {
            getTypeOfExpression(info.recvOfRecv)
        } catch (_: StackOverflowError) { return }
        if (recvOfRecvType === anyType || recvOfRecvType === errorType) return
        val apparent = try { getApparentType(recvOfRecvType) } catch (_: StackOverflowError) { return }
        val propSym = getPropertyOfType(apparent, info.propName) ?: return
        if (!isOptionalProperty(propSym)) return
        // Compute the receiver's declared type as `propType | undefined`, then
        // consult loop-aware flow narrowing. If undefined survives narrowing,
        // emit the diagnostic.
        val propType = try { getTypeOfSymbol(propSym) } catch (_: StackOverflowError) { return }
        if (propType === anyType || propType === errorType) return
        val declaredWithUndef = if (typeIncludesExplicitUndefined(propType)) propType
            else getUnionType(listOf(propType, undefinedType))
        val narrowed = try {
            getNarrowedTypeForReferenceFollowLoopEntry(declaredWithUndef, info.narrowExpr)
        } catch (_: StackOverflowError) { return }
        if (!typeIncludesExplicitUndefined(narrowed)) return
        // Construct the display path for the receiver. For PropertyAccess
        // (`foo.a`), use `getReferencePath` (dotted form). For ElementAccess
        // (`foo["a"]`), build a bracket-form display by combining the
        // receiver-of-receiver's path with the literal index.
        val display = when (recvExpr) {
            is PropertyAccessExpression -> getReferencePath(recvExpr) ?: return
            is ElementAccessExpression -> {
                val basePath = getReferencePath(info.recvOfRecv) ?: return
                val arg = recvExpr.argumentExpression as StringLiteralNode
                val q = if (arg.singleQuote) "'" else "\""
                "$basePath[$q${arg.text}$q]"
            }
            else -> return
        }
        val length = info.spanEnd - info.spanStart
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, info.spanStart)
        diagnostics.add(Diagnostic(
            message = "'$display' is possibly 'undefined'.",
            category = DiagnosticCategory.Error,
            code = 18048,
            fileName = fileName,
            line = line,
            character = character,
            start = info.spanStart,
            length = length,
        ))
    }

    /** Internal carrier for [emitTs18048ForOptionalPropertyAccessReceiver]. */
    private data class ReceiverInfo(
        val recvOfRecv: Expression,
        val propName: String,
        val spanStart: Int,
        val spanEnd: Int,
        val narrowExpr: Expression,
    )

    /**
     * 17.44: Walk a synthetic-paren receiver (or its inner expression) to find the
     * operand of the OUTERMOST `?.` access. For `a?.b<c>.d`, the receiver `(a?.b)`
     * peels to `PropertyAccessExpression(a, b, ?.)` whose operand is `a`. Returns
     * null if no `?.` is found in the chain.
     */
    private fun findOptionalChainRootOperand(receiver: ParenthesizedExpression): Expression? {
        var current: Expression = receiver.expression
        while (true) {
            when (current) {
                is PropertyAccessExpression -> {
                    if (current.questionDotToken) return current.expression
                    current = current.expression
                }
                is ElementAccessExpression -> {
                    if (current.questionDotToken) return current.expression
                    current = current.expression
                }
                is CallExpression -> {
                    if (current.questionDotToken) return current.expression
                    current = current.expression
                }
                else -> return null
            }
        }
    }

    // -----------------------------------------------------------------------
    // B1.3: TS2532 for `typeof X.Y.Z.W` chains in type positions.
    //
    // Walks type bodies (currently TypeAliasDeclaration's `type`) looking for
    // [TypeQuery] nodes whose `exprName` is a [QualifiedName] chain with depth
    // ≥ 2. For each chain step, computes the receiver type and emits TS2532 at
    // the receiver's source span when the receiver type contains `undefined`
    // (after path-based flow narrowing applied at the TypeAlias's recorded flow).
    //
    // Conservative gates:
    //   - strictNullChecks only (TS2532 follows TypeScript's strict-mode gate).
    //   - Path-resolvable chains only (leftmost Identifier; intermediate `.x`
    //     segments only — no calls, no indexed-access).
    //   - Receiver must be a Type.Union that explicitly contains `undefined`
    //     (or a non-Union `undefined` — degenerate; never produced by getProp).
    //     `any` / `unknown` are NOT treated as "possibly undefined" — TypeScript
    //     doesn't emit TS2532 for those.
    //   - First emission per chain wins; the walker stops descending once it
    //     emits, to avoid cascading diagnostics on the same chain.
    // -----------------------------------------------------------------------

    /**
     * Walk a TypeNode (used as a TypeAlias body) looking for TypeQuery nodes
     * with multi-segment QualifiedName chains. Each chain is checked for
     * undefined-receiver-dereferences via [checkTypeQueryQualifiedChain].
     */
    private fun walkTypeNodeForUndefinedTypeQueryChain(
        type: TypeNode, source: String, fileName: String, atNode: Node,
    ) {
        when (type) {
            is TypeQuery -> {
                val name = type.exprName
                if (name is QualifiedName) {
                    checkTypeQueryQualifiedChain(name, source, fileName, atNode)
                }
            }
            is UnionType -> type.types.forEach {
                walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode)
            }
            is IntersectionType -> type.types.forEach {
                walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode)
            }
            is ParenthesizedType ->
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            is ArrayType ->
                walkTypeNodeForUndefinedTypeQueryChain(type.elementType, source, fileName, atNode)
            is TupleType -> type.elements.forEach {
                if (it is TypeNode) walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode)
            }
            is RestType ->
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            is OptionalType ->
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            is TypeOperator ->
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            is NamedTupleMember ->
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) } }
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) } }
                walkTypeNodeForUndefinedTypeQueryChain(type.type, source, fileName, atNode)
            }
            is TypeLiteral -> for (m in type.members) {
                when (m) {
                    is PropertyDeclaration -> m.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) }
                    is MethodDeclaration -> {
                        m.parameters.forEach { p -> p.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) } }
                        m.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) }
                    }
                    is IndexSignature -> m.type?.let { walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode) }
                    else -> {}
                }
            }
            is ConditionalType -> {
                walkTypeNodeForUndefinedTypeQueryChain(type.checkType, source, fileName, atNode)
                walkTypeNodeForUndefinedTypeQueryChain(type.extendsType, source, fileName, atNode)
                walkTypeNodeForUndefinedTypeQueryChain(type.trueType, source, fileName, atNode)
                walkTypeNodeForUndefinedTypeQueryChain(type.falseType, source, fileName, atNode)
            }
            is IndexedAccessType -> {
                walkTypeNodeForUndefinedTypeQueryChain(type.objectType, source, fileName, atNode)
                walkTypeNodeForUndefinedTypeQueryChain(type.indexType, source, fileName, atNode)
            }
            is TypeReference -> type.typeArguments?.forEach {
                walkTypeNodeForUndefinedTypeQueryChain(it, source, fileName, atNode)
            }
            else -> { /* leaf or unsupported shape */ }
        }
    }

    /**
     * Walk a QualifiedName chain inside `typeof X.Y.Z.W`. Returns the
     * receiver span (pos, length) of the first intermediate step whose
     * receiver type contains `undefined`, or null when no emission is
     * warranted.
     */
    private fun checkTypeQueryQualifiedChain(
        name: QualifiedName, source: String, fileName: String, atNode: Node,
    ) {
        // Collect the chain root-to-leaf. After this loop, `leftmost` is the
        // start Identifier and `segments` lists the QualifiedName nodes in
        // order [foo.a, foo.a.b, foo.a.b.c, ...].
        val segments = mutableListOf<QualifiedName>()
        var cur: Node = name
        while (cur is QualifiedName) {
            segments.add(0, cur)
            cur = cur.left
        }
        val leftmost = cur as? Identifier ?: return
        if (segments.size < 2) return

        // Flow node at the enclosing statement (TypeAlias).
        val flow = currentFlowGraph?.nodeToFlow?.get(nodeKey(atNode)) ?: return

        // Resolve the leftmost identifier's type.
        var receiverType: Type = getTypeOfIdentifier(leftmost)
        if (receiverType === anyType || receiverType === errorType) return
        var path: String = leftmost.text
        if (receiverType is Type.Union) {
            receiverType = narrowTypeFromFlowFollowLoopEntry(receiverType, flow, path, mutableSetOf(), 0)
        }

        // Walk each segment in order. At each step, we're about to access
        // `.propName` on `receiverType`. If receiverType contains undefined
        // (after narrowing), emit TS2532 at the receiver's source span and stop.
        for (segment in segments) {
            val propName = segment.right.text
            val newPath = "$path.$propName"

            if (typeIncludesExplicitUndefined(receiverType)) {
                val receiverNode: Node = segment.left
                val receiverStart = receiverNode.pos
                val receiverEnd = qualifiedNameOrIdentifierTrueEnd(receiverNode)
                val length = receiverEnd - receiverStart
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, receiverStart)
                    diagnostics.add(Diagnostic(
                        message = "Object is possibly 'undefined'.",
                        category = DiagnosticCategory.Error,
                        code = 2532,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = receiverStart,
                        length = length,
                    ))
                }
                return
            }

            // Compute the type of `receiverType.propName` and continue.
            val apparent = try { getApparentType(receiverType) } catch (_: StackOverflowError) { return }
            val prop = getPropertyOfType(apparent, propName) ?: return
            var propType = try { getTypeOfSymbol(prop) } catch (_: StackOverflowError) { return }
            if (propType === errorType) return
            if (isOptionalProperty(prop) && !typeIncludesExplicitUndefined(propType)) {
                propType = getUnionType(listOf(propType, undefinedType))
            }
            path = newPath
            receiverType = if (propType is Type.Union) {
                narrowTypeFromFlowFollowLoopEntry(propType, flow, path, mutableSetOf(), 0)
            } else propType
        }
    }

    /**
     * True when [t] is `undefined` or a Union that explicitly includes `undefined`.
     * Does NOT match `any`/`unknown` — TypeScript doesn't emit TS2532 for those.
     */
    private fun typeIncludesExplicitUndefined(t: Type): Boolean {
        if (t === undefinedType) return true
        if (t.flags.hasAny(TypeFlags.Undefined)) return true
        if (t is Type.Union) return t.types.any { typeIncludesExplicitUndefined(it) }
        return false
    }

    /**
     * True end of a QualifiedName / Identifier chain — `node.end` is unreliable
     * because the parser stores `scanner.getPos()` after `nextToken()` advanced
     * past the next trivia. For accurate squiggle spans, derive end from the
     * rightmost identifier's text.
     */
    private fun qualifiedNameOrIdentifierTrueEnd(node: Node): Int = when (node) {
        is Identifier -> node.pos + node.text.length
        is QualifiedName -> node.right.pos + node.right.text.length
        else -> node.end
    }

    /**
     * Variant of [narrowTypeFromFlow] that follows FlowLoopLabel's
     * `antecedents[0]` (the loop entry) instead of returning declaredType.
     * Used ONLY by the B1.3 TS2532-typeof-chain walker so the existing
     * conservative narrowing in [narrowTypeFromFlow] is unchanged.
     *
     * The loop-entry walk is sound for property-path narrowing under our
     * test corpus because none of the relevant tests reassign the narrowed
     * property inside the loop body. If a future test exposes a back-edge
     * sensitivity, this helper can grow a FlowAssignment-aware widening.
     */
    private fun narrowTypeFromFlowFollowLoopEntry(
        declaredType: Type, flowNode: FlowNode, name: String,
        seen: MutableSet<Int>, depth: Int,
    ): Type {
        if (depth >= NARROW_MAX_DEPTH) return declaredType
        if (!seen.add(flowNode.id)) return declaredType
        return when (flowNode) {
            is FlowStart -> declaredType
            is FlowUnreachable -> neverType
            is FlowCondition -> {
                val antecedent = narrowTypeFromFlowFollowLoopEntry(
                    declaredType, flowNode.antecedent, name, seen, depth + 1,
                )
                applyConditionNarrowing(antecedent, flowNode.expression, flowNode.isTrue, name)
            }
            is FlowBranchLabel -> {
                if (flowNode.antecedents.isEmpty()) return neverType
                val branchTypes = flowNode.antecedents.map {
                    narrowTypeFromFlowFollowLoopEntry(
                        declaredType, it, name,
                        mutableSetOf<Int>().apply { addAll(seen) }, depth + 1,
                    )
                }
                getUnionType(branchTypes)
            }
            is FlowLoopLabel -> {
                // Follow the loop-entry antecedent (index 0). Back-edges are
                // ignored: for property-path narrowing inside a loop body, the
                // narrowed entry type holds at each iteration unless the path
                // is reassigned — and we have no FlowAssignment for property
                // paths in our flow graph today.
                val entry = flowNode.antecedents.firstOrNull() ?: return declaredType
                narrowTypeFromFlowFollowLoopEntry(declaredType, entry, name, seen, depth + 1)
            }
            is FlowAssignment -> {
                val antecedent = narrowTypeFromFlowFollowLoopEntry(
                    declaredType, flowNode.antecedent, name, seen, depth + 1,
                )
                val rhsLiteralType = if (flowAssignmentTargetsName(flowNode.node, name))
                    getLiteralRhsTypeForAssignment(flowNode.node) else null
                if (rhsLiteralType != null) narrowUnionByRhsAssignment(antecedent, rhsLiteralType)
                else antecedent
            }
            is FlowCall -> {
                val antecedent = narrowTypeFromFlowFollowLoopEntry(
                    declaredType, flowNode.antecedent, name, seen, depth + 1,
                )
                // round 43 iter4: assert-function narrowing mirror (see iter3 in
                // narrowTypeFromFlow's FlowCall branch). Loop-entry variant gets
                // the same assert-call narrowing applied after the call returns.
                narrowByAssertCall(antecedent, flowNode.node, name) ?: antecedent
            }
            is FlowSwitchClause -> {
                val antecedent = narrowTypeFromFlowFollowLoopEntry(
                    declaredType, flowNode.antecedent, name, seen, depth + 1,
                )
                // round 43 iter6: mirror iter5's switch-discriminant narrowing into
                // the loop-aware variant.
                narrowBySwitchClause(antecedent, flowNode, name) ?: antecedent
            }
            is FlowArrayMutation -> narrowTypeFromFlowFollowLoopEntry(
                declaredType, flowNode.antecedent, name, seen, depth + 1,
            )
        }
    }

    /**
     * Narrow TS2339 for `namespaceImport.ClassName.prop` chains. When `ns` is a namespace
     * import alias (`import * as ns from "./m"`) and `ClassName` is a locally-declared
     * class in the imported module, verify `prop` exists as a static member of that
     * class; emit TS2339 with `typeof ClassName` display when it doesn't. Bails on
     * heritage chains and on symbols with multiple declarations (merges).
     */
    private fun tryEmitNamespaceMemberTs2339(
        access: PropertyAccessExpression, propName: String,
        diagStart: Int, diagLength: Int, source: String, fileName: String,
    ): Boolean {
        if (propName.isEmpty() || propName in RUNTIME_PROPERTIES) return false
        val nsIdent = access.expression as? Identifier ?: return false
        val nsSym = globals[nsIdent.text] ?: return false
        if (!nsSym.flags.hasAny(SymbolFlags.Alias)) return false
        val resolved = resolveAliasTarget(nsSym) ?: return false
        if (!resolved.flags.hasAny(SymbolFlags.Module)) return false
        val memberName = access.name.text
        val memberSym = resolved.exports?.get(memberName) ?: return false
        if (!memberSym.flags.hasAny(SymbolFlags.Class)) return false
        if (memberSym.declarations.size > 1) return false  // merged — be conservative
        val classDecl = memberSym.declarations.firstOrNull() as? ClassDeclaration ?: return false
        // Heritage complicates static-member lookup; skip.
        val hasExtends = classDecl.heritageClauses?.any {
            it.token == SyntaxKind.ExtendsKeyword
        } == true
        if (hasExtends) return false
        val hasStatic = classDecl.members.any { m ->
            val (mName, modifiers) = when (m) {
                is PropertyDeclaration -> ((m.name as? Identifier)?.text) to m.modifiers
                is MethodDeclaration -> ((m.name as? Identifier)?.text) to m.modifiers
                is GetAccessor -> ((m.name as? Identifier)?.text) to m.modifiers
                is SetAccessor -> ((m.name as? Identifier)?.text) to m.modifiers
                else -> null to null
            }
            if (mName != propName || modifiers == null) false
            else ModifierFlag.Static in modifiers
        }
        if (hasStatic) return false
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type 'typeof $memberName'.",
            category = DiagnosticCategory.Error,
            code = 2339,
            fileName = fileName,
            line = line,
            character = character,
            start = diagStart,
            length = diagLength,
        ))
        return true
    }

    /**
     * 17.22: Narrow TS2339 for `E.A.X` where `E.A` is an enum member access. The enum literal
     * type's apparent value is the underlying primitive (number/string), so anything not present
     * on the Number or String wrapper apparent type is a missing property. Display is `EnumName.MemberName`.
     * Conservative gates: prop must not be empty / in RUNTIME_PROPERTIES, and must be absent from
     * BOTH Number and String wrapper apparent types (we can't always tell numeric vs string enum
     * without computing values, so we accept members of either to avoid FPs).
     */
    private fun tryEmitEnumMemberAccessTs2339(
        enumAccess: PropertyAccessExpression, propName: String,
        diagStart: Int, diagLength: Int, source: String, fileName: String,
    ): Boolean {
        if (propName.isEmpty() || propName in RUNTIME_PROPERTIES) return false
        val enumIdent = enumAccess.expression as? Identifier ?: return false
        val enumSym = currentFileLocals?.get(enumIdent.text) ?: globals[enumIdent.text] ?: return false
        // Require an actual EnumDeclaration: namespaces holding only const enums get
        // SymbolFlags.ConstEnum set via ModuleInstanceState.ConstEnumOnly, so checking
        // the flag alone aliases real `enum E {}` declarations with `namespace M { const enum X {} }`.
        if (enumSym.declarations.none { it is EnumDeclaration }) return false
        val memberName = enumAccess.name.text
        val memberSym = enumSym.exports?.get(memberName) ?: return false
        if (!memberSym.flags.hasAny(SymbolFlags.EnumMember)) return false
        val numHasIt = try { getPropertyOfType(getApparentType(numberType), propName) } catch (_: StackOverflowError) { null }
        if (numHasIt != null) return false
        val strHasIt = try { getPropertyOfType(getApparentType(stringType), propName) } catch (_: StackOverflowError) { null }
        if (strHasIt != null) return false
        val display = "${enumIdent.text}.$memberName"
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$display'.",
            category = DiagnosticCategory.Error,
            code = 2339,
            fileName = fileName,
            line = line,
            character = character,
            start = diagStart,
            length = diagLength,
        ))
        return true
    }

    /**
     * 16.4ed: Narrow TS2339 for `g.prop` where `g: Partial<T>` / `Required<T>` / `Readonly<T>`.
     * These utility types preserve T's property set, so if `prop` isn't a member of T, the
     * access is invalid. Fires only when the inner type resolves to a plain Object/Interface
     * (no base types) with a known property set — keeps FP surface minimal. Display mimics
     * TypeScript: `Partial<Foo>`.
     */
    private fun tryEmitUtilityWrapperTs2339(
        identSymbol: Symbol, propName: String, diagStart: Int, diagLength: Int,
        source: String, fileName: String,
    ) {
        if (propName.isEmpty() || propName in RUNTIME_PROPERTIES) return
        val decl = identSymbol.valueDeclaration as? VariableDeclaration ?: return
        val typeNode = decl.type as? TypeReference ?: return
        val utilName = getTypeReferenceLastName(typeNode.typeName) ?: return
        if (utilName != "Partial" && utilName != "Required" && utilName != "Readonly") return
        val typeArgs = typeNode.typeArguments ?: return
        if (typeArgs.size != 1) return
        val argType = try { getTypeFromTypeNode(typeArgs[0]) } catch (_: StackOverflowError) { return }
        if (argType !is Type.Object || argType === anyType || argType === errorType) return
        if (argType is Type.Interface && !argType.baseTypes.isNullOrEmpty()) return
        try { resolveStructuredTypeMembers(argType) } catch (_: StackOverflowError) { return }
        if (getPropertyOfType(argType, propName) != null) return
        val inner = typeToString(argType)
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$utilName<$inner>'.",
            category = DiagnosticCategory.Error,
            code = 2339,
            fileName = fileName,
            line = line,
            character = character,
            start = diagStart,
            length = diagLength,
        ))
    }

    /**
     * Shared TS2339/TS2551 "property does not exist" check used by both property access
     * (`obj.prop`) and element access with literal key (`obj["prop"]`, `obj[0]`).
     *
     * `emitTs2728RelatedInfo` controls whether to attach the TS2728 "'X' is declared here"
     * related info for spelling suggestions. TypeScript only emits this for property
     * access, not for element access.
     */
    private fun checkMemberAccessMissing(
        objectExprIn: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        enclosingClassType: Type?,
        emitTs2728RelatedInfo: Boolean,
        keySuggestion: String? = null,
        ts2576SquiggleStart: Int = diagStart,
        ts2576SquiggleLength: Int = diagLength,
    ) {
        // 17.57: Skip TS2339 emission when the property name is empty — that's a parser
        // error-recovery placeholder for incomplete syntax like `var p = window.` (TS1003
        // already fires for the missing identifier; emitting TS2339 would be redundant).
        if (propName.isEmpty()) return
        // Unwrap ParenthesizedExpression wrappers so `(new X).blah` / `(x).blah` reach the
        // same branches as their un-parenthesized forms. Parens only affect precedence.
        var objectExpr = objectExprIn
        while (objectExpr is ParenthesizedExpression) objectExpr = objectExpr.expression
        // B8.1: receiver typed as `never` because its annotation is an intersection
        // that reduced to never due to a conflicting private property. Emit TS2339
        // with `never` display + chain. Gate on cache hit so we don't change the
        // emission for receivers that are `never` for OTHER reasons (the existing
        // narrowed-to-never path below handles those for Union receivers).
        run {
            val reductionReason = findIntersectionReductionForExpr(objectExpr) ?: return@run
            val recvType = try { getTypeOfExpression(objectExpr) } catch (_: StackOverflowError) { return@run }
            if (recvType !== neverType) return@run
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type 'never'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
                messageChain = listOf(intersectionReductionChainMessage(reductionReason)),
            ))
            return
        }
        // For the TS2576 "did you mean static member 'A.Y'" message, the suffix depends on
        // the access form — `.y` for property access, `["y"]`/`['y']` for element access.
        // Default to `.propName` if not supplied.
        val suggestionKey: String = keySuggestion ?: ".$propName"
        val ts2576Start = ts2576SquiggleStart
        val ts2576Length = ts2576SquiggleLength
        val isThisAccess = objectExpr is Identifier && objectExpr.text == "this"

        // 17.161: String literal receiver — `"".bogus` / `"foo".missing`. Resolves
        // to the String apparent type and emits TS2339 with the literal value displayed
        // verbatim ("\"\"" / "\"foo\"") when the property isn't a String wrapper member.
        // Used by patterns like `class C extends "".bogus {}` where the heritage
        // expression is a PropertyAccessExpression on a StringLiteralNode receiver.
        if (objectExpr is StringLiteralNode && propName !in RUNTIME_PROPERTIES) {
            val apparent = try { getApparentType(stringType) } catch (_: StackOverflowError) { return }
            if (apparent is Type.Object) {
                try { resolveStructuredTypeMembers(apparent) } catch (_: StackOverflowError) { return }
                val hasProp = try { getPropertyOfType(apparent, propName) } catch (_: StackOverflowError) { return } != null
                if (!hasProp) {
                    val display = "\"" + (objectExpr.text) + "\""
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$display'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                }
            }
            return
        }

        // 17.115: Empty `{}` literal element/property access — emit TS2339 with display
        // `{}`. Squiggle uses the caller-provided ts2576SquiggleStart/Length (which covers
        // the full element-access expression for `{}["X"]` / `{}[N]`); for property-access
        // form `({}).hi` it falls back to the bare `.hi` span. Conservative gate: only
        // empty literals — non-empty literals have their own member set.
        if (objectExpr is ObjectLiteralExpression && objectExpr.properties.isEmpty()) {
            if (propName !in RUNTIME_PROPERTIES) {
                val (line, character) = getLineAndCharacterOfPosition(source, ts2576Start)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '{}'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = ts2576Start, length = ts2576Length,
                ))
            }
            return
        }

        // 16.4cq: `new ClassName(...).prop` or `(new ClassName(...)).prop` — emit TS2339 when
        // the class is declared locally and neither declares the property itself nor inherits
        // a satisfying declaration. Narrow gate: handles the simple "empty class + circular
        // or empty base" pattern. Display uses `ClassName<unknown, unknown, …>` based on the
        // class's type-parameter count, matching TypeScript's format for un-instantiated news.
        if (objectExpr is NewExpression) {
            val ctor = objectExpr.expression
            if (ctor is Identifier) {
                // B15.2: for namespace-nested `new C(...).prop` patterns, look up the
                // ctor symbol via the property-access namespace stack first — the
                // binder puts namespace-internal classes in `namespaceSymbol.exports`,
                // not directly in `globals`. Falls back to `globals` for top-level
                // classes (the original behavior).
                var ctorSym: Symbol? = null
                for (ns in propertyAccessEnclosingNamespaces.asReversed()) {
                    ctorSym = ns.exports?.get(ctor.text)
                    if (ctorSym != null) break
                }
                if (ctorSym == null) ctorSym = globals[ctor.text]
                if (ctorSym != null && ctorSym.flags.hasAny(SymbolFlags.Class)) {
                    // Skip when the class symbol has multiple declarations — interface or
                    // namespace merging (including module augmentation) may contribute
                    // properties that the ClassDeclaration alone doesn't show.
                    if (ctorSym.declarations.size > 1) return
                    val classDecl = ctorSym.declarations.firstOrNull() as? ClassDeclaration
                    if (classDecl != null && propName !in RUNTIME_PROPERTIES) {
                        // Walk own members + extends chain. `false` means the chain
                        // resolves cleanly (no IndexSignature, no ambient base, no
                        // unresolvable extends expression) and the property is
                        // genuinely missing — fire TS2339. `true` means a base
                        // class declares it. `null` means the chain has parts we
                        // can't safely walk (complex extends like `Foo.Bar`,
                        // generic call form, ambient base, IndexSignature) — bail.
                        val chainResult = lookupInstanceMemberInResolvableChain(classDecl, propName)
                        val isCircular = classHasCircularBase(classDecl)
                        val canEmit = chainResult == false || isCircular
                        if (canEmit) {
                            val typeArgs = classDecl.typeParameters?.size ?: 0
                            val display = if (typeArgs > 0) {
                                ctor.text + "<" + List(typeArgs) { "unknown" }.joinToString(", ") + ">"
                            } else ctor.text
                            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$display'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                            ))
                        }
                    }
                }
            }
            return
        }

        // 17.37: CallExpression receiver returning `never` — emit TS2339 'never'.
        // Covers `foo([]).bar` where `foo<T>(x: T[]): T` infers T = never from the
        // empty array literal arg, then `.bar` accesses a property on never.
        // Narrow gate: only fires when the call's resolved return type IS exactly
        // neverType. Calls returning Object/Reference/anyType/etc. still skip — full
        // call-result property checking is out of scope here (no access to the
        // return type's apparent-type member table at this site without broader
        // refactoring).
        if (objectExpr is CallExpression) {
            val callType = try { getReturnTypeOfCallExpression(objectExpr) } catch (_: StackOverflowError) { return }
            if (callType === neverType) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type 'never'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return
            }
            // B64.1: CallExpression receiver returning a primitive (number/string/
            // boolean/bigint) — emit TS2339 when the property is absent from the
            // primitive's apparent (wrapper) type. Display uses the primitive name,
            // not the wrapper. Skip the broad RUNTIME_PROPERTIES filter here — the
            // primitive wrapper interfaces (Number/String/Boolean/BigInt) authoritatively
            // declare which members exist on the primitive; relying on getPropertyOfType
            // against the apparent type gives the correct answer for both directions
            // (`.length` on number → TS2339; `.toString` on number → no error).
            if (callType is Type.Intrinsic &&
                callType.intrinsicName in PRIMITIVE_WRAPPER_INTRINSIC_NAMES
            ) {
                val apparent = try { getApparentType(callType) } catch (_: StackOverflowError) { return }
                if (apparent is Type.Object) {
                    try { resolveStructuredTypeMembers(apparent) } catch (_: StackOverflowError) { return }
                    if (getPropertyOfType(apparent, propName) != null) return
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    // B65.1: route through typeToString so TemplateLiteralType-sourced
                    // intrinsics render their original source text (e.g.
                    // `\`${string}:\t${number}\r\n\``) rather than plain `string`.
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${typeToString(callType)}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
            return
        }

        // === Static method "this" access ===
        // In static methods, "this" refers to the constructor type (typeof C).
        if (isThisAccess && inStaticClassMethod && enclosingClassType is Type.Object) {
            val classSymbol = enclosingClassType.symbol ?: return
            val classDecl = classSymbol.declarations.firstOrNull() as? ClassDeclaration ?: return
            if (isStaticMemberOfClass(classDecl, propName)) return
            if (classSymbol.exports?.containsKey(propName) == true) return
            if (propName in RUNTIME_PROPERTIES) return
            val typeName = "typeof ${classSymbol.name}"
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return
        }

        // 16.0: track a display-override type for primitives whose apparent (wrapper)
        // type is used for property lookup — diagnostic must show the primitive name.
        var displayTypeOverride: Type? = null
        val objectType = if (isThisAccess) {
            if (enclosingClassType == null) return
            enclosingClassType
        } else if (objectExpr is ArrayLiteralExpression) {
            // 16.4: `[1,2,3].NonexistantMethod()` → TS2339 against `number[]`.
            val rawArr = try { getTypeOfArrayLiteral(objectExpr) } catch (_: StackOverflowError) { return }
            if (rawArr === anyType || rawArr === errorType) return
            if (rawArr !is Type.Reference || rawArr.target !== globalArrayType) return
            // Widen literal element types for display: [1,2,3] → number[] (not (1|2|3)[]).
            val args = rawArr.resolvedTypeArguments
            if (!args.isNullOrEmpty()) {
                val widened = args.map { t ->
                    if (t is Type.Union) {
                        val ws = t.types.map { getWidenedLiteralType(it) }.distinct()
                        if (ws.size == 1) ws[0] else getUnionType(ws)
                    } else getWidenedLiteralType(t)
                }
                displayTypeOverride = if (widened == args) rawArr else getOrInternReference(rawArr.target, widened)
            } else {
                displayTypeOverride = rawArr
            }
            rawArr
        } else {
            // Narrow: `ns.Class.prop` — namespace import alias + class in target module's
            // locals + prop is not a static member. Emits TS2339 with `typeof Class` display.
            if (objectExpr is PropertyAccessExpression &&
                objectExpr.expression is Identifier &&
                tryEmitNamespaceMemberTs2339(objectExpr, propName, diagStart, diagLength, source, fileName)) {
                return
            }
            // 17.22: `E.A.prop` — enum-member access then property. Emits TS2339 with `E.A` display
            // when prop is absent from both Number and String wrapper apparent types.
            if (objectExpr is PropertyAccessExpression &&
                objectExpr.expression is Identifier &&
                tryEmitEnumMemberAccessTs2339(objectExpr, propName, diagStart, diagLength, source, fileName)) {
                return
            }
            // Phase 17 / Blocker #1 step 2c: narrowed-to-never on receiver emits
            // TS2339 with 'never' display. Walks the flow graph from the receiver
            // expression's recorded flow node; when narrowing collapses a Union
            // receiver to never via exhaustive typeof/instanceof/equality checks,
            // the property access is invalid. Uses `getTypeOfExpression` so this
            // works for function-local identifiers (parameters, locals) too — not
            // just file-level globals. Gate: only when raw type is a Union (most
            // common narrow-to-never shape; single-type contradictions are rarer
            // and the existing identSymbol-resolution path already handles them).
            //
            // 17.34c: extended to also accept `objectExpr is PropertyAccessExpression`
            // (gated via `getReferencePath(objectExpr) != null` so only pure
            // Identifier-or-PropertyAccess chains qualify; calls/parens/element-access
            // still bail early). The narrowing helpers from 17.34a/b consume
            // dotted-path strings so PropertyAccess receivers narrow uniformly with
            // bare Identifiers. After the narrowing block, the identifier-symbol
            // lookup paths (globals[identName]) only apply to Identifier shapes.
            val narrowingEligible = objectExpr is Identifier ||
                (objectExpr is PropertyAccessExpression && getReferencePath(objectExpr) != null)
            if (!narrowingEligible) return
            try {
                val rawForNarrowing = getTypeOfExpression(objectExpr)
                if (rawForNarrowing is Type.Union) {
                    val narrowed = getNarrowedTypeForReference(rawForNarrowing, objectExpr)
                    if (narrowed === neverType) {
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type 'never'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                    // Phase 17 / Blocker #1 step 2g: multi-member union TS2339 elaboration.
                    // When the narrowed receiver is still a Union with at least one member
                    // missing the property AND at least one member having it (partial
                    // coverage), emit TS2339 with the union display + a chain line naming
                    // the first missing member. Mirrors TypeScript's baseline format.
                    //
                    // 17.7b: gate widened from "all missing are primitives" to "any missing
                    // member" once 17.7a discriminant-property narrowing landed — the prior
                    // restriction existed only because un-narrowed discriminated unions
                    // (e.g. `partiallyDiscriminantedUnions_ts`'s `if (ab.type === 'a') if
                    // (ab.subtype === 2) ab.foo`) would FP. With discriminant narrowing in
                    // place, the union collapses to the right member and this branch is
                    // skipped (single Type.Object, not Union). Only patterns that genuinely
                    // shouldn't narrow (e.g. `controlFlowAliasing_ts`'s `const isFoo =
                    // obj.kind === 'foo'; if (isFoo) obj.foo` — TypeScript doesn't track
                    // aliased conditions for narrowing) reach this elaboration with a
                    // partial-coverage Union.
                    if (narrowed is Type.Union && propName.isNotEmpty() && propName !in RUNTIME_PROPERTIES) {
                        val members = narrowed.types
                        fun memberHasIt(m: Type): Boolean {
                            if (m === anyType || m === errorType || m === unknownType) return true
                            return try { typeHasOwnProperty(getApparentType(m), propName) } catch (_: StackOverflowError) { true }
                        }
                        val missingMembers = members.filter { !memberHasIt(it) }
                        val anyHasIt = members.any { memberHasIt(it) }
                        if (missingMembers.isNotEmpty() && anyHasIt) {
                            val missingMember = missingMembers.first()
                            val unionDisplay = typeToString(narrowed)
                            val memberDisplay = typeToString(missingMember)
                            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$unionDisplay'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                                messageChain = listOf("  Property '$propName' does not exist on type '$memberDisplay'."),
                            ))
                            return
                        }
                    }
                    // Phase 17 / Blocker #1 step 2h (17.7c/17.7d): narrowed-to-single-Object
                    // emission. When discriminant/typeof/instanceof narrowing collapses a Union
                    // to a single Type.Object — anonymous (`{ kind: 'a', a: string }`) or named
                    // interface without base types — accessing a property missing on that single
                    // member fires TS2339. Conservative gates:
                    //   - `narrowed` must be a Type.Object that is NOT a Type.Reference
                    //     (generic instantiation — `resolveGenericPropertyType` interaction
                    //     not handled here).
                    //   - For Type.Interface variants: skip if base types are non-empty
                    //     (mirrors the line ~40300 skip — incomplete inheritance resolution).
                    //     17.7d widening: allow Type.Interface with empty/null baseTypes (the
                    //     standard discriminated-union case `interface A { kind:'a'; aProps:string }`).
                    //   - Narrowing must have ACTUALLY changed the type (`narrowed !== rawForNarrowing`);
                    //   - `propName` must not be empty or a RUNTIME_PROPERTIES member;
                    //   - the property must not exist on the narrowed type.
                    // Display uses the narrowed type's string form (NOT the un-narrowed union),
                    // matching TypeScript's baseline format for narrowed property access.
                    if (narrowed is Type.Object && narrowed !is Type.Reference &&
                        narrowed !== rawForNarrowing && propName.isNotEmpty() && propName !in RUNTIME_PROPERTIES
                    ) {
                        val skipForBaseTypes = narrowed is Type.Interface &&
                            narrowed.baseTypes != null && narrowed.baseTypes!!.isNotEmpty()
                        if (!skipForBaseTypes) {
                            try {
                                resolveStructuredTypeMembers(narrowed)
                                if (getPropertyOfType(narrowed, propName) == null) {
                                    val narrowedDisplay = typeToString(narrowed)
                                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                                    diagnostics.add(Diagnostic(
                                        message = "Property '$propName' does not exist on type '$narrowedDisplay'.",
                                        category = DiagnosticCategory.Error, code = 2339,
                                        fileName = fileName, line = line, character = character,
                                        start = diagStart, length = diagLength,
                                    ))
                                    return
                                }
                            } catch (_: StackOverflowError) { /* fall through to normal check */ }
                        }
                    }
                }
            } catch (_: StackOverflowError) { /* fall through to normal check */ }

            // 17.34c: paths beyond this point assume an Identifier receiver (look up
            // the bare name in globals to drive namespace/typeof/wrapper-type emissions).
            // PropertyAccess receivers exit here — the narrowing block above already
            // covered the narrowed-to-never / single-Object / Union-with-missing cases;
            // the remaining identifier-symbol lookup paths don't generalize to
            // dotted-path receivers (no `globals["A._a"]` lookup makes sense).
            if (objectExpr !is Identifier) {
                // 17.130: `ClassIdent.prototype.X` — `Class.prototype` doesn't resolve to
                // the class's instance type in our checker (no `prototype` member on the
                // static side), so the receiver type is anyType and the standard checks bail.
                // Detect the syntactic shape and route to `tryEmitClassInstanceMissingTs2339`
                // with the class symbol's declared instance type so missing-property emission
                // fires on `A.prototype.foo` when `foo` isn't on A's instance shape.
                if (objectExpr is PropertyAccessExpression &&
                    objectExpr.name.text == "prototype" &&
                    objectExpr.expression is Identifier
                ) {
                    val classIdent = objectExpr.expression as Identifier
                    val rawSym = currentFileLocals?.get(classIdent.text) ?: globals[classIdent.text]
                    val classSym = rawSym?.let {
                        if (it.flags.hasAny(SymbolFlags.Alias)) resolveAliasTarget(it) else it
                    }
                    if (classSym != null && classSym.flags.hasAny(SymbolFlags.Class)) {
                        try {
                            val classType = getDeclaredTypeOfSymbol(classSym)
                            if (classType is Type.Interface) {
                                tryEmitClassInstanceMissingTs2339(classSym, classType, propName, objectExpr, diagStart, diagLength, source, fileName)
                            }
                        } catch (_: StackOverflowError) { /* fall through */ }
                    }
                }
                return
            }
            val identName = objectExpr.text
            // B69.12: enclosing-namespace local-var shadow. When `M.X` is accessed
            // inside `namespace M2 { var M = 0; ... M.X }` (and there's an outer
            // `namespace M { export class X {} }`), the `var M` shadows the outer
            // namespace within M2's body. Walk the namespace stack innermost-first
            // looking for a Variable symbol (not also Module) that shadows.
            var enclosingNsShadow: Symbol? = null
            for (ns in propertyAccessEnclosingNamespaces.asReversed()) {
                val sym = ns.exports?.get(identName) ?: continue
                if (sym.flags.hasAny(SymbolFlags.Variable) &&
                    !sym.flags.hasAny(SymbolFlags.Module or SymbolFlags.Class)) {
                    enclosingNsShadow = sym
                    break
                }
            }
            val identSymbol = enclosingNsShadow ?: globals[identName]

            if (identSymbol != null) {
                // 17.194: TS2339 for `A.foo()` where A is a top-level class and
                // `foo` is an instance method (not static). Display uses `typeof
                // ClassName`. Conservative gate: identifier resolves to a Class
                // symbol with EXACTLY ONE declaration that is a ClassDeclaration
                // (no merge with namespace/var/function), valueDeclaration is
                // also that ClassDeclaration (rules out cross-file leaks where
                // the symbol is mostly a variable but flagged Class), no extends
                // (heritage complicates static-member lookup), `foo` isn't a
                // static member, isn't in RUNTIME_PROPERTIES, and isn't an
                // exported namespace member. Also gated on PropertyAccessExpression
                // shape (keySuggestion null or starts with `.`) — element access
                // `C[1]` is NOT diagnosable here (could be reading a static).
                val isPropertyAccessShape = keySuggestion == null || keySuggestion.startsWith(".")
                if (isPropertyAccessShape &&
                    identSymbol.flags.hasAny(SymbolFlags.Class) &&
                    !identSymbol.flags.hasAny(SymbolFlags.Module or SymbolFlags.Alias or SymbolFlags.Variable or SymbolFlags.Function) &&
                    identSymbol.declarations.size == 1 &&
                    propName !in RUNTIME_PROPERTIES &&
                    propName.isNotEmpty() && propName[0] !in '0'..'9') {
                    val classDecl = identSymbol.declarations.firstOrNull() as? ClassDeclaration
                    val isPureClass = classDecl != null && identSymbol.valueDeclaration === classDecl
                    val hasExtends = classDecl?.heritageClauses?.any {
                        it.token == SyntaxKind.ExtendsKeyword
                    } == true
                    if (isPureClass && !hasExtends && !isStaticMemberOfClass(classDecl!!, propName)) {
                        if (identSymbol.exports?.containsKey(propName) != true) {
                            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type 'typeof $identName'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                            ))
                            return
                        }
                    }
                }
                // === Namespace/Module property access ===
                // Skip import aliases — can't reliably resolve imported module exports
                if (identSymbol.flags.hasAny(SymbolFlags.Alias)) return
                if (identSymbol.flags.hasAny(SymbolFlags.Module) && !identSymbol.flags.hasAny(SymbolFlags.Class) &&
                    !identSymbol.flags.hasAny(SymbolFlags.Variable)) {
                    // B63.34: Skip the namespace path when the symbol ALSO carries Variable
                    // flag — typically caused by `mergeSymbolTable` polluting an unrelated
                    // module symbol with a same-named `let`/`const` declaration. In that
                    // case, the variable's type annotation should drive property lookup
                    // (falls through to the `getTypeOfSymbol(identSymbol)` branch below).
                    val exports = identSymbol.exports
                    if (exports != null) {
                        if (isNameExportedFromNamespace(identSymbol, propName)) return
                        // Enum members are always accessible on the enum type
                        if (identSymbol.flags.hasAny(SymbolFlags.Enum) && exports.containsKey(propName)) return
                        if (propName in RUNTIME_PROPERTIES) return
                        val typeName = "typeof $identName"
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '$typeName'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                    return
                }

                // B95e (round 82): enum-receiver missing member, e.g. `U8.bit_2` where the
                // enum U8 (RegularEnum, no Module flag → not handled above) has member BIT_2.
                // TS2551 "Property 'bit_2' does not exist on type 'typeof U8'. Did you mean
                // 'BIT_2'?" + related TS2728 at the member declaration. Falls to plain TS2339
                // when no close spelling match. Gated on a pure Enum symbol whose exports hold
                // the members (always — the receiver here is already an Identifier).
                run {
                    val enumExports = identSymbol.exports
                    // Only PROPERTY access `E.foo` (isPropertyAccessShape) — NOT element access
                    // `E[0]` (numeric enum reverse-mapping `E[0]` is valid) nor `E["x"]`. Also
                    // skip an all-numeric propName defensively (reverse mapping).
                    val isNumericProp = propName.isNotEmpty() && propName.all { it in '0'..'9' }
                    if (identSymbol.flags.hasAny(SymbolFlags.Enum)
                        && !identSymbol.flags.hasAny(SymbolFlags.Module)
                        && enumExports != null
                        && isPropertyAccessShape
                        && !isNumericProp
                    ) {
                        if (enumExports.containsKey(propName) || propName in RUNTIME_PROPERTIES) return
                        val typeName = "typeof $identName"
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        val suggestion = getSpellingSuggestionFromNames(propName, enumExports.keys)
                        if (suggestion != null) {
                            val memberDecl = enumExports[suggestion]?.declarations?.firstOrNull() as? EnumMember
                            val related = memberDecl?.let { md ->
                                val nm = md.name
                                val namePos = nm.pos
                                val nameLen = (nm as? Identifier)?.text?.length ?: (nm.end - nm.pos).coerceAtLeast(1)
                                val (rl, rc) = getLineAndCharacterOfPosition(source, namePos)
                                listOf(Diagnostic(
                                    message = "'$suggestion' is declared here.",
                                    category = DiagnosticCategory.Message, code = 2728,
                                    fileName = fileName, line = rl, character = rc,
                                    start = namePos, length = nameLen,
                                ))
                            } ?: emptyList()
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
                                category = DiagnosticCategory.Error, code = 2551,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                                relatedInformation = related,
                            ))
                        } else {
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$typeName'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                            ))
                        }
                        return
                    }
                }

                val rawType = getTypeOfSymbol(identSymbol)
                if (rawType === anyType || rawType === errorType || rawType === unknownType) {
                    tryEmitUtilityWrapperTs2339(identSymbol, propName, diagStart, diagLength, source, fileName)
                    return
                }
                // For primitive types (e.g. `declare var foo: number`), resolve to the
                // wrapper interface's apparent type so property lookups fire TS2339 when
                // the property doesn't exist on the wrapper. Display uses the primitive name.
                // Narrow gate: only fire for file-level Variable declarations with an
                // explicit type annotation — avoids FPs on function params/destructured
                // bindings whose inferred types may be stale primitives.
                // B69.11: also accept top-level (parent == null) literal-initialized vars
                // (`var x = 5;` / `var s = "y";` / `var b = true|false;`). Skip when the
                // name is locally shadowed via `currentLocalTypes` (function/arrow scope) —
                // detected by comparing the local type to the file-level symbol type: if
                // they differ (after literal widening), an inner scope shadows the file
                // var and the gate must not fire.
                // B69.12: namespace-local-var shadow case (enclosingNsShadow != null) is
                // also literal-init eligible — bypass the parent==null check because
                // namespace-internal vars have a parent. localShadow is irrelevant here
                // (currentLocalTypes doesn't carry namespace-internal vars).
                val exprType = if (rawType !is Type.Object) {
                    val decl = identSymbol.valueDeclaration
                    val annotated = decl is VariableDeclaration && decl.type != null
                    val isNsShadow = enclosingNsShadow != null
                    val localShadow = !isNsShadow && currentLocalTypes[identName]?.let {
                        it !== rawType && it !== getWidenedLiteralType(rawType)
                    } == true
                    val literalInferred = !annotated && decl is VariableDeclaration &&
                        (isNsShadow || identSymbol.parent == null) &&
                        identSymbol.declarations.size == 1 &&
                        !localShadow && when (val init = decl.initializer) {
                            is NumericLiteralNode -> true
                            is StringLiteralNode -> true
                            is Identifier -> init.text == "true" || init.text == "false"
                            else -> false
                        }
                    // B83.4i: also accept a `CallExpression`-initialized var whose
                    // resolved type is a concrete primitive intrinsic. `getTypeOfSymbol`
                    // (above) already resolved the call's return type — when it lands on
                    // a non-Object primitive (number/string/boolean/etc., NOT any/error/
                    // unknown, filtered above), property access on it is checkable via the
                    // wrapper apparent type, exactly like a literal-initialized var. Gate
                    // mirrors `literalInferred` (top-level OR namespace-shadow, single
                    // declaration, not locally shadowed) so it only fires for the same
                    // narrow file-level var population. Unblocks `var n = arr.map(...)
                    // .reduce(...); n.bogus` → TS2339 (genericReduce). Skipped when the
                    // call's return type is a Type.Object (handled by the else branch).
                    // Exclude when the name is bound by an enclosing function/method
                    // parameter (including destructured patterns like `[x]` / `{x}`) —
                    // there the identifier refers to the param, not the file-level var,
                    // so the file-var's call-inferred type must NOT drive TS2339. This is
                    // the `function foo([x]: {a}[]){ return x.a }` + `var x = foo(...)`
                    // shadow case (functionOverloads43). The `localShadow` check above
                    // misses destructured params because they aren't in `currentLocalTypes`;
                    // `currentParamBindingNames` tracks destructured-param binding names
                    // for exactly this purpose (populated in populateParameterLocalTypes).
                    val shadowedByParam = identName in currentParamBindingNames
                    val callInferred = !annotated && !literalInferred && !shadowedByParam &&
                        decl is VariableDeclaration &&
                        (isNsShadow || identSymbol.parent == null) &&
                        identSymbol.declarations.size == 1 &&
                        !localShadow && decl.initializer is CallExpression
                    if ((!annotated && !literalInferred && !callInferred) || !identSymbol.flags.hasAny(SymbolFlags.Variable)) return
                    if (propName.isEmpty()) return
                    displayTypeOverride = if (literalInferred) getWidenedLiteralType(rawType) else rawType
                    getApparentType(rawType)
                } else rawType
                if (exprType !is Type.Object) return
                // For variables, skip class-typed access (may be narrowed via instanceof).
                // Anonymous object types (typeSym == null) ARE checkable — e.g.
                // `declare var x: { a: string }; x.missing` → TS2339.
                if (identSymbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
                    val typeSym = exprType.symbol
                    if (typeSym != null && typeSym.flags.hasAny(SymbolFlags.Class)) {
                        // Instance-side class type (Type.Interface) — the narrowing concern
                        // applies: the variable may be narrowed by `instanceof`, so bail.
                        // Constructor-side `typeof K` (Type.Object with Class symbol) carries
                        // the static members as properties and falls through to normal
                        // property-missing checks (TS2339) below.
                        if (exprType is Type.Interface) {
                            if (tryEmitStaticAccessTs2576(typeSym, propName, ts2576Start, ts2576Length, suggestionKey, source, fileName, exprType)) return
                            tryEmitClassInstanceMissingTs2339(typeSym, rawType, propName, objectExpr, diagStart, diagLength, source, fileName)
                            return
                        }
                    }
                }
                exprType
            } else {
                // Fallback: try resolving from currentLocalTypes (function params, local vars)
                val rawType = getTypeOfIdentifier(objectExpr)
                if (rawType === anyType || rawType === errorType || rawType === unknownType) return
                // 16.0: For primitive types, use the apparent (wrapper) type so that
                // e.g. `s: string` can detect `s.hmm` as TS2339 via the String wrapper.
                val exprType = if (rawType !is Type.Object) {
                    displayTypeOverride = rawType
                    getApparentType(rawType)
                } else rawType
                if (exprType !is Type.Object) return
                // For local variables, skip class-typed (may be narrowed) — same
                // instance-side-only gate as the globals branch above.
                val typeSym = exprType.symbol
                if (typeSym != null && typeSym.flags.hasAny(SymbolFlags.Class)) {
                    if (exprType is Type.Interface) {
                        if (tryEmitStaticAccessTs2576(typeSym, propName, ts2576Start, ts2576Length, suggestionKey, source, fileName, exprType)) return
                        tryEmitClassInstanceMissingTs2339(typeSym, rawType, propName, objectExpr, diagStart, diagLength, source, fileName)
                        return
                    }
                }
                // Skip malformed types (e.g., unresolved mapped types with empty property names)
                resolveStructuredTypeMembers(exprType)
                if (exprType.properties != null && exprType.properties!!.any { it.name.isEmpty() }) return
                exprType
            }
        }
        // Check Interface and Object types (anonymous object literals, type literals, etc.)
        if (objectType !is Type.Object) return
        // Skip enum types
        if (objectType.symbol?.flags?.hasAny(SymbolFlags.Enum) == true) return
        // Resolve members
        resolveStructuredTypeMembers(objectType)
        if (objectType.properties.isNullOrEmpty()) {
            // B63.33: empty `{}` Type.Object — receiver typed as truly-empty (e.g.
            // `const z = {}; z.x` or `function f(): {} {} f().x`). Conservative gate:
            // no symbol, no signatures, no index sigs, no base types (if Interface).
            // Display: '{}'. Mirrors the existing ObjectLiteralExpression-direct path
            // (17.115) but covers the Identifier-receiver case where the type was
            // INFERRED from an empty initializer.
            if (objectType.symbol == null &&
                objectType.callSignatures.isNullOrEmpty() &&
                objectType.constructSignatures.isNullOrEmpty() &&
                objectType.stringIndexInfo == null &&
                objectType.numberIndexInfo == null &&
                (objectType !is Type.Interface || objectType.baseTypes.isNullOrEmpty()) &&
                propName !in RUNTIME_PROPERTIES &&
                propName.isNotEmpty()) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '{}'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return
            }
            // Constructor-side class receiver (typeof K) may have no cached properties (the
            // binder may not have populated exports), but we can still check the class
            // declaration for the static-member presence and emit a precise TS2339 when
            // the property isn't a static of the class.
            val ctorClassSym = objectType.symbol
            if (ctorClassSym != null && ctorClassSym.flags.hasAny(SymbolFlags.Class)) {
                val classDecl = ctorClassSym.declarations.firstOrNull() as? ClassDeclaration
                if (classDecl != null && propName !in RUNTIME_PROPERTIES) {
                    if (isStaticMemberOfClass(classDecl, propName)) return
                    if (objectType !is Type.Interface) {
                        // Constructor side (`typeof C`): static-member check above already
                        // rejected static hits. The class shape is the static side, which
                        // is built once and not subject to "inherited static" cache misses,
                        // so emit unconditionally.
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type 'typeof ${ctorClassSym.name}'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                    // Instance side (Type.Interface) with empty/missing properties: only
                    // fire for `this`-access where we know we're authoritatively on the
                    // instance side of the enclosing class. Other Type.Interface receivers
                    // (variable references, class-Identifier-as-value like `C[1]` whose
                    // `getTypeOfSymbol` mis-resolves to the declared instance type) have
                    // their own dedicated handlers (`tryEmitClassInstanceMissingTs2339`,
                    // `NewExpression` branch above) — calling here would FP-fire on
                    // value-position class references. Display: bare `C`, not `typeof C`.
                    if (!isThisAccess) return
                    val chainResult = lookupInstanceMemberInResolvableChain(classDecl, propName)
                    if (chainResult != false) return
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${ctorClassSym.name}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
            return
        }
        // B15.1: TS2339 for `this.X` where X is genuinely missing across the entire
        // resolvable instance-side inheritance chain. The general "skip class with
        // base types" guard below is conservative — for `this` access we know the
        // receiver IS the enclosing class instance, and `lookupInstanceMemberInResolvableChain`
        // safely returns `false` only when every base is resolvable as a ClassDeclaration
        // (no `Foo.Bar` base, no ambient `declare class`, no IndexSignature, no sibling
        // InterfaceDeclaration) and no member matches anywhere in the chain. Display
        // mirrors TypeScript's format: `ClassName<A, B, C>` for generic classes.
        if (isThisAccess && objectType is Type.Interface
            && objectType.baseTypes != null && objectType.baseTypes!!.isNotEmpty()
            && propName !in RUNTIME_PROPERTIES
        ) {
            val classDecl = objectType.symbol?.declarations?.firstOrNull() as? ClassDeclaration
            if (classDecl != null && lookupInstanceMemberInResolvableChain(classDecl, propName) == false
                && !isStaticMemberOfClass(classDecl, propName)
            ) {
                val baseName = classDecl.name?.text ?: objectType.symbol?.name
                if (baseName != null) {
                    val tps = classDecl.typeParameters
                    val className = if (!tps.isNullOrEmpty())
                        "$baseName<${tps.joinToString(", ") { it.name.text }}>"
                    else baseName
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$className'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
        }
        // Skip if class/interface has base types — incomplete inheritance resolution causes FPs.
        // Also applies to generic references whose target is an Interface with base types
        // (e.g. `c: IC<number>` where IC extends IA<T>, IB<T> — inherited members on the
        // Reference are populated via instantiation, but cache misses or ordering quirks
        // can leave one base's members unresolved, producing TS2339 for properties that
        // structurally exist).
        if (objectType is Type.Interface && objectType.baseTypes != null && objectType.baseTypes!!.isNotEmpty()) return
        if (objectType is Type.Reference) {
            val tgt = objectType.target
            if (tgt.baseTypes != null && tgt.baseTypes!!.isNotEmpty()) return
        }
        // Skip well-known runtime properties (FP-prevention for class instances and
        // structural types where we may not have full member info). For primitive
        // types resolved through apparent type (displayTypeOverride != null), we DO
        // have authoritative member info from the wrapper interface — only allow the
        // RUNTIME_PROPERTIES exemption when the member actually exists on the
        // apparent type. This makes `s: string; s.length` pass (length is on String)
        // while `n: number; n.length` fires TS2339 (length is not on Number).
        if (propName in RUNTIME_PROPERTIES) {
            if (displayTypeOverride == null) return
            if (getPropertyOfType(objectType, propName) != null) return
        }
        // Check if property exists in type members
        val prop = getPropertyOfType(objectType, propName)
        if (prop != null) {
            // TS2576: `this.X` in an instance method where X is a STATIC member of the
            // enclosing class. `resolveInterfaceMembers` stores statics and instance
            // members in the same table, so we need to re-check the declaration modifier
            // on the resolved symbol to distinguish.
            if (isThisAccess && !inStaticClassMethod) {
                val classDecl = objectType.symbol?.declarations?.firstOrNull() as? ClassDeclaration
                if (classDecl != null
                    && isStaticMemberOfClass(classDecl, propName)
                    && !hasInstanceMemberNamed(classDecl, propName)
                ) {
                    val baseName = classDecl.name?.text ?: objectType.symbol?.name
                    if (baseName != null) {
                        val tps = classDecl.typeParameters
                        val className = if (!tps.isNullOrEmpty())
                            "$baseName<${tps.joinToString(", ") { it.name.text }}>"
                        else baseName
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '$className'. Did you mean to access the static member '$className.$propName' instead?",
                            category = DiagnosticCategory.Error, code = 2576,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                }
            }
            return
        }
        // Check namespace exports (for merged class+namespace symbols like `Observable.someValue`)
        val sym = objectType.symbol
        if (sym != null && sym.flags.hasAny(SymbolFlags.Module) && sym.exports?.containsKey(propName) == true) return
        // Check index signatures. For primitive apparent-type checks (16.0),
        // a number-index only matches numeric-looking names (so `s.hmm` on string
        // reports TS2339). For other paths, keep the permissive check since
        // many static-side accesses (e.g. Array.isArray) rely on it to avoid FPs.
        if (objectType.stringIndexInfo != null) return
        if (objectType.numberIndexInfo != null) {
            if (displayTypeOverride == null || propName.toDoubleOrNull() != null) return
        }
        // Try spelling suggestion from known properties
        val memberNames = (objectType.properties ?: emptyList()).map { it.name }.toSet()
        val suggestion = getSpellingSuggestionFromNames(propName, memberNames)
        // For static access on class/namespace identifiers, use "typeof X" format
        val rawTypeName = typeToString(displayTypeOverride ?: objectType)
        val typeName = if (!isThisAccess && objectType.symbol?.flags?.hasAny(SymbolFlags.Class) == true) {
            "typeof $rawTypeName"
        } else {
            rawTypeName
        }
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        if (suggestion != null) {
            // Find the declaration of the suggested property for TS2728 related info
            val suggestedProp = objectType.properties?.find { it.name == suggestion }
            val relatedInfo = if (emitTs2728RelatedInfo && suggestedProp != null) {
                val decl = suggestedProp.valueDeclaration ?: suggestedProp.declarations.firstOrNull()
                if (decl != null) {
                    val declPos = when (decl) {
                        is PropertyDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is MethodDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is Parameter -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        else -> decl.pos
                    }
                    val declLength = suggestion.length
                    val (declFile, declSource) = resolveDeclarationSourceFile(declPos)
                    val resolvedFile = declFile ?: fileName
                    val resolvedSource = declSource ?: source
                    val isLib = isLibFileName(resolvedFile)
                    val (declLine, declChar) = if (isLib) {
                        Pair(null as Int?, null as Int?)
                    } else {
                        val p = getLineAndCharacterOfPosition(resolvedSource, declPos)
                        Pair(p.first, p.second)
                    }
                    // TypeScript's deprecated HTML helper methods on String (sub, sup, big,
                    // small, bold, italics, etc.) are declared in lib.es5.d.ts.deprecated.d.ts,
                    // but TS error baselines render them as lib.es2015.core.d.ts. Override
                    // the file name for these specific suggestions to match baseline format.
                    val baselineFile = if (isLib && suggestion in DEPRECATED_STRING_HTML_HELPERS)
                        "lib.es2015.core.d.ts" else resolvedFile
                    listOf(Diagnostic(
                        message = "'$suggestion' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = baselineFile,
                        line = declLine,
                        character = declChar,
                        start = declPos,
                        length = declLength,
                    ))
                } else emptyList()
            } else emptyList()
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
                category = DiagnosticCategory.Error,
                code = 2551,
                fileName = fileName,
                line = line,
                character = character,
                start = diagStart,
                length = diagLength,
                relatedInformation = relatedInfo,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'.",
                category = DiagnosticCategory.Error,
                code = 2339,
                fileName = fileName,
                line = line,
                character = character,
                start = diagStart,
                length = diagLength,
            ))
        }
    }

    /**
     * Element access with literal key: `obj["prop"]` or `obj[0]`.
     * Mirrors `checkSinglePropertyAccess` for the TS2339/TS2551 diagnostic, but only
     * when the argument expression is a string or numeric literal (so the key is known
     * at check time). Runtime index expressions fall through to normal index-signature
     * resolution elsewhere.
     */
    private fun checkSingleElementAccess(
        expr: ElementAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        val arg = expr.argumentExpression
        // 17.93: TS2538 "Type 'null'/'undefined' cannot be used as an index type." for
        // element-access indices that resolve to null/undefined. Mirrors TypeScript's
        // checker: this fires independent of strictNullChecks because it's a constant
        // index whose type is exactly null/undefined (not a widened "any" path).
        if (arg is Identifier && (arg.text == "null" || arg.text == "undefined")) {
            val argType = getTypeOfIdentifier(arg)
            if (argType === nullType || argType === undefinedType) {
                val display = if (argType === nullType) "null" else "undefined"
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$display' cannot be used as an index type.",
                    category = DiagnosticCategory.Error,
                    code = 2538,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = arg.pos,
                    length = arg.text.length,
                ))
                return
            }
        }
        // 17.178: TS2538 — array-typed index. `arr2[arr1[0]]` where `arr1` is
        // `(string | string[])[]` makes the indexer `string | string[]`, and
        // the `string[]` constituent is invalid as an index. TypeScript reports
        // the FIRST invalid constituent. Conservative gate: only fire when the
        // arg is an ElementAccessExpression (the targeted shape) whose computed
        // type is a Union with at least one Array `Type.Reference` constituent.
        // Squiggle covers the full arg expression via expressionTrueEnd.
        if (arg is ElementAccessExpression) {
            val argType = try { getTypeOfExpression(arg) } catch (_: StackOverflowError) { null }
            if (argType is Type.Union) {
                val arrayConstituent = argType.types.firstOrNull { t ->
                    t is Type.Reference && t.target.symbol?.name == "Array"
                }
                if (arrayConstituent != null) {
                    val display = typeToString(arrayConstituent)
                    val argEnd = expressionTrueEnd(arg)
                    val length = (argEnd - arg.pos).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$display' cannot be used as an index type.",
                        category = DiagnosticCategory.Error,
                        code = 2538,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = arg.pos,
                        length = length,
                    ))
                    return
                }
            }
        }
        // 17.220: TS2538 — class-instance-typed index via comma expression. Targets the
        // `new Foo[a, b, c]` syntax artifact (parsed as `new (Foo[<comma-expr>])`),
        // where the rightmost operand is `new ClassName(...)`. Narrow gate: arg is a
        // comma BinaryExpression whose rightmost operand is a NewExpression on a
        // class identifier. Type display uses the class identifier text directly
        // (avoids `getReturnTypeOfNewExpression`'s base-class-return-type quirk
        // for derived classes). Squiggle covers full arg span.
        if (arg is BinaryExpression && arg.operator == SyntaxKind.Comma) {
            var rightmost: Expression = arg
            while (rightmost is BinaryExpression && rightmost.operator == SyntaxKind.Comma) {
                rightmost = rightmost.right
            }
            val rightmostNew = rightmost as? NewExpression
            val ctorIdent = rightmostNew?.expression as? Identifier
            val ctorSym = ctorIdent?.let { globals[it.text] }
            val isClass = ctorSym?.declarations?.any { it is ClassDeclaration } == true
            if (ctorIdent != null && isClass) {
                val argEnd = expressionTrueEnd(arg)
                val length = (argEnd - arg.pos).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '${ctorIdent.text}' cannot be used as an index type.",
                    category = DiagnosticCategory.Error,
                    code = 2538,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = arg.pos,
                    length = length,
                ))
                return
            }
        }
        // 17.116: TS7053 "Element implicitly has an 'any' type because expression of
        // type 'any' can't be used to index type 'X'." Fires when the key expression
        // resolves to `any` AND the receiver is an empty `{}`-typed value (Type.Object
        // with no members and no index signatures). Gated on noImplicitAny/strict.
        // Squiggle covers full `receiver[key]` expression. Must run BEFORE the `when (arg)`
        // block which returns for non-literal keys.
        if (arg is Identifier && (options.noImplicitAny || options.strict)) {
            val argType = try { getTypeOfIdentifier(arg) } catch (_: StackOverflowError) { null }
            // B70.2: accept both `any` and `string` as the index expression's type.
            // For-in loop variables (typed as `string` via the ForInStatement walker)
            // also trigger TS7053 with `'string'` in the message — TypeScript's rule
            // is "no index signature with a parameter of type 'string'" applies
            // regardless of whether the source is `any` or `string`.
            val argDisplay = when {
                argType === anyType -> "any"
                argType === stringType -> "string"
                else -> null
            }
            if (argDisplay != null) {
                val recvType = try { getTypeOfExpression(expr.expression) } catch (_: StackOverflowError) { null }
                if (recvType is Type.Object && recvType !is Type.Reference && recvType !is Type.Interface) {
                    try { resolveStructuredTypeMembers(recvType) } catch (_: StackOverflowError) { /* fall-through */ }
                    val noProps = recvType.properties.isNullOrEmpty()
                    val noIndex = recvType.stringIndexInfo == null && recvType.numberIndexInfo == null
                    val noCalls = recvType.callSignatures.isNullOrEmpty() && recvType.constructSignatures.isNullOrEmpty()
                    if (noProps && noIndex && noCalls) {
                        val recvStart = expr.expression.pos
                        var closeBracket = arg.pos + arg.text.length
                        while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
                        val end = if (closeBracket < source.length) closeBracket + 1 else expr.end
                        val length = (end - recvStart).coerceAtLeast(1)
                        val recvDisplay = typeToString(recvType)
                        val (line, character) = getLineAndCharacterOfPosition(source, recvStart)
                        val chain = if (argDisplay == "string") listOf(
                            "  No index signature with a parameter of type 'string' was found on type '$recvDisplay'.",
                        ) else emptyList()
                        diagnostics.add(Diagnostic(
                            message = "Element implicitly has an 'any' type because expression of type '$argDisplay' can't be used to index type '$recvDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 7053,
                            messageChain = chain,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = recvStart,
                            length = length,
                        ))
                        return
                    }
                }
            }
        }
        val propName: String
        val diagStart: Int
        val diagLength: Int
        // Squiggle covers the whole `receiver[key]` expression (TS2576 convention).
        // For TS2339/TS2551 element access, `propName` is set but the squiggle length
        // we pass stays narrow (key+brackets) to match existing element-access behavior.
        when (arg) {
            is StringLiteralNode -> {
                propName = arg.text
                diagStart = arg.pos
                diagLength = (arg.rawText?.length ?: arg.text.length) + 2
            }
            is NumericLiteralNode -> {
                propName = arg.text
                diagStart = arg.pos
                diagLength = arg.text.length
            }
            else -> return
        }
        // 17.116: TS7015 "Element implicitly has an 'any' type because index expression
        // is not of type 'number'." Fires when a StringLiteral key accesses an enum-typed
        // identifier AND the key isn't a known enum member name AND the key isn't a
        // numeric-looking string. Enums have implicit number-index sigs (member name
        // string -> number for forward, number -> name for reverse); a non-numeric string
        // key bypasses both. Gated on noImplicitAny/strict.
        //
        // 17.162: When NOT in strict mode, the same shape (enum + non-numeric string key
        // not matching a known member) emits TS2339 "Property 'X' does not exist on
        // type 'typeof E'." instead — TypeScript's behavior for `const enum E { A }; E["B"]`
        // and equivalent regular-enum cases. The const-enum case is the primary target
        // (`constEnumBadPropertyNames_ts`); regular enums get the same diagnostic for
        // non-member non-numeric string keys because the property still doesn't exist on
        // the enum's static shape.
        if (arg is StringLiteralNode) {
            val recvIdent = expr.expression as? Identifier
            if (recvIdent != null) {
                val recvSym = globals[recvIdent.text]
                if (recvSym != null && recvSym.flags.hasAny(SymbolFlags.Enum)) {
                    val isNumericKey = arg.text.toDoubleOrNull() != null
                    val isKnownMember = recvSym.exports?.containsKey(arg.text) == true
                    if (!isNumericKey && !isKnownMember) {
                        val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                        if (options.noImplicitAny || options.strict) {
                            diagnostics.add(Diagnostic(
                                message = "Element implicitly has an 'any' type because index expression is not of type 'number'.",
                                category = DiagnosticCategory.Error,
                                code = 7015,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = arg.pos,
                                length = (arg.rawText?.length ?: arg.text.length) + 2,
                            ))
                        } else {
                            diagnostics.add(Diagnostic(
                                message = "Property '${arg.text}' does not exist on type 'typeof ${recvIdent.text}'.",
                                category = DiagnosticCategory.Error,
                                code = 2339,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = arg.pos,
                                length = (arg.rawText?.length ?: arg.text.length) + 2,
                            ))
                        }
                        return
                    }
                }
            }
        }
        // Build the raw suggestion syntax for TS2576 from the source text:
        // - StringLiteral key keeps original quoting: a["\""] → `["\""]`
        // - Numeric key: a[0] → `[0]`
        // Position: from `[` (just before arg.pos) to end of key.
        val keySuggestion: String = run {
            val keyEnd = when (arg) {
                is StringLiteralNode -> arg.pos + (arg.rawText?.length ?: arg.text.length) + 2
                is NumericLiteralNode -> arg.pos + arg.text.length
                else -> return@run ".$propName"
            }
            // Find opening `[` by scanning backwards from arg.pos.
            var openBracket = arg.pos - 1
            while (openBracket >= 0 && source[openBracket] != '[') openBracket--
            if (openBracket < 0) return@run ".$propName"
            // Expected layout: `[keySrc]` — closing bracket just after keyEnd (possibly with whitespace).
            var closeBracket = keyEnd
            while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
            if (closeBracket >= source.length) return@run ".$propName"
            source.substring(openBracket, closeBracket + 1)
        }
        // TS2576 squiggle covers the whole `receiver[key]` expression. For compat with the
        // existing TS2339 path, pass a SEPARATE squiggle range via the TS2576 helper — we
        // only widen when TS2576 actually fires (in tryEmitStaticAccessTs2576).
        // Compute the full expression span (receiver.pos .. closeBracket+1):
        val fullStart = expr.expression.pos
        val fullEnd = run {
            var cb = diagStart + diagLength
            while (cb < source.length && source[cb] != ']') cb++
            if (cb < source.length) cb + 1 else diagStart + diagLength
        }
        val fullLength = fullEnd - fullStart
        checkMemberAccessMissing(
            objectExprIn = expr.expression,
            propName = propName,
            diagStart = diagStart,
            diagLength = diagLength,
            source = source,
            fileName = fileName,
            enclosingClassType = enclosingClassType,
            emitTs2728RelatedInfo = false,
            keySuggestion = keySuggestion,
            ts2576SquiggleStart = fullStart,
            ts2576SquiggleLength = fullLength,
        )
    }

    /** Check if `propName` is exported from a namespace symbol. */
    private fun isNameExportedFromNamespace(nsSym: Symbol, propName: String): Boolean {
        val memberSym = nsSym.exports?.get(propName) ?: return false
        // Sub-namespaces (Module flag) are always accessible
        if (memberSym.flags.hasAny(SymbolFlags.Module)) return true
        // Ambient namespaces (declare namespace) implicitly export all members
        if (nsSym.flags.hasAny(SymbolFlags.NamespaceModule)) return true
        // Non-ambient: check for explicit ExportValue flag
        if (memberSym.flags.hasAny(SymbolFlags.ExportValue)) return true
        for (decl in memberSym.declarations) {
            when (decl) {
                is FunctionDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is ClassDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is InterfaceDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is TypeAliasDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is EnumDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is ModuleDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                else -> {}
            }
        }
        // For variables, scan namespace body for VariableStatement with export modifier
        for (nsDecl in nsSym.declarations) {
            val body = (nsDecl as? ModuleDeclaration)?.body as? ModuleBlock ?: continue
            for (stmt in body.statements) {
                if (stmt !is VariableStatement) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                for (d in stmt.declarationList.declarations) {
                    if (d.name is Identifier && (d.name as Identifier).text == propName) return true
                }
            }
        }
        return false
    }

    /** Check if `name` is a static member of `classDecl` (including inherited). */
    /**
     * Returns true if [classDecl] (or a base class) declares an INSTANCE member named [name].
     * Instance members include:
     *  - non-static PropertyDeclaration / MethodDeclaration / GetAccessor / SetAccessor
     *  - Constructor parameter properties (parameters with an access modifier or readonly)
     * Used to suppress TS2576 "did you mean static" for `this.X` when the class has
     * BOTH an instance member X and a static member X. `this.X` in an instance method
     * legitimately resolves to the instance member.
     */
    /** Walk [classDecl]'s instance-side member set + extends chain looking for a
     *  member named [propName]. Returns:
     *
     *  - `true` — member found in this class or any safely-resolvable base.
     *  - `false` — chain fully resolved (terminates at a class with no extends or
     *    a cycle) without finding the member.
     *  - `null` — chain has un-resolvable parts (non-Identifier extends like
     *    `Foo.Bar` or `q<T>()`, an Identifier base whose symbol isn't a
     *    [ClassDeclaration] in [globals], an `IndexSignature` member that would
     *    accept any property name, or a `declare class` whose lib augmentations
     *    we can't see). Caller MUST treat `null` as "unsafe to emit" and bail.
     *
     *  Used by TS2339 emitters that need to ask "is this property genuinely
     *  missing from the entire instance-side view?" without re-walking the
     *  chain manually. Implements clauses are intentionally NOT followed —
     *  per [resolveBaseTypesLazy], implements is a structural constraint, not
     *  a source of inherited members. */
    /** Set of class names that have a sibling [InterfaceDeclaration] with the
     *  same name in any binderResult. Our binder's `canMerge` does not include
     *  Class+Interface, so the second-bound declaration silently overwrites
     *  the first, and `symbol.declarations` ends up holding only one — but the
     *  AST still contains both, and TypeScript treats them as a merged
     *  declaration with combined member sets. The chain walker must bail for
     *  these names because it can't see members contributed by the
     *  non-canonical sibling declaration. Computed on first access (during init)
     *  via [classNamesWithSiblingInterfacesCache] — cannot use `by lazy {}`
     *  because that would declare the property after init and the Lazy backing
     *  field would be null during init-time access. */
    private fun classNamesWithSiblingInterfaces(): Set<String> {
        classNamesWithSiblingInterfacesCache?.let { return it }
        val byName = mutableMapOf<String, MutableSet<String>>()
        for (binderResult in binderResults) {
            for (stmt in binderResult.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> {
                        val n = stmt.name?.text ?: continue
                        byName.getOrPut(n) { mutableSetOf() }.add("C")
                    }
                    is InterfaceDeclaration -> {
                        byName.getOrPut(stmt.name.text) { mutableSetOf() }.add("I")
                    }
                    else -> {}
                }
            }
        }
        val result = byName.filterValues { "C" in it && "I" in it }.keys
        classNamesWithSiblingInterfacesCache = result
        return result
    }

    private fun lookupInstanceMemberInResolvableChain(
        classDecl: ClassDeclaration, propName: String, visited: MutableSet<String>? = null,
    ): Boolean? {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return null
        if (!v.add(className)) return false
        if (className in classNamesWithSiblingInterfaces()) return null
        if (classDecl.members.any { it is IndexSignature }) return null
        if (ModifierFlag.Declare in classDecl.modifiers) return null
        for (m in classDecl.members) {
            when (m) {
                is PropertyDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is MethodDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is GetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is SetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is Constructor -> {
                    for (p in m.parameters) {
                        if (p.modifiers.isEmpty()) continue
                        if ((p.name as? Identifier)?.text == propName) return true
                    }
                }
                else -> {}
            }
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression ?: return false
        if (baseExpr !is Identifier) return null
        val baseSym = globals[baseExpr.text] ?: return null
        val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration ?: return null
        return lookupInstanceMemberInResolvableChain(baseDecl, propName, v)
    }

    private fun hasInstanceMemberNamed(classDecl: ClassDeclaration, name: String, visited: MutableSet<String>? = null): Boolean {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return false
        if (!v.add(className)) return false
        for (m in classDecl.members) {
            when (m) {
                is PropertyDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is MethodDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is GetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is SetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is Constructor -> {
                    for (p in m.parameters) {
                        if (p.modifiers.isEmpty()) continue
                        if ((p.name as? Identifier)?.text == name) return true
                    }
                }
                else -> {}
            }
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression
        if (baseExpr is Identifier) {
            val baseSym = globals[baseExpr.text]
            if (baseSym != null) {
                val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration
                if (baseDecl != null && hasInstanceMemberNamed(baseDecl, name, v)) return true
            }
        }
        return false
    }

    /** TS2576 when `instance.X` / `instance["X"]` accesses a STATIC-only member of the class.
     *  Returns true if emitted (caller should return early).
     *
     *  Only fires for INSTANCE-side access: skip when the receiver type already carries the
     *  property (e.g. `const k2: typeof K; k2.bar` — k2's type is the constructor side, so
     *  `bar` resolves there and `k2.bar` is legitimate). */
    /** TS2339 when a class-instance receiver accesses a property that is genuinely
     *  absent from the class hierarchy.
     *
     *  Conservative gates defend against false positives:
     *   - propName not in [RUNTIME_PROPERTIES];
     *   - symbol has exactly 1 declaration (no interface/namespace augmentation
     *     contributing extra members);
     *   - class is non-generic (TypeParam constraints could supply members we
     *     don't yet check structurally);
     *   - chain walk via [lookupInstanceMemberInResolvableChain] returns `false`
     *     (own + entire extends chain resolved cleanly, no member found). The
     *     helper itself bails (`null`) on hazardous shapes — non-Identifier
     *     extends (`Foo.Bar`, `q<T>()`), unresolvable Identifier bases, ambient
     *     bases (`declare class`), index signatures, or sibling
     *     [InterfaceDeclaration]s of the same name in any binderResult (since
     *     our binder's `canMerge` does not include Class+Interface, those
     *     declarations would silently overwrite each other and the helper can't
     *     see members from the lost declaration);
     *   - flow narrowing yields the same type (e.g., `if (c instanceof D) c.bar()`
     *     narrows `c` from C to D which may have `bar` — the narrowed type
     *     differs and we bail).
     *
     *  Implements clauses are NOT inherited members per [resolveBaseTypesLazy]'s
     *  skip-implements rule, so this fires correctly for
     *  `class C implements A {}; let c: C; c.bar()` where A has only `static bar()`. */
    private fun tryEmitClassInstanceMissingTs2339(
        typeSym: Symbol, rawType: Type, propName: String, objectExpr: Expression,
        diagStart: Int, diagLength: Int, source: String, fileName: String,
    ) {
        if (propName.isEmpty()) return
        if (propName in RUNTIME_PROPERTIES) return
        // 17.130: Count only "shape-defining" declarations (Class/Interface/TypeAlias/Module).
        // Import-specifier and alias declarations are appended via `mergeSymbolTable` at init's
        // global merge step (see CLAUDE.md "ALL file locals merged into globals" gotcha), but
        // they don't contribute members to the class shape. Pre-fix: `declarations.size != 1`
        // bailed whenever a class was imported into any file, over-suppressing TS2339.
        val shapeDecls = typeSym.declarations.count { d ->
            d is ClassDeclaration || d is InterfaceDeclaration ||
                d is TypeAliasDeclaration || d is ModuleDeclaration
        }
        if (shapeDecls != 1) return
        val classDecl = typeSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return
        if (!classDecl.typeParameters.isNullOrEmpty()) return
        // Walk own + extends chain. The helper itself bails on IndexSignature
        // and `declare class` (in this class OR any base), so those gates need
        // not be repeated at this level. `null` means chain isn't safely
        // resolvable (complex extends like `Foo.Bar`, unresolved Identifier,
        // ambient base, etc.); `true` means a base in the chain declares the
        // property; only `false` means "genuinely missing across the entire
        // resolvable instance side".
        if (lookupInstanceMemberInResolvableChain(classDecl, propName) != false) return
        if (isStaticMemberOfClass(classDecl, propName)) return
        val narrowed = getNarrowedTypeForReference(rawType, objectExpr)
        if (narrowed !== rawType) return
        val typeName = classDecl.name?.text ?: typeSym.name
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$typeName'.",
            category = DiagnosticCategory.Error, code = 2339,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
        ))
    }

    private fun tryEmitStaticAccessTs2576(
        typeSym: Symbol, propName: String, diagStart: Int, diagLength: Int,
        suggestionKey: String, source: String, fileName: String,
        receiverType: Type? = null,
    ): Boolean {
        if (propName.isEmpty()) return false
        if (propName in RUNTIME_PROPERTIES) return false
        // Only fire for INSTANCE-side access (Type.Interface). Constructor-side receivers
        // (`typeof C`, Type.Object built by `getTypeOfSymbolForTypeQuery`) carry static
        // members as actual properties and should fall through to normal TS2339 checking.
        // NOTE: Type.Interface extends Type.Object so `is Type.Object` alone matches both.
        if (receiverType != null && receiverType !is Type.Interface && receiverType is Type.Object) return false
        val classDecl = typeSym.declarations.firstOrNull() as? ClassDeclaration ?: return false
        if (!isStaticMemberOfClass(classDecl, propName)) return false
        if (hasInstanceMemberNamed(classDecl, propName)) return false
        val baseName = classDecl.name?.text ?: typeSym.name
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$baseName'. Did you mean to access the static member '$baseName$suggestionKey' instead?",
            category = DiagnosticCategory.Error, code = 2576,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
        ))
        return true
    }

    private fun classMemberNameText(nameNode: Node?): String? = when (nameNode) {
        is Identifier -> nameNode.text
        is StringLiteralNode -> nameNode.text
        is NumericLiteralNode -> nameNode.text
        else -> null
    }

    private fun isStaticMemberOfClass(classDecl: ClassDeclaration, name: String, visited: MutableSet<String>? = null): Boolean {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return false
        if (!v.add(className)) return false
        for (m in classDecl.members) {
            val memberName = when (m) {
                is PropertyDeclaration -> classMemberNameText(m.name)
                is MethodDeclaration -> classMemberNameText(m.name)
                is GetAccessor -> classMemberNameText(m.name)
                is SetAccessor -> classMemberNameText(m.name)
                else -> null
            }
            if (memberName != name) continue
            val isStatic = when (m) {
                is PropertyDeclaration -> ModifierFlag.Static in m.modifiers
                is MethodDeclaration -> ModifierFlag.Static in m.modifiers
                is GetAccessor -> ModifierFlag.Static in m.modifiers
                is SetAccessor -> ModifierFlag.Static in m.modifiers
                else -> false
            }
            if (isStatic) return true
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression
        if (baseExpr is Identifier) {
            val baseSym = globals[baseExpr.text]
            if (baseSym != null) {
                val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration
                if (baseDecl != null && isStaticMemberOfClass(baseDecl, name, v)) return true
            }
        }
        return false
    }

    /**
     * Resolve the type of a property access's object expression.
     * Enhanced version that handles 'this' with class context.
     */
    private fun resolvePropertyAccessObjectType(expr: Expression, enclosingClassType: Type?): Type {
        if (expr is Identifier && expr.text == "this" && enclosingClassType != null) {
            return enclosingClassType
        }
        return getTypeOfExpression(expr)
    }

    // -----------------------------------------------------------------------
    // TS2345: Argument type checking (Phase 4 item 7a)
    // -----------------------------------------------------------------------

    private fun checkCallExpressionTypes() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip .js files
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                checkCallTypesInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {
                // Safety net for deeply nested ASTs
            }
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkCallTypesInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            checkCallTypesInStatement(stmt, source, fileName)
        }
    }

    private fun checkCallTypesInStatement(stmt: Statement, source: String, fileName: String) {
        if (++callTypeCheckDepth > maxCheckDepth) { callTypeCheckDepth--; return }
        try {
        when (stmt) {
            is ExpressionStatement -> checkCallTypesInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is IfStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkCallTypesInStatement(it, source, fileName) }
            }
            is Block -> checkCallTypesInStatements(stmt.statements, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        }
                    }
                    is Expression -> checkCallTypesInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkCallTypesInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkCallTypesInExpr(it, source, fileName) }
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
                checkCallTypesInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkCallTypesInStatements(clauseStmts, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                // Check parameter default initializers for call expression type errors
                for (param in stmt.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                stmt.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    populateParameterLocalTypes(stmt.parameters)
                    checkCallTypesInStatements(body.statements, source, fileName)
                    currentLocalTypes = savedLocalTypes
                }
            }
            is ClassDeclaration -> {
                // 17.20: Push class type parameters onto `currentTypeParamScope` during
                // heritage-clause resolution AND member body walks. Without this,
                // `class D<T> extends C<T>` resolves the heritage `T` to errorType
                // (D's T isn't in scope), so heritage type args drop to []. Same
                // applies to `<T>` references inside method bodies (e.g.
                // `super.bar<T>(null)`).
                //
                // 17.21: When inside a namespace (`inferenceNamespaceStack` non-empty),
                // the class symbol is in the enclosing namespace's `exports`, not in
                // `globals` — fall back to that lookup so e.g. a class declared in
                // `namespace Editor { class List<T> {} }` still gets its TypeParam scope.
                val classSym = stmt.name?.let { name ->
                    globals[name.text] ?: inferenceNamespaceStack.lastOrNull()?.exports?.get(name.text)
                }
                val classTypeParams: List<Type.TypeParam> = if (classSym != null) {
                    try {
                        (getDeclaredTypeOfSymbol(classSym) as? Type.Interface)?.typeParameters.orEmpty()
                    } catch (_: StackOverflowError) { emptyList() }
                } else emptyList()
                val savedClassScope = currentTypeParamScope
                if (classTypeParams.isNotEmpty()) {
                    val newScope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                    for (tp in classTypeParams) {
                        tp.symbol?.name?.let { newScope[it] = tp }
                    }
                    currentTypeParamScope = newScope
                }
                val pushedClass = classSym?.also { callWalkerClassStack.addLast(it) }
                try {
                    // 17.19/17.20: Resolve the base class's symbol + heritage type args
                    // once per class. Used by both `super(...)` arg checking (17.19, via
                    // baseSig) and `super.method(...)` arg checking (17.20, via
                    // baseInstanceType). Heritage type args resolve in the class scope
                    // so D's T is visible in `extends C<T>`.
                    val baseResolution: Pair<Signature?, Type?> = run {
                        val extClause = stmt.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                            ?: return@run null to null
                        val baseExpr = extClause.types.firstOrNull() ?: return@run null to null
                        val baseName = when (val bn = baseExpr.expression) {
                            is Identifier -> bn.text
                            else -> return@run null to null
                        }
                        val baseSym = globals[baseName] ?: return@run null to null
                        val typeArgs = baseExpr.typeArguments?.mapNotNull { tn ->
                            try { getTypeFromTypeNode(tn).takeIf { it !== errorType } } catch (_: StackOverflowError) { null }
                        }.orEmpty()
                        val sig = try {
                            buildBaseConstructorSignatureForSuper(baseSym, typeArgs)
                        } catch (_: StackOverflowError) { null }
                        val instType = try {
                            buildBaseInstanceTypeForSuper(baseSym, typeArgs)
                        } catch (_: StackOverflowError) { null }
                        sig to instType
                    }
                    val baseSig = baseResolution.first
                    val baseInstanceType = baseResolution.second
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                for (param in member.parameters) {
                                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                                }
                                member.body?.let { body ->
                                    val savedLocalTypes = currentLocalTypes
                                    val savedSuperBaseType = currentSuperBaseType
                                    currentLocalTypes = currentLocalTypes.toMutableMap()
                                    currentSuperBaseType = baseInstanceType
                                    // 17.21: Static methods don't see class TypeParams (TypeScript
                                    // emits TS2302 for any reference). Pop the class scope while
                                    // walking a static method body so re-resolution of `<T>` etc.
                                    // returns errorType, which the new-expression type-arg gate
                                    // uses to skip the 17.20 null-vs-bare-TypeParam emission.
                                    // B74.5: Static methods that declare their OWN type parameters
                                    // (e.g. `static MakeHead2<T>()`) MUST still see those — only
                                    // the class's TPs are out of scope. Mint fresh Type.TypeParam
                                    // for each method TP (mirrors the pattern at Checker.kt:~49187)
                                    // and push them onto savedClassScope so explicit `<T>` in
                                    // `new List<T>(...)` resolves cleanly and the 17.21 re-resolution
                                    // gate fires for `null` args.
                                    val isStatic = ModifierFlag.Static in member.modifiers
                                    val savedMethodScope = currentTypeParamScope
                                    if (isStatic) {
                                        val methodTpNodes = member.typeParameters
                                        if (methodTpNodes.isNullOrEmpty()) {
                                            currentTypeParamScope = savedClassScope
                                        } else {
                                            val newScope = (savedClassScope?.toMutableMap() ?: mutableMapOf())
                                            for (tpNode in methodTpNodes) {
                                                val tp = Type.TypeParam()
                                                tp.symbol = Symbol(SymbolFlags.TypeParameter, tpNode.name.text)
                                                newScope[tpNode.name.text] = tp
                                            }
                                            currentTypeParamScope = newScope
                                        }
                                    }
                                    try {
                                        populateParameterLocalTypes(member.parameters)
                                        checkCallTypesInStatements(body.statements, source, fileName)
                                    } finally {
                                        currentLocalTypes = savedLocalTypes
                                        currentSuperBaseType = savedSuperBaseType
                                        currentTypeParamScope = savedMethodScope
                                    }
                                }
                            }
                            is Constructor -> {
                                for (param in member.parameters) {
                                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                                }
                                member.body?.let { body ->
                                    val savedLocalTypes = currentLocalTypes
                                    val savedSuperBaseSig = currentSuperBaseSig
                                    val savedSuperBaseType = currentSuperBaseType
                                    currentLocalTypes = currentLocalTypes.toMutableMap()
                                    currentSuperBaseSig = baseSig
                                    currentSuperBaseType = baseInstanceType
                                    try {
                                        populateParameterLocalTypes(member.parameters)
                                        checkCallTypesInStatements(body.statements, source, fileName)
                                    } finally {
                                        currentLocalTypes = savedLocalTypes
                                        currentSuperBaseSig = savedSuperBaseSig
                                        currentSuperBaseType = savedSuperBaseType
                                    }
                                }
                            }
                            is GetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                            is PropertyDeclaration -> member.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                            else -> {}
                        }
                    }
                } finally {
                    currentTypeParamScope = savedClassScope
                    if (pushedClass != null) callWalkerClassStack.removeLast()
                }
            }
            is TryStatement -> {
                checkCallTypesInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkCallTypesInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is LabeledStatement -> checkCallTypesInStatement(stmt.statement, source, fileName)
            is WithStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ModuleDeclaration -> {
                // 17.21: Recurse into namespace bodies so call/new arg checking fires
                // inside namespace-scoped classes/functions. Pushes the namespace symbol
                // onto `inferenceNamespaceStack` so [getCalleeType]'s Identifier branch
                // (and downstream lookups) can resolve namespace-internal names via
                // [lookupInInferenceNamespace]. Mirrors the precedent in
                // `checkTypeAssignabilityInStmt`.
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    val nameNode = stmt.name
                    val moduleSymbol = if (nameNode is Identifier) {
                        if (inferenceNamespaceStack.isNotEmpty()) {
                            inferenceNamespaceStack.last().exports?.get(nameNode.text)
                        } else {
                            currentFileLocals?.get(nameNode.text) ?: globals[nameNode.text]
                        }
                    } else null
                    val pushed = if (moduleSymbol != null && moduleSymbol.flags.hasAny(SymbolFlags.Module)) {
                        inferenceNamespaceStack.addLast(moduleSymbol)
                        true
                    } else false
                    try {
                        when (val body = stmt.body) {
                            is ModuleBlock -> checkCallTypesInStatements(body.statements, source, fileName)
                            is ModuleDeclaration -> checkCallTypesInStatement(body, source, fileName)
                            else -> {}
                        }
                    } finally {
                        if (pushed) inferenceNamespaceStack.removeLast()
                    }
                }
            }
            else -> {}
        }
        } finally { callTypeCheckDepth-- }
    }

    private fun checkCallTypesInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is CallExpression -> {
                checkSingleCallExpressionTypes(expr, source, fileName)
                // Recurse into callee and arguments
                checkCallTypesInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkCallTypesInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkSingleNewExpressionTypes(expr, source, fileName)
                checkCallTypesInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkCallTypesInExpr(it, source, fileName) }
            }
            is BinaryExpression -> {
                // B64.6: iterative left-spine flatten to avoid StackOverflow.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkCallTypesInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkCallTypesInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkCallTypesInExpr(expr.condition, source, fileName)
                checkCallTypesInExpr(expr.whenTrue, source, fileName)
                checkCallTypesInExpr(expr.whenFalse, source, fileName)
            }
            is ParenthesizedExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PropertyAccessExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkCallTypesInExpr(expr.expression, source, fileName)
                checkCallTypesInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkCallTypesInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        is SpreadAssignment -> checkCallTypesInExpr(prop.expression, source, fileName)
                        is MethodDeclaration -> prop.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        is GetAccessor -> prop.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        is SetAccessor -> prop.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                expr.body?.let { body ->
                    when (body) {
                        is Block -> checkCallTypesInStatements(body.statements, source, fileName)
                        is Expression -> checkCallTypesInExpr(body, source, fileName)
                        else -> {}
                    }
                }
            }
            is FunctionExpression -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                expr.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) checkCallTypesInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkSingleTaggedTemplateTypes(expr, source, fileName)
                checkCallTypesInExpr(expr.tag, source, fileName)
                // Also recurse into substitutions so nested calls/errors surface.
                (expr.template as? TemplateExpression)?.let { tmpl ->
                    for (span in tmpl.templateSpans) checkCallTypesInExpr(span.expression, source, fileName)
                }
            }
            is AsExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SpreadElement -> checkCallTypesInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is DeleteExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Check argument types for a single CallExpression against resolved signature(s).
     * For non-overloaded functions: check against the single signature.
     * For overloaded functions: try each overload in order, skip if any matches,
     * report TS2345 against the last overload if none match (TypeScript convention).
     */
    /**
     * True when `expr` is a (possibly nested) property-access chain whose root is
     * a plain Identifier resolving to a `var`/`let`/`const` declaration without a
     * type annotation AND without an initializer — i.e. definitively implicit-any.
     * Used as a narrow gate for TS2347 emission.
     */
    private fun isImplicitAnyVarChain(expr: Expression): Boolean {
        var cur: Expression = expr
        while (cur is PropertyAccessExpression) cur = cur.expression
        if (cur !is Identifier) return false
        val name = cur.text
        val symbol = currentFileLocals?.get(name) ?: globals[name] ?: return false
        if (!symbol.flags.hasAny(SymbolFlags.Variable)) return false
        val decl = symbol.valueDeclaration as? VariableDeclaration ?: return false
        // Definitively implicit-any when BOTH annotation and initializer are absent.
        if (decl.type == null && decl.initializer == null) return true
        // Explicit `: any` annotation also counts (`declare var g: any; g<T>()`).
        val ann = decl.type
        return ann is KeywordTypeNode && ann.kind == SyntaxKind.AnyKeyword
    }

    /**
     * 16.4ey: TS2345 for tagged template substitutions whose type doesn't match the
     * tag function's parameter. The tag's first parameter is `TemplateStringsArray`
     * (bound to the static parts); substitutions map to parameters[1..N]. Narrow:
     * skipped when tag has 0 signatures, multi-signature, or type parameters; only
     * fires when both substitution type and expected param type are simple-checkable
     * (primitives / literal unions). This mirrors the CallExpression path without
     * re-invoking the full overload/contextual-typing machinery.
     */
    private fun checkSingleTaggedTemplateTypes(
        expr: TaggedTemplateExpression, source: String, fileName: String,
    ) {
        val calleeType = try { getCalleeType(expr.tag) } catch (_: StackOverflowError) { return }
        if (calleeType === anyType || calleeType === errorType) return
        val signatures = getCallSignaturesOfType(calleeType)
        if (signatures.size != 1) return
        val sig = signatures[0]
        if (!sig.typeParameters.isNullOrEmpty()) return
        val tmpl = expr.template as? TemplateExpression ?: return
        val substitutions = tmpl.templateSpans.map { it.expression }
        if (substitutions.any { it is OmittedExpression }) return
        val params = sig.parameters
        // TypeScript counts the unterminated trailing `${` as a phantom substitution — a
        // template `...${1}${2}${` at a tag expecting 3 params (TSA + 2) is still 4 args
        // → TS2554 (which we don't emit, but TS does), so per-arg TS2345 is suppressed.
        // Our gate: count isUnterminated as +1 arg. Skip TS2345 when total > params.size.
        val phantomUnterminated = if (tmpl.isUnterminated) 1 else 0
        if (substitutions.size + 1 + phantomUnterminated > params.size) return
        for ((i, sub) in substitutions.withIndex()) {
            val paramIdx = i + 1 // skip TemplateStringsArray
            if (paramIdx >= params.size) break
            val paramType = getTypeOfSymbol(params[paramIdx])
            if (paramType === anyType || paramType === errorType) continue
            if (!isSimpleCheckableType(paramType)) continue
            val argType = try { getTypeOfExpression(sub) } catch (_: StackOverflowError) { continue }
            if (argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(argType)) continue
            // Use the subtype relation to check assignability.
            val widenedArg = getWidenedLiteralType(argType)
            val widenedParam = getWidenedLiteralType(paramType)
            if (checkTypeRelatedTo(argType, paramType, assignableRelation)) continue
            // Also allow widened-literal to pass (e.g. `1` vs `number`).
            if (widenedArg === widenedParam) continue
            val argStr = typeToString(widenedArg)
            val paramStr = typeToString(widenedParam)
            val start = sub.pos
            val length = (expressionTrueEnd(sub) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argStr' is not assignable to parameter of type '$paramStr'.",
                category = DiagnosticCategory.Error,
                code = 2345,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            break // Report one error per tagged template
        }
    }

    private fun checkSingleCallExpressionTypes(expr: CallExpression, source: String, fileName: String) {
        // 16.4dx: TS2754 "'super' may not use type arguments." fires when a `super(...)`
        // call has explicit type arguments (e.g. `super<T>()`). Only for direct super
        // calls — `super.method<T>()` is a regular method call and valid. Squiggle
        // spans the whole `<...>` section; `node.end` in this AST already overshoots
        // to the token AFTER the last type arg's `>`, so subtract when computing end.
        val calleeExpr = expr.expression
        if (calleeExpr is Identifier && calleeExpr.text == "super" && !expr.typeArguments.isNullOrEmpty()) {
            val typeArgs = expr.typeArguments!!
            val start = typeArgs.first().pos - 1
            val end = typeArgs.last().end
            val length = end - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "'super' may not use type arguments.",
                    category = DiagnosticCategory.Error,
                    code = 2754,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
        // 17.19: `super(...)` arg checking via the base ctor signature stashed by the
        // ClassDeclaration handler. `getCalleeType("super")` returns anyType (no global
        // entry), so the standard path early-returns at the anyType bail below. Handle
        // here, then return.
        if (calleeExpr is Identifier && calleeExpr.text == "super") {
            currentSuperBaseSig?.let { sig ->
                checkArgumentsAgainstSignature(expr.arguments, sig, source, fileName)
            }
            return
        }
        // 17.20: `super.method(...)` arg checking. Resolves the method on the base
        // instance type stashed by the ClassDeclaration handler. The standard path
        // would treat `super` as anyType and bail before reaching arg checking.
        if (calleeExpr is PropertyAccessExpression && calleeExpr.expression is Identifier &&
            (calleeExpr.expression as Identifier).text == "super") {
            val baseType = currentSuperBaseType
            if (baseType != null) {
                if (handleSuperMethodCall(expr, calleeExpr, baseType, source, fileName)) return
            }
        }
        // Resolve callee to get its type
        val calleeType = getCalleeType(expr.expression)
        // TS2347: "Untyped function calls may not accept type arguments." Fires when a
        // call like `untypedVar.method<T>(arg)` has explicit type args on a callee that
        // resolves to `any`. Narrowly gated on the chain root being an Identifier that
        // refers to a `var`/`let` declared without a type annotation AND without an
        // initializer — definitively implicit-any. Broader "calleeType === anyType" is
        // unsafe: our checker resolves many callees to `any` due to incomplete inference,
        // so a universal emission would regress heavily.
        if (!expr.typeArguments.isNullOrEmpty() && isImplicitAnyVarChain(expr.expression)) {
            val start = expr.pos
            val length = expressionTrueEnd(expr) - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Untyped function calls may not accept type arguments.",
                    category = DiagnosticCategory.Error,
                    code = 2347,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
        // B62.2 (early): bare null/undefined literal callees. getCalleeType returns
        // anyType for these (no symbol resolution path), so we must catch them BEFORE
        // the anyType bail. Detect via AST shape: parser produces
        // `Identifier(text="null"/"undefined")` for these keywords.
        if (strictNullChecks && calleeExpr is Identifier) {
            val isNullIdent = calleeExpr.text == "null"
            val isUndefIdent = calleeExpr.text == "undefined"
            if (isNullIdent || isUndefIdent) {
                val start = calleeExpr.pos
                val length = expressionTrueEnd(calleeExpr) - start
                if (length > 0) {
                    val (msg, code) = if (isNullIdent)
                        "Cannot invoke an object which is possibly 'null'." to 2721
                    else
                        "Cannot invoke an object which is possibly 'undefined'." to 2722
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = msg,
                        category = DiagnosticCategory.Error, code = code,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                    return
                }
            }
        }
        if (calleeType === anyType || calleeType === errorType) return
        // B60.14: union callee — three cases:
        //   (a) all constituents non-callable → "No constituent ... is callable."
        //   (b) some constituents non-callable → "Not all constituents ... are callable." + missing display
        //   (c) all constituents callable but sigs differ structurally → "Each member ... has signatures, but none ... compatible..."
        if (calleeType is Type.Union) {
            val constituents = calleeType.types
            val nonCallable = constituents.filter { getCallSignaturesOfType(it).isEmpty() }
            val unionDisplay = typeToString(calleeType)
            val computeSpan = {
                if (calleeExpr is PropertyAccessExpression) {
                    Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                } else {
                    val s = calleeExpr.pos
                    Pair(s, expressionTrueEnd(calleeExpr) - s)
                }
            }
            if (nonCallable.isNotEmpty() && nonCallable.size != constituents.size) {
                // Case (b): mixed callable / non-callable.
                val firstMissing = nonCallable[0]
                val missingDisplay = typeToString(firstMissing)
                val (start, length) = computeSpan()
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error, code = 2349,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf(
                            "  Not all constituents of type '$unionDisplay' are callable.",
                            "    Type '$missingDisplay' has no call signatures.",
                        ),
                    ))
                }
                return
            }
            if (nonCallable.isEmpty() && constituents.size >= 2) {
                // Case (c): all callable; check if sigs differ structurally (different
                // TypeParam counts, different first-param types).
                val sigsList = constituents.map { getCallSignaturesOfType(it).firstOrNull() }
                val hasNullSig = sigsList.any { it == null }
                if (!hasNullSig) {
                    val sigs = sigsList.map { it!! }
                    val differ = run {
                        for (i in sigs.indices) for (j in i + 1 until sigs.size) {
                            val s1 = sigs[i]; val s2 = sigs[j]
                            if ((s1.typeParameters?.size ?: 0) != (s2.typeParameters?.size ?: 0)) return@run true
                            if (s1.parameters.size != s2.parameters.size) return@run true
                            for (k in s1.parameters.indices) {
                                val t1 = try { getTypeOfSymbol(s1.parameters[k]) } catch (_: StackOverflowError) { return@run false }
                                val t2 = try { getTypeOfSymbol(s2.parameters[k]) } catch (_: StackOverflowError) { return@run false }
                                if (t1 !== t2) return@run true
                            }
                        }
                        false
                    }
                    if (differ) {
                        val (start, length) = computeSpan()
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "This expression is not callable.",
                                category = DiagnosticCategory.Error, code = 2349,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                messageChain = listOf(
                                    "  Each member of the union type '$unionDisplay' has signatures, but none of those signatures are compatible with each other.",
                                ),
                            ))
                        }
                        return
                    }
                }
            }
        }
        // Get call signatures
        val signatures = getCallSignaturesOfType(calleeType)
        if (signatures.isEmpty()) {
            // 17.166: TS2348 — `var c = C();` where C is a class. The class
            // value's type is `typeof C` with construct signatures only; calling
            // it without `new` is a user error. Squiggle covers the full call
            // expression (matches TypeScript's `C()` span in the baseline) —
            // computed locally so the shared expressionTrueEnd helper stays
            // unchanged (an earlier attempt to widen its empty-args fallback
            // regressed -2 unrelated tests).
            if (calleeExpr is Identifier) {
                val sym = globals[calleeExpr.text]
                // 17.166: gate TS2348 to symbols that are PURE classes — i.e. no
                // FunctionDeclaration anywhere in any binderResult's source file with
                // the same name (the binder's `canMerge` rejects Class+Function so the
                // function decl lives in a separate slot or is overwritten — check the
                // AST directly). Without this gate, `callOverloads3/4/5_ts` and
                // `callOnInstance_ts` (which merge `function Foo(): Foo` /
                // `declare function D()` with classes named the same) FP-fire TS2348.
                val name = calleeExpr.text
                val hasFunctionWithSameName = binderResults.any { br ->
                    br.sourceFile.statements.any { st ->
                        st is FunctionDeclaration && st.name?.text == name
                    }
                }
                if (sym != null && sym.flags.hasAny(SymbolFlags.Class) && !hasFunctionWithSameName) {
                    val start = expr.pos
                    val end = if (expr.arguments.isNotEmpty()) {
                        expressionTrueEnd(expr.arguments.last()) + 1
                    } else {
                        // empty `()` past the callee identifier
                        calleeExpr.pos + calleeExpr.text.length + 2
                    }
                    val length = end - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Value of type 'typeof ${calleeExpr.text}' is not callable. Did you mean to include 'new'?",
                            category = DiagnosticCategory.Error,
                            code = 2348,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    return
                }
            }
            // 16.4cs: TS6234 — calling a property whose only declarations are
            // `get`/`set` accessors. The property resolves to its return type
            // (e.g. `number`), which has no call signatures, so an attempted
            // `obj.prop()` is a user error — they likely meant `obj.prop`.
            val firedTs6234 = checkTs6234GetAccessorCall(expr, calleeType, source, fileName)
            // 16.4gk: TS2349 "This expression is not callable." Narrow gate on
            // primitives: when the callee resolves to a Type.Intrinsic (number,
            // string, boolean, etc.), the call is definitively invalid. Display
            // uses the wrapper interface name (e.g. 'Number' for number).
            // Skip when TS6234 already fired (get-accessor calls share the same
            // primitive return-type pattern).
            // B62.2: TS2721/TS2722/TS2723 for nullable callees under strictNullChecks.
            //   null()      → TS2721 "Cannot invoke an object which is possibly 'null'."
            //   undefined() → TS2722 "Cannot invoke an object which is possibly 'undefined'."
            //   f() where f: null | undefined → TS2723 "Cannot invoke ... 'null' or 'undefined'."
            // Span: full callee expression text.
            if (!firedTs6234 && strictNullChecks) {
                val isNullCallee = calleeType === nullType
                val isUndefCallee = calleeType === undefinedType
                val isUnionNullUndef = calleeType is Type.Union &&
                    calleeType.types.size == 2 &&
                    calleeType.types.all { it === nullType || it === undefinedType } &&
                    calleeType.types.any { it === nullType } &&
                    calleeType.types.any { it === undefinedType }
                if (isNullCallee || isUndefCallee || isUnionNullUndef) {
                    val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                        Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                    } else {
                        val s = calleeExpr.pos
                        Pair(s, expressionTrueEnd(calleeExpr) - s)
                    }
                    if (length > 0) {
                        val (msg, code) = when {
                            isNullCallee -> "Cannot invoke an object which is possibly 'null'." to 2721
                            isUndefCallee -> "Cannot invoke an object which is possibly 'undefined'." to 2722
                            else -> "Cannot invoke an object which is possibly 'null' or 'undefined'." to 2723
                        }
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = msg,
                            category = DiagnosticCategory.Error, code = code,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                        ))
                        return
                    }
                }
            }
            // B60.14: union callee — "No constituent ... is callable" or
            // "Not all constituents ... are callable" depending on whether any
            // constituent has call sigs.
            if (!firedTs6234 && calleeType is Type.Union) {
                val unionDisplay = typeToString(calleeType)
                val constituents = calleeType.types
                val nonCallable = constituents.filter { getCallSignaturesOfType(it).isEmpty() }
                if (nonCallable.isNotEmpty() && nonCallable.size == constituents.size) {
                    // All constituents lack call sigs.
                    val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                        Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                    } else {
                        val s = calleeExpr.pos
                        Pair(s, expressionTrueEnd(calleeExpr) - s)
                    }
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "This expression is not callable.",
                            category = DiagnosticCategory.Error, code = 2349,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                            messageChain = listOf("  No constituent of type '$unionDisplay' is callable."),
                        ))
                        return
                    }
                } else if (nonCallable.isNotEmpty()) {
                    // Some constituents lack call sigs.
                    val firstMissing = nonCallable[0]
                    val missingDisplay = typeToString(firstMissing)
                    val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                        Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                    } else {
                        val s = calleeExpr.pos
                        Pair(s, expressionTrueEnd(calleeExpr) - s)
                    }
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "This expression is not callable.",
                            category = DiagnosticCategory.Error, code = 2349,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                            messageChain = listOf(
                                "  Not all constituents of type '$unionDisplay' are callable.",
                                "    Type '$missingDisplay' has no call signatures.",
                            ),
                        ))
                        return
                    }
                }
            }
            if (!firedTs6234 && calleeType is Type.Intrinsic && calleeType !== voidType &&
                calleeType !== nullType && calleeType !== undefinedType &&
                calleeType !== neverType && calleeType !== unknownType) {
                val displayType = typeToString(getApparentType(calleeType))
                // 17.84: When the callee is a PropertyAccessExpression, squiggle just
                // the property name (matches TypeScript's per-segment elaboration for
                // chained calls like `obj.method().notMethod()` — only `notMethod`
                // is highlighted, not the whole chain).
                val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                    Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                } else {
                    val s = calleeExpr.pos
                    Pair(s, expressionTrueEnd(calleeExpr) - s)
                }
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    // B60.13: When the callee is a CallExpression whose end is on a
                    // different (earlier) line than the outer call's first argument,
                    // emit TS2734 "Are you missing a semicolon?" related info pointing
                    // to the inner call's start. Covers the `foo()\n(1 as number)`
                    // accidental-call pattern from `betterErrorForAccidentalCall_ts`.
                    val related = mutableListOf<Diagnostic>()
                    if (calleeExpr is CallExpression && expr.arguments.isNotEmpty()) {
                        val innerEnd = expressionTrueEnd(calleeExpr)
                        val firstArgPos = expr.arguments.first().pos
                        val (innerEndLine, _) = getLineAndCharacterOfPosition(source, innerEnd)
                        val (argLine, _) = getLineAndCharacterOfPosition(source, firstArgPos)
                        if (innerEndLine < argLine) {
                            val innerStart = calleeExpr.pos
                            val (relLine, relChar) = getLineAndCharacterOfPosition(source, innerStart)
                            related.add(Diagnostic(
                                message = "Are you missing a semicolon?",
                                category = DiagnosticCategory.Message, code = 2734,
                                fileName = fileName, line = relLine, character = relChar,
                                start = innerStart, length = length,
                            ))
                        }
                    }
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error,
                        code = 2349,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = listOf("  Type '$displayType' has no call signatures."),
                        relatedInformation = if (related.isEmpty()) emptyList() else related.toList(),
                    ))
                }
            }
            return
        }
        // 16.4: Instantiate signature when explicit type arguments are provided
        val typeArgs = expr.typeArguments
        if (typeArgs != null && typeArgs.isNotEmpty()) {
            val resolvedTypeArgs = try {
                typeArgs.map { getTypeFromTypeNode(it) }
            } catch (_: StackOverflowError) { null }
            if (resolvedTypeArgs != null && resolvedTypeArgs.none { it === errorType }) {
                // Find a generic signature with matching type parameter count
                val genericSig = signatures.firstOrNull { sig ->
                    val tp = sig.typeParameters
                    tp != null && tp.size == resolvedTypeArgs.size
                }
                if (genericSig?.typeParameters != null) {
                    val mapper = createTypeMapper(genericSig.typeParameters!!, resolvedTypeArgs)
                    // TS2344: Check type argument constraints
                    checkCallTypeArgConstraints(genericSig.typeParameters!!, resolvedTypeArgs, typeArgs, mapper, source, fileName)
                    // B83.4f-a: use instantiateContextualSignature (not the plain
                    // instantiateSignature) so a nested FUNCTION-typed param like
                    // `f: (x: T) => Date` substitutes its inner `(x: T)` to `(x: <number>)`.
                    // Plain instantiateType deliberately no-ops on function-shaped
                    // Type.Object (CLAUDE.md gotcha); instantiateContextualSignature descends
                    // into the call signatures, so explicit `<number>` reaches the callback
                    // param and TS2345 (`(x:number)=>string` ≠ `(x:number)=>Date`) can fire.
                    val instantiated = instantiateContextualSignature(genericSig, mapper)
                    // TS2793: only attach "implementation would have succeeded" related info
                    // when the implementation signature actually accepts these args under
                    // the supplied type-args. For overloaded generic functions like
                    // `foo<T extends Date>(test: T)` / `foo<T extends Number>(test: string)`
                    // / `foo<T extends String>(test: any)` (impl), calling `foo<Date>("")`
                    // doesn't satisfy the impl's `T extends String` constraint, so the impl
                    // wouldn't have succeeded either — TS2793 should be suppressed.
                    var implRelated: Diagnostic? = null
                    val implRelatedCandidate = getOverloadImplementationRelated(genericSig, source, fileName)
                    if (implRelatedCandidate != null) {
                        val implSig = getImplementationSignature(genericSig, source, fileName)
                        if (implSig != null && allArgumentsMatch(expr.arguments, implSig, bivariantFnParams = true) &&
                            implTypeArgConstraintsSatisfied(implSig, resolvedTypeArgs)
                        ) {
                            implRelated = implRelatedCandidate
                        }
                    }
                    checkTs2554ForPropertyAccessCall(expr, instantiated, source, fileName)
                    checkArgumentsAgainstSignature(expr.arguments, instantiated, source, fileName, implRelated, calleeGenericInstantiation = true)
                    return
                }
            }
        }
        if (signatures.size == 1) {
            // TS2793: only attach "implementation would have succeeded" when the
            // implementation signature actually accepts these args. Without this
            // gate, calls like `foo("HI")` against `function foo(name: "SPAN");
            // function foo(name: "DIV") {}` would dangle a TS2793 hint pointing at
            // an impl that rejects "HI" too. Mirrors the gate already in place for
            // the generic-overload path (~48347) and the multi-overload path
            // (~48974) — see CLAUDE.md "TS2793 conditional on implementation match".
            var implRelated: Diagnostic? = null
            val implRelatedCandidate = getOverloadImplementationRelated(signatures[0], source, fileName)
            if (implRelatedCandidate != null) {
                val implSig = getImplementationSignature(signatures[0], source, fileName)
                if (implSig != null && allArgumentsMatch(expr.arguments, implSig, bivariantFnParams = true)) {
                    implRelated = implRelatedCandidate
                }
            }
            checkTs2554ForPropertyAccessCall(expr, signatures[0], source, fileName)
            checkArgumentsAgainstSignature(expr.arguments, signatures[0], source, fileName, implRelated)
        } else {
            // Skip overload resolution when any signature has type parameters —
            // without generic type argument inference, parameter types may resolve
            // incorrectly and produce false positive TS2769 errors.
            val hasTypeParams = signatures.any { !it.typeParameters.isNullOrEmpty() }
            if (hasTypeParams) return
            // Overload resolution: try each signature in order
            checkArgumentsAgainstOverloads(expr.arguments, signatures, source, fileName, expr.expression)
        }
    }

    /**
     * 17.11b: Emit TS2554 (Expected N arguments, but got M) for property-access
     * call expressions like `x.b()` where the resolved sig requires more args
     * than provided. The syntactic arg-count walker (`checkArgCountInExprCore`)
     * only handles `Identifier` callees because it works without type
     * resolution; PropertyAccess callees fall through. This type-aware check
     * fills the gap for that subset. Squiggle is on the property name (matches
     * TypeScript baseline). For too-few args, emits a TS6210 related info
     * pointing to the missing parameter's declaration.
     */
    private fun checkTs2554ForPropertyAccessCall(
        expr: CallExpression,
        sig: Signature,
        source: String,
        fileName: String,
    ) {
        val callee = expr.expression as? PropertyAccessExpression ?: return
        val params = sig.parameters
        val hasRest = (params.lastOrNull()?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        val argCount = expr.arguments.size
        val minParams = sig.minArgumentCount
        val maxParams = params.size
        if (argCount >= minParams && (hasRest || argCount <= maxParams)) return
        if (argCount >= minParams) return // too-many: squiggle differs (covers excess args) — defer to a future extension
        val nameNode = callee.name
        val start = nameNode.pos
        val length = nameNode.text.length
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = mutableListOf<Diagnostic>()
        if (argCount < params.size) {
            val missingSym = params[argCount]
            val missingParam = missingSym.valueDeclaration as? Parameter
            val pname = missingParam?.name as? Identifier
            if (pname != null && missingParam.name !is ObjectBindingPattern && missingParam.name !is ArrayBindingPattern) {
                val (rLine, rChar) = getLineAndCharacterOfPosition(source, pname.pos)
                relatedInfo.add(Diagnostic(
                    message = "An argument for '${pname.text}' was not provided.",
                    category = DiagnosticCategory.Message,
                    code = 6210,
                    fileName = fileName,
                    line = rLine,
                    character = rChar,
                    start = pname.pos,
                    length = pname.text.length,
                ))
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $argCount.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    /**
     * 16.4cs: TS6234 — emit when a call's callee is `recv.prop()` and `prop` is a
     * `get` accessor (no callable companion). Squiggle on the property name; chain
     * uses the apparent type's display name ("Number" for `number`, etc.).
     */
    private fun checkTs6234GetAccessorCall(
        expr: CallExpression,
        calleeType: Type,
        source: String,
        fileName: String,
    ): Boolean {
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        val recvType = try { getTypeOfExpression(callee.expression) } catch (_: StackOverflowError) { return false }
        if (recvType === anyType || recvType === errorType) return false
        val apparent = getApparentType(recvType)
        val prop = getPropertyOfType(apparent, callee.name.text) ?: return false
        val decls = prop.declarations
        if (decls.isEmpty()) return false
        var hasGetter = false
        for (d in decls) {
            when (d) {
                is GetAccessor -> hasGetter = true
                is SetAccessor -> { /* getter+setter pair still qualifies */ }
                else -> return false
            }
        }
        if (!hasGetter) return false
        val name = callee.name
        val start = name.pos
        val length = name.text.length
        if (length <= 0) return false
        val displayType = typeToString(getApparentType(calleeType))
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This expression is not callable because it is a 'get' accessor. Did you mean to use it without '()'?",
            category = DiagnosticCategory.Error,
            code = 6234,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf("  Type '$displayType' has no call signatures."),
        ))
        return true
    }

    /**
     * Check if a signature belongs to an overloaded function/method with an implementation.
     * Returns a TS2793 related diagnostic pointing to the implementation, or null.
     * Uses the signature's declaration to find the implementation among sibling declarations.
     */
    private fun getOverloadImplementationRelated(sig: Signature, source: String, fileName: String): Diagnostic? {
        val overloadDecl = sig.declaration ?: return null
        // For functions, look up the symbol by name
        if (overloadDecl is FunctionDeclaration) {
            val name = overloadDecl.name?.text ?: return null
            val symbol = globals[name] ?: currentFileLocals?.get(name) ?: return null
            return getImplRelatedFromDecls(symbol.declarations, source, fileName)
        }
        // For methods, find the containing class and search for sibling methods with same name
        if (overloadDecl is MethodDeclaration) {
            val methodName = (overloadDecl.name as? Identifier)?.text ?: return null
            // Search source files for a class containing this method declaration
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findImplementationInStatements(result.sourceFile.statements, methodName, overloadDecl)
                if (implDecl != null) {
                    return makeTs2793Diagnostic(implDecl, source, fileName)
                }
            }
        }
        // 17.91: Constructor overloads — find the containing class and the FIRST
        // constructor implementation. The first impl is the conventional anchor
        // for TS2793 even when multiple impls exist (which themselves emit TS2392).
        if (overloadDecl is Constructor) {
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findCtorImplementationInStatements(result.sourceFile.statements, overloadDecl)
                if (implDecl != null) {
                    return makeTs2793Diagnostic(implDecl, source, fileName)
                }
            }
        }
        return null
    }

    private fun findCtorImplementationInStatements(stmts: List<Statement>, overloadDecl: Constructor): Constructor? {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    var foundOverload = false
                    var hasBodylessOverload = false
                    var firstImpl: Constructor? = null
                    for (member in stmt.members) {
                        if (member !is Constructor) continue
                        if (member === overloadDecl) foundOverload = true
                        if (member.body == null) hasBodylessOverload = true
                        if (member.body != null && firstImpl == null) firstImpl = member
                    }
                    if (foundOverload && hasBodylessOverload && firstImpl != null) return firstImpl
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val result = findCtorImplementationInStatements(body.statements, overloadDecl)
                        if (result != null) return result
                    }
                }
                else -> {}
            }
        }
        return null
    }

    /** Search statements for a class/interface containing the given overload and its implementation. */
    private fun findImplementationInStatements(stmts: List<Statement>, methodName: String, overloadDecl: Node): MethodDeclaration? {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // 17.76: Require at least one body-less overload-sig declaration AND
                    // a separate body-having implementation. A single method with a body
                    // is NOT an overload pair — without this gate, a bare `bar(x: T) {}`
                    // emits TS2793 "implementation would have succeeded" pointing to
                    // itself (cf. genericOfACloduleType1/2_ts).
                    var foundOverload = false
                    var hasBodylessOverload = false
                    var impl: MethodDeclaration? = null
                    for (member in stmt.members) {
                        if (member !is MethodDeclaration) continue
                        val name = (member.name as? Identifier)?.text ?: continue
                        if (name != methodName) continue
                        if (member === overloadDecl) foundOverload = true
                        if (member.body == null) hasBodylessOverload = true
                        if (member.body != null) impl = member
                    }
                    if (foundOverload && hasBodylessOverload && impl != null) return impl
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val result = findImplementationInStatements(body.statements, methodName, overloadDecl)
                        if (result != null) return result
                    }
                }
                else -> {}
            }
        }
        return null
    }

    private fun getImplRelatedFromDecls(decls: List<Node>, source: String, fileName: String): Diagnostic? {
        val hasOverload = decls.any { d ->
            (d is MethodDeclaration && d.body == null) || (d is FunctionDeclaration && d.body == null)
        }
        val implDecl = decls.firstOrNull { d ->
            (d is MethodDeclaration && d.body != null) || (d is FunctionDeclaration && d.body != null)
        }
        if (!hasOverload || implDecl == null) return null
        return makeTs2793Diagnostic(implDecl, source, fileName)
    }

    private fun makeTs2793Diagnostic(implDecl: Node, source: String, fileName: String): Diagnostic {
        // Point to the function/method name, spanning to the body start.
        // For Constructor, point to the `constructor` keyword (no name node).
        val namePos = when (implDecl) {
            is FunctionDeclaration -> implDecl.name?.pos ?: implDecl.pos
            is MethodDeclaration -> (implDecl.name as? Identifier)?.pos ?: implDecl.pos
            is Constructor -> {
                val kwStart = source.indexOf("constructor", startIndex = implDecl.pos)
                if (kwStart in implDecl.pos..<implDecl.end) kwStart else implDecl.pos
            }
            else -> implDecl.pos
        }
        val implEnd = when (implDecl) {
            is MethodDeclaration -> implDecl.body?.pos ?: implDecl.end
            is FunctionDeclaration -> implDecl.body?.pos ?: implDecl.end
            is Constructor -> implDecl.body?.pos ?: implDecl.end
            else -> implDecl.end
        }
        val implLength = implEnd - namePos
        val (implLine, implChar) = getLineAndCharacterOfPosition(source, namePos)
        return Diagnostic(
            message = "The call would have succeeded against this implementation, but implementation signatures of overloads are not externally visible.",
            category = DiagnosticCategory.Message,
            code = 2793,
            fileName = fileName,
            line = implLine,
            character = implChar,
            start = namePos,
            length = implLength,
        )
    }

    /**
     * For a TS2769 overload error caused by a property type mismatch,
     * generate TS6500 related info: "The expected type comes from property 'X'
     * which is declared here on type 'Y'".
     * Points to the property declaration in the parameter's type literal.
     */
    private fun getPropertySourceRelated(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
    ): Diagnostic? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            // Dig through array types to get to the element type
            val (actualArg, actualParamType) = unwrapArrayArg(arg, paramType) ?: Pair(arg, paramType)
            if (actualArg !is ObjectLiteralExpression || actualParamType !is Type.Object) continue
            resolveStructuredTypeMembers(actualParamType)
            val targetProps = actualParamType.properties ?: continue
            val argType = getTypeOfExpression(actualArg) as? Type.Object ?: continue
            for (targetProp in targetProps) {
                val sourceProp = argType.members?.get(targetProp.name) ?: continue
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    // Found the mismatched property — point to its declaration in the param type
                    val propDecl = targetProp.declarations.firstOrNull() ?: continue
                    val propName = targetProp.name
                    val propPos = when (propDecl) {
                        is PropertyDeclaration -> propDecl.name.pos
                        is PropertyAssignment -> propDecl.name.pos
                        else -> propDecl.pos
                    }
                    val propLength = propName.length
                    // Get the containing type display name
                    val typeDisplay = typeToString(actualParamType)
                    val (propLine, propChar) = getLineAndCharacterOfPosition(source, propPos)
                    return Diagnostic(
                        message = "The expected type comes from property '$propName' which is declared here on type '$typeDisplay'",
                        category = DiagnosticCategory.Message,
                        code = 6500,
                        fileName = fileName,
                        line = propLine,
                        character = propChar,
                        start = propPos,
                        length = propLength,
                    )
                }
            }
        }
        return null
    }

    /**
     * For a TS2769 overload error caused by a MISSING property,
     * generate TS2728 related info: "'X' is declared here."
     * Points to the property declaration in the parameter's type literal.
     */
    private fun getMissingPropertyDeclaredHere(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
    ): Diagnostic? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val (actualArg, actualParamType) = unwrapArrayArg(arg, paramType) ?: Pair(arg, paramType)
            if (actualParamType !is Type.Object) continue
            resolveStructuredTypeMembers(actualParamType)
            val targetProps = actualParamType.properties ?: continue
            val argType = getTypeOfExpression(actualArg)
            if (argType !is Type.Object) continue
            for (targetProp in targetProps) {
                if (isOptionalProperty(targetProp)) continue
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    // Found missing property — point to its declaration
                    val propDecl = targetProp.declarations.firstOrNull() ?: continue
                    val propPos = when (propDecl) {
                        is PropertyDeclaration -> propDecl.name.pos
                        else -> propDecl.pos
                    }
                    val propName = targetProp.name
                    val (propLine, propChar) = getLineAndCharacterOfPosition(source, propPos)
                    return Diagnostic(
                        message = "'$propName' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = fileName,
                        line = propLine,
                        character = propChar,
                        start = propPos,
                        length = propName.length,
                    )
                }
            }
        }
        return null
    }

    /**
     * Get the implementation signature for a function/method that has overloads.
     * Returns null if no implementation exists.
     */
    private fun getImplementationSignature(
        overloadSig: Signature,
        source: String,
        fileName: String,
    ): Signature? {
        val overloadDecl = overloadSig.declaration ?: return null
        if (overloadDecl is FunctionDeclaration) {
            val name = overloadDecl.name?.text ?: return null
            val symbol = globals[name] ?: currentFileLocals?.get(name) ?: return null
            val implDecl = symbol.declarations.filterIsInstance<FunctionDeclaration>()
                .find { it.body != null } ?: return null
            val returnType = implDecl.type?.let { getTypeFromTypeNode(it) } ?: anyType
            return Signature(
                declaration = implDecl,
                parameters = getParameterSymbols(implDecl.parameters),
                resolvedReturnType = returnType,
                minArgumentCount = implDecl.parameters.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                },
            )
        }
        // 17.137a: Method overloads — find the impl among sibling methods of the
        // same class. Mirrors the existing `findImplementationInStatements` walker
        // used by `getOverloadImplementationRelated`. Used as the TS2793 gate so
        // tests like `overloadErrorMatchesImplementationElaboaration` (impl is
        // generic `<T>(event: T)`) get a non-null implSig — the existing fallback
        // returned null for methods, leaving the TS2793 gate without enough info.
        if (overloadDecl is MethodDeclaration) {
            val methodName = (overloadDecl.name as? Identifier)?.text ?: return null
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findImplementationInStatements(
                    result.sourceFile.statements, methodName, overloadDecl,
                ) ?: continue
                val returnType = implDecl.type?.let { getTypeFromTypeNode(it) } ?: anyType
                return Signature(
                    declaration = implDecl,
                    parameters = getParameterSymbols(implDecl.parameters),
                    resolvedReturnType = returnType,
                    minArgumentCount = implDecl.parameters.count {
                        !it.questionToken && !it.dotDotDotToken && it.initializer == null
                    },
                )
            }
        }
        // 17.91: Constructor overloads — find the FIRST impl among sibling constructors
        // in the containing class. Used as the TS2793 "would have succeeded" gate.
        if (overloadDecl is Constructor) {
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findCtorImplementationInStatements(result.sourceFile.statements, overloadDecl)
                    ?: continue
                return Signature(
                    declaration = implDecl,
                    parameters = getParameterSymbols(implDecl.parameters),
                    resolvedReturnType = overloadSig.resolvedReturnType,
                    minArgumentCount = implDecl.parameters.count {
                        !it.questionToken && !it.dotDotDotToken && it.initializer == null
                    },
                )
            }
        }
        return null
    }

    /**
     * Check whether the implementation signature's own type-param constraints accept
     * the given resolved type-args. Used as a TS2793 gate — when the user calls
     * `foo<X>(args)` with explicit type-args and the impl's type-param has a constraint
     * that `X` doesn't satisfy (e.g. impl is `foo<T extends String>(test: any)` and
     * caller passes `<Date>`), the impl wouldn't have succeeded either, so the
     * "implementation would have matched" related info should be suppressed.
     *
     * Returns true when constraints are satisfied (or no constraints / mismatched arity
     * / resolution errors — conservative default to allow TS2793).
     */
    private fun implTypeArgConstraintsSatisfied(
        implSig: Signature,
        resolvedTypeArgs: List<Type>,
    ): Boolean {
        val decl = implSig.declaration ?: return true
        val tpNodes = when (decl) {
            is FunctionDeclaration -> decl.typeParameters
            is MethodDeclaration -> decl.typeParameters
            else -> null
        } ?: return true
        if (tpNodes.size != resolvedTypeArgs.size) return true
        for (i in tpNodes.indices) {
            val constraintNode = tpNodes[i].constraint ?: continue
            try {
                val constraint = getTypeFromTypeNode(constraintNode)
                if (constraint === errorType || constraint === anyType) continue
                if (!checkTypeRelatedTo(resolvedTypeArgs[i], constraint, assignableRelation)) {
                    return false
                }
            } catch (_: StackOverflowError) { /* skip */ }
        }
        return true
    }

    /**
     * If arg is ArrayLiteral and paramType is Array<T>, return the first element
     * and the element type T. Otherwise return null.
     */
    private fun unwrapArrayArg(arg: Expression, paramType: Type): Pair<Expression, Type>? {
        if (arg !is ArrayLiteralExpression) return null
        if (paramType !is Type.Reference || paramType.target?.symbol?.name != "Array") return null
        val elemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
        val firstElem = arg.elements.firstOrNull() ?: return null
        if (firstElem is SpreadElement) return null
        return Pair(firstElem, elemType)
    }

    /**
     * Check argument types for a NewExpression against the construct signature.
     */
    private fun checkSingleNewExpressionTypes(expr: NewExpression, source: String, fileName: String) {
        // 16.4fd: `new []` — empty array literal is not constructable.
        // Narrow to empty array literal — non-empty would need element-type
        // resolution for the chain display.
        if (expr.expression is ArrayLiteralExpression && (expr.expression as ArrayLiteralExpression).elements.isEmpty()) {
            val arr = expr.expression as ArrayLiteralExpression
            val close = source.indexOf(']', arr.pos)
            val length = if (close >= arr.pos) close + 1 - arr.pos else 2
            val (line, character) = getLineAndCharacterOfPosition(source, arr.pos)
            diagnostics.add(Diagnostic(
                message = "This expression is not constructable.",
                category = DiagnosticCategory.Error,
                code = 2351,
                fileName = fileName,
                line = line,
                character = character,
                start = arr.pos,
                length = length,
                messageChain = listOf("  Type 'never[]' has no construct signatures."),
            ))
            return
        }
        // 17.221: TS2674 — protected constructor accessibility. When `new ClassName(...)`
        // resolves to a class whose effective constructor (own or inherited) is declared
        // `protected`, the call must be inside the declaring class or one of its subclasses.
        // Squiggle covers the full `new` expression. Only fires for bare Identifier callees
        // with a resolvable class symbol.
        if (expr.expression is Identifier) {
            val ident = expr.expression as Identifier
            val classSym = globals[ident.text]
            if (classSym != null && classSym.declarations.any { it is ClassDeclaration }) {
                val ctorInfo = findEffectiveConstructorVisibility(classSym)
                if (ctorInfo != null && ctorInfo.first == ModifierFlag.Protected) {
                    val declaringClass = ctorInfo.second
                    val accessible = callWalkerClassStack.any { enclosing ->
                        classExtendsOrIs(enclosing, declaringClass)
                    }
                    if (!accessible) {
                        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                        val length = expressionTrueEnd(expr) - expr.pos
                        diagnostics.add(Diagnostic(
                            message = "Constructor of class '${declaringClass.name}' is protected and only accessible within the class declaration.",
                            category = DiagnosticCategory.Error,
                            code = 2674,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = expr.pos,
                            length = length,
                        ))
                    }
                }
            }
        }
        val args = expr.arguments ?: return
        val calleeType = getCalleeType(expr.expression)
        if (calleeType === anyType || calleeType === errorType) return
        // B60.15: union callee for `new` — mirror of B60.14 for TS2349 with three cases:
        //   (a) all constituents non-constructable → "No constituent ... is constructable."
        //   (b) some non-constructable → "Not all constituents ... are constructable." + first missing display
        //   (c) all constructable but sigs differ structurally → "Each member ... has construct signatures, but none ... compatible..."
        if (calleeType is Type.Union) {
            val constituents = calleeType.types
            val nonCtor = constituents.filter { getConstructSignaturesOfType(it).isEmpty() }
            val unionDisplay = typeToString(calleeType)
            val ce = expr.expression
            val (start, length) = run {
                val s = ce.pos
                Pair(s, expressionTrueEnd(ce) - s)
            }
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                if (nonCtor.isNotEmpty() && nonCtor.size == constituents.size) {
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error, code = 2351,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf("  No constituent of type '$unionDisplay' is constructable."),
                    ))
                    return
                }
                if (nonCtor.isNotEmpty() && nonCtor.size != constituents.size) {
                    val missingDisplay = typeToString(nonCtor[0])
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error, code = 2351,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf(
                            "  Not all constituents of type '$unionDisplay' are constructable.",
                            "    Type '$missingDisplay' has no construct signatures.",
                        ),
                    ))
                    return
                }
                if (nonCtor.isEmpty() && constituents.size >= 2) {
                    // All constructable; check pairwise sig compat heuristic
                    val sigsList = constituents.map { getConstructSignaturesOfType(it).firstOrNull() }
                    val hasNullSig = sigsList.any { it == null }
                    if (!hasNullSig) {
                        val sigs = sigsList.map { it!! }
                        val differ = run {
                            for (i in sigs.indices) for (j in i + 1 until sigs.size) {
                                val s1 = sigs[i]; val s2 = sigs[j]
                                if ((s1.typeParameters?.size ?: 0) != (s2.typeParameters?.size ?: 0)) return@run true
                                if (s1.parameters.size != s2.parameters.size) return@run true
                                for (k in s1.parameters.indices) {
                                    val t1 = try { getTypeOfSymbol(s1.parameters[k]) } catch (_: StackOverflowError) { return@run false }
                                    val t2 = try { getTypeOfSymbol(s2.parameters[k]) } catch (_: StackOverflowError) { return@run false }
                                    if (t1 !== t2) return@run true
                                }
                            }
                            false
                        }
                        if (differ) {
                            diagnostics.add(Diagnostic(
                                message = "This expression is not constructable.",
                                category = DiagnosticCategory.Error, code = 2351,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                messageChain = listOf(
                                    "  Each member of the union type '$unionDisplay' has construct signatures, but none of those signatures are compatible with each other.",
                                ),
                            ))
                            return
                        }
                    }
                }
            }
        }
        // Get construct signatures
        val signatures = getConstructSignaturesOfType(calleeType)
        if (signatures.isEmpty()) {
            // 17.170: TS2351 — `new x()` where x is a plain instance variable (not
            // a class identifier). Class-instance Type.Interface has no construct
            // signatures (those live on the static side). Squiggle on the callee.
            // Conservative gate: only fire when the callee is a bare Identifier
            // resolving to a Variable symbol whose type is a Type.Interface with a
            // class symbol — definitively a "new on instance" case.
            val ce = expr.expression
            if (ce is Identifier) {
                val sym = globals[ce.text]
                val isVarOrParam = sym != null && sym.flags.hasAny(SymbolFlags.Variable) &&
                    !sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Function)
                if (isVarOrParam && calleeType is Type.Interface) {
                    val typeName = calleeType.symbol?.name ?: typeToString(calleeType)
                    val (line, character) = getLineAndCharacterOfPosition(source, ce.pos)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error,
                        code = 2351,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = ce.pos,
                        length = ce.text.length,
                        messageChain = listOf("  Type '$typeName' has no construct signatures."),
                    ))
                }
            }
            return
        }
        // 17.21: When the class has its own TypeParameters (e.g. `class List<T>`)
        // AND the call site has explicit type arguments (e.g. `new List<T>(...)`),
        // build a fresh signature with each param's type re-resolved under the
        // class TypeParam scope. The original sig's params may have been cached
        // as `errorType` from an earlier eager-pass resolution that ran with no
        // scope — re-resolving here lets the 17.20 null-vs-unconstrained-TypeParam
        // path fire on the bare `T` parameter. We mint fresh Symbols + cache
        // entries so the original cache isn't disturbed (which would break
        // `instantiateSignature`-produced sigs in `handleSuperMethodCall`).
        //
        // The explicit-type-args gate is critical: without it, `new D(null)`
        // where `class D<T> { constructor(x: T) }` would FP-emit TS2345 because
        // we don't perform generic argument inference (TypeScript would infer
        // T = null and silently accept). With explicit type args, TypeScript
        // bypasses inference so a bare `<T>` (unconstrained) → null arg fires.
        //
        // Also skip when any explicit type arg resolves to errorType — that
        // means the call site can't actually access the type (e.g. inside a
        // static method, a class-level T is out of scope and TypeScript already
        // emits TS2302; emitting TS2345 too would double-fault).
        val classTypeParams = (calleeType as? Type.Interface)?.typeParameters
        val hasExplicitTypeArgs = !expr.typeArguments.isNullOrEmpty()
        val resolvedTypeArgs: List<Type>? = if (hasExplicitTypeArgs) {
            expr.typeArguments!!.map { tn ->
                try { getTypeFromTypeNode(tn) } catch (_: StackOverflowError) { errorType }
            }
        } else null
        val explicitArgsAllResolve = resolvedTypeArgs != null && resolvedTypeArgs.none { it === errorType }
        val effectiveSigs: List<Signature> = if (!classTypeParams.isNullOrEmpty() && explicitArgsAllResolve) {
            val reresolved = signatures.map { sig -> reresolveSigParamsUnderClassScope(sig, classTypeParams) }
            // B74.5: After re-resolving params under class scope, substitute the class
            // TypeParams with the explicit type arguments. Without this, a static method
            // `MakeHead3<U>()` calling `new List<U>(...)` displays the param type as the
            // class's `T` (the un-substituted classT) instead of the supplied `U`. The
            // class TPs and explicit type args have matching arity (guaranteed by the
            // type-arg parser/resolver; if mismatched, we'd have emitted TS2558 earlier).
            if (classTypeParams.size == resolvedTypeArgs!!.size) {
                val mapper = createTypeMapper(classTypeParams, resolvedTypeArgs)
                reresolved.map { sig -> instantiateSignature(sig, mapper) }
            } else reresolved
        } else signatures
        if (effectiveSigs.size == 1) {
            checkArgumentsAgainstSignature(args, effectiveSigs[0], source, fileName)
        } else {
            checkArgumentsAgainstOverloads(args, effectiveSigs, source, fileName, expr.expression)
        }
    }

    /**
     * 17.21: Build a fresh [Signature] with each parameter's type re-resolved
     * under [classTypeParams] in scope. Mints new parameter Symbols and stores
     * their types in [symbolTypes] so [getTypeOfSymbol] returns the re-resolved
     * type without re-running the AST resolution path. Preserves the original
     * symbols' cache entries (used by `instantiateSignature` in [handleSuperMethodCall]).
     */
    private fun reresolveSigParamsUnderClassScope(
        sig: Signature,
        classTypeParams: List<Type.TypeParam>,
    ): Signature {
        val savedScope = currentTypeParamScope
        val newScope = (savedScope?.toMutableMap() ?: mutableMapOf())
        for (tp in classTypeParams) tp.symbol?.name?.let { newScope[it] = tp }
        currentTypeParamScope = newScope
        try {
            var changed = false
            val freshParams = sig.parameters.map { p ->
                val decl = p.valueDeclaration as? Parameter
                val typeNode = decl?.type
                if (typeNode == null) return@map p
                val freshType = try { getTypeFromTypeNode(typeNode) } catch (_: StackOverflowError) { return@map p }
                if (freshType === errorType) return@map p
                val cached = symbolTypes[p.id]
                if (cached === freshType) return@map p
                changed = true
                val freshSym = Symbol(p.flags, p.name)
                freshSym.declarations.addAll(p.declarations)
                freshSym.valueDeclaration = p.valueDeclaration
                freshSym.parent = p.parent
                symbolTypes[freshSym.id] = freshType
                freshSym
            }
            return if (!changed) sig else Signature(
                declaration = sig.declaration,
                typeParameters = sig.typeParameters,
                parameters = freshParams,
                resolvedReturnType = sig.resolvedReturnType,
                minArgumentCount = sig.minArgumentCount,
            )
        } finally {
            currentTypeParamScope = savedScope
        }
    }

    /**
     * Try each overload signature in order. If any overload accepts all arguments, no error.
     * If none succeed, report TS2345 against the last overload (TypeScript convention).
     *
     * 17.15b: [callee] is the call/new expression's callee. When provided AND the failing
     * arg is a fn-type-vs-fn-type mismatch (TypeScript treats this as a "more fundamental"
     * error pointing at the callee), TS2769 is squiggled at the callee position
     * (e.g. `x3` for `x3(...)`) instead of the failing argument.
     */
    private fun checkArgumentsAgainstOverloads(
        args: List<Expression>,
        signatures: List<Signature>,
        source: String,
        fileName: String,
        callee: Expression? = null,
    ) {
        // Filter overloads by arity — if only one matches by arity,
        // check it as a single signature (TS2345, not TS2769).
        val arityMatches = signatures.filter { sig ->
            val params = sig.parameters
            val hasRest = params.isNotEmpty() && params.last().declarations.any {
                it is Parameter && it.dotDotDotToken
            }
            args.size >= sig.minArgumentCount && (args.size <= params.size || hasRest)
        }
        if (arityMatches.size == 1) {
            // Check TS2793: only add implementation related info if the implementation
            // would have actually matched the arguments (e.g. impl has `any` param type).
            var implRelated: Diagnostic? = null
            val implRelatedCandidate = getOverloadImplementationRelated(arityMatches[0], source, fileName)
            if (implRelatedCandidate != null) {
                val implSig = getImplementationSignature(arityMatches[0], source, fileName)
                if (implSig != null && allArgumentsMatch(args, implSig, bivariantFnParams = true)) {
                    implRelated = implRelatedCandidate
                }
            }
            checkArgumentsAgainstSignature(args, arityMatches[0], source, fileName, implRelated)
            return
        }
        for (sig in signatures) {
            if (allArgumentsMatch(args, sig)) return // found a matching overload
        }
        // None matched — emit TS2769 with errors from each overload
        // Collect the first argument mismatch per overload for the error chain
        val overloadErrors = mutableListOf<Triple<Int, Signature, String>>() // (overloadIndex, sig, errorMsg)
        for ((idx, sig) in signatures.withIndex()) {
            val errorMsg = getFirstArgumentError(args, sig)
            if (errorMsg != null) {
                overloadErrors.add(Triple(idx + 1, sig, errorMsg))
            }
        }
        if (overloadErrors.isNotEmpty()) {
            // 17.15b: When ANY overload's first failing arg is a fn-type-vs-fn-type
            // mismatch and we have a callee, point the squiggle at the callee instead
            // of the failing argument — TypeScript treats fn-vs-fn arg mismatch as a
            // more fundamental error and squiggles the callee identifier.
            // 17.77: Refinement — only switch to callee when overloads fail at
            // DIFFERENT argument positions (e.g. overload 1 fails on arg[1]:fn,
            // overload 2 fails on arg[0]:primitive). When ALL overloads fail at
            // the SAME arg position (e.g. both fail on the arrow-fn arg),
            // TypeScript squiggles the argument, not the callee. Cf.
            // signatureLengthMismatchInOverload_ts where two overloads both fail
            // at arg[0] (arity vs param-type) — expected squiggle is the arg.
            val anyFnFnMismatch = callee != null && overloadErrors.any { (_, sig, _) ->
                getFirstFailingFnTypeArgPair(args, sig) != null
            }
            // B50.11: ANY overload that fails on a NON-function-vs-function shape
            // (e.g. function arg vs string param) suggests heterogeneous overload
            // shapes — TypeScript prefers callee squiggle in that case. Mirrors
            // `overloadsWithProvisionalErrors_ts` baseline.
            val hasNonFnFnFailing = callee != null && overloadErrors.any { (_, sig, _) ->
                getFirstFailingFnTypeArgPair(args, sig) == null
            }
            // Collect first-failing-arg position per overload. If all overloads
            // share the same failing position, use that — otherwise fall back to
            // callee for fn-vs-fn cases.
            val perOverloadPos = overloadErrors.map { (_, sig, _) ->
                getFirstFailingArgPosition(args, sig)
            }
            val allSamePos = perOverloadPos.isNotEmpty() && perOverloadPos.all { it == perOverloadPos.first() }
            val pos: Pair<Int, Int>? = if (anyFnFnMismatch && callee != null && (!allSamePos || hasNonFnFnFailing)) {
                Pair(callee.pos, expressionTrueEnd(callee) - callee.pos)
            } else {
                getFirstFailingArgPosition(args, signatures.last())
            }
            if (pos != null) {
                val (argStart, argLength) = pos
                val (line, character) = getLineAndCharacterOfPosition(source, argStart)
                val chain = mutableListOf<String>()
                val totalOverloads = signatures.size
                for ((overloadIdx, sig, errorMsg) in overloadErrors) {
                    // 17.85: Use signatureToStringColon (which handles optional
                    // params via formatParameter — `?:` + `| undefined` widening)
                    // for TS2769 overload chain display, instead of the simpler
                    // 1-arg signatureToString which omitted both. Cf.
                    // namespaceMergedWithFunctionWithOverloadsUsage_ts where
                    // `(opts?: Foo.Whatever)` should display as
                    // `'(opts?: Whatever | undefined): void'`.
                    val sigStr = signatureToStringColon(sig, isConstruct = false)
                    chain.add("  Overload $overloadIdx of $totalOverloads, '$sigStr', gave the following error.")
                    chain.add("    $errorMsg")
                    // 17.15b: Add deeper "Types of parameters X and Y are incompatible." chain
                    // when the failing arg is a function type vs function-type param.
                    val firstFailingPair = getFirstFailingFnTypeArgPair(args, sig)
                    if (firstFailingPair != null) {
                        val (argFnType, paramFnType) = firstFailingPair
                        val nested = getFunctionMismatchElaboration(argFnType, paramFnType)
                        chain.addAll(nested.map { "    $it" })
                    }
                }
                // Collect related info: TS6500/TS2728 for property source, TS2793 for implementation
                val related = mutableListOf<Diagnostic>()
                for ((_, sig, errorMsg) in overloadErrors) {
                    if (errorMsg.startsWith("Object literal may only specify known properties")) {
                        // Excess-property errors get no TS2728/TS6500 related info.
                        continue
                    }
                    if (errorMsg.startsWith("Property '") && errorMsg.contains("is missing")) {
                        // TS2728: "'X' is declared here." for missing property errors
                        val ts2728 = getMissingPropertyDeclaredHere(args, sig, source, fileName)
                        if (ts2728 != null) related.add(ts2728)
                    } else {
                        // TS6500: "The expected type comes from property 'X' which is declared here on type 'Y'"
                        val ts6500 = getPropertySourceRelated(args, sig, source, fileName)
                        if (ts6500 != null) related.add(ts6500)
                    }
                }
                // TS2793: only if implementation would have matched the arguments
                val implRelated = getOverloadImplementationRelated(signatures[0], source, fileName)
                if (implRelated != null) {
                    // Check if implementation actually accepts these args
                    val implSig = getImplementationSignature(signatures[0], source, fileName)
                    if (implSig != null && allArgumentsMatch(args, implSig, bivariantFnParams = true)) {
                        related.add(implRelated)
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "No overload matches this call.",
                    category = DiagnosticCategory.Error,
                    code = 2769,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = argStart,
                    length = argLength,
                    messageChain = chain,
                    relatedInformation = related,
                ))
                return
            }
        }
        // Fallback: no position found despite errors — try fallback TS2345
        val lastSig = signatures.last()
        checkArgumentsAgainstSignature(args, lastSig, source, fileName)
    }

    /**
     * 17.15b: For overload error chain elaboration. When the first failing arg is a
     * function-type vs function-type-param, return the (argType, paramType) pair so the
     * caller can append the deeper "Types of parameters X and Y are incompatible." chain
     * via [getFunctionMismatchElaboration]. Returns null when the first failing arg is
     * not a fn-vs-fn mismatch (or none fails).
     */
    private fun getFirstFailingFnTypeArgPair(args: List<Expression>, sig: Signature): Pair<Type.Object, Type.Object>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // Both anonymous Type.Object with non-empty callSignatures = fn-type vs fn-type.
                if (argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface &&
                    argType.symbol == null && !argType.callSignatures.isNullOrEmpty() &&
                    paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface &&
                    paramType.symbol == null && !paramType.callSignatures.isNullOrEmpty()
                ) {
                    return Pair(argType, paramType)
                }
                return null
            }
        }
        return null
    }

    /** Get the first argument type error message for a signature, or null if all match. */
    private fun getFirstArgumentError(args: List<Expression>, sig: Signature): String? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // For object literal args, try to find the specific mismatched property
                val propError = getObjectLiteralPropertyError(arg, argType, paramType)
                if (propError != null) return propError
                val displayArgType = getWidenedLiteralType(argType)
                return "Argument of type '${typeToString(displayArgType)}' is not assignable to parameter of type '${typeToString(paramType)}'."
            }
        }
        return null
    }

    /**
     * For an object literal argument that doesn't match a target object type,
     * find the specific property that mismatches and return an elaborated error.
     * e.g., "Type 'string' is not assignable to type 'number'."
     */
    private fun getObjectLiteralPropertyError(
        arg: Expression,
        argType: Type,
        paramType: Type,
    ): String? {
        if (arg !is ObjectLiteralExpression && arg !is ArrayLiteralExpression) return null
        // For array literal → array type: dig into element comparison
        if (arg is ArrayLiteralExpression && paramType is Type.Reference &&
            paramType.target?.symbol?.name == "Array") {
            val targetElemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
            for (elem in arg.elements) {
                if (elem is SpreadElement) continue
                val elemType = getTypeOfExpression(elem)
                if (elemType === anyType || elemType === errorType) continue
                if (!checkTypeRelatedTo(elemType, targetElemType, assignableRelation)) {
                    // Recurse: check if the element is an object literal with property mismatch
                    val inner = getObjectLiteralPropertyError(elem, elemType, targetElemType)
                    if (inner != null) return inner
                    val displayArgType = getWidenedLiteralType(elemType)
                    return "Type '${typeToString(displayArgType)}' is not assignable to type '${typeToString(targetElemType)}'."
                }
            }
            return null
        }
        // For object literal → object type: find first mismatched property
        if (arg is ObjectLiteralExpression && paramType is Type.Object) {
            resolveStructuredTypeMembers(paramType)
            val targetProps = paramType.properties ?: return null
            if (argType !is Type.Object) return null
            // Excess-property check first: object literals against object types without an
            // index signature get the stricter "Object literal may only specify known properties"
            // message at the first excess property (matching tsc).
            if (paramType.stringIndexInfo == null && paramType.numberIndexInfo == null) {
                val targetNames = targetProps.map { it.name }.toSet()
                for (prop in arg.properties) {
                    val name = when (val n = (prop as? PropertyAssignment)?.name
                        ?: (prop as? ShorthandPropertyAssignment)?.name
                        ?: (prop as? MethodDeclaration)?.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    if (name !in targetNames) {
                        return "Object literal may only specify known properties, and '$name' does not exist in type '${typeToString(paramType)}'."
                    }
                }
            }
            for (targetProp in targetProps) {
                val isOptional = isOptionalProperty(targetProp)
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    if (!isOptional) {
                        return "Property '${targetProp.name}' is missing in type '${typeToString(argType)}' but required in type '${typeToString(paramType)}'."
                    }
                    continue
                }
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    val displaySource = getWidenedLiteralType(sourcePropType)
                    return "Type '${typeToString(displaySource)}' is not assignable to type '${typeToString(targetPropType)}'."
                }
            }
        }
        return null
    }

    /**
     * Widen literal types to their base types for error message display.
     * TypeScript displays `true` as `boolean`, string literals as `string`, etc.
     */
    private fun getWidenedLiteralType(type: Type): Type {
        val f = type.flags
        if (f.hasAny(TypeFlags.BooleanLiteral)) return booleanType
        if (type is Type.StringLiteral) return stringType
        if (type is Type.NumberLiteral) return numberType
        if (type is Type.BigIntLiteral) return bigintType
        return type
    }

    /**
     * B70.1ext: For chain-display rendering: when `literalCandidate` is a literal type
     * AND `otherSide` is a non-matching primitive (different base), return the widened
     * form of `literalCandidate` so the chain message reads `'string' is not assignable
     * to 'number'` instead of `'"hi"' is not assignable to 'number'`. When bases match
     * (e.g. `'hi'` vs `string`, or `'hi'` vs `'bye'`), return the literal unchanged.
     */
    private fun widenLiteralForDifferentBaseDisplay(literalCandidate: Type, otherSide: Type): Type {
        val widened = getWidenedLiteralType(literalCandidate)
        if (widened === literalCandidate) return literalCandidate
        // widened is a primitive base (string/number/boolean/bigint). Only widen for
        // display when otherSide is a DIFFERENT primitive base (no shared base).
        val otherBase = getWidenedLiteralType(otherSide)
        if (otherBase === widened) return literalCandidate  // same base, keep literal
        // Different base — only widen if otherSide is a recognizable primitive,
        // not an object/union/intersection.
        val isOtherPrimitive = otherSide.flags.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or TypeFlags.BigInt
        ) && otherSide !is Type.StringLiteral && otherSide !is Type.NumberLiteral &&
            otherSide !is Type.BigIntLiteral && !otherSide.flags.hasAny(TypeFlags.BooleanLiteral)
        return if (isOtherPrimitive) widened else literalCandidate
    }

    /**
     * Get the position and length of the first failing argument for a signature.
     * For object literal/array literal arguments, dig into elements to find the
     * specific mismatched value (TypeScript squiggles the inner value, not the whole arg).
     */
    private fun getFirstFailingArgPosition(args: List<Expression>, sig: Signature): Pair<Int, Int>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // For object/array literals, find the inner mismatched expression
                val inner = findInnerMismatchPosition(arg, paramType)
                if (inner != null) return inner
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) return Pair(start, length)
            }
        }
        return null
    }

    /**
     * For an array/object literal arg, find the position of the specific inner
     * expression that causes the type mismatch. Returns (start, length) or null.
     */
    private fun findInnerMismatchPosition(arg: Expression, paramType: Type): Pair<Int, Int>? {
        // Array literal → array type: find the mismatched element
        if (arg is ArrayLiteralExpression && paramType is Type.Reference &&
            paramType.target?.symbol?.name == "Array") {
            val targetElemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
            for (elem in arg.elements) {
                if (elem is SpreadElement) continue
                val elemType = getTypeOfExpression(elem)
                if (elemType === anyType || elemType === errorType) continue
                if (!checkTypeRelatedTo(elemType, targetElemType, assignableRelation)) {
                    // Recurse into the element (might be an object literal)
                    val inner = findInnerMismatchPosition(elem, targetElemType)
                    if (inner != null) return inner
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length > 0) return Pair(start, length)
                }
            }
        }
        // Object literal → object type: find the mismatched property value
        if (arg is ObjectLiteralExpression && paramType is Type.Object) {
            resolveStructuredTypeMembers(paramType)
            val targetProps = paramType.properties ?: return null
            val argType = getTypeOfExpression(arg)
            if (argType !is Type.Object) return null
            // Excess-property: squiggle the FIRST excess property name (matching tsc).
            if (paramType.stringIndexInfo == null && paramType.numberIndexInfo == null) {
                val targetNames = targetProps.map { it.name }.toSet()
                for (prop in arg.properties) {
                    val nameNode = when (prop) {
                        is PropertyAssignment -> prop.name
                        is ShorthandPropertyAssignment -> prop.name
                        is MethodDeclaration -> prop.name
                        else -> continue
                    }
                    val name = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> continue
                    }
                    if (name !in targetNames) {
                        return Pair(nameNode.pos, name.length)
                    }
                }
            }
            for (targetProp in targetProps) {
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    // Missing property — squiggle the whole object literal
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) return Pair(start, length)
                    continue
                }
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    // Find the PropertyAssignment and squiggle the property NAME
                    for (prop in arg.properties) {
                        if (prop !is PropertyAssignment) continue
                        val propNameNode = prop.name
                        val propName = when (propNameNode) {
                            is Identifier -> propNameNode.text
                            is StringLiteralNode -> propNameNode.text
                            else -> continue
                        }
                        if (propName == targetProp.name) {
                            val start = propNameNode.pos
                            val length = propName.length
                            if (length > 0) return Pair(start, length)
                        }
                    }
                }
            }
        }
        return null
    }

    /** Format a signature for display in TS2769 messages: (param: type, ...): returnType */
    private fun signatureToString(sig: Signature): String {
        val params = sig.parameters.joinToString(", ") { param ->
            val paramType = getTypeOfSymbol(param)
            val typeStr = if (paramType === anyType) "any" else typeToString(paramType)
            // B9.5: source-slice rendering for binding-pattern synthesized params.
            val displayName = when (val name = (param.valueDeclaration as? Parameter)?.name) {
                is ObjectBindingPattern, is ArrayBindingPattern -> formatBindingPatternFromAst(name as Node)
                else -> param.name
            }
            "$displayName: $typeStr"
        }
        val returnType = sig.resolvedReturnType
        val returnStr = if (returnType != null && returnType !== anyType) typeToString(returnType) else "any"
        return "($params): $returnStr"
    }

    /**
     * Check if all arguments match a signature (no TS2345 errors would fire).
     * Returns true if all args are assignable to their corresponding param types.
     * For overload resolution, we check ALL types (not just simple checkable ones)
     * because we need to determine if any overload matches.
     *
     * B70.15: [bivariantFnParams] enables bivariant comparison for function-typed
     * arg/param pairs — used by TS2793 "would the impl have succeeded" gates under
     * `@strict: false`. TypeScript treats method parameter checking bivariantly when
     * `strictFunctionTypes` is off, so e.g. `(x: 'bye') => number` is accepted by
     * impl param `(x: string) => number`. Only enabled when [bivariantFnParams] is
     * true AND `strictExplicitlyFalse` is set — otherwise contravariant-only check.
     * Strict-mode overload resolution (the `allArgumentsMatch(args, sig)` matching
     * call in `checkArgumentsAgainstOverloads`) keeps the default (contravariant)
     * to avoid mis-matching overloads.
     */
    private fun allArgumentsMatch(
        args: List<Expression>,
        sig: Signature,
        bivariantFnParams: Boolean = false,
    ): Boolean {
        val params = sig.parameters
        // Check arity: too few arguments
        if (args.size < sig.minArgumentCount) return false
        // Check arity: too many arguments (unless last param is rest)
        val hasRestParam = params.isNotEmpty() && params.last().let { lastParam ->
            lastParam.declarations.any { d -> d is Parameter && d.dotDotDotToken }
        }
        if (args.size > params.size && !hasRestParam) return false
        val useBivariant = bivariantFnParams && options.strictExplicitlyFalse
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            // 17.137a: Free Type.TypeParam accepts any arg under TypeScript's
            // inference semantics (T would simply be inferred as the arg type).
            // Used by TS2793 gates that ask "would the impl signature have
            // accepted these args?" — the impl `<T>(event: T)` accepts anything.
            // Constrained TypeParams ALSO accept here conservatively; the relation
            // engine doesn't return useful results for `Source vs TypeParam(C)`
            // without a full instantiation pass, so erring toward "match" matches
            // pre-17.137a behavior for the TS2793 path (always emit) for generic
            // impls.
            if (paramType is Type.TypeParam) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // B70.15: Bivariant fallback for function-vs-function under @strict: false.
                // Also try reverse direction; if param accepts arg's shape going either way,
                // count as match. Only fires for anonymous function-typed Type.Object pairs
                // (both have callSignatures) so non-function mismatches still fail.
                if (useBivariant &&
                    argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface &&
                    !argType.callSignatures.isNullOrEmpty() &&
                    paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface &&
                    !paramType.callSignatures.isNullOrEmpty() &&
                    checkTypeRelatedTo(paramType, argType, assignableRelation)
                ) {
                    continue
                }
                return false
            }
        }
        return true
    }

    /**
     * Get the type of a callee expression for call/new checking.
     */
    private fun getCalleeType(expr: Expression): Type {
        return when (expr) {
            is Identifier -> {
                // Local scope (function params, block-scoped vars) shadows globals.
                // E.g. `function b1(b1: number) { b1(12); }` — the inner `b1` is the
                // param, not the outer function — so resolving via globals would
                // miss the primitive-callee case.
                currentLocalTypes[expr.text]?.let { return it }
                // 17.21: Namespace fallback so a class/fn declared inside `namespace M`
                // is reachable from a call/new inside another method in the same
                // namespace. Without this, `new List<T>(null)` inside
                // `namespace Editor { class ListFactory<T> { make() { ... } } }` would
                // bail at anyType and skip arg-type checking. Mirrors
                // `getTypeOfIdentifier`'s namespace fallback.
                lookupInInferenceNamespace(expr.text)?.let { return it }
                val symbol = globals[expr.text] ?: return anyType
                getTypeOfSymbol(symbol)
            }
            is PropertyAccessExpression -> getTypeOfPropertyAccess(expr)
            is ElementAccessExpression -> getTypeOfElementAccess(expr)
            is ParenthesizedExpression -> getCalleeType(expr.expression)
            is NonNullExpression -> getCalleeType(expr.expression)
            is SatisfiesExpression -> getCalleeType(expr.expression)
            is CallExpression -> try { getReturnTypeOfCallExpression(expr) } catch (_: StackOverflowError) { anyType }
            is NewExpression -> try { getReturnTypeOfNewExpression(expr) } catch (_: StackOverflowError) { anyType }
            else -> anyType
        }
    }

    /**
     * 17.221: Walks the class's extends chain to find the effective constructor's
     * accessibility modifier and its declaring class symbol. Returns null when no
     * constructor with `private` or `protected` is found (public or no explicit
     * constructor anywhere in chain).
     */
    private fun findEffectiveConstructorVisibility(classSym: Symbol): Pair<ModifierFlag, Symbol>? {
        val visited = mutableSetOf<Int>()
        var currentSym: Symbol? = classSym
        while (currentSym != null && visited.add(currentSym.id)) {
            val classDecl = currentSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                ?: return null
            val ownCtor = classDecl.members.firstOrNull { it is Constructor } as? Constructor
            if (ownCtor != null) {
                val mods = ownCtor.modifiers
                return when {
                    ModifierFlag.Private in mods -> ModifierFlag.Private to currentSym
                    ModifierFlag.Protected in mods -> ModifierFlag.Protected to currentSym
                    else -> null
                }
            }
            // No own constructor — walk to base class
            val extendsClause = classDecl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            val baseExpr = extendsClause?.types?.firstOrNull()?.expression
            val baseIdent = baseExpr as? Identifier ?: return null
            currentSym = globals[baseIdent.text]
        }
        return null
    }

    /**
     * 17.221: Returns true when `subClassSym` is `targetSym` itself, or extends it
     * (directly or transitively). Used for TS2674 protected-constructor accessibility.
     */
    private fun classExtendsOrIs(subClassSym: Symbol, targetSym: Symbol): Boolean {
        val visited = mutableSetOf<Int>()
        var current: Symbol? = subClassSym
        while (current != null && visited.add(current.id)) {
            if (current.id == targetSym.id) return true
            val classDecl = current.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                ?: return false
            val extendsClause = classDecl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            val baseExpr = extendsClause?.types?.firstOrNull()?.expression
            val baseIdent = baseExpr as? Identifier ?: return false
            current = globals[baseIdent.text]
        }
        return false
    }

    /**
     * Get call signatures from a type.
     */
    private fun getCallSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.callSignatures ?: emptyList()
        }
        if (type is Type.Union) {
            // Collect call signatures from all union constituents
            val allSigs = mutableListOf<Signature>()
            for (constituent in type.types) {
                allSigs.addAll(getCallSignaturesOfType(constituent))
            }
            return allSigs
        }
        return emptyList()
    }

    /**
     * Get construct signatures from a type.
     */
    private fun getConstructSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.constructSignatures ?: emptyList()
        }
        return emptyList()
    }

    /**
     * Check each argument against the corresponding parameter type.
     * Emits TS2345 for type mismatches.
     *
     * Conservative: only checks when both argument and parameter types are
     * well-understood (primitives, literals, intrinsics). Skips complex types
     * (interfaces, objects, unions, intersections) to avoid false positives
     * from incomplete structural comparison and missing generic instantiation.
     */
    private fun checkArgumentsAgainstSignature(
        args: List<Expression>,
        sigIn: Signature,
        source: String,
        fileName: String,
        implementationRelated: Diagnostic? = null,
        // Round 79l: true when [sigIn] is an instantiation of a GENERIC callee (the
        // call site already substituted explicit/inferred type args). Suppresses the
        // fine-grained TS2322-at-arrow-return conversion — for a generic-instantiated
        // callback param TypeScript keeps the coarse whole-argument TS2345.
        calleeGenericInstantiation: Boolean = false,
    ) {
        // 17.31a: Single-typeParam inference for non-overloaded sigs.
        // When the gate matches, instantiate the signature with the inferred T so
        // subsequent T-typed parameters are checked against the substituted type
        // instead of falling through the 16.4i bare-TypeParam continue. Eg.
        // `f<T>(x: T, y: T)` called with `f(1, "")` infers T=number from arg[0],
        // then arg[1]: "" vs number fires TS2345 via the standard path.
        // 17.31b: pass source/fileName so the helper can emit literal-preserving
        // TS2345 directly for context-sensitive sigs (function-type-T param).
        val sig = if (sigIn.typeParameters.isNullOrEmpty()) sigIn else {
            val mapper = tryInferSingleTypeParamFromArgs(sigIn, args, source, fileName)
            if (mapper != null) instantiateSignature(sigIn, mapper) else sigIn
        }
        val params = sig.parameters
        // 17.31c: track whether the standard loop emits a TS2345 so the
        // post-loop rest-args helper doesn't double-fire (TypeScript reports
        // only the first failing arg per call).
        val initialDiagCount = diagnostics.size
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break // extra args handled by TS2554
            // Skip spread arguments — complex handling
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            // 16.0b: contextual typing — set param type as context so arrow/function
            // arguments get their parameters typed from the expected signature.
            // B83.4g: also propagate the param type for ObjectLiteralExpression args
            // so getTypeOfObjectLiteral's per-property contextual push (B52.4) fires —
            // e.g. `f2({ toString: (s) => s })` against param `I { toString: (t: string)
            // => string }` types `s` as `string`, so the TS2345 source displays
            // `{ toString: (s: string) => string }` (not `(s: any) => any`).
            val savedContextual = contextualType
            val useCtx = paramType is Type.Object &&
                (arg is ArrowFunction || arg is FunctionExpression || arg is ObjectLiteralExpression)
            if (useCtx) contextualType = paramType
            // 17.67: contextual literal preservation for call args (extends 17.66's
            // var-decl init / assignment-RHS pattern). When the param's type contains
            // literal types and the arg is a literal expression, preserve the literal
            // type instead of widening to the primitive — matches TypeScript's
            // bidirectional contextual-typing rule for TS2345 source display.
            val argType = try {
                val widened = getTypeOfExpression(arg)
                if (propTypeContainsLiteral(paramType)) {
                    literalTypeOfExpression(arg) ?: widened
                } else widened
            } finally {
                if (useCtx) contextualType = savedContextual
            }
            if (argType === anyType || argType === errorType) continue
            // 16.0: contextual typing for array literal arguments — check each
            // element against the parameter's array element type. Catches
            // `foo([1, "a"])` where foo takes `number[]`.
            val isRestParam = (params[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
            if (!isRestParam && arg is ArrayLiteralExpression && paramType is Type.Reference &&
                paramType.target?.symbol?.name == "Array") {
                checkArrayLiteralElementsAgainstType(arg, paramType, source, fileName)
            }
            // 16.0a: excess property check for object literal arguments passed
            // to typed object parameters. Emits TS2353 and stops further arg checks.
            // Skip rest parameters — param type is an array wrapper, not the element type.
            // Intersection paramType: `attributes: PropertyDescriptor & ThisType<any>` — flatten
            // member-name set across constituents via collectTargetPropertyNames; emit TS2353
            // for ObjectLiteral excess props using the intersection's display name.
            if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.Intersection &&
                argType is Type.Object) {
                for (constituent in paramType.types) {
                    if (constituent is Type.Object) resolveStructuredTypeMembers(constituent)
                }
                val displayTarget = typeToString(paramType)
                if (checkExcessProperties(arg, argType, paramType, displayTarget, source, fileName)) {
                    break // TS2353 emitted — one error per call
                }
            }
            if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.Object) {
                try {
                    resolveStructuredTypeMembers(paramType)
                    // Only emit TS2353 if target has known named properties — skip
                    // empty object types, array types (properties list empty), and
                    // types with index signatures that accept arbitrary keys.
                    val hasTargetProps = !paramType.properties.isNullOrEmpty()
                    if (hasTargetProps && canUseTypeEngine(argType, paramType)) {
                        val displayTarget = typeToString(paramType)
                        if (checkExcessProperties(arg, argType, paramType, displayTarget, source, fileName)) {
                            break // TS2353 emitted — one error per call
                        }
                        // 16.4dn: Missing-required-property check for object literal arguments.
                        // If source is missing one or more required target props, emit TS2345
                        // at arg span with "Property 'X' is missing in type 'Y' but required in
                        // type 'Z'." chain. Matches TypeScript's `foo({ name: "hello" })` vs
                        // param `{ id: number; name?: string }` → TS2345 + missing-prop chain
                        // + TS2728 related info pointing to first missing property declaration.
                        // B83.4h: source-defined Object.prototype-member OVERRIDE check.
                        // When the source object literal defines a property whose name is an
                        // Object.prototype member (toString/valueOf/...) that the TARGET does
                        // NOT declare itself, TypeScript compares the source's property type
                        // against the INHERITED Object.prototype member signature (e.g.
                        // Object.toString: () => string). If incompatible, it emits TS2322 at
                        // the property NAME and SUPPRESSES the arg-level missing-prop TS2345.
                        // Example: `f2({ toString: (s) => s })` against `I2 { value; doStuff }`
                        //   → TS2322 "Type '(s: any) => any' is not assignable to type
                        //     '() => string'. Target signature provides too few arguments...".
                        if (argType is Type.Object) {
                            var protoOverrideEmitted = false
                            for (propNode in arg.properties) {
                                val (propName, keyPos, keyLen) = when (propNode) {
                                    is PropertyAssignment -> {
                                        val n = propNode.name
                                        if (n is Identifier) Triple(n.text, n.pos, n.text.length) else continue
                                    }
                                    else -> continue
                                }
                                if (propName !in OBJECT_PROTOTYPE_PROPERTIES) continue
                                // Skip when the target declares this property itself — then the
                                // standard per-property mismatch path (below) owns the comparison.
                                if (paramType.members?.get(propName) != null) continue
                                val inheritedType = getObjectPrototypeMemberType(propName) ?: continue
                                val sourcePropSym = argType.members?.get(propName) ?: continue
                                val sourcePropType = getTypeOfSymbol(sourcePropSym)
                                if (sourcePropType === anyType || sourcePropType === errorType) continue
                                // Only handle anonymous-function-typed source/inherited pairs
                                // (both have callSignatures) — the inherited prototype members
                                // we filter on (toString/valueOf/...) are all methods.
                                val srcIsFunc = sourcePropType is Type.Object &&
                                    sourcePropType !is Type.Interface &&
                                    !(sourcePropType as Type.Object).callSignatures.isNullOrEmpty()
                                val tgtIsFunc = inheritedType is Type.Object &&
                                    inheritedType !is Type.Interface &&
                                    !(inheritedType as Type.Object).callSignatures.isNullOrEmpty()
                                if (!srcIsFunc || !tgtIsFunc) continue
                                if (checkTypeRelatedTo(sourcePropType, inheritedType, assignableRelation)) continue
                                val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
                                val displayInherited = typeToString(inheritedType)
                                val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
                                val chain = mutableListOf<String>()
                                chain.addAll(getFunctionMismatchElaboration(
                                    sourcePropType as Type.Object,
                                    inheritedType as Type.Object,
                                ))
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayInherited'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = kline,
                                    character = kchar,
                                    start = keyPos,
                                    length = keyLen,
                                    messageChain = chain,
                                ))
                                protoOverrideEmitted = true
                            }
                            if (protoOverrideEmitted) return
                        }
                        if (argType is Type.Object) {
                            val missing = mutableListOf<Symbol>()
                            for (targetProp in paramType.properties!!) {
                                if (isOptionalProperty(targetProp)) continue
                                // B83.4g: a target property whose name is an Object.prototype
                                // member (toString/valueOf/etc.) is satisfied by the literal's
                                // implicit prototype when the source doesn't define it — so it
                                // is NOT "missing". Matches TypeScript: `f2({ value: '' })`
                                // against `I { value; toString: (t)=>string }` does NOT flag
                                // toString. Mirrors the OBJECT_PROTOTYPE_PROPERTIES filter in
                                // propertiesRelatedTo (Checker.kt:~69600). Only skips when the
                                // source omits it — a source-defined toString still falls
                                // through to the normal property-compatibility check elsewhere.
                                if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                                if (argType.members?.get(targetProp.name) == null) {
                                    missing.add(targetProp)
                                }
                            }
                            if (missing.isNotEmpty()) {
                                val argDisplay = typeToString(argType)
                                val argStart = arg.pos
                                val argLen = expressionTrueEnd(arg) - argStart
                                if (argLen > 0) {
                                    val (aline, achar) = getLineAndCharacterOfPosition(source, argStart)
                                    val chain = mutableListOf<String>()
                                    val missingNames = missing.map { it.name }
                                    if (missing.size == 1) {
                                        chain.add("  Property '${missingNames[0]}' is missing in type '$argDisplay' but required in type '$displayTarget'.")
                                    } else {
                                        chain.add("  " + formatTs2740Message(argDisplay, displayTarget, missingNames))
                                    }
                                    val related = mutableListOf<Diagnostic>()
                                    val firstDecl = missing[0].declarations.firstOrNull()
                                    if (firstDecl != null) {
                                        val declPos = when (firstDecl) {
                                            is PropertyDeclaration -> firstDecl.name.pos
                                            else -> firstDecl.pos
                                        }
                                        val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                                        related.add(Diagnostic(
                                            message = "'${missing[0].name}' is declared here.",
                                            category = DiagnosticCategory.Message,
                                            code = 2728,
                                            fileName = fileName,
                                            line = dline,
                                            character = dchar,
                                            start = declPos,
                                            length = missing[0].name.length,
                                        ))
                                    }
                                    diagnostics.add(Diagnostic(
                                        message = "Argument of type '$argDisplay' is not assignable to parameter of type '$displayTarget'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2345,
                                        fileName = fileName,
                                        line = aline,
                                        character = achar,
                                        start = argStart,
                                        length = argLen,
                                        messageChain = chain,
                                        relatedInformation = related,
                                    ))
                                    break
                                }
                            }
                        }
                        // 16.4dn: Per-property value-type mismatch → TS2322 at property key,
                        // plus TS6500 related info pointing to target prop declaration.
                        // Conservative: only emit when BOTH source value type AND target prop
                        // type are simple-checkable (primitives / literals / all-primitive unions).
                        // Object↔object property mismatches are handled elsewhere via
                        // `getPropertyElaborationChain` during arg-level TS2345 emission.
                        // 16.4dy: Also emit when both sides are anonymous function types with
                        // simple-typed signatures — mirrors 16.4dw's arg-level function check
                        // but at the per-property level (e.g. `test({thunk: (n:number)=>{}})`
                        // vs `test(t: {thunk: (s:string) => void})`).
                        if (argType is Type.Object) {
                            var perPropEmitted = false
                            for (propNode in arg.properties) {
                                val (propName, keyPos, keyLen) = when (propNode) {
                                    is PropertyAssignment -> {
                                        val n = propNode.name
                                        when (n) {
                                            is Identifier -> Triple(n.text, n.pos, n.text.length)
                                            else -> continue
                                        }
                                    }
                                    else -> continue
                                }
                                val targetProp = paramType.members?.get(propName) ?: continue
                                val targetPropType = getTypeOfSymbol(targetProp)
                                if (targetPropType === anyType || targetPropType === errorType) continue
                                val sourcePropSym = argType.members?.get(propName) ?: continue
                                val sourcePropType = getTypeOfSymbol(sourcePropSym)
                                if (sourcePropType === anyType || sourcePropType === errorType) continue
                                val bothSimple = isSimpleCheckableType(targetPropType) &&
                                    isSimpleCheckableType(sourcePropType)
                                val tgtIsAnonFunc = targetPropType is Type.Object &&
                                    targetPropType !is Type.Interface &&
                                    !(targetPropType as Type.Object).callSignatures.isNullOrEmpty() &&
                                    (targetPropType as Type.Object).properties.isNullOrEmpty()
                                val srcIsAnonFunc = sourcePropType is Type.Object &&
                                    sourcePropType !is Type.Interface &&
                                    !(sourcePropType as Type.Object).callSignatures.isNullOrEmpty() &&
                                    (sourcePropType as Type.Object).properties.isNullOrEmpty()
                                val bothFuncSimple = tgtIsAnonFunc && srcIsAnonFunc &&
                                    sigHasOnlySimpleTypes((targetPropType as Type.Object).callSignatures!!.first()) &&
                                    sigHasOnlySimpleTypes((sourcePropType as Type.Object).callSignatures!!.first())
                                if (!bothSimple && !bothFuncSimple) continue
                                if (checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) continue
                                val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
                                val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
                                val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
                                val related = mutableListOf<Diagnostic>()
                                val tpDecl = targetProp.declarations.firstOrNull()
                                if (tpDecl != null) {
                                    val declPos = when (tpDecl) {
                                        is PropertyDeclaration -> tpDecl.name.pos
                                        is PropertyAssignment -> tpDecl.name.pos
                                        else -> tpDecl.pos
                                    }
                                    val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                                    related.add(Diagnostic(
                                        message = "The expected type comes from property '$propName' which is declared here on type '$displayTarget'",
                                        category = DiagnosticCategory.Message,
                                        code = 6500,
                                        fileName = fileName,
                                        line = dline,
                                        character = dchar,
                                        start = declPos,
                                        length = propName.length,
                                    ))
                                }
                                val chain = mutableListOf<String>()
                                if (bothFuncSimple) {
                                    chain.addAll(getFunctionMismatchElaboration(
                                        sourcePropType as Type.Object,
                                        targetPropType as Type.Object,
                                    ))
                                }
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = kline,
                                    character = kchar,
                                    start = keyPos,
                                    length = keyLen,
                                    messageChain = chain,
                                    relatedInformation = related,
                                ))
                                perPropEmitted = true
                            }
                            // B52.3: when per-property TS2322 fired for this object-literal
                            // arg, stop all subsequent arg checks for this call — TypeScript
                            // emits per-property errors at the literal and SKIPS the bare-T
                            // arg check (which would otherwise FP-emit TS2345 at e.g. m:T = 4
                            // when T is bound to mismatched-with-some-prop).
                            if (perPropEmitted) return
                        }
                    }
                } catch (_: StackOverflowError) { /* circular type */ }
            }
            // 16.4dt: For an OPTIONAL TypeParam-typed parameter (`x?: T` where T extends
            // some non-null constraint), TypeScript rejects `null` arguments with
            // `Argument of type 'null' is not assignable to parameter of type '<C> | undefined'`.
            // Emit TS2345 with constraint-based display.
            if (!isRestParam && paramType is Type.TypeParam && argType.flags.hasAny(TypeFlags.Null)) {
                val paramDecl = params[i].valueDeclaration as? Parameter
                val isOptional = paramDecl?.questionToken == true
                val constraint = paramType.constraint
                if (isOptional && constraint != null &&
                    !constraint.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Any)
                ) {
                    val argTypeStr = typeToString(argType)
                    val paramTypeStr = "${typeToString(constraint)} | undefined"
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                            category = DiagnosticCategory.Error,
                            code = 2345,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                        continue
                    }
                }
            }
            // 17.11c: TS2345 for null/undefined argument vs Type.Reference parameter
            // whose resolvedTypeArguments contain unconstrained sig-side TypeParams.
            // Example: `fold<T,S>(c: Array<T>, ...)` called with `null` — null isn't
            // structurally assignable to any Array instantiation. Display substitutes
            // each sig-side TypeParam with `unknown` (so `T[]` renders as `unknown[]`),
            // matching TypeScript's "T inferred as unknown when no information" rule.
            // Skip when the relation actually accepts null (e.g. paramType happens to
            // include null in a constraint) so we don't regress tests where null is
            // compatible.
            // 17.153: When the Reference is fully concrete (no sig-side TPs in
            // resolvedTypeArguments — e.g. inherited generic call sigs `interface
            // I2<T> extends I1<T[]>; var x: I2<Date>; x(undefined)` where
            // I2<Date>'s callSig param resolves to `Date[]`), still emit TS2345
            // with the plain display. Without this branch, the simple-checkable
            // gate downstream skips the case (paramType is Reference, not
            // Interface, so paramIsNamedType=false and the
            // `argIsPrimitive && paramIsNamedType` allowlist doesn't match).
            if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
                paramType is Type.Reference) {
                val sigTps = sig.typeParameters
                val refArgs = paramType.resolvedTypeArguments
                val hasSigTp = !sigTps.isNullOrEmpty() && refArgs != null &&
                    refArgs.any { sourceContainsTypeParam(it, sigTps) }
                if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                    val displayParamBase = if (hasSigTp) {
                        val mapper = TypeMapper { tp -> if (sigTps!!.contains(tp)) unknownType else null }
                        typeToStringWithMapper(paramType, mapper)
                    } else {
                        typeToString(paramType)
                    }
                    // B51.7: widen display to `T | undefined` when the parameter is
                    // optional under strictNullChecks AND the param type is a
                    // Type.Reference (e.g. `Array<T>`). Simple primitive params
                    // (`a?:string`) do NOT get the `| undefined` widening in
                    // TS2345 messages — matches TypeScript's display convention.
                    val paramIsOptional = (params[i].valueDeclaration as? Parameter)?.questionToken == true
                    val displayParam = if (paramIsOptional && strictNullChecks &&
                        paramType is Type.Reference) {
                        "$displayParamBase | undefined"
                    } else displayParamBase
                    val argTypeStr = typeToString(argType)
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$displayParam'.",
                            category = DiagnosticCategory.Error,
                            code = 2345,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                        break
                    }
                }
            }
            // 17.40: TS2345 for null/undefined argument vs anonymous function-type parameter
            // (Type.Object with callSignatures, NOT Type.Reference / Type.Interface) whose
            // signature mentions sig-side TypeParams. Example:
            //   foo<T>(x: (a: Iterator<T>) => number)  called with  foo(null)
            // Display substitutes each sig-side TypeParam with `unknown` so the param type
            // renders as `(a: Iterator<unknown>) => number`, matching TypeScript's "T inferred
            // as unknown when no information" rule. Mirror of 17.11c (Type.Reference param) but
            // for anonymous function-type params.
            if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
                paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface) {
                val sigTps = sig.typeParameters
                val callSigs = paramType.callSignatures
                val ctorSigs = paramType.constructSignatures
                val anyFnSig = !callSigs.isNullOrEmpty() || !ctorSigs.isNullOrEmpty()
                val mentionsSigTp = !sigTps.isNullOrEmpty() && anyFnSig && (
                    callSigs?.any { sigMentionsAnyTp(it, sigTps) } == true ||
                    ctorSigs?.any { sigMentionsAnyTp(it, sigTps) } == true
                )
                if (mentionsSigTp && !checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                    val mapper = TypeMapper { tp -> if (sigTps!!.contains(tp)) unknownType else null }
                    // Build a display-only Type.Object with substituted callSigs/ctorSigs.
                    val displayObj = Type.Object().also {
                        it.callSignatures = callSigs?.map { s -> instantiateSignature(s, mapper) }
                        it.constructSignatures = ctorSigs?.map { s -> instantiateSignature(s, mapper) }
                    }
                    val displayParam = typeToString(displayObj)
                    val argTypeStr = typeToString(argType)
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$displayParam'.",
                            category = DiagnosticCategory.Error,
                            code = 2345,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                        break
                    }
                }
            }
            // 17.20: TS2345 for null/undefined argument vs unconstrained bare `Type.TypeParam`
            // parameter. Example: `super.bar<T>(null)` where the base method is `bar<U>(x: U)`
            // and explicit `<T>` substitutes U → T. The arg is null and the param is the bare
            // unconstrained type-parameter — emit TS2345 with chain "'T' could be instantiated
            // with an arbitrary type which could be unrelated to 'null'.".
            // Constrained TypeParams are handled by the 16.4i branch below (which uses the
            // constraint as the displayed param type, matching TypeScript's baseline for
            // `fn<T extends string>(n:T)` called with `fn(null)`).
            if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
                paramType is Type.TypeParam && paramType.constraint == null) {
                val tpName = paramType.symbol?.name ?: "T"
                val argTypeStr = typeToString(argType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$tpName'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = listOf(
                            "  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$argTypeStr'.",
                        ),
                    ))
                    break
                }
            }
            // 16.4ds: Per-property TS2322 when paramType is a TypeParam whose CONSTRAINT
            // is an Object with named properties. `fn<T extends {x:string}>(n: T)` called
            // with `fn({ x: null })` should emit TS2322 at `x` for null-vs-string. Only
            // the per-property loop extends to this case — excess/missing-required are
            // skipped because generic-param constraints have different semantics for those.
            if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.TypeParam) {
                val constraint = paramType.constraint
                if (constraint is Type.Object) {
                    try {
                        resolveStructuredTypeMembers(constraint)
                        val hasConstraintProps = !constraint.properties.isNullOrEmpty()
                        if (hasConstraintProps && argType is Type.Object) {
                            val displayTargetObj = typeToString(constraint)
                            for (propNode in arg.properties) {
                                val (propName, keyPos, keyLen) = when (propNode) {
                                    is PropertyAssignment -> {
                                        val n = propNode.name
                                        when (n) {
                                            is Identifier -> Triple(n.text, n.pos, n.text.length)
                                            else -> continue
                                        }
                                    }
                                    else -> continue
                                }
                                val targetProp = constraint.members?.get(propName) ?: continue
                                val targetPropType = getTypeOfSymbol(targetProp)
                                if (targetPropType === anyType || targetPropType === errorType) continue
                                if (!isSimpleCheckableType(targetPropType)) continue
                                val sourcePropSym = argType.members?.get(propName) ?: continue
                                val sourcePropType = getTypeOfSymbol(sourcePropSym)
                                if (sourcePropType === anyType || sourcePropType === errorType) continue
                                if (!isSimpleCheckableType(sourcePropType)) continue
                                if (checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) continue
                                val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
                                val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
                                val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
                                val related = mutableListOf<Diagnostic>()
                                // 16.4dt: TypeScript only emits TS6500 for ANONYMOUS object constraints
                                // (no symbol), not for named interfaces like `T extends Item`. Gate the
                                // related-info emission on `constraint.symbol == null`.
                                val tpDecl = targetProp.declarations.firstOrNull()
                                if (tpDecl != null && constraint.symbol == null) {
                                    val declPos = when (tpDecl) {
                                        is PropertyDeclaration -> tpDecl.name.pos
                                        is PropertyAssignment -> tpDecl.name.pos
                                        else -> tpDecl.pos
                                    }
                                    val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                                    related.add(Diagnostic(
                                        message = "The expected type comes from property '$propName' which is declared here on type '$displayTargetObj'",
                                        category = DiagnosticCategory.Message,
                                        code = 6500,
                                        fileName = fileName,
                                        line = dline,
                                        character = dchar,
                                        start = declPos,
                                        length = propName.length,
                                    ))
                                }
                                diagnostics.add(Diagnostic(
                                    message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2322,
                                    fileName = fileName,
                                    line = kline,
                                    character = kchar,
                                    start = keyPos,
                                    length = keyLen,
                                    relatedInformation = related,
                                ))
                            }
                        }
                    } catch (_: StackOverflowError) { /* circular type */ }
                }
            }
            // 16.4i: Generic parameter with a simple constraint — when the argument
            // doesn't satisfy the constraint, report TS2345 using the constraint as
            // the effective parameter type (the type parameter would be inferred as
            // the argument type, which would then fail the constraint check).
            if (paramType is Type.TypeParam) {
                val constraint = paramType.constraint
                if (constraint != null &&
                    isSimpleCheckableType(constraint) &&
                    isSimpleCheckableType(argType) &&
                    !checkTypeRelatedTo(argType, constraint, assignableRelation)
                ) {
                    val argTypeStr = typeToString(argType)
                    val paramTypeStr = typeToString(constraint)
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                            category = DiagnosticCategory.Error,
                            code = 2345,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
                continue
            }
            // 17.27: Type.Reference source (e.g. `string[]`) vs named-Interface target
            // (e.g. `Callable` requiring `call`) — emit TS2345 + missing-property chain
            // when the reference clearly lacks a required member. Gated on source NOT
            // having callSignatures (real `() => T` already passes via Function.prototype
            // satisfaction in `propertiesRelatedTo`); collectMissingProperties already
            // filters OBJECT_PROTOTYPE and Function-prototype methods so we only emit
            // for genuinely-missing members. Squiggle covers the whole arg expression.
            // 17.29: Extended to Type.Interface source (named class) vs Type.Interface
            // target (named class) when symbols differ — covers same-name-different-scope
            // class cases (e.g. namespace-nested `m.variable` vs top-level `variable`).
            // collectMissingProperties uses resolveStructuredTypeMembers which flattens
            // base-type members, so subclass-of-target safely returns empty (no FP).
            val argIsRefForArgCheck = argType is Type.Reference
            val argIsDistinctNamedClass = argType is Type.Interface && argType.symbol != null &&
                paramType is Type.Interface && argType.symbol !== paramType.symbol
            if (!isRestParam && (argIsRefForArgCheck || argIsDistinctNamedClass) &&
                paramType is Type.Interface && paramType.symbol != null) {
                try {
                    resolveStructuredTypeMembers(argType as Type.Object)
                    resolveStructuredTypeMembers(paramType)
                    if ((argType as Type.Object).callSignatures.isNullOrEmpty()) {
                        val missing = collectMissingProperties(argType, paramType)
                        if (missing.isNotEmpty()) {
                            val argTypeStr = typeToStringQualified(argType)
                            val paramTypeStr = typeToStringQualified(paramType)
                            val start = arg.pos
                            val length = expressionTrueEnd(arg) - start
                            if (length > 0) {
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                val firstMissing = missing[0]
                                val chain = mutableListOf<String>()
                                chain.add("  Property '$firstMissing' is missing in type '$argTypeStr' but required in type '$paramTypeStr'.")
                                val missingPropSym = paramType.properties?.find { it.name == firstMissing }
                                val related: List<Diagnostic> = missingPropSym?.let { sym ->
                                    createPropertyDeclaredHereRelatedInfo(sym)?.let { listOf(it) }
                                } ?: emptyList()
                                diagnostics.add(Diagnostic(
                                    message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2345,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                    messageChain = chain,
                                    relatedInformation = related,
                                ))
                                break
                            }
                        }
                    }
                } catch (_: StackOverflowError) { /* circular type */ }
            }
            // Conservative: only check when parameter type is a well-known type
            // (primitive, void, undefined, null, never). Skip object/interface/union/
            // intersection types which need deeper structural comparison or generics.
            // 16.4: Also check when arg is a primitive type and param is a named class/interface
            // (primitives are never structurally assignable to class instances with members).
            // 16.4dk: Additionally check when both sides are named class interfaces AND the
            // structural comparison would fail on a private-brand mismatch — that's a nominal
            // brand check with no FP risk (same-class private props pass trivially).
            if (!isSimpleCheckableType(paramType)) {
                val argIsPrimitive = isSimpleCheckableType(argType)
                val paramIsNamedType = paramType is Type.Interface && paramType.symbol != null
                val argIsNamedType = argType is Type.Interface && argType.symbol != null
                val hasPrivateBrand = argIsNamedType && paramIsNamedType &&
                    hasPrivateBrandMismatchBetween(argType as Type.Object, paramType as Type.Object)
                // 16.4dw: Function-to-function comparison — when both param and arg are
                // anonymous function types (Object with only call signatures, no members)
                // AND both signatures have only simple-checkable param/return types (no
                // Type.TypeParam, Reference, Union, etc.), proceed with the structural
                // check so TS2345 fires for callback arg mismatches. The simple-types
                // guard avoids FPs in generic-inference scenarios we don't yet handle.
                val paramIsAnonFunc = paramType is Type.Object && paramType !is Type.Interface &&
                    !paramType.callSignatures.isNullOrEmpty() && paramType.properties.isNullOrEmpty()
                val argIsAnonFunc = argType is Type.Object && argType !is Type.Interface &&
                    !(argType as Type.Object).callSignatures.isNullOrEmpty() &&
                    (argType as Type.Object).properties.isNullOrEmpty()
                val allowFuncToFunc = paramIsAnonFunc && argIsAnonFunc &&
                    sigHasOnlySimpleTypes((paramType as Type.Object).callSignatures!!.first()) &&
                    sigHasOnlySimpleTypes((argType as Type.Object).callSignatures!!.first())
                // 17.24: Arity-mismatch is a definitive function-vs-function failure regardless
                // of param/return type complexity. When source's minArgumentCount exceeds
                // target's total params, the assignment is invalid because a caller of the
                // target signature would not pass enough arguments to satisfy the source.
                // Allows the check even when sigHasOnlySimpleTypes fails (e.g. unresolved
                // ItemSet → errorType, or `any` return type).
                val allowArityMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                    val argSig = (argType as Type.Object).callSignatures!!.first()
                    val paramSig = (paramType as Type.Object).callSignatures!!.first()
                    argSig.minArgumentCount > paramSig.parameters.size
                }
                // 17.238: Zero-param void-return source vs anon-func target with a simple
                // non-void return — assign-incompatible regardless of target's param types.
                // void-return-is-special applies only when TARGET returns void; the reverse
                // direction must fail.
                val allowVoidReturnMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                    val argSig = (argType as Type.Object).callSignatures!!.first()
                    val paramSig = (paramType as Type.Object).callSignatures!!.first()
                    val argReturn = argSig.resolvedReturnType
                    val paramReturn = paramSig.resolvedReturnType
                    argSig.parameters.isEmpty() && argReturn === voidType &&
                        paramReturn != null && paramReturn !== voidType &&
                        paramReturn !== anyType && paramReturn !== errorType &&
                        isSimpleCheckableType(paramReturn)
                }
                // B83.4f-d: Function-vs-function arg comparison when the ONLY mismatch is
                // a concrete-and-incompatible RETURN type (params are pairwise assignable).
                // The `allowFuncToFunc` gate above requires BOTH sigs to be fully simple-
                // checkable, which excludes a callback param like `(x: T) => Date` whose
                // return type `Date` (Type.Reference) is not simple. This narrow gate fires
                // when: same param count, each param pair contravariant-assignable, the
                // arg's return is a simple-checkable concrete type (e.g. `string`), the
                // param's return is a concrete non-void/any/error type (e.g. `Date`), and
                // the arg return is NOT assignable to the param return. Produces the
                // `Type 'string' is not assignable to type 'Date'.` chain via
                // `getFunctionMismatchElaboration`'s return-type block.
                val allowFuncReturnMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                    val argSig = (argType as Type.Object).callSignatures!!.first()
                    val paramSig = (paramType as Type.Object).callSignatures!!.first()
                    val argReturn = argSig.resolvedReturnType
                    val paramReturn = paramSig.resolvedReturnType
                    if (argReturn == null || paramReturn == null) return@run false
                    if (argSig.parameters.size != paramSig.parameters.size) return@run false
                    // Arg return must be a concrete simple type; param return must be a
                    // concrete (non-void/any/error) type that is structurally describable.
                    if (!isSimpleCheckableType(argReturn)) return@run false
                    if (paramReturn === voidType || paramReturn === anyType ||
                        paramReturn === errorType || argReturn === anyType ||
                        argReturn === errorType) return@run false
                    // Skip when the param return is itself a type parameter (unresolved
                    // generic) — that's an inference scenario, not a concrete mismatch.
                    if (paramReturn is Type.TypeParam) return@run false
                    // Each param pair must be contravariant-assignable (target→source) so
                    // the ONLY remaining incompatibility is the return type. If any param
                    // pair fails, fall through to the standard paths (allowFuncToFunc etc.).
                    val paramsCompatible = (0 until argSig.parameters.size).all { i ->
                        val ap = getTypeOfSymbol(argSig.parameters[i])
                        val pp = getTypeOfSymbol(paramSig.parameters[i])
                        checkTypeRelatedTo(pp, ap, assignableRelation)
                    }
                    if (!paramsCompatible) return@run false
                    // Final: the return types must actually be incompatible.
                    !checkTypeRelatedTo(argReturn, paramReturn, assignableRelation)
                }
                // B50.4: Object→Object structural mismatch — narrow gate. Only fires
                // when BOTH source and target are anonymous Type.Object with alias
                // context registered (via B50.1's substitution or B50.4's non-generic
                // alias registration). This isolates the new TS2345 emission to cases
                // driven by the B50.x alias infrastructure, avoiding FPs in
                // pre-existing Object-vs-Object comparisons (e.g. inferred-from-
                // object-literal types vs interface-shaped params).
                val allowChainObjObj = paramType is Type.Object && argType is Type.Object &&
                    paramType !is Type.Interface && paramType !is Type.Reference &&
                    argType !is Type.Interface && argType !is Type.Reference &&
                    paramType.id in aliasDisplayMap && argType.id in aliasDisplayMap &&
                    !paramType.properties.isNullOrEmpty() && argType.members != null && run {
                        val chain = getPropertyElaborationChain(argType, paramType)
                        chain != null && chain.isNotEmpty()
                    }
                if (!(argIsPrimitive && paramIsNamedType) && !hasPrivateBrand && !allowFuncToFunc && !allowArityMismatch && !allowVoidReturnMismatch && !allowFuncReturnMismatch && !allowChainObjObj) continue
                // Round 79l (orchestrated — Agent A plan): for a contextually-typed
                // ARROW / FUNCTION-EXPRESSION argument whose ONLY mismatch is the
                // body-return type (allowFuncReturnMismatch), TypeScript reports a
                // fine-grained TS2322 AT THE ARROW'S RETURN EXPRESSION (+ related
                // TS6502 pointing at the callback signature's return-type node), NOT
                // the coarse whole-argument TS2345. Emit it here and `continue` to
                // suppress the TS2345 below. (`foo(a => a)` vs `(item: number) =>
                // boolean` → TS2322 'number' not assignable to 'boolean' at `a`.)
                if (!calleeGenericInstantiation && sigIn.typeParameters.isNullOrEmpty() &&
                    allowFuncReturnMismatch && (arg is ArrowFunction || arg is FunctionExpression)) {
                    val argSig = (argType as Type.Object).callSignatures!!.first()
                    val paramSig = (paramType as Type.Object).callSignatures!!.first()
                    val argReturn = argSig.resolvedReturnType
                    val paramReturn = paramSig.resolvedReturnType
                    val retExpr: Expression? = when (arg) {
                        is ArrowFunction -> when (val b = arg.body) {
                            is Block -> b.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                            is Expression -> b
                            else -> null
                        }
                        is FunctionExpression -> arg.body.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                        else -> null
                    }
                    if (retExpr != null && argReturn != null && paramReturn != null) {
                        val rStart = retExpr.pos
                        val rLength = (expressionTrueEnd(retExpr) - rStart).coerceAtLeast(1)
                        val (rLine, rChar) = getLineAndCharacterOfPosition(source, rStart)
                        // TS6502 points at the START of the callback SIGNATURE
                        // `(item: number) => boolean` (the `(`), i.e. the FunctionType
                        // declaration node's pos — NOT the return-type node.
                        val related = (paramSig.declaration as? FunctionType)?.let { ftNode ->
                            val (relLine, relChar) = getLineAndCharacterOfPosition(source, ftNode.pos)
                            listOf(Diagnostic(
                                message = "The expected type comes from the return type of this signature.",
                                category = DiagnosticCategory.Message,
                                code = 6502,
                                fileName = fileName,
                                line = relLine,
                                character = relChar,
                                start = ftNode.pos,
                                length = (ftNode.type.end - ftNode.pos).coerceAtLeast(1),
                            ))
                        } ?: emptyList()
                        diagnostics.add(Diagnostic(
                            message = "Type '${typeToString(argReturn)}' is not assignable to type '${typeToString(paramReturn)}'.",
                            category = DiagnosticCategory.Error,
                            code = 2322,
                            fileName = fileName,
                            line = rLine,
                            character = rChar,
                            start = rStart,
                            length = rLength,
                            relatedInformation = related,
                        ))
                        continue
                    }
                }
            }
            // B71.1: Strict-only void→undefined fn-return mismatch. Argument is a NAMED
            // FunctionDeclaration (source.symbol carries the function's symbol — arrow
            // functions and function expressions do NOT set fnType.symbol) whose return
            // type infers to `void` (no explicit return). Target param's return type is
            // `undefined`. Under strictNullChecks, this is incompatible — even though
            // `isSimpleTypeRelatedTo` treats void→undefined as assignable globally.
            // Force a relation failure so TS2345 emits with the standard chain.
            val forceVoidUndefinedFail = strictNullChecks &&
                argType is Type.Object && argType.symbol != null &&
                argType.symbol!!.declarations.any { it is FunctionDeclaration } &&
                paramType is Type.Object &&
                !argType.callSignatures.isNullOrEmpty() &&
                !paramType.callSignatures.isNullOrEmpty() && run {
                    val aSig = argType.callSignatures!!.first()
                    val pSig = paramType.callSignatures!!.first()
                    aSig.parameters.isEmpty() && pSig.parameters.isEmpty() &&
                        aSig.resolvedReturnType === voidType &&
                        pSig.resolvedReturnType != null &&
                        pSig.resolvedReturnType!!.flags.hasAny(TypeFlags.Undefined) &&
                        !pSig.resolvedReturnType!!.flags.hasAny(TypeFlags.Void)
                }
            if (forceVoidUndefinedFail || !checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // Emit TS2345
                val argTypeStr = typeToString(argType)
                val paramTypeStr = typeToString(paramType)
                val start = arg.pos
                // 17.238: ArrowFunction with a MULTI-LINE Block body — clip squiggle to
                // end of source line containing the body's `{`. TypeScript clips at the
                // body open brace line only when the body spans multiple source lines;
                // single-line bodies like `() => {}` keep the full arrow span. End-of-line
                // includes any trailing same-line whitespace after `{` (e.g. `{ \n` keeps
                // the trailing space in the squiggle, matching baseline 8-char span).
                val length = if (arg is ArrowFunction && arg.body is Block) {
                    val body = arg.body as Block
                    val fullEnd = expressionTrueEnd(arg)
                    val isMultiLine = body.pos in 0..<source.length &&
                        body.pos < fullEnd &&
                        source.substring(body.pos, fullEnd.coerceAtMost(source.length)).contains('\n')
                    if (isMultiLine) {
                        // Find `=>` between arg.pos and body.pos. If `=>` is on a separate line
                        // from `{` (rare: `() =>\n // comment \n {`), clip at end-of-line-of-`=>`
                        // so the squiggle covers only `() =>` (matching TypeScript's narrow span).
                        // Otherwise clip at end-of-line-of-`{` (the common multi-line-body case).
                        val arrowMarkerPos = source.lastIndexOf("=>", (body.pos - 1).coerceAtLeast(0))
                        val anchorPos = if (arrowMarkerPos in start..<body.pos) {
                            // Use the `=>` position to find its line's end-of-line.
                            val arrowEolPos = source.indexOf('\n', arrowMarkerPos).let { if (it < 0) source.length else it }
                            val braceEolPos = source.indexOf('\n', body.pos).let { if (it < 0) source.length else it }
                            // If `=>` and `{` are on different lines, prefer `=>`'s EOL (narrower).
                            if (arrowEolPos < body.pos) arrowEolPos else braceEolPos
                        } else {
                            source.indexOf('\n', body.pos).let { if (it < 0) fullEnd else it }
                        }
                        (anchorPos.coerceAtMost(fullEnd) - start).coerceAtLeast(1)
                    } else {
                        fullEnd - start
                    }
                } else {
                    expressionTrueEnd(arg) - start
                }
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                // TS6213: If the argument type has construct signatures but no call signatures,
                // suggest "Did you mean to use 'new' with this expression?". TS6212 mirrors
                // this for call signatures whose return type would satisfy the parameter —
                // "Did you mean to call this expression?".
                val relatedInfo: MutableList<Diagnostic> = mutableListOf()
                if (argType is Type.Object) {
                    val constructSigs = getConstructSignaturesOfType(argType)
                    val callSigs = getCallSignaturesOfType(argType)
                    if (constructSigs.isNotEmpty() && callSigs.isEmpty()) {
                        relatedInfo.add(Diagnostic(
                            message = "Did you mean to use 'new' with this expression?",
                            category = DiagnosticCategory.Message,
                            code = 6213,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    } else if (callSigs.isNotEmpty() && arg !is ArrowFunction && arg !is FunctionExpression) {
                        val callingHelpsArg = callSigs.any { sig ->
                            val rt = sig.resolvedReturnType ?: return@any false
                            checkTypeRelatedTo(rt, paramType, assignableRelation)
                        }
                        if (callingHelpsArg) {
                            relatedInfo.add(Diagnostic(
                                message = "Did you mean to call this expression?",
                                category = DiagnosticCategory.Message,
                                code = 6212,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                // TS2793: overload implementation would have matched
                if (implementationRelated != null) {
                    relatedInfo.add(implementationRelated)
                }
                // Union elaboration: find the failing constituent and add as message chain
                val chain = mutableListOf<String>()
                if (argType is Type.Union) {
                    // Find the last failing constituent (matches TypeScript's behavior)
                    var lastFailing: Type? = null
                    for (constituent in argType.types) {
                        if (!checkTypeRelatedTo(constituent, paramType, assignableRelation)) {
                            lastFailing = constituent
                        }
                    }
                    if (lastFailing != null) {
                        val constStr = typeToString(lastFailing)
                        chain.add("  Type '$constStr' is not assignable to type '$paramTypeStr'.")
                    }
                }
                // Private-brand elaboration: "Types have separate declarations of a private property 'X'."
                if (argType is Type.Object && paramType is Type.Object) {
                    val mismatchName = findPrivateBrandMismatchName(argType, paramType)
                    if (mismatchName != null) {
                        chain.add("  Types have separate declarations of a private property '$mismatchName'.")
                    }
                }
                // 16.4dw: Function-to-function elaboration chain — for function-typed
                // argument vs function-typed parameter mismatches. Emits param-mismatch
                // or return-type-mismatch lines, matching the TS2322 elaboration used in
                // assignment contexts.
                if (chain.isEmpty() && argType is Type.Object && paramType is Type.Object &&
                    !argType.callSignatures.isNullOrEmpty() && !paramType.callSignatures.isNullOrEmpty()
                ) {
                    chain.addAll(getFunctionMismatchElaboration(argType, paramType))
                }
                // B50.4: Object→Object property-elaboration chain. When the B50.4 gate
                // above allowed the structural compare to fire AND a per-property
                // mismatch exists, get the chain from `getPropertyElaborationChain`.
                if (chain.isEmpty() && argType is Type.Object && paramType is Type.Object &&
                    argType !is Type.Interface && argType !is Type.Reference &&
                    paramType !is Type.Interface && paramType !is Type.Reference &&
                    !paramType.properties.isNullOrEmpty()
                ) {
                    val propChain = getPropertyElaborationChain(argType, paramType)
                    if (propChain != null) chain.addAll(propChain)
                }
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = chain,
                    relatedInformation = relatedInfo,
                ))
                break // TypeScript reports only the first failing argument per call
            }
        }
        // 17.31c: emit TS2345 for trailing args matched at a rest parameter
        // position whose element type is a fully-resolved primitive/named type.
        // The standard loop above only iterates `i in 0 until params.size`, so
        // for a single rest param it processes arg[0] against the Array<X> type
        // (which never fires TS2345 because Array isn't a simple type), then
        // breaks — leaving every trailing rest arg silently unchecked. After
        // either explicit type-arg substitution OR 17.31a/c inference has
        // resolved the element type, this pass walks every arg matched at the
        // rest position and emits at the first mismatch.
        if (diagnostics.size == initialDiagCount) {
            checkRestArgsAgainstArrayElementType(sig, args, source, fileName)
        }
    }

    /**
     * 17.31c: when [sig]'s last parameter is a rest of `Array<X>` (`...args: X[]`)
     * with a fully-resolved element type X (i.e. X is NOT an unsubstituted
     * TypeParam), emit TS2345 for the first trailing arg whose type is not
     * assignable to X. Uses widened-literal display ('string' not '""') to
     * match TypeScript's TS2345 baseline. One emission per call.
     *
     * Skipped when X is still a TypeParam (inference failed or not attempted),
     * when no rest param exists, or when rest paramType isn't `Array<X>`.
     */
    private fun checkRestArgsAgainstArrayElementType(
        sig: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
    ) {
        val params = sig.parameters
        if (params.isEmpty()) return
        val lastIdx = params.size - 1
        val lastParam = params[lastIdx]
        val isRest = (lastParam.valueDeclaration as? Parameter)?.dotDotDotToken == true
        if (!isRest) return
        val paramType = try { getTypeOfSymbol(lastParam) } catch (_: StackOverflowError) { return }
        if (paramType !is Type.Reference) return
        if (paramType.target?.symbol?.name != "Array") return
        val tArgs = paramType.resolvedTypeArguments ?: return
        if (tArgs.size != 1) return
        val elementType = tArgs[0]
        if (elementType === errorType || elementType === anyType) return
        // Skip when element is still an unresolved TypeParam — inference either
        // failed or wasn't attempted (e.g. anonymous Object literal arg). The
        // standard pre-rest paths handle bare-T checks for non-rest cases.
        if (elementType is Type.TypeParam) return
        for (i in lastIdx until args.size) {
            val arg = args[i]
            if (arg is SpreadElement) continue
            val argType = try { getTypeOfExpression(arg) } catch (_: StackOverflowError) { continue }
            if (argType === anyType || argType === errorType) continue
            if (argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) continue
            // Conservative gate: only emit when argType is a simple/primitive
            // type (string/number/boolean/literal/intrinsic union). Skipping
            // complex args (arrays, objects, named types) avoids FPs from
            // (a) lib methods like `Array.concat` that should have a `T[][]`
            // overload but don't in our parsed lib (so an arg of `T[]` looks
            // like a mismatch against `T[]` element), and (b) structural
            // comparison gaps for nested generic shapes (`Array<{a:T;b:U}>`
            // vs `Array<{a:number;b:string}>` after explicit-typeArg
            // substitution). The original test motivating this helper
            // (`genericRestArgs_ts`) has only literal/primitive args, which
            // pass this gate. Skipping `continue`s rather than `return`s so
            // a later simple-arg mismatch can still emit.
            // B-vararg: ALSO check a NAMED class/interface-instance arg against a
            // PRIMITIVE rest element type (`...rest: string[]` ← `x: C`). A class
            // instance is never assignable to a primitive, so this is FP-safe and
            // mirrors the main-loop "primitive arg vs named class param" rule. The
            // structurally-risky named-vs-named element case stays excluded (element
            // must be simple-checkable here).
            val argIsNamedInstance = argType is Type.Interface && (argType as Type.Interface).symbol != null
            if (!isSimpleCheckableType(argType) &&
                !(argIsNamedInstance && isSimpleCheckableType(elementType))) continue
            val ok = try {
                checkTypeRelatedTo(argType, elementType, assignableRelation)
            } catch (_: StackOverflowError) { true }
            if (!ok) {
                val argDisplay = typeToString(getWidenedLiteralType(argType))
                val paramDisplay = typeToString(elementType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argDisplay' is not assignable to parameter of type '$paramDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                return
            }
        }
    }

    /**
     * 16.4: Check type argument constraints for call expression type arguments.
     * For each type parameter with a constraint, check the supplied type arg against
     * the instantiated constraint. Emits TS2344.
     */
    private fun checkCallTypeArgConstraints(
        typeParams: List<Type.TypeParam>,
        resolvedTypeArgs: List<Type>,
        typeArgNodes: List<TypeNode>,
        mapper: TypeMapper,
        source: String,
        fileName: String,
    ) {
        val len = minOf(typeParams.size, resolvedTypeArgs.size, typeArgNodes.size)
        for (i in 0 until len) {
            val constraint = typeParams[i].constraint ?: continue
            val argType = resolvedTypeArgs[i]
            if (argType === anyType || argType === errorType) continue
            // Instantiate the constraint (e.g., `U extends T` where T is mapped to number → constraint = number)
            val instantiatedConstraint = instantiateType(constraint, mapper)
            if (instantiatedConstraint === anyType || instantiatedConstraint === errorType) continue
            lastMissingPropertyName = null
            lastMissingPropertySymbol = null
            if (!checkTypeRelatedTo(argType, instantiatedConstraint, assignableRelation)) {
                val argNode = typeArgNodes[i]
                val argDisplay = formatTypeForDisplay(argNode) ?: typeToString(argType)
                // 16.4gb: For anonymous Type.Object constraints where instantiateType
                // doesn't rewrite member types, render with explicit substitution so a
                // constraint like `{ a: T }` with T→string displays as `{ a: string; }`.
                val constraintDisplay = typeToStringWithMapper(instantiatedConstraint, mapper)
                val start = argNode.pos
                // 16.4gb: Use the source span (trim trailing whitespace/`,`/`>`/`;`) instead
                // of display-text length. Source text `{ a: number }` is 13 chars but display
                // renders as `{ a: number; }` (14 chars) — display length over-extends the
                // squiggle past the source text.
                var trueEnd = argNode.end
                while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let {
                    it == ' ' || it == '\t' || it == '\n' || it == '\r' ||
                    it == ',' || it == '>' || it == ')' || it == ';'
                } == true) trueEnd--
                val length = if (trueEnd > start) trueEnd - start else argDisplay.length
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                val chain = mutableListOf<String>()
                val missingProp = lastMissingPropertyName
                val missingPropSym = lastMissingPropertySymbol
                val relatedInfo = mutableListOf<Diagnostic>()
                if (missingProp != null) {
                    chain.add("  Property '$missingProp' is missing in type '$argDisplay' but required in type '$constraintDisplay'.")
                    missingPropSym?.let { createPropertyDeclaredHereRelatedInfo(it) }?.let { relatedInfo.add(it) }
                } else if (argType is Type.Object && instantiatedConstraint is Type.Object) {
                    // 16.4gb: Property-type-mismatch elaboration. When both sides have the
                    // same property but its types are incompatible, emit
                    //   "  Types of property 'X' are incompatible."
                    //   "    Type 'A' is not assignable to type 'B'."
                    // mirroring TS2322's per-property elaboration chain.
                    resolveStructuredTypeMembers(argType)
                    resolveStructuredTypeMembers(instantiatedConstraint)
                    val argMembers = argType.members ?: emptyMap()
                    val cProps = instantiatedConstraint.properties ?: emptyList()
                    for (cp in cProps) {
                        val ap = argMembers[cp.name] ?: continue
                        val cpType = symbolTypes[cp.id] ?: continue
                        val apType = symbolTypes[ap.id] ?: continue
                        val cpTypeInst = instantiateType(cpType, mapper)
                        if (cpTypeInst === anyType || cpTypeInst === errorType) continue
                        if (!checkTypeRelatedTo(apType, cpTypeInst, assignableRelation)) {
                            val cpDisplay = typeToStringWithMapper(cpType, mapper)
                            chain.add("  Types of property '${cp.name}' are incompatible.")
                            chain.add("    Type '${typeToString(apType)}' is not assignable to type '$cpDisplay'.")
                            break
                        }
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "Type '$argDisplay' does not satisfy the constraint '$constraintDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2344,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = chain,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * Check if a type is "simple" enough that we can safely check TS2345 against it
     * without risking false positives from incomplete structural comparison.
     * Returns true for primitive types (string, number, boolean, void, null, undefined, never,
     * bigint, symbol) and their literal variants.
     */
    private fun isSimpleCheckableType(type: Type): Boolean {
        val f = type.flags
        if (f.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.Void or TypeFlags.Undefined or TypeFlags.Null or
            TypeFlags.Never or TypeFlags.BigInt or TypeFlags.ESSymbol or
            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
            TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
        )) return true
        // Allow union types where all members are checkable (e.g., string | number)
        if (type is Type.Union) {
            if (type.types.any { it === anyType || it === errorType }) return false
            return type.types.all { isSimpleCheckableType(it) }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Structural typing engine (Phase 4 items 4a-4e)
    // -----------------------------------------------------------------------

    /** Ternary logic for type relations: True, False, or Maybe (for recursive checks). */
    private enum class Ternary { True, False, Maybe }

    /** Relation cache — maps (sourceId, targetId) packed into Long → result. */
    private class Relation {
        private val cache = HashMap<Long, Ternary>()

        fun get(sourceId: Int, targetId: Int): Ternary? {
            return cache[packKey(sourceId, targetId)]
        }

        fun set(sourceId: Int, targetId: Int, result: Ternary) {
            cache[packKey(sourceId, targetId)] = result
        }

        private fun packKey(a: Int, b: Int): Long =
            (a.toLong() shl 32) or (b.toLong() and 0xFFFFFFFFL)
    }

    /**
     * 4a. Fast flag-based type relatedness check (no recursion).
     * Returns true if the relation holds purely from type flags.
     */
    private fun isSimpleTypeRelatedTo(source: Type, target: Type): Boolean {
        val sf = source.flags
        val tf = target.flags
        // Any target accepts everything
        if (tf.hasAny(TypeFlags.Any)) return true
        // Any source is assignable to everything (any is both top and bottom type)
        if (sf.hasAny(TypeFlags.Any)) return true
        // Unknown target accepts everything (for assignability)
        if (tf.hasAny(TypeFlags.Unknown)) return true
        // Never source is assignable to everything
        if (sf.hasAny(TypeFlags.Never)) return true
        // Same type by identity
        if (source === target) return true
        // Literal value comparison (different instances with same value)
        if (source is Type.StringLiteral && target is Type.StringLiteral && source.value == target.value) return true
        if (source is Type.NumberLiteral && target is Type.NumberLiteral && source.value == target.value) return true
        if (source is Type.BigIntLiteral && target is Type.BigIntLiteral && source.value == target.value) return true
        // Primitive widening: string literal → string, number literal → number, etc.
        if (sf.hasAny(TypeFlags.StringLiteral) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLiteral) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLiteral) && tf.hasAny(TypeFlags.BigInt)) return true
        if (sf.hasAny(TypeFlags.BooleanLiteral) && tf.hasAny(TypeFlags.Boolean)) return true
        if (sf.hasAny(TypeFlags.EnumLiteral) && tf.hasAny(TypeFlags.Enum)) return true
        if (sf.hasAny(TypeFlags.UniqueESSymbol) && tf.hasAny(TypeFlags.ESSymbol)) return true
        // String-like types to string
        if (sf.hasAny(TypeFlags.StringLike) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLike) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLike) && tf.hasAny(TypeFlags.BigInt)) return true
        // undefined → void
        if (sf.hasAny(TypeFlags.Undefined) && tf.hasAny(TypeFlags.Void)) return true
        // void → undefined (void is treated as undefined for assignability)
        if (sf.hasAny(TypeFlags.Void) && tf.hasAny(TypeFlags.Undefined)) return true
        // When strict null checks are off, null/undefined assignable to everything
        if (!strictNullChecks && sf.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return true
        // number → enum type (TypeScript allows number → enum)
        if (sf.hasAny(TypeFlags.NumberLike) && target is Type.Object && target.symbol != null &&
            target.symbol!!.flags.hasAny(SymbolFlags.Enum)) return true
        // object type (non-primitive) — primitives are NOT assignable to object
        if (tf.hasAny(TypeFlags.NonPrimitive)) {
            return !sf.hasAny(TypeFlags.Primitive or TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)
        }
        return false
    }

    /**
     * 4b. Main entry point for type relation checking with error reporting.
     * Returns true if source is related to target in the given relation.
     */
    private fun checkTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        if (source === target) return true
        // Fast check
        if (isSimpleTypeRelatedTo(source, target)) return true
        // Check cache
        val cached = relation.get(source.id, target.id)
        if (cached == Ternary.True) return true
        if (cached == Ternary.False) return false
        // Depth limit (safety net)
        if (relationDepth >= maxRelationDepth) return false
        // Cycle detection: if we're already comparing this (source, target) pair,
        // assume compatibility to break the cycle (TypeScript's approach for recursive types).
        val pairKey = packRelationKey(source.id, target.id)
        if (pairKey in state.relationComparisonStack) {
            relationUsedCycleBreak = true
            return true
        }
        // Deeply-nested heuristic (matches TypeScript's `isDeeplyNestedType`): when
        // either side's `target.id` already appears 5+ times on its respective stack,
        // assume compatibility. Catches infinitely-expanding generic comparisons like
        // `A<T> { x: A<()=>T> }` vs `B<T> { x: B<()=>T> }` whose Refs grow unboundedly
        // and never re-occur identically (so id-based cycle detection alone never fires).
        val srcRef = source as? Type.Reference
        val tgtRef = target as? Type.Reference
        if (srcRef != null && countOccurrences(state.relationSourceTargets, srcRef.target.id) >= 5) {
            relationUsedCycleBreak = true
            return true
        }
        if (tgtRef != null && countOccurrences(state.relationTargetTargets, tgtRef.target.id) >= 5) {
            relationUsedCycleBreak = true
            return true
        }
        state.relationComparisonStack.add(pairKey)
        if (srcRef != null) state.relationSourceTargets.add(srcRef.target.id)
        if (tgtRef != null) state.relationTargetTargets.add(tgtRef.target.id)
        relationDepth++
        val savedCycleBreak = relationUsedCycleBreak
        relationUsedCycleBreak = false
        val result = structuredTypeRelatedTo(source, target, relation)
        val usedCycle = relationUsedCycleBreak
        relationUsedCycleBreak = savedCycleBreak || usedCycle
        relationDepth--
        if (tgtRef != null) state.relationTargetTargets.removeAt(state.relationTargetTargets.lastIndex)
        if (srcRef != null) state.relationSourceTargets.removeAt(state.relationSourceTargets.lastIndex)
        state.relationComparisonStack.remove(pairKey)
        // Only cache "true" results that were NOT influenced by cycle assumptions.
        // A "true" result from cycle detection is speculative — it may be wrong
        // once the full comparison completes (typeComparisonCaching test verifies this).
        // "false" results are always safe to cache — if it failed even with the
        // cycle break giving it the benefit of the doubt, it's genuinely incompatible.
        if (!result || !usedCycle) {
            val ternary = if (result) Ternary.True else Ternary.False
            relation.set(source.id, target.id, ternary)
        }
        return result
    }

    private fun packRelationKey(a: Int, b: Int): Long =
        (a.toLong() shl 32) or (b.toLong() and 0xFFFFFFFFL)

    private fun countOccurrences(stack: List<Int>, id: Int): Int {
        var n = 0
        for (e in stack) if (e == id) n++
        return n
    }

    /**
     * 4c. Core structural comparison — handles unions, intersections, and objects.
     */
    private fun structuredTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        // Union source: each constituent must be related to the target
        if (source is Type.Union) {
            return source.types.all { checkTypeRelatedTo(it, target, relation) }
        }
        // Union target: source must be related to some constituent
        if (target is Type.Union) {
            return target.types.any { checkTypeRelatedTo(source, it, relation) }
        }
        // Intersection target: source must be related to each constituent
        if (target is Type.Intersection) {
            return target.types.all { checkTypeRelatedTo(source, it, relation) }
        }
        // Intersection source: some constituent must be related to target
        if (source is Type.Intersection) {
            return source.types.any { checkTypeRelatedTo(it, target, relation) }
        }
        // Generic type references with matching target: compare type arguments directly.
        // For Ref<A> vs Ref<B> (same target), check A → B instead of full structural
        // comparison. Structural comparison would otherwise pass trivially because our
        // built-in lib methods resolve to anyType and property types containing type
        // parameters resolve to errorType when the param isn't in scope. Covariant
        // arg comparison (each source arg assignable to the matching target arg) matches
        // Array's existing behavior and is the pragmatic default for built-in generic
        // containers (Array, Map, Promise, etc.). Cycle detection for self-referential
        // generics like `interface List<T> { next: List<T> }` is handled by
        // `relationComparisonStack` in `checkTypeRelatedTo`.
        //
        // Skip the shortcut when any target arg is `void`: the void-return-type rule
        // (a signature returning T is assignable to one returning void) applies
        // transitively when a type arg appears in a covariant return position inside
        // the generic (e.g. `B<T> { x(): T }` — `B<number>` should be assignable to
        // `B<void>`). We don't have variance info, so fall back to structural
        // comparison in this case — it preserves the prior trivial-pass behavior.
        if (source is Type.Reference && target is Type.Reference &&
            source.target === target.target) {
            val sourceArgs = source.resolvedTypeArguments
            val targetArgs = target.resolvedTypeArguments
            if (sourceArgs != null && targetArgs != null && sourceArgs.size == targetArgs.size &&
                targetArgs.none { it.flags.hasAny(TypeFlags.Void) }) {
                // Skip the arg-shortcut on re-entry: when this target already appears
                // earlier on the comparison stacks, an eager false here would prevent
                // structural recursion from reaching the cycle-break or deeply-nested
                // bail-out (regresses recursiveTypeComparison, infinitelyExpandingTypes,
                // etc. — Observable<{}> vs Observable<number> reached via propertiesRelatedTo
                // must defer to structural so the inner needThisOne self-reference cycle-breaks).
                // count > 1 because the current pair was already pushed by checkTypeRelatedTo.
                val tid = source.target.id
                val isReentry = countOccurrences(state.relationSourceTargets, tid) > 1 ||
                    countOccurrences(state.relationTargetTargets, tid) > 1
                if (!isReentry) {
                    for (i in sourceArgs.indices) {
                        if (!checkTypeRelatedTo(sourceArgs[i], targetArgs[i], relation)) return false
                    }
                    return true
                }
            }
        }
        // B75.2: Array-derived source → ReadonlyArray<T> target — covariant element shortcut.
        // TypeScript treats `ReadonlyArray<T>` covariantly in T: any `Array<U>`-derived
        // value is assignable to `ReadonlyArray<T>` when `U → T`. Without this, both
        // plain `Array<U>` and SUBCLASS-of-Array (e.g. `class C<T> extends Array<T>`)
        // vs `ReadonlyArray<A>` fall through to `objectTypeRelatedTo` → spurious
        // `concat`-method contravariance mismatch (`(...items: U[]) => U[]` vs
        // `(...items: A[]) => A[]`) because we don't have per-typeparam variance info
        // to mark `concat`'s element-type position as covariant. Pre-B75.1 this worked
        // by accident because ReadonlyArray collapsed onto globalArrayType (same target,
        // covariant arg shortcut applied). Direct extraction via Array's base-type chain
        // restores the behavior cleanly. Plain `Array<U>` source: directly use source.args.
        // Subclass-of-Array: walk source's target's baseTypes to find an Array<U>-shaped
        // ancestor, instantiate with source's args.
        if (source is Type.Reference && target is Type.Reference &&
            globalReadonlyArrayType != null && target.target === globalReadonlyArrayType &&
            source.target !== globalReadonlyArrayType) {
            val targetArgs = target.resolvedTypeArguments
            if (targetArgs != null && targetArgs.size == 1) {
                if (source.target === globalArrayType) {
                    val srcArgs = source.resolvedTypeArguments
                    if (srcArgs != null && srcArgs.size == 1) {
                        if (checkTypeRelatedTo(srcArgs[0], targetArgs[0], relation)) {
                            return true
                        }
                    }
                } else {
                    val srcInterface = source.target as? Type.Interface
                    if (srcInterface != null) {
                        if (srcInterface.baseTypes == null) resolveBaseTypesLazy(srcInterface)
                        val srcBaseTypes = srcInterface.baseTypes
                        val srcTypeParams = srcInterface.typeParameters ?: emptyList()
                        val srcInstArgs = source.resolvedTypeArguments ?: emptyList()
                        if (srcBaseTypes != null && srcTypeParams.size == srcInstArgs.size) {
                            val mapper = createTypeMapper(srcTypeParams, srcInstArgs)
                            for (baseType in srcBaseTypes) {
                                val baseRef = baseType as? Type.Reference ?: continue
                                if (baseRef.target !== globalArrayType &&
                                    baseRef.target !== globalReadonlyArrayType) continue
                                val baseArgs = baseRef.resolvedTypeArguments ?: continue
                                if (baseArgs.size != 1) continue
                                val instElt = instantiateType(baseArgs[0], mapper)
                                if (checkTypeRelatedTo(instElt, targetArgs[0], relation)) {
                                    return true
                                }
                            }
                        }
                    }
                }
            }
        }
        // Object types: structural comparison
        if (source is Type.Object && target is Type.Object) {
            return objectTypeRelatedTo(source, target, relation)
        }
        // Primitive source vs Object target: use the source's apparent (wrapper) type
        // and recurse. `string` → `Object` is assignable because `String` (wrapper)
        // extends `Object`. Without this, primitives fail to satisfy any object
        // constraint that mentions `Object` even though TypeScript treats them as
        // assignable via apparent type.
        // Scope: bare named interfaces only (Type.Interface). Skip Type.Reference
        // (generic instantiations like `Promise<number>` need true assignability —
        // an async function returning `1` should compare via Awaited unwrapping,
        // not via Number-wrapper-extends-Object). Also skip wrapper interfaces
        // themselves so TS2322 keeps firing for primitive→mismatched-wrapper.
        if (target is Type.Interface && target !is Type.Reference &&
            (source is Type.Intrinsic || source is Type.StringLiteral ||
                source is Type.NumberLiteral || source is Type.BigIntLiteral)) {
            val targetName = target.symbol?.name
            val isWrapperTarget = targetName in WRAPPER_INTERFACE_NAMES
            if (isWrapperTarget) {
                // B69.8: Primitive → matching wrapper assignment is allowed via
                // auto-boxing. `number → Number`, `string → String`, etc.
                // `boolean → Boolean` (including literal true/false) is also valid.
                val srcIntrinsicName = (source as? Type.Intrinsic)?.intrinsicName
                val matchingWrapper = when {
                    source is Type.NumberLiteral || srcIntrinsicName == "number" -> "Number"
                    source is Type.StringLiteral || srcIntrinsicName == "string" -> "String"
                    source is Type.BigIntLiteral || srcIntrinsicName == "bigint" -> "BigInt"
                    srcIntrinsicName == "boolean" || source.flags.hasAny(TypeFlags.BooleanLiteral) -> "Boolean"
                    srcIntrinsicName == "symbol" -> "Symbol"
                    else -> null
                }
                if (matchingWrapper != null && targetName == matchingWrapper) return true
            } else {
                val apparent = getApparentType(source)
                if (apparent !== source && apparent is Type.Object) {
                    return checkTypeRelatedTo(apparent, target, relation)
                }
            }
        }
        // TypeParam vs TypeParam: relate via apparent types (constraint, or {} when
        // unconstrained). Matters for generic-method signature comparison where source's
        // K and target's K (separate fresh params from `resolveGenericPropertyType`) would
        // otherwise compare as opaque-and-distinct → spurious TS2322 in tests like
        // `infinitelyExpandingTypes4` (Promise<Q.then<U_src>> vs Promise<Q.then<U_tgt>>).
        if (source is Type.TypeParam && target is Type.TypeParam) {
            val srcConstraint = source.constraint
            val tgtConstraint = target.constraint
            if (srcConstraint == null || tgtConstraint == null) return true
            return checkTypeRelatedTo(srcConstraint, tgtConstraint, relation)
        }
        return false
    }

    /**
     * Structural comparison of two object types.
     * Checks properties, call signatures, and construct signatures.
     * For class instance types, skip construct signature comparison — those belong
     * to the static side (typeof Class), not the instance type.
     */
    private fun objectTypeRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        // Check properties
        if (!propertiesRelatedTo(source, target, relation)) return false
        // Check call signatures
        if (!signaturesRelatedTo(source, target, relation, isConstruct = false)) return false
        // Check construct signatures — skip for class/interface instance types where
        // construct signatures come from the class constructor (static side), not the instance.
        val isClassInstance = target is Type.Interface && target.symbol != null &&
            target.symbol!!.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)
        if (!isClassInstance) {
            if (!signaturesRelatedTo(source, target, relation, isConstruct = true)) return false
        }
        // Check index signatures: if target has a string/number index signature but source
        // (a named class/interface) doesn't declare one, TypeScript rejects the assignment
        // with "Index signature for type '<kind>' is missing in type 'X'." This only applies
        // to NOMINAL source types (named class/interface) — anonymous object literals use
        // a different rule where properties individually satisfy the index type.
        // Type.Reference's own `symbol` is null; its target's symbol carries the nominal info.
        // Skip when the target's index type accepts `any`/`unknown` — any source satisfies
        // it implicitly so emitting "missing index signature" would be a FP (cf.
        // `assignmentCompatability36_ts`'s `{[k:string]:any}` target).
        val srcNominalSym = source.symbol ?: (source as? Type.Reference)?.target?.symbol
        val isNominalSource = srcNominalSym != null &&
            srcNominalSym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)
        // 17.74: Function-shaped sources (callSignatures only, no nominal members)
        // also trigger the missing-index-sig check — mirrors TypeScript's "Index
        // signature for type 'number' is missing in type '() => void'." for
        // `func: () => void; const a: ArrayLike<any> = func;`. Note: for function
        // sources we DON'T skip when target's index type is `any`/`unknown` — a
        // function type doesn't implicitly satisfy `[n:number]:any` (unlike a
        // nominal class which can be subclassed/extended), so the diagnostic IS
        // appropriate. The `any`-skip remains for nominal sources to avoid FPs
        // (cf. `assignmentCompatability36_ts`).
        val isFunctionShaped = !source.callSignatures.isNullOrEmpty() && source.members.isNullOrEmpty()
        if (isNominalSource || isFunctionShaped) {
            val tgtStr = target.stringIndexInfo
            if (tgtStr != null && source.stringIndexInfo == null &&
                (isFunctionShaped || !tgtStr.type.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown))) {
                lastMissingIndexSigKind = "string"
                return false
            }
            val tgtNum = target.numberIndexInfo
            if (tgtNum != null && source.numberIndexInfo == null &&
                (isFunctionShaped || !tgtNum.type.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown))) {
                lastMissingIndexSigKind = "number"
                return false
            }
        }
        return true
    }

    /**
     * 4d. Property-by-property structural comparison.
     * For each required property in target, source must have a compatible property.
     */
    private fun propertiesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        val targetProps = target.properties ?: return true
        val sourceHasCallSigs = !source.callSignatures.isNullOrEmpty()
        val sourceMembers = source.members ?: if (sourceHasCallSigs) emptyMap() else return targetProps.isEmpty()
        // Statics filter: when target carries a static side (class declaration),
        // skip target.properties entries that live on the static side. Instance-vs-
        // instance shape comparison must not see `static bar()` on either side.
        // Type.Reference defers to its target Interface's staticMembers.
        val targetStatics = getStaticMembersOfType(target)
        for (targetProp in targetProps) {
            val targetName = targetProp.name
            if (targetStatics != null && targetStatics.containsKey(targetName)) continue
            // Inherited Object prototype members (constructor, toString, valueOf, …)
            // are never "missing" — every JS object has them via the prototype chain.
            // Without this filter, an empty `{a:string}` fails to satisfy `Object` because
            // `constructor` etc. are listed as Object's own properties in our embedded lib.
            // B67.3: only skip when source doesn't EXPLICITLY define this property — if
            // source has its own `toString: 5`, fall through to the type-compatibility
            // check (number vs () => string emits TS2322 per `assignmentToObject_ts`).
            if (targetName in OBJECT_PROTOTYPE_PROPERTIES && !sourceMembers.containsKey(targetName)) continue
            // 17.27: When source is a function type (has callSignatures), Function.prototype
            // methods (call/apply/bind) are implicitly available through the apparent type.
            // Lets `() => void` satisfy `interface Callable { call(blah: any) }` etc.
            if (sourceHasCallSigs && targetName in FUNCTION_PROTOTYPE_METHODS) continue
            // B66.4: Function-side runtime properties (prototype/arguments/caller) are
            // implicitly available on any function value via Function.prototype.
            // Lets a function expression / arrow satisfy the `Function` interface.
            if (sourceHasCallSigs && targetName in FUNCTION_RUNTIME_PROPERTIES) continue
            // 17.74: Function.prototype's `length: number` and `name: string` implicitly
            // satisfy the corresponding target property when source has callSignatures.
            // Lets `() => void` satisfy `interface ArrayLike<T> { length: number }` —
            // clears the way for the index-signature-missing check to fire (matching
            // TypeScript's elaboration which prefers "Index signature missing" over
            // "Property 'length' missing" for function-vs-ArrayLike-shape comparisons).
            if (sourceHasCallSigs && (targetName == "length" || targetName == "name")) {
                val targetPropType = getPropertyTypeForRelation(target, targetProp)
                val protoType = if (targetName == "length") numberType else stringType
                if (checkTypeRelatedTo(protoType, targetPropType, relation)) continue
            }
            // Check if property is optional (question mark in declaration)
            val isOptional = isOptionalProperty(targetProp)
            val sourceProp = sourceMembers[targetName]
            if (sourceProp == null) {
                // Check index signature
                val indexInfo = source.stringIndexInfo
                if (indexInfo != null) {
                    val targetPropType = getPropertyTypeForRelation(target, targetProp)
                    if (!checkTypeRelatedTo(indexInfo.type, targetPropType, relation)) return false
                    continue
                }
                if (!isOptional) {
                    lastMissingPropertyName = targetName
                    lastMissingPropertySymbol = targetProp
                    return false // missing required property
                }
                continue
            }
            // Private-brand mismatch: if both source and target declare this property as
            // `private` but on different parent classes, TypeScript treats them as unrelated
            // nominal shapes even though the declared types are structurally equal.
            // Matches `typeIdentityConsidersBrands_ts` etc.
            if (isPropPrivateBrandMismatch(sourceProp, targetProp)) {
                lastPrivateBrandMismatchName = targetName
                return false
            }
            // Compare property types
            val sourcePropType = getPropertyTypeForRelation(source, sourceProp)
            val targetPropType = getPropertyTypeForRelation(target, targetProp)
            val effectiveSource = widenOptionalSourcePropType(sourcePropType, sourceProp, targetProp)
            if (!checkTypeRelatedTo(effectiveSource, targetPropType, relation)) return false
        }
        return true
    }

    /**
     * Scan source and target's own members for any shared property name where both sides
     * declare it as `private` on different parent classes. Used to opt the conservative
     * TS2345 guard into running a full assignability check for named→named class args.
     */
    private fun hasPrivateBrandMismatchBetween(source: Type.Object, target: Type.Object): Boolean {
        return findPrivateBrandMismatchName(source, target) != null
    }

    /**
     * Return the first property name where both source and target declare a private property
     * on different parent classes, or null when no such nominal mismatch exists.
     */
    private fun findPrivateBrandMismatchName(source: Type.Object, target: Type.Object): String? {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val sMembers = source.members ?: return null
        val tMembers = target.members ?: return null
        for ((name, tProp) in tMembers) {
            val sProp = sMembers[name] ?: continue
            if (isPropPrivateBrandMismatch(sProp, tProp)) return name
        }
        return null
    }

    /**
     * Detect TypeScript's "separate declarations of a private property" nominal brand check.
     * Two properties are brand-incompatible when both are declared `private` AND their
     * declaring parent classes differ by identity. Properties that share a single declaration
     * (e.g. inherited from the same base class) remain compatible.
     */
    private fun isPropPrivateBrandMismatch(sourceProp: Symbol, targetProp: Symbol): Boolean {
        val sDecl = sourceProp.valueDeclaration ?: sourceProp.declarations.firstOrNull() ?: return false
        val tDecl = targetProp.valueDeclaration ?: targetProp.declarations.firstOrNull() ?: return false
        if (sDecl === tDecl) return false
        if (!isMemberPrivate(sDecl) || !isMemberPrivate(tDecl)) return false
        val sParent = findParentClassOrInterface(sDecl)
        val tParent = findParentClassOrInterface(tDecl)
        return sParent != null && tParent != null && sParent !== tParent
    }

    private fun findParentClassOrInterface(node: Node): Node? {
        // The parent isn't stored on the AST; look up via the property symbol's parent's
        // declarations to find the enclosing class.
        val propName = when (node) {
            is PropertyDeclaration -> (node.name as? Identifier)?.text
            is MethodDeclaration -> (node.name as? Identifier)?.text
            is GetAccessor -> (node.name as? Identifier)?.text
            is SetAccessor -> (node.name as? Identifier)?.text
            else -> null
        } ?: return null
        // Walk all class declarations looking for one whose members contain `node` by identity.
        for (sym in globals.values) {
            if (!sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)) continue
            for (decl in sym.declarations) {
                val members = when (decl) {
                    is ClassDeclaration -> decl.members
                    is InterfaceDeclaration -> decl.members
                    else -> continue
                }
                if (members.any { it === node }) return decl
            }
        }
        return null
    }

    /**
     * 16.4df step (b): For Type.Reference sources/targets, substitute the property's
     * declared type via the reference's type-arg mapper (`resolveGenericPropertyType`)
     * before comparison. This prevents trivial-pass on raw `T` for cases that step (a)
     * cannot catch — e.g. `Derived<string>` vs `Base<number>` where source/target have
     * DIFFERENT target interfaces. Self-referential generics (`List<T> { next: List<T> }`)
     * are now safe because Type.Reference interning makes logically-identical Refs share
     * an id, so `relationComparisonStack` catches the cycle.
     *
     * Method handling relies on `resolvedPropertyTypes` caching to avoid OOM in
     * Promise/IPromise-style deep overload-permutation comparisons (each level would
     * otherwise allocate fresh Symbols/Signatures/Type.Object instances).
     *
     * Falls back to raw `getTypeOfSymbol` when the helper returns null (non-passthrough
     * inherited property or non-Reference object type).
     */
    private fun getPropertyTypeForRelation(obj: Type.Object, prop: Symbol): Type {
        if (obj is Type.Reference && relationDepth < 4) {
            // Skip when we're already deep in a comparison: deep generic-method
            // recursion (Promise/IPromise overload permutations, bluebird-style)
            // allocates a fresh Symbol/Signature/Type.Object per call, OOMing
            // before the deeply-nested heuristic can bail. Outer layers still
            // benefit from substituted property types; inner layers fall back
            // to raw `getTypeOfSymbol` (errorType for unbound T) which the
            // existing trivial-pass path handles.
            resolveGenericPropertyType(obj, prop)?.let { return it }
        }
        return getTypeOfSymbol(prop)
    }

    /**
     * Collect all non-optional property names from targetType that are missing from sourceType.
     * Used to decide between TS2741 (single missing) and TS2740 (multiple missing).
     *
     * Returns an empty list when `source.members` is null — e.g., anonymous function
     * types from `() => T` whose `Type.Object` carries only call signatures. In that
     * case the comparison failure is a kind mismatch (callable vs shape), not a
     * "property X is missing" situation, so the caller should fall through to plain
     * TS2322 instead of TS2739/TS2741. Matches TypeScript's baseline for tests like
     * `assigningFunctionToTupleIssuesError_ts` (`() => void` → `[string]`).
     */
    private fun collectMissingProperties(sourceType: Type, targetType: Type): List<String> {
        if (sourceType !is Type.Object || targetType !is Type.Object) return emptyList()
        resolveStructuredTypeMembers(sourceType)
        resolveStructuredTypeMembers(targetType)
        val sourceMembers = sourceType.members ?: return emptyList()
        val targetProps = targetType.properties ?: return emptyList()
        val targetStatics = getStaticMembersOfType(targetType)
        // Round 53 iter7: when target is the `Function` interface, `toString` is a
        // real own member (declared on Function itself, returns the function source),
        // not Object.prototype.toString. Allow it through the OBJECT_PROTOTYPE_PROPERTIES
        // filter so missing-property counts match TypeScript for Function-typed targets.
        val targetIsFunction = targetType is Type.Interface && targetType.symbol?.name == "Function"
        val missing = mutableListOf<String>()
        for (prop in targetProps) {
            if (isOptionalProperty(prop)) continue
            // Skip target static members — they live on the class's static side and
            // are not part of the instance shape we're comparing against.
            if (targetStatics != null && targetStatics.containsKey(prop.name)) continue
            val isPrototypeProp = prop.name in OBJECT_PROTOTYPE_PROPERTIES
            val isFunctionOwnToString = targetIsFunction && prop.name == "toString"
            if (prop.name !in sourceMembers && (!isPrototypeProp || isFunctionOwnToString)) {
                missing.add(prop.name)
            }
        }
        return missing
    }

    /**
     * Format a TS2740 message: "Type 'X' is missing the following properties from type 'Y': a, b, c, and N more."
     * Lists up to 4 property names; if >5 total, appends "and N more".
     */
    /**
     * B50.10: Detect the `Object`-source-to-named-target shape that warrants
     * TS2696 "The 'Object' type is assignable to very few other types. Did you
     * mean to use the 'any' type instead?" instead of plain TS2739/TS2740. The
     * source must be the lib `Object` interface (named, no own type args), and
     * the target a different named class/interface. Anonymous-object sources
     * and `Object`-target cases fall through to the standard chain.
     */
    private fun shouldEmitTs2696ForObject(source: Type, target: Type): Boolean {
        if (source !is Type.Interface) return false
        if (source.symbol?.name != "Object") return false
        if (target !is Type.Interface) return false
        if (target.symbol == null || target.symbol?.name == "Object") return false
        return true
    }

    private fun formatTs2740Message(displaySource: String, displayTarget: String, missing: List<String>): String {
        val listed = if (missing.size > 5) missing.take(4) else missing
        val suffix = if (missing.size > 5) ", and ${missing.size - 4} more." else ""
        return "Type '$displaySource' is missing the following properties from type '$displayTarget': ${listed.joinToString(", ")}$suffix"
    }

    /**
     * Collects all property names from a target type, flattening intersections and interfaces.
     * Returns null if the type cannot be used for excess property checking.
     */
    private fun collectTargetPropertyNames(type: Type): Set<String>? {
        return when (type) {
            is Type.Object -> {
                // If the target has a string index signature, any string-keyed property is valid
                if (type.stringIndexInfo != null) return null
                type.members?.keys?.toSet()
            }
            is Type.Interface -> {
                // If the target has a declared string index signature, any string-keyed property is valid
                if (type.declaredStringIndexInfo != null || type.stringIndexInfo != null) return null
                type.members?.keys?.toSet()
            }
            is Type.Intersection -> {
                val names = mutableSetOf<String>()
                for (constituent in type.types) {
                    // If any constituent has a string index signature, all properties are valid
                    val constituentNames = collectTargetPropertyNames(constituent)
                    if (constituentNames == null) return null
                    names.addAll(constituentNames)
                }
                if (names.isEmpty()) null else names
            }
            is Type.Union -> {
                // 16.0: Union target — a source property is excess only if it's in NONE
                // of the union constituents. Take the union of all object/interface constituent
                // property names. Non-shape constituents (primitives, function-only object
                // types) don't contribute property names and are skipped. If any shape
                // constituent has a string index signature, all keys are valid → bail.
                val names = mutableSetOf<String>()
                var hasShapeConstituent = false
                for (constituent in type.types) {
                    if (constituent !is Type.Object && constituent !is Type.Interface) continue
                    resolveStructuredTypeMembers(constituent)
                    val cObj = constituent as Type.Object
                    // Skip function-only types (call sigs but no members)
                    if (cObj.members == null) continue
                    val constituentNames = collectTargetPropertyNames(constituent)
                    if (constituentNames == null) return null // string index sig → bail
                    names.addAll(constituentNames)
                    hasShapeConstituent = true
                }
                if (!hasShapeConstituent) null
                else if (names.isEmpty()) null
                else names
            }
            else -> null
        }
    }

    /**
     * For union target display in TS2353, pick the first Object/Interface constituent
     * that contains none of the excess source property names (i.e., the constituent
     * whose shape the source was "meant" to match). Fallback: first object constituent.
     */
    private fun pickUnionDisplayTarget(unionType: Type.Union): Type? {
        for (c in unionType.types) {
            if (c is Type.Object || c is Type.Interface) return c
        }
        return null
    }

    /**
     * 16.0: Check that the RHS of an `in` expression is an object-like type.
     * Emits TS2322 "Type 'X' is not assignable to type 'object'." for primitive
     * RHS types like `'' in 0` or `0 in 'foo'`.
     */
    private fun checkInOperatorRhs(rhs: Expression, source: String, fileName: String) {
        try {
            val rhsType = getTypeOfExpression(rhs)
            if (rhsType === anyType || rhsType === errorType) return
            if (rhsType === unknownType) return
            // null/undefined are valid (handled separately by strictNullChecks)
            if (rhsType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return
            // Object/Interface/Reference types are valid
            if (rhsType is Type.Object || rhsType is Type.Interface) return
            if (rhsType is Type.TypeParam) return // generic — accept conservatively
            // Primitive types are invalid for `in` RHS
            val isPrimitive = rhsType.flags.hasAny(
                TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
                TypeFlags.BigInt or TypeFlags.ESSymbol or TypeFlags.Void or
                TypeFlags.Never or
                TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
                TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
                TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral or
                TypeFlags.Enum
            )
            if (!isPrimitive) return
            val displaySource = typeToString(rhsType)
            val start = rhs.pos
            val length = expressionTrueEnd(rhs) - start
            if (length <= 0) return
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type 'object'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * TS2367: "This comparison appears to be unintentional because the types
     * 'A' and 'B' have no overlap."
     *
     * Narrow scope: both sides must be `Type.Reference` sharing the same
     * target interface with incompatible type arguments (e.g. `l == l2`
     * where `l: List<number>`, `l2: List<string>`). Broader overlap rules
     * (primitives, unions, literal members) are intentionally NOT checked
     * here — each carries its own FP risk and would need a wider
     * investigation. Mutual-assignability tests piggyback on the existing
     * step (a) infrastructure in `structuredTypeRelatedTo`.
     */
    private fun checkEqualityComparisonNoOverlap(
        expr: BinaryExpression, source: String, fileName: String,
    ) {
        try {
            val leftType = getTypeOfExpression(expr.left)
            val rightType = getTypeOfExpression(expr.right)
            if (leftType === anyType || leftType === errorType) return
            if (rightType === anyType || rightType === errorType) return
            if (leftType === unknownType || rightType === unknownType) return
            if (leftType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
            if (rightType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
            // 17.73: TypeParam-with-literal-union-constraint vs literal — when one
            // side is a TypeParam whose apparent type is a union of all literals
            // (e.g. `T extends "a" | "b"`) and the other side is a literal, use
            // the literal-subtype-aware intersection helper to detect empty
            // overlap. If empty (never), emit TS2367 with the TypeParam's NAME
            // (not its constraint) so the message reads `... types 'T' and '"x"'
            // have no overlap.` matching TypeScript's display.
            checkTypeParamLiteralNoOverlap(expr, leftType, rightType, source, fileName)?.let { return }
            // B53.2: Named Type.Object non-overlap detection. When both sides are
            // distinct named (non-anonymous, non-Reference) object types with no shared
            // required property names, emit TS2367. Gate: both Type.Object with a
            // non-null symbol (rules out anonymous `{a:1}` literals), different symbols,
            // neither assignable to the other, and ALL required props of one side absent
            // from the other. Uses the same `import("X").T` cross-file qualification as
            // B53.1 when display names collide.
            val leftObjSym = (leftType as? Type.Object)?.symbol
            val rightObjSym = (rightType as? Type.Object)?.symbol
            // B63.32: Same-name cross-file interfaces. When two distinct Type.Interface
            // instances share the same display name but are declared in different files
            // (typical pattern: `import * as A from './a'; import * as B from './b';
            // declare let a: A.F; declare let b: B.F`), `mergeSymbolTable` pollutes one
            // side's `properties` with the other side's members. Use own-file declaration
            // names directly for disjointness check, bypassing the merged Type.Interface
            // contents. Emits TS2367 with `import("X").T` cross-file qualification.
            if (leftType is Type.Object && rightType is Type.Object &&
                leftType !is Type.Reference && rightType !is Type.Reference &&
                leftObjSym != null && rightObjSym != null && leftObjSym !== rightObjSym &&
                leftObjSym.name == rightObjSym.name) {
                val leftImport = getSymbolImportName(leftObjSym)
                val rightImport = getSymbolImportName(rightObjSym)
                if (leftImport != null && rightImport != null && leftImport != rightImport) {
                    val leftOwn = getOwnFileInterfacePropertyNames(leftObjSym, leftImport)
                    val rightOwn = getOwnFileInterfacePropertyNames(rightObjSym, rightImport)
                    if (leftOwn != null && rightOwn != null &&
                        leftOwn.isNotEmpty() && rightOwn.isNotEmpty() &&
                        leftOwn.intersect(rightOwn).isEmpty()) {
                        val leftDispRaw = typeToString(leftType)
                        val rightDispRaw = typeToString(rightType)
                        val leftDisp = "import(\"$leftImport\").$leftDispRaw"
                        val rightDisp = "import(\"$rightImport\").$rightDispRaw"
                        val start = expr.pos
                        val length = expressionTrueEnd(expr.right) - start
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
                                category = DiagnosticCategory.Error,
                                code = 2367,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                        return
                    }
                }
            }
            if (leftType is Type.Object && rightType is Type.Object &&
                leftType !is Type.Reference && rightType !is Type.Reference &&
                leftObjSym != null && rightObjSym != null && leftObjSym !== rightObjSym) {
                resolveStructuredTypeMembers(leftType)
                resolveStructuredTypeMembers(rightType)
                val leftProps = leftType.properties ?: emptyList()
                val rightProps = rightType.properties ?: emptyList()
                val leftRequired = leftProps.filter { !isOptionalProperty(it) && it.name !in OBJECT_PROTOTYPE_PROPERTIES }
                val rightRequired = rightProps.filter { !isOptionalProperty(it) && it.name !in OBJECT_PROTOTYPE_PROPERTIES }
                if (leftRequired.isNotEmpty() && rightRequired.isNotEmpty()) {
                    val rightMembers = rightType.members
                    val leftMembers = leftType.members
                    val leftAbsentFromRight = leftRequired.all { rightMembers?.get(it.name) == null }
                    val rightAbsentFromLeft = rightRequired.all { leftMembers?.get(it.name) == null }
                    if (leftAbsentFromRight && rightAbsentFromLeft &&
                        !checkTypeRelatedTo(leftType, rightType, assignableRelation) &&
                        !checkTypeRelatedTo(rightType, leftType, assignableRelation)) {
                        var leftDisp = typeToString(leftType)
                        var rightDisp = typeToString(rightType)
                        if (leftDisp == rightDisp) {
                            val li = getSymbolImportName(leftObjSym)
                            val ri = getSymbolImportName(rightObjSym)
                            if (li != null && ri != null && li != ri) {
                                leftDisp = "import(\"$li\").$leftDisp"
                                rightDisp = "import(\"$ri\").$rightDisp"
                            }
                        }
                        val start = expr.pos
                        val length = expressionTrueEnd(expr.right) - start
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
                                category = DiagnosticCategory.Error,
                                code = 2367,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                        return
                    }
                }
            }
            if (leftType !is Type.Reference || rightType !is Type.Reference) return
            if (leftType.target !== rightType.target) return
            val leftArgs = leftType.resolvedTypeArguments ?: return
            val rightArgs = rightType.resolvedTypeArguments ?: return
            if (leftArgs.size != rightArgs.size) return
            if (leftArgs == rightArgs) return
            if (checkTypeRelatedTo(leftType, rightType, assignableRelation)) return
            if (checkTypeRelatedTo(rightType, leftType, assignableRelation)) return
            val leftDisp = typeToString(leftType)
            val rightDisp = typeToString(rightType)
            val start = expr.pos
            val length = expressionTrueEnd(expr.right) - start
            if (length <= 0) return
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
                category = DiagnosticCategory.Error,
                code = 2367,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * 17.73: TS2367 narrow extension — TypeParam-with-literal-union-constraint
     * vs literal. Returns Unit (non-null) if a TS2367 diagnostic was emitted,
     * null if the pattern didn't apply. Uses the 17.72 [intersectTwoTypesForWrite]
     * helper to compute the apparent-type intersection with full union
     * distribution + literal subtype reduction.
     *
     * Pattern: `t === "x"` where `t: T` and `T extends "a" | "b"` — apparent
     * type of T is `"a" | "b"`; intersection with `"x"` distributes to
     * `"a" & "x" | "b" & "x"` = `never`. When the apparent type is NOT a
     * union of all literals (e.g. `T extends string`), bail — that case is
     * a primitive vs literal pair which would still overlap (`string & "x"`
     * = `"x"`).
     */
    private fun checkTypeParamLiteralNoOverlap(
        expr: BinaryExpression,
        leftType: Type,
        rightType: Type,
        source: String,
        fileName: String,
    ): Unit? {
        val literalFlags = TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral

        fun apparentLiteralUnion(t: Type): Type? {
            if (t !is Type.TypeParam) return null
            val apparent = t.constraint?.let { getApparentType(it) } ?: return null
            return when (apparent) {
                is Type.Union -> if (apparent.types.all { it.flags.hasAny(literalFlags) }) apparent else null
                else -> if (apparent.flags.hasAny(literalFlags)) apparent else null
            }
        }

        // Recover the literal-typed view of an expression that getTypeOfExpression
        // widened to its primitive (e.g. StringLiteralNode → stringType). When the
        // expression IS a literal node, [literalTypeOfExpression] returns the
        // narrow literal type — exactly what TS2367 needs to compare against the
        // TypeParam's apparent literal-union constraint.
        val leftLit = literalTypeOfExpression(expr.left)
        val rightLit = literalTypeOfExpression(expr.right)
        val leftEffective = leftLit ?: leftType
        val rightEffective = rightLit ?: rightType

        val leftIsTP = leftEffective is Type.TypeParam
        val rightIsTP = rightEffective is Type.TypeParam
        val leftIsLit = leftEffective.flags.hasAny(literalFlags)
        val rightIsLit = rightEffective.flags.hasAny(literalFlags)

        val intersected: Type? = when {
            leftIsTP && rightIsLit -> {
                val app = apparentLiteralUnion(leftEffective) ?: return null
                intersectTwoTypesForWrite(app, rightEffective)
            }
            rightIsTP && leftIsLit -> {
                val app = apparentLiteralUnion(rightEffective) ?: return null
                intersectTwoTypesForWrite(leftEffective, app)
            }
            else -> return null
        }
        if (intersected == null || !intersected.flags.hasAny(TypeFlags.Never)) return null

        // Display the un-widened TypeParam name (typeToString of leftType / rightType)
        // and the literal form of the other side — matches TypeScript's TS2367 message.
        val leftDisp = if (leftLit != null) typeToString(leftLit) else typeToString(leftType)
        val rightDisp = if (rightLit != null) typeToString(rightLit) else typeToString(rightType)
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return null
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
            category = DiagnosticCategory.Error,
            code = 2367,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return Unit
    }

    /**
     * TS2839: "This condition will always return 'false'/'true' since JavaScript
     * compares objects by reference, not value." Fires when one side of an
     * `==`/`===`/`!=`/`!==` comparison is a fresh object-/array-literal expression
     * — a newly allocated object never matches anything by reference.
     *
     * Narrow: requires the other side's type to overlap with the literal (i.e.
     * TS2367 wouldn't fire). If the other side is purely primitive without any
     * object-like constituent, the overlap check handles it as a different
     * diagnostic class.
     */
    private fun checkFreshLiteralReferenceEquality(
        expr: BinaryExpression, source: String, fileName: String,
    ) {
        val leftIsLit = expr.left is ObjectLiteralExpression || expr.left is ArrayLiteralExpression
        val rightIsLit = expr.right is ObjectLiteralExpression || expr.right is ArrayLiteralExpression
        if (!leftIsLit && !rightIsLit) return
        try {
            val otherType = getTypeOfExpression(if (leftIsLit) expr.right else expr.left)
            if (otherType === anyType || otherType === errorType || otherType === unknownType) return
            // Need at least one object-like constituent in the other side's type
            // for the "comparison by reference" message to apply (otherwise TS2367
            // would flag as no-overlap instead).
            val hasObjectLike: (Type) -> Boolean = { t ->
                t is Type.Object || t is Type.Reference || t is Type.Interface ||
                t.flags.hasAny(TypeFlags.NonPrimitive)
            }
            val overlaps = when (otherType) {
                is Type.Union -> otherType.types.any(hasObjectLike)
                else -> hasObjectLike(otherType)
            }
            if (!overlaps) return
            val op = expr.operator
            val isTruthy = op == SyntaxKind.ExclamationEquals || op == SyntaxKind.ExclamationEqualsEquals
            val verdict = if (isTruthy) "'true'" else "'false'"
            val start = expr.pos
            val length = expressionTrueEnd(expr.right) - start
            if (length <= 0) return
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "This condition will always return $verdict since JavaScript compares objects by reference, not value.",
                category = DiagnosticCategory.Error,
                code = 2839,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * 16.0: Traverse a chained assignment right-hand side to find the innermost
     * ObjectLiteralExpression. Returns null if the chain doesn't end in a literal.
     * E.g. for `obj2 = obj3 = { a: 1 }`, returns the `{a: 1}` node.
     */
    private fun findChainedObjectLiteral(expr: Expression): ObjectLiteralExpression? {
        var cur: Expression = expr
        while (cur is BinaryExpression && cur.operator == SyntaxKind.Equals) {
            cur = cur.right
        }
        return cur as? ObjectLiteralExpression
    }

    /**
     * 16.0: Compute the display target string for a TS2353 diagnostic.
     * For inline union annotations (e.g. `const x: IProps | number = {...}`), pick
     * a representative object constituent so we display "IProps" instead of
     * "IProps | number". For type alias references that resolve to a union
     * (e.g. `type DoesntWork = A | B; const x: DoesntWork = {...}`), preserve
     * the alias name from the annotation text.
     */
    private fun excessPropDisplayTarget(targetType: Type, typeAnnotation: TypeNode?): String {
        // Only narrow when the annotation itself is a UnionType (not a reference to one)
        if (targetType is Type.Union && typeAnnotation is UnionType) {
            val pick = pickUnionDisplayTarget(targetType)
            if (pick != null) return typeToString(pick)
        }
        return typeAnnotation?.let { formatTypeForDisplay(it) } ?: typeToString(targetType)
    }

    /**
     * Excess property check for fresh object literals (TS2353).
     * When an object literal is assigned to a typed target, any properties
     * in the source that don't exist in the target are excess properties.
     * Returns true if TS2353 diagnostics were emitted (caller should skip TS2741/TS2322).
     */
    /**
     * 16.0: For an array literal call argument with an Array<T> parameter type,
     * check each element against T using TS2322. Catches `foo([1, "a"])` where
     * foo takes number[]. Only fires when T is a simple checkable type to avoid
     * FPs from incomplete structural comparison.
     */
    private fun checkArrayLiteralElementsAgainstType(
        arrLit: ArrayLiteralExpression,
        arrayParamType: Type.Reference,
        source: String,
        fileName: String,
    ) {
        val elementType = arrayParamType.resolvedTypeArguments?.firstOrNull() ?: return
        if (elementType === anyType || elementType === errorType) return
        if (elementType is Type.TypeParam) return
        if (!isSimpleCheckableType(elementType)) {
            // For object element types, fall through to existing object-element TS2353 path
            if (elementType is Type.Object) {
                try {
                    resolveStructuredTypeMembers(elementType)
                    if (elementType.properties.isNullOrEmpty()) return
                    val display = typeToString(elementType)
                    for (elem in arrLit.elements) {
                        if (elem is ObjectLiteralExpression) {
                            val elemType = getTypeOfExpression(elem)
                            if (elemType is Type.Object && canUseTypeEngine(elemType, elementType)) {
                                checkExcessProperties(elem, elemType, elementType, display, source, fileName)
                            }
                        }
                    }
                } catch (_: StackOverflowError) {}
            }
            return
        }
        // Primitive element type — TS2322 per element
        try {
            for (elem in arrLit.elements) {
                if (elem is SpreadElement) continue
                val elemType = getTypeOfExpression(elem)
                if (elemType === anyType || elemType === errorType) continue
                if (!checkTypeRelatedTo(elemType, elementType, assignableRelation)) {
                    val displaySource = typeToString(elemType)
                    val displayTarget = typeToString(elementType)
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length <= 0) continue
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        } catch (_: StackOverflowError) { /* circular */ }
    }

    /**
     * 16.0: TS2353 check for each object literal element in an array literal
     * whose target is an array type with a resolvable element type. Also emits
     * TS2322 for primitive elements that aren't assignable to an Object element type.
     */
    private fun checkArrayLiteralElementExcessProps(
        init: Expression,
        targetType: Type,
        source: String,
        fileName: String,
    ) {
        if (init !is ArrayLiteralExpression) return
        if (targetType !is Type.Reference) return
        if (targetType.target?.symbol?.name != "Array") return
        val elementType = targetType.resolvedTypeArguments?.firstOrNull() ?: return
        if (elementType !is Type.Object) {
            // Primitive element type (e.g. `string[] = [voidFn()]`) — narrow void-call
            // element check. `void` call results can't satisfy any concrete primitive
            // element type. Skip if elementType is any/unknown/never/itself void.
            if (elementType is Type.Intrinsic &&
                !elementType.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never or TypeFlags.Void)) {
                val elementDisplay = typeToString(elementType)
                for (elem in init.elements) {
                    if (elem !is CallExpression) continue
                    val callType = getReturnTypeOfCallExpression(elem) ?: continue
                    if (!callType.flags.hasAny(TypeFlags.Void)) continue
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length <= 0) continue
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type 'void' is not assignable to type '$elementDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            return
        }
        try {
            resolveStructuredTypeMembers(elementType)
            if (elementType.properties.isNullOrEmpty()) return
            val elementDisplay = typeToString(elementType)
            for (elem in init.elements) {
                if (elem is SpreadElement) continue
                when (elem) {
                    is ObjectLiteralExpression -> {
                        val elemType = getTypeOfExpression(elem)
                        if (elemType is Type.Object && canUseTypeEngine(elemType, elementType)) {
                            checkExcessProperties(elem, elemType, elementType, elementDisplay, source, fileName)
                        }
                    }
                    is TypeAssertionExpression, is AsExpression -> {
                        // 17.81: Type-asserted element vs structured element-type — emit
                        // TS2741 when the asserted type is missing a required property of
                        // the target element. Cf. contextualTyping11_ts:
                        // `class foo { public bar: {id:number;}[] = [<foo>({})]; }` —
                        // the cast type `foo` lacks `id`, so element-level TS2741 fires.
                        val elemType = getTypeOfExpression(elem)
                        if (elemType !is Type.Object) continue
                        try { resolveStructuredTypeMembers(elemType) } catch (_: StackOverflowError) { continue }
                        val missingSym = getMissingRequiredPropertySymbol(elemType, elementType)
                        if (missingSym != null) {
                            val displaySource = typeToString(elemType)
                            val start = elem.pos
                            val length = expressionTrueEnd(elem) - start
                            if (length <= 0) continue
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            val relatedInfo = createPropertyDeclaredHereRelatedInfo(missingSym)
                            diagnostics.add(Diagnostic(
                                message = "Property '${missingSym.name}' is missing in type '$displaySource' but required in type '$elementDisplay'.",
                                category = DiagnosticCategory.Error,
                                code = 2741,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                                relatedInformation = listOfNotNull(relatedInfo),
                            ))
                        }
                    }
                    is ArrowFunction, is FunctionExpression -> {
                        // Skip — function expressions get checked elsewhere
                    }
                    is ArrayLiteralExpression -> {
                        // Nested array literal: if the expected element type is itself
                        // an Array<X>, recurse so the inner literal's primitive
                        // elements get checked against X. Handles `number[][][] =
                        // [[1, 2]]` shape where the inner `[1, 2]` needs each
                        // numeric literal checked against `number[]`.
                        if (elementType is Type.Reference && elementType.target?.symbol?.name == "Array") {
                            checkArrayLiteralElementExcessProps(elem, elementType, source, fileName)
                        }
                    }
                    else -> {
                        // 16.0: Primitive element vs Object element type — emit TS2322.
                        val elemType = getTypeOfExpression(elem)
                        if (elemType === anyType || elemType === errorType) continue
                        // Only flag clear primitive mismatches (not unions/objects)
                        val elemIsPrimitive = elemType is Type.Intrinsic ||
                            elemType is Type.StringLiteral || elemType is Type.NumberLiteral ||
                            elemType is Type.BigIntLiteral
                        if (!elemIsPrimitive) continue
                        // null/undefined/void → skip (strictNullChecks variance)
                        if (elemType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void or TypeFlags.Any)) continue
                        // Primitive can never be assignable to a non-empty object type.
                        // Widen literal types for display (TypeScript convention).
                        val displaySource = typeToString(getWidenedLiteralType(elemType))
                        val start = elem.pos
                        val length = expressionTrueEnd(elem) - start
                        if (length <= 0) continue
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Type '$displaySource' is not assignable to type '$elementDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 2322,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
        } catch (_: StackOverflowError) { /* circular */ }
    }

    private fun checkExcessProperties(
        objLiteral: ObjectLiteralExpression,
        sourceType: Type,
        targetType: Type,
        displayTarget: String,
        source: String,
        fileName: String,
    ): Boolean {
        if (sourceType !is Type.Object) return false
        val sourceProps = sourceType.properties ?: return false
        // Collect all target property names, flattening intersections
        val targetPropNames = collectTargetPropertyNames(targetType) ?: return false
        val excessProps = mutableListOf<Pair<String, Int>>() // (propName, position)
        for (sourceProp in sourceProps) {
            val name = sourceProp.name
            // B66.5: OBJECT_PROTOTYPE_PROPERTIES (toString, valueOf, hasOwnProperty, …)
            // are inherited via Object.prototype on every object literal — they're
            // never "excess" relative to a target shape. TypeScript checks them
            // against the corresponding Object signature (e.g. `toString(): string`)
            // via the standard property-type check and emits TS2322 there instead.
            if (name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (name !in targetPropNames) {
                // Find the position of this property in the object literal
                val propNode = objLiteral.properties.firstOrNull { prop ->
                    when (prop) {
                        is PropertyAssignment -> (prop.name as? Identifier)?.text == name
                                || (prop.name as? StringLiteralNode)?.text == name
                        is ShorthandPropertyAssignment -> prop.name.text == name
                        is MethodDeclaration -> (prop.name as? Identifier)?.text == name
                        else -> false
                    }
                }
                if (propNode != null) {
                    val propPos = when (propNode) {
                        is PropertyAssignment -> propNode.name.pos
                        is ShorthandPropertyAssignment -> propNode.name.pos
                        is MethodDeclaration -> propNode.name.pos
                        else -> propNode.pos
                    }
                    excessProps.add(name to propPos)
                }
            }
        }
        var emitted = false
        for ((propName, propPos) in excessProps) {
            val (line, character) = getLineAndCharacterOfPosition(source, propPos)
            // Check for spelling suggestion (TS2561) vs plain excess (TS2353)
            val suggestion = getSpellingSuggestionFromNames(propName, targetPropNames)
            if (suggestion != null) {
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, but '$propName' does not exist in type '$displayTarget'. Did you mean to write '$suggestion'?",
                    category = DiagnosticCategory.Error,
                    code = 2561,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propPos,
                    length = propName.length,
                ))
            } else {
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, and '$propName' does not exist in type '$displayTarget'.",
                    category = DiagnosticCategory.Error,
                    code = 2353,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propPos,
                    length = propName.length,
                ))
            }
            emitted = true
        }
        // 16.0: Recurse into non-excess properties whose source value is itself
        // an object literal and whose target type is a resolvable object. This
        // catches nested excess properties like
        //   `{ nestedProp: { asdfasdf: 1 } }` vs `{ nestedProp?: { testBool?: boolean } }`.
        try {
            for (propNode in objLiteral.properties) {
                if (propNode !is PropertyAssignment) continue
                val propName = when (val n = propNode.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> continue
                }
                if (propName !in targetPropNames) continue // already flagged
                val nestedInit = propNode.initializer
                if (nestedInit !is ObjectLiteralExpression) continue
                val nestedTargetType = getTargetPropertyType(targetType, propName) ?: continue
                if (nestedTargetType !is Type.Object) continue
                resolveStructuredTypeMembers(nestedTargetType)
                if (nestedTargetType.properties.isNullOrEmpty()) continue
                val nestedSourceType = getTypeOfExpression(nestedInit)
                if (nestedSourceType !is Type.Object) continue
                if (!canUseTypeEngine(nestedSourceType, nestedTargetType)) continue
                val nestedDisplay = typeToString(nestedTargetType)
                if (checkExcessProperties(nestedInit, nestedSourceType, nestedTargetType, nestedDisplay, source, fileName)) {
                    emitted = true
                }
            }
        } catch (_: StackOverflowError) { /* circular */ }
        return emitted
    }

    /**
     * 16.0: Resolve the declared type of a property on a target type, flattening
     * intersections and unions (takes the first object constituent that has the prop).
     */
    private fun getTargetPropertyType(targetType: Type, propName: String): Type? {
        when (targetType) {
            is Type.Object -> {
                val sym = targetType.members?.get(propName) ?: return null
                return getTypeOfSymbol(sym)
            }
            is Type.Intersection -> {
                for (c in targetType.types) {
                    getTargetPropertyType(c, propName)?.let { return it }
                }
                return null
            }
            is Type.Union -> {
                for (c in targetType.types) {
                    getTargetPropertyType(c, propName)?.let { return it }
                }
                return null
            }
            else -> return null
        }
    }

    /**
     * 4e. Compare call or construct signatures.
     * Parameter types compared contravariantly, return types covariantly.
     */
    private fun signaturesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
        isConstruct: Boolean,
    ): Boolean {
        val targetSigs = if (isConstruct) target.constructSignatures else target.callSignatures
        if (targetSigs.isNullOrEmpty()) return true // no signatures to match
        val sourceSigs = if (isConstruct) source.constructSignatures else source.callSignatures
        if (sourceSigs.isNullOrEmpty()) return false // target has signatures, source doesn't
        // Each target signature must be matched by some source signature
        for (targetSig in targetSigs) {
            val matched = sourceSigs.any { sourceSig ->
                signatureRelatedTo(sourceSig, targetSig, relation)
            }
            if (!matched) return false
        }
        return true
    }

    /** Compare two individual signatures. */
    private fun signatureRelatedTo(
        source: Signature,
        target: Signature,
        relation: Relation,
    ): Boolean {
        // Source requires more args than target provides → incompatible
        val sourceParams = source.parameters
        val targetParams = target.parameters
        if (source.minArgumentCount > targetParams.size) return false
        // 17.10d: Light type-param inference for the SOURCE-generic, TARGET-non-generic
        // case. When source has type parameters and target doesn't, treat source's
        // TypeParam-typed param positions as "wildcards" pinned to the target's
        // concrete type at that position — a single TypeParam appearing multiple times
        // must map to the SAME target type (modulo subtyping); otherwise the comparison
        // fails. Each pinning must also satisfy the TypeParam's constraint. Without
        // this, FunctionType nodes with type params (added in 17.10b) FP-reject
        // legitimate contravariant param assignments like `(g: Giraffe) => void` ←
        // `<T extends Animal>(x: T) => void`.
        val sourceHasTpInParams = !source.typeParameters.isNullOrEmpty() &&
            target.typeParameters.isNullOrEmpty() &&
            sourceParams.any { getTypeOfSymbol(it) is Type.TypeParam }
        val tpAssignments = if (sourceHasTpInParams) mutableMapOf<Int, Type>() else null
        // Check parameter types (contravariant). We do params BEFORE return type so
        // the type-param assignments from param pinning could (in a future extension)
        // also drive return-type substitution.
        val len = minOf(sourceParams.size, targetParams.size)
        // B63.29: When target's last param is a rest `...t: U[]`, positional comparison
        // beyond target.size-1 (and AT target.size-1 against a non-rest source param)
        // should use the rest element type U, not U[]. Without this, source's typed
        // param like `bar: string` vs target's rest `...tail: any[]` contravariantly
        // checks `any[]` vs `string` → false. Correct: check element `any` vs `string` → true.
        val targetLast = targetParams.lastOrNull()
        val targetLastIsRest = (targetLast?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        // Compute the rest element type, OR a sentinel marking "non-array rest" (which
        // can't actually accept tuple-like spreads and TypeScript treats as accept-all).
        // - Array<U> / ReadonlyArray<U> → element type U
        // - any → anyType (accept all)
        // - Tuple → fall through to standard comparison (don't bail)
        // - Anything else (intersection, named non-array, never) → anyType (accept all,
        //   since the rest type isn't a valid spread target)
        val targetRestRaw = if (targetLastIsRest) getTypeOfSymbol(targetLast!!) else null
        val targetRestElement: Type? = if (targetLastIsRest && targetRestRaw != null) {
            when {
                targetRestRaw is Type.Reference &&
                    targetRestRaw.target?.symbol?.name in setOf("Array", "ReadonlyArray") ->
                    targetRestRaw.resolvedTypeArguments?.firstOrNull()
                targetRestRaw === anyType -> anyType
                // B63.31: Non-array rest type (intersection of object literals, named non-array,
                // etc.) — TypeScript treats these as accept-anything since the rest spread can't
                // actually deliver values of that shape. Fixed-arity comparison bails by using
                // anyType for the element. Tuples (Type.Object with tupleElementTypes) fall
                // through (we don't have per-position tuple-element comparison yet).
                targetRestRaw is Type.Object && targetRestRaw.tupleElementTypes != null -> null
                else -> anyType
            }
        } else null
        for (i in 0 until len) {
            val sourceParamType = getTypeOfSymbol(sourceParams[i])
            val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
            // For the target's rest param position, if source is also rest, compare U[] vs T[]
            // normally. If source is non-rest at the same position, compare element vs source.
            val targetParamType = if (i == targetParams.size - 1 && targetLastIsRest && !sourceIsRest && targetRestElement != null) {
                targetRestElement
            } else {
                getTypeOfSymbol(targetParams[i])
            }
            if (tpAssignments != null && sourceParamType is Type.TypeParam) {
                val tpId = sourceParamType.id
                val existing = tpAssignments[tpId]
                if (existing != null && existing !== targetParamType) return false
                tpAssignments[tpId] = targetParamType
                // Constraint check: target must satisfy source TypeParam's constraint
                val cons = sourceParamType.constraint
                if (cons != null && cons !== errorType) {
                    if (!checkTypeRelatedTo(targetParamType, cons, relation)) return false
                }
                continue
            }
            // Standard contravariant: target param must be assignable to source param
            if (!checkTypeRelatedTo(targetParamType, sourceParamType, relation)) return false
        }
        // B63.29 continuation: Source has MORE params than target.size — target's rest
        // covers them. For each excess source position, check target rest element type
        // contravariantly against the source param type.
        if (targetLastIsRest && targetRestElement != null && sourceParams.size > targetParams.size) {
            for (i in targetParams.size until sourceParams.size) {
                val sourceParamType = getTypeOfSymbol(sourceParams[i])
                val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                // Source's own rest: compare its element vs target rest element
                val srcCmp = if (sourceIsRest && sourceParamType is Type.Reference &&
                    sourceParamType.target?.symbol?.name in setOf("Array", "ReadonlyArray"))
                    sourceParamType.resolvedTypeArguments?.firstOrNull() ?: sourceParamType
                else sourceParamType
                if (!checkTypeRelatedTo(targetRestElement, srcCmp, relation)) return false
            }
        }
        // Check return types (covariant)
        // Void target return accepts any source return type (void means "don't care about return")
        val sourceReturn = source.resolvedReturnType ?: anyType
        val targetReturn = target.resolvedReturnType ?: anyType
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, relation)) return false
        return true
    }

    /**
     * Generate elaboration chain for a function→function type mismatch.
     * Returns lines like:
     *   "  Type 'void' is not assignable to type 'boolean'."
     * or:
     *   "  Types of parameters 'x' and 's1' are incompatible."
     *   "    Type 'string' is not assignable to type 'number'."
     */
    /**
     * 16.4dw: A signature has only simple-checkable param/return types (primitives,
     * literals, void, undefined, null, never). Used to guard function-to-function
     * structural comparison against generic-inference FPs.
     */
    /**
     * B70.7: Format target's params [startIdx..end] as a labeled-tuple display
     * `[name: type, name: type, ...name: type]` for use in rest-param elaboration
     * (source rest param absorbing target positional params). Uses the param's
     * AST type-node source text when available (preserves `T` for unbound
     * TypeParams in function-type alias bodies); falls back to `typeToString`.
     * Returns null if any param lacks a usable display.
     */
    private fun formatTargetParamsAsTuple(targetParams: List<Symbol>, startIdx: Int): String? {
        val parts = mutableListOf<String>()
        for (i in startIdx until targetParams.size) {
            val sym = targetParams[i]
            val paramDecl = sym.valueDeclaration as? Parameter ?: return null
            val isRest = paramDecl.dotDotDotToken
            val typeNode = paramDecl.type
            val typeText = typeNode?.let { formatTypeForDisplay(it) } ?: typeToString(getTypeOfSymbol(sym))
            val prefix = if (isRest) "..." else ""
            parts.add("$prefix${sym.name}: $typeText")
        }
        return "[${parts.joinToString(", ")}]"
    }

    private fun sigHasOnlySimpleTypes(sig: Signature): Boolean {
        val ret = sig.resolvedReturnType ?: return false
        if (ret !== voidType && !isSimpleCheckableType(ret)) return false
        for (p in sig.parameters) {
            val pt = getTypeOfSymbol(p)
            if (!isSimpleCheckableType(pt)) return false
        }
        return true
    }

    private fun getFunctionMismatchElaboration(
        source: Type.Object, target: Type.Object
    ): List<String> {
        val sourceSigs = source.callSignatures
        val targetSigs = target.callSignatures
        if (sourceSigs.isNullOrEmpty() || targetSigs.isNullOrEmpty()) return emptyList()
        val sourceSig = sourceSigs.first()
        val targetSig = targetSigs.first()
        // Arity mismatch: source requires more arguments than target provides.
        // Emit "Target signature provides too few arguments. Expected N or more, but got M."
        // — matches `signatureLengthMismatchCall`-style baselines for TS2345 with
        // function args. Take this branch BEFORE per-param comparison since the
        // arity gap is more fundamental than any individual param-type mismatch.
        if (sourceSig.minArgumentCount > targetSig.parameters.size) {
            return listOf(
                "  Target signature provides too few arguments. Expected ${sourceSig.parameters.size} or more, but got ${targetSig.parameters.size}."
            )
        }
        // 16.4dw: Check parameter type mismatch FIRST (contravariant) — TypeScript reports
        // the parameter mismatch before the return-type mismatch when both fail, because
        // params are contravariant and the failure is more fundamental.
        // 17.10e: Mirror `signatureRelatedTo`'s light type-param inference. When source has
        // type parameters and target doesn't, the FAILING pair is the one where the source
        // TypeParam was already pinned to a different target type — and the elaboration
        // should display the EARLIER pinned target (substituted) instead of the raw `T`.
        // Example: `<T>(x: T, y: T) => void` vs `(g: Giraffe, e: Elephant) => void`
        //   → first pair pins T = Giraffe (passes constraint Animal); second pair fails
        //     because Elephant !== Giraffe; report `(y, e)` mismatch with substituted
        //     `Type 'Elephant' is not assignable to type 'Giraffe'.`
        val sourceParams = sourceSig.parameters
        val targetParams = targetSig.parameters
        val sigHasTpInParams = !sourceSig.typeParameters.isNullOrEmpty() &&
            targetSig.typeParameters.isNullOrEmpty() &&
            sourceParams.any { getTypeOfSymbol(it) is Type.TypeParam }
        val tpAssignments = if (sigHasTpInParams) mutableMapOf<Int, Type>() else null
        val len = minOf(sourceParams.size, targetParams.size)
        for (i in 0 until len) {
            val sourceParamType = getTypeOfSymbol(sourceParams[i])
            val targetParamType = getTypeOfSymbol(targetParams[i])
            if (tpAssignments != null && sourceParamType is Type.TypeParam) {
                val tpId = sourceParamType.id
                val existing = tpAssignments[tpId]
                if (existing != null && existing !== targetParamType) {
                    // Pinning conflict — substitute the EARLIER pinned target into the
                    // source param display, then run a property-elaboration to surface
                    // a "Property X is missing in Y but required in Z" line if applicable.
                    val pinned = existing
                    val nestedChain = if (targetParamType is Type.Object && pinned is Type.Object) {
                        getPropertyElaborationChain(targetParamType, pinned)
                    } else null
                    val secondLine = if (!nestedChain.isNullOrEmpty()) {
                        // getPropertyElaborationChain returns lines indented "  ..." — bump to "    ..."
                        nestedChain.first().replaceFirst("  ", "    ")
                    } else {
                        "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(pinned)}'."
                    }
                    return listOf(
                        "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                        secondLine,
                    )
                }
                tpAssignments[tpId] = targetParamType
                val cons = sourceParamType.constraint
                if (cons != null && cons !== errorType) {
                    if (!checkTypeRelatedTo(targetParamType, cons, assignableRelation)) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(cons)}'.",
                        )
                    }
                }
                continue
            }
            if (!checkTypeRelatedTo(targetParamType, sourceParamType, assignableRelation)) {
                // B70.7: When source's param at position i is REST and target has
                // a non-rest param at position i (and may have more positions
                // after), TypeScript constructs a labeled-tuple `[name: type, ...]`
                // from target's params [i..end] and displays that as the "from"
                // type, comparing it against source's rest type as a whole.
                // Example (`genericRestTypes_ts`):
                //   source `(...args: never) => void`, target `(x:string, ...rest:T) => void`
                //   → chain `Type '[x: string, ...rest: T]' is not assignable to type 'never'.`
                val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                val targetIsRest = (targetParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                if (sourceIsRest && i == sourceParams.size - 1 && !targetIsRest && targetParams.size > i) {
                    val tupleDisplay = formatTargetParamsAsTuple(targetParams, i)
                    if (tupleDisplay != null) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '$tupleDisplay' is not assignable to type '${typeToString(sourceParamType)}'.",
                        )
                    }
                }
                // 17.15a: When both inner param types are function types, recurse
                // for deeper "Types of parameters X and Y are incompatible" chain
                // matching TypeScript's contravariant elaboration. The inner call's
                // (source, target) mirror the outer-comparison's contravariant
                // checkTypeRelatedTo direction: inner-source = outer-target's param,
                // inner-target = outer-source's param.
                if (targetParamType is Type.Object && sourceParamType is Type.Object &&
                    !targetParamType.callSignatures.isNullOrEmpty() &&
                    !sourceParamType.callSignatures.isNullOrEmpty()
                ) {
                    val nested = getFunctionMismatchElaboration(targetParamType, sourceParamType)
                    if (nested.isNotEmpty()) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                        ) + nested.map { "  $it" }
                    }
                }
                // When both inner param types are non-function Type.Object, recurse via
                // property elaboration so the chain shows the inner property mismatch
                // (e.g. `{a: number}` vs `{a: string}` → "Types of property 'a' are
                // incompatible. Type 'number' is not assignable to type 'string'.").
                // Argument order mirrors the contravariance: targetParam is the "from"
                // and sourceParam is the "to" in the displayed chain line.
                if (targetParamType is Type.Object && sourceParamType is Type.Object &&
                    targetParamType.callSignatures.isNullOrEmpty() &&
                    sourceParamType.callSignatures.isNullOrEmpty()
                ) {
                    val propChain = getPropertyElaborationChain(targetParamType, sourceParamType)
                    if (!propChain.isNullOrEmpty()) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(sourceParamType)}'.",
                        ) + propChain.map { "    $it" }
                    }
                }
                // typeParameterConstrainedToOuterTypeParameter: target param reduces to a
                // bare call-sig TypeParam (U) and source param reduces to Array<TypeParam>
                // (U[]) whose element TypeParam carries a constraint. TypeScript substitutes
                // each side's own call-sig type parameter by its CONSTRAINT for display
                // (source U[] -> <srcCons>[], target U -> <tgtCons>), then drills one level
                // into the array: deeper line compares target's <tgtCons> scalar against
                // source's <srcCons>[] array. The constraint of an inner `<U extends T>` is
                // the OUTER interface type param `T`, which must be instantiated through the
                // enclosing reference's args (A<string> -> T=string) before display — without
                // this it renders the raw `T[]`/`T` (empirically confirmed). Gated tightly to
                // this exact array-element-vs-scalar shape with BOTH constraints resolving to
                // concrete types, so every other param shape falls through unchanged.
                run {
                    val tgtTp = targetParamType as? Type.TypeParam
                    val srcRef = sourceParamType as? Type.Reference
                    val srcElem = srcRef?.resolvedTypeArguments?.singleOrNull() as? Type.TypeParam
                    if (tgtTp != null && srcRef != null && srcRef.target === globalArrayType &&
                        srcElem != null
                    ) {
                        val rawTgtCons = tgtTp.constraint
                        val rawSrcCons = srcElem.constraint
                        if (rawTgtCons != null && rawTgtCons !== errorType &&
                            rawSrcCons != null && rawSrcCons !== errorType
                        ) {
                            // Instantiate each constraint through its enclosing reference's
                            // type-arg mapper so an outer-TP constraint (`U extends T`) becomes
                            // the concrete outer arg (`string`). When the enclosing type isn't
                            // a generic reference the mapper is identity (constraint unchanged).
                            fun refMapper(t: Type.Object): TypeMapper? {
                                val ref = t as? Type.Reference ?: return null
                                val tps = ref.target.typeParameters ?: return null
                                val args = ref.resolvedTypeArguments ?: return null
                                if (tps.isEmpty() || tps.size != args.size) return null
                                return createTypeMapper(tps, args)
                            }
                            val srcMapper = refMapper(source)
                            val tgtMapper = refMapper(target)
                            val tgtCons = if (tgtMapper != null) instantiateType(rawTgtCons, tgtMapper) else rawTgtCons
                            val srcCons = if (srcMapper != null) instantiateType(rawSrcCons, srcMapper) else rawSrcCons
                            // Only take this branch when at least one constraint actually
                            // became concrete (not still a bare TypeParam) — otherwise the
                            // raw-`T` display would not match TypeScript and we'd flip nothing
                            // while risking an unexpected baseline; fall through instead.
                            if (srcCons !is Type.TypeParam && tgtCons !is Type.TypeParam) {
                                val srcArrDisplay = "${typeToString(srcCons)}[]"
                                return listOf(
                                    "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                                    "    Type '${typeToString(tgtTp)}' is not assignable to type '$srcArrDisplay'.",
                                    "      Type '${typeToString(tgtCons)}' is not assignable to type '$srcArrDisplay'.",
                                )
                            }
                        }
                    }
                }
                // B70.1ext: When `targetParamType` is a literal type AND `sourceParamType`
                // is a primitive of a DIFFERENT base (e.g. `'hi'` (StringLiteral) vs
                // `number`), TypeScript widens the literal in the chain display:
                // `Type 'string' is not assignable to type 'number'.`, not
                // `Type '"hi"' is not assignable to type 'number'.`. Same-base mismatches
                // (`'hi'` vs `'bye'` — both string literals) keep both literals.
                val displayTargetParam = widenLiteralForDifferentBaseDisplay(targetParamType, sourceParamType)
                return listOf(
                    "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                    "    Type '${typeToString(displayTargetParam)}' is not assignable to type '${typeToString(sourceParamType)}'.",
                )
            }
        }
        // Check return type mismatch
        val sourceReturn = sourceSig.resolvedReturnType ?: anyType
        val targetReturn = targetSig.resolvedReturnType ?: anyType
        // B71.1: Mirror the arg-level strict void→undefined gate. Source's return is
        // `void` (e.g. implicit-void FunctionDeclaration); target's return is `undefined`.
        // Emit the chain "Type 'void' is not assignable to type 'undefined'." so the
        // caller's TS2345 displays a proper elaboration.
        if (strictNullChecks &&
            sourceReturn === voidType &&
            targetReturn.flags.hasAny(TypeFlags.Undefined) &&
            !targetReturn.flags.hasAny(TypeFlags.Void)
        ) {
            return listOf("  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, assignableRelation)) {
            // 17.11a: When target's return type is one of target's own type
            // parameters (e.g. `<T>(x:T) => T`) AND source has its own type
            // parameters whose names appear in source's return type (e.g.
            // `<S>() => S[]`), TypeScript displays the source return with each
            // source TypeParam substituted by `unknown` and adds the elaboration
            // line "'T' could be instantiated with an arbitrary type which could
            // be unrelated to '<displayed-source>'." The intuition: source's `S`
            // is unbound from target's `T`, so the caller's `T` can be any type
            // the caller picks — yet source guarantees only `S[]` (which is
            // `unknown[]` when displayed without context). The target TypeParam
            // is therefore not safely instantiable to whatever the caller picks.
            val targetTpReturn = targetReturn as? Type.TypeParam
            val sourceTps = sourceSig.typeParameters
            if (targetTpReturn != null
                && targetSig.typeParameters?.contains(targetTpReturn) == true
                && !sourceTps.isNullOrEmpty()
                && sourceContainsTypeParam(sourceReturn, sourceTps)
            ) {
                val mapper = TypeMapper { tp ->
                    if (sourceTps.contains(tp)) unknownType else null
                }
                val srcDisplay = typeToStringWithMapper(sourceReturn, mapper)
                val tgtDisplay = typeToString(targetReturn)
                return listOf(
                    "  Type '$srcDisplay' is not assignable to type '$tgtDisplay'.",
                    "    '$tgtDisplay' could be instantiated with an arbitrary type which could be unrelated to '$srcDisplay'.",
                )
            }
            // B50.6: Function return-type chain. When BOTH returns are pure function
            // types (call signatures only, no properties/members/construct sigs),
            // recurse with a "Call signature return types '<src>' and '<tgt>' are
            // incompatible." header so nested-callback patterns produce the full
            // drilled chain (cf. `nestedCallbackErrorNotFlattened_ts`).
            if (sourceReturn is Type.Object && targetReturn is Type.Object &&
                !sourceReturn.callSignatures.isNullOrEmpty() &&
                !targetReturn.callSignatures.isNullOrEmpty() &&
                sourceReturn.properties.isNullOrEmpty() &&
                targetReturn.properties.isNullOrEmpty() &&
                sourceReturn.members.isNullOrEmpty() &&
                targetReturn.members.isNullOrEmpty() &&
                sourceReturn.constructSignatures.isNullOrEmpty() &&
                targetReturn.constructSignatures.isNullOrEmpty()
            ) {
                val srcDisp = typeToString(sourceReturn)
                val tgtDisp = typeToString(targetReturn)
                val nested = getFunctionMismatchElaboration(sourceReturn, targetReturn)
                val header = "  Call signature return types '$srcDisp' and '$tgtDisp' are incompatible."
                return listOf(header) + nested.map { "  $it" }
            }
            // B75.3: When return types are same-target generic references (e.g. both
            // `Array<U>` / `ReadonlyArray<U>`) with differing args whose deeper chain
            // can be elaborated, append the drill-in. Matches TypeScript's `concat(...)`
            // chain for Array-derived → ReadonlyArray<T> tests, which surfaces the
            // missing-required-property line at element depth.
            val srcRefRet = sourceReturn as? Type.Reference
            val tgtRefRet = targetReturn as? Type.Reference
            if (srcRefRet != null && tgtRefRet != null &&
                srcRefRet.target === tgtRefRet.target) {
                val sArgs = srcRefRet.resolvedTypeArguments
                val tArgs = tgtRefRet.resolvedTypeArguments
                if (sArgs != null && tArgs != null && sArgs.size == tArgs.size) {
                    val header = "  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'."
                    for (i in sArgs.indices) {
                        if (!checkTypeRelatedTo(sArgs[i], tArgs[i], assignableRelation)) {
                            val sa = sArgs[i]
                            val ta = tArgs[i]
                            if (sa is Type.Object && ta is Type.Object) {
                                val deeper = getPropertyElaborationChain(sa, ta, "")
                                if (deeper != null) {
                                    val firstTrimmed = deeper.first().trimStart()
                                    return if (firstTrimmed.startsWith("Property '")) {
                                        listOf(header) + deeper.map { "  $it" }
                                    } else {
                                        listOf(header) + deeper.map { "  $it" }
                                    }
                                }
                            }
                            return listOf(header)
                        }
                    }
                }
            }
            return listOf("  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
        return emptyList()
    }

    /**
     * 17.11a: True when [type] (or any TypeParam reachable via Type.Reference args
     * / Union / Intersection) is one of the source-side TypeParam instances in
     * [sourceTps]. Used to gate the "could be instantiated with an arbitrary type"
     * elaboration so we don't substitute when source's return is a concrete type
     * unrelated to its own type parameters.
     */
    private fun sourceContainsTypeParam(type: Type, sourceTps: List<Type.TypeParam>): Boolean {
        return when (type) {
            is Type.TypeParam -> sourceTps.contains(type)
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return false
                args.any { sourceContainsTypeParam(it, sourceTps) }
            }
            is Type.Union -> type.types.any { sourceContainsTypeParam(it, sourceTps) }
            is Type.Intersection -> type.types.any { sourceContainsTypeParam(it, sourceTps) }
            else -> false
        }
    }

    /**
     * 17.40: Does any of `sig`'s param types or return type mention any TypeParam in
     * `tps`? Used to detect when an anonymous function-type parameter's signature
     * carries sig-side TypeParams that would need `unknown` substitution for display
     * in TS2345 messages (`(a: Iterator<T>) => number` → `(a: Iterator<unknown>) => number`
     * when the call provides no info to infer T).
     */
    private fun sigMentionsAnyTp(sig: Signature, tps: List<Type.TypeParam>): Boolean {
        val ret = sig.resolvedReturnType
        if (ret != null && sourceContainsTypeParam(ret, tps)) return true
        return sig.parameters.any { sourceContainsTypeParam(getTypeOfSymbol(it), tps) }
    }

    /**
     * Generate elaboration chain for an Object→Object type mismatch by
     * recursively comparing properties to find the deepest incompatible path.
     *
     * Returns lines like:
     *   "  Types of property 'x' are incompatible."
     *   "    Type 'number' is not assignable to type 'string'."
     * or for nested paths:
     *   "  The types of 'x.y' are incompatible between these types."
     *   "    Type 'string' is not assignable to type 'number'."
     */
    /**
     * Per-property TS2322 + TS6500 emission for object-literal initializers (var-decl,
     * property assignment) where the target is a known object type.
     *
     * Walks the source object literal's properties in source order. For each property
     * whose value type doesn't match the target's same-named property AND both sides
     * are simple-checkable (primitives / literals / all-primitive unions), emits a
     * TS2322 at the property KEY position with a TS6500 "expected type comes from"
     * related info pointing to the target property's declaration.
     *
     * Returns true if at least one TS2322 was emitted — caller should then suppress
     * the wider variable-name TS2322. Conservative: skips computed property names,
     * spread elements, methods, and shorthand property assignments.
     */
    private fun emitPerPropertyMismatchesForObjectLiteral(
        init: ObjectLiteralExpression,
        sourceType: Type.Object,
        targetType: Type.Object,
        displayTarget: String,
        source: String, fileName: String,
    ): Boolean {
        var emitted = false
        for (propNode in init.properties) {
            if (propNode !is PropertyAssignment) continue
            val nameNode = propNode.name
            val (propName, keyPos, keyLen) = when (nameNode) {
                is Identifier -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is NumericLiteralNode -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is StringLiteralNode -> Triple(
                    nameNode.text,
                    nameNode.pos,
                    (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                )
                else -> continue
            }
            val targetProp = targetType.members?.get(propName) ?: continue
            val targetPropType = getTypeOfSymbol(targetProp)
            if (targetPropType === anyType || targetPropType === errorType) continue
            val sourceProp = sourceType.members?.get(propName) ?: continue
            val sourcePropType = getTypeOfSymbol(sourceProp)
            if (sourcePropType === anyType || sourcePropType === errorType) continue
            if (!isSimpleCheckableType(targetPropType) || !isSimpleCheckableType(sourcePropType)) continue
            if (checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) continue
            val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
            val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
            val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
            val related = mutableListOf<Diagnostic>()
            val tpDecl = targetProp.declarations.firstOrNull()
            if (tpDecl != null) {
                val declPos = when (tpDecl) {
                    is PropertyDeclaration -> tpDecl.name.pos
                    is PropertyAssignment -> tpDecl.name.pos
                    else -> tpDecl.pos
                }
                val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                related.add(Diagnostic(
                    message = "The expected type comes from property '$propName' which is declared here on type '$displayTarget'",
                    category = DiagnosticCategory.Message,
                    code = 6500,
                    fileName = fileName,
                    line = dline,
                    character = dchar,
                    start = declPos,
                    length = propName.length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = kline,
                character = kchar,
                start = keyPos,
                length = keyLen,
                relatedInformation = related,
            ))
            emitted = true
        }
        return emitted
    }

    private fun getPropertyElaborationChain(
        source: Type,
        target: Type,
        path: String = "",
    ): List<String>? {
        // 17.42: handle Type.Intersection source by merging members from object-like
        // constituents. For `Type.Intersection({fooProp: string}, Bar)` vs target
        // `FooBar`, the merged source has `fooProp: string` and `barProp: string`,
        // and a target prop like `fooProp: boolean` produces the standard
        // "Types of property 'fooProp' are incompatible. Type 'string' is not
        // assignable to type 'boolean'." chain. Pairs with 17.41's substitution
        // (so the pre-substitution `T & Bar` source becomes `{...} & Bar`).
        if (source is Type.Intersection && target is Type.Object) {
            return getIntersectionPropertyElaborationChain(source, target, path)
        }
        // B50.4: Object → Union elaboration — emit the per-level "Type X vs '<union>'"
        // line, then drill into the best-matching constituent with "Type X vs '<best>'"
        // + nested chain. Resets `path` so the constituent's per-property chain
        // doesn't carry the outer caller's path prefix. Matches TypeScript's chain
        // shape for `typeAssignabilityErrorMessage_ts`-style cases.
        if (source is Type.Object && target is Type.Union) {
            val best = findBestUnionConstituent(source, target)
            if (best is Type.Object) {
                val perLevel = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                val drillIn = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(best)}'."
                val deeper = getPropertyElaborationChain(source, best, "")
                return if (deeper != null) {
                    listOf(perLevel) + listOf("  $drillIn") + deeper.map { "    $it" }
                } else {
                    listOf(perLevel, "  $drillIn")
                }
            }
            return null
        }
        if (source !is Type.Object || target !is Type.Object) return null
        // B58.2: tuple-tuple elaboration uses "Type at position N in source is
        // not compatible with type at position N in target." per TypeScript
        // convention. When both sides have tupleElementTypes and the same arity,
        // iterate positionally and emit per-mismatch chain.
        val srcTuple = source.tupleElementTypes
        val tgtTuple = target.tupleElementTypes
        if (srcTuple != null && tgtTuple != null && srcTuple.size == tgtTuple.size) {
            for (i in srcTuple.indices) {
                val sElem = srcTuple[i]
                val tElem = tgtTuple[i]
                if (!checkTypeRelatedTo(sElem, tElem, assignableRelation)) {
                    val chain = mutableListOf<String>()
                    chain.add("  Type at position $i in source is not compatible with type at position $i in target.")
                    chain.add("    Type '${typeToString(sElem)}' is not assignable to type '${typeToString(tElem)}'.")
                    return chain
                }
            }
            return null
        }
        // Cycle detection: don't re-enter elaboration for the same type pair
        val pairKey = packRelationKey(source.id, target.id)
        if (pairKey in state.elaborationStack) return null
        state.elaborationStack.add(pairKey)
        try {
            // B75.3: Plain `Array<U>` source vs `ReadonlyArray<T>` target — elaborate
            // the ELEMENT pair directly (covariant). Without this, falling through to
            // `propertiesRelatedTo` produces a misleading `concat` method chain even
            // though TypeScript correctly reports the element-type mismatch as a
            // missing-required-property line. Matches the pre-B75.1 behavior where
            // Array and ReadonlyArray collapsed onto the same target.
            //
            // Scope: source.target === globalArrayType (plain Array<U>), NOT subclass
            // of Array. Subclass-of-Array (e.g. `class C<T> extends Array<T>`) keeps
            // the structural concat-chain (TypeScript renders that for named subclasses).
            if (source is Type.Reference && target is Type.Reference &&
                globalReadonlyArrayType != null &&
                target.target === globalReadonlyArrayType &&
                source.target === globalArrayType) {
                val srcArgs = source.resolvedTypeArguments
                val tgtArgs = target.resolvedTypeArguments
                if (srcArgs != null && tgtArgs != null && srcArgs.size == 1 && tgtArgs.size == 1) {
                    val sa = srcArgs[0]
                    val ta = tgtArgs[0]
                    if (!checkTypeRelatedTo(sa, ta, assignableRelation)) {
                        val argChain = if (sa is Type.Object && ta is Type.Object) {
                            getPropertyElaborationChain(sa, ta, "")
                        } else null
                        return if (path.isEmpty()) {
                            val header = "  Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'."
                            if (argChain != null) {
                                val firstTrimmed = argChain.first().trimStart()
                                if (firstTrimmed.startsWith("Property '")) {
                                    argChain
                                } else {
                                    listOf(header) + argChain.map { "  $it" }
                                }
                            } else {
                                listOf(header)
                            }
                        } else {
                            val ctx = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                            if (argChain != null) {
                                listOf(ctx) + argChain.map { "  $it" }
                            } else {
                                listOf(ctx, "    Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'.")
                            }
                        }
                    }
                }
            }
            // Generic ref mismatch: when source and target share a target interface but
            // differ in type arguments (e.g. `Bar<string>` vs `Bar<number>`), elaborate
            // with the first failing arg pair. For top-level (path == "") the main
            // TS2322 message already shows "Type 'A<X>' vs 'A<Y>'.", so emit only the
            // deeper chain. For nested calls (path != "") include a context line at
            // this level so the chain reads "  Types of prop X incompatible.
            //   Type 'A<X>[]' vs 'A<Y>[]'.    Type 'X' vs 'Y'."
            if (source is Type.Reference && target is Type.Reference &&
                source.target === target.target) {
                val sourceArgs = source.resolvedTypeArguments
                val targetArgs = target.resolvedTypeArguments
                if (sourceArgs != null && targetArgs != null && sourceArgs.size == targetArgs.size) {
                    for (i in sourceArgs.indices) {
                        val sa = sourceArgs[i]
                        val ta = targetArgs[i]
                        if (!checkTypeRelatedTo(sa, ta, assignableRelation)) {
                            // Try richer elaboration when both args are object types.
                            val argChain = if (sa is Type.Object && ta is Type.Object) {
                                getPropertyElaborationChain(sa, ta, "")
                            } else null
                            return if (path.isEmpty()) {
                                val header = "  Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'."
                                if (argChain != null) {
                                    // Skip the header when argChain's first line is a
                                    // "Property 'X' is missing in type 'A' but required
                                    // in type 'B'." terminal — that line already mentions
                                    // both source and target type names so the header is
                                    // redundant (matches TypeScript's `promisesWithConstraints`-
                                    // style output). For deeper structural chains
                                    // ("The types returned by '...'", "Types of property '...'",
                                    // etc.), include the header to identify the parent
                                    // arg pair being compared (matches `generics4`-style output).
                                    val firstTrimmed = argChain.first().trimStart()
                                    if (firstTrimmed.startsWith("Property '")) {
                                        argChain
                                    } else {
                                        listOf(header) + argChain.map { "  $it" }
                                    }
                                } else {
                                    listOf(header)
                                }
                            } else {
                                val ctx = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                                if (argChain != null) {
                                    listOf(ctx) + argChain.map { "  $it" }
                                } else {
                                    listOf(ctx, "    Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'.")
                                }
                            }
                        }
                    }
                }
            }
            resolveStructuredTypeMembers(source)
            resolveStructuredTypeMembers(target)
            val targetProps = target.properties ?: return null
            val sourceMembers = source.members ?: return null

            // Private-brand mismatch: emit the nominal-brand elaboration for the first
            // property that's declared private on both sides in different classes.
            for (targetProp in targetProps) {
                val sourceProp = sourceMembers[targetProp.name] ?: continue
                if (isPropPrivateBrandMismatch(sourceProp, targetProp)) {
                    return listOf("  Types have separate declarations of a private property '${targetProp.name}'.")
                }
            }

            // 17.14c: Asymmetric privacy mismatch — target has a private property whose
            // source counterpart isn't private (or vice versa). Matches TypeScript's
            // "Property 'X' is private in type 'A' but not in type 'B'." for the
            // `assignmentCompatability40-42` family. Emitted at the FIRST asymmetric
            // mismatch — symmetric brand mismatches above take precedence.
            for (targetProp in targetProps) {
                val sourceProp = sourceMembers[targetProp.name] ?: continue
                val tDecl = targetProp.valueDeclaration ?: targetProp.declarations.firstOrNull()
                val sDecl = sourceProp.valueDeclaration ?: sourceProp.declarations.firstOrNull()
                if (tDecl == null || sDecl == null) continue
                val tPriv = isMemberPrivate(tDecl)
                val sPriv = isMemberPrivate(sDecl)
                if (tPriv && !sPriv) {
                    return listOf("  Property '${targetProp.name}' is private in type '${typeToString(target)}' but not in type '${typeToString(source)}'.")
                }
                if (sPriv && !tPriv) {
                    return listOf("  Property '${targetProp.name}' is private in type '${typeToString(source)}' but not in type '${typeToString(target)}'.")
                }
            }

            // Collect all incompatible properties
            data class IncompatibleProp(
                val name: String,
                val sourceType: Type,
                val targetType: Type,
                val sourceWidenedForOptional: Boolean,
            )
            val incompatible = mutableListOf<IncompatibleProp>()
            for (targetProp in targetProps) {
                val targetName = targetProp.name
                val sourceProp = sourceMembers[targetName] ?: continue
                // Use substituted property types (Blocker #1 step (b)/(d)) so generic
                // inheritance mismatches like `B<number> extends A<string>` produce
                // "Types of property 'x' are incompatible. Type 'string' is not
                // assignable to type 'number'." instead of falling out silently.
                val sourcePropType = getPropertyTypeForRelation(source, sourceProp)
                val targetPropType = getPropertyTypeForRelation(target, targetProp)
                val effectiveSource = widenOptionalSourcePropType(sourcePropType, sourceProp, targetProp)
                val sourceWidened = effectiveSource !== sourcePropType
                if (!checkTypeRelatedTo(effectiveSource, targetPropType, assignableRelation)) {
                    incompatible.add(IncompatibleProp(targetName, effectiveSource, targetPropType, sourceWidened))
                }
            }
            if (incompatible.isEmpty()) {
                // No property-type mismatch — try the missing-required-property path.
                // Matches `propertiesRelatedTo`'s missing-prop logic so structural
                // failures via missing members still produce an informative chain
                // (e.g. `Animal[]` vs `Giraffe[]` → "Property 'g' is missing in
                // type 'Animal' but required in type 'Giraffe'.").
                val missing = getMissingRequiredPropertySymbol(source, target)
                if (missing != null) {
                    return listOf(
                        "  Property '${missing.name}' is missing in type '${typeToString(source)}' but required in type '${typeToString(target)}'."
                    )
                }
                return null
            }

            // Prefer leaf mismatches (non-Object types) over recursive ones
            // This avoids following circular property paths (A.p→D→C.q→B→A.p...)
            // when there's a direct primitive mismatch like A.s:string vs B.s:number
            // B50.4: Object→Union prop pair is NOT a leaf — the top-of-function
            // Object→Union branch can drill into the best constituent. Only treat
            // truly-non-Object sources/targets as leaves.
            val leaf = incompatible.firstOrNull {
                (it.sourceType !is Type.Object && it.sourceType !is Type.Union) ||
                (it.targetType !is Type.Object && it.targetType !is Type.Union)
            }
            val chosen = leaf ?: incompatible.first()

            val propPath = if (path.isEmpty()) chosen.name else "$path.${chosen.name}"
            val outerLine = if (path.isEmpty()) {
                "  Types of property '${chosen.name}' are incompatible."
            } else {
                "  The types of '$propPath' are incompatible between these types."
            }
            // Try to go deeper into nested object properties (if not a leaf)
            if (leaf == null) {
                // B86.7c: nested nullable-target collapse. When the chosen property's
                // source is an Object and its target is a Union of exactly ONE
                // non-nullish Object constituent + nullish-only siblings (e.g. source
                // `{ bar: ... }` vs target `{ bar: ... } | undefined`), TypeScript does
                // NOT emit the per-level Object→Union drill-in chain. It collapses
                // directly through the single non-nullish constituent, carrying the
                // property path so the deeper line reads "The types of 'foo.bar' are
                // incompatible between these types." Recurse into the non-nullish
                // constituent with the SAME propPath (collapsed form), preserving the
                // outer chain shape. Gate is narrow: exactly one non-nullish Object
                // constituent, all other constituents nullish.
                val sObj = chosen.sourceType as? Type.Object
                val tUnion = chosen.targetType as? Type.Union
                if (sObj != null && tUnion != null) {
                    val nonNullish = tUnion.types.filterNot { isNullishConstituent(it) }
                    if (nonNullish.size == 1 && nonNullish[0] is Type.Object) {
                        val collapsed = getPropertyElaborationChain(sObj, nonNullish[0], propPath)
                        if (collapsed != null &&
                            collapsed.first().trimStart().startsWith("The types of '")) {
                            return collapsed
                        }
                    }
                }
                val deeper = getPropertyElaborationChain(chosen.sourceType, chosen.targetType, propPath)
                if (deeper != null) {
                    // Two chain forms depending on what the deeper recursion produced:
                    //   1. **Collapsed form** — pure Object property nesting (no
                    //      Array/Reference elements in the middle). Deeper's first
                    //      line already reads "The types of '$propPath' are
                    //      incompatible between these types." naming the full path,
                    //      so the outer need not prepend its own "Types of property
                    //      'x' are incompatible." line. Matches TypeScript's
                    //      collapsed chain (e.g. `multiLineErrors_ts`).
                    //   2. **Per-level form** — chain went through an Array/Reference
                    //      element in the middle (deeper's first line starts with
                    //      "Type 'A[]' is not assignable to type 'B[]'." from the
                    //      same-target-ref shortcut). The path context isn't in the
                    //      deeper line, so we prepend the outer "Types of property
                    //      'X' are incompatible." line and indent the deeper chain
                    //      by 2 more spaces (e.g. `typeMatch2_ts`'s `{ f2: Animal[] }`
                    //      vs `{ f2: Giraffe[] }`).
                    val isCollapsed = deeper.first().trimStart().startsWith("The types of '")
                    return if (isCollapsed) deeper
                        else listOf(outerLine) + deeper.map { "  $it" }
                }
            }
            // Report at this level
            val sourcePropStr = typeToString(chosen.sourceType)
            val targetPropStr = typeToString(chosen.targetType)
            // Method-property collapsed form: when both prop types are pure function
            // types (call signatures only, no own properties/members) AND the
            // function-mismatch elaboration produces exactly one line — which is the
            // case for return-type-only mismatch, since param mismatch returns two
            // lines via `Types of parameters '...' incompatible.` — TypeScript collapses
            // the chain to "The types returned by 'X()' are incompatible between these
            // types." instead of "Types of property 'X' are incompatible. Type '() => A'
            // is not assignable to type '() => B'." (cf. `generics4_ts`'s `f(): boolean`
            // vs `f(): string`). For param mismatches and arity mismatches, fall through
            // to the standard "Types of property" + function-type-display + funcExtra path.
            val srcObjForCollapse = chosen.sourceType as? Type.Object
            val tgtObjForCollapse = chosen.targetType as? Type.Object
            val funcMismatch: List<String>? = if (
                srcObjForCollapse != null && tgtObjForCollapse != null &&
                !srcObjForCollapse.callSignatures.isNullOrEmpty() &&
                !tgtObjForCollapse.callSignatures.isNullOrEmpty() &&
                srcObjForCollapse.properties.isNullOrEmpty() &&
                tgtObjForCollapse.properties.isNullOrEmpty() &&
                srcObjForCollapse.members.isNullOrEmpty() &&
                tgtObjForCollapse.members.isNullOrEmpty()
            ) {
                getFunctionMismatchElaboration(srcObjForCollapse, tgtObjForCollapse)
            } else null
            // Use collapsed "types returned by" form for return-type mismatch.
            // funcMismatch's first line is "  Type 'A' is not assignable to type 'B'.".
            // Arity mismatch ("Target signature provides too few...") and param mismatch
            // ("Types of parameters...") keep the standard "Types of property" + function-
            // type-display + funcExtra format.
            // B75.3: funcMismatch may now have MULTIPLE lines when the return type
            // drills deeper into a generic element pair (e.g. `A[]` vs `B[]` →
            // `Property 'b' is missing...`). The deeper lines are property-drill chains,
            // not param-mismatch chains, so the collapsed "types returned by" form is
            // still appropriate. Gate on FIRST line shape only.
            if (funcMismatch != null && funcMismatch.isNotEmpty() &&
                funcMismatch[0].trimStart().startsWith("Type '")) {
                // B75.2: TypeScript renders the method-name suffix as `(...)` when the
                // target signature has at least one parameter, `()` when it has none.
                // Mirrors `Type '() => A' is not assignable to type '() => B'.` collapsed
                // header convention. Use target's first call signature's parameter list
                // (we already passed the `!callSignatures.isNullOrEmpty()` gate above).
                val tgtFirstSig = tgtObjForCollapse!!.callSignatures!!.first()
                val parenSuffix = if (tgtFirstSig.parameters.isNotEmpty()) "(...)" else "()"
                val collapsedHeader = if (path.isEmpty()) {
                    "  The types returned by '${chosen.name}$parenSuffix' are incompatible between these types."
                } else {
                    "  The types returned by '$propPath$parenSuffix' are incompatible between these types."
                }
                return listOf(collapsedHeader) + funcMismatch.map { "  $it" }
            }
            // If the chosen mismatched property is a function (call signatures only),
            // append parameter-mismatch / return-type lines to deepen the chain.
            // The chain line ("    Type 'A' is not assignable to type 'B'.") sits at
            // 4-space depth; the function-mismatch lines sit two levels deeper at
            // 6 and 8 spaces. `getFunctionMismatchElaboration` emits at 2/4 spaces,
            // so prepend 4 extra spaces to each line.
            val funcExtra: List<String> = run {
                val srcObj = chosen.sourceType as? Type.Object ?: return@run emptyList()
                val tgtObj = chosen.targetType as? Type.Object ?: return@run emptyList()
                if (srcObj.callSignatures.isNullOrEmpty() || tgtObj.callSignatures.isNullOrEmpty()) {
                    return@run emptyList()
                }
                getFunctionMismatchElaboration(srcObj, tgtObj).map { "    $it" }
            }
            // When the source prop was widened from `T` to `T | undefined` because the
            // source declares it optional but the target requires it (strictNullChecks),
            // add the deeper "Type 'undefined' is not assignable to type '$target'." chain
            // line to match TypeScript's elaboration depth (cf. `assignmentCompatability11`,
            // `…15`, `…21`, `…25`, `…39`, `…43`, etc.).
            val undefinedExtra: List<String> = if (chosen.sourceWidenedForOptional) {
                listOf("      Type 'undefined' is not assignable to type '$targetPropStr'.")
            } else emptyList()
            // B86.7c: per-failing-constituent elaboration for Union sources. When the
            // source prop type is a Union and the leaf line "Type '<union>' is not
            // assignable to type '<target>'." is emitted, TypeScript follows it with a
            // sub-line naming the SPECIFIC constituent that fails (e.g. for
            // `number | undefined` vs `string | null`, the `undefined` member is the
            // elaborated failing constituent). Gate is narrow: only fire when source is
            // a Union, no funcExtra/undefinedExtra already applies, and at least one
            // constituent genuinely fails assignability to the target prop type.
            // Prefer the nullish failing constituent (matches TypeScript's display
            // ordering for nullable targets); fall back to the first failing one.
            val unionConstituentExtra: List<String> =
                if (chosen.sourceType is Type.Union && undefinedExtra.isEmpty() && funcExtra.isEmpty()) {
                    // Narrow gate: only elaborate when the failing constituent is NULLISH
                    // (null/undefined/void). Non-nullish failing constituents (e.g. a
                    // plain `number` vs `string | null`) are NOT shown by TypeScript,
                    // and broadening to them would change many existing union-source
                    // TS2322 chains. This keeps the surface limited to the
                    // nullable-mismatch family (cf. elaboratedErrorsOnNullableTargets01).
                    val pick = (chosen.sourceType as Type.Union).types.firstOrNull {
                        isNullishConstituent(it) &&
                            !checkTypeRelatedTo(it, chosen.targetType, assignableRelation)
                    }
                    if (pick != null) {
                        listOf("      Type '${typeToString(pick)}' is not assignable to type '$targetPropStr'.")
                    } else emptyList()
                } else emptyList()
            return listOf(
                outerLine,
                "    Type '$sourcePropStr' is not assignable to type '$targetPropStr'.",
            ) + undefinedExtra + unionConstituentExtra + funcExtra
        } finally {
            state.elaborationStack.remove(pairKey)
        }
    }

    /**
     * 17.42: elaboration chain for `Type.Intersection` source vs `Type.Object` target.
     * Merges members from intersection constituents (`{fooProp: string}` + `Bar` →
     * `{fooProp: string, barProp: string}`), then walks target's properties looking
     * for the first incompatible match. Emits the standard "Types of property '$name'
     * are incompatible. Type '$src' is not assignable to type '$tgt'." chain — same
     * shape as Object→Object property mismatch.
     *
     * Pairs with 17.41's substitution so calls returning `T & Bar` (with T inferred
     * from anonymous Type.Object args) get the substituted intersection source and
     * a per-property elaboration chain. Conservative: only handles direct property-
     * level mismatches (no recursion into nested objects, no method-collapsed form,
     * no privacy / private-brand checks — those don't apply to intersection sources
     * in the corpus). When the chain doesn't find an incompatible property, falls
     * through to the missing-property path.
     */
    private fun getIntersectionPropertyElaborationChain(
        source: Type.Intersection,
        target: Type.Object,
        path: String,
    ): List<String>? {
        // Cycle detection: pack (source.id, target.id) like the Object→Object path
        val pairKey = packRelationKey(source.id, target.id)
        if (pairKey in state.elaborationStack) return null
        state.elaborationStack.add(pairKey)
        try {
            // Merge object-like constituent members. Reference / Interface / anonymous
            // Object all contribute. Later constituents override earlier on conflict
            // (matches TS's intersection-member resolution for our scope).
            val mergedMembers = mutableMapOf<String, Symbol>()
            for (c in source.types) {
                if (c is Type.Object) {
                    resolveStructuredTypeMembers(c)
                    c.members?.forEach { (n, s) -> mergedMembers[n] = s }
                }
            }
            if (mergedMembers.isEmpty()) return null
            resolveStructuredTypeMembers(target)
            val targetProps = target.properties ?: return null
            // First incompatible property emits the chain
            for (targetProp in targetProps) {
                val sourceProp = mergedMembers[targetProp.name] ?: continue
                if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                val srcType = try { getTypeOfSymbol(sourceProp) } catch (_: StackOverflowError) { continue }
                val tgtType = try { getTypeOfSymbol(targetProp) } catch (_: StackOverflowError) { continue }
                if (srcType === errorType || tgtType === errorType) continue
                if (!checkTypeRelatedTo(srcType, tgtType, assignableRelation)) {
                    val propPath = if (path.isEmpty()) targetProp.name else "$path.${targetProp.name}"
                    val outerLine = if (path.isEmpty()) {
                        "  Types of property '${targetProp.name}' are incompatible."
                    } else {
                        "  The types of '$propPath' are incompatible between these types."
                    }
                    val sourcePropStr = typeToString(srcType)
                    val targetPropStr = typeToString(tgtType)
                    return listOf(
                        outerLine,
                        "    Type '$sourcePropStr' is not assignable to type '$targetPropStr'.",
                    )
                }
            }
            // No property-type mismatch — try missing-required-property path against
            // any constituent that's an Object-like (FIRST constituent for simplicity;
            // matches TypeScript's behavior of attributing missing-prop to the named
            // intersection member).
            for (c in source.types) {
                if (c is Type.Object) {
                    resolveStructuredTypeMembers(c)
                    val missing = getMissingRequiredPropertySymbol(c, target)
                    if (missing != null) {
                        return listOf(
                            "  Property '${missing.name}' is missing in type '${typeToString(source)}' but required in type '${typeToString(target)}'."
                        )
                    }
                }
            }
            return null
        } finally {
            state.elaborationStack.remove(pairKey)
        }
    }

    /**
     * Find the first non-optional target property that source lacks and that source's
     * string index signature (if any) does not satisfy. Mirrors `propertiesRelatedTo`'s
     * missing-property logic so the elaboration chain can include "Property 'X' is
     * missing in type 'A' but required in type 'B'." for purely structural failures
     * (no per-property type mismatch). Sets `lastChainMissingPropSymbol` so callers
     * can attach matching TS2728 "'X' is declared here." related info to TS2322.
     */
    private fun getMissingRequiredPropertySymbol(source: Type.Object, target: Type.Object): Symbol? {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val targetProps = target.properties ?: return null
        val sourceMembers = source.members ?: return null
        val srcIndex = source.stringIndexInfo
        val targetStatics = getStaticMembersOfType(target)
        for (targetProp in targetProps) {
            if (targetStatics != null && targetStatics.containsKey(targetProp.name)) continue
            if (sourceMembers[targetProp.name] != null) continue
            if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (isOptionalProperty(targetProp)) continue
            if (srcIndex != null) {
                val targetPropType = getPropertyTypeForRelation(target, targetProp)
                if (checkTypeRelatedTo(srcIndex.type, targetPropType, assignableRelation)) continue
            }
            lastChainMissingPropSymbol = targetProp
            return targetProp
        }
        return null
    }

    /** Check if a property symbol is optional (has questionToken in its declaration). */
    /**
     * 16.4eb: Does the type accept `undefined` as a value? True for explicit undefined,
     * any/unknown/never, or unions whose constituents include any of those. Used by
     * the TS2790 "delete operand must be optional" check.
     */
    private fun typeIncludesUndefinedOrTop(type: Type): Boolean {
        if (type.flags.hasAny(
                TypeFlags.Undefined or TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never)) return true
        if (type is Type.Union) return type.types.any { typeIncludesUndefinedOrTop(it) }
        return false
    }

    private fun isOptionalProperty(symbol: Symbol): Boolean {
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull() ?: return false
        return when (decl) {
            is PropertyDeclaration -> decl.questionToken
            is Parameter -> decl.questionToken
            is MethodDeclaration -> decl.questionToken
            else -> false
        }
    }

    /**
     * Under strictNullChecks, optional source property `prop?: T` accepts `undefined` —
     * it widens to `T | undefined` when comparing against a target's required property.
     * Returns the widened type, or the original type when widening doesn't apply.
     */
    private fun widenOptionalSourcePropType(
        sourceType: Type,
        sourceProp: Symbol,
        targetProp: Symbol,
    ): Type {
        if (!strictNullChecks) return sourceType
        if (!isOptionalProperty(sourceProp)) return sourceType
        if (isOptionalProperty(targetProp)) return sourceType
        if (typeIncludesUndefinedOrTop(sourceType)) return sourceType
        return getUnionType(listOf(sourceType, undefinedType))
    }

    /**
     * Render a property's name for type display. Quotes the name when it was written as
     * a string-literal key AND is not a valid JS identifier (mirrors TypeScript's display:
     * `"0"`, `"ns:attribute"`, `"resolution-mode"` stay quoted; `"hello"` displays as
     * `hello`; numeric-literal keys like `0:` and identifier keys stay unquoted).
     */
    private fun formatPropertyDisplayName(symbol: Symbol): String {
        val name = symbol.name
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
        val nameNode = when (decl) {
            is PropertyAssignment -> decl.name
            is ShorthandPropertyAssignment -> decl.name
            is MethodDeclaration -> decl.name
            is PropertyDeclaration -> decl.name
            else -> null
        }
        if (nameNode is StringLiteralNode && !isValidJsIdentifier(name)) {
            return "\"$name\""
        }
        return name
    }

    private fun isValidJsIdentifier(text: String): Boolean {
        if (text.isEmpty()) return false
        val first = text[0]
        if (!first.isLetter() && first != '_' && first != '$') return false
        for (i in 1 until text.length) {
            val c = text[i]
            if (!c.isLetterOrDigit() && c != '_' && c != '$') return false
        }
        return true
    }

    /**
     * Check if source type is assignable to target type using the new Type-based engine.
     * This is the replacement for the string-based isAssignableTo.
     */
    private fun isTypeAssignableTo(source: Type, target: Type): Boolean {
        return checkTypeRelatedTo(source, target, assignableRelation)
    }

    // -----------------------------------------------------------------------
    // Generic type instantiation (Phase 4 item 8a)
    // -----------------------------------------------------------------------

    /**
     * TypeMapper — maps type parameters to concrete types during generic instantiation.
     */
    private fun interface TypeMapper {
        fun map(typeParam: Type.TypeParam): Type?
    }

    /**
     * Create a TypeMapper from parallel lists of type parameters and type arguments.
     */
    private fun createTypeMapper(typeParams: List<Type.TypeParam>, typeArgs: List<Type>): TypeMapper {
        return TypeMapper { tp ->
            val index = typeParams.indexOf(tp)
            if (index >= 0 && index < typeArgs.size) typeArgs[index] else null
        }
    }

    /**
     * Recursively substitute type parameters in a type according to the given mapper.
     * Returns the same type if no substitution occurs.
     */
    private fun instantiateType(type: Type, mapper: TypeMapper): Type {
        return when (type) {
            is Type.TypeParam -> mapper.map(type) ?: type
            is Type.Union -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getUnionType(mapped)
            }
            is Type.Intersection -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getIntersectionType(mapped)
            }
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return type
                val mapped = args.map { instantiateType(it, mapper) }
                if (mapped.zip(args).all { (a, b) -> a === b }) type
                else getOrInternReference(type.target, mapped)
            }
            is Type.Object -> {
                // B52.3: For anonymous Type.Object (no Interface/Reference subclass,
                // no symbol, no call/construct signatures), walk members and substitute
                // TypeParam-typed property types. This unlocks per-property TS2322 at
                // object-literal args under explicit type args (e.g. `foo<number>({x:3, y:""})`
                // against `(n: {x:T, y:T})`). Narrow gate: only PURE PROPERTY-BAG anonymous
                // objects — function-shaped objects (call/construct sigs) and named types
                // are still returned as-is to avoid broad regressions (see CLAUDE.md
                // "instantiateType for Type.Object" gotcha).
                if (type is Type.Interface || type is Type.Reference) return type
                if (type.symbol != null) return type
                if (!type.callSignatures.isNullOrEmpty()) return type
                if (!type.constructSignatures.isNullOrEmpty()) return type
                val origMembers = type.members ?: return type
                if (origMembers.isEmpty()) return type
                var anyChanged = false
                val newMembers: SymbolTable = mutableMapOf()
                val newProps = mutableListOf<Symbol>()
                for ((name, memberSym) in origMembers) {
                    val memberType = try { getTypeOfSymbol(memberSym) } catch (_: StackOverflowError) {
                        return type
                    }
                    val instMemberType = instantiateType(memberType, mapper)
                    if (instMemberType === memberType) {
                        newMembers[name] = memberSym
                        newProps.add(memberSym)
                    } else {
                        anyChanged = true
                        val newSym = Symbol(memberSym.flags, memberSym.name)
                        newSym.declarations.addAll(memberSym.declarations)
                        newSym.valueDeclaration = memberSym.valueDeclaration
                        symbolTypes[newSym.id] = instMemberType
                        newMembers[name] = newSym
                        newProps.add(newSym)
                    }
                }
                if (!anyChanged) return type
                val newObj = Type.Object()
                newObj.members = newMembers
                newObj.properties = newProps
                newObj
            }
            // Intrinsic, literal types don't contain type parameters
            else -> type
        }
    }

    /**
     * B86.1b (activation, 2026-05-28): instantiate a CONTEXTUAL parameter type through an
     * inference mapper. Unlike [instantiateType] (which deliberately returns
     * function-shaped Type.Object UNCHANGED — see CLAUDE.md "instantiateType for
     * Type.Object" gotcha), this helper DOES descend into a function-shaped
     * Type.Object's call signatures so a contextual callback type like `(x: T) => U`
     * becomes `(x: <mapped T>) => <mapped U>`. This is what lets the un-annotated lambda
     * param `x` resolve to the concrete inferred type during the diagnostic walk
     * (`checkPropertyAccessInExpr`'s ArrowFunction / FunctionExpression branches push
     * `currentLocalTypes[x] = <contextual sig param type>`). Used ONLY at the
     * checkPropertyAccessInExpr CallExpression arg-context computation — narrowly scoped
     * so the existing instantiateType no-op behavior (relied on elsewhere) is untouched.
     */
    private fun instantiateContextualParamType(type: Type, mapper: TypeMapper): Type {
        if (type is Type.Object && type !is Type.Interface && type !is Type.Reference &&
            type.symbol == null && !type.callSignatures.isNullOrEmpty() &&
            type.constructSignatures.isNullOrEmpty()
        ) {
            val newSigs = type.callSignatures!!.map { instantiateContextualSignature(it, mapper) }
            // Avoid allocating a fresh object when nothing changed (identity preserved
            // per-signature is not guaranteed, so compare element-wise on the sigs).
            if (newSigs.zip(type.callSignatures!!).all { (a, b) -> a === b }) return type
            val newObj = Type.Object()
            newObj.callSignatures = newSigs
            newObj.properties = type.properties
            newObj.members = type.members
            return newObj
        }
        return instantiateType(type, mapper)
    }

    /**
     * B83.4d: like [instantiateSignature] but uses [instantiateContextualParamType]
     * (rather than the function-shape-no-op [instantiateType]) for BOTH parameter
     * types AND the return type, so a callback-returning-a-callback contextual type
     * `() => (a: T) => void` substitutes its inner `(a: T)` to `(a: <mapped>)`.
     * Used only by the contextual-param substitution path in [checkPropertyAccessInExpr];
     * preserves [instantiateSignature]'s behavior for non-function-shaped members.
     */
    private fun instantiateContextualSignature(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateContextualParamType(it, mapper) }
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateContextualParamType(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        return Signature(
            declaration = sig.declaration,
            typeParameters = null,
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * Instantiate a signature with type arguments — substitute type params in parameter types
     * and return type.
     */
    private fun instantiateSignature(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateType(it, mapper) }
        // Instantiate parameter types — create new symbols with mapped types
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateType(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        return Signature(
            declaration = sig.declaration,
            typeParameters = null, // instantiated signature has no type parameters
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * 17.39: Substitute outer typeArgs into a freshly-resolved function-typed property's
     * inner generic signatures — typeParam constraints/defaults, param types, return
     * type. Mutates [rawType]'s callSignatures/constructSignatures lists in place; the
     * inner Signatures' typeParameters are also mutated in place (their `constraint` /
     * `default` fields reassigned). Caller must guarantee [rawType] is freshly allocated
     * (e.g. resolved through `getTypeFromTypeNode` while `currentTypeParamScope != null`)
     * — this is currently the case in `resolveGenericPropertyType`'s PropertyDeclaration
     * branch. Preserves the inner sig's typeParameter list (T stays generic) so call-site
     * inference + constraint check via 16.4ds / 16.4i still fires.
     */
    private fun substituteOuterTypeArgsInGenericFnObject(rawType: Type.Object, mapper: TypeMapper) {
        rawType.callSignatures = rawType.callSignatures?.map { substituteOuterTypeArgsInSignature(it, mapper) }
        rawType.constructSignatures = rawType.constructSignatures?.map { substituteOuterTypeArgsInSignature(it, mapper) }
    }

    private fun substituteOuterTypeArgsInSignature(sig: Signature, mapper: TypeMapper): Signature {
        // Mutate sig's typeParameter constraints/defaults in place — they reference the
        // outer interface's TypeParams (e.g. `<T extends S>` where S is the outer one),
        // and we want substituted forms visible at the call site without erasing T's
        // generic identity. TPs are fresh per-call (see uncached getTypeFromTypeNode).
        sig.typeParameters?.forEach { tp ->
            tp.constraint = tp.constraint?.let { instantiateType(it, mapper) }
            tp.default = tp.default?.let { instantiateType(it, mapper) }
        }
        val newReturnType = sig.resolvedReturnType?.let { instantiateType(it, mapper) }
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateType(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        val paramsChanged = newParams.zip(sig.parameters).any { (a, b) -> a !== b }
        val returnChanged = newReturnType !== sig.resolvedReturnType
        if (!paramsChanged && !returnChanged) return sig
        return Signature(
            declaration = sig.declaration,
            typeParameters = sig.typeParameters, // preserve — still generic at call site
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * Like [typeToString] but substitutes TypeParam references via [mapper] at display
     * time. Used to render an un-instantiated constraint (e.g. `{ a: T }`) as the
     * substituted form (`{ a: string }`) in TS2344 messages without touching the type
     * system. Walks anonymous Type.Object property types; falls back to [typeToString]
     * for named types, signatures, and anything the walker doesn't know how to render.
     */
    private fun typeToStringWithMapper(type: Type, mapper: TypeMapper): String {
        // Order matters: Type.Interface and Type.Reference must be checked BEFORE
        // Type.Object — both extend Type.Object.
        return when (type) {
            is Type.TypeParam -> mapper.map(type)?.let { typeToString(it) } ?: (type.symbol?.name ?: "T")
            is Type.Interface -> typeToString(type)
            is Type.Reference -> {
                val args = type.resolvedTypeArguments
                if (type.target === globalArrayType && args != null && args.size == 1) {
                    val elemStr = typeToStringWithMapper(args[0], mapper)
                    if (args[0] is Type.Union || args[0] is Type.Intersection) "($elemStr)[]"
                    else "$elemStr[]"
                } else {
                    val target = type.target.symbol?.name ?: "Object"
                    if (args != null && args.isNotEmpty()) {
                        "$target<${args.joinToString(", ") { typeToStringWithMapper(it, mapper) }}>"
                    } else target
                }
            }
            is Type.Object -> {
                // Only rewrite anonymous object types (no backing symbol declaration).
                // Named types display by name via typeToString; callers don't expect
                // their bodies to be walked.
                if (type.symbol != null) return typeToString(type)
                val hasSignatures = !type.callSignatures.isNullOrEmpty() || !type.constructSignatures.isNullOrEmpty()
                if (hasSignatures) return typeToString(type)
                val props = type.properties ?: return typeToString(type)
                val parts = mutableListOf<String>()
                for (p in props) {
                    val pt = symbolTypes[p.id]
                    val typeStr = if (pt != null) typeToStringWithMapper(pt, mapper) else "any"
                    val displayName = formatPropertyDisplayName(p)
                    if (isOptionalProperty(p)) {
                        parts.add("$displayName?: $typeStr | undefined")
                    } else {
                        parts.add("$displayName: $typeStr")
                    }
                }
                if (parts.isNotEmpty()) "{ ${parts.joinToString("; ")}; }" else "{}"
            }
            is Type.Union -> type.types.joinToString(" | ") { typeToStringWithMapper(it, mapper) }
            is Type.Intersection -> type.types.joinToString(" & ") { typeToStringWithMapper(it, mapper) }
            else -> typeToString(type)
        }
    }

    /**
     * Return an interned `Type.Reference` for `(target, args)`. Two calls with the same
     * target and the same arg ids return the SAME instance, so the resulting `Type.id`
     * is stable across instantiations. Cycle detection in `relationComparisonStack`
     * keys on `(source.id, target.id)` and relies on this identity to catch
     * self-referential generics like `interface List<T> { next: List<T> }` whose
     * member instantiation would otherwise mint fresh Ref ids per recursion level.
     *
     * Pass `args = null` to denote a Reference with no resolved arguments (e.g. a raw
     * generic with no instantiation). This is rare; most call sites pass an actual list.
     */
    private fun getOrInternReference(target: Type.Interface, args: List<Type>?): Type.Reference {
        val key = buildString {
            append(target.id)
            append('|')
            if (args != null) args.joinTo(this, ",") { it.id.toString() }
        }
        return state.referenceCache.getOrPut(key) {
            Type.Reference(target, resolvedTypeArguments = args)
        }
    }

    /** Create an array type: `Type.Reference(globalArrayType, [elementType])`. */
    private fun getArrayType(elementType: Type): Type {
        return getOrInternReference(globalArrayType, listOf(elementType))
    }

    /** Create a tuple type from a TupleType node. */
    private fun getTupleType(node: TupleType): Type {
        val elementTypes = node.elements.map { elem ->
            when (elem) {
                is NamedTupleMember -> getTypeFromTypeNode(elem.type)
                is OptionalType -> getTypeFromTypeNode(elem.type)
                is RestType -> getTypeFromTypeNode(elem.type)
                else -> getTypeFromTypeNode(elem)
            }
        }
        val tupleObj = Type.Object()
        tupleObj.tupleElementTypes = elementTypes
        // Create numbered property symbols: "0", "1", "2", ...
        val props = mutableListOf<Symbol>()
        val members = symbolTable()
        for ((i, elemType) in elementTypes.withIndex()) {
            val propSymbol = Symbol(
                flags = SymbolFlags.Property,
                name = i.toString(),
            )
            symbolTypes[propSymbol.id] = elemType
            props.add(propSymbol)
            members[propSymbol.name] = propSymbol
        }
        // Add readonly "length" property with literal type
        val lengthSymbol = Symbol(
            flags = SymbolFlags.Property,
            name = "length",
        )
        symbolTypes[lengthSymbol.id] = Type.NumberLiteral(elementTypes.size.toDouble())
        props.add(lengthSymbol)
        members["length"] = lengthSymbol
        tupleObj.properties = props
        tupleObj.members = members
        // Tuple has a number index signature for element access
        if (elementTypes.isNotEmpty()) {
            val elementUnion = if (elementTypes.size == 1) elementTypes[0]
                else getUnionType(elementTypes)
            tupleObj.numberIndexInfo = IndexInfo(keyType = numberType, type = elementUnion)
        }
        return tupleObj
    }

    /** Resolve a typeof type query: `typeof X` in type annotation position. */
    private fun getTypeFromTypeQuery(node: TypeQuery): Type {
        val exprName = node.exprName
        when (exprName) {
            is Identifier -> {
                // Handle special built-in names
                when (exprName.text) {
                    "undefined" -> return undefinedType
                    "NaN", "Infinity" -> return numberType
                    "true", "false" -> return booleanType
                }
                // Look up in globals only — currentLocalTypes contains function-scoped
                // variables that shouldn't be visible in type annotation positions
                val symbol = globals[exprName.text] ?: return anyType
                return getTypeOfSymbolForTypeQuery(symbol)
            }
            is QualifiedName -> {
                // typeof A.B.C — resolve chain
                val symbol = resolveQualifiedName(exprName) ?: return anyType
                return getTypeOfSymbolForTypeQuery(symbol)
            }
            else -> return anyType
        }
    }

    /** Get the type of a symbol as it appears in a typeof query.
     *  For classes, returns the constructor type (static side), not the instance type.
     *  For functions/variables, delegates to getTypeOfSymbol. */
    private fun getTypeOfSymbolForTypeQuery(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Class) -> {
                // typeof ClassName → constructor type with construct signature
                val classType = getDeclaredTypeOfSymbol(symbol)
                if (classType === anyType || classType === errorType) return anyType
                val ctorType = Type.Object()
                ctorType.symbol = symbol
                // Mark `abstract new (...) => X` if the class declaration has the abstract modifier.
                val classDecl = symbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                val isAbstract = classDecl != null && ModifierFlag.Abstract in classDecl.modifiers
                // Use the class's actual constructor parameters (or empty for implicit no-arg
                // ctor). Without real params, structural comparison of `typeof Class` against
                // another constructor-typed target is too loose — see classSideInheritance3
                // where C's 1-param ctor must match A's 1-param ctor through `typeof A`.
                val ctor = classDecl?.members?.filterIsInstance<Constructor>()?.let { ctors ->
                    ctors.firstOrNull { it.body != null } ?: ctors.firstOrNull()
                }
                val params = ctor?.parameters?.let { getParameterSymbols(it) } ?: emptyList()
                val minArgs = ctor?.parameters?.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                } ?: 0
                val ctorSig = Signature(
                    declaration = ctor,
                    parameters = params,
                    resolvedReturnType = classType,
                    minArgumentCount = minArgs,
                    isAbstract = isAbstract,
                )
                ctorType.constructSignatures = listOf(ctorSig)
                // Copy static members from class symbol exports
                val staticProps = mutableListOf<Symbol>()
                val staticMembers = symbolTable()
                symbol.exports?.forEach { (name, exportSym) ->
                    staticProps.add(exportSym)
                    staticMembers[name] = exportSym
                }
                if (staticProps.isNotEmpty()) {
                    ctorType.properties = staticProps
                    ctorType.members = staticMembers
                }
                ctorType
            }
            flags.hasAny(SymbolFlags.Alias) -> {
                val target = resolveAliasTarget(symbol)
                if (target != null && target !== symbol) getTypeOfSymbolForTypeQuery(target) else anyType
            }
            else -> getTypeOfSymbol(symbol)
        }
    }

    /**
     * Build a Type.Object representing the constructor side of a class symbol —
     * a `Type.Object` carrying the class's actual constructor parameter list(s)
     * as its `constructSignatures`. Used for diagnostic display when a class
     * Identifier is used in value position (e.g. `const foo = Foo`); the
     * resulting type is what TypeScript would print as `typeof Foo`.
     *
     * Reads the class declaration's first explicit Constructor member; falls
     * back to a 0-param implicit constructor if none. Marks the construct sig
     * `isAbstract` when the class itself is abstract.
     */
    private fun buildClassValueConstructorTypeForDisplay(symbol: Symbol): Type.Object? {
        val classDecl = symbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
            ?: return null
        val classType = getDeclaredTypeOfSymbol(symbol)
        if (classType === anyType || classType === errorType) return null
        val isAbstract = ModifierFlag.Abstract in classDecl.modifiers
        val ctors = classDecl.members.filterIsInstance<Constructor>()
        // Prefer overload signatures (body-less) over the implementation when both are present —
        // matches TypeScript's caller-visible signature set. When no explicit ctor, synthesize
        // a single 0-param signature (the implicit constructor).
        val sigDecls = if (ctors.any { it.body == null && ctors.size > 1 }) {
            ctors.filter { it.body == null }
        } else if (ctors.isNotEmpty()) {
            listOf(ctors.first())
        } else {
            emptyList()
        }
        val sigs = if (sigDecls.isEmpty()) {
            listOf(Signature(
                resolvedReturnType = classType,
                parameters = emptyList(),
                minArgumentCount = 0,
                isAbstract = isAbstract,
            ))
        } else sigDecls.map { ctor ->
            Signature(
                declaration = ctor,
                parameters = getParameterSymbols(ctor.parameters),
                resolvedReturnType = classType,
                minArgumentCount = ctor.parameters.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                },
                isAbstract = isAbstract,
            )
        }
        val ctorType = Type.Object()
        ctorType.symbol = symbol
        ctorType.constructSignatures = sigs
        return ctorType
    }

    /**
     * 17.19: Build the base-class constructor signature for `super(...)` checking,
     * substituting the heritage clause's type arguments for the base class's
     * type parameters. Returns null if the base symbol can't be resolved or has
     * no constructor decl. Picks the first implementation ctor if any; otherwise
     * the first overload decl.
     *
     * @param baseSymbol  The base class's symbol (resolved from the heritage clause)
     * @param typeArgs    Resolved heritage-clause type arguments, or empty list for non-generic
     */
    private fun buildBaseConstructorSignatureForSuper(
        baseSymbol: Symbol,
        typeArgs: List<Type>,
    ): Signature? {
        if (!baseSymbol.flags.hasAny(SymbolFlags.Class)) return null
        val baseDecl = baseSymbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
            ?: return null
        val ctors = baseDecl.members.filterIsInstance<Constructor>()
        // Prefer the implementation (body present); else the first overload decl.
        val ctor = ctors.firstOrNull { it.body != null } ?: ctors.firstOrNull()
        val params = ctor?.parameters?.let { getParameterSymbols(it) } ?: emptyList()
        val minArgs = ctor?.parameters?.count {
            !it.questionToken && !it.dotDotDotToken && it.initializer == null
        } ?: 0
        val baseType = getDeclaredTypeOfSymbol(baseSymbol) as? Type.Interface ?: return null
        val baseTypeParams = baseType.typeParameters.orEmpty()
        // Resolve param types in the base class's type-param scope so `T` resolves to
        // the base's TypeParam (not errorType). Cache into symbolTypes per param.
        if (ctor != null) {
            val savedScope = currentTypeParamScope
            try {
                if (baseTypeParams.isNotEmpty()) {
                    val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                    baseTypeParams.forEach { tp ->
                        tp.symbol?.name?.let { scope[it] = tp }
                    }
                    currentTypeParamScope = scope
                }
                for ((pi, paramSym) in params.withIndex()) {
                    if (pi < ctor.parameters.size) {
                        val paramTypeNode = ctor.parameters[pi].type
                        if (paramTypeNode != null) {
                            try {
                                symbolTypes[paramSym.id] = getTypeFromTypeNode(paramTypeNode)
                            } catch (_: StackOverflowError) { /* leave unresolved */ }
                        }
                    }
                }
            } finally {
                currentTypeParamScope = savedScope
            }
        }
        val rawSig = Signature(
            declaration = ctor,
            parameters = params,
            resolvedReturnType = baseType,
            minArgumentCount = minArgs,
        )
        if (baseTypeParams.isEmpty() || typeArgs.size != baseTypeParams.size) return rawSig
        val mapper = createTypeMapper(baseTypeParams, typeArgs)
        return instantiateSignature(rawSig, mapper)
    }

    /**
     * 17.20: Build the base-class instance type for `super.method(...)` lookups.
     * Returns:
     * - `Type.Reference(baseInterface, typeArgs)` if the base is generic and arity matches
     * - the bare `Type.Interface` if the base is non-generic
     * - the bare `Type.Interface` if arity doesn't match (raw — substitution skipped)
     * - null if the base isn't a class symbol or its declared type isn't an Interface
     */
    private fun buildBaseInstanceTypeForSuper(
        baseSymbol: Symbol,
        typeArgs: List<Type>,
    ): Type? {
        if (!baseSymbol.flags.hasAny(SymbolFlags.Class)) return null
        val baseType = getDeclaredTypeOfSymbol(baseSymbol) as? Type.Interface ?: return null
        val baseTypeParams = baseType.typeParameters.orEmpty()
        if (baseTypeParams.isEmpty()) return baseType
        if (typeArgs.size != baseTypeParams.size) return baseType
        return getOrInternReference(baseType, typeArgs)
    }

    /**
     * 17.20: Resolve and arg-check `super.method(...)` against the base instance
     * type stashed by the ClassDeclaration handler. Returns true if handled
     * (caller skips standard arg-checking), false if not (caller falls through).
     *
     * Conservative — only fires when:
     * - the method is found on the base type
     * - the method has at least one call signature
     * - either: explicit type args resolve cleanly to a generic sig, OR exactly one
     *   non-generic signature (no overload resolution attempt with generics)
     */
    private fun handleSuperMethodCall(
        expr: CallExpression,
        callee: PropertyAccessExpression,
        baseType: Type,
        source: String,
        fileName: String,
    ): Boolean {
        val methodName = callee.name.text
        if (baseType !is Type.Object) return false
        val methodSym = try {
            getPropertyOfType(baseType, methodName)
        } catch (_: StackOverflowError) { null } ?: return false
        // Resolve method's type with substitution if base is a Reference
        val methodType = try {
            if (baseType is Type.Reference) {
                resolveGenericPropertyType(baseType, methodSym) ?: getTypeOfSymbol(methodSym)
            } else {
                getTypeOfSymbol(methodSym)
            }
        } catch (_: StackOverflowError) { return false }
        if (methodType !is Type.Object) return false
        val sigs = methodType.callSignatures
        if (sigs.isNullOrEmpty()) return false
        val typeArgs = expr.typeArguments
        // Explicit type args: instantiate matching generic sig
        if (!typeArgs.isNullOrEmpty()) {
            val resolvedTypeArgs = try {
                typeArgs.map { getTypeFromTypeNode(it) }
            } catch (_: StackOverflowError) { return false }
            if (resolvedTypeArgs.any { it === errorType }) return false
            val genericSig = sigs.firstOrNull { sig ->
                val tp = sig.typeParameters
                tp != null && tp.size == resolvedTypeArgs.size
            }
            if (genericSig?.typeParameters != null) {
                val mapper = createTypeMapper(genericSig.typeParameters!!, resolvedTypeArgs)
                val instantiated = try {
                    instantiateSignature(genericSig, mapper)
                } catch (_: StackOverflowError) { return false }
                checkArgumentsAgainstSignature(expr.arguments, instantiated, source, fileName)
                return true
            }
            return false
        }
        // No explicit type args: only handle single non-generic signature.
        if (sigs.size == 1 && sigs[0].typeParameters.isNullOrEmpty()) {
            checkArgumentsAgainstSignature(expr.arguments, sigs[0], source, fileName)
            return true
        }
        return false
    }

    /**
     * Generate a TS2322 elaboration chain for a construct-signature mismatch.
     * Mirrors `getFunctionMismatchElaboration` but operates on `constructSignatures`,
     * and prefixes the chain with `Types of construct signatures are incompatible.`
     * to match TypeScript's baseline format (see `assignmentCompatability44/45`).
     *
     * Returns `emptyList()` when neither side has construct sigs or when the
     * single-sig pair is mutually compatible (defensive — caller should only
     * invoke this after confirming `signaturesRelatedTo(... isConstruct=true)`
     * returned false).
     */
    private fun getConstructMismatchElaboration(
        source: Type.Object, target: Type.Object,
    ): List<String> {
        val sourceSigs = source.constructSignatures
        val targetSigs = target.constructSignatures
        if (sourceSigs.isNullOrEmpty() || targetSigs.isNullOrEmpty()) return emptyList()
        val sourceSig = sourceSigs.first()
        val targetSig = targetSigs.first()
        val sourceStr = signatureToString(sourceSig, isConstruct = true)
        val targetStr = signatureToString(targetSig, isConstruct = true)
        val chain = mutableListOf(
            "  Types of construct signatures are incompatible.",
            "    Type '$sourceStr' is not assignable to type '$targetStr'.",
        )
        if (sourceSig.minArgumentCount > targetSig.parameters.size) {
            chain.add(
                "      Target signature provides too few arguments. Expected ${sourceSig.parameters.size} or more, but got ${targetSig.parameters.size}."
            )
            return chain
        }
        // Per-parameter contravariant check
        val len = minOf(sourceSig.parameters.size, targetSig.parameters.size)
        for (i in 0 until len) {
            val sp = getTypeOfSymbol(sourceSig.parameters[i])
            val tp = getTypeOfSymbol(targetSig.parameters[i])
            if (!checkTypeRelatedTo(tp, sp, assignableRelation)) {
                // B9.1: binding-pattern synthesized params have empty `Symbol.name`;
                // render as `_` here (consistent with formatParameter).
                val sName = sourceSig.parameters[i].let { p ->
                    if (p.name.isEmpty() && (p.valueDeclaration as? Parameter)?.name.let {
                            it is ObjectBindingPattern || it is ArrayBindingPattern
                        }) "_" else p.name
                }
                val tName = targetSig.parameters[i].let { p ->
                    if (p.name.isEmpty() && (p.valueDeclaration as? Parameter)?.name.let {
                            it is ObjectBindingPattern || it is ArrayBindingPattern
                        }) "_" else p.name
                }
                chain.add(
                    "      Types of parameters '$sName' and '$tName' are incompatible."
                )
                chain.add("        Type '${typeToString(tp)}' is not assignable to type '${typeToString(sp)}'.")
                return chain
            }
        }
        // Return-type mismatch (covariant)
        val sourceRet = sourceSig.resolvedReturnType ?: anyType
        val targetRet = targetSig.resolvedReturnType ?: anyType
        if (!targetRet.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceRet, targetRet, assignableRelation)) {
            chain.add("      Type '${typeToString(sourceRet)}' is not assignable to type '${typeToString(targetRet)}'.")
        }
        return chain
    }

    /** Create a Type from a literal type node (e.g., `type X = "hello"` or `type Y = 42`). */
    private fun getTypeFromLiteralTypeNode(node: LiteralType): Type {
        return when (val literal = node.literal) {
            is StringLiteralNode -> Type.StringLiteral(literal.text)
            is NumericLiteralNode -> {
                val value = literal.text.toDoubleOrNull() ?: 0.0
                Type.NumberLiteral(value)
            }
            is BigIntLiteralNode -> Type.BigIntLiteral(literal.text.removeSuffix("n"))
            is Identifier -> when (literal.text) {
                "true" -> trueType
                "false" -> falseType
                else -> errorType
            }
            is PrefixUnaryExpression -> {
                // -42, -1n, etc.
                if (literal.operator == SyntaxKind.Minus) {
                    when (val operand = literal.operand) {
                        is NumericLiteralNode -> {
                            val value = -(operand.text.toDoubleOrNull() ?: 0.0)
                            Type.NumberLiteral(value)
                        }
                        is BigIntLiteralNode -> Type.BigIntLiteral("-${operand.text.removeSuffix("n")}")
                        else -> errorType
                    }
                } else errorType
            }
            else -> errorType
        }
    }

    /** Create a function type from a FunctionType node. */
    private fun getFunctionTypeFromNode(node: FunctionType): Type {
        val fnType = Type.Object()
        val sig = buildSignatureForFunctionLikeTypeNode(
            decl = node, typeParamDecls = node.typeParameters,
            params = node.parameters, returnTypeNode = node.type,
        )
        fnType.callSignatures = listOf(sig)
        return fnType
    }

    /** Create a constructor type from a ConstructorType node. */
    private fun getFunctionTypeFromConstructorNode(node: ConstructorType): Type {
        val ctorType = Type.Object()
        val sig = buildSignatureForFunctionLikeTypeNode(
            decl = node, typeParamDecls = node.typeParameters,
            params = node.parameters, returnTypeNode = node.type,
        )
        ctorType.constructSignatures = listOf(sig)
        return ctorType
    }

    /**
     * 17.10b: Shared signature builder for `FunctionType` / `ConstructorType` nodes.
     * Builds Type.TypeParam objects from `typeParamDecls`, pushes them into
     * `currentTypeParamScope`, eagerly resolves param types within that scope
     * (cached via `symbolTypes`), then resolves the return type. Without the
     * scope, type-param-named annotations like `<T>(x: T) => T`'s `T` resolve
     * via global lookup and the displayed signature drops `<T>` and shows raw `T`.
     */
    private fun buildSignatureForFunctionLikeTypeNode(
        decl: Node, typeParamDecls: List<TypeParameter>?,
        params: List<Parameter>, returnTypeNode: TypeNode?,
    ): Signature {
        val sigTypeParams = typeParamDecls?.map { tpDecl ->
            // B59.5: intern by TypeParameter AST position (mirrors B59.1/2 pattern at
            // FunctionExpression site ~51865 — FunctionType/ConstructorType TypeNodes
            // are TYPE-position annotations resolved many times during checking;
            // sharing identity across calls lets downstream caches keyed on Type.id
            // (e.g. substitutionResultCache) actually hit. Constraints/defaults are
            // re-resolved per call below (no null guard) to preserve original
            // per-call constraint-scope semantics — a 'null guard' regressed -1.
            typeParamInternCache.getOrPut(tpDecl.pos) {
                Type.TypeParam().also { tp ->
                    tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                }
            }
        }
        val savedScope = currentTypeParamScope
        if (!sigTypeParams.isNullOrEmpty()) {
            val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
            sigTypeParams.forEachIndexed { i, tp ->
                scope[typeParamDecls!![i].name.text] = tp
            }
            currentTypeParamScope = scope
        }
        val paramSyms = getParameterSymbols(params)
        val returnType: Type
        try {
            sigTypeParams?.forEachIndexed { i, tp ->
                typeParamDecls!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                typeParamDecls[i].default?.let { tp.default = getTypeFromTypeNode(it) }
            }
            for ((pi, param) in paramSyms.withIndex()) {
                if (pi < params.size) {
                    params[pi].type?.let { typeNode ->
                        symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                    }
                }
            }
            returnType = returnTypeNode?.let { getTypeFromTypeNode(it) } ?: anyType
        } finally {
            currentTypeParamScope = savedScope
        }
        return Signature(
            declaration = decl,
            typeParameters = sigTypeParams,
            parameters = paramSyms,
            resolvedReturnType = returnType,
            minArgumentCount = params.count { !it.questionToken && !it.dotDotDotToken && it.initializer == null },
        )
    }

    /** Create an object type from a TypeLiteral node (e.g., `{ x: number; y: string }`). */
    private fun getTypeFromTypeLiteral(node: TypeLiteral): Type {
        val members = mutableMapOf<String, Symbol>()
        val properties = mutableListOf<Symbol>()
        val callSignatures = mutableListOf<Signature>()
        val constructSignatures = mutableListOf<Signature>()
        // Detect mapped-type placeholder — the parser emits PropertyDeclaration(name="")
        // for `[K in T]:` constructs inside a TypeLiteral (see parseIndexSignatureOrProperty).
        // When present, treat the entire literal as an opaque mapped type (→ anyType)
        // because we can't enumerate members precisely.
        var sawMappedTypePlaceholder = false
        for (member in node.members) {
            when (member) {
                is PropertyDeclaration -> {
                    val name = when (val n = member.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> continue
                    }
                    if (name.isEmpty()) {
                        // Parser placeholder for `[K in T]: V` — skip; emit anyType for the literal.
                        sawMappedTypePlaceholder = true
                        continue
                    }
                    val propType = if (member.type != null) getTypeFromTypeNode(member.type!!) else anyType
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(member)
                    sym.valueDeclaration = member
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is MethodDeclaration -> {
                    val nameNode = member.name
                    val name = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> ""
                    }
                    // 17.10a: Build the call/construct/method signature's own type
                    // parameters and push them into the type-param scope so
                    // `<Tstring>(a: Tstring): Tstring` resolves the `Tstring`
                    // annotations to our TypeParam (instead of falling through to
                    // global lookup → errorType → display `(a: error) => any`).
                    // B59.7: intern by TypeParameter AST position (mirrors B59.5 at
                    // buildSignatureForFunctionLikeTypeNode site ~69044). TypeLiteral
                    // MethodDeclaration TypeParams are TYPE-position annotations
                    // resolved many times during checking; identity-stable instances
                    // let downstream id-keyed caches (substitutionResultCache,
                    // referenceCache) actually hit. Constraints/defaults are re-resolved
                    // per call below (no null guard) — matching B59.5's note that the
                    // null guard regressed there.
                    val sigTypeParams = member.typeParameters?.map { tpDecl ->
                        typeParamInternCache.getOrPut(tpDecl.pos) {
                            Type.TypeParam().also { tp ->
                                tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                            }
                        }
                    }
                    val savedScope = currentTypeParamScope
                    if (!sigTypeParams.isNullOrEmpty()) {
                        val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                        sigTypeParams.forEachIndexed { i, tp ->
                            scope[member.typeParameters!![i].name.text] = tp
                        }
                        currentTypeParamScope = scope
                    }
                    val params = getParameterSymbols(member.parameters)
                    val returnType: Type
                    try {
                        sigTypeParams?.forEachIndexed { i, tp ->
                            member.typeParameters!![i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                            member.typeParameters!![i].default?.let { tp.default = getTypeFromTypeNode(it) }
                        }
                        for ((pi, param) in params.withIndex()) {
                            if (pi < member.parameters.size) {
                                member.parameters[pi].type?.let { typeNode ->
                                    symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                                }
                            }
                        }
                        returnType = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                    } finally {
                        currentTypeParamScope = savedScope
                    }
                    val sig = Signature(
                        declaration = member,
                        typeParameters = sigTypeParams,
                        parameters = params,
                        resolvedReturnType = returnType,
                        minArgumentCount = member.parameters.count {
                            !it.questionToken && !it.dotDotDotToken && it.initializer == null
                        },
                    )
                    if (name.isEmpty()) {
                        // Call signature: MethodDeclaration with empty name
                        callSignatures.add(sig)
                    } else if (name == "new") {
                        // Construct signature: MethodDeclaration with name "new"
                        constructSignatures.add(sig)
                    } else {
                        // Named method member
                        val sym = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                        sym.declarations.add(member)
                        sym.valueDeclaration = member
                        members[name] = sym
                        properties.add(sym)
                        val methodType = Type.Object()
                        methodType.callSignatures = listOf(sig)
                        methodType.properties = emptyList()
                        symbolTypes[sym.id] = methodType
                    }
                }
                is IndexSignature -> {
                    // Handled in second pass below
                }
                is Constructor -> {
                    val params = getParameterSymbols(member.parameters)
                    constructSignatures.add(Signature(
                        declaration = member,
                        parameters = params,
                        resolvedReturnType = anyType,
                        minArgumentCount = member.parameters.count {
                            !it.questionToken && !it.dotDotDotToken && it.initializer == null
                        },
                    ))
                }
                else -> continue
            }
        }
        // Second pass: collect index signatures
        var stringIndexInfo: IndexInfo? = null
        var numberIndexInfo: IndexInfo? = null
        for (member in node.members) {
            if (member is IndexSignature) {
                val indexType = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                val paramType = member.parameters.firstOrNull()?.type
                val isNumber = paramType is KeywordTypeNode && paramType.kind == SyntaxKind.NumberKeyword
                val info = IndexInfo(
                    keyType = if (isNumber) numberType else stringType,
                    type = indexType,
                    isReadonly = ModifierFlag.Readonly in member.modifiers,
                    declaration = member,
                )
                if (isNumber) numberIndexInfo = info else stringIndexInfo = info
            }
        }
        // If the literal was purely a mapped-type placeholder, return anyType —
        // enumerable members aren't known, so suppress member-level diagnostics.
        if (sawMappedTypePlaceholder && members.isEmpty() && callSignatures.isEmpty() &&
            constructSignatures.isEmpty() && stringIndexInfo == null && numberIndexInfo == null
        ) return anyType
        val objType = Type.Object()
        objType.members = members
        objType.properties = properties
        if (callSignatures.isNotEmpty()) objType.callSignatures = callSignatures
        if (constructSignatures.isNotEmpty()) objType.constructSignatures = constructSignatures
        objType.stringIndexInfo = stringIndexInfo
        objType.numberIndexInfo = numberIndexInfo
        return objType
    }

    /** Handle TypeOperator nodes (keyof, unique, readonly). */
    private fun getTypeFromTypeOperator(node: TypeOperator): Type {
        return when (node.operator) {
            SyntaxKind.KeyOfKeyword -> getKeyofType(getTypeFromTypeNode(node.type))
            SyntaxKind.UniqueKeyword -> esSymbolType // unique symbol
            SyntaxKind.ReadonlyKeyword -> {
                // `readonly T[]` shorthand: route to globalReadonlyArrayType so the
                // resulting Type.Reference exposes ReadonlyArray's read-only surface
                // (no `push`/`pop`/etc.) — pairs with the `ReadonlyArray<T>` branch in
                // `getTypeFromTypeReference`. For other shapes (e.g. `readonly [T, U]`
                // tuple) the readonly modifier is a no-op at the type level (TS only
                // surfaces it via narrower assignment rules we don't yet model).
                val inner = node.type
                if (inner is ArrayType && globalReadonlyArrayType != null) {
                    val elt = getTypeFromTypeNode(inner.elementType)
                    return getOrInternReference(globalReadonlyArrayType!!, listOf(elt))
                }
                getTypeFromTypeNode(node.type)
            }
            else -> anyType
        }
    }

    /**
     * Resolve a MappedType: { [K in C]: T }
     * Creates an object type with one property per key in the constraint C.
     * e.g., { [K in "a" | "b"]: number } → { a: number; b: number }
     * e.g., { [K in keyof T]: T[K] } → homomorphic mapped type
     */
    private fun getTypeFromMappedType(node: MappedType): Type {
        // B57.3b: depth-bail to signal excessive recursion. Mirror the alias-
        // substitution depth-bail pattern at getTypeFromTypeReference (~50362).
        // When a mapped type's value type recursively expands deeply, set the
        // deepInstantiationBailed flag so outer callers can emit TS2589.
        if (mappedTypeResolutionDepth >= MAPPED_TYPE_MAX_DEPTH) {
            deepInstantiationBailed = true
            return anyType
        }
        // Resolve the constraint type (e.g., keyof T, "a" | "b", string)
        val constraint = node.typeParameter.constraint
        if (constraint == null) return anyType
        val constraintType = try {
            getTypeFromTypeNode(constraint)
        } catch (_: StackOverflowError) { return anyType }
        if (constraintType === anyType || constraintType === errorType) return anyType
        // Collect all keys from the constraint
        val keys = when (constraintType) {
            is Type.StringLiteral -> listOf(constraintType.value)
            is Type.Union -> constraintType.types.mapNotNull { (it as? Type.StringLiteral)?.value }
            else -> return anyType // Can't enumerate keys for non-literal constraints
        }
        if (keys.isEmpty()) return anyType
        val isOutermost = mappedTypeResolutionDepth == 0
        // B57.3c: capture bail-flag transition at the outermost mapped-type call so
        // we can record TS2615 circular-property info only when the bail actually
        // originates inside this mapped type's body resolution.
        val savedBailAtEntry = deepInstantiationBailed
        mappedTypeResolutionDepth++
        try {
            // Build the mapped object type
            val result = Type.Object()
            val members = symbolTable()
            val properties = mutableListOf<Symbol>()
            val typeParamName = node.typeParameter.name.text
            for (key in keys) {
                val propType = if (node.type != null) {
                    // Temporarily bind the type parameter to the current key for evaluation
                    // This enables { [K in keyof T]: T[K] } to resolve T[K] per key
                    try {
                        getTypeFromTypeNode(node.type!!)
                    } catch (_: StackOverflowError) { anyType }
                } else anyType
                val sym = Symbol(SymbolFlags.Property, key)
                members[key] = sym
                properties.add(sym)
                symbolTypes[sym.id] = propType
            }
            result.members = members
            result.properties = properties
            // B57.3c: at the outermost mapped-type level, if the bail flag was raised
            // inside body resolution (and wasn't already set on entry), record info
            // about THIS mapped type so the alias-body consumer can emit TS2615
            // ("Type of property 'X' circularly references itself in mapped type '...'.").
            // Display: `{ [P in "K1" | "K2" | ...]: any; }` — readonly/optional modifiers
            // are not yet plumbed through; matches the simple test cases like
            // `recursivelyExpandingUnionNoStackoverflow_ts`.
            if (isOutermost && deepInstantiationBailed && !savedBailAtEntry &&
                mappedTypeCircularInfo == null) {
                val firstKey = keys.first()
                val paramName = typeParamName
                val keyDisplay = if (keys.size == 1) "\"${keys[0]}\""
                    else keys.joinToString(" | ") { "\"$it\"" }
                val display = "{ [$paramName in $keyDisplay]: any; }"
                mappedTypeCircularInfo = firstKey to display
            }
            return result
        } finally {
            mappedTypeResolutionDepth--
        }
    }

    /**
     * Resolve a ConditionalType: T extends U ? X : Y
     * - If T and U are concrete: evaluate isTypeRelatedTo(T, U) and return X or Y
     * - If T is a union: distribute — (A | B) extends U ? X : Y → (A extends U ? X : Y) | (B extends U ? X : Y)
     * - If T is an unresolved type parameter: return anyType (can't evaluate)
     */
    private fun getTypeFromConditionalType(node: ConditionalType): Type {
        val checkType = try { getTypeFromTypeNode(node.checkType) } catch (_: StackOverflowError) { return anyType }
        val extendsType = try { getTypeFromTypeNode(node.extendsType) } catch (_: StackOverflowError) { return anyType }
        if (checkType === anyType || checkType === errorType) return anyType
        if (extendsType === anyType || extendsType === errorType) return anyType
        // Unresolved type parameter — can't evaluate
        if (checkType is Type.TypeParam) return anyType
        // Distribution over unions
        if (checkType is Type.Union) {
            val results = checkType.types.map { constituent ->
                evaluateConditional(constituent, extendsType, node)
            }
            return getUnionType(results)
        }
        return evaluateConditional(checkType, extendsType, node)
    }

    private fun evaluateConditional(checkType: Type, extendsType: Type, node: ConditionalType): Type {
        // Check if checkType extends extendsType
        val related = try {
            isSimpleTypeRelatedTo(checkType, extendsType) ||
                checkTypeRelatedTo(checkType, extendsType, assignableRelation)
        } catch (_: StackOverflowError) {
            return anyType
        }
        return if (related) {
            getTypeFromTypeNode(node.trueType)
        } else {
            getTypeFromTypeNode(node.falseType)
        }
    }

    /**
     * Resolve an IndexedAccessType node: T[K] → the type of property K on T.
     * e.g., `{ a: number; b: string }["a"]` → `number`
     */
    private fun getTypeFromIndexedAccess(node: IndexedAccessType): Type {
        val objectType = getTypeFromTypeNode(node.objectType)
        val indexType = getTypeFromTypeNode(node.indexType)
        if (objectType === anyType || objectType === errorType) return anyType
        if (indexType === anyType || indexType === errorType) return anyType
        return getIndexedAccessType(objectType, indexType)
    }

    /**
     * Resolve T[K] at the type level:
     * - String literal K → look up named property
     * - Number → number index signature type
     * - Union K → union of T[each constituent]
     * - keyof T → union of all property types
     */
    private fun getIndexedAccessType(objectType: Type, indexType: Type): Type {
        // String literal key: T["prop"] → type of property "prop"
        if (indexType is Type.StringLiteral) {
            val prop = getPropertyOfType(objectType, indexType.value)
            if (prop != null) return getTypeOfSymbol(prop)
            // Check string index signature
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val strIdx = objectType.stringIndexInfo
                if (strIdx != null) return strIdx.type
            }
            return anyType
        }
        // Number literal key: T[0] → type of property "0" (tuple)
        if (indexType is Type.NumberLiteral) {
            val idx = indexType.value.toInt().toString()
            val prop = getPropertyOfType(objectType, idx)
            if (prop != null) return getTypeOfSymbol(prop)
            // Check number index signature
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val numIdx = objectType.numberIndexInfo
                if (numIdx != null) return numIdx.type
            }
            return anyType
        }
        // Number type as index: T[number] → number index signature type
        if (indexType.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLike)) {
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val numIdx = objectType.numberIndexInfo
                if (numIdx != null) return numIdx.type
                // For tuple types, return union of all element types
                val tupleTypes = objectType.tupleElementTypes
                if (tupleTypes != null && tupleTypes.isNotEmpty()) {
                    return getUnionType(tupleTypes)
                }
            }
            return anyType
        }
        // String type as index: T[string] → string index signature type
        if (indexType.flags.hasAny(TypeFlags.String or TypeFlags.StringLike)) {
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val strIdx = objectType.stringIndexInfo
                if (strIdx != null) return strIdx.type
            }
            return anyType
        }
        // Union index: T[A | B] → T[A] | T[B]
        if (indexType is Type.Union) {
            val types = indexType.types.map { getIndexedAccessType(objectType, it) }
                .filter { it !== anyType }
            if (types.isNotEmpty()) return getUnionType(types)
            return anyType
        }
        return anyType
    }

    /**
     * Get the keyof type for a type: produces a union of string literal types for each
     * property name. e.g., `keyof { a: number; b: string }` → `"a" | "b"`.
     */
    private fun getKeyofType(type: Type): Type {
        if (type === anyType || type === errorType) return stringType // keyof any = string
        if (type is Type.Object) {
            // Only use already-resolved properties to avoid triggering member resolution
            // during init (which can cause test ordering sensitivity).
            val props = type.properties
            if (props != null) {
                if (props.isEmpty()) return neverType
                val literals = props.map { Type.StringLiteral(it.name) }
                return getUnionType(literals)
            }
            // Members not yet resolved — trigger resolution
            try {
                resolveStructuredTypeMembers(type)
                val resolvedProps = type.properties
                if (resolvedProps.isNullOrEmpty()) return stringType
                val literals = resolvedProps.map { Type.StringLiteral(it.name) }
                return getUnionType(literals)
            } catch (_: StackOverflowError) {
                return stringType
            }
        }
        if (type is Type.Union) {
            // keyof (A | B) = keyof A & keyof B (intersection of keys)
            // Simplified: return string for now
            return stringType
        }
        if (type is Type.TypeParam) {
            // keyof T where T is a type parameter — return string | number | symbol
            return stringType
        }
        return stringType
    }

    // -----------------------------------------------------------------------
    // Union and Intersection type construction (basic — Phase 4 items 1b/1c)
    // -----------------------------------------------------------------------

    /** Construct a union type from a list of constituent types, with basic normalization. */
    private fun getUnionType(types: List<Type>): Type {
        if (types.isEmpty()) return neverType
        // Flatten nested unions
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Union) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // Remove never types
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Never) }
        if (filtered.isEmpty()) return neverType
        // If any constituent is any, the union is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no union needed
        if (filtered.size == 1) return filtered[0]
        // Deduplicate by type identity (by id)
        val seen = mutableSetOf<Int>()
        val deduped = filtered.filter { seen.add(it.id) }
        if (deduped.size == 1) return deduped[0]
        // Sort by TypeFlags value to match TypeScript's display order
        // TypeScript sorts: string(4) < number(8) < boolean(16) < bigint(64) < ...
        val sorted = deduped.sortedBy { it.flags.value }
        return Type.Union(sorted)
    }

    /** Construct an intersection type from a list of constituent types, with basic normalization. */
    private fun getIntersectionType(types: List<Type>): Type {
        if (types.isEmpty()) return unknownType
        // Flatten nested intersections
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Intersection) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // If any constituent is never, the intersection is never
        if (flattened.any { it.flags.hasAny(TypeFlags.Never) }) return neverType
        // Remove unknown types (unknown & X = X)
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Unknown) }
        if (filtered.isEmpty()) return unknownType
        // If any constituent is any, the intersection is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no intersection needed
        if (filtered.size == 1) return filtered[0]
        // Reduce incompatible primitive intersections to never:
        // e.g., number & boolean, string & number → never
        val primitiveFlags = TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.BigInt or TypeFlags.ESSymbol or TypeFlags.Void or TypeFlags.Null or TypeFlags.Undefined
        val primitives = filtered.filter { it.flags.hasAny(primitiveFlags) }
        if (primitives.size >= 2) {
            // Two distinct primitive types → always never
            val distinctPrimitiveKinds = primitives.map { it.flags.value and primitiveFlags.value }.toSet()
            if (distinctPrimitiveKinds.size >= 2) return neverType
        }
        // B8.1: reduce `A & B` to `never` when a property name appears in 2+
        // class constituents and is `private` in at least one. The reduction
        // reason (display string + conflicting prop name) is captured by
        // [getTypeFromTypeNodeWorker]'s IntersectionType branch (post-call)
        // so TS2322 / TS2339 emitters can append the
        // "The intersection 'A & B' was reduced to 'never' ..." chain line.
        if (findConflictingPrivateInIntersection(filtered) != null) return neverType
        return Type.Intersection(filtered)
    }

    /**
     * B8.1: find the FIRST property name that appears in 2+ constituents of
     * an intersection AND has `private` modifier in at least one declaration.
     *
     * Walks each [Type.Interface] (class) constituent's `symbol.declarations`
     * and inspects DIRECT declared members only — inherited members are
     * intentionally skipped to avoid OBJECT_PROTOTYPE_PROPERTIES noise and
     * to match TypeScript's behavior. Anonymous [Type.Object] / [Type.Reference]
     * constituents don't contribute (their members are not `private`-declared
     * in the type-system sense, only class members can be).
     *
     * Returns null when no conflict is found (caller leaves the intersection
     * intact).
     */
    private fun findConflictingPrivateInIntersection(types: List<Type>): String? {
        // (propName → list of "is this declaration private?" booleans, one per occurrence)
        val nameOccurrences = HashMap<String, MutableList<Boolean>>()
        for (t in types) {
            val iface = (t as? Type.Interface) ?: ((t as? Type.Reference)?.target) ?: continue
            val symbol = iface.symbol ?: continue
            for (decl in symbol.declarations) {
                if (decl !is ClassDeclaration) continue
                for (member in decl.members) {
                    val name = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        is GetAccessor -> (member.name as? Identifier)?.text
                        is SetAccessor -> (member.name as? Identifier)?.text
                        else -> null
                    } ?: continue
                    if (name in OBJECT_PROTOTYPE_PROPERTIES) continue
                    nameOccurrences.getOrPut(name) { mutableListOf() }.add(isMemberPrivate(member))
                }
            }
        }
        for ((name, occurrences) in nameOccurrences) {
            if (occurrences.size >= 2 && occurrences.any { it }) return name
        }
        return null
    }

    /** B8.1: chain message text for an intersection that reduced to `never` due to
     *  conflicting private members. Same text appended to TS2322 and TS2339. */
    private fun intersectionReductionChainMessage(reason: IntersectionReductionReason): String =
        "  The intersection '${reason.displayString}' was reduced to 'never' " +
            "because property '${reason.conflictingPropName}' exists in multiple " +
            "constituents and is private in some."

    /** B8.1: look up the intersection-reduction reason for an expression that resolves
     *  to `never` due to a conflicting-private intersection reduction. Walks the
     *  receiver's symbol declarations for a VariableDeclaration / Parameter /
     *  PropertyDeclaration / PropertySignature whose type annotation contains an
     *  IntersectionType registered in [CheckerState.intersectionReductionReasons].
     *  Returns null when no reduction info is recorded (callers fall through to
     *  the standard never-display path). */
    private fun findIntersectionReductionForExpr(expr: Expression): IntersectionReductionReason? {
        if (state.intersectionReductionReasons.isEmpty()) return null
        val symbol = when (expr) {
            is Identifier -> currentFileLocals?.get(expr.text) ?: globals[expr.text]
            else -> null
        } ?: return null
        for (decl in symbol.declarations) {
            val typeNode: TypeNode? = when (decl) {
                is VariableDeclaration -> decl.type
                is Parameter -> decl.type
                is PropertyDeclaration -> decl.type
                else -> null
            }
            if (typeNode != null) {
                findIntersectionReductionInTypeNode(typeNode)?.let { return it }
            }
        }
        return null
    }

    /** B8.1: walk a TypeNode looking for any IntersectionType registered in the
     *  reduction-reason cache. Returns the first match found. */
    private fun findIntersectionReductionInTypeNode(node: TypeNode): IntersectionReductionReason? {
        when (node) {
            is IntersectionType -> {
                state.intersectionReductionReasons[node]?.let { return it }
                for (t in node.types) findIntersectionReductionInTypeNode(t)?.let { return it }
            }
            is UnionType -> for (t in node.types) findIntersectionReductionInTypeNode(t)?.let { return it }
            is ParenthesizedType -> return findIntersectionReductionInTypeNode(node.type)
            is ArrayType -> return findIntersectionReductionInTypeNode(node.elementType)
            else -> {}
        }
        return null
    }

    // -----------------------------------------------------------------------
    // String-based type resolution (legacy — to be replaced by Type-based)
    // -----------------------------------------------------------------------

    /** Resolve a type annotation to a type name string. Returns null for complex types we can't handle.
     *  Named types (from TypeReference) are prefixed with "@" to distinguish from keyword types. */
    private fun resolveSimpleTypeName(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // Format as Name<Arg1, Arg2> for display in TS2322 messages
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "@$baseName<${argNames.joinToString(", ")}>"
                } else {
                    // Simple type reference — prefix with "@" to mark as named type
                    "@$baseName"
                }
            }
            is UnionType -> {
                // Format as "type1 | type2 | ..." for display
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                // Use "|" prefix to mark as union type for assignability checking
                "|${memberTypes.joinToString(" | ")}"
            }
            is TypePredicate -> "boolean" // Type predicates return boolean
            else -> null
        }
    }

    /** Get the last identifier name from a TypeReference typeName (Identifier or QualifiedName). */
    private fun getTypeReferenceLastName(node: Node): String? {
        return when (node) {
            is Identifier -> node.text
            is QualifiedName -> node.right.text
            else -> null
        }
    }

    /** 17.238: Format full dotted name `a.b.c` for QualifiedName. */
    private fun formatTypeReferenceName(node: Node): String? {
        return when (node) {
            is Identifier -> node.text
            is QualifiedName -> {
                val l = formatTypeReferenceName(node.left) ?: return null
                "$l.${node.right.text}"
            }
            else -> null
        }
    }

    /** Resolve a TypeReference typeName (Identifier or QualifiedName) to a Symbol. */
    private fun resolveTypeNameToSymbol(node: Node): Symbol? {
        return when (node) {
            is Identifier -> globals[node.text]
            is QualifiedName -> resolveQualifiedName(node)
            else -> null
        }
    }

    /**
     * Format a TypeNode for display in TS2322 messages (no "@" prefix).
     * Returns null for unsupported types (caller falls back to typeToString).
     */
    /** 17.10c: Format a TypeParameter AST node as `name` or `name extends Constraint`. */
    private fun tpDeclToDisplay(tp: TypeParameter): String {
        val name = tp.name.text
        val cons = tp.constraint?.let { formatTypeForDisplay(it) }
        return if (cons != null) "$name extends $cons" else name
    }

    /**
     * Format a Parameter AST node for display in function/constructor type strings.
     * Honors `?` (optional → `name?: type | undefined` for non-fn types, `name?: type`
     * for fn/ctor types) and `...` (rest → `...name: type`).
     * Mirrors [formatParameter] (which operates on Symbol) but works directly on the AST.
     *
     * 17.15a: Drop `| undefined` when the param type is itself a `FunctionType` or
     * `ConstructorType`. The form `name?: T => U | undefined` would parse as a function
     * returning `U | undefined` (`=>` binds tighter than `|`). TypeScript's display
     * convention is to drop `| undefined` for fn-type params to avoid this ambiguity.
     */
    private fun formatParameterDecl(p: Parameter): String {
        val pName = (p.name as? Identifier)?.text ?: "_"
        val pType = p.type?.let { formatTypeForDisplay(it) } ?: "any"
        // B51.6: TypeScript displays params with default values as optional
        // (`a?: T`) in type positions — the default makes the param effectively
        // optional from a caller's perspective. Mirrors the display in
        // `defaultValueInFunctionTypes_ts`'s `(a?: string) => any` baseline.
        val hasInitializer = p.initializer != null
        return when {
            p.dotDotDotToken -> "...$pName: $pType"
            p.questionToken -> {
                val isFnType = p.type is FunctionType || p.type is ConstructorType
                if (isFnType) "$pName?: $pType" else "$pName?: $pType | undefined"
            }
            hasInitializer -> "$pName?: $pType"
            else -> "$pName: $pType"
        }
    }

    /**
     * Returns true if [typeNode] renders via formatTypeForDisplay as a function or constructor
     * type shorthand (`(x: T) => U` or `new (x: T) => U`). Used to decide when parens are
     * needed in array element or union member positions. Unwraps ParenthesizedType.
     */
    private fun typeNodeRendersAsFunctionLike(typeNode: TypeNode): Boolean {
        var t: TypeNode = typeNode
        while (t is ParenthesizedType) t = t.type
        return when (t) {
            is FunctionType, is ConstructorType -> true
            is TypeLiteral -> {
                // Single call/construct signature → renders as shorthand
                if (t.members.size == 1) {
                    val only = t.members[0]
                    only is MethodDeclaration && (only.name is Identifier &&
                        (only.name.text == "" || only.name.text == "new"))
                } else false
            }
            else -> false
        }
    }

    /**
     * B86.7a (additive helper, no callers yet): strip outer `null` / `undefined`
     * constituents from a `Type.Union` target when the source is non-nullable. Used
     * downstream to render `A | B` instead of `A | B | null | undefined` in TS2322
     * diagnostics where the actual incompatibility is between the non-nullish
     * shapes. Returns [targetType] unchanged when:
     *   - target is not a Type.Union,
     *   - source is itself nullable (both nullable: keep null in display),
     *   - target has no nullish constituents to strip,
     *   - stripping would leave nothing behind (safety).
     */
    private fun stripNullishFromDisplayTarget(targetType: Type, sourceType: Type): Type {
        if (targetType !is Type.Union) return targetType
        if (typeIsPossiblyNullish(sourceType)) return targetType
        val nonNullish = targetType.types.filter { it !== nullType && it !== undefinedType }
        if (nonNullish.size == targetType.types.size) return targetType
        if (nonNullish.isEmpty()) return targetType
        return if (nonNullish.size == 1) nonNullish[0] else getUnionType(nonNullish)
    }

    private fun formatTypeForDisplay(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // TypeScript normalizes Array<T> → T[] and ReadonlyArray<T> → readonly T[]
                    // in error messages. B50.8: preserve the `readonly` prefix for
                    // ReadonlyArray to match TypeScript's display convention.
                    if ((baseName == "Array" || baseName == "ReadonlyArray") && typeArgs.size == 1) {
                        val elementDisplay = formatTypeForDisplay(typeArgs[0]) ?: return null
                        // Parens for function/constructor-like element types
                        val needsParens = typeArgs[0] !is ParenthesizedType &&
                            typeNodeRendersAsFunctionLike(typeArgs[0])
                        val arr = if (needsParens) "(${elementDisplay})[]" else "${elementDisplay}[]"
                        return if (baseName == "ReadonlyArray") "readonly $arr" else arr
                    }
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "$baseName<${argNames.joinToString(", ")}>"
                } else {
                    // 16.4fi: for TypeAliases with circular-default type params, fill in
                    // `<any, any, ...>` for bare references — matches TypeScript's
                    // substitution-on-invalid-default display.
                    val tnName = typeNode.typeName
                    val sym = if (tnName is Identifier) currentFileLocals?.get(tnName.text) ?: globals[tnName.text]
                        else null
                    val n = sym?.let { circularDefaultTypeParamCount[it.id] }
                    if (n != null && n > 0) {
                        "$baseName<${List(n) { "any" }.joinToString(", ")}>"
                    } else {
                        // B70.1: when the TypeReference resolves to a non-generic TypeAlias
                        // whose body evaluates to a singleton literal type (NumberLiteral /
                        // StringLiteral / BigIntLiteral), TypeScript displays the resolved
                        // literal in TS2322 messages instead of the alias name. Example:
                        // `type U = [any] extends [number] ? 1 : 0;` → display `'1'`, not `'U'`.
                        // Conservative gate: only literal singletons; object-shape aliases
                        // keep the alias name (more readable + matches TS for those).
                        if (sym != null && sym.flags.hasAny(SymbolFlags.TypeAlias)) {
                            val decl = sym.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                            if (decl != null && decl.typeParameters.isNullOrEmpty()) {
                                try {
                                    val resolved = getDeclaredTypeOfSymbol(sym)
                                    when (resolved) {
                                        is Type.NumberLiteral -> return resolved.toString()
                                        is Type.StringLiteral -> return "\"${resolved.value}\""
                                        is Type.BigIntLiteral -> return resolved.toString()
                                        else -> {}
                                    }
                                } catch (_: Throwable) { /* fall through */ }
                            }
                        }
                        baseName
                    }
                }
            }
            is ArrayType -> {
                // Function/constructor types must be parenthesized as Array elements:
                // `(new () => T)[]` not `new () => T[]` (the latter parses as `new () => (T[])`).
                // Don't add a second set of parens if the source already wraps in ParenthesizedType
                // (formatTypeForDisplay for ParenthesizedType already emits `(...)`).
                val elementType = formatTypeForDisplay(typeNode.elementType) ?: return null
                if (typeNode.elementType !is ParenthesizedType &&
                    typeNodeRendersAsFunctionLike(typeNode.elementType)) "($elementType)[]"
                else "$elementType[]"
            }
            is UnionType -> {
                // Function/constructor types in unions need parens: `number | (new () => T)`.
                val memberStrs = typeNode.types.map { m ->
                    val s = formatTypeForDisplay(m) ?: return null
                    if (typeNodeRendersAsFunctionLike(m)) "($s)" else s
                }
                memberStrs.joinToString(" | ")
            }
            is IntersectionType -> {
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                memberTypes.joinToString(" & ")
            }
            is FunctionType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { formatParameterDecl(it) }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "$tpStr($params) => $retType"
            }
            is ConstructorType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { formatParameterDecl(it) }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "new $tpStr($params) => $retType"
            }
            is ParenthesizedType -> {
                val inner = formatTypeForDisplay(typeNode.type) ?: return null
                "($inner)"
            }
            is TupleType -> {
                val elements = typeNode.elements.map { formatTypeForDisplay(it) }
                if (elements.any { it == null }) return null
                "[${elements.joinToString(", ")}]"
            }
            is TypeLiteral -> {
                // Single call/construct signature: display as arrow form
                // `{(): T}` → `() => T` and `{new(): T}` → `new () => T`
                if (typeNode.members.size == 1) {
                    val only = typeNode.members[0]
                    if (only is MethodDeclaration) {
                        val name = (only.name as? Identifier)?.text
                        if (name == "" || name == "new") {
                            // 17.10b: Include type parameters from the call/construct sig
                            // so `{<T>(x:T): T}` displays as `<T>(x: T) => T` not `(x: T) => T`.
                            val sigTps = only.typeParameters ?: emptyList()
                            val tpStr = if (sigTps.isNotEmpty()) "<${sigTps.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                            val params = only.parameters.joinToString(", ") { formatParameterDecl(it) }
                            val retType = only.type?.let { formatTypeForDisplay(it) } ?: "any"
                            val prefix = if (name == "new") "new " else ""
                            return "$prefix$tpStr($params) => $retType"
                        }
                    }
                }
                val parts = mutableListOf<String>()
                for (member in typeNode.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            val propName = (member.name as? Identifier)?.text ?: continue
                            val propType = member.type?.let { formatTypeForDisplay(it) } ?: "any"
                            if (member.questionToken) {
                                // Optional properties display as `name?: type | undefined`
                                parts.add("$propName?: $propType | undefined")
                            } else {
                                parts.add("$propName: $propType")
                            }
                        }
                        is IndexSignature -> {
                            val param = member.parameters.firstOrNull()
                            val paramName = (param?.name as? Identifier)?.text ?: "key"
                            val paramType = param?.type?.let { formatTypeForDisplay(it) } ?: "string"
                            val valueType = member.type?.let { formatTypeForDisplay(it) } ?: continue
                            parts.add("[$paramName: $paramType]: $valueType")
                        }
                        is MethodDeclaration -> {
                            val methodName = (member.name as? Identifier)?.text ?: continue
                            val params = member.parameters.joinToString(", ") { formatParameterDecl(it) }
                            val retType = member.type?.let { formatTypeForDisplay(it) } ?: "any"
                            // 17.215: include `?` for optional method declarations
                            // (e.g. `k?(a: any): any` in `interface { k?(a: any): any }`).
                            val opt = if (member.questionToken) "?" else ""
                            parts.add("$methodName$opt($params): $retType")
                        }
                        else -> return null // unsupported member type
                    }
                }
                "{ ${parts.joinToString("; ")}; }"
            }
            is TypeQuery -> {
                val name = when (val expr = typeNode.exprName) {
                    is Identifier -> expr.text
                    is QualifiedName -> {
                        // Build "A.B.C" from nested QualifiedName
                        fun fmt(n: Node): String? = when (n) {
                            is Identifier -> n.text
                            is QualifiedName -> {
                                val l = fmt(n.left) ?: return null
                                "$l.${n.right.text}"
                            }
                            else -> null
                        }
                        fmt(expr) ?: return null
                    }
                    else -> return null
                }
                "typeof $name"
            }
            is TypePredicate -> {
                val paramName = when (val pn = typeNode.parameterName) {
                    is Identifier -> pn.text
                    // Parser quirk: `c is C1` parses `c` as TypeReference. See narrowByCallPredicate.
                    is TypeReference -> (pn.typeName as? Identifier)?.text
                    is ThisType -> "this"
                    else -> null
                } ?: return null
                val asserts = if (typeNode.assertsModifier) "asserts " else ""
                val tPart = typeNode.type
                if (tPart == null) {
                    "$asserts$paramName"
                } else {
                    val typePart = formatTypeForDisplay(tPart) ?: return null
                    "$asserts$paramName is $typePart"
                }
            }
            is LiteralType -> when (val lit = typeNode.literal) {
                is NumericLiteralNode -> lit.text
                is StringLiteralNode -> "\"${lit.text}\""
                is NoSubstitutionTemplateLiteralNode -> "\"${lit.text}\""
                is Identifier -> when (lit.text) {
                    "true", "false", "null", "undefined" -> lit.text
                    else -> null
                }
                is PrefixUnaryExpression -> if (lit.operand is NumericLiteralNode && lit.operator == SyntaxKind.Minus) {
                    "-${(lit.operand as NumericLiteralNode).text}"
                } else null
                else -> null
            }
            else -> null
        }
    }

    /** Infer the type of a simple expression. Returns null for complex expressions. */
    private fun inferSimpleExprType(expr: Expression, varTypes: Map<String, String>): String? {
        return when (expr) {
            is NumericLiteralNode -> "number"
            is StringLiteralNode -> "string"
            is NoSubstitutionTemplateLiteralNode -> "string"
            is TemplateExpression -> "string"
            is RegularExpressionLiteralNode -> "object" // RegExp
            is Identifier -> when (expr.text) {
                "undefined" -> "undefined"
                "null" -> "null"
                "true", "false" -> "boolean"
                "NaN", "Infinity" -> "number"
                else -> null // Don't look up variable types — causes FPs with enum/union targets
            }
            is TypeOfExpression -> "string" // typeof always returns string
            is VoidExpression -> "undefined"
            is DeleteExpression -> "boolean"
            is BigIntLiteralNode -> "bigint"
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.Exclamation -> "boolean" // !x is boolean
                SyntaxKind.Minus, SyntaxKind.Plus, SyntaxKind.Tilde -> "number"
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> "number"
                else -> null
            }
            is PostfixUnaryExpression -> "number" // x++ / x-- always produce number
            is ParenthesizedExpression -> inferSimpleExprType(expr.expression, varTypes)
            is NonNullExpression -> inferSimpleExprType(expr.expression, varTypes)
            is SatisfiesExpression -> inferSimpleExprType(expr.expression, varTypes)
            is AsExpression -> {
                // Type assertion: return the asserted type, not the inner expression type
                val assertedType = resolveSimpleTypeName(expr.type)
                if (assertedType != null) assertedType
                else inferSimpleExprType(expr.expression, varTypes)
            }
            is TypeAssertionExpression -> {
                // `<T>expr` legacy assertion form — mirrors AsExpression
                val assertedType = resolveSimpleTypeName(expr.type)
                if (assertedType != null) assertedType
                else inferSimpleExprType(expr.expression, varTypes)
            }
            is ArrayLiteralExpression -> "array" // Used internally for assignability
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals -> inferSimpleExprType(expr.right, varTypes)
                else -> null
            }
            else -> null
        }
    }

    /** Check if an expression is a simple literal (no elaboration needed in TS2322 chain). */
    private fun isSimpleLiteral(expr: Expression): Boolean {
        return when (expr) {
            is NumericLiteralNode -> true
            is StringLiteralNode -> true
            is NoSubstitutionTemplateLiteralNode -> true
            is BigIntLiteralNode -> true
            is Identifier -> true // All identifiers are "simple" (no elaboration chain)
            is ParenthesizedExpression -> isSimpleLiteral(expr.expression)
            is NonNullExpression -> isSimpleLiteral(expr.expression)
            is SatisfiesExpression -> isSimpleLiteral(expr.expression)
            is AsExpression -> isSimpleLiteral(expr.expression)
            is TypeAssertionExpression -> isSimpleLiteral(expr.expression)
            is PrefixUnaryExpression -> expr.operand is NumericLiteralNode || expr.operand is BigIntLiteralNode
            is BinaryExpression -> expr.operator == SyntaxKind.Equals && isSimpleLiteral(expr.right)
            else -> false
        }
    }

    /** Check if sourceType is assignable to targetType.
     *  Named types (from TypeReference) are prefixed with "@".
     *  Union types are prefixed with "|". */
    private fun isAssignableTo(sourceType: String, targetType: String, typeParams: Set<String> = emptySet()): Boolean {
        if (sourceType == targetType) return true
        if (targetType == "any" || targetType == "unknown") return true
        if (sourceType == "any") return true
        // undefined is assignable to void
        if (sourceType == "undefined" && targetType == "void") return true
        // When strict null checks are off, null and undefined are assignable to everything
        if (!strictNullChecks && (sourceType == "null" || sourceType == "undefined")) return true
        // Union types: source is assignable to union if it matches any member
        if (targetType.startsWith("|")) {
            val members = targetType.removePrefix("|").split(" | ")
            // null/undefined are only assignable to union if a member is null/undefined/void
            if (sourceType == "null" || sourceType == "undefined") {
                return members.any { it == sourceType || it == "any" || it == "unknown" || (sourceType == "undefined" && it == "void") }
            }
            // For other source types, assignable if it matches any member
            return members.any { isAssignableTo(sourceType, it) }
        }
        // For named types (TypeReference, prefixed with "@"), we can only confidently say
        // that null/undefined are NOT assignable. Other source types might actually be
        // assignable via structural typing, type aliases, etc.
        if (targetType.startsWith("@")) {
            // B54.3: when source and target are both same-base-name parameterized types
            // (`@A<string>` vs `@A<number>`), compare type args directly. Different args
            // for the same base interface are NOT assignable. Narrowed by B54.9 to ONLY
            // fire when at least one of the args is a primitive type name (string, number,
            // boolean, etc.) — for named-type args (interfaces like X, Y, Foo, Bar), we
            // can't determine structural compatibility from the varTypes strings, and
            // `class C<T>` is structurally compatible for structurally-identical X/Y per
            // generics3_ts. Excludes TypeParam-only cases (`A<T>` vs `A<U>`) too unless
            // ONE side is a concrete primitive (per typeParameterAssignmentCompat1 vs
            // generics3 distinction).
            if (sourceType.startsWith("@") && sourceType != targetType) {
                // B60.6: bare TypeParam vs bare TypeParam (distinct names, no type
                // args on either side). Treat as nominally distinct per strict-
                // generic-checks semantics — `function ff<T, U>(x: T, y: U) { x = y; }`
                // fires TS2322 for `x = y` because T and U could be instantiated
                // with unrelated types. Mirrors B55.1's same-base-with-different-
                // TypeParam-args logic for the bare case.
                if (!sourceType.contains('<') && !targetType.contains('<')) {
                    val srcName = sourceType.removePrefix("@")
                    val tgtName = targetType.removePrefix("@")
                    if (srcName != tgtName && srcName in typeParams && tgtName in typeParams) {
                        // B60.6e: SKIP when src directly extends tgt (e.g. `B extends A`,
                        // then B is assignable to A). Walk source's constraint chain looking
                        // for tgt.
                        val srcDecl = currentTypeParamDecls[srcName]
                        var cur: TypeParameter? = srcDecl
                        var foundSubtype = false
                        var depth = 0
                        while (cur != null && depth++ < 8) {
                            val cnstr = cur.constraint
                            if (cnstr is TypeReference) {
                                val cnstrName = (cnstr.typeName as? Identifier)?.text
                                if (cnstrName == tgtName) { foundSubtype = true; break }
                                cur = if (cnstrName != null) currentTypeParamDecls[cnstrName] else null
                            } else break
                        }
                        if (!foundSubtype) return false
                    }
                    // B60.7: bare TypeParam source → named non-TypeParam target.
                    // Source must be UNCONSTRAINED (no `extends`). With unconstrained T,
                    // the apparent type is {} — not assignable to a named interface.
                    // With `T extends X`, source IS assignable (apparent type is X) —
                    // skip the gate (only fires for unconstrained or self-circular).
                    if (srcName != tgtName && srcName in typeParams && tgtName !in typeParams) {
                        val srcDecl = currentTypeParamDecls[srcName]
                        val isCircular = (srcDecl?.constraint as? TypeReference)?.let {
                            (it.typeName as? Identifier)?.text == srcName
                        } == true
                        val effectivelyUnconstrained = srcDecl?.constraint == null || isCircular
                        if (effectivelyUnconstrained) {
                            // B60.7c (broadened): allow ALL named targets, not just
                            // Object/Function. TypeScript flags unconstrained T → any
                            // specific named interface. Skip primitive-keyword names
                            // (those are handled elsewhere — `number`, etc. don't start
                            // with `@` here so won't be picked up by this branch anyway).
                            return false
                        }
                    }
                }
                val srcBase = sourceType.substringBefore('<')
                val tgtBase = targetType.substringBefore('<')
                if (srcBase == tgtBase && sourceType.contains('<') && targetType.contains('<')) {
                    val srcArgRaw = sourceType.substringAfter('<').removeSuffix(">")
                    val tgtArgRaw = targetType.substringAfter('<').removeSuffix(">")
                    val srcArg = srcArgRaw.removePrefix("@")
                    val tgtArg = tgtArgRaw.removePrefix("@")
                    val primitives = setOf("string", "number", "boolean", "bigint", "symbol",
                        "void", "null", "undefined", "any", "unknown", "never")
                    val srcIsPrim = srcArg in primitives
                    val tgtIsPrim = tgtArg in primitives
                    // B54.9 gate (post-regression-narrowing): fire when at least one arg is
                    // a primitive type (definitively different from any non-primitive). For
                    // named-type-vs-named-type args (X, Y, Foo, Bar), we can't determine
                    // structural compatibility from the string form, so we defer to the
                    // safe default (return true at the bottom). Excludes:
                    //   - generics3_ts `C<X>` vs `C<Y>` (both X, Y are named types — structurally identical)
                    //   - promisesWithConstraints_ts `Promise<Foo>` vs `Promise<Bar>` (covariance)
                    // Includes:
                    //   - getAndSetNotIdenticalType3_ts `A<string>` vs `A<number>` (primitives)
                    //   - getAndSetNotIdenticalType2_ts `A<string>` vs `A<T>` (TypeParam vs primitive)
                    if (srcIsPrim || tgtIsPrim) return false
                    // B55.1 (probe): both args are different TypeParams in the current scope —
                    // treat as nominally distinct per strict-generic-checks semantics.
                    // typeParameterAssignmentCompat1_ts wants TS2322 for `Foo<T>` vs `Foo<U>`.
                    if (srcArg != tgtArg && srcArg in typeParams && tgtArg in typeParams) return false
                }
            }
            // null and undefined are never assignable to named types (with strict null checks)
            return sourceType != "null" && sourceType != "undefined"
        }
        if (sourceType.startsWith("@") || sourceType.startsWith("|")) {
            // Named/union source type vs keyword target — can't determine without full resolution
            return true // safe default: assume assignable to avoid FPs
        }
        // null is assignable to any/unknown (already handled above) but NOT void or other types
        // number literal subtypes
        if (sourceType == "number" && targetType == "object") return false
        if (sourceType == "string" && targetType == "object") return false
        // Otherwise, different primitive types are not assignable
        return false
    }

    /** B57.3c: emit TS2615 "Type of property 'X' circularly references itself in mapped
     *  type '...'." at the same span as the paired TS2589, using the captured
     *  [mappedTypeCircularInfo]. Span computed identically to [emitTs2589AtTypeNode]. */
    private fun emitTs2615AtTypeNode(node: TypeNode, propertyName: String, mappedTypeDisplay: String, source: String, fileName: String) {
        val startPos = node.pos
        if (startPos < 0 || startPos >= source.length) return
        var endPos = node.end.coerceAtMost(source.length)
        while (endPos > startPos) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ']') break
            if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' ||
                ch == ';' || ch == ',' || ch == ')' || ch == '=') endPos--
            else break
        }
        val length = (endPos - startPos).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
        diagnostics.add(Diagnostic(
            message = "Type of property '$propertyName' circularly references itself in mapped type '$mappedTypeDisplay'.",
            category = DiagnosticCategory.Error,
            code = 2615,
            fileName = fileName,
            line = line,
            character = character,
            start = startPos,
            length = length,
        ))
    }

    /** B57.3d (a): record a `new C<...>(...)` whose explicit-type-arg resolution
     *  triggered [deepInstantiationBailed]. Span covers the full `new` expression
     *  (matches TypeScript baselines like `circularInlineMappedGenericTupleTypeNoCrash`).
     *  Dedup by (fileName, pos). */
    private fun recordDeepBailNewExpression(expr: NewExpression) {
        recordDeepBailExpression(expr)
    }

    /** B57.3d (b): record any Expression whose explicit-type-arg resolution
     *  triggered [deepInstantiationBailed]. Generalizes [recordDeepBailNewExpression]
     *  so the same dedup+deferred-emit infrastructure is shared by NewExpression
     *  and CallExpression call sites (both have `typeArguments`). */
    private fun recordDeepBailExpression(expr: Expression) {
        val fileName = currentCheckFileName ?: return
        val start = expr.pos
        if (start < 0) return
        val key = "$fileName|$start"
        if (!deepBailNewExprPositions.add(key)) return
        val end = expressionTrueEnd(expr)
        val length = (end - start).coerceAtLeast(1)
        deepBailNewExprEmits.add(Triple(fileName, start, length))
    }

    /** B57.3d (a): flush queued TS2589 emissions into [diagnostics]. */
    private fun flushDeepBailNewExpressionEmits() {
        if (deepBailNewExprEmits.isEmpty()) return
        for ((fileName, start, length) in deepBailNewExprEmits) {
            val source = binderResults.find { it.sourceFile.fileName == fileName }?.sourceFile?.text
                ?: continue
            if (start >= source.length) continue
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type instantiation is excessively deep and possibly infinite.",
                category = DiagnosticCategory.Error,
                code = 2589,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
        deepBailNewExprEmits.clear()
        deepBailNewExprPositions.clear()
    }

    /** B57.1: emit TS2589 "Type instantiation is excessively deep" at a TypeNode's span.
     *  For a TypeReferenceNode like `Foo<"true", {}>`, spans from the name's position to
     *  the position right after the closing `>`. node.end overshoots (includes the next
     *  token's scan), so we trim trailing whitespace/punctuation back to find the real end. */
    private fun emitTs2589AtTypeNode(node: TypeNode, source: String, fileName: String) {
        val startPos = node.pos
        if (startPos < 0 || startPos >= source.length) return
        var endPos = node.end.coerceAtMost(source.length)
        // Trim back past trailing whitespace / `;` / `,` / `)` etc. to land at `>`.
        while (endPos > startPos) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ']') break
            if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' ||
                ch == ';' || ch == ',' || ch == ')' || ch == '=') endPos--
            else break
        }
        val length = (endPos - startPos).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
        diagnostics.add(Diagnostic(
            message = "Type instantiation is excessively deep and possibly infinite.",
            category = DiagnosticCategory.Error,
            code = 2589,
            fileName = fileName,
            line = line,
            character = character,
            start = startPos,
            length = length,
        ))
    }

    private fun emitTS2322(start: Int, length: Int, sourceType: String, targetType: String, source: String, fileName: String, hasElaboration: Boolean = false, typeParams: Set<String> = emptySet()) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Strip "@"/"@" prefix from named/union types for display
        val displaySource = sourceType.removePrefix("@").removePrefix("|")
        val displayTarget = targetType.removePrefix("@").removePrefix("|")
        val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
        // Check if target type is a type parameter — add elaboration chain
        val chain = mutableListOf<String>()
        if (hasElaboration) chain.add("  $message")
        if (targetType.startsWith("@")) {
            val targetBaseName = displayTarget.substringBefore('<')
            if (targetBaseName in typeParams) {
                // B60.6c: when target is a bare TypeParam with a constraint AND source
                // is bare TypeParam with the SAME constraint (display-equal), use the
                // "constraint-assignable" chain form. Matches B60.2's logic for the
                // Type-engine path. Pure-string heuristic: pull each TypeParam's
                // constraint text from currentTypeParamDecls and compare displays.
                val tgtDecl = currentTypeParamDecls[targetBaseName]
                val srcBareName = if (sourceType.startsWith("@") && !sourceType.contains('<'))
                    sourceType.removePrefix("@") else null
                val srcDecl = srcBareName?.let { currentTypeParamDecls[it] }
                val tgtCnstr = tgtDecl?.constraint
                val srcCnstr = srcDecl?.constraint
                val constraintMatch = tgtCnstr != null && srcCnstr != null &&
                    formatTypeForDisplay(tgtCnstr) == formatTypeForDisplay(srcCnstr)
                if (constraintMatch) {
                    val constraintDisplay = formatTypeForDisplay(tgtCnstr!!) ?: "any"
                    chain.add("  '$displaySource' is assignable to the constraint of type '$targetBaseName', but '$targetBaseName' could be instantiated with a different subtype of constraint '$constraintDisplay'.")
                    // B60.6d: source is the lib `Object` type → add the special hint
                    // "The 'Object' type is assignable to very few other types. Did you
                    // mean to use the 'any' type instead?"
                    if (displaySource == "Object") {
                        chain.add("    The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?")
                    }
                } else {
                    chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                }
            }
        }
        // B54.4: same-base same-name generic ref mismatch — add leaf chain entry comparing
        // diverging type args. For `@A<string>` vs `@A<number>`, emit
        // "  Type 'string' is not assignable to type 'number'." Pairs with B54.3's gate.
        if (sourceType.startsWith("@") && targetType.startsWith("@") &&
            sourceType.contains('<') && targetType.contains('<')) {
            val srcBase = sourceType.substringBefore('<')
            val tgtBase = targetType.substringBefore('<')
            if (srcBase == tgtBase) {
                val srcArg = sourceType.substringAfter('<').removeSuffix(">").removePrefix("@")
                val tgtArg = targetType.substringAfter('<').removeSuffix(">").removePrefix("@")
                if (srcArg != tgtArg && !srcArg.contains(',') && !tgtArg.contains(',')) {
                    chain.add("  Type '$srcArg' is not assignable to type '$tgtArg'.")
                    // B54.8 (re-enable, narrower gate): when target type arg is a TypeParam
                    // in scope, add "'X' could be instantiated with an arbitrary type which
                    // could be unrelated to 'Y'." matching TypeScript's behavior for
                    // generic-ref-assignment mismatches into a TypeParam-parameterized
                    // target. Gate on tgtArg in typeParams (don't require srcArg to be one).
                    if (tgtArg in typeParams) {
                        chain.add("    '$tgtArg' could be instantiated with an arbitrary type which could be unrelated to '$srcArg'.")
                    }
                }
            }
        }
        // B55.2: TS2208 related info "This type parameter might need an `extends X` constraint."
        // Fires when same-base ref mismatch with both args as different TypeParams in scope.
        // Points to the source TypeParam's declaration (the one that "needs the constraint").
        val relatedInfo = mutableListOf<Diagnostic>()
        if (sourceType.startsWith("@") && targetType.startsWith("@") &&
            sourceType.contains('<') && targetType.contains('<')
        ) {
            val srcBase = sourceType.substringBefore('<')
            val tgtBase = targetType.substringBefore('<')
            if (srcBase == tgtBase) {
                val srcArg = sourceType.substringAfter('<').removeSuffix(">").removePrefix("@")
                val tgtArg = targetType.substringAfter('<').removeSuffix(">").removePrefix("@")
                if (srcArg != tgtArg && srcArg in typeParams && tgtArg in typeParams) {
                    // Source TypeParam needs `extends <Target>` constraint.
                    val srcTpDecl = currentTypeParamDecls[srcArg]
                    if (srcTpDecl != null) {
                        val decPos = srcTpDecl.name.pos
                        val decLen = srcTpDecl.name.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                        relatedInfo.add(Diagnostic(
                            message = "This type parameter might need an `extends $tgtArg` constraint.",
                            category = DiagnosticCategory.Message,
                            code = 2208,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = decPos,
                            length = decLen,
                        ))
                    }
                }
            }
        }
        // B60.6f: TS2208 for bare TypeParam mismatch — either both bare TypeParams
        // (`U → T`), or bare TypeParam source → named target (`T → Object`), or
        // bare TypeParam source → primitive target (`T → number`). Points to
        // source's declaration with the suggested `extends <target>` constraint.
        // Gate: source TypeParam must be UNCONSTRAINED (no existing extends clause,
        // OR has a self-circular constraint which is effectively unconstrained).
        val tgtIsPrimitiveName = targetType in setOf("number", "string", "boolean", "bigint", "symbol", "object", "void")
        val tgtAcceptable = (targetType.startsWith("@") && !targetType.contains('<')) || tgtIsPrimitiveName
        if (sourceType.startsWith("@") && !sourceType.contains('<') && tgtAcceptable
        ) {
            val srcName = sourceType.removePrefix("@")
            val tgtName = targetType.removePrefix("@")
            if (srcName != tgtName && srcName in typeParams) {
                val srcTpDecl = currentTypeParamDecls[srcName]
                // B60.10b: treat self-circular constraint (e.g. `T extends T`) as
                // effectively unconstrained — TypeScript also suggests a constraint
                // here despite the syntactic constraint existing.
                fun isEffectivelyUnconstrained(tp: TypeParameter?): Boolean {
                    if (tp == null) return false
                    if (tp.constraint == null) return true
                    val cnstr = tp.constraint as? TypeReference ?: return false
                    val cnstrName = (cnstr.typeName as? Identifier)?.text ?: return false
                    return cnstrName == tp.name.text
                }
                if (srcTpDecl != null && isEffectivelyUnconstrained(srcTpDecl)) {
                    val decPos = srcTpDecl.name.pos
                    val decLen = srcTpDecl.name.text.length
                    val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                    relatedInfo.add(Diagnostic(
                        message = "This type parameter might need an `extends $tgtName` constraint.",
                        category = DiagnosticCategory.Message,
                        code = 2208,
                        fileName = fileName,
                        line = relLine,
                        character = relChar,
                        start = decPos,
                        length = decLen,
                    ))
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = 2322,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = chain,
            relatedInformation = if (relatedInfo.isEmpty()) emptyList() else relatedInfo.toList(),
        ))
    }

    /**
     * For TS2741 "required in type 'X'", when the missing property is inherited,
     * TypeScript displays the DECLARING class/interface name (where the property
     * was actually declared), not the annotation target type. E.g. `c2 = c` where
     * `c2: C2 extends A` and `x` comes from A → "required in type 'A'", not 'C2'.
     *
     * Conservative: only override when the property symbol has a parent symbol
     * whose name differs from the target type's symbol — indicating an inherited
     * property. Keeps the annotation display for directly-declared properties.
     */
    private fun getDeclaringTypeDisplay(
        propSymbol: Symbol?,
        targetType: Type,
        fallback: String,
    ): String {
        val parent = propSymbol?.parent ?: return fallback
        val parentName = parent.name
        if (parentName.isEmpty()) return fallback
        val targetSym = when (targetType) {
            is Type.Reference -> targetType.target.symbol
            is Type.Object -> targetType.symbol
            else -> null
        } ?: return fallback
        if (targetSym === parent) return fallback
        // 17.213: TypeScript's TS2741 message uses the displayed target type
        // name for PUBLIC inherited properties (interfaces extending interfaces,
        // classes extending other classes via public members). It uses the
        // DECLARING class name only when the missing property is private or
        // protected — those modifiers tie the property nominally to its
        // declaring class. So for `var x: B = {}` with `interface A { x: string }
        // interface B extends A {}`, the message is "...required in type 'B'"
        // (uses target). For `c2 = c` with `class A { private x = 1 } class C2
        // extends A {}`, the message is "...required in type 'A'" (uses
        // declaring class because `x` is private).
        val isPrivateOrProtected = propSymbol.declarations.any { decl ->
            val mods = when (decl) {
                is PropertyDeclaration -> decl.modifiers
                is MethodDeclaration -> decl.modifiers
                else -> emptySet()
            }
            ModifierFlag.Private in mods || ModifierFlag.Protected in mods
        }
        return if (isPrivateOrProtected) parentName else fallback
    }

    /**
     * Create TS2728 related diagnostic ("'name' is declared here.") for a property symbol.
     * Used as related info for TS2741 (missing property) diagnostics.
     */
    private fun createPropertyDeclaredHereRelatedInfo(propSymbol: Symbol): Diagnostic? {
        val decl = propSymbol.declarations.firstOrNull() ?: return null
        val declPos = when (decl) {
            is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
            is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
            else -> decl.pos
        }
        if (declPos < 0) return null
        val (declFile, declSource) = resolveDeclarationSourceFile(declPos)
        if (declFile == null || declSource == null) return null
        val declLength = propSymbol.name.length
        val isLib = isLibFileName(declFile)
        val declLine: Int?
        val declChar: Int?
        if (isLib) {
            declLine = null
            declChar = null
        } else {
            val p = getLineAndCharacterOfPosition(declSource, declPos)
            declLine = p.first
            declChar = p.second
        }
        return Diagnostic(
            message = "'${propSymbol.name}' is declared here.",
            category = DiagnosticCategory.Message,
            code = 2728,
            fileName = declFile,
            line = declLine,
            character = declChar,
            start = declPos,
            length = declLength,
        )
    }

    /**
     * Resolve the source file containing [declPos]. Checks user files in [binderResults]
     * first, then falls back to the built-in lib source file. Returns `(fileName, text)`
     * of the matching source, or `(null, null)` if not found.
     */
    private fun resolveDeclarationSourceFile(declPos: Int): Pair<String?, String?> {
        if (declPos < 0) return Pair(null, null)
        for (result in binderResults) {
            val sf = result.sourceFile
            if (declPos in 0 until sf.text.length) {
                return Pair(sf.fileName, sf.text)
            }
        }
        val builtin = builtinLibSourceFile
        if (builtin != null && declPos in 0 until builtin.text.length) {
            return Pair(builtin.fileName, builtin.text)
        }
        return Pair(null, null)
    }

    /**
     * True when [fileName] matches the TypeScript `lib.*.d.ts` convention. Such diagnostics
     * are rendered with `:--:--` in TypeScript's error baselines (line/column hidden because
     * lib line numbers shift between TS versions).
     */
    private fun isLibFileName(fileName: String): Boolean {
        val base = fileName.substringAfterLast('/').substringAfterLast('\\')
        return base.startsWith("lib.") && base.endsWith(".d.ts")
    }

    /**
     * Find the declaring file for [sym] by searching each binderResult's top-level locals
     * for identity-equality with the symbol. Returns the basename (no path, no extension)
     * for `import("X")` qualification. Returns null if not found at file-level (e.g. lib
     * symbols, nested namespace exports). Used by TS2741 cross-file disambiguation.
     */
    private fun getSymbolImportName(sym: Symbol?): String? {
        if (sym == null) return null
        for (br in binderResults) {
            if (br.locals.values.any { it === sym }) {
                val base = br.sourceFile.fileName
                    .substringAfterLast('/').substringAfterLast('\\')
                return base.substringBeforeLast('.')
            }
        }
        return null
    }

    /**
     * B73.1: Return the module basename (no path, no extension) if [expr] is an
     *  Identifier whose symbol is an import alias targeting another file via
     *  `import X = require("./Y")` or `import * as X from "./Y"`. Used to render
     *  `typeof import("X")` displays in TS2322 diagnostics for cross-file module
     *  references. Returns null when the alias doesn't resolve to a file-targeted
     *  module reference (e.g. namespace alias `import X = M.N`).
     */
    private fun tryGetModuleImportNameForExpr(expr: Expression): String? {
        if (expr !is Identifier) return null
        val name = expr.text
        val sym = currentFileLocals?.get(name) ?: globals[name] ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Alias)) return null
        for (decl in sym.declarations) {
            when (decl) {
                is ImportEqualsDeclaration -> {
                    val ref = decl.moduleReference
                    if (ref is ExternalModuleReference) {
                        val specifier = (ref.expression as? StringLiteralNode)?.text ?: continue
                        val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                        val base = targetFile.substringAfterLast('/').substringAfterLast('\\')
                        return base.substringBeforeLast('.')
                    }
                }
                is ImportDeclaration -> {
                    // `import * as X from "./Y"` — namespace import
                    val namedBindings = decl.importClause?.namedBindings
                    if (namedBindings is NamespaceImport && namedBindings.name.text == name) {
                        val specifier = (decl.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                        val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                        val base = targetFile.substringAfterLast('/').substringAfterLast('\\')
                        return base.substringBeforeLast('.')
                    }
                }
                else -> {}
            }
        }
        return null
    }

    /**
     * B63.32: Collect property/method names declared in [sym]'s InterfaceDeclaration
     * in the source file matching [basename]. Bypasses `Type.Interface.properties`
     * which `mergeSymbolTable` pollutes with cross-file declarations of the same
     * name. Used by TS2367 "no overlap" detection for same-name interfaces in
     * different files.
     */
    private fun getOwnFileInterfacePropertyNames(sym: Symbol, basename: String): Set<String>? {
        val name = sym.name
        val br = binderResults.firstOrNull { r ->
            val b = r.sourceFile.fileName.substringAfterLast('/').substringAfterLast('\\')
                .substringBeforeLast('.')
            b == basename
        } ?: return null
        val result = mutableSetOf<String>()
        for (stmt in br.sourceFile.statements) {
            if (stmt is InterfaceDeclaration && stmt.name.text == name) {
                for (member in stmt.members) {
                    val propName: String? = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        else -> null
                    }
                    if (propName != null) result.add(propName)
                }
            }
        }
        return result
    }

    // -----------------------------------------------------------------------
    // TS2362/TS2363: Arithmetic operator type checking (Phase 4 item 14a)
    // -----------------------------------------------------------------------

    // TS2362/TS2363 arithmetic operator type checking — deferred.
    // Naive implementation causes 1300+ regressions because getTypeOfExpression
    // resolves many globals (string, boolean types) that participate in valid
    // arithmetic in test code. Needs conservative approach: only check when operand
    // type is DEFINITIVELY non-numeric (literal string, literal boolean, etc.)
    // and not just any resolved type.
    private fun checkArithmeticOperandTypes() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            try {
                checkArithmeticInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) { }
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun checkArithmeticInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkArithmeticInStatement(stmt, source, fileName)
    }

    private fun checkArithmeticInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkArithmeticInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is Block -> checkArithmeticInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkArithmeticInStatement(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                    }
                    is Expression -> checkArithmeticInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkArithmeticInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkArithmeticInExpr(it, source, fileName) }
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkArithmeticInStatement(stmt.statement, source, fileName)
                checkArithmeticInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkArithmeticInExpr(clause.expression, source, fileName)
                            checkArithmeticInStatements(clause.statements, source, fileName)
                        }
                        is DefaultClause -> checkArithmeticInStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkArithmeticInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                stmt.finallyBlock?.let { checkArithmeticInStatements(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    currentLocalTypes = currentLocalTypes.toMutableMap()
                    // 17.73: Push function type parameters during param-annotation
                    // resolution so refs like `t: T` resolve to Type.TypeParam(T)
                    // instead of errorType. Required for TS2367 narrow extension
                    // to detect TypeParam-vs-literal no-overlap. Scope is restored
                    // before walking the body — currentLocalTypes carries the
                    // resolved Type.TypeParam forward.
                    val savedScope = pushFunctionTypeParamsScope(stmt.typeParameters)
                    try {
                        populateParameterLocalTypes(stmt.parameters)
                    } finally {
                        currentTypeParamScope = savedScope
                    }
                    checkArithmeticInStatements(body.statements, source, fileName)
                    currentLocalTypes = savedLocalTypes
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { body ->
                            val savedLocalTypes = currentLocalTypes
                            currentLocalTypes = currentLocalTypes.toMutableMap()
                            val savedScope = pushFunctionTypeParamsScope(member.typeParameters)
                            try {
                                populateParameterLocalTypes(member.parameters)
                            } finally {
                                currentTypeParamScope = savedScope
                            }
                            checkArithmeticInStatements(body.statements, source, fileName)
                            currentLocalTypes = savedLocalTypes
                        }
                        is Constructor -> member.body?.let { body ->
                            val savedLocalTypes = currentLocalTypes
                            currentLocalTypes = currentLocalTypes.toMutableMap()
                            populateParameterLocalTypes(member.parameters)
                            checkArithmeticInStatements(body.statements, source, fileName)
                            currentLocalTypes = savedLocalTypes
                        }
                        is GetAccessor -> member.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is LabeledStatement -> checkArithmeticInStatement(stmt.statement, source, fileName)
            is ExportAssignment -> checkArithmeticInExpr(stmt.expression, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                checkArithmeticInStatements(it.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkArithmeticInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // B64.4-style iterative left-spine flatten. Run `checkBinaryOperatorTypes`
                // for each BinaryExpression on the spine — preserves the per-node
                // diagnostic emission while avoiding StackOverflow on deep chains.
                val rightStack = ArrayDeque<Expression>()
                val operatorStack = ArrayDeque<BinaryExpression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    operatorStack.addLast(cur)
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkArithmeticInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkArithmeticInExpr(rightStack.removeLast(), source, fileName)
                // Emit binary-operator diagnostics for each spine node (post-order is fine
                // — these are per-binary-expression checks, no cross-node dependencies).
                while (operatorStack.isNotEmpty()) checkBinaryOperatorTypes(operatorStack.removeLast(), source, fileName)
            }
            is ParenthesizedExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkArithmeticInExpr(expr.condition, source, fileName)
                checkArithmeticInExpr(expr.whenTrue, source, fileName)
                checkArithmeticInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkArithmeticInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkArithmeticInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkArithmeticInExpr(expr.operand, source, fileName)
            is ArrayLiteralExpression -> expr.elements.forEach { checkArithmeticInExpr(it, source, fileName) }
            is NewExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkArithmeticInExpr(it, source, fileName) }
            }
            is ArrowFunction -> {
                val savedLocalTypes = currentLocalTypes
                currentLocalTypes = currentLocalTypes.toMutableMap()
                val savedScope = pushFunctionTypeParamsScope(expr.typeParameters)
                try {
                    populateParameterLocalTypes(expr.parameters)
                } finally {
                    currentTypeParamScope = savedScope
                }
                when (val body = expr.body) {
                    is Block -> checkArithmeticInStatements(body.statements, source, fileName)
                    is Expression -> checkArithmeticInExpr(body, source, fileName)
                    else -> {}
                }
                currentLocalTypes = savedLocalTypes
            }
            is FunctionExpression -> {
                val savedLocalTypes = currentLocalTypes
                currentLocalTypes = currentLocalTypes.toMutableMap()
                val savedScope = pushFunctionTypeParamsScope(expr.typeParameters)
                try {
                    populateParameterLocalTypes(expr.parameters)
                } finally {
                    currentTypeParamScope = savedScope
                }
                checkArithmeticInStatements(expr.body.statements, source, fileName)
                currentLocalTypes = savedLocalTypes
            }
            is TemplateExpression -> expr.templateSpans.forEach { checkArithmeticInExpr(it.expression, source, fileName) }
            is AsExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkArithmeticInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> checkArithmeticInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ElementAccessExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                checkArithmeticInExpr(expr.argumentExpression, source, fileName)
            }
            is SpreadElement -> checkArithmeticInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is DeleteExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkArithmeticInExpr(expr.tag, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { checkArithmeticInExpr(it.expression, source, fileName) }
                    else -> {}
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkArithmeticInExpr(it, source, fileName) }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is Constructor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is GetAccessor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    /** Check a binary expression for arithmetic type errors (TS2362/TS2363/TS2365). */
    private fun checkBinaryOperatorTypes(expr: BinaryExpression, source: String, fileName: String) {
        val op = expr.operator
        // 16.0: `in` operator — RHS must be an object-like type, not a primitive.
        // TypeScript emits TS2322 "Type 'X' is not assignable to type 'object'."
        if (op == SyntaxKind.InKeyword) {
            checkInOperatorRhs(expr.right, source, fileName)
            return
        }
        // TS2367: "This comparison appears to be unintentional because the
        // types 'A' and 'B' have no overlap." — narrow scope: both sides
        // are Type.Reference with the same target and incompatible type
        // args (e.g. `l == l2` where `l: List<number>`, `l2: List<string>`).
        if (op == SyntaxKind.EqualsEquals || op == SyntaxKind.ExclamationEquals ||
            op == SyntaxKind.EqualsEqualsEquals || op == SyntaxKind.ExclamationEqualsEquals) {
            checkEqualityComparisonNoOverlap(expr, source, fileName)
            // TS2839: "This condition will always return 'false' since JavaScript
            // compares objects by reference, not value." — fresh object/array literal
            // on one side can never equal anything else by reference.
            checkFreshLiteralReferenceEquality(expr, source, fileName)
            // Fall through — there's no arithmetic check for equality ops, so the
            // rest of this function won't double-emit.
        }
        // Only check arithmetic and comparison operators
        val isArithmetic = op == SyntaxKind.Minus || op == SyntaxKind.Asterisk ||
            op == SyntaxKind.Slash || op == SyntaxKind.Percent ||
            op == SyntaxKind.AsteriskAsterisk ||
            op == SyntaxKind.LessThanLessThan || op == SyntaxKind.GreaterThanGreaterThan ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThan ||
            op == SyntaxKind.Ampersand || op == SyntaxKind.Bar || op == SyntaxKind.Caret
        val isCompoundArithmetic = op == SyntaxKind.MinusEquals || op == SyntaxKind.AsteriskEquals ||
            op == SyntaxKind.SlashEquals || op == SyntaxKind.PercentEquals ||
            op == SyntaxKind.AsteriskAsteriskEquals ||
            op == SyntaxKind.LessThanLessThanEquals || op == SyntaxKind.GreaterThanGreaterThanEquals ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals ||
            op == SyntaxKind.AmpersandEquals || op == SyntaxKind.BarEquals || op == SyntaxKind.CaretEquals
        val isPlus = op == SyntaxKind.Plus
        val isPlusEquals = op == SyntaxKind.PlusEquals
        val isComparison = op == SyntaxKind.LessThan || op == SyntaxKind.GreaterThan ||
            op == SyntaxKind.LessThanEquals || op == SyntaxKind.GreaterThanEquals

        if (!isArithmetic && !isCompoundArithmetic && !isPlus && !isPlusEquals && !isComparison) return

        val leftType = getTypeOfExpression(expr.left)
        val rightType = getTypeOfExpression(expr.right)

        // Skip if either side is anyType or errorType (unresolvable)
        if (leftType === anyType || leftType === errorType) return
        if (rightType === anyType || rightType === errorType) return
        // Skip unknown type
        if (leftType === unknownType || rightType === unknownType) return
        // Null/undefined operands: under strictNullChecks, TS18050 fires (checkNullUndefinedUsage)
        // so we skip here. Under non-strict, let TS2365 fire for `3 + null` etc.
        if (strictNullChecks) {
            if (leftType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return
            if (rightType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return
        }
        // Skip when either side is a non-wrapper Object type (class, interface, etc.)
        // TypeScript handles these via other checks (TS2629 etc.), not arithmetic checks.
        // Only wrapper types (Number, Boolean, String) get arithmetic errors.
        if (isNonWrapperObjectType(leftType) || isNonWrapperObjectType(rightType)) return

        val leftOk = isValidArithmeticOperand(leftType, isPlus || isPlusEquals)
        val rightOk = isValidArithmeticOperand(rightType, isPlus || isPlusEquals)

        // For + / +=: if both sides are valid, skip (string + string, number + number)
        // but if types are incompatible (number + bigint, string + Number), emit TS2365
        if (isPlus || isPlusEquals) {
            if (leftOk && rightOk) {
                // Check for number + bigint mixing
                val leftIsNumber = isNumberLikeType(leftType)
                val rightIsNumber = isNumberLikeType(rightType)
                val leftIsBigInt = isBigIntLikeType(leftType)
                val rightIsBigInt = isBigIntLikeType(rightType)
                if ((leftIsNumber && rightIsBigInt) || (leftIsBigInt && rightIsNumber)) {
                    emitTs2365(expr, op, leftType, rightType, source, fileName)
                }
                return
            }
            // For +: if either is string, allow (string concatenation)
            if (isStringLikeType(leftType) || isStringLikeType(rightType)) return
        }

        if (isArithmetic || isCompoundArithmetic) {
            // TS2447: For bitwise compound (^=, &=, |=) where BOTH operands are
            // boolean, suggest the logical equivalent instead of emitting
            // TS2362/TS2363. Maps: ^= → !==, &= → &&, |= → ||.
            if (isCompoundArithmetic) {
                val bitOpAlt = when (op) {
                    SyntaxKind.CaretEquals -> "!=="
                    SyntaxKind.AmpersandEquals -> "&&"
                    SyntaxKind.BarEquals -> "||"
                    else -> null
                }
                if (bitOpAlt != null &&
                    leftType.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral) &&
                    rightType.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral)) {
                    val opText = getOperatorText(op)
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.left.pos)
                    val length = (expressionTrueEnd(expr.right) - expr.left.pos).coerceAtLeast(1)
                    diagnostics.add(Diagnostic(
                        message = "The '$opText' operator is not allowed for boolean types. Consider using '$bitOpAlt' instead.",
                        category = DiagnosticCategory.Error,
                        code = 2447,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.left.pos,
                        length = length,
                    ))
                    return
                }
            }
            // For strict arithmetic: both sides must be number/bigint/any/enum
            if (!leftOk && !rightOk) {
                // Both bad — emit TS2362 + TS2363
                emitTs2362(expr.left, source, fileName)
                emitTs2363(expr.right, source, fileName)
                return
            }
            if (!leftOk) {
                emitTs2362(expr.left, source, fileName)
                return
            }
            if (!rightOk) {
                emitTs2363(expr.right, source, fileName)
                return
            }
            // Both OK — check number/bigint mixing
            val leftIsNumber = isNumberLikeType(leftType)
            val rightIsNumber = isNumberLikeType(rightType)
            val leftIsBigInt = isBigIntLikeType(leftType)
            val rightIsBigInt = isBigIntLikeType(rightType)
            if ((leftIsNumber && rightIsBigInt) || (leftIsBigInt && rightIsNumber)) {
                emitTs2365(expr, op, leftType, rightType, source, fileName)
            }
            return
        }

        if (isPlus || isPlusEquals) {
            // Neither side is valid for + and neither is string — emit TS2365
            if (!leftOk && !rightOk) {
                emitTs2365(expr, op, leftType, rightType, source, fileName)
                return
            }
            // One side is valid, other is not — emit TS2365
            emitTs2365(expr, op, leftType, rightType, source, fileName)
            return
        }

        if (isComparison) {
            // Comparison: both must be comparable types (string, number, bigint, any, enum)
            val leftComparable = isComparableType(leftType)
            val rightComparable = isComparableType(rightType)
            if (leftComparable && rightComparable) return
            emitTs2365(expr, op, leftType, rightType, source, fileName)
        }
    }

    /** Check if a type is valid for arithmetic operations. */
    private fun isValidArithmeticOperand(type: Type, allowString: Boolean): Boolean {
        if (type === anyType) return true
        if (isNumberLikeType(type)) return true
        if (isBigIntLikeType(type)) return true
        if (type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) return true
        // Enum literal types
        if (type.flags.hasAny(TypeFlags.EnumLiteral)) return true
        // Unions: all constituents must be valid
        if (type is Type.Union) return type.types.all { isValidArithmeticOperand(it, allowString) }
        // TypeParam — recurse on constraint (apparent type). Unconstrained
        // TypeParams are NOT valid arithmetic operands — they could be any
        // type, including non-numeric ones. (TypeScript correctly emits
        // TS2362/TS2363 in this case.)
        if (type is Type.TypeParam) {
            val c = type.constraint ?: return false
            return isValidArithmeticOperand(c, allowString)
        }
        if (allowString && isStringLikeType(type)) return true
        return false
    }

    /** Check if type is number, number literal, or Number-enum. */
    private fun isNumberLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLiteral)) return true
        if (type.flags.hasAny(TypeFlags.EnumLiteral)) return true
        if (type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) return true
        if (type is Type.Union) return type.types.all { isNumberLikeType(it) }
        return false
    }

    /** Check if type is bigint or bigint literal. */
    private fun isBigIntLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.BigInt or TypeFlags.BigIntLiteral)) return true
        if (type is Type.Union) return type.types.all { isBigIntLikeType(it) }
        return false
    }

    /** Check if type is string or string literal. */
    private fun isStringLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral)) return true
        if (type is Type.Union) return type.types.any { isStringLikeType(it) }
        return false
    }

    /** Check if type is valid for comparison operators. */
    /** Check if type is a non-wrapper Object type (user class/interface, not Number/Boolean/String). */
    private fun isNonWrapperObjectType(type: Type): Boolean {
        if (type !is Type.Object) return false
        val name = type.symbol?.name ?: return true // anonymous objects are non-wrapper
        return name != "Number" && name != "Boolean" && name != "String" && name != "Symbol" && name != "BigInt"
    }

    private fun isComparableType(type: Type): Boolean {
        if (type === anyType) return true
        if (isNumberLikeType(type)) return true
        if (isBigIntLikeType(type)) return true
        if (isStringLikeType(type)) return true
        if (type.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral)) return true
        if (type is Type.Union) return type.types.all { isComparableType(it) }
        return false
    }

    /** For TS2365 "Operator X cannot be applied to types 'A' and 'B'", display the
     *  LITERAL form of literal operands (number `3`, null, undefined) rather than
     *  the widened type. Matches TypeScript's baseline behavior. */
    private fun ts2365OperandDisplay(operand: Expression, type: Type): String {
        return when (operand) {
            is NumericLiteralNode -> operand.text
            is BigIntLiteralNode -> operand.text
            is Identifier -> when (operand.text) {
                "null" -> "null"
                "undefined" -> "undefined"
                "true" -> "true"
                "false" -> "false"
                else -> typeToString(type)
            }
            is ParenthesizedExpression -> ts2365OperandDisplay(operand.expression, type)
            is NonNullExpression -> ts2365OperandDisplay(operand.expression, type)
            is AsExpression -> typeToString(type)
            is SatisfiesExpression -> ts2365OperandDisplay(operand.expression, type)
            else -> typeToString(type)
        }
    }

    private fun emitTs2365(expr: BinaryExpression, op: SyntaxKind, leftType: Type, rightType: Type, source: String, fileName: String) {
        val opText = getOperatorText(op)
        val leftStr = ts2365OperandDisplay(expr.left, leftType)
        val rightStr = ts2365OperandDisplay(expr.right, rightType)
        val start = expr.left.pos
        val length = expressionTrueEnd(expr.right) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Operator '$opText' cannot be applied to types '$leftStr' and '$rightStr'.",
            category = DiagnosticCategory.Error, code = 2365,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun emitTs2362(operand: Expression, source: String, fileName: String) {
        val start = operand.pos
        val length = expressionTrueEnd(operand) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The left-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.",
            category = DiagnosticCategory.Error, code = 2362,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun emitTs2363(operand: Expression, source: String, fileName: String) {
        val start = operand.pos
        val length = expressionTrueEnd(operand) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The right-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.",
            category = DiagnosticCategory.Error, code = 2363,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun getOperatorText(op: SyntaxKind): String = when (op) {
        SyntaxKind.Plus -> "+"
        SyntaxKind.Minus -> "-"
        SyntaxKind.Asterisk -> "*"
        SyntaxKind.Slash -> "/"
        SyntaxKind.Percent -> "%"
        SyntaxKind.AsteriskAsterisk -> "**"
        SyntaxKind.PlusEquals -> "+="
        SyntaxKind.MinusEquals -> "-="
        SyntaxKind.AsteriskEquals -> "*="
        SyntaxKind.SlashEquals -> "/="
        SyntaxKind.PercentEquals -> "%="
        SyntaxKind.AsteriskAsteriskEquals -> "**="
        SyntaxKind.LessThan -> "<"
        SyntaxKind.GreaterThan -> ">"
        SyntaxKind.LessThanEquals -> "<="
        SyntaxKind.GreaterThanEquals -> ">="
        SyntaxKind.LessThanLessThan -> "<<"
        SyntaxKind.GreaterThanGreaterThan -> ">>"
        SyntaxKind.GreaterThanGreaterThanGreaterThan -> ">>>"
        SyntaxKind.Ampersand -> "&"
        SyntaxKind.Bar -> "|"
        SyntaxKind.Caret -> "^"
        SyntaxKind.LessThanLessThanEquals -> "<<="
        SyntaxKind.GreaterThanGreaterThanEquals -> ">>="
        SyntaxKind.GreaterThanGreaterThanGreaterThanEquals -> ">>>="
        SyntaxKind.AmpersandEquals -> "&="
        SyntaxKind.BarEquals -> "|="
        SyntaxKind.CaretEquals -> "^="
        else -> op.name
    }

    // -----------------------------------------------------------------------
    // TS2364: Invalid assignment target
    // -----------------------------------------------------------------------

    private fun checkInvalidAssignmentTargets() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkInvalidAssignInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkInvalidAssignInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkInvalidAssignInStatement(stmt, source, fileName)
    }

    private fun checkInvalidAssignInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkInvalidAssignInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkInvalidAssignInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkInvalidAssignInExpr(it, source, fileName) }
            is Block -> checkInvalidAssignInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkInvalidAssignInExpr(stmt.expression, source, fileName)
                checkInvalidAssignInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkInvalidAssignInStatement(it, source, fileName) }
            }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { checkInvalidAssignInExpr(it, source, fileName) }
                stmt.condition?.let { checkInvalidAssignInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkInvalidAssignInExpr(it, source, fileName) }
                checkInvalidAssignInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkInvalidAssignInExpr(stmt.expression, source, fileName)
                checkInvalidAssignInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkInvalidAssignInExpr(stmt.expression, source, fileName)
                checkInvalidAssignInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkInvalidAssignInExpr(stmt.expression, source, fileName)
                checkInvalidAssignInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkInvalidAssignInExpr(stmt.expression, source, fileName)
                checkInvalidAssignInStatement(stmt.statement, source, fileName)
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkInvalidAssignInStatements(clause.statements, source, fileName)
                        is DefaultClause -> checkInvalidAssignInStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkInvalidAssignInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                stmt.finallyBlock?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> stmt.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is Constructor -> member.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is GetAccessor -> member.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { checkInvalidAssignInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> checkInvalidAssignInStatement(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkInvalidAssignInExpr(it, source, fileName) }
            is ExportAssignment -> checkInvalidAssignInExpr(stmt.expression, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkInvalidAssignInExpr(expr: Expression, source: String, fileName: String) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try {
        checkInvalidAssignInExprCore(expr, source, fileName)
        } finally { checkDepth-- }
    }
    private fun checkInvalidAssignInExprCore(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // Check if this is an assignment
                if (expr.operator == SyntaxKind.Equals) {
                    if (!isValidAssignmentTarget(expr.left)) {
                        val start = expr.left.pos
                        val length = expressionTrueEnd(expr.left) - start
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "The left-hand side of an assignment expression must be a variable or a property access.",
                            category = DiagnosticCategory.Error,
                            code = 2364,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    } else {
                        // Destructuring patterns: check for private identifiers as direct elements.
                        // E.g. `[#abc] = x` — `#abc` (Identifier whose text starts with `#`) is not
                        // a valid assignment target outside of a `this.#abc` member-access chain.
                        checkDestructuringPrivateIds(expr.left, source, fileName)
                    }
                }
                checkInvalidAssignInExpr(expr.left, source, fileName)
                checkInvalidAssignInExpr(expr.right, source, fileName)
            }
            is ConditionalExpression -> {
                checkInvalidAssignInExpr(expr.condition, source, fileName)
                checkInvalidAssignInExpr(expr.whenTrue, source, fileName)
                checkInvalidAssignInExpr(expr.whenFalse, source, fileName)
            }
            is ParenthesizedExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkInvalidAssignInStatements(body.statements, source, fileName)
                    is Expression -> checkInvalidAssignInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> expr.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
            is CallExpression -> {
                checkInvalidAssignInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkInvalidAssignInExpr(arg, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkInvalidAssignInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template as TemplateExpression).templateSpans) checkInvalidAssignInExpr(span.expression, source, fileName)
                }
            }
            is PrefixUnaryExpression -> checkInvalidAssignInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkInvalidAssignInExpr(expr.operand, source, fileName)
            is SpreadElement -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is ArrayLiteralExpression -> {
                for (el in expr.elements) checkInvalidAssignInExpr(el, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkInvalidAssignInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkInvalidAssignInExpr(it, source, fileName) }
                        is SpreadAssignment -> checkInvalidAssignInExpr(prop.expression, source, fileName)
                        is MethodDeclaration -> prop.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is GetAccessor -> prop.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        is SetAccessor -> prop.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) checkInvalidAssignInExpr(span.expression, source, fileName)
            }
            is AsExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is NewExpression -> {
                checkInvalidAssignInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkInvalidAssignInExpr(it, source, fileName) }
            }
            is ElementAccessExpression -> {
                checkInvalidAssignInExpr(expr.expression, source, fileName)
                checkInvalidAssignInExpr(expr.argumentExpression, source, fileName)
            }
            is PropertyAccessExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkInvalidAssignInExpr(it, source, fileName) }
            is VoidExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkInvalidAssignInExpr(expr.expression, source, fileName)
            is CommaListExpression -> for (e in expr.elements) checkInvalidAssignInExpr(e, source, fileName)
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                is Constructor -> m.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                is GetAccessor -> m.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { checkInvalidAssignInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { checkInvalidAssignInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    /** Check if an expression is a valid assignment target (LHS of =). */
    private fun isValidAssignmentTarget(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> true
            is PropertyAccessExpression -> true
            is ElementAccessExpression -> true
            // A ParenthesizedExpression carrying `instantiationEnd` is a synthetic
            // wrapper inserted by the parser for an instantiation expression like
            // `obj.fn<T>`. TypeScript treats InstantiationExpression as an invalid
            // assignment target — emit TS2364 "The left-hand side of an assignment
            // expression must be a variable or a property access."
            is ParenthesizedExpression ->
                if (expr.instantiationEnd != null) false
                else isValidAssignmentTarget(expr.expression)
            is NonNullExpression -> isValidAssignmentTarget(expr.expression)
            // Type-only wrappers: `x as T`, `<T>x`, `x satisfies T` preserve the
            // underlying reference and remain valid assignment targets so long as
            // their inner expression is.
            is AsExpression -> isValidAssignmentTarget(expr.expression)
            is TypeAssertionExpression -> isValidAssignmentTarget(expr.expression)
            is SatisfiesExpression -> isValidAssignmentTarget(expr.expression)
            // Destructuring patterns are valid (array/object literal on LHS)
            is ArrayLiteralExpression -> true
            is ObjectLiteralExpression -> true
            else -> false
        }
    }

    /**
     * Walk a destructuring pattern (ArrayLiteralExpression / ObjectLiteralExpression) on
     * the LHS of an assignment and emit TS2364 at any private-identifier element. A bare
     * `#abc` (Identifier scanned as a single token with leading `#`) is never a valid
     * assignment target — private fields require `this.#abc` or `obj.#abc` syntax.
     */
    private fun checkDestructuringPrivateIds(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is Identifier -> {
                if (expr.text.startsWith("#")) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "The left-hand side of an assignment expression must be a variable or a property access.",
                        category = DiagnosticCategory.Error,
                        code = 2364,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                }
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) {
                    val target = if (el is SpreadElement) el.expression else el
                    checkDestructuringPrivateIds(target, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkDestructuringPrivateIds(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> {
                            if (prop.name.text.startsWith("#")) {
                                val start = prop.name.pos
                                val length = prop.name.text.length
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "The left-hand side of an assignment expression must be a variable or a property access.",
                                    category = DiagnosticCategory.Error,
                                    code = 2364,
                                    fileName = fileName, line = line, character = character,
                                    start = start, length = length,
                                ))
                            }
                        }
                        is SpreadAssignment -> checkDestructuringPrivateIds(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkDestructuringPrivateIds(expr.expression, source, fileName)
            is BinaryExpression -> {
                // Default value: `[x = 1] = ...` — recurse into LHS only.
                if (expr.operator == SyntaxKind.Equals) {
                    checkDestructuringPrivateIds(expr.left, source, fileName)
                }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2405: for-in LHS must be 'string' or 'any'
    // -----------------------------------------------------------------------

    private fun checkForInLhsTypes() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            try {
                checkForInLhsInStatements(result.sourceFile.statements, result.locals, source, fileName, inAmbient = false)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkForInLhsInStatements(
        stmts: List<Statement>, locals: SymbolTable, source: String, fileName: String, inAmbient: Boolean,
    ) {
        for (stmt in stmts) checkForInLhsInStmt(stmt, locals, source, fileName, inAmbient)
    }

    private fun checkForInLhsInStmt(
        stmt: Statement, locals: SymbolTable, source: String, fileName: String, inAmbient: Boolean,
    ) {
        when (stmt) {
            is ForInStatement -> {
                val lhs = stmt.initializer
                if (lhs is Identifier) {
                    val sym = locals[lhs.text]
                    val decl = sym?.valueDeclaration
                    if (decl is VariableDeclaration) {
                        val typeNode = decl.type
                        if (typeNode != null && !isForInLhsCompatible(typeNode)) {
                            val start = lhs.pos
                            val length = lhs.text.length
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "The left-hand side of a 'for...in' statement must be of type 'string' or 'any'.",
                                category = DiagnosticCategory.Error,
                                code = 2405,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                } else if (lhs is ElementAccessExpression) {
                    // n[i] for-in LHS: element type must be string/any. Narrow surgical detection:
                    // when base is an Identifier whose initializer is an ArrayLiteralExpression
                    // (possibly through ||/??), and at least one of those array literals contains
                    // an array/object literal element, the element type is object/array → TS2405.
                    val base = lhs.expression
                    if (base is Identifier) {
                        val sym = locals[base.text]
                        val decl = sym?.valueDeclaration
                        if (decl is VariableDeclaration && decl.type == null) {
                            val init = decl.initializer
                            if (init != null && initializerHasNestedArrayOrObjectElement(init)) {
                                val start = lhs.pos
                                val length = (expressionTrueEnd(lhs) - start).coerceAtLeast(1)
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "The left-hand side of a 'for...in' statement must be of type 'string' or 'any'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2405,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                    }
                }
                // TS2407: RHS must be 'any', an object type, or a type parameter.
                // Skip in ambient contexts (TypeScript only emits TS1036 for those).
                val rhsDisplay = if (!inAmbient) simpleRhsNonObjectDisplay(stmt.expression) else null
                if (rhsDisplay != null) {
                    val rhsStart = stmt.expression.pos
                    val rhsEnd = expressionTrueEnd(stmt.expression)
                    val rhsLen = (rhsEnd - rhsStart).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, rhsStart)
                    diagnostics.add(Diagnostic(
                        message = "The right-hand side of a 'for...in' statement must be of type 'any', an object type or a type parameter, but here has type '$rhsDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2407,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = rhsStart,
                        length = rhsLen,
                    ))
                }
                checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            }
            is Block -> checkForInLhsInStatements(stmt.statements, locals, source, fileName, inAmbient)
            is IfStatement -> {
                checkForInLhsInStmt(stmt.thenStatement, locals, source, fileName, inAmbient)
                stmt.elseStatement?.let { checkForInLhsInStmt(it, locals, source, fileName, inAmbient) }
            }
            is ForStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is ForOfStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is WhileStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is DoStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkForInLhsInStatements(clause.statements, locals, source, fileName, inAmbient)
                        is DefaultClause -> checkForInLhsInStatements(clause.statements, locals, source, fileName, inAmbient)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkForInLhsInStatements(stmt.tryBlock.statements, locals, source, fileName, inAmbient)
                stmt.catchClause?.block?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                stmt.finallyBlock?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
            }
            is FunctionDeclaration -> stmt.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is Constructor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is GetAccessor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is SetAccessor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                else -> {}
            }
            is LabeledStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                val ambient = inAmbient || ModifierFlag.Declare in stmt.modifiers
                checkForInLhsInStatements(it.statements, locals, source, fileName, ambient)
            }
            else -> {}
        }
    }

    /**
     * If the RHS expression of a for-in is clearly a non-object, non-any value (number literal,
     * string literal, boolean, null, undefined), return its display text for TS2407. Otherwise
     * return null — conservative: unknown expressions are assumed valid.
     */
    private fun simpleRhsNonObjectDisplay(expr: Expression): String? {
        return when (expr) {
            is NumericLiteralNode -> expr.text
            is BigIntLiteralNode -> expr.text
            is StringLiteralNode -> "\"${expr.text}\""
            is Identifier -> when (expr.text) {
                "true", "false", "null", "undefined" -> expr.text
                else -> {
                    // 17.184: Identifier resolving to a primitive-typed variable
                    // (e.g. `declare var expr: number`). Look up the symbol's
                    // declared type via globals; if KeywordTypeNode and not
                    // string/any/unknown/object, return its display.
                    val sym = globals[expr.text] ?: return null
                    val decl = sym.valueDeclaration as? VariableDeclaration ?: return null
                    val typeNode = decl.type as? KeywordTypeNode ?: return null
                    when (typeNode.kind) {
                        SyntaxKind.NumberKeyword -> "number"
                        SyntaxKind.BooleanKeyword -> "boolean"
                        SyntaxKind.BigIntKeyword -> "bigint"
                        SyntaxKind.SymbolKeyword -> "symbol"
                        SyntaxKind.VoidKeyword -> "void"
                        SyntaxKind.NeverKeyword -> "never"
                        else -> null
                    }
                }
            }
            is PrefixUnaryExpression -> {
                // `-1` is still a numeric literal form
                if (expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) {
                    val inner = simpleRhsNonObjectDisplay(expr.operand) ?: return null
                    (if (expr.operator == SyntaxKind.Minus) "-" else "") + inner
                } else null
            }
            else -> null
        }
    }

    /**
     * Returns true if [init] is (recursively through `||`/`??` BinaryExpression) an
     * `ArrayLiteralExpression`, where at least one branch's array has at least one
     * element that is itself an `ArrayLiteralExpression` or `ObjectLiteralExpression`.
     * Used to detect that `var x = init; x[i]` yields an object/array element type
     * (not string/any), which would make `x[i]` an invalid for-in LHS (TS2405).
     */
    private fun initializerHasNestedArrayOrObjectElement(init: Expression): Boolean {
        var allArrayLiterals = true
        var hasNested = false
        fun walk(e: Expression) {
            when (e) {
                is ArrayLiteralExpression -> {
                    if (e.elements.any { it is ArrayLiteralExpression || it is ObjectLiteralExpression }) {
                        hasNested = true
                    }
                }
                is BinaryExpression -> if (e.operator == SyntaxKind.BarBar || e.operator == SyntaxKind.QuestionQuestion) {
                    walk(e.left)
                    walk(e.right)
                } else {
                    allArrayLiterals = false
                }
                is ParenthesizedExpression -> walk(e.expression)
                else -> allArrayLiterals = false
            }
        }
        walk(init)
        return allArrayLiterals && hasNested
    }

    /** Returns true if the annotated type can appear on the LHS of `for..in`: string/any/unknown. */
    private fun isForInLhsCompatible(typeNode: TypeNode): Boolean {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.StringKeyword, SyntaxKind.AnyKeyword, SyntaxKind.UnknownKeyword -> true
                else -> false
            }
            is UnionType -> typeNode.types.all { isForInLhsCompatible(it) }
            is ParenthesizedType -> isForInLhsCompatible(typeNode.type)
            // Unknown type forms (type references, literal types, etc.) — conservative: accept.
            else -> true
        }
    }

    // -----------------------------------------------------------------------
    // TS2709: Cannot use namespace as a type
    // -----------------------------------------------------------------------

    private fun checkNamespaceUsedAsType() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentCheckLocals = result.locals

            for (stmt in result.sourceFile.statements) {
                checkNamespaceAsTypeInStmt(stmt, source, fileName)
            }
        }
        currentCheckLocals = null
    }

    private fun checkNamespaceAsTypeInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkTypeRefForNamespace(decl.type, source, fileName)
                    decl.initializer?.let { checkTypeRefsInExpr(it, source, fileName) }
                }
            }
            is FunctionDeclaration -> {
                for (param in stmt.parameters) {
                    checkTypeRefForNamespace(param.type, source, fileName)
                }
                checkTypeRefForNamespace(stmt.type, source, fileName)
                stmt.body?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkNamespaceAsTypeInStmt(s, source, fileName)
                }
            }
            is ClassDeclaration -> {
                // 16.4cx: `class C2 implements M` (M = namespace) → TS2709 at M.
                // (`class C extends M` is a value position → TS2708, handled elsewhere.)
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ImplementsKeyword) {
                        for (typeExpr in clause.types) {
                            checkHeritageExprForNamespace(typeExpr.expression, source, fileName)
                        }
                    }
                }
                for (member in stmt.members) {
                    when (member) {
                        is PropertyDeclaration -> checkTypeRefForNamespace(member.type, source, fileName)
                        is MethodDeclaration -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                            checkTypeRefForNamespace(member.type, source, fileName)
                        }
                        is Constructor -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                        }
                        is GetAccessor -> checkTypeRefForNamespace(member.type, source, fileName)
                        is SetAccessor -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is InterfaceDeclaration -> {
                // 16.4cx: `interface I extends M` (M = namespace) → TS2709 at M.
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (typeExpr in clause.types) {
                            checkHeritageExprForNamespace(typeExpr.expression, source, fileName)
                        }
                    }
                }
            }
            is ExpressionStatement -> checkTypeRefsInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkTypeRefsInExpr(it, source, fileName) }
            is IfStatement -> {
                checkTypeRefsInExpr(stmt.expression, source, fileName)
                checkNamespaceAsTypeInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is ForStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ForInStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is WhileStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is DoStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> c.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                    is DefaultClause -> c.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                stmt.catchClause?.block?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is LabeledStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkTypeRefsInExpr(it, source, fileName) }
            is ExportAssignment -> checkTypeRefsInExpr(stmt.expression, source, fileName)
            is Block -> stmt.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Walk an expression looking for ArrowFunction / FunctionExpression and check their
     * parameter/return type annotations for namespace-used-as-type.
     */
    private fun checkTypeRefsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                for (p in expr.parameters) checkTypeRefForNamespace(p.type, source, fileName)
                checkTypeRefForNamespace(expr.type, source, fileName)
                val body = expr.body
                if (body is Block) body.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                else if (body is Expression) checkTypeRefsInExpr(body, source, fileName)
            }
            is FunctionExpression -> {
                for (p in expr.parameters) checkTypeRefForNamespace(p.type, source, fileName)
                checkTypeRefForNamespace(expr.type, source, fileName)
                expr.body.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is CallExpression -> {
                checkTypeRefsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkTypeRefsInExpr(arg, source, fileName)
            }
            is ParenthesizedExpression -> checkTypeRefsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                // B64.6: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkTypeRefsInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkTypeRefsInExpr(rightStack.removeLast(), source, fileName)
            }
            else -> {}
        }
    }

    private var currentCheckLocals: SymbolTable? = null

    /**
     * 16.4cx: Heritage-clause variant — emit TS2709 when an interface `extends X`
     * or class `implements X` and `X` resolves to a namespace-only symbol.
     */
    private fun checkHeritageExprForNamespace(expr: Expression, source: String, fileName: String) {
        if (expr !is Identifier) return
        val name = expr.text
        val symbol = currentCheckLocals?.get(name) ?: globals[name] ?: return
        if (!symbol.flags.hasAny(SymbolFlags.Module)) return
        if (symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Enum)) return
        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
        diagnostics.add(Diagnostic(
            message = "Cannot use namespace '$name' as a type.",
            category = DiagnosticCategory.Error,
            code = 2709,
            fileName = fileName,
            line = line,
            character = character,
            start = expr.pos,
            length = name.length,
        ))
    }

    private fun checkTypeRefForNamespace(typeNode: TypeNode?, source: String, fileName: String) {
        if (typeNode == null) return
        if (typeNode !is TypeReference) return
        val name = (typeNode.typeName as? Identifier)?.text ?: return
        // Check if name is imported locally via `import X = require("mod")`.
        // If the target module has no `export =`, X is a namespace alias and
        // using it as a type is TS2709.
        val localSym = currentCheckLocals?.get(name)
        if (localSym != null && localSym.flags.hasAny(SymbolFlags.Alias)) {
            val decl = localSym.declarations.firstOrNull()
            if (decl is ImportEqualsDeclaration) {
                val modRef = decl.moduleReference
                if (modRef is ExternalModuleReference) {
                    val specifierExpr = modRef.expression
                    val moduleSpecifier = (specifierExpr as? StringLiteralNode)?.text
                    if (moduleSpecifier != null) {
                        val targetFile = resolveModuleSpecifier(moduleSpecifier, decl)
                        val targetResult = targetFile?.let { fileResults[it] }
                        if (targetResult != null) {
                            val hasExportEquals = targetResult.sourceFile.statements.any {
                                it is ExportAssignment && it.isExportEquals
                            }
                            if (!hasExportEquals) {
                                val (line, character) = getLineAndCharacterOfPosition(source, typeNode.typeName.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Cannot use namespace '$name' as a type.",
                                    category = DiagnosticCategory.Error,
                                    code = 2709,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = typeNode.typeName.pos,
                                    length = name.length,
                                ))
                            }
                        }
                    }
                }
            }
            return
        }
        val symbol = globals[name] ?: return
        // Check if symbol is ONLY a namespace (no Class, Interface, TypeAlias, Enum)
        if (!symbol.flags.hasAny(SymbolFlags.Module)) return
        if (symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Enum)) return
        val (line, character) = getLineAndCharacterOfPosition(source, typeNode.typeName.pos)
        diagnostics.add(Diagnostic(
            message = "Cannot use namespace '$name' as a type.",
            category = DiagnosticCategory.Error,
            code = 2709,
            fileName = fileName,
            line = line,
            character = character,
            start = typeNode.typeName.pos,
            length = name.length,
        ))
    }

    // TS2802: Type can only be iterated through when using --downlevelIteration
    // -----------------------------------------------------------------------

    private fun checkDownlevelIteration() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val typedArrayVars = collectTypedArrayVars(result.sourceFile.statements)
            checkDownlevelIterationInStatements(result.sourceFile.statements, source, fileName, typedArrayVars = typedArrayVars)
        }
    }

    private fun checkDownlevelIterationInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        iteratorVars: Set<String> = emptySet(),
        typedArrayVars: Map<String, String> = emptyMap(),
    ) {
        for (stmt in stmts) checkDownlevelIterationInStmt(stmt, source, fileName, iteratorVars, typedArrayVars)
    }

    /** Collect names of vars initialized from `arguments[<expr>]` at this body's top level.
     *  These produce `ArrayIterator<any>` when called, so iterating their result needs TS2802. */
    private fun collectArgumentsIteratorVars(stmts: List<Statement>): Set<String> {
        val names = mutableSetOf<String>()
        for (stmt in stmts) {
            if (stmt !is VariableStatement) continue
            for (decl in stmt.declarationList.declarations) {
                val name = decl.name
                val init = decl.initializer ?: continue
                if (name !is Identifier) continue
                if (init !is ElementAccessExpression) continue
                val target = init.expression
                if (target is Identifier && target.text == "arguments") {
                    names.add(name.text)
                }
            }
        }
        return names
    }

    /** Collect names of vars initialized from `new TypedArrayConstructor(...)` or `new NodeList()`.
     *  Iterating these via `[...x]` under target<ES2015 && !downlevelIteration emits TS2802. */
    private fun collectTypedArrayVars(stmts: List<Statement>): Map<String, String> {
        val names = mutableMapOf<String, String>()
        for (stmt in stmts) {
            if (stmt !is VariableStatement) continue
            for (decl in stmt.declarationList.declarations) {
                val name = decl.name
                val init = decl.initializer ?: continue
                if (name !is Identifier) continue
                if (init !is NewExpression) continue
                val callee = init.expression as? Identifier ?: continue
                if (callee.text in TYPED_ARRAY_CONSTRUCTORS) {
                    names[name.text] = callee.text
                }
            }
        }
        return names
    }

    /** For a `Identifier(...)` call expression, compute the squiggle length covering
     *  the callee identifier through the matching `)`. */
    private fun computeIdentCallSpanLength(callee: Identifier, source: String): Int {
        var i = callee.pos + callee.text.length
        while (i < source.length && source[i].isWhitespace()) i++
        if (i >= source.length || source[i] != '(') return callee.text.length
        var depth = 1
        i++
        while (i < source.length && depth > 0) {
            when (source[i]) {
                '(' -> depth++
                ')' -> depth--
            }
            i++
        }
        return i - callee.pos
    }

    private fun checkDownlevelIterationInStmt(
        stmt: Statement, source: String, fileName: String,
        iteratorVars: Set<String> = emptySet(),
        typedArrayVars: Map<String, String> = emptyMap(),
    ) {
        when (stmt) {
            is ForOfStatement -> {
                // Check if the expression is `arguments` (type IArguments)
                val expr = stmt.expression
                if (expr is Identifier && expr.text == "arguments") {
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'IArguments' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                        category = DiagnosticCategory.Error,
                        code = 2802,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.pos,
                        length = expr.text.length,
                    ))
                } else if (expr is CallExpression) {
                    val callee = expr.expression
                    if (callee is Identifier && callee.text in iteratorVars) {
                        val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                        val len = computeIdentCallSpanLength(callee, source)
                        diagnostics.add(Diagnostic(
                            message = "Type 'ArrayIterator<any>' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                            category = DiagnosticCategory.Error,
                            code = 2802,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = callee.pos,
                            length = len,
                        ))
                    }
                }
                // Recurse into body
                when (val body = stmt.statement) {
                    is Block -> checkDownlevelIterationInStatements(body.statements, source, fileName, iteratorVars, typedArrayVars)
                    else -> checkDownlevelIterationInStmt(body, source, fileName, iteratorVars, typedArrayVars)
                }
            }
            is ExpressionStatement -> {
                checkDownlevelIterationInExpr(stmt.expression, source, fileName, typedArrayVars)
            }
            is VariableStatement -> {
                // Check for array destructuring from `arguments`: let [x, y, z] = arguments
                for (decl in stmt.declarationList.declarations) {
                    if (decl.name is ArrayBindingPattern && decl.initializer is Identifier) {
                        val init = decl.initializer as Identifier
                        if (init.text == "arguments") {
                            val bindingPattern = decl.name as ArrayBindingPattern
                            val start = bindingPattern.pos
                            // Find the closing ] in source text
                            val closeBracket = source.indexOf(']', start)
                            val len = if (closeBracket >= 0) closeBracket - start + 1 else bindingPattern.end - start
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type 'IArguments' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                                category = DiagnosticCategory.Error,
                                code = 2802,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = len,
                            ))
                        }
                    }
                }
            }
            is Block -> checkDownlevelIterationInStatements(stmt.statements, source, fileName, iteratorVars, typedArrayVars)
            is IfStatement -> {
                checkDownlevelIterationInStmt(stmt.thenStatement, source, fileName, iteratorVars, typedArrayVars)
                stmt.elseStatement?.let { checkDownlevelIterationInStmt(it, source, fileName, iteratorVars, typedArrayVars) }
            }
            is WhileStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is DoStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is ForStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is ForInStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkDownlevelIterationInStatements(c.statements, source, fileName, iteratorVars, typedArrayVars)
                    is DefaultClause -> checkDownlevelIterationInStatements(c.statements, source, fileName, iteratorVars, typedArrayVars)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkDownlevelIterationInStatements(stmt.tryBlock.statements, source, fileName, iteratorVars, typedArrayVars)
                stmt.catchClause?.let { checkDownlevelIterationInStatements(it.block.statements, source, fileName, iteratorVars, typedArrayVars) }
                stmt.finallyBlock?.let { checkDownlevelIterationInStatements(it.statements, source, fileName, iteratorVars, typedArrayVars) }
            }
            is LabeledStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is FunctionDeclaration -> stmt.body?.let {
                checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
            }
            is ClassDeclaration -> for (member in stmt.members) {
                when (member) {
                    is MethodDeclaration -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is Constructor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is GetAccessor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is SetAccessor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                checkDownlevelIterationInStatements(it.statements, source, fileName, iteratorVars, typedArrayVars)
            }
            else -> {}
        }
    }

    /** Check an expression for `[...identifier]` patterns where identifier names a typed-array
     *  variable. Emits TS2802 on the identifier's span. */
    private fun checkDownlevelIterationInExpr(
        expr: Expression, source: String, fileName: String,
        typedArrayVars: Map<String, String>,
    ) {
        if (typedArrayVars.isEmpty()) return
        if (expr !is ArrayLiteralExpression) return
        for (element in expr.elements) {
            if (element !is SpreadElement) continue
            val spreadTarget = element.expression
            if (spreadTarget !is Identifier) continue
            val ctorName = typedArrayVars[spreadTarget.text] ?: continue
            val displayType = if (ctorName == "NodeList") "NodeList" else "$ctorName<ArrayBuffer>"
            val (line, character) = getLineAndCharacterOfPosition(source, spreadTarget.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$displayType' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                category = DiagnosticCategory.Error,
                code = 2802,
                fileName = fileName,
                line = line,
                character = character,
                start = spreadTarget.pos,
                length = spreadTarget.text.length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // TS2737: BigInt literals not available below ES2020
    // -----------------------------------------------------------------------

    private fun checkBigIntLiterals() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue  // .d.ts files are entirely ambient
            val source = result.sourceFile.text
            checkBigIntLiteralsInStmts(result.sourceFile.statements, source, fileName, ambient = false)
        }
    }

    private fun checkBigIntLiteralsInStmts(
        stmts: List<Statement>, source: String, fileName: String, ambient: Boolean
    ) {
        for (stmt in stmts) checkBigIntLiteralsInStmt(stmt, source, fileName, ambient)
    }

    private fun checkBigIntLiteralsInStmt(
        stmt: Statement, source: String, fileName: String, ambient: Boolean
    ) {
        when (stmt) {
            is VariableStatement -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                if (!ambient && !isDeclare) {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    }
                }
            }
            is ExpressionStatement -> {
                if (!ambient) checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                if (!ambient) stmt.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            }
            is Block -> checkBigIntLiteralsInStmts(stmt.statements, source, fileName, ambient)
            is IfStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.thenStatement, source, fileName, ambient = false)
                    stmt.elseStatement?.let { checkBigIntLiteralsInStmt(it, source, fileName, ambient = false) }
                }
            }
            is WhileStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForStatement -> {
                if (!ambient) {
                    (stmt.initializer as? Expression)?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    stmt.condition?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    stmt.incrementor?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForOfStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForInStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is DoStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                }
            }
            is SwitchStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    for (c in stmt.caseBlock) when (c) {
                        is CaseClause -> {
                            checkBigIntLiteralsInExpr(c.expression, source, fileName)
                            checkBigIntLiteralsInStmts(c.statements, source, fileName, ambient = false)
                        }
                        is DefaultClause -> checkBigIntLiteralsInStmts(c.statements, source, fileName, ambient = false)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInStmts(stmt.tryBlock.statements, source, fileName, ambient = false)
                    stmt.catchClause?.let { checkBigIntLiteralsInStmts(it.block.statements, source, fileName, ambient = false) }
                    stmt.finallyBlock?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                }
            }
            is LabeledStatement -> {
                if (!ambient) checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
            }
            is ThrowStatement -> {
                if (!ambient) stmt.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            }
            is ExportAssignment -> {
                if (!ambient) checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
            }
            is FunctionDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                stmt.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = isDeclare) }
            }
            is ClassDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                if (!isDeclare && !ambient) {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is Constructor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is PropertyDeclaration -> {
                                if (ModifierFlag.Declare !in member.modifiers) {
                                    member.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                                }
                            }
                            is GetAccessor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is SetAccessor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            else -> {}
                        }
                    }
                }
            }
            is ModuleDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkBigIntLiteralsInStmts(body.statements, source, fileName, ambient = ambient || isDeclare)
                }
            }
            else -> {}
        }
    }

    private fun checkBigIntLiteralsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BigIntLiteralNode -> {
                val start = expr.pos
                val length = expr.text.length  // text already includes the trailing 'n'
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "BigInt literals are not available when targeting lower than ES2020.",
                    category = DiagnosticCategory.Error,
                    code = 2737,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
            is PrefixUnaryExpression -> checkBigIntLiteralsInExpr(expr.operand, source, fileName)
            is BinaryExpression -> {
                checkBigIntLiteralsInExpr(expr.left, source, fileName)
                checkBigIntLiteralsInExpr(expr.right, source, fileName)
            }
            is ParenthesizedExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is CallExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkBigIntLiteralsInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments ?: emptyList()) checkBigIntLiteralsInExpr(arg, source, fileName)
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) checkBigIntLiteralsInExpr(el, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkBigIntLiteralsInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> checkBigIntLiteralsInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is PropertyAccessExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                checkBigIntLiteralsInExpr(expr.argumentExpression, source, fileName)
            }
            is ConditionalExpression -> {
                checkBigIntLiteralsInExpr(expr.condition, source, fileName)
                checkBigIntLiteralsInExpr(expr.whenTrue, source, fileName)
                checkBigIntLiteralsInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> expr.body.let { body ->
                when (body) {
                    is Block -> checkBigIntLiteralsInStmts(body.statements, source, fileName, ambient = false)
                    is Expression -> checkBigIntLiteralsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> expr.body.let {
                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
            }
            is AsExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is PostfixUnaryExpression -> checkBigIntLiteralsInExpr(expr.operand, source, fileName)
            is SpreadElement -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            is VoidExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkBigIntLiteralsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkBigIntLiteralsInExpr(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkBigIntLiteralsInExpr(it.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (el in expr.elements) checkBigIntLiteralsInExpr(el, source, fileName)
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is Constructor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is GetAccessor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is SetAccessor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is PropertyDeclaration -> m.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2437: Module hidden by local declaration
    // -----------------------------------------------------------------------

    private fun checkModuleHiddenByLocal() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkModuleHiddenInStmts(result.sourceFile.statements, source, fileName, result.locals)
        }
    }

    private fun checkModuleHiddenInStmts(
        stmts: List<Statement>, source: String, fileName: String,
        outerLocals: Map<String, Symbol>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        // Collect local variable names in this namespace
                        val localVarNames = mutableSetOf<String>()
                        for (s in body.statements) {
                            when (s) {
                                is VariableStatement -> {
                                    for (d in s.declarationList.declarations) {
                                        val name = d.name
                                        if (name is Identifier) localVarNames.add(name.text)
                                    }
                                }
                                else -> {}
                            }
                        }

                        // Check import equals declarations
                        for (s in body.statements) {
                            if (s is ImportEqualsDeclaration) {
                                val ref = s.moduleReference
                                if (ref is Identifier) {
                                    val refName = ref.text
                                    // Check if the referenced name is both:
                                    // 1. A local variable in this namespace
                                    // 2. A module/class/namespace in the outer scope
                                    if (refName in localVarNames) {
                                        val outerSymbol = outerLocals[refName] ?: globals[refName]
                                        if (outerSymbol != null && outerSymbol.flags.hasAny(
                                                SymbolFlags.Module or SymbolFlags.Class or SymbolFlags.ValueModule or SymbolFlags.NamespaceModule
                                            )) {
                                            val start = ref.pos
                                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                                            diagnostics.add(Diagnostic(
                                                message = "Module '$refName' is hidden by a local declaration with the same name.",
                                                category = DiagnosticCategory.Error,
                                                code = 2437,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = start,
                                                length = refName.length,
                                            ))
                                        }
                                    }
                                }
                            }
                        }

                        // Recurse into nested namespaces
                        val innerLocals = mutableMapOf<String, Symbol>()
                        innerLocals.putAll(outerLocals)
                        checkModuleHiddenInStmts(body.statements, source, fileName, innerLocals)
                    }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2714: Export assignment expression must be identifier in ambient context
    // -----------------------------------------------------------------------

    /**
     * In ambient contexts (.d.ts files, declare module bodies), `export default X` and
     * `export = X` require X to be an identifier or qualified name (A.B.C), not an
     * arbitrary expression like `2 + 2` or `typeof X`.
     */
    private fun checkAmbientExportAssignmentExpressions() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            val isAmbient = isDtsFile(fileName)
            // Check top-level statements
            checkAmbientExportAssignInStmts(result.sourceFile.statements, source, fileName, isAmbient)
        }
    }

    private fun checkAmbientExportAssignInStmts(
        stmts: List<Statement>, source: String, fileName: String, ambient: Boolean
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ExportAssignment -> {
                    if (!ambient) continue
                    val expr = stmt.expression
                    if (!isIdentifierOrQualifiedName(expr)) {
                        // Compute span: the expression itself
                        val exprStart = expressionTrueStart(expr, source)
                        val exprEnd = expressionTrueEnd(expr)
                        val length = maxOf(1, exprEnd - exprStart)
                        val (line, character) = getLineAndCharacterOfPosition(source, exprStart)
                        diagnostics.add(Diagnostic(
                            message = "The expression of an export assignment must be an identifier or qualified name in an ambient context.",
                            category = DiagnosticCategory.Error,
                            code = 2714,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exprStart,
                            length = length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    val isDeclare = ModifierFlag.Declare in stmt.modifiers
                    val name = stmt.name
                    // Ambient context if: already ambient, or this is `declare module "..."`, or `declare namespace`
                    val isStringLiteralModule = name is StringLiteralNode
                    val newAmbient = ambient || isDeclare || isStringLiteralModule
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkAmbientExportAssignInStmts(body.statements, source, fileName, newAmbient)
                    }
                }
                else -> {}
            }
        }
    }

    /**
     * Returns true if [expr] is an identifier or a chain of property accesses on identifiers
     * (i.e., a qualified name like `A.B.C.D`).
     */
    private fun isIdentifierOrQualifiedName(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> true
            is PropertyAccessExpression -> {
                // Check the chain: `A.B.C` where each part is an identifier
                var current: Expression = expr
                while (current is PropertyAccessExpression) {
                    current = current.expression
                }
                current is Identifier
            }
            else -> false
        }
    }

    /**
     * Returns the true start of an expression (skipping leading trivia).
     */
    private fun expressionTrueStart(expr: Expression, source: String): Int {
        var pos = expr.pos
        // Skip whitespace
        while (pos < source.length && source[pos].isWhitespace()) pos++
        return pos
    }

    // -----------------------------------------------------------------------
    // TS2458: Multiple AMD module name directives
    // -----------------------------------------------------------------------

    /**
     * In AMD modules, at most one `/// <amd-module name='...'/>` directive is allowed.
     * If a second one is found, emit TS2458.
     */
    private fun checkMultipleAmdModuleNames() {
        val amdModuleRegex = Regex("""<amd-module\s+name=['"][^'"]+['"]""")
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val lines = source.split('\n')
            var foundCount = 0
            var offset = 0
            for (line in lines) {
                val trimmed = line.trimStart()
                if (!trimmed.startsWith("///")) {
                    offset += line.length + 1
                    // directives only at top of file, but keep scanning all lines
                    // Actually TypeScript only scans until the first non-/// line
                    break
                }
                if (amdModuleRegex.containsMatchIn(trimmed)) {
                    foundCount++
                    if (foundCount == 2) {
                        // Emit TS2458 at the start of this line
                        val lineStart = offset
                        val lineEnd = offset + line.length
                        val (lineNum, character) = getLineAndCharacterOfPosition(source, lineStart)
                        diagnostics.add(Diagnostic(
                            message = "An AMD module cannot have multiple name assignments.",
                            category = DiagnosticCategory.Error,
                            code = 2458,
                            fileName = fileName,
                            line = lineNum,
                            character = character,
                            start = lineStart,
                            length = lineEnd - lineStart,
                        ))
                        break
                    }
                }
                offset += line.length + 1
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2725: Class name cannot be 'Object' with CJS/AMD/System/UMD module
    // -----------------------------------------------------------------------

    private fun checkObjectClassNameConflict() {
        // Only fires for CommonJS, AMD, System, or UMD modules
        val moduleName = when (options.effectiveModule) {
            ModuleKind.CommonJS -> "CommonJS"
            ModuleKind.AMD -> "AMD"
            ModuleKind.System -> "System"
            ModuleKind.UMD -> "UMD"
            else -> return
        }
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkObjectClassNameInStatements(result.sourceFile.statements, source, fileName, moduleName)
        }
    }

    private fun checkObjectClassNameInStatements(
        stmts: List<Statement>, source: String, fileName: String, moduleName: String
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Recurse into class member bodies for nested classes
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is Constructor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is GetAccessor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is SetAccessor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            else -> {}
                        }
                    }
                    val name = stmt.name
                    if (name != null && name.text == "Object") {
                        val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Class name cannot be 'Object' when targeting ES5 and above with module $moduleName.",
                            category = DiagnosticCategory.Error,
                            code = 2725,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkObjectClassNameInStatements(body.statements, source, fileName, moduleName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                is Block -> checkObjectClassNameInStatements(stmt.statements, source, fileName, moduleName)
                is IfStatement -> {
                    checkObjectClassNameInStatements(listOf(stmt.thenStatement), source, fileName, moduleName)
                    stmt.elseStatement?.let { checkObjectClassNameInStatements(listOf(it), source, fileName, moduleName) }
                }
                is ForStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is ForInStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is ForOfStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is WhileStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is DoStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkObjectClassNameInStatements(clause.statements, source, fileName, moduleName)
                            is DefaultClause -> checkObjectClassNameInStatements(clause.statements, source, fileName, moduleName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkObjectClassNameInStatements(stmt.tryBlock.statements, source, fileName, moduleName)
                    stmt.catchClause?.block?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                    stmt.finallyBlock?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                }
                is LabeledStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS4105: Private or protected member cannot be accessed on a type parameter
    // -----------------------------------------------------------------------

    private fun checkIndexedAccessPrivateMembers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkIndexedAccessPrivateInStatements(result.sourceFile.statements, source, fileName, emptyMap())
        }
    }

    private fun checkIndexedAccessPrivateInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        outerTpConstraints: Map<String, TypeNode>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is TypeAliasDeclaration -> {
                    val tpConstraints = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    walkTypeForIndexedAccess(stmt.type, tpConstraints, source, fileName)
                }
                is InterfaceDeclaration -> {
                    val tpConstraints = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    for (member in stmt.members) {
                        walkMemberForIndexedAccess(member, tpConstraints, source, fileName)
                    }
                }
                is ClassDeclaration -> {
                    val classTp = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    for (member in stmt.members) {
                        walkMemberForIndexedAccess(member, classTp, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkIndexedAccessPrivateInStatements(body.statements, source, fileName, outerTpConstraints)
                    }
                }
                is FunctionDeclaration -> {
                    val fnTp = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    stmt.body?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, fnTp) }
                }
                is Block -> checkIndexedAccessPrivateInStatements(stmt.statements, source, fileName, outerTpConstraints)
                is IfStatement -> {
                    checkIndexedAccessPrivateInStatements(listOf(stmt.thenStatement), source, fileName, outerTpConstraints)
                    stmt.elseStatement?.let { checkIndexedAccessPrivateInStatements(listOf(it), source, fileName, outerTpConstraints) }
                }
                is ForStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is ForInStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is ForOfStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is WhileStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is DoStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkIndexedAccessPrivateInStatements(clause.statements, source, fileName, outerTpConstraints)
                            is DefaultClause -> checkIndexedAccessPrivateInStatements(clause.statements, source, fileName, outerTpConstraints)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkIndexedAccessPrivateInStatements(stmt.tryBlock.statements, source, fileName, outerTpConstraints)
                    stmt.catchClause?.block?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, outerTpConstraints) }
                    stmt.finallyBlock?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, outerTpConstraints) }
                }
                is LabeledStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                else -> {}
            }
        }
    }

    private fun collectTpConstraints(tps: List<TypeParameter>?): Map<String, TypeNode> {
        if (tps.isNullOrEmpty()) return emptyMap()
        val m = mutableMapOf<String, TypeNode>()
        for (tp in tps) {
            val c = tp.constraint
            if (c != null) m[tp.name.text] = c
        }
        return m
    }

    private fun walkMemberForIndexedAccess(
        member: Node, outerTp: Map<String, TypeNode>,
        source: String, fileName: String,
    ) {
        when (member) {
            is PropertyDeclaration -> member.type?.let { walkTypeForIndexedAccess(it, outerTp, source, fileName) }
            is MethodDeclaration -> {
                val methodTp = outerTp + collectTpConstraints(member.typeParameters)
                for (p in member.parameters) p.type?.let { walkTypeForIndexedAccess(it, methodTp, source, fileName) }
                member.type?.let { walkTypeForIndexedAccess(it, methodTp, source, fileName) }
            }
            else -> {}
        }
    }

    private fun walkTypeForIndexedAccess(
        type: TypeNode, tpConstraints: Map<String, TypeNode>,
        source: String, fileName: String,
    ) {
        when (type) {
            is IndexedAccessType -> {
                walkTypeForIndexedAccess(type.objectType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.indexType, tpConstraints, source, fileName)
                val keyLit = type.indexType as? LiteralType ?: return
                val keyStr = (keyLit.literal as? StringLiteralNode)?.text ?: return
                if (indexedAccessHasPrivateMember(type.objectType, keyStr, tpConstraints, mutableSetOf())) {
                    val closeIdx = source.indexOf(']', type.indexType.pos)
                    if (closeIdx < 0) return
                    val start = type.pos
                    val length = closeIdx + 1 - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Private or protected member '$keyStr' cannot be accessed on a type parameter.",
                        category = DiagnosticCategory.Error,
                        code = 4105,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is UnionType -> type.types.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is IntersectionType -> type.types.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is ParenthesizedType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is ArrayType -> walkTypeForIndexedAccess(type.elementType, tpConstraints, source, fileName)
            is TupleType -> type.elements.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is TypeOperator -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is FunctionType -> {
                val innerTp = tpConstraints + collectTpConstraints(type.typeParameters)
                for (p in type.parameters) p.type?.let { walkTypeForIndexedAccess(it, innerTp, source, fileName) }
                walkTypeForIndexedAccess(type.type, innerTp, source, fileName)
            }
            is ConstructorType -> {
                val innerTp = tpConstraints + collectTpConstraints(type.typeParameters)
                for (p in type.parameters) p.type?.let { walkTypeForIndexedAccess(it, innerTp, source, fileName) }
                walkTypeForIndexedAccess(type.type, innerTp, source, fileName)
            }
            is ConditionalType -> {
                walkTypeForIndexedAccess(type.checkType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.extendsType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.trueType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.falseType, tpConstraints, source, fileName)
            }
            is MappedType -> {
                type.type?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
                type.nameType?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
                type.typeParameter.constraint?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            }
            is TypeLiteral -> for (m in type.members) walkMemberForIndexedAccess(m, tpConstraints, source, fileName)
            is RestType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is OptionalType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is NamedTupleMember -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            else -> {}
        }
    }

    /** Returns true if [typeNode] (object side of an IndexedAccessType) refers to at
     * least one class with a private/protected member named [propName]. An intersection
     * constraint returns false — TS allows indexed access through intersection. */
    /**
     * Returns true when [typeNode] names a TYPE PARAMETER (or contains one in a
     * union) whose constraint exposes a private/protected member named [propName].
     * Direct class/interface references that happen to have a same-named private
     * member do NOT count — TS4105's message ("cannot be accessed on a type
     * parameter") only applies when the access is THROUGH a type parameter.
     * `(Foo | Bar)["foo"]` where Foo/Bar are concrete classes with `protected foo`
     * should fire TS2339, not TS4105.
     */
    private fun indexedAccessHasPrivateMember(
        typeNode: TypeNode, propName: String,
        tpConstraints: Map<String, TypeNode>, visited: MutableSet<String>,
    ): Boolean {
        return when (typeNode) {
            is ParenthesizedType -> indexedAccessHasPrivateMember(typeNode.type, propName, tpConstraints, visited)
            is UnionType -> typeNode.types.any { indexedAccessHasPrivateMember(it, propName, tpConstraints, visited) }
            is IntersectionType -> false
            is TypeReference -> {
                val baseName = (typeNode.typeName as? Identifier)?.text ?: return false
                val constraint = tpConstraints[baseName] ?: return false
                if (baseName in visited) return false
                visited.add(baseName)
                val r = constraintHasPrivatePropByName(constraint, propName)
                visited.remove(baseName)
                r
            }
            else -> false
        }
    }

    /**
     * Walks a type-parameter constraint to determine whether it exposes a
     * private/protected member named [propName]. Used by TS4105: the constraint
     * (e.g. `T extends A`) is what determines whether T["x"] would access a
     * private member. Walks through Parenthesized/Union/Intersection wrappers.
     */
    private fun constraintHasPrivatePropByName(typeNode: TypeNode, propName: String): Boolean = when (typeNode) {
        is ParenthesizedType -> constraintHasPrivatePropByName(typeNode.type, propName)
        is UnionType -> typeNode.types.any { constraintHasPrivatePropByName(it, propName) }
        // IntersectionType constraint: TypeScript treats `T extends A & B` indexed
        // access as compatible — the intersection has "merged" access. Do NOT fire
        // TS4105 here (mirrors the pre-existing IntersectionType -> false rule).
        is IntersectionType -> false
        is TypeReference -> {
            val baseName = (typeNode.typeName as? Identifier)?.text
            if (baseName != null) classOrInterfaceHasPrivatePropByName(baseName, propName) else false
        }
        else -> false
    }

    private fun classOrInterfaceHasPrivatePropByName(className: String, propName: String): Boolean {
        val sym = globals[className] ?: return false
        for (decl in sym.declarations ?: emptyList()) {
            when (decl) {
                is ClassDeclaration -> {
                    for (m in decl.members) {
                        val memberName = when (m) {
                            is PropertyDeclaration -> (m.name as? Identifier)?.text
                            is MethodDeclaration -> (m.name as? Identifier)?.text
                            is GetAccessor -> (m.name as? Identifier)?.text
                            is SetAccessor -> (m.name as? Identifier)?.text
                            else -> null
                        }
                        if (memberName != propName) continue
                        val modifiers = when (m) {
                            is PropertyDeclaration -> m.modifiers
                            is MethodDeclaration -> m.modifiers
                            is GetAccessor -> m.modifiers
                            is SetAccessor -> m.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Private in modifiers || ModifierFlag.Protected in modifiers) return true
                    }
                }
                else -> {}
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2393: Duplicate function implementation (cross-file)
    // -----------------------------------------------------------------------

    private fun checkCrossFileDuplicateFunction() {
        // Only check when using outFile (bundle mode) — separate module files have their own scope
        if (options.outFile == null) return

        // Collect top-level function names with bodies across non-module files
        // Map: function name → list of (fileName, position, nameLength)
        val funcDecls = mutableMapOf<String, MutableList<Triple<String, Int, Int>>>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            // Skip module files — they have their own scope
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is FunctionDeclaration && stmt.body != null) {
                    val name = stmt.name?.text ?: continue
                    funcDecls.getOrPut(name) { mutableListOf() }.add(
                        Triple(fileName, stmt.name!!.pos, name.length)
                    )
                }
            }
        }

        // Emit TS2393 for duplicate implementations
        for ((name, decls) in funcDecls) {
            if (decls.size < 2) continue
            // Emit on all .ts declarations (not .js)
            for ((fileName, pos, length) in decls) {
                if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
                val source = binderResults.first { it.sourceFile.fileName == fileName }.sourceFile.text
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "Duplicate function implementation.",
                    category = DiagnosticCategory.Error,
                    code = 2393,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = pos,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2300 / TS2451 cross-file: unified identifier conflicts (B93)
    // -----------------------------------------------------------------------

    /**
     * B93: Unified cross-file duplicate-identifier conflicts for top-level declarations
     * in script (non-module) files that MIX a CLASS / TYPE-ALIAS with CONST/LET (or have
     * multiple type-aliases). These are the cases the per-kind checkers miss:
     *  - [checkCrossFileBlockScopedDuplicates] (73b) handles pure const/let/var but not a
     *    class sharing the name, and emits no TS6204 follow-on for 3+ files.
     *  - [checkCrossFileClassConflicts] (73g) handles pure class-vs-class only.
     *  - No checker handled cross-file type-alias conflicts at all.
     *
     * TypeScript reports these PER SPACE (value-space / type-space) with a HUB model: the
     * FIRST-processed declaration occupying the conflicting space is the hub; its
     * diagnostic accumulates a related TS6203 (first other) then TS6204 (subsequent
     * others), and each other declaration points back at the hub (TS6203). The code is
     * TS2451 when any conflicting value-space decl is block-scoped (const/let), else
     * TS2300; type-space conflicts are always TS2300. (This mirrors TypeScript's
     * `mergeSymbol` amalgamation where the first-merged file's declaration stays the
     * persistent target and `lookupOrIssueError` dedup accumulates the related infos.)
     *
     * Gate is narrow to keep the FP surface minimal:
     *  - every declaration of the name is a class / type-alias / const / let (names that
     *    also have a var / function / interface / namespace / enum decl have merge
     *    semantics and are left to their own checkers);
     *  - at most ONE class decl (≥2 classes → pure class-vs-class is 73g's job);
     *  - the name must involve a type-alias OR a class+block-scoped mix (pure const/let →
     *    73b). Block-scoped names emitted here are recorded in
     *    [crossFileIdentifierHandledBlockNames] so 73b skips them.
     */
    private fun checkCrossFileIdentifierConflicts() {
        // One tracked declaration. kind ∈ {"class","typeAlias","const","let"}.
        class IdDecl(
            val name: String, val nameNode: Node, val fileName: String,
            val source: String, val kind: String,
        )
        val byName = mutableMapOf<String, MutableList<IdDecl>>()
        // Names that also have a merge-semantics decl (var/function/interface/namespace/
        // enum) at top level in a script file → bail (leave to their own checkers).
        val bailNames = mutableSetOf<String>()

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> stmt.name?.let {
                        if (it.text.isNotEmpty())
                            byName.getOrPut(it.text) { mutableListOf() }
                                .add(IdDecl(it.text, it, fileName, source, "class"))
                    }
                    is TypeAliasDeclaration -> {
                        val n = stmt.name
                        if (n.text.isNotEmpty())
                            byName.getOrPut(n.text) { mutableListOf() }
                                .add(IdDecl(n.text, n, fileName, source, "typeAlias"))
                    }
                    is VariableStatement -> {
                        val kind = when (stmt.declarationList.flags) {
                            SyntaxKind.ConstKeyword -> "const"
                            SyntaxKind.LetKeyword -> "let"
                            else -> null  // var → merge semantics
                        }
                        for (decl in stmt.declarationList.declarations) {
                            val n = decl.name as? Identifier ?: continue
                            if (n.text.isEmpty()) continue
                            if (kind == null) bailNames.add(n.text)
                            else byName.getOrPut(n.text) { mutableListOf() }
                                .add(IdDecl(n.text, n, fileName, source, kind))
                        }
                    }
                    is FunctionDeclaration -> stmt.name?.let { bailNames.add(it.text) }
                    is InterfaceDeclaration -> bailNames.add(stmt.name.text)
                    is EnumDeclaration -> bailNames.add(stmt.name.text)
                    is ModuleDeclaration -> (stmt.name as? Identifier)?.let { bailNames.add(it.text) }
                    else -> {}
                }
            }
        }

        for ((name, decls) in byName) {
            if (name in bailNames) continue
            if (decls.size < 2) continue
            if (decls.map { it.fileName }.distinct().size < 2) continue
            val classCount = decls.count { it.kind == "class" }
            if (classCount >= 2) continue  // pure/partial class-vs-class → 73g
            val typeAliasCount = decls.count { it.kind == "typeAlias" }
            val hasBlock = decls.any { it.kind == "const" || it.kind == "let" }
            // Must involve a type-alias OR a class+block-scoped mix; pure const/let → 73b.
            if (typeAliasCount == 0 && !(classCount > 0 && hasBlock)) continue

            // value-space occupiers: class, const, let.
            val valueDecls = decls.filter { it.kind == "class" || it.kind == "const" || it.kind == "let" }
            // type-space occupiers: class, type-alias.
            val typeDecls = decls.filter { it.kind == "class" || it.kind == "typeAlias" }

            if (valueDecls.size >= 2 && valueDecls.map { it.fileName }.distinct().size >= 2) {
                val anyBlock = valueDecls.any { it.kind == "const" || it.kind == "let" }
                if (anyBlock) crossFileIdentifierHandledBlockNames.add(name)
                emitCrossFileHubDuplicates(
                    valueDecls.map { CrossFileDupDecl(it.name, it.nameNode, it.fileName, it.source) },
                    if (anyBlock) 2451 else 2300,
                    if (anyBlock) "Cannot redeclare block-scoped variable '$name'."
                    else "Duplicate identifier '$name'.",
                )
            }
            if (typeDecls.size >= 2 && typeDecls.map { it.fileName }.distinct().size >= 2) {
                emitCrossFileHubDuplicates(
                    typeDecls.map { CrossFileDupDecl(it.name, it.nameNode, it.fileName, it.source) },
                    2300, "Duplicate identifier '$name'.",
                )
            }
        }
    }

    /**
     * Emit a cross-file duplicate-identifier conflict with the HUB model (B93): the first
     * declaration in [ordered] (source-processing order) is the hub. The hub's diagnostic
     * relates to each other declaration — TS6203 for the first, TS6204 for the rest. Each
     * other declaration relates back to the hub with a single TS6203.
     */
    private fun emitCrossFileHubDuplicates(ordered: List<CrossFileDupDecl>, code: Int, message: String) {
        if (ordered.size < 2) return
        fun related(targets: List<CrossFileDupDecl>): List<Diagnostic> =
            targets.mapIndexed { idx, other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = if (idx == 0) "'${other.name}' was also declared here." else "and here.",
                    category = DiagnosticCategory.Message,
                    code = if (idx == 0) 6203 else 6204,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
        fun emitOne(decl: CrossFileDupDecl, rel: List<Diagnostic>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            diagnostics.add(Diagnostic(
                message = message,
                category = DiagnosticCategory.Error, code = code,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }
        val hub = ordered.first()
        val others = ordered.drop(1)
        emitOne(hub, related(others))
        for (o in others) emitOne(o, related(listOf(hub)))
    }

    // -----------------------------------------------------------------------
    // TS2451 cross-file: block-scoped variable redeclarations across files
    // -----------------------------------------------------------------------

    /**
     * Check for top-level `let`/`const` redeclarations across non-module files.
     * When multiple non-module files share the global scope, a `let`/`const` in one file
     * conflicts with any same-named `let`, `const`, or `var` in another file.
     * Both files get TS2451 with TS6203 related info pointing to the other file.
     */
    private fun checkCrossFileBlockScopedDuplicates() {
        // Collect top-level let/const/var names from non-module files
        // Map: name → list of (fileName, nameStart, nameLength, isBlockScoped)
        data class VarInfo(val fileName: String, val nameStart: Int, val nameLength: Int, val isBlockScoped: Boolean)
        val varDecls = mutableMapOf<String, MutableList<VarInfo>>()

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip module files — they have their own scope
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                val isBlockScoped = stmt.declarationList.flags == SyntaxKind.LetKeyword ||
                    stmt.declarationList.flags == SyntaxKind.ConstKeyword
                for (decl in stmt.declarationList.declarations) {
                    val name = decl.name as? Identifier ?: continue
                    if (name.text.isEmpty()) continue
                    varDecls.getOrPut(name.text) { mutableListOf() }.add(
                        VarInfo(fileName, name.pos, name.text.length, isBlockScoped)
                    )
                }
            }
        }

        // Emit TS2451 for names that appear in multiple files where at least one is block-scoped
        for ((name, infos) in varDecls) {
            if (infos.size < 2) continue
            // B93: skip names whose value-space conflict the unified checker already emitted
            // (those that also have a cross-file class/type-alias declaration).
            if (name in crossFileIdentifierHandledBlockNames) continue
            val anyBlockScoped = infos.any { it.isBlockScoped }
            if (!anyBlockScoped) continue  // only var+var conflicts are TS2300, not TS2451

            // Check for duplicates: skip if all declarations are in the same file
            val fileNames = infos.map { it.fileName }.toSet()
            if (fileNames.size < 2) continue

            // Emit TS2451 for each declaration, with TS6203 pointing to the other declaration(s)
            for (info in infos) {
                val source = binderResults.first { it.sourceFile.fileName == info.fileName }.sourceFile.text
                val (line, character) = getLineAndCharacterOfPosition(source, info.nameStart)
                // Related info: one TS6203 per OTHER file declaring the same name
                val relatedInfo = infos
                    .filter { it.fileName != info.fileName }
                    .map { other ->
                        val otherSource = binderResults.first { it.sourceFile.fileName == other.fileName }.sourceFile.text
                        val (otherLine, otherChar) = getLineAndCharacterOfPosition(otherSource, other.nameStart)
                        Diagnostic(
                            message = "'$name' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = other.fileName,
                            line = otherLine,
                            character = otherChar,
                            start = other.nameStart,
                            length = other.nameLength,
                        )
                    }
                diagnostics.add(Diagnostic(
                    message = "Cannot redeclare block-scoped variable '$name'.",
                    category = DiagnosticCategory.Error,
                    code = 2451,
                    fileName = info.fileName,
                    line = line,
                    character = character,
                    start = info.nameStart,
                    length = info.nameLength,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * 17.108: Cross-file detection of enum-merge conflicts (TS2567).
     *
     * The per-file [checkDuplicateDeclarations] walker only sees declarations
     * within a single file's top-level. When two non-module (script) files
     * share global scope and one declares `enum X` while another declares
     * `class X` / `function X` / `var X` / `interface X`, the merged group
     * is invalid and TS2567 must fire on each non-namespace declaration with
     * TS6203 related info pointing to the cross-file partner(s).
     *
     * Skip:
     *  - module files (separate scope per file)
     *  - .d.ts files (per-file walker also skips them)
     *  - declarations whose own file ALREADY has an enum + non-enum/non-namespace
     *    pair — the per-file walker already emits TS2567 on those positions.
     */
    private fun checkCrossFileEnumConflicts() {
        data class XInfo(
            val name: String, val kind: String,
            val nameNode: Node, val fileName: String, val source: String,
        )
        val byName = mutableMapOf<String, MutableList<XInfo>>()

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is EnumDeclaration -> byName.getOrPut(stmt.name.text) { mutableListOf() }
                        .add(XInfo(stmt.name.text, "enum", stmt.name, fileName, source))
                    is ClassDeclaration -> stmt.name?.let {
                        byName.getOrPut(it.text) { mutableListOf() }
                            .add(XInfo(it.text, "class", it, fileName, source))
                    }
                    is FunctionDeclaration -> stmt.name?.let {
                        byName.getOrPut(it.text) { mutableListOf() }
                            .add(XInfo(it.text, "function", it, fileName, source))
                    }
                    is InterfaceDeclaration -> byName.getOrPut(stmt.name.text) { mutableListOf() }
                        .add(XInfo(stmt.name.text, "interface", stmt.name, fileName, source))
                    is ModuleDeclaration -> {
                        val n = stmt.name as? Identifier ?: continue
                        byName.getOrPut(n.text) { mutableListOf() }
                            .add(XInfo(n.text, "namespace", n, fileName, source))
                    }
                    is VariableStatement -> {
                        if (stmt.declarationList.flags != SyntaxKind.VarKeyword) continue
                        for (decl in stmt.declarationList.declarations) {
                            val n = decl.name as? Identifier ?: continue
                            if (n.text.isEmpty()) continue
                            byName.getOrPut(n.text) { mutableListOf() }
                                .add(XInfo(n.text, "var", n, fileName, source))
                        }
                    }
                    else -> {}
                }
            }
        }

        for ((_, infos) in byName) {
            if (infos.size < 2) continue
            // Need cross-file presence
            if (infos.map { it.fileName }.toSet().size < 2) continue
            // Need an enum + non-enum/non-namespace partner across the global merged group
            val hasEnum = infos.any { it.kind == "enum" }
            val nonEnumKinds = setOf("class", "function", "var", "interface")
            val hasNonEnum = infos.any { it.kind in nonEnumKinds }
            if (!(hasEnum && hasNonEnum)) continue

            for (info in infos) {
                if (info.kind == "namespace") continue
                // Skip if the per-file walker already emits for this position:
                // its own file's local group has both enum and non-enum.
                val sameFile = infos.filter { it.fileName == info.fileName }
                val sameFileHasEnum = sameFile.any { it.kind == "enum" }
                val sameFileHasNonEnum = sameFile.any { it.kind in nonEnumKinds }
                if (sameFileHasEnum && sameFileHasNonEnum) continue

                val others = infos.filter { it.fileName != info.fileName && it.kind != "namespace" }
                if (others.isEmpty()) continue
                val relatedInfo = others.map { other ->
                    val (oLine, oChar) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                    Diagnostic(
                        message = "'${other.name}' was also declared here.",
                        category = DiagnosticCategory.Message,
                        code = 6203,
                        fileName = other.fileName,
                        line = oLine,
                        character = oChar,
                        start = other.nameNode.pos,
                        length = other.name.length,
                    )
                }
                val (line, character) = getLineAndCharacterOfPosition(info.source, info.nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Enum declarations can only merge with namespace or other enum declarations.",
                    category = DiagnosticCategory.Error,
                    code = 2567,
                    fileName = info.fileName,
                    line = line,
                    character = character,
                    start = info.nameNode.pos,
                    length = info.name.length,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * B92: Cross-file duplicate-identifier conflicts for MERGED interface members.
     *
     * When the same interface name is declared in two different files that share a
     * scope — global script scope, a `declare global { }` block, or a
     * `declare module "X" { }` block — and a member appears as a PROPERTY in one
     * file and a METHOD in another, the merged interface has a duplicate-identifier
     * conflict (property-vs-method is always a hard conflict in TypeScript).
     *
     * TypeScript amalgamates these per ordered file-pair: when FEWER THAN 8 member
     * names conflict, it emits per-member TS2300 "Duplicate identifier 'X'." with a
     * related TS6203 "'X' was also declared here." pointing to the other file's
     * member. When 8 OR MORE names conflict, it COLLAPSES to a single TS6200 per
     * file ("Definitions of the following identifiers conflict ...: a, b, c") at the
     * file's first non-trivia token, with a related TS6201 "Conflicts are in this
     * file." pointing at the other file's first token. (TypeScript's threshold is
     * `conflictingSymbols.size < 8` → per-member, else collapsed.)
     *
     * Gate is narrow (property-vs-method, cross-file, same interface name in a shared
     * scope) so the FP surface is tiny: such a pairing is always a genuine error.
     */
    private fun checkCrossFileInterfaceMemberConflicts() {
        // A merged-interface member declaration site.
        data class MemberDecl(
            val memberName: String,
            val nameNode: Node,   // member name node (for the squiggle)
            val isMethod: Boolean,
            val fileName: String,
            val source: String,
        )
        // scopeKey -> (interfaceName -> member decls across files). scopeKey is
        // "global" for script/`declare global` interfaces, "module:<spec>" for
        // ambient-module interfaces. Namespace-scoped interfaces are excluded
        // (they do not merge across files).
        val groups = mutableMapOf<String, MutableMap<String, MutableList<MemberDecl>>>()
        val fileSources = mutableMapOf<String, String>()

        fun addInterface(scopeKey: String, iface: InterfaceDeclaration, fileName: String, source: String) {
            val list = groups.getOrPut(scopeKey) { mutableMapOf() }
                .getOrPut(iface.name.text) { mutableListOf() }
            for (member in iface.members) {
                val (nameNode, isMethod) = when (member) {
                    is PropertyDeclaration -> member.name to false
                    is MethodDeclaration -> member.name to true
                    else -> continue
                }
                val text = getMemberNameText(nameNode) ?: continue
                if (text.isEmpty() || text == "new") continue
                list.add(MemberDecl(text, nameNode, isMethod, fileName, source))
            }
        }

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            fileSources[fileName] = source
            val isModule = isModuleFile(result.sourceFile.statements)
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is InterfaceDeclaration ->
                        // A top-level interface merges into the global scope only in
                        // script files; in module files it is module-local.
                        if (!isModule) addInterface("global", stmt, fileName, source)
                    is ModuleDeclaration -> {
                        val body = stmt.body as? ModuleBlock ?: continue
                        val nm = stmt.name
                        when {
                            nm is Identifier && nm.text == "global" ->
                                for (inner in body.statements)
                                    if (inner is InterfaceDeclaration) addInterface("global", inner, fileName, source)
                            nm is StringLiteralNode ->
                                for (inner in body.statements)
                                    if (inner is InterfaceDeclaration)
                                        addInterface("module:" + nm.text, inner, fileName, source)
                            else -> {}
                        }
                    }
                    else -> {}
                }
            }
        }

        // Build conflicting member declarations (property-vs-method, cross-file).
        val entries = mutableListOf<CrossFileDupDecl>()
        for ((_, byIface) in groups) {
            for ((_, members) in byIface) {
                for ((_, decls) in members.groupBy { it.memberName }) {
                    val distinctFiles = decls.map { it.fileName }.distinct()
                    if (distinctFiles.size != 2) continue   // only the common 2-file case
                    // Cross-file property-vs-method conflict: a property in one file
                    // and a method in another (different) file.
                    val propFiles = decls.filter { !it.isMethod }.map { it.fileName }.toSet()
                    val methFiles = decls.filter { it.isMethod }.map { it.fileName }.toSet()
                    val crossConflict = propFiles.any { pf -> methFiles.any { mf -> pf != mf } }
                    if (!crossConflict) continue
                    for (d in decls) entries.add(CrossFileDupDecl(d.memberName, d.nameNode, d.fileName, d.source))
                }
            }
        }
        amalgamateAndEmitCrossFileDuplicates(entries)
    }

    /** One conflicting declaration site for cross-file duplicate-identifier reporting. */
    private class CrossFileDupDecl(
        val name: String,
        val nameNode: Node,
        val fileName: String,
        val source: String,
    )

    /**
     * Shared amalgamation + emission for cross-file duplicate-identifier conflicts
     * (B92). [entries] are the conflicting declaration sites; the caller has already
     * decided they conflict. Groups by name, restricts to the common 2-distinct-file
     * case, amalgamates per ordered file-pair, then for each pair: when FEWER THAN 8
     * names conflict → per-member TS2300 "Duplicate identifier 'X'." + related TS6203
     * "'X' was also declared here."; when 8 OR MORE → collapsed TS6200 "Definitions of
     * the following identifiers conflict ...: a, b, c" at the file's first non-trivia
     * token + related TS6201 "Conflicts are in this file." (TypeScript's threshold is
     * `conflictingSymbols.size < 8`.)
     */
    private fun amalgamateAndEmitCrossFileDuplicates(entries: List<CrossFileDupDecl>) {
        if (entries.isEmpty()) return
        val fileSources = mutableMapOf<String, String>()
        for (e in entries) fileSources.getOrPut(e.fileName) { e.source }

        class PairConflict(val firstFile: String, val secondFile: String) {
            val names = mutableListOf<String>()
            val firstLocs = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
            val secondLocs = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
        }
        val amalgam = mutableMapOf<String, PairConflict>()

        for ((name, decls) in entries.groupBy { it.name }) {
            val distinctFiles = decls.map { it.fileName }.distinct()
            if (distinctFiles.size != 2) continue
            val (fA, fB) = distinctFiles.sorted()
            val pc = amalgam.getOrPut("$fA|$fB") { PairConflict(fA, fB) }
            if (name !in pc.names) pc.names.add(name)
            pc.firstLocs.getOrPut(name) { mutableListOf() }.addAll(decls.filter { it.fileName == fA })
            pc.secondLocs.getOrPut(name) { mutableListOf() }.addAll(decls.filter { it.fileName == fB })
        }

        fun emit2300(decl: CrossFileDupDecl, related: List<CrossFileDupDecl>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            val rel = related.map { other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = "'${decl.name}' was also declared here.",
                    category = DiagnosticCategory.Message, code = 6203,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
            diagnostics.add(Diagnostic(
                message = "Duplicate identifier '${decl.name}'.",
                category = DiagnosticCategory.Error, code = 2300,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }

        fun emit6200(thisFile: String, otherFile: String, list: String) {
            val thisSrc = fileSources[thisFile] ?: return
            val otherSrc = fileSources[otherFile] ?: return
            val (tStart, tLen) = firstTokenSpanOfFile(thisSrc)
            val (oStart, oLen) = firstTokenSpanOfFile(otherSrc)
            val (tLine, tCh) = getLineAndCharacterOfPosition(thisSrc, tStart)
            val (oLine, oCh) = getLineAndCharacterOfPosition(otherSrc, oStart)
            diagnostics.add(Diagnostic(
                message = "Definitions of the following identifiers conflict with those in another file: $list",
                category = DiagnosticCategory.Error, code = 6200,
                fileName = thisFile, line = tLine, character = tCh, start = tStart, length = tLen,
                relatedInformation = listOf(Diagnostic(
                    message = "Conflicts are in this file.",
                    category = DiagnosticCategory.Message, code = 6201,
                    fileName = otherFile, line = oLine, character = oCh, start = oStart, length = oLen,
                )),
            ))
        }

        for ((_, pc) in amalgam) {
            if (pc.names.size < 8) {
                for (name in pc.names) {
                    val firstNodes = pc.firstLocs[name] ?: emptyList()
                    val secondNodes = pc.secondLocs[name] ?: emptyList()
                    for (fn in firstNodes) emit2300(fn, secondNodes)
                    for (sn in secondNodes) emit2300(sn, firstNodes)
                }
            } else {
                val list = pc.names.joinToString(", ")
                emit6200(pc.firstFile, pc.secondFile, list)
                emit6200(pc.secondFile, pc.firstFile, list)
            }
        }
    }

    /**
     * B92d: Cross-file duplicate-identifier conflicts for top-level CLASS declarations
     * in script (non-module) files sharing the global scope. Two same-named class
     * declarations in different script files always conflict (classes never merge with
     * classes), so this is a genuine TS2300 — collapsed to TS6200 when >= 8 names
     * conflict (e.g. `class A..I` in two files). Restricted to script files (module
     * files are scoped separately) and the 2-distinct-file case to keep FP surface
     * minimal. Class-vs-interface / class-vs-namespace MERGES are unaffected (only the
     * class-vs-class pair conflicts; an interface/namespace partner does not rescue it).
     */
    private fun checkCrossFileClassConflicts() {
        val byName = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is ClassDeclaration) {
                    val nm = stmt.name ?: continue
                    if (nm.text.isEmpty()) continue
                    byName.getOrPut(nm.text) { mutableListOf() }
                        .add(CrossFileDupDecl(nm.text, nm, fileName, source))
                }
            }
        }
        val entries = mutableListOf<CrossFileDupDecl>()
        for ((_, decls) in byName) {
            // Conflict only when the SAME class name is declared in 2 different files.
            if (decls.map { it.fileName }.distinct().size != 2) continue
            entries.addAll(decls)
        }
        amalgamateAndEmitCrossFileDuplicates(entries)
    }

    /**
     * B92d: TS2451 for a block-scoped `export const`/`export let` that is re-declared
     * via `declare module "X"` augmentation(s) of the SAME file-module (which already
     * exports it), or across two augmentations of the same module. Re-declaring an
     * existing block-scoped export through an augmentation is illegal. The original
     * declaration is the "hub": its diagnostic accumulates a related TS6203 (then
     * TS6204 for each subsequent) pointing at each augmentation re-declaration; each
     * augmentation re-declaration points back at the hub (TS6203). The existing
     * `checkCrossFileBlockScopedDuplicates` (step 73b) skips module files, so there is
     * no double-emit. Gate is narrow (augmentation re-declaring an existing
     * block-scoped file-module export) → tiny FP surface.
     */
    private fun checkCrossFileModuleAugmentationDuplicates() {
        class Decl(val name: String, val nameNode: Node, val fileName: String, val source: String)
        fun isBlockScopedExport(stmt: VariableStatement): Boolean =
            ModifierFlag.Export in stmt.modifiers &&
                (stmt.declarationList.flags == SyntaxKind.LetKeyword ||
                    stmt.declarationList.flags == SyntaxKind.ConstKeyword)

        // A file-module's OWN top-level block-scoped exports: moduleFile -> (name -> Decl).
        val ownExports = mutableMapOf<String, MutableMap<String, Decl>>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && isBlockScopedExport(stmt)) {
                    for (d in stmt.declarationList.declarations) {
                        val nm = d.name as? Identifier ?: continue
                        ownExports.getOrPut(fileName) { mutableMapOf() }[nm.text] =
                            Decl(nm.text, nm, fileName, source)
                    }
                }
            }
        }

        // Augmentation block-scoped exports grouped by (targetFile, name), in source order.
        val augByTarget = mutableMapOf<Pair<String, String>, MutableList<Decl>>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val spec = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                val target = resolveModuleSpecifierRelative(spec, fileName) ?: continue
                for (inner in body.statements) {
                    if (inner is VariableStatement && isBlockScopedExport(inner)) {
                        for (d in inner.declarationList.declarations) {
                            val nm = d.name as? Identifier ?: continue
                            augByTarget.getOrPut(target to nm.text) { mutableListOf() }
                                .add(Decl(nm.text, nm, fileName, source))
                        }
                    }
                }
            }
        }

        fun emit2451(decl: Decl, related: List<Decl>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            val rel = related.mapIndexed { idx, other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = if (idx == 0) "'${decl.name}' was also declared here." else "and here.",
                    category = DiagnosticCategory.Message,
                    code = if (idx == 0) 6203 else 6204,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
            diagnostics.add(Diagnostic(
                message = "Cannot redeclare block-scoped variable '${decl.name}'.",
                category = DiagnosticCategory.Error, code = 2451,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }

        for ((key, augs) in augByTarget) {
            val (target, name) = key
            val own = ownExports[target]?.get(name)
            val total = (if (own != null) 1 else 0) + augs.size
            if (total < 2) continue   // single declaration: a valid augmentation, no conflict
            val hub: Decl
            val others: List<Decl>
            if (own != null) {
                hub = own
                others = augs
            } else {
                hub = augs.first()
                others = augs.drop(1)
            }
            emit2451(hub, others)
            for (o in others) emit2451(o, listOf(hub))
        }
    }

    /**
     * Span of the first non-trivia token in [source] (start position + length).
     * Mirrors TypeScript's `getSpanOfTokenAtPosition(sourceFile, skipTrivia(text, 0))`
     * used when a diagnostic is reported on a whole SourceFile node (e.g. TS6200).
     * Skips whitespace, line comments (`//`, `///`) and block comments, then reads
     * the leading identifier/keyword run (e.g. `interface`, `class`, `declare`).
     */
    private fun firstTokenSpanOfFile(source: String): Pair<Int, Int> {
        var i = 0
        val n = source.length
        loop@ while (i < n) {
            when (source[i]) {
                ' ', '\t', '\r', '\n', '\u000B', '\u000C', '\u00A0', '\uFEFF' -> i++
                '/' -> when {
                    i + 1 < n && source[i + 1] == '/' -> {
                        i += 2
                        while (i < n && source[i] != '\n' && source[i] != '\r') i++
                    }
                    i + 1 < n && source[i + 1] == '*' -> {
                        i += 2
                        while (i + 1 < n && !(source[i] == '*' && source[i + 1] == '/')) i++
                        i = (i + 2).coerceAtMost(n)
                    }
                    else -> break@loop
                }
                else -> break@loop
            }
        }
        val start = i
        if (i >= n) return start to 0
        val c0 = source[i]
        if (c0.isLetter() || c0 == '_' || c0 == '$') {
            var j = i + 1
            while (j < n && (source[j].isLetterOrDigit() || source[j] == '_' || source[j] == '$')) j++
            return start to (j - start)
        }
        return start to 1
    }

    /**
     * Resolved declaration of a name in a module file, following `export * from`
     * and `export { X } from` re-export chains.
     */
    private class ReexportedDecl(
        val stmt: Statement, val nameNode: Node, val fileName: String, val source: String,
    )

    /**
     * Find the declaration of [name] exported (possibly re-exported) by [fileName].
     * Follows `export * from "Y"` and `export { name } from "Y"` chains. Returns the
     * concrete declaration (class/function/interface/enum/var) or null.
     */
    private fun findExportedDeclAcrossReexports(
        fileName: String, name: String, visited: MutableSet<String>,
    ): ReexportedDecl? {
        if (!visited.add(fileName)) return null
        val res = fileResults[fileName] ?: return null
        val source = res.sourceFile.text
        // Direct declarations first.
        for (stmt in res.sourceFile.statements) {
            when (stmt) {
                is ClassDeclaration -> stmt.name?.let {
                    if (it.text == name) return ReexportedDecl(stmt, it, fileName, source)
                }
                is FunctionDeclaration -> stmt.name?.let {
                    if (it.text == name) return ReexportedDecl(stmt, it, fileName, source)
                }
                is InterfaceDeclaration ->
                    if (stmt.name.text == name) return ReexportedDecl(stmt, stmt.name, fileName, source)
                is EnumDeclaration ->
                    if (stmt.name.text == name) return ReexportedDecl(stmt, stmt.name, fileName, source)
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    val n = d.name as? Identifier ?: continue
                    if (n.text == name) return ReexportedDecl(stmt, n, fileName, source)
                }
                else -> {}
            }
        }
        // Re-export chains.
        for (stmt in res.sourceFile.statements) {
            if (stmt !is ExportDeclaration) continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val target = resolveModuleSpecifier(spec, stmt) ?: continue
            val clause = stmt.exportClause
            if (clause == null) {
                // export * from "Y" — name passes through unchanged
                findExportedDeclAcrossReexports(target, name, visited)?.let { return it }
            } else if (clause is NamedExports) {
                // export { X as name } from "Y" — look up the original X under name
                for (el in clause.elements) {
                    if (el.name.text != name) continue
                    val original = el.propertyName?.text ?: el.name.text
                    findExportedDeclAcrossReexports(target, original, visited)?.let { return it }
                }
            }
        }
        return null
    }

    /**
     * TS2567 for a `declare module "X" { export enum E { ... } }` augmentation whose
     * target module "X" (possibly via `export * from`) already declares a non-enum,
     * non-namespace `E` (class/function/var/interface). The per-file and cross-file
     * (script) walkers don't see this shape: the augmentation lives in a module file
     * and the conflicting partner is reached only through module-specifier + re-export
     * resolution. Emits TS2567 on BOTH the enum name and the partner declaration name,
     * each with a TS6203 "was also declared here" related info pointing at the other.
     */
    private fun checkModuleAugmentationEnumMerge() {
        for (result in binderResults) {
            val augFile = result.sourceFile.fileName
            if (isDtsFile(augFile)) continue
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val specName = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                val targetFile = resolveModuleSpecifier(specName, stmt) ?: continue
                if (targetFile == augFile) continue
                for (inner in body.statements) {
                    val enumDecl = inner as? EnumDeclaration ?: continue
                    val enumName = enumDecl.name.text
                    val partner = findExportedDeclAcrossReexports(targetFile, enumName, mutableSetOf())
                        ?: continue
                    val partnerKind = when (partner.stmt) {
                        is ClassDeclaration, is FunctionDeclaration,
                        is InterfaceDeclaration, is VariableStatement -> true
                        else -> false // enum partner merges fine; anything else: skip
                    }
                    if (!partnerKind) continue

                    val (enumLine, enumChar) = getLineAndCharacterOfPosition(augSource, enumDecl.name.pos)
                    val (pLine, pChar) = getLineAndCharacterOfPosition(partner.source, partner.nameNode.pos)

                    // TS2567 on the enum name, related info -> partner declaration.
                    diagnostics.add(Diagnostic(
                        message = "Enum declarations can only merge with namespace or other enum declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2567,
                        fileName = augFile,
                        line = enumLine,
                        character = enumChar,
                        start = enumDecl.name.pos,
                        length = enumName.length,
                        relatedInformation = listOf(Diagnostic(
                            message = "'$enumName' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = partner.fileName,
                            line = pLine,
                            character = pChar,
                            start = partner.nameNode.pos,
                            length = enumName.length,
                        )),
                    ))
                    // TS2567 on the partner declaration name, related info -> enum.
                    diagnostics.add(Diagnostic(
                        message = "Enum declarations can only merge with namespace or other enum declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2567,
                        fileName = partner.fileName,
                        line = pLine,
                        character = pChar,
                        start = partner.nameNode.pos,
                        length = enumName.length,
                        relatedInformation = listOf(Diagnostic(
                            message = "'$enumName' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = augFile,
                            line = enumLine,
                            character = enumChar,
                            start = enumDecl.name.pos,
                            length = enumName.length,
                        )),
                    ))
                }
            }
        }
    }

    /**
     * B90.1: TS2671 "Cannot augment module 'X' because it resolves to a non-module
     * entity." An ambient module defined with `export = V` where V is a value-only
     * entity (a `var`/`function` with no namespace/class/interface/enum/module
     * meaning) has no namespace meaning, so a `declare module "X" { ... }`
     * augmentation of it is illegal. Mirrors the B88.1 cross-file augmentation
     * walker structure. The augmentation block is distinguished from the
     * definition block by the ABSENCE of the `export =` inside it.
     */
    private fun checkModuleAugmentationOfNonModuleEntity() {
        for (result in binderResults) {
            val augFile = result.sourceFile.fileName
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val nameNode = stmt.name as? StringLiteralNode ?: continue
                val specifier = nameNode.text
                val body = stmt.body as? ModuleBlock ?: continue
                // Skip the DEFINITION block (carries `export = X`) — only augmentations error.
                if (body.statements.any { it is ExportAssignment && it.isExportEquals }) continue
                // An augmentation with no declarations to merge isn't worth flagging.
                if (body.statements.isEmpty()) continue
                if (!ambientModuleExportEqualsIsValueOnly(specifier)) continue
                val (line, character) = getLineAndCharacterOfPosition(augSource, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Cannot augment module '$specifier' because it resolves to a non-module entity.",
                    category = DiagnosticCategory.Error,
                    code = 2671,
                    fileName = augFile,
                    line = line,
                    character = character,
                    start = nameNode.pos,
                    length = (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                ))
            }
        }
    }

    /**
     * B90.1: Returns true when ambient module [specifier] is DEFINED with
     * `export = V` where V is a value-only entity (declared as `var`/`function`
     * only, with no namespace/class/interface/enum/module meaning) in the same
     * module block — making it a non-module entity (no namespace meaning).
     * Used for TS2671 (illegal augmentation) and TS2503 (`x.A` namespace use).
     */
    private fun ambientModuleExportEqualsIsValueOnly(specifier: String): Boolean {
        for (result in binderResults) {
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if ((stmt.name as? StringLiteralNode)?.text != specifier) continue
                val body = stmt.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s is ExportAssignment && s.isExportEquals) {
                        val expr = s.expression as? Identifier ?: continue
                        if (isNameValueOnlyInBlock(expr.text, body)) return true
                    }
                }
            }
        }
        return false
    }

    /**
     * B90.1: True when [name] is declared inside [block] ONLY as a value
     * (`var`/`function`) and NOT as any namespace/type entity (class, interface,
     * type alias, enum, namespace/module). Used to classify an `export = name`
     * target as a pure non-module value.
     */
    private fun isNameValueOnlyInBlock(name: String, block: ModuleBlock): Boolean {
        var hasValue = false
        var hasNsOrType = false
        for (stmt in block.statements) {
            when (stmt) {
                is VariableStatement ->
                    if (stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValue = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasNsOrType = true
                is InterfaceDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is EnumDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) hasNsOrType = true
                else -> {}
            }
        }
        return hasValue && !hasNsOrType
    }

    /**
     * B90.1: Extract the external-module specifier of an `import X = require("spec")`
     * alias symbol, or null if it's not such an import-equals.
     */
    private fun getImportEqualsSpecifier(sym: Symbol): String? {
        for (decl in sym.declarations) {
            if (decl is ImportEqualsDeclaration) {
                val ref = decl.moduleReference
                if (ref is ExternalModuleReference) {
                    return (ref.expression as? StringLiteralNode)?.text
                }
            }
        }
        return null
    }

    // -----------------------------------------------------------------------
    // TS2558: Expected N type arguments, but got M (call/new expressions)
    // -----------------------------------------------------------------------

    private fun checkCallTypeArgCount() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCallTypeArgCountInStmts(result.sourceFile.statements, source, fileName, result.locals)
        }
    }

    private fun checkCallTypeArgCountInStmts(
        stmts: List<Statement>, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        for (stmt in stmts) checkCallTypeArgCountInStmt(stmt, source, fileName, locals)
    }

    private fun checkCallTypeArgCountInStmt(
        stmt: Statement, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            }
            is ReturnStatement -> stmt.expression?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            is FunctionDeclaration -> stmt.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is Constructor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is GetAccessor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is SetAccessor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is PropertyDeclaration -> m.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                    else -> {}
                }
            }
            is Block -> checkCallTypeArgCountInStmts(stmt.statements, source, fileName, locals)
            is IfStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.thenStatement, source, fileName, locals)
                stmt.elseStatement?.let { checkCallTypeArgCountInStmt(it, source, fileName, locals) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                    }
                    is Expression -> checkCallTypeArgCountInExpr(init, source, fileName, locals)
                    else -> {}
                }
                stmt.condition?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                stmt.incrementor?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is ForInStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is ForOfStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is WhileStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is DoStatement -> {
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            }
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkCallTypeArgCountInStmts(c.statements, source, fileName, locals)
                    is DefaultClause -> checkCallTypeArgCountInStmts(c.statements, source, fileName, locals)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkCallTypeArgCountInStmts(stmt.tryBlock.statements, source, fileName, locals)
                stmt.catchClause?.let { checkCallTypeArgCountInStmts(it.block.statements, source, fileName, locals) }
                stmt.finallyBlock?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            }
            is LabeledStatement -> checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            is ThrowStatement -> stmt.expression?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            is ExportAssignment -> checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            else -> {}
        }
    }

    private fun checkCallTypeArgCountInExpr(
        expr: Expression, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        when (expr) {
            is CallExpression -> {
                checkCallOrNewTypeArgCount(expr.expression, expr.typeArguments, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
                for (arg in expr.arguments) checkCallTypeArgCountInExpr(arg, source, fileName, locals)
            }
            is NewExpression -> {
                checkCallOrNewTypeArgCount(expr.expression, expr.typeArguments, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
                expr.arguments?.forEach { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkCallTypeArgCountInExpr(current.right, source, fileName, locals)
                    current = current.left
                }
                checkCallTypeArgCountInExpr(current, source, fileName, locals)
            }
            is ParenthesizedExpression -> checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
            is ConditionalExpression -> {
                checkCallTypeArgCountInExpr(expr.condition, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.whenTrue, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.whenFalse, source, fileName, locals)
            }
            is PropertyAccessExpression -> checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkCallTypeArgCountInStmts(body.statements, source, fileName, locals)
                is Expression -> checkCallTypeArgCountInExpr(body, source, fileName, locals)
                else -> {}
            }
            is FunctionExpression -> checkCallTypeArgCountInStmts(expr.body.statements, source, fileName, locals)
            else -> {}
        }
    }

    private fun checkCallOrNewTypeArgCount(
        callee: Expression,
        typeArguments: List<TypeNode>?,
        source: String,
        fileName: String,
        locals: Map<String, Symbol>,
    ) {
        // Only check if type arguments are provided and non-empty
        if (typeArguments == null || typeArguments.isEmpty()) return

        // 17.188: PropertyAccessExpression with ArrayLiteralExpression receiver
        // for known fixed-arity Array methods (e.g. `[1,2,3].map<any,any>(...)`
        // where Array.map takes exactly 1 type arg). Conservative gate: only
        // fires for hardcoded method names with array-literal receivers.
        if (callee is PropertyAccessExpression && callee.expression is ArrayLiteralExpression) {
            val methodName = callee.name.text
            val expectedTypeParams = when (methodName) {
                "map", "flatMap" -> 1
                else -> -1
            }
            if (expectedTypeParams > 0 && typeArguments.size != expectedTypeParams) {
                val firstArg = typeArguments.first()
                val lastArg = typeArguments.last()
                val start = firstArg.pos
                var endPos = lastArg.end
                while (endPos > start && endPos < source.length) {
                    val ch = source[endPos - 1]
                    if (ch == '>' || ch == ')' || ch.isWhitespace()) endPos--
                    else break
                }
                val length = (endPos - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Expected $expectedTypeParams type arguments, but got ${typeArguments.size}.",
                    category = DiagnosticCategory.Error,
                    code = 2558,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                return
            }
        }

        // B60.17: PropertyAccess on well-known lib globals — narrow gate to avoid
        // FPs from incomplete sig resolution for user types. Targets `Object.create<X>`,
        // `Array.from<X>`, etc. where the static side's method has a known type-param
        // count and the call passes a different count.
        if (callee is PropertyAccessExpression) {
            val recv = callee.expression
            if (recv is Identifier && recv.text in BUILTIN_LIB_GLOBAL_VALUE_NAMES) {
                val calleeType = try { getTypeOfPropertyAccess(callee) } catch (_: StackOverflowError) { return }
                if (calleeType === anyType || calleeType === errorType) return
                val sigs = getCallSignaturesOfType(calleeType)
                if (sigs.isEmpty()) return
                val tpCounts = sigs.map { it.typeParameters?.size ?: 0 }.distinct()
                if (tpCounts.size != 1) return
                val expectedCount = tpCounts[0]
                val providedCount = typeArguments.size
                if (providedCount == expectedCount) return
                val firstArg = typeArguments.first()
                val lastArg = typeArguments.last()
                val start = firstArg.pos
                var endPos = lastArg.end
                while (endPos > start && endPos < source.length) {
                    val ch = source[endPos - 1]
                    if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') endPos--
                    else break
                }
                val length = (endPos - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Expected $expectedCount type arguments, but got $providedCount.",
                    category = DiagnosticCategory.Error, code = 2558,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                ))
                return
            }
        }
        // Resolve the callee to a symbol
        val name = when (callee) {
            is Identifier -> callee.text
            else -> return // PropertyAccessExpression, etc. — skip for now
        }
        if (name.isEmpty()) return

        // Look up the symbol
        val symbol = locals[name] ?: globals[name] ?: return

        // Follow import alias
        val resolved = if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            try { resolveAlias(symbol) } catch (_: StackOverflowError) { symbol }
        } else symbol

        // Get type parameters from the function/class declarations. For overloaded
        // functions, collect per-overload (min, max) ranges and compute the union
        // of acceptable type-arg counts. Implementation declarations (bodied
        // FunctionDeclaration when there are also body-less overload signatures)
        // are skipped — TypeScript's TS2558/TS2743 only consider the declared
        // overload signatures, not the impl signature.
        val perOverloadRanges = mutableListOf<IntRange>()
        var lastNonFnMaxParams = -1
        var lastNonFnMinParams = -1
        val fnDecls = resolved.declarations.filterIsInstance<FunctionDeclaration>()
        val hasOverloadSigs = fnDecls.count { it.body == null } >= 1 && fnDecls.size >= 2
        var anyFnDecl = false
        for (decl in resolved.declarations) {
            when (decl) {
                is FunctionDeclaration -> {
                    // When overload signatures exist, skip the impl (bodied) decl
                    if (hasOverloadSigs && decl.body != null) continue
                    val tps = decl.typeParameters
                    val paramCount = tps?.size ?: 0
                    val minRequired = tps?.count { it.default == null } ?: 0
                    perOverloadRanges.add(minRequired..paramCount)
                    anyFnDecl = true
                }
                is ClassDeclaration -> {
                    val tps = decl.typeParameters ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                is InterfaceDeclaration -> {
                    val tps = decl.typeParameters ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                is VariableDeclaration -> {
                    val tps = when (val init = decl.initializer) {
                        is ArrowFunction -> init.typeParameters
                        is FunctionExpression -> init.typeParameters
                        else -> null
                    } ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                else -> {}
            }
        }

        // Always also include the non-function decls (classes/interfaces are NOT
        // overloaded — they merge into a single declared shape).
        if (lastNonFnMaxParams >= 0) {
            perOverloadRanges.add(lastNonFnMinParams..lastNonFnMaxParams)
        }
        if (perOverloadRanges.isEmpty()) return
        // If only FunctionDeclarations were found AND none have typeParameters,
        // skip emission unless overloads (then we report TS2558 "Expected 0").
        if (!anyFnDecl && lastNonFnMaxParams < 0) return

        val providedCount = typeArguments.size
        // Acceptable counts = union of all overload ranges
        if (perOverloadRanges.any { providedCount in it }) return

        // Compute squiggle span — covers the type argument text only (no < >)
        val firstArg = typeArguments.first()
        val lastArg = typeArguments.last()
        val start = firstArg.pos
        var endPos = lastArg.end
        while (endPos > start && endPos < source.length) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') {
                endPos--
            } else break
        }
        val length = endPos - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        // Decide TS2743 (overload-aware) vs TS2558 (out-of-range or single-overload).
        // TS2743 fires when providedCount sits BETWEEN overload mins/maxes (i.e. some
        // overload accepts fewer and some accepts more) but no overload's exact range
        // covers it.
        val overallMin = perOverloadRanges.minOf { it.first }
        val overallMax = perOverloadRanges.maxOf { it.last }
        if (perOverloadRanges.size >= 2 && providedCount in (overallMin + 1) until overallMax) {
            // TS2743 — list the "bracketing" boundary counts: for each overload
            // entirely BELOW providedCount, take its max; for each overload
            // entirely ABOVE providedCount, take its min. Matches TypeScript's
            // wording "either N or M" / "N, M, or P".
            val brackets = sortedSetOf<Int>()
            for (r in perOverloadRanges) {
                if (r.last < providedCount) brackets.add(r.last)
                else if (r.first > providedCount) brackets.add(r.first)
            }
            val list = brackets.toList()
            val countListText = when (list.size) {
                1 -> "${list[0]}"
                2 -> "either ${list[0]} or ${list[1]}"
                else -> list.dropLast(1).joinToString(", ") + ", or ${list.last()}"
            }
            diagnostics.add(Diagnostic(
                message = "No overload expects $providedCount type arguments, but overloads do exist that expect $countListText type arguments.",
                category = DiagnosticCategory.Error, code = 2743,
                fileName = fileName, line = line, character = character,
                start = start, length = length,
            ))
            return
        }

        // TS2558 — "Expected X type arguments, but got Y." X is the boundary overload's range:
        // - if providedCount > overallMax → X = overallMax
        // - if providedCount < overallMin → X = overallMin
        // - single overload with default-typed params: X = "min-max"
        val expectedText = if (providedCount > overallMax) {
            overallMax.toString()
        } else if (providedCount < overallMin) {
            overallMin.toString()
        } else {
            // Edge: providedCount IS in some overload range but our check missed?
            // Fallback: pick the closest range.
            val targetRange = perOverloadRanges.minByOrNull {
                if (providedCount > it.last) providedCount - it.last
                else it.first - providedCount
            } ?: perOverloadRanges.first()
            if (targetRange.first == targetRange.last) "${targetRange.first}"
            else "${targetRange.first}-${targetRange.last}"
        }
        // When there's only ONE overload range and it spans (min..max with min<max), prefer "min-max".
        val finalExpected = if (perOverloadRanges.size == 1) {
            val r = perOverloadRanges[0]
            if (r.first == r.last) "${r.first}"
            else "${r.first}-${r.last}"
        } else expectedText

        diagnostics.add(Diagnostic(
            message = "Expected $finalExpected type arguments, but got $providedCount.",
            category = DiagnosticCategory.Error,
            code = 2558,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // TS2440: Import declaration conflicts with local declaration
    // -----------------------------------------------------------------------

    /**
     * Returns true if [name] is exported from [moduleSpecifier] only via a type-only declaration
     * (`export type X = ...`, `export interface X {}`). Walks the target file's top-level
     * statements and inspects each export form.
     */
    private fun isExportedNameTypeOnly(name: String, moduleSpecifier: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        var hasTypeOnly = false
        var hasValue = false
        for (stmt in targetResult.sourceFile.statements) {
            when (stmt) {
                is TypeAliasDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasTypeOnly = true
                is InterfaceDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasTypeOnly = true
                is ClassDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is FunctionDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is EnumDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is VariableStatement ->
                    if (ModifierFlag.Export in stmt.modifiers &&
                        stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                is ExportDeclaration -> {
                    val clause = stmt.exportClause as? NamedExports ?: continue
                    for (spec in clause.elements) {
                        if (spec.name.text != name) continue
                        if (stmt.isTypeOnly || spec.isTypeOnly) hasTypeOnly = true else hasValue = true
                    }
                }
                else -> {}
            }
        }
        return hasTypeOnly && !hasValue
    }

    /**
     * B61.5f helper: returns true when the source text leading up to an
     * ImportEqualsDeclaration's pos contains a class-only modifier keyword
     * (public/private/protected/static). Used to suppress TS2440 FP when
     * TS1044 already fires for the invalid modifier.
     */
    private fun sourceHasClassOnlyModifierBeforeImportEquals(
        stmt: ImportEqualsDeclaration,
        source: String,
    ): Boolean {
        val classOnlyKws = listOf("public", "private", "protected", "static")
        // Find start of line containing stmt.pos
        var lineStart = stmt.pos
        while (lineStart > 0 && source[lineStart - 1] != '\n') lineStart--
        val prefix = source.substring(lineStart, stmt.pos)
        for (kw in classOnlyKws) {
            // Word-boundary match: must be surrounded by non-letter-digit chars
            var idx = 0
            while (true) {
                val found = prefix.indexOf(kw, idx)
                if (found < 0) break
                val before = if (found == 0) ' ' else prefix[found - 1]
                val after = if (found + kw.length >= prefix.length) ' ' else prefix[found + kw.length]
                if (!before.isLetterOrDigit() && !after.isLetterOrDigit()) return true
                idx = found + 1
            }
        }
        return false
    }

    /**
     * B61.5h: TS1473 "An import declaration can only be used at the top level of a module."
     * Walks each file's statements; for nested function bodies / blocks etc., emits TS1473
     * at any ImportDeclaration found. Top-level imports remain valid.
     */
    private fun checkImportNotAtTopLevel() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // B76.2: TS1473 fires only for .js/.jsx files. For .ts/.tsx,
            // checkNamespaceTopLevelOnly emits TS1232 (correct code for
            // nested-block imports) at the same positions.
            if (fileName.endsWith(".ts") || fileName.endsWith(".tsx") ||
                fileName.endsWith(".mts") || fileName.endsWith(".cts")) continue
            val source = result.sourceFile.text
            // Walk each top-level statement, recursing into non-module-level constructs.
            for (stmt in result.sourceFile.statements) {
                walkForNestedImports(stmt, source, fileName, topLevel = true)
            }
        }
    }

    private fun walkForNestedImports(stmt: Statement, source: String, fileName: String, topLevel: Boolean) {
        if (!topLevel && stmt is ImportDeclaration) {
            val start = stmt.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "An import declaration can only be used at the top level of a module.",
                category = DiagnosticCategory.Error,
                code = 1473,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = 6, // "import"
            ))
        }
        when (stmt) {
            is FunctionDeclaration -> stmt.body?.statements?.forEach {
                walkForNestedImports(it, source, fileName, topLevel = false)
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is Constructor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is GetAccessor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is SetAccessor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                // Module body — top-level inside namespace counts as top-level too
                // (`namespace M { import X from "y"; }` is allowed).
                (stmt.body as? ModuleBlock)?.statements?.forEach {
                    walkForNestedImports(it, source, fileName, topLevel = true)
                }
            }
            is Block -> stmt.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
            is IfStatement -> {
                walkForNestedImports(stmt.thenStatement, source, fileName, topLevel = false)
                stmt.elseStatement?.let { walkForNestedImports(it, source, fileName, topLevel = false) }
            }
            is WhileStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is DoStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForInStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForOfStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                stmt.catchClause?.block?.statements?.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                stmt.finallyBlock?.statements?.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                        is DefaultClause -> clause.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            else -> {}
        }
    }

    /**
     * B98.r17: TS2440 "Import declaration conflicts with local declaration of 'X'." for an
     * `import X = <internal-ns-ref>` (NOT `require(...)`) declared inside a namespace block whose
     * name X collides with a `var/let/const X` declared in ANOTHER block of the SAME merged
     * namespace. The file-level `checkImportConflictsWithLocal` never recurses into namespace
     * bodies, so cross-block conflicts inside a merged namespace were missed. Only conflicts with
     * VARIABLES (internal aliases declaration-merge with class/function/enum, so those don't count).
     */
    private fun checkNamespaceImportVarConflict() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkNsImportVarConflictInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkNsImportVarConflictInStatements(stmts: List<Statement>, source: String, fileName: String) {
        val nsGroups = mutableMapOf<String, MutableList<ModuleDeclaration>>()
        for (stmt in stmts) {
            if (stmt is ModuleDeclaration) {
                (stmt.name as? Identifier)?.let { nsGroups.getOrPut(it.text) { mutableListOf() }.add(stmt) }
                (stmt.body as? ModuleBlock)?.let { checkNsImportVarConflictInStatements(it.statements, source, fileName) }
            }
        }
        for ((_, blocks) in nsGroups) {
            // Merge var names across all blocks of this same-named namespace.
            val varNames = mutableSetOf<String>()
            for (block in blocks) {
                val body = block.body as? ModuleBlock ?: continue
                for (s in body.statements) if (s is VariableStatement) {
                    for (decl in s.declarationList.declarations) (decl.name as? Identifier)?.let { varNames.add(it.text) }
                }
            }
            if (varNames.isEmpty()) continue
            for (block in blocks) {
                val body = block.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s !is ImportEqualsDeclaration) continue
                    if (s.isTypeOnly) continue
                    if (s.moduleReference is ExternalModuleReference) continue   // `require(...)` is a different conflict
                    val name = s.name.text
                    if (name !in varNames) continue
                    // ImportEqualsDeclaration.pos points at `import`; back up over the
                    // `export` modifier (parser drops it from pos) so the squiggle covers
                    // the whole `export import X = …;` statement.
                    var stmtStart = s.pos
                    if (ModifierFlag.Export in s.modifiers) {
                        var p = s.pos
                        while (p > 0 && source[p - 1].isWhitespace()) p--
                        if (p >= 6 && source.substring(p - 6, p) == "export") stmtStart = p - 6
                    }
                    val endIdx = source.indexOf(';', stmtStart)
                    val stmtLen = if (endIdx >= 0) endIdx - stmtStart + 1 else (s.end - stmtStart).coerceAtLeast(name.length)
                    val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                    diagnostics.add(Diagnostic(
                        message = "Import declaration conflicts with local declaration of '$name'.",
                        category = DiagnosticCategory.Error,
                        code = 2440,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmtStart,
                        length = stmtLen,
                    ))
                }
            }
        }
    }

    private fun checkImportConflictsWithLocal() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Collect all non-import declared names in this file, tracking declaration kind
            // Variables conflict with import aliases; classes/functions/interfaces can merge
            val varNames = mutableSetOf<String>()     // variable declarations
            val mergeableNames = mutableSetOf<String>() // class/function/enum — can merge with internal aliases
            val typeOnlyNames = mutableSetOf<String>() // type alias / interface — can conflict with type-only imports
            // Type aliases specifically — these CANNOT merge with any other declaration kind
            // (unlike interfaces which can merge with classes/namespaces/values via declaration merging).
            // `import { X } from "..."` (binding a value) + local `type X = ...` is therefore a hard
            // conflict regardless of the imported symbol's kind, distinct from the type-only-vs-type-only
            // case handled by `isExportedNameTypeOnly`.
            val typeAliasNames = mutableSetOf<String>()
            // Local value-declaration names that a NAMED import cannot share (function /
            // class / enum / namespace). A named `import { X }` does not declaration-merge
            // with a local function/class/enum/namespace of the same name → TS2440. (This is
            // distinct from `mergeableNames`, which exists to AVOID conflicting with an
            // import-equals INTERNAL alias.)
            val namedImportConflictNames = mutableSetOf<String>()
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement -> {
                        for (decl in stmt.declarationList.declarations) {
                            val name = (decl.name as? Identifier)?.text ?: continue
                            varNames.add(name)
                        }
                    }
                    is FunctionDeclaration -> stmt.name?.let { mergeableNames.add(it.text); namedImportConflictNames.add(it.text) }
                    is ClassDeclaration -> stmt.name?.let { mergeableNames.add(it.text); namedImportConflictNames.add(it.text) }
                    is EnumDeclaration -> { mergeableNames.add(stmt.name.text); namedImportConflictNames.add(stmt.name.text) }
                    is ModuleDeclaration -> (stmt.name as? Identifier)?.let { namedImportConflictNames.add(it.text) }
                    is TypeAliasDeclaration -> {
                        typeOnlyNames.add(stmt.name.text)
                        typeAliasNames.add(stmt.name.text)
                    }
                    is InterfaceDeclaration -> typeOnlyNames.add(stmt.name.text)
                    else -> {}
                }
            }
            val localNames = varNames + mergeableNames

            // Check imports against local names
            for (stmt in stmts) {
                when (stmt) {
                    is ImportEqualsDeclaration -> {
                        if (stmt.isTypeOnly) continue
                        // B61.5f: Skip TS2440 when import-equals has class-only modifier keywords
                        // in source text (parser drops them from stmt.modifiers, so source-scan).
                        // TS1044 fires for these and the binding shouldn't also conflict.
                        if (sourceHasClassOnlyModifierBeforeImportEquals(stmt, source)) continue
                        // Internal namespace aliases (import foo = m1) can merge with class/function/interface
                        // but NOT with variable declarations
                        if (stmt.moduleReference !is ExternalModuleReference) {
                            val name = stmt.name.text
                            if (name !in varNames) continue
                        }
                        val name = stmt.name.text
                        if (name in localNames) {
                            // Error on entire import statement
                            val stmtStart = stmt.pos
                            // Find end of statement including semicolon
                            var stmtEnd = stmt.end
                            // Approximate length: scan source for semicolon or newline after pos
                            val endIdx = source.indexOf(';', stmtStart)
                            val stmtLen = if (endIdx >= 0) endIdx - stmtStart + 1
                                else (stmtEnd - stmtStart).coerceAtLeast(name.length)
                            val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                            diagnostics.add(Diagnostic(
                                message = "Import declaration conflicts with local declaration of '$name'.",
                                category = DiagnosticCategory.Error,
                                code = 2440,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = stmtStart,
                                length = stmtLen,
                            ))
                        }
                    }
                    is ImportDeclaration -> {
                        // TS2440 fires for bindings that conflict with local var declarations.
                        // Rule: fires when there's a var with the same name AFTER the import AND
                        // NO var with the same name BEFORE the import (first occurrence determines the slot).
                        val clause = stmt.importClause ?: continue
                        // `import type { X }` / `import type X` create no runtime binding, so no conflict.
                        if (clause.isTypeOnly) continue
                        val importPos = stmt.pos
                        val moduleSpecifierText = (stmt.moduleSpecifier as? StringLiteralNode)?.text

                        // Helper: check if name conflicts (var after import, no var before import)
                        fun hasVarConflict(name: String): Boolean {
                            val varBeforeImport = stmts.any { s ->
                                s is VariableStatement && s.pos < importPos &&
                                    s.declarationList.declarations.any { d ->
                                        (d.name as? Identifier)?.text == name
                                    }
                            }
                            if (varBeforeImport) return false
                            return stmts.any { s ->
                                s is VariableStatement && s.pos > importPos &&
                                    s.declarationList.declarations.any { d ->
                                        (d.name as? Identifier)?.text == name
                                    }
                            }
                        }

                        // Default binding
                        val defaultName = clause.name?.text
                        if (defaultName != null && defaultName in varNames) {
                            if (hasVarConflict(defaultName)) {
                                val (line, character) = getLineAndCharacterOfPosition(source, clause.name!!.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Import declaration conflicts with local declaration of '$defaultName'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2440,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = clause.name!!.pos,
                                    length = defaultName.length,
                                ))
                            }
                        }
                        // Namespace binding: import * as NS
                        val nb = clause.namedBindings
                        if (nb is NamespaceImport) {
                            val nsName = nb.name.text
                            if (nsName in varNames) {
                                val varAfterImport = hasVarConflict(nsName)
                                if (varAfterImport) {
                                    val (line, character) = getLineAndCharacterOfPosition(source, nb.name.pos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$nsName'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = nb.name.pos,
                                        length = nsName.length,
                                    ))
                                }
                            }
                        }
                        // Named specifiers: import { x } or { x as localAlias }
                        if (nb is NamedImports) {
                            for (element in nb.elements) {
                                // Per-specifier `import { type X }` creates no runtime binding.
                                if (element.isTypeOnly) continue
                                val localAlias = element.name.text
                                val sourceNameForElt = (element.propertyName ?: element.name).text
                                // Type-only-vs-type-only conflict: `import { T }` (where T is a type-only
                                // export in source) + local `type T` / `interface T` declaration. Both
                                // declare T as a type, so they collide. Emit TS2440 (NOT TS2865 — local
                                // is a type, not a value). The narrow gate (isExportedNameTypeOnly) avoids
                                // FPs against valid `import { Class }` + `interface Class` augmentation
                                // patterns (where Class is a value+type in source).
                                if (localAlias in typeOnlyNames &&
                                    moduleSpecifierText != null &&
                                    isExportedNameTypeOnly(sourceNameForElt, moduleSpecifierText)) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                // TypeAlias-vs-value-import conflict: `type X = ...` cannot share a name
                                // with `import { X } from "..."` since TypeAlias doesn't participate in
                                // declaration merging. Mirrors TS2440 fired in this exact shape (e.g.
                                // `import {E} from "./f1"; type E = E;` where f1 re-exports a value).
                                if (localAlias in typeAliasNames) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                // Named import of a value name conflicting with a local
                                // function / class / enum / namespace declaration → TS2440
                                // (these do not declaration-merge with a named import).
                                if (localAlias in namedImportConflictNames) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                if (localAlias in varNames) {
                                    if (hasVarConflict(localAlias)) {
                                        // Position at the start of the element (propertyName if aliased, otherwise name)
                                        // Span covers the full element including "as" keyword: "x as y"
                                        val startNode = element.propertyName ?: element.name
                                        val startPos = startNode.pos
                                        val spanLen = if (element.propertyName != null) {
                                            // "x as y" — from property name start to alias name end
                                            element.name.pos + element.name.text.length - startPos
                                        } else {
                                            localAlias.length
                                        }
                                        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                        // TS2865: under isolatedModules, when the imported name resolves to a
                                        // type-only export in the source module, the import should have been
                                        // `import type { X }`. Emit TS2865 in place of TS2440 to direct the
                                        // user to the right fix. verbatimModuleSyntax routes through TS1484.
                                        val sourceName = (element.propertyName ?: element.name).text
                                        val sourceIsTypeOnly = moduleSpecifierText != null &&
                                            isExportedNameTypeOnly(sourceName, moduleSpecifierText)
                                        // 17.131: Under verbatimModuleSyntax + type-only-in-source, the new
                                        // checkVerbatimModuleSyntax walker emits TS1484 covering the same
                                        // diagnostic surface — suppress TS2440 here. TS2865 still fires
                                        // alongside TS1484 when isolatedModules is also enabled.
                                        val verbatimTypeOnlyInSource = options.verbatimModuleSyntax && sourceIsTypeOnly
                                        val isolatedTypeOnlyInSource = options.isolatedModules && sourceIsTypeOnly
                                        if (isolatedTypeOnlyInSource) {
                                            diagnostics.add(Diagnostic(
                                                message = "Import '$localAlias' conflicts with local value, so must be declared with a type-only import when 'isolatedModules' is enabled.",
                                                category = DiagnosticCategory.Error,
                                                code = 2865,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = startPos,
                                                length = spanLen,
                                            ))
                                        }
                                        if (!verbatimTypeOnlyInSource && !isolatedTypeOnlyInSource) {
                                            diagnostics.add(Diagnostic(
                                                message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                                category = DiagnosticCategory.Error,
                                                code = 2440,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = startPos,
                                                length = spanLen,
                                            ))
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    // TS1292: 'X' resolves to a type and must be marked type-only when re-exporting under isolatedModules
    // -----------------------------------------------------------------------

    /**
     * Under `isolatedModules`, `export default X` where X resolves to a type-only import
     * (and there's no local value declaration named X) requires `export type { X as default }`
     * because the transpiler can't know whether to elide the export at runtime. Emits TS1292
     * at the expression's position. Skipped when `verbatimModuleSyntax` is enabled (different
     * diagnostic family fires there).
     */
    /**
     * TS1269: "Cannot use 'export import' on a type or type-only namespace when
     * 'isolatedModules' is enabled." Fires for `export import X = Y` (or `export import X = A.B`)
     * where Y resolves to a type alias, interface, or type-only namespace under
     * `@isolatedModules`. The transpiler cannot keep the runtime binding if Y has no value side.
     */
    private fun checkIsolatedModulesExportImportIsType() {
        if (!options.isolatedModules || options.verbatimModuleSyntax) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Detect: is the local binding `name` an import alias of a type-only export
            // from some other file in this program?
            fun importedFromTypeOnlyExport(name: String): Boolean {
                for (stmt in stmts) {
                    if (stmt !is ImportDeclaration) continue
                    val clause = stmt.importClause ?: continue
                    val moduleSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                    val nb = clause.namedBindings
                    if (nb is NamedImports) {
                        val element = nb.elements.firstOrNull { it.name.text == name } ?: continue
                        if (clause.isTypeOnly || element.isTypeOnly) return true
                        val sourceName = (element.propertyName ?: element.name).text
                        if (isExportedNameTypeOnly(sourceName, moduleSpec)) return true
                        // Also handle exported namespace whose members are all types — the
                        // existing helper doesn't yet walk ModuleDeclaration.
                        val targetFile = resolveModuleSpecifier(moduleSpec, null) ?: continue
                        val targetResult = fileResults[targetFile] ?: continue
                        for (s in targetResult.sourceFile.statements) {
                            if (s !is ModuleDeclaration) continue
                            val moduleName = s.name
                            val n = if (moduleName is Identifier) moduleName.text
                                else if (moduleName is StringLiteralNode) moduleName.text
                                else null
                            if (n != sourceName) continue
                            if (ModifierFlag.Export !in s.modifiers) continue
                            // Check via binder's moduleInstanceState — a non-instantiated namespace
                            // (only type members) qualifies.
                            val state = binderResults.firstNotNullOfOrNull { br ->
                                br.moduleInstanceStates[nodeKey(s)]
                            }
                            if (state == ModuleInstanceState.NonInstantiated) return true
                        }
                    }
                    if (nb is NamespaceImport && nb.name.text == name) {
                        // `import * as X from "./m"` — X is a namespace import. Treat as
                        // type-only if the target file exports ONLY types (no value
                        // declarations). Skip for now to avoid over-firing; this is the
                        // narrower namespaced-from-import path.
                    }
                }
                return false
            }

            for (stmt in stmts) {
                if (stmt !is ImportEqualsDeclaration) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                // Only fires for `export import X = SomeIdent` where SomeIdent resolves to type-only.
                // Skip `export import X = require("...")` (external module ref) — different code path.
                val ref = stmt.moduleReference
                if (ref is ExternalModuleReference) continue
                val rootName = when (ref) {
                    is Identifier -> ref.text
                    is QualifiedName -> {
                        var leftmost: Node = ref
                        while (leftmost is QualifiedName) leftmost = leftmost.left
                        (leftmost as? Identifier)?.text
                    }
                    else -> null
                } ?: continue
                if (!importedFromTypeOnlyExport(rootName)) continue
                // The parser's stmt.pos points to `import` (after the `export` modifier was
                // consumed). Walk backward through whitespace to find the start of `export`.
                var startPos = stmt.pos
                var p = startPos - 1
                while (p >= 0 && source[p] in " \t\r\n") p--
                if (p >= 5 && source.substring(p - 5, p + 1) == "export") {
                    startPos = p - 5
                }
                // End at the semicolon (stmt.end overshoots per CLAUDE.md gotcha).
                val semi = source.indexOf(';', stmt.pos)
                val endPos = if (semi >= 0) semi + 1 else stmt.end
                val length = endPos - startPos
                val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                diagnostics.add(Diagnostic(
                    message = "Cannot use 'export import' on a type or type-only namespace when 'isolatedModules' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1269,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = startPos,
                    length = length,
                ))
            }
        }
    }

    private fun checkIsolatedModulesExportDefaultIsType() {
        if (!options.isolatedModules || options.verbatimModuleSyntax) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Collect names declared as values in this file (used to short-circuit when the
            // exported identifier is shadowed by a same-name local value declaration).
            val localValueNames = mutableSetOf<String>()
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement ->
                        for (decl in stmt.declarationList.declarations) {
                            (decl.name as? Identifier)?.text?.let { localValueNames.add(it) }
                        }
                    is FunctionDeclaration -> stmt.name?.let { localValueNames.add(it.text) }
                    is ClassDeclaration -> stmt.name?.let { localValueNames.add(it.text) }
                    is EnumDeclaration -> localValueNames.add(stmt.name.text)
                    else -> {}
                }
            }

            // Returns true when [name] is imported and resolves to a type-only export in the source
            // module — covers both syntactic `import type { X }` / `import { type X }` AND
            // `import { X }` where X happens to be a type-only export in the source module.
            fun isImportedAsTypeOnly(name: String): Boolean {
                for (stmt in stmts) {
                    if (stmt !is ImportDeclaration) continue
                    val clause = stmt.importClause ?: continue
                    val nb = clause.namedBindings as? NamedImports ?: continue
                    val element = nb.elements.firstOrNull { it.name.text == name } ?: continue
                    if (clause.isTypeOnly || element.isTypeOnly) return true
                    val moduleSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                    val sourceName = (element.propertyName ?: element.name).text
                    if (isExportedNameTypeOnly(sourceName, moduleSpec)) return true
                }
                return false
            }

            for (stmt in stmts) {
                if (stmt !is ExportAssignment) continue
                if (stmt.isExportEquals) continue // `export = X` is a separate diagnostic family
                val expr = stmt.expression as? Identifier ?: continue
                val name = expr.text
                if (name in localValueNames) continue
                if (!isImportedAsTypeOnly(name)) continue
                val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                diagnostics.add(Diagnostic(
                    message = "'$name' resolves to a type and must be marked type-only in this file before re-exporting when 'isolatedModules' is enabled. Consider using 'export type { $name as default }'.",
                    category = DiagnosticCategory.Error,
                    code = 1292,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = expr.pos,
                    length = name.length,
                ))
            }
        }
    }

    // 17.131: TS1295 / TS1484 — verbatimModuleSyntax restrictions on imports/exports.
    // -----------------------------------------------------------------------

    /**
     * Under `verbatimModuleSyntax`, two related diagnostics fire for non-type-only imports:
     *  - TS1295: in a CommonJS file, ECMAScript imports/exports cannot be written
     *    (the runtime bindings would need to be transformed to require()/exports.X — but
     *    verbatim mode preserves syntax as-written, so the file would be invalid CJS).
     *  - TS1484: when the imported name is a type-only export in the source module, it
     *    must be imported using a type-only form (`import type { X }` or `import { type X }`).
     *
     * Both fire at the imported-name position. Type-only imports (`import type {}`) are
     * exempt from both — they're erased at compile time and have no runtime emission.
     *
     * Scope: named imports + default imports + namespace imports. Side-effect imports
     * (`import "./x"`), import-equals, and export declarations are not yet handled here
     * (deferred — additional surface that may yield more failing-test flips when added).
     */
    private fun checkVerbatimModuleSyntax() {
        if (!options.verbatimModuleSyntax) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isCjs = !isESModuleFormat(options, fileName)

            fun emitTs1295(pos: Int, length: Int) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "ECMAScript imports and exports cannot be written in a CommonJS file under 'verbatimModuleSyntax'. Adjust the 'type' field in the nearest 'package.json' to make this file an ECMAScript module, or adjust your 'verbatimModuleSyntax', 'module', and 'moduleResolution' settings in TypeScript.",
                    category = DiagnosticCategory.Error,
                    code = 1295,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = length,
                ))
            }

            fun emitTs1484(pos: Int, length: Int, displayName: String) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "'$displayName' is a type and must be imported using a type-only import when 'verbatimModuleSyntax' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1484,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = length,
                ))
            }

            fun emitTs1287(pos: Int) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "A top-level 'export' modifier cannot be used on value declarations in a CommonJS module when 'verbatimModuleSyntax' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1287,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = 6,  // "export"
                ))
            }

            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ImportDeclaration -> {
                        val clause = stmt.importClause ?: continue
                        // `import type { ... }` — entirely type-only, no diagnostics fire here.
                        if (clause.isTypeOnly) continue
                        val moduleSpecifierText = (stmt.moduleSpecifier as? StringLiteralNode)?.text

                        // Default binding: `import X from "./y"`
                        clause.name?.let { defaultName ->
                            if (isCjs) emitTs1295(defaultName.pos, defaultName.text.length)
                            // TS1484 for default imports of type-only-default exports is not yet handled
                            // (default-as-type is rare and detection requires checking the source's
                            // `export default X` for type-only X — out of scope for the named-imports
                            // path we're focused on).
                        }

                        when (val nb = clause.namedBindings) {
                            is NamespaceImport -> {
                                // `import * as ns from "./y"` — namespace import is non-type-only at the binding,
                                // so TS1295 fires in CJS+verbatim. (TS1484 doesn't apply: a namespace import
                                // brings in both types and values, so type-only-import isn't a meaningful
                                // alternative even when the source is mostly types.)
                                if (isCjs) emitTs1295(nb.name.pos, nb.name.text.length)
                            }
                            is NamedImports -> {
                                for (element in nb.elements) {
                                    if (element.isTypeOnly) continue  // per-element `type` qualifier
                                    val nameNode = element.propertyName ?: element.name
                                    val pos = nameNode.pos
                                    val len = nameNode.text.length
                                    val sourceName = (element.propertyName ?: element.name).text
                                    if (isCjs) emitTs1295(pos, len)
                                    if (moduleSpecifierText != null &&
                                        isExportedNameTypeOnly(sourceName, moduleSpecifierText)) {
                                        emitTs1484(pos, len, sourceName)
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                    // TS1287: top-level `export` modifier on value declaration in CJS+verbatim.
                    // Value-shape declarations: class / function / var-statement (let/const/var) / enum.
                    // Type-shape declarations (interface, type alias) are exempt — type-only erases at compile time.
                    // `declare`-prefixed declarations are ambient (type-only at runtime) — exempt.
                    is ClassDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = source.lastIndexOf("export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is FunctionDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = source.lastIndexOf("export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is VariableStatement -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = source.lastIndexOf("export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is EnumDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = source.lastIndexOf("export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    // TS2661: Cannot export non-local declaration
    // -----------------------------------------------------------------------

    private fun checkExportSpecifierLocality() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val locals = result.locals

            for (stmt in result.sourceFile.statements) {
                if (stmt !is ExportDeclaration) continue
                // Only check `export { X }` without `from "..."` (re-exports from modules are fine)
                if (stmt.moduleSpecifier != null) continue
                if (stmt.isTypeOnly) continue
                val namedExports = stmt.exportClause as? NamedExports ?: continue

                for (spec in namedExports.elements) {
                    if (spec.isTypeOnly) continue
                    val exportedName = (spec.propertyName ?: spec.name).text
                    // Check if locally declared (not just aliased by the export itself)
                    val localSymbol = locals[exportedName]
                    if (localSymbol != null) {
                        // If the symbol has non-ExportSpecifier declarations, it's a real local
                        val hasRealDecl = localSymbol.declarations.any { it !is ExportSpecifier }
                        if (hasRealDecl) continue
                    }
                    // The name was not locally declared — check if it's a global or known global
                    if (exportedName == "undefined" || exportedName in globals || exportedName in KNOWN_GLOBALS) {
                        val nameNode = spec.propertyName ?: spec.name
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Cannot export '$exportedName'. Only local declarations can be exported from a module.",
                            category = DiagnosticCategory.Error,
                            code = 2661,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = exportedName.length,
                        ))
                    }
                }
            }
        }
    }

    // TS8xxx: TypeScript syntax in JavaScript files
    // -----------------------------------------------------------------------

    private fun checkTsSyntaxInJsFiles() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (!fileName.endsWith(".js") && !fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            checkTsSyntaxInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkTsSyntaxInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkTsSyntaxInStatement(stmt, source, fileName)
    }

    private fun checkTsSyntaxInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                emitTs8xxx(stmt.name, "'interface' declarations can only be used in TypeScript files.", 8006, source, fileName)
            }
            is EnumDeclaration -> {
                emitTs8xxx(stmt.name, "'enum' declarations can only be used in TypeScript files.", 8006, source, fileName)
            }
            is ModuleDeclaration -> {
                if (stmt.name is StringLiteralNode) {
                    // `declare module "foo" {}` - skip, this is ambient module declaration
                } else {
                    emitTs8xxx(stmt.name, "'namespace' declarations can only be used in TypeScript files.", 8006, source, fileName)
                }
            }
            is TypeAliasDeclaration -> {
                emitTs8xxx(stmt.name, "Type aliases can only be used in TypeScript files.", 8008, source, fileName)
            }
            is ImportEqualsDeclaration -> {
                val start = stmt.pos
                val importStart = source.indexOf("import", start)
                if (importStart >= 0) {
                    // Span covers the full statement including semicolon
                    val semiPos = source.indexOf(';', importStart)
                    val stmtLength = if (semiPos >= 0) semiPos - importStart + 1 else stmt.end - importStart
                    val (line, character) = getLineAndCharacterOfPosition(source, importStart)
                    diagnostics.add(Diagnostic(
                        message = "'import ... =' can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8002,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = importStart,
                        length = stmtLength,
                    ))
                }
            }
            is ExportAssignment -> {
                if (stmt.isExportEquals) {
                    val start = stmt.pos
                    // Find "export" in source near stmt.pos
                    val exportStart = source.indexOf("export", start)
                    if (exportStart >= 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, exportStart)
                        diagnostics.add(Diagnostic(
                            message = "'export =' can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8003,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exportStart,
                            length = 11, // "export = ..."
                        ))
                    }
                }
            }
            is FunctionDeclaration -> {
                // TS8017: Signature declarations without body — takes priority over other TS8xxx
                if (stmt.body == null) {
                    val nameNode = stmt.name
                    if (nameNode != null) {
                        emitTs8xxx(nameNode, "Signature declarations can only be used in TypeScript files.", 8017, source, fileName)
                    }
                } else {
                    // Check type parameters (TS8004) — skip JSDoc-derived ones (B5.3)
                    val firstTsTp = stmt.typeParameters?.firstOrNull { !it.fromJSDoc }
                    if (firstTsTp != null) {
                        emitTs8xxx(firstTsTp.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                    }
                    // Check parameter types (TS8010), optional params (TS8009)
                    checkTsSyntaxInParams(stmt.parameters, source, fileName)
                    // Check return type (TS8010)
                    if (stmt.type != null) {
                        emitTs8xxxForType(stmt.type!!, source, fileName)
                    }
                    checkTsSyntaxInStatements(stmt.body!!.statements, source, fileName)
                }
            }
            is ClassDeclaration -> {
                // Check abstract modifier (TS8009) — search backward from class pos since pos may be at 'class' keyword
                if (ModifierFlag.Abstract in stmt.modifiers) {
                    val searchFrom = maxOf(0, stmt.pos - 30)
                    val idx = source.indexOf("abstract", searchFrom)
                    if (idx >= 0 && idx < stmt.pos + 2) {
                        val (line, character) = getLineAndCharacterOfPosition(source, idx)
                        diagnostics.add(Diagnostic(
                            message = "The 'abstract' modifier can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8009,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = idx,
                            length = 8,
                        ))
                    }
                }
                // Check type parameters (TS8004) — skip JSDoc-derived ones (B5.3)
                val firstClassTsTp = stmt.typeParameters?.firstOrNull { !it.fromJSDoc }
                if (firstClassTsTp != null) {
                    emitTs8xxx(firstClassTsTp.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                }
                // Check implements clause (TS8005)
                val hasImplements = stmt.heritageClauses?.any { it.token == SyntaxKind.ImplementsKeyword } == true
                if (hasImplements) {
                    // Find "implements" keyword position — use name pos + length (not name.end which overshoots)
                    val nameEnd = stmt.name?.let { it.pos + ((it as? Identifier)?.text?.length ?: 1) } ?: stmt.pos
                    val implIdx = source.indexOf("implements", nameEnd)
                    if (implIdx >= 0) {
                        // Span covers "implements <types>" — find the end of the implements clause
                        val implClause = stmt.heritageClauses?.find { it.token == SyntaxKind.ImplementsKeyword }
                        val implEnd = implClause?.let { clause ->
                            // Compute true end from last type in the clause
                            val lastType = clause.types.lastOrNull()
                            if (lastType != null) {
                                val typeExpr = lastType.expression
                                when (typeExpr) {
                                    is Identifier -> typeExpr.pos + typeExpr.text.length
                                    else -> lastType.end
                                }
                            } else implIdx + 10
                        } ?: (implIdx + 10)
                        val (line, character) = getLineAndCharacterOfPosition(source, implIdx)
                        diagnostics.add(Diagnostic(
                            message = "'implements' clauses can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8005,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = implIdx,
                            length = implEnd - implIdx,
                        ))
                    }
                }
                for (member in stmt.members) {
                    checkTsSyntaxInClassMember(member, source, fileName)
                }
            }
            is VariableStatement -> {
                // Check for declare modifier (TS8009)
                if (ModifierFlag.Declare in stmt.modifiers) {
                    emitTs8xxxDeclare(stmt.pos, source, fileName)
                }
                // Check variable type annotations and initializer expressions
                for (decl in stmt.declarationList.declarations) {
                    // 17.62: types synthesized from a leading primitive `@type {...}` JSDoc
                    // comment are valid in JS files — skip TS8010 for that case.
                    if (decl.type != null && !decl.typeFromJSDoc) {
                        emitTs8xxxForType(decl.type!!, source, fileName)
                    }
                    // Walk into initializer to find ClassExpression type params etc.
                    decl.initializer?.let { checkTsSyntaxInExpression(it, source, fileName) }
                }
            }
            is ExpressionStatement -> {
                checkTsSyntaxInExpression(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let { checkTsSyntaxInExpression(it, source, fileName) }
            }
            is Block -> checkTsSyntaxInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkTsSyntaxInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkTsSyntaxInStatement(it, source, fileName) }
            }
            is ForStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    private fun checkTsSyntaxInClassMember(member: ClassElement, source: String, fileName: String) {
        // Get modifiers and pos from the specific member type
        val modifiers: Set<ModifierFlag>
        val memberPos: Int
        when (member) {
            is MethodDeclaration -> { modifiers = member.modifiers; memberPos = member.pos }
            is Constructor -> { modifiers = member.modifiers; memberPos = member.pos }
            is PropertyDeclaration -> { modifiers = member.modifiers; memberPos = member.pos }
            is GetAccessor -> { modifiers = member.modifiers; memberPos = member.pos }
            is SetAccessor -> { modifiers = member.modifiers; memberPos = member.pos }
            else -> { modifiers = emptySet(); memberPos = 0 }
        }
        // Check access modifiers (public/private/protected) on class members — TS8009
        checkTsSyntaxAccessModifier(modifiers, memberPos, source, fileName)
        // Check abstract modifier on members — TS8009
        if (ModifierFlag.Abstract in modifiers) {
            emitTs8xxxModifier("abstract", memberPos, 8, source, fileName)
        }
        when (member) {
            is MethodDeclaration -> {
                // TS8017: Signature declarations without body — takes priority over other checks
                if (member.body == null) {
                    emitTs8xxx(member.name, "Signature declarations can only be used in TypeScript files.", 8017, source, fileName)
                    return
                }
                // Check optional ? modifier (TS8009)
                if (member.questionToken) {
                    // Find ? after the method name
                    val nameEnd = member.name.pos + ((member.name as? Identifier)?.text?.length ?: 1)
                    val qIdx = source.indexOf('?', nameEnd)
                    if (qIdx >= 0 && qIdx < nameEnd + 5) {
                        emitTs8xxxQuestionToken(qIdx, source, fileName)
                    }
                }
                // Check type parameters (TS8004)
                if (!member.typeParameters.isNullOrEmpty()) {
                    val typeParam = member.typeParameters!!.first()
                    emitTs8xxx(typeParam.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                }
                // Check parameter types, optional params
                checkTsSyntaxInParams(member.parameters, source, fileName)
                if (member.type != null) emitTs8xxxForType(member.type!!, source, fileName)
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is Constructor -> {
                // TS8017: Constructor signature without body
                if (member.body == null) {
                    // Span covers "constructor" keyword
                    val ctorIdx = source.indexOf("constructor", memberPos)
                    if (ctorIdx >= 0 && ctorIdx < memberPos + 30) {
                        val (line, character) = getLineAndCharacterOfPosition(source, ctorIdx)
                        diagnostics.add(Diagnostic(
                            message = "Signature declarations can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8017,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = ctorIdx,
                            length = 11, // "constructor"
                        ))
                    }
                    return
                }
                // Check constructor parameters — types and modifiers (TS8012)
                for (param in member.parameters) {
                    if (param.type != null) emitTs8xxxForType(param.type!!, source, fileName)
                    if (param.questionToken) {
                        findQuestionTokenPos(param, source)?.let { emitTs8xxxQuestionToken(it, source, fileName) }
                    }
                    // Check parameter modifiers (public/private/etc.) — TS8012
                    if (param.modifiers.any { isParameterPropertyModifier(it) }) {
                        emitTs8xxxParamModifier(param.pos, source, fileName)
                    }
                }
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is PropertyDeclaration -> {
                // Check optional ? modifier (TS8009)
                if (member.questionToken) {
                    val nameEnd = member.name.pos + ((member.name as? Identifier)?.text?.length ?: 1)
                    val qIdx = source.indexOf('?', nameEnd)
                    if (qIdx >= 0 && qIdx < nameEnd + 5) {
                        emitTs8xxxQuestionToken(qIdx, source, fileName)
                    }
                }
                // 17.58b: types synthesized from a leading `@type {...}` JSDoc comment
                // are valid in JS files — skip the TS8010 emission for that case.
                if (member.type != null && !member.typeFromJSDoc) emitTs8xxxForType(member.type!!, source, fileName)
                // Check declare modifier (TS8009)
                if (ModifierFlag.Declare in member.modifiers) {
                    emitTs8xxxDeclare(member.pos, source, fileName)
                }
            }
            is GetAccessor -> {
                if (member.type != null) emitTs8xxxForType(member.type!!, source, fileName)
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is SetAccessor -> {
                for (param in member.parameters) {
                    if (param.type != null) emitTs8xxxForType(param.type!!, source, fileName)
                }
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    /** Check parameters for type annotations (TS8010) and optional ? modifiers (TS8009). */
    private fun checkTsSyntaxInParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            // 17.140 / B5.2: skip TS8010 for params whose type was synthesized
            // from a JSDoc `@param {T} name` tag — those are valid in JS files.
            if (param.type != null && !param.typeFromJSDoc) emitTs8xxxForType(param.type!!, source, fileName)
            if (param.questionToken) {
                findQuestionTokenPos(param, source)?.let { emitTs8xxxQuestionToken(it, source, fileName) }
            }
        }
    }

    /** Find the position of the ? token after a parameter name. */
    private fun findQuestionTokenPos(param: Parameter, source: String): Int? {
        val nameEnd = param.name.pos + when (val n = param.name) {
            is Identifier -> n.text.length
            else -> 1
        }
        val qIdx = source.indexOf('?', nameEnd)
        return if (qIdx >= 0 && qIdx < nameEnd + 5) qIdx else null
    }

    /** Walk expression tree to find TypeScript-only syntax (non-null assertions, type assertions, class expressions). */
    private fun checkTsSyntaxInExpression(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is NonNullExpression -> {
                // TS8013: Non-null assertions can only be used in TypeScript files
                // Span covers the entire expression including the `!`
                val start = expr.pos
                val length = expressionTrueEnd(expr) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Non-null assertions can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8013,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                checkTsSyntaxInExpression(expr.expression, source, fileName)
            }
            is ClassExpression -> {
                // Check type parameters on class expressions (TS8004)
                if (!expr.typeParameters.isNullOrEmpty()) {
                    val typeParam = expr.typeParameters!!.first()
                    emitTs8xxx(typeParam.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                }
                for (member in expr.members) {
                    checkTsSyntaxInClassMember(member, source, fileName)
                }
            }
            is ParenthesizedExpression -> checkTsSyntaxInExpression(expr.expression, source, fileName)
            is BinaryExpression -> {
                // B64.8: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkTsSyntaxInExpression(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkTsSyntaxInExpression(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkTsSyntaxInExpression(expr.condition, source, fileName)
                checkTsSyntaxInExpression(expr.whenTrue, source, fileName)
                checkTsSyntaxInExpression(expr.whenFalse, source, fileName)
            }
            is AsExpression -> {
                // TS8016: Type assertion expressions can only be used in TypeScript files
                // Span covers just the type node (e.g., "number" in "0 as number")
                val typeNode = expr.type
                val start = typeNode.pos
                var trueEnd = typeNode.end
                while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ';' || it == ')' || it == '}' || it == ',' } == true) {
                    trueEnd--
                }
                val length = trueEnd - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type assertion expressions can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8016,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            else -> {}
        }
    }

    /** Check for public/private/protected access modifiers — TS8009 */
    private fun checkTsSyntaxAccessModifier(modifiers: Set<ModifierFlag>, pos: Int, source: String, fileName: String) {
        if (ModifierFlag.Public in modifiers) {
            emitTs8xxxModifier("public", pos, 6, source, fileName)
        } else if (ModifierFlag.Private in modifiers) {
            emitTs8xxxModifier("private", pos, 7, source, fileName)
        } else if (ModifierFlag.Protected in modifiers) {
            emitTs8xxxModifier("protected", pos, 9, source, fileName)
        }
    }

    /** Emit TS8009 for a modifier keyword found near the given pos. */
    private fun emitTs8xxxModifier(keyword: String, nearPos: Int, keywordLen: Int, source: String, fileName: String) {
        val idx = source.indexOf(keyword, nearPos)
        if (idx < 0 || idx > nearPos + 30) return
        val (line, character) = getLineAndCharacterOfPosition(source, idx)
        diagnostics.add(Diagnostic(
            message = "The '$keyword' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = idx,
            length = keywordLen,
        ))
    }

    /** Emit TS8009 for a ? token at the given position. */
    private fun emitTs8xxxQuestionToken(pos: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "The '?' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = 1, // "?"
        ))
    }

    /** Emit TS8012 for parameter modifier (public/private/protected/readonly). */
    private fun emitTs8xxxParamModifier(paramPos: Int, source: String, fileName: String) {
        // Find the first modifier keyword near paramPos
        val modifiers = listOf("public" to 6, "private" to 7, "protected" to 9, "readonly" to 8)
        for ((kw, len) in modifiers) {
            val idx = source.indexOf(kw, paramPos)
            if (idx >= 0 && idx < paramPos + 20) {
                val (line, character) = getLineAndCharacterOfPosition(source, idx)
                diagnostics.add(Diagnostic(
                    message = "Parameter modifiers can only be used in TypeScript files.",
                    category = DiagnosticCategory.Error,
                    code = 8012,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = idx,
                    length = len,
                ))
                return
            }
        }
    }

    private fun emitTs8xxx(nameNode: Node, message: String, code: Int, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            else -> nameNode.end - nameNode.pos
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTs8xxxForType(type: TypeNode, source: String, fileName: String) {
        val start = type.pos
        // type.end overshoots (includes next token's start), so compute true length
        // by trimming trailing whitespace/semicolons/delimiters from the source span
        var trueEnd = type.end
        while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ';' || it == ')' || it == '}' || it == ',' || it == '{' } == true) {
            trueEnd--
        }
        val length = trueEnd - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type annotations can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8010,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTs8xxxDeclare(stmtPos: Int, source: String, fileName: String) {
        // Search backward from stmtPos since stmt.pos may be at keyword after 'declare'
        val searchFrom = maxOf(0, stmtPos - 20)
        val declareIdx = source.indexOf("declare", searchFrom)
        if (declareIdx < 0 || declareIdx > stmtPos + 20) return
        val (line, character) = getLineAndCharacterOfPosition(source, declareIdx)
        diagnostics.add(Diagnostic(
            message = "The 'declare' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = declareIdx,
            length = 7, // "declare"
        ))
    }
}
